CREATE FUNCTION traking.addactividadgestion(fechaactividadi character varying, horaactividadi character varying, idtipoactividadgestioni bigint, descripciontipoi character varying, nombreclientecomi character varying, nombreareainteresi character varying, idclientecomcontactoi bigint, idmotivoactividadgestioni bigint, descripcionmotivoi character varying, idusuarioi bigint, status bigint, usercreate character varying, aplicatodoeldiai boolean, idrecurrenciai bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN

    insert into traking.mct_actividadgestion (
		   idactividadgestion,
		   fechaactividad,
           horaactividad,
		   idtipoactividadgestion ,
		   descripciontipo ,
           nombreclientecom,
           nombreareainteres,
		   idclientecomcontacto ,
		   idmotivoactividadgestion ,
		   descripcionmotivo ,
           idusuario,
           estado, 
           fechacreacion, 
           usuariocreacion,
           aplicatodoeldia,
           idrecurrencia
           ) 
     values (
          nextval('traking.mct_actividadgestion_seq'), 
          to_date(fechaactividadi, 'yyyy-mm-dd')+1,
          (to_timestamp(horaactividadi, 'HH24:MI'))::time,
