--
-- TOC entry 1567 (class 1255 OID 16401)
-- Name: addcalculoequipocirculante(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addcalculoequipocirculante(sdate character varying, edate character varying, annos bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    sp_otprioridades     bigint := 0;
    sp_otgar             bigint := 0;
    sp_otfab             bigint := 0;

    sp_sumanoevaluada    bigint := 0;
    sp_sumaevanocot      bigint := 0;
    sp_sumacotnoauto     bigint := 0;

    sp_totacirculante    bigint := 0;

    rec1                 record;

    v_sdate              date;
    v_edate              date;
    v_exists             boolean := false;
    v_id                 bigint := 0;

    -- Para capturar detalle del error
    v_sqlstate           text;
    v_message            text;
    v_detail             text;
    v_hint               text;
    v_context            text;
BEGIN
    -------------------------------------------------------------------------
    -- 1) Validaciones de entrada
    -------------------------------------------------------------------------
    IF sdate IS NULL OR btrim(sdate) = '' THEN
        RAISE EXCEPTION 'sdate viene NULL o vacío';
    END IF;

    IF edate IS NULL OR btrim(edate) = '' THEN
        RAISE EXCEPTION 'edate viene NULL o vacío';
    END IF;

    IF annos IS NULL OR annos <= 0 THEN
        RAISE EXCEPTION 'annos inválido (%). Debe ser > 0', annos;
    END IF;

    -- Parse seguro de fechas (captura formato inválido)
    BEGIN
        v_sdate := to_date(sdate, 'YYYY-MM-DD');
        v_edate := to_date(edate, 'YYYY-MM-DD');
    EXCEPTION WHEN others THEN
        RAISE EXCEPTION 'Formato de fecha inválido. sdate=%, edate=%. Debe ser YYYY-MM-DD', sdate, edate;
    END;

    IF v_sdate > v_edate THEN
        RAISE EXCEPTION 'Rango inválido: sdate (%) es mayor que edate (%)', v_sdate, v_edate;
    END IF;

    -------------------------------------------------------------------------
    -- 2) Cálculo por loop (con null/blank handling correcto)
    -------------------------------------------------------------------------
    FOR rec1 IN (
        SELECT *
        FROM traking.evtlistcalculoequipocirculante(-1, -1, sdate, edate, annos)
    )
    LOOP
        -- Normalizamos strings vacíos a NULL (por si vienen como texto)
        -- Si esos campos son tipo date, NULLIF no molesta si ya viene NULL.
        IF rec1.estadoit = 0 THEN
            sp_sumanoevaluada := sp_sumanoevaluada + 1;

        ELSIF (NULLIF(btrim(COALESCE(rec1.fechacotiza::text, '')), '') IS NULL)
              OR (rec1.estadocotiza = 0) THEN
            sp_sumaevanocot := sp_sumaevanocot + 1;

        ELSIF (
            ( NULLIF(btrim(COALESCE(rec1.fechaautoriza::text, '')), '') IS NULL
              OR rec1.tienedesviacion = 99
            )
            AND NULLIF(btrim(COALESCE(rec1.fechacotiza::text, '')), '') IS NOT NULL
        ) THEN
            sp_sumacotnoauto := sp_sumacotnoauto + 1;
        END IF;
    END LOOP;

    -------------------------------------------------------------------------
    -- 3) Conteos OT
    -------------------------------------------------------------------------
    SELECT count(*)
      INTO sp_otprioridades
      FROM mct_ordentrabajo a
     WHERE a.idordentrabajo >= 30000
       AND a.idestadoorden  >= 6 AND a.idestadoorden < 9
       AND a.idfamilia = 8
       AND a.flagfacturacion IS TRUE
       AND a.debaja < 1;

    SELECT count(*)
      INTO sp_otgar
      FROM mct_ordentrabajo a
     WHERE a.idordentrabajo >= 30000
       AND a.idestadoorden  >= 6 AND a.idestadoorden < 9
       AND a.idfamilia = 8
       AND a.flagfacturacion IS TRUE
       AND a.debaja < 1
       AND a.idtipoorden = 3;

    SELECT count(*)
      INTO sp_otfab
      FROM mct_ordentrabajo a
     WHERE a.idordentrabajo >= 30000
       AND a.idestadoorden  >= 6 AND a.idestadoorden < 9
       AND a.idfamilia = 8
       AND a.flagfacturacion IS TRUE
       AND a.debaja < 1
       AND a.idtipoorden = 2;

    sp_totacirculante := (
        sp_otprioridades
        + sp_sumacotnoauto
        + sp_sumaevanocot
        + sp_sumanoevaluada
        - sp_otgar
        - sp_otfab
    );

    -------------------------------------------------------------------------
    -- 4) Update/Insert con EXISTS correcto
    -------------------------------------------------------------------------
    SELECT EXISTS (
        SELECT 1
          FROM traking.mct_equiposcirculantes
         WHERE fechadesde = v_sdate
           AND fechahasta = v_edate
    )
    INTO v_exists;

    IF v_exists THEN
        UPDATE traking.mct_equiposcirculantes
           SET otprioridades   = sp_otprioridades,
               otnoauto        = sp_sumacotnoauto,
               otevanocot      = sp_sumaevanocot,
               otnoeva         = sp_sumanoevaluada,
               orgarantia      = sp_otgar,
               otfab           = sp_otfab,
               numerodeequipos = sp_totacirculante
         WHERE fechadesde = v_sdate
           AND fechahasta = v_edate
         RETURNING idequiposcirculantes INTO v_id;

    ELSE
        INSERT INTO traking.mct_equiposcirculantes
            (idequiposcirculantes, fechadesde, fechahasta,
             otprioridades, otnoauto, otevanocot, otnoeva,
             orgarantia, otfab, numerodeequipos)
        VALUES
            (nextval('traking.mct_equiposcirculantes_seq'),
             v_sdate, v_edate,
             sp_otprioridades, sp_sumacotnoauto, sp_sumaevanocot, sp_sumanoevaluada,
             sp_otgar, sp_otfab, sp_totacirculante)
        RETURNING idequiposcirculantes INTO v_id;
    END IF;

    -- Devuelvo el ID afectado (más útil que retornar 0)
    RETURN COALESCE(v_id, 0);

EXCEPTION
    WHEN others THEN
        GET STACKED DIAGNOSTICS
            v_sqlstate = RETURNED_SQLSTATE,
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT;

        -- No revienta: deja traza en log y retorna -1
        RAISE WARNING
            'Error en traking.addcalculoequipocirculante(sdate=%, edate=%, annos=%) | SQLSTATE=% | % | DETAIL=% | HINT=% | CONTEXT=%',
            sdate, edate, annos, v_sqlstate, v_message, v_detail, v_hint, v_context;

        RETURN -1;
END;
$$;


ALTER FUNCTION traking.addcalculoequipocirculante(sdate character varying, edate character varying, annos bigint) OWNER TO postgres;

--
-- TOC entry 1096 (class 1255 OID 16403)
-- Name: addcambioingenieria(character varying, bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addcambioingenieria(codhojarutai character varying, idusuarioi bigint, comentarioi character varying, idcierrei bigint, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	bigint;
       sp_plano			varchar;
       sp_usuario		varchar;
      
begin
	
	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;
    sp_plano        := '';
    sp_usuario		:= '';

   	select usuario
	  into sp_usuario
	  from mct_usuario
	 where idusuario = idusuarioi;
	
	select idcambioingenieria ,
	       idcierre
	  into sp_id,
	       sp_cierre
	  from mct_cambioingenieria
	 where codhojaruta = codhojarutai
	   and idcierre = 0;
	  
	 select coalesce (b.idcomponente, 0) ,
	        replace(b.nombreplano,' ', '') 
	   into sp_componente,
	        sp_plano
	   from mct_detallehojarutatemp a,
	        mct_hojarutatemp b 
	  where a.codhojaruta = codhojarutai
	    and a.idhojarutatemp = b.idhojarutatemp ;
	  
	if ( sp_id > 0 and sp_cierre = 0) then
	
	    update traking.mct_cambioingenieria 
	       set codhojaruta = codhojarutai, 
	           idusuario = idusuarioi, 
	           comentario = comentarioi,
	           idcomponente = sp_componente,
	           nombreplano = sp_plano,
	           idcierre = idcierrei ,
	           usuariomodificacion = sp_usuario, 
	           fechamodificacion = now()
	     where idcambioingenieria = sp_id;
	
	else
	
		sp_id := nextval('traking.mct_cambioingenieria_seq');

		INSERT INTO traking.mct_cambioingenieria 
	               (idcambioingenieria ,
	               codhojaruta, 
	               idusuario,
	               comentario,
	               idcomponente, 
	               nombreplano ,
	               idcierre , 
	               fechacreacion,
	               usuariocreacion
	               )
	         values
	              (sp_id, 
	               codhojarutai, 
	               idusuarioi,
	               comentarioi,
	               sp_componente, 
	               sp_plano ,
	               idcierrei ,
	               now(),
	               sp_usuario
	              );
	             
	
	end if;

    RETURN sp_id;  

END
$$;


ALTER FUNCTION traking.addcambioingenieria(codhojarutai character varying, idusuarioi bigint, comentarioi character varying, idcierrei bigint, usercreatei character varying) OWNER TO postgres;

