--
-- TOC entry 898 (class 1255 OID 16408)
-- Name: addchecklistinftec(bigint, bigint, character varying, bigint, character varying, character varying, character varying, character varying, character varying, boolean, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addchecklistinftec(indexrow bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, returncomp boolean, componentegenerico character varying, materialgenerico character varying, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_texto            varchar;
    sp_criterio         varchar;
    intervalo           varchar;
    sp_fecha_requerida  varchar;
    dias_totales        integer;
    minima_fecha        timestamp;
    maxima_fecha        timestamp;
   
    es_inicial          integer;
    maxima_fila         integer;
    sp_familia			integer;
   
    sp_idcomponente		integer;
    sp_idmaterial		integer;
   
BEGIN
	
	sp_criterio := UPPER(repaircriteria);
    sp_criterio := replace(sp_criterio,'-','_');
	
	sp_texto    := '';
    sp_texto    := idworkorder||sp_criterio;
    maxima_fila	:= 0;
    sp_familia	:= 0;
    sp_idcomponente	:= 0;
    sp_idmaterial	:= 0;
  
    -- Saca componente
    select idcomponente 
      into sp_idcomponente
      from mct_componente 
     where nombrecomponente = componentegenerico;
       --and estado = 2;
    -- Esto se comenta por SQ por que al cargar a las hojas de rutas se cargan en blanco cuando no estan en ese estado

    -- Saca material
    select idmaterial 
      into sp_idmaterial
      from mct_material 
     where nombrematerial = materialgenerico;
       --and estado = 1;   
    -- Esto se comenta por SQ por que al cargar a las hojas de rutas se cargan en blanco cuando no estan en ese estado
    
    -- Saca Familia ordentrabajo
   
    select idfamilia
      into sp_familia
      from mct_ordentrabajo
     where idordentrabajo = idworkorder;
    
    -- Saca maxima indice fila
   
    select max(indicefila)
      into maxima_fila
      from mct_checklistinftec mc 
     where idordentrabajo = idworkorder;
   
    --if ( sp_criterio not in  'FAB_FU' && sp_criterio != 'FAB_PA' && sp_criterio != 'FAB_CA' && && sp_criterio != 'RPO' ) then
    if ( sp_criterio not in  ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO', 'STOCK_CC', 'RPO_SM') ) then
    
        sp_criterio := 'OTROS';
        sp_texto    := idworkorder||sp_criterio;
       
    end if;
	
	select min(fecha_inicio), 
	       max(fecha_termino),
	       round(cast(date_part('day',max(fecha_termino) - min(fecha_inicio)) as integer)*0.35)
	  into minima_fecha,
	       maxima_fecha,
	       dias_totales
	  from mct_progavisos mp 
	 where idordentrabajo = idworkorder
	 and idsla in (5,8);
	 
	intervalo := ''''||dias_totales||' day';
 
    select to_char(minima_fecha + intervalo::interval, 'dd-mm-yyyy') into sp_fecha_requerida;
   
    if ( select 1 from traking.mct_checklistinftec where idchecklistinftec = indexrow) then
    
        if ( deleterow = 'Yes') then 
        
            delete from traking.mct_checklistinftec
             where idordentrabajo = idworkorder
               and idchecklistinftec = indexrow;          
        else
        
            if ( sp_familia in (10, 15) ) then
            
               if ( componentegenerico != '' and materialgenerico != '') then 
               
 		        update traking.mct_checklistinftec 
		           set nombreparte = partname,
		               cantidad = quantity,
		               material = materialname,
		               criterio = repaircriteria,
		               reparacion = repair,
		               plano = blueprintname,
		               tipotrabajostd = sp_criterio,
		               codigoqr = sp_texto,
		               devolucion = returncomp,
		               muestrachecklist = false,
		               idcomponente = sp_idcomponente,
		               nombrecomponente = componentegenerico,
		               idmaterial = sp_idmaterial,
		               nombrematerial = materialgenerico	,
		               fecharequerida = to_date(sp_fecha_requerida,'dd-mm-yyyy')		               
		         where idordentrabajo = idworkorder
		           and idchecklistinftec = indexrow;                  
               
               else
               
		        update traking.mct_checklistinftec 
		           set nombreparte = partname,
		               cantidad = quantity,
		               material = materialname,
		               criterio = repaircriteria,
		               reparacion = repair,
		               plano = blueprintname,
		               tipotrabajostd = sp_criterio,
		               codigoqr = sp_texto,
		               devolucion = returncomp,
		               muestrachecklist = false	,
		               fecharequerida = to_date(sp_fecha_requerida,'dd-mm-yyyy')
		              -- idcomponente = sp_idcomponente,
		              -- nombrecomponente = componentegenerico
		         where idordentrabajo = idworkorder
		           and idchecklistinftec = indexrow;                
               
               end if;
             
            
            else

                 if ( componentegenerico != '' and materialgenerico != '' ) then 
                           
			        update traking.mct_checklistinftec 
			           set nombreparte = partname,
			               cantidad = quantity,
			               material = materialname,
			               criterio = repaircriteria,
			               reparacion = repair,
			               plano = blueprintname,
			               tipotrabajostd = sp_criterio,
			               codigoqr = sp_texto,
			               devolucion = returncomp,
				           idcomponente = sp_idcomponente,
				           nombrecomponente = componentegenerico,
		               	   idmaterial = sp_idmaterial,
		                   nombrematerial = materialgenerico		,
		                   fecharequerida = to_date(sp_fecha_requerida,'dd-mm-yyyy')
			         where idordentrabajo = idworkorder
			           and idchecklistinftec = indexrow;                             
                           
                 else
                           
			        update traking.mct_checklistinftec 
			           set nombreparte = partname,
			               cantidad = quantity,
			               material = materialname,
			               criterio = repaircriteria,
			               reparacion = repair,
			               plano = blueprintname,
			               tipotrabajostd = sp_criterio,
			               codigoqr = sp_texto,
			               devolucion = returncomp	,
		                   fecharequerida = to_date(sp_fecha_requerida,'dd-mm-yyyy')
				         --  idcomponente = sp_idcomponente,
				         --  nombrecomponente = componentegenerico
			         where idordentrabajo = idworkorder
			           and idchecklistinftec = indexrow;                             
                           
                 end if;

	          
            end if;
           
      
        
        end if;
        

    
    else
    
        es_inicial := 0;
       
        select count(*)
          into es_inicial
          from traking.mct_checklistinftecinicial mc 
         where idordentrabajo = idworkorder;
        
		INSERT INTO traking.mct_checklistinftec
					(idchecklistinftec, 
					 idordentrabajo, 
					 nombreparte, 
					 cantidad, 
					 material, 
					 criterio, 
					 reparacion, 
					 plano, 
					 usuariocreacion, 
					 fechacreacion, 
					 indicefila,
					 codigoqr,
					 fecharequerida,
					 tipotrabajostd ,
					 devolucion ,
					 muestrachecklist ,
					 idcomponente ,
					 nombrecomponente ,
					 idmaterial ,
					 nombrematerial 
					 )
			 values (nextval('mct_checklistinftec_seq'),
			         idworkorder, 
			         partname, 
			         quantity, 
			         materialname, 
			         repaircriteria, 
			         repair, 
			         blueprintname, 
			         usercreate, 
			         now(), 
			         --indexrow,
			         maxima_fila+1,
			         sp_texto,
			         to_date(sp_fecha_requerida,'dd-mm-yyyy'),
			         sp_criterio,
			         returncomp,
			         true,
			         sp_idcomponente,
			         componentegenerico,
			         sp_idmaterial,
			         materialgenerico
			        );
        
 		       
    end if;
   

END
$$;


ALTER FUNCTION traking.addchecklistinftec(indexrow bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, returncomp boolean, componentegenerico character varying, materialgenerico character varying, usercreate character varying) OWNER TO postgres;

--
-- TOC entry 2168 (class 1255 OID 16410)
-- Name: addchecklistinftecfundcab(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addchecklistinftecfundcab(idordentrabajoi bigint, usercreate character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 

    sp_id				integer;
    sp_existecheck		integer;
   
   
BEGIN
	
    sp_existecheck	:= 0;
   
    select count(*)
      into sp_existecheck
      from mct_checklistinftecfundcab 
     where idordentrabajo  = idordentrabajoi;

    if ( sp_existecheck > 0 ) then
    
		sp_id	:= -1;
    else

	    sp_id	:= nextval('mct_checklistinftecparamcab_seq');
	
	    INSERT INTO traking.mct_checklistinftecfundcab
	               (idchecklistinftecfundcab, 
	               idordentrabajo , 
	               estado, 
	               usuariocreacion, 
	               fechacreacion
	               )
	         VALUES(sp_id, 
	                idordentrabajoi,  
	                1, 
	                usercreate, 
	                now()
	               );
	    
    end if;

    return sp_id;
				
END
$$;


ALTER FUNCTION traking.addchecklistinftecfundcab(idordentrabajoi bigint, usercreate character varying) OWNER TO postgres;

