--

CREATE FUNCTION traking.addchecklistinftecfunddet(idchecklistinftecfundi bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, nombrezonai character varying, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_texto            varchar;
    sp_criterio         varchar;
    sp_idcriterio		integer;
    intervalo           varchar;
    sp_fecha_requerida  varchar;
    dias_totales        integer;
    minima_fecha        timestamp;
    maxima_fecha        timestamp;
   
    es_inicial          integer;
    sp_muestra          boolean;
   
    sp_idmaterial		integer;
   
BEGIN
	
	sp_criterio := UPPER(repaircriteria);
    sp_criterio := replace(sp_criterio,'-','_');
   
    sp_idcriterio	:= 0;
    -- Saca el id para insertarlo en la tabla
    select idcriterioevaluacion
      into sp_idcriterio
      from mct_criterioevaluacion
     where UPPER(nombrecriterioevaluacion) = UPPER(sp_criterio);

    sp_idmaterial	:= 0;
    -- Saca el id para insertarlo en la tabla
    select idmaterial
      into sp_idmaterial
      from mct_material
     where UPPER(nombrematerial) = upper(materialname) ;
    
	INSERT INTO traking.mct_checklistinftecfund
				(idchecklistinftecfunddet, 
				 idchecklistinftecfundcab, 
				 nombreparte, 
				 cantidad, 
				 material, 
				 criterio,
				 reparacion, 
				 plano, 
				 idcriterioevaluacion, 
				 nombrezona, 
				 usuariocreacion, 
				 fechacreacion,
				 idmaterial 
				 )
		  VALUES(nextval('mct_checklistinftecfunddet_seq'),
		         idchecklistinftecfundcabi, 
		         partname, 
		         quantity, 
		         materialname, 
		         repaircriteria, 
		         repair,
		         blueprintname, 
		         sp_idcriterio,		         
		         nombrezonai, 
		         'squijada', 
		         now(),
		         coalesce(sp_idmaterial,0)
		          );		

				
END
$$;


