CREATE FUNCTION traking.addchecklistinftecparamcab(idcustomeri bigint, generalplani character varying, usercreate character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 

    sp_id				integer;
    sp_existecheck		integer;
   
   
BEGIN
	
    sp_existecheck	:= 0;
   
    select count(*)
      into sp_existecheck
      from mct_checklistinftecparamcab 
     where idcliente = idcustomeri
       and planogeneral = generalplani ;

    if ( sp_existecheck > 0 ) then
    
		sp_id	:= -1;
    else

	    sp_id	:= nextval('mct_checklistinftecparamcab_seq');
	
	    INSERT INTO traking.mct_checklistinftecparamcab
	               (idchecklistinftecparamcab, 
	               idcliente, 
	               planogeneral, 
	               estado, 
	               usuariocreacion, 
	               fechacreacion
	               )
	         VALUES(sp_id, 
	                idcustomeri,  
	                generalplani, 
	                1, 
	                usercreate, 
	                now()
	               );
	    
    end if;

    return sp_id;
				
END
$$;


ALTER FUNCTION traking.addchecklistinftecparamcab(idcustomeri bigint, generalplani character varying, usercreate character varying) OWNER TO postgres;

--
-- TOC entry 1968 (class 1255 OID 16415)
-- Name: addchecklistinftecparamdet(bigint, character varying, bigint, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addchecklistinftecparamdet(idchecklistinftecparamcabi bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, nombrezonai character varying, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_texto            varchar;
    sp_criterio         varchar;
    sp_idcriterio		integer;
    intervalo           varchar;
    sp_fecha_requerida  varchar;
    dias_totales        integer;
    minima_fecha        timestamp;
    maxima_fecha        timestamp;
   
    es_inicial          integer;
    sp_muestra          boolean;
   
    sp_idmaterial		integer;

    sp_id				bigint;
   
BEGIN
	
	--sp_criterio := UPPER(repaircriteria);
    sp_criterio := replace(UPPER(repaircriteria),'-','_');

raise notice '%', UPPER(repaircriteria)||'-'||sp_criterio; 
   
    sp_idcriterio	:= 0;
    -- Saca el id para insertarlo en la tabla
    select idcriterioevaluacion
      into sp_idcriterio
      from mct_criterioevaluacion
     where UPPER(nombrecriterioevaluacion) = UPPER(sp_criterio) or
           UPPER(alias) = UPPER(sp_criterio);

    sp_idmaterial	:= 0;
    -- Saca el id para insertarlo en la tabla
    select idmaterial
      into sp_idmaterial
      from mct_material
     where UPPER(nombrematerial) = upper(materialname) ;
    
	sp_id	:= nextval('mct_checklistinftecparamdet_seq');

	INSERT INTO traking.mct_checklistinftecparamdet
				(idchecklistinftecparamdet, 
				 idchecklistinftecparamcab, 
				 nombreparte, 
				 cantidad, 
				 material, 
				 criterio,
				 reparacion, 
				 plano, 
				 idcriterioevaluacion, 
				 nombrezona, 
				 usuariocreacion, 
				 fechacreacion,
				 idmaterial ,
                 idpadre
				 )
		  VALUES(sp_id,
		         idchecklistinftecparamcabi, 
		         partname, 
		         quantity, 
		         materialname, 
		         repaircriteria, 
		         repair,
		         blueprintname, 
		         sp_idcriterio,		         
		         nombrezonai, 
		         'admin', 
		         now(),
		         coalesce(sp_idmaterial,0),
                 sp_id
		          );		

				
END
$$;


ALTER FUNCTION traking.addchecklistinftecparamdet(idchecklistinftecparamcabi bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, nombrezonai character varying, usercreate character varying) OWNER TO postgres;

