CREATE FUNCTION traking.addchecklistinftecpeso(indexrow bigint, idworkorder bigint, weightcomp double precision, userupdate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
   
BEGIN
	
   
    if ( select 1 from traking.mct_checklistinftec where idchecklistinftec = indexrow) then
               
 		  update traking.mct_checklistinftec 
		     set pesocomponente = weightcomp	               
		   where idordentrabajo = idworkorder
	         and idchecklistinftec = indexrow;                  
 		       
    end if;
   

END
$$;


