--
-- TOC entry 1645 (class 1255 OID 16417)
-- Name: addchecklistinftecreception(bigint, character varying, bigint, bigint, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addchecklistinftecreception(idworkorder bigint, qrcode character varying, idchecklistinfteci bigint, iduser bigint, idoperator bigint, qdispatch bigint, observation character varying, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	bigint;
       sp_plano			varchar;
       sp_usuario		varchar;
       sp_idot			bigint;

       sp_idhojaruta	bigint;
      
       sp_accion		varchar;
       sp_area			bigint;
   	   sp_seccion		bigint;
   	   sp_codhojruta	varchar;
   	  
   	   sp_mensaje		varchar;
	   sp_idfamilia		bigint;

       sp_imprimehojas	bigint;
	   indice			int;
   	  
   
BEGIN

	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;
 
    sp_idhojaruta	:= 0;

    sp_plano        := '';
    sp_usuario		:= '';
    sp_idot			:= 0;
    sp_accion		:= '';
   
    sp_area			:= 0;
   	sp_seccion		:= 0;
    sp_codhojruta	:= '';
    sp_mensaje		:= '';

	sp_idfamilia	:= 0;
	sp_imprimehojas	:= 0;
    indice			:= 0;

	select idfamilia
	  into sp_idfamilia
	  from traking.mct_ordentrabajo
	where idordentrabajo = idworkorder;

	if (sp_idfamilia in (11) ) then

		select d.idhojaruta, 
	           c.codhojaruta
	      into sp_idhojaruta, 
	           sp_codhojruta
		  from traking.mct_hojarutatemp a 
		  left join traking.mct_checklistinftec b on a.idchecklistinftecvalido = b.idchecklistinftec 
		  left join traking.mct_detallehojarutatemp c on a.idhojarutatemp = c.idhojarutatemp
		  left join traking.mct_hojaruta d on a.idhojarutatemp = d.idhojarutatemp
		 where a.idordentrabajo = idworkorder
		   and b.idchecklistinftec = idchecklistinfteci
		   and not exists ( select 'x' 
		                     from traking.mct_movimientoordentrabajo mm 
		                    where mm.codhojaruta = c.codhojaruta
		                      and mm.codigoaccion = 'R_PL'
		                           )
		 order by c.codhojaruta 
		 limit 1;


		INSERT INTO traking.mct_checklistinftecrecept
		           (idchecklistinftecrecep, 
		            idordentrabajo, 
		            codigoqr, 
		            idchecklistinftec, 
		            idusuario, 
		            idoperatorent, 
		            cantidad, 
		            observacion,
		            fechacreacion, 
		            usuariocreacion
		            )
		     VALUES(nextval('traking.mct_checklistinftecrecept_seq'), 
		            idworkorder, 
		            qrcode, 
		            idchecklistinfteci, 
		            iduser, 
		            idoperator, 
		            qdispatch, 
		            observation,
		            now(), 
		            usercreate
		           );

	   	select idareaapp ,
	   	       idseccionapp
		  into sp_area,
		       sp_seccion
		  from traking.mct_operador
		 where idoperador = idoperator;
	
		sp_mensaje	:= 'Se procede con la recepción de la Pieza asociada a la hoja de Ruta : '||sp_codhojruta||E'\nObservación : '||observation;
	
		select *
		  into sp_id
		  from traking.evtaddregisterjobrecepcionpieza(idoperator, sp_codhojruta, 'R_PL', sp_seccion, 0, 0, 2, 42, sp_mensaje, null, iduser );


	else

		select a.idimprimehojas -- 1 = agrupadas, 2 = Individuales
          into sp_imprimehojas
          from traking.mct_hojarutatemp a
          left join traking.mct_checklistinftecvalido b on a.idchecklistinftecvalido = b.idchecklistinftecvalido
         where a.idordentrabajo = idworkorder
		   and b.idchecklistinftec = idchecklistinfteci;

		if (sp_imprimehojas = 2) then

			indice	:= 1;

			while (indice <= qdispatch) loop

					select d.idhojaruta, 
				           c.codhojaruta
				      into sp_idhojaruta, 
				           sp_codhojruta
					  from traking.mct_hojarutatemp a 
					  left join traking.mct_checklistinftecvalido b on a.idchecklistinftecvalido = b.idchecklistinftecvalido 
					  left join traking.mct_detallehojarutatemp c on a.idhojarutatemp = c.idhojarutatemp
					  left join traking.mct_hojaruta d on a.idhojarutatemp = d.idhojarutatemp
					 where a.idordentrabajo = idworkorder
					   and b.idchecklistinftec = idchecklistinfteci
					   and not exists ( select 'x' 
					                     from traking.mct_movimientoordentrabajo mm 
					                    where mm.codhojaruta = c.codhojaruta
					                      and mm.codigoaccion = 'R_PL'
					                           )
					 order by c.codhojaruta 
					 limit 1;
			
					INSERT INTO traking.mct_checklistinftecrecept
					           (idchecklistinftecrecep, 
					            idordentrabajo, 
					            codigoqr, 
					            idchecklistinftec, 
					            idusuario, 
					            idoperatorent, 
					            cantidad, 
					            observacion,
					            fechacreacion, 
					            usuariocreacion
					            )
					     VALUES(nextval('traking.mct_checklistinftecrecept_seq'), 
					            idworkorder, 
					            qrcode, 
					            idchecklistinfteci, 
					            iduser, 
					            idoperator, 
					            --qdispatch, 
                        		1,
					            observation,
					            now(), 
					            usercreate
					           );
			
				   	select idareaapp ,
				   	       idseccionapp
					  into sp_area,
					       sp_seccion
					  from traking.mct_operador
					 where idoperador = idoperator;
				
					sp_mensaje	:= 'Se procede con la recepción de la Pieza asociada a la hoja de Ruta : '||sp_codhojruta||E'\nObservación : '||observation;
				
					select *
					  into sp_id
					  from traking.evtaddregisterjobrecepcionpieza(idoperator, sp_codhojruta, 'R_PL', sp_seccion, 0, 0, 2, 42, sp_mensaje, null, iduser );

				indice	:= indice + 1;

			end loop;


		else

			select d.idhojaruta, 
		           c.codhojaruta
		      into sp_idhojaruta, 
		           sp_codhojruta
			  from traking.mct_hojarutatemp a 
			  left join traking.mct_checklistinftecvalido b on a.idchecklistinftecvalido = b.idchecklistinftecvalido 
			  left join traking.mct_detallehojarutatemp c on a.idhojarutatemp = c.idhojarutatemp
			  left join traking.mct_hojaruta d on a.idhojarutatemp = d.idhojarutatemp
			 where a.idordentrabajo = idworkorder
			   and b.idchecklistinftec = idchecklistinfteci
			   and not exists ( select 'x' 
			                     from traking.mct_movimientoordentrabajo mm 
			                    where mm.codhojaruta = c.codhojaruta
			                      and mm.codigoaccion = 'R_PL'
			                           )
			 order by c.codhojaruta 
			 limit 1;
	
			INSERT INTO traking.mct_checklistinftecrecept
			           (idchecklistinftecrecep, 
			            idordentrabajo, 
			            codigoqr, 
			            idchecklistinftec, 
			            idusuario, 
			            idoperatorent, 
			            cantidad, 
			            observacion,
			            fechacreacion, 
			            usuariocreacion
			            )
			     VALUES(nextval('traking.mct_checklistinftecrecept_seq'), 
			            idworkorder, 
			            qrcode, 
			            idchecklistinfteci, 
			            iduser, 
			            idoperator, 
			            qdispatch, 
			            observation,
			            now(), 
			            usercreate
			           );
	
		   	select idareaapp ,
		   	       idseccionapp
			  into sp_area,
			       sp_seccion
			  from traking.mct_operador
			 where idoperador = idoperator;
		
			sp_mensaje	:= 'Se procede con la recepción de la Pieza asociada a la hoja de Ruta : '||sp_codhojruta||E'\nObservación : '||observation;
		
			select *
			  into sp_id
			  from traking.evtaddregisterjobrecepcionpieza(idoperator, sp_codhojruta, 'R_PL', sp_seccion, 0, 0, 2, 42, sp_mensaje, null, iduser );


		end if;


	end if;


END
$$;


ALTER FUNCTION traking.addchecklistinftecreception(idworkorder bigint, qrcode character varying, idchecklistinfteci bigint, iduser bigint, idoperator bigint, qdispatch bigint, observation character varying, usercreate character varying) OWNER TO postgres;

