CREATE FUNCTION traking.addchecklistinftectime(idchecklistinftectime bigint, idchecklistinftec bigint, idproceso bigint, action1 character varying, idmachine1 bigint, machine1 character varying, time1 bigint, action2 character varying, idmachine2 bigint, machine2 character varying, time2 bigint, action3 character varying, idmachine3 bigint, machine3 character varying, time3 bigint, action4 character varying, idmachine4 bigint, machine4 character varying, time4 bigint, userupdate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_idmachine1       integer;
    sp_idmachine2       integer;
    sp_idmachine3       integer;
    sp_idmachine4       integer;   
   
BEGIN
	
		
	-- Proceso 1
	if ( idproceso = 1) then
	
		if ( idchecklistinftectime > 0 ) then
	
			   update traking.mct_checklistinftectiempo
			      set accion1 		= action1,
				      idmaquina1 	= sp_idmachine1,
				      maquina1 		= machine1,
				      tiempo1       = time1,
				      idmaquina2 	= sp_idmachine2,
				      maquina2 		= machine2,
				      tiempo2       = time2,
				      idmaquina3 	= sp_idmachine3,
				      maquina3 		= machine3,
				      tiempo3       = time3,
				      idmaquina4 	= sp_idmachine4,
				      maquina4 		= machine4,
				      tiempo4       = time4,
				      usuariomodificacion = userupdate,
				      fechamodificacion = now()
				  where idchecklistinftectiempo = idchecklistinftectime;
	
		else
	
			INSERT INTO traking.mct_checklistinftectiempo
						(idchecklistinftectiempo, 
						 idchecklistinftec, 
						 accion1, 
						 idmaquina1,
						 maquina1, 
						 tiempo1, 
						 idmaquina2,
						 maquina2, 
						 tiempo2, 
						 idmaquina3,
						 maquina3, 
						 tiempo3, 
						 idmaquina4,
						 maquina4, 
						 tiempo4, 						 
						 usuariocreacion, 
						 fechacreacion
						 )
				VALUES(nextval('mct_checklistinftectiempo_seq'),
			           idchecklistinftec, 
			           action1,
			           sp_idmachine1, 
			           machine1,
			           time1, 
			           sp_idmachine2, 
			           machine2,
			           time2,  
			           sp_idmachine3, 
			           machine3,
			           time3,           
			           sp_idmachine4, 
			           machine4,
			           time4,  
			           userupdate,
			           now()
			           );

		end if;
	
	end if;
	
	-- Proceso 2
 	if ( idproceso = 2) then
	
		if ( idchecklistinftectime > 0 ) then
	
			   update traking.mct_checklistinftectiempo
			      set accion2 		= action2,
				      idmaquina2 	= sp_idmachine2,
				      maquina2 		= machine2,
				      tiempo2       = time2,
				      usuariomodificacion = userupdate,
				      fechamodificacion = now()
				  where idchecklistinftectiempo = idchecklistinftectime;
	
		else
	
			INSERT INTO traking.mct_checklistinftectiempo
						(idchecklistinftectiempo, 
						 idchecklistinftec, 
						 accion2, 
						 idmaquina2,
						 maquina2, 
						 tiempo2, 
						 usuariocreacion, 
						 fechacreacion
						 )
				VALUES(nextval('mct_checklistinftectiempo_seq'),
			           idchecklistinftec, 
			           action2,
			           sp_idmachine2, 
			           machine2,
			           time2, 
			           userupdate,
			           now()
			           );

		end if;
	
	end if;

	-- Proceso 3
 	if ( idproceso = 3) then
	
		if ( idchecklistinftectime > 0 ) then
	
			   update traking.mct_checklistinftectiempo
			      set accion3 		= action3,
				      idmaquina3 	= sp_idmachine3,
				      maquina3 		= machine3,
				      tiempo3       = time3,
				      usuariomodificacion = userupdate,
				      fechamodificacion = now()
				  where idchecklistinftectiempo = idchecklistinftectime;
	
		else
	
			INSERT INTO traking.mct_checklistinftectiempo
						(idchecklistinftectiempo, 
						 idchecklistinftec, 
						 accion3, 
						 idmaquina3,
						 maquina3, 
						 tiempo3, 
						 usuariocreacion, 
						 fechacreacion
						 )
				VALUES(nextval('mct_checklistinftectiempo_seq'),
			           idchecklistinftec, 
			           action3,
			           sp_idmachine3, 
			           machine3,
			           time3, 
			           userupdate,
			           now()
			           );

		end if;
	
	end if;

	-- Proceso 4
 	if ( idproceso = 4) then
	
		if ( idchecklistinftectime > 0 ) then
	
			   update traking.mct_checklistinftectiempo
			      set accion4 		= action4,
				      idmaquina4 	= sp_idmachine4,
				      maquina4 		= machine4,
				      tiempo4       = time4,
				      usuariomodificacion = userupdate,
				      fechamodificacion = now()
				  where idchecklistinftectiempo = idchecklistinftectime;
	
		else
	
			INSERT INTO traking.mct_checklistinftectiempo
						(idchecklistinftectiempo, 
						 idchecklistinftec, 
						 accion4, 
						 idmaquina4,
						 maquina4, 
						 tiempo4, 
						 usuariocreacion, 
						 fechacreacion
						 )
				VALUES(nextval('mct_checklistinftectiempo_seq'),
			           idchecklistinftec, 
			           action4,
			           sp_idmachine4, 
			           machine4,
			           time4, 
			           userupdate,
			           now()
			           );

		end if;
	
	end if;

END
$$;


