-- TOC entry 964 (class 1255 OID 16423)
-- Name: addcomponent(character varying, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addcomponent(namecomponent character varying, directevaluation bigint, status bigint, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 
			
        sp_idcomp  	    INTEGER;
BEGIN

	sp_idcomp := nextval('traking.mct_componente_seq');
	       
    insert into traking.mct_componente 
                (idcomponente, 
                 nombrecomponente, 
                 evaluaciondirecta , 
                 estado, 
                 fechacreacion, 
                 usuariocreacion) 
         values (sp_idcomp, 
                 namecomponent, 
