--

CREATE FUNCTION traking.addcontrolmaquina(idcomponenteplanocontrolmaqi bigint, codhojarutai character varying, idusuarioi bigint, idcierrei bigint, datoai double precision, datobi double precision, datoci double precision, datodi double precision, datoei double precision, datofi double precision, datogi double precision, datohi double precision, datoii double precision, datoji double precision, datoki double precision, datoli double precision, datomi double precision, datoni double precision, datooi double precision, datopi double precision, datoqi double precision, datori double precision, datosi double precision, datoti double precision, datoui double precision, datovi double precision, datowi double precision, datoxi double precision, datoyi double precision, datozi double precision, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	bigint;
       sp_plano			varchar;
       sp_usuario		varchar;
      
begin
	
	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;
    sp_plano        := '';
    sp_usuario		:= '';

   	select usuario
	  into sp_usuario
	  from mct_usuario
	 where idusuario = idusuarioi;
	
	select idcontrolmaquina ,
	       idcierre
	  into sp_id,
	       sp_cierre
	  from mct_controlmaquina
	 where codhojaruta = codhojarutai
	   and idcierre = 0;
	  
	 select coalesce (b.idcomponente, 0) ,
	        replace(b.nombreplano,' ', '') 
	   into sp_componente,
	        sp_plano
	   from mct_detallehojarutatemp a,
	        mct_hojarutatemp b 
	  where a.codhojaruta = codhojarutai
	    and a.idhojarutatemp = b.idhojarutatemp ;
	  
	if ( sp_id > 0 and sp_cierre = 0) then
	
	    update traking.mct_controlmaquina 
	       set idcomponenteplanocontrolmaq = idcomponenteplanocontrolmaqi,
	           codhojaruta = codhojarutai, 
	           idusuario = idusuarioi, 
	           idcomponente = sp_componente,
	           nombreplano = sp_plano,
	           datoa = datoai, 
	           datob = datobi, 
	           datoc = datoci, 
	           datod = datodi, 
	           datoe = datoei, 
	           datof = datofi, 
	           datog = datogi, 
	           datoh = datohi, 
	           datoi = datoii, 
	           datoj = datoji, 
	           datok = datoki, 
	           datol = datoli, 
	           datom = datomi ,
   			   daton = datoni ,
   			   datoo = datooi ,
   			   datop = datopi ,
   			   datoq = datoqi ,
               dator = datori ,
               datos = datosi ,
               datot = datoti ,
               datou = datoui ,
               datov = datovi ,
               datow = datowi ,
               datox = datoxi ,
               datoy = datoyi ,
               datoz = datozi ,
	           idcierre = idcierrei ,
	           usuariomodificacion = sp_usuario, 
	           fechamodificacion = now()
	     where idcontrolmaquina = sp_id;
	
	else
	
		sp_id := nextval('traking.mct_controlmaquina_seq');

		INSERT INTO traking.mct_controlmaquina 
	               (idcontrolmaquina ,
	               idcomponenteplanocontrolmaq,
	               codhojaruta, 
	               idusuario,
	               idcomponente, 
	               nombreplano ,
	               datoa ,
	               datob ,
	               datoc , 
	               datod ,
	               datoe ,
	               datof ,
	               datog ,
	               datoh ,
	               datoi ,
	               datoj ,
	               datok ,
	               datol ,
	               datom ,
	               daton ,
	               datoo ,
	               datop ,
	               datoq ,
	               dator ,
	               datos ,
	               datot ,
	               datou ,
	               datov ,
	               datow ,
	               datox ,
	               datoy ,
	               datoz ,
	               idcierre , 
	               fechacreacion,
	               usuariocreacion
	               )
	         values
	              (sp_id, 
	               idcomponenteplanocontrolmaqi,
	               codhojarutai, 
	               idusuarioi,
	               sp_componente, 
	               sp_plano ,
	               coalesce (datoai, 0) ,
	               coalesce (datobi, 0) ,
	               coalesce (datoci, 0) , 
	               coalesce (datodi, 0) ,
	               coalesce (datoei, 0) ,
	               coalesce (datofi, 0) ,
	               coalesce (datogi, 0) ,
	               coalesce (datohi, 0) ,
	               coalesce (datoii, 0) ,
	               coalesce (datoji, 0) ,
	               coalesce (datoki, 0) ,
	               coalesce (datoli, 0) ,
	               coalesce (datomi, 0) ,
	               coalesce (datoni, 0) ,
	               coalesce (datooi, 0) ,
	               coalesce (datopi, 0) ,
	               coalesce (datoqi, 0) ,
	               coalesce (datori, 0) ,
	               coalesce (datosi, 0) ,
	               coalesce (datoti, 0) ,
	               coalesce (datoui, 0) ,
	               coalesce (datovi, 0) ,
	               coalesce (datowi, 0) ,
	               coalesce (datoxi, 0) ,
	               coalesce (datoyi, 0) ,
	               coalesce (datozi, 0) ,
	               coalesce (idcierrei, 0) ,
	               now(),
	               sp_usuario
	              );
	             
	
	end if;

    RETURN sp_id;  

END
$$;


