CREATE FUNCTION traking.adddefectocausa(iddefectocausai bigint, iddefectofundicioni bigint, descripcioni character varying, estadoi bigint, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare

	sp_id			bigint;
    sp_cantidad		bigint;
    sp_idinc		bigint;

begin

	if (iddefectocausai > 0) then
	
		update traking.mct_defectocausa
		   set descripcion = descripcioni
		 where iddefectocausa = iddefectocausai;
	
		return iddefectocausai;
	
	else 
	
	      sp_id	:= nextval('traking.mct_defectocausa_seq');
	 
	      insert into traking.mct_defectocausa
                (iddefectocausa , 
				 iddefectofundicion ,
			     descripcion ,
			     estado,
			     fechacreacion,
			     usuariocreacion 
                 ) 
          values (
                 sp_id , 
                 iddefectofundicioni ,
		  	 	 descripcioni ,
		  	 	 estadoi,
                 now(),
                 usercreatei
                );
 
      return sp_id;         
	
	end if;


END
$$;


