    LANGUAGE plpgsql
    AS $$
declare

	sp_id				bigint;
    sp_cantidad			bigint;
    sp_idinc			bigint;
   
    sp_fechaejecucion	timestamp;

begin

	  sp_id			:= 0;
	  sp_cantidad	:= 0;
	  sp_idinc		:= 0;

	  select coalesce (a.iddefectocausaaccionpdf,0) 
	    into sp_id
	    from traking.mct_defectocausaaccionpdf a
	   where a.iddefectocausaaccion = iddefectocausaaccioni
	     and a.nombrearchivo = nombrearchivoi ;

	    
	  if (sp_id > 0) then
	  
			update traking.mct_defectocausaaccionpdf 
			   set archivo = picfilei,
			       nombrearchivo = nombrearchivoi,
			       nombreresponsable = nombreresponsablei,
			       tipo = tipoi,
			       urlfirebase = urlfirebasei, 
			       fechamodificacion = now(),
			       usuariomodificacion = usercreatei
			 where iddefectocausaaccionpdf = sp_id;
		
	  else

	      sp_id	:= nextval('traking.mct_defectocausaaccionpdf_seq');
	 
	      insert into traking.mct_defectocausaaccionpdf 
                (iddefectocausaaccionpdf , 
				 iddefectocausaaccion ,
			     archivo ,
			     nombrearchivo ,
			     nombrerespaldo ,
			     tipo,
			     correlativo,
			     urlfirebase ,
			     fechacreacion,
			     usuariocreacion 
                 ) 
          values (
                 sp_id , 
                 iddefectocausaaccioni ,
		  	 	 picfilei ,
				 nombrearchivoi,
				 nombrerespaldoi,
				 tipoi,
			     correlativoi ,
			     urlfirebasei , 
                 now(),
                 usercreatei
                );
               
         select fechaejecucion
           into sp_fechaejecucion
           from mct_defectocausaaccion md
          where iddefectocausaaccion = iddefectocausaaccioni;
         
         insert into traking.mct_auditoriadefectocargarespaldo 
                (
         	     idauditoriadefectocargarespaldo,
	             iddefectocausaaccionpdf,
	             estado,
	             contador,
	             fechaejecucion,
	             fechacreacion                
                )
           values 
                (
                 nextval('traking.mct_auditoriadefectocargarespaldo_seq'),
                 sp_id,
                 1,
                 1,
                 sp_fechaejecucion,
                 now()                
                );
         
         
	  end if;
	 	    	   
      return sp_id;         

END
$$;


