-- Name: adddeffunparcial(character varying, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint, boolean, boolean, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.adddeffunparcial(codhojarutai character varying, idusuarioi bigint, iddefectoi bigint, idmaquinai bigint, iddefectofundicionorigeni bigint, idsubseccioni bigint, idcierrei bigint, iddebajai bigint, iddetectadefectoi bigint, urgentei boolean, dardebajai boolean, observacioni character varying, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	bigint;
       sp_plano			varchar;
       sp_usuario		varchar;
       sp_idot			bigint;
      
begin
	

	
	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;
    sp_plano        := '';
    sp_usuario		:= '';
    sp_idot			:= 0;

   	select usuario
	  into sp_usuario
	  from mct_usuario
	 where idusuario = idusuarioi;
	
	select iddefectofundicion ,
	       idcierre
	  into sp_id,
	       sp_cierre
	  from mct_defectofundicion
	 where codhojaruta = codhojarutai
	   and idcierre = 0;
	  
	 select coalesce (b.idcomponente, 0) ,
	        replace(b.nombreplano,' ', '') ,
	        b.idordentrabajo 
	   into sp_componente,
	        sp_plano,
	        sp_idot
	   from mct_detallehojarutatemp a,
	        mct_hojarutatemp b 
	   where a.codhojaruta = codhojarutai
	     and a.idhojarutatemp = b.idhojarutatemp ;
	  
	if ( sp_id > 0 and sp_cierre = 0) then
	
	    update traking.mct_defectofundicion 
	       set codhojaruta = codhojarutai, 
	           idordentrabajo = sp_idot,	           
	           idusuario = idusuarioi, 
	           iddefecto = iddefectoi,
	           idmaquina = idmaquinai,
	           idsubseccion = idsubseccioni, 
	           iddefectofundicionorigen = iddefectofundicionorigeni,
	           idcierre = idcierrei ,
	           iddebaja = iddebajai,
	           iddetectadefecto = iddetectadefectoi,
	           urgente = urgentei,
	           dardebaja = dardebajai,
	           observacion = observacioni,
	           usuariomodificacion = sp_usuario, 
	           fechamodificacion = now()
	     where iddefectofundicion = sp_id;
	
	else
	
		sp_id := nextval('traking.mct_defectofundicion_seq');

		INSERT INTO traking.mct_defectofundicion 
	               (iddefectofundicion , 
	               codhojaruta, 
	               idusuario, 
	               iddefecto ,
	               idmaquina ,
	               iddefectofundicionorigen ,
	               idsubseccion , 
	               idcierre , 
	               iddebaja,
	               iddetectadefecto,
	               usuariocreacion, 
	               fechacreacion,
	               idcomponente,
	               nombreplano ,
	               urgente ,
	               dardebaja ,
	               observacion ,
	               idordentrabajo 
	               )
	         values
	              (sp_id, 
	              codhojarutai, 
	              idusuarioi, 
	              iddefectoi ,
	              coalesce (idmaquinai, 0) ,
	              iddefectofundicionorigeni ,
	              idsubseccioni ,
	              idcierrei ,
	              iddebajai,
	              iddetectadefectoi,
	              sp_usuario, 
	              now(),
	              sp_componente,
	              sp_plano,
	              urgentei,
	              dardebajai,
	              observacioni,
	              sp_idot
	             );
	            
	    insert into traking.mct_auditoriadefectovalido values (
	           nextval('traking.mct_auditoriadefectovalido_seq'),
	           sp_id,
	           1,
	           1,
	           now()
	    );
	            
	
	end if;

    RETURN sp_id;  

END
$$;


