CREATE FUNCTION traking.addgestionncf(codhojarutai character varying, idoperadori bigint, idorigenncfi bigint, idaccionncfi bigint, observacioni character varying, idcierrei bigint, iddebajai bigint, urgentei boolean, dardebajai boolean, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	bigint;
       sp_plano			varchar;
       sp_usuario		varchar;
       sp_idot			bigint;
      
       sp_accion		varchar;
       sp_area			bigint;
   	   sp_seccion		bigint;
   	   sp_salida		varchar;
   	  
   	   sp_mensaje		varchar;
   
begin
	
	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;
    sp_plano        := '';
    sp_usuario		:= '';
    sp_idot			:= 0;
    sp_accion		:= '';
   
    sp_area			:= 0;
   	sp_seccion		:= 0;
    sp_salida		:= '';
    sp_mensaje		:= '';

   	select idareaapp ,
   	       idseccionapp
	  into sp_area,
	       sp_seccion
	  from mct_operador
	 where idoperador = idoperadori;
   
   	select codigoaccion
      into sp_accion
   	  from mct_origenncf
   	 where idorigenncf = idorigenncfi;
	
	select idgestionncf ,
	       idcierre
	  into sp_id,
	       sp_cierre
	  from mct_gestionncf
	 where codhojaruta = codhojarutai
	   and idcierre = 0;
	  
	 select coalesce (b.idcomponente, 0) ,
	        replace(b.nombreplano,' ', '') ,
	        b.idordentrabajo 
	   into sp_componente,
	        sp_plano,
	        sp_idot
	   from mct_detallehojarutatemp a,
	        mct_hojarutatemp b 
	   where a.codhojaruta = codhojarutai
	     and a.idhojarutatemp = b.idhojarutatemp ;
	  
	if ( sp_id > 0 and sp_cierre = 0) then
	
	    update traking.mct_gestionncf 
	       set codhojaruta = codhojarutai, 
	           idordentrabajo = sp_idot,	           
	           idoperador = idoperadori, 
	           idcierre = idcierrei ,
	           iddebaja = iddebajai,
	           urgente = urgentei,
	           dardebaja = dardebajai,
	           observacion = observacioni,
	           usuariomodificacion = sp_usuario, 
	           fechamodificacion = now()
	     where idgestionncf = sp_id;
	
	else
	
		sp_id := nextval('traking.mct_gestionncf_seq');

		INSERT INTO traking.mct_gestionncf 
	               (idgestionncf , 
	               codhojaruta, 
	               idoperador, 
	               idorigenncf  ,
	               idaccionncf  ,
	               idcomponente,
	               nombreplano ,
	               urgente ,
	               dardebaja ,
	               observacion ,
	               idordentrabajo ,
	               usuariocreacion, 
	               fechacreacion,
	               idcierre 
	               )
	         values
	              (sp_id, 
	              codhojarutai, 
	              idoperadori, 
	              idorigenncfi  ,
	              idaccionncfi  ,	               
	              sp_componente,
	              sp_plano,
	              urgentei,
	              dardebajai,
	              observacioni,
	              sp_idot,
	              'squijada',
	              now(),
	              1
	             );
	            
	    insert into traking.mct_auditoriagestionncfvalido values (
	           nextval('traking.mct_auditoriagestionncfvalido_seq'),
	           sp_id,
	           1,
	           1,
	           now()
	    );
                      
	   sp_mensaje	:= 'Se registra la NCF de la Pieza asociada a la hoja de Ruta : '||codhojarutai;
	  
	   select *
	     into sp_salida
	     from evtaddregisterjobmovil(idoperadori, codhojarutai, sp_accion, sp_seccion, 0, 0, 2, 42, sp_mensaje, null, 5 );
	
	end if;

    RETURN sp_id;  

END
$$;


