-- Name: addgestionncfadjunto(bigint, bigint, text); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addgestionncfadjunto(idgestionncfi bigint, correlativoi bigint, archivoadjuntoi text) RETURNS void
    LANGUAGE plpgsql
    AS $$

BEGIN

	if ( select 1 
	       from traking.mct_gestionncfadjunto mn 
	      where idgestionncf = idgestionncfi and  
