--

CREATE FUNCTION traking.addinspparcial(idordentrabajoi bigint, idusuarioi bigint, codhojarutai character varying, idtipoinspi bigint, numeroinspi bigint, nombreplanoi character varying, idclosei bigint, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	integer;
      
begin
	
	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;

	select idinsp,
	       idcierre
	  into sp_id,
	       sp_cierre
	  from mct_insp 
	 where idordentrabajo = idordentrabajoi
	   and codhojaruta = codhojarutai
	   and idcierre = 0;
	  
	  
	  select b.cantidad,
	         b.idcomponente 
	    into sp_cantidad,
	         sp_componente
	    from mct_detallehojarutatemp a,
	         mct_hojarutatemp b 
	   where a.codhojaruta = codhojarutai
	     and a.idhojarutatemp = b.idhojarutatemp ;
	  
	if ( sp_id > 0 and sp_cierre = 0) then
	
	    update traking.mct_insp
	       set idordentrabajo = idordentrabajoi , 
	           codhojaruta = codhojarutai, 
	           idusuario = idusuarioi, 
	           idtipoinsp = idtipoinspi, 
	           numeroinsp = idtipoinspi, 
	           nombreplano = nombreplanoi, 
	           idcierre = idclosei , 
	           usuariomodificacion = 'admin', 
	           fechamodificacion = now()
	     where idinsp = sp_id;
	
	else
	
		sp_id := nextval('traking.mct_insp_seq');

		INSERT INTO traking.mct_insp
	               (idinsp , idordentrabajo, codhojaruta, idusuario, idtipoinsp , idcomponente , numeroinsp , nombreplano , cantidad , idcierre , usuariocreacion, fechacreacion)
	         values
	              (sp_id, 
