--
-- TOC entry 1706 (class 1255 OID 16470)
-- Name: addkitdetalle(bigint, character varying, character varying, bigint, integer, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addkitdetalle(idkiti bigint, nombrekitdetallei character varying, planoi character varying, cantidadi bigint, status integer, usercreatei character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    sp_cantidad BIGINT := 0;
    sp_montokit BIGINT := 0;
BEGIN

    INSERT INTO traking.mct_kitdetalle (
        idkitdetalle,
        idkit,
        nombrekitdetalle,
        plano,
        cantidad,
        valorindividual,
        valorkit,
        estado,
        fechacreacion,
        usuariocreacion
    )
    VALUES (
        nextval('traking.mct_kitdetalle_seq'),
        idkiti,
        nombrekitdetallei,
        planoi,
        cantidadi,
        0,
        0,
        status,
        NOW(),
        usercreatei
    );

    SELECT COALESCE(MAX(montokit), 0)
      INTO sp_montokit
      FROM traking.mct_kit
     WHERE idkit = idkiti;

    SELECT COALESCE(SUM(cantidad), 0)
      INTO sp_cantidad
      FROM traking.mct_kitdetalle
     WHERE idkit = idkiti;

    IF sp_cantidad > 0 THEN
        RAISE NOTICE 'sp_montokit: %, sp_cantidad: %', sp_montokit, sp_cantidad;

        UPDATE traking.mct_kitdetalle
           SET valorkit = ROUND(sp_montokit::NUMERIC / sp_cantidad::NUMERIC, 0)::BIGINT
         WHERE idkit = idkiti;
    END IF;

END
$$;


