--
-- TOC entry 2286 (class 1255 OID 16473)
-- Name: addlimpmaqadjunto(bigint, bigint, text); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addlimpmaqadjunto(idlimpiezamaquinai bigint, correlativoi bigint, archivoadjuntoi text) RETURNS void
    LANGUAGE plpgsql
    AS $$

BEGIN

	if ( select 1 
	       from traking.mct_limpiezamaquinaadjunto 
	      where idlimpiezamaquina = idlimpiezamaquinai and  
	            correlativo = correlativoi) then 
	            
	     update traking.mct_limpiezamaquinaadjunto 
	        set archivoadjunto = archivoadjuntoi
	      where idlimpiezamaquina = idlimpiezamaquinai
	        and correlativo = correlativoi;
	
	else 
	
		INSERT INTO traking.mct_limpiezamaquinaadjunto 
               (idlimpiezamaquinaadjunto , idlimpiezamaquina , correlativo, archivoadjunto )
         values
              (nextval('traking.mct_limpiezamaquinaadjunto_seq'), 
              idlimpiezamaquinai, 
              correlativoi, 
              archivoadjuntoi
             );
            
	end if;


END
$$;


ALTER FUNCTION traking.addlimpmaqadjunto(idlimpiezamaquinai bigint, correlativoi bigint, archivoadjuntoi text) OWNER TO postgres;

--
-- TOC entry 1522 (class 1255 OID 16474)
-- Name: addlimpmaqparcial(bigint, bigint, bigint, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addlimpmaqparcial(idusuarioi bigint, idsubseccioni bigint, idmaquinai bigint, idoperatori bigint, iddefectoi bigint, idcierrei bigint, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	integer;
      
begin
	
	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;

	select idlimpiezamaquina ,
	       idcierre
	  into sp_id,
	       sp_cierre
	  from mct_limpiezamaquina
	 where idmaquina = idmaquinai
	   and idcierre = 0;
	  
	  
	if ( sp_id > 0 and sp_cierre = 0) then
	
	    update traking.mct_limpiezamaquina 
	       set idusuario = idusuarioi, 
	           idsubseccion = idsubseccioni, 
	           idmaquina = idmaquinai,
	           idoperador = idoperatori,
	           iddefecto = iddefectoi,
	           idcierre = idcierrei , 
	           usuariomodificacion = 'admin', 
	           fechamodificacion = now()
	     where iddefectofundicion = sp_id;
	
	else
	
		sp_id := nextval('traking.mct_limpiezamaquina_seq');

		INSERT INTO traking.mct_limpiezamaquina 
	               (idlimpiezamaquina , 
	               idusuario, 
	               idsubseccion ,
	               idmaquina ,
	               idoperador ,
	               iddefecto , 
	               idcierre , 
	               usuariocreacion, 
	               fechacreacion)
	         values
	              (sp_id,
	              idusuarioi, 
	              idsubseccioni ,
	              coalesce (idmaquinai, 0) ,
	              coalesce (idoperatori, 0) ,
	              coalesce (iddefectoi, 0) ,
	              idcierrei ,
	              usercreatei, 
	              now()
	             );
	            
	
	end if;

    RETURN sp_id;  

END
$$;


ALTER FUNCTION traking.addlimpmaqparcial(idusuarioi bigint, idsubseccioni bigint, idmaquinai bigint, idoperatori bigint, iddefectoi bigint, idcierrei bigint, usercreatei character varying) OWNER TO postgres;

