-- Name: addmachine(bigint, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addmachine(idsubsection bigint, namemachine character varying, codemachine character varying, codenew character varying, codelcd character varying, status integer, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

	sp_id		bigint;
    md5temp		varchar;

BEGIN

	sp_id	:= nextval('traking.mct_maquina_seq');

	md5temp = CAST(sp_id AS varchar);

    SELECT MD5(md5temp) into md5temp;
   
    insert into traking.mct_maquina (
	          "idsubseccion", 
	          "idmaquina", 
	          "nombremaquina", 
	          codigomaquina, 
	          codigonuevo, 
	          codigolcd, 
	          "estado", 
	          "fechacreacion", 
	          "usuariocreacion",
	          qrcodigo
	          ) 
       values ( 
               idsubsection, 
               sp_id, 
               namemachine, 
               codemachine, 
               codenew, 
               codelcd, 
               status, 
               now(), 
               usercreate ,
               md5temp
               );

END
$$;


ALTER FUNCTION traking.addmachine(idsubsection bigint, namemachine character varying, codemachine character varying, codenew character varying, codelcd character varying, status integer, usercreate character varying) OWNER TO postgres;

