--
-- TOC entry 2218 (class 1255 OID 16486)
-- Name: addmovimientoordentrabajooperador(bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addmovimientoordentrabajooperador(idmovimientoordentrabajoi bigint, codhojarutai character varying, idoperadori bigint, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare

	sp_glosamotivo      varchar;
	sp_nombreoperador	varchar;

BEGIN

    insert into traking.mct_movimientoordentrabajooperador 
           (
            idmovimientoordentrabajooperador, 
            idmovimientoordentrabajo, 
            codhojaruta, 
            idoperador,
            fechacreacion, 
            usuariocreacion
           ) 
    values ( 
            nextval('traking.mct_movimientoordentrabajooperador_seq'), 
            idmovimientoordentrabajoi, 
            codhojarutai, 
            idoperadori,
            now(), 
            usercreate 
           );
          
    select nombreoperador
      into sp_nombreoperador
      from mct_operador mo
     where idoperador = idoperadori;

    
    sp_glosamotivo := 'Se agrega el operador : '||sp_nombreoperador;
   
    update traking.mct_movimientoordentrabajo 
       set observacion = observacion||E'\n'||sp_glosamotivo
     where idmovimientoordentrabajo = idmovimientoordentrabajoi;          

END
$$;


ALTER FUNCTION traking.addmovimientoordentrabajooperador(idmovimientoordentrabajoi bigint, codhojarutai character varying, idoperadori bigint, usercreate character varying) OWNER TO postgres;

