-- TOC entry 2075 (class 1255 OID 16488)
-- Name: addncfcaldadjunto(bigint, bigint, text); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addncfcaldadjunto(idnoconformidadcaldi bigint, correlativoi bigint, archivoadjuntoi text) RETURNS void
    LANGUAGE plpgsql
    AS $$

BEGIN

	if ( select 1 
	       from traking.mct_noconformidadcaldadjunto mn 
	      where idnoconformidadcald = idnoconformidadcaldi and  
	            correlativo = correlativoi) then 
	            
	     update traking.mct_noconformidadcaldadjunto 
	        set archivoadjunto = archivoadjuntoi
	      where idnoconformidadcald = idnoconformidadcaldi
	        and correlativo = correlativoi;
	
	else 
	
		INSERT INTO traking.mct_noconformidadcaldadjunto 
               (idnoconformidadcaldadjunto , idnoconformidadcald , correlativo, archivoadjunto )
         values
              (nextval('traking.mct_noconformidadcaldadjunto_seq'), 
              idnoconformidadcaldi, 
              correlativoi, 
              archivoadjuntoi
             );
            
	end if;


END
$$;


ALTER FUNCTION traking.addncfcaldadjunto(idnoconformidadcaldi bigint, correlativoi bigint, archivoadjuntoi text) OWNER TO postgres;

--
-- TOC entry 1483 (class 1255 OID 16489)
-- Name: addncfcaldparcial(character varying, bigint, bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addncfcaldparcial(codhojarutai character varying, idusuarioi bigint, idseccioni bigint, comentarioi character varying, idclosei bigint, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	integer;
      
begin
	
	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;

	select idnoconformidadcald,
	       idcierre
	  into sp_id,
	       sp_cierre
	  from mct_noconformidadcald
	 where codhojaruta = codhojarutai
	   and idcierre = 0;
	  
	  
	if ( sp_id > 0 and sp_cierre = 0) then
	
	    update traking.mct_noconformidadcald 
	       set codhojaruta = codhojarutai, 
	           idusuario = idusuarioi, 
	           idseccion = idseccioni, 
	           comentario = comentarioi, 
	           idcierre = idclosei , 
	           usuariomodificacion = 'admin', 
	           fechamodificacion = now()
	     where idnoconformidadcald = sp_id;
	
	else
	
		sp_id := nextval('traking.mct_noconformidadcald_seq');

		INSERT INTO traking.mct_noconformidadcald 
	               (idnoconformidadcald , 
	               codhojaruta, 
	               idusuario, 
	               idseccion , 
	               comentario , 
	               idcierre , 
	               usuariocreacion, 
	               fechacreacion)
	         values
	              (sp_id, 
	              codhojarutai, 
	              idusuarioi, 
	              idseccioni ,
	              comentarioi, 
	              idclosei ,
	              usercreatei, 
	              now()
	             );
	            
	
	end if;

    RETURN sp_id;  

END
$$;


ALTER FUNCTION traking.addncfcaldparcial(codhojarutai character varying, idusuarioi bigint, idseccioni bigint, comentarioi character varying, idclosei bigint, usercreatei character varying) OWNER TO postgres;

