CREATE FUNCTION traking.addoperadorturno(idoperadorturnoi bigint, idoperadori bigint, fechaturnoi character varying, turno13i boolean, turno16i boolean, turno18i boolean, turno20i boolean, turnoexcepcionali boolean, turnonochei boolean, idhoraminutoi bigint, turnootroi boolean, idhoraminutootroi bigint, ausentei boolean, idmotivoausenciai bigint, observacioni character varying, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idoperadorturnoi > 0 ) then
	
	    update traking.mct_operadorturno 
	       set turno13 = turno13i ,
	           turno16 = turno16i ,
	           turno18 = turno18i ,
	           turno20 = turno20i ,
	           turnoexcepcional = turnoexcepcionali ,
