--
-- TOC entry 1529 (class 1255 OID 16501)
-- Name: addoperator(bigint, character varying, character varying, bigint, bigint, boolean, character varying, bigint, bigint, boolean, boolean, boolean, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addoperator(idprofile bigint, nameoperator character varying, rut character varying, status bigint, idmachine bigint, movilizacionpropiai boolean, direccioni character varying, idsectori bigint, telefonocontactoi bigint, aplicacontrolturnoi boolean, aplicacontrolturnofundi boolean, aplicacontrolturnofund2i boolean, idseccionprincipali bigint, idcargoi bigint, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
	
		rutn 		VARCHAR := 0;
		rutd 		VARCHAR := '';
		sp_idperfil	bigint	:= 6;
		
BEGIN


	if (idseccionprincipali = 11 ) then
		sp_idperfil	:= 9;
	elsif (idseccionprincipali = 14 ) then
		sp_idperfil	:= 8;	
	elsif (idseccionprincipali = 76 ) then
		sp_idperfil	:= 16;
	elsif (idseccionprincipali = 77 ) then
		sp_idperfil	:= 16;
	elsif (idseccionprincipali = 39 ) then
		sp_idperfil	:= 14;
	elsif (idseccionprincipali = 36 ) then
		sp_idperfil	:= 15;
	end if;
	
   rutn := split_part(rut,'-',1);
   rutd := split_part(rut,'-',2);
   
   insert into traking.mct_operador ("idperfil", 
	    idoperador, 
	    nombreoperador, 
	    estado, 
	    fechacreacion, 
	    usuariocreacion,
	    rut,
	    digito,
	    idmaquina,
        movilizacionpropia,
        direccion,
        idsector,
        telefonocontacto,
        aplicacontrolturno,
        aplicacontrolturnofund,
        aplicacontrolturnofund2,
        idseccionprincipal	,
        idcargo 
	 ) 
   values ( sp_idperfil,
		nextval('traking.mct_operador_seq'), 
		nameoperator, 
		status, 
		now(), 
		usercreate,
		rutn,
		rutd,
		idmachine ,
        movilizacionpropiai,
        direccioni,
        idsectori,
        telefonocontactoi,
        aplicacontrolturnoi,
        aplicacontrolturnofundi,
        aplicacontrolturnofund2i,
        idseccionprincipali	,
        idcargoi
	);

END
$$;


