--
-- TOC entry 1564 (class 1255 OID 16510)
-- Name: addparttipworkactivity(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addparttipworkactivity(idparttipwork bigint, idactivity bigint, orderact bigint, productiontime bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 
        sp_orden  	    INTEGER;
       
       BEGIN

	sp_orden := orderact;

	if (orderact = 0) then
		select coalesce (max(orden),null,0) 
		  into sp_orden 
		  from mct_partetipotrabajoactividad 
		 where idpartetipotrabajo = idparttipwork ;
		 --  and orden = orderact;
    
    end if;
   
	
	if (sp_orden = 0) then 
                
       insert into traking.mct_partetipotrabajoactividad 
	              (idpartetipotrabajoactividad , 
	               idpartetipotrabajo , 
	               idactividad, 
	               orden,
	               tiempoproduccion )
	       values ( nextval('traking.mct_partetipotrabajoactividad_seq'), 
	               idparttipwork, 
	               idactivity,
		           1,
	               productiontime  );
                
	else 
	
		if (orderact > 0) then 
		
			update traking.mct_partetipotrabajoactividad 
			   set orden = orden + 1
			 where idpartetipotrabajo = idparttipwork
			   and orden >= orderact;
			 
		                
		    insert into traking.mct_partetipotrabajoactividad 
	                   (idpartetipotrabajoactividad , 
	                    idpartetipotrabajo , 
	                    idactividad, 
	                    orden,
	                    tiempoproduccion )
	            values ( nextval('traking.mct_partetipotrabajoactividad_seq'), 
	                    idparttipwork, 
	                    idactivity,
		                 orderact,
	                    productiontime  );
	    else
	                
		    insert into traking.mct_partetipotrabajoactividad 
	                   (idpartetipotrabajoactividad , 
	                    idpartetipotrabajo , 
	                    idactividad, 
	                    orden,
	                    tiempoproduccion )
	            values ( nextval('traking.mct_partetipotrabajoactividad_seq'), 
	                     idparttipwork, 
	                     idactivity,
	                     sp_orden + 1,
	                     productiontime  );
	    
	    end if;
	   
		
	end if;
	
end

--BEGIN

--    insert into traking.mct_partetipotrabajoactividad 
--               (idpartetipotrabajoactividad , 
--               idpartetipotrabajo , 
--                idactividad, 
--                tiempoproduccion )
--        values ( nextval('traking.mct_partetipotrabajoactividad_seq'), 
--                 idparttipwork, 
--                 idactivity,
--                 timeproduction  );

--END
$$;


