--
-- TOC entry 885 (class 1255 OID 16512)
-- Name: addproduct(character varying, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addproduct(nameproduct character varying, idmanufacturer bigint, idmodel bigint, idcustomer bigint, status bigint, flowval bigint, rpmval bigint, lengthval bigint, heightval bigint, powerval bigint, idphaseparam bigint, generalplan character varying, idmaterialp bigint, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_nombreproducto		varchar;
		sp_idproducto			integer;
	    sp_nombreetapa          varchar;
	   
begin

	    select nombreparam 
	      into sp_nombreetapa
    	  from traking.mct_etapaparam 
    	 where idetapaparam = idphaseparam;
    	
    	if ( idphaseparam = 13 ) then

		   	select c.nombrefamilia||' - '||b.nombresubfamilia||' - '||a.nombremodelo
		      into sp_nombreproducto
		      from mct_modelo a,
		  	       mct_subfamilia b,
				   mct_familia c
			 where a.idmodelo = idmodel
		   	   and a.idsubfamilia = b.idsubfamilia 
			   and b.idfamilia  = c.idfamilia ;    	
    	
    	else
    	
	  	   	select c.nombrefamilia||' - '||b.nombresubfamilia||' - '||a.nombremodelo||' - '||sp_nombreetapa
		      into sp_nombreproducto
		      from mct_modelo a,
		  	       mct_subfamilia b,
				   mct_familia c
			 where a.idmodelo = idmodel
		   	   and a.idsubfamilia = b.idsubfamilia 
			   and b.idfamilia  = c.idfamilia ;
		  
    	end if;
		
		sp_idproducto = nextval('traking.mct_producto_seq');

	    insert into traking.mct_producto 
	               (idproducto, 
	               nombreproducto, 
	               idfabricante, 
	               idmodelo,
	               idcliente, 
	               estado, 
	               fechacreacion,
	               usuariocreacion,
	               caudal, 
	               rpm, 
	               largo,
	               altura, 
	               potencia, 
	               idetapaparam, 
	               planogeneral , 
	               idmaterial ) 
	         values 
	               (sp_idproducto, 
	                sp_nombreproducto, 
	                idmanufacturer, 
	                idmodel, 
	           	    idcustomer, 
	           	    status, 
	           	    now(), 
	           	    usercreate, 
	           	    flowval, 
	           	    rpmval, 
	           	    lengthval,
	           	    heightval, 
	           	    powerval, 
	           	    idphaseparam, 
	           	    generalplan, 
	           	    idmaterialp 
	           	   );

	        insert into traking.mct_productoparte 
	        select nextval('mct_productoparte_seq'),
	               sp_idproducto,
	               a.idparte ,
			       --a.nombreparte ,
			       --a.idplano ,
			       b.cantidad 
			       --b.nombreplano ,
			       --a.esprincipal 
			  from mct_parte a ,
			       mct_plano b ,
			       mct_producto c
			 where a.idplano = b.idplano 
			 and   b.nombreplano like '%'||c.planogeneral ||'%'
			 and   c.idproducto = sp_idproducto
			order by esprincipal asc, idparte asc;
		
		    insert into traking.mct_productoplano 
		    select nextval('mct_productoplano_seq'),
		           sp_idproducto,
		           a.idplano
		      from traking.mct_plano a,
		           traking.mct_producto b
		     where b.idproducto = sp_idproducto
		       and a.nombreplano like '%'||b.planogeneral ||'%'
		       and idtipoplano = 39
		      order by a.idplano asc;

END
$$;


