-- TOC entry 1607 (class 1255 OID 16517)
-- Name: addprogramafacturacionresumenfoto(bigint, boolean, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addprogramafacturacionresumenfoto(idordentrabajoi bigint, checkdescartei boolean, periodoi bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

   sp_tiene    integer;

BEGIN

	select coalesce(count(*), 0)
	  into sp_tiene
	  from mct_programafacturacionresumenfoto a 
	 where a.idordentrabajo = idordentrabajoi
       and a.periodo = periodoi;

	if (sp_tiene > 0) then

		update mct_programafacturacionresumenfoto
		   set checkdescarte = checkdescartei
	 	 where idordentrabajo = idordentrabajoi
           and periodo = periodoi;

	else
	
		INSERT INTO traking.mct_programafacturacionresumenfoto
		           (idprogramafacturacionresumenfoto, 
		            idordentrabajo, 
		            checkdescarte, 
		            periodo
		            )
		     VALUES(nextval('traking.mct_programafacturacionresumenfoto_seq'), 
		            idordentrabajoi, 
		            checkdescartei,
		            periodoi
		           );

	end if;


END
$$;


