-- TOC entry 1263 (class 1255 OID 16522)
-- Name: addrecepcionmateriaprima(bigint, bigint, bigint, character varying, bigint, bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addrecepcionmateriaprima(idmateriali bigint, idproveedori bigint, cantidadi bigint, entregai character varying, idrecibei bigint, nroguiai bigint, fechaguiai character varying, idusuarioi bigint, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      integer;
       sp_cierre  integer;
begin
	
	sp_id     := 0;

	sp_id := nextval('traking.inv_recepcionmateriaprima_seq');

	INSERT INTO traking.mct_recepcionmateriaprima
	           (idrecepcionmateriaprima, 
	            idmaterial, 
	            idproveedor, 
	            cantidad, 
	            entrega, 
	            idrecibe, 
	            nroguia,
	            fechaguia,
	            idusuario, 
	            usuariocreacion, 
	            fechacreacion
	            )       
	      values
	            (sp_id, 
			     idmateriali, 
			     idproveedori, 
			     cantidadi, 
			     entregai, 
		         idrecibei, 
			     nroguiai, 
			     to_date(fechaguiai, 'dd-mm-yyyy'), 
			     idusuarioi, 
			     usercreatei,
	             now()
	            );
	            
	
    RETURN sp_id;  

END
$$;


