--
-- TOC entry 1981 (class 1255 OID 16523)
-- Name: addrecepcionpiezatablet(character varying, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addrecepcionpiezatablet(codhojarutai character varying, idoperadori bigint, idaccioni bigint, usercreatei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_id      		integer;
       sp_cierre  		integer;
       sp_cantidad 		integer;
       sp_componente	bigint;
       sp_plano			varchar;
       sp_usuario		varchar;
       sp_idot			bigint;
      
       sp_accion		varchar;
       sp_area			bigint;
   	   sp_seccion		bigint;
   	   sp_salida		varchar;
   	  
   	   sp_mensaje		varchar;
   	  
   
begin
	
	sp_id     		:= 0;
    sp_cierre 		:= 0;
    sp_cantidad		:= 0;
    sp_componente	:= 0;
    sp_plano        := '';
    sp_usuario		:= '';
    sp_idot			:= 0;
    sp_accion		:= '';
   
    sp_area			:= 0;
   	sp_seccion		:= 0;
    sp_salida		:= '';
    sp_mensaje		:= '';
   
   	select idareaapp ,
   	       idseccionapp
	  into sp_area,
	       sp_seccion
	  from mct_operador
	 where idoperador = idoperadori;
	
   	select codigoaccion
      into sp_accion
   	  from mct_accion 
   	 where idaccion = idaccioni;
		    
   	sp_mensaje	:= 'Se procede con la recepción de la Pieza asociada a la hoja de Ruta : '||codhojarutai;
   
	select *
	  into sp_id
	  from evtaddregisterjobrecepcionpieza(idoperadori, codhojarutai, sp_accion, sp_seccion, 0, 0, 2, 42, sp_mensaje, null, 5 );
	
    RETURN sp_id;  

END
$$;


ALTER FUNCTION traking.addrecepcionpiezatablet(codhojarutai character varying, idoperadori bigint, idaccioni bigint, usercreatei character varying) OWNER TO postgres;

