--

CREATE FUNCTION traking.addrecorridocontrol(idcaracterizacionup bigint, planoup character varying, idclienteup bigint, idfamiliaup bigint, idproductoup bigint, idproductonepcastup bigint, idcomponenteup bigint, idmaterialup bigint, codigomoldeup character varying, pesopiezacoladaascastup double precision, porcentajeutilizacioncanchaup double precision, cantidadhornoup double precision, iddobleup bigint, idsimpleup bigint, pesopiezalimpiaup double precision, porcentajeascastretornoup double precision, pesopiezaliberadaup double precision, porcentajepiezaliberadaup double precision, tiempodecoladaup double precision, tiempodefusionup double precision, cucharasup double precision, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_id			bigint;
   
    sp_cuentapt		numeric;
    sp_cuentart		numeric;
    sp_cuentaepp	numeric;
    sp_cuentamar	numeric;

begin
   
   
	if ( idcaracterizacionup > 0 ) then
    
    
		UPDATE traking.mct_caracterizacion
		   SET idcliente=idclienteup, 
		       idfamilia=idfamiliaup, 
		       idproducto=idproductoup, 
		       idproductonepcast=idproductonepcastup, 
		       idcomponente=idcomponenteup, 
		       idmaterial=idmaterialup, 
		       codigomolde=codigomoldeup, 
		       pesopiezacoladaascast=pesopiezacoladaascastup,
		       porcentajeutilizacioncancha=porcentajeutilizacioncanchaup, 
		       cantidadhorno=cantidadhornoup, 
		       iddoble=iddobleup, 
		       idsimple=idsimpleup, 
		       pesopiezalimpia=pesopiezalimpiaup, 
