--

CREATE FUNCTION traking.addrecorridocontrol(idrecorridocontroli bigint, idoperadori bigint, fechacontroli character varying, control1pti boolean, control1rti boolean, control1eppi boolean, control1mari boolean, control2pti boolean, control2rti boolean, control2eppi boolean, control2mari boolean, control3pti boolean, control3rti boolean, control3eppi boolean, control3mari boolean, control4pti boolean, control4rti boolean, control4eppi boolean, control4mari boolean, observacioni character varying, esfundicion1i boolean, esfundicion2i boolean, esmaestranzai boolean, ausentei boolean, idmotivoausenciai bigint, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_id			bigint;
   
    sp_cuentapt		numeric;
    sp_cuentart		numeric;
    sp_cuentaepp	numeric;
    sp_cuentamar	numeric;

begin
	
	sp_cuentapt		:= 0;
    sp_cuentart		:= 0;
    sp_cuentaepp	:= 0;
    sp_cuentamar	:= 0;
   
    if (control1pti is true) then
    	sp_cuentapt	:= sp_cuentapt + 1;
    end if;
    if (control2pti is true) then
    	sp_cuentapt	:= sp_cuentapt + 1;
    end if;
    if (control3pti is true) then
    	sp_cuentapt	:= sp_cuentapt + 1;
    end if;
    if (control4pti is true) then
    	sp_cuentapt	:= sp_cuentapt + 1;
    end if;

    if (control1rti is true) then
    	sp_cuentart	:= sp_cuentart + 1;
    end if;
    if (control2rti is true) then
    	sp_cuentart	:= sp_cuentart + 1;
    end if;
    if (control3rti is true) then
    	sp_cuentart	:= sp_cuentart + 1;
    end if;
    if (control4rti is true) then
    	sp_cuentart	:= sp_cuentart + 1;
    end if;
   
    if (control1eppi is true) then
    	sp_cuentaepp	:= sp_cuentaepp + 1;
    end if;
    if (control2eppi is true) then
    	sp_cuentaepp	:= sp_cuentaepp + 1;
    end if;
    if (control3eppi is true) then
    	sp_cuentaepp	:= sp_cuentaepp + 1;
    end if;
    if (control4eppi is true) then
    	sp_cuentaepp	:= sp_cuentaepp + 1;
    end if;
   
    if (control1mari is true) then
    	sp_cuentamar	:= sp_cuentamar + 1;
    end if;
    if (control2mari is true) then
    	sp_cuentamar	:= sp_cuentamar + 1;
    end if;
    if (control3mari is true) then
    	sp_cuentamar	:= sp_cuentamar + 1;
    end if;
    if (control4mari is true) then
    	sp_cuentamar	:= sp_cuentamar + 1;
    end if;
   
   
	if ( idrecorridocontroli > 0 ) then
     
	    update traking.mct_recorridocontrol 
	       set control1pt = control1pti ,
	           control1rt = control1rti ,
	           control1epp = control1eppi ,
	           control1mar = control1mari ,
	           control2pt = control2pti ,
	           control2rt = control2rti ,
	           control2epp = control2eppi ,
	           control2mar = control2mari ,
	           control3pt = control3pti ,
	           control3rt = control3rti ,
	           control3epp = control3eppi ,
	           control3mar = control3mari ,
	           control4pt = control4pti ,
	           control4rt = control4rti ,
	           control4epp = control4eppi ,
	           control4mar = control4mari ,
	           resumenpt = (sp_cuentapt / 4) * 100,
	           resumenrt = (sp_cuentart / 4) * 100,
	           resumenepp = (sp_cuentaepp / 4) * 100,
	           resumenmar = (sp_cuentamar / 4) * 100,
	           observacion = observacioni,
	           esfundicion1 = esfundicion1i,
	           esfundicion2 = esfundicion2i,
	           esmaestranza = esmaestranzai,
	           ausente = ausentei,
	           idmotivoausencia = idmotivoausenciai , 
	           fechamodificacion = now(),
	           usuariomodificacion = usercreate
	     where idrecorridocontrol = idrecorridocontroli;
    
	else 
	
		sp_id	:= nextval('traking.mct_recorridocontrol_seq');
	    insert into traking.mct_recorridocontrol  
                (
                 idrecorridocontrol, 
                 idoperador,
                 fechacontrol, 
                 control1pt,
	             control1rt,
	             control1epp,
	             control1mar,
	             control2pt,
	             control2rt,
	             control2epp,
	             control2mar,
	             control3pt,
	             control3rt,
	             control3epp,
	             control3mar,
	             control4pt,
	             control4rt,
	             control4epp,
	             control4mar,
	             resumenpt,
	             resumenrt,
	             resumenepp,
	             resumenmar,
                 observacion,
                 esfundicion1 ,
                 esfundicion2 ,
                 esmaestranza,
                 ausente ,
                 idmotivoausencia,
                 fechacreacion, 
                 usuariocreacion
	           ) 
         values ( 
                 sp_id, 
                 idoperadori,
                 to_date(fechacontroli, 'yyyy-mm-dd'), 
                 control1pti,
	             control1rti,
	             control1eppi,
	             control1mari,
	             control2pti,
	             control2rti,
	             control2eppi,
	             control2mari,
	             control3pti,
	             control3rti,
	             control3eppi,
	             control3mari,
	             control4pti,
	             control4rti,
	             control4eppi,
	             control4mari,
	             (sp_cuentapt / 4) * 100,
	             (sp_cuentart / 4) * 100,
	             (sp_cuentaepp / 4) * 100,
	             (sp_cuentamar / 4) * 100,
                 observacioni,
                 esfundicion1i,
                 esfundicion2i,
                 esmaestranzai,
                 ausentei ,
                 idmotivoausenciai ,
                 now(), 
                 usercreate
                );

         
	end if;

END
$$;


