-- Name: addrecorridocontrolpdfsave(character varying, text, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addrecorridocontrolpdfsave(fechacontrols character varying, filepdf text, filename character varying, idprocess bigint, usercreate character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

begin
	
      IF (select 1
		    from mct_recorridocontrolpdf 
           where nombrearchivo   = filename
             and idproceso       = idprocess) then
           
			UPDATE traking.mct_recorridocontrolpdf
			   set archivoadjunto  = filepdf,
			       fechamodificacion = now(),
			       usuariomodificacion = usercreate
			 where nombrearchivo   = filename; 	

	  else
             
			insert into traking.mct_recorridocontrolpdf (
			      idtrecorridocontrolpdf ,
				  fechacontrol,
				  archivoadjunto,
				  nombrearchivo ,
				  idproceso,
				  fechacreacion,
				  usuariomodificacion
				 ) 
				values (
				  nextval('mct_recorridocontrolpdf_seq'),
				  to_date(fechacontrols,'yyyy-mm-dd'),
				  filepdf,
				  filename,
				  idprocess,
				  now(),
				  usercreate
				);	
      END IF;

     return 0;

END;
$$;


