--

CREATE FUNCTION traking.addroadmapactivitytemp(idroadmaptemp bigint, idactivity bigint, orderact bigint, productiontime bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 
        sp_orden  	    INTEGER;
BEGIN

	sp_orden := orderact;

	if (orderact = 0) then
		select coalesce (max(orden),null,0) 
		  into sp_orden 
		  from mct_hojarutaactividadtemp 
		 where idhojarutatemp = idroadmaptemp ;
		 --  and orden = orderact;
    
    end if;
   
	
	if (sp_orden = 0) then 
		  
		INSERT INTO traking.mct_hojarutaactividadtemp 
                (idhojarutaactividadtemp , 
                 idhojarutatemp , 
                 idactividad , 
                 orden ,
                 tiempoproduccion )
          VALUES(nextval('mct_hojarutaactividadtemp_seq'), 
                 idroadmaptemp, 
                 idActivity, 
                 1,
                 productiontime);
                
	else 
	
		if (orderact > 0) then 
		
			update traking.mct_hojarutaactividadtemp 
			   set orden = orden + 1
			 where idhojarutatemp = idroadmaptemp
			   and orden >= orderact;
			  

			INSERT INTO traking.mct_hojarutaactividadtemp 
		                (idhojarutaactividadtemp , 
		                 idhojarutatemp , 
		                 idactividad , 
		                 orden ,
		                 tiempoproduccion )
		          VALUES(nextval('mct_hojarutaactividadtemp_seq'), 
		                 idroadmaptemp, 
		                 idActivity, 
		                 orderact,
		                 productiontime);
	    else
	    
	    	INSERT INTO traking.mct_hojarutaactividadtemp 
	                (idhojarutaactividadtemp , 
	                 idhojarutatemp , 
	                 idactividad , 
	                 orden ,
	                 tiempoproduccion )
	          VALUES(nextval('mct_hojarutaactividadtemp_seq'), 
	                 idroadmaptemp, 
	                 idActivity, 
	                 sp_orden + 1,
	                 productiontime);
	    
	    end if;
	    
		
	end if;
	
end

$$;


