--
-- TOC entry 1558 (class 1255 OID 16531)
-- Name: addroadmaptemp(bigint, bigint, bigint, character varying, character varying, bigint, character varying, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addroadmaptemp(idworkorder bigint, idcomponent bigint, idmaterial bigint, materialname character varying, blueprintname character varying, quantity bigint, aditionaltext character varying, idworkhr bigint, itemcorri bigint, idimprimehojasi bigint, idboleanoi bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 

        sp_idhr   				    INTEGER;

        sp_hrchar                   TEXT;
        sp_partchar                 TEXT;
        sp_itemchar                 TEXT;
        sp_corrchar                 TEXT;

        indice   				    INTEGER;
        tope	   				    INTEGER;
       
        sp_idpwo   				    INTEGER;
        sp_idtipoorden              integer;       
       
BEGIN

	sp_idhr := nextval('traking.mct_hojarutatemp_seq');
		       
	INSERT INTO traking.mct_hojarutatemp
                (idhojarutatemp, 
                 idordentrabajo, 
                 idcomponente, 
                 idmaterial, 
                 nombrematerial,
                 nombreplano, 
                 cantidad,
                 textoadicional,
                 idtrabajohr,
                 idimprimehojas,
                 idboleano)
          VALUES(sp_idhr, 
                 idworkorder, 
                 idcomponent, 
                 idmaterial, 
                 materialname,
                 blueprintname, 
                 quantity,
                 aditionaltext,
                 idworkhr,
                 idimprimehojasi,
                 idboleanoi
                );

	select idtipoorden 
	  into sp_idtipoorden
	  from mct_ordentrabajo
	 where idordentrabajo = idworkorder;
	
	if ( sp_idtipoorden = 1 ) then -- Remanufactura
	   -- con 27
	
	    insert into mct_hojarutaactividadtemp 
	                (
	                idhojarutaactividadtemp ,
	                idhojarutatemp ,
	                idactividad ,
	                tiempoproduccion ,
	                orden 
	                )        	     
			select nextval('mct_hojarutaactividadtemp_seq'),
			       sp_idhr,
			       idactividad , 
			       tiempoproduccion , 
			       orden 
			  from mct_partetipotrabajoactividad mp 
			 where idpartetipotrabajo = ( select idcomponentetipotrabajo 
									        from mct_componentetipotrabajo mc
									       where idcomponente  = idcomponent
									         and idtipotrabajo in (27))
			order by idpartetipotrabajoactividad  asc, orden asc;
		
	end if;
	

	if ( sp_idtipoorden = 2 ) then -- fabricacion
		   -- con 21
		   
		    insert into mct_hojarutaactividadtemp 
	                (
	                idhojarutaactividadtemp ,
	                idhojarutatemp ,
	                idactividad ,
	                tiempoproduccion ,
	                orden 
	                )        	     
			select nextval('mct_hojarutaactividadtemp_seq'),
			       sp_idhr,
			       idactividad , 
			       tiempoproduccion , 
			       orden 
			  from mct_partetipotrabajoactividad mp 
			 where idpartetipotrabajo = ( select idcomponentetipotrabajo 
									        from mct_componentetipotrabajo mc
									       where idcomponente  = idcomponent 
									         and idtipotrabajo in (21))
			order by idpartetipotrabajoactividad  asc, orden asc;
	
	end if;                
                
    if ( idimprimehojasi = 1 ) then
    
       tope  := 1;
      
    else
 
    	tope := coalesce(quantity,0);
    
    end if;

		           
	indice := 1;
		
	loop						
	
		sp_hrchar   := LPAD(idWorkorder::integer::text::varchar, 6, '0');  
		sp_partchar := LPAD(idComponent::integer::text::varchar, 3, '0');
		sp_itemchar := LPAD(itemcorri::integer::text::varchar, 3, '0'); 	
		sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
		
		insert into mct_detallehojarutatemp 
		           (iddetallehojarutatemp 
		           ,idhojarutatemp 
		           ,codhojaruta 
		           ,correlativoparte
		           )
		     VALUES
		           (nextval('traking.mct_detallehojarutatemp_seq')
		           ,sp_idhr
		           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
		           ,indice
		           );                     

		         
		sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
	
		insert into mct_ordentrabajoparte 
		           (idordentrabajoparte 
		           ,idordentrabajo 
		           ,idcomponente 
		           ,itemparte
		           ,itemcorr 
		           )
		     VALUES
		           (sp_idpwo
		           ,idworkorder
		           ,idcomponent 
		           ,indice
		           ,itemcorri
		           );   

		-- Esto es para igualar la tabla Hoja Ruta
	    insert into mct_hojaruta 
		           (idhojaruta 
		           ,idordentrabajoparte 
		           ,codhojaruta 
		           ,usuariocreacion 
		           ,fechacreacion
		           ,modalidad 
		           ,idhojarutatemp 
		           )
		     VALUES
		           (nextval('traking.mct_hojaruta_seq')
		           ,sp_idpwo
		           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
		           ,'admin' 
		           ,now()
		           ,1
		           ,sp_idhr
		           ); 
		          
		 indice := indice + 1;
		                           				   
		 EXIT when indice > tope;
		                    
	END loop;                
	
END
$$;


