--
-- TOC entry 888 (class 1255 OID 16533)
-- Name: addroadmaptemppiezafundicion(bigint, bigint, bigint, character varying, character varying, bigint, character varying, bigint, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addroadmaptemppiezafundicion(idworkorder bigint, idcomponent bigint, idmaterial bigint, materialname character varying, blueprintname character varying, quantity bigint, aditionaltext character varying, idcriterioevaluacioni bigint, itemcorri bigint, idimprimehojasi bigint, idboleanoi bigint, nombrezonai character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 

        sp_idhr   				    INTEGER;
        
        sp_id                       integer;

        sp_hrchar                   TEXT;
        sp_partchar                 TEXT;
        sp_itemchar                 TEXT;
        sp_corrchar                 TEXT;

        indice   				    INTEGER;
        tope	   				    INTEGER;
       
        sp_idpwo   				    INTEGER;
        sp_idtipoorden              integer;   
        sp_indicefila				integer;
       
        sp_areaclasificacion		integer;
        sp_fechafundicion			timestamp;
       
BEGIN
	
	sp_areaclasificacion := 0;
	sp_indicefila		 := 0;
    sp_fechafundicion	 := null;

    select max(indicefila)+1
      into sp_indicefila
      from mct_checklistinftec mc
     where idordentrabajo = idworkorder;

	select idtipoorden,
	       coalesce (fechafaceclte, fechaentrega) - interval '15 day'
	  into sp_idtipoorden,
	       sp_fechafundicion
	  from mct_ordentrabajo
	 where idordentrabajo = idworkorder;
   
	
	select coalesce (idareaclasificacion , 0)
	  into sp_areaclasificacion
	  from mct_componente
	 where idcomponente = idcomponent;
	
	sp_idhr := nextval('traking.mct_hojarutatemp_seq');
		       
	INSERT INTO traking.mct_hojarutatemp
                (idhojarutatemp, 
                 idordentrabajo, 
                 idcomponente, 
                 idmaterial, 
                 nombrematerial,
                 nombreplano, 
                 cantidad,
                 textoadicional,
                 idcriterioevaluacion ,
                 idimprimehojas,
                 idboleano,
                 idareaclasificacion,
                 nombrezona)
          VALUES(sp_idhr, 
                 idworkorder, 
                 idcomponent, 
                 idmaterial, 
                 materialname,
                 blueprintname, 
                 quantity,
                 aditionaltext,
                 idcriterioevaluacioni,
                 idimprimehojasi,
                 idboleanoi,
                 8,
                 nombrezonai
                );

         sp_id	:= nextval('traking.mct_checklistinftec_seq');

         INSERT INTO traking.mct_checklistinftec
                     (idchecklistinftec, 
                      idordentrabajo, 
                      nombreparte, 
                      cantidad, 
                      material, 
                      criterio, 
                      reparacion, 
                      plano, 
                      usuariocreacion, 
                      fechacreacion, 
                      indicefila, 
                      codigoqr, 
                      tipotrabajostd, 
                      fecharequerida, 
                      devolucion, 
                      muestrachecklist, 
                      flagpantallafacturacion, 
                      idcomponente, 
                      nombrecomponente, 
                      idmaterial, 
                      nombrematerial, 
                      idesmecanizado, 
                      idcriterioevaluacion, 
                      nombrezona, 
                      idhojarutatemp
                      )
               select sp_id, 
                      idworkorder,
                      b.nombrecomponente||' - '||a.textoadicional ,
                      a.cantidad,
                      c.nombrematerial,
                      'FAb_FuPl',
                      'Fabricación de Pieza Fundida para Planificación',
                      nombreplano,
                      'admin',
                      now(),
                      sp_indicefila,
                      idworkorder||'FAB_FUPL',
                      'FAB_FUPL',
                      sp_fechafundicion,
                      false,
                      true,
                      true,
                      a.idcomponente,
                      b.nombrecomponente,
                      a.idmaterial,
                      c.nombrematerial,
                      2,
                      13,
                      a.nombrezona,
                      sp_idhr
                 from mct_hojarutatemp a,
                      mct_componente b,
                      mct_material c
                where a.idhojarutatemp = sp_idhr
                  and a.idcomponente = b.idcomponente 
                  and a.idmaterial = c.idmaterial;

	-- Esto es para que se cargue la solicitud en el checklistvalido
			INSERT INTO traking.mct_checklistinftecvalido
			           (
			            idchecklistinftecvalido, 
			            idordentrabajo, 
			            nombreparte, 
			            cantidad, 
			            material, 
			            criterio, 
			            reparacion, 
			            plano, 
			            usuariocreacion, 
			            fechacreacion, 
			            indicefila, 
			            codigoqr, 
			            tipotrabajostd, 
			            fecharequerida, 
			            devolucion, 
			            muestrachecklist, 
			            flagpantallafacturacion, 
			            idcomponente, 
			            nombrecomponente, 
			            idmaterial, 
			            nombrematerial, 
			            pesocomponente, 
			            flagtraeurgente, 
			            idesmecanizado, 
			            idcriterioevaluacion, 
			            nombrezona, 
			            idchecklistinftecparamdet, 
			            idpadre, 
			            checkinfaprobado, 
			            idchecklistinftec, 
			            adelantafecha
			            )            
			     select nextval('traking.mct_checklistinftecvalido_seq'),
			            sm.idordentrabajo,
			            sm.nombreparte,
			            sm.cantidad,
			            sm.material,
			            sm.criterio,
			            sm.reparacion,
			            sm.plano,
			            sm.usuariocreacion,
			            sm.fechacreacion,
			            sm.indicefila,
			            sm.codigoqr,
			            sm.tipotrabajostd,
			            sm.fecharequerida,
			            sm.devolucion,
			            sm.muestrachecklist,
			            sm.flagpantallafacturacion,
			            sm.idcomponente,
			            sm.nombrecomponente,
			            sm.idmaterial,
			            sm.nombrematerial,
			            sm.pesocomponente,
			            sm.flagtraeurgente,
			            sm.idesmecanizado,
			            sm.idcriterioevaluacion,
			            sm.nombrezona,
			            sm.idchecklistinftecparamdet,
			            sm.idpadre,
			            sm.checkinfaprobado,
			            sm.idchecklistinftec,
			            sm.adelantafecha 
			       from mct_checklistinftec sm
			      where sm.idordentrabajo = idworkorder
			        and sm.idchecklistinftec = sp_id
			        and sm.criterio = 'FAb_FuPl';
                 
                 
	if ( sp_idtipoorden = 1 ) then -- Remanufactura
	   -- con 27
	
	    insert into mct_hojarutaactividadtemp 
	                (
	                idhojarutaactividadtemp ,
	                idhojarutatemp ,
	                idactividad ,
	                tiempoproduccion ,
	                orden 
	                )        	     
			select nextval('mct_hojarutaactividadtemp_seq'),
			       sp_idhr,
			       idactividad , 
			       tiempoproduccion , 
			       orden 
			  from mct_partetipotrabajoactividad mp 
			 where idpartetipotrabajo = ( select idcomponentetipotrabajo 
									        from mct_componentetipotrabajo mc
									       where idcomponente  = idcomponent
									         and idtipotrabajo in (21))
			order by idpartetipotrabajoactividad  asc, orden asc;
		
	end if;
	

	if ( sp_idtipoorden = 2 ) then -- fabricacion
		   -- con 21
		   
		    insert into mct_hojarutaactividadtemp 
	                (
	                idhojarutaactividadtemp ,
	                idhojarutatemp ,
	                idactividad ,
	                tiempoproduccion ,
	                orden 
	                )        	     
			select nextval('mct_hojarutaactividadtemp_seq'),
			       sp_idhr,
			       idactividad , 
			       tiempoproduccion , 
			       orden 
			  from mct_partetipotrabajoactividad mp 
			 where idpartetipotrabajo = ( select idcomponentetipotrabajo 
									        from mct_componentetipotrabajo mc
									       where idcomponente  = idcomponent 
									         and idtipotrabajo in (21))
			order by idpartetipotrabajoactividad  asc, orden asc;
	
	end if;                
                
    if ( idimprimehojasi = 1 ) then
    
       tope  := 1;
      
    else
 
    	tope := coalesce(quantity,0);
    
    end if;

		           
	indice := 1;
		
	loop						
	
		sp_hrchar   := LPAD(idWorkorder::integer::text::varchar, 6, '0');  
		sp_partchar := LPAD(idComponent::integer::text::varchar, 3, '0');
		sp_itemchar := LPAD(itemcorri::integer::text::varchar, 3, '0'); 	
		sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
		
		insert into mct_detallehojarutatemp 
		           (iddetallehojarutatemp 
		           ,idhojarutatemp 
		           ,codhojaruta 
		           ,correlativoparte
		           )
		     VALUES
		           (nextval('traking.mct_detallehojarutatemp_seq')
		           ,sp_idhr
		           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
		           ,indice
		           );                     

		         
		sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
	
		insert into mct_ordentrabajoparte 
		           (idordentrabajoparte 
		           ,idordentrabajo 
		           ,idcomponente 
		           ,itemparte
		           ,itemcorr 
		           )
		     VALUES
		           (sp_idpwo
		           ,idworkorder
		           ,idcomponent 
		           ,indice
		           ,itemcorri
		           );   

		-- Esto es para igualar la tabla Hoja Ruta
	    insert into mct_hojaruta 
		           (idhojaruta 
		           ,idordentrabajoparte 
		           ,codhojaruta 
		           ,usuariocreacion 
		           ,fechacreacion
		           ,modalidad 
		           ,idhojarutatemp 
		           )
		     VALUES
		           (nextval('traking.mct_hojaruta_seq')
		           ,sp_idpwo
		           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
		           ,'admin' 
		           ,now()
		           ,1
		           ,sp_idhr
		           ); 
		          
		 indice := indice + 1;
		                           				   
		 EXIT when indice > tope;
		                    
	END loop;                
	
END
$$;


