        sp_seccion_text             varchar;
       
BEGIN

	sp_idhr := nextval('traking.mct_hojarutatemp_seq');
    
    sp_seccion_text   := '';

    if ( idprofilei = 16 ) then
    
        sp_seccion_text   := 'F';
    
    elsif ( idprofilei = 15 ) then

            sp_seccion_text   := 'TM';
           
    elsif ( idprofilei = 14 ) then
    
            sp_seccion_text   := 'P';
           
    elsif ( idprofilei = 9 ) then
        
            sp_seccion_text   := 'C';
           
    elsif ( idprofilei = 8 ) then
        
            sp_seccion_text   := 'CC';
 
    elsif ( idprofilei = 17 ) then
        
            sp_seccion_text   := 'A';
           
    end if;
		       
	INSERT INTO traking.mct_hojarutatemp
                (idhojarutatemp, 
