                 cantidad,
                 textoadicional,
                 idtrabajohr,
                 idperfil,
                 idboleano)
          VALUES(sp_idhr, 
                 idworkorder, 
                 idcomponent, 
                 idmaterial, 
                 materialname,
                 blueprintname, 
                 quantity,
                 aditionaltext,
                 idworkhr,
                 idprofilei,
                 2 -- 1: suma, 2: no suma
                 );

	select idtipoorden 
	  into sp_idtipoorden
	  from mct_ordentrabajo
	 where idordentrabajo = idworkorder;
	
	if ( sp_idtipoorden = 1 ) then -- Remanufactura
	   -- con 27
	
	   -- insert into mct_hojarutaactividadtemp 
