		--	 where idpartetipotrabajo = ( select idcomponentetipotrabajo 
		--							        from mct_componentetipotrabajo mc
		--							       where idcomponente  = idcomponent
		--							         and idtipotrabajo in (27))
		--	order by idpartetipotrabajoactividad  asc, orden asc;
		
	end if;
	

	if ( sp_idtipoorden = 2 ) then -- fabricacion
		   -- con 21
		   
		  --  insert into mct_hojarutaactividadtemp 
	      --          (
	      --          idhojarutaactividadtemp ,
	      --          idhojarutatemp ,
	      --          idactividad ,
	      --          tiempoproduccion ,
	      --          orden 
	      --          )        	     
			--select nextval('mct_hojarutaactividadtemp_seq'),
			--       sp_idhr,
			--       idactividad , 
			--       tiempoproduccion , 
			--       orden 
			--  from mct_partetipotrabajoactividad mp 
			-- where idpartetipotrabajo = ( select idcomponentetipotrabajo 
			--						        from mct_componentetipotrabajo mc
			--						       where idcomponente  = idcomponent 
			--						         and idtipotrabajo in (21))
			--order by idpartetipotrabajoactividad  asc, orden asc;
	
	end if;                
                
	tope := coalesce(quantity,0);
		           
	indice := 1;
		
	loop						
	
		sp_hrchar   := LPAD(idWorkorder::integer::text::varchar, 6, '0');  
		sp_partchar := LPAD(idComponent::integer::text::varchar, 3, '0');
		sp_itemchar := LPAD(itemcorri::integer::text::varchar, 3, '0'); 	
		sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
		
		insert into mct_detallehojarutatemp 
		           (iddetallehojarutatemp 
		           ,idhojarutatemp 
		           ,codhojaruta 
		           ,correlativoparte
		           )
		     VALUES
		           (nextval('traking.mct_detallehojarutatemp_seq')
		           ,sp_idhr
		           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar||sp_seccion_text
		           ,indice
		           );                     

		         
		sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
	
		insert into mct_ordentrabajoparte 
		           (idordentrabajoparte 
		           ,idordentrabajo 
		           ,idcomponente 
		           ,itemparte
		           ,itemcorr 
		           )
		     VALUES
		           (sp_idpwo
		           ,idworkorder
		           ,idcomponent 
		           ,indice
		           ,itemcorri
		           );   

		-- Esto es para igualar la tabla Hoja Ruta
	    insert into mct_hojaruta 
		           (idhojaruta 
		           ,idordentrabajoparte 
		           ,codhojaruta 
		           ,usuariocreacion 
