--
-- TOC entry 1123 (class 1255 OID 16547)
-- Name: addsolcomp(bigint, bigint, character varying, bigint, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addsolcomp(indexrow bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_texto            varchar;
    sp_criterio         varchar;
    intervalo           varchar;
    sp_fecha_requerida  varchar;
    dias_totales        integer;
    minima_fecha        timestamp;
    maxima_fecha        timestamp;
   
    es_inicial          integer;
   
BEGIN
	
	sp_criterio := UPPER(repaircriteria);
    sp_criterio := replace(sp_criterio,'-','_');
	
	sp_texto := '';
    sp_texto := idworkorder||sp_criterio;
  
   
    --if ( sp_criterio not in  'FAB_FU' && sp_criterio != 'FAB_PA' && sp_criterio != 'FAB_CA' && && sp_criterio != 'RPO' ) then
    if ( sp_criterio not in  ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO') ) then
    
        sp_criterio := 'SOLCOMP';
        sp_texto    := idworkorder||sp_criterio;
       
    end if;
	
	select min(fecha_inicio), 
	       max(fecha_termino),
	       cast(date_part('day',max(fecha_termino) - min(fecha_inicio)) / 2 as integer)
	  into minima_fecha,
	       maxima_fecha,
	       dias_totales
	  from mct_progavisos mp 
	 where idordentrabajo = idworkorder
	 and idsla in (5,8);
	 
	intervalo := ''''||dias_totales||' day';
 
    select to_char(minima_fecha + intervalo::interval, 'dd-mm-yyyy') into sp_fecha_requerida;
   
    if ( select 1 from traking.mct_solcomp where idsolcomp = indexrow) then
    
        if ( deleterow = 'Yes') then 
        
            delete from traking.mct_solcomp
             where idordentrabajo = idworkorder
               and idsolcomp = indexrow;          
        else

	        update traking.mct_solcomp 
	           set nombreparte = partname,
	               cantidad = quantity,
	               material = materialname,
	               criterio = repaircriteria,
	               reparacion = repair,
	               plano = blueprintname,
	               tipotrabajostd = sp_criterio,
	               codigoqr = sp_texto
	         where idordentrabajo = idworkorder
	           and idsolcomp = indexrow;        
        
        end if;
        

    
    else
    
        es_inicial := 0;
       
        select count(*)
          into es_inicial
          from traking.mct_solcompinicial mc 
         where idordentrabajo = idworkorder;
        
		INSERT INTO traking.mct_solcomp
					(idsolcomp, 
					 idordentrabajo, 
					 nombreparte, 
					 cantidad, 
					 material, 
					 criterio, 
					 reparacion, 
					 plano, 
					 usuariocreacion, 
					 fechacreacion, 
					 indicefila,
					 codigoqr,
					 fecharequerida,
					 tipotrabajostd 
					 )
			 values (nextval('mct_solcomp_seq'),
			         idworkorder, 
			         partname, 
			         quantity, 
			         materialname, 
			         repaircriteria, 
			         repair, 
			         blueprintname, 
			         usercreate, 
			         now(), 
			         indexrow,
			         sp_texto,
			         to_date(sp_fecha_requerida,'dd-mm-yyyy'),
			         sp_criterio
			        );
        
 		       
    end if;
   

END
$$;


ALTER FUNCTION traking.addsolcomp(indexrow bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, usercreate character varying) OWNER TO postgres;

