--
-- TOC entry 1828 (class 1255 OID 16550)
-- Name: addsolcompdetallerecep(bigint, character varying, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addsolcompdetallerecep(idordentrabajoi bigint, qrcodei character varying, idsolcompdetallei bigint, iduseri bigint, idoperatori bigint, qdispatchi bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
	sp_total		integer;
	sp_recibidas	integer;
BEGIN

	sp_total		:= 0;
	sp_recibidas	:= 0;

INSERT INTO traking.mct_solcompdetallerecept 
           (idsolcompdetallerecept, 
            idordentrabajo, 
            qrcode , 
            idsolcompdetalle, 
            idusuario, 
            idoperatorrec , 
            cantidad, 
            fechacreacion, 
            usuariocreacion
            )
     VALUES(nextval('traking.mct_solcompdetallerecept_seq'), 
            idordentrabajoi, 
            qrcodei, 
            idsolcompdetallei, 
            iduseri, 
            coalesce(idoperatori,0), 
            qdispatchi, 
            now(), 
            'admin'
           );

   select sum(cantidad)
     into sp_total
     from mct_solcompdetalle  
    where codigoqr = qrcodei;
     
   select sum(cantidad)
     into sp_recibidas
     from mct_solcompdetallerecept 
    where qrcode = qrcodei;
    
    if ( sp_recibidas >= sp_total ) then 
        update mct_solcompcabecera 
           set estado = 3
         where qrcode = qrcodei;
    end if;
   
END
$$;


