--
-- TOC entry 1422 (class 1255 OID 16562)
-- Name: addtrabajoonlinealaespera(bigint, character varying, boolean, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addtrabajoonlinealaespera(idoperadori bigint, codigoqri character varying, statusactivoi boolean, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare

	sp_glosamotivo      varchar;
	sp_nombreoperador	varchar;

    sp_inicioam			boolean	:= false;
    sp_iniciopm			boolean	:= false;
	sp_statusactivo		boolean	:= false;
    

BEGIN

	if ( now() <= to_timestamp(to_char(current_date,'yyyymmdd')||' 07:45:00', 'yyyymmdd hh24:mi:ss')  ) then

		sp_inicioam	    := true;
		sp_iniciopm	    := false;
		sp_statusactivo	:= true;

	elsif ( now() > to_timestamp(to_char(current_date,'yyyymmdd')||' 07:45:00', 'yyyymmdd hh24:mi:ss') and
            now() <= to_timestamp(to_char(current_date,'yyyymmdd')||' 13:30:00', 'yyyymmdd hh24:mi:ss')  ) then

		sp_inicioam	    := true;
		sp_iniciopm	    := false;
		sp_statusactivo	:= true;

	elsif ( now() > to_timestamp(to_char(current_date,'yyyymmdd')||' 13:30:00', 'yyyymmdd hh24:mi:ss') ) then

		sp_inicioam	    := false;
		sp_iniciopm	    := true;
		sp_statusactivo	:= true;

	end if;

    if (select 1
          from traking.mct_trabajoonlinealaespera
         where idoperador = idoperadori) then

			update traking.mct_trabajoonlinealaespera
	           set codigoqr = codigoqri,
	               statusactivo = sp_statusactivo,
	               inicioam = sp_inicioam,
                   iniciopm = sp_iniciopm,
	               usuariomodificacion = usercreate,
	               fechamodificacion = now()
	         where idoperador = idoperadori;
    
    else

		insert into traking.mct_trabajoonlinealaespera
                    (
                    idtrabajoonlinealaespera,
					idoperador,
					codigoqr,
					statusactivo,
					inicioam,
                    iniciopm,
					fechacreacion,
					usuariocreacion
					)
             values (
					nextval('traking.mct_trabajoonlinealaespera_seq'),
					idoperadori,
					codigoqri,
					sp_statusactivo,
					sp_inicioam,
					sp_iniciopm,
					now(),
					usercreate
					);
	
    end if;
      

END
$$;


ALTER FUNCTION traking.addtrabajoonlinealaespera(idoperadori bigint, codigoqri character varying, statusactivoi boolean, usercreate character varying) OWNER TO postgres;

