--
-- TOC entry 1242 (class 1255 OID 16565)
-- Name: addturnofundpdfsave(bigint, text, character varying, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.addturnofundpdfsave(idoperadorturnos bigint, filepdf text, filename character varying, idprocess bigint, usercreate character varying, fechaturnoi character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

begin
	
      IF (select 1
		    from mct_turnofundpdf 
           where nombrearchivo   = filename
             and idproceso       = idprocess 
             and esturnofundicion1 is true) then
           
			UPDATE traking.mct_turnofundpdf
			   set archivoadjunto  = filepdf,
			       esturnofundicion1 = true,
			       fechamodificacion = now(),
			       usuariomodificacion = usercreate
			 where nombrearchivo   = filename; 	

	  else
             
			insert into traking.mct_turnofundpdf (
			      idturnofundpdf ,
				  idoperadorturno,
				  archivoadjunto,
				  nombrearchivo ,
				  idproceso,
				  esturnofundicion1 ,
				  fechacreacion,
				  usuariomodificacion,
				  fechaturno 
				 ) 
				values (
				nextval('mct_turnofundpdf_seq'),
						idoperadorturnos,
						filepdf,
						filename,
						idprocess,
						true,
						now(),
						usercreate,
						to_date(fechaturnoi,'yyyy-mm-dd')
				);	
      END IF;

     return 0;

END;
$$;


ALTER FUNCTION traking.addturnofundpdfsave(idoperadorturnos bigint, filepdf text, filename character varying, idprocess bigint, usercreate character varying, fechaturnoi character varying) OWNER TO postgres;

