--
-- TOC entry 2264 (class 1255 OID 16570)
-- Name: adduser(bigint, character varying, character varying, integer, character varying, character varying, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.adduser(idprofile bigint, usuario character varying, password character varying, status integer, dni character varying, name character varying, email character varying, idcustomer bigint, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 
	sp_id		bigint;
	md5temp 	varchar;
BEGIN

	sp_id	:= nextval('traking.mct_user_seq');

	md5temp = concat(CAST(sp_id AS varchar),dni);
    SELECT MD5(md5temp) into md5temp;
	
    insert into traking.mct_usuario 
           (idperfil, 
            idusuario, 
            usuario, 
            password, 
            estado, 
            rut, 
            nombre, 
            email, 
            idcliente ,
            fechacreacion, 
            usuariocreacion,
            hashcodecredencial) 
    values ( idprofile, 
             sp_id, 
             usuario, 
             password, 
             status, 
             dni, 
             name, 
             email,
             idcustomer,
             now(), 
             usercreate ,
             md5temp
          );

END
$$;


