--

CREATE FUNCTION traking.addusuarioappcontrolmaestranz(idusuarioi bigint, flagevaluacioni boolean, flagcambioingenieriai boolean, flagcontrolmaquinai boolean, flagdespachoi boolean, flagdefectofundicioni boolean, flaginspi boolean, flaglimpiezamaquinai boolean, flagmateriaprimai boolean, flagnoconformidadi boolean, flagnoconformidadcaldi boolean, flagotra1i boolean, flagotra2i boolean, flagotra3i boolean, flagotra4i boolean, flagotra5i boolean, userupdatei character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
   sp_cantidad    integer;
BEGIN

	sp_cantidad := 0;

	select count(*)
	  into sp_cantidad
	  from traking.mct_usuariocontrolmaestranza
	 where idusuario = idusuarioi;

	if ( sp_cantidad > 0 ) then

	    update traking.mct_usuariocontrolmaestranza  
	       set flagevaluacion = flagevaluacioni ,
	           flagcambioingenieria = flagcambioingenieriai ,
	           flagcontrolmaquina = flagcontrolmaquinai ,
	           flagdespacho = flagdespachoi ,
	           flagdefectofundicion = flagdefectofundicioni ,
	           flaginsp = flaginspi,
	           flaglimpiezamaquina = flaglimpiezamaquinai,
	           flagmateriaprima = flagmateriaprimai,
	           flagnoconformidad = flagnoconformidadi,
	           idhoraminutootro = idhoraminutootroi,
	           flagnoconformidadcald = flagnoconformidadcaldi,
	           flagotra1 = flagotra1i,
	           flagotra2 = flagotra2i,
	           flagotra3 = flagotra3i,
	           flagotra4 = flagotra4i,
	           flagotra5 = flagotra5i,
               usuariomodificacion = userupdatei	           
	     where idusuario = idusuarioi;
    
	else 
	
		INSERT INTO traking.mct_usuariocontrolmaestranza
		       (
		        idusuariocontrolmaestranza, 
		        idusuario, 
		        flagevaluacion, 
		        flagcambioingenieria, 
		        flagcontrolmaquina, 
		        flagdespacho, 
		        flagdefectofundicion, 
		        flaginsp, 
		        flaglimpiezamaquina, 
		        flagmateriaprima, 
		        flagnoconformidad, 
		        flagnoconformidadcald, 
		        flagotra1, 
		        flagotra2, 
		        flagotra3, 
		        flagotra4, 
		        flagotra5, 
		        estado, 
		        fechacreacion, 
		        usuariocreacion
		        )
		  VALUES(
		         nextval('traking.mct_usuariocontrolmaestranza_seq'), 
		         idusuarioi, 
		         flagevaluacioni, 
		         flagcambioingenieriai, 
		         flagcontrolmaquinai, 
		         flagdespachoi, 
		         flagdefectofundicioni, 
		         flaginspi, 
		         flaglimpiezamaquinai, 
		         flagmateriaprimai, 
		         flagnoconformidadi, 
		         flagnoconformidadcaldi, 
		         flagotra1i, 
		         flagotra2i, 
		         flagotra3i, 
		         flagotra4i, 
		         flagotra5i, 
		         1, 
		         now(), 
		         userupdatei
		         );
	      
	end if;

END
$$;


