	sp_cantidad := 0;

	select count(*)
	  into sp_cantidad
	  from traking.mct_usuariocontrolmaestranza
	 where idusuario = idusuarioi;

	if ( sp_cantidad > 0 ) then

	    update traking.mct_usuariocontrolmaestranza  
	       set flagevaluacion = flagevaluacioni ,
	           flagcambioingenieria = flagcambioingenieriai ,
	           flagcontrolmaquina = flagcontrolmaquinai ,
	           flagdespacho = flagdespachoi ,
	           flagdefectofundicion = flagdefectofundicioni ,
	           flaginsp = flaginspi,
	           flaglimpiezamaquina = flaglimpiezamaquinai,
	           flagmateriaprima = flagmateriaprimai,
	           flagnoconformidad = flagnoconformidadi,
	           flagnoconformidadcald = flagnoconformidadcaldi,
	           flagotra1 = flagotra1i,
	           flagotra2 = flagotra2i,
	           flagotra3 = flagotra3i,
	           flagotra4 = flagotra4i,
	           flagotra5 = flagotra5i,
flagotra6 = flagotra6i,
flagotra7 = flagotra7i,
flagotra8 = flagotra8i,
flagotra9 = flagotra9i,
flagotra10 = flagotra10i,
               usuariomodificacion = userupdatei	           
	     where idusuario = idusuarioi;
    
	else 
	
		INSERT INTO traking.mct_usuariocontrolmaestranza
		       (
		        idusuariocontrolmaestranza, 
		        idusuario, 
		        flagevaluacion, 
		        flagcambioingenieria, 
		        flagcontrolmaquina, 
		        flagdespacho, 
		        flagdefectofundicion, 
		        flaginsp, 
		        flaglimpiezamaquina, 
		        flagmateriaprima, 
		        flagnoconformidad, 
		        flagnoconformidadcald, 
		        flagotra1, 
		        flagotra2, 
		        flagotra3, 
		        flagotra4, 
		        flagotra5, 
flagotra6,
flagotra7,
flagotra8,
flagotra9,
flagotra10,
		        estado, 
		        fechacreacion, 
		        usuariocreacion
		        )
		  VALUES(
		         nextval('traking.mct_usuariocontrolmaestranza_seq'), 
		         idusuarioi, 
		         flagevaluacioni, 
		         flagcambioingenieriai, 
		         flagcontrolmaquinai, 
		         flagdespachoi, 
		         flagdefectofundicioni, 
		         flaginspi, 
		         flaglimpiezamaquinai, 
