--

CREATE FUNCTION traking.addworkorder(nameworkorder character varying, idcustomer bigint, quotation bigint, idordertype bigint, idproduct bigint, purshaseorder bigint, receptiondate character varying, deliverydate character varying, requestdate character varying, orderstatus bigint, iduser bigint, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    insert into traking.mct_ordentrabajo 
                (idordentrabajo, 
                 nombreordentrabajo, 
                 idcliente, 
                 idtipoorden, 
                 idproducto, 
                 fecharecepcion, 
                 fechaentrega ,
                 idestadoorden, 
                 idusuario, 
                 fechacreacion, 
                 usuariocreacion) 
   values (nextval('traking.mct_ordentrabajo_seq'), 
                 nameworkorder , 
                 idcustomer, 
                 idordertype , 
                 idproduct  , 
                 now() , 
                 now()+ interval '60 day',
                 2  , 
                 idUser , 
                 now(), 
                 usercreate );

END
$$;


ALTER FUNCTION traking.addworkorder(nameworkorder character varying, idcustomer bigint, quotation bigint, idordertype bigint, idproduct bigint, purshaseorder bigint, receptiondate character varying, deliverydate character varying, requestdate character varying, orderstatus bigint, iduser bigint, usercreate character varying) OWNER TO postgres;

