CREATE FUNCTION traking.addworkordermanual(idcustomer bigint, idordertype bigint, idproduct bigint, idfamily bigint, idlinedesign bigint, idworkorderprev bigint, tag character varying, receptiondateup character varying, deliverydateup character varying, iduser bigint, customercontact character varying, observationcrea character varying, usercreate character varying, workordername character varying, otcientei character varying, idproyectoi bigint, idfueraiquiquei bigint, montofabi bigint, idrepuestosi bigint, solpedi character varying, serieequipoi character varying, idtipootdesgastei bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
			
        sp_flgfact					boolean;
       
        sp_idot   				    INTEGER;

        sp_idotp   				    INTEGER;
		sp_ocompra 				    INTEGER;
		sp_idcotizacion 			INTEGER;
	    sp_idestado		            INTEGER;
	   
	    sp_tipoorden                varchar;

	    sp_nombreproducto           varchar;
	    sp_nombre			        varchar;
	    sp_nombrefamilia            varchar;
	   
	    sp_otchar                   TEXT;
        sp_partchar                 TEXT;
        sp_corrchar                 TEXT;
        intervalo                   varchar;
        sp_fecha_requerida          varchar;
   
        indice   				    INTEGER;
        tope	   				    INTEGER;

	    dias_totales                integer;
	    minima_fecha                timestamp;
	    maxima_fecha                timestamp;
	   
	    sp_oc						bigint;
		       
		rec_unicopartecant          RECORD;
        cur_unicopartecant          CURSOR(sp_idprod integer) 
                    		           FOR select a.idproducto,
                    		                      a.idparte,
                    		                      b.idtipoparte ,
                    		                      a.cantidad
   											 from traking.mct_productoparte a,
       											  mct_parte b
         						            where idproducto = sp_idprod 
         						              and a.idparte = b.idparte
         						            order by idparte ;
         						           
        sp_fechatm					timestamp;
        sp_fechaclte				timestamp;
        sp_fechafund				timestamp;
        
        -- Cambios el dia 08/09 pedidos por HC
        sp_fechamod					timestamp;
        sp_fechacol					timestamp;
       
        sp_ot						integer; 
        sp_mec						integer;
        sp_cant						integer;
       
	    dias_totalescheck           integer;
	    dias_totalesaviso           integer;   
	    minima_fechacheck           timestamp;
	    maxima_fechacheck           timestamp; 
	    intervalocheck          	varchar;
    	intervalocheckavi       	varchar;   
       
        
BEGIN

		sp_idcotizacion := 0;
		sp_ocompra      := 0;
        sp_otchar       := '';
        sp_partchar     := '';
        sp_corrchar     := '';
       
        sp_tipoorden    := '';
        --sp_cliente      := '';  
        sp_nombreproducto := '';
        sp_nombrefamilia := '';
       
        -- Fechas
        sp_fechatm		:= null;
        sp_fechaclte	:= null;
        sp_fechafund	:= null;
       
		if ( idordertype in ( 1, 3) ) then
			sp_idestado := 2;
		else
		    if ( idfamily = 11) then
		    	sp_idestado := 6;
		    else
		    
		        -- Agregado el 08/09
		        if ( idfamily in (10, 14, 15) ) then
		        
		            sp_idestado := 6;
		      
		        elsif ( idordertype in ( 7) and  idfamily in (8) ) then
		        
		            sp_idestado := 6;
		        
		        else
		        
		            sp_idestado := 4;
		            
		        end if;
		    
		    	
		    end if;
			
		end if;
	
	
		-- Agregado el 03/12	
		if ( idordertype in (2) and idfamily in (8,10) ) then
			sp_idestado := 6;
		end if;
	
	    select nombretipoorden 
	      into sp_tipoorden
	      from mct_tipoorden
	     where idtipoorden = idordertype;
	    
	   -- select nombrecliente
	   --  into sp_cliente
	   --  from mct_cliente
	   -- where idcliente = idcustomer;
	   
	    
	    if ( idproduct > 0 ) then

	        if ( idfamily = 11) then
	        
	    	   select nombreproductonepcast 
			     into sp_nombreproducto
			     from mct_productonepcast
			    where idproductonepcast = idproduct;	        
	        
	        else
	    	   select nombreproducto
			     into sp_nombreproducto
			     from mct_producto
			    where idproducto = idproduct;
	   
			end if;
	    else
	     
	     	   select nombrefamilia
			     into sp_nombrefamilia
			     from mct_familia
			    where idfamilia = idfamily;
			   
	            sp_nombreproducto := sp_nombrefamilia||' - '||workordername;
	    			   
	          --  sp_nombreproducto := workordername;
	           
	    end if;

	
	    sp_idot := nextval('traking.mct_ordentrabajo_seq');
	       
	    if ( idfamily in (10,11) ) then
	    	sp_flgfact := true;
	        if ( idordertype in (2) ) then
	            sp_oc := cast(otcientei as bigint);
	        else
	            sp_oc := 0;
	        end if;
	    else
	    	sp_flgfact := false;
	    end if;
	    
	  
 		if ( idordertype in ( 7) and  idfamily in (8,15) ) then
	    	sp_flgfact 	:= true;
	        sp_oc 		:= cast(otcientei as bigint);
	    end if;
	  

	   if ( idordertype in ( 2) and  idfamily in (8, 10) ) then
	    	sp_flgfact 	:= true;
	        sp_oc 		:= cast(otcientei as bigint);
	    end if;
	   
	   if ( idfamily = 10 ) then
	   
			delete from mct_progavisoschecklist 
				     where idordentrabajo = sp_idot;
				  
				    select min(fecha_inicio), 
					       max(fecha_termino),
					       cast(date_part('day',max(fecha_termino) - min(fecha_inicio)) / 2 as integer),
					       round(cast(date_part('day',max(fecha_termino) - min(fecha_inicio)) / 2 as integer) * 0.75)
				      into minima_fechacheck,
				           maxima_fechacheck,
				           dias_totalescheck,
				           dias_totalesaviso	
					  from mct_progavisos mp 
					 where idordentrabajo = sp_idot
					   and idsla in (5,8);
					  
					 intervalocheck    := ''''||dias_totalescheck||' day';
					 intervalocheckavi := ''''||dias_totalesaviso||' day';
					
			       --  select to_char(minima_fecha + intervalocheck::interval, 'dd-mm-yyyy') into sp_fecha_requerida;
			       --  select to_char(minima_fecha + intervalocheckavi::interval, 'dd-mm-yyyy') into fecha_aviso;
			                 
			         insert into mct_progavisoschecklist (
