						    sp_idot||d.sigla,
						    d.sigla ,	
						    d.nombretipotrabajo ,
						    d.idusuarioresp ,
						    minima_fechacheck,
						    minima_fechacheck + intervalocheck::interval,
						    minima_fechacheck + intervalocheckavi::interval,
						   -- to_date(sp_fecha_requerida,			    
						   -- to_date(fecha_aviso,
					        d.idnotificacion,
						    0
			           from mct_notificacionlista a
			           join mct_tipotrabajochecklist d on a.idnotificacion = d.idnotificacion
			           left join mct_usuario e         on d.idusuarioresp = e.idusuario 
