	                 fechacreacion, 	                 
	                 idestadoorden,                 
	                 idordentrabajoanterior ,	                 
	                 tag ,	                 	                 
	                 idmodalidadcreacion ,
	                 contactocliente ,
	                 observacioncreacion ,
	                 idusuario ,
	                 otcliente ,
	                 idproyecto ,
	                 flagfacturacion ,
	                 ordencompra ,
	                 fechafacetm ,
	                 fechafaceclte ,
	                 fechafundicion ,
	                 fechafundicion2 ,
	                 fechafundicion3 ,
	                 fechafundicionmodelo ,
	                 fechafundicioncal ,
	                 idfueraiquique ,
	                 montorepfab ,
	                 idrepuestos,
                     fechaentregainicial,
                     solped,
                     serieequipo,
                     idtipootdesgaste
	                 ) 
	          values (sp_idot,
	                 idcustomer, 
	                -- sp_idcotizacion,
	                 idordertype , 
	                 idproduct  ,
	                 idfamily,
	                 idlinedesign,
	                 sp_tipoorden||' '||sp_nombreproducto,	                 
	                 to_date(receptiondateup,'yyyy-mm-dd')+1, 
	                -- now()+ interval '60 day',	
	                 to_date(deliverydateup,'yyyy-mm-dd')+1,                 
	                 usercreate , -- usuariocreacion
	                 now() , -- fechacreacion		                
	                 sp_idestado  , 	                 
	                 idworkorderprev ,	
	                 tag ,	                 
	                 1,
	                 customercontact,
	                 observationcrea,
	                 iduser,
	                 otcientei,
	                 idproyectoi,
	                 sp_flgfact,
	                 sp_oc,
	                 --(to_date(deliverydateup,'yyyy-mm-dd')+1) - interval '7 days',
	                 sp_fechatm,
	                 --to_date(deliverydateup,'yyyy-mm-dd')+1,
	                 sp_fechaclte,
	                 sp_fechafund,
	                 sp_fechafund,
	                 sp_fechafund,
	                 sp_fechamod,
	                 sp_fechacol ,
	                 idfueraiquiquei ,
	                 montofabi ,
	                 idrepuestosi,
                     to_date(deliverydateup,'yyyy-mm-dd')+1,
                     solpedi,
                     serieequipoi,
                     idtipootdesgastei
	                 );
	   
	   -- Esto se omite para provocar confusion con productos automaticos
 	--		if ( idproduct > 0 ) then
