CREATE FUNCTION traking.addworkordermanualinterna(idcustomer bigint, idordertype bigint, idproduct bigint, idfamily bigint, idlinedesign bigint, idworkorderprev bigint, tag character varying, receptiondateup character varying, deliverydateup character varying, iduser bigint, customercontact character varying, observationcrea character varying, usercreate character varying, workordername character varying, otcientei character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
			
        sp_idot   				    INTEGER;

        sp_idotp   				    INTEGER;
		sp_ocompra 				    INTEGER;
		sp_idcotizacion 			INTEGER;
	    sp_idestado		            INTEGER;
	   
	    sp_tipoorden                varchar;

	    sp_nombreproducto           varchar;
	    sp_nombre			        varchar;
	    sp_nombrefamilia            varchar;
	   
	    sp_otchar                   TEXT;
        sp_partchar                 TEXT;
        sp_corrchar                 TEXT;
        intervalo                   varchar;
        sp_fecha_requerida          varchar;
   
        indice   				    INTEGER;
        tope	   				    INTEGER;

	    dias_totales                integer;
	    minima_fecha                timestamp;
	    maxima_fecha                timestamp;
		             						           
         						           
BEGIN

		sp_idcotizacion := 0;
		sp_ocompra      := 0;
        sp_otchar       := '';
        sp_partchar     := '';
        sp_corrchar     := '';
       
        sp_tipoorden    := '';
        --sp_cliente      := '';  
        sp_nombreproducto := '';
        sp_nombrefamilia := '';
       
		if ( idordertype in ( 1, 3) ) then
			sp_idestado := 2;
		else
			sp_idestado := 4;
		end if;
	
	    select nombretipoorden 
	      into sp_tipoorden
	      from mct_tipoorden
	     where idtipoorden = idordertype;
	    
	     
	    select nombrefamilia
	      into sp_nombrefamilia
	      from mct_familia
	     where idfamilia = idfamily;
			   
	    sp_nombreproducto := 'ORDEN INTERNA'||' - '||sp_nombrefamilia;
	    			   
	    sp_idot := nextval('traking.mct_ordentrabajo_seq');
	       
	    insert into traking.mct_ordentrabajo 
	                (idordentrabajo, 
	                 idcliente, 
	                -- idcotizacion ,
	                 idtipoorden, 
	                 idproducto,
	                 idfamilia ,
	                 idlineadiseno ,
	                 nombreordentrabajo,           	                 
	                 fecharecepcion, 
	                 fechaentrega ,
	                 usuariocreacion,	                 
	                 fechacreacion, 	                 
	                 idestadoorden,                 
	                 idordentrabajoanterior ,	                 
	                 tag ,	                 	                 
	                 idmodalidadcreacion ,
	                 contactocliente ,
	                 observacioncreacion ,
	                 idusuario ,
	                 otcliente ,
	                 idproyecto 
	                 ) 
	          values (sp_idot,
	                 idcustomer, 
	                -- sp_idcotizacion,
	                 idordertype , 
	                 idproduct  ,
	                 idfamily,
	                 idlinedesign,
	                 sp_tipoorden||' '||sp_nombreproducto,	                 
	                 to_date(receptiondateup,'yyyy-mm-dd')+1, 
	                -- now()+ interval '60 day',	
	                 to_date(deliverydateup,'yyyy-mm-dd')+1,                 
	                 usercreate , -- usuariocreacion
	                 now() , -- fechacreacion		                
	                 sp_idestado  , 	                 
	                 idworkorderprev ,	
	                 tag ,	                 
	                 1,
	                 customercontact,
	                 observationcrea,
	                 iduser,
	                 otcientei,
	                 2
	                 );
		
       
		RETURN sp_idot;	                	               

END
$$;


