CREATE FUNCTION traking.calculahorasincumplimientos(fechaoorigen timestamp without time zone, idnotificacions bigint) RETURNS TABLE(salhorav numeric)
    LANGUAGE plpgsql
    AS $$
declare
	   
	    sp_horas				numeric;
	    sp_diasem				bigint;
	   
	    sp_fechatope			timestamp;
	    sp_fechatopesabado		timestamp;
	    sp_fechatopeinicio		timestamp;
	   
	    sp_newfechaorigen		timestamp;
	   
	    sp_horasmail			bigint;
	   
	    sp_horasprimerdia		numeric;
	   
	    valor1					numeric(10,2);
	    valor2					numeric;
	    valor3					numeric;
	    valor4					numeric;
	    valor5					numeric;
	   
	    intervalo    			varchar;
			       
BEGIN			
	    -- desde aca el nuevo calculo
		sp_horas  			:= 0;
	    sp_diasem			:= 0;
	   
	    sp_horasmail		:= 0;
	    sp_horasprimerdia	:= 0;

		select kpihoras -- 115
		  into sp_horasmail
		  from mct_agendamientomail ma 
		 where idnotificacion = idnotificacions;--idnotificacions;			 	     
		       
	    if (idnotificacions = 76 ) then
	    
	    	raise notice '%', 'Son 15 horas ';
	    	
			SELECT coalesce(round(( EXTRACT(EPOCH FROM fechaoorigen::timestamp)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 0),
			       date_part('dow', fechaoorigen)
		      into sp_horas,
		           sp_diasem ;
		   
			raise notice '%', 'Son horas '||sp_horas;
			raise notice '%', 'Dia semana '||sp_diasem;
			
		    if (sp_diasem = 1 or sp_diasem = 2 or sp_diasem = 3 or sp_diasem = 4 or sp_diasem = 5) then
		        
			    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 22:30:00', 'yyyy-mm-dd HH24:MI:SS')
			      into sp_fechatope;
			  
			    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 14:30:00', 'yyyy-mm-dd HH24:MI:SS')
			      into sp_fechatopesabado;
			        
			    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS')
			      into sp_fechatopeinicio;
			      
		        select coalesce(round(( EXTRACT(EPOCH FROM sp_fechatope)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 0)
		          into sp_horas;
		    		    
		        --sp_horas :=	sp_horas + (15 - sp_horas) + 9; 
		        sp_horas :=	569; 
		       
		        intervalo := ''''||sp_horas||' hours';

		        raise notice '%', 'Fecha final es : '||fechaoorigen + intervalo::interval;
		        --salhorav := round(sp_horas);
		        salhorav := round(569);
		         
		    elsif (sp_diasem = 6) then
			  
				  select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 14:30:00', 'yyyy-mm-dd HH24:MI:SS')
				    into sp_fechatopesabado;
			   
		          if (sp_diasem = 6) then
		          
			          if ( fechaoorigen > sp_fechatopesabado) then
			          
			            fechaoorigen	:= to_timestamp(to_char(fechaoorigen + interval '2 days', 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS');
			           
			            select coalesce(round(( EXTRACT(EPOCH FROM sp_fechatope)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 0)
				          into sp_horas;
				                
					    sp_horas :=	sp_horas + (15 - sp_horas) + 9;

					  else
     
					    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 22:30:00', 'yyyy-mm-dd HH24:MI:SS')
					      into sp_fechatope;
					     
					    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS')
					      into sp_fechatopeinicio;
		
					    select coalesce(round(( EXTRACT(EPOCH FROM sp_fechatopesabado)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 0)
				          into sp_horas;
       
					    sp_horas :=	sp_horas + 10 + 24 + (15 - sp_horas) + 7;
					  				   
			          end if;		          
		          
		          else
		          
		            fechaoorigen	:= to_timestamp(to_char(fechaoorigen + interval '1 days', 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS');

				    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 22:30:00', 'yyyy-mm-dd HH24:MI:SS')
				      into sp_fechatope;
				     
				    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS')
				      into sp_fechatopeinicio;
	
				    select coalesce(round(( EXTRACT(EPOCH FROM sp_fechatope)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 0)
			          into sp_horas;
			                
				    sp_horas :=	sp_horas + (15 - sp_horas) + 9 + 24;		           
		          
		          end if;
			     
			      intervalo := ''''||sp_horas||' hours';
				
			      salhorav := round(sp_horas);
			       
		    end if;	    	
	    
	    end if;

	   
	    if (idnotificacions = 77 or idnotificacions = 78) then
	
			raise notice '%', 'Son horas : '||sp_horasmail;

			SELECT coalesce(round(( EXTRACT(EPOCH FROM fechaoorigen::timestamp)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 0),
			       date_part('dow', fechaoorigen)
		      into sp_horas,
		           sp_diasem ;
		   
			raise notice '%', 'Son horas '||sp_horas;
			raise notice '%', 'Dia semana '||sp_diasem;
			
		    if (sp_diasem = 1 or sp_diasem = 2 or sp_diasem = 3 or sp_diasem = 4 or sp_diasem = 5) then
 
			       select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 22:30:00', 'yyyy-mm-dd HH24:MI:SS')
			         into sp_fechatope;
			     
			       select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 14:30:00', 'yyyy-mm-dd HH24:MI:SS')
			         into sp_fechatopesabado;
			     
			       select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS')
			         into sp_fechatopeinicio;
	   
				   SELECT coalesce((( EXTRACT(EPOCH FROM sp_fechatope)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 1)
		  	  	     into sp_horas;
		        
				   SELECT coalesce((( EXTRACT(EPOCH FROM fechaoorigen)-EXTRACT(EPOCH FROM sp_fechatopeinicio)) / 3600), 0)::numeric
         	  	     into sp_horasprimerdia;	   
			  
			  	   raise notice '%', 'Horas a sumar en 77 : '||sp_horas;
		    	   raise notice '%', 'Horas desde el tope inicial : '||sp_horasprimerdia;
			   
		           valor1	:= (108::numeric/15::numeric);
		           valor2	:= valor1 * 24::numeric;
		           valor3	:= valor2::numeric + 24::numeric;
		           valor4	:= valor3::numeric + 17::numeric;
		           valor5	:= valor4::numeric + sp_horasprimerdia::numeric;
		       
--		           raise notice '%', 'Valor1 en 77 : '||valor1;
--		           raise notice '%', 'Valor2 en 77 : '||valor2;
--		           raise notice '%', 'Valor3 en 77 : '||valor3;
--		           raise notice '%', 'Valor4 en 77 : '||valor4;
--		           raise notice '%', 'Valor5 en 77 : '||valor5;
		    
		           raise notice '%', 'Horas a sumar en 77 : '||round(valor5);
		       
		           intervalo := ''''||valor5||' hours';
				
		           raise notice '%', 'Fecha final es : '||fechaoorigen + intervalo::interval;
		       
		           salhorav := round(valor5);
		    
		    elsif (sp_diasem = 6 or sp_diasem = 0) then
		   
				  select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 14:30:00', 'yyyy-mm-dd HH24:MI:SS')
				    into sp_fechatopesabado;
				   
		          if (sp_diasem = 6) then
		          
			          if ( fechaoorigen > sp_fechatopesabado) then
			          	
			            --fechaoorigen	:= fechaoorigen + interval '2 days';
			            select to_timestamp(to_char(fechaoorigen + interval '2 days', 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS')
			              into fechaoorigen;
			          
			          end if;		          
		          
		          else
		          
		            select to_timestamp(to_char(fechaoorigen + interval '1 days', 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS')
			          into fechaoorigen;
			         
		          	--fechaoorigen	:= fechaoorigen + interval '1 days';
		                  
		          end if;
		         
			      select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 22:30:00', 'yyyy-mm-dd HH24:MI:SS')
			        into sp_fechatope;
			          
			      select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS')
			        into sp_fechatopeinicio;
	   
				  SELECT coalesce((( EXTRACT(EPOCH FROM sp_fechatope)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 1)
		  	  	    into sp_horas;
		        
			      SELECT coalesce((( EXTRACT(EPOCH FROM fechaoorigen)-EXTRACT(EPOCH FROM sp_fechatopeinicio)) / 3600), 0)::numeric
         	  	    into sp_horasprimerdia;	   
			  
			  	  raise notice '%', 'Horas a sumar en 77 : '||sp_horas;
		    	  raise notice '%', 'Horas desde el tope inicial : '||sp_horasprimerdia;
			   
		          valor1	:= (108::numeric/15::numeric);
		          valor2	:= valor1 * 24::numeric;
		          valor3	:= valor2::numeric + 24::numeric;
		          valor4	:= valor3::numeric + 17::numeric;
		          valor5	:= valor4::numeric + sp_horasprimerdia::numeric;
		       
--		          raise notice '%', 'Valor1 en 77 : '||valor1;
--		          raise notice '%', 'Valor2 en 77 : '||valor2;
--		          raise notice '%', 'Valor3 en 77 : '||valor3;
--		          raise notice '%', 'Valor4 en 77 : '||valor4;
--		          raise notice '%', 'Valor5 en 77 : '||valor5;
		    
		          raise notice '%', 'Horas a sumar en 77 : '||round(valor5);
		       
		          intervalo := ''''||valor5||' hours';
				
		          raise notice '%', 'Fecha final es : '||fechaoorigen + intervalo::interval;
		       
		          salhorav := round(valor5);
		       
		    end if;	    	
	    
	    end if;
	          
		RETURN NEXT;
	
END;
$$;


ALTER FUNCTION traking.calculahorasincumplimientos(fechaoorigen timestamp without time zone, idnotificacions bigint) OWNER TO postgres;

--
-- TOC entry 1983 (class 1255 OID 16583)
-- Name: calculahorasincumplimientos_test(timestamp without time zone, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calculahorasincumplimientos_test(fechaoorigen timestamp without time zone, idnotificacions bigint) RETURNS TABLE(salhorav numeric)
    LANGUAGE plpgsql
    AS $$
declare
	   
	    sp_horas				numeric;
	    sp_horastotales			numeric;
	    sp_diasem				bigint;
	   
	    sp_fechatope			timestamp;
	    sp_fechatopesabado		timestamp;
	    sp_fechatopeinicio		timestamp;
	   
	    sp_fechaoorigen			timestamp;
	   
	    sp_newfechaorigen		timestamp;
	   
	    sp_horasmail			bigint;
	   
	    sp_horasprimerdia		numeric;
	   
	    valor1					numeric(10,2);
	    valor2					numeric;
	    valor3					numeric;
	    valor4					numeric;
	    valor5					numeric;
	   
	    intervalo    			varchar;
	   
	    sp_dia					bigint;
			       
begin
	
	sp_horas	:= 0;

	select kpihoras
	  into sp_horasmail
	  from mct_agendamientomail ma 
	 where idnotificacion = idnotificacions;
	
	raise notice 'Horas del kip son %', sp_horasmail;
		 	
    select date_part('dow', fechaoorigen)
      into sp_diasem ;

    raise notice 'Dia de la semana %', sp_diasem;
   
    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 22:30:00', 'yyyy-mm-dd HH24:MI:SS')
      into sp_fechatope;
  
    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 14:30:00', 'yyyy-mm-dd HH24:MI:SS')
      into sp_fechatopesabado;
        
    select to_timestamp(to_char(fechaoorigen, 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS')
      into sp_fechatopeinicio;
      
    if ( fechaoorigen > sp_fechatopesabado and sp_diasem = 6) then
    
        sp_horas		:= 0;
    	sp_horastotales	:= 24 + 17;

    	raise notice 'Horas iniciales Sab %', round(sp_horas);
					
	    sp_fechaoorigen	:= fechaoorigen;
	    fechaoorigen 	:= to_timestamp(to_char(fechaoorigen + interval '2 days', 'yyyy-mm-dd')||' 07:30:00', 'yyyy-mm-dd HH24:MI:SS');
   	   
    else

       if ( sp_diasem = 6) then
       
			SELECT coalesce((( EXTRACT(EPOCH FROM sp_fechatopesabado)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 1)
			  into sp_horas;
	
			raise notice 'Horas iniciales Sem %', round(sp_horas);
		   
    	    sp_horastotales	:= 24 + 17;
						
		    sp_fechaoorigen	:= fechaoorigen;
		    --fechaoorigen 	:= fechaoorigen + interval '1 days';
       
       else
       
			SELECT coalesce((( EXTRACT(EPOCH FROM sp_fechatope)-EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 1)
			  into sp_horas;
	
			raise notice 'Horas iniciales Sem %', round(sp_horas);
			 
		    sp_horastotales	:= round(sp_horas);  
						
		    sp_fechaoorigen	:= fechaoorigen;
    
       end if;
      
    end if;
   
    raise notice '---- %', fechaoorigen;
    raise notice '---- %', sp_horas;
    raise notice '---- %', sp_horasmail;
    raise notice '---- %', sp_horastotales;
  
	while round(sp_horas) < sp_horasmail loop
	
		fechaoorigen 	:= fechaoorigen + interval '1 days';
	
		select date_part('dow', fechaoorigen)
          into sp_diasem ;
        
        raise notice 'sp - Dia de la semana %', sp_diasem;
        raise notice 'sp - Nueva fecha %', fechaoorigen;
    
		if (sp_diasem in (1,2,3,4,5)) then
		
		   sp_horas			:= sp_horas + 15;
		   sp_horastotales	:= sp_horas + 9;
		  
		elsif (sp_diasem in (6)) then
		
		   sp_horas			:= sp_horas + 7;
		   sp_horastotales	:= sp_horastotales + 17;
		  
		elsif (sp_diasem in (0)) then

		   sp_horastotales	:= sp_horastotales + 24;
		  
		end if;
         
   	end loop;
  
    raise notice 'Horas %', sp_horas ;
    raise notice 'Horas mail %', sp_horasmail ;
    raise notice 'Horas mail %', (sp_horasmail-sp_horas)*-1 ;
    raise notice 'Horas totales %', sp_horastotales;

    --intervalo := ''''||sp_horastotales-(sp_horas-sp_horasmail)||' hours';
    intervalo := ''''||sp_horastotales-((sp_horasmail-sp_horas)*-1)||' hours';
				
    salhorav := round(sp_horastotales-((sp_horasmail-sp_horas)*-1)::numeric);
   
    raise notice '%', 'Fecha final 1 es : '||sp_fechaoorigen + intervalo::interval;

    sp_fechatope	:= sp_fechaoorigen + intervalo::interval;
        
    raise notice '%', 'Fecha origen es : '||fechaoorigen;
    raise notice '%', 'Fecha tope es : '||sp_fechatope;
       
    return next;
      
  END;
$$;


ALTER FUNCTION traking.calculahorasincumplimientos_test(fechaoorigen timestamp without time zone, idnotificacions bigint) OWNER TO postgres;

--
-- TOC entry 1879 (class 1255 OID 16584)
-- Name: calculahorasincumplimientos_test_v1(timestamp without time zone, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calculahorasincumplimientos_test_v1(fechaoorigen timestamp without time zone, idnotificacions bigint) RETURNS TABLE(salhorav numeric)
    LANGUAGE plpgsql
    AS $$
declare
	   

	    sp_horas				numeric;
	    sp_horastotales			numeric;
	    sp_diasem				bigint;
	    sp_diasemhoy			bigint;
	   
	    sp_fechatope			timestamp;
	    sp_fechatopesabado		timestamp;
	    sp_fechatopeinicio		timestamp;
	   
	    sp_fechaoorigen			timestamp;
	   
	    sp_newfechaorigen		timestamp;
	   
	    sp_horasmail			bigint;
	   
	    sp_horasprimerdia		numeric;
	   
	    i                       numeric := 1;
        sp_cont                 numeric;
	    proceso                 boolean := true;
	    valor1					numeric(10,2);
	    valor2					numeric(10,2);
	    valor3					numeric(10,2);
	    valor4					numeric(10,2);
	    valor5					numeric(10,2);
	   	valor6					numeric(10,2);
	   	valor7					numeric(10,2);
	    valorKpi				numeric(10,2);
	   
	   	sp_ingresosabado		varchar := '08:30:00';
		sp_ingresodiahabil		varchar := '08:30:00';
		sp_finturnosabado		varchar := '14:30:00';
		sp_finturnohabil		varchar := '22:30:00';
		sp_findiahabil			varchar := '24:00:00';
	
		fechaHoy				timestamp without time zone  := substring(NOW()::Varchar,1,19)::timestamp without time zone;
	
		fechaOCdate				date   := substring(fechaoorigen::Varchar,1,10)::date;
	    
	    fechaOCfth              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 22:30:00')::timestamp without time zone;
	    fechaOCfts              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 14:30:00')::timestamp without time zone;
	   	fechaOCfdi              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 24:00:00')::timestamp without time zone;
	    fechaOCidi              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 00:00:00')::timestamp without time zone;
	    fechaOCith              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 07:30:00')::timestamp without time zone;
	   
	   	per_i					numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 07:30:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 00:00:00'::timestamp)) / 3600), 1);

	    per_kpi_h				numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 22:30:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 07:30:00'::timestamp)) / 3600), 1);

	    per_fh					numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 24:00:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 22:30:00'::timestamp)) / 3600), 1);
 
	    per_kpi_s				numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 14:30:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 07:30:00'::timestamp)) / 3600), 1);
 		
	    per_fs					numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 24:00:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 14:30:00'::timestamp)) / 3600), 1);
	   
	    per_df					numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 24:00:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 00:00:00'::timestamp)) / 3600), 1);
	   
	    sp_dia					bigint;
			       
begin
	
	RAISE NOTICE 'Inicio proceso ...........................................';
	sp_horas	:= 0;

	select kpihoras
	  into sp_horasmail
	  from traking.mct_agendamientomail ma 
	where idnotificacion = idnotificacions;

	select date_part('dow', fechaoorigen)  into sp_diasem;
	select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = fechaoorigen;
	if ( sp_cont >= 1) then 
		-- Los festivos los hago pasar por Domingo
		sp_diasem := 0;
	end if;

	select date_part('dow', fechaHoy)      into sp_diasemhoy;
	select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = fechaHoy;
	if ( sp_cont >= 1) then 
		-- Los festivos los hago pasar por Domingo
		sp_diasemhoy := 0;
	end if;

         
    valor5 := 0;
    if ( fechaoorigen <= fechaHoy ) then -- La OC esta en el pasado
        valor5 := 0;
    else  -- La OC esta en el futuro
		SELECT coalesce((( EXTRACT(EPOCH FROM  fechaoorigen) - EXTRACT(EPOCH FROM  fechaHoy)) / 3600), 1)
		   into valor5;
    end if;
	
   
   valor1   := 0; -- En esta variable contendra las horas conbsumida del KPI
   valor2   := 0; -- En esta variable contendra las horas que debera enviarse el mail
   valorKpi := 0;
   
   if sp_diasem <> 0 and sp_diasem <> 6 then -- Dia Habil   
   
        -- La F-OC estan entre el inicio de dia e inicio de turno
         if fechaoorigen >= fechaOCidi and fechaoorigen < fechaOCith then
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCith) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
			 
			-- RAISE NOTICE '1Valor2 % % %', sp_diasem,valor2,valorKpi;
			 
			SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfth) - EXTRACT(EPOCH FROM fechaOCith)) / 3600), 1)
			  into valor3;
			-- RAISE NOTICE '2Valor2 % % %', sp_diasem,valor3,valorKpi;
			 
			if ( valor3 >= sp_horasmail ) then
			   proceso := false;
			   valor2  := valor2 + valor3;
			else
			   valorKpi := valor3;
			   SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM fechaOCfth)) / 3600), 1)
			   into valor4;
			   valor2  := valor2 + valor3 + valor4;
			end if; 
		--	 RAISE NOTICE '3Valor2 % % %', sp_diasem,valor2,valorKpi;
         end if;
        
        -- La F-OC esta esta en el rango de turno de trabajo
         if fechaoorigen >= fechaOCith and fechaoorigen <= fechaOCfth then
         
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfth) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
			 
			if ( valor2 >= sp_horasmail ) then
			   proceso := false;
			else
			   valorKpi := valor2;
			   SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM fechaOCfth)) / 3600), 1)
			   into valor3;
			   valor2  := valor2 + valor3;
			end if; 
			
		--	 RAISE NOTICE '2Valor2 % %', sp_diasem,valor2;
         end if;
        
         -- La F-OC supera al rango de fin de turno y es menor fin de dia
         if fechaoorigen > fechaOCfth and fechaoorigen <= fechaOCfdi then
         
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi ) - EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 1)
			  into valor2;
			 valorKpi := 0;
			 
		--	 RAISE NOTICE '3Valor2 % %', sp_diasem,valor2;
         end if;
    end if;
   -- Dia dia Sabado --------------------------------------------
    if sp_diasem = 6 then 
    	--	RAISE NOTICE 'En el sabado';
    	
        -- La F-OC estan entre el inicio de dia e inicio de turno
         if fechaoorigen >= fechaOCidi and fechaoorigen < fechaOCith then
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCith) - EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 1)
			  into valor2;
			 
			SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfts) - EXTRACT(EPOCH FROM fechaOCith)) / 3600), 1)
			  into valor3;
			 
			 if ( valor3 >= sp_horasmail) then
			    proceso := false;
			    valor2 := valor2 + valor3;
			 else
				SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM fechaOCfts)) / 3600), 1)
			  	into valor4;
				valor2 := valor2 + valor3 + valor4;
		   		valorKpi := valor3;
		   	 end if;
			 
		--	 RAISE NOTICE '61Valor2 % %', sp_diasem,valor2;
         end if;
        
        -- La F-OC esta esta en el rango de turnbo de trabajo
         if fechaoorigen >= fechaOCith and fechaoorigen <= fechaOCfts then
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfts) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
			 
			--SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM  fechaOCfts)) / 3600), 1)
			--  into valor2;
			 --RAISE NOTICE '--------Valor2 % %', sp_diasem,valor2;
			 if ( valor3 >= sp_horasmail ) then
			    proceso := false;
			 else
				SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM fechaOCfts)) / 3600), 1)
			  	into valor4;
		   		valorKpi := valor2;
		   	    valor2 := valor2 + valor4;
		   	 end if;
		
			--RAISE NOTICE '62Valor2 % %', sp_diasem,valor2;
         end if;
        
         -- La F-OC supera al rango de fin de turno y es menor fin de dia
         if fechaoorigen > fechaOCfts and fechaoorigen <= fechaOCfdi then
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
			 valorKpi := 0;
			
		--	 RAISE NOTICE '63Valor2 % %', sp_diasem,valor2;
         end if;
    
    end if;
   -- Dia Domingo ------------------------------------
    if sp_diasem = 0 then 
    
       SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
		
	  -- RAISE NOTICE '0Valor2 % %', sp_diasem,valor2;
    
    end if;
   
   
   ---Ciclo   -------------------------------------------------------------------------------------------------
   i := 1;
   SELECT fechaOCdate + CAST('1 days' AS INTERVAL) into fechaOCdate;
   RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaoorigen,sp_diasem,valorKpi, valor2;

   while ( proceso ) loop
	   
	       i := i + 1;

		   select date_part('dow', fechaOCdate)  into sp_diasem; 
           	select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = fechaOCdate;
			if ( sp_cont >= 1) then 
				-- Los festivos los hago pasar por Domingo
				sp_diasem := 0;
			end if;
		   if sp_diasem <> 0 and sp_diasem <> 6 then -- Dia Habil  
		      --RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaOCdate,sp_diasem,valorKpi, valor2;
			  valor2 := valor2 + per_i; 	
			  RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaOCdate,sp_diasem,valorKpi, valor2;
		      if ( ( valorKpi+ per_kpi_h ) >= sp_horasmail ) then
		           valor7 := ( sp_horasmail - valorKpi );
		           valor2  := valor2 + valor7;
		           RAISE NOTICE '---------------------Valor2 % % % %', fechaOCdate, valor2, valorKpi, valor7;
		            proceso := false;
		      else
		           valor2  := valor2 + per_kpi_h + per_fh;
		           valorKpi := valorKpi + per_kpi_h;  
		       end if;
		        
		   end if;
		   -- Dia dia Sabado --------------------------------------------
		   if sp_diasem = 6 then -- Sabado
		   
				valor7 := valor2;
			    valor2 := valor2 + per_i;
			    if (( valorKpi + per_kpi_s ) >= sp_horasmail ) then
		                 valor2  := valor2 + (sp_horasmail - valorKpi);
		                 proceso := false;
		        else
		                 valor2  := valor2 + per_kpi_s + per_fs;
		                 valorKpi := valorKpi + per_kpi_s;
		       end if;
			   
			   RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaOCdate,sp_diasem,valorKpi, valor2;
			   
		   end if;
		   -- Dia Domingo ------------------------------------
		   if sp_diasem = 0 then -- Domingo o festivo
		       valor7 := valor2;
		       valor2 := valor2 + per_df;
			   RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaOCdate,sp_diasem,valorKpi, valor2;
		   end if;
		   
		   SELECT fechaOCdate + CAST('1 days' AS INTERVAL) into fechaOCdate;

    end loop;
    RAISE NOTICE 'valorFinal % % ', valorKpi, valor2;
 	salhorav := valor2 + valor5;
	       
	return next;
      
  END;
$$;


ALTER FUNCTION traking.calculahorasincumplimientos_test_v1(fechaoorigen timestamp without time zone, idnotificacions bigint) OWNER TO postgres;

--
-- TOC entry 2250 (class 1255 OID 16586)
-- Name: calculahorasincumplimientos_test_v1_resp(timestamp without time zone, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calculahorasincumplimientos_test_v1_resp(fechaoorigen timestamp without time zone, idnotificacions bigint) RETURNS TABLE(salhorav numeric)
    LANGUAGE plpgsql
    AS $$
declare
	   

	    sp_horas				numeric;
	    sp_horastotales			numeric;
	    sp_diasem				bigint;
	    sp_diasemhoy			bigint;
	   
	    sp_fechatope			timestamp;
	    sp_fechatopesabado		timestamp;
	    sp_fechatopeinicio		timestamp;
	   
	    sp_fechaoorigen			timestamp;
	   
	    sp_newfechaorigen		timestamp;
	   
	    sp_horasmail			bigint;
	   
	    sp_horasprimerdia		numeric;
	   
	    i                       numeric := 1;
	    proceso                 boolean := true;
	    valor1					numeric(10,2);
	    valor2					numeric(10,2);
	    valor3					numeric(10,2);
	    valor4					numeric(10,2);
	    valor5					numeric(10,2);
	   	valor6					numeric(10,2);
	   	valor7					numeric(10,2);
	    valorKpi				numeric(10,2);
	   
	   	sp_ingresosabado		varchar := '08:30:00';
		sp_ingresodiahabil		varchar := '08:30:00';
		sp_finturnosabado		varchar := '14:30:00';
		sp_finturnohabil		varchar := '22:30:00';
		sp_findiahabil			varchar := '24:00:00';
	
		fechaHoy				timestamp without time zone  := substring(NOW()::Varchar,1,19)::timestamp without time zone;
	
		fechaOCdate				date   := substring(fechaoorigen::Varchar,1,10)::date;
	    
	    fechaOCfth              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 22:30:00')::timestamp without time zone;
	    fechaOCfts              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 14:30:00')::timestamp without time zone;
	   	fechaOCfdi              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 24:00:00')::timestamp without time zone;
	    fechaOCidi              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 00:00:00')::timestamp without time zone;
	    fechaOCith              timestamp without time zone :=  CONCAT(substring(fechaoorigen::Varchar,1,10),' 07:30:00')::timestamp without time zone;
	   
	   	per_i					numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 07:30:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 00:00:00'::timestamp)) / 3600), 1);

	    per_kpi_h				numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 22:30:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 07:30:00'::timestamp)) / 3600), 1);

	    per_fh					numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 24:00:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 22:30:00'::timestamp)) / 3600), 1);
 
	    per_kpi_s				numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 14:30:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 07:30:00'::timestamp)) / 3600), 1);
 		
	    per_fs					numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 24:00:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 14:30:00'::timestamp)) / 3600), 1);
	   
	    per_df					numeric(10,2) :=  coalesce((( EXTRACT(EPOCH FROM  '2023-09-13 24:00:00'::timestamp) - EXTRACT(EPOCH FROM  '2023-09-13 00:00:00'::timestamp)) / 3600), 1);
	   
	    sp_dia					bigint;
			       
begin
	
	RAISE NOTICE 'Inicio proceso ...........................................';
	sp_horas	:= 0;

	select kpihoras
	  into sp_horasmail
	  from traking.mct_agendamientomail ma 
	where idnotificacion = idnotificacions;

	select date_part('dow', fechaoorigen)  into sp_diasem;
	select date_part('dow', fechaHoy)      into sp_diasemhoy;
  
         
    valor5 := 0;
    if ( fechaoorigen <= fechaHoy ) then -- La OC esta en el pasado
        valor5 := 0;
    else  -- La OC esta en el futuro
		SELECT coalesce((( EXTRACT(EPOCH FROM  fechaoorigen) - EXTRACT(EPOCH FROM  fechaHoy)) / 3600), 1)
		   into valor5;
    end if;
	
   
   valor1   := 0; -- En esta variable contendra las horas conbsumida del KPI
   valor2   := 0; -- En esta variable contendra las horas que debera enviarse el mail
   valorKpi := 0;
   
   if sp_diasem <> 0 and sp_diasem <> 6 then -- Dia Habil   
   
        -- La F-OC estan entre el inicio de dia e inicio de turno
         if fechaoorigen >= fechaOCidi and fechaoorigen < fechaOCith then
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCith) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
			 
			-- RAISE NOTICE '1Valor2 % % %', sp_diasem,valor2,valorKpi;
			 
			SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfth) - EXTRACT(EPOCH FROM fechaOCith)) / 3600), 1)
			  into valor3;
			-- RAISE NOTICE '2Valor2 % % %', sp_diasem,valor3,valorKpi;
			 
			if ( valor3 >= sp_horasmail ) then
			   proceso := false;
			   valor2  := valor2 + valor3;
			else
			   valorKpi := valor3;
			   SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM fechaOCfth)) / 3600), 1)
			   into valor4;
			   valor2  := valor2 + valor3 + valor4;
			end if; 
		--	 RAISE NOTICE '3Valor2 % % %', sp_diasem,valor2,valorKpi;
         end if;
        
        -- La F-OC esta esta en el rango de turno de trabajo
         if fechaoorigen >= fechaOCith and fechaoorigen <= fechaOCfth then
         
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfth) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
			 
			if ( valor2 >= sp_horasmail ) then
			   proceso := false;
			else
			   valorKpi := valor2;
			   SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM fechaOCfth)) / 3600), 1)
			   into valor3;
			   valor2  := valor2 + valor3;
			end if; 
			
		--	 RAISE NOTICE '2Valor2 % %', sp_diasem,valor2;
         end if;
        
         -- La F-OC supera al rango de fin de turno y es menor fin de dia
         if fechaoorigen > fechaOCfth and fechaoorigen <= fechaOCfdi then
         
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi ) - EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 1)
			  into valor2;
			 valorKpi := 0;
			 
		--	 RAISE NOTICE '3Valor2 % %', sp_diasem,valor2;
         end if;
    end if;
   -- Dia dia Sabado --------------------------------------------
    if sp_diasem = 6 then 
    	--	RAISE NOTICE 'En el sabado';
    	
        -- La F-OC estan entre el inicio de dia e inicio de turno
         if fechaoorigen >= fechaOCidi and fechaoorigen < fechaOCith then
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCith) - EXTRACT(EPOCH FROM fechaoorigen)) / 3600), 1)
			  into valor2;
			 
			SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfts) - EXTRACT(EPOCH FROM fechaOCith)) / 3600), 1)
			  into valor3;
			 
			 if ( valor3 >= sp_horasmail) then
			    proceso := false;
			    valor2 := valor2 + valor3;
			 else
				SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM fechaOCfts)) / 3600), 1)
			  	into valor4;
				valor2 := valor2 + valor3 + valor4;
		   		valorKpi := valor3;
		   	 end if;
			 
		--	 RAISE NOTICE '61Valor2 % %', sp_diasem,valor2;
         end if;
        
        -- La F-OC esta esta en el rango de turnbo de trabajo
         if fechaoorigen >= fechaOCith and fechaoorigen <= fechaOCfts then
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfts) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
			 
			--SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM  fechaOCfts)) / 3600), 1)
			--  into valor2;
			 --RAISE NOTICE '--------Valor2 % %', sp_diasem,valor2;
			 if ( valor3 >= sp_horasmail ) then
			    proceso := false;
			 else
				SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM fechaOCfts)) / 3600), 1)
			  	into valor4;
		   		valorKpi := valor2;
		   	    valor2 := valor2 + valor4;
		   	 end if;
		
			--RAISE NOTICE '62Valor2 % %', sp_diasem,valor2;
         end if;
        
         -- La F-OC supera al rango de fin de turno y es menor fin de dia
         if fechaoorigen > fechaOCfts and fechaoorigen <= fechaOCfdi then
            SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
			 valorKpi := 0;
			
		--	 RAISE NOTICE '63Valor2 % %', sp_diasem,valor2;
         end if;
    
    end if;
   -- Dia Domingo ------------------------------------
    if sp_diasem = 0 then 
    
       SELECT coalesce((( EXTRACT(EPOCH FROM fechaOCfdi) - EXTRACT(EPOCH FROM  fechaoorigen)) / 3600), 1)
			  into valor2;
		
	  -- RAISE NOTICE '0Valor2 % %', sp_diasem,valor2;
    
    end if;
   
   
   ---Ciclo   -------------------------------------------------------------------------------------------------
   i := 1;
   SELECT fechaOCdate + CAST('1 days' AS INTERVAL) into fechaOCdate;
   RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaoorigen,sp_diasem,valorKpi, valor2;

   while ( proceso ) loop
	   
	       i := i + 1;

		   select date_part('dow', fechaOCdate)  into sp_diasem; 
		   if sp_diasem <> 0 and sp_diasem <> 6 then -- Dia Habil  
		      --RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaOCdate,sp_diasem,valorKpi, valor2;
			  valor2 := valor2 + per_i; 	
			  RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaOCdate,sp_diasem,valorKpi, valor2;
		      if ( ( valorKpi+ per_kpi_h ) >= sp_horasmail ) then
		           valor7 := ( sp_horasmail - valorKpi );
		           valor2  := valor2 + valor7;
		           RAISE NOTICE '---------------------Valor2 % % % %', fechaOCdate, valor2, valorKpi, valor7;
		            proceso := false;
		      else
		           valor2  := valor2 + per_kpi_h + per_fh;
		           valorKpi := valorKpi + per_kpi_h;  
		       end if;
		        
		   end if;
		   -- Dia dia Sabado --------------------------------------------
		   if sp_diasem = 6 then -- Sabado
		   
				valor7 := valor2;
			    valor2 := valor2 + per_i;
			    if (( valorKpi + per_kpi_s ) >= sp_horasmail ) then
		                 valor2  := valor2 + (sp_horasmail - valorKpi);
		                 proceso := false;
		        else
		                 valor2  := valor2 + per_kpi_s + per_fs;
		                 valorKpi := valorKpi + per_kpi_s;
		       end if;
			   
			   RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaOCdate,sp_diasem,valorKpi, valor2;
			   
		   end if;
		   -- Dia Domingo ------------------------------------
		   if sp_diasem = 0 then -- Domingo o festivo
		       valor7 := valor2;
		       valor2 := valor2 + per_df;
			   RAISE NOTICE '% % KpiTmp( % ) TpoMail ( % )', fechaOCdate,sp_diasem,valorKpi, valor2;
		   end if;
		   
		   SELECT fechaOCdate + CAST('1 days' AS INTERVAL) into fechaOCdate;

    end loop;
    RAISE NOTICE 'valorFinal % % ', valorKpi, valor2;
 	salhorav := valor2 + valor5;
	       
	return next;
      
  END;
$$;


ALTER FUNCTION traking.calculahorasincumplimientos_test_v1_resp(fechaoorigen timestamp without time zone, idnotificacions bigint) OWNER TO postgres;

--
-- TOC entry 1271 (class 1255 OID 16588)
-- Name: calcularavancemecanizado(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calcularavancemecanizado(idworkorders bigint) RETURNS TABLE(salav numeric)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombreordentrabajo   varchar; 
		sp_planogeneral 		varchar;
		sp_idproducto           integer;
		sp_nombreproducto		varchar;
		sp_ordencompra          bigint;
		sp_idcotizacion         integer;
		sp_fechaentrega			timestamp;
		sp_idestadoorden        integer;
		sp_nombreestado         varchar;
		sp_minutos              integer;	       
		sp_cantidadtot          integer;
	   
	    sp_cantidadlcc			integer;
	    sp_cantidadrtm			integer;
	   
	    sp_porcentajelcc		varchar;
	   	sp_porcentajertm		varchar;
	   
	    sp_piezas               integer;
	    
	    sp_idot					integer;
	    sp_idproductonep		integer;
	    --sp_nombreordentrabajo	varchar;
	    sp_idfamilia			integer;
	   
	    sp_sumatotallcc			integer;
	    sp_canthr				integer;
	    sp_liberadascc			integer;

	    sp_avance				numeric;
	    sp_avancetm				numeric;
	    rec_lcc      			RECORD;
	   
	    sp_textoout				varchar;
	   
	    sp_imprime				bigint;
			       
BEGIN
			
		    -- desde aca el nuevo calculo
			sp_sumatotallcc  := 0;
		    sp_avance		 := 0;
		    sp_avancetm		 := 0;
		   
		    sp_imprime		 := 0;
		   
			FOR rec_lcc IN (   
					select distinct b.idhojarutatemp, b.codhojaruta 
					  from mct_movimientoordentrabajo a,
					       mct_hojaruta b
					 where a.codigoaccion in ('L_CC','R_TM')
				       and a.idordentrabajo = idworkorders
				       and a.idhojaruta = b.idhojaruta 
				       order by 1 asc
						)
	    		loop 	
		    		
		    		
				      sp_liberadascc	:= 0;
								   
				      select a.idimprimehojas
				        into sp_imprime
				        from mct_hojarutatemp a 
				       where a.idhojarutatemp = rec_lcc.idhojarutatemp;
				     
				      --raise notice '%', sp_imprime;
				      if (sp_imprime = 2) then --individuales
				      
					      select count(b.*)      
				  	        into sp_liberadascc
				  	        from mct_hojarutatemp a,
				  	             mct_detallehojarutatemp b
					       where a.idhojarutatemp = rec_lcc.idhojarutatemp
					         and a.idhojarutatemp = b.idhojarutatemp 
					         and b.codhojaruta = rec_lcc.codhojaruta
					         and a.idboleano = 1
					         and a.aplicahojaruta is true
					         and a.idcriterioevaluacion != 7
					         and a.idareaclasificacion in (0,1,2,3,4,5,8);				      
				      
				      else
				      
					      select coalesce (sum(a.cantidad),0)      
				  	        into sp_liberadascc
				  	        from mct_hojarutatemp a,
				  	             mct_detallehojarutatemp b
					       where a.idhojarutatemp = rec_lcc.idhojarutatemp
					         and a.idhojarutatemp = b.idhojarutatemp 
					         and b.codhojaruta = rec_lcc.codhojaruta
					         and a.idboleano = 1
					         and a.aplicahojaruta is true
					         and a.idcriterioevaluacion != 7
					         and a.idareaclasificacion in (0,1,2,3,4,5,8);				      
				      
				      
				      end if;
				     
						     
--					  sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
				        
					  if ( select 1
						     from mct_movimientoordentrabajo a,
				                  mct_hojaruta b,
			  	                  mct_detallehojarutatemp c
			                where b.idhojarutatemp = rec_lcc.idhojarutatemp
			                  and b.idhojarutatemp = c.idhojarutatemp 
				              and c.codhojaruta = rec_lcc.codhojaruta
			                  and a.idhojaruta = b.idhojaruta 
				              and (a.codigoaccion = 'NC_MECCCC' or a.codigoaccion = 'NC_FUUUU') 
				              ) then
					                   
			              if ( select 1
				                 from mct_movimientoordentrabajo a,
				                      mct_hojaruta b,
				                      mct_detallehojarutatemp c
				                where b.idhojarutatemp = rec_lcc.idhojarutatemp
				                  and a.idhojaruta = b.idhojaruta 
				                  and b.idhojarutatemp = c.idhojarutatemp 
				                  and c.codhojaruta = rec_lcc.codhojaruta
				                  and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
						                                              from mct_movimientoordentrabajo b
						                                             where a.idhojaruta = b.idhojaruta 
						                                               and a.codigoaccion = 'L_CC' ) ) then

							 sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						                  
						     sp_textoout := idworkorders||' 1- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
						     raise notice '%', sp_textoout;
						                   
						  else
						                              
					         sp_sumatotallcc := sp_sumatotallcc + 0;
						                  
						     sp_textoout := idworkorders||' 2- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
						     raise notice '%', sp_textoout;
					                  
				         end if;
						                               
					  else
					      sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
					                  
					      sp_textoout := idworkorders||' 3- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
					      raise notice '%', sp_textoout;
					                  
					  end if;				        
						           
			END LOOP;
				  		
		    sp_sumatotallcc := sp_sumatotallcc * 100;
		    -- hasta aca el nuevo calculo
		    raise notice '%', sp_sumatotallcc;
				  	
			-- aca sacamos la cantidad de piezas totales
		    select coalesce ( sum(cantidad), 0)
		      into sp_canthr
		      from mct_hojarutatemp mh
		     where idordentrabajo = idworkorders
		       and idboleano = 1
		       and aplicahojaruta is true
		       and idcriterioevaluacion != 7
		       and idareaclasificacion in (0,1,2,3,4,5,8);
					     
		    -- aca sacamos la cantidad de piezas liberadas de control de calidad
					      
		    if ( sp_canthr = 0) then
			     sp_avance := 0;
		    else
				--sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
				sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
		    end if;


            --percentlcc 		:= cast(round(sp_avance) as varchar);
            salav			:= sp_avance;
              
		RETURN NEXT;
	
	return;

END;
$$;


ALTER FUNCTION traking.calcularavancemecanizado(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1078 (class 1255 OID 16590)
-- Name: calcularavancemecanizadozona1(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calcularavancemecanizadozona1(idworkorders bigint) RETURNS TABLE(avancemasfecha character varying)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombreordentrabajo   varchar; 
		sp_planogeneral 		varchar;
		sp_idproducto           integer;
		sp_nombreproducto		varchar;
		sp_ordencompra          bigint;
		sp_idcotizacion         integer;
		sp_fechaentrega			timestamp;
		sp_idestadoorden        integer;
		sp_nombreestado         varchar;
		sp_minutos              integer;	       
		sp_cantidadtot          integer;
	   
	    sp_cantidadlcc			integer;
	    sp_cantidadrtm			integer;
	   
	    sp_porcentajelcc		varchar;
	   	sp_porcentajertm		varchar;
	   
	    sp_piezas               integer;
	    
	    sp_idot					integer;
	    sp_idproductonep		integer;
	    --sp_nombreordentrabajo	varchar;
	    sp_idfamilia			integer;
	   
	    sp_sumatotallcc			integer;
	    sp_canthr				integer;
	    sp_liberadascc			integer;

	    sp_avance				numeric;
	    sp_avancetm				numeric;
	    rec_lcc      			RECORD;
	   
	    sp_textoout				varchar;
	   
	    sp_imprime				bigint;
        sp_fechamaximaz1		varchar;
			       
BEGIN
			
		    -- desde aca el nuevo calculo
			sp_sumatotallcc  	:= 0;
		    sp_avance		 	:= 0;
		    sp_avancetm		 	:= 0;
		   
		    sp_imprime		 	:= 0;
			sp_fechamaximaz1	:= null;
		   
			FOR rec_lcc IN (   
					select distinct b.idhojarutatemp, 
                           b.codhojaruta 
					  from mct_movimientoordentrabajo a,
					       mct_hojaruta b,
                           mct_hojarutatemp c
					 where a.codigoaccion in ('L_CC','R_TM')
				       and a.idordentrabajo = idworkorders --33738
				       and a.idhojaruta = b.idhojaruta 
                       and b.idhojarutatemp = c.idhojarutatemp
                       and c.nombrezona = 'I'
				       order by 1 asc
						)
	    		loop 			
		    		
				      sp_liberadascc	:= 0;
								   
				      select a.idimprimehojas
				        into sp_imprime
				        from mct_hojarutatemp a 
				       where a.idhojarutatemp = rec_lcc.idhojarutatemp;
				     
				      --raise notice '%', sp_imprime;
				      if (sp_imprime = 2) then --individuales
				      
					      select count(b.*)      
				  	        into sp_liberadascc
				  	        from mct_hojarutatemp a,
				  	             mct_detallehojarutatemp b
					       where a.idhojarutatemp = rec_lcc.idhojarutatemp
					         and a.idhojarutatemp = b.idhojarutatemp 
					         and b.codhojaruta = rec_lcc.codhojaruta
					         and a.idboleano = 1
					         and a.aplicahojaruta is true
					         and a.idcriterioevaluacion != 7
					         and a.idareaclasificacion in (0,1,2,3,4,5,8);				      
				      
				      else
				      
					      select coalesce (sum(a.cantidad),0)      
				  	        into sp_liberadascc
				  	        from mct_hojarutatemp a,
				  	             mct_detallehojarutatemp b
					       where a.idhojarutatemp = rec_lcc.idhojarutatemp
					         and a.idhojarutatemp = b.idhojarutatemp 
					         and b.codhojaruta = rec_lcc.codhojaruta
					         and a.idboleano = 1
					         and a.aplicahojaruta is true
					         and a.idcriterioevaluacion != 7
					         and a.idareaclasificacion in (0,1,2,3,4,5,8);				      
				      
				      
				      end if;
				     
						     
--					  sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
				        
					  if ( select 1
						     from mct_movimientoordentrabajo a,
				                  mct_hojaruta b,
			  	                  mct_detallehojarutatemp c
			                where b.idhojarutatemp = rec_lcc.idhojarutatemp
			                  and b.idhojarutatemp = c.idhojarutatemp 
				              and c.codhojaruta = rec_lcc.codhojaruta
			                  and a.idhojaruta = b.idhojaruta 
				              and (a.codigoaccion = 'NC_MECCCC' or a.codigoaccion = 'NC_FUUUU') 
				              ) then
					                   
			              if ( select 1
				                 from mct_movimientoordentrabajo a,
				                      mct_hojaruta b,
				                      mct_detallehojarutatemp c
				                where b.idhojarutatemp = rec_lcc.idhojarutatemp
				                  and a.idhojaruta = b.idhojaruta 
				                  and b.idhojarutatemp = c.idhojarutatemp 
				                  and c.codhojaruta = rec_lcc.codhojaruta
				                  and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
						                                              from mct_movimientoordentrabajo b
						                                             where a.idhojaruta = b.idhojaruta 
						                                               and a.codigoaccion = 'L_CC' ) ) then

							 sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						                  
						     sp_textoout := idworkorders||' 1- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
						     --raise notice '%', sp_textoout;
						                   
						  else
						                              
					         sp_sumatotallcc := sp_sumatotallcc + 0;
						                  
						     sp_textoout := idworkorders||' 2- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
						     --raise notice '%', sp_textoout;
					                  
				         end if;
						                               
					  else
					      sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
					                  
					      sp_textoout := idworkorders||' 3- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
					      --raise notice '%', sp_textoout;
					                  
					  end if;				        
						           
			END LOOP;
				  		
		    sp_sumatotallcc := sp_sumatotallcc * 100;
		    -- hasta aca el nuevo calculo
		    raise notice '%', sp_sumatotallcc;
				  	
			-- aca sacamos la cantidad de piezas totales
		    select coalesce ( sum(cantidad), 0)
		      into sp_canthr
		      from mct_hojarutatemp mh
		     where idordentrabajo = idworkorders
		       and idboleano = 1
		       and aplicahojaruta is true
		       and idcriterioevaluacion != 7
		       and idareaclasificacion in (0,1,2,3,4,5,8)
               and nombrezona = 'I';
					     
		    -- aca sacamos la cantidad de piezas liberadas de control de calidad
					      
		    if ( sp_canthr = 0) then
			     sp_avance := 0;
		    else
				sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
		    end if;

			-- Sacamos maxima fecha 100% zona1
			select to_char(max(a.fechatermino) , 'dd-mm-yyyy')
              into sp_fechamaximaz1
			  from mct_movimientoordentrabajo a,
			       mct_hojaruta b,
                   mct_hojarutatemp c
			 where a.codigoaccion in ('L_CC')
		       and a.idordentrabajo = idworkorders
		       and a.idhojaruta = b.idhojaruta 
               and b.idhojarutatemp = c.idhojarutatemp
               and c.nombrezona = 'I';

            avancemasfecha	:= sp_avance||'#'||sp_fechamaximaz1;
              
		RETURN NEXT;
	
	return;

END;
$$;


ALTER FUNCTION traking.calcularavancemecanizadozona1(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1899 (class 1255 OID 16592)
-- Name: calcularavancepanol(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calcularavancepanol(idworkorders bigint) RETURNS TABLE(salav numeric)
    LANGUAGE plpgsql
    AS $$
declare
	   
	    sp_cantidad_pa			bigint;
	    sp_codigoqr_pa			varchar;
	    sp_fecharequerida_pa	timestamp;
	    
	    sp_recept_pa			bigint;
	    sp_maxfecha_pa			timestamp;

	    sp_avance_pa			numeric;

			       
BEGIN
			
	-- desde aca el nuevo calculo
	   sp_avance_pa		 := 0;
		   
   	-- Pañol
	-- aca sacamos las piezas totales solicitadas a fundicion  
	   select coalesce ( sum(cantidad), 0),
	          codigoqr, 
	          fecharequerida
	     into sp_cantidad_pa,
	          sp_codigoqr_pa,
	          sp_fecharequerida_pa				          
	     from mct_checklistinftecvalido mc 
	    where tipotrabajostd = 'FAB_PA'
	      and idordentrabajo = idworkorders
	      group by codigoqr, fecharequerida;
	   
	   -- aca sacamos el total de piezas recepcionadas   
	   select coalesce ( sum(cantidad), 0),
	          max(fechacreacion)
	     into sp_recept_pa,
	          sp_maxfecha_pa		   
	     from mct_checklistinftecrecept
	    where codigoqr = sp_codigoqr_pa;

       if (sp_cantidad_pa = 0 ) then
           sp_cantidad_pa := 1;
       end if;
  
	   sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    

       salav			:= sp_avance_pa;
              
	RETURN NEXT;
	
END;
$$;


ALTER FUNCTION traking.calcularavancepanol(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1218 (class 1255 OID 16593)
-- Name: calcularavancerpo(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calcularavancerpo(idworkorders bigint) RETURNS TABLE(salav numeric)
    LANGUAGE plpgsql
    AS $$
declare
	   
	    sp_cantidad_co			bigint;
	    sp_codigoqr_co			varchar;
	    sp_fecharequerida_co	timestamp;
	    
	    sp_recept_co			bigint;
	    sp_maxfecha_co			timestamp;

	    sp_avance_co			numeric;

			       
BEGIN
			
	-- desde aca el nuevo calculo
	   sp_avance_co		 := 0;
		   
    -- Compras
	   -- aca sacamos las piezas totales solicitadas a compras  
	   select coalesce ( sum(cantidad), 0),
	          codigoqr, 
	          fecharequerida
	     into sp_cantidad_co,
	          sp_codigoqr_co,
	          sp_fecharequerida_co				          
	     from mct_checklistinftecvalido mc 
	    where tipotrabajostd = 'RPO'
	      and idordentrabajo = idworkorders
	      group by codigoqr, fecharequerida;
	   
	   -- aca sacamos el total de piezas recepcionadas   
	   select coalesce ( sum(cantidad), 0),
	          max(fechacreacion)
	     into sp_recept_co,
	          sp_maxfecha_co	 			   
	     from mct_checklistinftecrecept
	    where codigoqr = sp_codigoqr_co;			    

       if (sp_cantidad_co = 0 ) then
           sp_cantidad_co := 1;
       end if;				   
	   
	   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);						    

       salav			:= sp_avance_co;
              
	RETURN NEXT;
	
END;
$$;


ALTER FUNCTION traking.calcularavancerpo(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1650 (class 1255 OID 16594)
-- Name: calculavencimientodefecto(timestamp without time zone); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calculavencimientodefecto(createdate timestamp without time zone) RETURNS TABLE(fecvec character varying)
    LANGUAGE plpgsql
    AS $$
declare
	   
	  sp_diasem			bigint;
	  sp_horas			bigint;
	  intervalo         varchar;
			       
BEGIN
		
	-- Calcula dia de la semana
	select date_part('dow', createdate)
	  into sp_diasem;
		    
    sp_horas	:= 72;
		   
    if (sp_diasem = 5) then
        sp_horas = 144;
    elsif (sp_diasem = 4) then
           sp_horas = 120;
    elsif (sp_diasem = 3) then
           sp_horas = 120;
    end if;
   		
    intervalo := ''''||sp_horas||' hours';
 
    select to_char(createdate + intervalo::interval, 'dd-mm-yyyy')
      into fecvec;
     
     raise notice '%', fecvec;
   
 --   salav	:= sp_avance;
              	
	return next;

END;
$$;


ALTER FUNCTION traking.calculavencimientodefecto(createdate timestamp without time zone) OWNER TO postgres;

--
-- TOC entry 1633 (class 1255 OID 16595)
-- Name: calculohorashextras(bigint, character varying, character varying, integer); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.calculohorashextras(inoperador bigint, infechadesde character varying, infechahasta character varying, inarea integer) RETURNS TABLE(salhe numeric, salhei numeric)
    LANGUAGE plpgsql
    AS $$
declare 

    var_record1 			record;
    sp_horaminuto			varchar;
   	sp_aplicaturnofund		boolean;
	sp_horanticipadadh		varchar := '07:30';
	sp_horanticipadasabado	varchar := '07:30';
	sp_salidanormaldf		varchar := '13:30';
	sp_salidanormaldh		varchar := '16:00';
	sp_salidanormalsabado 	varchar := '13:00';
	
	sp_finturno				varchar := '13:30';

	sp_ingresodf			varchar := '08:30';
	sp_ingresosabado		varchar := '07:30';
	sp_ingresodiahabil		varchar := '07:30';

    sp_turno13 				varchar := '13:00';
    sp_turno16 				varchar := '16:00';
    sp_turno18				varchar := '18:00';
    sp_turno20 				varchar := '20:00';
   	sp_turno2130 			varchar := '21:30';
   
    sp_turno2400 			varchar := '24:00';
   
    sp_salidatmp		 	varchar := '24:00';
    sp_ingresotmp		 	varchar := '08:00';
     				
	sp_tipodia				integer;
    sp_tipodiaTmp			integer;
   	sp_DiaSig    			timestamp;
	sp_cont					integer;
	sp_he					numeric := 0.0;
	sp_hetmp				numeric := 0.0;
	sp_hetmp00				numeric := 0.0;
	sp_hetmp01				numeric := 0.0;
	sp_flagbool				boolean;
	queryHE					varchar;
begin
	sp_he 		:= 0.0;
	sp_hetmp 	:= 0.0;
	salhe		:= 0.0;
	salhei		:= 0.0;
	if ( inarea = 0 ) then
	   queryHE := concat('select * from  traking.mct_operador a left join  traking.mct_operadorturnofund b on ( a.idoperador = b.idoperador )
			where (b.fechaturno between to_date(',E'''',infechadesde,E'''',E',''','yyyy-mm-dd',E''') and  to_date(',E'''',infechahasta,E'''',E',''','yyyy-mm-dd',E''')) and  a.idoperador = ',inoperador);
	else
	  queryHE := concat('select * from  traking.mct_operador a left join  traking.mct_operadorturnomaestranza b on ( a.idoperador = b.idoperador )
			where (b.fechaturno between to_date(',E'''',infechadesde,E'''',E',''','yyyy-mm-dd',E''') and  to_date(',E'''',infechahasta,E'''',E',''','yyyy-mm-dd',E''')) and  a.idoperador = ',inoperador);	
	end if;
	
	FOR var_record1 in execute queryHE
	   loop

		   --0: Domingo
		   --6: Sabado
		   --1-5: Habil
		--   raise notice 'ausente %',var_record1.ausente;
		--   if ( var_record1.ausente) then
		--        -- operador ausente
		   		--raise notice 'ausente %',var_record1.ausente;
		--   		salhe		:= 0.0;
		--		salhei		:= 0.0;
		--		return next;
		--   		return;
		--   end if;
		  
		   select extract (DOW from  var_record1.fechaturno ) into sp_tipodia;
		   select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = var_record1.fechaturno;
		   if ( sp_cont >= 1) then 
		        -- Los festivos los hago pasar por Domingo
		  		sp_tipodia := 0;
		   end if;	
			 -- Festivo o Domingo
		  	raise notice 'Tipo dia-----> %',sp_tipodia;
		  	
-------- Domingo o festivo -------------------------------------------------------------------------------------------------------
			if ( sp_tipodia = 0 ) then 
				if (  var_record1.ingresoanticipado ) then 
					select c.nombrehoraminuto, c.aplicaturnofund  into sp_horaminuto, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutoingant;
					raise notice ' % Horas-----> %',sp_horaminuto, sp_ingresodf;
				   select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_ingresodf AS TIME) - CAST(sp_horaminuto AS TIME) as Tiempo) T;
       				salhei :=  salhei + sp_hetmp;
		    	end if;
		    
		    	-- Determino horario de salida
		    	sp_flagbool := true;
		        case
     				 when  var_record1.turno13 		then sp_finturno := sp_turno13;
     				 when  var_record1.turno16 		then sp_finturno := sp_turno16;
     				
     				
     				 when  var_record1.turno18 		then sp_finturno := sp_turno18;
     				 when  var_record1.turno20 		then sp_finturno := sp_turno20;
     				 when  var_record1.turno2130 	then sp_finturno := sp_turno2130;
     				 when  var_record1.turnootro 	then select c.nombrehoraminuto, c.aplicaturnofund  into sp_finturno, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutootro;
     				else sp_flagbool = false;
     			end case;
     			-- Calculo Horas hasta el fin de su turno
				if ( sp_flagbool ) then
				    raise notice ' % Horas-----> %',sp_horaminuto, sp_ingresodf;
					select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_ingresodf AS TIME) as Tiempo) T;
       				salhe :=  salhe + sp_hetmp;
				end if;   
			
				if ( var_record1.turnonoche ) then
				        
					    select c.nombrehoraminuto  into sp_finturno from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutonoche;
						--select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
						--into sp_hetmp
       					--from (select CAST(sp_finturno AS TIME) - CAST(sp_ingresodf AS TIME) as Tiempo) T;
       				    --raise notice '1. Turno Noche -----> % % %', sp_finturno, sp_ingresodf, sp_hetmp;
       					--if ( sp_hetmp < 0) then
       					    
       					-- Calculo de las horas del dia domingo/festivo hasta las 24:00 hrs
       						select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       						into sp_hetmp
       						from (select CAST(sp_turno2400 AS TIME) - CAST(sp_ingresodf AS TIME) as Tiempo) T;
       						salhe :=  sp_hetmp;
       						raise notice '1. Turno Noche -----> % % % %',sp_ingresodf, sp_finturno, sp_hetmp, salhe;
       					
       					 -- Reviso siguiente dia( puede ser Festivo, Sabado o Dia habil
       						SELECT cast((CAST(var_record1.fechaturno  AS DATE) + CAST('1 days' AS INTERVAL)) as timestamp) into sp_DiaSig;
       						select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = sp_DiaSig;
		   					if ( sp_cont >= 1) then 
		       					 -- Los festivos los hago pasar por Domingo
		  						sp_tipodiaTmp   := 0;
		  					    sp_salidatmp	:= sp_salidanormaldf;
    							sp_ingresotmp	:= sp_ingresodf;
		  					else
		  					    select extract (DOW from  ( SELECT CAST(var_record1.fechaturno  AS DATE) + CAST('1 days' AS INTERVAL)) ) 
       					    	into sp_tipodiaTmp;
       					        if ( sp_tipodiaTmp = 6) then
		  					    	sp_salidatmp	:= sp_salidanormalsabado;
    								sp_ingresotmp	:= sp_ingresosabado;
       					        else
		  					    	sp_salidatmp	:= sp_ingresodiahabil;
    								sp_ingresotmp	:= sp_ingresodiahabil;
       					        end if;
		   					end if;	
       					    
       					    case 
	       					   when sp_tipodiaTmp = 0 then
	       					        -- El dia siguiente es domingo o festivo, todas las horas son extras  							
       							    select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       							    into sp_hetmp
       								from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       								salhe := salhe + sp_hetmp;
       							    raise notice '2. Turno Noche % % %',sp_hetmp00,sp_hetmp, salhe;
	       					   when (sp_tipodiaTmp = 6)  or ( sp_tipodiaTmp >= 1 and  sp_tipodiaTmp <= 5  ) then
									select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
									into sp_hetmp00
       								from (select CAST(sp_ingresotmp AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       							
       							    select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       							    into sp_hetmp
       								from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       							
       							
       								raise notice '3 Tipo Dia % % %',sp_hetmp00,sp_hetmp, salhe;
       							    if ( sp_hetmp  <=  sp_hetmp00 ) then
       							    -- la salida esta entre las 00 y Ingreso del sabado/habil, Acumulo las horas del dia anterior
       							        salhe := salhe + sp_hetmp;
       							    else
       							    -- paso al horario normal del sabado
       							       salhe := salhe + sp_hetmp00;
       							       select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       							       into sp_hetmp00
       								   from (select CAST(sp_salidatmp AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       								  
       								   select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       								   into sp_hetmp01
       								   from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       								  
       								  raise notice '4 Turno Noche % % %',sp_hetmp00,sp_hetmp,salhe;
       							
       								   if ( sp_hetmp00 <= sp_hetmp01) then
       								   --   Extraigo las horas y las acumulo
       								        raise notice '6 Turno Noche % % ',salhe,( sp_hetmp01 - sp_hetmp00 );
       								   		salhe := salhe + ( sp_hetmp01 - sp_hetmp00 );
       								   else
       								   -- Salio antes o en el horario normal de la jirnada
       								   raise notice '5 Turno Noche % % ',salhe,( sp_hetmp01 - sp_hetmp00 );
       								      salhe := salhe + 0;
       								   end if;
       							    end if;
       							end case;
	       				        raise notice 'Calculo Final  % % %',sp_hetmp, sp_hetmp00, salhe;
       					--else
       					    -- Se queda hasta entes de las 24:00 hrs
       					--	select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       					--	from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormaldf AS TIME) as Tiempo) T;
       					--	salhe := sp_hetmp;
       					--	raise notice 'Else TurnoNoche % % % %',sp_finturno,sp_salidanormaldf,sp_hetmp,salhe;
       					--end if;
       			    
       			end if;	
       		
			    raise notice 'Domingo % %',salhe,salhe;
			end if;
		
---------- Sabado -------------------------------------------------------------------------------
			if ( sp_tipodia = 6 ) then 
				-- Validacion si entra anticipado
				if (  var_record1.ingresoanticipado ) then 
					select c.nombrehoraminuto, c.aplicaturnofund  into sp_horaminuto, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutoingant;
					select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_horanticipadasabado AS TIME) - CAST(sp_horaminuto AS TIME) as Tiempo) T;
       				salhei :=  salhei + sp_hetmp;	
		    	end if;
		    
		    	-- Determino horario de salida
		    	sp_flagbool := true;
		       case
     				 when  var_record1.turno13 		then sp_finturno := sp_turno13;
     				 when  var_record1.turno16 		then sp_finturno := sp_turno16;
     				 when  var_record1.turno18 		then sp_finturno := sp_turno18;
     				 when  var_record1.turno20 		then sp_finturno := sp_turno20;
     				 when  var_record1.turno2130 	then sp_finturno := sp_turno2130;
     				 when  var_record1.turnootro 	then select c.nombrehoraminuto, c.aplicaturnofund  into sp_finturno, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutootro;
     				else sp_flagbool = false;
     			end case;
     		
     			-- Calculo del exceso entre la hora normal de salida y el turno q cumplido 
			
				if ( sp_flagbool ) then
					
					if ( var_record1.turnootro ) then
							select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormalsabado AS TIME) as Tiempo) T;
       					     raise notice 'turnoOtro SalidNornalSabado: % FinTurno: %',sp_finturno,sp_ingresosabado;
       			    else
       			    		select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormalsabado AS TIME) as Tiempo) T;
       					    raise notice ' SalidNornalSabado: % FinTurno: %',sp_finturno,sp_salidanormalsabado;
       				end if;			
       				salhe :=  sp_hetmp + salhe;
				end if;  
			
				if ( var_record1.turnonoche ) then				
					    select c.nombrehoraminuto  into sp_finturno from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutonoche;
						select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
						into sp_hetmp
       					from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormalsabado AS TIME) as Tiempo) T;
       					raise notice 'TurnoNoche % % % %',sp_finturno,sp_salidanormalsabado,sp_hetmp,salhe;
       					if ( sp_hetmp < 0) then
       					-- Salida el proximo dia
       						select c.nombrehoraminuto  into sp_finturno from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutonoche;
							select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
							into sp_hetmp
       						from (select CAST('24:00' AS TIME) - CAST(sp_salidanormalsabado AS TIME) as Tiempo) T;
       						salhe := sp_hetmp;
       						raise notice '1 Calculo TurnoNoche % % ',sp_hetmp, salhe;
       					
							select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
							into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       						salhe := salhe + sp_hetmp;
       					
       						raise notice '1 Calculo TurnoNoche % % ',sp_hetmp,salhe;
       					else
       						select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormalsabado AS TIME) as Tiempo) T;
       						salhe := sp_hetmp;
       						raise notice 'TurnoNoche % % % %',sp_finturno,sp_salidanormalsabado,sp_hetmp,salhe;
       					end if;
       			end if;	
     			raise notice 'Sabado % %',salhe,salhe;
			end if;
		
----------- Dia Habil ---------------------------------------------------------------------------------------------------
			if ( sp_tipodia >= 1 and  sp_tipodia <= 5) then 
			    raise notice  ' Tipo de Dia Habil % %',sp_tipodia, sp_finturno;
				-- Validacion si entra anticipado
				if (  var_record1.ingresoanticipado ) then 
					select c.nombrehoraminuto, c.aplicaturnofund  into sp_horaminuto, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutoingant;
					select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_horanticipadadh AS TIME) - CAST(sp_horaminuto AS TIME) as Tiempo) T;
       				salhei :=  salhei + sp_hetmp;
		    	end if;
		    
		    		    	-- Determino horario de salida
		    	sp_flagbool := true;
		       case
     				 when  var_record1.turno13 		then sp_finturno := sp_turno13;
     				 when  var_record1.turno16 		then sp_finturno := sp_turno16;
     				 when  var_record1.turno18 		then sp_finturno := sp_turno18;
     				 when  var_record1.turno20 		then sp_finturno := sp_turno20;
     				 when  var_record1.turno2130 	then sp_finturno := sp_turno2130;
     				 when  var_record1.turnootro 	then select c.nombrehoraminuto, c.aplicaturnofund  into sp_finturno, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutootro;
     				else sp_flagbool = false;
     			end case;
     		    raise notice  ' Tipo de Dia Habil % %',sp_tipodia, sp_finturno;
     		     -- Calculo del exceso entre la hora normal de salida y el turno cumplido
				if ( sp_flagbool ) then
					
					if ( var_record1.turnootro ) then
							select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
							into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormaldh AS TIME) as Tiempo) T;
       					    raise notice  ' --> Otro Dia FinTurno:  %  SalodaNormal: %',sp_finturno, sp_salidanormaldh;
       			    else
       			    		select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       			    		into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormaldh AS TIME) as Tiempo) T;
       					    raise notice  ' --> Nomal Dia FinTurno:  %  SalodaNormal: %',sp_finturno, sp_salidanormaldh;
       				end if;	
       			    if ( sp_hetmp < 0 ) then
       			       sp_hetmp := 0;
       			    end if;
       			    
       				salhe :=  sp_hetmp + salhe;
       			    raise notice  ' 1 Dia Habil % %',sp_hetmp, salhe;
       			
				end if; 
			
				if ( var_record1.turnonoche ) then
						
       					select c.nombrehoraminuto  into sp_finturno from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutonoche;
						select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
						into sp_hetmp
       					from (select CAST(sp_turno2400 AS TIME) - CAST(sp_salidanormaldh AS TIME) as Tiempo) T;
       					salhe := sp_hetmp;
       						
       			    -- Reviso siguiente dia( puede ser Festivo, Sabado o Dia habil
       					SELECT cast((CAST(var_record1.fechaturno  AS DATE) + CAST('1 days' AS INTERVAL)) as timestamp) into sp_DiaSig;
       					select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = sp_DiaSig;
		   				if ( sp_cont >= 1) then 
		       			-- Los festivos los hago pasar por Domingo
		  					sp_tipodiaTmp   := 0;
		  					sp_salidatmp	:= sp_salidanormaldf;
    						sp_ingresotmp	:= sp_ingresodf;
		  				else
		  					select extract (DOW from  ( SELECT CAST(var_record1.fechaturno  AS DATE) + CAST('1 days' AS INTERVAL)) ) 
       					    into sp_tipodiaTmp;
       					    if ( sp_tipodiaTmp = 6) then
		  					    sp_salidatmp	:= sp_salidanormalsabado;
    							sp_ingresotmp	:= sp_ingresosabado;
       					    else
		  					    sp_salidatmp	:= sp_ingresodiahabil;
    							sp_ingresotmp	:= sp_ingresodiahabil;
       					     end if;
		   				end if;	
		   				
       					raise notice '0 Turno Noche TD y FT % %  Datos Inicio: % %',sp_tipodiaTmp, sp_finturno, sp_hetmp, salhe;
       					    
       					case 
	       					   when sp_tipodiaTmp = 0 then
	       					        -- Caso desde un dia normal a un festivo
	       					        select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       							    into sp_hetmp
       								from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       							    salhe := salhe + sp_hetmp;		
       							    raise notice '3 Tipo Dia % % %',sp_finturno,sp_hetmp,salhe;
	       					    
	       					   when sp_tipodiaTmp = 6 then
									select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
									into sp_hetmp00
       								from (select CAST(sp_ingresosabado AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       							
       							    select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       							    into sp_hetmp
       								from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       							
       							
       								raise notice '1 Turno Noche % %',sp_hetmp, salhe;
       							    if ( sp_hetmp  <=  sp_hetmp00 ) then
       							    -- la salida esta entre las 00 y Ingreso del sabado, Acumulo las horas del dia anterior
       							        salhe := salhe + sp_hetmp;
       							    else
       							    -- paso al horario normal del sabado
       							       raise notice '----1 Turno Noche % % ',sp_hetmp00, salhe;
       							       salhe := salhe + sp_hetmp00;
       							       raise notice '----1 Turno Noche % ',salhe;
       							       select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       							       into sp_hetmp00
       								   from (select CAST(sp_salidanormalsabado AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       								  
       								   select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       								   into sp_hetmp01
       								   from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       								  
       								  --raise notice '2 Tipo Dia % % %',sp_hetmp00,sp_hetmp,salhe;
       							
       								   if ( sp_hetmp00 <= sp_hetmp01) then
       								   --   Extraigo las horas y las acumulo
       								        raise notice '----2 Tipo Dia % % ',( sp_hetmp01 - sp_hetmp00 ), salhe;
       								   		salhe := salhe + ( sp_hetmp01 - sp_hetmp00 );
       								   else
       								   -- Salio antes o en el horario normal de la jirnada
       								      raise notice '3 Tipo Dia % % ',0, salhe;
       								      salhe := salhe + 0;
       								   end if;
       							    end if;
       							
	       				            raise notice 'Calculo Final  % % %',sp_hetmp, sp_hetmp00, salhe;
	       					   when  sp_tipodiaTmp >= 1 and  sp_tipodiaTmp <= 5 then
	       					        -- Caso: Siguiente dia es habil
	       					   		select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
									into sp_hetmp00
       								from (select CAST(sp_ingresodiahabil AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       							
       							    select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       							    into sp_hetmp
       								from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       							
       							
       								raise notice '1 Turno Noche  % % %',sp_tipodiaTmp, sp_hetmp, salhe;
       							    if ( sp_hetmp  <=  sp_hetmp00 ) then
       							    -- la salida esta entre las 00 y Ingreso del sabado, Acumulo las horas del dia anterior
       							        salhe := salhe + sp_hetmp;
       							    else
       							    -- paso al horario normal del sabado
       							       salhe := salhe + sp_hetmp00;
       							       select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       							       into sp_hetmp00
       								   from (select CAST(sp_salidanormaldh AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       								  
       								   select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) 
       								   into sp_hetmp01
       								   from (select CAST(sp_finturno AS TIME) - CAST('00:00' AS TIME) as Tiempo) T;
       								  
       								  raise notice '2 Turno Noche desde las 00:00 a la entrada: %  -> %',sp_hetmp,salhe;
       							
       								   if ( sp_hetmp00 <= sp_hetmp01) then
       								   --   Extraigo las horas y las acumulo
       								        raise notice '3 Turno Noche % % ',( sp_hetmp01 - sp_hetmp00 ), salhe;
       								   		salhe := salhe + ( sp_hetmp01 - sp_hetmp00 );
       								   else
       								   -- Salio antes o en el horario normal de la jirnada
       								      salhe := salhe + 0;
       								   end if;
       							    end if;
       							
	       				            raise notice 'Calculo Final  % %',sp_hetmp, salhe;
	       					   
	       					    else
	       					    -- EXcepcion, sino el dia siguiente es error, conserva las misnas he
									salhe := salhe + 0;
	       					    
	       				end case;
       					
       					
       					raise notice 'TurnoNoche Calculo Final % % % ',sp_finturno,sp_salidanormaldh,salhe;
       					--else
       					--    -- Se queda hasta entes de las 24:00 hrs
       					--	select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       					--	from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormaldh AS TIME) as Tiempo) T;
       					--	salhe := sp_hetmp;
       					--	raise notice 'TurnoNoche % % % %',sp_finturno,sp_salidanormaldh,sp_hetmp,salhe;
       					--end if;
       			    
       			end if;	
       			
			end if;		
	END LOOP; 
	return next;
	return;
   
END
$$;


ALTER FUNCTION traking.calculohorashextras(inoperador bigint, infechadesde character varying, infechahasta character varying, inarea integer) OWNER TO postgres;

--
-- TOC entry 2096 (class 1255 OID 16597)
-- Name: cambiapasswordusuariosneptuno(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.cambiapasswordusuariosneptuno() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare

       sp_password		varchar;
	   rec_usu 			record;
	 
begin
		
	FOR rec_usu IN (  
	          select idusuario,
	                 nombre,
                     email,
	                 iniciales||'_' as iniciales
	            from mct_usuario mu 
	           where idcliente = 77
	             and estado = 1
	             and iniciales is not null
				  )
	   loop
		   
		  SELECT rec_usu.iniciales||array_to_string(ARRAY(SELECT chr((48 + round(random() * 9)) :: integer) 
		    INTO sp_password 				
		    FROM generate_series(1,5)), '');	
		  
		  raise notice '%', rec_usu.email || ' - ' || rec_usu.nombre||'-'||sp_password; 
          update mct_usuario 
             set password = sp_password 
	   	   where idusuario = rec_usu.idusuario;  
		   
	end loop;
     
  return 'hecho';
END;
$$;


ALTER FUNCTION traking.cambiapasswordusuariosneptuno() OWNER TO postgres;

--
-- TOC entry 1438 (class 1255 OID 16598)
-- Name: conshorasextras(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.conshorasextras(infechadesde character varying, infechahasta character varying, inarea bigint) RETURNS TABLE(salidoperador bigint, salidturno bigint, salnombreoperador character varying, saltipoturno character varying, salfechaturno character varying, salhe numeric, salhei numeric, salobservacion character varying, salfundicion integer, salestatus integer)
    LANGUAGE plpgsql
    AS $$
declare 

    var_record1 			record;
    var_record2 			record;
	sp_desctmp				varchar(500);
    sp_horaminuto			varchar;
   	sp_aplicaturnofund		boolean;

	sp_finturno				varchar := '13:30';
	sp_ingresodf			varchar := '08:30';
	sp_ingresosabado		varchar := '08:30';
	sp_ingresodiahabil		varchar := '08:30';
	sp_finturnosabado		varchar := '12:30';
	sp_finturnohabil		varchar := '18:30';

    sp_turno13 				varchar := '13:00';
    sp_turno16 				varchar := '16:00';
    sp_turno18				varchar := '18:00';
    sp_turno20 				varchar := '20:00';
   	sp_turno2130 			varchar := '21:30';
     				
	sp_tipodia				integer;
	sp_cont					integer;
	sp_he					numeric := 0.0;
	he1						numeric := 0.0;
	he2						numeric := 0.0;
	sp_hetmp				numeric := 0.0;
	sp_flagbool				boolean;
	queryHE					varchar;

begin
	
	sp_he 		:= 0.0;
	sp_hetmp 	:= 0.0;
	salhe		:= 0.0;
	salhei		:= 0.0;
	salobservacion := '';
	if ( inarea = 0 ) then
	   queryHE := concat('select * from  traking.mct_operador a left join  traking.mct_operadorturnofund b on ( a.idoperador = b.idoperador )
			where (b.fechaturno between to_date(',E'''',infechadesde,E'''',E',''','yyyy-mm-dd',E''') and  to_date(',E'''',infechahasta,E'''',E',''','yyyy-mm-dd',E'''))');
	else
	  queryHE := concat('select * from  traking.mct_operador a left join  traking.mct_operadorturnomaestranza b on ( a.idoperador = b.idoperador )
			where (b.fechaturno between to_date(',E'''',infechadesde,E'''',E',''','yyyy-mm-dd',E''') and  to_date(',E'''',infechahasta,E'''',E',''','yyyy-mm-dd',E'''))');	
	end if;

	 FOR var_record1 in execute queryHE
	 loop

			salhe			:= 0.0;
			salhei			:= 0.0;
		  	he1				:= 0.0;
		  	he2				:= 0.0;
		  	salobservacion 	:= '';
		  	saltipoturno 	:= '';
		   --0: Domingo
		   --6: Sabado
		   --1-5: Habil
		  		  	salidoperador 			:= var_record1.idoperador;
		  -- raise notice ' ----- > % % %', salidoperador, to_char(var_record1.fechaturno,'yyyy-mm-dd'), inarea;
		  		  

		  	for var_record2 in 
		         select * from traking.calculohorashextras(salidoperador,to_char(var_record1.fechaturno,'yyyy-mm-dd'), to_char(var_record1.fechaturno,'yyyy-mm-dd'),cast(inarea as integer))
		    loop
		 		raise notice ' % ----- > % %', salidoperador,var_record2.salhe, var_record2.salhei;
		 		he1 := var_record2.salhei;
		 		he2 := var_record2.salhe;
		 	end loop;
		 
		   select extract (DOW from  var_record1.fechaturno ) into sp_tipodia;
		   select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = var_record1.fechaturno;
		   if ( sp_cont >= 1) then 
		        -- Los festivos los hago pasar por Domingo
		  		sp_tipodia := 0;
		   end if;

			salnombreoperador 		:= var_record1.nombreoperador;
			salfechaturno 			:= var_record1.fechaturno;
			if ( var_record1.horaextraentrada <> he1 OR var_record1. horaextrasalida <> he2 ) then
				  salestatus = 1;
			      salobservacion := concat('**  ',cast(var_record1.horaextraentrada as numeric(5,2)),' ',var_record1. horaextrasalida,'  TipoDia: ',sp_tipodia,' ',to_char(var_record1.fechaturno,'dd-mm-yyyy'));
			else
				salestatus = 0;
				salobservacion := concat(' ',var_record1.horaextraentrada,' ',var_record1. horaextrasalida,'  TipoDia: ',sp_tipodia,' ',to_char(var_record1.fechaturno,'dd-mm-yyyy'));
			end if;

			if (  var_record1.ingresoanticipado ) then 
					saltipoturno := 'EA';
					select c.nombrehoraminuto  into sp_horaminuto from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutoingant;
       		    	salobservacion := concat(salobservacion,' Entrada ',sp_horaminuto);	
		    end if;
		    
		    	-- Determino horario de salida
		   sp_flagbool:= true;
		    case
	     				 when  var_record1.turno13 		then sp_finturno := sp_turno13;
	     				 when  var_record1.turno16 		then sp_finturno := sp_turno16;
	     				 when  var_record1.turno18 		then sp_finturno := sp_turno18;
	     				 when  var_record1.turno20 		then sp_finturno := sp_turno20;
	     				 when  var_record1.turno2130 	then sp_finturno := sp_turno2130;
	     				 when  var_record1.turnootro 	then select c.nombrehoraminuto into sp_horaminuto from traking.mct_horaminuto c 
     				                                     where c.idhoraminuto = var_record1.idhoraminutootro;
     				else sp_flagbool = false;
     			end case;
     			-- Valicacion que tenga un turno asignado
			if ( sp_flagbool ) then
					saltipoturno := 'TN';
       		    	salobservacion := concat(salobservacion,' Salida ',sp_finturno);	
			end if;   
		
		if ( var_record1.turnonoche ) then
				saltipoturno := 'QD';
				select c.nombrehoraminuto  into sp_finturno from traking.mct_horaminuto c 
			                               where c.idhoraminuto = var_record1.idhoraminutonoche;
				salobservacion := concat(salobservacion,' Salida ',sp_horaminuto);	
		
		end if;
		salhe  := he2;
	    salhei := he1;
		return next;
		
	END LOOP; 
return;
   
END
$$;


ALTER FUNCTION traking.conshorasextras(infechadesde character varying, infechahasta character varying, inarea bigint) OWNER TO postgres;

--
-- TOC entry 1540 (class 1255 OID 16600)
-- Name: copiafechaoperadorturno(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.copiafechaoperadorturno(fechacopia character varying, fechato character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
    sp_copiatiene		integer;
    sp_copiatotiene		integer;
    sp_salida			bigint;
begin
	
		
	    sp_copiatiene	:= 0;
	   	sp_salida		:= 3;
	   
        if ( select distinct 1
               from mct_operadorturno mo 
              where to_char(fechaturno, 'yyyy-mm-dd') = fechacopia) then
              
              sp_copiatiene = 1;
              sp_salida		= 1;
             
        end if;
     
       	sp_copiatotiene	:= 0;
	   
        if ( select distinct 1
               from mct_operadorturno mo 
              where to_char(fechaturno, 'yyyy-mm-dd') = fechato) then
              
              sp_copiatotiene = 1;
              sp_salida		  = 2;
             
        end if;
       
        if ( sp_copiatiene = 1 and sp_copiatotiene = 0) then
         
            --return 'Puede copiar las fechas';
			INSERT INTO traking.mct_operadorturno
			(idoperadorturno, idoperador, fechaturno, turno13, turno16, turno18, turno20, turnoexcepcional, turnonoche, idhoraminuto, nombrehoraminuto, turnootro, idhoraminutootro, nombrehoraminutootro, ausente, idmotivoausencia, observacion, usuariocreacion, fechacreacion, usuariomodificacion, fechamodificacion)
			select nextval('mct_operadorturno_seq'),idoperador, to_date(fechato,'yyyy-mm-dd'), turno13, turno16, turno18, turno20, turnoexcepcional, turnonoche, idhoraminuto, nombrehoraminuto, turnootro, idhoraminutootro, nombrehoraminutootro, ausente, idmotivoausencia, observacion, usuariocreacion, fechacreacion, usuariomodificacion, fechamodificacion
