ALTER FUNCTION traking.copiafechaoperadorturno(fechacopia character varying, fechato character varying) OWNER TO postgres;

--
-- TOC entry 1823 (class 1255 OID 16601)
-- Name: copiafechaoperadorturnofund(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.copiafechaoperadorturnofund(fechacopia character varying, fechato character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
    sp_copiatiene		integer;
    sp_copiatotiene		integer;
    sp_salida			bigint;
	rec_copia			RECORD;


    sp_id				bigint;
	he1 				numeric	:= 0;
	he2					numeric	:= 0;

begin
	
		
	    sp_copiatiene	:= 0;
	   	sp_salida		:= 3;
	   
        if ( select distinct 1
               from mct_operadorturnofund mo 
              where to_char(fechaturno, 'yyyy-mm-dd') = fechacopia
                and esturnofundicion1  is true) then
              
              sp_copiatiene = 1;
              sp_salida		= 1;
             
        end if;
     
       	sp_copiatotiene	:= 0;
	   
        if ( select distinct 1
               from mct_operadorturnofund mo 
              where to_char(fechaturno, 'yyyy-mm-dd') = fechato
                and esturnofundicion1 is true) then
              
              sp_copiatotiene = 1;
              sp_salida		  = 2;
             
        end if;
       
        if ( sp_copiatiene = 1 and sp_copiatotiene = 0) then
         
        
         		 FOR rec_copia IN ( 
        		 
						SELECT idoperadorturnofund, 
						       idoperador, 
						       turno13, 
						       turno16, 
						       turno18, 
						       turno20, 
						       turno2130, 
						       turnonoche, 
						       idhoraminutonoche, 
						       nombrehoraminutonoche, 
						       motivoquedada, 
						       turnootro, 
						       idhoraminutootro, 
						       nombrehoraminutootro, 
						       ausente, 
						       idmotivoausencia, 
						       observacion, 
						       usuariocreacion, 
						       fechacreacion, 
						       usuariomodificacion, 
						       fechamodificacion, 
						       idhoraminutofundext, 
						       nombrehoraminutofundext,
						       motivoausencia, 
						       motivootro, 
						       esturnofundicion1, 
						       esturnofundicion2, 
						       ingresoanticipado, 
						       idhoraminutoingant, 
						       motivoingresoanticipado, 
						       horaextraentrada, 
						       horaextrasalida
						  FROM traking.mct_operadorturnofund
				         where to_char(fechaturno, 'yyyy-mm-dd') = fechacopia
				           and esturnofundicion1 is true
				      union
				       	select cast(0 as bigint) ,
				       	       a.idoperador ,
						       false, 
						       false, 
						       false, 
						       false, 
						       false, 
						       false, 
						       0, 
						       '', 
						       '', 
						       false, 
						       0, 
						       '', 
						       false, 
						       0, 
						       '', 
						       'admin', 
						       now(), 
						       'admin', 
						       now(), 
						       0, 
						       '',
						       '', 
						       '', 
						       true, 
						       false, 
						       false, 
						       0, 
						       '', 
						       0, 
						       0 
				          from traking.mct_operador a
				         where a.estado = 1 
						   and a.aplicacontrolturnofund is true 
						   and not exists (select 'x' 
						                    from mct_operadorturnofund b 
						                   where a.idoperador = b.idoperador 
						                     and to_char(b.fechaturno, 'yyyy-mm-dd') = fechacopia
						                     and b.esturnofundicion1 is true)
			
        		 )
        		 loop 

	        		 sp_id	:= nextval('traking.mct_operadorturnofund_seq');
	 
		        	 INSERT INTO traking.mct_operadorturnofund
	                            (idoperadorturnofund, 
	                             idoperador, 
	                             fechaturno, 
	                             turno13, 
	                             turno16, 
	                             turno18, 
	                             turno20, 
	                             turno2130, 
	                             turnonoche, 
	                             idhoraminutonoche, 
	                             nombrehoraminutonoche, 
	                             motivoquedada, 
	                             turnootro, 
	                             idhoraminutootro, 
	                             nombrehoraminutootro, 
	                             ausente, 
	                             idmotivoausencia, 
	                             observacion, 
	                             usuariocreacion, 
	                             fechacreacion, 
	                             usuariomodificacion, 
	                             fechamodificacion, 
	                             idhoraminutofundext, 
	                             nombrehoraminutofundext, 
	                             motivoausencia, 
	                             motivootro, 
	                             esturnofundicion1, 
	                             esturnofundicion2, 
	                             ingresoanticipado, 
	                             idhoraminutoingant, 
	                             motivoingresoanticipado, 
	                             horaextraentrada, 
	                             horaextrasalida	                             
	                             )
	                      VALUES(
								 sp_id, 
	                             rec_copia.idoperador, 
	                             to_date(fechato,'yyyy-mm-dd'), 
	                             rec_copia.turno13, 
	                             rec_copia.turno16, 
	                             rec_copia.turno18, 
	                             rec_copia.turno20, 
	                             rec_copia.turno2130, 
	                             rec_copia.turnonoche, 
	                             rec_copia.idhoraminutonoche, 
	                             rec_copia.nombrehoraminutonoche, 
	                             rec_copia.motivoquedada, 
	                             rec_copia.turnootro, 
	                             rec_copia.idhoraminutootro, 
	                             rec_copia.nombrehoraminutootro, 
	                             rec_copia.ausente, 
	                             rec_copia.idmotivoausencia, 
	                             rec_copia.observacion, 
	                             rec_copia.usuariocreacion, 
	                             rec_copia.fechacreacion, 
	                             rec_copia.usuariomodificacion, 
	                             rec_copia.fechamodificacion, 
	                             rec_copia.idhoraminutofundext, 
	                             rec_copia.nombrehoraminutofundext, 
	                             rec_copia.motivoausencia, 
	                             rec_copia.motivootro, 
	                             rec_copia.esturnofundicion1, 
	                             rec_copia.esturnofundicion2, 
	                             rec_copia.ingresoanticipado, 
	                             rec_copia.idhoraminutoingant, 
	                             rec_copia.motivoingresoanticipado,
	                             he2,
					             he1
	                            );

					    select coalesce (salhe, 0), 
					           coalesce (salhei, 0) 
					      into he1,
					           he2 
					      from traking.calculohorashextras(rec_copia.idoperador, fechato, fechato, 0);     
					     
					     
					    update traking.mct_operadorturnofund
					       set horaextraentrada = he2,
					           horaextrasalida = he1
				         where idoperadorturnofund = sp_id;
        
        		 end loop;       
        

            --return 'Puede copiar las fechas';
--			INSERT INTO traking.mct_operadorturnofund
--			(idoperadorturnofund, idoperador, fechaturno, turno13, turno16, turno18, turno20, turno2130, turnonoche, idhoraminutonoche, motivoquedada , nombrehoraminutonoche , turnootro, idhoraminutootro, nombrehoraminutootro, ausente, idmotivoausencia, observacion, usuariocreacion, fechacreacion, usuariomodificacion, fechamodificacion, esturnofundicion1)
--			select nextval('mct_operadorturnofund_seq'),idoperador, to_date(fechato,'yyyy-mm-dd'), turno13, turno16, turno18, turno20, turno2130, turnonoche, idhoraminutonoche , motivoquedada, nombrehoraminutonoche, turnootro, idhoraminutootro, nombrehoraminutootro, ausente, idmotivoausencia, observacion, usuariocreacion, fechacreacion, usuariomodificacion, fechamodificacion, true
--			  from mct_operadorturnofund 
--			 where to_char(fechaturno, 'yyyy-mm-dd') = fechacopia
--			   and esturnofundicion1 is true; 

			sp_salida		:= 0;
        
        end if;
       
        return sp_salida;
       

END;
$$;


