    sp_copiatotiene		integer;
    sp_salida			bigint;
	rec_copia			RECORD;


    sp_id				bigint;
	he1 				numeric	:= 0;
	he2					numeric	:= 0;

begin
	
		
	    sp_copiatiene	:= 0;
