                and esturnofundicion1 is true) then
              
              sp_copiatotiene = 1;
              sp_salida		  = 2;
             
        end if;
       
        if ( sp_copiatiene = 1 and sp_copiatotiene = 0) then
         
        
         		 FOR rec_copia IN ( 
        		 
						SELECT idoperadorturnofund, 
						       idoperador, 
						       turno13, 
						       turno16, 
						       turno18, 
						       turno20, 
						       turno2130, 
						       turnonoche, 
						       idhoraminutonoche, 
