						  FROM traking.mct_operadorturnofund
				         where to_char(fechaturno, 'yyyy-mm-dd') = fechacopia
				           and esturnofundicion1 is true
			
        		 )
        		 loop 

	        		 sp_id	:= nextval('traking.mct_operadorturnofund_seq');
	 
		        	 INSERT INTO traking.mct_operadorturnofund
	                            (idoperadorturnofund, 
	                             idoperador, 
	                             fechaturno, 
	                             turno13, 
	                             turno16, 
	                             turno18, 
	                             turno20, 
	                             turno2130, 
	                             turnonoche, 
	                             idhoraminutonoche, 
	                             nombrehoraminutonoche, 
	                             motivoquedada, 
	                             turnootro, 
	                             idhoraminutootro, 
	                             nombrehoraminutootro, 
	                             ausente, 
	                             idmotivoausencia, 
	                             observacion, 
	                             usuariocreacion, 
	                             fechacreacion, 
	                             usuariomodificacion, 
	                             fechamodificacion, 
	                             idhoraminutofundext, 
	                             nombrehoraminutofundext, 
	                             motivoausencia, 
	                             motivootro, 
	                             esturnofundicion1, 
	                             esturnofundicion2, 
