				       union
				       	select cast(0 as bigint) ,
				       	       a.idoperador ,
						       false, 
						       false, 
						       false, 
						       false, 
						       false, 
						       false, 
						       0, 
						       '', 
						       '', 
						       false, 
						       0, 
