CREATE FUNCTION traking.delaction(iddel bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

   -- delete from traking.mct_accion where mct_accion.idaccion = iddel;
   
   update traking.mct_accion set estado = 99 where mct_accion.idaccion = iddel;
  
END;
$$;


ALTER FUNCTION traking.delaction(iddel bigint) OWNER TO postgres;

--
-- TOC entry 1403 (class 1255 OID 16610)
-- Name: delactividaddiariaimagen(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.delactividaddiariaimagen(iddel bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
	sp_retorno		varchar;
    sp_existebd		varchar;
    sp_noexistebd	varchar;
    sp_exito        varchar;

 	an_integer 		integer = 1;
 	rt_status		varchar(200) = '';
 
    sp_idppto		bigint;
    sp_inc			bigint;
    sp_cantidad		bigint;

BEGIN

      delete 
        from traking.mct_actividaddiariaimagen   
       where mct_actividaddiariaimagen.idactividaddiariaimagen = iddel;
	 
	 
    return concat('0:exito');
   
    exception 
	   when others then 
	      select descripcion  into rt_status from grupoddi.ddi_errorpostgres where codigo = sqlstate;
	      RETURN CONCAT('sqlstate:',sqlstate,'-', rt_status);
      
      
END;
$$;


