--

CREATE FUNCTION traking.delaleacion(idaleacioni bigint, usuariomodificacioni character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    update traking.mct_aleacion
       set fechamodificacion = now(),
           usuariomodificacion = usuariomodificacioni,
		   estado = 0
	 where idaleacion = idaleacioni;
    
END
$$;


