--
-- TOC entry 1833 (class 1255 OID 16628)
-- Name: delchecklistinftecreinicia(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.delchecklistinftecreinicia(iddel bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    	delete from traking.mct_checklistinftec where mct_checklistinftec.idordentrabajo = iddel;
   
   		INSERT INTO traking.mct_checklistinftec
				(idchecklistinftec, 
				idordentrabajo, 
				nombreparte, 
				cantidad, 
				material, 
				criterio, 
				reparacion, 
				plano, 
				usuariocreacion, 
				fechacreacion, 
				indicefila,
				codigoqr,
				fecharequerida,
				tipotrabajostd 
				)
		 select nextval('mct_checklistinftec_seq'),
				 a.idordentrabajo, 
				 a.nombreparte, 
				 a.cantidad, 
				 a.material, 
				 a.criterio, 
				 a.reparacion, 
				 a.plano, 
				 a.usuariocreacion , 
				 a.fechacreacion, 
				 a.indicefila,
				 a.codigoqr,
				 a.fecharequerida,
				 a.tipotrabajostd
		   from traking.mct_checklistinftecinicial a
		  where a.idordentrabajo = iddel;
		   
    
END;
$$;


ALTER FUNCTION traking.delchecklistinftecreinicia(iddel bigint) OWNER TO postgres;

--
-- TOC entry 2151 (class 1255 OID 16629)
-- Name: delchecklistinftectotal(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.delchecklistinftectotal(iddel bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
  sp_validado   boolean;
begin
	
	select coalesce (checklistvalido , false)
	  into sp_validado
	  from traking.mct_ordentrabajo 
	 where idordentrabajo = iddel;

	if ( sp_validado != true) then
	
	   delete from traking.mct_checklistinftec where idordentrabajo = iddel and criterio != 'FAb_FuPl';
	  
	   delete from traking.mct_checklistinftecinicial where idordentrabajo = iddel and criterio != 'FAb_FuPl';
	  
	   return 0;
	  
	else
	
	   return 1;
	
	end if;

END;
$$;


ALTER FUNCTION traking.delchecklistinftectotal(iddel bigint) OWNER TO postgres;

