--
-- TOC entry 1241 (class 1255 OID 16639)
-- Name: deldefectocausaaccion(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.deldefectocausaaccion(iddel bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
	sp_retorno		varchar;
    sp_existebd		varchar;
    sp_noexistebd	varchar;
    sp_exito        varchar;

 	an_integer 		integer = 1;
 	rt_status		varchar(200) = '';
 
    sp_idppto		bigint;
    sp_inc			bigint;
    sp_cantidad		bigint;

BEGIN

      delete 
        from traking.mct_defectocausaaccion   
       where mct_defectocausaaccion.iddefectocausaaccion = iddel;
	 
	 
    return concat('0:exito');
   
    exception 
	   when others then 
	      select descripcion  into rt_status from grupoddi.ddi_errorpostgres where codigo = sqlstate;
	      RETURN CONCAT('sqlstate:',sqlstate,'-', rt_status);
      
      
END;
$$;


ALTER FUNCTION traking.deldefectocausaaccion(iddel bigint) OWNER TO postgres;

