--
-- TOC entry 2293 (class 1255 OID 16712)
-- Name: delroadmaptemp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.delroadmaptemp(iddel bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

     sp_idot        integer;
     sp_idcomp      integer;
    
BEGIN

	--select idordentrabajo,
	--       idcomponente
	--  into sp_idot,
	--       sp_idcomp
	--  from traking.mct_hojarutatemp 
	-- where idhojarutatemp = iddel;
	

	
	-- Primero elimina los idordentrabajoparte de la ot
	delete from mct_ordentrabajoparte 
	 where idordentrabajoparte in ( select idordentrabajoparte
	                                  from mct_hojaruta
	                                 where idhojarutatemp = iddel) ;

   -- Luego borra las hojas de ruta asociadas a los idordentrabajoparte de la ot
	delete from mct_hojaruta 
	 where idhojarutatemp = iddel;
	

    delete from traking.mct_hojarutatemp where mct_hojarutatemp.idhojarutatemp = iddel;
   
    delete from traking.mct_detallehojarutatemp where mct_detallehojarutatemp.idhojarutatemp  = iddel;
   
    delete from traking.mct_hojarutaactividadtemp where mct_hojarutaactividadtemp.idhojarutatemp = iddel;
   
END;
$$;


ALTER FUNCTION traking.delroadmaptemp(iddel bigint) OWNER TO postgres;

--
-- TOC entry 2263 (class 1255 OID 16713)
-- Name: delroadmaptempmanual(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.delroadmaptempmanual(iddel bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

     sp_idot        integer;
     sp_idcomp      integer;
    
     sp_idotp       integer;
     sp_codhr       varchar;
     sp_idhr        integer;
     sp_idhrt		integer;
     sp_cant		integer;
    
BEGIN

	sp_idotp	:= 0;
    sp_codhr	:= '';
    sp_idhr		:= 0;
    sp_idhrt	:= 0;
    sp_cant		:= 0;
    
	select idordentrabajoparte,
	       codhojaruta
	  into sp_idotp,
	       sp_codhr
	  from mct_hojaruta mh 
	 where idhojaruta = iddel;

	delete
	  from mct_movimientoordentrabajo
	 where idhojaruta = iddel;
	 
	-- Se elimina ordentrabajo parte 
	delete 
	  from mct_ordentrabajoparte
	 where idordentrabajoparte = sp_idotp;
	 

   -- Luego borra las hojas de ruta asociadas
	delete from mct_hojaruta 
	 where idhojaruta = iddel;
	
	if (select distinct 1
	      from mct_detallehojarutatemp  
	     where codhojaruta = sp_codhr) then
	     
	     select idhojarutatemp
	       into sp_idhrt
	       from mct_detallehojarutatemp 
	      where codhojaruta = sp_codhr;

	     select cantidad
	       into sp_cant
	       from mct_hojarutatemp 
	      where idhojarutatemp = sp_idhrt;

	     
	     if ( sp_cant > 1) then
	     
	        update traking.mct_hojarutatemp
	           set cantidad = cantidad - 1
	         where idhojarutatemp = sp_idhrt;

	        delete 
    	      from traking.mct_detallehojarutatemp 
    	     where mct_detallehojarutatemp.codhojaruta = sp_codhr;
    	 
    	 else
 
	         delete 
    	       from traking.mct_detallehojarutatemp 
    	      where mct_detallehojarutatemp.codhojaruta = sp_codhr;
    	    
	 	     delete 
		       from traking.mct_hojarutatemp 
		      where mct_hojarutatemp.idhojarutatemp = sp_idhrt;
	   
	   		 delete 
	   		   from traking.mct_hojarutaactividadtemp 
	   		  where mct_hojarutaactividadtemp.idhojarutatemp = sp_idhrt;   	    
    	   
	     end if;

   
	end if;

END;
$$;


ALTER FUNCTION traking.delroadmaptempmanual(iddel bigint) OWNER TO postgres;

