--
-- TOC entry 1490 (class 1255 OID 16747)
-- Name: evtaddcaracterizacionpdf(bigint, text, character varying, double precision, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddcaracterizacionpdf(idcaracterizacioni bigint, archivoadjuntoi text, nombrearchivoi character varying, tamanoi double precision, idtipocaracterizacionpdfi bigint, usuariocreacioni character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

begin
	 
      IF (select distinct 1
		    from mct_caracterizacionpdf 
           where idcaracterizacion = idcaracterizacioni
             and nombrearchivo = nombrearchivoi
             and idtipocaracterizacionpdf = idtipocaracterizacionpdfi ) then
           
			UPDATE traking.mct_caracterizacionpdf
			   set archivoadjunto = archivoadjuntoi,
			       tamano = tamanoi,
			       solicitudvalidaparaenvio = sp_validaenviosol
			 where idcaracterizacion  = idcaracterizacioni
               and nombrearchivo = nombrearchivoi; 	

	  else	  
	
			insert into traking.mct_caracterizacionpdf (
				      idcaracterizacionpdf ,
					  idcaracterizacion,
					  archivoadjunto,
					  nombrearchivo,
					  tamano ,
					  idtipocaracterizacionpdf ,
					  usuariocreacion,
					  fechacreacion 
					 ) 
				values 
				     (
				      nextval('traking.mct_caracterizacionpdf_seq'),
					  idcaracterizacioni,
					  archivoadjuntoi,
					  nombrearchivoi,
					  tamanoi,
					  idtipocaracterizacionpdfi,
					  usuariocreacioni,
					  now()
				);	
      END IF;

	
     RETURN '0:Exito';

END;
$$;


ALTER FUNCTION traking.evtaddcaracterizacionpdf(idcaracterizacioni bigint, archivoadjuntoi text, nombrearchivoi character varying, tamanoi double precision, idtipocaracterizacionpdfi bigint, usuariocreacioni character varying) OWNER TO postgres;

