--
-- TOC entry 1054 (class 1255 OID 16749)
-- Name: evtaddchecklistinftecdetinf(bigint, bigint, bigint, character varying, bigint, character varying, character varying, character varying, character varying, boolean, bigint, character varying, bigint, character varying, bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddchecklistinftecdetinf(indexrowi bigint, idchecklistinfteci bigint, idworkorderi bigint, partnamei character varying, quantityi bigint, materialnamei character varying, repaircriteriai character varying, repairi character varying, blueprintnamei character varying, returncompi boolean, idcomponentei bigint, componentegenericoi character varying, idmateriali bigint, materialgenericoi character varying, idcriterioevaluacioni bigint, nombrezonai character varying, idpadrei bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 

    sp_fecha_requerida      varchar;
    sp_criterioname			varchar;
    sp_indicefila           integer;
   	sp_id					bigint;
   
    sp_criterio				varchar;
    sp_texto				varchar;   
			  
BEGIN 
--	
 	sp_criterioname	:= '';
    sp_indicefila	:= 0;
   
    sp_criterio		:= '';
    sp_texto		:= '';
   
--
	select nombrecriterioevaluacion 
	  into sp_criterioname
	  from mct_criterioevaluacion 
	 where idcriterioevaluacion = cast(repaircriteriai as bigint);
	
	select max(indicefila+1) 
	  into sp_indicefila
	  from mct_checklistinftec  
	 where idchecklistinftec = idpadrei;

	    --if ( sp_criterio not in  'FAB_FU' && sp_criterio != 'FAB_PA' && sp_criterio != 'FAB_CA' && && sp_criterio != 'RPO' ) then
	    if ( upper(sp_criterioname) not in  ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO', 'STOCK_CC', 'RPO_SM') ) then
	    
	        sp_criterio := 'OTROS';
	        sp_texto    := idworkorderi||sp_criterio;
	       
	    else
	    
	        sp_criterio := upper(sp_criterioname);
	        sp_texto    := idworkorderi||upper(sp_criterioname);
	       
	    end if;	
	   
	sp_id	:= nextval('mct_checklistinftec_seq');

	if ( idchecklistinfteci = -1 ) then
	
		insert into mct_checklistinftec 
		           (
		           idchecklistinftec,
		           idordentrabajo ,
		           nombreparte ,
		           cantidad ,
		           material ,
		           criterio ,
		           reparacion ,
		           plano ,
		           usuariocreacion ,
		           fechacreacion ,
		           indicefila ,
		           codigoqr ,
		           tipotrabajostd ,
		           devolucion ,
		           muestrachecklist ,
		           flagpantallafacturacion ,
		           idcomponente ,
		           nombrecomponente ,
		           idmaterial ,
		           nombrematerial ,
		           idesmecanizado ,
		           idcriterioevaluacion ,
		           nombrezona ,
		           idpadre
		           )
		   values (
		           sp_id,
		           idworkorderi ,
		           partnamei ,
		           quantityi ,
		           materialnamei ,
		           sp_criterioname ,
		           repairi ,
		           blueprintnamei ,
		           'admin' ,
		           now() ,
		           sp_indicefila ,
		           --idworkorderi||upper(sp_criterioname) ,
		           --upper(sp_criterioname) ,
		           sp_texto,
		           upper(sp_criterio),
		           returncompi ,
		           true ,
		           true ,
		           idcomponentei ,
		           componentegenericoi ,
		           idmateriali ,
		           materialgenericoi ,
		           2 ,
		           cast(repaircriteriai as bigint),
		           nombrezonai ,
		           idpadrei
		          );
		      
		      return sp_id;
		
	end if;

END			
$$;


ALTER FUNCTION traking.evtaddchecklistinftecdetinf(indexrowi bigint, idchecklistinfteci bigint, idworkorderi bigint, partnamei character varying, quantityi bigint, materialnamei character varying, repaircriteriai character varying, repairi character varying, blueprintnamei character varying, returncompi boolean, idcomponentei bigint, componentegenericoi character varying, idmateriali bigint, materialgenericoi character varying, idcriterioevaluacioni bigint, nombrezonai character varying, idpadrei bigint) OWNER TO postgres;

