		           idpadre
		           )
		   values (sp_idv,
		           sp_id,
		           idworkorderi ,
		           partnamei ,
		           quantityi ,
		           materialnamei ,
		           sp_criterioname ,
		           repairi ,
		           blueprintnamei ,
		           'admin' ,
		           now() ,
		           sp_indicefila ,
		           --idworkorderi||upper(sp_criterioname) ,
		           --upper(sp_criterioname) ,
		           sp_texto,
		           upper(sp_criterio),
		           returncompi ,
		           true ,
