--
-- TOC entry 1934 (class 1255 OID 16751)
-- Name: evtadddossierpdfsave(bigint, bigint, text, character varying, double precision, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtadddossierpdfsave(idworkorders bigint, idtipodocumentodossiers bigint, filepdf text, filename character varying, filesize double precision, columnas bigint, usercreate character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
	sp_idfamily     integer;
	sp_tipoorden	integer;
    sp_aprobado		boolean;
    sp_validado		boolean;
    
    sp_validaenviosol	boolean;
begin
	
	 
      IF (select distinct 1
		    from mct_dossierpdf 
           where idordentrabajo = idworkorders
             and nombrearchivo  = filename
             and columna        = columnas ) then
           
			UPDATE traking.mct_dossierpdf
			   set archivoadjunto = filepdf,
			       tamano  = filesize
			 where idordentrabajo  = idworkorders
               and nombrearchivo = filename; 	

	  else
	  	        
		insert into traking.mct_dossierpdf 
		           (
				      iddossierpdf ,
					  idordentrabajo,
					  idtipodocumentodossier,
					  archivoadjunto,
					  nombrearchivo ,
					  tamano ,
					  columna,
					  fechacreacion,
					  usuariocreacion
					) 
			values (
					nextval('mct_dossierpdf_seq'),
					idworkorders,
					idtipodocumentodossiers,
					filepdf,
					filename,
					filesize,
					columnas,
					now(),
					usercreate
			);
		
      END IF;

	
     RETURN '0:Exito';

END;
$$;


ALTER FUNCTION traking.evtadddossierpdfsave(idworkorders bigint, idtipodocumentodossiers bigint, filepdf text, filename character varying, filesize double precision, columnas bigint, usercreate character varying) OWNER TO postgres;

--
-- TOC entry 1220 (class 1255 OID 16752)
-- Name: evtaddevaluacionmovil(bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddevaluacionmovil(idpartworkorder bigint, idworkorder bigint, iduser bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

       sp_ideva   INTEGER;
BEGIN 
	  update mct_ordentrabajo 
	     set idusuario = iduser
	   where idordentrabajo = idworkorder;
	  
	  IF (select 1
		    from mct_evaluacion
           where idordentrabajoparte = idpartworkorder ) then
            
           select idevaluacion
	         into sp_ideva
		     from mct_evaluacion
            where idordentrabajoparte = idpartworkorder;
           
            return sp_ideva;
           
      else
      	   sp_ideva := nextval('traking.mct_evaluacion_seq');
			       
		   insert into mct_evaluacion(idevaluacion,idordentrabajoparte)
		        values (sp_ideva,idpartworkorder);
					
		   RETURN sp_ideva;
		  
      end if;
END			
$$;


ALTER FUNCTION traking.evtaddevaluacionmovil(idpartworkorder bigint, idworkorder bigint, iduser bigint) OWNER TO postgres;

--
-- TOC entry 1267 (class 1255 OID 16753)
-- Name: evtaddinfcotipdfsave(bigint, bigint, text, character varying, double precision, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddinfcotipdfsave(idworkorders bigint, infcotis bigint, filepdf text, filename character varying, filesize double precision, idprocess bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
	sp_idfamily     integer;
	sp_tipoorden	integer;
    sp_aprobado		boolean;
    sp_validado		boolean;
    
    sp_validaenviosol	boolean;
begin
	
	  select idfamilia ,
	         idtipoorden,
	         checklistinfaprobado ,
	         checklistvalido 
	    into sp_idfamily,
	         sp_tipoorden,
	         sp_aprobado,
	         sp_validado
	    from mct_ordentrabajo 
	   where idordentrabajo = idworkorders;
	
	  if ( sp_aprobado is true or sp_validado is true ) then
	  	sp_validaenviosol := true;	  
	  else
	  	sp_validaenviosol := false;	  
