--
-- TOC entry 2294 (class 1255 OID 16758)
-- Name: evtaddot(bigint, bigint, bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddot(idcustomer bigint, idordertype bigint, idproduct bigint, nameworkorder character varying, idorderstatus bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

			
        sp_idot   				    INTEGER;
        sp_idotp   				    INTEGER;
		sp_ocompra 				    INTEGER;
		sp_idcotizacion 			INTEGER;
		sp_idestado          		INTEGER;

        sp_otchar                   TEXT;
        sp_partchar                 TEXT;
        sp_corrchar                 TEXT;

        indice   				    INTEGER;
        tope	   				    INTEGER;

        rec_partecant               RECORD;
        cur_partecantidad  CURSOR(sp_idot integer) 
                    		  FOR select b.idordentrabajoparte, b.idparte, c.cantidad
		                            from mct_ordentrabajo a, 
		                                 mct_ordentrabajoparte b, 
		                                 mct_productoparte c
		                            where a.idordentrabajo = sp_idot
		                            and  a.idproducto = c.idproducto
		                            and  b.idparte = c.idparte;

BEGIN
        sp_idestado     := 2;
		sp_idcotizacion := 0;
		sp_ocompra      := 0;
        sp_otchar       := '';
        sp_partchar     := '';
        sp_corrchar     := '';

        sp_idot := nextval('traking.mct_ordentrabajo_seq');

        insert into mct_ordentrabajo 
                    (idordentrabajo 
                    ,idcliente 
                    ,idcotizacion 
                    ,idtipoorden 
                    ,idproducto 
                    ,nombreordentrabajo 
                    ,ordencompra 
                    ,fecharecepcion
                    ,fechaentrega 
                    ,usuariocreacion 
                    ,fechacreacion 
                    ,idestadoorden )
                VALUES
                    (sp_idot
                    ,idcustomer
                    ,sp_idcotizacion
                    ,idordertype
                    ,idproduct
                    ,nameworkorder
                    ,sp_ocompra
                    ,now()
                    ,now() + interval '60 day'
                    ,'admin'
                    ,now()
                    ,idorderstatus );

                          
        insert into mct_ordentrabajoparte
        select nextval('traking.mct_ordentrabajoparte_seq'), sp_idot,  idparte
          from traking.mct_productoparte
         where idproducto = idproduct;
        
        
        insert into mct_evaluacion
                           (idevaluacion
                           ,idordentrabajoparte)
        select (nextval('traking.mct_evaluacion_seq')), idordentrabajoparte
          from traking.mct_ordentrabajoparte
         where traking.mct_ordentrabajoparte.idordentrabajo = sp_idot;


        OPEN cur_partecantidad(sp_idot);

        LOOP
                
            FETCH cur_partecantidad INTO rec_partecant;

            EXIT WHEN NOT FOUND;
           
            tope := rec_partecant.cantidad;
            indice := 1;
 --          	FOR r IN 1..rec_partecant.cantidad
				loop
 
                    sp_otchar   := LPAD(sp_idot::integer::text::varchar, 6, '0');  
                    sp_partchar := LPAD(rec_partecant.idparte::integer::text::varchar, 2, '0');
                    sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 

                    insert into mct_hojaruta 
                            (idhojaruta 
                            ,idordentrabajoparte 
                            ,codhojaruta 
                            ,usuariocreacion 
                            ,fechacreacion )
                        VALUES
                            (nextval('traking.mct_hojaruta_seq')
                            ,rec_partecant.idordentrabajoparte
                            ,sp_otchar||sp_partchar||sp_corrchar
                            ,'admin'
                            ,now() );
                           
        
                           indice := indice + 1;
                           				   
                           EXIT when indice > tope;
                    
                END loop;

        End Loop;
        
        CLOSE cur_partecantidad;

		RETURN sp_idot;
							
END;				
$$;


ALTER FUNCTION traking.evtaddot(idcustomer bigint, idordertype bigint, idproduct bigint, nameworkorder character varying, idorderstatus bigint) OWNER TO postgres;

--
-- TOC entry 2221 (class 1255 OID 16759)
-- Name: evtaddotmovil(bigint, bigint, bigint, bigint, bigint, bigint, character varying, bigint, character varying, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddotmovil(idcustomer bigint, idordertype bigint, idproduct bigint, idfamily bigint, idlinedesign bigint, idworkorderprev bigint, taginput character varying, iduser bigint, nameworkorder character varying, idorderstatus bigint, inputguide bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
			
        sp_idot   				    INTEGER;
        --sp_idprod   			    INTEGER;
        sp_idotp   				    INTEGER;
		sp_ocompra 				    INTEGER;
		sp_idcotizacion 			INTEGER;
		sp_idestado          		INTEGER;

		sp_tipoorden                varchar;
	    --sp_cliente                  varchar;
	    sp_nombreproducto           varchar;
	   
        sp_otchar                   TEXT;
        sp_partchar                 TEXT;
        sp_corrchar                 TEXT;

        indice   				    INTEGER;
        tope	   				    INTEGER;
		                           
		rec_unicopartecant          RECORD;
        cur_unicopartecant          CURSOR(sp_idprod integer) 
                    		           FOR select a.idproducto,
                    		                      a.idparte,
                    		                      b.idtipoparte ,
                    		                      a.cantidad
   											 from traking.mct_productoparte a,
       											  mct_parte b
         						            where idproducto = sp_idprod 
         						              and a.idparte = b.idparte
         						            order by idparte ;

BEGIN
        sp_idestado     := 2;
		sp_idcotizacion := 0;
		sp_ocompra      := 0;
        sp_otchar       := '';
        sp_partchar     := '';
        sp_corrchar     := '';
        sp_tipoorden    := '';
        --sp_cliente      := '';  
        sp_nombreproducto := '';  

       	select nombretipoorden 
	      into sp_tipoorden
	      from mct_tipoorden
	     where idtipoorden = idordertype;
	    
	   select nombreproducto
	     into sp_nombreproducto
	     from mct_producto
	    where idproducto = idproduct;	    
       
        sp_idot := nextval('traking.mct_ordentrabajo_seq');

        insert into mct_ordentrabajo 
                    (idordentrabajo 
                    ,idcliente 
                   -- ,idcotizacion 
                    ,idtipoorden 
                    ,idproducto 
                    ,idfamilia 
	                ,idlineadiseno 
                    ,nombreordentrabajo 
                    ,fecharecepcion 
                    ,fechaentrega 
                    ,usuariocreacion 
                    ,fechacreacion 
                    ,idestadoorden
                    ,guiaentrante
                    ,idordentrabajoanterior
                    ,tag
                    ,idmodalidadcreacion
                    ,idusuario
                    )
                VALUES
                    (sp_idot
                    ,idcustomer
                   -- ,sp_idcotizacion
                    ,idordertype
                    ,idproduct
                    ,idfamily
	                ,idlinedesign
                    ,sp_tipoorden||' '||sp_nombreproducto
                    ,now()
                    ,now() + interval '60 day'
                    ,'admin'
                    ,now()
                    ,idorderstatus
                    ,inputguide
                    ,idworkorderprev
                    ,taginput
                    ,2
                    ,iduser);
                   
        OPEN cur_unicopartecant(idproduct);

        loop 
                
            FETCH cur_unicopartecant INTO rec_unicopartecant;

            EXIT WHEN NOT FOUND;
           
           -- aca debe validar para el tipoparte = 17
           
            if ( rec_unicopartecant.idtipoparte = 17 ) then
            
            -- Primera vez para registros que tienen el total
            	 sp_idotp := nextval('traking.mct_ordentrabajoparte_seq');
		 
			     insert INTO traking.mct_ordentrabajoparte
		                    (idordentrabajoparte, 
		                     idordentrabajo, 
		                     idparte, 
		                     itemparte)
		              VALUES(sp_idotp, 
		                     sp_idot, 
		                     rec_unicopartecant.idparte, 
		                     rec_unicopartecant.cantidad
		                    );
		                   
		        sp_otchar   := LPAD(sp_idot::integer::text::varchar, 6, '0');  
		        sp_partchar := LPAD(rec_unicopartecant.idparte::integer::text::varchar, 3, '0');
		        sp_corrchar := LPAD(rec_unicopartecant.cantidad::integer::text::varchar, 3, '0'); 
		
		        insert into mct_hojaruta 
		                   (idhojaruta 
		                   ,idordentrabajoparte 
		                   ,codhojaruta 
		                   ,usuariocreacion 
		                   ,fechacreacion 
		                   )
		              VALUES
		                   (nextval('traking.mct_hojaruta_seq')
		                   ,sp_idotp
		                   ,sp_otchar||sp_partchar||sp_corrchar
		                   ,'admin'
		                   ,now() 
		                   );    
		                  
		      -- Segunda vez para registros en 0 para que cuando se aplique limpieza se actualicen con el valor
		 
		                   
		        sp_otchar   := LPAD(sp_idot::integer::text::varchar, 6, '0');  
		        sp_partchar := LPAD(rec_unicopartecant.idparte::integer::text::varchar, 3, '0');
		        sp_corrchar := LPAD(0::integer::text::varchar, 3, '0'); 
		
		        insert into mct_hojaruta 
		                   (idhojaruta 
		                   ,idordentrabajoparte 
		                   ,codhojaruta 
		                   ,usuariocreacion 
		                   ,fechacreacion 
		                   )
		              VALUES
		                   (nextval('traking.mct_hojaruta_seq')
		                   ,sp_idotp
		                   ,sp_otchar||sp_partchar||sp_corrchar
		                   ,'admin'
		                   ,now() 
		                   );    
		      -- Hasta aca la segunda parte
            else
           
		            tope := coalesce(rec_unicopartecant.cantidad,0);
		           
		            indice := 1;
		
						loop
						
						   sp_idotp := nextval('traking.mct_ordentrabajoparte_seq');
		 
						   insert INTO traking.mct_ordentrabajoparte
		                               (idordentrabajoparte, 
		                                idordentrabajo, 
		                                idparte, 
		                                itemparte)
		                         VALUES(sp_idotp, 
		                                sp_idot, 
		                                rec_unicopartecant.idparte, 
		                                indice
		                               );
		
		                    sp_otchar   := LPAD(sp_idot::integer::text::varchar, 6, '0');  
		                    sp_partchar := LPAD(rec_unicopartecant.idparte::integer::text::varchar, 3, '0');
		                    sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
		
		                    insert into mct_hojaruta 
		                               (idhojaruta 
		                               ,idordentrabajoparte 
		                               ,codhojaruta 
		                               ,usuariocreacion 
		                               ,fechacreacion )
		                          VALUES
		                               (nextval('traking.mct_hojaruta_seq')
		                               ,sp_idotp
		                               ,sp_otchar||sp_partchar||sp_corrchar
		                               ,'admin'
		                               ,now() 
		                               );                     
		        
		                           indice := indice + 1;
		                           				   
		                           EXIT when indice > tope;
		                    
		                END loop;
		    end if;

        End Loop;
        
        CLOSE cur_unicopartecant;
                   

       insert into mct_evaluacion
                   (idevaluacion
                   ,idordentrabajoparte
                   ,idtipotrabajo 
                   ,idreparafabrica
                   ,observacion
                   ,cantidadcompra )        
           select  (nextval('traking.mct_evaluacion_seq')), idordentrabajoparte, 
                case 
                    when traking.mct_componente.evaluaciondirecta = 1 then
                       21
                  end,
                case 
                  when traking.mct_componente.evaluaciondirecta = 1 then
                       1
                end,
                case 
                  when traking.mct_componente.evaluaciondirecta = 1 then
                       'EVALUADO DIRECTAMENTE'
                end ,
                0 
          from traking.mct_ordentrabajoparte
          left join traking.mct_parte      on  traking.mct_parte.idparte = traking.mct_ordentrabajoparte.idparte 
          left join traking.mct_componente on  traking.mct_componente.idcomponente = traking.mct_parte.idcomponente 
          left join traking.mct_ordentrabajo on traking.mct_ordentrabajo.idordentrabajo  = traking.mct_ordentrabajoparte.idordentrabajo 
          left join traking.mct_productoparte on traking.mct_productoparte.idproducto  = traking.mct_ordentrabajo.idproducto and traking.mct_productoparte.idparte = traking.mct_ordentrabajoparte.idparte 
         where traking.mct_ordentrabajoparte.idordentrabajo = sp_idot;

      
		RETURN sp_idot;
							
END;				
$$;


ALTER FUNCTION traking.evtaddotmovil(idcustomer bigint, idordertype bigint, idproduct bigint, idfamily bigint, idlinedesign bigint, idworkorderprev bigint, taginput character varying, iduser bigint, nameworkorder character varying, idorderstatus bigint, inputguide bigint) OWNER TO postgres;

--
-- TOC entry 1494 (class 1255 OID 16761)
-- Name: evtaddpartialdispatchbody(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddpartialdispatchbody(idpart bigint, qdispatch bigint, idworkorderpart bigint, iddispatchhead bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 

			
DECLARE 

       sp_despacho        integer;
       sp_idordentrabajo  integer;
       sp_idfamilia       integer;
       sp_total           integer;
       sp_totaldesp       integer;      
      
BEGIN
			  
	  sp_total		:= 0;
	  sp_totaldesp	:= 0;
	 
      INSERT INTO traking.mct_despachopartedetalle
                 (iddespachopartedetalle , 
                  idparte, 
                  fechadespacho, 
                  qdespacho, 
                  idordentrabajoparte,
                  iddespachopartecabecera)
           VALUES(nextval('traking.mct_despachopartedetalle_seq'),
                  idpart, 
                  now(), 
                  qdispatch, 
                  idworkorderpart,
                  iddispatchhead);
					
                 
	     select idordentrabajo 
	       into sp_idordentrabajo
	       from mct_despachopartecabecera 
	      where iddespachopartecabecera = iddispatchhead;
	     
	     select idfamilia 
	       into sp_idfamilia
	       from mct_ordentrabajo 
	      where idordentrabajo = sp_idordentrabajo;
       
	      if ( sp_idfamilia != 8 ) then
	      
		      select sum(cantidad)
		        into sp_total
		        from mct_ordentrabajorepuesto a 
		       where idordentrabajo = sp_idordentrabajo;
		       
		      select sum(b.qdespacho)
		        into sp_totaldesp
		        from mct_despachopartecabecera a ,
		             mct_despachopartedetalle b
		       where a.idordentrabajo = sp_idordentrabajo
		         and a.iddespachopartecabecera = b.iddespachopartecabecera ;
		         
		       if ( sp_total = sp_totaldesp ) then 
		       
		          update mct_ordentrabajo 
		             set idestadoorden = 9
		           where idordentrabajo = sp_idordentrabajo;
		       
		       end if;
	      
	      end if;
     
     
		 RETURN 0;  

END			
$$;


ALTER FUNCTION traking.evtaddpartialdispatchbody(idpart bigint, qdispatch bigint, idworkorderpart bigint, iddispatchhead bigint) OWNER TO postgres;

