CREATE FUNCTION traking.evtaddpdfsave(idworkorders bigint, infcotis bigint, filepdf text) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

begin
	
	
      IF (select 1
		    from mct_infcotipdf 
           where idordentrabajo  = idworkorders
             and infcoti      = infcotis) then
           
			UPDATE  traking.mct_infcotipdf
			   SET
					archivoadjunto = filepdf
			 where idordentrabajo  = idworkorders
               and infcoti      = infcotis; 	

	  ELSE
			insert into traking.mct_infcotipdf (
				  idordentrabajo,
				  infcoti,
				  archivoadjunto
				 ) 
				values (
						idworkorders,
						infcotis,
						filepdf
				);	
      END IF;

	
     RETURN '0:Exito';

END;
$$;


