--
-- TOC entry 992 (class 1255 OID 16770)
-- Name: evtaddpicpartbyot(bigint, text, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddpicpartbyot(idpartworkorder bigint, picfile text, correlative bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  sp_idevaluacion 			integer;
  sp_count					integer;
begin
	
	select count(*),idevaluacion
	  into sp_count, sp_idevaluacion
	from mct_evaluacion
   where idordentrabajoparte = idpartworkorder
  group by idevaluacion;

 
  IF (sp_count) then
                        
      IF (select 1
		    from mct_evaluacionadjunto
           where idevaluacion        = sp_idevaluacion
             and idtipoadjunto       = 2
             and correlativo         = correlative) then
           
			UPDATE  traking.mct_evaluacionadjunto
			   SET
					archivoadjunto=picfile,
					correlativo = correlative
			 where idevaluacion = sp_idevaluacion
			   and idtipoadjunto = 2
			   and correlativo = correlative; 	

	  ELSE
			insert into traking.mct_evaluacionadjunto (
				  "idevaluacionadjunto", 
				  "idevaluacion", 
				  "idtipoadjunto", 
				  "archivoadjunto", 
				  "correlativo"
				 ) 
				values (
						nextval('traking.mct_evaluacionadjunto_seq'),
						sp_idevaluacion,
						2,
						picfile,
						correlative
				);	
      END IF;
  ELSE
      RETURN '1:No existe la partde a evaluar';
  END IF;
	
     RETURN '0:Exito';

END;
$$;


