--

CREATE FUNCTION traking.evtaddregisterjob(idoperator bigint, coderoadmap character varying, idsection bigint, idsubsection bigint, idmachine bigint, idoption bigint, idcauseend bigint, idsubcause bigint, descriptionpend character varying, idcausereproceso bigint, idmovetype bigint, idactivity bigint, idaction bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idroadmap		bigint;
	    sp_idhojaruta		bigint;
	    sp_idparte          bigint;
	   	sp_idordentrabajoparte          bigint;
	   	sp_idordentrabajo   bigint;
	   	sp_codigoaccion     varchar;
	   
begin
	
		select codigoaccion into sp_codigoaccion
		  from mct_accion 
