-- TOC entry 1816 (class 1255 OID 16774)
-- Name: evtaddregisterjobcc(bigint, bigint, bigint, bigint, bigint, bigint, bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddregisterjobcc(idoperators bigint, idsections bigint, idsubsections bigint, idmachines bigint, idmovetypes bigint, idactivitys bigint, idactions bigint, coderoadmaps character varying, idsectionf08s bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idhojaruta					integer;
	    sp_idparte          			integer;
	   	sp_idordentrabajoparte          integer;
	   	sp_idordentrabajo   			integer;
	   	sp_codigoaccion     			varchar;
	   	sp_codigoseccion     			varchar;	   
	    sp_estado						integer;
	    
	    sp_textof08                     varchar;
	   	sp_observacion					varchar;
	   
	   	sp_idseccion_ant				integer;
		sp_codigoseccion_ant			varchar;
		sp_idaccion_ant					integer;
		sp_estadoactividad_ant			integer;
	    sp_idaccion_salto               integer;
	    sp_texto_accion                 varchar;
	   
	    sp_modalidad                    integer;
	    sp_idcomponente                 integer;
	   
begin
	
		select codigoseccion 
		  into sp_codigoseccion
		  from mct_seccion 
		 where idseccion = idsections;
		
		select codigoaccion 
		  into sp_codigoaccion
		  from mct_accion 
		 where idaccion = idactions;
		   
		select idhojaruta, 
		       idordentrabajoparte,
		       modalidad
		  into sp_idhojaruta, 
		       sp_idordentrabajoparte,
		       sp_modalidad
		  from mct_hojaruta 
		 where codhojaruta = coderoadmaps;
		
	    select idparte, 
	           idordentrabajo,
	           idcomponente
	      into sp_idparte, 
	           sp_idordentrabajo,
	           sp_idcomponente
		  from mct_ordentrabajoparte mo 
		 where idordentrabajoparte = sp_idordentrabajoparte;
		
		sp_textof08 := '';
		if (idsectionf08s > 0 ) then
		    select 'Sección que rechaza la parte es : '||nombreseccion 
		      into sp_textof08
			  from mct_seccion 
			 where idseccion = idsectionf08s;		
		end if;
		
	    sp_observacion := 'Hoja de Ruta : '||coderoadmaps;
		
		-- Aca extraemos el ultimo trabajo realizado 		                                       
		select a.idseccion, 
		       b.codigoseccion , 
		       a.idaccion , 
		       a.estadoactividad 
		  into sp_idseccion_ant,
		       sp_codigoseccion_ant,
		       sp_idaccion_ant,
		       sp_estadoactividad_ant
		  from mct_movimientoordentrabajo a,
		       mct_seccion b
		 where idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
		                                           from mct_movimientoordentrabajo b 
		                                          where b.idhojaruta = sp_idhojaruta )
		   and a.idseccion = b.idseccion ;	
		  

		  if ( sp_idseccion_ant != idsections and 
		       sp_idaccion_ant != 91 ) then
		       
		       sp_texto_accion := 'R/E_'||sp_codigoseccion;
		      
		       select idaccion
		         into sp_idaccion_salto
		         from mct_accion
		        where codigoaccion = sp_texto_accion;
		       
		        sp_observacion := 'Hoja de Ruta : '||coderoadmaps||E'\nNO se realizo el traspaso entre áreas para el código : '||sp_texto_accion;
		  
				if (sp_modalidad = 1) then
                   sp_idparte := sp_idcomponente;
                end if;
       
       
				INSERT INTO traking.mct_movimientoordentrabajo
				            (idmovimientoordentrabajo, 
				             idordentrabajo, 
				             idhojaruta, 
				             codhojaruta, 
				             idparte, 
				             idseccion, 
				             idaccion, 
				             fechainicio, 
				             fechatermino, 
				             codigoaccion, 
				             estadoactividad,  
				             idoperador ,
				             operadorentrega, 
				             operadorrecibe,
				             idtipomovimiento,
				             idcausacierre ,
				             observacion 
				            )
				      values
				             (nextval('traking.mct_movimientoordentrabajo_seq'), 
				             sp_idordentrabajo, 
				             sp_idhojaruta, 
				             coderoadmaps, 
				             sp_idparte, 
				             idsections, 
				             91, 
				             now(), 
				             now(), 
				             'N/M', 
				             4, -- Este estado es para que aparezca el fondo cafe por salto de proceso
				             idoperators,
				             0, 
				             0,
				             91,
				             sp_idaccion_salto,
				             --E'Hoja de rutaNO se realizo el traspaso entre áreas para el codigo : '||sp_texto_accion
				             'Hoja de Ruta : '||coderoadmaps||E'\nNO se realizo el traspaso entre áreas para el código : '||sp_texto_accion
				            );		  
		  
		  
		  end if;
		  
		 
	   
		if (idmovetypes in (56,58,59,50)) then
			sp_estado := 2;

				  
			if (sp_modalidad = 1) then
                sp_idparte := sp_idcomponente;
            end if;
               
			INSERT INTO traking.mct_movimientoordentrabajo
			            (idmovimientoordentrabajo, 
			             idordentrabajo, 
			             idhojaruta, 
			             codhojaruta, 
			             idparte, 
			             idmaquina, 
			             idseccion, 
			             idactividad, 
			             idaccion, 
			             fechainicio, 
			             fechatermino, 
			             codigoaccion, 
			             estadoactividad, 
			             numeroinspeccion, 
			             idoperador ,
			             operadorentrega, 
			             operadorrecibe,
			             idtipomovimiento,
			             idcausacierre ,
			             idmotivocierre ,
			             idsubseccion,
			             idseccionrechazapieza,
			             observacion )
			      values
			             (nextval('traking.mct_movimientoordentrabajo_seq'), 
			             sp_idordentrabajo, 
			             sp_idhojaruta, 
			             coderoadmaps, 
			             sp_idparte, 
			             idmachines, 
			             idsections, 
			             idactivitys, 
			             idactions, 
			             now(), 
			             now(), 
			             sp_codigoaccion, 
			             sp_estado, -- 1: abierto, 2: cerrado 
			             '', 
			             idoperators,
			             0, 
			             0,
			             idmovetypes,
			             99,
			             99,
			             idsubsections,
			             idsectionf08s,
			             'Hoja de ruta : '||coderoadmaps||E'\n'||sp_textof08);		
		
		else
		    sp_estado := 1;

			if (sp_modalidad = 1) then
                sp_idparte := sp_idcomponente;
            end if;
           
			INSERT INTO traking.mct_movimientoordentrabajo
			            (idmovimientoordentrabajo, 
			             idordentrabajo, 
			             idhojaruta, 
			             codhojaruta, 
			             idparte, 
			             idmaquina, 
			             idseccion, 
			             idactividad, 
			             idaccion, 
			             fechainicio, 
			             fechatermino, 
			             codigoaccion, 
			             estadoactividad, 
			             numeroinspeccion, 
			             idoperador ,
			             operadorentrega, 
			             operadorrecibe,
			             idtipomovimiento,
			             idsubseccion,
			             observacion )
			      values
			             (nextval('traking.mct_movimientoordentrabajo_seq'), 
			             sp_idordentrabajo, 
			             sp_idhojaruta, 
			             coderoadmaps, 
			             sp_idparte, 
			             idmachines, 
			             idsections, 
			             idactivitys, 
			             idactions, 
			             now(), 
			             null, 
			             sp_codigoaccion, 
			             sp_estado, -- 1: abierto, 2: cerrado 
			             '', 
			             idoperators,
			             0, 
			             0,
			             idmovetypes,
			             idsubsections,
			            'Hoja de ruta : '||coderoadmaps);		   
		   
		end if;
	

		            
		if (idmovetypes in (52)) then
			sp_estado := 2;
		-- aca debe insertar en la tabla recepcionpieza
		end if;

END;
$$;


