--

CREATE FUNCTION traking.evtaddregisterjobing(idoperators bigint, idsections bigint, idmovetypes bigint, idactivitys bigint, idactions bigint, coderoadmaps character varying, idclosemotive bigint, idclosecause bigint, description character varying, observation character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idhojaruta					integer;
	    sp_idparte          			integer;
	   	sp_idordentrabajoparte          integer;
	   	sp_idordentrabajo   			integer;
	   	sp_codigoaccion     			varchar;
	   	sp_codigoseccion     			varchar;
	    sp_idaccion                     integer;
	   
	    sp_premec                       varchar;
	    sp_idseccion                    integer;
	   
		sp_idseccion_ant				integer;
		sp_codigoseccion_ant			varchar;
		sp_idaccion_ant					integer;
		sp_estadoactividad_ant			integer;
	    sp_idaccion_salto               integer;
	    sp_texto_accion                 varchar;
	   
	    sp_observacion					varchar;
	   
	    sp_idcomponente                 integer;
	    sp_modalidad                    integer;
	   
begin
	
		sp_codigoaccion  := '';
		sp_codigoseccion := '';
		sp_observacion := '';
	
		select codigoseccion 
		  into sp_codigoseccion
		  from mct_seccion 
		 where idseccion = idsections;
		
			
		sp_codigoseccion := 'ING';
		
	    select codigoaccion 
		  into sp_codigoaccion
	      from mct_accion 
		 where idaccion = idactions;
	    
		select idaccion 
		  into sp_idaccion
		  from mct_accion 
		 where codigoaccion = sp_codigoaccion
		   and tipoaccion = 1;
		  
		select idhojaruta, 
		       idordentrabajoparte,
		       modalidad
		  into sp_idhojaruta, 
		       sp_idordentrabajoparte,
		       sp_modalidad
		  from mct_hojaruta 
		 where codhojaruta = coderoadmaps;
		
		-- Aca extraemos el ultimo trabajo realizado 		                                       
		select a.idseccion, 
		       b.codigoseccion , 
		       a.idaccion , 
		       a.estadoactividad 
		  into sp_idseccion_ant,
		       sp_codigoseccion_ant,
		       sp_idaccion_ant,
		       sp_estadoactividad_ant
		  from mct_movimientoordentrabajo a,
		       mct_seccion b
		 where idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
		                                           from mct_movimientoordentrabajo b 
		                                          where b.idhojaruta = sp_idhojaruta )
		   and a.idseccion = b.idseccion ;		                                         

		  
		select idparte, 
	           idordentrabajo,
	           idcomponente
	      into sp_idparte, 
	           sp_idordentrabajo,
	           sp_idcomponente
		  from mct_ordentrabajoparte mo 
		 where idordentrabajoparte = sp_idordentrabajoparte;
		
		sp_observacion := 'Hoja de Ruta : '||coderoadmaps;		
				
		if ( idactions = 120 ) then
		
			sp_observacion := sp_observacion||E'\nSe da de baja esta pieza por los siguientes motivos : '||description;		
		
	    end if;

		if ( idactions in  ( 121, 122, 124 )  ) then
		
			sp_observacion := sp_observacion||E'\nLa Observacion es la siguiente : '||observation;		
		 
			update mct_movimientobloqueo 
			   set estadobloqueo = 2,
			       fechadesbloqueo = now(),
			       idoperadordesbloquea = idoperators
			 where codhojaruta = coderoadmaps
			   and estadobloqueo = 1;
		
		end if;
	


	    if (sp_modalidad = 1) then
            sp_idparte := sp_idcomponente;
        end if;
               
		INSERT INTO traking.mct_movimientoordentrabajo
		            (idmovimientoordentrabajo, 
		             idordentrabajo, 
		             idhojaruta, 
		             codhojaruta, 
		             idparte, 
		             idseccion, 
		             idactividad, 
		             idaccion, 
		             fechainicio, 
		             fechatermino, 
		             codigoaccion, 
		             estadoactividad, 
		             idoperador ,
		             idtipomovimiento,
		             idcausacierre ,
		             idmotivocierre ,
		             observacion,
		             descripcioning
		             )
		      values
		             (nextval('traking.mct_movimientoordentrabajo_seq'), 
		             sp_idordentrabajo, 
		             sp_idhojaruta, 
		             coderoadmaps, 
		             sp_idparte, 
		             idsections, 
		             idactivitys, 
		             idactions, 
		             now(), 
		             now(), 
		             'ING', 
		             2, -- 1: abierto, 2: cerrado 
		             idoperators,
		             idmovetypes,
		             idclosemotive,
                     idclosecause,
		             sp_observacion,
		             description);


END;
$$;


