CREATE FUNCTION traking.evtaddregisterjobmovil(idoperadori bigint, coderoadmapi character varying, codigoaccioni character varying, idseccioni bigint, idsubseccioni bigint, idmaquinai bigint, estadoactividadi bigint, idcausaterminoi bigint, descripcioni character varying, numeroinspeccioni character varying, idusuarioi bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idroadmap		 	 bigint;
	    sp_idhojaruta			 bigint;
	    sp_idparte               bigint;
	   	sp_idordentrabajoparte   bigint;
	   	sp_idordentrabajo  		 bigint;
	   	sp_codigoaccion    		 varchar;
	    sp_idcodigoaccion		 bigint;
	   
begin
	
		select idaccion  
		  into sp_idcodigoaccion
		  from mct_accion 
		 where codigoaccion = codigoaccioni;
		   
		select idhojaruta, 
		       idordentrabajoparte  
		  into sp_idhojaruta, 
		       sp_idordentrabajoparte
		  from mct_hojaruta 
		 where codhojaruta = coderoadmapi;
		
		
	    select idcomponente , 
	           idordentrabajo  
	      into sp_idparte, 
	           sp_idordentrabajo
		  from mct_ordentrabajoparte mo 
		 where idordentrabajoparte = sp_idordentrabajoparte;
		
		  
		if (estadoactividadi = 2) then
		
	         INSERT INTO traking.mct_movimientoordentrabajo
	                    (
	                    idmovimientoordentrabajo, 
	                    idhojaruta,
	                    idoperador, 
	                    codhojaruta, 
	                    idparte,
	                    idordentrabajo, 
	                    idseccion, 
	                    idsubseccion, 
	                    idmaquina, 
	                    idmotivocierre ,
	                    idcausacierre, 
	                    observacion, 
	                    idaccion, 
	                    fechainicio, 
	                    fechatermino, 
	                    codigoaccion,
	                    estadoactividad, 
	                    numeroinspeccion
	                   -- operadorentrega, 
	                    --operadorrecibe
	                    )
	             values
	                    (nextval('traking.mct_movimientoordentrabajo_seq'),
	                     sp_idhojaruta,
	                     idoperadori, 
	                     coderoadmapi, 
	                     sp_idparte,
	                     sp_idordentrabajo, 
	                     idseccioni, 
	       				 idsubseccioni, 
	       				 idmaquinai,
	                	 42, 
	                	 42,
	              		 descripcioni, 
	             		 sp_idcodigoaccion, 
	            		 now(), 
	            		 now(), 
	            		 codigoaccioni, 
	            		 estadoactividadi, -- 1: abierto, 2: cerrado , 
	            		 '0'
	            		);
	            	
		else
		
	         INSERT INTO traking.mct_movimientoordentrabajo
	                    (
	                    idmovimientoordentrabajo, 
	                    idhojaruta,
	                    idoperador, 
	                    codhojaruta, 
	                    idparte,
	                    idordentrabajo, 
	                    idseccion, 
	                    idsubseccion, 
	                    idmaquina, 
	                    idcausacierre, 
	                    observacion, 
	                    idaccion, 
	                    fechainicio, 
	                    fechatermino, 
	                    codigoaccion,
	                    estadoactividad, 
	                    numeroinspeccion
	                   -- operadorentrega, 
	                    --operadorrecibe
	                    )
	             values
	                    (nextval('traking.mct_movimientoordentrabajo_seq'),
	                     sp_idhojaruta,
	                     idoperadori, 
	                     coderoadmapi, 
	                     sp_idparte,
	                     sp_idordentrabajo, 
	                     idseccioni, 
	       				 idsubseccioni, 
	       				 idmaquinai,
	                	 idcausaterminoi, 
	              		 descripcioni, 
	             		 sp_idcodigoaccion, 
	            		 now(), 
	            		 null, 
	            		 codigoaccioni, 
	            		 estadoactividadi, -- 1: abierto, 2: cerrado , 
	            		 '0'
	            		);
		
		
		end if;

END;
$$;


