                        iniciaarmadodesarme
	                   -- operadorentrega, 
	                    --operadorrecibe
	                    )
	             values
	                    (nextval('traking.mct_movimientoordentrabajo_seq'),
	                     0,
	                     idoperadori, 
	                     sp_hojaruta, 
	                     0,
	                     cast(coderoadmapi as bigint), 
	                     idseccioni, 
	       				 idsubseccioni, 
	       				 idmaquinai,
	                	 42, 
	                	 42,
	              		 descripcioni, 
	             		 sp_idcodigoaccion, 
	            		 now(), 
	            		 now(), 
	            		 codigoaccioni, 
	            		 estadoactividadi, -- 1: abierto, 2: cerrado , 
