-- Name: evtaddregisterjobrepro(bigint, bigint, bigint, bigint, bigint, bigint, bigint, character varying, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddregisterjobrepro(idoperator bigint, idsection bigint, idsubsection bigint, idmachine bigint, idmovetype bigint, idactivity bigint, idaction bigint, roadmapcodes character varying, idrepromotive bigint, idregisterjob bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare


		sp_idhojaruta					integer;
	    sp_idparte          			integer;
	   	sp_idordentrabajoparte          integer;
	   	sp_idordentrabajo   			integer;
	   	sp_codigoaccion     			varchar;
	   
	    sp_modalidad                    integer;
	    sp_idcomponente                 integer;
	   
	    sp_observacion                  varchar;
	   	sp_textoreproc                  varchar;
	   
BEGIN
	
		select codigoaccion 
		  into sp_codigoaccion
		  from mct_accion 
		 where idaccion = idaction;
		   
		select idhojaruta, 
		       idordentrabajoparte,
		       modalidad
		  into sp_idhojaruta, 
		       sp_idordentrabajoparte,
		       sp_modalidad
		  from mct_hojaruta 
		 where codhojaruta = roadmapcodes;
		
	    select idparte, 
	           idordentrabajo,
	           idcomponente
	      into sp_idparte, 
	           sp_idordentrabajo,
	           sp_idcomponente
		  from mct_ordentrabajoparte mo 
		 where idordentrabajoparte = sp_idordentrabajoparte;
		
		select nombreaccion
	      into sp_textoreproc
		  from mct_accion  
		 where idaccion = idrepromotive;

		if (sp_modalidad = 1) then
            sp_idparte := sp_idcomponente;
        end if;
       
        sp_observacion := 'Hoja de Ruta : '||roadmapcodes||E'\nSe reprocesa la pieza por : '||sp_textoreproc;
      
		            
		INSERT INTO traking.mct_movimientoordentrabajo
		            (idmovimientoordentrabajo, 
		             idordentrabajo, 
		             idhojaruta, 
		             codhojaruta, 
		             idparte, 
		             idmaquina, 
		             idseccion, 
		             idactividad, 
		             idaccion, 
		             fechainicio, 
		             fechatermino, 
		             codigoaccion, 
		             estadoactividad, 
		             numeroinspeccion, 
		             idoperador ,
		             operadorentrega, 
		             operadorrecibe,
		             idtipomovimiento,
		             idsubseccion,
		             observacion )
		      values
		             (nextval('traking.mct_movimientoordentrabajo_seq'), 
		             sp_idordentrabajo, 
		             sp_idhojaruta, 
		             roadmapcodes, 
		             sp_idparte, 
		             idmachine, 
		             idsection, 
		             idactivity, 
		             idaction, 
		             now(), 
		             now(), 
		             sp_codigoaccion, 
		             1, -- 1: abierto, 2: cerrado 
		             '', 
		             idoperator,
		             0, 
		             0,
		             idmovetype,
		             idsubsection,
		             sp_observacion);
	
		            
			insert into traking.mct_movimientoreproceso
			            (
							idmovimientoreproceso,
							idregistrotrabajo,
							codhojaruta,
							idoperador,
							idseccion,
							idmotivoreproceso,
							fechareproceso
			            )
			      values
					    (nextval('traking.mct_movimientoreproceso_seq'), 
			            idregisterjob,
			            roadmapcodes,
			            idoperator,
			            idsection,
			            idrepromotive,
			            now()
			           );

END;
$$;


ALTER FUNCTION traking.evtaddregisterjobrepro(idoperator bigint, idsection bigint, idsubsection bigint, idmachine bigint, idmovetype bigint, idactivity bigint, idaction bigint, roadmapcodes character varying, idrepromotive bigint, idregisterjob bigint) OWNER TO postgres;

--
-- TOC entry 2004 (class 1255 OID 16783)
-- Name: evtaddregisterjobtm(bigint, bigint, bigint, bigint, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddregisterjobtm(idclosemotive bigint, idclosecause bigint, idoperators bigint, idsections bigint, idmovetypes bigint, idactivitys bigint, idactions bigint, coderoadmaps character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idhojaruta					integer;
	    sp_idparte          			integer;
	   	sp_idordentrabajoparte          integer;
	   	sp_idordentrabajo   			integer;
	   	sp_codigoaccion     			varchar;
	    sp_estado						integer;
	   
	    sp_modalidad                    integer;
	    sp_idcomponente                 integer;
	   
begin
	
		select codigoaccion
		  into sp_codigoaccion
		  from mct_accion 
		 where idaccion = idactions;
		   
		select idhojaruta,
		       idordentrabajoparte,
		       modalidad
		  into sp_idhojaruta, 
		       sp_idordentrabajoparte,
		       sp_modalidad
		  from mct_hojaruta 
		 where codhojaruta = coderoadmaps;
		
	    select idparte, 
	           idordentrabajo,
	           idcomponente
	      into sp_idparte,
	           sp_idordentrabajo,
	           sp_idcomponente
		  from mct_ordentrabajoparte mo 
		 where idordentrabajoparte = sp_idordentrabajoparte;
		
		if (idmovetypes in (82, 62, 84, 87, 83)) then
			sp_estado := 2;

				if (sp_modalidad = 1) then
	                sp_idparte := sp_idcomponente;
	            end if;
           
				INSERT INTO traking.mct_movimientoordentrabajo
		            (idmovimientoordentrabajo, 
		             idordentrabajo, 
		             idhojaruta, 
		             codhojaruta, 
		             idparte, 
		             --idmaquina, 
		             idseccion, 
		             idactividad, 
		             idaccion, 
		             fechainicio, 
		             fechatermino, 
		             codigoaccion, 
		             estadoactividad, 
		             numeroinspeccion, 
		             idoperador ,
		             operadorentrega, 
		             operadorrecibe,
		             idtipomovimiento,
		             observacion,
		             idmotivocierre ,
		             idcausacierre )
		      values
		             (nextval('traking.mct_movimientoordentrabajo_seq'), 
		             sp_idordentrabajo, 
		             sp_idhojaruta, 
		             coderoadmaps, 
		             sp_idparte, 
		            -- idmachines, 
		             idsections, 
		             idactivitys, 
		             idactions, 
		             now(), 
		             now(), 
		             sp_codigoaccion, 
		             sp_estado, -- 1: abierto, 2: cerrado 
		             '', 
		             idoperators,
		             0, 
		             0,
		             idmovetypes,
		             'Hoja de Ruta : '||coderoadmaps,
		             idclosemotive,
		             idclosecause);
		
		else
		    sp_estado := 1;

				if (sp_modalidad = 1) then
	                sp_idparte := sp_idcomponente;
	            end if;		   
		   
		   		INSERT INTO traking.mct_movimientoordentrabajo
		            (idmovimientoordentrabajo, 
		             idordentrabajo, 
		             idhojaruta, 
		             codhojaruta, 
		             idparte, 
		            -- idmaquina, 
		             idseccion, 
		             idactividad, 
		             idaccion, 
		             fechainicio, 
		             fechatermino, 
		             codigoaccion, 
		             estadoactividad, 
		             numeroinspeccion, 
		             idoperador ,
		             operadorentrega, 
		             operadorrecibe,
		             idtipomovimiento,
		             observacion)
		      values
		             (nextval('traking.mct_movimientoordentrabajo_seq'), 
		             sp_idordentrabajo, 
		             sp_idhojaruta, 
		             coderoadmaps, 
		             sp_idparte, 
		            -- idmachines, 
		             idsections, 
		             idactivitys, 
		             idactions, 
		             now(), 
		             null, 
		             sp_codigoaccion, 
		             sp_estado, -- 1: abierto, 2: cerrado 
		             '', 
		             idoperators,
		             0, 
		             0,
		             idmovetypes,
		             'Hoja de Ruta : '||coderoadmaps);
		end if;
	

		            
		if (idmovetypes in (2)) then
			sp_estado := 2;
		-- aca debe insertar en la tabla recepcionpieza
		end if;

END;
$$;


ALTER FUNCTION traking.evtaddregisterjobtm(idclosemotive bigint, idclosecause bigint, idoperators bigint, idsections bigint, idmovetypes bigint, idactivitys bigint, idactions bigint, coderoadmaps character varying) OWNER TO postgres;

