--
-- TOC entry 2085 (class 1255 OID 16786)
-- Name: evtaddsolcomppdfsave(bigint, text, character varying, double precision, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddsolcomppdfsave(idsolcompcabeceras bigint, filepdf text, filename character varying, filesize double precision, idprocess bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
	sp_idfamily     integer;
	sp_tipoorden	integer;
begin

	
      IF (select distinct 1
		    from mct_solcompadjunto 
           where idsolcompcabecera = idsolcompcabeceras
             and nombrearchivo     = filename ) then
           
			UPDATE traking.mct_solcompadjunto
			   set archivoadjunto = filepdf,
			       tamano         = filesize
			 where idordentrabajo = idsolcompcabeceras
               and nombrearchivo  = filename; 	

	  else
             
			insert into traking.mct_solcompadjunto (
			      idsolcompadjunto ,
				  idsolcompcabecera,
				  archivoadjunto,
				  nombrearchivo ,
				  tamano ,
				  idproceso
				 ) 
				values (
				nextval('mct_solcompadjunto_seq'),
						idsolcompcabeceras,
						filepdf,
						filename,
						filesize,
						idprocess
				);	
      END IF;

	
     RETURN '0:Exito';

END;
$$;


ALTER FUNCTION traking.evtaddsolcomppdfsave(idsolcompcabeceras bigint, filepdf text, filename character varying, filesize double precision, idprocess bigint) OWNER TO postgres;

