--
-- TOC entry 2211 (class 1255 OID 16788)
-- Name: evtaddtransferrecord(bigint, bigint, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddtransferrecord(iduserents bigint, iduserrecs bigint, idsectionents bigint, idsectionrecs bigint, coderoadmaps character varying, datend character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idroadmap			integer;
	    sp_idhojaruta			integer;
	    sp_idparte          	integer;
	   	sp_idordentrabajoparte  integer;
	   	sp_idordentrabajo   	integer;
	   	sp_codigoaccion     	varchar;
	    sp_codigoseccion        varchar;
	    sp_observacion          varchar;
	    sp_idaccion             integer;
	    sp_nombreoperadorent    varchar;
	    sp_nombreoperadorrec    varchar;
	    sp_modalidad            integer;
	    sp_componente           integer;
	   
	   
begin
	
		select idhojaruta, 
		       idordentrabajoparte,
		       modalidad
		  into sp_idhojaruta, 
		       sp_idordentrabajoparte,
		       sp_modalidad
		  from mct_hojaruta 
		 where codhojaruta = coderoadmaps;
		
	    select idparte, 
	           idordentrabajo,
	           idcomponente
	      into sp_idparte, 
	           sp_idordentrabajo,
	           sp_componente
		  from mct_ordentrabajoparte 
		 where idordentrabajoparte = sp_idordentrabajoparte;
		
		select 'R/E_'||codigoseccion 
		  into sp_codigoseccion
		  from mct_seccion ms 
		 where idseccion = idsectionrecs;
	
	    select idaccion 
	      into sp_idaccion
	      from mct_accion 
	     where codigoaccion = sp_codigoseccion;
	    
	    select nombreoperador 
	      into sp_nombreoperadorent
	      from mct_operador 
	    where idoperador = iduserents;
	   
	   	select nombreoperador 
	      into sp_nombreoperadorrec
	      from mct_operador 
	    where idoperador = iduserrecs;	    

	   
	    sp_observacion := 'Hoja de Ruta : '||coderoadmaps;
	   
	   	sp_observacion := sp_observacion||E'\nSe hace entrega de la hoja de ruta';	
	    
	   	sp_observacion := sp_observacion||E'\nOperador que entrega es : '||sp_nombreoperadorent;	
	   	sp_observacion := sp_observacion||E'\nOperador que recibe  es : '||sp_nombreoperadorrec;	
	   
	    if ( datend is not null ) then
	   		sp_observacion := sp_observacion||E'\nCon la siguiente fecha de compromiso : '||datend;		       
	    end if;
	   
	    if ( sp_modalidad = 1 ) then
	       sp_idparte := sp_componente;
	    end if;

	   
		INSERT INTO traking.mct_movimientoordentrabajo
		            (idmovimientoordentrabajo, 
		             idordentrabajo, 
		             idhojaruta, 
		             codhojaruta, 
		             idparte, 
		             idseccion,  
		             idactividad,
		             fechainicio, 
		             fechatermino, 
		             codigoaccion, 
		             estadoactividad, 
		            -- idusuario,
		             operadorentrega, 
		             operadorrecibe,
		             observacion,
		             idcausacierre ,
		             idmotivocierre ,
		             idoperador ,
		             idaccion 
		             )
		      values
		             (nextval('traking.mct_movimientoordentrabajo_seq'), 
		             sp_idordentrabajo, 
		             sp_idhojaruta, 
		             coderoadmaps, 
		             sp_idparte, 
		             idsectionrecs, 
		             4, -- esto debe indicar que es un traspaso entre areas
		             now(), 
		             now(), 
		             sp_codigoseccion, 
		             2, -- 1: abierto, 2: cerrado 
		             --'', 
		            -- 0,
		             iduserents, 
		             iduserrecs,
		             sp_observacion,
		             sp_idaccion,
		             99,
		             iduserrecs,
		             sp_idaccion
		            );

END;
$$;


ALTER FUNCTION traking.evtaddtransferrecord(iduserents bigint, iduserrecs bigint, idsectionents bigint, idsectionrecs bigint, coderoadmaps character varying, datend character varying) OWNER TO postgres;

--
-- TOC entry 1083 (class 1255 OID 16789)
-- Name: evtaddtratamientotermicopdf(bigint, text, character varying, double precision, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddtratamientotermicopdf(idtratamientotermicoi bigint, archivoadjuntoi text, nombrearchivoi character varying, tamanoi double precision, idtipocaracterizacionpdfi bigint, usuariocreacioni character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

begin
	 
      IF (select distinct 1
		    from mct_tratamientotermicopdf 
           where idtratamientotermico = idtratamientotermicoi
             and nombrearchivo = nombrearchivoi
             and idtipocaracterizacionpdf = idtipocaracterizacionpdfi ) then
           
			UPDATE traking.mct_tratamientotermicopdf
			   set archivoadjunto = archivoadjuntoi,
			       tamano = tamanoi,
			       solicitudvalidaparaenvio = sp_validaenviosol
			 where idtratamientotermico  = idtratamientotermicoi
               and nombrearchivo = nombrearchivoi; 	

	  else	  
	
			insert into traking.mct_tratamientotermicopdf (
				      idtratamientotermicopdf ,
					  idtratamientotermico,
					  archivoadjunto,
					  nombrearchivo,
					  tamano ,
					  idtipocaracterizacionpdf ,
					  usuariocreacion,
					  fechacreacion 
					 ) 
				values 
				     (
				      nextval('traking.mct_tratamientotermicopdf_seq'),
					  idtratamientotermicoi,
					  archivoadjuntoi,
					  nombrearchivoi,
					  tamanoi,
					  idtipocaracterizacionpdfi,
					  usuariocreacioni,
					  now()
				);	
      END IF;

	
     RETURN '0:Exito';

END;
$$;


