CREATE FUNCTION traking.evtaddworkqueue(idmachine bigint, idworkorder bigint, idroadmap bigint, idpart bigint, idpartworkorder bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 
		sp_maxorden		integer;
begin
	
		sp_maxorden := 0;
	
		select max(orden)
		  into sp_maxorden
		  from mct_colatrabajo 
		 where idmaquina = idmachine;

        insert into mct_colatrabajo 
                    (idcolatrabajo
                    ,idmaquina 
                    ,idhojaruta 
                    ,idestadocolatrabajo 
                    ,usuariocreacion 
                    ,fechacreacion
                    ,orden)
                VALUES
                    (nextval('traking.mct_colatrabajo_seq')
                    ,idmachine
                    ,idroadmap
                    ,1
                    ,'admin'
                    ,now()
                    ,sp_maxorden + 1);
							
END;				
$$;


