--
-- TOC entry 920 (class 1255 OID 16791)
-- Name: evtaddworkrecord(bigint, bigint, bigint, bigint, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddworkrecord(idoperators bigint, idsections bigint, idsubsections bigint, idmachines bigint, idmovetypes bigint, idactivitys bigint, idactions bigint, coderoadmaps character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idhojaruta					integer;
	    sp_idparte          			integer;
	   	sp_idordentrabajoparte          integer;
	   	sp_idordentrabajo   			integer;
	   	sp_codigoaccion     			varchar;
	   	sp_codigoseccion     			varchar;
	    sp_idaccion                     integer;
	   
	    sp_premec                       varchar;
	    sp_idseccion                    integer;
	   
		sp_idseccion_ant				integer;
		sp_codigoseccion_ant			varchar;
		sp_idaccion_ant					integer;
		sp_estadoactividad_ant			integer;
	    sp_idaccion_salto               integer;
	    sp_texto_accion                 varchar;
	   
	    sp_observacion					varchar;
	   
	    sp_idcomponente                 integer;
	    sp_modalidad                    integer;
	   
begin
	
		sp_codigoaccion  := '';
		sp_codigoseccion := '';
		sp_observacion := '';
	
		select codigoseccion 
		  into sp_codigoseccion
		  from mct_seccion 
		 where idseccion = idsections;
		
		if ( idsections = 1 ) then
		
			if ( idsubsections = 5 ) then
			
				sp_codigoseccion := sp_codigoseccion||'_T';
		
		    elsif ( idsubsections = 3 ) then
		    
		    		sp_codigoseccion := sp_codigoseccion||'_C';
		
		    end if;
		
		end if;

		
	    if ( idmovetypes = 1 ) then
	    
	    	sp_codigoaccion := 'P_'||sp_codigoseccion;
	    
	    else
	        if ( idmovetypes = 2 ) then
	        
	        	 sp_codigoaccion := 'M_'||sp_codigoseccion;
	    
	        else
	             select codigoaccion 
			       into sp_codigoaccion
			       from mct_accion 
			      where idaccion = idactions;
	    
	        end if;
	    end if;
	    
		select idaccion 
		  into sp_idaccion
		  from mct_accion 
		 where codigoaccion = sp_codigoaccion
		   and tipoaccion = 1;
		
		   
		select idhojaruta, 
		       idordentrabajoparte,
		       modalidad
		  into sp_idhojaruta, 
		       sp_idordentrabajoparte,
		       sp_modalidad
		  from mct_hojaruta 
		 where codhojaruta = coderoadmaps;
		
		-- Aca extraemos el ultimo trabajo realizado 		                                       
		select a.idseccion, 
		       b.codigoseccion , 
		       a.idaccion , 
		       a.estadoactividad 
		  into sp_idseccion_ant,
		       sp_codigoseccion_ant,
		       sp_idaccion_ant,
		       sp_estadoactividad_ant
		  from mct_movimientoordentrabajo a,
		       mct_seccion b
		 where idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
		                                           from mct_movimientoordentrabajo b 
		                                          where b.idhojaruta = sp_idhojaruta )
		   and a.idseccion = b.idseccion ;		                                         

		  
		select idparte, 
	           idordentrabajo,
	           idcomponente
	      into sp_idparte, 
	           sp_idordentrabajo,
	           sp_idcomponente
		  from mct_ordentrabajoparte mo 
		 where idordentrabajoparte = sp_idordentrabajoparte;
		
		  -- Verifica para ingresar un registro sin movimiento sin entrega entre areas
		  if ( sp_idseccion_ant != idsections and 
		       sp_idaccion_ant != 91 ) then
		       
		       sp_texto_accion := 'R/E_'||sp_codigoseccion;
		      
		       select idaccion
		         into sp_idaccion_salto
		         from mct_accion
		        where codigoaccion = sp_texto_accion;
		       
		        sp_observacion := 'Hoja de Ruta : '||coderoadmaps||E'\nNO se realizo el traspaso entre áreas para el código : '||sp_texto_accion;
		  
				     
                if (sp_modalidad = 1) then
                   sp_idparte := sp_idcomponente;
                end if;
		       
				INSERT INTO traking.mct_movimientoordentrabajo
				            (idmovimientoordentrabajo, 
				             idordentrabajo, 
				             idhojaruta, 
				             codhojaruta, 
				             idparte, 
				             idseccion, 
				             idaccion, 
				             fechainicio, 
				             fechatermino, 
				             codigoaccion, 
				             estadoactividad,  
				             idoperador ,
				             operadorentrega, 
				             operadorrecibe,
				             idtipomovimiento,
				             idcausacierre ,
				             observacion 
				            )
				      values
				             (nextval('traking.mct_movimientoordentrabajo_seq'), 
				             sp_idordentrabajo, 
				             sp_idhojaruta, 
				             coderoadmaps, 
				             sp_idparte, 
				             idsections, 
				             91, 
				             now(), 
				             now(), 
				             'N/M', 
				             4, -- Este estado es para que aparezca el fondo cafe por salto de proceso
				             idoperators,
				             0, 
				             0,
				             91,
				             sp_idaccion_salto,
				             --E'Hoja de rutaNO se realizo el traspaso entre áreas para el codigo : '||sp_texto_accion
				             'Hoja de Ruta : '||coderoadmaps||E'\nNO se realizo el traspaso entre áreas para el código : '||sp_texto_accion
				            );		  
		  
		  
		  end if;
		  
		sp_observacion := 'Hoja de Ruta : '||coderoadmaps;

	    if (sp_modalidad = 1) then
            sp_idparte := sp_idcomponente;
        end if;
               
		INSERT INTO traking.mct_movimientoordentrabajo
		            (idmovimientoordentrabajo, 
		             idordentrabajo, 
		             idhojaruta, 
		             codhojaruta, 
		             idparte, 
		             idmaquina, 
		             idseccion, 
		             idactividad, 
		             idaccion, 
		             fechainicio, 
		             --fechatermino, 
		             codigoaccion, 
		             estadoactividad, 
		             numeroinspeccion, 
		             idoperador ,
		             operadorentrega, 
		             operadorrecibe,
		             idtipomovimiento,
		             idsubseccion,
		             observacion )
		      values
		             (nextval('traking.mct_movimientoordentrabajo_seq'), 
		             sp_idordentrabajo, 
		             sp_idhojaruta, 
		             coderoadmaps, 
		             sp_idparte, 
		             idmachines, 
		             idsections, 
		             idactivitys, 
		             sp_idaccion, 
		             now(), 
		             --'', 
		             sp_codigoaccion, 
		             1, -- 1: abierto, 2: cerrado 
		             '', 
		             idoperators,
		             0, 
		             0,
		             idmovetypes,
		             idsubsections,
		             sp_observacion);

END;
$$;


ALTER FUNCTION traking.evtaddworkrecord(idoperators bigint, idsections bigint, idsubsections bigint, idmachines bigint, idmovetypes bigint, idactivitys bigint, idactions bigint, coderoadmaps character varying) OWNER TO postgres;

--
-- TOC entry 2305 (class 1255 OID 16793)
-- Name: evtaddworkrecordmassive(bigint, bigint, bigint, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtaddworkrecordmassive(idoperatorent bigint, idoperatorrec bigint, idsection bigint, requestdate character varying, coderoadmap character varying, actioncode character varying, observation character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idhojaruta					integer;
	    sp_idparte          			integer;
	   	sp_idordentrabajoparte          integer;
	   	sp_idordentrabajo   			integer;
	   	sp_codigoaccion     			varchar;
	   	sp_codigoseccion     			varchar;
	    sp_idaccion                     integer;
	   
	    sp_premec                       varchar;
	    sp_idseccion                    integer;
	   
		sp_idseccion_ant				integer;
		sp_codigoseccion_ant			varchar;
		sp_idaccion_ant					integer;
		sp_estadoactividad_ant			integer;
	    sp_idaccion_salto               integer;
	    sp_texto_accion                 varchar;
	   
	    sp_observacion					varchar;
	   
	    sp_idcomponente                 integer;
	    sp_modalidad                    integer;
	   
begin
	
		sp_codigoaccion  := '';
		sp_codigoseccion := '';
		sp_observacion := '';
	    
		select idaccion 
		  into sp_idaccion
		  from mct_accion 
		 where codigoaccion = actioncode;
		   
		select idhojaruta, 
		       idordentrabajoparte,
		       modalidad
		  into sp_idhojaruta, 
		       sp_idordentrabajoparte,
		       sp_modalidad
		  from mct_hojaruta 
		 where codhojaruta = coderoadmap;
		
		-- Aca extraemos el ultimo trabajo realizado 		                                       
		select a.idseccion, 
		       b.codigoseccion , 
		       a.idaccion , 
		       a.estadoactividad 
		  into sp_idseccion_ant,
		       sp_codigoseccion_ant,
		       sp_idaccion_ant,
		       sp_estadoactividad_ant
		  from mct_movimientoordentrabajo a,
		       mct_seccion b
		 where idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
		                                           from mct_movimientoordentrabajo b 
		                                          where b.idhojaruta = sp_idhojaruta )
		   and a.idseccion = b.idseccion ;		                                         

		  	
		select idparte, 
	           idordentrabajo,
	           idcomponente
	      into sp_idparte, 
	           sp_idordentrabajo,
	           sp_idcomponente
		  from mct_ordentrabajoparte mo 
		 where idordentrabajoparte = sp_idordentrabajoparte;
		  
		sp_observacion := 'Hoja de Ruta : '||coderoadmap;
	    sp_observacion := sp_observacion||observation;

	    if (sp_modalidad = 1) then
            sp_idparte := sp_idcomponente;
        end if;
               
		INSERT INTO traking.mct_movimientoordentrabajo
		            (idmovimientoordentrabajo, 
		             idordentrabajo, 
		             idhojaruta, 
		             codhojaruta, 
		             idparte, 
		             --idmaquina, 
		             idseccion, 
		             --idactividad, 
		             idaccion, 
		             fechainicio,
		             fechafundicion ,
		             fechatermino, 
		             codigoaccion, 
		             estadoactividad, 
		             --numeroinspeccion, 
		             idoperador ,
		             operadorentrega, 
		             operadorrecibe,
		             idmotivocierre ,
		             idcausacierre ,
		             --idtipomovimiento,
		             --idsubseccion,
		             observacion )
		      values
		             (nextval('traking.mct_movimientoordentrabajo_seq'), 
		             sp_idordentrabajo, 
		             sp_idhojaruta, 
		             coderoadmap, 
		             sp_idparte, 
		             --idmachines, 
		             idsection, 
		             --idactivitys, 
		             sp_idaccion, 
		             now(),
		             to_date(requestdate, 'yyyy-mm-dd'),
		             now(),
		             actioncode, 
		             2, -- 1: abierto, 2: cerrado 
		             --'', 
		             idoperatorent,
		             idoperatorent, 
		             idoperatorrec,
		             --idmovetypes,
		             --idsubsections,
		             99,
		             99,
		             sp_observacion);
		            
		    update mct_hojaruta 
		       set fechafundicion = to_date(requestdate, 'yyyy-mm-dd')
		     where codhojaruta = coderoadmap;
		    

END;
$$;


ALTER FUNCTION traking.evtaddworkrecordmassive(idoperatorent bigint, idoperatorrec bigint, idsection bigint, requestdate character varying, coderoadmap character varying, actioncode character varying, observation character varying) OWNER TO postgres;

--
-- TOC entry 2072 (class 1255 OID 16794)
-- Name: evtanalisisdefecto(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtanalisisdefecto(defecto bigint) RETURNS TABLE(analisisdefecto character varying)
    LANGUAGE plpgsql
    AS $$
declare
	strinTmp 		varchar(500) 	= '';
	causa 			varchar(500) 	= '';
	var_record1 	record;
	var_record2 	record;
	indexi			INTEGER = 0;
    fectcausa		INTEGER = -1;
    val_rowSpam     INTEGER = 0;
    respaldo        varchar(500) 	= '';
BEGIN

	FOR var_record1 in (
		select b.iddefectocausa,
		       b.descripcion,
		       c.iddefectocausaaccion,
		       c.descripcion defecaccion,
		       c.fechaejecucion,
		       c.jsonresponsable,
		       traking.evtrespdefecto(c.jsonresponsable) responsable,
		       d.nombrerespaldo,
		       d.nombrearchivo
	   from traking.mct_defectofundicion a
	   left join traking.mct_defectocausa b          on a.iddefectofundicion = b.iddefectofundicion
	   left join traking.mct_defectocausaaccion c    on b.iddefectocausa = c.iddefectocausa
	   left join traking.mct_defectocausaaccionpdf d on c.iddefectocausaaccion = d.iddefectocausaaccion
	   where a.iddefectofundicion = defecto
	   order by b.iddefectocausa asc, c.iddefectocausaaccion  asc, d.iddefectocausaaccionpdf asc

	  )
	  loop
		 if ( fectcausa <> var_record1.iddefectocausa) then 
		 	indexi = 1;
		 	fectcausa := var_record1.iddefectocausa;
		 	causa     := var_record1.descripcion;
		 	respaldo  := '';
			 select count(*) into val_rowSpam
			  	from traking.mct_defectofundicion a
			  	left join traking.mct_defectocausa b          on a.iddefectofundicion = b.iddefectofundicion
			  	left join traking.mct_defectocausaaccion c    on b.iddefectocausa = c.iddefectocausa
			  	left join traking.mct_defectocausaaccionpdf d on c.iddefectocausaaccion = d.iddefectocausaaccion
			  	 where a.iddefectofundicion = defecto and b.iddefectocausa = fectcausa;
			  	
			  FOR var_record2 in (
			   		select d.nombrerespaldo
			  		from traking.mct_defectofundicion a
			  			left join traking.mct_defectocausa b          on a.iddefectofundicion = b.iddefectofundicion
			  			left join traking.mct_defectocausaaccion c    on b.iddefectocausa = c.iddefectocausa
			  			left join traking.mct_defectocausaaccionpdf d on c.iddefectocausaaccion = d.iddefectocausaaccion
			  		 where a.iddefectofundicion = defecto and b.iddefectocausa = fectcausa
			  		 )
			  loop 
			  		respaldo := concat(respaldo,'~',var_record2.nombrerespaldo);
			  end loop;	   
		 else
		    indexi = indexi + 1;
		    causa = '';
		 end if;
	  	 analisisdefecto := concat('{{rowSpan: ',val_rowSpam,',text: ''',indexi,'''},');
	  	 analisisdefecto := concat(analisisdefecto,'{rowSpan:',val_rowSpam,',text: ''',causa,'''},');
	  	 analisisdefecto := concat(analisisdefecto,'{text: ''',indexi,'. ',var_record1.defecaccion,'''},');
	  	 analisisdefecto := concat(analisisdefecto,'{text: ''',var_record1.responsable,   '''},','{text: ''',var_record1.fechaejecucion,'''},','{text: ''',respaldo,'''}}');
	return next;
	  end loop;
END;
$$;


ALTER FUNCTION traking.evtanalisisdefecto(defecto bigint) OWNER TO postgres;

