--
-- TOC entry 1068 (class 1255 OID 16798)
-- Name: evtcalculafechacompra(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtcalculafechacompra(fechas character varying) RETURNS TABLE(fecha character varying, hora character varying, horas bigint)
    LANGUAGE plpgsql
    AS $$
declare

	sp_horas				bigint;
    sp_fechatms				timestamp;
    sp_fecha				varchar;
	intervalo               varchar;

BEGIN

	select round(salhorav) 
      into sp_horas
      from traking.calculahorasincumplimientos_test_v1(fechas::timestamp, 79);
 
    intervalo := ''''||sp_horas||' hours';
   
    select fechas::timestamp + intervalo::interval
      into sp_fechatms;
    
    
    fecha 	:= to_char(sp_fechatms,'dd-mm-yyyy');
    hora 	:= to_char(sp_fechatms,'hh24:mi:ss');
    horas 	:= sp_horas;
         
    RETURN next;


END;
$$;


ALTER FUNCTION traking.evtcalculafechacompra(fechas character varying) OWNER TO postgres;

--
-- TOC entry 1669 (class 1255 OID 16799)
-- Name: evtcreatemailnotif(bigint, bigint, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtcreatemailnotif(ot_in bigint, idsla_in bigint, idordertype bigint, idfamily bigint, idlinedesign bigint, requestdate character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

declare

		sp_date1			DATE;
	    sp_date2			DATE;
		sp_idsla			INTEGER;
		sp_nombresla		VARCHAR(12);
		sp_idestadoinicial	INTEGER;
		sp_idestadofinal	INTEGER;
		sp_escritico		INTEGER;
		sp_diastramo		INTEGER;
		sp_diasinicioaviso	INTEGER;
		sp_reintentos		INTEGER;
		sp_idlista			INTEGER;
		sp_estado			INTEGER;
		sp_fecha            TIMESTAMP;
		rec1 				record;
		sp_dias1            INTEGER;
		sp_dias2            INTEGER;
	    sp_fecha_entrega    varchar;

       -- Para el calculo de la fecha de entrega
        intervalo    			varchar;
        sp_fecha_termino     	varchar;
        sp_fecha_aviso     	    varchar;       
        indice       			integer;
        dias_totales			integer;
        dia_inicial  			integer;	
        dias_totales_inicio		integer;       
       
        sp_fecha_hoy            timestamp=now();
       
       	sp_tipoorden  			integer;
	    sp_idfamilia  			integer;
	    sp_lineadiseno  	    integer;
	   
	    sp_paso_dias            integer;
	    sp_dias_tramo_fab       integer;
	    indice_dias_fab         integer;
	    cuenta_habiles          integer;
	    fecha_paso              timestamp;
	
	    sp_i                    integer;
	    dia_dow                 integer;
	    restar_dias             integer;
	   
begin
	
		sp_i := 1;
	    sp_dias_tramo_fab := 0;
	    cuenta_habiles := 0;
	    restar_dias := 0;
	    fecha_paso := now();
	   
	    if ( requestdate is not null ) then 
	    
	        indice_dias_fab   := date_part('day', to_date(requestdate,'yyyy-mm-dd') - now());
	       
	        while ( sp_i <= indice_dias_fab) loop
	              
	              fecha_paso := fecha_paso + interval '1 day';
	             
	              dia_dow := date_part('dow', fecha_paso);
	              if ( dia_dow in (1,2,3,4,5) ) then
	                  cuenta_habiles := cuenta_habiles + 1;
	              end if;
	              
	              sp_i := sp_i + 1;
	        end loop;
	       	cuenta_habiles := cuenta_habiles + 1;
	        sp_dias_tramo_fab := cuenta_habiles;
	        --sp_dias_tramo_fab := date_part('day', to_date(requestdate,'dd-mm-yyyy') - now());
	        
	    end if;

	  
	   sp_tipoorden   := idordertype;
	   sp_idfamilia   := idfamily;
	   sp_lineadiseno := idlinedesign;	  
	 
	  
	   FOR rec1 IN (   
					SELECT idsla,
						   nombresla,
						   idestadoinicial,
						   idestadofinal,
						   escritico,
						   rembbalinea ,
						   rembbadiseno ,
						   remreplinea ,
						   remrepdiseno ,
						   fabbbalinea ,
						   fabbbadiseno ,
						   fabreplinea ,
						   fabrepdiseno ,
						   inicioaviso ,
						   reintentos,
						   idlista,
						   estado,
						   ordencolumna 
					  FROM traking.mct_sla
				  --ORDER BY idsla
				  order by ordencolumna 
					)
		loop
		
		        -- Para la fecha de termino del tramo
		    	-- Desde aca para calcular las fechas
	            indice       := 1;
                dias_totales := 0;
                sp_diastramo := 0;
                dias_totales_inicio := 0;

			    select date_part('dow', sp_fecha_hoy) into dia_inicial;
			  
			    if (sp_tipoorden in (1,3)) then -- Remanufactura
			        
			       if ( sp_idfamilia in (8, 15) ) then -- Bombas
			           if ( sp_lineadiseno = 2 ) then 
			               sp_diastramo := rec1.rembbalinea; -- De linea
			           else
			           		sp_diastramo := rec1.rembbadiseno; -- De diseño
			           end if;
			       elsif ( sp_idfamilia in (10,11) ) then -- Repuestos
			           if ( sp_lineadiseno = 2 ) then 
			               sp_diastramo := rec1.remreplinea; -- De linea
			           else
			           		sp_diastramo := rec1.remrepdiseno; -- De diseño
			           end if;
			       
			       end if;
			      
			    elsif (sp_tipoorden = 2) then -- Fabricación
			        
			       if ( sp_idfamilia in (8, 15) ) then -- Bombas
			           if ( sp_lineadiseno in ( 2,3) ) then 
			               sp_diastramo := rec1.fabbbalinea; -- De linea
			           else
			           	   sp_diastramo := rec1.fabbbadiseno; -- De diseño
			           end if;
			       elsif ( sp_idfamilia in (10,11) ) then -- Repuestos
			       
			           if ( rec1.idsla = 8 ) then
			           
			              sp_diastramo := sp_dias_tramo_fab - restar_dias;
			           
			           else
			           
				           if ( sp_lineadiseno in ( 2, 3, 4 ) ) then 
				           	   restar_dias  := restar_dias + rec1.fabreplinea;
				               sp_diastramo := rec1.fabreplinea; -- De linea
				           else
				           		restar_dias  := restar_dias + rec1.fabrepdiseno;
				           		sp_diastramo := rec1.fabrepdiseno; -- 
				           end if;
			          
			           end if;

			       
			       end if;
			      
			    end if;
			   
			   
			    --WHILE indice <= rec1.diastramo
			    WHILE indice < sp_diastramo			    
			        LOOP
			
			            if ( dia_inicial < 6 ) then
			               dias_totales := dias_totales + 1;
			               dia_inicial  := dia_inicial + 1;
			               indice       := indice + 1;
			            else
			               dia_inicial  := 1;
			               dias_totales := dias_totales + 2;
			            end if;
			
			        END LOOP;
				
			    if ( sp_diastramo > 0 ) then

				    if ( dia_inicial < 5 ) then
		
				         dias_totales := dias_totales + 1;
		              
				    end if;		                   
				    if ( dia_inicial = 5 ) then
		
				         dias_totales := dias_totales + 3;
		              
				    end if;
				   	if ( dia_inicial > 5 ) then
		
				         dias_totales := dias_totales + 2;
		              
				    end if;
			   
			    end if;

			      
				intervalo := ''''||dias_totales||' day';
				
				select to_char(sp_fecha_hoy + intervalo::interval, 'dd-mm-yyyy') into sp_fecha_termino;
			    -- aca termina el proceso
    
			dias_totales_inicio := (sp_diastramo * rec1.inicioaviso)/100;
		
            -- Para la fecha de inicio del aviso
			-- Desde aca para calcular las fechas
			indice       := 1;
		    dias_totales := 0;
		
		    select date_part('dow', sp_fecha_hoy) into dia_inicial;		   
			       
		    WHILE indice < dias_totales_inicio		    
		    
		        LOOP
		
		            if ( dia_inicial < 6 ) then
		               dias_totales := dias_totales + 1;
		               dia_inicial  := dia_inicial + 1;
		               indice       := indice + 1;
		            else
		               dia_inicial  := 1;
		               dias_totales := dias_totales + 2;
		            end if;
		
		        END LOOP;
			
		                   
			    if ( sp_diastramo > 0 ) then

				    if ( dia_inicial < 5 ) then
		
				         dias_totales := dias_totales + 1;
		              
				    end if;		                   
				    if ( dia_inicial = 5 ) then
		
				         dias_totales := dias_totales + 3;
		              
				    end if;
				   	if ( dia_inicial > 5 ) then
		
				         dias_totales := dias_totales + 2;
		              
				    end if;
			   
			    end if;
		      
			intervalo := ''''||dias_totales||' day';
			
			select to_char(sp_fecha_hoy + intervalo::interval, 'dd-mm-yyyy') into sp_fecha_aviso;
		    -- aca termina el proceso    

		
		    if ( sp_tipoorden = 7 ) then
		    
			   	  if ( rec1.idsla in (2,10,3,4,5,6) ) then
				
				      insert into mct_progavisos 
				               (
								idordentrabajo,
								idsla,
								fecha_inicio,
								fecha_termino,
								fecha_inicio_aviso,
								dias_tramo,
								nro_alarmas_enviada,
								reintentos,
								idlista,
								estado,
								fecha_real_termino,
								ordenproceso
								)
						VALUES (
								ot_in,
								rec1.idsla,
								sp_fecha_hoy,
								to_date(sp_fecha_termino,'dd-mm-yyy'),
								to_date(sp_fecha_aviso,'dd-mm-yyy'),						
								sp_diastramo,
								0,
								rec1.reintentos,
								rec1.idlista,
								1,
								now(),
								rec1.ordencolumna
							   );
				  
							  
				  end if;
		    
			elsif ( sp_tipoorden = 2 ) then
			
			   if (sp_idfamilia in (8, 10) ) then
			   
			        if ( rec1.idsla in (2,10,3,4,5,6) ) then
			        
					      insert into mct_progavisos 
					               (
