								to_date(sp_fecha_termino,'dd-mm-yyy'),
								to_date(sp_fecha_aviso,'dd-mm-yyy'),						
								sp_diastramo,
								0,
								rec1.reintentos,
								rec1.idlista,
								0,
								now(),
								rec1.ordencolumna
							   );			        
			        end if;			
			   
			   
			   elsif ( sp_idfamilia in (14, 15) ) then
			   
			        if ( rec1.idsla in (2,3,4,5,6,7) ) then
			        
					      insert into mct_progavisos 
