									sp_fecha_hoy,
									to_date(sp_fecha_termino,'dd-mm-yyy'),
									to_date(sp_fecha_aviso,'dd-mm-yyy'),						
									sp_diastramo,
									0,
									rec1.reintentos,
									rec1.idlista,
									1,
									now(),
									rec1.ordencolumna
								   );			        
			        
			        else

				        	insert into mct_progavisos 
					               (
									idordentrabajo,
									idsla,
									fecha_inicio,
									fecha_termino,
									fecha_inicio_aviso,
									dias_tramo,
									nro_alarmas_enviada,
									reintentos,
									idlista,
									estado,
									ordenproceso
									)
							VALUES (
									ot_in,
									rec1.idsla,
									sp_fecha_hoy,
									to_date(sp_fecha_termino,'dd-mm-yyy'),
									to_date(sp_fecha_aviso,'dd-mm-yyy'),						
									sp_diastramo,
									0,
									rec1.reintentos,
									rec1.idlista,
									0,
									rec1.ordencolumna
								   );
							  
			        end if;
		
			   else
			   
			        if ( sp_idfamilia in (10,11)) then
			        
					   	  --if ( rec1.idsla in (2,10,3,4,5,6,7,8) ) then
					   	  if ( rec1.idsla in (2,10,3,4,5,6) ) then
						
						      insert into mct_progavisos 
