	--  where idordentrabajo = ot_in;
    
    return sp_fecha_termino;
    --return dia_dow;

END;
$$;


ALTER FUNCTION traking.evtcreatemailnotif(ot_in bigint, idsla_in bigint, idordertype bigint, idfamily bigint, idlinedesign bigint, requestdate character varying) OWNER TO postgres;

--
-- TOC entry 925 (class 1255 OID 16801)
-- Name: evtdefectofundicionkpi(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtdefectofundicionkpi(startdate character varying, enddate character varying, idusers bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	sp_totaldefectos		bigint	:= 0;
    sp_totaldefectosV		bigint	:= 0;
   
    sp_totaldefectosET		bigint	:= 0;
    sp_totalaccionesmes		bigint	:= 0;
    
    sp_totalaccionesmesET	bigint	:= 0;
   
    sp_sumareincidencia		bigint	:= 0;
   
    sp_porcentajeRein		bigint	:= 0;
   
    sp_horas				bigint	:= 0;
   
    sp_porcentajeValET		numeric	:= 0;
   
    sp_porcentajeActET		numeric	:= 0;
    sp_notafinal			numeric	:= 0;
   
	rec_reinc      			RECORD;
	rec_trab       			RECORD;

	sp_lista				varchar;

    sp_suma					bigint	:= 0;
   
    sp_porcentaje1			numeric	:= 0; -- por cantidad de defectos
    sp_porcentaje2			numeric	:= 0;
    sp_porcentaje33			numeric	:= 0;
    sp_porcentaje3			numeric	:= 0;
    sp_porcentaje4			numeric	:= 0;
    sp_porcentaje5			numeric	:= 0;
   
    sp_porcentot			numeric	:= 0;
   
    sp_sq					numeric	:= 0;
   
    sp_stringporcentaje		varchar	:= '';
   
    sp_valor1				bigint	:= 0;
    sp_valor2				bigint	:= 0;
    sp_valor3				bigint	:= 0;
   
    sp_defporanalizar		bigint	:= 0;
	sp_porcdefporanalizar	bigint	:= 0;
   
   	sp_defnoanalizadosant		bigint	:= 0;
    sp_porcdefnoanalizadosant	bigint	:= 0;
  
    sp_totalperiodoant		bigint	:= 0;
   
    sp_mindefecto			bigint	:= 0;
    sp_mincorr				bigint	:= 0;
    sp_minfecha				varchar	:= '';
   
	   
begin
	
	-- Defectos Levantados en el Periodo anterior
	select coalesce(count(*),0), min(a.iddefectofundicion) 
	  into sp_defnoanalizadosant,
	       sp_mindefecto
	  from mct_defectofundicion a,
	       mct_componente b
	--where a.fechavencimiento >= TO_TIMESTAMP('2023-08-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP('2023-08-31'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
	where a.fechacreacion >= TO_TIMESTAMP('2023-04-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') --and a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
  	  and a.idcomponente = b.idcomponente
  	  --and to_char(a.fechacreacion,'mm') = '04'
      and b.idresponsablefundicion = idusers
      and a.defectovalidado is false;
 
    select b.correlativo,
           to_char(b.fechacreacion, 'dd-mm-yyyy')
      into sp_mincorr,
           sp_minfecha
      from mct_defectofundicion b 
     where b.iddefectofundicion = sp_mindefecto;
   
	-- Defectos Levantados en el Periodo 
	select coalesce(count(*),0)  
	  into sp_totaldefectos
	  from mct_defectofundicion a,
	       mct_componente b
	--where a.fechavencimiento >= TO_TIMESTAMP('2023-08-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP('2023-08-31'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
	where a.fechavencimiento >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
  	  and a.idcomponente = b.idcomponente 
      and b.idresponsablefundicion = idusers;
     
    if (sp_totaldefectos = 0) then
    
    	sp_porcentaje1	:= 100 * 0.20;
        sp_valor1		:= 100;
    	
    elseif (sp_totaldefectos <= 10) then
    
    	sp_porcentaje1	:= 50 * 0.20;
        sp_valor1		:= 50;
       
    else
    
    	sp_porcentaje1	:= 0;
        sp_valor1		:= 0;
    
    end if;
--	raise notice '%', sp_totaldefectos;
							
	sp_lista := '';
    sp_suma	 := 0;
		
    -- Piezas con Reincidencia de Defectos
	FOR rec_reinc IN (   
			select count(*) as cantidad,a.nombreplano, a.idcomponente, c.nombrecomponente
			  from mct_defectofundicion a,
			       mct_parte b,
			       mct_componente c
			--where a.fechavencimiento >= TO_TIMESTAMP('2023-08-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP('2023-08-31'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
			--where a.fechavencimiento >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
            where a.fechavencimiento >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
			  and a.idcomponente = b.idparte 
			  and a.idcomponente = c.idcomponente
			  and c.idresponsablefundicion = idusers
			group by a.nombreplano, a.idcomponente, c.nombrecomponente
			having count(*) > 1
			)
	    loop 	
						
		    sp_lista := sp_lista||rec_reinc.nombreplano||' '||rec_reinc.nombrecomponente||'('||rec_reinc.cantidad||')'||E'\n';
		   
		    sp_sumareincidencia	:= sp_sumareincidencia + rec_reinc.cantidad;
		   
		    sp_suma	:= sp_suma + 1;
				           
	END LOOP;

    -- Aca calcula el % de incidencia
    if (sp_sumareincidencia = 0) then
    	sp_porcentajeRein	:= 0;
    	sp_porcentaje2		:= 100 * 0.10;
        sp_valor2			:= 100;
    elsif (sp_sumareincidencia = 1) then
    	sp_porcentajeRein	:= round((sp_sumareincidencia * 100) / sp_totaldefectos);	
        sp_porcentaje2		:= 50 * 0.10;
        sp_valor2			:= 50;
    elsif (sp_sumareincidencia > 0) then
    	sp_porcentajeRein	:= round((sp_sumareincidencia * 100) / sp_totaldefectos);	
        sp_porcentaje2		:= 0 * 0.10;
        sp_valor2			:= 0;
    end if;

       -- Aca calcula el % de incidencia
    if (sp_defnoanalizadosant = 0) then
    	sp_porcentaje33		:= 100 * 0.10;
        sp_valor3			:= 0;
    elsif (sp_defnoanalizadosant > 0) then
        sp_porcentaje33		:= 0 * 0.10;
        sp_valor3			:= 0;
    end if;
   
    -- Saca todos los Defectos Analizados y Subidos a Sistema	
	select count(*)
	  into sp_totaldefectosV
	  from mct_defectofundicion a,
	       mct_componente b
	 --where a.fechacreacion >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
	 --where a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
     where a.fechavencimiento >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
	   and a.defectovalidado is true
	   and a.idcomponente = b.idcomponente
	   and b.idresponsablefundicion = idusers;
	  
	-- Defectos Analizados en tiempo programado
	FOR rec_reinc IN (   
			select a.fechavalidaciondefecto, a.fechacreacion ,
			       date_part('dow', b.fechacreacion) as diasem,
			       cast((date_part('day', a.fechavalidaciondefecto::timestamp - a.fechacreacion::timestamp ) * 1440 + 
						 date_part('hour', a.fechavalidaciondefecto::timestamp - a.fechacreacion::timestamp ) * 60 + 
						 date_part('minute', a.fechavalidaciondefecto::timestamp - a.fechacreacion::timestamp )) as integer)/60 as tiempo
			  from mct_defectofundicion a,
			       mct_auditoriadefectovalido b,
				       mct_componente c
			 --where a.fechavencimiento >= TO_TIMESTAMP('2023-08-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP('2023-08-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
	         where a.fechavencimiento >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
               and a.defectovalidado is true  
			   and a.iddefectofundicion = b.iddefectofundicion 
			   and a.idcomponente = c.idcomponente
			   and c.idresponsablefundicion = idusers

			)
	    loop 	
		    
		   	sp_horas	:= 72;
		   
		    if (rec_reinc.diasem = 5) then
		        sp_horas = 144;
		    elsif (rec_reinc.diasem = 4) then
		           sp_horas = 120;
		    elsif (rec_reinc.diasem = 3) then
		           sp_horas = 120;
		    end if;
		   
		    if (rec_reinc.tiempo <= sp_horas) then
		    	sp_totaldefectosET	:= sp_totaldefectosET + 1;
			end if;	

	END LOOP;

    -- Total acciones levantadas en el mes
	select coalesce(count(*),0)
	  into sp_totalaccionesmes
	  from mct_defectocausaaccion a ,
	       mct_defectocausa b,
	       mct_defectofundicion c,
	       mct_componente d
	 --where a.fechacreacion >= TO_TIMESTAMP('2023-08-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP('2023-08-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
	 where a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
       and a.iddefectocausa = b.iddefectocausa 
	   and b.iddefectofundicion = c.iddefectofundicion 
	   and c.idcomponente = d.idcomponente
	   and d.idresponsablefundicion = idusers;


	-- Total acciones subidas en tiempo en el mes
	select coalesce(count(*),0)
	  into sp_totalaccionesmesET
	  from mct_defectocausaaccion a,
	       mct_defectocausaaccionpdf b,
	       mct_defectocausa c,
	       mct_defectofundicion d,
	       mct_componente e
	 --where a.fechacreacion >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
	 where a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
       and a.iddefectocausaaccion = b.iddefectocausaaccion
	   and b.fechamodificacion <= a.fechaejecucion 
	   and a.iddefectocausa = c.iddefectocausa 
	   and c.iddefectofundicion = d.iddefectofundicion 
	   and d.idcomponente = e.idcomponente 
	   and e.idresponsablefundicion = idusers;

    -- Saca todos los Defectos Analizados y Subidos a Sistema	
	select round(sum(nota)/coalesce(count(*),0),1)
	  into sp_notafinal
	  from mct_defectofundicion a,
	       mct_componente b
	 --where a.fechacreacion >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
     where a.fechavencimiento >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
       and a.defectovalidado is true
	   and a.idcomponente = b.idcomponente
	   and b.idresponsablefundicion = idusers;	  
	  
	sp_porcentajeValET	:= round((sp_totaldefectosET * 100) / sp_totaldefectos);

    sp_sq				:= (sp_totaldefectosV * 100) / sp_totaldefectos ;
   
    raise notice '%', sp_totaldefectosV||'-'||sp_totaldefectos||'-'||sp_sq;

    sp_porcentajeActET	:= round((sp_totalaccionesmesET * 100) / sp_totalaccionesmes);
  
    sp_porcentaje3	:= sp_porcentajeValET * 0.20;
    sp_porcentaje4	:= sp_porcentajeActET * 0.20;
    sp_porcentaje5	:= sp_notafinal * 0.20;
   
    sp_porcentot	:= round((coalesce(sp_porcentaje1,0) + coalesce(sp_porcentaje2,0) + coalesce(sp_porcentaje3,0) + coalesce(sp_porcentaje4,0) + coalesce(sp_porcentaje5,0)), 2);
   
    raise notice '%', coalesce(sp_porcentaje1,0)||'-'||coalesce(sp_porcentaje2,0)||'-'||coalesce(sp_porcentaje3,0)||'-'||coalesce(sp_porcentaje4,0)||'-'||coalesce(sp_porcentaje5,0);
    raise notice '%', sp_porcentot;
   
   	sp_stringporcentaje	:= coalesce(sp_valor1,0)||'~'||
                           coalesce(sp_valor2,0)||'~'||
                           coalesce(sp_valor3,0)||'~'||
                           coalesce(sp_porcentajeValET,0)||'~'||
                           coalesce(sp_porcentajeActET,0)||'~'||
                           coalesce(sp_notafinal,0);

    raise notice '%', coalesce(sp_stringporcentaje,'xx');

   
    sp_porcdefporanalizar		:= round(((sp_totaldefectos-sp_defnoanalizadosant) * 100) / sp_totaldefectos);	
    sp_porcdefnoanalizadosant	:= round((sp_defnoanalizadosant * 100) / sp_totaldefectos);	
       
    return cast(coalesce(sp_totaldefectos,0)||':100~'||
                coalesce(sp_totaldefectos,0)-coalesce(sp_totaldefectosV,0)||':'||100-coalesce(sp_sq,0)||'~'||
                coalesce(sp_defnoanalizadosant,0)||':'||coalesce(sp_porcdefnoanalizadosant,0)||'~'||
                coalesce(sp_suma,0)||'~'||sp_lista||'~'||
                coalesce(sp_sumareincidencia,0)||':'||coalesce(sp_porcentajeRein,0)||'~'||
                coalesce(sp_totaldefectosV,0)||':'||coalesce(sp_sq,0)||'~'||
                coalesce(sp_totaldefectosET,0)||':'||coalesce(sp_porcentajeValET,0)||'~'||
                coalesce(sp_totalaccionesmes,0)||':100~'||
                coalesce(sp_totalaccionesmesET,0)||':'||coalesce(sp_porcentajeActET,0)||'~'||
                coalesce(sp_notafinal,0)||'~'||coalesce(sp_porcentot,0)||'#'||         
                --sp_porcentajeRein*0.25||'~0~70~50~75' as varchar
                sp_stringporcentaje||'#'|| 
                sp_mincorr||'~'||sp_minfecha as varchar
               );
	
END;
$$;


ALTER FUNCTION traking.evtdefectofundicionkpi(startdate character varying, enddate character varying, idusers bigint) OWNER TO postgres;

--
-- TOC entry 2102 (class 1255 OID 16803)
-- Name: evtdefectojsontostring(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtdefectojsontostring(jsonelemento character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
	strinTmp 		varchar(500) 	= '';
	var_record1 	record;
			  
BEGIN 

	FOR var_record1 in (
           select replace(replace(replace(replace(regexp_split_to_table,'"name":',''),'"',''),'}',''),']','') as texto 
             from regexp_split_to_table(jsonelemento,',') 
            where regexp_split_to_table like '%name%'
           )
     loop
     	strinTmp := CONCAT(strinTmp,var_record1.texto,E'\n');
     end loop;
    
	 return substring(strinTmp,1,length(strinTmp)-1);
	
END			
$$;


ALTER FUNCTION traking.evtdefectojsontostring(jsonelemento character varying) OWNER TO postgres;

