--
-- TOC entry 878 (class 1255 OID 16812)
-- Name: evtdetailot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtdetailot(idot bigint) RETURNS TABLE(nombreordentrabajo character varying, nombrecliente character varying, nombreproducto character varying, fechaentrega timestamp without time zone, fecharecepcion timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
		
		  select a.nombreordentrabajo,  
			b.nombrecliente, 
			c.nombreproducto, 
			a.fechaentrega, 
			a.fecharecepcion
			from mct_ordentrabajo a
			LEFT JOIN mct_cliente  b    ON ( b.idcliente = a.idcliente)
			LEFT JOIN mct_producto c ON ( c.idproducto = a.idproducto)
			WHERE a.idordentrabajo= idot;
END;
$$;


ALTER FUNCTION traking.evtdetailot(idot bigint) OWNER TO postgres;

--
-- TOC entry 1743 (class 1255 OID 16813)
-- Name: evtevaluadoreskpi(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtevaluadoreskpi(startdate character varying, enddate character varying, idusers bigint) RETURNS TABLE(item bigint, ot bigint, equipo character varying, cliente character varying, informe_r character varying, informe_t character varying, validacheck character varying, entrega_cp character varying, informe_f character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

   
	rec_trab       	RECORD;
    sp_ir			varchar;
   	sp_it			varchar;
   	sp_check		varchar;
   	sp_cp			varchar;
   	sp_if			varchar;
   
   	sp_total_ir		bigint	:= 0;
    sp_total_it		bigint	:= 0;
    sp_total_check	bigint	:= 0;
    sp_total_pl		bigint	:= 0;
    sp_total_if		bigint	:= 0;
   
   	sp_si_ir		bigint	:= 0;
   	sp_no_ir		bigint	:= 0;
  
   	sp_si_it		bigint	:= 0;
   	sp_no_it		bigint	:= 0;
   
    sp_si_check		bigint	:= 0;
   	sp_no_check		bigint	:= 0;
   
    sp_si_pl		bigint	:= 0;
   	sp_no_pl		bigint	:= 0;
   
    sp_si_if		bigint	:= 0;
   	sp_no_if		bigint	:= 0;
   
    sp_sumamail_ir	bigint	:= 0;
    sp_sumamail_it	bigint	:= 0;
    sp_sumamail_pl	bigint	:= 0;
    sp_sumamail_if	bigint	:= 0;
    sp_sumamail_check	bigint	:= 0;
   
    sp_divide_ir	bigint	:= 0;
    sp_divide_it	bigint	:= 0;
    sp_divide_pl	bigint	:= 0;
    sp_divide_if	bigint	:= 0;
    sp_divide_check	bigint	:= 0;
   
    sp_evaluados	bigint	:= 0;
    sp_meses		bigint	:= 0;
   
    prom1			numeric	:= 0;
    prom2			numeric	:= 0;
    prom3			numeric	:= 0;
    prom4			numeric	:= 0;
    prom5			numeric	:= 0;
   
    salida			numeric	:= 0;
   
    sp_horasir		bigint	:= 0;
   
    sp_evair		numeric	:= 0;
    sp_evait		numeric	:= 0;
    sp_evacheck		numeric	:= 0;
    sp_evacp		numeric	:= 0;
    sp_evaif		numeric	:= 0;
   	   
begin
	
	
    -- Extrae las OT de Bombas para el analisis
	FOR rec_trab IN (   			
			select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo asc) AS item,
			       a.idordentrabajo,
			       a.idestadoorden,
			       a.idfamilia,					       
				   d.sigla||'_'||e.sigla as sigla,
				   a.idproducto,
                   h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
				   b.nombrecorto ,
				   j.nombre ,
				   a.fechadespacho,
				   a.checklistvalido ,
				   case
					   when a.checklistvalido is true then
					   		'SI'
					   else
					   		'NO'
				   end as checkvalido,
				   a.fecharecepcion 
			  from mct_ordentrabajo a
			  left join  mct_cliente b         		 on a.idcliente = b.idcliente
			  left join  mct_producto c        		 on a.idproducto = c.idproducto 
			  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
			  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
			  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j               on a.idusuario = j.idusuario
			 where a.idusuario = idusers
			   and a.idfamilia = 8
			   and a.debaja < 1
			   and (a.fecharecepcion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fecharecepcion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   
			)
	    loop 	

			-- Informe Recepcion
		    select case 
			          when a.estado = 1 then
			               'SI'
			          else
			               'NO'
			       end as infrec,
			       coalesce(round(( EXTRACT(EPOCH FROM a.fecha_real_termino::timestamp)-EXTRACT(EPOCH FROM rec_trab.fecharecepcion::timestamp)) / 3600),0)
			  into sp_ir,
			       sp_horasir
		      from mct_progavisos  a
		     where a.idordentrabajo = rec_trab.idordentrabajo
		       and a.idsla = 10;
		      
		    if (sp_ir = 'SI' and sp_horasir > 24) then
		    	sp_ir	:= 'NO';
		    end if;
		   
		    --raise notice '%', 'Horas IR son-'||sp_horasir;
		      
			-- Informe Tecnico
		    select case 
			          when estado = 1 then
			               'SI'
			          else
			               'NO'
			          end as inftec
			  into sp_it
		      from mct_progavisos 
		     where idordentrabajo = rec_trab.idordentrabajo
		       and idsla = 3;
		      
			-- Entrega Plano
		    select case 
			          when estado = 1 then
			               'SI'
			          else
			               'NO'
			          end as entpla
			  into sp_cp
		      from mct_progavisos 
		     where idordentrabajo = rec_trab.idordentrabajo
		       and idsla = 7;
		      
			-- Informe Final
		    select case 
			          when estado = 1 then
			               'SI'
			          else
			               'NO'
			          end as entpla
			  into sp_if
		      from mct_progavisos 
		     where idordentrabajo = rec_trab.idordentrabajo
		       and idsla = 7;

		    -- Informe Final
			select case
				      when coalesce (count(*),0) > 0 then
				           'SI'
				      else
				      	   'NO'
				   end
			  into sp_if
			  from mct_infcotipdf mi 
			 where idordentrabajo = rec_trab.idordentrabajo
			   and nombrearchivo like 'IF_OT%';
			  
			  
			-- Revalida checklist por auditoria de mail
			select coalesce(sum(contador),0)
			  into sp_sumamail_check
			  from mct_auditoriachecklistvalido
			 where idordentrabajo = rec_trab.idordentrabajo;

			sp_total_check	:= sp_total_check + sp_sumamail_check;
			if (sp_sumamail_check > 0) then
				rec_trab.checkvalido	:= 'NO';
			end if;
		
			-- Revalida inf. Recep por auditoria de mail
			select coalesce(sum(contador),0) 
			  into sp_sumamail_ir
			  from mct_auditoriaincumplimiento
			 where idordentrabajo = rec_trab.idordentrabajo
			   and idnotificacion = 76;
			
			sp_total_ir	:= sp_total_ir + sp_sumamail_ir;
			if (sp_sumamail_ir > 0) then
				sp_ir	:= 'NO';
			end if;

			-- Revalida inf. Tenico por auditoria de mail
			select coalesce(sum(contador),0) 
			  into sp_sumamail_it
			  from mct_auditoriaincumplimiento
			 where idordentrabajo = rec_trab.idordentrabajo
			   and idnotificacion = 77;
			
			sp_total_it	:= sp_total_it + sp_sumamail_it;
			if (sp_sumamail_it > 0) then
				sp_it	:= 'NO';
			end if;
		
			-- Revalida Carp. Plano por auditoria de mail
			select coalesce(sum(contador),0) 
			  into sp_sumamail_pl
			  from mct_auditoriaincumplimiento
			 where idordentrabajo = rec_trab.idordentrabajo
			   and idnotificacion = 78;
			
			sp_total_pl	:= sp_total_pl + sp_sumamail_pl;
			if (sp_sumamail_pl > 0) then
				sp_cp	:= 'NO';
			end if;
	
			-- Revalida Carp. Plano por auditoria de mail
			select coalesce(sum(contador),0) 
			  into sp_sumamail_if
			  from mct_auditoriaincumplimiento
			 where idordentrabajo = rec_trab.idordentrabajo
			   and idnotificacion = 81;
			
			sp_total_if	:= sp_total_if + sp_sumamail_if;
			if (sp_sumamail_if > 0) then
				sp_if	:= 'NO';
			end if;
		
		    if (sp_ir = 'SI') then
		    	sp_si_ir	:= sp_si_ir + 1;
		    else
		    	sp_no_ir	:= sp_no_ir + 1;
		    end if;
		
		    if (sp_it = 'SI') then
		    	sp_si_it	:= sp_si_it + 1;
		    else
		    	sp_no_it	:= sp_no_it + 1;
		    end if;		   

		    if (coalesce(rec_trab.checkvalido,'SI') = 'SI') then
		    	sp_si_check	:= sp_si_check + 1;
		    else
		    	sp_no_check	:= sp_no_check + 1;
		    end if;	
		   
		    if (sp_cp = 'SI') then
		    	sp_si_pl	:= sp_si_pl + 1;
		    else
		    	sp_no_pl	:= sp_no_pl + 1;
		    end if;	
		    
		    if (sp_if = 'SI') then
		    	sp_si_if	:= sp_si_if + 1;
		    else
		    	sp_no_if	:= sp_no_if + 1;
		    end if;
		   
		    item 		:= rec_trab.item; 
	        ot 			:= rec_trab.idordentrabajo;
	        equipo 		:= rec_trab.producto; 
	        cliente 	:= rec_trab.nombrecorto;
	        informe_r 	:= sp_ir; 
	        informe_t 	:= sp_it;
	        validacheck := coalesce(rec_trab.checkvalido,'SI');
	        entrega_cp 	:= sp_cp; 
	        informe_f 	:= sp_if;
	       
	       return next;
       	       
       
	END LOOP;

    raise notice '%', item;
    sp_evaluados	:= item;

    prom1		:= round((sp_si_ir*100) / (sp_si_ir + sp_no_ir));
    prom2		:= round((sp_si_it*100) / (sp_si_it + sp_no_it));
    prom3		:= round((sp_si_check*100) / (sp_si_check + sp_no_check));
    prom4		:= round((sp_si_pl*100) / (sp_si_pl + sp_no_pl));
    prom5		:= round((sp_si_if*100) / (sp_si_if + sp_no_if));
   
   	item 		:= -1; 
    ot 			:= 0;
    equipo 		:= '%CUMPLIMIENTO KPIs'; 
    cliente 	:= '';
    informe_r 	:= prom1; 
    informe_t 	:= prom2;
    validacheck := prom3;
    entrega_cp 	:= prom4; 
    informe_f 	:= prom5;

    raise notice '%', sp_si_ir||'-'||(sp_si_ir + sp_no_ir)::numeric;
    raise notice '%', sp_si_it||'-'||(sp_si_it + sp_no_it)::numeric;
    raise notice '%', sp_si_check||'-'||(sp_si_check + sp_no_check)::numeric;
    raise notice '%', sp_si_pl||'-'||(sp_si_pl + sp_no_pl)::numeric;
    raise notice '%', sp_si_if||'-'||(sp_si_if + sp_no_if)::numeric;
   
    return next;
  
   	item 		:= -2; 
    ot 			:= 0;
    equipo 		:= 'PROMEDIO MAILS INCUMPLIMIENTOS'; 
    cliente 	:= '';
    informe_r 	:= sp_total_ir; 
    informe_t 	:= sp_total_it;
    validacheck := sp_total_check;
    entrega_cp 	:= sp_total_pl; 
    informe_f 	:= sp_total_if;

    return next;
	
    select (date_part('year', age) * 12) + date_part('month', age)
      into sp_meses
	  from (select age(enddate::date, startdate::date)) foodate;
	  
	salida	:= (sp_evaluados::numeric / sp_meses::numeric);
	raise notice '%', sp_meses;
    raise notice '%', round(salida,2);

    sp_evair	:= (prom1::numeric * 0.05);
    sp_evait	:= (prom2::numeric * 0.3);
    sp_evacheck	:= (prom3::numeric * 0.3);
    sp_evacp	:= (prom4::numeric * 0.25);
    sp_evaif	:= (prom5::numeric * 0.1);
   
   	item 		:= -3; 
    ot 			:= 0;
    equipo 		:= 'footer'; 
    cliente 	:= '';
    informe_r 	:= sp_evaluados; 
    informe_t 	:= sp_meses+1;
    validacheck := round(salida,2);
    --entrega_cp 	:= round((prom1 + prom2 + prom3 + prom4 + prom5) / 5); 
    entrega_cp 	:= round((sp_evair + sp_evait + sp_evacheck + sp_evacp + sp_evaif));
    informe_f 	:= round((sp_total_ir + sp_total_it + sp_total_check + sp_total_pl + sp_total_if) / 5);

    return next;
   
END;
$$;


ALTER FUNCTION traking.evtevaluadoreskpi(startdate character varying, enddate character varying, idusers bigint) OWNER TO postgres;

