--
-- TOC entry 1566 (class 1255 OID 16820)
-- Name: evtgeneratekeyrecuppass(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgeneratekeyrecuppass(userup character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
       sp_password 	  VARCHAR(10);
	   sp_mail        VARCHAR;
	   sp_asunto      varchar;
	   sp_cuerpo      varchar;
	   sp_fecha_hoy   varchar=to_char(now(),'DD-MM-YYYY hh24:mi');
BEGIN
			
     IF (SELECT 1 
           FROM traking.mct_usuario
          WHERE usuario = userup ) THEN
				 
		 SELECT email 
		   INTO sp_mail 
		   FROM traking.mct_usuario
          WHERE usuario = userup;
         
		 SELECT array_to_string(ARRAY(SELECT chr((48 + round(random() * 9)) :: integer) 
		   INTO sp_password 				
		   FROM generate_series(1,10)), '');
		  
		 sp_password := '0000000000';
		  
		 select asunto,
	            REPLACE(REPLACE(cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_clave',sp_password) as cuerpo
	       into sp_asunto,
	            sp_cuerpo
		   from mct_cuerpomensaje
		  where idnotificacion = 14;
					
		 UPDATE traking.mct_usuario 	
			SET	"password" =  sp_password
		  WHERE usuario=userup;
					
		 RETURN CONCAT('0#',sp_password,'#',sp_mail,'#',sp_asunto,'#',sp_cuerpo);										
	 
	 else
	 
		RETURN '1:Usuario no registrado';
	 
	 END IF;

		
END;
$$;


ALTER FUNCTION traking.evtgeneratekeyrecuppass(userup character varying) OWNER TO postgres;

--
-- TOC entry 2381 (class 1255 OID 16821)
-- Name: evtgetareasimputacionrechazo(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetareasimputacionrechazo() RETURNS TABLE(idareaimputacionrechazo bigint, codigo integer, area character varying, requieresubarea boolean, idsubareaimputacionrechazo bigint, subarea character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

    SELECT
        a.idareaimputacionrechazo,
        a.codigo,
        a.nombre::varchar AS area,
        a.requieresubarea,
        s.idsubareaimputacionrechazo,
        s.nombre::varchar AS subarea

    FROM mct_areaimputacionrechazo a

    LEFT JOIN mct_subareaimputacionrechazo s
           ON s.idareaimputacionrechazo =
              a.idareaimputacionrechazo
          AND s.activo = true

    WHERE a.activo = true

    ORDER BY
        a.codigo,
        s.idsubareaimputacionrechazo;

END;
$$;


ALTER FUNCTION traking.evtgetareasimputacionrechazo() OWNER TO postgres;

--
-- TOC entry 896 (class 1255 OID 16822)
-- Name: evtgetcantidadciclos(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetcantidadciclos(ots bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
	    arreglo     varchar[];
	   
	    textoin     varchar;
	    sp_salir    bigint;   
	    sale		bigint;
	    sel_ot		bigint;
	    ot_ant		bigint;
	   	tot_ciclo	bigint;
	   
begin

	--delete from mct_relacionotciclo where mct_relacionotciclo.ot = ots; 
	    
   	sale 	:= 0;
   	sel_ot	:= ots;
   
   --	insert into mct_relacionotciclo values (ot);
  
   	while sale = 0 loop
   	
   	    if (select 1 from mct_ordentrabajo
		     where idordentrabajo = sel_ot) then 
		 
		 select coalesce (idordentrabajoanterior, 0)
		   into ot_ant
		   from mct_ordentrabajo
		  where idordentrabajo = sel_ot;
		 
		else 
			ot_ant 	:= 0;
			sale	:= 1;
		end if;
		 
		if sale = 0 then

			if ot_ant > 0 then
			
			    if (select 1
			          from mct_relacionotciclo
			         where ot = ots
			           and otanterior = ot_ant
			           and pantalla = 'rep') then
			           
			    else
			   	    insert into mct_relacionotciclo values (ots, ot_ant, 'rep');
			
			   	end if;
			   	   
			    sel_ot	:= ot_ant;
			    ot_ant	:= 0;
			else
				sale := 1;
			end if;		
		
		end if;

		 
	end loop;

	tot_ciclo	:= 0;

    select count(*)
      into tot_ciclo
      from mct_relacionotciclo
     where ot = ots;
	
	RETURN tot_ciclo;

END;
$$;


ALTER FUNCTION traking.evtgetcantidadciclos(ots bigint) OWNER TO postgres;

--
-- TOC entry 985 (class 1255 OID 16823)
-- Name: evtgetcantidadcicloshist(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetcantidadcicloshist(ots bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
	    arreglo     varchar[];
	   
	    textoin     varchar;
	    sp_salir    bigint;   
	    sale		bigint;
	    sel_ot		bigint;
	    ot_ant		bigint;
	   	tot_ciclo	bigint;
	   	primero		bigint;
	   
begin

	--delete from mct_relacionotciclo where mct_relacionotciclo.ot = ots; 
	    
   	sale 	:= 0;
   	sel_ot	:= ots;
    primero	:= 0;
  
   	while sale = 0 loop
   	
   	    if (select 1 from mct_ordentrabajo
		     where idordentrabajo = sel_ot) then 
		 
		 select coalesce (idordentrabajoanterior, 0)
		   into ot_ant
		   from mct_ordentrabajo
		  where idordentrabajo = sel_ot;
		 
		 if primero = 0 then
		 	insert into mct_relacionotciclo values (sel_ot, sel_ot, 'hist');
		    primero = 1;
		 end if;
		 
		else 
			ot_ant 	:= 0;
			sale	:= 1;
		end if;
		 
		if sale = 0 then

			if ot_ant > 0 then
			
				if (select 1
			          from mct_relacionotciclo
			         where ot = ots
			           and otanterior = ot_ant
			           and pantalla = 'rep') then
			           
			    else
			    	--insert into mct_relacionotciclo values (ots, ot_ant, 'hist'); -- hoy
			   	    insert into mct_relacionotciclo values (ots, ot_ant, 'hist');
			
			   	end if;			   
			   
			    sel_ot	:= ot_ant;
			    ot_ant	:= 0;
			else
			    --insert into mct_relacionotciclo values (sel_ot, ot_ant, 'hist');
				sale := 1;
			end if;		
		
		end if;

		 
	end loop;

	tot_ciclo	:= 0;

    select count(*)
      into tot_ciclo
      from mct_relacionotciclo
     where ot = ots;
	
	RETURN tot_ciclo;

END;
$$;


ALTER FUNCTION traking.evtgetcantidadcicloshist(ots bigint) OWNER TO postgres;

