--

CREATE FUNCTION traking.evtgetcaracterizacionpdf(idcaracterizacions bigint, idtipocaracterizacionpdfs bigint) RETURNS TABLE(idcaracterizacionpdf bigint, idcaracterizacion bigint, archivoadjunto text, nombrearchivo character varying, tamano numeric, idtipocaracterizacionpdf bigint, nombretipocaracterizacionpdf character varying, usuariocreacion character varying)
    LANGUAGE plpgsql
    AS $$

begin

		return QUERY
		
		select a.idcaracterizacionpdf,
		       a.idcaracterizacion,
		       a.archivoadjunto,
		       a.nombrearchivo,
		       cast(round(a.tamano/1024/1024, 2) as numeric),
		       a.idtipocaracterizacionpdf,
		       b.nombretipocaracterizacionpdf ,
		       a.usuariocreacion 
		  from mct_caracterizacionpdf a
		  left join traking.mct_tipocaracterizacionpdf b on a.idtipocaracterizacionpdf = b.idtipocaracterizacionpdf 
		 where a.idcaracterizacion = idcaracterizacions
		   and a.idtipocaracterizacionpdf = idtipocaracterizacionpdfs;
	  

END;
$$;


