--
-- TOC entry 1282 (class 1255 OID 16827)
-- Name: evtgetfiledossierpdf(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetfiledossierpdf(idworkorders bigint, idcolumnaf bigint) RETURNS TABLE(idworkorder bigint, idtipodocumentodossier bigint, filepdf text, filename character varying, filesize numeric, columna bigint, datecreate character varying, usercreate character varying)
    LANGUAGE plpgsql
    AS $$

begin
	
	if ( idcolumnaf = 1) then

		return QUERY
		
		select idordentrabajo,
		       idinfcotipdf,
		       archivoadjunto,
		       nombrearchivo,
		       round(tamano/1024/1024, 2),		       
		       idproceso,
		       cast(to_char(now(),'dd-mm-yyyy')  as varchar),
		       cast('admin' as varchar)
		  from mct_infcotipdf
		 where idproceso = 2
		   and idordentrabajo = idworkorders
		 union		 
		select a.idordentrabajo ,
		       a.iddossierpdf,
		       a.archivoadjunto ,
		       a.nombrearchivo,
		       round(a.tamano/1024/1024, 2),
		       a.columna,
		       cast(to_char(a.fechacreacion,'dd-mm-yyyy') as varchar),
		       a.usuariocreacion 
		  from mct_dossierpdf a
		 where a.idordentrabajo = idworkorders
		   and a.columna = idcolumnaf;
	  
	elsif ( idcolumnaf = 2) then
	
		return QUERY
	
		select a.idordentrabajo ,
		       a.iddossierpdf,
		       a.archivoadjunto ,
		       a.nombrearchivo,
		       round(a.tamano/1024/1024, 2),
		       a.columna,
		       cast(to_char(a.fechacreacion,'dd-mm-yyyy') as varchar),
		       a.usuariocreacion 
		  from mct_dossierpdf a
		 where a.idordentrabajo = idworkorders
		   and a.columna = idcolumnaf;		  
	  
	end if;


END;
$$;


