--
-- TOC entry 1504 (class 1255 OID 16830)
-- Name: evtgetfileinfcotipdfdesk(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetfileinfcotipdfdesk(idworkorders bigint, idprocessf bigint) RETURNS TABLE(idinfcoti bigint, filename character varying, tamanofile character varying, idprocess bigint, file text, nameprocess character varying)
    LANGUAGE plpgsql
    AS $$

begin
	

	
	if ( idprocessf = 2) then

		return QUERY
		
		select idinfcotipdf,
		       nombrearchivo,
		       cast(round(tamano/1024/1024, 2)||' MB' as varchar),
		       idproceso,
		       archivoadjunto ,
		       mct_sla.nombresla 
		  from mct_infcotipdf
		  left join mct_sla on idproceso = mct_sla.idsla 
		 where idproceso = idprocessf
		   and idordentrabajo = idworkorders
		   and eshistoria is not true
           and substring(nombrearchivo,1,5) != 'OTRD_'
		   -- Esto es solo para aquellas OT que tienen solo 8 filas en progavisos
		 union
		select idinfcotipdf,
		       nombrearchivo,
		       cast(round(tamano/1024/1024, 2)||' MB' as varchar),
		       idproceso,
		       archivoadjunto ,
		       cast('SOLICITUDES' as varchar) 
		  from mct_infcotipdf
		where idproceso = 10
		  and idordentrabajo = idworkorders
		  --and idordentrabajo < 30674
		  and eshistoria is not true
          and substring(nombrearchivo,1,5) != 'OTRD_';
	  
	elsif ( idprocessf = 11) then
	
		return QUERY
	
		select idinfcotipdf,
		       nombrearchivo,
		       cast(round(tamano/1024/1024, 2)||' MB' as varchar),
		       idproceso,
		       archivoadjunto ,
		       mct_sla.nombresla 
		  from mct_infcotipdf
		  left join mct_sla on idproceso = mct_sla.idsla 
		 where idproceso = idprocessf
		   and idordentrabajo = idworkorders
		   and eshistoria is not true
		 union
		select idinfcotipdf,
		       nombrearchivo,
		       cast(round(tamano/1024/1024, 2)||' MB' as varchar),
		       idproceso,
		       archivoadjunto ,
		       cast('SOLICITUDES' as varchar) 
		  from mct_infcotipdf
		 where idproceso in (100, 200)
		   and idordentrabajo = idworkorders
		   and eshistoria is not true;
		  
	else
	
		return QUERY
	
		select idinfcotipdf,
		       nombrearchivo,
		       cast(round(tamano/1024/1024, 2)||' MB' as varchar),
		       idproceso,
		       archivoadjunto ,
		       mct_sla.nombresla 
		  from mct_infcotipdf
		  left join mct_sla on idproceso = mct_sla.idsla 
		 where idproceso = idprocessf
		   and idordentrabajo = idworkorders
		   and eshistoria is not true;
		  
	  
	end if;


END;
$$;


