--

CREATE FUNCTION traking.evtgetfileturnopdfprogramacionfundicion2(fechas character varying) RETURNS TABLE(idturnopdf bigint, filename character varying, idprocess bigint, file text)
    LANGUAGE plpgsql
    AS $$
declare

   sp_diasemana		integer;  
   sp_fechahasta	varchar;

begin
	
	sp_diasemana 	:= 0;
	sp_fechahasta	:= null;
	sp_diasemana	:= date_part('dow', to_date(fechas, 'yyyy-mm-dd'));
	sp_fechahasta	:= to_char(to_date(fechas, 'yyyy-mm-dd') + interval '1 day', 'yyyy-mm-dd');
    
    if (sp_diasemana = 6 ) then
    
		return QUERY
		
		select a.idturnofundpdf  ,
		       a.nombrearchivo,
		       a.idproceso,
		       replace(a.archivoadjunto, 'data:application/pdf;base64,','' )
		  from mct_turnofundpdf a 
		 where a.fechaturno >= TO_TIMESTAMP(fechas||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaturno <= TO_TIMESTAMP(sp_fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
		   and a.idproceso in (1,2,3)
		   and a.esturnofundicion2 is true
		  order by a.idproceso asc;
	 
	 else
	 
		return QUERY
		
		select a.idturnofundpdf  ,
		       a.nombrearchivo,
		       a.idproceso,
		       replace(a.archivoadjunto, 'data:application/pdf;base64,','' )
		  from mct_turnofundpdf a 
		 where to_char(a.fechaturno, 'yyyy-mm-dd') = fechas --to_char(a.fechacreacion, 'yyyy-mm-dd') = fechas
		   and a.idproceso in (1,2,3)
		   and a.esturnofundicion2 is true
		  order by a.idproceso asc;
	 
	 end if;
	  
 
END;
$$;


