--
-- TOC entry 1941 (class 1255 OID 16849)
-- Name: evtgetgestionncfimputacion_tablet(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetgestionncfimputacion_tablet(idgestionncfs bigint, roadmapcodes character varying) RETURNS TABLE(idgestionncf bigint, ot bigint, identificacion character varying, componente character varying, plano character varying, material character varying, equipo character varying, cliente character varying, emisor character varying, origen character varying, suborigen character varying, accioninmediata character varying, descripcion character varying, codhojaruta character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

    SELECT
        g.idgestionncf,

        ot.idordentrabajo::bigint AS ot,

        (
            COALESCE(hr.nombrecomponente, 'N/A')
            || ' / ' ||
            COALESCE(hr.nombreplano, 'N/A')
            || ' / ' ||
            COALESCE(hr.nombrematerial, 'N/A')
        )::varchar AS identificacion,

        COALESCE(hr.nombrecomponente, 'N/A')::varchar AS componente,

        COALESCE(hr.nombreplano, 'N/A')::varchar AS plano,

        COALESCE(hr.nombrematerial, 'N/A')::varchar AS material,

        (
            CASE

                /*
                 * PRODUCTOS NEPCAST
                 */
                WHEN ot.idproducto IN (
                    10,11,12,13,14,15,16,17
                )
                THEN
                    COALESCE(
                        pn.nombreproductonepcast,
                        'SIN NOMBRE B'
                    )

                /*
                 * PRODUCTOS NORMALES
                 */
                ELSE
                    COALESCE(
                        sf.sigla
                        || ' ' ||
                        mo.nombremodelo
                        || ' ' ||
                        COALESCE(ep.nombreparam, ''),
                        'SIN NOMBRE B'
                    )

            END
        )::varchar AS equipo,

        COALESCE(cli.nombrecorto, 'N/A')::varchar AS cliente,

        COALESCE(op.nombreoperador, 'N/A')::varchar AS emisor,

        COALESCE(ori.nombreorigen, 'N/A')::varchar AS origen,

        COALESCE(sub.nombresuborigen, 'NO APLICA')::varchar AS suborigen,

        COALESCE(acc.nombreaccion, 'N/A')::varchar AS accioninmediata,

        COALESCE(g.observacion, 'N/A')::varchar AS descripcion,

        roadmapcodes::varchar AS codhojaruta

    FROM mct_gestionncf g

    LEFT JOIN mct_operador op
        ON op.idoperador = g.idoperador

    LEFT JOIN mct_origenncf ori
        ON ori.idorigenncf = g.idorigenncf

    LEFT JOIN mct_suborigenncf sub
        ON sub.idsuborigenncf = g.idsuborigenncf

    LEFT JOIN mct_accionncf acc
        ON acc.idaccionncf = g.idaccionncf

    /*
     * Buscamos información asociada a la hoja de ruta
     */
LEFT JOIN (

    SELECT
        h.idordentrabajo,
        c.nombrecomponente,
        h.nombreplano,
        h.nombrematerial

    FROM mct_detallehojarutatemp d

    JOIN mct_hojarutatemp h
        ON h.idhojarutatemp = d.idhojarutatemp

    LEFT JOIN mct_componente c
        ON c.idcomponente = h.idcomponente

    WHERE d.codhojaruta = roadmapcodes

    LIMIT 1

) hr ON TRUE

    LEFT JOIN mct_ordentrabajo ot
        ON ot.idordentrabajo = hr.idordentrabajo

    /*
     * PRODUCTO NEPCAST
     */
    LEFT JOIN mct_productonepcast pn
        ON pn.idproductonepcast = ot.idproducto
       AND ot.idproducto IN (
            10,11,12,13,14,15,16,17
       )

    /*
     * PRODUCTO NORMAL
     */
    LEFT JOIN mct_producto prod
        ON prod.idproducto = ot.idproducto
       AND ot.idproducto NOT IN (
            10,11,12,13,14,15,16,17
       )

    LEFT JOIN mct_modelo mo
        ON mo.idmodelo = prod.idmodelo

    LEFT JOIN mct_subfamilia sf
        ON sf.idsubfamilia = mo.idsubfamilia

    LEFT JOIN mct_etapaparam ep
        ON ep.idetapaparam = prod.idetapaparam

    LEFT JOIN mct_cliente cli
        ON cli.idcliente = ot.idcliente

    WHERE g.idgestionncf = idgestionncfs;

END;
$$;


ALTER FUNCTION traking.evtgetgestionncfimputacion_tablet(idgestionncfs bigint, roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 1177 (class 1255 OID 16850)
-- Name: evtgetgestionncfimputacionresumen(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetgestionncfimputacionresumen(p_idgestionncfimputacion bigint, p_idgestionncf bigint) RETURNS TABLE(idgestionncfimputacion bigint, idgestionncf bigint, areas text, descripcion text, usuario character varying, fechaimputacion timestamp without time zone)
    LANGUAGE sql STABLE
    AS $$

    SELECT
        i.idgestionncfimputacion,
        i.idgestionncf,

        (
            SELECT string_agg(
                CASE
                    WHEN s.nombre IS NOT NULL
                    THEN '- ' || a.nombre || ' / ' || s.nombre
                    ELSE '- ' || a.nombre
                END,
                E'\n'
                ORDER BY d.idgestionncfimputaciondetalle
            )
            FROM mct_gestionncfimputaciondetalle d
            INNER JOIN mct_areaimputacionrechazo a
                ON a.idareaimputacionrechazo =
                   d.idareaimputacionrechazo
            LEFT JOIN mct_subareaimputacionrechazo s
                ON s.idsubareaimputacionrechazo =
                   d.idsubareaimputacionrechazo
            WHERE d.idgestionncfimputacion =
                  i.idgestionncfimputacion
        ) AS areas,

        i.descripcion::text,
        i.usuario,
        i.fechaimputacion

    FROM mct_gestionncfimputacion i

    WHERE i.idgestionncfimputacion =
          p_idgestionncfimputacion

      AND i.idgestionncf =
          p_idgestionncf;

$$;


ALTER FUNCTION traking.evtgetgestionncfimputacionresumen(p_idgestionncfimputacion bigint, p_idgestionncf bigint) OWNER TO postgres;

