--
-- TOC entry 2093 (class 1255 OID 16852)
-- Name: evtgethojarutatemdata(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgethojarutatemdata(coderoadmap character varying) RETURNS TABLE(idordentrabajo bigint, nombrecomponente character varying, nombrecliente character varying, nombreproducto character varying, nombretipoorden character varying, nombrematerial character varying)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombretipoorden		varchar;
		sp_nombrecliente		varchar;
		sp_nombreproducto		varchar;
		sp_idordentrabajoparte	integer;	
		sp_nombreparte			varchar;
		sp_idordentrabajo		integer;
	
	    sp_modalidad            integer;
	   	sp_bloqueo              integer;
	   
	    sp_tipoproducto			bigint;
	   
	
begin
	
		select a.idordentrabajoparte,
               a.modalidad,
               b.idordentrabajo 
          into sp_idordentrabajoparte,
               sp_modalidad,
               sp_idordentrabajo
          from mct_hojaruta a
          left join mct_ordentrabajoparte b on a.idordentrabajoparte = b.idordentrabajoparte
         where a.codhojaruta = coderoadmap;
		        
		select a.idproducto 
		  into sp_tipoproducto
		  from mct_ordentrabajo a
	  	 where a.idordentrabajo = sp_idordentrabajo;
			  	 
	  	 
	  if (sp_tipoproducto <= 17 ) then
	  
		   return query
		   
	       select a.idordentrabajo ,
			      d.nombrecomponente ,
			      e.nombrecliente ,
			      f.nombreproductonepcast  ,
			      g.nombretipoorden,
			      a.nombrematerial 
			 from mct_hojarutatemp a,
			      mct_detallehojarutatemp b,
			      mct_ordentrabajo c,
			      mct_componente d,
			      mct_cliente e,
			      mct_productonepcast f,
			      mct_tipoorden g
		 	where b.codhojaruta    = coderoadmap
		 	and   a.idhojarutatemp = b.idhojarutatemp 
			and   a.idordentrabajo = c.idordentrabajo 
			and   a.idcomponente   = d.idcomponente 
			and   c.idcliente      = e.idcliente 
			and   c.idproducto     = f.idproductonepcast  
			and   c.idtipoorden    = g.idtipoorden ;
	
	  else
	  
		   return query
		   
	       select a.idordentrabajo ,
			      d.nombrecomponente ,
			      e.nombrecliente ,
			      f.nombreproducto ,
			      g.nombretipoorden,
			      a.nombrematerial 
			 from mct_hojarutatemp a,
			      mct_detallehojarutatemp b,
			      mct_ordentrabajo c,
			      mct_componente d,
			      mct_cliente e,
			      mct_producto f,
			      mct_tipoorden g
		 	where b.codhojaruta    = coderoadmap
		 	and   a.idhojarutatemp = b.idhojarutatemp 
			and   a.idordentrabajo = c.idordentrabajo 
			and   a.idcomponente   = d.idcomponente 
			and   c.idcliente      = e.idcliente 
			and   c.idproducto     = f.idproducto 
			and   c.idtipoorden    = g.idtipoorden ;	  
	  
	  end if;


END;
$$;


ALTER FUNCTION traking.evtgethojarutatemdata(coderoadmap character varying) OWNER TO postgres;

--
-- TOC entry 2280 (class 1255 OID 16853)
-- Name: evtgetinformencfconsolidado(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetinformencfconsolidado(desde character varying, hasta character varying) RETURNS TABLE(grupo_area character varying, area_desviacion character varying, responsable character varying, cantidad bigint, porcentaje numeric, promedio_6_meses bigint, nuevo character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE
	       
	    sp_promedio             bigint;	 
		sp_cantidad				bigint;   
        sp_total				bigint;
	
	    rec_data       			RECORD;		
	   
	    sp_salida				bigint;
	   
begin 
	
	  sp_salida 	:= 0;
	  sp_cantidad	:= 0;
	  sp_total		:= 0;

	  select count(*)
        into sp_total
        from traking.mct_gestionncf a
        left join traking.mct_origenncf b on a.idorigenncf = b.idorigenncf
       where a.fechacreacion::date BETWEEN desde::date AND hasta::date
         and ( aplicancfapp is true
           or a.idorigenncf in (4,10,11,12) );
 
	  FOR rec_data IN (  
 
					select a.idorigenncf,
					       a.nombreorigen,
					       a.codigoaccion,
					       a.responsable,
					       a.alias,
					       a.email
					  from mct_origenncf a
					 where a.aplicancfapp is true
                        or a.idorigenncf in (4,10,11,12)
                     order by a.ordenconsolidado asc

					)
								
		loop 	
        
			sp_promedio	:= 0;
            sp_cantidad	:= 0;

			select count(*)
              into sp_cantidad
              from traking.mct_gestionncf a
             where a.fechacreacion::date BETWEEN desde::date AND hasta::date
               and a.idorigenncf = rec_data.idorigenncf;

			WITH params AS (
			    SELECT desde::date AS fecha_inicio
			),
			meses AS (
			    SELECT generate_series(
			        date_trunc('month', fecha_inicio) - interval '5 month',
			        date_trunc('month', fecha_inicio),
			        interval '1 month'
			    )::date AS inicio_mes
			    FROM params
			),
			conteo_por_mes AS (
			    SELECT
			        m.inicio_mes,
			        COUNT(a.*) AS c_cantidad
			    FROM meses m
			    LEFT JOIN traking.mct_gestionncf a
			        ON a.fechacreacion::date >= m.inicio_mes
			       AND a.fechacreacion::date < (m.inicio_mes + interval '1 month')
			       AND a.idorigenncf = rec_data.idorigenncf
			    GROUP BY m.inicio_mes
			)
			SELECT ROUND(AVG(c_cantidad)::numeric, 0) AS promedio_ultimos_6_meses
              into sp_promedio 
			  FROM conteo_por_mes;

	      grupo_area 		:= 'MECANIZADO'; 
	      area_desviacion 	:= rec_data.alias; 
	      responsable 		:= rec_data.responsable;
	      cantidad 			:= sp_cantidad;
	      porcentaje 		:= ROUND(
								    CASE 
								        WHEN sp_total IS NULL OR sp_total = 0 THEN 0
								        ELSE ((sp_cantidad * 100.0) / sp_total)
								    END
								, 2);
	      promedio_6_meses 	:= sp_promedio;
	      nuevo 			:= 'vacio';

		  RETURN next;	
		           

	  END LOOP;	 
	
        	     
END;
$$;


ALTER FUNCTION traking.evtgetinformencfconsolidado(desde character varying, hasta character varying) OWNER TO postgres;

