--
-- TOC entry 1739 (class 1255 OID 16855)
-- Name: evtgetlastpartworkorderitemseq(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetlastpartworkorderitemseq(idworkorder bigint) RETURNS TABLE(itemcorr bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE 
			
        sp_idot   		INTEGER;
        sp_maxitem    	INTEGER;


BEGIN
        sp_maxitem      := 0;

	    select max(a.itemcorr) 
	      into sp_maxitem
	      from mct_ordentrabajoparte a
	     where a.idordentrabajo = idworkorder;
  
		if sp_maxitem > 0 then
		   itemcorr := sp_maxitem;
		else
		   itemcorr := 0;
		end if;

		RETURN NEXT;
							
END;				
$$;


ALTER FUNCTION traking.evtgetlastpartworkorderitemseq(idworkorder bigint) OWNER TO postgres;

--
-- TOC entry 1782 (class 1255 OID 16856)
-- Name: evtgetlastworkorderseq(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgetlastworkorderseq() RETURNS TABLE(idworkorder bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE 
			
        sp_idot   		INTEGER;
        sp_maxcorr    	INTEGER;
        sp_actualcorr   INTEGER;

BEGIN
        sp_maxcorr      := 0;
		sp_actualcorr   := 0;

	    select max(idordentrabajo) 
	      into sp_maxcorr
	      from mct_ordentrabajo;

        select last_value 
	      into sp_actualcorr
          from mct_ordentrabajo_seq;
  
		if sp_maxcorr = sp_actualcorr then
		   idworkorder := sp_actualcorr;
		else
		   idworkorder := 0;
		end if;

		RETURN NEXT;
							
END;				
$$;


ALTER FUNCTION traking.evtgetlastworkorderseq() OWNER TO postgres;

