--
-- TOC entry 2364 (class 1255 OID 16859)
-- Name: evtgettratamientotermicopdf(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtgettratamientotermicopdf(idtratamientotermicos bigint, idtipocaracterizacionpdfs bigint) RETURNS TABLE(idtratamientotermicopdf bigint, idtratamientotermico bigint, archivoadjunto text, nombrearchivo character varying, tamano numeric, idtipocaracterizacionpdf bigint, nombretipocaracterizacionpdf character varying, usuariocreacion character varying)
    LANGUAGE plpgsql
    AS $$

begin

		return QUERY
		
		select a.idtratamientotermicopdf,
		       a.idtratamientotermico,
		       a.archivoadjunto,
		       a.nombrearchivo,
		       cast(round(a.tamano/1024/1024, 2) as numeric),
		       a.idtipocaracterizacionpdf,
		       b.nombretipocaracterizacionpdf ,
		       a.usuariocreacion 
		  from mct_tratamientotermicopdf a
