CREATE FUNCTION traking.evtlistaccionncf() RETURNS TABLE(idactionncf bigint, actionname character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		SELECT a.idaccionncf, 
		       a.nombreaccion, 
		       a.estado, 
		       b.nombreestado ,
		       a.fechacreacion, 
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion
	 	  FROM traking.mct_accionncf a,
	 	       traking.mct_estado b
	 	 where a.estado = b.idestado 
           and a.estado = 1
	  order by idaccionncf;

END;
$$;


