--
-- TOC entry 1603 (class 1255 OID 16861)
-- Name: evtlistaccionncfpororigen(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistaccionncfpororigen(idorigens bigint) RETURNS TABLE(idactionncf bigint, actionname character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    if (idorigens in (2)) then -- fundicion

    	RETURN QUERY
    
		SELECT a.idaccionncf, 
		       a.nombreaccion, 
		       a.estado, 
		       b.nombreestado ,
		       a.fechacreacion, 
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion
	 	  FROM traking.mct_accionncf a,
	 	       traking.mct_estado b
	 	 where a.estado = b.idestado 
           and a.estado = 1
           and a.idaccionncf in (1,2,3)
	     order by idaccionncf;

	elsif (idorigens in (6, 1, 8, 3, 5, 4)) then

        RETURN QUERY

		SELECT a.idaccionncf, 
		       a.nombreaccion, 
		       a.estado, 
		       b.nombreestado ,
		       a.fechacreacion, 
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion
	 	  FROM traking.mct_accionncf a,
	 	       traking.mct_estado b
	 	 where a.estado = b.idestado 
           --and a.estado = 1
           and a.idaccionncf in (1, 2, 5)
	     order by idaccionncf;

     elsif (idorigens in ( 9 )) then

        RETURN QUERY

		SELECT a.idaccionncf, 
		       a.nombreaccion, 
		       a.estado, 
		       b.nombreestado ,
		       a.fechacreacion, 
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion
	 	  FROM traking.mct_accionncf a,
	 	       traking.mct_estado b
	 	 where a.estado = b.idestado 
           --and a.estado = 1
           and a.idaccionncf in (6, 7)
	     order by idaccionncf;

	end if;

END;
$$;


