CREATE FUNCTION traking.evtlistactividaddiaria(idusuarios bigint) RETURNS TABLE(idactividaddiaria bigint, idactividaddiariaparam bigint, idhoraminuto bigint, nombrehoraminuto character varying, idusuario bigint, nombreusuario character varying, descripcion character varying, protocoloobligatorio boolean, validacionobligatoria boolean, imagenobligatoria boolean, requierefirma boolean, observacion character varying, fechaactividad character varying, lunes boolean, martes boolean, miercoles boolean, jueves boolean, viernes boolean, sabado boolean, domingo boolean, estado boolean, atrasado boolean)
    LANGUAGE plpgsql
    AS $$

declare
   
	sp_dia			bigint;
    sp_cantidad		bigint;	
   
begin
	
	select date_part('dow', now())
	  into sp_dia;
	 
	select count(*)
	  into sp_cantidad
	  from mct_actividaddiaria a 
	 where a.fechaactividad = current_date 
	   and a.idusuario = idusuarios;
	

	if (sp_dia = 1 ) then

		if (sp_cantidad = 0) then
		
		    insert into mct_actividaddiaria 
		          (
		          idactividaddiaria,
		          idactividaddiariaparam,
		          idusuario,
		          fechaactividad,
		          estado,
		          fechaejecucion
		          )	    
			select nextval('traking.mct_actividaddiaria_seq'),
			       b.idactividaddiariaparam,
			       b.idusuario,
			       current_date ,
			       false,
			       null
			  from mct_actividaddiariaparam b 
			 where b.idusuario = idusuarios
			   and b.lunes is true
			 order by 2 asc;
		
		end if;

	    return QUERY
	    
		SELECT d.idactividaddiaria,
		       a.idactividaddiariaparam, 
		       a.idhoraminuto, 
		       b.nombrehoraminuto,
		       a.idusuario, 
		       c.nombre,
		       a.descripcion, 
		       a.protocoloobligatorio, 
		       a.validacionobligatoria, 
		       a.imagenobligatoria, 
		       a.requierefirma, 
		       a.observacion, 
		       cast(to_char(d.fechaactividad , 'dd-mm-yyyy') as varchar),
		       a.lunes, 
		       a.martes, 
		       a.miercoles, 
		       a.jueves, 
		       a.viernes, 
		       a.sabado, 
		       a.domingo,
		       d.estado,
		       cast(case 
			       when to_char(d.fechaejecucion , 'hh24:mi') > b.nombrehoraminuto then
			            true
			       else
			            false
			   end as boolean)
		  FROM traking.mct_actividaddiariaparam a
		  join traking.mct_horaminuto b on a.idhoraminuto = b.idhoraminuto
		  join traking.mct_usuario c    on a.idusuario = c.idusuario
		  left join traking.mct_actividaddiaria d on a.idactividaddiariaparam = d.idactividaddiariaparam
