--
-- TOC entry 2232 (class 1255 OID 16863)
-- Name: evtlistactivityroadmap(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistactivityroadmap(roadmapse character varying) RETURNS TABLE(activityname character varying, codesection character varying, tothour numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		 
	select --a.idordentrabajo,
	       --a.idordentrabajoparte,
	       --a.idparte,
	       --b.nombreparte,
	       --c.idactividad,
	       --d.idsubseccion,
	       --e.idseccion,
	       --f.nombreseccion,
	       --g.idhojaruta,  
	       h.nombreactividad,
	       f.codigoseccion,
	       sum(c.tiempohistorico)
	  from mct_ordentrabajoparte a,
	       mct_parte b,
	       mct_parteactividad c,
	       mct_partesubseccion d,
	       mct_subseccion e,
	       mct_seccion f,
	       mct_hojaruta g,
	       mct_actividad h
     where a.idparte = b.idparte
       and b.idparte = c.idparte
       and a.idparte = d.idparte
       and d.idpartesubseccion = e.idsubseccion
       and e.idseccion = f.idseccion
       and g.codhojaruta = roadmapse
       and g.idordentrabajoparte = a.idordentrabajoparte
       and h.idactividad = c.idactividad
       group by h.nombreactividad,
	       f.codigoseccion;

END;
$$;


ALTER FUNCTION traking.evtlistactivityroadmap(roadmapse character varying) OWNER TO postgres;

--
-- TOC entry 1863 (class 1255 OID 16864)
-- Name: evtlistacusaacciontotales(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistacusaacciontotales(iddefectos bigint) RETURNS TABLE(iddefectofundicion bigint, iddefectocausa bigint, totalcausa bigint, totalaccion bigint)
    LANGUAGE plpgsql
    AS $$
	
declare
begin
	
	return query
	
	select a.iddefectofundicion,
	       a.iddefectocausa ,
	       cast(count(a.*) as bigint) as cantcausa, 
	       cast(count(b.*) as bigint) as cantaccion
      from mct_defectocausa a
      left join mct_defectocausaaccion b on b.iddefectocausa = a.iddefectocausa
     where a.iddefectofundicion = iddefectos
     group by a.iddefectofundicion, a.iddefectocausa;

END			
$$;


