			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 7
			 group by a.fecha_real_termino;
			
			-- Armado
			 select min(a.fechainicio) ,
			        coalesce(max(b.fechatermino ), now()) ,
			        cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint)
              into sp_fechauno,
				   sp_fechados,
                   sp_armado
			   from mct_movimientoordentrabajo a 
			   left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  where a.idordentrabajo = rec1.idordentrabajo
			    and a.idaccion = 165
			    and a.iniciaarmadodesarme is true
			  group by a.fechainicio;
			  
			-- Informe Reparacion
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint)
              into sp_fechauno,
				   sp_fechados,
                   sp_informerepara
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 80 and b.idproceso = 8
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			   
			 
			-- Dossier de Calidad
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint)
              into sp_fechauno,
				   sp_fechados,
                   sp_dossier
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 131 and b.idproceso = 13
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			
			   
			-- Despacho
			select coalesce(max(b.fechatermino), max(c.fechadespacho)), 
			       coalesce(max(c.fechadespacho), now() ),
			       cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint)
              into sp_fechauno,
				   sp_fechados,
                   sp_despacho
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idestadoorden  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;


			sp_totalots				:= sp_totalots + 1;

			sp_sumabombaenpiso 		:= sp_sumabombaenpiso + coalesce(sp_bombaenpiso,0);
			sp_sumadesarme 			:= sp_sumadesarme + coalesce(sp_desarme,0);
			sp_sumaevaluacion 		:= sp_sumaevaluacion + coalesce(sp_evaluacion,0);
		    sp_sumacotizacion 		:= sp_sumacotizacion + coalesce(sp_cotizacion,0);
			sp_sumaautorizacion 	:= sp_sumaautorizacion + coalesce(sp_autorizacion,0);
			sp_sumamecanizado 		:= sp_sumamecanizado + coalesce(sp_mecanizado,0);
			sp_sumaarmado 			:= sp_sumaarmado + coalesce(sp_armado,0);
			sp_sumainformerepara 	:= sp_sumainformerepara + coalesce(sp_informerepara,0);
			sp_sumadossier 			:= sp_sumadossier + coalesce(sp_dossier,0);
			sp_sumadespacho 		:= sp_sumadespacho + coalesce(sp_despacho,0);			
			sp_sumaresumen 			:= sp_sumaresumen + coalesce(sp_resumen,0);

			raise notice '%', sp_sumacotizacion||' - '||sp_cotizacion;

			
			end loop;

	 		bombaenpiso 	:= coalesce(sp_sumabombaenpiso / sp_totalots,0);
 			desarme 		:= coalesce(sp_sumadesarme / sp_totalots,0);
 			evaluacion 		:= coalesce(sp_sumaevaluacion / sp_totalots,0);
 	        cotizacion 		:= coalesce(sp_sumacotizacion / sp_totalots,0);
 			autorizacion 	:= coalesce(sp_sumaautorizacion / sp_totalots,0);
 			mecanizado 		:= coalesce(sp_sumamecanizado / sp_totalots,0);
 			armado 			:= coalesce(sp_sumaarmado / sp_totalots,0);
 			informerepara 	:= coalesce(sp_sumainformerepara / sp_totalots,0);
  			dossier 		:= coalesce(sp_sumadossier / sp_totalots,0);
 			despacho 		:= coalesce(sp_sumadespacho / sp_totalots,0);
 			resumen 		:= coalesce(sp_sumaresumen / sp_totalots,0);

			RETURN NEXT;


   	end if;



END;
$$;


ALTER FUNCTION traking.evtlistanalisisremanufacturaarmado(idots bigint, idclientes bigint, idproductos bigint, cantidads bigint, idevaluadors bigint, fechadesde character varying, fechahasta character varying) OWNER TO postgres;

--
-- TOC entry 2222 (class 1255 OID 16868)
-- Name: evtlistanalisisremanufacturacabecera(bigint, bigint, bigint, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistanalisisremanufacturacabecera(idots bigint, idclientes bigint, idproductos bigint, cantidads bigint, idevaluadors bigint, fechadesde character varying, fechahasta character varying) RETURNS TABLE(idordentrabajo bigint, nombrecorto character varying, nombrecliente character varying, nombreevaluador character varying, nombreordentrabajo character varying, planogeneral character varying, materialgeneral character varying, clientesconsultados bigint, equiposevaluados bigint, cantidad bigint, montototalpromedio bigint)
    LANGUAGE plpgsql
    AS $$
declare 
			
	rec1      			    record;
  
BEGIN 
			
   	if (idots != -1) then

		RETURN QUERY
	
		-- consulta por OT
		select a.idordentrabajo,
		       d.nombrecorto,
		       d.nombrecliente,
		       cast('' as varchar) as nombreevaluador,
		       a.nombreordentrabajo,
               b.planogeneral,
		       c.nombrematerial as materialgeneral,
               cast(0 as bigint) as clientesevaluados,
               cast(0 as bigint) as equiposevaluados,
               cast(1 as bigint),
               a.montorepfab as montototalpromedio		       
		  from mct_ordentrabajo a
		  left join mct_producto b on a.idproducto = b.idproducto
		  left join mct_material c on b.idmaterial = c.idmaterial
		  left join mct_cliente d on a.idcliente = d.idcliente
		 where a.idordentrabajo = idots;


   	elsif (idclientes != -1 and idproductos != -1 and cantidads != -1) then

			RETURN QUERY
	
			-- cliente, equipo y cantidad
			select cast(0 as bigint),
	               d.nombrecorto,
			       d.nombrecliente,
			       cast('' as varchar) as nombreevaluador,
                   a.nombreordentrabajo,		       
			       b.planogeneral,
			       c.nombrematerial as materialgeneral,
			       --a.idproducto,
	               cast(0 as bigint) as clientesevaluados,
	               cast(0 as bigint) as equiposevaluados,
	               count(*),
	               cast(round(sum(a.montorepfab) / count(*)) as bigint)
			  from mct_ordentrabajo a
			  left join mct_producto b on a.idproducto = b.idproducto
			  left join mct_material c on b.idmaterial = c.idmaterial
			  left join mct_cliente d on a.idcliente = d.idcliente
			 where a.idcliente = idclientes
               and a.idproducto = idproductos -- viene del combobox
			   and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
			 group by d.nombrecorto,
			       d.nombrecliente,
			       a.nombreordentrabajo,
			       b.planogeneral,
			       b.idmaterial,
			       c.nombrematerial
			 limit cantidads;

	elsif (idclientes != -1 and fechadesde != 'NA' and fechahasta != 'NA') then

			RETURN QUERY

			-- cliente, tiempo 
			select cast(0 as bigint),
                   d.nombrecorto,
			       d.nombrecliente,
                   cast('' as varchar) as nombreevaluador,
                   cast('' as varchar) as nombreordentrabajo,
                   cast('' as varchar) as planogeneral,
                   cast('' as varchar) as materialgeneral,
	               cast(0 as bigint) as clientesevaluados,
	               cast(0 as bigint) as equiposevaluados,
	               count(distinct(a.idproducto)),
			       cast(round(sum(a.montorepfab) / count(distinct(a.idproducto)) ) as bigint)
			  from mct_ordentrabajo a
			  left join mct_cliente d on a.idcliente = d.idcliente
			 where a.idcliente = idclientes -- ciene del combobox
			   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyymmdd HH24:MI:SS'))  
			   and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
			 group by d.nombrecorto,
			          d.nombrecliente;

	elsif (idevaluadors != -1 and fechadesde != 'NA' and fechahasta != 'NA') then


 			RETURN QUERY
			
			-- Evaluador, tiempo 
			select cast(0 as bigint),
                   cast('' as varchar) as nombrecorto,
		           cast('' as varchar) as nombrecliente,                   
                   b.nombre as nombreevaluador,
				   cast('' as varchar) as nombreordentrabajo,
			       cast('' as varchar) as planogeneral,
		           cast('' as varchar) as materialgeneral,
                   cast(0 as bigint) as clientesevaluados,
                   cast(0 as bigint) as equiposevaluados,
                   count(distinct(a.idproducto)),
			       cast(round(sum(a.montorepfab) / count(distinct(a.idproducto)) ) as bigint)
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
			 where a.idusuario = idevaluadors -- viene del combobox
			   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyymmdd HH24:MI:SS'))  
			   and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
			 group by b.nombre;

	elsif (fechadesde != 'NA' and fechahasta != 'NA') then

		
			RETURN QUERY

			 -- Total Ots, tiempo 
			select cast(0 as bigint),
                   cast('' as varchar) as nombrecorto,
		           cast('' as varchar) as nombrecliente,                   
                   cast('' as varchar) as nombreevaluador,
				   cast('' as varchar) as nombreordentrabajo,
			       cast('' as varchar) as planogeneral,
		           cast('' as varchar) as materialgeneral,
                   count(distinct(a.idcliente)) as clientesevaluados,
			       count(distinct(a.idproducto)) as equiposevaluados,
			       cast(1 as bigint),
			       cast(round(sum(a.montorepfab) / count(distinct(a.idproducto)) ) as bigint)
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
			 where (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyymmdd HH24:MI:SS')) 
			   and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000;

   	end if;



END;
$$;


ALTER FUNCTION traking.evtlistanalisisremanufacturacabecera(idots bigint, idclientes bigint, idproductos bigint, cantidads bigint, idevaluadors bigint, fechadesde character varying, fechahasta character varying) OWNER TO postgres;

--
-- TOC entry 1305 (class 1255 OID 16869)
-- Name: evtlistanalisisremanufacturadetalle(bigint, bigint, bigint, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistanalisisremanufacturadetalle(idots bigint, idclientes bigint, idproductos bigint, cantidads bigint, idevaluadors bigint, fechadesde character varying, fechahasta character varying) RETURNS TABLE(bombaenpiso numeric, diabombaenpiso bigint, desarme numeric, diadesarme bigint, evaluacion numeric, diaevaluacion bigint, cotizacion numeric, diacotizacion bigint, autorizacion numeric, diaautorizacion bigint, mecanizado numeric, diamecanizado bigint, armado numeric, diarmado bigint, informerepara numeric, diainformerepara bigint, dossier numeric, diadossier bigint, despacho numeric, diadespacho bigint, resumen numeric, diaresumen bigint, estadobombaenpiso character varying, estadodesarme character varying, estadoevaluacion character varying, estadocotizacion character varying, estadoautorizacion character varying, estadomecanizado character varying, estadoarmado character varying, estadoinformerepara character varying, estadodossier character varying, estadodespacho character varying, estadoresumen character varying)
    LANGUAGE plpgsql
    AS $$
declare 
			
	rec1      			    record;

	sp_bombaenpiso 			bigint;
	sp_diabombaenpiso 		bigint;
	sp_desarme 				bigint;
	sp_diadesarme 			bigint;
	sp_evaluacion 			bigint;
	sp_diaevaluacion 		bigint;
    sp_cotizacion 			bigint;
	sp_diacotizacion 		bigint;
	sp_autorizacion 		bigint;
	sp_diaautorizacion 		bigint;
	sp_mecanizado 			bigint;
	sp_diamecanizado 		bigint;
	sp_armado 				bigint;
	sp_diarmado 			bigint;
	sp_informerepara 		bigint;
	sp_diainformerepara 	bigint;
	sp_dossier 				bigint;
	sp_diadossier 			bigint;
	sp_despacho 			bigint;
	sp_diadespacho			bigint; 			
	sp_resumen 				bigint;
	sp_diaresumen 			bigint;

	sp_fechauno				timestamp;
	sp_fechados				timestamp;

	sp_sumabombaenpiso 		bigint;
	sp_sumadesarme 			bigint;
	sp_sumaevaluacion 		bigint;
    sp_sumacotizacion 		bigint;
	sp_sumaautorizacion 	bigint;
	sp_sumamecanizado 		bigint;
	sp_sumaarmado 			bigint;
	sp_sumainformerepara 	bigint;
	sp_sumadossier 			bigint;
	sp_sumadespacho 		bigint;			
	sp_sumaresumen 			bigint;

	sp_totalots				bigint;
	
  
BEGIN 
	
	sp_sumabombaenpiso 		:= 0;
	sp_sumadesarme 			:= 0;
	sp_sumaevaluacion 		:= 0;
    sp_sumacotizacion 		:= 0;
	sp_sumaautorizacion 	:= 0;
	sp_sumamecanizado 		:= 0;
	sp_sumaarmado 			:= 0;
	sp_sumainformerepara 	:= 0;
	sp_sumadossier 			:= 0;
	sp_sumadespacho 		:= 0;			
	sp_sumaresumen 			:= 0;

	sp_totalots				:= 0;
	
	sp_bombaenpiso 			:= 0;
	sp_diabombaenpiso 		:= 0;
	sp_desarme 				:= 0;
	sp_diadesarme 			:= 0;
	sp_evaluacion 			:= 0;
	sp_diaevaluacion 		:= 0;
    sp_cotizacion 			:= 0;
	sp_diacotizacion 		:= 0;
	sp_autorizacion 		:= 0;
	sp_diaautorizacion 		:= 0;
	sp_mecanizado 			:= 0;
	sp_diamecanizado 		:= 0;
	sp_armado 				:= 0;
	sp_diarmado 			:= 0;
	sp_informerepara 		:= 0;
	sp_diainformerepara 	:= 0;
	sp_dossier 				:= 0;
	sp_diadossier 			:= 0;
	sp_despacho 			:= 0;
	sp_diadespacho			:= 0; 			
	sp_resumen 				:= 0;
	sp_diaresumen 			:= 0;

	select a.diabombapiso,
		   a.diadesarme,
		   a.diaevaluacion,
		   a.diacotizacion,
		   a.diaautorizacion,
		   a.diamecanizado,
		   a.diarmado,
		   a.diainformerepara,
		   a.diadossier,
		   a.diadespacho,
		   a.diaresumen
      into diabombaenpiso,
		   diadesarme,
		   diaevaluacion,
		   diacotizacion,
		   diaautorizacion,
		   diamecanizado,
		   diarmado,
		   diainformerepara,
		   diadossier,
		   diadespacho,
		   diaresumen
      from traking.mct_kpianalisis a;
	
   	if (idots != -1) then

			-- Bomba en Piso
            -- (Se inicia con la creación de la OT - termina cuando se inicia en tableta un desarme)
			select a.fechacreacion, 
			       coalesce(min(b.fechainicio), now()) ,
			       --cast(date_part('day', coalesce(min(b.fechainicio), now()) - a.fechacreacion) as bigint)
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_bombaenpiso
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173
			 where a.idordentrabajo = idots
			 group by a.fechacreacion;

			
			-- Desarme
            -- (Se inicia cuando ML inicia desarme - termina con validación de mecánico líder y responsable en tableta)
			select min(a.fechainicio) ,
			       coalesce(max(b.fechatermino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_desarme
			  from mct_movimientoordentrabajo a 
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173 and b.iniciaarmadodesarme is true
			 where a.idordentrabajo = idots
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechainicio;
			
			
			-- Evaluacion
            -- (Se inicia cuando ML termina desarme y termina con alojamiento de IT en sistema por el responsable)
			select max(a.fechatermino) ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fechatermino) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_evaluacion
			  from mct_movimientoordentrabajo a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 3
			 where a.idordentrabajo = idots
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechatermino;
			    

			-- Cotizacion 
            -- (Se inicia con alojamiento IT en sistema y termina con alojamiento de COT en sistema por el secretario)
			select a.fecha_real_termino ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fecha_real_termino) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
			       sp_fechados,
                   sp_cotizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 4 
			 where a.idordentrabajo = idots
			   and a.idsla = 3
			 group by a.fecha_real_termino;
			
			-- Autorizacion
            -- (Se inicia cuando se aloja la COT y termina con autorización de OT en sistema por el secretario)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_autorizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 5 
			 where a.idordentrabajo = idots
			   and a.idsla = 4
			 group by a.fecha_real_termino;
			 		
			-- Mecanizado  
            -- (Inicia con entrega de planos y termina con 100% MEC en sistema)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fechamarcapendientedespacho  ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_mecanizado
			  from mct_progavisos a 
			  left join mct_ordentrabajo b on a.idordentrabajo = b.idordentrabajo
			 where a.idordentrabajo = idots
			   and a.idsla = 7
			 group by a.fecha_real_termino;
			
			-- Armado
            -- (Inicia con inicio por ML armado y termina con el termino de ML de armado)
			 select min(a.fechainicio) ,
			        coalesce(max(b.fechatermino ), now()) ,
			        --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                    cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 3600)::numeric , 2)), 0) as bigint)*60 +
                    cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_armado
			   from mct_movimientoordentrabajo a 
			   left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  where a.idordentrabajo = idots
			    and a.idaccion = 165
			    and a.iniciaarmadodesarme is true
			  group by a.fechainicio;
  
			-- Informe Reparacion
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de IF en sistema por el responsable)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_informerepara
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 80 and b.idproceso = 8
			 where a.idordentrabajo = idots
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			   
			-- Dossier de Calidad
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de DOSSIER en sistema por el encargado de proyectos)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_dossier
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 131 and b.idproceso = 13
			 where a.idordentrabajo = idots
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			
			   
			-- Despacho
            -- (se inicia con termino de armado en tableta y termina con despacho en sistema)
			select coalesce(max(b.fechatermino), max(c.fechadespacho)),
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_despacho
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = idots;

			-- Resumen
			select coalesce(max(a.fechacreacion), now()), 
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_resumen
			  from mct_ordentrabajo a
			  --left join mct_movimientoordentrabajo b on a.idestadoorden  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = idots;


			estadobombaenpiso 	:= 'btn-default'; 
		    estadodesarme 		:= 'btn-default'; 
		    estadoevaluacion 	:= 'btn-default';
		    estadocotizacion 	:= 'btn-default'; 
		    estadoautorizacion 	:= 'btn-default'; 
		    estadomecanizado 	:= 'btn-default'; 
		    estadoarmado 		:= 'btn-default'; 
		    estadoinformerepara := 'btn-default'; 
		    estadodossier 		:= 'btn-default'; 
		    estadodespacho 		:= 'btn-default'; 
		    estadoresumen 		:= 'btn-default';

			-- Bomba en piso
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = idots 
	               and a.idaccion = 173
	               and a.fechainicio is not null) then

				estadobombaenpiso 	:= 'btn-success';

			end if;

			-- Desarme
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = idots 
	               and a.idaccion = 173
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadodesarme 	:= 'btn-success';

			end if;

			-- Evaluacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = idots
	               and a.idsla = 3
	               and a.estado = 1 ) then

				estadoevaluacion := 'btn-success';

			end if;

			-- Cotizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = idots
	               and a.idsla = 4
	               and a.estado = 1 ) then

				estadocotizacion := 'btn-success';

			end if;
			-- Autorizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = idots
	               and a.idsla = 5
	               and a.estado = 1 ) then

				estadoautorizacion := 'btn-success';

			end if;

			-- Mecanizado
			if (select 1
                  from mct_ordentrabajo a
                 where a.idordentrabajo = idots
                   and a.fechamarcapendientedespacho is not null ) then

				estadomecanizado := 'btn-success';

			end if;

			-- Armado
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = idots 
	               and a.idaccion = 164
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadoarmado 	:= 'btn-success';

			end if;

			-- Informe reparacion
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = idots
                   and a.infcoti = 80 
                   and a.idproceso = 8 ) then

				estadoinformerepara := 'btn-success';

			end if;

			-- Dossier
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = idots
                   and a.infcoti = 131 
                   and a.idproceso = 13 ) then

				estadodossier := 'btn-success';

			end if;

			-- Despacho
			if (select distinct 1 
                  from mct_despachopartecabecera a
                 where a.idordentrabajo = idots) then

				estadodespacho 		:= 'btn-success';

			end if;
			
	 		bombaenpiso 		:= coalesce(sp_bombaenpiso,0);
 			desarme 			:= coalesce(sp_desarme,0);
 			evaluacion 			:= coalesce(sp_evaluacion,0);
 	        cotizacion 			:= coalesce(sp_cotizacion,0);
 			autorizacion 		:= coalesce(sp_autorizacion,0);
 			mecanizado 			:= coalesce(sp_mecanizado,0);
 			armado 				:= coalesce(sp_armado,0);
 			informerepara 		:= coalesce(sp_informerepara,0);
  			dossier 			:= coalesce(sp_dossier,0);
 			despacho 			:= coalesce(sp_despacho,0);
 			resumen 			:= coalesce(sp_resumen,0);
		
			RETURN NEXT;


   	elsif (idclientes != -1 and idproductos != -1 and cantidads != -1) then


		 FOR rec1 IN ( 

			-- cliente, equipo y cantidad
			select a.idordentrabajo
			  from mct_ordentrabajo a
			  left join mct_producto b on a.idproducto = b.idproducto
			  left join mct_material c on b.idmaterial = c.idmaterial
			  left join mct_cliente d on a.idcliente = d.idcliente
			 where a.idcliente = idclientes -- viene del combobox
               and a.idproducto = idproductos -- viene del combobox
			   and a.idtipoorden = 1
               and a.idfamilia = 8
			   and a.idordentrabajo >= 30000
			 limit cantidads
			)
			Loop


			-- Bomba en Piso
            -- (Se inicia con la creación de la OT - termina cuando se inicia en tableta un desarme)
			select a.fechacreacion, 
			       coalesce(min(b.fechainicio), now()) ,
			       --cast(date_part('day', coalesce(min(b.fechainicio), now()) - a.fechacreacion) as bigint)
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_bombaenpiso
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173
			 where a.idordentrabajo = rec1.idordentrabajo
			 group by a.fechacreacion;

			
			-- Desarme
            -- (Se inicia cuando ML inicia desarme - termina con validación de mecánico líder y responsable en tableta)
			select min(a.fechainicio) ,
			       coalesce(max(b.fechatermino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_desarme
			  from mct_movimientoordentrabajo a 
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173 and b.iniciaarmadodesarme is true
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechainicio;
			
			
			-- Evaluacion
            -- (Se inicia cuando ML termina desarme y termina con alojamiento de IT en sistema por el responsable)
			select max(a.fechatermino) ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fechatermino) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_evaluacion
			  from mct_movimientoordentrabajo a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 3
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechatermino;
			    

			-- Cotizacion 
            -- (Se inicia con alojamiento IT en sistema y termina con alojamiento de COT en sistema por el secretario)
			select a.fecha_real_termino ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fecha_real_termino) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
			       sp_fechados,
                   sp_cotizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 4 
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 3
			 group by a.fecha_real_termino;
			
			-- Autorizacion
            -- (Se inicia cuando se aloja la COT y termina con autorización de OT en sistema por el secretario)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_autorizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 5 
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 4
			 group by a.fecha_real_termino;
			 		
			-- Mecanizado  
            -- (Inicia con entrega de planos y termina con 100% MEC en sistema)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fechamarcapendientedespacho  ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_mecanizado
			  from mct_progavisos a 
			  left join mct_ordentrabajo b on a.idordentrabajo = b.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 7
			 group by a.fecha_real_termino;
			
			-- Armado
            -- (Inicia con inicio por ML armado y termina con el termino de ML de armado)
			 select min(a.fechainicio) ,
			        coalesce(max(b.fechatermino ), now()) ,
			        --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                    cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 3600)::numeric , 2)), 0) as bigint)*60 +
                    cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_armado
			   from mct_movimientoordentrabajo a 
			   left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  where a.idordentrabajo = rec1.idordentrabajo
			    and a.idaccion = 165
			    and a.iniciaarmadodesarme is true
			  group by a.fechainicio;
  
			-- Informe Reparacion
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de IF en sistema por el responsable)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_informerepara
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 80 and b.idproceso = 8
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			   
			-- Dossier de Calidad
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de DOSSIER en sistema por el encargado de proyectos)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_dossier
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 131 and b.idproceso = 13
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			
			   
			-- Despacho
            -- (se inicia con termino de armado en tableta y termina con despacho en sistema)
			select coalesce(max(b.fechatermino), max(c.fechadespacho)),
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_despacho
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;

			-- Resumen
			select coalesce(max(a.fechacreacion), now()), 
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_resumen
			  from mct_ordentrabajo a
			  --left join mct_movimientoordentrabajo b on a.idestadoorden  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;


			estadobombaenpiso 	:= 'btn-default'; 
		    estadodesarme 		:= 'btn-default'; 
		    estadoevaluacion 	:= 'btn-default';
		    estadocotizacion 	:= 'btn-default'; 
		    estadoautorizacion 	:= 'btn-default'; 
		    estadomecanizado 	:= 'btn-default'; 
		    estadoarmado 		:= 'btn-default'; 
		    estadoinformerepara := 'btn-default'; 
		    estadodossier 		:= 'btn-default'; 
		    estadodespacho 		:= 'btn-default'; 
		    estadoresumen 		:= 'btn-default';

			-- Bomba en piso
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 173
	               and a.fechainicio is not null) then

				estadobombaenpiso 	:= 'btn-success';

			end if;

			-- Desarme
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 173
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadodesarme 	:= 'btn-success';

			end if;

			-- Evaluacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 3
	               and a.estado = 1 ) then

				estadoevaluacion := 'btn-success';

			end if;

			-- Cotizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 4
	               and a.estado = 1 ) then

				estadocotizacion := 'btn-success';

			end if;
			-- Autorizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 5
	               and a.estado = 1 ) then

				estadoautorizacion := 'btn-success';

			end if;

			-- Mecanizado
			if (select 1
                  from mct_ordentrabajo a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.fechamarcapendientedespacho is not null ) then

				estadomecanizado := 'btn-success';

			end if;

			-- Armado
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 164
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadoarmado 	:= 'btn-success';

			end if;

			-- Informe reparacion
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.infcoti = 80 
                   and a.idproceso = 8 ) then

				estadoinformerepara := 'btn-success';

			end if;

			-- Dossier
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.infcoti = 131 
                   and a.idproceso = 13 ) then

				estadodossier := 'btn-success';

			end if;

			-- Despacho
			if (select distinct 1 
                  from mct_despachopartecabecera a
                 where a.idordentrabajo = rec1.idordentrabajo) then

				estadodespacho 		:= 'btn-success';

			end if;

			sp_totalots				:= sp_totalots + 1;

			sp_sumabombaenpiso 		:= sp_sumabombaenpiso + coalesce(sp_bombaenpiso,0);
			sp_sumadesarme 			:= sp_sumadesarme + coalesce(sp_desarme,0);
			sp_sumaevaluacion 		:= sp_sumaevaluacion + coalesce(sp_evaluacion,0);
		    sp_sumacotizacion 		:= sp_sumacotizacion + coalesce(sp_cotizacion,0);
			sp_sumaautorizacion 	:= sp_sumaautorizacion + coalesce(sp_autorizacion,0);
			sp_sumamecanizado 		:= sp_sumamecanizado + coalesce(sp_mecanizado,0);
			sp_sumaarmado 			:= sp_sumaarmado + coalesce(sp_armado,0);
			sp_sumainformerepara 	:= sp_sumainformerepara + coalesce(sp_informerepara,0);
			sp_sumadossier 			:= sp_sumadossier + coalesce(sp_dossier,0);
			sp_sumadespacho 		:= sp_sumadespacho + coalesce(sp_despacho,0);			
			sp_sumaresumen 			:= sp_sumaresumen + coalesce(sp_resumen,0);

			raise notice '%', sp_sumacotizacion||' - '||sp_cotizacion;

			
			end loop;

	 		bombaenpiso 	:= coalesce(sp_sumabombaenpiso / sp_totalots,0);
 			desarme 		:= coalesce(sp_sumadesarme / sp_totalots,0);
 			evaluacion 		:= coalesce(sp_sumaevaluacion / sp_totalots,0);
 	        cotizacion 		:= coalesce(sp_sumacotizacion / sp_totalots,0);
 			autorizacion 	:= coalesce(sp_sumaautorizacion / sp_totalots,0);
 			mecanizado 		:= coalesce(sp_sumamecanizado / sp_totalots,0);
 			armado 			:= coalesce(sp_sumaarmado / sp_totalots,0);
 			informerepara 	:= coalesce(sp_sumainformerepara / sp_totalots,0);
  			dossier 		:= coalesce(sp_sumadossier / sp_totalots,0);
 			despacho 		:= coalesce(sp_sumadespacho / sp_totalots,0);
 			resumen 		:= coalesce(sp_sumaresumen / sp_totalots,0);

			RETURN NEXT;



	elsif (idclientes != -1 and fechadesde != 'NA' and fechahasta != 'NA') then

		 FOR rec1 IN ( 

			-- cliente, tiempo 
			select distinct a.idordentrabajo
			  from mct_ordentrabajo a
			  left join mct_cliente d on a.idcliente = d.idcliente
			 where a.idcliente = idclientes -- ciene del combobox
			   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyymmdd HH24:MI:SS'))  
			   --and (a.fechafaceclte >= TO_TIMESTAMP('20250101'||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP('20250701'||' 23:59:59','yyyymmdd HH24:MI:SS'))  
			   and a.idtipoorden = 1
               and a.idfamilia = 8
			   and a.idordentrabajo >= 30000
			)
			 Loop

			-- Bomba en Piso
            -- (Se inicia con la creación de la OT - termina cuando se inicia en tableta un desarme)
			select a.fechacreacion, 
			       coalesce(min(b.fechainicio), now()) ,
			       --cast(date_part('day', coalesce(min(b.fechainicio), now()) - a.fechacreacion) as bigint)
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_bombaenpiso
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173
			 where a.idordentrabajo = rec1.idordentrabajo
			 group by a.fechacreacion;

			
			-- Desarme
            -- (Se inicia cuando ML inicia desarme - termina con validación de mecánico líder y responsable en tableta)
			select min(a.fechainicio) ,
			       coalesce(max(b.fechatermino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_desarme
			  from mct_movimientoordentrabajo a 
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173 and b.iniciaarmadodesarme is true
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechainicio;
			
			
			-- Evaluacion
            -- (Se inicia cuando ML termina desarme y termina con alojamiento de IT en sistema por el responsable)
			select max(a.fechatermino) ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fechatermino) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_evaluacion
			  from mct_movimientoordentrabajo a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 3
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechatermino;
			    

			-- Cotizacion 
            -- (Se inicia con alojamiento IT en sistema y termina con alojamiento de COT en sistema por el secretario)
			select a.fecha_real_termino ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fecha_real_termino) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
			       sp_fechados,
                   sp_cotizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 4 
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 3
			 group by a.fecha_real_termino;
			
			-- Autorizacion
            -- (Se inicia cuando se aloja la COT y termina con autorización de OT en sistema por el secretario)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_autorizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 5 
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 4
			 group by a.fecha_real_termino;
			 		
			-- Mecanizado  
            -- (Inicia con entrega de planos y termina con 100% MEC en sistema)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fechamarcapendientedespacho  ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_mecanizado
			  from mct_progavisos a 
			  left join mct_ordentrabajo b on a.idordentrabajo = b.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 7
			 group by a.fecha_real_termino;
			
			-- Armado
            -- (Inicia con inicio por ML armado y termina con el termino de ML de armado)
			 select min(a.fechainicio) ,
			        coalesce(max(b.fechatermino ), now()) ,
			        --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                    cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 3600)::numeric , 2)), 0) as bigint)*60 +
                    cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_armado
			   from mct_movimientoordentrabajo a 
			   left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  where a.idordentrabajo = rec1.idordentrabajo
			    and a.idaccion = 165
			    and a.iniciaarmadodesarme is true
			  group by a.fechainicio;
  
			-- Informe Reparacion
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de IF en sistema por el responsable)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_informerepara
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 80 and b.idproceso = 8
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			   
			-- Dossier de Calidad
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de DOSSIER en sistema por el encargado de proyectos)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_dossier
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 131 and b.idproceso = 13
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			
			   
			-- Despacho
            -- (se inicia con termino de armado en tableta y termina con despacho en sistema)
			select coalesce(max(b.fechatermino), max(c.fechadespacho)),
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_despacho
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;

			-- Resumen
			select coalesce(max(a.fechacreacion), now()), 
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_resumen
			  from mct_ordentrabajo a
			  --left join mct_movimientoordentrabajo b on a.idestadoorden  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;


			estadobombaenpiso 	:= 'btn-default'; 
		    estadodesarme 		:= 'btn-default'; 
		    estadoevaluacion 	:= 'btn-default';
		    estadocotizacion 	:= 'btn-default'; 
		    estadoautorizacion 	:= 'btn-default'; 
		    estadomecanizado 	:= 'btn-default'; 
		    estadoarmado 		:= 'btn-default'; 
		    estadoinformerepara := 'btn-default'; 
		    estadodossier 		:= 'btn-default'; 
		    estadodespacho 		:= 'btn-default'; 
		    estadoresumen 		:= 'btn-default';

			-- Bomba en piso
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 173
	               and a.fechainicio is not null) then

				estadobombaenpiso 	:= 'btn-success';

			end if;

			-- Desarme
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 173
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadodesarme 	:= 'btn-success';

			end if;

			-- Evaluacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 3
	               and a.estado = 1 ) then

				estadoevaluacion := 'btn-success';

			end if;

			-- Cotizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 4
	               and a.estado = 1 ) then

				estadocotizacion := 'btn-success';

			end if;
			-- Autorizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 5
	               and a.estado = 1 ) then

				estadoautorizacion := 'btn-success';

			end if;

			-- Mecanizado
			if (select 1
                  from mct_ordentrabajo a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.fechamarcapendientedespacho is not null ) then

				estadomecanizado := 'btn-success';

			end if;

			-- Armado
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 164
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadoarmado 	:= 'btn-success';

			end if;

			-- Informe reparacion
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.infcoti = 80 
                   and a.idproceso = 8 ) then

				estadoinformerepara := 'btn-success';

			end if;

			-- Dossier
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.infcoti = 131 
                   and a.idproceso = 13 ) then

				estadodossier := 'btn-success';

			end if;

			-- Despacho
			if (select distinct 1 
                  from mct_despachopartecabecera a
                 where a.idordentrabajo = rec1.idordentrabajo) then

				estadodespacho 		:= 'btn-success';

			end if;

			sp_totalots				:= sp_totalots + 1;

			sp_sumabombaenpiso 		:= sp_sumabombaenpiso + coalesce(sp_bombaenpiso,0);
			sp_sumadesarme 			:= sp_sumadesarme + coalesce(sp_desarme,0);
			sp_sumaevaluacion 		:= sp_sumaevaluacion + coalesce(sp_evaluacion,0);
		    sp_sumacotizacion 		:= sp_sumacotizacion + coalesce(sp_cotizacion,0);
			sp_sumaautorizacion 	:= sp_sumaautorizacion + coalesce(sp_autorizacion,0);
			sp_sumamecanizado 		:= sp_sumamecanizado + coalesce(sp_mecanizado,0);
			sp_sumaarmado 			:= sp_sumaarmado + coalesce(sp_armado,0);
			sp_sumainformerepara 	:= sp_sumainformerepara + coalesce(sp_informerepara,0);
			sp_sumadossier 			:= sp_sumadossier + coalesce(sp_dossier,0);
			sp_sumadespacho 		:= sp_sumadespacho + coalesce(sp_despacho,0);			
			sp_sumaresumen 			:= sp_sumaresumen + coalesce(sp_resumen,0);

			raise notice '%', sp_sumacotizacion||' - '||sp_cotizacion;

			
			end loop;

	 		bombaenpiso 	:= coalesce(sp_sumabombaenpiso / sp_totalots,0);
 			desarme 		:= coalesce(sp_sumadesarme / sp_totalots,0);
 			evaluacion 		:= coalesce(sp_sumaevaluacion / sp_totalots,0);
 	        cotizacion 		:= coalesce(sp_sumacotizacion / sp_totalots,0);
 			autorizacion 	:= coalesce(sp_sumaautorizacion / sp_totalots,0);
 			mecanizado 		:= coalesce(sp_sumamecanizado / sp_totalots,0);
 			armado 			:= coalesce(sp_sumaarmado / sp_totalots,0);
 			informerepara 	:= coalesce(sp_sumainformerepara / sp_totalots,0);
  			dossier 		:= coalesce(sp_sumadossier / sp_totalots,0);
 			despacho 		:= coalesce(sp_sumadespacho / sp_totalots,0);
 			resumen 		:= coalesce(sp_sumaresumen / sp_totalots,0);

			RETURN NEXT;

	elsif (idevaluadors != -1 and fechadesde != 'NA' and fechahasta != 'NA') then

			
		 FOR rec1 IN ( 
			-- Evaluador, tiempo 
			select distinct a.idordentrabajo
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
			 where a.idusuario = idevaluadors -- viene del combobox
			   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyymmdd HH24:MI:SS'))  
			   --and (a.fechafaceclte >= TO_TIMESTAMP('20250101'||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP('20250701'||' 23:59:59','yyyymmdd HH24:MI:SS'))  
			   and a.idtipoorden = 1
               and a.idfamilia = 8
			   and a.idordentrabajo >= 30000

			)
			 Loop

			-- Bomba en Piso
            -- (Se inicia con la creación de la OT - termina cuando se inicia en tableta un desarme)
			select a.fechacreacion, 
			       coalesce(min(b.fechainicio), now()) ,
			       --cast(date_part('day', coalesce(min(b.fechainicio), now()) - a.fechacreacion) as bigint)
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_bombaenpiso
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173
			 where a.idordentrabajo = rec1.idordentrabajo
			 group by a.fechacreacion;

			
			-- Desarme
            -- (Se inicia cuando ML inicia desarme - termina con validación de mecánico líder y responsable en tableta)
			select min(a.fechainicio) ,
			       coalesce(max(b.fechatermino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_desarme
			  from mct_movimientoordentrabajo a 
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173 and b.iniciaarmadodesarme is true
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechainicio;
			
			
			-- Evaluacion
            -- (Se inicia cuando ML termina desarme y termina con alojamiento de IT en sistema por el responsable)
			select max(a.fechatermino) ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fechatermino) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_evaluacion
			  from mct_movimientoordentrabajo a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 3
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechatermino;
			    

			-- Cotizacion 
            -- (Se inicia con alojamiento IT en sistema y termina con alojamiento de COT en sistema por el secretario)
			select a.fecha_real_termino ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fecha_real_termino) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
			       sp_fechados,
                   sp_cotizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 4 
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 3
			 group by a.fecha_real_termino;
			
			-- Autorizacion
            -- (Se inicia cuando se aloja la COT y termina con autorización de OT en sistema por el secretario)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_autorizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 5 
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 4
			 group by a.fecha_real_termino;
			 		
			-- Mecanizado  
            -- (Inicia con entrega de planos y termina con 100% MEC en sistema)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fechamarcapendientedespacho  ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_mecanizado
			  from mct_progavisos a 
			  left join mct_ordentrabajo b on a.idordentrabajo = b.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 7
			 group by a.fecha_real_termino;
			
			-- Armado
            -- (Inicia con inicio por ML armado y termina con el termino de ML de armado)
			 select min(a.fechainicio) ,
			        coalesce(max(b.fechatermino ), now()) ,
			        --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                    cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 3600)::numeric , 2)), 0) as bigint)*60 +
                    cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_armado
			   from mct_movimientoordentrabajo a 
			   left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  where a.idordentrabajo = rec1.idordentrabajo
			    and a.idaccion = 165
			    and a.iniciaarmadodesarme is true
			  group by a.fechainicio;
  
			-- Informe Reparacion
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de IF en sistema por el responsable)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_informerepara
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 80 and b.idproceso = 8
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			   
			-- Dossier de Calidad
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de DOSSIER en sistema por el encargado de proyectos)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_dossier
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 131 and b.idproceso = 13
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			
			   
			-- Despacho
            -- (se inicia con termino de armado en tableta y termina con despacho en sistema)
			select coalesce(max(b.fechatermino), max(c.fechadespacho)),
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_despacho
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;

			-- Resumen
			select coalesce(max(a.fechacreacion), now()), 
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_resumen
			  from mct_ordentrabajo a
			  --left join mct_movimientoordentrabajo b on a.idestadoorden  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;


			estadobombaenpiso 	:= 'btn-default'; 
		    estadodesarme 		:= 'btn-default'; 
		    estadoevaluacion 	:= 'btn-default';
		    estadocotizacion 	:= 'btn-default'; 
		    estadoautorizacion 	:= 'btn-default'; 
		    estadomecanizado 	:= 'btn-default'; 
		    estadoarmado 		:= 'btn-default'; 
		    estadoinformerepara := 'btn-default'; 
		    estadodossier 		:= 'btn-default'; 
		    estadodespacho 		:= 'btn-default'; 
		    estadoresumen 		:= 'btn-default';

			-- Bomba en piso
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 173
	               and a.fechainicio is not null) then

				estadobombaenpiso 	:= 'btn-success';

			end if;

			-- Desarme
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 173
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadodesarme 	:= 'btn-success';

			end if;

			-- Evaluacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 3
	               and a.estado = 1 ) then

				estadoevaluacion := 'btn-success';

			end if;

			-- Cotizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 4
	               and a.estado = 1 ) then

				estadocotizacion := 'btn-success';

			end if;
			-- Autorizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 5
	               and a.estado = 1 ) then

				estadoautorizacion := 'btn-success';

			end if;

			-- Mecanizado
			if (select 1
                  from mct_ordentrabajo a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.fechamarcapendientedespacho is not null ) then

				estadomecanizado := 'btn-success';

			end if;

			-- Armado
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 164
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadoarmado 	:= 'btn-success';

			end if;

			-- Informe reparacion
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.infcoti = 80 
                   and a.idproceso = 8 ) then

				estadoinformerepara := 'btn-success';

			end if;

			-- Dossier
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.infcoti = 131 
                   and a.idproceso = 13 ) then

				estadodossier := 'btn-success';

			end if;

			-- Despacho
			if (select distinct 1 
                  from mct_despachopartecabecera a
                 where a.idordentrabajo = rec1.idordentrabajo) then

				estadodespacho 		:= 'btn-success';

			end if;

			sp_totalots				:= sp_totalots + 1;

			sp_sumabombaenpiso 		:= sp_sumabombaenpiso + coalesce(sp_bombaenpiso,0);
			sp_sumadesarme 			:= sp_sumadesarme + coalesce(sp_desarme,0);
			sp_sumaevaluacion 		:= sp_sumaevaluacion + coalesce(sp_evaluacion,0);
		    sp_sumacotizacion 		:= sp_sumacotizacion + coalesce(sp_cotizacion,0);
			sp_sumaautorizacion 	:= sp_sumaautorizacion + coalesce(sp_autorizacion,0);
			sp_sumamecanizado 		:= sp_sumamecanizado + coalesce(sp_mecanizado,0);
			sp_sumaarmado 			:= sp_sumaarmado + coalesce(sp_armado,0);
			sp_sumainformerepara 	:= sp_sumainformerepara + coalesce(sp_informerepara,0);
			sp_sumadossier 			:= sp_sumadossier + coalesce(sp_dossier,0);
			sp_sumadespacho 		:= sp_sumadespacho + coalesce(sp_despacho,0);			
			sp_sumaresumen 			:= sp_sumaresumen + coalesce(sp_resumen,0);

			raise notice '%', sp_sumacotizacion||' - '||sp_cotizacion;

			
			end loop;

	 		bombaenpiso 	:= coalesce(sp_sumabombaenpiso / sp_totalots,0);
 			desarme 		:= coalesce(sp_sumadesarme / sp_totalots,0);
 			evaluacion 		:= coalesce(sp_sumaevaluacion / sp_totalots,0);
 	        cotizacion 		:= coalesce(sp_sumacotizacion / sp_totalots,0);
 			autorizacion 	:= coalesce(sp_sumaautorizacion / sp_totalots,0);
 			mecanizado 		:= coalesce(sp_sumamecanizado / sp_totalots,0);
 			armado 			:= coalesce(sp_sumaarmado / sp_totalots,0);
 			informerepara 	:= coalesce(sp_sumainformerepara / sp_totalots,0);
  			dossier 		:= coalesce(sp_sumadossier / sp_totalots,0);
 			despacho 		:= coalesce(sp_sumadespacho / sp_totalots,0);
 			resumen 		:= coalesce(sp_sumaresumen / sp_totalots,0);

			RETURN NEXT;

	elsif (fechadesde != 'NA' and fechahasta != 'NA') then

		
		 FOR rec1 IN ( 
			 -- Total Ots, tiempo 
			select distinct a.idordentrabajo
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
			 where (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyymmdd HH24:MI:SS')) 
			   and a.idtipoorden = 1
               and a.idfamilia = 8
			   and a.idordentrabajo >= 30000

			)
			 Loop

			-- Bomba en Piso
            -- (Se inicia con la creación de la OT - termina cuando se inicia en tableta un desarme)
			select a.fechacreacion, 
			       coalesce(min(b.fechainicio), now()) ,
			       --cast(date_part('day', coalesce(min(b.fechainicio), now()) - a.fechacreacion) as bigint)
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( max(b.fechainicio) - min(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_bombaenpiso
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173
			 where a.idordentrabajo = rec1.idordentrabajo
			 group by a.fechacreacion;

			
			-- Desarme
            -- (Se inicia cuando ML inicia desarme - termina con validación de mecánico líder y responsable en tableta)
			select min(a.fechainicio) ,
			       coalesce(max(b.fechatermino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - min(a.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_desarme
			  from mct_movimientoordentrabajo a 
			  left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 173 and b.iniciaarmadodesarme is true
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechainicio;
			
			
			-- Evaluacion
            -- (Se inicia cuando ML termina desarme y termina con alojamiento de IT en sistema por el responsable)
			select max(a.fechatermino) ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fechatermino) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_evaluacion
			  from mct_movimientoordentrabajo a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 3
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 173
			   and a.iniciaarmadodesarme is true
			group by a.fechatermino;
			    

			-- Cotizacion 
            -- (Se inicia con alojamiento IT en sistema y termina con alojamiento de COT en sistema por el secretario)
			select a.fecha_real_termino ,
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - a.fecha_real_termino) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - min(a.fecha_real_termino) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
			       sp_fechados,
                   sp_cotizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 4 
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 3
			 group by a.fecha_real_termino;
			
			-- Autorizacion
            -- (Se inicia cuando se aloja la COT y termina con autorización de OT en sistema por el secretario)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fecha_real_termino ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fecha_real_termino ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_autorizacion
			  from mct_progavisos a 
			  left join mct_progavisos b on a.idordentrabajo = b.idordentrabajo and b.idsla = 5 
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 4
			 group by a.fecha_real_termino;
			 		
			-- Mecanizado  
            -- (Inicia con entrega de planos y termina con 100% MEC en sistema)
			select coalesce(a.fecha_real_termino , now()),
			       coalesce(max(b.fechamarcapendientedespacho  ), now()) ,
			       --cast(date_part('day', coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now())) as bigint),
				   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechamarcapendientedespacho  ), now()) - coalesce(a.fecha_real_termino , now()) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_mecanizado
			  from mct_progavisos a 
			  left join mct_ordentrabajo b on a.idordentrabajo = b.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idsla = 7
			 group by a.fecha_real_termino;
			
			-- Armado
            -- (Inicia con inicio por ML armado y termina con el termino de ML de armado)
			 select min(a.fechainicio) ,
			        coalesce(max(b.fechatermino ), now()) ,
			        --cast(date_part('day', coalesce(max(b.fechatermino ), now()) - a.fechainicio) as bigint),
                    cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 3600)::numeric , 2)), 0) as bigint)*60 +
                    cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechatermino ), now()) - a.fechainicio)) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_armado
			   from mct_movimientoordentrabajo a 
			   left join mct_movimientoordentrabajo b on a.idordentrabajo = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  where a.idordentrabajo = rec1.idordentrabajo
			    and a.idaccion = 165
			    and a.iniciaarmadodesarme is true
			  group by a.fechainicio;
  
			-- Informe Reparacion
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de IF en sistema por el responsable)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM ( coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino), now() ))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_informerepara
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 80 and b.idproceso = 8
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			   
			-- Dossier de Calidad
            -- (se inicia con termino de armado en tableta y se termina con alojamiento de DOSSIER en sistema por el encargado de proyectos)
			select coalesce(max(a.fechatermino ), now()),
			       coalesce(max(b.fechacreacion), now()),
			       --cast(date_part('day', coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino ), now())) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (coalesce(max(b.fechacreacion), now()) - coalesce(max(a.fechatermino),now() ) )) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_dossier
			  from mct_movimientoordentrabajo a 
			  left join mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 131 and b.idproceso = 13
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion = 165
			   and a.iniciaarmadodesarme is true;
			
			   
			-- Despacho
            -- (se inicia con termino de armado en tableta y termina con despacho en sistema)
			select coalesce(max(b.fechatermino), max(c.fechadespacho)),
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(b.fechatermino))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_despacho
			  from mct_ordentrabajo a
			  left join mct_movimientoordentrabajo b on a.idordentrabajo  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;

			-- Resumen
			select coalesce(max(a.fechacreacion), now()), 
			       coalesce(max(c.fechadespacho), now() ),
			       --cast(date_part('day', coalesce(max(c.fechadespacho), now() ) - coalesce(max(b.fechatermino), max(c.fechadespacho))) as bigint),
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 3600)::numeric , 2)), 0) as bigint)*60 +
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechadespacho) - max(a.fechacreacion))) / 60)::numeric, 60), 0) as bigint) AS minutos
              into sp_fechauno,
				   sp_fechados,
                   sp_resumen
			  from mct_ordentrabajo a
			  --left join mct_movimientoordentrabajo b on a.idestadoorden  = b.idordentrabajo and b.idaccion = 165 and b.iniciaarmadodesarme is true
			  left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			 where a.idordentrabajo = rec1.idordentrabajo;


			estadobombaenpiso 	:= 'btn-default'; 
		    estadodesarme 		:= 'btn-default'; 
		    estadoevaluacion 	:= 'btn-default';
		    estadocotizacion 	:= 'btn-default'; 
		    estadoautorizacion 	:= 'btn-default'; 
		    estadomecanizado 	:= 'btn-default'; 
		    estadoarmado 		:= 'btn-default'; 
		    estadoinformerepara := 'btn-default'; 
		    estadodossier 		:= 'btn-default'; 
		    estadodespacho 		:= 'btn-default'; 
		    estadoresumen 		:= 'btn-default';

			-- Bomba en piso
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 173
	               and a.fechainicio is not null) then

				estadobombaenpiso 	:= 'btn-success';

			end if;

			-- Desarme
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 173
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadodesarme 	:= 'btn-success';

			end if;

			-- Evaluacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 3
	               and a.estado = 1 ) then

				estadoevaluacion := 'btn-success';

			end if;

			-- Cotizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 4
	               and a.estado = 1 ) then

				estadocotizacion := 'btn-success';

			end if;
			-- Autorizacion
			if (select 1
	              from mct_progavisos a
	             where a.idordentrabajo = rec1.idordentrabajo
	               and a.idsla = 5
	               and a.estado = 1 ) then

				estadoautorizacion := 'btn-success';

			end if;

			-- Mecanizado
			if (select 1
                  from mct_ordentrabajo a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.fechamarcapendientedespacho is not null ) then

				estadomecanizado := 'btn-success';

			end if;

			-- Armado
			if (select 1
	              from mct_movimientoordentrabajo a 
	             where a.idordentrabajo = rec1.idordentrabajo 
	               and a.idaccion = 164
	               and a.iniciaarmadodesarme is true
	               and a.fechatermino is not null ) then

				estadoarmado 	:= 'btn-success';

			end if;

			-- Informe reparacion
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.infcoti = 80 
                   and a.idproceso = 8 ) then

				estadoinformerepara := 'btn-success';

			end if;

			-- Dossier
			if (select distinct 1
	              from mct_infcotipdf a
                 where a.idordentrabajo = rec1.idordentrabajo
                   and a.infcoti = 131 
                   and a.idproceso = 13 ) then

				estadodossier := 'btn-success';

			end if;

			-- Despacho
			if (select distinct 1 
                  from mct_despachopartecabecera a
                 where a.idordentrabajo = rec1.idordentrabajo) then

				estadodespacho 		:= 'btn-success';

			end if;

			sp_totalots				:= sp_totalots + 1;

			sp_sumabombaenpiso 		:= sp_sumabombaenpiso + coalesce(sp_bombaenpiso,0);
			sp_sumadesarme 			:= sp_sumadesarme + coalesce(sp_desarme,0);
			sp_sumaevaluacion 		:= sp_sumaevaluacion + coalesce(sp_evaluacion,0);
		    sp_sumacotizacion 		:= sp_sumacotizacion + coalesce(sp_cotizacion,0);
			sp_sumaautorizacion 	:= sp_sumaautorizacion + coalesce(sp_autorizacion,0);
			sp_sumamecanizado 		:= sp_sumamecanizado + coalesce(sp_mecanizado,0);
			sp_sumaarmado 			:= sp_sumaarmado + coalesce(sp_armado,0);
			sp_sumainformerepara 	:= sp_sumainformerepara + coalesce(sp_informerepara,0);
			sp_sumadossier 			:= sp_sumadossier + coalesce(sp_dossier,0);
			sp_sumadespacho 		:= sp_sumadespacho + coalesce(sp_despacho,0);			
			sp_sumaresumen 			:= sp_sumaresumen + coalesce(sp_resumen,0);

			raise notice '%', sp_bombaenpiso||' - '||rec1.idordentrabajo;
			
			end loop;

			raise notice '%', sp_sumabombaenpiso||' - '||bombaenpiso||' - '||sp_totalots;

	 		bombaenpiso 	:= coalesce(sp_sumabombaenpiso / sp_totalots,0);
 			desarme 		:= coalesce(sp_sumadesarme / sp_totalots,0);
 			evaluacion 		:= coalesce(sp_sumaevaluacion / sp_totalots,0);
 	        cotizacion 		:= coalesce(sp_sumacotizacion / sp_totalots,0);
 			autorizacion 	:= coalesce(sp_sumaautorizacion / sp_totalots,0);
 			mecanizado 		:= coalesce(sp_sumamecanizado / sp_totalots,0);
 			armado 			:= coalesce(sp_sumaarmado / sp_totalots,0);
 			informerepara 	:= coalesce(sp_sumainformerepara / sp_totalots,0);
  			dossier 		:= coalesce(sp_sumadossier / sp_totalots,0);
 			despacho 		:= coalesce(sp_sumadespacho / sp_totalots,0);
 			resumen 		:= coalesce(sp_sumaresumen / sp_totalots,0);

			RETURN NEXT;


   	end if;



END;
$$;


ALTER FUNCTION traking.evtlistanalisisremanufacturadetalle(idots bigint, idclientes bigint, idproductos bigint, cantidads bigint, idevaluadors bigint, fechadesde character varying, fechahasta character varying) OWNER TO postgres;

--
-- TOC entry 1580 (class 1255 OID 16871)
-- Name: evtlistanalisisremanufacturadetallearmado(bigint, bigint, bigint, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistanalisisremanufacturadetallearmado(idots bigint, idclientes bigint, idproductos bigint, cantidads bigint, idevaluadors bigint, fechadesde character varying, fechahasta character varying) RETURNS TABLE(difeendias bigint, nombreoperador character varying, otdiferentes bigint, horasminutos numeric, horas bigint, minutos bigint, mecanicolider boolean)
    LANGUAGE plpgsql
    AS $$
declare 

BEGIN 
	
	
   	if (idots != -1) then
			
            RETURN QUERY 

			select cast(date_part('day', coalesce(max(date(c.fechatermino) ), now()) - date(min(c.fechainicio))) as bigint) as difeendias,
                   cast('(ML) - '||d.nombreoperador as varchar),
                   cast(count(distinct(a.idordentrabajo)) as bigint) as otdiferentes,
                   cast(coalesce(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2), 0) as numeric) as horasminutos,
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2)), 0) as bigint) as horas,
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos,
                   true as mecanicolider
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
              left join mct_movimientoordentrabajo c on a.idordentrabajo = c.idordentrabajo and c.idaccion = 165 and c.iniciaarmadodesarme is true
              left join mct_operador d on c.idoperador = d.idoperador
			 where a.idordentrabajo = idots
               and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
               and c.idoperador is not null
             group by d.nombreoperador
			union
			 -- Total Ots, tiempo 
			select cast(date_part('day', coalesce(max(date(c.fechatermino) ), now()) - date(min(c.fechainicio))) as bigint) as difeendias,
                   d.nombreoperador,
                   cast(count(distinct(a.idordentrabajo)) as bigint) as otdiferentes,
                   cast(coalesce(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2), 0) as numeric) as horasminutos,
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2)), 0) as bigint) as horas,
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos,
                   false as mecanicolider
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
              left join mct_movimientoordentrabajo c on a.idordentrabajo = c.idordentrabajo and c.idaccion = 165 and c.iniciaarmadodesarme is false
              left join mct_operador d on c.idoperador = d.idoperador
			 where a.idordentrabajo = idots   
			   and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
               and c.idoperador is not null
             group by d.nombreoperador
			order by mecanicolider desc;


   	elsif (idclientes != -1 and idproductos != -1 and cantidads != -1) then


            RETURN QUERY 

			select cast(date_part('day', coalesce(max(date(c.fechatermino) ), now()) - date(min(c.fechainicio))) as bigint) as difeendias,
                   cast('(ML) - '||d.nombreoperador as varchar),
				   cast(count(distinct(a.idordentrabajo)) as bigint) as otdiferentes,
                   cast(coalesce(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2), 0) as numeric) as horasminutos,
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2)), 0) as bigint) as horas,
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos,
                   true as mecanicolider
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
              left join mct_movimientoordentrabajo c on a.idordentrabajo = c.idordentrabajo and c.idaccion = 165 and c.iniciaarmadodesarme is true
              left join mct_operador d on c.idoperador = d.idoperador
			 where a.idcliente = idclientes -- viene del combobox
               and a.idproducto = idproductos -- viene del combobox
               and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
               and c.idoperador is not null
             group by d.nombreoperador
			union
			 -- Total Ots, tiempo 
			select cast(date_part('day', coalesce(max(date(c.fechatermino) ), now()) - date(min(c.fechainicio))) as bigint) as difeendias,
                   d.nombreoperador,
				   cast(count(distinct(a.idordentrabajo)) as bigint) as otdiferentes,
                   cast(coalesce(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2), 0) as numeric) as horasminutos,
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2)), 0) as bigint) as horas,
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos,
                   false as mecanicolider
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
              left join mct_movimientoordentrabajo c on a.idordentrabajo = c.idordentrabajo and c.idaccion = 165 and c.iniciaarmadodesarme is false
              left join mct_operador d on c.idoperador = d.idoperador
			 where a.idcliente = idclientes -- viene del combobox
               and a.idproducto = idproductos -- viene del combobox		   
			   and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
               and c.idoperador is not null
             group by d.nombreoperador
			order by mecanicolider desc;


	elsif (idclientes != -1 and fechadesde != 'NA' and fechahasta != 'NA') then

            RETURN QUERY 

			select cast(date_part('day', coalesce(max(date(c.fechatermino) ), now()) - date(min(c.fechainicio))) as bigint) as difeendias,
                   cast('(ML) - '||d.nombreoperador as varchar),
				   cast(count(distinct(a.idordentrabajo)) as bigint) as otdiferentes,
                   cast(coalesce(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2), 0) as numeric) as horasminutos,
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2)), 0) as bigint) as horas,
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos,
                   true as mecanicolider
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
              left join mct_movimientoordentrabajo c on a.idordentrabajo = c.idordentrabajo and c.idaccion = 165 and c.iniciaarmadodesarme is true
              left join mct_operador d on c.idoperador = d.idoperador
			 where (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyymmdd HH24:MI:SS'))  
			   and a.idcliente = idclientes -- ciene del combobox
               and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
               and c.idoperador is not null
             group by d.nombreoperador
			union
			 -- Total Ots, tiempo 
			select cast(date_part('day', coalesce(max(date(c.fechatermino) ), now()) - date(min(c.fechainicio))) as bigint) as difeendias,
                   d.nombreoperador,
