                   cast(coalesce(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2), 0) as numeric) as horasminutos,
                   cast(coalesce(FLOOR(round((EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 3600)::numeric , 2)), 0) as bigint) as horas,
                   cast(coalesce(MOD(round(EXTRACT(EPOCH FROM (max(c.fechatermino) - min(c.fechainicio))) / 60)::numeric, 60), 0) as bigint) AS minutos,
                   false as mecanicolider
			  from mct_ordentrabajo a
			  left join mct_usuario b on a.idusuario = b.idusuario 
              left join mct_movimientoordentrabajo c on a.idordentrabajo = c.idordentrabajo and c.idaccion = 173 and c.iniciaarmadodesarme is false
              left join mct_operador d on c.idoperador = d.idoperador
			 where (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyymmdd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyymmdd HH24:MI:SS'))  
			   and a.idtipoorden = 1
			   and a.idordentrabajo >= 30000
               and c.idoperador is not null
             group by d.nombreoperador
			order by mecanicolider desc;


   	end if;

END;
$$;


