CREATE FUNCTION traking.evtlistbodytracing(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idpartworkorder bigint, idpart bigint, partname character varying, timeday integer, tothour character varying, deadtime character varying, idroadmap bigint, coderoadmap character varying, lastactivity character varying, statuslastactivity bigint, stjason character varying)
    LANGUAGE plpgsql
    AS $$
declare

		sp_jason	    varchar;
		sp_lastacti 	VARCHAR;
	    sp_estadolast   integer;
		rec1 			record;
		rec2			record;
