		--	  mct_productoparte b
	  --  where idordentrabajo = idworkorders
		--  and a.idproducto  = b.idproducto ;
			    
	   if ( sp_piezas > 1 ) then

	   	   FOR rec1 IN (   
					select a.idordentrabajo        as idordentrabajo,
					       a.idordentrabajoparte   as idordentrabajoparte,
