					)
		loop 				 
		
		       sp_jason 	 := '';
		       sp_lastacti	 := '';
		       sp_estadolast := 0;
		       sp_horasop    := 0;
		       sp_horasmuertas := 0;
		       sp_tiempo	   := 0;
		      
		      select min(fechainicio),
