CREATE FUNCTION traking.evtlistbodytracingts(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idpartworkorder bigint, idpart bigint, partname character varying, timeday integer, tothour character varying, deadtime character varying, idroadmap bigint, coderoadmap character varying, lastactivity character varying, statuslastactivity bigint, stjason character varying, rownum integer, idmovot bigint, actioncode character varying, activstatus bigint, itemcorr character varying, maquina character varying, plano character varying, operador character varying)
    LANGUAGE plpgsql
    AS $$
declare	 

		sp_jason	    varchar;
		sp_lastacti 	VARCHAR;
	    sp_estadolast   integer;
		rec1 			record;
		rec2			record;
	    minfecha        timestamp;
	    maxfecha        timestamp;
	   
	    sp_horasop      integer;
	    sp_horasmuertas integer;
	   
	    sp_tiempo		integer;
