-- Name: evtlistbodytracingts_resp31032025(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistbodytracingts_resp31032025(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idpartworkorder bigint, idpart bigint, partname character varying, timeday integer, tothour character varying, deadtime character varying, idroadmap bigint, coderoadmap character varying, lastactivity character varying, statuslastactivity bigint, stjason character varying, rownum integer, idmovot bigint, actioncode character varying, activstatus bigint, itemcorr character varying, maquina character varying, plano character varying, operador character varying)
    LANGUAGE plpgsql
    AS $$
declare	 

		sp_jason	    varchar;
		sp_lastacti 	VARCHAR;
	    sp_estadolast   integer;
		rec1 			record;
		rec2			record;
	    minfecha        timestamp;
	    maxfecha        timestamp;
	   
	    sp_horasop      integer;
	    sp_horasmuertas integer;
	   
	    sp_tiempo		integer;
	    sp_piezas       integer := 0;
	    sp_diferencia   varchar;
	    intervalo       varchar;
	   
	    sp_maquina		varchar;
	    sp_operador		varchar;
	    
	    sp_aplica		boolean;
	   
BEGIN
	
    --RETURN QUERY
    
	  -- select count(*)
	  --   into sp_piezas
	   --  from mct_ordentrabajo a,
	--		  mct_productoparte b
	  --  where idordentrabajo = idworkorders
	--	  and a.idproducto  = b.idproducto ;
			    
					  
	   if ( sp_piezas > 1 and idworkorders != 30055 and idworkorders != 30054 and idworkorders != 30063) then

	   	   FOR rec1 IN (  
	   	   
					select a.idordentrabajo        as idordentrabajo,
					       a.idordentrabajoparte   as idordentrabajoparte,
					       a.idparte               as idparte ,
					       b.nombreparte           as nombreparte,
					       1                       as uno,
					       c.idhojaruta            as idhojaruta,
					       c.codhojaruta           as codhojaruta,
					       row_number() over (order by d.idmovimientoordentrabajo ), 
					       d.idmovimientoordentrabajo, 
					       d.codigoaccion, 
					       cast(case
					          when d.fechatermino is null then
					          	   cast((date_part('day', now()::timestamp - d.fechainicio::timestamp ) * 1440 + 
						         		 date_part('hour', now()::timestamp - d.fechainicio::timestamp ) * 60 + 
								 		 date_part('minute', now()::timestamp - d.fechainicio::timestamp )) as integer)
					          when d.fechatermino is not null then 
					          	   cast((date_part('day', d.fechatermino::timestamp - d.fechainicio::timestamp ) * 1440 + 
						         		 date_part('hour', d.fechatermino::timestamp - d.fechainicio::timestamp ) * 60 + 
								 		 date_part('minute', d.fechatermino::timestamp - d.fechainicio::timestamp )) as integer)		          
					       end as varchar)as tiempo,
					       d.estadoactividad,
					       d.idcausacierre ,
					       d.idmotivocierre ,
					       a.itemcorr ,
					       c.idhojarutatemp
					  from mct_ordentrabajoparte a
					  inner join mct_parte b    on a.idparte = b.idparte
					  inner join mct_hojaruta c on a.idordentrabajoparte = c.idordentrabajoparte
					  left  join mct_movimientoordentrabajo d on c.idhojaruta = d.idhojaruta
					 where a.idordentrabajo = idworkorders
					   --and d.codigoaccion is not null
					  order by b.nombreparte asc, c.codhojaruta asc, d.idmovimientoordentrabajo asc
					  
					)
		  loop 				 
		
		       sp_jason 	   := '';
		       sp_lastacti	   := '';
		       sp_estadolast   := 0;
		       sp_horasop      := 0;
		       sp_horasmuertas := 0;
		       sp_tiempo	   := 0;
		       sp_aplica	   := false;

		      select aplicahojaruta 
		        into sp_aplica
		        from mct_hojarutatemp mh 
		       where idhojarutatemp = rec1.idhojarutatemp;		      
		      
		      if (sp_aplica is true ) then
		      
		      
			      select min(fechainicio),
			             coalesce( max(fechatermino), now())
			        into minfecha,
			             maxfecha
			        from mct_movimientoordentrabajo
			       where idhojaruta = rec1.idhojaruta;
			      
			      select cast((date_part('day', (maxfecha)::timestamp - (minfecha)::timestamp ) * 1440 + 
							   date_part('hour', (maxfecha)::timestamp - (minfecha)::timestamp ) * 60 + 
							   date_part('minute', (maxfecha)::timestamp - (minfecha)::timestamp )) as integer) 
				    into sp_tiempo		;
			      
				  select sum( case
						         when fechatermino is null then
					          	   cast((date_part('day', now()::timestamp - (fechainicio)::timestamp ) * 1440 + 
						         		 date_part('hour', now()::timestamp - (fechainicio)::timestamp ) * 60 + 
								 		 date_part('minute', now()::timestamp - (fechainicio)::timestamp )) as integer)
					             when fechatermino is not null then 
					          	   cast((date_part('day', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 1440 + 
							         		 date_part('hour', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 60 + 
									 		 date_part('minute', (fechatermino)::timestamp - (fechainicio)::timestamp )) as integer)		          
						       end ) as horastot,
							  sp_tiempo - sum( case
								         when fechatermino is null then
							          	   cast((date_part('day', now()::timestamp - (fechainicio)::timestamp ) * 1440 + 
								         		 date_part('hour', now()::timestamp - (fechainicio)::timestamp ) * 60 + 
										 		 date_part('minute', now()::timestamp - (fechainicio)::timestamp )) as integer)
							             when fechatermino is not null then 
							          	   cast((date_part('day', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 1440 + 
									         		 date_part('hour', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 60 + 
											 		 date_part('minute', (fechatermino)::timestamp - (fechainicio)::timestamp )) as integer)		          
						       end ) as horasmuertas
			        into sp_horasop,
			             sp_horasmuertas
					from mct_movimientoordentrabajo 
				   where idhojaruta = rec1.idhojaruta;
	
			      
			      select a.codigoaccion, 
			             a.estadoactividad,
			             c.nombremaquina
			        into sp_lastacti, 
			             sp_estadolast,
			             sp_maquina
			        from mct_movimientoordentrabajo a
			        left join mct_maquina c on a.idmaquina = c.idmaquina
			       where a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
			                                           from mct_movimientoordentrabajo b 
			                                          where b.idhojaruta = rec1.idhojaruta );
	
			      intervalo := ''''||rec1.tiempo||' minute';
			      sp_diferencia     :=  to_char(intervalo::interval, 'HH24:MI');
			     
			      idworkorder		:=  rec1.idordentrabajo; 
			      idpartworkorder 	:=	rec1.idordentrabajoparte; 
			      idpart 			:=	rec1.idparte; 
			      partname 			:=	rec1.nombreparte;
			      timeday 			:=	rec1.uno; 
			      tothour 			:=	sp_horasop; 
			      deadtime 			:=	sp_horasmuertas; 
			      idroadmap 		:=	rec1.idhojaruta; 
			      coderoadmap 		:=	rec1.codhojaruta; 
			      lastactivity 		:=	sp_lastacti;
			      statuslastactivity:=  sp_estadolast;
			      stjason			:=	sp_jason;
			     
			      rownum            :=  rec1.row_number; 
				  idmovot           :=  rec1.idmovimientoordentrabajo;
				  actioncode        :=  rec1.codigoaccion||'/('||sp_diferencia||')';
				  activstatus       :=  rec1.estadoactividad;
				  itemcorr          := LPAD(rec1.itemcorr::integer::text::varchar, 2, '0');  
				  maquina			:= coalesce(sp_maquina, 'NO APLICA MÁQUINA');
			     
			      RETURN NEXT;		      
		      
		      
		      end if;

		     
			END LOOP;
	   
	   else

	   	   FOR rec1 IN (   		

					select a.idordentrabajo            as idordentrabajo,
					       a.idordentrabajoparte       as idordentrabajoparte,
					       a.idcomponente              as idparte ,
					      -- coalesce (b.nombrecomponente||' '||e.textoadicional , b.nombrecomponente)         as nombreparte,
					       coalesce ( upper( coalesce(e.componentechecklist, b.nombrecomponente) )||' - '||e.textoadicional , b.nombrecomponente)         as nombreparte,
					       1                           as uno,
					       c.idhojaruta                as idhojaruta,
					       c.codhojaruta               as codhojaruta,
					       row_number() over (order by d.idmovimientoordentrabajo ), 
					       d.idmovimientoordentrabajo, 
					       d.codigoaccion, 
						   cast(case
					          when d.fechatermino is null then
					          	   cast((date_part('day', now()::timestamp - d.fechainicio::timestamp ) * 1440 + 
						         		 date_part('hour', now()::timestamp - d.fechainicio::timestamp ) * 60 + 
								 		 date_part('minute', now()::timestamp - d.fechainicio::timestamp )) as integer)
					          when d.fechatermino is not null then 
					          	   cast((date_part('day', d.fechatermino::timestamp - d.fechainicio::timestamp ) * 1440 + 
						         		 date_part('hour', d.fechatermino::timestamp - d.fechainicio::timestamp ) * 60 + 
								 		 date_part('minute', d.fechatermino::timestamp - d.fechainicio::timestamp )) as integer)		          
					       end as varchar) as tiempo,
					       d.estadoactividad,
					       d.idcausacierre ,
					       d.idmotivocierre ,
					       a.itemcorr,
					       e.idareaclasificacion ,
					       coalesce (g.sigla, 'STD') as sigla,
					       coalesce (e.nombrezona , 'I') as siglazona,
					       c.idhojarutatemp,
					       e.nombreplano
					  from mct_ordentrabajoparte a
					  inner join mct_componente b             on a.idcomponente = b.idcomponente 
					  inner join mct_hojaruta c               on a.idordentrabajoparte = c.idordentrabajoparte     
					   left join mct_movimientoordentrabajo d on c.idhojaruta = d.idhojaruta    
					   left join mct_detallehojarutatemp f    on c.codhojaruta = f.codhojaruta 
					   left join mct_hojarutatemp e           on e.idhojarutatemp  = f.idhojarutatemp  
					   left join mct_areaclasificacion g      on e.idareaclasificacion = g.idareaclasificacion 
					 where a.idordentrabajo = idworkorders
					   and e.idcriterioevaluacion != 7
					   and a.idordentrabajoparte not in (4208,4209,4210,4199,4200,4181,4182,4183,4184,4174,4175,4176,4177,4203,4204,4205,4206)
					   --and d.codigoaccion is not null
					  --and d.codigoaccion not in ('N/M') --and (d.codigoaccion != '' or d.codigoaccion != null)
					  --order by e.idareaclasificacion asc, b.nombrecomponente asc,c.codhojaruta asc, d.idmovimientoordentrabajo asc
					   order by coalesce (e.nombrezona,'I')  asc, b.nombrecomponente asc, c.codhojaruta asc, d.idmovimientoordentrabajo asc


					)
		   loop 				 
		
		       sp_jason 	   := '';
		       sp_lastacti	   := '';
		       sp_estadolast   := 0;
		       sp_horasop      := 0;
		       sp_horasmuertas := 0;
		       sp_tiempo	   := 0;
		      
		      sp_aplica	   := false;

		      select aplicahojaruta 
		        into sp_aplica
		        from mct_hojarutatemp mh 
		       where idhojarutatemp = rec1.idhojarutatemp;

		      if (sp_aplica is true ) then
		      
			      select min(fechainicio),
			             coalesce( max(fechatermino), now())
			        into minfecha,
			             maxfecha
			        from mct_movimientoordentrabajo
			       where idhojaruta = rec1.idhojaruta;
			      
			      select cast((date_part('day', (maxfecha)::timestamp - (minfecha)::timestamp ) * 1440 + 
							   date_part('hour', (maxfecha)::timestamp - (minfecha)::timestamp ) * 60 + 
							   date_part('minute', (maxfecha)::timestamp - (minfecha)::timestamp )) as integer) 
				    into sp_tiempo		;
			      
				  select sum( case
						         when fechatermino is null then
					          	   cast((date_part('day', now()::timestamp - (fechainicio)::timestamp ) * 1440 + 
						         		 date_part('hour', now()::timestamp - (fechainicio)::timestamp ) * 60 + 
								 		 date_part('minute', now()::timestamp - (fechainicio)::timestamp )) as integer)
					             when fechatermino is not null then 
					          	   cast((date_part('day', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 1440 + 
							         		 date_part('hour', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 60 + 
									 		 date_part('minute', (fechatermino)::timestamp - (fechainicio)::timestamp )) as integer)		          
						       end ) as horastot,
							  sp_tiempo - sum( case
								         when fechatermino is null then
							          	   cast((date_part('day', now()::timestamp - (fechainicio)::timestamp ) * 1440 + 
								         		 date_part('hour', now()::timestamp - (fechainicio)::timestamp ) * 60 + 
										 		 date_part('minute', now()::timestamp - (fechainicio)::timestamp )) as integer)
							             when fechatermino is not null then 
							          	   cast((date_part('day', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 1440 + 
									         		 date_part('hour', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 60 + 
											 		 date_part('minute', (fechatermino)::timestamp - (fechainicio)::timestamp )) as integer)		          
						       end ) as horasmuertas
			        into sp_horasop,
			             sp_horasmuertas
					from mct_movimientoordentrabajo 
				   where idhojaruta = rec1.idhojaruta;
	
			      
			      select a.codigoaccion, 
			             a.estadoactividad,
			             c.nombremaquina,
			             d.nombreoperador 
			        into sp_lastacti, 
			             sp_estadolast,
			             sp_maquina,
		                 sp_operador
			        from mct_movimientoordentrabajo a
			        left join mct_maquina c on a.idmaquina = c.idmaquina
			        left join mct_operador d on a.idoperador = d.idoperador
			       where a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
			                                           from mct_movimientoordentrabajo b 
			                                          where b.idhojaruta = rec1.idhojaruta );
			                                        		                                         
			      
			      if (rec1.codigoaccion = 'N/M') then
			      
			      else
	
				      intervalo := ''''||rec1.tiempo||' minute';
				      sp_diferencia     :=  to_char(intervalo::interval, 'HH24:MI');
				      
				      idworkorder		:=  rec1.idordentrabajo; 
				      idpartworkorder 	:=	rec1.idordentrabajoparte; 
				      idpart 			:=	rec1.idparte; 
				      partname 			:=	rec1.nombreparte;
				      timeday 			:=	rec1.uno; 
				      tothour 			:=	sp_horasop; 
				      deadtime 			:=	sp_horasmuertas; 
				      idroadmap 		:=	rec1.idhojaruta; 
				      coderoadmap 		:=	rec1.codhojaruta; 
				      lastactivity 		:=	sp_lastacti;
				      statuslastactivity:=  sp_estadolast;
				      stjason			:=	sp_jason;
				     
				      rownum            :=  rec1.row_number; 
					  idmovot           :=  rec1.idmovimientoordentrabajo;
					  actioncode        :=  rec1.codigoaccion||'/('||sp_diferencia||')';
					  itemcorr          :=  rec1.siglazona||'-'||rec1.sigla||'-'||LPAD(rec1.itemcorr::integer::text::varchar, 3, '0');  
					  maquina			:= coalesce(sp_maquina, 'NO APLICA MÁQUINA');
					  plano				:= rec1.nombreplano;
					  operador			:=  sp_operador;
					 
					  if rec1.idcausacierre = rec1.idmotivocierre and
					     rec1.idcausacierre = 81 then 
					     activstatus       :=  3;
					  else 
					     activstatus       :=  rec1.estadoactividad;
					  end if;
					 
				     
				      RETURN NEXT;
			     
			      end if;		      
		      
		      end if;

		     
		END LOOP;
	   
	   end if;
			 		 
	
END;
$$;


