				  actioncode        :=  rec1.codigoaccion||'/('||sp_diferencia||')';
				  activstatus       :=  rec1.estadoactividad;
				  itemcorr          := LPAD(rec1.itemcorr::integer::text::varchar, 2, '0');  
				  maquina			:= coalesce(sp_maquina, 'NO APLICA MÁQUINA');
			     
			      RETURN NEXT;		      
		      
		      
		      end if;

		     
			END LOOP;
	   
	   else

	   	   FOR rec1 IN (   		

					select tab.idordentrabajo,
					       tab.idordentrabajoparte,
					       tab.idparte ,					      
					       tab.nombreparte,
					       tab.uno,
					       tab.idhojaruta,
					       tab.codhojaruta,
					       row_number() over (order by tab.idmovimientoordentrabajo ), 
					       tab.idmovimientoordentrabajo, 
					       tab.codigoaccion, 
                           tab.idaccion,
						   tab.tiempo,
					       tab.estadoactividad,
					       tab.idcausacierre ,
					       tab.idmotivocierre ,
					       tab.itemcorr,
					       tab.idareaclasificacion ,
					       tab.sigla,
					       tab.siglazona,
					       tab.idhojarutatemp,
					       tab.nombreplano
					  from (   
							select a.idordentrabajo            as idordentrabajo,
							       a.idordentrabajoparte       as idordentrabajoparte,
							       a.idcomponente              as idparte ,
							      -- coalesce (b.nombrecomponente||' '||e.textoadicional , b.nombrecomponente)         as nombreparte,
							       coalesce ( upper( coalesce(e.componentechecklist, b.nombrecomponente) )||' - '||e.textoadicional , b.nombrecomponente)         as nombreparte,
							       1                           as uno,
							       c.idhojaruta                as idhojaruta,
							       c.codhojaruta               as codhojaruta,
							       --row_number() over (order by d.idmovimientoordentrabajo ), 
							       d.idmovimientoordentrabajo, 
							       d.codigoaccion, 
								   d.idaccion,
								   cast(case
							          when d.fechatermino is null then
							          	   cast((date_part('day', now()::timestamp - d.fechainicio::timestamp ) * 1440 + 
								         		 date_part('hour', now()::timestamp - d.fechainicio::timestamp ) * 60 + 
										 		 date_part('minute', now()::timestamp - d.fechainicio::timestamp )) as integer)
							          when d.fechatermino is not null then 
							          	   cast((date_part('day', d.fechatermino::timestamp - d.fechainicio::timestamp ) * 1440 + 
								         		 date_part('hour', d.fechatermino::timestamp - d.fechainicio::timestamp ) * 60 + 
										 		 date_part('minute', d.fechatermino::timestamp - d.fechainicio::timestamp )) as integer)		          
							       end as varchar) as tiempo,
							       d.estadoactividad,
							       d.idcausacierre ,
							       d.idmotivocierre ,
							       a.itemcorr,
							       e.idareaclasificacion ,
							       coalesce (g.sigla, 'STD') as sigla,
							       coalesce (e.nombrezona , 'I') as siglazona,
							       c.idhojarutatemp,
							       e.nombreplano,
                  				   coalesce (e.nombrezona,'I') as nombrezona, 
                                   b.nombrecomponente 
							  from mct_ordentrabajoparte a
							  inner join mct_componente b             on a.idcomponente = b.idcomponente 
							  inner join mct_hojaruta c               on a.idordentrabajoparte = c.idordentrabajoparte     
							   left join mct_movimientoordentrabajo d on c.idhojaruta = d.idhojaruta    
							   left join mct_detallehojarutatemp f    on c.codhojaruta = f.codhojaruta 
							   left join mct_hojarutatemp e           on e.idhojarutatemp  = f.idhojarutatemp  
							   left join mct_areaclasificacion g      on e.idareaclasificacion = g.idareaclasificacion 
							 where a.idordentrabajo = idworkorders
							   and e.idcriterioevaluacion != 7
							   and a.idordentrabajoparte not in (4208,4209,4210,4199,4200,4181,4182,4183,4184,4174,4175,4176,4177,4203,4204,4205,4206)
							union   
							 select a.idordentrabajo            as idordentrabajo,
							        0                           as idordentrabajoparte,
							        0                           as idparte ,
							        coalesce ( 'NO APLICA')     as nombreparte,
							        1                           as uno,
							        a.idhojaruta                as idhojaruta,
							        a.codhojaruta               as codhojaruta,
							        --row_number() over (order by a.idmovimientoordentrabajo ),
							        a.idmovimientoordentrabajo, 
							        a.codigoaccion, 
                                    a.idaccion,
								    cast(case
							          when a.fechatermino is null then
							          	   cast((date_part('day', now()::timestamp - a.fechainicio::timestamp ) * 1440 + 
								         		 date_part('hour', now()::timestamp - a.fechainicio::timestamp ) * 60 + 
										 		 date_part('minute', now()::timestamp - a.fechainicio::timestamp )) as integer)
							          when a.fechatermino is not null then 
							          	   cast((date_part('day', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 1440 + 
								         		 date_part('hour', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 60 + 
										 		 date_part('minute', a.fechatermino::timestamp - a.fechainicio::timestamp )) as integer)		          
							        end as varchar) as tiempo,
							        a.estadoactividad,
							        a.idcausacierre ,
							        a.idmotivocierre ,
							        '00' as itemcorr,
							        0 as idareaclasificacion ,
							        'STD' as sigla,
							        'I' as siglazona,
							        0 as idhojarutatemp,
							        c.planogeneral,
                                    cast('X' as varchar) as nombrezona, 
                                    cast('NO APLICA' as varchar) as nombrecomponente
							   from mct_movimientoordentrabajo a 
							   left join mct_ordentrabajo b on a.idordentrabajo = b.idordentrabajo
							   left join mct_producto c on b.idproducto = c.idproducto
							  where a.idordentrabajo = idworkorders
							    and a.idaccion in (165, 173)
						) tab
					   order by coalesce (tab.nombrezona,'I')  asc, tab.nombrecomponente asc, tab.codhojaruta asc, tab.idmovimientoordentrabajo asc

					)
		   loop 				 
		
		       sp_jason 	   := '';
		       sp_lastacti	   := '';
		       sp_estadolast   := 0;
		       sp_horasop      := 0;
		       sp_horasmuertas := 0;
		       sp_tiempo	   := 0;
		      
		      sp_aplica	   := false;

				if (rec1.idaccion in (165, 173) ) then
					sp_aplica	   := true;				
				else

				    select aplicahojaruta 
				      into sp_aplica
				      from mct_hojarutatemp mh 
		             where idhojarutatemp = rec1.idhojarutatemp;				
				
				end if;

		      if (sp_aplica is true ) then
		      
			      select min(fechainicio),
			             coalesce( max(fechatermino), now())
			        into minfecha,
			             maxfecha
			        from mct_movimientoordentrabajo
			       where idhojaruta = rec1.idhojaruta;
			      
			      select cast((date_part('day', (maxfecha)::timestamp - (minfecha)::timestamp ) * 1440 + 
							   date_part('hour', (maxfecha)::timestamp - (minfecha)::timestamp ) * 60 + 
							   date_part('minute', (maxfecha)::timestamp - (minfecha)::timestamp )) as integer) 
				    into sp_tiempo		;
			      
				  select sum( case
						         when fechatermino is null then
					          	   cast((date_part('day', now()::timestamp - (fechainicio)::timestamp ) * 1440 + 
						         		 date_part('hour', now()::timestamp - (fechainicio)::timestamp ) * 60 + 
								 		 date_part('minute', now()::timestamp - (fechainicio)::timestamp )) as integer)
					             when fechatermino is not null then 
					          	   cast((date_part('day', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 1440 + 
							         		 date_part('hour', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 60 + 
									 		 date_part('minute', (fechatermino)::timestamp - (fechainicio)::timestamp )) as integer)		          
						       end ) as horastot,
							  sp_tiempo - sum( case
								         when fechatermino is null then
							          	   cast((date_part('day', now()::timestamp - (fechainicio)::timestamp ) * 1440 + 
								         		 date_part('hour', now()::timestamp - (fechainicio)::timestamp ) * 60 + 
										 		 date_part('minute', now()::timestamp - (fechainicio)::timestamp )) as integer)
							             when fechatermino is not null then 
							          	   cast((date_part('day', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 1440 + 
									         		 date_part('hour', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 60 + 
											 		 date_part('minute', (fechatermino)::timestamp - (fechainicio)::timestamp )) as integer)		          
						       end ) as horasmuertas
			        into sp_horasop,
			             sp_horasmuertas
					from mct_movimientoordentrabajo 
				   where idhojaruta = rec1.idhojaruta;
	
			      
			      select a.codigoaccion, 
			             a.estadoactividad,
			             c.nombremaquina,
			             d.nombreoperador 
			        into sp_lastacti, 
			             sp_estadolast,
			             sp_maquina,
		                 sp_operador
			        from mct_movimientoordentrabajo a
			        left join mct_maquina c on a.idmaquina = c.idmaquina
			        left join mct_operador d on a.idoperador = d.idoperador
			       where a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
			                                           from mct_movimientoordentrabajo b 
			                                          where b.idhojaruta = rec1.idhojaruta );
			                                        		                                         
			      
			      if (rec1.codigoaccion = 'N/M') then
			      
			      else
	
				      intervalo := ''''||rec1.tiempo||' minute';
				      sp_diferencia     :=  to_char(intervalo::interval, 'HH24:MI');
				      
				      idworkorder		:=  rec1.idordentrabajo; 
				      idpartworkorder 	:=	rec1.idordentrabajoparte; 
				      idpart 			:=	rec1.idparte; 
				      partname 			:=	rec1.nombreparte;
				      timeday 			:=	rec1.uno; 
				      tothour 			:=	sp_horasop; 
				      deadtime 			:=	sp_horasmuertas; 
				      idroadmap 		:=	rec1.idhojaruta; 
				      coderoadmap 		:=	rec1.codhojaruta; 
				      lastactivity 		:=	sp_lastacti;
				      statuslastactivity:=  sp_estadolast;
				      stjason			:=	sp_jason;
				     
				      rownum            :=  rec1.row_number; 
					  idmovot           :=  rec1.idmovimientoordentrabajo;
					  actioncode        :=  rec1.codigoaccion||'/('||sp_diferencia||')';
					  itemcorr          :=  rec1.siglazona||'-'||rec1.sigla||'-'||LPAD(rec1.itemcorr::integer::text::varchar, 3, '0');  
					  maquina			:= coalesce(sp_maquina, 'NO APLICA MÁQUINA');
					  plano				:= rec1.nombreplano;
					  operador			:=  sp_operador;
					 
					  if rec1.idcausacierre = rec1.idmotivocierre and
					     rec1.idcausacierre = 81 then 
					     activstatus       :=  3;
					  else 
					     activstatus       :=  rec1.estadoactividad;
					  end if;
					 
				     
				      RETURN NEXT;
			     
			      end if;		      
		      
		      end if;

		     
		END LOOP;
	   
	   end if;
			 		 
	
END;
$$;


ALTER FUNCTION traking.evtlistbodytracingts_sqz(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1931 (class 1255 OID 16885)
-- Name: evtlistcalculoequipocirculante(bigint, bigint, character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcalculoequipocirculante(idevaluators bigint, ots bigint, sdate character varying, edate character varying, annos bigint) RETURNS TABLE(item bigint, idworkorder bigint, nombreproducto character varying, nombrecliente character varying, fecharecep character varying, orderstatus bigint, fechacontrolit character varying, fechasubecontrolit character varying, diferenciasubeit character varying, indicadorcontrolit bigint, estadoit bigint, fechacotiza character varying, diferenciacotiza character varying, indicadorcotiza bigint, estadocotiza bigint, fechaautoriza character varying, desviacion bigint, tienedesviacion bigint, procesadodespachado character varying, debaja bigint, colorestadodesarme character varying)
    LANGUAGE plpgsql
    AS $$
declare

         sp_fechacontrolit 			timestamp;  -- suma 200 horas desde autorizacion         
         sp_fechasubecontrolit 		timestamp;
         sp_diferenciasubeit		varchar;
         sp_indicadorcontrolit 		bigint;		-- 1: verde, 2: rojo
         sp_estadoit				bigint;
        
         sp_fechacotiza 			timestamp;
         sp_diferenciacotiza		varchar;
         sp_indicadorcotiza 		bigint;		-- 1: verde, 2: rojo
         sp_estadocotiza			bigint;
                 
         sp_fechaautoriza 			timestamp;
         
         desviacion 				bigint;
        
		 sp_tienedesviacion			bigint;
         
	   	 rec1  						record;
	   	 rec_lcc      				record;
	   	
	     sp_kpicoti              	integer;
		 sp_terminocot				varchar;	   
	     sp_estadocoti				integer;
	     sp_estado_coti				integer;
	     sp_diascoti             	integer;
	     sp_fecha_ter_coti			timestamp;	  
	     sp_fecha_real_ter_coti		timestamp;
	     sp_demora_coti				integer;
	   
	     intervaloit				varchar;
	     sp_horas					bigint;

		-- Nuevo estado para desarme
		sp_inicio					timestamp;
		sp_termino					timestamp;
		sp_colorestado				varchar;

        fechadesde					varchar;
		fechahasta					varchar;

begin
	
	if ( annos != -1 ) then
			-- Aca para un rango de fecha solamente

			fechadesde	:= annos||'-01-01';
			fechahasta	:= annos||'-12-31';

				FOR rec1 IN (   
			
				     select *
					     from (
							select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc, a.idordentrabajo asc) AS item,
							       a.idordentrabajo ,
							       a.idproducto ,
							       cast(e.sigla ||' '||d.nombremodelo||' '||f.nombreparam as varchar) as equipo,
							       g.nombrecliente ,
							       g.nombrecorto ,
							       to_date(to_char(a.fechacreacion,'yyyy-mm-dd'), 'yyyy-mm-dd')::timestamp as fechacreacion ,
							       a.idestadoorden ,
							       a.checklistvalido ,
							       to_date(to_char(a.fechachecklistvalido,'yyyy-mm-dd'), 'yyyy-mm-dd')::timestamp as fechachecklistvalido ,
							       a.subedesarme ,
							       to_date(to_char(a.fechasubedesarme,'yyyy-mm-dd'), 'yyyy-mm-dd')::timestamp as fechasubedesarme ,
							       a.fechafaceclte ,
							       case
								       when a.debaja != 1 then
								            'EN PROCESO'
								       else
								            'EN PROCESO DE BAJA'
								   end as debaja,
								   a.idestadoorden,
								   a.debaja as iddebaja
							  from mct_ordentrabajo a
							  left join mct_producto c     on a.idproducto = c.idproducto
							  left join mct_modelo d       on c.idmodelo = d.idmodelo
							  left join mct_subfamilia e   on d.idsubfamilia = e.idsubfamilia
							  left join mct_etapaparam f   on c.idetapaparam = f.idetapaparam 
							  left join mct_cliente g      on a.idcliente = g.idcliente 
							 where a.idordentrabajo  >= 30000--in (select idordentrabajo from mct_progavisos mp where idordentrabajo >= 30000 and idsla = 8 and estado = 0)
							   and a.idestadoorden < 9 -- esto se elimina hoy 20/05/2022 dado que cuando se suba el informe final recien se eliminan de esta consulta
							   and a.idtipoorden = 1
							   and a.debaja != 1
							   and a.idfamilia in (8)
                               and a.idordentrabajo not in (
									34096,
									34097,
									34098,
									34099,
									34102,
									34103,
                                    34181
									)
	                           and (a.fechacreacion >= '2023-01-01' or idordentrabajo in (30968))
					    ) tabla
			 	    order by tabla.fechafaceclte asc, tabla.idordentrabajo asc						
					)
	     		loop 
		     	   
		     		--sp_fechasubecontrolit := '';
		     	    sp_estadoit			:= 0;
		     	    select date(fecha_real_termino)::timestamp ,
		     	           estado 
		     	      into sp_fechasubecontrolit,
		     	           sp_estadoit
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 3;

		     	    sp_indicadorcontrolit	:= 1;  
		     	    sp_diferenciasubeit		:= null;
		     	   	       
                     select a.fecha_termino ,
                            a.estado,
	                        date(a.fecha_real_termino)::timestamp ,
	                        coalesce (date_part('day',a.fecha_real_termino - a.fecha_termino), 0) as demora
	                   into sp_fecha_ter_coti,
	                        sp_estado_coti,
	                        sp_fecha_real_ter_coti,
	                        sp_demora_coti
	                   from mct_progavisos a
	                   left join mct_usuario b on a.idusuarioinfrec = b.idusuario 
	                  where a.idordentrabajo = rec1.idordentrabajo
	                    and a.idsla = 4;
	                  
	                  		
			      	 sp_terminocot := to_char(sp_fecha_ter_coti,'yyyy-mm-dd hh24:mi:ss');
			         if sp_estado_coti != 0 then 		
			            sp_estadocoti := sp_estado_coti;
			            if sp_fecha_real_ter_coti is null then		            
			               --sp_diascoti  := date_part('day', now() - sp_fecharecepcion);
			               sp_kpicoti	:= date_part('day', now() - sp_fecharecepcion);
			            else
			               sp_kpicoti   := sp_demora_coti;
			            end if;		       
			         end if;	
			        
			        
		     		--sp_fechacotiza := '';
		     	    select date(fecha_real_termino)::timestamp ,
		     	           estado
		     	      into sp_fechacotiza ,
		     	           sp_estadocotiza
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 4;
		     	      	      
		     		--sp_fechaautoriza := '';
		     	    select date(fecha_real_termino)::timestamp 
		     	      into sp_fechaautoriza
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 5;
		     	     	     	      
			         sp_tienedesviacion	:= 0;
			         
			         select idtienedesviacion
			           into sp_tienedesviacion
			           from mct_controlequipoedesviacionpdf
			          where idordentrabajo = rec1.idordentrabajo;
			        
			         item 						:= rec1.item;
			         idworkorder 				:= rec1.idordentrabajo; 
			         nombreproducto 			:= rec1.equipo;
			         nombrecliente 				:= rec1.nombrecorto;
			         fecharecep 				:= to_char(rec1.fechacreacion, 'dd-mm-yyyy');
			         orderstatus  				:= rec1.idestadoorden;         
	     		
			         raise notice '%', 'sp_diferenciasubeit'||sp_diferenciasubeit;
			         fechacontrolit				:= to_char(rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 200 horas desde creada la ot
			         fechasubecontrolit			:= to_char(sp_fechasubecontrolit, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubeit			:= coalesce(replace(sp_diferenciasubeit,'',''), '00 hrs:00 min');
			         indicadorcontrolit			:= sp_indicadorcontrolit;  -- 1: ok, 2: nok
			         estadoit					:= sp_estadoit;	
			        
			         if (fechasubecontrolit is null) then
			        			               
			         	if (date_part('day',date(now())::timestamp - (rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL)) <= 0) then
			            	diferenciasubeit		:= date_part('day',(rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL) - date(now())::timestamp );
			                indicadorcontrolit	    := 1;
			            else
				            diferenciasubeit		:= date_part('day',date(now())::timestamp - (rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL));
				         	indicadorcontrolit		:= 2;
			            end if;
			         
			         elsif (date_part('day',sp_fechasubecontrolit - (rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL)) <= 0) then
			         	diferenciasubeit		:= to_char(sp_fechasubecontrolit, 'dd-mm-yyyy');
			         	indicadorcontrolit		:= 1;  

			         end if;
			   			       
			         			  
			         indicadorcotiza			:= 1;
			         estadocotiza				:= sp_estadocotiza;
			         if sp_kpicoti <= 0 then
			            fechacotiza				:= to_char(sp_fechacotiza, 'dd-mm-yyyy');
			         	diferenciacotiza		:= '';			         	
			         else
			         	fechacotiza				:= to_char(sp_fechacotiza, 'dd-mm-yyyy')||'('||sp_kpicoti||')';
			         	diferenciacotiza		:= '';
			         	indicadorcotiza			:= 2;	
			         end if;
			        
			         if (fechacotiza is null) then
			         	 raise notice '%', sp_fechasubecontrolit;
			        	 fechacotiza				:= to_char(sp_fechasubecontrolit, 'dd-mm-yyyy')||'('|| date_part('day',now() - sp_fechasubecontrolit::timestamp) ||')';
			        	 indicadorcotiza			:= 2;
			         end if;

			         
			         fechaautoriza				:= to_char(sp_fechaautoriza, 'dd-mm-yyyy');
			         if (sp_fechaautoriza is null) then
			         	fechaautoriza			:= date_part('day', date(now())::timestamp - sp_fechacotiza::TIMESTAMP);
			            sp_tienedesviacion		:= 99;
			         end if;
			          
			         desviacion					:= 0;
			         tienedesviacion			:= coalesce(sp_tienedesviacion, 0);
			         procesadodespachado		:= rec1.debaja;
			        	    
					 -- Estado desarme
					select min(a.fechainicio),
					       max(a.fechatermino)
	                  into sp_inicio,
	                       sp_termino
					  from mct_movimientoordentrabajo a
					  left join mct_operador b on a.idoperador = b.idoperador
					 where a.idordentrabajo = rec1.idordentrabajo
					   and a.idaccion in (173)
                       and a.iniciaarmadodesarme is true;

					 sp_colorestado = 'btn-danger';
					 if (sp_inicio is not null and sp_termino is not null) then
					 	 sp_colorestado	:= 'btn-success';
					 elsif (sp_inicio is not null and sp_termino is null) then
						 sp_colorestado	:= 'btn-warning';
					 end if;

					 colorestadodesarme	:= sp_colorestado;

			        return next;
	     		
	     		end loop;
	     	
	end if;

   
   END;
$$;


ALTER FUNCTION traking.evtlistcalculoequipocirculante(idevaluators bigint, ots bigint, sdate character varying, edate character varying, annos bigint) OWNER TO postgres;

--
-- TOC entry 2375 (class 1255 OID 16887)
-- Name: evtlistcalendario_consolidadosumaanterior(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcalendario_consolidadosumaanterior(periodo character varying, agno bigint) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying, piezas character varying, estaenproceso bigint, montototalot bigint, montototaldesp bigint, montoarrastre bigint, montodespachadosanteriores bigint, montodespachadoporguia bigint, ordencompra character varying, guiasdespacho character varying)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_funcav			   numeric;
    sp_canthr              integer;
    sp_liberadascc         integer;
   
    rec_ord          	   record;
   
   	sp_fechamaxlcc         timestamp;
	sp_dias_lcc            integer;

    -- nepcast
    sp_cantidad            integer;
    sp_subproducto         varchar;
    -- Variable para fundicion
    sp_cantidad_fu         integer; 
	sp_codigoqr_fu         varchar;  
	sp_fecharequerida_fu   timestamp;

    -- Variable para pañol
    sp_cantidad_pa         integer; 
	sp_codigoqr_pa         varchar;  
	sp_fecharequerida_pa   timestamp;
 
    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    -- Variable para stock cc
    sp_cantidad_cc         integer; 
	sp_codigoqr_cc         varchar;  
	sp_fecharequerida_cc   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
    sp_avance_cc           numeric;
    sp_atraso_cc           integer;  
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
    sp_recept_cc           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
    sp_color_cc            integer;   
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
    sp_dias_cc             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
    sp_dias_atraso_cc      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
    sp_maxfecha_cc         timestamp;
   
    sp_muestraorden		   integer;
    sp_countcheck		   integer;
    
    sp_indice              integer;
   
    sp_sumatotallcc        integer;
   
    rec_lcc      			RECORD;
    rec_email      			RECORD;
   
    sp_restanc			   integer;
    sp_textoout            varchar;
   
    sp_estaenproceso       bigint;
   
    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;   
    
    sp_montoadicional		bigint;

    sp_lista				varchar;
    
begin
	 
	sp_estaenproceso	:= 0;

	select to_char(now(),'yyyy')
	  into ano;
	 
	select lpad(periodo, 2,'0')
	  into mes;
	 
	fechadesde	:= agno||'-'||mes||'-01';

    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'dd'),
           to_date(fechadesde,'yyyy-mm-dd') + interval '1 month',
           to_char( to_date(fechadesde,'yyyy-mm-dd') + interval '1 month', 'yyyy-mm')||'-'||to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'dd')
	  into ultimodia,
	       fechadesde,
	       fechahasta;
	 
	select to_char(now(),'yyyy')
	  into anofin;
	 
	--fechahasta	:= agno||'-'||mes||'-'||ultimodia;
	

		FOR rec_ord IN (   
				select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc) AS item,
				       a.idordentrabajo ,
				       a.idestadoorden ,
				       case 
				          when a.ordencompra > 0 then 'OC'
				          when a.ordencompra = 0 then 'OI'
				          else 'OI'
				       end as tipoautoriza,   
				       d.nombretipoorden ,
				       e.nombrefamilia||'_'||a.idestadoorden ,
					   --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
					   case 
						  when a.idfamilia = 11 then c.nombreproducto
						  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
					   end as producto,
				       b.nombrecorto ,
				       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
				       fechafacetm,
				       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
				       --date_part('day', a.fechafaceclte - now()) as dias,
				       date_part('day', a.fechafacetm - current_date) as dias,
				       date_part('day', a.fechafaceclte - current_date) as diascliente,	
				       a.idmodalidadcreacion ,
				       j.nombre ,
				       a.flagfacturacion ,
				       d.sigla as siglatipo,
				       e.sigla||'_'||a.idestadoorden as siglafam,
				       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion,
				       coalesce (to_char(a.fechafundicion2, 'dd-mm-yyyy'), to_char(a.fechafacetm - interval '21 days','dd-mm-yyyy')) as fechafundicion,
		               a.checklistvalido ,
		               a.idfamilia ,
                       a.ordencompra
				  from mct_ordentrabajo a,
				       mct_cliente b,
				       mct_producto c,
				       mct_tipoorden d,
				       mct_familia e,
				       mct_estadoorden f,
				       mct_modelo g,
				       mct_subfamilia h,
				       mct_etapaparam i,
				       mct_usuario j
				 where a.idcliente = b.idcliente 
				   and a.idproducto = c.idproducto 
				   and a.idtipoorden = d.idtipoorden 
				   and a.idfamilia = e.idfamilia
				   and a.idestadoorden = f.idestadoorden 
				   and c.idmodelo = g.idmodelo 
				   and g.idsubfamilia = h.idsubfamilia 
				   and c.idetapaparam = i.idetapaparam 
				   and a.idordentrabajo >= 30000
				   and a.idusuario = j.idusuario 
				   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
				   and a.idfamilia in (8,10,15)
				   --and a.flagfacturacion is true
				   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				   and a.debaja < 1
				   order by a.fechafaceclte asc
				   
					)
		loop 	
		
		       -- colores seran
		       -- 1 : verde
		       -- 2 : amarillo
		       -- 3 : rojo
		       
		       -- sacamos el rango de fechas para el color de entrega
   
               select min(fecha_inicio), 
                      max(fecha_termino),
                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
                      date_part('day', max(fecha_termino) - now() ) ,
                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
                 into sp_fecha_auto,
                      sp_fecha_entdes,
                      dias_entrega,
                      dias_resto,
                      dias_calculo
                 from mct_progavisos 
                where idordentrabajo = rec_ord.idordentrabajo
                  and idsla in (5,8,9);
                 
               if (dias_resto = 0 ) then
                   dias_resto := 1;
               end if;

              
   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
   			   
   			   if now() > sp_fecha_entdes then 
   			      sp_color_item    := 3;
   			      sp_color_entrega := 3;
   			   elsif sp_calculo_itement < 80 then
	   			      sp_color_item    := 1;
	   			      sp_color_entrega := 1;   			   
   			   elsif sp_calculo_itement >= 80 then
 	   			      sp_color_item    := 2;
	   			      sp_color_entrega := 2;     			   
   			   end if; 
                  

   			   -- desde aca el nuevo calculo
	   		   sp_sumatotallcc  := 0;
	   			   
	   		   FOR rec_lcc IN (   
							select distinct b.idhojarutatemp
							  from mct_movimientoordentrabajo a,
							       mct_hojaruta b,
							       mct_hojarutatemp c
							 where a.codigoaccion = 'L_CC'
						       and a.idordentrabajo = rec_ord.idordentrabajo 
						       and a.idhojaruta = b.idhojaruta 
						       and b.idhojarutatemp = c.idhojarutatemp 
						       and c.idboleano = 1
			                   and c.idareaclasificacion in (0,1,2,3,4,5)
							)
		     		loop 	

		     			   sp_liberadascc	:= 0;
						     
		     			   select case
			     			         when idimprimehojas = 1 then
			     			              coalesce (count(*),0)
			     			         when idimprimehojas = 2 then
			     			              coalesce (sum(cantidad),0)     
			     			         else
			     			              0
			     			      end
						     into sp_liberadascc
						     from mct_hojarutatemp
						    where idhojarutatemp = rec_lcc.idhojarutatemp
						      and idboleano = 1
			                  and idareaclasificacion in (0,1,2,3,4,5)
			                 group by idimprimehojas;
				     
			                if ( select distinct 1
				                  from mct_movimientoordentrabajo a,
				                       mct_hojaruta b
				                 where b.idhojarutatemp = rec_lcc.idhojarutatemp
				                   and a.idhojaruta = b.idhojaruta 
				                   and (a.codigoaccion = 'NC_MEC' or a.codigoaccion = 'NC_FU') ) then
			                   
				                if ( select distinct 1
				                  from mct_movimientoordentrabajo a,
				                       mct_hojaruta b
				                 where b.idhojarutatemp = rec_lcc.idhojarutatemp
				                   and a.idhojaruta = b.idhojaruta 
				                   and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
				                                                       from mct_movimientoordentrabajo b
				                                                      where a.idhojaruta = b.idhojaruta 
				                                                        and ( a.codigoaccion = 'L_CC' or
				                                                              a.codigoaccion = 'R_TM' ) ) ) then

					                sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
				                  
				                    sp_textoout := rec_ord.idordentrabajo||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
				                    raise notice '%', sp_textoout;
				                   
				                else
				                
				                
					                sp_sumatotallcc := sp_sumatotallcc + 0;
				                  
				                    sp_textoout := rec_ord.idordentrabajo||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
				                    raise notice '%', sp_textoout;
			                  
				                end if;
				                   
			                   
			               
			                else
			                   sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
			                  
			                   sp_textoout := rec_ord.idordentrabajo||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
			                   raise notice '%', sp_textoout;
			                  
			                end if;
				           
		  			END LOOP;
		  		
		  	   sp_sumatotallcc := sp_sumatotallcc * 100;
		  	   -- hasta aca el nuevo calculo
		  		

			   if (rec_ord.idordentrabajo = 31912) then
			   
				    select count(distinct a.idhojarutatemp)
				      into sp_canthr
					  from mct_hojarutatemp a,
					       mct_hojaruta b
					 where a.idordentrabajo = rec_ord.idordentrabajo
					   and b.idhojarutatemp = b.idhojarutatemp
					   and a.idboleano = 1   
					   and a.idareaclasificacion in (0,1,2,3,4,5);
			   else
			   
				   select sum(total)
				     from (
						   select case 
							        when idimprimehojas = 1 then
						     			 coalesce (count(*),0)
						     	    when idimprimehojas = 2 then
						     			 coalesce (sum(cantidad),0)     
						     		else
						     			 0	
						          end as total
						     from mct_hojarutatemp mh
						    where idordentrabajo = rec_ord.idordentrabajo
						      and idboleano = 1
						      and idareaclasificacion in (0,1,2,3,4,5)
						     group by idimprimehojas
					    ) as tabla
				   into sp_canthr;
			  
			   end if;	
			     
			   -- aca sacamos la cantidad de piezas liberadas de control de calidad
			   select count(*) , 
                      max(fechatermino)
			     into sp_liberadascc,
			          sp_fechamaxlcc
			     from mct_movimientoordentrabajo
			    where codigoaccion = 'L_CC'
			      and idordentrabajo = rec_ord.idordentrabajo; 
			     
			   sp_dias_lcc := 0;
			   sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
			      
			   if ( sp_canthr = 0) then
			       sp_avance := 0;
			   else
			       --sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
				   sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			       if (sp_avance >= 100 ) then
			           sp_color_status  := 1;
			       end if;
               end if;

               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
                 			     
               if sp_dias_atraso_status < 0 then 
                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
               end if;
              
   			   --if now() > sp_fecha_entdes then 
   			   --   sp_color_status  := 3;
   			   --elsif sp_calculo_itement < 80 then
   			   --   sp_color_status  := 1;  
   			   --else
   			   --   sp_color_status  := 1;  
   			   --end if;

              
		
			   -- Fundicion
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          --codigoqr, 
				          max(fecharequerida)
				     into sp_cantidad_fu,
				    --      sp_codigoqr_fu,
				          sp_fecharequerida_fu
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd in ('FAB_FU','FAB_FUPL')
				      and idordentrabajo = rec_ord.idordentrabajo;
				      --group by fecharequerida;
				     
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_fu,
				          sp_maxfecha_fu
				     from mct_checklistinftecrecept
				    where codigoqr = rec_ord.idordentrabajo||'FAB_FU' or 
				          codigoqr = rec_ord.idordentrabajo||'FAB_FUPL'; 				     

				   if (sp_cantidad_fu = 0 ) then
	                   sp_cantidad_fu := 1;
	               end if;
	              
				   sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
				   sp_atraso_fu := 0;
				  
				   sp_color_fu  := 0;
				   if ( sp_avance_fu >= 100) then
				       sp_color_fu   := 1;
				   end if;
				  
				   if ( sp_cantidad_fu = 0 ) then
				       sp_avance_fu = 999;
				   end if;
				 
			  
			  
			   -- Pañol
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_pa,
				          sp_codigoqr_pa,
				          sp_fecharequerida_pa				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'FAB_PA'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_pa,
				          sp_maxfecha_pa		   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_pa;

			       if (sp_cantidad_pa = 0 ) then
                       sp_cantidad_pa := 1;
                   end if;
              
				   sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    
			       sp_atraso_pa := 0;

				   sp_color_pa  := 0;			      
			       if ( sp_avance_pa >= 100) then
				       sp_color_pa   := 1;
				   end if;
				  
				   --if ( sp_maxfecha_pa > sp_fecharequerida_pa ) then
				   --    sp_atraso_pa  := date_part('day', sp_maxfecha_pa -  sp_fecharequerida_pa );
				   --    sp_color_pa   := 3;
				   --else
				   --    sp_color_pa   := 1;			   
				   --end if;				 
			  
			   -- Caldereria
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_ca,
				          sp_codigoqr_ca,
				          sp_fecharequerida_ca				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'FAB_CA'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_ca,
				          sp_maxfecha_ca	   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_ca; 

			       if (sp_cantidad_ca = 0 ) then
                      sp_cantidad_ca := 1;
                   end if;
              
				   sp_avance_ca := round((sp_recept_ca * 100.00 ) / sp_cantidad_ca , 2);

				   sp_color_ca  := 0;					  
			       if ( sp_avance_ca >= 100) then
				       sp_color_ca   := 1;
				   end if;				  
				  
				   --if ( sp_maxfecha_ca > sp_fecharequerida_ca ) then
				   --    sp_atraso_ca  := date_part('day', sp_maxfecha_ca -  sp_fecharequerida_ca );
				   --    sp_color_ca   := 3;
				   --else
				   --    sp_color_ca   := 1;			   
				   --end if;					 
				 
			   -- Compras
				   -- aca sacamos las piezas totales solicitadas a compras  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_co,
				          sp_codigoqr_co,
				          sp_fecharequerida_co				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'RPO'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_co,
				          sp_maxfecha_co	 			   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_co;			    

			       sp_atraso_co := 0;
			       if (sp_cantidad_co = 0 ) then
                       sp_cantidad_co := 1;
                   end if;				   
				   
				   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			

				   sp_color_co  := 0;				  
			       if ( sp_avance_co >= 100) then
				       sp_color_co   := 1;
				   end if;	
				  
				   --if ( sp_maxfecha_co > sp_fecharequerida_co ) then
				   --    sp_atraso_co  := date_part('day', sp_maxfecha_co -  sp_fecharequerida_co );
				   --    sp_color_co   := 3;
				   --else
				   --    sp_color_co   := 1;			   
				   --end if;					 
				 
			   -- Taller Mecanico
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_ot,
				          sp_codigoqr_ot,
				          sp_fecharequerida_ot				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'OTROS'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_ot,
				          sp_maxfecha_ot				   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_ot;					    

			       if (sp_cantidad_ot = 0 ) then
                       sp_cantidad_ot := 1;
                   end if;					   
				   
				   sp_avance_ot := round((sp_recept_ot * 100.00 ) / sp_cantidad_ot , 2);						    
			       sp_atraso_ot := 0;

				   sp_color_ot  := 0;				      
			       if ( sp_avance_ot >= 100) then
				       sp_color_ot   := 1;
				   end if;	
				  
				   --if ( sp_maxfecha_ot > sp_fecharequerida_ot ) then
				   --    sp_atraso_ot  := date_part('day', sp_maxfecha_ot - sp_fecharequerida_ot );
				   --    sp_color_ot   := 3;
				   --else
				   --    sp_color_ot   := 1;			   
				   --end if;					 

			   -- Stock Cc
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_cc,
				          sp_codigoqr_cc,
				          sp_fecharequerida_cc				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'STOCK_CC'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_cc,
				          sp_maxfecha_cc				   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_ot;					    

			       if (sp_cantidad_cc = 0 ) then
                       sp_cantidad_cc := 1;
                   end if;					   
				   
				   sp_avance_cc := round((sp_recept_cc * 100.00 ) / sp_cantidad_cc , 2);						    
			       sp_atraso_cc := 0;

				   sp_color_cc  := 0;			      
			       if ( sp_avance_cc >= 100) then
				       sp_color_cc   := 1;
				   end if;	
				  					  
				  
				   --if ( sp_maxfecha_cc > sp_fecharequerida_cc ) then
				   --    sp_atraso_cc  := date_part('day', sp_maxfecha_cc - sp_fecharequerida_cc );
				   --    sp_color_cc   := 3;
				   --else
				   --    sp_color_cc   := 1;			   
				   --end if;
				  
	      --  sp_dias_av := date_part('day' , rec_ord.fechaentrega - now() )
	      
	      --  Para elementos de desgaste
	        sp_subproducto := '';
	        sp_cantidad := 0;
	      
		    if rec_ord.idfamilia = 11 then
		   
		        select count(distinct b.nombreproductonepcast)
		          into sp_cantidad
				  from mct_ordentrabajorepuesto a,
					   mct_productonepcast b
				 where a.idordentrabajo = rec_ord.idordentrabajo
				   and a.idproductonepcast  = b.idproductonepcast ;


				if sp_cantidad > 1 then
				
					sp_subproducto := 'Varios';
				else
				
					select distinct b.nombreproductonepcast
			          into sp_subproducto
					  from mct_ordentrabajorepuesto a,
						   mct_productonepcast b
					 where a.idordentrabajo = rec_ord.idordentrabajo
					   and a.idproductonepcast  = b.idproductonepcast ;
				  
				end if;
		   
	       
	        end if;
	       
		    itemot         := rec_ord.item;
		    idworkorder    := rec_ord.idordentrabajo;
			auttype        := rec_ord.tipoautoriza;	    
			--ordertypename  := rec_ord.nombretipoorden;
			ordertypename  := rec_ord.siglatipo;		
			username       := rec_ord.nombre;
		    --familyname     := rec_ord.nombrefamilia;
		    familyname     := rec_ord.siglafam;	
			productname    := rec_ord.producto;
			subproductname := sp_subproducto;
		    customername   := rec_ord.nombrecorto;
	        --deliverydatetm     := to_char(sp_fecha_entdes - interval '7 days','dd-mm-yyyy');
			--deliverydateclte   := to_char(sp_fecha_entdes,'dd-mm-yyyy');
			
		    deliverydatetm := rec_ord.fechaentregatm;
		    deliverydateclte := coalesce(rec_ord.fechaentregaclte,'S/F');
		   
		    --statusdispatch := sp_dias_atraso_status;
			  
			    if (rec_ord.idordentrabajo in (30322,30374) ) then
			       sp_avance   := 100;
			       sp_color_status := 1;
			    else
			       sp_color_status := 0;		    
			    end if;
			   
			    if (sp_avance >= 100) then
			        statusdispatch  := sp_dias_lcc;
			    else
			    	statusdispatch  := rec_ord.dias;
			    end if;
			   
			   	if ( sp_cantidad_fu is null) then
			        sp_avance_fu := 999;
			    end if;
			    if ( sp_cantidad_pa is null) then
			        sp_avance_pa := 999;
			    end if;
			   	if ( sp_cantidad_ca is null) then
			        sp_avance_ca := 999;
			    end if;
			    if ( sp_cantidad_co is null) then
			        sp_avance_co := 999;
			    end if;
			   	if ( sp_cantidad_ot is null) then
			        sp_avance_ot := 999;
			    end if;
			   	if ( sp_cantidad_cc is null) then
			        sp_avance_cc := 999;
			    end if;
			   
	
			    if (rec_ord.checklistvalido = false) then
			        sp_avance_fu := 888;
			        sp_avance_pa := 888;
			        sp_avance_ca := 888;
			        sp_avance_co := 888;
			        sp_avance_ot := 888;
			        sp_avance_cc := 888;				    
			    end if;
			    statuscliente  := rec_ord.diascliente;	
			   
			    select coalesce (salav)
                  into sp_funcav 
                  from traking.calcularavancemecanizado(rec_ord.idordentrabajo);
 
				advance        := sp_funcav;
			    --advance        := sp_avance;
			
		    advancefu      := coalesce(sp_avance_fu,0);
			advancepa      := coalesce(sp_avance_pa,0);
			advanceca      := coalesce(sp_avance_ca,0);
			advanceco      := coalesce(sp_avance_co,0);
			advanceot      := coalesce(sp_avance_ot,0);
			advancecc      := coalesce(sp_avance_cc,0);		
			itemcolor      := coalesce(sp_color_item,0);
   			statuscolor    := coalesce(sp_color_status,0);   		
			fucolor        := sp_color_fu;
			pacolor        := sp_color_pa;
			cacolor        := sp_color_ca;		
			cocolor        := sp_color_co;
			otcolor        := sp_color_ot;	
			cccolor        := sp_color_cc;			
			delayfu        := coalesce(sp_atraso_fu,0); 
			delaypa        := coalesce(sp_atraso_pa,0); 
			delayca        := coalesce(sp_atraso_ca,0); 
			delayco        := coalesce(sp_atraso_co,0); 
			delayot        := coalesce(sp_atraso_ot,0); 
			delaycc        := coalesce(sp_atraso_cc,0); 		
		    flagfact       := rec_ord.flagfacturacion;
		    fundiciondate  := rec_ord.fechafundicion;
		   
		    select count(*)
		      into sp_estaenproceso
		      from traking.mct_movimientoordentrabajo a
		     where a.idordentrabajo = rec_ord.idordentrabajo
		       and a.estadoactividad = 1;
		      
		    estaenproceso  := sp_estaenproceso;
		   
		    piezas		   := cast('' as varchar);
			
		    montototaldesp	:= 0;
		    montoarrastre	:= 0;
		   
	         if (rec_ord.idfamilia = 8) then
	         
	         	select coalesce(sum(montorepfab),0)
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	    --montoarrastre	:= montototalot - montototaldesp;
	         	    montoarrastre	:= montototalot;
	         	
	         	else
	         	
	         		montoarrastre	:= montototalot - montototaldesp;
	         	
	         	end if;	         	
	         
	         elsif (rec_ord.idfamilia = 11) then
	         
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into montototalot
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select sum(b.qdespacho * c.costo ) 
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
	         	
		        select sum(b.qdespacho * c.costo ) 
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		        montoarrastre	:= montototalot - montoarrastre;
		         	    	  
	         elsif (rec_ord.idfamilia = 10 or rec_ord.idfamilia = 15) then
	
	           	select coalesce(sum(montorepfab),0) 
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into sp_montoadicional
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	montototalot	:= montototalot + sp_montoadicional;
	         
	            select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		         	  
		        select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	    	
		        montoarrastre	:= montototalot - montoarrastre;

	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	end if;	    
	         
	         else
	         
	         	montototalot	:= 0;
	         
	         end if;
	        
	        --montoarrastre	:= 0;
	        
	        montodespachadosanteriores	:= 0;
	        montodespachadoporguia		:= 0;

			sp_lista := '';
						   
			FOR rec_email IN (   
						select guiasaliente 
					      from traking.mct_despachopartecabecera
					     where idordentrabajo = rec_ord.idordentrabajo 
				 	)
			    loop 	
							
					sp_lista := rec_email.guiasaliente||'-'||sp_lista;
							           
		    end loop;

			ordencompra		:= rec_ord.ordencompra;
			if (length(sp_lista) = 0) then
				guiasdespacho	:= '0';
			else
				guiasdespacho	:= cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
			end if;

				        
	        if (montototalot > montoarrastre) then
	        
	        	return next;
	       
	        end if;

		END LOOP;	    
	   
END;
$$;


ALTER FUNCTION traking.evtlistcalendario_consolidadosumaanterior(periodo character varying, agno bigint) OWNER TO postgres;

--
-- TOC entry 2285 (class 1255 OID 16889)
-- Name: evtlistcalendarioacciones(bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcalendarioacciones(idusersc bigint, iduserjv bigint, periodos character varying, desde character varying, hasta character varying) RETURNS TABLE(iddefectocausaaccion bigint, iddefectocausa bigint, descripcion character varying, nombrerespaldo character varying, fechaejecucion character varying, jsonresponsable character varying, estado bigint, statusname character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying, codhojaruta character varying, idcomponente bigint, idresponsablefundicion bigint, iddefectofundicion bigint, correlativo bigint, idordentrabajo bigint, pendientecarga boolean, atrasocarga boolean, jsontipodefecto character varying, descripciongeneraldefecto character varying, nombrecomponente character varying, planocomponente character varying, equipo character varying, planogeneral character varying, nombrematerial character varying, fechacreacioninf character varying)
    LANGUAGE plpgsql
    AS $$
declare

	rec_trab       		RECORD;
	sp_totalrespaldos	bigint;
	sp_totalcargas		bigint;
    sp_pendientecarga	boolean;
   
    ultimodia			varchar;
    ano				    varchar;
    anofin              varchar;
   
    fechadesde		    varchar;
    fechahasta          varchar;
    mes					varchar;   
   
	sp_atrasocarga		bigint;   

    --sp_idcomponente		bigint;
    sp_nombrecomponente	varchar;
    sp_planocomponente	varchar;
    sp_equipo			varchar;
    sp_planogeneral		varchar;
    sp_nombrematerial	varchar;
    sp_fechacreacion	varchar;

BEGIN

		   
	
	if (periodos != '-1') then

		select to_char(now() - interval '2 year','yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		select to_char(now() + interval '2 year','yyyy')
		  into anofin;
		 
		fechahasta	:= anofin||'-'||mes||'-'||ultimodia;
	
	    FOR rec_trab IN (  

		        SELECT a.iddefectocausaaccion , 
		        	   a.iddefectocausa ,              
		               a.descripcion , 
		               c.nombrerespaldo , 
		               cast(to_char(a.fechaejecucion, 'yyyy-mm-dd') as varchar)  as fechaejecucion,
		               a.jsonresponsable  ,
		               a.estado,
		               b.nombreestado,
		               a.fechacreacion,
		               a.usuariocreacion,
		               a.fechamodificacion,
		               a.usuariomodificacion,
		               e.codhojaruta ,
		               e.idcomponente ,
		               f.idresponsablefundicion ,
		               e.iddefectofundicion ,
		               e.correlativo ,
		               e.idordentrabajo ,
		               e.jsontipodefecto ,
		               e.descripciongeneraldefecto 
		        FROM traking.mct_defectocausaaccion a
		        left join traking.mct_estado                b on a.estado = b.idestado
		        left join traking.mct_defectocausaaccionpdf c on c.iddefectocausaaccion = a.iddefectocausaaccion 
                left join traking.mct_defectocausa          d on d.iddefectocausa = a.iddefectocausa
                left join traking.mct_defectofundicion      e on e.iddefectofundicion = d.iddefectofundicion  
                     join traking.mct_componente            f on e.idcomponente = f.idcomponente 
               where a.fechaejecucion >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaejecucion <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')
				 and f.idresponsablefundicion in (idusersc, iduserjv)
		        order by 5 asc	    
	    			   
	    	)
	    	loop
	   
		         iddefectocausaaccion	:= rec_trab.iddefectocausaaccion;
		         iddefectocausa			:= rec_trab.iddefectocausa;
		         descripcion			:= rec_trab.descripcion;
		         nombrerespaldo			:= rec_trab.nombrerespaldo;
		         fechaejecucion			:= rec_trab.fechaejecucion;
		         jsonresponsable		:= rec_trab.jsonresponsable;
		         estado					:= rec_trab.estado;
		         statusname				:= rec_trab.nombreestado;
		         fechacreacion			:= rec_trab.fechacreacion;
		         usuariocreacion		:= rec_trab.usuariocreacion;
		         fechamodificacion		:= rec_trab.fechamodificacion;
		         usuariomodificacion	:= rec_trab.usuariomodificacion;
		         codhojaruta			:= rec_trab.codhojaruta;
		         idcomponente 			:= rec_trab.idcomponente;
		         idresponsablefundicion := rec_trab.idresponsablefundicion;
		         iddefectofundicion 	:= rec_trab.iddefectofundicion;
		         correlativo 			:= rec_trab.correlativo;
		         idordentrabajo 		:= rec_trab.idordentrabajo;

				 atrasocarga			:= false;
				        
		         select count(*)
		           into sp_atrasocarga
		           from mct_defectocausa a,
		                mct_defectocausaaccion b,
		                mct_defectocausaaccionpdf c
		          where a.iddefectofundicion = rec_trab.iddefectofundicion
		            and a.iddefectocausa  = b.iddefectocausa 
		            and b.iddefectocausaaccion = c.iddefectocausaaccion 
		            and c.fechamodificacion > b.fechaejecucion ;
		    				        
		         if (sp_atrasocarga > 0) then
		             atrasocarga	:= true;
		         end if;
				        
				 select count(*)
				   into sp_totalrespaldos
				   from mct_defectocausaaccionpdf md
				  where md.iddefectocausaaccion  = rec_trab.iddefectocausaaccion;
				 
				 select count(*)
				   into sp_totalcargas
				   from mct_defectocausaaccionpdf md
				  where md.iddefectocausaaccion  = rec_trab.iddefectocausaaccion
				    and (length(tipo) > 0);
				
		          pendientecarga	:= false;
		          if (sp_totalrespaldos > 0) then		
		              if (sp_totalcargas < sp_totalrespaldos ) then 
		                  pendientecarga	:= true;
		              end if;
		             
		          end if;  
		         
		          jsontipodefecto 			:= rec_trab.jsontipodefecto;
		          descripciongeneraldefecto	:= rec_trab.descripciongeneraldefecto;

				  SELECT i.nombrecomponente ,
					 	 cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
					     cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					     cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
					     j.nombrematerial ,
						 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion
			        into sp_nombrecomponente,
			             sp_planocomponente,
			             sp_equipo,
			             sp_planogeneral,
			             sp_nombrematerial,
			             sp_fechacreacion
		 	 	    FROM traking.mct_defectofundicion a 
			  	    left join  traking.mct_detallehojarutatemp g 	on a.codhojaruta = g.codhojaruta 
				    left join  traking.mct_hojarutatemp h 	 on g.idhojarutatemp = h.idhojarutatemp 
				    left join  traking.mct_componente i 	 on h.idcomponente = i.idcomponente 
				    left join  traking.mct_material j 		 on h.idmaterial = j.idmaterial 
				    left join  traking.mct_ordentrabajo k 	 on h.idordentrabajo = k.idordentrabajo 
				    left join  traking.mct_producto l 		 on k.idproducto = l.idproducto 
				    left join  traking.mct_modelo m 		 on l.idmodelo = m.idmodelo 
				    left join  traking.mct_subfamilia n 	 on m.idsubfamilia = n.idsubfamilia 
				   where a.iddefectofundicion = rec_trab.iddefectofundicion;	
				  
			      nombrecomponente	:= sp_nombrecomponente;
			      planocomponente	:= sp_planocomponente;
			      equipo			:= sp_equipo;
			      planogeneral		:= sp_planogeneral;
			      nombrematerial	:= sp_nombrematerial;
			      fechacreacioninf	:= sp_fechacreacion;
    
		    	  return next;
		     
	    	end loop;
	
	end if;

END;
$$;


ALTER FUNCTION traking.evtlistcalendarioacciones(idusersc bigint, iduserjv bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 2344 (class 1255 OID 16891)
-- Name: evtlistcalendariodesgaste_consolidado(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcalendariodesgaste_consolidado(periodo character varying, agno bigint) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying, piezas character varying, estaenproceso bigint, montototalot bigint, montototaldesp bigint, montoarrastre bigint, montodespachadosanteriores bigint, montodespachadoporguia bigint, ordencompra character varying, guiasdespacho character varying)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_funcav			   numeric;
   
    sp_canthr              integer;
    sp_liberadascc         integer;
   
    rec_ord          	   record;
    rec_email         	   record;
   
    rec_ordcomp            record;
   
    sp_lista			   varchar;
   
   	sp_fechamaxlcc         timestamp;
	sp_dias_lcc            integer;

    -- nepcast
    sp_cantidad            integer;
    sp_subproducto         varchar;
    -- Variable para fundicion
    sp_cantidad_fu         integer; 
	sp_codigoqr_fu         varchar;  
	sp_fecharequerida_fu   timestamp;

    -- Variable para pañol
    sp_cantidad_pa         integer; 
	sp_codigoqr_pa         varchar;  
	sp_fecharequerida_pa   timestamp;

    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    -- Variable para stock cc
    sp_cantidad_cc         integer; 
	sp_codigoqr_cc         varchar;  
	sp_fecharequerida_cc   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
    sp_avance_cc           numeric;
    sp_atraso_cc           integer;  
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
    sp_recept_cc           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
    sp_color_cc            integer;   
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
    sp_dias_cc             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
    sp_dias_atraso_cc      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
    sp_maxfecha_cc         timestamp;
   
    sp_nombreproducto	   varchar;
   
    sp_muestraorden		   integer;
    sp_countcheck		   integer;
    
    sp_indice              integer;
   
    sp_sumatotallcc        integer;
   
    rec_lcc      			RECORD;
   
    sp_fami					integer;
    sp_mec					integer;
   
    sp_estaenproceso        bigint;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar; 
   
    sp_montoadicional		bigint;
   
begin
	 
	sp_estaenproceso	:= 0;

	sp_fami = 11;
	sp_mec = 1;
	

	select to_char(now(),'yyyy')
	  into ano;
	 
	select lpad(periodo, 2,'0')
	  into mes;
	 
	fechadesde	:= agno||'-'||mes||'-01';

    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
	  into ultimodia;
	 
	select to_char(now(),'yyyy')
	  into anofin;
	 
	fechahasta	:= agno||'-'||mes||'-'||ultimodia;


				FOR rec_ord IN (   
				
				        select ROW_NUMBER() OVER (ORDER BY tab.fechaentrega asc) AS item,
				               tab.idproducto,
				               tab.idordentrabajo,
				               tab.idestadoorden,
				               tab.tipoautoriza,
				               tab.nombretipoorden,
				               tab.nombrefamilia,
				               tab.producto,
				               tab.nombrecorto,
				               tab.fechaentrega,
				               tab.fechaentregatm,
				               tab.fechafacetm,
				               tab.fechaentregaclte,
				               tab.dias,
				               tab.diascliente,
				               tab.idmodalidadcreacion,
				               tab.nombre,
				               tab.flagfacturacion,
				               tab.siglatipo,
				               tab.siglafam,
				               tab.fechafundicion,
				               tab.idfamilia,
				               tab.anterior,
							   tab.ordencompra
				          from (
								select a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_CON'||'_'||a.idestadoorden as nombrefamilia,
	                                   c.nombreproductonepcast  as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       a.idusuario||'#'||j.nombre as nombre,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_CON'||'_'||a.idestadoorden
								       end as siglafam,
									   coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy')) as fechafundicion,
									   a.idfamilia,
									   0 as anterior,
                       				   cast(a.ordencompra as varchar) as ordencompra
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_productonepcast c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproductonepcast  
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   --and c.idresponsable = j.idusuario 
								   and a.idusuario = j.idusuario 
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
								   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
								   and a.debaja < 1							

							union 
							-- Despachos diferentes al periodo de entrega al cliente para mecanizado 1
								select distinct a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_CON'||'_'||a.idestadoorden as nombrefamilia,
	                                   c.nombreproductonepcast  as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       a.idusuario||'#'||j.nombre as nombre,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_CON'||'_'||a.idestadoorden
								       end as siglafam,
									   coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy')) as fechafundicion,
									   a.idfamilia,
									   99 as anterior,
                       				   cast(a.ordencompra as varchar) as ordencompra
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_productonepcast c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_usuario j,
								       mct_despachopartecabecera k
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproductonepcast  
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   --and c.idresponsable = j.idusuario 
								   and a.idusuario = j.idusuario
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
								   and (k.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and k.fechaguia  <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
								   and a.idordentrabajo = k.idordentrabajo 
								   and a.debaja < 1	
								   and not exists (
								   
										select 'x'
										  from mct_ordentrabajo aa,
										       mct_cliente b,
										       mct_productonepcast c,
										       mct_tipoorden d,
										       mct_familia e,
										       mct_estadoorden f,
										       mct_usuario j
										 where aa.idcliente = b.idcliente 
										   and aa.idproducto = c.idproductonepcast  
										   and aa.idtipoorden = d.idtipoorden 
										   and aa.idfamilia = e.idfamilia
										   and aa.idestadoorden = f.idestadoorden 
										   and aa.idordentrabajo >= 30000
										   and aa.idordentrabajo not in (30855)
										   and c.idresponsable = j.idusuario 
										   and aa.idestadoorden  >= 6 and a.idestadoorden <= 9
										   and aa.idfamilia = 11
										   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = aa.idordentrabajo and mo.idesmecanizado = 1)
										   and (aa.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and aa.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
										   and a.debaja < 1		
										   and a.idordentrabajo = aa.idordentrabajo
								   
								   )							
							
							
							union
								select a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_SIN'||'_'||a.idestadoorden as nombrefamilia,
	                                   c.nombreproductonepcast  as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       a.idusuario||'#'||j.nombre as nombre,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_SIN'||'_'||a.idestadoorden
								       end as siglafam,
									   to_char(a.fechafundicion ,'dd-mm-yyyy') as fechafundicion,
									   a.idfamilia,
									   0 as anterior,
                       				   cast(a.ordencompra as varchar) as ordencompra
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_productonepcast c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproductonepcast  
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   --and c.idresponsable = j.idusuario 
								   and a.idusuario = j.idusuario
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 2)
								   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
								   and a.debaja < 1	
						     union 
						
							-- Despachos diferentes al periodo de entrega al cliente para mecanizado 1
								select distinct a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_SIN'||'_'||a.idestadoorden as nombrefamilia,
	                                   c.nombreproductonepcast  as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       a.idusuario||'#'||j.nombre as nombre,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_SIN'||'_'||a.idestadoorden
								       end as siglafam,
									   coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy')) as fechafundicion,
									   a.idfamilia,
									   99 as anterior,
                       				   cast(a.ordencompra as varchar) as ordencompra
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_productonepcast c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_usuario j,
								       mct_despachopartecabecera k
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproductonepcast  
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   --and c.idresponsable = j.idusuario 
								   and a.idusuario = j.idusuario
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 2)
								   and (k.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and k.fechaguia  <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
								   and a.idordentrabajo = k.idordentrabajo 
								   and a.debaja < 1	
								   and not exists (
								   
										select 'x'
										  from mct_ordentrabajo aa,
										       mct_cliente b,
										       mct_productonepcast c,
										       mct_tipoorden d,
										       mct_familia e,
										       mct_estadoorden f,
										       mct_usuario j
										 where aa.idcliente = b.idcliente 
										   and aa.idproducto = c.idproductonepcast  
										   and aa.idtipoorden = d.idtipoorden 
										   and aa.idfamilia = e.idfamilia
										   and aa.idestadoorden = f.idestadoorden 
										   and aa.idordentrabajo >= 30000
										   and aa.idordentrabajo not in (30855)
										   --and c.idresponsable = j.idusuario 
								           and a.idusuario = j.idusuario 
										   and aa.idestadoorden  >= 6 and a.idestadoorden <= 9
										   and aa.idfamilia = 11
										   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = aa.idordentrabajo and mo.idesmecanizado = 2)
										   and (aa.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and aa.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
										   and a.debaja < 1		
										   and a.idordentrabajo = aa.idordentrabajo
								   
								   )							
						
							 ) tab
						     order by fechaentrega asc
								   
							)
				loop 	
				
				       -- colores seran
				       -- 1 : verde
				       -- 2 : amarillo
				       -- 3 : rojo
				       
				       -- sacamos el rango de fechas para el color de entrega
		   
		               select min(fecha_inicio), 
		                      max(fecha_termino),
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
		                      date_part('day', max(fecha_termino) - now() ) ,
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
		                 into sp_fecha_auto,
		                      sp_fecha_entdes,
		                      dias_entrega,
		                      dias_resto,
		                      dias_calculo
		                 from mct_progavisos 
		                where idordentrabajo = rec_ord.idordentrabajo
		                  and idsla in (5,8,9);
		                 
		               if (dias_resto = 0 ) then
		                   dias_resto := 1;
		               end if;
		
		              
		   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
		   			   
		   			   if now() > sp_fecha_entdes then 
		   			      sp_color_item    := 3;
		   			      sp_color_entrega := 3;
		   			   elsif sp_calculo_itement < 80 then
			   			      sp_color_item    := 1;
			   			      sp_color_entrega := 1;   			   
		   			   elsif sp_calculo_itement >= 80 then
		 	   			      sp_color_item    := 2;
			   			      sp_color_entrega := 2;     			   
		   			   end if; 
		                  

		   			   -- desde aca el nuevo calculo
			   		   sp_sumatotallcc  := 0;
			   			   
			   		   FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec_ord.idordentrabajo
								       and a.idhojaruta = b.idhojaruta 
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
				     			   select coalesce (sum(cantidad),0)
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5);
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  	   		   			  
				       -- aca sacamos la cantidad de piezas totales
					   select coalesce ( sum(cantidad), 0)
					     into sp_canthr
					     from mct_hojarutatemp mh
					    where idordentrabajo = rec_ord.idordentrabajo
					      and idboleano = 1
					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   -- aca sacamos la cantidad de piezas liberadas de control de calidad
					   select count(*) , 
		                      max(fechatermino)
					     into sp_liberadascc,
					          sp_fechamaxlcc
					     from mct_movimientoordentrabajo
					    where codigoaccion = 'L_CC'
					      and idordentrabajo = rec_ord.idordentrabajo; 
					     
					   sp_dias_lcc := 0;
					   sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
					      
					   if ( sp_canthr = 0) then
					       sp_avance := 0;
					   else
					       --sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
						   sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
					       if (sp_avance >= 100 ) then
					           sp_color_status  := 1;
					       end if;
		               end if;
		
		               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
		                 			     
		               if sp_dias_atraso_status < 0 then 
		                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
		               end if;
		                        
					   -- Fundicion
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_fu,
						          sp_codigoqr_fu,
						          sp_fecharequerida_fu
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_FU'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_fu,
						          sp_maxfecha_fu
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_fu; 
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						   sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_atraso_fu := 0;
						  
						   sp_color_fu  := 0;
						   if ( sp_avance_fu >= 100) then
						       sp_color_fu   := 1;
						   end if;
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;
					  
					   -- Pañol
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_pa,
						          sp_codigoqr_pa,
						          sp_fecharequerida_pa				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_PA'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_pa,
						          sp_maxfecha_pa		   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_pa;
		
					       if (sp_cantidad_pa = 0 ) then
		                       sp_cantidad_pa := 1;
		                   end if;
		              
						   sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    
					       sp_atraso_pa := 0;
		
						   sp_color_pa  := 0;			      
					       if ( sp_avance_pa >= 100) then
						       sp_color_pa   := 1;
						   end if;
						  	 
					   -- Caldereria
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_ca,
						          sp_codigoqr_ca,
						          sp_fecharequerida_ca				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_CA'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_ca,
						          sp_maxfecha_ca	   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ca; 
		
					       if (sp_cantidad_ca = 0 ) then
		                      sp_cantidad_ca := 1;
		                   end if;
		              
						   sp_avance_ca := round((sp_recept_ca * 100.00 ) / sp_cantidad_ca , 2);
		
						   sp_color_ca  := 0;					  
					       if ( sp_avance_ca >= 100) then
						       sp_color_ca   := 1;
						   end if;				  
				 
						 
					   -- Compras
						   -- aca sacamos las piezas totales solicitadas a compras  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_co,
						          sp_codigoqr_co,
						          sp_fecharequerida_co				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'RPO'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_co,
						          sp_maxfecha_co	 			   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_co;			    
		
					       sp_atraso_co := 0;
					       if (sp_cantidad_co = 0 ) then
		                       sp_cantidad_co := 1;
		                   end if;				   
						   
						   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			
		
						   sp_color_co  := 0;				  
					       if ( sp_avance_co >= 100) then
						       sp_color_co   := 1;
						   end if;				 
						 
					   -- Taller Mecanico
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_ot,
						          sp_codigoqr_ot,
						          sp_fecharequerida_ot				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'OTROS'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_ot,
						          sp_maxfecha_ot				   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ot;					    
		
					       if (sp_cantidad_ot = 0 ) then
		                       sp_cantidad_ot := 1;
		                   end if;					   
						   
						   sp_avance_ot := round((sp_recept_ot * 100.00 ) / sp_cantidad_ot , 2);						    
					       sp_atraso_ot := 0;
		
						   sp_color_ot  := 0;				      
					       if ( sp_avance_ot >= 100) then
						       sp_color_ot   := 1;
						   end if;	

					   -- Stock Cc
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_cc,
						          sp_codigoqr_cc,
						          sp_fecharequerida_cc				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'STOCK_CC'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_cc,
						          sp_maxfecha_cc				   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ot;					    
		
					       if (sp_cantidad_cc = 0 ) then
		                       sp_cantidad_cc := 1;
		                   end if;					   
						   
						   sp_avance_cc := round((sp_recept_cc * 100.00 ) / sp_cantidad_cc , 2);						    
					       sp_atraso_cc := 0;
		
						   sp_color_cc  := 0;			      
					       if ( sp_avance_cc >= 100) then
						       sp_color_cc   := 1;
						   end if;	

			      --  sp_dias_av := date_part('day' , rec_ord.fechaentrega - now() )
			      
			      --  Para elementos de desgaste
			        sp_subproducto := '';
			        sp_cantidad := 0;
			      
				    if rec_ord.idfamilia = 11 then
				   
				        select count(distinct b.nombreproductonepcast)
				          into sp_cantidad
						  from mct_ordentrabajorepuesto a,
							   mct_productonepcast b
						 where a.idordentrabajo = rec_ord.idordentrabajo
						   and a.idproductonepcast  = b.idproductonepcast ;
		
		
						if sp_cantidad > 1 then
						
							sp_subproducto := 'Varios';
						else
						
							select distinct b.nombreproductonepcast
					          into sp_subproducto
							  from mct_ordentrabajorepuesto a,
								   mct_productonepcast b
							 where a.idordentrabajo = rec_ord.idordentrabajo
							   and a.idproductonepcast  = b.idproductonepcast ;
						  
						end if;
				   
			       
			        end if;
			       
				    itemot         := rec_ord.item;
				    idworkorder    := rec_ord.idordentrabajo;
					auttype        := rec_ord.tipoautoriza;	    
					--ordertypename  := rec_ord.nombretipoorden;
					ordertypename  := rec_ord.siglatipo;		
					username       := rec_ord.nombre;
				    --familyname     := rec_ord.nombrefamilia;
				    familyname     := rec_ord.siglafam;	
					productname    := rec_ord.producto;
					subproductname := sp_subproducto;
				    customername   := rec_ord.nombrecorto;
			        --deliverydatetm     := to_char(sp_fecha_entdes - interval '7 days','dd-mm-yyyy');
					--deliverydateclte   := to_char(sp_fecha_entdes,'dd-mm-yyyy');
					
				    deliverydatetm := rec_ord.fechaentregatm;
				    deliverydateclte := rec_ord.fechaentregaclte;
				   
				    --statusdispatch := sp_dias_atraso_status;
				  
				    if (rec_ord.idordentrabajo in (30322,30374) ) then
				       sp_avance   := 100;
				       sp_color_status := 1;
				    else
				       sp_color_status := 0;		    
				    end if;
				   
				    if (sp_avance >= 100) then
				        statusdispatch  := sp_dias_lcc;
				    else
				    	statusdispatch  := rec_ord.dias;
				    end if;
				   
				   	if ( sp_cantidad_fu is null) then
				        sp_avance_fu := 999;
				    end if;
				    if ( sp_cantidad_pa is null) then
				        sp_avance_pa := 999;
				    end if;
				   	if ( sp_cantidad_ca is null) then
				        sp_avance_ca := 999;
				    end if;
				    if ( sp_cantidad_co is null) then
				        sp_avance_co := 999;
				    end if;
				   	if ( sp_cantidad_ot is null) then
				        sp_avance_ot := 999;
				    end if;
				   	if ( sp_cantidad_cc is null) then
				        sp_avance_cc := 999;
				    end if;
				   
		
				    statuscliente  := rec_ord.diascliente;	
				   
					--advance        := sp_avance;
					select coalesce (salav)
	                  into sp_funcav 
	                  from traking.calcularavancemecanizado(rec_ord.idordentrabajo);
	 
					advance        := sp_funcav;
					
				    advancefu      := coalesce(sp_avance_fu,0);
					advancepa      := coalesce(sp_avance_pa,0);
					advanceca      := coalesce(sp_avance_ca,0);
					advanceco      := coalesce(sp_avance_co,0);
					advanceot      := coalesce(sp_avance_ot,0);
					advancecc      := coalesce(sp_avance_cc,0);		
					itemcolor      := coalesce(sp_color_item,0);
		   			statuscolor    := coalesce(sp_color_status,0);   		
					fucolor        := sp_color_fu;
					pacolor        := sp_color_pa;
					cacolor        := sp_color_ca;		
					cocolor        := sp_color_co;
					otcolor        := sp_color_ot;	
					cccolor        := sp_color_cc;			
					delayfu        := coalesce(sp_atraso_fu,0); 
					delaypa        := coalesce(sp_atraso_pa,0); 
					delayca        := coalesce(sp_atraso_ca,0); 
					delayco        := coalesce(sp_atraso_co,0); 
					delayot        := coalesce(sp_atraso_ot,0); 
					delaycc        := coalesce(sp_atraso_cc,0); 		
				    flagfact       := rec_ord.flagfacturacion;
				    fundiciondate  := rec_ord.fechafundicion;
				   
					sp_lista := '(';
									   
					FOR rec_ordcomp IN (   
						select nombrecomponentetemp||'('||cantidad||') '||nombreplano  as pieza
						      from mct_ordentrabajorepuesto mo 
						     where idordentrabajo = rec_ord.idordentrabajo 
							)
					    loop 	
						    
						    sp_lista := rec_ordcomp.pieza||' / '||sp_lista;
										           
					END LOOP;
				
				    piezas		:= cast(substring(sp_lista,1,length(sp_lista)-3) as varchar);
				   
				    select count(*)
				      into sp_estaenproceso
				      from traking.mct_movimientoordentrabajo a
				     where a.idordentrabajo = rec_ord.idordentrabajo
				       and a.estadoactividad = 1;
				      
				    estaenproceso  := sp_estaenproceso;

		    montototaldesp	:= 0;
		    montoarrastre	:= 0;
		   
	         if (rec_ord.idfamilia = 8) then
	         
	         	select coalesce(sum(montorepfab),0)
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	    montoarrastre	:= montototalot - montototaldesp;
	         	
	         	else
	         	
	         		montoarrastre	:= montototalot - montototaldesp;
	         	
	         	end if;	         	
	         
	         elsif (rec_ord.idfamilia = 11) then
	         
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into montototalot
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(b.qdespacho * c.costo ) , 0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
	         	
		        select coalesce(sum(b.qdespacho * c.costo ) , 0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		        montoarrastre	:= montototalot - montoarrastre;
		         	    	  
	         elsif (rec_ord.idfamilia = 10 or rec_ord.idfamilia = 15) then
	
	           	select coalesce(sum(montorepfab),0) 
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into sp_montoadicional
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	montototalot	:= montototalot + sp_montoadicional;
	         
	            select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		         	  
		        select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	    	
		        montoarrastre	:= montototalot - montoarrastre;
	         	
	         else
	         
	         	montototalot	:= 0;
	         
	         
	         end if;	
	        
	        montodespachadosanteriores	:= 0;
	        montodespachadoporguia		:= 0;
	       
	        if (rec_ord.anterior = 99 ) then
	        
		        select coalesce(sum(b.qdespacho * c.costo ) , 0)*-1
	         	  into montodespachadoporguia
	         	  from mct_despachopartecabecera a ,
	         	       mct_despachopartedetalle b,
	         	       mct_ordentrabajorepuesto c
	         	 where a.idordentrabajo = rec_ord.idordentrabajo
	         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
	         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
	         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
         	  
	        else
	        
		        select coalesce(sum(b.qdespacho * c.costo ) , 0)*-1
	         	  into montodespachadosanteriores
	         	  from mct_despachopartecabecera a ,
	         	       mct_despachopartedetalle b,
	         	       mct_ordentrabajorepuesto c
	         	 where a.idordentrabajo = rec_ord.idordentrabajo
	         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
	         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
	         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;	        
	        
	        end if ;

			sp_lista := '';
						   
			FOR rec_email IN (   
						select guiasaliente 
					      from traking.mct_despachopartecabecera
					     where idordentrabajo = rec_ord.idordentrabajo 
				 	)
			    loop 	
							
					sp_lista := rec_email.guiasaliente||'-'||sp_lista;
							           
		    end loop;

			ordencompra		:= rec_ord.ordencompra;
			if (length(sp_lista) = 0) then
				guiasdespacho	:= '0';
			else
				guiasdespacho	:= cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
			end if;
				       
			return next;
		
			END LOOP;	    
	    
END;
$$;


ALTER FUNCTION traking.evtlistcalendariodesgaste_consolidado(periodo character varying, agno bigint) OWNER TO postgres;

--
-- TOC entry 2166 (class 1255 OID 16893)
-- Name: evtlistcalendariodesgaste_consolidadosumaanterior(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcalendariodesgaste_consolidadosumaanterior(periodo character varying, agno bigint) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying, piezas character varying, estaenproceso bigint, montototalot bigint, montototaldesp bigint, montoarrastre bigint, montodespachadosanteriores bigint, montodespachadoporguia bigint, ordencompra character varying, guiasdespacho character varying)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_funcav			   numeric;
   
    sp_canthr              integer;
    sp_liberadascc         integer;
   
    rec_ord          	   record;
   
    rec_ordcomp            record;
   
    sp_lista			   varchar;
   
   	sp_fechamaxlcc         timestamp;
	sp_dias_lcc            integer;

    -- nepcast
    sp_cantidad            integer;
    sp_subproducto         varchar;
    -- Variable para fundicion
    sp_cantidad_fu         integer; 
	sp_codigoqr_fu         varchar;  
	sp_fecharequerida_fu   timestamp;

    -- Variable para pañol
    sp_cantidad_pa         integer; 
	sp_codigoqr_pa         varchar;  
	sp_fecharequerida_pa   timestamp;

    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    -- Variable para stock cc
    sp_cantidad_cc         integer; 
	sp_codigoqr_cc         varchar;  
	sp_fecharequerida_cc   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
    sp_avance_cc           numeric;
    sp_atraso_cc           integer;  
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
    sp_recept_cc           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
    sp_color_cc            integer;   
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
    sp_dias_cc             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
    sp_dias_atraso_cc      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
    sp_maxfecha_cc         timestamp;
   
    sp_nombreproducto	   varchar;
   
    sp_muestraorden		   integer;
    sp_countcheck		   integer;
    
    sp_indice              integer;
   
    sp_sumatotallcc        integer;
   
    rec_lcc      			RECORD;
    rec_email     			RECORD;
   
    sp_fami					integer;
    sp_mec					integer;
   
    sp_estaenproceso       bigint;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar; 
   
    sp_montoadicional		bigint;
   
begin
	 
	sp_estaenproceso	:= 0;

--	if ( idfamily = 111) then
	   sp_fami = 11;
	   sp_mec = 1;
--	elsif ( idfamily = 112) then
--	   sp_fami = 11;
--	   sp_mec = 2;	
--	end if;
	
	  
	select to_char(now(),'yyyy')
	  into ano;
	 
	select lpad(periodo, 2,'0')
	  into mes;
	 
	fechadesde	:= agno||'-'||mes||'-01';

    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'dd'),
           to_date(fechadesde,'yyyy-mm-dd') + interval '1 month',
           to_char( to_date(fechadesde,'yyyy-mm-dd') + interval '1 month', 'yyyy-mm')||'-'||to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'dd')
	  into ultimodia,
	       fechadesde,
	       fechahasta;
	 
	select to_char(now(),'yyyy')
	  into anofin;
	 
	--fechahasta	:= agno||'-'||mes||'-'||ultimodia;

	 raise notice '%', ultimodia;
	 raise notice '%', fechadesde;
	 raise notice '%', fechahasta;

	
    --fechadesde	:= '2023-10-24';

	  --  if ( desde != 'NA' and hasta != 'NA') then
	    
				FOR rec_ord IN (   
						   
				        select ROW_NUMBER() OVER (ORDER BY tab.fechaentrega asc) AS item,
				               tab.idproducto,
				               tab.idordentrabajo,
				               tab.idestadoorden,
				               tab.tipoautoriza,
				               tab.nombretipoorden,
				               tab.nombrefamilia,
				               tab.producto,
				               tab.nombrecorto,
				               tab.fechaentrega,
				               tab.fechaentregatm,
				               tab.fechafacetm,
				               tab.fechaentregaclte,
				               tab.dias,
				               tab.diascliente,
				               tab.idmodalidadcreacion,
				               tab.nombre,
				               tab.flagfacturacion,
				               tab.siglatipo,
				               tab.siglafam,
				               tab.fechafundicion,
				               tab.idfamilia,
                               tab.ordencompra
				          from (
								select a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_CON'||'_'||a.idestadoorden as nombrefamilia,
								       --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
								       case 
								          when a.idfamilia = 11 then c.nombreproducto
								          else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
								       end as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       a.idusuario||'#'||j.nombre as nombre,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_CON'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy')) as fechafundicion,
--									       when sp_mec = 2 then 
--									            to_char(a.fechafundicion ,'dd-mm-yyyy')
--									   end as fechafundicion,
									   a.idfamilia	,
                       				   cast(a.ordencompra as varchar) as ordencompra
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_producto c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_modelo g,
								       mct_subfamilia h,
								       mct_etapaparam i,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproducto 
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and c.idmodelo = g.idmodelo 
								   and g.idsubfamilia = h.idsubfamilia 
								   and c.idetapaparam = i.idetapaparam 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   and a.idusuario = j.idusuario 
								   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
								   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           --and (a.fechafundicion2 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           --and a.flagfacturacion is true
								   and a.debaja < 1
								   --order by a.fechafaceclte asc

							union 
								select --ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
								       a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_CON'||'_'||a.idestadoorden as nombrefamilia,
	                                   c.nombreproductonepcast  as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       a.idusuario||'#'||j.nombre as nombre,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_CON'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy')) as fechafundicion,
--									       when sp_mec = 2 then 
--									            to_char(a.fechafundicion ,'dd-mm-yyyy')
--									   end as fechafundicion,
									   a.idfamilia,
                       				   cast(a.ordencompra as varchar) as ordencompra
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_productonepcast c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproductonepcast  
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   --and c.idresponsable = j.idusuario 
								   and a.idusuario = j.idusuario
								   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
								   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           --and (a.fechafundicion2 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           --and a.flagfacturacion is true
								   and a.debaja < 1							
							--- Desde aca la nueva union
								   
						union
							    select a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_SIN'||'_'||a.idestadoorden as nombrefamilia,
								       --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
								       case 
								          when a.idfamilia = 11 then c.nombreproducto
								          else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
								       end as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       a.idusuario||'#'||j.nombre as nombre,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_SIN'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
--									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
--									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'))
--									       when sp_mec = 2 then 
									            to_char(a.fechafundicion ,'dd-mm-yyyy') as fechafundicion,
--									   end as fechafundicion,
									   a.idfamilia	,
                       				   cast(a.ordencompra as varchar) as ordencompra
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_producto c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_modelo g,
								       mct_subfamilia h,
								       mct_etapaparam i,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproducto 
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and c.idmodelo = g.idmodelo 
								   and g.idsubfamilia = h.idsubfamilia 
								   and c.idetapaparam = i.idetapaparam 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   and a.idusuario = j.idusuario 
								   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 2)
								   --and (a.fechaentrega >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						          -- and a.flagfacturacion is true
								   and a.debaja < 1
								   --order by a.fechafaceclte asc

							union 
								select --ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
								       a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_SIN'||'_'||a.idestadoorden as nombrefamilia,
	                                   c.nombreproductonepcast  as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       a.idusuario||'#'||j.nombre as nombre,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_SIN'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
--									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
--									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'))
--									       when sp_mec = 2 then 
									            to_char(a.fechafundicion ,'dd-mm-yyyy') as fechafundicion,
--									   end as fechafundicion,
									   a.idfamilia,
                       				   cast(a.ordencompra as varchar) as ordencompra
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_productonepcast c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproductonepcast  
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   --and c.idresponsable = j.idusuario 
								   and a.idusuario = j.idusuario 
								   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 2)
								   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						          -- and a.flagfacturacion is true
								   and a.debaja < 1	
							 ) tab
						     order by fechaentrega asc
								   
							)
				loop 	
				
				       -- colores seran
				       -- 1 : verde
				       -- 2 : amarillo
				       -- 3 : rojo
				       
				       -- sacamos el rango de fechas para el color de entrega
		   
		               select min(fecha_inicio), 
		                      max(fecha_termino),
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
		                      date_part('day', max(fecha_termino) - now() ) ,
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
		                 into sp_fecha_auto,
		                      sp_fecha_entdes,
		                      dias_entrega,
		                      dias_resto,
		                      dias_calculo
		                 from mct_progavisos 
		                where idordentrabajo = rec_ord.idordentrabajo
		                  and idsla in (5,8,9);
		                 
		               if (dias_resto = 0 ) then
		                   dias_resto := 1;
		               end if;
		
		              
		   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
		   			   
		   			   if now() > sp_fecha_entdes then 
		   			      sp_color_item    := 3;
		   			      sp_color_entrega := 3;
		   			   elsif sp_calculo_itement < 80 then
			   			      sp_color_item    := 1;
			   			      sp_color_entrega := 1;   			   
		   			   elsif sp_calculo_itement >= 80 then
		 	   			      sp_color_item    := 2;
			   			      sp_color_entrega := 2;     			   
		   			   end if; 
		                  

		   			   -- desde aca el nuevo calculo
			   		   sp_sumatotallcc  := 0;
			   			   
			   		   FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec_ord.idordentrabajo
								       and a.idhojaruta = b.idhojaruta 
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
				     			   select coalesce (sum(cantidad),0)
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5);
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  	   		   			  
				       -- aca sacamos la cantidad de piezas totales
					   select coalesce ( sum(cantidad), 0)
					     into sp_canthr
					     from mct_hojarutatemp mh
					    where idordentrabajo = rec_ord.idordentrabajo
					      and idboleano = 1
					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   -- aca sacamos la cantidad de piezas liberadas de control de calidad
					   select count(*) , 
		                      max(fechatermino)
					     into sp_liberadascc,
					          sp_fechamaxlcc
					     from mct_movimientoordentrabajo
					    where codigoaccion = 'L_CC'
					      and idordentrabajo = rec_ord.idordentrabajo; 
					     
					   sp_dias_lcc := 0;
					   sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
					      
					   if ( sp_canthr = 0) then
					       sp_avance := 0;
					   else
					       --sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
						   sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
					       if (sp_avance >= 100 ) then
					           sp_color_status  := 1;
					       end if;
		               end if;
		
		               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
		                 			     
		               if sp_dias_atraso_status < 0 then 
		                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
		               end if;
		                        
					   -- Fundicion
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_fu,
						          sp_codigoqr_fu,
						          sp_fecharequerida_fu
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_FU'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_fu,
						          sp_maxfecha_fu
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_fu; 
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						   sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_atraso_fu := 0;
						  
						   sp_color_fu  := 0;
						   if ( sp_avance_fu >= 100) then
						       sp_color_fu   := 1;
						   end if;
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;
						  
						   --if ( sp_maxfecha_fu > sp_fecharequerida_fu ) then
						   --    sp_atraso_fu  := date_part('day', sp_maxfecha_fu -  sp_fecharequerida_fu );
						   --    sp_color_fu   := 3;
						   --else
						   --    sp_color_fu   := 1;			   
						   --end if;
					  
					  
					   -- Pañol
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_pa,
						          sp_codigoqr_pa,
						          sp_fecharequerida_pa				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_PA'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_pa,
						          sp_maxfecha_pa		   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_pa;
		
					       if (sp_cantidad_pa = 0 ) then
		                       sp_cantidad_pa := 1;
		                   end if;
		              
						   sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    
					       sp_atraso_pa := 0;
		
						   sp_color_pa  := 0;			      
					       if ( sp_avance_pa >= 100) then
						       sp_color_pa   := 1;
						   end if;
						  
						   --if ( sp_maxfecha_pa > sp_fecharequerida_pa ) then
						   --    sp_atraso_pa  := date_part('day', sp_maxfecha_pa -  sp_fecharequerida_pa );
						   --    sp_color_pa   := 3;
						   --else
						   --    sp_color_pa   := 1;			   
						   --end if;				 
					  
					   -- Caldereria
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_ca,
						          sp_codigoqr_ca,
						          sp_fecharequerida_ca				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_CA'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_ca,
						          sp_maxfecha_ca	   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ca; 
		
					       if (sp_cantidad_ca = 0 ) then
		                      sp_cantidad_ca := 1;
		                   end if;
		              
						   sp_avance_ca := round((sp_recept_ca * 100.00 ) / sp_cantidad_ca , 2);
		
						   sp_color_ca  := 0;					  
					       if ( sp_avance_ca >= 100) then
						       sp_color_ca   := 1;
						   end if;				  
				 
						 
					   -- Compras
						   -- aca sacamos las piezas totales solicitadas a compras  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_co,
						          sp_codigoqr_co,
						          sp_fecharequerida_co				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'RPO'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_co,
						          sp_maxfecha_co	 			   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_co;			    
		
					       sp_atraso_co := 0;
					       if (sp_cantidad_co = 0 ) then
		                       sp_cantidad_co := 1;
		                   end if;				   
						   
						   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			
		
						   sp_color_co  := 0;				  
					       if ( sp_avance_co >= 100) then
						       sp_color_co   := 1;
						   end if;				 
						 
					   -- Taller Mecanico
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_ot,
						          sp_codigoqr_ot,
						          sp_fecharequerida_ot				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'OTROS'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_ot,
						          sp_maxfecha_ot				   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ot;					    
		
					       if (sp_cantidad_ot = 0 ) then
		                       sp_cantidad_ot := 1;
		                   end if;					   
						   
						   sp_avance_ot := round((sp_recept_ot * 100.00 ) / sp_cantidad_ot , 2);						    
					       sp_atraso_ot := 0;
		
						   sp_color_ot  := 0;				      
					       if ( sp_avance_ot >= 100) then
						       sp_color_ot   := 1;
						   end if;	

					   -- Stock Cc
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_cc,
						          sp_codigoqr_cc,
						          sp_fecharequerida_cc				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'STOCK_CC'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_cc,
						          sp_maxfecha_cc				   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ot;					    
		
					       if (sp_cantidad_cc = 0 ) then
		                       sp_cantidad_cc := 1;
		                   end if;					   
						   
						   sp_avance_cc := round((sp_recept_cc * 100.00 ) / sp_cantidad_cc , 2);						    
					       sp_atraso_cc := 0;
		
						   sp_color_cc  := 0;			      
					       if ( sp_avance_cc >= 100) then
						       sp_color_cc   := 1;
						   end if;	

			      --  sp_dias_av := date_part('day' , rec_ord.fechaentrega - now() )
			      
			      --  Para elementos de desgaste
			        sp_subproducto := '';
			        sp_cantidad := 0;
			      
				    if rec_ord.idfamilia = 11 then
				   
				        select count(distinct b.nombreproductonepcast)
				          into sp_cantidad
						  from mct_ordentrabajorepuesto a,
							   mct_productonepcast b
						 where a.idordentrabajo = rec_ord.idordentrabajo
						   and a.idproductonepcast  = b.idproductonepcast ;
		
		
						if sp_cantidad > 1 then
						
							sp_subproducto := 'Varios';
						else
						
							select distinct b.nombreproductonepcast
					          into sp_subproducto
							  from mct_ordentrabajorepuesto a,
								   mct_productonepcast b
							 where a.idordentrabajo = rec_ord.idordentrabajo
							   and a.idproductonepcast  = b.idproductonepcast ;
						  
						end if;
				   
			       
			        end if;
			       
				    itemot         := rec_ord.item;
				    idworkorder    := rec_ord.idordentrabajo;
					auttype        := rec_ord.tipoautoriza;	    
					--ordertypename  := rec_ord.nombretipoorden;
					ordertypename  := rec_ord.siglatipo;		
					username       := rec_ord.nombre;
				    --familyname     := rec_ord.nombrefamilia;
				    familyname     := rec_ord.siglafam;	
					productname    := rec_ord.producto;
					subproductname := sp_subproducto;
				    customername   := rec_ord.nombrecorto;
			        --deliverydatetm     := to_char(sp_fecha_entdes - interval '7 days','dd-mm-yyyy');
					--deliverydateclte   := to_char(sp_fecha_entdes,'dd-mm-yyyy');
					
				    deliverydatetm := rec_ord.fechaentregatm;
				    deliverydateclte := rec_ord.fechaentregaclte;
				   
				    --statusdispatch := sp_dias_atraso_status;
				  
				    if (rec_ord.idordentrabajo in (30322,30374) ) then
				       sp_avance   := 100;
				       sp_color_status := 1;
				    else
				       sp_color_status := 0;		    
				    end if;
				   
				    if (sp_avance >= 100) then
				        statusdispatch  := sp_dias_lcc;
				    else
				    	statusdispatch  := rec_ord.dias;
				    end if;
				   
				   	if ( sp_cantidad_fu is null) then
				        sp_avance_fu := 999;
				    end if;
				    if ( sp_cantidad_pa is null) then
				        sp_avance_pa := 999;
				    end if;
				   	if ( sp_cantidad_ca is null) then
				        sp_avance_ca := 999;
				    end if;
				    if ( sp_cantidad_co is null) then
				        sp_avance_co := 999;
				    end if;
				   	if ( sp_cantidad_ot is null) then
				        sp_avance_ot := 999;
				    end if;
				   	if ( sp_cantidad_cc is null) then
				        sp_avance_cc := 999;
				    end if;
				   
		
				    statuscliente  := rec_ord.diascliente;	
				   
					--advance        := sp_avance;
					select coalesce (salav)
	                  into sp_funcav 
	                  from traking.calcularavancemecanizado(rec_ord.idordentrabajo);
	 
					advance        := sp_funcav;
					
				    advancefu      := coalesce(sp_avance_fu,0);
					advancepa      := coalesce(sp_avance_pa,0);
					advanceca      := coalesce(sp_avance_ca,0);
					advanceco      := coalesce(sp_avance_co,0);
					advanceot      := coalesce(sp_avance_ot,0);
					advancecc      := coalesce(sp_avance_cc,0);		
					itemcolor      := coalesce(sp_color_item,0);
		   			statuscolor    := coalesce(sp_color_status,0);   		
					fucolor        := sp_color_fu;
					pacolor        := sp_color_pa;
					cacolor        := sp_color_ca;		
					cocolor        := sp_color_co;
					otcolor        := sp_color_ot;	
					cccolor        := sp_color_cc;			
					delayfu        := coalesce(sp_atraso_fu,0); 
					delaypa        := coalesce(sp_atraso_pa,0); 
					delayca        := coalesce(sp_atraso_ca,0); 
					delayco        := coalesce(sp_atraso_co,0); 
					delayot        := coalesce(sp_atraso_ot,0); 
					delaycc        := coalesce(sp_atraso_cc,0); 		
				    flagfact       := rec_ord.flagfacturacion;
				    fundiciondate  := rec_ord.fechafundicion;
				   
					sp_lista := '(';
									   
					FOR rec_ordcomp IN (   
						select nombrecomponentetemp||'('||cantidad||') '||nombreplano  as pieza
						      from mct_ordentrabajorepuesto mo 
						     where idordentrabajo = rec_ord.idordentrabajo 
							)
					    loop 	
						    
						    sp_lista := rec_ordcomp.pieza||' / '||sp_lista;
										           
					END LOOP;
				
				    piezas		:= cast(substring(sp_lista,1,length(sp_lista)-3) as varchar);
				   
				    select count(*)
				      into sp_estaenproceso
				      from traking.mct_movimientoordentrabajo a
				     where a.idordentrabajo = rec_ord.idordentrabajo
				       and a.estadoactividad = 1;
				      
				    estaenproceso  := sp_estaenproceso;

		    montototaldesp	:= 0;
		    montoarrastre	:= 0;
		   
	         if (rec_ord.idfamilia = 8) then
	         
	         	select coalesce(sum(montorepfab),0)
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	    montoarrastre	:= montototalot - montototaldesp;
	         	
	         	else
	         	
	         		montoarrastre	:= montototalot - montototaldesp;
	         	
	         	end if;	         	
	         
	         elsif (rec_ord.idfamilia = 11) then
	         
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into montototalot
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(b.qdespacho * c.costo ) , 0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
	         	
		        select coalesce(sum(b.qdespacho * c.costo ) , 0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		        montoarrastre	:= montototalot - montoarrastre;
		         	    	  
	         elsif (rec_ord.idfamilia = 10 or rec_ord.idfamilia = 15) then
	
	           	select coalesce(sum(montorepfab),0) 
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into sp_montoadicional
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	montototalot	:= montototalot + sp_montoadicional;
	         
	            select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		         	  
		        select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	    	
		        montoarrastre	:= montototalot - montoarrastre;
	         	
	         else
	         
	         	montototalot	:= 0;
	         
	         end if;	


			sp_lista := '';
						   
			FOR rec_email IN (   
						select guiasaliente 
					      from traking.mct_despachopartecabecera
					     where idordentrabajo = rec_ord.idordentrabajo 
				 	)
			    loop 	
							
					sp_lista := rec_email.guiasaliente||'-'||sp_lista;
							           
		    end loop;

			ordencompra		:= rec_ord.ordencompra;
			if (length(sp_lista) = 0) then
				guiasdespacho	:= '0';
			else
				guiasdespacho	:= cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
			end if;
		   
	        
	        if (montototalot > montoarrastre) then
	        
	        	return next;
	       
	        end if;
	       
	        montodespachadosanteriores	:= 0;
	        montodespachadoporguia		:= 0;
				       		
			END LOOP;	    
	    
	  --  end if;


END;
$$;


ALTER FUNCTION traking.evtlistcalendariodesgaste_consolidadosumaanterior(periodo character varying, agno bigint) OWNER TO postgres;

--
-- TOC entry 2068 (class 1255 OID 16895)
-- Name: evtlistcambingscandata(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcambingscandata(scancode character varying) RETURNS TABLE(idworkorder bigint, idcomponent bigint, idclient bigint, idproduct bigint, productname character varying, customername character varying, componentname character varying, comentario character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
		return QUERY
		select  d.idordentrabajo,
				c.idcomponente,
				e.idcliente,
				f.idproducto,
				f.nombreproducto,
				e.nombrecorto , 
		        c.nombrecomponente,   
                g.comentario
		  from mct_detallehojarutatemp a,
		       mct_hojarutatemp b,
		       mct_componente c,
		       mct_ordentrabajo d,
		       mct_cliente e,
		       mct_producto f
		left join traking.mct_cambioingenieria g on g.codhojaruta = scancode and g.idcierre = 0 
		where a.codhojaruta = scancode
		  and a.idhojarutatemp = b.idhojarutatemp 
		  and b.idcomponente = c.idcomponente
		  and b.idordentrabajo = d.idordentrabajo 
		  and e.idcliente = d.idcliente 
		  and f.idproducto = d.idproducto
	  ;

   END;
$$;


ALTER FUNCTION traking.evtlistcambingscandata(scancode character varying) OWNER TO postgres;

--
-- TOC entry 2005 (class 1255 OID 16896)
-- Name: evtlistcambioingenieria(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcambioingenieria(idevaluators bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, idcambioingenieria bigint, codhojaruta character varying, idcomponente bigint, nombrecomponente character varying, nombreplano character varying, idusuario bigint, nombreusuario character varying, comentario character varying, nombreequipo character varying, nombrematerial character varying, usuariocreacion character varying, fechacreacion character varying, usuariomodificacion character varying, fechamodificacion timestamp without time zone, idcierre bigint, imagen text)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;

BEGIN
-- iddefectoi = -1: Todos

    
	if ( idevaluators = -1 and startdate = 'NA' ) then

	     -- Todos
	      	 RETURN QUERY
	      		
			 SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
					 a.idcambioingenieria ,
					 a.codhojaruta,
					 a.idcomponente ,
					 i.nombrecomponente ,
					 cast(replace(a.nombreplano,' ', '') as varchar) as planocomponente,
					 a.idusuario ,
					 d.nombre as nombreusuario,
					 a.comentario,
					 cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					 j.nombrematerial ,
					 a.usuariocreacion ,
					 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
					 a.usuariomodificacion,
					 a.fechamodificacion,
					 a.idcierre,
					 cast('' as text) 
			    FROM traking.mct_cambioingenieria a
				left join  traking.mct_componente b                on a.idcomponente = b.idcomponente 
				left join  traking.mct_usuario d   	               on d.idusuario = a.idusuario 
				left join  traking.mct_detallehojarutatemp g 	   on a.codhojaruta = g.codhojaruta 
				left join  traking.mct_hojarutatemp h 	           on g.idhojarutatemp = h.idhojarutatemp 
				left join  traking.mct_componente i 	           on h.idcomponente = i.idcomponente 
				left join  traking.mct_material j 		           on h.idmaterial = j.idmaterial 
				left join  traking.mct_ordentrabajo k 	           on h.idordentrabajo = k.idordentrabajo 
				left join  traking.mct_producto l 		           on k.idproducto = l.idproducto 
				left join  traking.mct_modelo m 		           on l.idmodelo = m.idmodelo 
				left join  traking.mct_subfamilia n 	           on m.idsubfamilia = n.idsubfamilia 
		        order by a.fechacreacion ;

				
	elsif ( idevaluators = -1 and startdate != 'NA' ) then

	      	 RETURN QUERY
	      		
			 SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
					 a.idcambioingenieria ,
					 a.codhojaruta,
					 a.idcomponente ,
					 i.nombrecomponente ,
					 cast(replace(a.nombreplano,' ', '') as varchar) as planocomponente,
					 a.idusuario ,
					 d.nombre as nombreusuario,
					 a.comentario,
					 cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					 j.nombrematerial ,
					 a.usuariocreacion ,
					 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
					 a.usuariomodificacion,
					 a.fechamodificacion,
					 a.idcierre,
					 cast('' as text) 
			    FROM traking.mct_cambioingenieria a
				left join  traking.mct_componente b                on a.idcomponente = b.idcomponente 
				left join  traking.mct_usuario d   	               on d.idusuario = a.idusuario 
				left join  traking.mct_detallehojarutatemp g 	   on a.codhojaruta = g.codhojaruta 
				left join  traking.mct_hojarutatemp h 	           on g.idhojarutatemp = h.idhojarutatemp 
				left join  traking.mct_componente i 	           on h.idcomponente = i.idcomponente 
				left join  traking.mct_material j 		           on h.idmaterial = j.idmaterial 
				left join  traking.mct_ordentrabajo k 	           on h.idordentrabajo = k.idordentrabajo 
				left join  traking.mct_producto l 		           on k.idproducto = l.idproducto 
				left join  traking.mct_modelo m 		           on l.idmodelo = m.idmodelo 
				left join  traking.mct_subfamilia n 	           on m.idsubfamilia = n.idsubfamilia 
			    WHERE
		 		   (a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
		            a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) ;
				 
	elsif ( idevaluators > 0 and startdate = 'NA' ) then

	      	 RETURN QUERY
	      		
			 SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
					 a.idcambioingenieria ,
					 a.codhojaruta,
					 a.idcomponente ,
					 i.nombrecomponente ,
					 cast(replace(a.nombreplano,' ', '') as varchar) as planocomponente,
					 a.idusuario ,
					 d.nombre as nombreusuario,
					 a.comentario,
					 cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					 j.nombrematerial ,
					 a.usuariocreacion ,
					 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
					 a.usuariomodificacion,
					 a.fechamodificacion,
					 a.idcierre,
					 cast('' as text) 
			    FROM traking.mct_cambioingenieria a
				left join  traking.mct_componente b                on a.idcomponente = b.idcomponente 
				left join  traking.mct_usuario d   	               on d.idusuario = a.idusuario 
				left join  traking.mct_detallehojarutatemp g 	   on a.codhojaruta = g.codhojaruta 
				left join  traking.mct_hojarutatemp h 	           on g.idhojarutatemp = h.idhojarutatemp 
				left join  traking.mct_componente i 	           on h.idcomponente = i.idcomponente 
				left join  traking.mct_material j 		           on h.idmaterial = j.idmaterial 
				left join  traking.mct_ordentrabajo k 	           on h.idordentrabajo = k.idordentrabajo 
				left join  traking.mct_producto l 		           on k.idproducto = l.idproducto 
				left join  traking.mct_modelo m 		           on l.idmodelo = m.idmodelo 
				left join  traking.mct_subfamilia n 	           on m.idsubfamilia = n.idsubfamilia 
			    where a.idusuario = idevaluators;
				 
	elsif ( idevaluators > 0 and startdate != 'NA' ) then	

	      	 RETURN QUERY
	      		
			 SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
					 a.idcambioingenieria ,
					 a.codhojaruta,
					 a.idcomponente ,
					 i.nombrecomponente ,
					 cast(replace(a.nombreplano,' ', '') as varchar) as planocomponente,
					 a.idusuario ,
					 d.nombre as nombreusuario,
					 a.comentario,
					 cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					 j.nombrematerial ,
					 a.usuariocreacion ,
					 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
					 a.usuariomodificacion,
					 a.fechamodificacion,
					 a.idcierre,
					 cast('' as text) 
			    FROM traking.mct_cambioingenieria a
				left join  traking.mct_componente b                on a.idcomponente = b.idcomponente 
				left join  traking.mct_usuario d   	               on d.idusuario = a.idusuario 
				left join  traking.mct_detallehojarutatemp g 	   on a.codhojaruta = g.codhojaruta 
				left join  traking.mct_hojarutatemp h 	           on g.idhojarutatemp = h.idhojarutatemp 
				left join  traking.mct_componente i 	           on h.idcomponente = i.idcomponente 
				left join  traking.mct_material j 		           on h.idmaterial = j.idmaterial 
				left join  traking.mct_ordentrabajo k 	           on h.idordentrabajo = k.idordentrabajo 
				left join  traking.mct_producto l 		           on k.idproducto = l.idproducto 
				left join  traking.mct_modelo m 		           on l.idmodelo = m.idmodelo 
				left join  traking.mct_subfamilia n 	           on m.idsubfamilia = n.idsubfamilia  
			    WHERE
		 		   (a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
		            a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) and
				 	a.idusuario = idevaluators;
				 
    end if;
		 
END;
$$;


ALTER FUNCTION traking.evtlistcambioingenieria(idevaluators bigint, startdate character varying, enddate character varying) OWNER TO postgres;

