--
-- TOC entry 2141 (class 1255 OID 16899)
-- Name: evtlistchecklistinftectime(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistchecklistinftectime(idworkorders bigint) RETURNS TABLE(indexrow integer, idchecklistinftectime bigint, idchecklistinftec bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, idproceso integer, action1 character varying, idmachine1 bigint, machine1 character varying, time1 bigint, action2 character varying, idmachine2 bigint, machine2 character varying, time2 bigint, action3 character varying, idmachine3 bigint, machine3 character varying, time3 bigint, action4 character varying, idmachine4 bigint, machine4 character varying, time4 bigint, blueprintname character varying, usercreate character varying, datecreate timestamp without time zone, userupdate character varying, dateupdate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		SELECT 0,
		       coalesce (b.idchecklistinftectiempo , 0),
		       a.idchecklistinftec, 
		       a.idordentrabajo, 
		       a.nombreparte, 
		       a.cantidad, 
		       a.material, 
		       a.criterio, 
		       a.reparacion, 
		       0, -- proceso 
		       b.accion1 ,
		       b.idmaquina1 ,
		       b.maquina1 ,
		       b.tiempo1 ,
		       b.accion2 ,
		       b.idmaquina2 ,
		       b.maquina2 ,
		       b.tiempo2 ,
		       b.accion3 ,
		       b.idmaquina3 ,
		       b.maquina3 ,
		       b.tiempo3 ,    
		       b.accion4 ,
		       b.idmaquina4 ,
		       b.maquina4 ,
		       b.tiempo4 ,		       
		       a.plano, 
		       b.usuariocreacion, 
		       b.fechacreacion,
		       b.usuariomodificacion ,
		       b.fechamodificacion 
		FROM traking.mct_checklistinftec a
		left join  traking.mct_checklistinftectiempo b on a.idchecklistinftec = b.idchecklistinftec 
		where a.idordentrabajo = idworkorders
      order by a.nombreparte asc;

END;
$$;


