--
-- TOC entry 1135 (class 1255 OID 16900)
-- Name: evtlistchecklistreceptiondetail(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistchecklistreceptiondetail(idworkorder bigint, qrcodes character varying) RETURNS TABLE(idchecklistinftec bigint, partname character varying, quantity bigint, materialname character varying, criteria character varying, blueprintname character varying, qrcode character varying, worktypestd character varying, requestdate character varying, quantityrecept bigint, quantitybalance bigint)
    LANGUAGE plpgsql
    AS $$
declare

	sp_familia		bigint;

begin

	select idfamilia 
	  into sp_familia
	  from mct_ordentrabajo mo 
	 where idordentrabajo = idworkorder;
	 
	    if ( qrcodes like '%FAB_FU') then
	    
	    	if (sp_familia = 11) then
	    	
		        RETURN QUERY
		
				select a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
				       cast(coalesce(sum(b.cantidad),0) as bigint),
				       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint)
				from mct_checklistinftec a
				left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec and (a.codigoqr = idworkorder||'FAB_FU' or a.codigoqr = idworkorder||'FAB_FUPL') 
				where a.idordentrabajo = idworkorder
		          --and replace(a.codigoqr,'_','') = replace(qrcodes,'_','')
                  and a.noaplicasolicitud is false
		          and (a.codigoqr = qrcodes	or a.codigoqr = idworkorder||'FAB_FUPL')	          
				group by a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       a.fecharequerida 
				having a.cantidad > coalesce(sum(b.cantidad),0);	    	
	    	
	    	else
	    	
		        RETURN QUERY
		
				select a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
				       cast(coalesce(sum(b.cantidad),0) as bigint),
				       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint)
				from mct_checklistinftecvalido a
				left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec and (a.codigoqr = idworkorder||'FAB_FU' or a.codigoqr = idworkorder||'FAB_FUPL') 
				where a.idordentrabajo = idworkorder
		          --and replace(a.codigoqr,'_','') = replace(qrcodes,'_','')
		          and (a.codigoqr = qrcodes	or a.codigoqr = idworkorder||'FAB_FUPL'	)      
                  and a.noaplicasolicitud is not true    
				group by a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       a.fecharequerida 
				having a.cantidad > coalesce(sum(b.cantidad),0);	    	
	    	
	    	end if;
	    

			
	    else

	    	if (sp_familia = 11) then
	    	
		        RETURN QUERY
		
				select a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
				       cast(coalesce(sum(b.cantidad),0) as bigint),
				       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint)
				from mct_checklistinftec a
				left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec and a.codigoqr = b.codigoqr 
				where a.idordentrabajo = idworkorder
		          --and replace(a.codigoqr,'_','') = replace(qrcodes,'_','')
		          and a.codigoqr = qrcodes	          
				group by a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       a.fecharequerida 
				having a.cantidad > coalesce(sum(b.cantidad),0);	    	
	    	
	    	else
	    	
		        RETURN QUERY
		
				select a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
				       cast(coalesce(sum(b.cantidad),0) as bigint),
				       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint)
				from mct_checklistinftecvalido a
				left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec and a.codigoqr = b.codigoqr 
				where a.idordentrabajo = idworkorder
		          --and replace(a.codigoqr,'_','') = replace(qrcodes,'_','')
                  and a.noaplicasolicitud is not true 
		          and a.codigoqr = qrcodes	          
				group by a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       a.fecharequerida 
				having a.cantidad > coalesce(sum(b.cantidad),0);	    	
	    	
	    	end if;
	    
	    
	    end if;
	   


END;
$$;


