-- TOC entry 2240 (class 1255 OID 16901)
-- Name: evtlistchecklistreceptiondetaildesgaste(bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistchecklistreceptiondetaildesgaste(idworkorder bigint, qrcodes character varying, idfamily bigint) RETURNS TABLE(idchecklistinftec bigint, partname character varying, quantity bigint, materialname character varying, criteria character varying, blueprintname character varying, qrcode character varying, worktypestd character varying, requestdate character varying, quantityrecept bigint, quantitybalance bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;
   
begin
	 
		if ( idfamily = 111) then
		   sp_fami = 11;
		   sp_mec = 1;
		elsif ( idfamily = 112) then
		   sp_fami = 11;
		   sp_mec = 2;	
		end if;

	    if (sp_fami = 11) then
	    
			RETURN QUERY
			
					select a.idchecklistinftec ,
					       a.nombreparte ,
					       a.cantidad ,
					       a.material ,
					       a.criterio,
					       a.plano,
					       a.codigoqr ,
					       a.tipotrabajostd ,
					       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
					       cast(coalesce(sum(b.cantidad),0) as bigint),
					       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint)
					from mct_checklistinftec a
					left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec --and a.codigoqr = b.codigoqr 
					where a.idordentrabajo = idworkorder
			          --and replace(a.codigoqr,'_','') = replace(qrcodes,'_','')
			          and (a.codigoqr = qrcodes or a.codigoqr = idworkorder||'FAB_FUPL')
			          and a.idesmecanizado = sp_mec
					group by a.idchecklistinftec ,
					       a.nombreparte ,
					       a.cantidad ,
					       a.material ,
					       a.criterio,
					       a.plano,
					       a.codigoqr ,
					       a.tipotrabajostd ,
					       a.fecharequerida 
					having a.cantidad > coalesce(sum(b.cantidad),0);
			
	    else
	    
			RETURN QUERY
			
					select a.idchecklistinftec ,
					       a.nombreparte ,
					       a.cantidad ,
					       a.material ,
					       a.criterio,
					       a.plano,
					       a.codigoqr ,
					       a.tipotrabajostd ,
					       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
					       cast(coalesce(sum(b.cantidad),0) as bigint),
					       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint)
					from mct_checklistinftec a
					left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec --and a.codigoqr = b.codigoqr 
					where a.idordentrabajo = idworkorder
			          --and replace(a.codigoqr,'_','') = replace(qrcodes,'_','')
			          and (a.codigoqr = qrcodes or a.codigoqr = idworkorder||'FAB_FUPL'	)	          
					group by a.idchecklistinftec ,
					       a.nombreparte ,
					       a.cantidad ,
					       a.material ,
					       a.criterio,
					       a.plano,
					       a.codigoqr ,
					       a.tipotrabajostd ,
					       a.fecharequerida 
					having a.cantidad > coalesce(sum(b.cantidad),0);
			
	    end if;


END;
$$;


ALTER FUNCTION traking.evtlistchecklistreceptiondetaildesgaste(idworkorder bigint, qrcodes character varying, idfamily bigint) OWNER TO postgres;

--
-- TOC entry 1316 (class 1255 OID 16902)
-- Name: evtlistchecklistreceptiondetaildesgastepdf(bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistchecklistreceptiondetaildesgastepdf(idworkorder bigint, qrcodes character varying, idfamily bigint) RETURNS TABLE(idchecklistinftec bigint, partname character varying, quantity bigint, materialname character varying, criteria character varying, blueprintname character varying, qrcode character varying, worktypestd character varying, requestdate character varying, quantityrecept bigint, quantitybalance bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;
   
begin
	 
		if ( idfamily = 111 or idfamily = 1111 or idfamily = 1110) then
		   sp_fami = 11;
		   sp_mec = 1;
		elsif ( idfamily = 112) then
		   sp_fami = 11;
		   sp_mec = 2;	
		end if;

		if (sp_fami = 11) then
		
			RETURN QUERY
		
			select * 
			   from (
					select a.idchecklistinftec ,
					       a.nombreparte ,
					       a.cantidad ,
					       a.material ,
					       a.criterio,
					       a.plano,
					       a.codigoqr ,
					       a.tipotrabajostd ,
					       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
					       cast(coalesce(sum(b.cantidad),0) as bigint) as recepcionada,
					       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint) as pendiente
					from mct_checklistinftec a
					left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec --and a.codigoqr = b.codigoqr 
					where a.idordentrabajo = idworkorder
					  and a.codigoqr = qrcodes
					  and a.idesmecanizado = sp_mec
					group by a.idchecklistinftec ,
					       a.nombreparte ,
					       a.cantidad ,
					       a.material ,
					       a.criterio,
					       a.plano,
					       a.codigoqr ,
					       a.tipotrabajostd ,
					       a.fecharequerida 
					--order by cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint) desc
					--having a.cantidad > coalesce(sum(b.cantidad),0)
				union
					select a.idchecklistinftec ,
						   a.nombreparte ,
						   a.cantidad ,
						   a.material ,
						   a.criterio,
						   a.plano,
						   a.codigoqr ,
						   a.tipotrabajostd ,
						   cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
						   a.cantidad as recepcionada,
						   0 as pendiente
					  from mct_checklistinftec a 
					 where idordentrabajo = idworkorder 
					  -- and codigoqr = qrcodes or codigoqr = idworkorder||'FAB_FUPL'
					   and codigoqr = idworkorder||'FAB_FUPL'
					   and a.idesmecanizado = sp_mec
					   and exists ( select * 
					                     from mct_checklistinftecrecept b 
					                    where a.idchecklistinftec = b.idchecklistinftec
					                      and a.cantidad = b.cantidad 
					                      )
			      ) tabla
			    order by tabla.pendiente desc,
			             tabla.nombreparte asc;
	    else
			  
	    	RETURN QUERY
		
			select * 
			   from (
					select a.idchecklistinftec ,
					       a.nombreparte ,
					       a.cantidad ,
					       a.material ,
					       a.criterio,
					       a.plano,
					       a.codigoqr ,
					       a.tipotrabajostd ,
					       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
					       cast(coalesce(sum(b.cantidad),0) as bigint) as recepcionada,
					       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint) as pendiente
					from mct_checklistinftec a
					left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec --and a.codigoqr = b.codigoqr 
					where a.idordentrabajo = idworkorder
					  and a.codigoqr = qrcodes
					group by a.idchecklistinftec ,
					       a.nombreparte ,
					       a.cantidad ,
					       a.material ,
					       a.criterio,
					       a.plano,
					       a.codigoqr ,
					       a.tipotrabajostd ,
					       a.fecharequerida 
					--order by cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint) desc
					having a.cantidad > coalesce(sum(b.cantidad),0)
				union
					select a.idchecklistinftec ,
						   a.nombreparte ,
						   a.cantidad ,
						   a.material ,
						   a.criterio,
						   a.plano,
						   a.codigoqr ,
						   a.tipotrabajostd ,
						   cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
						   a.cantidad as recepcionada,
						   0 as pendiente
					  from mct_checklistinftec a 
					 where idordentrabajo = idworkorder 
					   and (codigoqr = qrcodes or codigoqr = idworkorder||'FAB_FUPL')
					   --and codigoqr = idworkorder||'FAB_FUPL'
					   and exists ( select * 
					                     from mct_checklistinftecrecept b 
					                    where a.idchecklistinftec = b.idchecklistinftec
					                      and a.cantidad = b.cantidad 
					                      )
			      ) tabla
			    order by tabla.pendiente desc,
			             tabla.nombreparte asc;
		            
	    end if;
		    

			                      
END;
$$;


