--

CREATE FUNCTION traking.evtlistchecklistreceptiondetailpdf(idworkorder bigint, qrcodes character varying) RETURNS TABLE(idchecklistinftec bigint, partname character varying, quantity bigint, materialname character varying, criteria character varying, blueprintname character varying, qrcode character varying, worktypestd character varying, requestdate character varying, quantityrecept bigint, quantitybalance bigint)
    LANGUAGE plpgsql
    AS $$

begin

     if ( qrcodes like '%FAB_FU') then
	
     	RETURN QUERY
     		
		select * 
		   from (
				select a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
				       cast(coalesce(sum(b.cantidad),0) as bigint) as recepcionada,
				       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint) as pendiente
				from mct_checklistinftecvalido a
				left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec --and (a.codigoqr = 31057||'FAB_FU' or a.codigoqr = 31057||'FAB_FUPL') 
				where a.idordentrabajo = idworkorder
				  and a.codigoqr in ( idworkorder||'FAB_FU' , idworkorder||'FAB_FUPL')
                  and a.noaplicasolicitud is not true 
				group by a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       a.fecharequerida 
				--order by cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint) desc
				--having a.cantidad > coalesce(sum(b.cantidad),0) -- Se modifica hoy 18/08/2023
				having a.cantidad >= coalesce(sum(b.cantidad),0) 
			union
				select a.idchecklistinftec ,
					   a.nombreparte ,
					   a.cantidad ,
					   a.material ,
					   a.criterio,
					   a.plano,
					   a.codigoqr ,
					   a.tipotrabajostd ,
					   cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
					   a.cantidad as recepcionada,
					   0 as pendiente
				  from mct_checklistinftecvalido a 
				 where idordentrabajo = idworkorder 
				   and codigoqr in ( idworkorder||'FAB_FU' , idworkorder||'FAB_FUPL')
                   and a.noaplicasolicitud is not true 
				   and exists ( select * 
				                     from mct_checklistinftecrecept b 
				                    where a.idchecklistinftec = b.idchecklistinftec
				                      and a.cantidad = b.cantidad 
				                      and a.codigoqr = b.codigoqr 
				                      )
		      ) tabla
		    order by tabla.pendiente desc,
		             tabla.nombreparte asc;     
     
     else
		    
		RETURN QUERY
		
		select * 
		   from (
				select a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
				       cast(coalesce(sum(b.cantidad),0) as bigint) as recepcionada,
				       cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint) as pendiente
				from mct_checklistinftecvalido a
				left join mct_checklistinftecrecept b on a.idchecklistinftec  = b.idchecklistinftec --and (a.codigoqr = 31057||'FAB_FU' or a.codigoqr = 31057||'FAB_FUPL') 
				where a.idordentrabajo = idworkorder
				  and a.codigoqr = qrcodes
                  and a.noaplicasolicitud is not true 
				group by a.idchecklistinftec ,
				       a.nombreparte ,
				       a.cantidad ,
				       a.material ,
				       a.criterio,
				       a.plano,
				       a.codigoqr ,
				       a.tipotrabajostd ,
				       a.fecharequerida 
				--order by cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint) desc
				--having a.cantidad > coalesce(sum(b.cantidad),0) -- Se modifica hoy 18/08/2023
				having a.cantidad >= coalesce(sum(b.cantidad),0) 
			union
				select a.idchecklistinftec ,
					   a.nombreparte ,
					   a.cantidad ,
					   a.material ,
					   a.criterio,
					   a.plano,
					   a.codigoqr ,
					   a.tipotrabajostd ,
					   cast(to_char(a.fecharequerida,'dd-mm-yyyy') as varchar),
					   a.cantidad as recepcionada,
					   0 as pendiente
				  from mct_checklistinftecvalido a 
				 where idordentrabajo = idworkorder 
				   and codigoqr = qrcodes
                   and a.noaplicasolicitud is not true 
				   and exists ( select * 
				                     from mct_checklistinftecrecept b 
				                    where a.idchecklistinftec = b.idchecklistinftec
				                      and a.cantidad = b.cantidad 
				                      and a.codigoqr = b.codigoqr 
				                      )
		      ) tabla
		    order by tabla.pendiente desc,
		             tabla.nombreparte asc;
		            
	  end if;	            
			                      
END;
$$;


ALTER FUNCTION traking.evtlistchecklistreceptiondetailpdf(idworkorder bigint, qrcodes character varying) OWNER TO postgres;

--
-- TOC entry 2350 (class 1255 OID 16904)
-- Name: evtlistchecklistreceptionhead(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistchecklistreceptionhead(qrcodes character varying) RETURNS TABLE(idworkorder bigint, customername character varying, workordername character varying, idfamily bigint, familyname character varying, idordertype bigint, ordertypename character varying, idlinedesign bigint, linedesignname text)
    LANGUAGE plpgsql
    AS $$
declare

	sp_idfamilia	bigint	:= 0;

begin

	select distinct b.idfamilia  
	  into sp_idfamilia
	  from mct_checklistinftec a,
	       mct_ordentrabajo b
	 where a.codigoqr = qrcodes
	   and a.idordentrabajo = b.idordentrabajo ;
	
	  if (sp_idfamilia = 11) then
	  	  
		RETURN QUERY
		
		select distinct a.idordentrabajo ,
		       c.nombrecliente ,
		       b.nombreordentrabajo ,
		       b.idfamilia ,
		       e.nombrefamilia ,
		       b.idtipoorden ,
		       d.nombretipoorden ,
		       b.idlineadiseno ,
			   case
			      when b.idlineadiseno = 1 then 'DE DISEÑO'
			      when b.idlineadiseno = 2 then 'DE LÍNEA'
			   end
		from mct_checklistinftec a,
		     mct_ordentrabajo b,
		     mct_cliente c,
		     mct_tipoorden d,
		     mct_familia e
		where replace(a.codigoqr,'_','') = replace(qrcodes,'_','')
		--where a.codigoqr = '32206FAB_FU'		
		  and a.idordentrabajo = b.idordentrabajo 
		  and b.idcliente  = c.idcliente 
		  and b.idtipoorden = d.idtipoorden 
		  and b.idfamilia = e.idfamilia ;	  
	  
	  else
	  	  
	        raise notice 'Entro por aca %', sp_idfamilia;
	       
			RETURN QUERY
			
			select distinct a.idordentrabajo ,
			       c.nombrecliente ,
			       b.nombreordentrabajo ,
			       b.idfamilia ,
			       e.nombrefamilia ,
			       b.idtipoorden ,
			       d.nombretipoorden ,
			       b.idlineadiseno ,
				   case
				      when b.idlineadiseno = 1 then 'DE DISEÑO'
				      when b.idlineadiseno = 2 then 'DE LÍNEA'
				   end
			from mct_checklistinftecvalido a,
			     mct_ordentrabajo b,
			     mct_cliente c,
			     mct_tipoorden d,
			     mct_familia e
			where replace(a.codigoqr,'_','') = replace(qrcodes,'_','')
			--where a.codigoqr = '32206FAB_FU'		
			  and a.idordentrabajo = b.idordentrabajo 
			  and b.idcliente  = c.idcliente 
			  and b.idtipoorden = d.idtipoorden 
			  and b.idfamilia = e.idfamilia ;	  
	  
	  end if;
	 

END;
$$;


ALTER FUNCTION traking.evtlistchecklistreceptionhead(qrcodes character varying) OWNER TO postgres;

--
-- TOC entry 2256 (class 1255 OID 16905)
-- Name: evtlistchecklistreceptionpending(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistchecklistreceptionpending(idworkorders bigint, qrcode character varying) RETURNS TABLE(itemnumber bigint, partname character varying, blueprintname character varying, materialname character varying, quantity bigint)
    LANGUAGE plpgsql
    AS $$
declare	 
begin
	
	return QUERY
	
	select row_number() over (order by a.nombreparte ),
	       nombreparte ,
	       plano,
	       material,
	       cantidad 
	 from (
			select a.nombreparte ,
			       a.plano ,
			       a.material ,
			       a.cantidad 
			  from mct_checklistinftec a 
			 where idordentrabajo = idworkorders
			   and a.codigoqr = qrcode
			   and  not exists (select 'x' from mct_checklistinftecrecept b where a.idchecklistinftec = b.idchecklistinftec)
			union
			select a.nombreparte ,
			       a.plano ,
			       a.material ,
			       a.cantidad - b.cantidad 
			  from mct_checklistinftec a,
			       mct_checklistinftecrecept b
			 where a.idordentrabajo = idworkorders
			   and a.codigoqr = qrcode
			   and a.idchecklistinftec = b.idchecklistinftec 
			   and a.cantidad > (select sum(cantidad) from mct_checklistinftecrecept c where a.idchecklistinftec = c.idchecklistinftec)
		) as a;
	
END;
$$;


ALTER FUNCTION traking.evtlistchecklistreceptionpending(idworkorders bigint, qrcode character varying) OWNER TO postgres;

