CREATE FUNCTION traking.evtlistcheckworkorder(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idcustomer bigint, customername character varying, idproduct bigint, productname character varying, workordername character varying, idordertype bigint, ordertypename character varying, idworkorderprev bigint, receptiondate text, deliverydate text, dispatchdate text, iduser bigint, username character varying, idorderstatus bigint, statusname character varying, customercontact character varying, createobs character varying, reparefabcost bigint, idlinedesign bigint, linedesignname text, idfamily bigint, familyname character varying, tag character varying, createway bigint, createwayname text, inputguide bigint, outputguide bigint, orderconclusion character varying, recomendation character varying, idpurshase bigint, idquotation bigint, userupdate character varying, idmaterial bigint, materialname character varying, generalplan character varying, enviasolicitud bigint, otcliente character varying, checklisturgente boolean, estaautorizado boolean, debaja integer, checklistvalido boolean, solped character varying, serieequipo character varying)
    LANGUAGE plpgsql
    AS $$
declare

   sp_idfamilia      	integer;
   sp_fechacreacion  	timestamp;
   sp_idproducto		integer;
begin

	select idfamilia,
           fechacreacion,
           idproducto 
      into sp_idfamilia,
           sp_fechacreacion,
           sp_idproducto
      from mct_ordentrabajo mo 
     where idordentrabajo = idworkorders;
    
    --if (sp_idfamilia = 11 and sp_fechacreacion > '2022-07-17') then -- esto es por los productos nepcast nuevos
    if (sp_idfamilia = 11 and sp_idproducto in (10,11,12,13,14,15,16,17)) then -- esto es por los productos nepcast nuevos

        RETURN QUERY
	
		select distinct a.idordentrabajo ,
		       a.idcliente ,
		       b.nombrecliente ,
		       a.idproducto ,
		       c.nombreproductonepcast  ,
		       a.nombreordentrabajo ,
		       a.idtipoorden ,
		       d.nombretipoorden ,
		       a.idordentrabajoanterior ,
		       to_char(a.fecharecepcion , 'dd-mm-yyyy'),
		       to_char(a.fechaentrega, 'dd-mm-yyyy'),
		       to_char(a.fechadespacho, 'dd-mm-yyy'),
		       a.idusuario ,
		       e.nombre ,
		       a.idestadoorden ,
		       f.nombreestado ,
		       a.contactocliente ,
		       a.observacioncreacion ,
		       a.montorepfab ,
		       a.idlineadiseno ,
		       case
		          when a.idlineadiseno = 1 then 'DE DISEÑO'
		          when a.idlineadiseno = 2 then 'DE LÍNEA'    
		          else 'NO ASIGNADA'
		       end,
		       a.idfamilia ,
		       g.nombrefamilia ,
		       a.tag,
		       a.idmodalidadcreacion ,
		       case
		          when a.idmodalidadcreacion = 1 then 'MANUAL'
		          when a.idmodalidadcreacion = 2 then 'AUTOMÁTICA'
		          else 'NO ASIGNADA'
		       end,       
		       a.guiaentrante ,
		       a.guiasaliente ,
		       a.conclusion ,
		       a.recomendacion ,
		       a.ordencompra ,
		       a.idcotizacion ,
		       a.usuariomodificacion,
		       cast(0 as bigint),
		       --c.idmaterial ,
		       --h.nombrematerial ,
		       --cast('SIN MATERIAL DEFINIDO' as varchar),
		       --cast('SIN PLANO DEFINIDO' as varchar),
		       cast('' as varchar),
		       cast('' as varchar),
		       --c.planogeneral ,
		       i.enviosolicitud ,
		       a.otcliente ,
		       a.checklisturgente,
		       case
		          when i.estado = 1 then true
		          else false
		       end,
		       a.debaja ,
		       a.checklistvalido ,
               a.solped,
               a.serieequipo
		from mct_ordentrabajo a,
		     mct_cliente b,
		     mct_productonepcast c,
		     mct_tipoorden d,
		     mct_usuario e,
		     mct_estadoorden f,
		     mct_familia g,
		     --mct_material h,
		     mct_progavisos i
		where a.idordentrabajo = idworkorders
		  and a.idcliente = b.idcliente 
		  and a.idproducto = c.idproductonepcast  
		  and a.idtipoorden = d.idtipoorden 
		  and a.idusuario = e.idusuario 
		  and a.idestadoorden = f.idestadoorden 
		  and a.idfamilia = g.idfamilia
		  --and c.idmaterial = h.idmaterial
		  and a.idordentrabajo = i.idordentrabajo ;
		 -- and i.idsla = 5;    
    
    else
    
        RETURN QUERY
	
		select distinct a.idordentrabajo ,
		       a.idcliente ,
		       b.nombrecliente ,
		       a.idproducto ,
		       c.nombreproducto ,
		       a.nombreordentrabajo ,
		       a.idtipoorden ,
		       d.nombretipoorden ,
		       a.idordentrabajoanterior ,
		       to_char(a.fecharecepcion , 'dd-mm-yyyy'),
		       to_char(a.fechaentrega, 'dd-mm-yyyy'),
		       to_char(a.fechadespacho, 'dd-mm-yyy'),
		       a.idusuario ,
		       e.nombre ,
		       a.idestadoorden ,
		       f.nombreestado ,
		       a.contactocliente ,
		       a.observacioncreacion ,
		       a.montorepfab ,
		       a.idlineadiseno ,
		       case
		          when a.idlineadiseno = 1 then 'DE DISEÑO'
		          when a.idlineadiseno = 2 then 'DE LÍNEA'    
		          else 'NO ASIGNADA'
		       end,
		       a.idfamilia ,
		       g.nombrefamilia ,
		       a.tag,
		       a.idmodalidadcreacion ,
		       case
		          when a.idmodalidadcreacion = 1 then 'MANUAL'
		          when a.idmodalidadcreacion = 2 then 'AUTOMÁTICA'
		          else 'NO ASIGNADA'
		       end,       
		       a.guiaentrante ,
		       a.guiasaliente ,
		       a.conclusion ,
		       a.recomendacion ,
		       a.ordencompra ,
		       a.idcotizacion ,
		       a.usuariomodificacion,
		       c.idmaterial ,
		       h.nombrematerial ,
		       c.planogeneral ,
		       i.enviosolicitud ,
		       a.otcliente ,
		       a.checklisturgente,
		       case
		          when i.estado = 1 then true
		          else false
		       end,
		       a.debaja ,
		       a.checklistvalido  ,
               a.solped,
               a.serieequipo
		from mct_ordentrabajo a,
		     mct_cliente b,
		     mct_producto c,
		     mct_tipoorden d,
		     mct_usuario e,
		     mct_estadoorden f,
		     mct_familia g,
		     mct_material h,
		     mct_progavisos i
		where a.idordentrabajo = idworkorders
		  and a.idcliente = b.idcliente 
		  and a.idproducto = c.idproducto 
		  and a.idtipoorden = d.idtipoorden 
		  and a.idusuario = e.idusuario 
		  and a.idestadoorden = f.idestadoorden 
		  and a.idfamilia = g.idfamilia
		  and c.idmaterial = h.idmaterial
		  and a.idordentrabajo = i.idordentrabajo ;
		 -- and i.idsla = 5;    
    
    end if;
   


END;
$$;


