CREATE FUNCTION traking.evtlistcheckworkorderchecklist(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idcustomer bigint, customername character varying, idproduct bigint, productname character varying, workordername character varying, idordertype bigint, ordertypename character varying, idworkorderprev bigint, receptiondate text, deliverydate text, dispatchdate text, iduser bigint, username character varying, idorderstatus bigint, statusname character varying, customercontact character varying, createobs character varying, reparefabcost bigint, idlinedesign bigint, linedesignname text, idfamily bigint, familyname character varying, tag character varying, createway bigint, createwayname text, inputguide bigint, outputguide bigint, orderconclusion character varying, recomendation character varying, idpurshase bigint, idquotation bigint, userupdate character varying, idmaterial bigint, materialname character varying, generalplan character varying, enviasolicitud bigint, otcliente character varying, checklisturgente boolean, estaautorizado boolean, debaja integer, checklistvalido boolean, checklistinfaprobado boolean)
    LANGUAGE plpgsql
    AS $$

declare

	sp_idproducto	bigint;
    sp_idfamilia    bigint;

begin
	
	sp_idproducto	:= 0;
    sp_idfamilia	:= 0;

	select idproducto ,
           idfamilia
	  into sp_idproducto,
           sp_idfamilia
 	  from mct_ordentrabajo mo 
	 where idordentrabajo = idworkorders;
	
	if ( sp_idproducto in (10,11,12,13,14,15,16,17) and sp_idfamilia = 11) then
	
	    RETURN QUERY
	
		select a.idordentrabajo ,
		       a.idcliente ,
		       b.nombrecliente ,
		       a.idproducto ,
		       c.nombreproductonepcast  ,
		       a.nombreordentrabajo ,
		       a.idtipoorden ,
		       d.nombretipoorden ,
		       a.idordentrabajoanterior ,
		       to_char(a.fecharecepcion , 'dd-mm-yyyy'),
		       to_char(a.fechaentrega, 'dd-mm-yyyy'),
		       to_char(a.fechadespacho, 'dd-mm-yyy'),
		       a.idusuario ,
		       e.nombre ,
		       a.idestadoorden ,
		       f.nombreestado ,
		       a.contactocliente ,
		       a.observacioncreacion ,
		       a.montorepfab ,
		       a.idlineadiseno ,
		       case
		          when a.idlineadiseno = 1 then 'DE DISEÑO'
		          when a.idlineadiseno = 2 then 'DE LÍNEA'    
		          else 'NO ASIGNADA'
		       end,
		       a.idfamilia ,
		       g.nombrefamilia ,
		       a.tag,
		       a.idmodalidadcreacion ,
		       case
		          when a.idmodalidadcreacion = 1 then 'MANUAL'
		          when a.idmodalidadcreacion = 2 then 'AUTOMÁTICA'
		          else 'NO ASIGNADA'
		       end,       
		       a.guiaentrante ,
		       a.guiasaliente ,
		       a.conclusion ,
		       a.recomendacion ,
		       a.ordencompra ,
		       a.idcotizacion ,
		       a.usuariomodificacion,
		       cast(0 as bigint) ,
		       --h.nombrematerial ,
		       cast('S/M' as varchar),
		       cast('S/P' as varchar) ,
		       i.enviosolicitud ,
		       a.otcliente ,
		       a.checklisturgente,
		       case
		          when i.estado = 1 then true
		          else false
		       end,
		       a.debaja ,
		       a.checklistvalido,
		       a.checklistinfaprobado 
		from mct_ordentrabajo a,
		     mct_cliente b,
		     mct_productonepcast c,
		     mct_tipoorden d,
		     mct_usuario e,
		     mct_estadoorden f,
		     mct_familia g,
		     --mct_material h,
		     mct_progavisos i
		where a.idordentrabajo = idworkorders
		  and a.idcliente = b.idcliente 
		  and a.idproducto = c.idproductonepcast  
		  and a.idtipoorden = d.idtipoorden 
		  and a.idusuario = e.idusuario 
		  and a.idestadoorden = f.idestadoorden 
		  and a.idfamilia = g.idfamilia
		  --and c.idmaterial = h.idmaterial
		  and a.idordentrabajo = i.idordentrabajo 
		  and i.idsla = 5;
	
	else
	
	    RETURN QUERY
	
		select a.idordentrabajo ,
		       a.idcliente ,
		       b.nombrecliente ,
		       a.idproducto ,
		       c.nombreproducto ,
		       a.nombreordentrabajo ,
		       a.idtipoorden ,
		       d.nombretipoorden ,
		       a.idordentrabajoanterior ,
		       to_char(a.fecharecepcion , 'dd-mm-yyyy'),
		       to_char(a.fechaentrega, 'dd-mm-yyyy'),
		       to_char(a.fechadespacho, 'dd-mm-yyy'),
		       a.idusuario ,
		       e.nombre ,
		       a.idestadoorden ,
		       f.nombreestado ,
		       a.contactocliente ,
		       a.observacioncreacion ,
		       a.montorepfab ,
		       a.idlineadiseno ,
		       case
		          when a.idlineadiseno = 1 then 'DE DISEÑO'
		          when a.idlineadiseno = 2 then 'DE LÍNEA'    
		          else 'NO ASIGNADA'
		       end,
		       a.idfamilia ,
		       g.nombrefamilia ,
		       a.tag,
		       a.idmodalidadcreacion ,
		       case
		          when a.idmodalidadcreacion = 1 then 'MANUAL'
		          when a.idmodalidadcreacion = 2 then 'AUTOMÁTICA'
		          else 'NO ASIGNADA'
		       end,       
		       a.guiaentrante ,
		       a.guiasaliente ,
		       a.conclusion ,
		       a.recomendacion ,
		       a.ordencompra ,
		       a.idcotizacion ,
		       a.usuariomodificacion,
		       c.idmaterial ,
		       h.nombrematerial ,
		       c.planogeneral ,
		       i.enviosolicitud ,
		       a.otcliente ,
		       a.checklisturgente,
		       case
		          when i.estado = 1 then true
		          else false
		       end,
		       a.debaja ,
		       a.checklistvalido,
		       a.checklistinfaprobado 
		from mct_ordentrabajo a,
		     mct_cliente b,
		     mct_producto c,
		     mct_tipoorden d,
		     mct_usuario e,
		     mct_estadoorden f,
		     mct_familia g,
		     mct_material h,
		     mct_progavisos i
		where a.idordentrabajo = idworkorders
		  and a.idcliente = b.idcliente 
		  and a.idproducto = c.idproducto 
		  and a.idtipoorden = d.idtipoorden 
		  and a.idusuario = e.idusuario 
		  and a.idestadoorden = f.idestadoorden 
		  and a.idfamilia = g.idfamilia
		  and c.idmaterial = h.idmaterial
		  and a.idordentrabajo = i.idordentrabajo 
		  and i.idsla = 5;
		 
	end if;
	


END;
$$;


ALTER FUNCTION traking.evtlistcheckworkorderchecklist(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 2202 (class 1255 OID 16909)
-- Name: evtlistciclosot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistciclosot(ots bigint) RETURNS TABLE(item bigint, fechad character varying, tpooperacion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE

	    rec1 	   		record;
	   
		sp_operacion		varchar;
	    fechad_ant			timestamp;
	    fechac_ant			timestamp;
	    sp_fechacreacion	timestamp;
	   
BEGIN
  
   	FOR rec1 IN (   
		    select row_number() over (order by fechadespacho asc) as item,
		          ot ,
		          otanterior,
		          fechadespacho,
		          to_char(age(current_timestamp, fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS'),
		          fechacreacion
		     from mct_relacionotciclo ,
		          mct_ordentrabajo
		    where ot = ots 
		      and pantalla = 'rep'
		      and otanterior = idordentrabajo
		      and fechadespacho is not null
          )
		loop    
		  
		     
		      select --idordentrabajo , 
		             --idordentrabajoanterior , 
		             --fechadespacho , 
		             to_char(age(fechacreacion, '2020-12-07 10:21:23.000'), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS'),
		             fechacreacion
		        into sp_operacion,
		             sp_fechacreacion
		        from mct_ordentrabajo mo 
		       where idordentrabajo = rec1.ot;
		      
		       item			:= 	rec1.item;
		       fechad		:=	to_char(rec1.fechadespacho,'dd-mm-yyyy');
		      -- tpooperacion	:=	sp_fechacreacion;
		       tpooperacion	:= trim(cast(to_char(round(EXTRACT(Epoch FROM sp_fechacreacion-rec1.fechadespacho)/3600),'999,999,999') as varchar ));

		      
		      return next;
		
		
		end loop;

END;
$$;


ALTER FUNCTION traking.evtlistciclosot(ots bigint) OWNER TO postgres;

--
-- TOC entry 1370 (class 1255 OID 16910)
-- Name: evtlistciclosothist(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistciclosothist(ots bigint) RETURNS TABLE(item bigint, fechad character varying, tpooperacion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE

	    rec1 	   		record;
	   
		sp_operacion	varchar;
	    fechad_ant		timestamp;
	    fechac_ant		timestamp;
	    tienemas		integer;
	   
BEGIN
	
   	FOR rec1 IN (   
   	        select * 
   	        from (
		    select row_number() over (order by fechadespacho asc) as item,
		          ot ,
		          otanterior,
		          fechadespacho,
		          to_char(age(current_timestamp, fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS')
		     from mct_relacionotciclo,
		          mct_ordentrabajo
		    where ot = ots 
		      and pantalla = 'hist'
		      and otanterior = idordentrabajo
		      and fechadespacho is not null) tabla
		      order by 1 desc
		      )
		loop    
		   
			if rec1.ot = rec1.otanterior then
			
			  tienemas := 0;
			  select count(*)
			    into tienemas
			    from mct_ordentrabajo
			   where idordentrabajoanterior = rec1.ot;
			  
			  if ( tienemas = 1 ) then

			      select 
			             --to_char(age(fechacreacion, rec1.fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS')
			             trim(cast(to_char(round(EXTRACT(Epoch FROM fechacreacion-rec1.fechadespacho)/3600),'999,999,999') as varchar ))
			        into sp_operacion
			        from mct_ordentrabajo mo 
			       where idordentrabajoanterior = rec1.otanterior;	
		      
			  else

			      select 
			             --to_char(age(fechacreacion, rec1.fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS')
			             trim(cast(to_char(round(EXTRACT(Epoch FROM current_timestamp - rec1.fechadespacho)/3600),'999,999,999') as varchar ))
			        into sp_operacion
			        from mct_ordentrabajo
			       where idordentrabajo = rec1.otanterior;			  
			  
			  end if;
			    

		    else
		      select 
		             --to_char(age(fechacreacion, rec1.fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS')
		             trim(cast(to_char(round(EXTRACT(Epoch FROM fechacreacion-rec1.fechadespacho)/3600),'999,999,999') as varchar ))
		        into sp_operacion
		        from mct_ordentrabajo mo 
		       where idordentrabajoanterior = rec1.otanterior;		    
		    end if;
		      
		       item			:= 	rec1.item;
		       fechad		:=	to_char(rec1.fechadespacho,'dd-mm-yyyy');
		       tpooperacion	:=	sp_operacion;
		      
		      -- tpooperacion	:= trim(cast(to_char(round(EXTRACT(Epoch FROM current_timestamp-rec1.fechadespacho)/3600),'999,999,999') as varchar ));
		      
		      return next;
		
		
		end loop;

END;
$$;


ALTER FUNCTION traking.evtlistciclosothist(ots bigint) OWNER TO postgres;

