--

CREATE FUNCTION traking.evtlistcomponentcopytemp(idworkorderse bigint, idcomponentse bigint) RETURNS TABLE(idroadmaptemp bigint, componentname character varying)
    LANGUAGE plpgsql
    AS $$
begin
	
	   RETURN QUERY
	            
		select a.idhojarutatemp ,
		       b.nombrecomponente 
		  from mct_hojarutatemp a,
		       mct_componente b 
		 where idordentrabajo = idworkorderse
		   and a.idhojarutatemp != idcomponentse
		   and a.idcomponente = b.idcomponente 
		 order by a.idhojarutatemp ;

END;
$$;


