--
-- TOC entry 2142 (class 1255 OID 16912)
-- Name: evtlistconsultahistoriacomrcial(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistconsultahistoriacomrcial(clientes character varying, bombas character varying) RETURNS TABLE(idordentrabajo bigint, tipoautoriza character varying, nombretipoorden character varying, nombrefamilia character varying, producto character varying, nombrecorto character varying, fechacreacion character varying, fechaentrega character varying, fechaentregaclte character varying, responsable character varying, siglatipo character varying, siglafam character varying, debaja character varying, fechainftec character varying, fechacotiza character varying, fechaoc character varying, fechadesp character varying)
    LANGUAGE plpgsql
    AS $$
declare 
			
	rec1      			    record;
  
BEGIN 


		FOR rec1 IN ( 
		
			 select tab.idordentrabajo,
			        tab.tipoautoriza, 
			        tab.nombretipoorden, 
			        tab.nombrefamilia,         
			        tab.producto, 
			        tab.nombrecorto, 
			        tab.fechacreacion, 
			        tab.fechaentrega, 
			        tab.fechaentregaclte, 
			        tab.responsable,        
			        tab.siglatipo,
			        tab.siglafam,
			        tab.debaja ,
                    tab.idfamilia,
                    tab.observacioncreacion           
			   from (
					select a.idordentrabajo ,
					       case 
					          when a.ordencompra > 0 then cast('S/A' as varchar)
					          when a.ordencompra = 0 then cast('S/A' as varchar)
					          else cast('S/A' as varchar)
					       end as tipoautoriza,   
					       d.nombretipoorden ,
					       e.nombrefamilia ,
						   case 
							  when a.idfamilia = 11 then c.nombreproducto
							  else cast(h.sigla||' '||g.nombremodelo||' '||i.nombreparam as varchar)
						   end as producto,
					       b.nombrecorto ,
					       cast(to_char(a.fechacreacion,'dd-mm-yyyy') as varchar) as fechacreacion ,
					       cast(to_char(a.fechaentrega,'dd-mm-yyyy') as varchar) as fechaentrega ,
					       cast(to_char(a.fechafaceclte,'dd-mm-yyyy') as varchar) as fechaentregaclte ,				       		       
					       j.nombre as responsable,
					       d.sigla as siglatipo,
					       e.sigla as siglafam,
					       case 
		                      when a.debaja = 1 then
		                           cast('DE BAJA' as varchar)
		                      else
		                           cast('Activa' as varchar)
		                   end as debaja,
                           a.idfamilia,
                           a.observacioncreacion
						  from mct_ordentrabajo a
						  left join mct_cliente b      on a.idcliente = b.idcliente
						  left join mct_producto c     on a.idproducto = c.idproducto
						  left join mct_tipoorden d    on a.idtipoorden = d.idtipoorden
						  left join mct_familia e      on a.idfamilia = e.idfamilia
						  left join mct_estadoorden f  on a.idestadoorden = f.idestadoorden
						  left join mct_modelo g       on c.idmodelo = g.idmodelo
						  left join mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia
						  left join mct_etapaparam i   on c.idetapaparam = i.idetapaparam
						  left join mct_usuario j      on a.idusuario = j.idusuario
						 where a.idordentrabajo >= 30000
						 order by a.fechacreacion asc
				) tab
			where case 
			          WHEN clientes != '-1' THEN 
			               tab.nombrecorto like '%'||replace(clientes,' ','%')||'%'
			          ELSE true 
			       end
			   and case 
			          WHEN bombas != '-1' THEN 
				           (
				               coalesce(tab.producto, '') like '%'||replace(bombas,' ','%')||'%'
				               or coalesce(tab.observacioncreacion, '') like '%'||replace(bombas,' ','%')||'%'
				           )
			          ELSE true 
			       end 

			)
 			Loop

				if (rec1.idfamilia in ( 11, 15, 13, 14) ) then
					fechainftec	:= null;
					fechacotiza	:= null;
					fechaoc		:= rec1.fechacreacion;
	
				elsif (rec1.idfamilia in (8, 10) ) then
	
					select to_char(fecha_real_termino, 'dd-mm-yyyy')
	                  into fechainftec
		              from mct_progavisos a
		             where a.idordentrabajo = rec1.idordentrabajo
		               and a.idsla = 3;
	
					select to_char(fecha_real_termino, 'dd-mm-yyyy')
	                  into fechacotiza
		              from mct_progavisos a
		             where a.idordentrabajo = rec1.idordentrabajo
		               and a.idsla = 4;
	
					select to_char(fecha_real_termino, 'dd-mm-yyyy')
	                  into fechaoc
		              from mct_progavisos a
		             where a.idordentrabajo = rec1.idordentrabajo
		               and a.idsla = 5;

					select to_char(max(fechadespacho), 'dd-mm-yyyy')
                      into fechadesp
					  from mct_despachopartecabecera a
                     where a.idordentrabajo = rec1.idordentrabajo;
	
				end if;
	
	
	 			idordentrabajo 		:= rec1.idordentrabajo;
	 			tipoautoriza 		:= rec1.tipoautoriza;
	 			nombretipoorden 	:= rec1.nombretipoorden;
	 			nombrefamilia 		:= rec1.nombrefamilia;
	 			producto 			:= rec1.producto;
	 			nombrecorto 		:= rec1.nombrecorto;
	 			fechacreacion 		:= rec1.fechacreacion;
	 			fechaentrega 		:= rec1.fechaentrega;
	 			fechaentregaclte 	:= rec1.fechaentregaclte;
	 			responsable 		:= rec1.responsable;
	 			siglatipo 			:= rec1.siglatipo;
	 			siglafam 			:= rec1.siglafam;
	 			debaja 				:= rec1.debaja;
	
				return next;

			end loop;

  
END;
$$;


ALTER FUNCTION traking.evtlistconsultahistoriacomrcial(clientes character varying, bombas character varying) OWNER TO postgres;

--
-- TOC entry 1935 (class 1255 OID 16914)
-- Name: evtlistcontrolequipo(bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcontrolequipo(idevaluators bigint, ots bigint, sdate character varying, edate character varying) RETURNS TABLE(item bigint, idworkorder bigint, idevaluator bigint, evaluatorname character varying, nombreproducto character varying, nombrecliente character varying, fecharecep character varying, orderstatus bigint, fechacontrolir character varying, fechasubecontrolir character varying, diferenciasubeir character varying, indicadorir bigint, estadoir bigint, fechadesarme character varying, fechasubedesarme character varying, diferenciasubedesarme character varying, indicadordesarme bigint, estadodesarme bigint, fechacontrolit character varying, fechasubecontrolit character varying, diferenciasubeit character varying, indicadorcontrolit bigint, estadoit bigint, fechacotiza character varying, diferenciacotiza character varying, indicadorcotiza bigint, fechaautoriza character varying, fechacontrolcheck character varying, fechasubecontrolcheck character varying, diferenciacontrolcheck character varying, indicadorcontrolcheck bigint, estadocheck bigint, fechacarpeta character varying, fechasubecarpeta character varying, diferenciasubecarpeta character varying, indicadorcarpeta bigint, estadocarpeta bigint, avance numeric, fechadespacho character varying, fechacontrolif character varying, fechasubeif character varying, diferenciasubeif character varying, indicadorsubeif bigint, estadoif bigint, desviacion bigint, tienedesviacion bigint)
    LANGUAGE plpgsql
    AS $$
declare

         sp_funcav					numeric;
         sp_fechacontrolir 			timestamp; 	-- suma 48 horas desde creada la ot
         sp_fechasubecontrolir 		timestamp;
         sp_diferenciasubeir		varchar;
         sp_indicadorir 			bigint;		-- 1: verde, 2: rojo
         sp_estadoir				bigint;
         
         sp_fechadesarme 			timestamp;  -- suma 96 horas desde autorizacion
         sp_fechasubedesarme 		timestamp;
         sp_diferenciasubedesarme	varchar;         
         sp_indicadordesarme 		bigint;		-- 1: verde, 2: rojo
         sp_estadodesarme			bigint;
        
         sp_fechacontrolit 			timestamp;  -- suma 200 horas desde autorizacion         
         sp_fechasubecontrolit 		timestamp;
         sp_diferenciasubeit		varchar;
         sp_indicadorcontrolit 		bigint;		-- 1: verde, 2: rojo
         sp_estadoit				bigint;
        
         sp_fechacotiza 			timestamp;
         sp_diferenciacotiza		varchar;
         sp_indicadorcotiza 		bigint;		-- 1: verde, 2: rojo
                 
         sp_fechaautoriza 			timestamp;
        
         sp_fechacontrolcheck 		timestamp; 	-- suma 48 horas desde autorizacion
         sp_fechasubecontrolcheck 	timestamp;
         sp_diferenciacontrolcheck	varchar;
         sp_indicadorcontrolcheck 	bigint;		-- 1: verde, 2: rojo
         sp_estadocheck				bigint;
        
         sp_fechacarpeta 			timestamp;  -- suma 96 horas desde autorizacion
         sp_fechasubecarpeta 		timestamp;
         sp_diferenciasubecarpeta	varchar;
         sp_indicadorcarpeta 		bigint;		-- 1: verde, 2: rojo
         sp_estadocarpeta			bigint;
        
         sp_fechadespacho 			timestamp;
         sp_fechacontrolif 			timestamp;  -- suma 72 horas desde despacho
         sp_fechasubeif 			timestamp;
         sp_diferenciasubeif		varchar;
         sp_indicadorsubeif 		bigint;		-- 1: verde, 2: rojo
         sp_estadoif				bigint;
         sp_sumatotallcc			numeric;
         
         desviacion 				bigint;
        
         sp_canthr					bigint;
		 sp_liberadascc				bigint;
		 sp_fechamaxlcc				timestamp;
		 sp_dias_lcc				bigint;
		 sp_avance					numeric;
		 sp_tienedesviacion			bigint;
         
	   	 rec1  						record;
	   	 rec_lcc      				record;
	   
begin
	
	if ( ots != -1 ) then

				FOR rec1 IN (   
			
						select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc, a.idordentrabajo asc) AS item,
						       a.idordentrabajo ,
						       a.idusuario ,
						       b.iniciales ,
						       b.nombre ,
						       a.idproducto ,
						       cast(e.sigla ||' '||d.nombremodelo||' '||f.nombreparam as varchar) as equipo,
						       g.nombrecliente ,
						       g.nombrecorto ,
						       a.fechacreacion ,
						       a.idestadoorden ,
						       a.checklistvalido ,
						       a.fechachecklistvalido ,
						       a.subedesarme ,
						       a.fechasubedesarme 
						  from mct_ordentrabajo a,
						       mct_usuario b,
						       mct_producto c,
						       mct_modelo d,
						       mct_subfamilia e,
						       mct_etapaparam f,
						       mct_cliente g
						 where --a.idordentrabajo in  (30963, 30968, 30975)
						       a.idordentrabajo  = ots
						   and a.idusuario = b.idusuario 
						   and a.idproducto = c.idproducto 
						   and c.idmodelo = d.idmodelo 
						   and d.idsubfamilia = e.idsubfamilia 
						   and c.idetapaparam = f.idetapaparam 
						   and a.idcliente = g.idcliente 
						   and a.idestadoorden < 9 -- esto se elimina hoy 20/05/2022 dado que cuando se suba el informe final recien se eliminan de esta consulta
						   and a.idtipoorden = 1
						   and a.debaja != 1
						  -- and a.idfamilia in (8, 10)
						   and a.idfamilia in (8)
						   --and a.fechacreacion >= '2022-03-14'
						   and (a.fechacreacion >= '2022-03-14' or idordentrabajo in (30968))
						   order by a.fechafaceclte desc, a.idordentrabajo asc
						   --and a.debaja 
						   
						   						   
					)
	     		loop 
	     		
		     		--sp_fechasubecontrolir := '';
	     		    sp_estadoir			:= 0;
		     	    select fecha_real_termino,
		     	           estado 
		     	      into sp_fechasubecontrolir,
		     	           sp_estadoir
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 10;
		     	    
		     	    sp_indicadorir		:= 1;  
		     	    sp_diferenciasubeir	:= null;
		     	    if ( sp_fechasubecontrolir >= rec1.fechacreacion::TIMESTAMP + '24 hr'::INTERVAL) then
		     	        --sp_diferenciasubeir	:= sp_fechasubecontrolir - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval);
		     	        sp_diferenciasubeir	:= (date_part( 'day', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp ), '00');
		     	        sp_indicadorir		:= 2;
		     	    else
		     	       -- sp_diferenciasubeir	:= (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval) - sp_fechasubecontrolir;
		     	        sp_diferenciasubeir	:= (date_part( 'day', (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp - sp_fechasubecontrolir::timestamp) * 24 +
						        date_part( 'hours', (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp - sp_fechasubecontrolir::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp - sp_fechasubecontrolir::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp - sp_fechasubecontrolir::timestamp), '00');
		     	           
		     	    end if;
		     	      
		     	   
		     	    -- Desarme
		     	    sp_indicadordesarme			:= 1;  
		     	    sp_diferenciasubedesarme	:= null;
		     	    if ( rec1.fechasubedesarme > rec1.fechacreacion::TIMESTAMP + '96 hr'::INTERVAL) then
		     	        --sp_diferenciasubeit	:= rec1.fechasubedesarme - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval);
		     	        sp_diferenciasubedesarme	:= (date_part( 'day', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ), '00');
		     	        sp_indicadordesarme		:= 2;
		     	    else
		     	       -- sp_diferenciasubeit	:= (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval) - rec1.fechasubedesarme;
		     	        sp_diferenciasubedesarme	:= (date_part( 'day', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp) * 24 +
