						        date_part( 'hours', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp), '00')||' Min';
						       --||':'||
