		     	        sp_diferenciasubedesarme	:= (date_part( 'day', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ), '00');
		     	        sp_indicadordesarme		:= 2;
		     	    else
		     	       -- sp_diferenciasubeit	:= (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval) - rec1.fechasubedesarme;
		     	        sp_diferenciasubedesarme	:= (date_part( 'day', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp) * 24 +
						        date_part( 'hours', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp), '00');
		     	       
		     	    end if;
		     	   
		     		--sp_fechasubecontrolit := '';
		     	    sp_estadoit			:= 0;
		     	    select fecha_real_termino ,
		     	           estado 
		     	      into sp_fechasubecontrolit,
		     	           sp_estadoit
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 3;

		     	    sp_indicadorcontrolit	:= 1;  
		     	    sp_diferenciasubeit		:= null;
		     	    if ( sp_fechasubecontrolit > rec1.fechacreacion::TIMESTAMP + '200 hr'::INTERVAL) then
		     	        --sp_diferenciasubeit	:= sp_fechasubecontrolit - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval);
		     	        sp_diferenciasubeit	:= (date_part( 'day', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp ), '00');
		     	        sp_indicadorcontrolit		:= 2;
		     	    else
		     	       -- sp_diferenciasubeit	:= (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval) - sp_fechasubecontrolit;
		     	        sp_diferenciasubeit	:= (date_part( 'day', (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubecontrolit::timestamp) * 24 +
						        date_part( 'hours', (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubecontrolit::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubecontrolit::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubecontrolit::timestamp), '00');
		     	       
		     	    end if;
		     	   
		     		--sp_fechacotiza := '';
		     	    select fecha_real_termino 
		     	      into sp_fechacotiza
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 4;
		     	      	      
		     		--sp_fechaautoriza := '';
		     	    select fecha_real_termino 
		     	      into sp_fechaautoriza
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 5;
		     	      
		     	      
		     		--sp_fechasubecarpeta := '';
		     	    sp_estadocarpeta		:= 0;
		     	    select fecha_real_termino ,
		     	           estado 
		     	      into sp_fechasubecarpeta ,
		     	           sp_estadocarpeta
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 6;
	
		     	    sp_diferenciacontrolcheck	:= null;
		     	    if ( rec1.fechachecklistvalido  <= sp_fechaautoriza::TIMESTAMP + '48 hr'::interval ) then
		     	        sp_diferenciacontrolcheck 	:= '00 hrs:00 min';
		     	        sp_indicadorcontrolcheck	:= 1;
		     	    elsif ( rec1.fechachecklistvalido  > sp_fechaautoriza::TIMESTAMP + '48 hr'::INTERVAL) then
		     	        --sp_diferenciasubeit	:= rec1.fechachecklistvalido - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval);
		     	        sp_diferenciacontrolcheck	:= (date_part( 'day', rec1.fechachecklistvalido::timestamp - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', rec1.fechachecklistvalido::timestamp - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', rec1.fechachecklistvalido::timestamp - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', rec1.fechachecklistvalido::timestamp - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp ), '00');
		     	        sp_indicadorcontrolcheck		:= 2;
		     	    else
		     	       -- sp_diferenciasubeit	:= (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval) - rec1.fechachecklistvalido;
		     	        sp_diferenciacontrolcheck	:= (date_part( 'day', (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp - rec1.fechachecklistvalido::timestamp) * 24 +
						        date_part( 'hours', (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp - rec1.fechachecklistvalido::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp - rec1.fechachecklistvalido::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (rec1.fechacreacion::TIMESTAMP + '48 hr'::interval)::timestamp - rec1.fechachecklistvalido::timestamp), '00');
		     	        sp_indicadorcontrolcheck		:= 1;
		     	    end if;
		     	      
		     	   
		     	    sp_indicadorcarpeta			:= 1;  
		     	    sp_diferenciasubecarpeta	:= null;
		     	    if ( sp_fechasubecarpeta > sp_fechaautoriza::TIMESTAMP + '96 hr'::INTERVAL) then
		     	        --sp_diferenciasubecarpeta	:= sp_fechasubecarpeta - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval);
		     	        sp_diferenciasubecarpeta	:= (date_part( 'day', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp ), '00');
		     	        sp_indicadorcarpeta		:= 2;
		     	    else
		     	       -- sp_diferenciasubecarpeta	:= (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval) - sp_fechasubecarpeta;
		     	        sp_diferenciasubecarpeta	:= (date_part( 'day', (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp - sp_fechasubecarpeta::timestamp) * 24 +
						        date_part( 'hours', (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp - sp_fechasubecarpeta::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp - sp_fechasubecarpeta::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp - sp_fechasubecarpeta::timestamp), '00');
		     	       
		     	    end if;
		     	   
		     		--sp_fechasubeif := '';
		     	    sp_estadoif			:= 0;
		     	    select fecha_real_termino,
		     	           estado 
		     	      into sp_fechasubeif,
		     	           sp_estadoif
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 8;

		     	    --select fechaguia
		     	    select d.fechadespacho
		     	      into sp_fechadespacho
		     	      from mct_despachopartecabecera d
		     	     where d.idordentrabajo = rec1.idordentrabajo;
		     	      
		     	    sp_indicadorsubeif	:= 1;  
		     	    sp_diferenciasubeif	:= null;
		     	    if ( sp_fechasubeif > sp_fechadespacho::TIMESTAMP + '200 hr'::INTERVAL) then
		     	        --sp_diferenciasubeif	:= sp_fechasubeif - (sp_fechadespacho::TIMESTAMP + '200 hr'::interval);
		     	        sp_diferenciasubeif	:= (date_part( 'day', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', sp_fechasubeif::timestamp - (rec1.fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp ), '00');
		     	        sp_indicadorsubeif		:= 2;
		     	    else
		     	       -- sp_diferenciasubeif	:= (sp_fechadespacho::TIMESTAMP + '200 hr'::interval) - sp_fechasubeif;
		     	        sp_diferenciasubeif	:= (date_part( 'day', (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubeif::timestamp) * 24 +
						        date_part( 'hours', (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubeif::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubeif::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubeif::timestamp), '00');
		     	       
		     	    end if;
		     	   
	     	      
		     	    sp_estadocheck		:= 0;
		     	    if ( rec1.checklistvalido = true) then
		     	        sp_estadocheck	:= 1;
		     	    end if;
		     	   
		     	    sp_estadodesarme		:= 0;
		     	    if ( rec1.subedesarme = true) then
		     	        sp_estadodesarme	:= 1;
		     	    end if;
		     	   
				    -- calcula avance mecanizado	
		     	    sp_sumatotallcc  := 0;

		     	   
			     	 FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec1.idordentrabajo 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
--				       			   select coalesce (sum(cantidad),0)
--								     into sp_liberadascc
--								     from mct_hojarutatemp
--								    where idhojarutatemp = rec_lcc.idhojarutatemp
--								      and idboleano = 1
--					                  and idareaclasificacion in (0,1,2,3,4,5);
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  		
				  	   -- aca sacamos la cantidad de piezas totales
--					   select coalesce ( sum(cantidad), 0)
--					     into sp_canthr
--					     from mct_hojarutatemp mh
--					    where idordentrabajo = rec_ord.idordentrabajo
--					      and idboleano = 1
--					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.idordentrabajo
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;
					  
--				    FOR rec_lcc IN (   
--								select distinct b.idhojarutatemp
--								  from mct_movimientoordentrabajo a,
--								       mct_hojaruta b
--								 where a.codigoaccion   = 'L_CC'
--							       and a.idordentrabajo = rec1.idordentrabajo
--							       and a.idhojaruta     = b.idhojaruta 
--								)
--					     loop 	
--	
--					     	sp_liberadascc	:= 0;
--									   
--					     	select coalesce (sum(cantidad),0)
