		     	        --sp_diferenciasubeit	:= sp_fechasubecontrolit - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval);
		     	        sp_diferenciasubeit	:= (date_part( 'day', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
