						        date_part( 'hours', (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubecontrolit::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubecontrolit::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubecontrolit::timestamp), '00');
		     	       
		     	    end if;
		     	   
		     		--sp_fechacotiza := '';
		     	    select fecha_real_termino 
