		     	        sp_diferenciasubecarpeta	:= (date_part( 'day', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp ), '00');
		     	        sp_indicadorcarpeta		:= 2;
		     	    else
		     	       -- sp_diferenciasubecarpeta	:= (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval) - sp_fechasubecarpeta;
		     	        sp_diferenciasubecarpeta	:= (date_part( 'day', (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp - sp_fechasubecarpeta::timestamp) * 24 +
						        date_part( 'hours', (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp - sp_fechasubecarpeta::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp - sp_fechasubecarpeta::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (sp_fechaautoriza::TIMESTAMP + '96 hr'::interval)::timestamp - sp_fechasubecarpeta::timestamp), '00');
		     	       
		     	    end if;
		     	   
		     		--sp_fechasubeif := '';
		     	    sp_estadoif			:= 0;
		     	    select fecha_real_termino,
