		     	    end if;
		     	   
		     	   
		     	    sp_estadodesarme		:= 0;
		     	    if ( rec1.subedesarme = true) then
		     	        sp_estadodesarme	:= 1;
		     	    end if;
		     	   
				    -- calcula avance mecanizado	
		     	    sp_sumatotallcc  := 0;

		     	   
			     	 FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
