					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
--				       			   select coalesce (sum(cantidad),0)
--								     into sp_liberadascc
--								     from mct_hojarutatemp
--								    where idhojarutatemp = rec_lcc.idhojarutatemp
--								      and idboleano = 1
--					                  and idareaclasificacion in (0,1,2,3,4,5);
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  		
				  	   -- aca sacamos la cantidad de piezas totales
--					   select coalesce ( sum(cantidad), 0)
--					     into sp_canthr
