--					    where idordentrabajo = rec_ord.idordentrabajo
--					      and idboleano = 1
--					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.idordentrabajo
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;
					  
--				    FOR rec_lcc IN (   
