						sp_dias_lcc := 0;
						sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
						      
						if ( sp_canthr = 0) then
						     sp_avance := 0;
					    else
							 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			            end if;		     	   
		     	      
			         sp_tienedesviacion	:= 0;
			         
			         select idtienedesviacion
			           into sp_tienedesviacion
			           from mct_controlequipoedesviacionpdf
			          where idordentrabajo = rec1.idordentrabajo;
			         
			        
			         item 						:= rec1.item;
			         idworkorder 				:= rec1.idordentrabajo; 
			         idevaluator 				:= rec1.idusuario; 
