						       to_char(date_part( 'minute', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + '200 hr'::interval)::timestamp ), '00');
