		     	        sp_diferenciasubeif	:= (date_part( 'day', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', sp_fechasubeif::timestamp - (rec1.fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp ), '00');
		     	        sp_indicadorsubeif		:= 2;
		     	    else
		     	       -- sp_diferenciasubeif	:= (sp_fechadespacho::TIMESTAMP + '200 hr'::interval) - sp_fechasubeif;
		     	        sp_diferenciasubeif	:= (date_part( 'day', (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubeif::timestamp) * 24 +
						        date_part( 'hours', (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubeif::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubeif::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (sp_fechadespacho::TIMESTAMP + '200 hr'::interval)::timestamp - sp_fechasubeif::timestamp), '00');
		     	       
		     	    end if;
		     	   
	     	      
		     	    sp_estadocheck		:= 0;
		     	    if ( rec1.checklistvalido = true) then
