			         fecharecep 				:= to_char(rec1.fechacreacion, 'dd-mm-yyyy');
			         --fecharecep 				:= rec1.fechacreacion;
			         orderstatus  				:= rec1.idestadoorden;         
	     		
			         fechacontrolir				:= to_char(rec1.fechacreacion::TIMESTAMP + '24 hr'::interval, 'yyyy-mm-dd hh24:mi:ss'); -- suma 24 horas desde creada la ot
			         fechasubecontrolir			:= to_char(sp_fechasubecontrolir, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubeir			:= coalesce(replace(sp_diferenciasubeir,'',''), '00 hrs:00 min');
			         indicadorir				:= sp_indicadorir;  -- 1: ok, 2: nok
			         estadoir					:= sp_estadoir;
			         
			         fechadesarme				:= to_char(rec1.fechacreacion::TIMESTAMP + '96 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 96 horas desde creada la ot
			         fechasubedesarme			:= to_char(rec1.fechasubedesarme, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubedesarme		:= coalesce(replace(sp_diferenciasubedesarme,'',''), '00 hrs:00 min');
			         indicadordesarme			:= sp_indicadordesarme;  -- 1: ok, 2: nok
			         estadodesarme				:= sp_estadodesarme;
			         
			         fechacontrolit				:= to_char(rec1.fechacreacion::TIMESTAMP + '200 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 200 horas desde creada la ot
			         fechasubecontrolit			:= to_char(sp_fechasubecontrolit, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubeit			:= coalesce(replace(sp_diferenciasubeit,'',''), '00 hrs:00 min');
			         indicadorcontrolit			:= sp_indicadorcontrolit;  -- 1: ok, 2: nok
			         estadoit					:= sp_estadoit;
			         
			         fechacotiza				:= to_char(sp_fechacotiza, 'dd-mm-yyyy');
			         diferenciacotiza			:= '';
			         indicadorcotiza			:= 1;		
			        
			         fechaautoriza				:= to_char(sp_fechaautoriza, 'dd-mm-yyyy');
			         
			         fechacontrolcheck			:= to_char(sp_fechaautoriza::TIMESTAMP + '48 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss'); -- suma 48 horas desde autorizacion
			         fechasubecontrolcheck		:= to_char(rec1.fechachecklistvalido, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciacontrolcheck		:= coalesce(replace(sp_diferenciacontrolcheck,'',''), '00 hrs:00 min');
			         indicadorcontrolcheck		:= sp_indicadorcontrolcheck;  -- 1: ok, 2: nok
			         estadocheck			    := sp_estadocheck;
			         
			         fechacarpeta				:= to_char(sp_fechaautoriza::TIMESTAMP + '96 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 96 horas desde autorizacion
			         fechasubecarpeta			:= to_char(sp_fechasubecarpeta, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubecarpeta		:= coalesce(replace(sp_diferenciasubecarpeta,'',''), '00 hrs:00 min');
			         indicadorcarpeta			:= sp_indicadorcarpeta;  -- 1: ok, 2: nok
			         estadocarpeta				:= sp_estadocarpeta;
			        
			         avance						:= coalesce (sp_avance, 0);
			        
			         --fechadespacho				:= to_char(sp_fechadespacho, 'yyyy-mm-dd hh24:mi:ss');
			         fechadespacho				:= to_char(sp_fechadespacho, 'dd-mm-yyyy');
			         
			         fechacontrolif				:= to_char(sp_fechadespacho::TIMESTAMP + '72 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 72 horas desde despacho
			         fechasubeif				:= to_char(sp_fechasubeif, 'yyyy-mm-dd hh24:mi:ss');
			         --fechasubeif				:= sp_fechasubeif;
			         diferenciasubeif			:= coalesce(replace(sp_diferenciasubeif,'',''), '00 hrs:00 min');
			         indicadorsubeif			:= sp_indicadorsubeif;  -- 1: ok, 2: nok
			         estadoif					:= sp_estadoif;
			        
			         desviacion					:= 0;
			         tienedesviacion			:= coalesce(sp_tienedesviacion, 0);
	     		
			        return next;
	     		
	     		end loop;
	     	
	elsif ( idevaluators > 0 and sdate = 'NA' ) then

				FOR rec1 IN (   
			
						select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc, a.idordentrabajo) AS item,
						       a.idordentrabajo ,
						       a.idusuario ,
						       b.iniciales ,
						       b.nombre ,
						       a.idproducto ,
						       cast(e.sigla ||' '||d.nombremodelo||' '||f.nombreparam as varchar) as equipo,
						       g.nombrecliente ,
						       g.nombrecorto ,
						       a.fechacreacion ,
						       a.idestadoorden ,
						       a.checklistvalido ,
						       a.fechachecklistvalido,
						       a.subedesarme ,
						       a.fechasubedesarme 
						  from mct_ordentrabajo a,
						       mct_usuario b,
						       mct_producto c,
						       mct_modelo d,
						       mct_subfamilia e,
						       mct_etapaparam f,
						       mct_cliente g
						 where --a.idordentrabajo in  (30963, 30968, 30975)
						       a.idordentrabajo  in (select idordentrabajo from mct_progavisos mp where idordentrabajo >= 30000 and idsla = 8 and estado = 0)
						   and a.idusuario = idevaluators
						   and a.idusuario = b.idusuario 
						   and a.idproducto = c.idproducto 
						   and c.idmodelo = d.idmodelo 
						   and d.idsubfamilia = e.idsubfamilia 
						   and c.idetapaparam = f.idetapaparam 
						   and a.idcliente = g.idcliente 
						   --and a.idestadoorden < 9 -- esto se elimina hoy 20/05/2022 dado que cuando se suba el informe final recien se eliminan de esta consulta
						   and a.idtipoorden = 1
						   and a.debaja != 1
						  -- and a.idfamilia in (8, 10)
						   and a.idfamilia in (8)
						   --and a.fechacreacion >= '2022-03-14'
						   and (a.fechacreacion >= '2022-03-14' or idordentrabajo in (30968))
						   order by a.fechafaceclte asc, a.idordentrabajo asc
						   --and a.debaja 
						   
						   						   
					)
	     		loop 
	     		
		     		--sp_fechasubecontrolir := '';
	     		    sp_estadoir			:= 0;
		     	    select fecha_real_termino,
		     	           estado 
		     	      into sp_fechasubecontrolir,
		     	           sp_estadoir
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 10;
		     	    
		     	    sp_indicadorir		:= 1;  
		     	    sp_diferenciasubeir	:= null;
		     	    if ( sp_fechasubecontrolir >= rec1.fechacreacion::TIMESTAMP + '24 hr'::INTERVAL) then
		     	        --sp_diferenciasubeir	:= sp_fechasubecontrolir - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval);
		     	        sp_diferenciasubeir	:= (date_part( 'day', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp ), '00');
		     	        sp_indicadorir		:= 2;
		     	    else
		     	       -- sp_diferenciasubeir	:= (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval) - sp_fechasubecontrolir;
		     	        sp_diferenciasubeir	:= (date_part( 'day', (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp - sp_fechasubecontrolir::timestamp) * 24 +
						        date_part( 'hours', (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp - sp_fechasubecontrolir::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp - sp_fechasubecontrolir::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp - sp_fechasubecontrolir::timestamp), '00');
		     	           
		     	    end if;
		     	      
		     	   
		     	    -- Desarme
		     	    sp_indicadordesarme			:= 1;  
