		     	    if ( rec1.fechasubedesarme > rec1.fechacreacion::TIMESTAMP + '96 hr'::INTERVAL) then
		     	        --sp_diferenciasubeit	:= rec1.fechasubedesarme - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval);
		     	        sp_diferenciasubedesarme	:= (date_part( 'day', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ), '00');
		     	        sp_indicadordesarme		:= 2;
		     	    else
		     	       -- sp_diferenciasubeit	:= (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval) - rec1.fechasubedesarme;
		     	        sp_diferenciasubedesarme	:= (date_part( 'day', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp) * 24 +
						        date_part( 'hours', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp), '00')||' Min';
						       --||':'||
						       --to_char(date_part( 'seconds', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp), '00');
		     	       
		     	    end if;
		     	   
		     		--sp_fechasubecontrolit := '';
		     	    sp_estadoit			:= 0;
		     	    select fecha_real_termino ,
		     	           estado 
