			         	indicadorsubeif		:= 1;  

			         end if;
			        
			        
			         desviacion					:= 0;
			         tienedesviacion			:= coalesce(sp_tienedesviacion, 0);
			         procesadodespachado		:= rec1.debaja;
	
					 -- Estado desarme
					select min(a.fechainicio),
					       max(a.fechatermino)
	                  into sp_inicio,
	                       sp_termino
					  from mct_movimientoordentrabajo a
					  left join mct_operador b on a.idoperador = b.idoperador
