		     	        sp_diferenciacontrolcheck	:= to_char(rec1.fechachecklistvalido , 'dd-mm-yyyy')||'('||date_part( 'day', (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval ) - rec1.fechachecklistvalido)*-1||')';
		     	     
		     	    end if;
		     	      
		     	   
		     	    sp_indicadorcarpeta			:= 1;  
