						       to_char(date_part( 'minute', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '110 hr'::interval)::timestamp ), '00')||' Min';
		     	        sp_indicadorcarpeta		:= 2;
		     	       
