						  left join mct_etapaparam f   on c.idetapaparam = f.idetapaparam 
						  left join mct_cliente g      on a.idcliente = g.idcliente 
						 where a.idordentrabajo  >= 30000--in (select idordentrabajo from mct_progavisos mp where idordentrabajo >= 30000 and idsla = 8 and estado = 0)
						   and a.idusuario = idevaluators
						   and (a.fechacreacion >= TO_TIMESTAMP(sdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP(edate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						   and a.idestadoorden < 9 -- esto se elimina hoy 20/05/2022 dado que cuando se suba el informe final recien se eliminan de esta consulta
						   and a.idtipoorden = 1
						   and a.debaja != 1
						   and a.idfamilia in (8, 15)
						   ----and (a.fechacreacion >= '2025-06-01' or idordentrabajo in (30968))
                           and (a.fechacreacion >= '2023-01-01' or idordentrabajo in (30968))
					union	   
						select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc, a.idordentrabajo asc) AS item,
						       a.idordentrabajo ,
