							   a.idestadoorden,
							   a.debaja as iddebaja
						  from mct_ordentrabajo a 
					      left join mct_usuario b      on a.idusuario = b.idusuario
					      left join mct_producto c     on a.idproducto = c.idproducto
						  left join mct_modelo d       on c.idmodelo = d.idmodelo
						  left join mct_subfamilia e   on d.idsubfamilia = e.idsubfamilia
						  left join mct_etapaparam f   on c.idetapaparam = f.idetapaparam 
						  left join mct_cliente g      on a.idcliente = g.idcliente
						 where a.idordentrabajo >= 30000
						   and a.idordentrabajo in (select idordentrabajo from mct_despachopartecabecera where a.fechadespacho >= '2023-01-01')
						   and a.idusuario = idevaluators
                           and a.idestadoorden <= 9 -- Se agrega por familia 15
						   and (a.fechacreacion >= TO_TIMESTAMP(sdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechacreacion <= TO_TIMESTAMP(edate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						   and a.idfamilia in (8, 15)
						   and a.idtipoorden = 1	
						   ) tabla
						   order by tabla.fechafaceclte desc, tabla.idordentrabajo asc				   
						   						   
					)
	     		loop 
	     		
		     		--sp_fechasubecontrolir := '';
	     		    sp_estadoir			:= 0;
		     	    select date(fecha_real_termino)::timestamp ,
		     	           estado 
		     	      into sp_fechasubecontrolir,
		     	           sp_estadoir
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 10;
		     	    
		     	    sp_indicadorir		:= 1;  
		     	    sp_diferenciasubeir	:= null;
		     	    if ( sp_fechasubecontrolir  <= (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)) then
		     	    
		     	        sp_diferenciasubeir 	:= to_char(sp_fechasubecontrolir , 'dd-mm-yyyy');
		     	        sp_indicadorir			:= 1;
		     	    
		     	    elsif ( sp_fechasubecontrolir > (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)) then
		     	        sp_diferenciasubeir	:= (date_part( 'day', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecontrolir::timestamp - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp ), '00')||' Min';
		     	        
						sp_indicadorir		:= 2;
		     	       
		     	        sp_diferenciasubeir	:= to_char(sp_fechasubecontrolir , 'dd-mm-yyyy')||'('||date_part( 'day', sp_fechasubecontrolir - (rec1.fechacreacion::TIMESTAMP + '24 hr'::interval)::timestamp)||')';
		     	       
		     	    end if;
		     	      
		     	   
		     	    -- Desarme
		     	    sp_indicadordesarme			:= 1;  
		     	    sp_diferenciasubedesarme	:= null;
		     	    if ( rec1.fechasubedesarme > (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)) then
		     	        sp_diferenciasubedesarme	:= (date_part( 'day', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', rec1.fechasubedesarme::timestamp - (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp ), '00')||' Min';
		     	        sp_indicadordesarme		:= 2;
		     	    else
		     	        sp_diferenciasubedesarme	:= (date_part( 'day', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp) * 24 +
						        date_part( 'hours', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', (rec1.fechacreacion::TIMESTAMP + '96 hr'::interval)::timestamp - rec1.fechasubedesarme::timestamp), '00')||' Min';
		     	       
		     	    end if;
		     	   
		     		--sp_fechasubecontrolit := '';
		     	    sp_estadoit			:= 0;
		     	    select date(fecha_real_termino)::timestamp ,
		     	           estado 
		     	      into sp_fechasubecontrolit,
		     	           sp_estadoit
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 3;

		     	    sp_indicadorcontrolit	:= 1;  
		     	    sp_diferenciasubeit		:= null;
		     	   
		     	   
		     	   select round(salhorav) 
					      into sp_horas
					 from traking.calculahorasincumplimientos_test_v1(rec1.fechacreacion, 77);
 
		     	    intervaloit    := ''''||sp_horas||' hr';
		     	   
		     	    if ( sp_fechasubecontrolit  <= (rec1.fechacreacion::TIMESTAMP + intervaloit::interval)) then
		     	    
		     	        sp_diferenciasubeit 	:= to_char(sp_fechasubecontrolit , 'dd-mm-yyyy');
		     	        sp_indicadorcontrolit	:= 1;
		     	    
		     	    elsif ( sp_fechasubecontrolit > (rec1.fechacreacion::TIMESTAMP + intervaloit::interval)) then
		     	        sp_diferenciasubeit	:= (date_part( 'day', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + intervaloit::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + intervaloit::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecontrolit::timestamp - (rec1.fechacreacion::TIMESTAMP + intervaloit::interval)::timestamp ), '00')||' Min';
		     	        sp_indicadorcontrolit		:= 2;
		     	       
		     	        sp_diferenciasubeit	:= to_char(sp_fechasubecontrolit , 'dd-mm-yyyy')||'('||date_part( 'day', sp_fechasubecontrolit - (rec1.fechacreacion::TIMESTAMP + intervaloit::interval)::timestamp)||')';
		     	       
					
		     	    end if;
		     	   
		       
                     select a.fecha_termino ,
                            a.estado,
	                        date(a.fecha_real_termino)::timestamp ,
	                        coalesce (date_part('day',a.fecha_real_termino - a.fecha_termino), 0) as demora
	                   into sp_fecha_ter_coti,
	                        sp_estado_coti,
	                        sp_fecha_real_ter_coti,
	                        sp_demora_coti
	                   from mct_progavisos a
	                   left join mct_usuario b on a.idusuarioinfrec = b.idusuario 
	                  where a.idordentrabajo = rec1.idordentrabajo
	                    and a.idsla = 4;
	                  
	                  		
			      	 sp_terminocot := to_char(sp_fecha_ter_coti,'yyyy-mm-dd hh24:mi:ss');
			         if sp_estado_coti != 0 then 		
			            sp_estadocoti := sp_estado_coti;
			            if sp_fecha_real_ter_coti is null then		            
			               --sp_diascoti  := date_part('day', now() - sp_fecharecepcion);
			               sp_kpicoti	:= date_part('day', now() - sp_fecharecepcion);
			            else
			               sp_kpicoti   := sp_demora_coti;
			            end if;		       
			         end if;	
			        
			        
		     		--sp_fechacotiza := '';
		     	    select date(fecha_real_termino)::timestamp ,
		     	           estado
		     	      into sp_fechacotiza ,
		     	           sp_estadocotiza
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 4;
		     	      	      
		     		--sp_fechaautoriza := '';
		     	    select date(fecha_real_termino)::timestamp 
		     	      into sp_fechaautoriza
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 5;
		     	      
		     	      
		     		--sp_fechasubecarpeta := '';
		     	    sp_estadocarpeta		:= 0;
		     	    select date(fecha_real_termino)::timestamp  ,
		     	           estado 
		     	      into sp_fechasubecarpeta ,
		     	           sp_estadocarpeta
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 6;
	
		     	             
		     	    sp_diferenciacontrolcheck	:= null;
		     	    if ( rec1.fechachecklistvalido  <= (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval) ) then
		     	    
		     	        sp_diferenciacontrolcheck 	:= to_char(rec1.fechachecklistvalido , 'dd-mm-yyyy');
		     	        sp_indicadorcontrolcheck	:= 1;
		     	    
		     	    elsif ( rec1.fechachecklistvalido  > (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)) then
		     	        sp_diferenciacontrolcheck	:= (date_part( 'day', rec1.fechachecklistvalido::timestamp - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', rec1.fechachecklistvalido::timestamp - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', rec1.fechachecklistvalido::timestamp - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)::timestamp ), '00')||' Min';
		     	        sp_indicadorcontrolcheck		:= 2;
		     	       
		     	        -- Se prueba con esto el nuevo proceso
		     	        -----sp_diferenciacontrolcheck	:= to_char(rec1.fechachecklistvalido , 'dd-mm-yyyy')||'('||date_part( 'day', sp_fechaautoriza - (rec1.fechachecklistvalido::TIMESTAMP + '48 hr'::interval)::timestamp)||')';
		     	        sp_diferenciacontrolcheck	:= to_char(rec1.fechachecklistvalido , 'dd-mm-yyyy')||'('||date_part( 'day', (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval ) - rec1.fechachecklistvalido)*-1||')';
		     	     
		     	    end if;
		     	      
		     	   
		     	    sp_indicadorcarpeta			:= 1;  
		     	    sp_diferenciasubecarpeta	:= null;
		     	    if ( sp_fechasubecarpeta <= (sp_fechaautoriza::TIMESTAMP + '110 hr'::interval)) then
		     	    
		     	        sp_diferenciasubecarpeta 	:= to_char(sp_fechasubecarpeta , 'dd-mm-yyyy');
		     	        sp_indicadorcarpeta			:= 1;
		     	    
		     	    elsif ( sp_fechasubecarpeta > (sp_fechaautoriza::TIMESTAMP + '110 hr'::interval)) then
		     	        sp_diferenciasubecarpeta	:= (date_part( 'day', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '110 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '110 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubecarpeta::timestamp - (sp_fechaautoriza::TIMESTAMP + '110 hr'::interval)::timestamp ), '00')||' Min';
		     	        sp_indicadorcarpeta		:= 2;
		     	       
		     	        -- Se prueba con esto el nuevo proceso
		     	        ----sp_diferenciasubecarpeta	:= to_char(sp_fechasubecarpeta , 'dd-mm-yyyy')||'('||date_part( 'day', sp_fechasubecarpeta - (sp_fechaautoriza::TIMESTAMP + '110 hr'::interval)::timestamp)||')';
		     	        sp_diferenciasubecarpeta	:= to_char(sp_fechasubecarpeta , 'dd-mm-yyyy')||'('||date_part( 'day', sp_fechasubecarpeta - (sp_fechaautoriza::TIMESTAMP + '110 hr'::interval) )||')';
		     	       
						
		     	    end if;
		     	   
		     		--sp_fechasubeif := '';
		     	    sp_estadoif			:= 0;
		     	    select date(fecha_real_termino)::timestamp,
		     	           estado 
		     	      into sp_fechasubeif,
		     	           sp_estadoif
		     	      from mct_progavisos mp 
		     	     where idordentrabajo = rec1.idordentrabajo
		     	       and idsla = 8;

		     	    --select fechaguia
		     	    select date(d.fechadespacho)::timestamp
		     	      into sp_fechadespacho
		     	      from mct_despachopartecabecera d
		     	     where d.idordentrabajo = rec1.idordentrabajo;
		     	      
		     	    sp_indicadorsubeif	:= 1;  
		     	    sp_diferenciasubeif	:= null;
		     	    if ( sp_fechasubeif <= (sp_fechadespacho::TIMESTAMP + '72 hr'::interval)) then
		     	    
		     	        sp_diferenciasubeif 	:= to_char(sp_fechasubeif , 'dd-mm-yyyy');
		     	        sp_indicadorsubeif		:= 1;
		     	    
		     	    elsif ( sp_fechasubeif > (sp_fechadespacho::TIMESTAMP + '72 hr'::interval)) then
		     	        sp_diferenciasubeif	:= (date_part( 'day', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '72 hr'::interval)::timestamp) * 24 +
						        date_part( 'hours', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '72 hr'::interval)::timestamp ) )::varchar||' Hrs :'||
						       to_char(date_part( 'minute', sp_fechasubeif::timestamp - (sp_fechadespacho::TIMESTAMP + '72 hr'::interval)::timestamp ), '00')||' Min';
		     	        sp_indicadorsubeif		:= 2;
		     	       
		     	        sp_diferenciasubeif	:= to_char(sp_fechasubeif , 'dd-mm-yyyy')||'('||date_part( 'day', sp_fechasubeif - (sp_fechadespacho::TIMESTAMP + '72 hr'::interval)::timestamp)||')';
		     	      
		     	       
		     	    end if;
		     	   
	     	      
		     	    sp_estadocheck		:= 0;
		     	    if ( rec1.checklistvalido = true) then
		     	        sp_estadocheck	:= 1;
		     	    end if;
		     	   
		     	    sp_estadodesarme		:= 0;
		     	    if ( rec1.subedesarme = true) then
		     	        sp_estadodesarme	:= 1;
		     	    end if;
		     	   
				    -- calcula avance mecanizado	
		     	    sp_sumatotallcc  := 0;

		     	   
			     	 FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec1.idordentrabajo 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;

					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.idordentrabajo
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;
					  
						     
						-- aca sacamos la cantidad de piezas liberadas de control de calidad
						select count(*) , 
			                   max(fechatermino)
						  into sp_liberadascc,
						       sp_fechamaxlcc
					      from mct_movimientoordentrabajo
					     where codigoaccion   = 'L_CC'
				 	       and idordentrabajo = rec1.idordentrabajo; 
						     
						sp_dias_lcc := 0;
						sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
						      
						if ( sp_canthr = 0) then
						     sp_avance := 0;
					    else
							 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			            end if;		     	   
		     	      
			         sp_tienedesviacion	:= 0;
			         
			         select idtienedesviacion
			           into sp_tienedesviacion
			           from mct_controlequipoedesviacionpdf
			          where idordentrabajo = rec1.idordentrabajo;
			        
			         item 						:= rec1.item;
			         idworkorder 				:= rec1.idordentrabajo; 
			         idevaluator 				:= rec1.idusuario; 
			         evaluatorname 				:= coalesce(rec1.iniciales, rec1.nombre);
			         nombreproducto 			:= rec1.equipo;
			         nombrecliente 				:= rec1.nombrecorto;
			         fecharecep 				:= to_char(rec1.fechacreacion, 'dd-mm-yyyy');
			         orderstatus  				:= rec1.idestadoorden;         
	     		
			         raise notice '%', 'sp_diferenciasubeir'||sp_diferenciasubeir;
			        
			         fechacontrolir				:= to_char(rec1.fechacreacion::TIMESTAMP + '24 hr'::interval, 'yyyy-mm-dd hh24:mi:ss'); -- suma 24 horas desde creada la ot
			         fechasubecontrolir			:= to_char(sp_fechasubecontrolir, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubeir			:= coalesce(replace(sp_diferenciasubeir,'',''), '00 hrs:00 min');
			         indicadorir				:= sp_indicadorir;  -- 1: ok, 2: nok
			         estadoir					:= sp_estadoir;
			         
			         raise notice '%', 'sp_diferenciasubedesarme'||sp_diferenciasubedesarme;
			         fechadesarme				:= to_char(rec1.fechacreacion::TIMESTAMP + '96 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 96 horas desde creada la ot
			         fechasubedesarme			:= to_char(rec1.fechasubedesarme, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubedesarme		:= coalesce(replace(sp_diferenciasubedesarme,'',''), '00 hrs:00 min');
			         indicadordesarme			:= sp_indicadordesarme;  -- 1: ok, 2: nok
			         estadodesarme				:= sp_estadodesarme;
			         
			         raise notice '%', 'sp_diferenciasubeit'||sp_diferenciasubeit;
			         fechacontrolit				:= to_char(rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 200 horas desde creada la ot
			         fechasubecontrolit			:= to_char(sp_fechasubecontrolit, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubeit			:= coalesce(replace(sp_diferenciasubeit,'',''), '00 hrs:00 min');
			         indicadorcontrolit			:= sp_indicadorcontrolit;  -- 1: ok, 2: nok
			         estadoit					:= sp_estadoit;	
			        
			         raise notice '%', 'fechasubecontrolit'||fechasubecontrolit;
			         if (fechasubecontrolit is null) then
			        			               
			         	if (date_part('day',date(now())::timestamp - (rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL)) <= 0) then
			            	diferenciasubeit		:= date_part('day',(rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL) - date(now())::timestamp );
			                indicadorcontrolit	    := 1;
			            else
				            diferenciasubeit		:= date_part('day',date(now())::timestamp - (rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL));
				         	indicadorcontrolit		:= 2;
			            end if;
			         
			         elsif (date_part('day',sp_fechasubecontrolit - (rec1.fechacreacion::TIMESTAMP + intervaloit::INTERVAL)) <= 0) then
			         	diferenciasubeit		:= to_char(sp_fechasubecontrolit, 'dd-mm-yyyy');
			         	indicadorcontrolit		:= 1;  

			         end if;
			   			       
			         			  
			         indicadorcotiza			:= 1;
			         estadocotiza				:= sp_estadocotiza;
			         if sp_kpicoti <= 0 then
			            fechacotiza				:= to_char(sp_fechacotiza, 'dd-mm-yyyy');
			         	diferenciacotiza		:= '';			         	
			         else
			         	fechacotiza				:= to_char(sp_fechacotiza, 'dd-mm-yyyy')||'('||sp_kpicoti||')';
			         	diferenciacotiza		:= '';
			         	indicadorcotiza			:= 2;	
			         end if;
			        
			         if (fechacotiza is null) then
			         	 raise notice '%', sp_fechasubecontrolit;
			        	 fechacotiza				:= to_char(sp_fechasubecontrolit, 'dd-mm-yyyy')||'('|| date_part('day',now() - sp_fechasubecontrolit::timestamp) ||')';
			        	 indicadorcotiza			:= 2;
			         end if;

			         
			         fechaautoriza				:= to_char(sp_fechaautoriza, 'dd-mm-yyyy');
			         if (sp_fechaautoriza is null) then
			         	fechaautoriza			:= date_part('day', date(now())::timestamp - sp_fechacotiza::TIMESTAMP);
			            sp_tienedesviacion		:= 99;
			         end if;
			         
			        raise notice '%', 'sp_fechaautoriza'||sp_fechaautoriza;
			         fechacontrolcheck			:= to_char(sp_fechaautoriza::TIMESTAMP + '48 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss'); -- suma 48 horas desde autorizacion
			         fechasubecontrolcheck		:= to_char(rec1.fechachecklistvalido, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciacontrolcheck		:= coalesce(replace(sp_diferenciacontrolcheck,'',''), '00 hrs:00 min');
			         indicadorcontrolcheck		:= sp_indicadorcontrolcheck;  -- 1: ok, 2: nok
			         estadocheck			    := sp_estadocheck;
			        
			         if (fechasubecontrolcheck is null) then
			         
			            if (date_part('day',now() - (date(sp_fechaautoriza)::TIMESTAMP + '48 hr'::interval)) <= 0) then
			            	diferenciacontrolcheck		:= to_char(sp_fechaautoriza::TIMESTAMP + '48 hr'::INTERVAL, 'dd-mm-yyyy')||'('|| date_part('day',date(now())::timestamp - (date(sp_fechaautoriza)::TIMESTAMP + '48 hr'::interval))||')';
			                indicadorcontrolcheck		:= 1;
			            else
				            diferenciacontrolcheck		:= to_char(sp_fechaautoriza::TIMESTAMP + '48 hr'::INTERVAL, 'dd-mm-yyyy')||'('|| date_part('day',date(now())::timestamp - (date(sp_fechaautoriza)::TIMESTAMP + '48 hr'::interval))||')';
				         	indicadorcontrolcheck		:= 2;
			            end if;			           
			         	
			         elsif (date_part('day',now() - (sp_fechaautoriza::TIMESTAMP + '48 hr'::interval)) <= 0) then
			         	diferenciacontrolcheck		:= to_char(sp_fechaautoriza::TIMESTAMP + '48 hr'::INTERVAL, 'dd-mm-yyyy');
			         	indicadorcontrolcheck		:= 1;			         
			         end if;
			        
			        
			         fechacarpeta				:= to_char(sp_fechaautoriza::TIMESTAMP + '110 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 110 horas desde autorizacion
			         fechasubecarpeta			:= to_char(sp_fechasubecarpeta, 'yyyy-mm-dd hh24:mi:ss');
			         diferenciasubecarpeta		:= coalesce(replace(sp_diferenciasubecarpeta,'',''), '00 hrs:00 min');
			         indicadorcarpeta			:= sp_indicadorcarpeta;  -- 1: ok, 2: nok
			         estadocarpeta				:= sp_estadocarpeta;
			        
			        
			         if (fechasubecarpeta is null) then
			         
			         	if (date_part('day',date(now())::timestamp - date(sp_fechaautoriza::TIMESTAMP + '110 hr'::INTERVAL)) < 0) then
			            	diferenciasubecarpeta	:= to_char(date(sp_fechaautoriza::TIMESTAMP + '110 hr'::interval), 'dd-mm-yyyy')||'('|| date_part('day',date(now())::timestamp - date(sp_fechaautoriza::TIMESTAMP + '110 hr'::INTERVAL))*-1||')';
			                indicadorcarpeta		:= 1;
			            elsif (date_part('day',date(now())::timestamp - date(sp_fechaautoriza::TIMESTAMP + '110 hr'::INTERVAL)) = 0) then
				            diferenciasubecarpeta	:= to_char(date(sp_fechaautoriza::TIMESTAMP + '110 hr'::interval), 'dd-mm-yyyy');
				         	indicadorcarpeta		:= 1;
				        else 
				            diferenciasubecarpeta	:= to_char(date(sp_fechaautoriza::TIMESTAMP + '110 hr'::interval), 'dd-mm-yyyy')||'('|| date_part('day',date(now())::timestamp - date(sp_fechaautoriza::TIMESTAMP + '110 hr'::INTERVAL))||')';
				         	indicadorcarpeta		:= 2;
			            end if;
			         
			         elsif (date_part('day',sp_fechasubecarpeta - (sp_fechaautoriza::TIMESTAMP + '110 hr'::INTERVAL)) <= 0) then
			         	diferenciasubecarpeta	:= to_char(sp_fechasubecarpeta, 'dd-mm-yyyy');
			         	indicadorcarpeta		:= 1;  

			         end if;
			        
			        
			         select coalesce (salav)
                       into sp_funcav 
                       from traking.calcularavancemecanizado(rec1.idordentrabajo);
     
					 avance        				:= sp_funcav;

					
					 if (sp_fechadespacho is null) then
					 
					    if ( date_part('day',rec1.fechafaceclte - date(now())::timestamp) <= 0 ) then
					    
					    	fechadespacho	:= to_char(rec1.fechafaceclte, 'dd-mm-yyyy')||'('|| date_part('day', date(now())::timestamp - rec1.fechafaceclte )||')';
					    
					    else
					    
					    	fechadespacho	:= to_char(rec1.fechafaceclte, 'dd-mm-yyyy');
					    
					    end if;
					 	
					 
					 elsif (rec1.idestadoorden = 9) then
					 
					    if (date_part('day',rec1.fechafaceclte - sp_fechadespacho) >= 0) then
					    
					    	fechadespacho	:= to_char(sp_fechadespacho, 'dd-mm-yyyy');
					    
					    else
					    
					        fechadespacho	:= to_char(sp_fechadespacho, 'dd-mm-yyyy')||'('|| date_part('day',sp_fechadespacho - rec1.fechafaceclte)||')';
					    
					    end if;					 	
					 
					 --else
					 
					 --   fechadespacho				:= to_char(sp_fechadespacho, 'dd-mm-yyyy');
					 
					 end if;
			         
					 if (rec1.iddebaja = 1) then
					    if (rec1.idestadoorden = 9) then
					    	fechadespacho				:= to_char(sp_fechadespacho, 'dd-mm-yyyy');					    
					    else					    
					    	fechadespacho				:= null;
					    end if;
					 
					 end if;			        
					
					raise notice '%', 'sp_fechadespacho'||sp_fechadespacho;
			         fechacontrolif				:= to_char(sp_fechadespacho::TIMESTAMP + '72 hr'::INTERVAL, 'yyyy-mm-dd hh24:mi:ss');  -- suma 72 horas desde despacho
			         fechasubeif				:= to_char(sp_fechasubeif, 'yyyy-mm-dd hh24:mi:ss');
			         --fechasubeif				:= sp_fechasubeif;
			         diferenciasubeif			:= coalesce(replace(sp_diferenciasubeif,'',''), '00 hrs:00 min');
			         indicadorsubeif			:= sp_indicadorsubeif;  -- 1: ok, 2: nok
			         estadoif					:= sp_estadoif;
			        

			         if (fechasubeif is null) then
			         
			         	if (date_part('day',date(now())::timestamp - (sp_fechadespacho::TIMESTAMP + '72 hr'::INTERVAL)) <= 0) then
			            	diferenciasubeif		:= to_char(sp_fechadespacho::TIMESTAMP + '72 hr'::INTERVAL, 'dd-mm-yyyy');
			                indicadorsubeif	:= 1;
			            else
				            diferenciasubeif	:= to_char(sp_fechadespacho::TIMESTAMP + '72 hr'::INTERVAL, 'dd-mm-yyyy')||'('|| date_part('day',date(now())::timestamp - (sp_fechadespacho::TIMESTAMP + '72 hr'::INTERVAL))||')';
				         	indicadorsubeif		:= 2;
			            end if;
			         
			         elsif (date_part('day',sp_fechasubeif - (sp_fechadespacho::TIMESTAMP + '72 hr'::INTERVAL)) <= 0) then
			         	diferenciasubeif	:= to_char(sp_fechasubeif, 'dd-mm-yyyy');
			         	indicadorsubeif		:= 1;  

			         end if;
			        
			        
			         desviacion					:= 0;
			         tienedesviacion			:= coalesce(sp_tienedesviacion, 0);
			         procesadodespachado		:= rec1.debaja;
	     		
					 -- Estado desarme
					select min(a.fechainicio),
					       max(a.fechatermino)
	                  into sp_inicio,
	                       sp_termino
					  from mct_movimientoordentrabajo a
					  left join mct_operador b on a.idoperador = b.idoperador
					 where a.idordentrabajo = rec1.idordentrabajo
					   and a.idaccion in (173)
                       and a.iniciaarmadodesarme is true;

					 sp_colorestado = 'btn-danger';
					 if (sp_inicio is not null and sp_termino is not null) then
					 	 sp_colorestado	:= 'btn-success';
					 elsif (sp_inicio is not null and sp_termino is null) then
						 sp_colorestado	:= 'btn-warning';
					 end if;

					 colorestadodesarme	:= sp_colorestado;

			        return next;
	     		
	     		end loop;
	     	
	end if;

   
   END;
$$;


ALTER FUNCTION traking.evtlistcontrolequipo_testsq_newconanno(idevaluators bigint, ots bigint, sdate character varying, edate character varying, annos bigint) OWNER TO postgres;

