--
-- TOC entry 2199 (class 1255 OID 16929)
-- Name: evtlistcontrolmaquina(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcontrolmaquina(idevaluators bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, idcontrolmaquina bigint, idcomponenteplanocontrolmaq bigint, descripcionplano character varying, codhojaruta character varying, idcomponente bigint, nombrecomponente character varying, nombreplano character varying, idusuario bigint, nombreusuario character varying, datoa numeric, datob numeric, datoc numeric, datod numeric, datoe numeric, datof numeric, datog numeric, datoh numeric, datoi numeric, datoj numeric, datok numeric, datol numeric, datom numeric, daton numeric, datoo numeric, datop numeric, datoq numeric, dator numeric, datos numeric, datot numeric, datou numeric, datov numeric, datow numeric, datox numeric, datoy numeric, datoz numeric, nombreequipo character varying, nombrematerial character varying, usuariocreacion character varying, fechacreacion character varying, usuariomodificacion character varying, fechamodificacion timestamp without time zone, idcierre bigint, imagen text)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;

BEGIN
-- iddefectoi = -1: Todos

    
	if ( idevaluators = -1 and startdate = 'NA' ) then

	     -- Todos
	      	 RETURN QUERY
	      		
			 SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
					 a.idcontrolmaquina ,
					 a.idcomponenteplanocontrolmaq ,
					 c.descripcionplano ,
					 a.codhojaruta,
					 a.idcomponente ,
					 i.nombrecomponente ,
					 cast(replace(a.nombreplano,' ', '') as varchar) as planocomponente,
					 a.idusuario ,
					 d.nombre as nombreusuario,
					 a.datoa ,
					 a.datob ,
					 a.datoc ,
					 a.datod ,
					 a.datoe ,
					 a.datof ,
					 a.datog ,
					 a.datoh ,
					 a.datoi ,
					 a.datoj ,
					 a.datok ,
					 a.datol ,
					 a.datom ,
					 a.daton ,
					 a.datoo ,
					 a.datop ,
					 a.datoq ,
					 a.dator ,
					 a.datos ,
					 a.datot ,
					 a.datou ,
					 a.datov ,
					 a.datow ,
					 a.datox ,
					 a.datoy ,
					 a.datoz ,
					 cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					 j.nombrematerial ,
					 a.usuariocreacion ,
					 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
					 a.usuariomodificacion,
					 a.fechamodificacion,
					 a.idcierre,
					 cast('' as text) 
			    FROM traking.mct_controlmaquina a
				left join  traking.mct_componente b                on a.idcomponente = b.idcomponente 
				left join  traking.mct_componenteplanocontrolmaq c on c.idcomponenteplanocontrolmaq = a.idcomponenteplanocontrolmaq 
				left join  traking.mct_usuario d   	               on d.idusuario = a.idusuario 
				left join  traking.mct_detallehojarutatemp g 	   on a.codhojaruta = g.codhojaruta 
				left join  traking.mct_hojarutatemp h 	           on g.idhojarutatemp = h.idhojarutatemp 
				left join  traking.mct_componente i 	           on h.idcomponente = i.idcomponente 
				left join  traking.mct_material j 		           on h.idmaterial = j.idmaterial 
				left join  traking.mct_ordentrabajo k 	           on h.idordentrabajo = k.idordentrabajo 
				left join  traking.mct_producto l 		           on k.idproducto = l.idproducto 
				left join  traking.mct_modelo m 		           on l.idmodelo = m.idmodelo 
				left join  traking.mct_subfamilia n 	           on m.idsubfamilia = n.idsubfamilia 
		        order by a.fechacreacion desc;

				
	elsif ( idevaluators = -1 and startdate != 'NA' ) then

	      	 RETURN QUERY
	      		
			 SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
					 a.idcontrolmaquina ,
					 a.idcomponenteplanocontrolmaq ,
					 c.descripcionplano ,
					 a.codhojaruta,
					 a.idcomponente ,
					 i.nombrecomponente ,
					 cast(replace(a.nombreplano,' ', '') as varchar) as planocomponente,
					 a.idusuario ,
					 d.nombre as nombreusuario,
					 a.datoa ,
					 a.datob ,
					 a.datoc ,
					 a.datod ,
					 a.datoe ,
					 a.datof ,
					 a.datog ,
					 a.datoh ,
					 a.datoi ,
					 a.datoj ,
					 a.datok ,
					 a.datol ,
					 a.datom ,
					 a.daton ,
					 a.datoo ,
					 a.datop ,
					 a.datoq ,
					 a.dator ,
					 a.datos ,
					 a.datot ,
					 a.datou ,
					 a.datov ,
					 a.datow ,
					 a.datox ,
					 a.datoy ,
					 a.datoz ,
					 cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					 j.nombrematerial ,
					 a.usuariocreacion ,
					 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
					 a.usuariomodificacion,
					 a.fechamodificacion,
					 a.idcierre,
					 cast('' as text) 
			    FROM traking.mct_controlmaquina a
				left join  traking.mct_componente b                on a.idcomponente = b.idcomponente 
				left join  traking.mct_componenteplanocontrolmaq c on c.idcomponenteplanocontrolmaq = a.idcomponenteplanocontrolmaq 
				left join  traking.mct_usuario d   	               on d.idusuario = a.idusuario 
				left join  traking.mct_detallehojarutatemp g 	   on a.codhojaruta = g.codhojaruta 
				left join  traking.mct_hojarutatemp h 	           on g.idhojarutatemp = h.idhojarutatemp 
				left join  traking.mct_componente i 	           on h.idcomponente = i.idcomponente 
				left join  traking.mct_material j 		           on h.idmaterial = j.idmaterial 
				left join  traking.mct_ordentrabajo k 	           on h.idordentrabajo = k.idordentrabajo 
				left join  traking.mct_producto l 		           on k.idproducto = l.idproducto 
				left join  traking.mct_modelo m 		           on l.idmodelo = m.idmodelo 
				left join  traking.mct_subfamilia n 	           on m.idsubfamilia = n.idsubfamilia 
			    WHERE
		 		   (a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
		            a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
                order by a.fechacreacion desc;
				 
	elsif ( idevaluators > 0 and startdate = 'NA' ) then

	      	 RETURN QUERY
	      		
			 SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
					 a.idcontrolmaquina ,
					 a.idcomponenteplanocontrolmaq ,
					 c.descripcionplano ,
					 a.codhojaruta,
					 a.idcomponente ,
					 i.nombrecomponente ,
					 cast(replace(a.nombreplano,' ', '') as varchar) as planocomponente,
					 a.idusuario ,
					 d.nombre as nombreusuario,
					 a.datoa ,
					 a.datob ,
					 a.datoc ,
					 a.datod ,
					 a.datoe ,
					 a.datof ,
					 a.datog ,
					 a.datoh ,
					 a.datoi ,
					 a.datoj ,
					 a.datok ,
					 a.datol ,
					 a.datom ,
					 a.daton ,
					 a.datoo ,
					 a.datop ,
					 a.datoq ,
					 a.dator ,
					 a.datos ,
					 a.datot ,
					 a.datou ,
					 a.datov ,
					 a.datow ,
					 a.datox ,
					 a.datoy ,
					 a.datoz ,
					 cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					 j.nombrematerial ,
					 a.usuariocreacion ,
					 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
					 a.usuariomodificacion,
					 a.fechamodificacion,
					 a.idcierre,
					 cast('' as text) 
			    FROM traking.mct_controlmaquina a
				left join  traking.mct_componente b                on a.idcomponente = b.idcomponente 
				left join  traking.mct_componenteplanocontrolmaq c on c.idcomponenteplanocontrolmaq = a.idcomponenteplanocontrolmaq 
				left join  traking.mct_usuario d   	               on d.idusuario = a.idusuario 
				left join  traking.mct_detallehojarutatemp g 	   on a.codhojaruta = g.codhojaruta 
				left join  traking.mct_hojarutatemp h 	           on g.idhojarutatemp = h.idhojarutatemp 
				left join  traking.mct_componente i 	           on h.idcomponente = i.idcomponente 
				left join  traking.mct_material j 		           on h.idmaterial = j.idmaterial 
				left join  traking.mct_ordentrabajo k 	           on h.idordentrabajo = k.idordentrabajo 
				left join  traking.mct_producto l 		           on k.idproducto = l.idproducto 
				left join  traking.mct_modelo m 		           on l.idmodelo = m.idmodelo 
				left join  traking.mct_subfamilia n 	           on m.idsubfamilia = n.idsubfamilia 
			    where a.idusuario = idevaluators
                order by a.fechacreacion desc;
				 
	elsif ( idevaluators > 0 and startdate != 'NA' ) then	

	      	 RETURN QUERY
	      		
			 SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
					 a.idcontrolmaquina ,
					 a.idcomponenteplanocontrolmaq ,
					 c.descripcionplano ,
					 a.codhojaruta,
					 a.idcomponente ,
					 i.nombrecomponente ,
					 cast(replace(a.nombreplano,' ', '') as varchar) as planocomponente,
					 a.idusuario ,
					 d.nombre as nombreusuario,
					 a.datoa ,
					 a.datob ,
					 a.datoc ,
					 a.datod ,
					 a.datoe ,
					 a.datof ,
					 a.datog ,
					 a.datoh ,
					 a.datoi ,
					 a.datoj ,
					 a.datok ,
					 a.datol ,
					 a.datom ,
					 a.daton ,
					 a.datoo ,
					 a.datop ,
					 a.datoq ,
					 a.dator ,
					 a.datos ,
					 a.datot ,
					 a.datou ,
					 a.datov ,
					 a.datow ,
					 a.datox ,
					 a.datoy ,
					 a.datoz ,
					 cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
					 j.nombrematerial ,
					 a.usuariocreacion ,
					 cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
					 a.usuariomodificacion,
					 a.fechamodificacion,
					 a.idcierre,
					 cast('' as text) 
			    FROM traking.mct_controlmaquina a
				left join  traking.mct_componente b                on a.idcomponente = b.idcomponente 
				left join  traking.mct_componenteplanocontrolmaq c on c.idcomponenteplanocontrolmaq = a.idcomponenteplanocontrolmaq 
				left join  traking.mct_usuario d   	               on d.idusuario = a.idusuario 
				left join  traking.mct_detallehojarutatemp g 	   on a.codhojaruta = g.codhojaruta 
				left join  traking.mct_hojarutatemp h 	           on g.idhojarutatemp = h.idhojarutatemp 
				left join  traking.mct_componente i 	           on h.idcomponente = i.idcomponente 
				left join  traking.mct_material j 		           on h.idmaterial = j.idmaterial 
				left join  traking.mct_ordentrabajo k 	           on h.idordentrabajo = k.idordentrabajo 
				left join  traking.mct_producto l 		           on k.idproducto = l.idproducto 
				left join  traking.mct_modelo m 		           on l.idmodelo = m.idmodelo 
				left join  traking.mct_subfamilia n 	           on m.idsubfamilia = n.idsubfamilia 
			    WHERE
		 		   (a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
		            a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) and
				 	a.idusuario = idevaluators
                order by a.fechacreacion desc;
				 
    end if;
		 
END;
$$;


