--
-- TOC entry 1693 (class 1255 OID 16933)
-- Name: evtlistcontrolotfundicion(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcontrolotfundicion(idworkorders bigint) RETURNS TABLE(item bigint, idordentrabajo bigint, idordentrabajoparte bigint, idcomponente bigint, nombreparte character varying, idhojaruta bigint, idhojarutatemp bigint, codhojaruta character varying, nombreplano character varying, idcriterioevaluacion bigint, modelo bigint, moldeo bigint, armado bigint, horno1 bigint, horno2 bigint, horno3 bigint, horno4 bigint, horno5 bigint, horno6 bigint, horno7 bigint, tratamiento bigint, rpl bigint, kpi bigint)
    LANGUAGE plpgsql
    AS $$
declare	 


		rec1 			record;
		rec2			record;

	    
	    sp_modelo		bigint;
        sp_moldeo 		bigint;
        sp_armado 		bigint;
        sp_horno1 		bigint;
        sp_horno2 		bigint;
        sp_horno3 		bigint;
        sp_horno4 		bigint;
        sp_horno5 		bigint;
        sp_horno6 		bigint;
        sp_horno7 		bigint;
        sp_tratamiento	bigint;
        sp_haytt		bigint;
        sp_hayttabierto	bigint;
        sp_hayttcerrado	bigint;
        sp_rpl			bigint;
        sp_kpi			bigint;
        sp_fechatermino	timestamp;
	   
BEGIN
       
	   	   FOR rec1 IN (   		

					select row_number() over (order by e.nombreplano nulls last) as item,
					       a.idordentrabajo            as idordentrabajo,
					       a.idordentrabajoparte       as idordentrabajoparte,
					       a.idcomponente              as idcomponente ,
					       coalesce ( upper( coalesce(e.componentechecklist, b.nombrecomponente) )||' - '||e.textoadicional , b.nombrecomponente) as nombreparte,
					       c.idhojaruta                as idhojaruta,
					       e.idhojarutatemp,
					       c.codhojaruta               as codhojaruta,
					       e.nombreplano,
					       e.idcriterioevaluacion,
					       e.idchecklistinftecvalido,
					       cast(date_part('day', (h.fechafaceclte - interval '15 days')  - current_date ) as bigint) as diasfund,
					       cast(to_char(h.fechafaceclte - interval '15 days' ,'dd-mm-yyyy') as varchar) as fechaentmec,
					       h.fechafaceclte - interval '15 days' as fechaentregamec
					  from mct_ordentrabajoparte a
					  inner join mct_componente b             on a.idcomponente = b.idcomponente 
					  inner join mct_hojaruta c               on a.idordentrabajoparte = c.idordentrabajoparte       
					   left join mct_detallehojarutatemp f    on c.codhojaruta = f.codhojaruta 
					   left join mct_hojarutatemp e           on e.idhojarutatemp  = f.idhojarutatemp  
					   left join mct_areaclasificacion g      on e.idareaclasificacion = g.idareaclasificacion 
					   left join mct_ordentrabajo h           on a.idordentrabajo = h.idordentrabajo
					 where a.idordentrabajo = idworkorders
					   and e.idcriterioevaluacion in (2,13)
					   order by e.nombreplano asc

					)
		   loop 				 
		

			  sp_modelo			:= 0;
			  sp_moldeo 		:= 0;
			  sp_armado 		:= 0;
			  sp_horno1 		:= 0;
			  sp_horno2 		:= 0;
			  sp_horno3 		:= 0;
			  sp_horno4 		:= 0;
			  sp_horno5 		:= 0;
			  sp_horno6 		:= 0;
			  sp_horno7 		:= 0;
			  sp_tratamiento	:= 0;
		      sp_haytt			:= 0;
		      sp_hayttabierto	:= 0;
        	  sp_hayttcerrado	:= 0;
        	  sp_rpl			:= 0;
			  sp_kpi			:= 0;
			  sp_fechatermino	:= null;
		     
		      -- Moldeo
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_modelo
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 56
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 56);

		      -- Modelo
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_moldeo     
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 66
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 66);
											         
		      -- Armado
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_armado     
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 53
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 53);

			  -- Horno1
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno1
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 1
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 1);
									

			  -- Horno2
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno2
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 2
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 2);
											         
			  -- Horno3
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno3
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 3
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 3);											         
											         
			  -- Horno4
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno4
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 4
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 4);	
											         
			  -- Horno5
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno5
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 5
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 5);
											         
			  -- Horno6
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno6
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 6
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 6);
											         
			  -- Horno7
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno7
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 7
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 7);											         
											         
											         
			  -- Tratamiento termico
		      select count(*) 
		        into sp_haytt
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7;

		      select count(*) 
		        into sp_hayttabierto
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 1;

		      select count(*) 
		        into sp_hayttcerrado
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 2;
		        
		      if (sp_haytt = 0) then
		      	
		      	sp_tratamiento	:= -1;
		      
		      elsif (sp_hayttabierto > 0) then
		      
		      	sp_tratamiento	:= 0;
		      
		      elsif (sp_hayttcerrado > 0) then
		      
		      	sp_tratamiento	:= 1;
		      
		      end if;
											         
			  -- RPL
		      select count(*),
		             max(a.fechatermino) 
		        into sp_rpl,
		             sp_fechatermino
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.codigoaccion = 'R_PL';
		        
		     if (sp_fechatermino is not null) then
		     	
		     	 if (date_part('day', sp_fechatermino - rec1.fechaentregamec) > 0) then
		     	 
		     	 	sp_kpi	:= 0; -- En tiempo
		     	 
		     	 else
		     	 
		     	 	sp_kpi	:= 1; -- Atrasada
		     	 
		     	 end if;
		     	
		     else
		     
		     	sp_kpi	:= 0; -- En tiempo
		     
		     end if;
		        
	         item 					:= rec1.item;
	         idordentrabajo 		:= rec1.idordentrabajo; 
	         idordentrabajoparte 	:= rec1.idordentrabajoparte;
	         idcomponente 			:= rec1.idcomponente;
	         nombreparte 			:= rec1.nombreparte;
	         idhojaruta 			:= rec1.idhojaruta;
	         idhojarutatemp 		:= rec1.idhojarutatemp;
	         codhojaruta 			:= rec1.codhojaruta;   
	         nombreplano 			:= rec1.nombreplano; 
	         idcriterioevaluacion 	:= rec1.idcriterioevaluacion;
	         modelo 				:= coalesce(sp_modelo,-1); 
	         moldeo 				:= coalesce(sp_moldeo,-1);
	         armado 				:= coalesce(sp_armado,-1);
	         horno1 				:= coalesce(sp_horno1,-1);
	         horno2 				:= coalesce(sp_horno2,-1);
	         horno3 				:= coalesce(sp_horno3,-1);
	         horno4 				:= coalesce(sp_horno4,-1);
	         horno5 				:= coalesce(sp_horno5,-1);
	         horno6 				:= coalesce(sp_horno6,-1);
	         horno7 				:= coalesce(sp_horno7,-1);
	         tratamiento 			:= sp_tratamiento;
	         rpl 					:= sp_rpl;
	         kpi					:= sp_kpi;			 
		     
		     RETURN NEXT;			    
		     
		END LOOP;		 		 
	
END;
$$;


ALTER FUNCTION traking.evtlistcontrolotfundicion(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1712 (class 1255 OID 16935)
-- Name: evtlistcontrolotfundiciongeneral(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcontrolotfundiciongeneral(idfamilias bigint, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, idordentrabajoparte bigint, idcomponente bigint, nombreparte character varying, idhojaruta bigint, idhojarutatemp bigint, codhojaruta character varying, nombreplano character varying, idcriterioevaluacion bigint, modelo bigint, moldeo bigint, armado bigint, horno1 bigint, horno2 bigint, horno3 bigint, horno4 bigint, horno5 bigint, horno6 bigint, horno7 bigint, tratamiento bigint, rpl bigint, kpi bigint, diasentrega bigint)
    LANGUAGE plpgsql
    AS $$
declare	 


		rec1 			record;
		rec2			record;

	    
	    sp_modelo		bigint;
        sp_moldeo 		bigint;
        sp_armado 		bigint;
        sp_horno1 		bigint;
        sp_horno2 		bigint;
        sp_horno3 		bigint;
        sp_horno4 		bigint;
        sp_horno5 		bigint;
        sp_horno6 		bigint;
        sp_horno7 		bigint;
        sp_tratamiento	bigint;
        sp_haytt		bigint;
        sp_hayttabierto	bigint;
        sp_hayttcerrado	bigint;
        sp_rpl			bigint;
        sp_kpi			bigint;
        sp_fechatermino	timestamp;
	   
BEGIN
       
	if (desde != 'NA' and hasta != 'NA') then

	   	   FOR rec1 IN (   		

--					select row_number() over (order by e.nombreplano nulls last) as item,
--					       a.idordentrabajo            as idordentrabajo,
--					       a.idordentrabajoparte       as idordentrabajoparte,
--					       a.idcomponente              as idcomponente ,
--					       coalesce ( upper( coalesce(e.componentechecklist, b.nombrecomponente) )||' - '||e.textoadicional , b.nombrecomponente) as nombreparte,
--					       c.idhojaruta                as idhojaruta,
--					       e.idhojarutatemp,
--					       c.codhojaruta               as codhojaruta,
--					       e.nombreplano,
--					       e.idcriterioevaluacion,
--					       e.idchecklistinftecvalido,
--					       cast(date_part('day', (h.fechafaceclte - interval '15 days')  - current_date ) as bigint) as diasfund,
--					       cast(to_char(h.fechafaceclte - interval '15 days' ,'dd-mm-yyyy') as varchar) as fechaentmec,
--					       h.fechafaceclte - interval '15 days' as fechaentregamec
--					  from mct_ordentrabajoparte a
--					  inner join mct_componente b             on a.idcomponente = b.idcomponente 
--					  inner join mct_hojaruta c               on a.idordentrabajoparte = c.idordentrabajoparte       
--					   left join mct_detallehojarutatemp f    on c.codhojaruta = f.codhojaruta 
