--					 where a.idordentrabajo >= 30000
--				       and h.idestadoorden  >= 6 and h.idestadoorden < 9
--				       and h.flagfacturacion is true
--				       and h.debaja < 1
--					   and h.checklistvalido = true
--					   and e.idcriterioevaluacion in (2,13)
--					   and case 
--		                   WHEN 8 = 10 THEN 
--		                        h.idfamilia in (10) --and a.idlineadiseno in (1,2,4)
--		                   WHEN 8 = 102 THEN  
