--		                   end
--				  	   --and (h.fechafaceclte - interval '15 days' >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and h.fechafaceclte - interval '15 days' <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))		   
--					 order by h.fechafaceclte - interval '15 days' asc,
--					          h.idordentrabajo
					          
			    select ROW_NUMBER() OVER (ORDER BY (a.fechafaceclte - interval '15 days') asc, a.idordentrabajo) AS item,
					   a.idordentrabajo ,
					   k.idcomponente,
					   k.nombreparte ,			   
					   k.plano as nombreplano,
					   cast(date_part('day', (a.fechafaceclte - interval '15 days')  - current_date ) as bigint) as diasfund,
					   (a.fechafaceclte - interval '15 days') as fechaentregamec,
					   n.codhojaruta,
					   m.idhojarutatemp,
					   m.idcriterioevaluacion,
					   m.idchecklistinftecvalido
					   --k.cantidad as total
					   --cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
					   --cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes
				  from mct_ordentrabajo a
				  left join  mct_producto c        		 on a.idproducto = c.idproducto 
				  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
				  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
				  left join  mct_checklistinftecvalido k on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL') 
				  left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr
				  left join  mct_hojarutatemp m  on m.idchecklistinftecvalido = k.idchecklistinftecvalido
				  left join  mct_detallehojarutatemp n on n.idhojarutatemp = m.idhojarutatemp
				  where a.idordentrabajo >= 30000
			       and a.idestadoorden  >= 5 and a.idestadoorden < 9
				   and case 
		                   WHEN idfamilias = 10 THEN 
		                        a.idfamilia in (10) and a.idlineadiseno in (1,2,4)
		                   WHEN idfamilias = 102 THEN  
		                        a.idfamilia in (10) and a.idlineadiseno in (3) 
		                   ELSE 
		                        a.idfamilia = idfamilias
		              end
