		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 53
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 53);

			  -- Horno1
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno1
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 1
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 1);
									

			  -- Horno2
