			  -- Tratamiento termico
		      select count(*) 
		        into sp_haytt
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7;

		      select count(*) 
		        into sp_hayttabierto
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 1;

		      select count(*) 
		        into sp_hayttcerrado
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 2;
		        
		      if (sp_haytt = 0) then
		      	
		      	sp_tratamiento	:= -1;
		      
		      elsif (sp_hayttabierto > 0) then
		      
		      	sp_tratamiento	:= 0;
		      
		      elsif (sp_hayttcerrado > 0) then
		      
		      	sp_tratamiento	:= 1;
		      
		      end if;
											         
			  -- RPL
		      select count(*),
		             max(a.fechatermino) 
		        into sp_rpl,
		             sp_fechatermino
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.codigoaccion = 'R_PL';
		        
		     if (sp_fechatermino is not null) then
		     	
		     	 if (date_part('day', sp_fechatermino - rec1.fechaentregamec) > 0) then
		     	 
		     	 	sp_kpi	:= 0; -- En tiempo
		     	 
		     	 else
		     	 
		     	 	sp_kpi	:= 1; -- Atrasada
		     	 
		     	 end if;
		     	
		     else
		     
		     	sp_kpi	:= 0; -- En tiempo
		     
		     end if;
		        
	         item 					:= rec1.item;
	         idordentrabajo 		:= rec1.idordentrabajo; 
	         idordentrabajoparte 	:= 0;
	         idcomponente 			:= 0;
	         nombreparte 			:= rec1.nombreparte;
	         idhojaruta 			:= 0;
	         idhojarutatemp 		:= rec1.idhojarutatemp;
	         codhojaruta 			:= rec1.codhojaruta;   
	         nombreplano 			:= rec1.plano; 
	         idcriterioevaluacion 	:= rec1.idcriterioevaluacion;
	         modelo 				:= coalesce(sp_modelo,-1); 
	         moldeo 				:= coalesce(sp_moldeo,-1);
	         armado 				:= coalesce(sp_armado,-1);
	         horno1 				:= coalesce(sp_horno1,-1);
	         horno2 				:= coalesce(sp_horno2,-1);
	         horno3 				:= coalesce(sp_horno3,-1);
	         horno4 				:= coalesce(sp_horno4,-1);
	         horno5 				:= coalesce(sp_horno5,-1);
	         horno6 				:= coalesce(sp_horno6,-1);
	         horno7 				:= coalesce(sp_horno7,-1);
	         tratamiento 			:= sp_tratamiento;
