					       cast(to_char(a.fechafaceclte - interval '10 days' ,'dd-mm-yyyy') as varchar) as fechaentmec,
					       (a.fechafaceclte - interval '10 days') as fechaentregamec,
					       cast(case 
								  when a.idproducto in (10,11,12,13,14,15,16,17) then 
								       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
								  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
								       cc.nombreproducto
								  else hh.sigla||' '||gg.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   k.cantidad as total,
						   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
			               cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes
					  from mct_ordentrabajo a
					   left join mct_ordentrabajoparte h      on a.idordentrabajo = h.idordentrabajo
					   left join mct_hojaruta c               on h.idordentrabajoparte = c.idordentrabajoparte 					   
					   left join mct_detallehojarutatemp f    on c.codhojaruta = f.codhojaruta 
					   left join mct_hojarutatemp e           on e.idhojarutatemp  = f.idhojarutatemp  
					   left join mct_areaclasificacion g      on e.idareaclasificacion = g.idareaclasificacion 
					   left join mct_producto cc              on a.idproducto = cc.idproducto
					   left join mct_checklistinftec k        on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
					   left join mct_checklistinftecrecept l  on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')
					   left join mct_modelo gg       on cc.idmodelo = gg.idmodelo 
