											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 53);

			  -- Horno1
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno1
