			    into sp_horno4
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 4
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 4);	
											         
			  -- Horno5
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno5
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 5
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 5);
											         
			  -- Horno6
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno6
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 6
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 6);
											         
			  -- Horno7
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno7
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 7
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 7);											         
											         
											         
			  -- Tratamiento termico
		      select count(*) 
		        into sp_haytt
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7;

		      select count(*) 
		        into sp_hayttabierto
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 1;

		      select count(*) 
		        into sp_hayttcerrado
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 2;
		        
		      if (sp_haytt = 0) then
		      	
		      	sp_tratamiento	:= -1;
		      
		      elsif (sp_hayttabierto > 0) then
		      
		      	sp_tratamiento	:= 0;
		      
		      elsif (sp_hayttcerrado > 0) then
		      
		      	sp_tratamiento	:= 1;
		      
		      end if;
											         
			  -- RPL
		      select count(*),
		             max(a.fechatermino) 
		        into sp_rpl,
		             sp_fechatermino
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.codigoaccion = 'R_PL';
		        
		     if (sp_fechatermino is not null) then
		     	
		     	 if (date_part('day', sp_fechatermino - rec1.fechaentregamec) > 0) then
		     	 
		     	 	sp_kpi	:= 0; -- En tiempo
		     	 
		     	 else
		     	 
		     	 	sp_kpi	:= 1; -- Atrasada
		     	 
		     	 end if;
		     	
		     else
		     
		     	sp_kpi	:= 0; -- En tiempo
		     
		     end if;
		        
	         item 					:= rec1.item;
	         idordentrabajo 		:= rec1.idordentrabajo; 
	         idordentrabajoparte 	:= 0;
	         idcomponente 			:= 0;
	         nombreparte 			:= rec1.nombreparte;
	         idhojaruta 			:= 0;
	         idhojarutatemp 		:= rec1.idhojarutatemp;
	         codhojaruta 			:= rec1.codhojaruta;   
	         nombreplano 			:= rec1.plano; 
	         idcriterioevaluacion 	:= rec1.idcriterioevaluacion;
	         modelo 				:= coalesce(sp_modelo,-1); 
	         moldeo 				:= coalesce(sp_moldeo,-1);
	         armado 				:= coalesce(sp_armado,-1);
	         horno1 				:= coalesce(sp_horno1,-1);
	         horno2 				:= coalesce(sp_horno2,-1);
	         horno3 				:= coalesce(sp_horno3,-1);
	         horno4 				:= coalesce(sp_horno4,-1);
	         horno5 				:= coalesce(sp_horno5,-1);
	         horno6 				:= coalesce(sp_horno6,-1);
	         horno7 				:= coalesce(sp_horno7,-1);
	         tratamiento 			:= sp_tratamiento;
	         rpl 					:= sp_rpl;
	         kpi					:= sp_kpi;	
	         diasentrega			:= rec1.diasfund;
		     
		     RETURN NEXT;			    
		     
		END LOOP;	

	end if;
	 		 
	
END;
$$;


ALTER FUNCTION traking.evtlistcontrolotfundiciongeneraldesgastecr(idfamilias bigint, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1426 (class 1255 OID 16941)
-- Name: evtlistcontrolotfundiciongeneraldesgastesr(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcontrolotfundiciongeneraldesgastesr(idfamilias bigint, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, idordentrabajoparte bigint, idcomponente bigint, nombreparte character varying, idhojaruta bigint, idhojarutatemp bigint, codhojaruta character varying, nombreplano character varying, idcriterioevaluacion bigint, modelo bigint, moldeo bigint, armado bigint, horno1 bigint, horno2 bigint, horno3 bigint, horno4 bigint, horno5 bigint, horno6 bigint, horno7 bigint, tratamiento bigint, rpl bigint, kpi bigint, diasentrega bigint)
    LANGUAGE plpgsql
    AS $$
declare	 


		rec1 			record;
		rec2			record;

	    
	    sp_modelo		bigint;
        sp_moldeo 		bigint;
        sp_armado 		bigint;
        sp_horno1 		bigint;
        sp_horno2 		bigint;
        sp_horno3 		bigint;
        sp_horno4 		bigint;
        sp_horno5 		bigint;
        sp_horno6 		bigint;
        sp_horno7 		bigint;
        sp_tratamiento	bigint;
        sp_haytt		bigint;
        sp_hayttabierto	bigint;
        sp_hayttcerrado	bigint;
        sp_rpl			bigint;
        sp_kpi			bigint;
        sp_fechatermino	timestamp;
	   
    	sp_fami			integer;
    	sp_mec			integer;
   
BEGIN
       
	if ( idfamilias = 1110 or idfamilias = 1111) then
	   sp_fami = 11;
	   sp_mec = 1;
	end if;

	if (desde != 'NA' and hasta != 'NA') then

	   	   FOR rec1 IN (   		
					      
				select row_number() over (order by a.fechafundicion2 asc, a.idordentrabajo) as item,
					       a.idordentrabajo            as idordentrabajo,
					       --a.idordentrabajoparte       as idordentrabajoparte,
					       k.nombreparte,
					       --c.idhojaruta                as idhojaruta,
					       e.idhojarutatemp,
					       c.codhojaruta               as codhojaruta,
					       k.plano,
					       e.idcriterioevaluacion,
					       e.idchecklistinftecvalido,
					       cast(date_part('day', (a.fechafaceclte - interval '10 days')  - current_date ) as bigint) as diasfund,
					       cast(to_char(a.fechafaceclte - interval '10 days' ,'dd-mm-yyyy') as varchar) as fechaentmec,
					       (a.fechafaceclte - interval '10 days') as fechaentregamec,
					       cast(case 
								  when a.idproducto in (10,11,12,13,14,15,16,17) then 
								       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
								  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
								       cc.nombreproducto
								  else hh.sigla||' '||gg.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   k.cantidad as total,
						   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
			               cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes
					  from mct_ordentrabajo a
					   left join mct_ordentrabajoparte h      on a.idordentrabajo = h.idordentrabajo
					   left join mct_hojaruta c               on h.idordentrabajoparte = c.idordentrabajoparte 					   
					   left join mct_detallehojarutatemp f    on c.codhojaruta = f.codhojaruta 
					   left join mct_hojarutatemp e           on e.idhojarutatemp  = f.idhojarutatemp  
					   left join mct_areaclasificacion g      on e.idareaclasificacion = g.idareaclasificacion 
					   left join mct_producto cc              on a.idproducto = cc.idproducto
					   left join mct_checklistinftec k        on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
					   left join mct_checklistinftecrecept l  on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')
					   left join mct_modelo gg       on cc.idmodelo = gg.idmodelo 
		               left join mct_subfamilia hh   on gg.idsubfamilia = hh.idsubfamilia 
		               left join mct_etapaparam i    on cc.idetapaparam = i.idetapaparam
					  where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
				       and a.idfamilia = 11
				       and a.flagfacturacion is true
				       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = sp_mec)
				       and a.debaja < 1
					   --and h.checklistvalido = true
					   --and e.idcriterioevaluacion in (2,13)		
					   and (a.fechafaceclte - interval '10 days' >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte - interval '10 days' <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))		   					 			   
                       and not exists (select 'x' from mct_ordentrabajorepuesto  aa, mct_clasificafundicion b
												where a.idordentrabajo = aa.idordentrabajo 
												  and aa.nombreplano = b.plano 
												  and b.recocido = true )
			  group by a.idordentrabajo,
					   k.nombreparte,
					   e.idhojarutatemp,
					   c.codhojaruta,
					   k.plano,
					   e.idcriterioevaluacion,
					   e.idchecklistinftecvalido,
					   cast(date_part('day', (a.fechafaceclte - interval '10 days')  - current_date ) as bigint),
					   cast(to_char(a.fechafaceclte - interval '10 days' ,'dd-mm-yyyy') as varchar),
					   (a.fechafaceclte),
					   cast(case 
							  when a.idproducto in (10,11,12,13,14,15,16,17) then 
							       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
							  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
							       cc.nombreproducto
							  else hh.sigla||' '||gg.nombremodelo||' '||i.nombreparam
					   end as varchar),
					   k.cantidad,
					   a.fechafundicion2
			    having k.cantidad > coalesce(sum(l.cantidad),0)		 			  
			     order by a.fechafundicion2 asc,
					      a.idordentrabajo					      

					)
		   loop 				 
		

			  sp_modelo			:= 0;
			  sp_moldeo 		:= 0;
			  sp_armado 		:= 0;
			  sp_horno1 		:= 0;
			  sp_horno2 		:= 0;
			  sp_horno3 		:= 0;
			  sp_horno4 		:= 0;
			  sp_horno5 		:= 0;
			  sp_horno6 		:= 0;
			  sp_horno7 		:= 0;
			  sp_tratamiento	:= 0;
		      sp_haytt			:= 0;
		      sp_hayttabierto	:= 0;
        	  sp_hayttcerrado	:= 0;
        	  sp_rpl			:= 0;
			  sp_kpi			:= 0;
			  sp_fechatermino	:= null;
		     
		      -- Moldeo
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_modelo
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 56
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 56);

		      -- Modelo
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_moldeo     
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 66
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 66);
											         
		      -- Armado
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_armado     
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 53
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 53);

			  -- Horno1
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno1
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 1
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 1);
									

			  -- Horno2
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno2
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 2
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 2);
											         
			  -- Horno3
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno3
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 3
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 3);											         
											         
			  -- Horno4
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno4
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 4
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 4);	
											         
			  -- Horno5
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno5
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 5
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 5);
											         
			  -- Horno6
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno6
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 6
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 6);
											         
			  -- Horno7
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno7
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 7
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 7);											         
											         
											         
			  -- Tratamiento termico
		      select count(*) 
		        into sp_haytt
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7;

		      select count(*) 
		        into sp_hayttabierto
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 1;

		      select count(*) 
		        into sp_hayttcerrado
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 2;
		        
		      if (sp_haytt = 0) then
		      	
		      	sp_tratamiento	:= -1;
		      
		      elsif (sp_hayttabierto > 0) then
		      
		      	sp_tratamiento	:= 0;
		      
		      elsif (sp_hayttcerrado > 0) then
		      
		      	sp_tratamiento	:= 1;
		      
		      end if;
											         
			  -- RPL
		      select count(*),
		             max(a.fechatermino) 
		        into sp_rpl,
		             sp_fechatermino
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.codigoaccion = 'R_PL';
		        
		     if (sp_fechatermino is not null) then
		     	
		     	 if (date_part('day', sp_fechatermino - rec1.fechaentregamec) > 0) then
		     	 
		     	 	sp_kpi	:= 0; -- En tiempo
		     	 
		     	 else
		     	 
		     	 	sp_kpi	:= 1; -- Atrasada
		     	 
		     	 end if;
		     	
		     else
		     
		     	sp_kpi	:= 0; -- En tiempo
		     
		     end if;
		        
	         item 					:= rec1.item;
	         idordentrabajo 		:= rec1.idordentrabajo; 
	         idordentrabajoparte 	:= 0;
	         idcomponente 			:= 0;
	         nombreparte 			:= rec1.nombreparte;
	         idhojaruta 			:= 0;
	         idhojarutatemp 		:= rec1.idhojarutatemp;
	         codhojaruta 			:= rec1.codhojaruta;   
	         nombreplano 			:= rec1.plano; 
	         idcriterioevaluacion 	:= rec1.idcriterioevaluacion;
	         modelo 				:= coalesce(sp_modelo,-1); 
	         moldeo 				:= coalesce(sp_moldeo,-1);
	         armado 				:= coalesce(sp_armado,-1);
	         horno1 				:= coalesce(sp_horno1,-1);
	         horno2 				:= coalesce(sp_horno2,-1);
	         horno3 				:= coalesce(sp_horno3,-1);
	         horno4 				:= coalesce(sp_horno4,-1);
	         horno5 				:= coalesce(sp_horno5,-1);
	         horno6 				:= coalesce(sp_horno6,-1);
	         horno7 				:= coalesce(sp_horno7,-1);
	         tratamiento 			:= sp_tratamiento;
	         rpl 					:= sp_rpl;
	         kpi					:= sp_kpi;	
	         diasentrega			:= rec1.diasfund;
		     
		     RETURN NEXT;			    
		     
		END LOOP;	

	else

	   	   FOR rec1 IN (   		

				select row_number() over (order by a.fechafundicion2 asc, a.idordentrabajo) as item,
					       a.idordentrabajo            as idordentrabajo,
					       --a.idordentrabajoparte       as idordentrabajoparte,
					       k.nombreparte,
					       --c.idhojaruta                as idhojaruta,
					       e.idhojarutatemp,
					       c.codhojaruta               as codhojaruta,
					       k.plano,
					       e.idcriterioevaluacion,
					       e.idchecklistinftecvalido,
					       cast(date_part('day', (a.fechafaceclte - interval '10 days')  - current_date ) as bigint) as diasfund,
					       cast(to_char(a.fechafaceclte - interval '10 days' ,'dd-mm-yyyy') as varchar) as fechaentmec,
					       (a.fechafaceclte - interval '10 days') as fechaentregamec,
					       cast(case 
								  when a.idproducto in (10,11,12,13,14,15,16,17) then 
								       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
								  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
								       cc.nombreproducto
								  else hh.sigla||' '||gg.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   k.cantidad as total,
						   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
			               cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes
					  from mct_ordentrabajo a
					   left join mct_ordentrabajoparte h      on a.idordentrabajo = h.idordentrabajo
					   left join mct_hojaruta c               on h.idordentrabajoparte = c.idordentrabajoparte 					   
					   left join mct_detallehojarutatemp f    on c.codhojaruta = f.codhojaruta 
					   left join mct_hojarutatemp e           on e.idhojarutatemp  = f.idhojarutatemp  
					   left join mct_areaclasificacion g      on e.idareaclasificacion = g.idareaclasificacion 
					   left join mct_producto cc              on a.idproducto = cc.idproducto
					   left join mct_checklistinftec k        on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
					   left join mct_checklistinftecrecept l  on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')
					   left join mct_modelo gg       on cc.idmodelo = gg.idmodelo 
		               left join mct_subfamilia hh   on gg.idsubfamilia = hh.idsubfamilia 
		               left join mct_etapaparam i    on cc.idetapaparam = i.idetapaparam
					  where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
				       and a.idfamilia = 11
				       and a.flagfacturacion is true
				       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = sp_mec)
				       and a.debaja < 1
					   --and h.checklistvalido = true
					   --and e.idcriterioevaluacion in (2,13)	
					   and not exists (select 'x' from mct_ordentrabajorepuesto  aa, mct_clasificafundicion b
												where a.idordentrabajo = aa.idordentrabajo 
												  and aa.nombreplano = b.plano 
												  and b.recocido = true )				   
			  group by a.idordentrabajo,
					   k.nombreparte,
					   e.idhojarutatemp,
					   c.codhojaruta,
					   k.plano,
					   e.idcriterioevaluacion,
					   e.idchecklistinftecvalido,
					   cast(date_part('day', (a.fechafaceclte - interval '10 days')  - current_date ) as bigint),
					   cast(to_char(a.fechafaceclte - interval '10 days' ,'dd-mm-yyyy') as varchar),
					   (a.fechafaceclte),
					   cast(case 
							  when a.idproducto in (10,11,12,13,14,15,16,17) then 
							       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
							  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
							       cc.nombreproducto
							  else hh.sigla||' '||gg.nombremodelo||' '||i.nombreparam
					   end as varchar),
					   k.cantidad,
					   a.fechafundicion2
			    having k.cantidad > coalesce(sum(l.cantidad),0)		 			  
			     order by a.fechafundicion2 asc,
					      a.idordentrabajo

					)
		   loop 				 
		

			  sp_modelo			:= 0;
			  sp_moldeo 		:= 0;
			  sp_armado 		:= 0;
			  sp_horno1 		:= 0;
			  sp_horno2 		:= 0;
			  sp_horno3 		:= 0;
			  sp_horno4 		:= 0;
			  sp_horno5 		:= 0;
			  sp_horno6 		:= 0;
			  sp_horno7 		:= 0;
			  sp_tratamiento	:= 0;
		      sp_haytt			:= 0;
		      sp_hayttabierto	:= 0;
        	  sp_hayttcerrado	:= 0;
        	  sp_rpl			:= 0;
			  sp_kpi			:= 0;
			  sp_fechatermino	:= null;
		     
		      -- Moldeo
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_modelo
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 56
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 56);

		      -- Modelo
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_moldeo     
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 66
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 66);
											         
		      -- Armado
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            else
			                 1--'CERRADO'
			         end as estado
			    into sp_armado     
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 53
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 53);

			  -- Horno1
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno1
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 1
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 1);
									

			  -- Horno2
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno2
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 2
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 2);
											         
			  -- Horno3
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno3
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 3
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 3);											         
											         
			  -- Horno4
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno4
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 4
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 4);	
											         
			  -- Horno5
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno5
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 5
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 5);
											         
			  -- Horno6
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno6
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 6
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 6);
											         
			  -- Horno7
		      select case
			            when a.estadoactividad < 2 then
			                 0--'ABIERTO'
			            when a.estadoactividad = 2 then
			            	 1--'CERRADO'
			            else
			                 -1--'NO EXISTE'
			         end as estado 
			    into sp_horno7
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 88
		         and a.idhorno = 7
		         and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
		                                             from mct_movimientoordentrabajo b 
											        where b.codhojaruta = rec1.codhojaruta
											          and b.idseccion = 88
											          and b.idhorno = 7);											         
											         
											         
			  -- Tratamiento termico
		      select count(*) 
		        into sp_haytt
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7;

		      select count(*) 
		        into sp_hayttabierto
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 1;

		      select count(*) 
		        into sp_hayttcerrado
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.idseccion = 89
		         and a.idhorno = 7
		         and a.estadoactividad = 2;
		        
		      if (sp_haytt = 0) then
		      	
		      	sp_tratamiento	:= -1;
		      
		      elsif (sp_hayttabierto > 0) then
		      
		      	sp_tratamiento	:= 0;
		      
		      elsif (sp_hayttcerrado > 0) then
		      
		      	sp_tratamiento	:= 1;
		      
		      end if;
											         
			  -- RPL
		      select count(*),
		             max(a.fechatermino) 
		        into sp_rpl,
		             sp_fechatermino
		        from mct_movimientoordentrabajo a  
		       where a.codhojaruta = rec1.codhojaruta
		         and a.codigoaccion = 'R_PL';
		        
		     if (sp_fechatermino is not null) then
		     	
		     	 if (date_part('day', sp_fechatermino - rec1.fechaentregamec) > 0) then
		     	 
		     	 	sp_kpi	:= 0; -- En tiempo
		     	 
		     	 else
		     	 
		     	 	sp_kpi	:= 1; -- Atrasada
		     	 
		     	 end if;
		     	
		     else
		     
		     	sp_kpi	:= 0; -- En tiempo
		     
		     end if;
		        
	         item 					:= rec1.item;
	         idordentrabajo 		:= rec1.idordentrabajo; 
	         idordentrabajoparte 	:= 0;
	         idcomponente 			:= 0;
	         nombreparte 			:= rec1.nombreparte;
	         idhojaruta 			:= 0;
	         idhojarutatemp 		:= rec1.idhojarutatemp;
	         codhojaruta 			:= rec1.codhojaruta;   
	         nombreplano 			:= rec1.plano; 
	         idcriterioevaluacion 	:= rec1.idcriterioevaluacion;
	         modelo 				:= coalesce(sp_modelo,-1); 
	         moldeo 				:= coalesce(sp_moldeo,-1);
	         armado 				:= coalesce(sp_armado,-1);
	         horno1 				:= coalesce(sp_horno1,-1);
	         horno2 				:= coalesce(sp_horno2,-1);
	         horno3 				:= coalesce(sp_horno3,-1);
	         horno4 				:= coalesce(sp_horno4,-1);
	         horno5 				:= coalesce(sp_horno5,-1);
	         horno6 				:= coalesce(sp_horno6,-1);
	         horno7 				:= coalesce(sp_horno7,-1);
	         tratamiento 			:= sp_tratamiento;
	         rpl 					:= sp_rpl;
	         kpi					:= sp_kpi;	
	         diasentrega			:= rec1.diasfund;
		     
		     RETURN NEXT;			    
		     
		END LOOP;	

	end if;
	 		 
	
END;
$$;


ALTER FUNCTION traking.evtlistcontrolotfundiciongeneraldesgastesr(idfamilias bigint, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1885 (class 1255 OID 16943)
-- Name: evtlistcotipdfapp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistcotipdfapp(idworkorders bigint) RETURNS TABLE(idworkorder bigint, picfile text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
			select a.idordentrabajo ,
			       --split_part(archivoadjunto,'data:image/jpeg;base64,',2)
			        replace (a.archivoadjunto,'data:application/pdf;base64,','') 
			  from mct_infcotipdf a
			 where a.idordentrabajo = idworkorders 
			   and a.nombrearchivo like 'COT_%'
			   and a.infcoti = 40			 
			   and a.idproceso = 4;
END;
$$;


ALTER FUNCTION traking.evtlistcotipdfapp(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1092 (class 1255 OID 16944)
-- Name: evtlistctrlmaqscandata(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistctrlmaqscandata(scancode character varying) RETURNS TABLE(idworkorder bigint, idcomponent bigint, idclient bigint, idproduct bigint, productname character varying, customername character varying, componentname character varying, idcontrolmaquina bigint, idcomponenteplanocontrolmaq bigint, datoa numeric, datob numeric, datoc numeric, datod numeric, datoe numeric, datof numeric, datog numeric, datoh numeric, datoi numeric, datoj numeric, datok numeric, datol numeric, datom numeric, daton numeric, datoo numeric, datop numeric, datoq numeric, dator numeric, datos numeric, datot numeric, datou numeric, datov numeric, datow numeric, datox numeric, datoy numeric, datoz numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
		return QUERY
		select  d.idordentrabajo,
				c.idcomponente,
				e.idcliente,
				f.idproducto,
				f.nombreproducto,
				e.nombrecorto , 
		        c.nombrecomponente,   
		        coalesce(g.idcontrolmaquina ,0) as idcontrolmaquina,
		        case 
		           when g.idcierre = 0 then coalesce(g.idcomponenteplanocontrolmaq ,0)
		           else 0
		        end as idcomponenteplanocontrolmaq,
		        coalesce(g.datoa ,null),
		        coalesce(g.datob ,null),
		        coalesce(g.datoc ,null),
		        coalesce(g.datod ,null),
		        coalesce(g.datoe ,null),
		        coalesce(g.datof ,null),
		        coalesce(g.datog ,null),
		        coalesce(g.datoh ,null),
		        coalesce(g.datoi ,null),
		        coalesce(g.datoj ,null),
		        coalesce(g.datok ,null),
		        coalesce(g.datol ,null),
		        coalesce(g.datom, null) ,
	               coalesce (g.daton, null) ,
	               coalesce (g.datoo, null) ,
	               coalesce (g.datop, null) ,
	               coalesce (g.datoq, null) ,
	               coalesce (g.dator, null) ,
	               coalesce (g.datos, null) ,
	               coalesce (g.datot, null) ,
	               coalesce (g.datou, null) ,
	               coalesce (g.datov, null) ,
	               coalesce (g.datow, null) ,
	               coalesce (g.datox, null) ,
	               coalesce (g.datoy, null) ,
	               coalesce (g.datoz, null) 
		  from mct_detallehojarutatemp a,
		       mct_hojarutatemp b,
		       mct_componente c,
		       mct_ordentrabajo d,
		       mct_cliente e,
		       mct_producto f
		left join traking.mct_controlmaquina g on g.codhojaruta = scancode and g.idcierre = 0 
		where a.codhojaruta = scancode
		   and a.idhojarutatemp = b.idhojarutatemp 
		   and b.idcomponente = c.idcomponente
		   and b.idordentrabajo = d.idordentrabajo 
		   and e.idcliente = d.idcliente 
		   and f.idproducto = d.idproducto
		   ;

   END;
$$;


ALTER FUNCTION traking.evtlistctrlmaqscandata(scancode character varying) OWNER TO postgres;

--
-- TOC entry 1145 (class 1255 OID 16945)
-- Name: evtlistdatedispatch(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdatedispatch(startdate character varying, enddate character varying, idfamilys bigint) RETURNS TABLE(idpartdispatchhead bigint, datedispatch timestamp without time zone, idworkorder bigint, outputguide bigint, workordername character varying, clientname character varying, orderstatusname character varying, productname character varying, dateguia character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
        
	if ( idfamilys = 24 ) then
	
	        RETURN QUERY
	        
--	  		select a.iddespachopartecabecera,
--			       a.fechadespacho,
--			       a.idordentrabajo,
--			       --c.guiasaliente,
--			       a.guiasaliente,
--			       --c.nombreordentrabajo,
--			       cast(f.sigla||'_'||g.sigla as varchar),
--			       d.nombrecliente,
--			       e.nombreestado,
--			       cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam  as varchar) ,
--			       cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar)
--			from mct_despachopartecabecera a,
--			     mct_ordentrabajo c,
--			     mct_cliente d,
--			     mct_estadoorden e,
--			     mct_tipoorden f,
--			     mct_familia g,
--			     mct_producto h,
--			     mct_modelo i,
--			     mct_subfamilia j,
--			     mct_etapaparam k
--			--where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
--			where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
--			  and a.idordentrabajo = c.idordentrabajo
--			  and c.idcliente = d.idcliente
--			  and c.idestadoorden = e.idestadoorden
--			  and c.idtipoorden = f.idtipoorden 
--			  and c.idfamilia = g.idfamilia 
--			  and c.idordentrabajo >= 30000
--			  and c.idproducto = h.idproducto
--			  and h.idmodelo = i.idmodelo
--			  and i.idsubfamilia = j.idsubfamilia 
--			  and h.idetapaparam = k.idetapaparam 
--			 order by a.fechaguia asc;

	        select iddespachopartecabecera,
	               fechadespacho,
	               idordentrabajo,
	               guiasaliente,
	               sigla,
	               nombrecliente,
	               nombreestado,
	               producto,
	               cast(to_char(fechaguia, 'dd-mm-yyyy') as varchar)
	          from 
	        (
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar) as sigla,
			       d.nombrecliente,
			       e.nombreestado,
			       cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam as varchar) as producto,
			       --cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar) as fechaguia
			       a.fechaguia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_producto h,
			     mct_modelo i,
			     mct_subfamilia j,
			     mct_etapaparam k
			--where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			  and a.idordentrabajo = c.idordentrabajo
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			 -- and c.idfamilia = idfamilys
			  and c.idproducto = h.idproducto
			  and h.idmodelo = i.idmodelo
			  and i.idsubfamilia = j.idsubfamilia 
			  and h.idetapaparam = k.idetapaparam
			 --order by a.fechaguia asc
	      union 
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar) as sigla,
			       d.nombrecliente,
			       e.nombreestado,
			       --cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam as varchar),
			       cast(h.nombreproductonepcast  as varchar) as producto,
			       --cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar) as fechaguia
			       a.fechaguia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_productonepcast h
--			     mct_modelo i,
--			     mct_subfamilia j,
--			     mct_etapaparam k
			--where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			  and a.idordentrabajo = c.idordentrabajo
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  --and c.idfamilia = idfamilys
			  and c.idproducto = h.idproductonepcast
--			  and h.idmodelo = i.idmodelo
--			  and i.idsubfamilia = j.idsubfamilia 
--			  and h.idetapaparam = k.idetapaparam
			-- order by a.fechaguia asc	
			) as tabla
			order by tabla.iddespachopartecabecera asc;
		
	else

	        RETURN QUERY
               
	        select iddespachopartecabecera,
	               fechadespacho,
	               idordentrabajo,
	               guiasaliente,
	               sigla,
	               nombrecliente,
	               nombreestado,
	               producto,
	               cast(to_char(fechaguia, 'dd-mm-yyyy') as varchar)
	          from 
	        (
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar) as sigla,
			       d.nombrecliente,
			       e.nombreestado,
			       cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam as varchar) as producto,
			       --cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar) as fechaguia
			       a.fechaguia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_producto h,
			     mct_modelo i,
			     mct_subfamilia j,
			     mct_etapaparam k
			--where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			  and a.idordentrabajo = c.idordentrabajo
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  and c.idfamilia = idfamilys
			  and c.idproducto = h.idproducto
			  and h.idmodelo = i.idmodelo
			  and i.idsubfamilia = j.idsubfamilia 
			  and h.idetapaparam = k.idetapaparam
			 --order by a.fechaguia asc
	      union 
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar) as sigla,
			       d.nombrecliente,
			       e.nombreestado,
			       --cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam as varchar),
			       cast(h.nombreproductonepcast  as varchar) as producto,
			       --cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar) as fechaguia
			       a.fechaguia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_productonepcast h
--			     mct_modelo i,
--			     mct_subfamilia j,
--			     mct_etapaparam k
			--where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			  and a.idordentrabajo = c.idordentrabajo
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  and c.idfamilia = idfamilys
			  and c.idproducto = h.idproductonepcast
--			  and h.idmodelo = i.idmodelo
--			  and i.idsubfamilia = j.idsubfamilia 
--			  and h.idetapaparam = k.idetapaparam
			-- order by a.fechaguia asc	
			) as tabla
			order by tabla.iddespachopartecabecera asc;
	      
	end if;


END;
$$;


ALTER FUNCTION traking.evtlistdatedispatch(startdate character varying, enddate character varying, idfamilys bigint) OWNER TO postgres;

--
-- TOC entry 1004 (class 1255 OID 16946)
-- Name: evtlistdatedispatch_test(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdatedispatch_test(startdate character varying, enddate character varying, idfamilys bigint) RETURNS TABLE(idpartdispatchhead bigint, datedispatch timestamp without time zone, idworkorder bigint, outputguide bigint, workordername character varying, clientname character varying, orderstatusname character varying, productname character varying, dateguia character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
        
	if ( idfamilys = 24 ) then
	
	        RETURN QUERY
	        
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			       --c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar),
			       d.nombrecliente,
			       e.nombreestado,
			       cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam  as varchar) ,
			       cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar)
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_producto h,
			     mct_modelo i,
			     mct_subfamilia j,
			     mct_etapaparam k
			--where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  and c.idproducto = h.idproducto
			  and h.idmodelo = i.idmodelo
			  and i.idsubfamilia = j.idsubfamilia 
			  and h.idetapaparam = k.idetapaparam 
			 order by a.fechaguia asc;
	
	else

	        RETURN QUERY
               
	        select * from 
	        (
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar) as sigla,
			       d.nombrecliente,
			       e.nombreestado,
			       cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam as varchar) as producto,
			       cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar) as fechaguia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_producto h,
			     mct_modelo i,
			     mct_subfamilia j,
			     mct_etapaparam k
			--where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			  and a.idordentrabajo = c.idordentrabajo
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  and c.idfamilia = 11
			  and c.idproducto = h.idproducto
			  and h.idmodelo = i.idmodelo
			  and i.idsubfamilia = j.idsubfamilia 
			  and h.idetapaparam = k.idetapaparam
			 --order by a.fechaguia asc
	      union 
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar) as sigla,
			       d.nombrecliente,
			       e.nombreestado,
			       --cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam as varchar),
			       cast(h.nombreproductonepcast  as varchar) as producto,
			       cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar) as fechaguia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_productonepcast h
--			     mct_modelo i,
--			     mct_subfamilia j,
--			     mct_etapaparam k
			--where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			  and a.idordentrabajo = c.idordentrabajo
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  and c.idfamilia = 11
			  and c.idproducto = h.idproductonepcast
--			  and h.idmodelo = i.idmodelo
--			  and i.idsubfamilia = j.idsubfamilia 
--			  and h.idetapaparam = k.idetapaparam
			-- order by a.fechaguia asc	
			) as tabla
			order by tabla.fechaguia asc;
	      
	end if;


END;
$$;


ALTER FUNCTION traking.evtlistdatedispatch_test(startdate character varying, enddate character varying, idfamilys bigint) OWNER TO postgres;

--
-- TOC entry 1269 (class 1255 OID 16947)
-- Name: evtlistdatedispatchotunica(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdatedispatchotunica(startdate character varying, enddate character varying, idfamilys bigint) RETURNS TABLE(cantidadot bigint, totalbombas bigint, totalrepuestos bigint, totalelementos bigint, totalotros bigint)
    LANGUAGE plpgsql
    AS $$
declare

    rec_ord          	record;
    rec_ordtot          record;
   
    sp_cantidadtot		bigint;
    sp_montotot			bigint;
    sp_totalbomba		bigint;
    sp_totalrepuesto	bigint;
    sp_totalelemento	bigint;
    sp_totalotros		bigint;
   
    sp_elementoparte	bigint;
    sp_cantidadtot_ed   bigint;
   
BEGIN

	sp_cantidadtot		:= 0;
    sp_montotot			:= 0;
    sp_totalbomba		:= 0;
    sp_totalrepuesto	:= 0;
    sp_totalelemento	:= 0;
    sp_totalotros		:= 0;
    sp_cantidadtot_ed	:= 0;
   
	if ( idfamilys = 24 ) then
	
				FOR rec_ord IN (   
				  		select count(distinct(c.idordentrabajo) ) as ots,
				  		       coalesce (sum(c.montorepfab) , 0) as monto,
				  		       c.idfamilia as idfamilia
						from mct_despachopartecabecera a,
						     mct_ordentrabajo c
						where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
	  				    --where (a.fechaguia >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
						and a.idordentrabajo = c.idordentrabajo
						  and c.idordentrabajo >= 30000
						  group by c.idfamilia
					)
				loop 	
	       
				     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
				    
			         if ( rec_ord.idfamilia = 8 ) then
                        -- bombas
			            sp_totalbomba := sp_totalbomba + rec_ord.monto;

			         
			         end if;
			        
			         if ( rec_ord.idfamilia = 14 ) then
                        -- bombas
			            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;

			         
			         end if;
			        
			         if ( rec_ord.idfamilia = 10 ) then
                        -- repuestos
			            select sum(costo * cantidad)
			              into sp_totalrepuesto
			              from mct_ordentrabajorepuesto mo 
			             where idordentrabajo in 
					            ( 
					           	  select distinct(c.idordentrabajo)
									from mct_despachopartecabecera a,
									     mct_ordentrabajo c
					                where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
									  and a.idordentrabajo = c.idordentrabajo
									  and c.idordentrabajo >= 30000
									  and c.idfamilia = rec_ord.idfamilia
					            );
			            
			            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
			         
			         end if;
			        
			         if ( rec_ord.idfamilia = 11 ) then
                        -- elemnetos
			        
						select sum(tabla.ots) as ots,
					           sum(tabla.monto) as monto
						       --tabla.idfamilia as idfamilia
						  into sp_cantidadtot_ed,
						       sp_montotot
						  from (
								select count(distinct(c.idordentrabajo) ) as ots,
								       coalesce (sum(c.montorepfab) , 0) as monto,
								       c.idfamilia as idfamilia
								  from mct_despachopartecabecera a,
							  	       mct_ordentrabajo c
								 where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
								 --where (a.fechaguia >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
								   and a.idordentrabajo = c.idordentrabajo
								   and c.idordentrabajo >= 30000
								   and c.idfamilia = 11
								   group by c.idfamilia
							   ) as tabla
						  group by tabla.idfamilia;
										   
						FOR rec_ordtot IN (   
								    
								select b.idparte        as idparte, 
								       sum(b.qdespacho) as cantidad
								  from mct_despachopartecabecera a,
								       mct_despachopartedetalle b, 
									   mct_ordentrabajo c
							 	 where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
								 --where (a.fechaguia >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
							 	   and a.idordentrabajo = c.idordentrabajo
								   and c.idordentrabajo >= 30000
								   and c.idfamilia = 11
								   and a.iddespachopartecabecera = b.iddespachopartecabecera
							     group by b.idparte
													  
									)
								loop 	
					       
									sp_elementoparte	:= 0;
								
									select coalesce(sum(a.costo * rec_ordtot.cantidad),0)
									  into sp_elementoparte
									  from mct_ordentrabajorepuesto a 
									 where a.idordentrabajorepuesto = rec_ordtot.idparte;
														
									sp_totalelemento := sp_totalelemento + sp_elementoparte;	
								
								    raise notice '%', rec_ordtot.idparte||' - '||rec_ordtot.cantidad||' - '||sp_totalelemento||' - '||sp_elementoparte;
						
								END LOOP;	
							
								cantidadot		:= sp_cantidadtot + sp_cantidadtot_ed;
							    totalbombas	    := sp_totalbomba;
							    totalrepuestos	:= sp_totalrepuesto;
							    totalelementos	:= sp_totalelemento +  sp_montotot;
							    totalotros		:= sp_totalotros;
							   
--							   	return next;
			   
			         end if;
			        
			         if ( rec_ord.idfamilia = 15 ) then
                        -- otros
			            select sum(costo * cantidad)
			              into sp_totalotros
			              from mct_ordentrabajorepuesto mo 
                         where idordentrabajo in 
					            ( 
					           	  select distinct(c.idordentrabajo)
									from mct_despachopartecabecera a,
									     mct_ordentrabajo c
									where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
									  and a.idordentrabajo = c.idordentrabajo 
									  and c.idordentrabajo >= 30000
									  and c.idfamilia = rec_ord.idfamilia
					            );
			            
			            sp_totalotros := sp_totalotros + rec_ord.monto;
			            
			         
			         end if;
			 
		
				END LOOP;	
			
				cantidadot		:= sp_cantidadtot;
			    totalbombas	    := sp_totalbomba;
			    totalrepuestos	:= sp_totalrepuesto;
			    totalelementos	:= sp_totalelemento;
			    totalotros		:= sp_totalotros;
			   
			   	return next;
			
	end if;


	if ( idfamilys = 8 ) then

				FOR rec_ord IN (   
			  		select count(distinct(c.idordentrabajo) ) as ots,
			  		       coalesce (sum(c.montorepfab) , 0) as monto,
			  		       c.idfamilia as idfamilia
					from mct_despachopartecabecera a,
					     mct_ordentrabajo c
					where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
					  and a.idordentrabajo = c.idordentrabajo
					  and c.idordentrabajo >= 30000
					  and c.idfamilia = 8
					 group by c.idfamilia 
						   
							)
				loop 	
	       
				     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
				    
			         if ( rec_ord.idfamilia = 8 ) then
                        -- bombas
			            sp_totalbomba := sp_totalbomba + rec_ord.monto;

			         
			         end if;
			       
		
				END LOOP;	
			
				cantidadot		:= sp_cantidadtot;
			    totalbombas	    := sp_totalbomba;
			    totalrepuestos	:= sp_totalrepuesto;
			    totalelementos	:= sp_totalelemento;
			    totalotros		:= sp_totalotros;
			   
			   	return next;	
	end if;


	if ( idfamilys = 10 ) then

				FOR rec_ord IN (   
			  		select count(distinct(c.idordentrabajo) ) as ots,
			  		       coalesce (sum(c.montorepfab) , 0) as monto,
			  		       c.idfamilia as idfamilia
					from mct_despachopartecabecera a,
					     mct_ordentrabajo c
					where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
					  and a.idordentrabajo = c.idordentrabajo
					  and c.idordentrabajo >= 30000
					  and c.idfamilia = 10
					 group by c.idfamilia 
						   
							)
				loop 	
	       
				     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
				    
			         if ( rec_ord.idfamilia = 10 ) then
                        -- repuestos
			            select sum(costo * cantidad)
			              into sp_totalrepuesto
			              from mct_ordentrabajorepuesto mo 
			             where idordentrabajo in 
					            ( 
					           	  select distinct(c.idordentrabajo)
									from mct_despachopartecabecera a,
									     mct_ordentrabajo c
									where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
									  and a.idordentrabajo = c.idordentrabajo
									  and c.idordentrabajo >= 30000
									  and c.idfamilia = rec_ord.idfamilia
					            );
			            
			            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
			         
			         end if;
			 
		
				END LOOP;	
			
				cantidadot		:= sp_cantidadtot;
			    totalbombas	    := sp_totalbomba;
			    totalrepuestos	:= sp_totalrepuesto;
			    totalelementos	:= sp_totalelemento;
			    totalotros		:= sp_totalotros;
			   
			   	return next;
	
	end if;


	if ( idfamilys = 11 ) then

		select sum(tabla.ots) as ots,
	           sum(tabla.monto) as monto
		       --tabla.idfamilia as idfamilia
		  into sp_cantidadtot,
		       sp_montotot
		  from (
				select count(distinct(c.idordentrabajo) ) as ots,
				       coalesce (sum(c.montorepfab) , 0) as monto,
				       c.idfamilia as idfamilia
				  from mct_despachopartecabecera a,
			  	       mct_ordentrabajo c
				 where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				   and a.idordentrabajo = c.idordentrabajo
				   and c.idordentrabajo >= 30000
				   and c.idfamilia = 11
				   group by c.idfamilia
			   ) as tabla
		  group by tabla.idfamilia;
						   
		FOR rec_ord IN (   
				    
				select b.idparte        as idparte, 
				       sum(b.qdespacho) as cantidad
				  from mct_despachopartecabecera a,
				       mct_despachopartedetalle b, 
					   mct_ordentrabajo c
			 	 where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				   and a.idordentrabajo = c.idordentrabajo
				   and c.idordentrabajo >= 30000
				   and c.idfamilia = 11
				   and a.iddespachopartecabecera = b.iddespachopartecabecera
			     group by b.idparte  
									  
					)
				loop 	
	       
					sp_elementoparte	:= 0;
				
					select coalesce(sum(a.costo * rec_ord.cantidad),0)
					  into sp_elementoparte
