					where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
					  and a.idordentrabajo = c.idordentrabajo
					  and c.idordentrabajo >= 30000
					  and c.idfamilia = 15
					 group by c.idfamilia 
						   
							)
				loop 	
	       
				     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
			        
			         if ( rec_ord.idfamilia = 15 ) then
                        -- otros
			            select sum(costo * cantidad)
			              into sp_totalotros
			              from mct_ordentrabajorepuesto mo 
                         where idordentrabajo in 
					            ( 
					           	  select distinct(c.idordentrabajo)
									from mct_despachopartecabecera a,
									     mct_ordentrabajo c
									where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
									  and a.idordentrabajo = c.idordentrabajo
									  and c.idordentrabajo >= 30000
									  and c.idfamilia = rec_ord.idfamilia
					            );
			            
			            sp_totalotros := sp_totalotros + rec_ord.monto;
			            
			         
			         end if;
			 
		
				END LOOP;	
			
				cantidadot		:= sp_cantidadtot;
			    totalbombas	    := sp_totalbomba;
			    totalrepuestos	:= sp_totalrepuesto;
			    totalelementos	:= sp_totalelemento;
			    totalotros		:= sp_totalotros;
			   
			   	return next;
	
	end if;


	if ( idfamilys = 14 ) then

	
				FOR rec_ord IN (   
			  		select count(distinct(c.idordentrabajo) ) as ots,
			  		       coalesce (sum(c.montorepfab) , 0) as monto,
			  		       c.idfamilia as idfamilia
					from mct_despachopartecabecera a,
					     mct_ordentrabajo c
					where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
					  and a.idordentrabajo = c.idordentrabajo
					  and c.idordentrabajo >= 30000
					  and c.idfamilia = 14
					 group by c.idfamilia 
						   
							)
				loop 	
	       
				     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
			
--			         if ( rec_ord.idfamilia = 14 ) then
--                        -- repuestos
--			            select sum(costo * cantidad)
--			              into sp_totalrepuesto
--			              from mct_ordentrabajorepuesto mo 
--			             where idordentrabajo in 
--					            ( 
--					           	  select distinct(c.idordentrabajo)
--									from mct_despachopartecabecera a,
--									     mct_ordentrabajo c
--									where (a.fechaguia  >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
--									  and a.idordentrabajo = c.idordentrabajo
--									  and c.idordentrabajo >= 30000
--									  and c.idfamilia = rec_ord.idfamilia
--					            );
--			            
--			            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
--			         
--			         end if;
			         
				     if ( rec_ord.idfamilia = 14 ) then
                        -- motores
			            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
			         
			         end if;
			        			        			 
		
				END LOOP;	
			
				cantidadot		:= sp_cantidadtot;
			    totalbombas	    := sp_totalbomba;
			    totalrepuestos	:= sp_totalrepuesto;
			    totalelementos	:= sp_totalelemento;
			    totalotros		:= sp_totalotros;
			   
			   	return next;
	
	end if;

END;
$$;


ALTER FUNCTION traking.evtlistdatedispatchotunica(startdate character varying, enddate character varying, idfamilys bigint) OWNER TO postgres;

--
-- TOC entry 2050 (class 1255 OID 16949)
-- Name: evtlistdatedispatchotunica_porguia(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdatedispatchotunica_porguia(idguias bigint) RETURNS TABLE(cantidadot bigint, totalbombas bigint, totalrepuestos bigint, totalelementos bigint, totalotros bigint)
    LANGUAGE plpgsql
    AS $$
declare

    rec_ord          	record;
    rec_ordtot          record;
   
    sp_cantidadtot		bigint;
    sp_montotot			bigint;
    sp_totalbomba		bigint;
    sp_totalrepuesto	bigint;
    sp_totalelemento	bigint;
    sp_totalotros		bigint;
   
    sp_elementoparte	bigint;
    sp_cantidadtot_ed   bigint;
   
BEGIN

	sp_cantidadtot		:= 0;
    sp_montotot			:= 0;
    sp_totalbomba		:= 0;
    sp_totalrepuesto	:= 0;
    sp_totalelemento	:= 0;
    sp_totalotros		:= 0;
    sp_cantidadtot_ed	:= 0;
   

	FOR rec_ord IN (   
	  		select count(distinct(c.idordentrabajo) ) as ots,
	  		       coalesce (sum(c.montorepfab) , 0) as monto,
	  		       c.idfamilia as idfamilia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c
			where a.guiasaliente  = idguias
		  	  and a.idordentrabajo = c.idordentrabajo
			  and c.idordentrabajo >= 30000
		    group by c.idfamilia
			)
		loop 	
   
		     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
		    
	         if ( rec_ord.idfamilia = 8 ) then
                -- bombas
            sp_totalbomba := sp_totalbomba + rec_ord.monto;

         
         end if;
        
         if ( rec_ord.idfamilia = 14 ) then
            -- bombas
            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;

         
         end if;
        
         if ( rec_ord.idfamilia = 10 ) then
            -- repuestos
            select sum(costo * cantidad)
              into sp_totalrepuesto
              from mct_ordentrabajorepuesto mo 
             where idordentrabajo in 
		            ( 
		           	  select distinct(c.idordentrabajo)
						from mct_despachopartecabecera a,
						     mct_ordentrabajo c
		                where c.guiasaliente  = idguias
						  and a.idordentrabajo = c.idordentrabajo
						  and c.idordentrabajo >= 30000
						  and c.idfamilia = rec_ord.idfamilia
		            );
            
            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
         
         end if;
        
         if ( rec_ord.idfamilia = 11 ) then
            -- elemnetos
        
			select sum(tabla.ots) as ots,
		           sum(tabla.monto) as monto
			       --tabla.idfamilia as idfamilia
			  into sp_cantidadtot_ed,
			       sp_montotot
			  from (
					select count(distinct(c.idordentrabajo) ) as ots,
					       coalesce (sum(c.montorepfab) , 0) as monto,
					       c.idfamilia as idfamilia
					  from mct_despachopartecabecera a,
				  	       mct_ordentrabajo c
					 where c.guiasaliente  = idguias
					 --where (a.fechaguia >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
					   and a.idordentrabajo = c.idordentrabajo
					   and c.idordentrabajo >= 30000
					   and c.idfamilia = 11
					   group by c.idfamilia
				   ) as tabla
			  group by tabla.idfamilia;
							   
			FOR rec_ordtot IN (   
					    
					select b.idparte        as idparte, 
					       sum(b.qdespacho) as cantidad
					  from mct_despachopartecabecera a,
					       mct_despachopartedetalle b, 
						   mct_ordentrabajo c
				 	 where a.guiasaliente  = idguias
					 --where (a.fechaguia >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				 	   and a.idordentrabajo = c.idordentrabajo
					   and c.idordentrabajo >= 30000
					   and c.idfamilia = 11
					   and a.iddespachopartecabecera = b.iddespachopartecabecera
				     group by b.idparte
										  
						)
					loop 	
		       
						sp_elementoparte	:= 0;
					
						select coalesce(sum(a.costo * rec_ordtot.cantidad),0)
						  into sp_elementoparte
						  from mct_ordentrabajorepuesto a 
						 where a.idordentrabajorepuesto = rec_ordtot.idparte;
											
						sp_totalelemento := sp_totalelemento + sp_elementoparte;	
					
					    raise notice '%', rec_ordtot.idparte||' - '||rec_ordtot.cantidad||' - '||sp_totalelemento||' - '||sp_elementoparte;
			
					END LOOP;	
				
					cantidadot		:= sp_cantidadtot + sp_cantidadtot_ed;
				    totalbombas	    := sp_totalbomba;
				    totalrepuestos	:= sp_totalrepuesto;
				    totalelementos	:= sp_totalelemento +  sp_montotot;
				    totalotros		:= sp_totalotros;
				   
--							   	return next;
   
         end if;
        
         if ( rec_ord.idfamilia = 15 ) then
            -- otros
            select sum(costo * cantidad)
              into sp_totalotros
              from mct_ordentrabajorepuesto mo 
             where idordentrabajo in 
		            ( 
		           	  select distinct(c.idordentrabajo)
						from mct_despachopartecabecera a,
						     mct_ordentrabajo c
						where a.guiasaliente  = idguias
						  and a.idordentrabajo = c.idordentrabajo 
						  and c.idordentrabajo >= 30000
						  and c.idfamilia = rec_ord.idfamilia
		            );
            
            sp_totalotros := sp_totalotros + rec_ord.monto;
            
         
         end if;
 

	END LOOP;	

	cantidadot		:= sp_cantidadtot;
    totalbombas	    := sp_totalbomba;
    totalrepuestos	:= sp_totalrepuesto;
    totalelementos	:= sp_totalelemento;
    totalotros		:= sp_totalotros;
   
   	return next;

END;
$$;


ALTER FUNCTION traking.evtlistdatedispatchotunica_porguia(idguias bigint) OWNER TO postgres;

--
-- TOC entry 1440 (class 1255 OID 16950)
-- Name: evtlistdatedispatchotunica_poroc(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdatedispatchotunica_poroc(oc bigint) RETURNS TABLE(cantidadot bigint, totalbombas bigint, totalrepuestos bigint, totalelementos bigint, totalotros bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

    rec_ord             record;
    rec_ordtot          record;

    sp_cantidadtot      bigint;
    sp_montotot         bigint;
    sp_totalbomba       bigint;
    sp_totalrepuesto    bigint;
    sp_totalelemento    bigint;
    sp_totalotros       bigint;
    sp_elementoparte    bigint;
    sp_cantidadtot_ed   bigint;

BEGIN

    sp_cantidadtot      := 0;
    sp_montotot         := 0;
    sp_totalbomba       := 0;
    sp_totalrepuesto    := 0;
    sp_totalelemento    := 0;
    sp_totalotros       := 0;
    sp_cantidadtot_ed   := 0;


    FOR rec_ord IN (

        SELECT
            count(distinct(c.idordentrabajo)) AS ots,
            coalesce(sum(c.montorepfab), 0) AS monto,
            c.idfamilia AS idfamilia

        FROM mct_despachopartecabecera a,
             mct_ordentrabajo c

        WHERE a.idordentrabajo = c.idordentrabajo
          AND c.idordentrabajo >= 30000

          -- NUEVO FILTRO POR OC
          AND c.ordencompra = oc

        GROUP BY c.idfamilia

    )

    LOOP

        sp_cantidadtot := sp_cantidadtot + rec_ord.ots;


        -- =====================================================
        -- BOMBAS
        -- =====================================================
        IF (rec_ord.idfamilia = 8) THEN

            sp_totalbomba :=
                sp_totalbomba + rec_ord.monto;

        END IF;


        -- =====================================================
        -- REPUESTOS FAMILIA 14
        -- =====================================================
        IF (rec_ord.idfamilia = 14) THEN

            sp_totalrepuesto :=
                sp_totalrepuesto + rec_ord.monto;

        END IF;


        -- =====================================================
        -- REPUESTOS FAMILIA 10
        -- =====================================================
        IF (rec_ord.idfamilia = 10) THEN

            SELECT sum(costo * cantidad)
              INTO sp_totalrepuesto
              FROM mct_ordentrabajorepuesto mo
             WHERE idordentrabajo IN
             (
                 SELECT DISTINCT(c.idordentrabajo)

                   FROM mct_despachopartecabecera a,
                        mct_ordentrabajo c

                  WHERE a.idordentrabajo = c.idordentrabajo
                    AND c.idordentrabajo >= 30000
                    AND c.idfamilia = rec_ord.idfamilia

                    -- NUEVO FILTRO POR OC
                    AND c.ordencompra = oc
             );

            sp_totalrepuesto :=
                sp_totalrepuesto + rec_ord.monto;

        END IF;


        -- =====================================================
        -- ELEMENTOS DE DESGASTE
        -- =====================================================
        IF (rec_ord.idfamilia = 11) THEN


            SELECT
                sum(tabla.ots) AS ots,
                sum(tabla.monto) AS monto

              INTO
                sp_cantidadtot_ed,
                sp_montotot

              FROM
              (
                  SELECT
                      count(distinct(c.idordentrabajo)) AS ots,
                      coalesce(sum(c.montorepfab), 0) AS monto,
                      c.idfamilia AS idfamilia

                    FROM mct_despachopartecabecera a,
                         mct_ordentrabajo c

                   WHERE a.idordentrabajo = c.idordentrabajo
                     AND c.idordentrabajo >= 30000
                     AND c.idfamilia = 11

                     -- NUEVO FILTRO POR OC
                     AND c.ordencompra = oc

                   GROUP BY c.idfamilia

              ) AS tabla

             GROUP BY tabla.idfamilia;


            FOR rec_ordtot IN (

                SELECT
                    b.idparte AS idparte,
                    sum(b.qdespacho) AS cantidad

                  FROM mct_despachopartecabecera a,
                       mct_despachopartedetalle b,
                       mct_ordentrabajo c

                 WHERE a.idordentrabajo = c.idordentrabajo
                   AND c.idordentrabajo >= 30000
                   AND c.idfamilia = 11

                   AND a.iddespachopartecabecera =
                       b.iddespachopartecabecera

                   -- NUEVO FILTRO POR OC
                   AND c.ordencompra = oc

                 GROUP BY b.idparte

            )

            LOOP

                sp_elementoparte := 0;


                SELECT coalesce(
                           sum(a.costo * rec_ordtot.cantidad),
                           0
                       )
                  INTO sp_elementoparte

                  FROM mct_ordentrabajorepuesto a

                 WHERE a.idordentrabajorepuesto =
                       rec_ordtot.idparte;


                sp_totalelemento :=
                    sp_totalelemento + sp_elementoparte;


                RAISE NOTICE '%',
                    rec_ordtot.idparte
                    ||' - '||
                    rec_ordtot.cantidad
                    ||' - '||
                    sp_totalelemento
                    ||' - '||
                    sp_elementoparte;

            END LOOP;


            cantidadot :=
                sp_cantidadtot + sp_cantidadtot_ed;

            totalbombas :=
                sp_totalbomba;

            totalrepuestos :=
                sp_totalrepuesto;

            totalelementos :=
                sp_totalelemento + sp_montotot;

            totalotros :=
                sp_totalotros;

        END IF;


        -- =====================================================
        -- OTROS
        -- =====================================================
        IF (rec_ord.idfamilia = 15) THEN

            SELECT sum(costo * cantidad)
              INTO sp_totalotros

              FROM mct_ordentrabajorepuesto mo

             WHERE idordentrabajo IN
             (
                 SELECT DISTINCT(c.idordentrabajo)

                   FROM mct_despachopartecabecera a,
                        mct_ordentrabajo c

                  WHERE a.idordentrabajo = c.idordentrabajo
                    AND c.idordentrabajo >= 30000
                    AND c.idfamilia = rec_ord.idfamilia

                    -- NUEVO FILTRO POR OC
                    AND c.ordencompra = oc
             );


            sp_totalotros :=
                sp_totalotros + rec_ord.monto;

        END IF;


    END LOOP;


    cantidadot      := sp_cantidadtot;
    totalbombas     := sp_totalbomba;
    totalrepuestos  := sp_totalrepuesto;
    totalelementos  := sp_totalelemento;
    totalotros      := sp_totalotros;

    RETURN NEXT;

END;

$$;


ALTER FUNCTION traking.evtlistdatedispatchotunica_poroc(oc bigint) OWNER TO postgres;

--
-- TOC entry 1657 (class 1255 OID 16951)
-- Name: evtlistdatedispatchotunica_porot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdatedispatchotunica_porot(idworkorders bigint) RETURNS TABLE(cantidadot bigint, totalbombas bigint, totalrepuestos bigint, totalelementos bigint, totalotros bigint)
    LANGUAGE plpgsql
    AS $$
declare

    rec_ord          	record;
    rec_ordtot          record;
   
    sp_cantidadtot		bigint;
    sp_montotot			bigint;
    sp_totalbomba		bigint;
    sp_totalrepuesto	bigint;
    sp_totalelemento	bigint;
    sp_totalotros		bigint;
   
    sp_elementoparte	bigint;
    sp_cantidadtot_ed   bigint;
   
BEGIN

	sp_cantidadtot		:= 0;
    sp_montotot			:= 0;
    sp_totalbomba		:= 0;
    sp_totalrepuesto	:= 0;
    sp_totalelemento	:= 0;
    sp_totalotros		:= 0;
    sp_cantidadtot_ed	:= 0;
   

	FOR rec_ord IN (   
	  		select count(distinct(c.idordentrabajo) ) as ots,
	  		       coalesce (sum(c.montorepfab) , 0) as monto,
	  		       c.idfamilia as idfamilia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c
			where c.idordentrabajo = idworkorders
		    --where (a.fechaguia >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				and a.idordentrabajo = c.idordentrabajo
				  and c.idordentrabajo >= 30000
				  group by c.idfamilia
			)
		loop 	
   
		     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
		    
	         if ( rec_ord.idfamilia = 8 ) then
                -- bombas
            sp_totalbomba := sp_totalbomba + rec_ord.monto;

         
         end if;
        
         if ( rec_ord.idfamilia = 14 ) then
            -- bombas
            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;

         
         end if;
        
         if ( rec_ord.idfamilia = 10 ) then
            -- repuestos
            select sum(costo * cantidad)
              into sp_totalrepuesto
              from mct_ordentrabajorepuesto mo 
             where idordentrabajo in 
		            ( 
		           	  select distinct(c.idordentrabajo)
						from mct_despachopartecabecera a,
						     mct_ordentrabajo c
		                where c.idordentrabajo = idworkorders
						  and a.idordentrabajo = c.idordentrabajo
						  and c.idordentrabajo >= 30000
						  and c.idfamilia = rec_ord.idfamilia
		            );
            
            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
         
         end if;
        
         if ( rec_ord.idfamilia = 11 ) then
            -- elemnetos
        
			select sum(tabla.ots) as ots,
		           sum(tabla.monto) as monto
			       --tabla.idfamilia as idfamilia
			  into sp_cantidadtot_ed,
			       sp_montotot
			  from (
					select count(distinct(c.idordentrabajo) ) as ots,
					       coalesce (sum(c.montorepfab) , 0) as monto,
					       c.idfamilia as idfamilia
					  from mct_despachopartecabecera a,
				  	       mct_ordentrabajo c
					 where c.idordentrabajo = idworkorders
					 --where (a.fechaguia >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
					   and a.idordentrabajo = c.idordentrabajo
					   and c.idordentrabajo >= 30000
					   and c.idfamilia = 11
					   group by c.idfamilia
				   ) as tabla
			  group by tabla.idfamilia;
							   
			FOR rec_ordtot IN (   
					    
					select b.idparte        as idparte, 
					       sum(b.qdespacho) as cantidad
					  from mct_despachopartecabecera a,
					       mct_despachopartedetalle b, 
						   mct_ordentrabajo c
				 	 where c.idordentrabajo = idworkorders
					 --where (a.fechaguia >= TO_TIMESTAMP('2023-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP('2023-06-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				 	   and a.idordentrabajo = c.idordentrabajo
					   and c.idordentrabajo >= 30000
					   and c.idfamilia = 11
					   and a.iddespachopartecabecera = b.iddespachopartecabecera
				     group by b.idparte
										  
						)
					loop 	
		       
						sp_elementoparte	:= 0;
					
						select coalesce(sum(a.costo * rec_ordtot.cantidad),0)
						  into sp_elementoparte
						  from mct_ordentrabajorepuesto a 
						 where a.idordentrabajorepuesto = rec_ordtot.idparte;
											
						sp_totalelemento := sp_totalelemento + sp_elementoparte;	
					
					    raise notice '%', rec_ordtot.idparte||' - '||rec_ordtot.cantidad||' - '||sp_totalelemento||' - '||sp_elementoparte;
			
					END LOOP;	
				
					cantidadot		:= sp_cantidadtot + sp_cantidadtot_ed;
				    totalbombas	    := sp_totalbomba;
				    totalrepuestos	:= sp_totalrepuesto;
				    totalelementos	:= sp_totalelemento +  sp_montotot;
				    totalotros		:= sp_totalotros;
				   
--							   	return next;
   
         end if;
        
         if ( rec_ord.idfamilia = 15 ) then
            -- otros
            select sum(costo * cantidad)
              into sp_totalotros
              from mct_ordentrabajorepuesto mo 
             where idordentrabajo in 
		            ( 
		           	  select distinct(c.idordentrabajo)
						from mct_despachopartecabecera a,
						     mct_ordentrabajo c
						where c.idordentrabajo = idworkorders
						  and a.idordentrabajo = c.idordentrabajo 
						  and c.idordentrabajo >= 30000
						  and c.idfamilia = rec_ord.idfamilia
		            );
            
            sp_totalotros := sp_totalotros + rec_ord.monto;
            
         
         end if;
 

	END LOOP;	

	cantidadot		:= sp_cantidadtot;
    totalbombas	    := sp_totalbomba;
    totalrepuestos	:= sp_totalrepuesto;
    totalelementos	:= sp_totalelemento;
    totalotros		:= sp_totalotros;
   
   	return next;

END;
$$;


