--

CREATE FUNCTION traking.evtlistdatedispatchotunica_porplano(planos character varying) RETURNS TABLE(cantidadot bigint, totalbombas bigint, totalrepuestos bigint, totalelementos bigint, totalotros bigint)
    LANGUAGE plpgsql
    AS $$
declare

    rec_ord          	record;
    rec_ordtot          record;
   
    sp_cantidadtot		bigint;
    sp_montotot			bigint;
    sp_totalbomba		bigint;
    sp_totalrepuesto	bigint;
    sp_totalelemento	bigint;
    sp_totalotros		bigint;
   
    sp_elementoparte	bigint;
    sp_cantidadtot_ed   bigint;
   
BEGIN

	sp_cantidadtot		:= 0;
    sp_montotot			:= 0;
    sp_totalbomba		:= 0;
    sp_totalrepuesto	:= 0;
    sp_totalelemento	:= 0;
    sp_totalotros		:= 0;
    sp_cantidadtot_ed	:= 0;
   

	FOR rec_ord IN (   
	  		select count(distinct(c.idordentrabajo) ) as ots,
	  		       coalesce (sum(c.montorepfab) , 0) as monto,
	  		       c.idfamilia as idfamilia
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_producto d
			where a.idordentrabajo = c.idordentrabajo
			  and c.idordentrabajo >= 30000
			  and c.idproducto = d.idproducto
			  and d.planogeneral like '%'||planos||'%'
		    group by c.idfamilia
			)
		loop 	
   
		     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
		    
	         if ( rec_ord.idfamilia = 8 ) then
                -- bombas
	            sp_totalbomba := sp_totalbomba + rec_ord.monto;
	
	         
	         end if;
	        
	         if ( rec_ord.idfamilia = 14 ) then
	            -- bombas
	            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
	
	         
	         end if;
	        
	         if ( rec_ord.idfamilia = 10 ) then
	            -- repuestos
	            select sum(costo * cantidad)
	              into sp_totalrepuesto
	              from mct_ordentrabajorepuesto mo 
	             where idordentrabajo in 
			            ( 
			           	  select distinct(c.idordentrabajo)
							from mct_despachopartecabecera a,
							     mct_ordentrabajo c,
			     				 mct_producto d
			                where a.idordentrabajo = c.idordentrabajo
							  and c.idordentrabajo >= 30000
							  and c.idfamilia = rec_ord.idfamilia
							  and c.idproducto = d.idproducto
							  and d.planogeneral like '%'||planos||'%'
			            );
	            
	            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
	         
	         end if;
	        
	         if ( rec_ord.idfamilia = 11 ) then
	            -- elemnetos
	        
				select sum(tabla.ots) as ots,
			           sum(tabla.monto) as monto
				       --tabla.idfamilia as idfamilia
				  into sp_cantidadtot_ed,
				       sp_montotot
				  from (
						select count(distinct(c.idordentrabajo) ) as ots,
						       coalesce (sum(c.montorepfab) , 0) as monto,
						       c.idfamilia as idfamilia
						  from mct_despachopartecabecera a,
					  	       mct_ordentrabajo c,
			                   mct_producto d
						 where a.idordentrabajo = c.idordentrabajo
						   and c.idordentrabajo >= 30000
						   and c.idfamilia = 11
						   and c.idproducto = d.idproducto
						   and d.planogeneral like '%'||planos||'%'
						   group by c.idfamilia
					   ) as tabla
				  group by tabla.idfamilia;
								   
				FOR rec_ordtot IN (   
						    
						select b.idparte        as idparte, 
						       sum(b.qdespacho) as cantidad
						  from mct_despachopartecabecera a,
						       mct_despachopartedetalle b, 
							   mct_ordentrabajo c,
			                   mct_producto d
					 	 where a.idordentrabajo = c.idordentrabajo
						   and c.idordentrabajo >= 30000
						   and c.idfamilia = 11
						   and a.iddespachopartecabecera = b.iddespachopartecabecera
						   and c.idproducto = d.idproducto
						   and d.planogeneral like '%'||planos||'%'
					     group by b.idparte
											  
							)
						loop 	
			       
							sp_elementoparte	:= 0;
						
							select coalesce(sum(a.costo * rec_ordtot.cantidad),0)
							  into sp_elementoparte
							  from mct_ordentrabajorepuesto a 
							 where a.idordentrabajorepuesto = rec_ordtot.idparte;
												
							sp_totalelemento := sp_totalelemento + sp_elementoparte;	
						
						    raise notice '%', rec_ordtot.idparte||' - '||rec_ordtot.cantidad||' - '||sp_totalelemento||' - '||sp_elementoparte;
				
						END LOOP;	
					
						cantidadot		:= sp_cantidadtot + sp_cantidadtot_ed;
					    totalbombas	    := sp_totalbomba;
					    totalrepuestos	:= sp_totalrepuesto;
					    totalelementos	:= sp_totalelemento +  sp_montotot;
					    totalotros		:= sp_totalotros;
					   
	--							   	return next;
	   
	         end if;
	        
	         if ( rec_ord.idfamilia = 15 ) then
	            -- otros
	            select sum(costo * cantidad)
	              into sp_totalotros
	              from mct_ordentrabajorepuesto mo 
	             where idordentrabajo in 
			            ( 
			           	  select distinct(c.idordentrabajo)
							from mct_despachopartecabecera a,
							     mct_ordentrabajo c,
			                     mct_producto d
							where a.idordentrabajo = c.idordentrabajo 
							  and c.idordentrabajo >= 30000
							  and c.idfamilia = rec_ord.idfamilia
							  and c.idproducto = d.idproducto
							  and d.planogeneral like '%'||planos||'%'
			            );
	            
	            sp_totalotros := sp_totalotros + rec_ord.monto;
	            
	         
	         end if;
 

	END LOOP;	

	cantidadot		:= sp_cantidadtot;
    totalbombas	    := sp_totalbomba;
    totalrepuestos	:= sp_totalrepuesto;
    totalelementos	:= sp_totalelemento;
    totalotros		:= sp_totalotros;
   
   	return next;

END;
$$;


