CREATE FUNCTION traking.evtlistdatedispatchotunica_sq(startdate character varying, enddate character varying, idfamilys bigint) RETURNS TABLE(cantidadot bigint, totalbombas bigint, totalrepuestos bigint, totalelementos bigint, totalotros bigint)
    LANGUAGE plpgsql
    AS $$
declare

    rec_ord          	record;
    rec_ordtot          record;
   
    sp_cantidadtot		bigint;
    sp_montotot			bigint;
    sp_totalbomba		bigint;
    sp_totalrepuesto	bigint;
    sp_totalelemento	bigint;
    sp_totalotros		bigint;
   
    sp_elementoparte	bigint;
   
BEGIN

	sp_cantidadtot		:= 0;
    sp_montotot			:= 0;
    sp_totalbomba		:= 0;
    sp_totalrepuesto	:= 0;
    sp_totalelemento	:= 0;
    sp_totalotros		:= 0;
   
	if ( idfamilys = 24 ) then
	
				FOR rec_ord IN (   
				  		select count(distinct(c.idordentrabajo) ) as ots,
				  		       coalesce (sum(c.montorepfab) , 0) as monto,
				  		       c.idfamilia as idfamilia
						from mct_despachopartecabecera a,
						     mct_ordentrabajo c
						where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
