					     mct_subfamilia j,
					     mct_etapaparam k
					where (a.fechaguia >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
					  and a.idordentrabajo = c.idordentrabajo
					  and c.idcliente = d.idcliente
					  and c.idestadoorden = e.idestadoorden
					  and c.idtipoorden = f.idtipoorden 
					  and c.idfamilia = g.idfamilia 
					  and c.idordentrabajo >= 30000
					  and c.idproducto = h.idproducto
					  and h.idmodelo = i.idmodelo
					  and i.idsubfamilia = j.idsubfamilia 
					  and h.idetapaparam = k.idetapaparam 
					  and c.idfamilia = 14
					 group by c.idfamilia 
						   
							)
				loop 	
	       
				     sp_cantidadtot := sp_cantidadtot + rec_ord.ots;
				    
			        
			         if ( rec_ord.idfamilia = 14 ) then
                        -- repuestos
			            select sum(costo)
			              into sp_totalrepuesto
			              from mct_ordentrabajorepuesto mo 
			             where idordentrabajo in 
					            ( 
					           	  select distinct(c.idordentrabajo)
									from mct_despachopartecabecera a,
									     mct_ordentrabajo c,
									     mct_cliente d,
									     mct_estadoorden e,
									     mct_tipoorden f,
									     mct_familia g,
									     mct_producto h,
									     mct_modelo i,
									     mct_subfamilia j,
									     mct_etapaparam k
									where (a.fechadespacho >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
									  and a.idordentrabajo = c.idordentrabajo
									  and c.idcliente = d.idcliente
									  and c.idestadoorden = e.idestadoorden
									  and c.idtipoorden = f.idtipoorden 
									  and c.idfamilia = g.idfamilia 
									  and c.idordentrabajo >= 30000
									  and c.idproducto = h.idproducto
									  and h.idmodelo = i.idmodelo
									  and i.idsubfamilia = j.idsubfamilia 
									  and h.idetapaparam = k.idetapaparam 
									  and c.idfamilia = rec_ord.idfamilia
					            );
			            
			            sp_totalrepuesto := sp_totalrepuesto + rec_ord.monto;
			         
			         end if;
			        			 
		
				END LOOP;	
			
				cantidadot		:= sp_cantidadtot;
			    totalbombas	    := sp_totalbomba;
			    totalrepuestos	:= sp_totalrepuesto;
			    totalelementos	:= sp_totalelemento;
			    totalotros		:= sp_totalotros;
			   
			   	return next;
	
	end if;

END;
$$;


ALTER FUNCTION traking.evtlistdatedispatchotunica_test(startdate character varying, enddate character varying, idfamilys bigint) OWNER TO postgres;

--
-- TOC entry 2154 (class 1255 OID 16960)
-- Name: evtlistdefectofundicion(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdefectofundicion(idot bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, iddefectofundicion bigint, codhojaruta character varying, nombrecomponente character varying, planocomponente character varying, equipo character varying, planogeneral character varying, critica character varying, sigla character varying, material character varying, cantidad bigint, repetitividad bigint, comentariofundicion character varying, idestadodefecto bigint, idusuario bigint, nombreusuario character varying, iddefecto bigint, nombredefecto character varying, idmaquina bigint, nombremaquina character varying, idsubseccion bigint, nombresubseccion character varying, iddefectofundicionorigen bigint, nombredefectofundicionorigen character varying, usuariocreacion character varying, fechacreacion character varying, usuariomodificacion character varying, fechamodificacion timestamp without time zone, idcierre bigint, correlativo bigint, iddebaja bigint, nombredebaja character varying, iddetectadefecto bigint, nombredetectadefecto character varying, imagen text, urgente boolean, dardebaja boolean, observacion character varying, defectovalidado boolean, fechavalidaciondefecto character varying, idtipodefecto bigint, nombretipodefecto character varying, descripciongeneraldefecto character varying, pendientecarga boolean, atrasovalidacion boolean, atrasocarga boolean, jsontipodefecto character varying, fechavencimiento character varying, nota bigint)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;
    
    sp_totalrespaldos 	bigint;
    sp_totalcargas		bigint;
   
    sp_horas			bigint;
    sp_atrasocarga		bigint;
    sp_diasem			bigint;
   
    sp_fechavenc		varchar;

BEGIN
-- iddefectoi = -1: Todos
     
	     
		 IF ( idot > 0 ) 
	     THEN 
	     -- Todos
	      		--RETURN QUERY
	      		
	      	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.iddefectofundicion,
								a.codhojaruta,
								h.idcomponente ,
								i.nombrecomponente ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
							    cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
							    case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
								a.idusuario,
								c.nombre as nombreusuario,
								a.iddefecto,
								e.nombre  as nombredefecto,
								a.idmaquina,
								d.nombremaquina,
								a.idsubseccion,
								b.nombresubseccion,
								a.iddefectofundicionorigen ,
								f.nombre ,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2, 
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								a.idcierre,
								a.correlativo,
								k.idordentrabajo ,
								a.comentariofundicion ,
								a.idestadodefecto ,
								a.iddebaja ,
								r.nombredebaja ,
								a.iddetectadefecto ,
								s.nombredetectadefecto ,
								q.archivoadjunto ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.defectovalidado ,
								cast(to_char(a.fechavalidaciondefecto , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciondefecto,
								a.idtipodefecto ,
								t.nombretipodefecto,
								a.descripciongeneraldefecto,
								a.jsontipodefecto,
					            cast('' as varchar) as fechavencimiento,
					            a.nota 
				 	 	    FROM traking.mct_defectofundicion a
							left join  traking.mct_subseccion b on a.idsubseccion = b.idsubseccion 
							left join  traking.mct_usuario c  	on c.idusuario = a.idusuario 
							left join  traking.mct_maquina d   	on d.idmaquina = a.idmaquina 
							left join  traking.mct_defecto e   	on e.iddefecto = a.iddefecto 
							left join  traking.mct_defectofundicionorigen f on a.iddefectofundicionorigen  = f.iddefectofundicionorigen 
							left join  traking.mct_detallehojarutatemp g 	on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	 on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	 on h.idcomponente = i.idcomponente 
							left join  traking.mct_material j 		 on h.idmaterial = j.idmaterial 
							left join  traking.mct_ordentrabajo k 	 on h.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		 on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		 on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	 on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o         on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p on replace(l.planogeneral,' ','') = p.plano 
							left join  traking.mct_defectofundicionadjunto q on a.iddefectofundicion = q.iddefectofundicion  and q.correlativo = 0
							left join  traking.mct_debaja r			 on a.iddebaja = r.iddebaja 
							left join  traking.mct_detectadefecto s  on a.iddetectadefecto = s.iddetectadefecto 
							left join  traking.mct_tipodefecto   t   on a.idtipodefecto = t.idtipodefecto  
						   where a.idordentrabajo = idot
--						   (a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
--				            a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				        order by a.iddefecto, a.iddefectofundicion
					)
				loop
				
					sp_cantidad := 0;
--				    select count(*)
--				      into sp_cantidad
--				      from mct_defectofundicion md 
--				     where idcomponente = rec1.idcomponente;
--				    
				    select count(*)
				      into sp_cantidad
				      from mct_defectofundicion a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				        
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_defectofundicion a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
				
				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_defectofundicion a,
				           mct_defectocausa b,
				           mct_defectocausaaccion c,
				           mct_defectocausaaccionpdf d
				     where a.iddefectofundicion = rec1.iddefectofundicion
				       and a.iddefectofundicion = b.iddefectofundicion 
				       and b.iddefectocausa = c.iddefectocausa 
				       and c.iddefectocausaaccion = d.iddefectocausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_defectofundicion a,
				           mct_defectocausa b,
				           mct_defectocausaaccion c,
				           mct_defectocausaaccionpdf d
				     where a.iddefectofundicion = rec1.iddefectofundicion
				       and a.iddefectofundicion = b.iddefectofundicion 
				       and b.iddefectocausa = c.iddefectocausa 
				       and c.iddefectocausaaccion = d.iddefectocausaaccion
				       and (length(d.tipo) > 0);
   
				   
				         item 							:= rec1.item;
				         iddefectofundicion 			:= rec1.iddefectofundicion;
				         codhojaruta 					:= rec1.codhojaruta;
				         nombrecomponente 				:= rec1.nombrecomponente;
				         planocomponente 				:= rec1.planocomponente;
				         equipo 						:= rec1.equipo;
				         planogeneral 					:= rec1.planogeneral;
				         critica 						:= rec1.critica;
				         sigla 							:= rec1.sigla;
				         material 						:= rec1.nombrematerial;
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
				         comentariofundicion			:= rec1.comentariofundicion;
				         idestadodefecto				:= rec1.idestadodefecto;
				         idusuario 						:= rec1.idusuario;
				         nombreusuario 					:= rec1.nombreusuario; 
				         iddefecto 						:= rec1.iddefecto;
				         nombredefecto 					:= rec1.nombredefecto;
				         idmaquina 						:= rec1.idmaquina;
				         nombremaquina 					:= rec1.nombremaquina;
				         idsubseccion 					:= rec1.idsubseccion; 
				         nombresubseccion 				:= rec1.nombresubseccion; 
				         iddefectofundicionorigen 	  	:= rec1.iddefectofundicionorigen;
				         nombredefectofundicionorigen 	:= rec1.nombre; 
				         usuariocreacion				:= rec1.usuariocreacion;
				         fechacreacion 					:= rec1.fechacreacion; 
				         usuariomodificacion 			:= rec1.usuariomodificacion;
				         fechamodificacion 				:= rec1.fechamodificacion; 
				         idcierre 						:= rec1.idcierre; 
				         correlativo 					:= rec1.correlativo;
				         iddebaja 						:= rec1.iddebaja;
				         nombredebaja					:= rec1.nombredebaja;
				         iddetectadefecto 				:= rec1.iddetectadefecto;
				         nombredetectadefecto			:= rec1.nombredetectadefecto;
				         imagen							:= rec1.archivoadjunto;
				         urgente						:= rec1.urgente;
				         dardebaja						:= rec1.dardebaja;
				         observacion					:= rec1.observacion;
				         defectovalidado				:= rec1.defectovalidado;
				         fechavalidaciondefecto			:= rec1.fechavalidaciondefecto;
				        
				         idtipodefecto					:= rec1.idtipodefecto;
				         nombretipodefecto				:= rec1.nombretipodefecto;
				         descripciongeneraldefecto		:= rec1.descripciongeneraldefecto;
				        
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;   
				        
				        		 
				         atrasovalidacion	:= false;
				         if (rec1.defectovalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciondefecto)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriadefectovalido a,
						           mct_defectofundicion b
						     where b.iddefectofundicion = rec1.iddefectofundicion
						       and a.iddefectofundicion = b.iddefectofundicion ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;
						   
--						    if (sp_horas > 0) then
--						    	atrasovalidacion	:= true;						    
--						    end if;
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_defectocausa a,
				                mct_defectocausaaccion b,
				                mct_defectocausaaccionpdf c
				          where a.iddefectofundicion = rec1.iddefectofundicion
				            and a.iddefectocausa  = b.iddefectocausa 
				            and b.iddefectocausaaccion = c.iddefectocausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;
				         
				         jsontipodefecto	:= rec1.jsontipodefecto;
				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	:= sp_fechavenc;
                         --fechavencimiento	:= rec1.fechavencimiento;
						 nota 				:= rec1.nota;
         			
				return next;
			
				end loop;

				
		 elsif ( startdate != 'NA' and enddate != 'NA'  ) then
		 
		 		--RETURN QUERY
		 	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.iddefectofundicion,
								a.codhojaruta,
								h.idcomponente ,
								i.nombrecomponente ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
							    cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
							    case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
								a.idusuario,
								c.nombre as nombreusuario,
								a.iddefecto,
								e.nombre  as nombredefecto,
								a.idmaquina,
								d.nombremaquina,
								a.idsubseccion,
								b.nombresubseccion,
								a.iddefectofundicionorigen ,
								f.nombre ,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2,
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								a.idcierre,
								a.correlativo,
								k.idordentrabajo ,
								a.comentariofundicion  ,
								a.idestadodefecto  ,
								a.iddebaja ,
								r.nombredebaja ,
								a.iddetectadefecto ,
								s.nombredetectadefecto ,
								q.archivoadjunto  ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.defectovalidado ,
								cast(to_char(a.fechavalidaciondefecto , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciondefecto,
								a.idtipodefecto ,
								t.nombretipodefecto,
								a.descripciongeneraldefecto ,
								a.jsontipodefecto,
					            a.fechavencimiento,
					            a.nota 
				 	 	   FROM traking.mct_defectofundicion a
						left join  traking.mct_subseccion b on a.idsubseccion = b.idsubseccion 
						left join  traking.mct_usuario c  	on c.idusuario = a.idusuario 
						left join  traking.mct_maquina d   	on d.idmaquina = a.idmaquina 
						left join  traking.mct_defecto e   	on e.iddefecto = a.iddefecto 
						left join  traking.mct_defectofundicionorigen f on a.iddefectofundicionorigen  = f.iddefectofundicionorigen 
						left join  traking.mct_detallehojarutatemp g 	on a.codhojaruta = g.codhojaruta 
						left join  traking.mct_hojarutatemp h 	 on g.idhojarutatemp = h.idhojarutatemp 
						left join  traking.mct_componente i 	 on h.idcomponente = i.idcomponente 
						left join  traking.mct_material j 		 on h.idmaterial = j.idmaterial 
						left join  traking.mct_ordentrabajo k 	 on h.idordentrabajo = k.idordentrabajo 
						left join  traking.mct_producto l 		 on k.idproducto = l.idproducto 
						left join  traking.mct_modelo m 		 on l.idmodelo = m.idmodelo 
						left join  traking.mct_subfamilia n 	 on m.idsubfamilia = n.idsubfamilia 
					    left join  traking.mct_familia o         on n.idfamilia = o.idfamilia 
						left join  traking.mct_planobbacritica p on replace(l.planogeneral,' ','') = p.plano 
						left join  traking.mct_defectofundicionadjunto q on a.iddefectofundicion = q.iddefectofundicion  and q.correlativo = 0
						left join  traking.mct_debaja r			 on a.iddebaja = r.iddebaja 
						left join  traking.mct_detectadefecto s  on a.iddetectadefecto = s.iddetectadefecto 
						left join  traking.mct_tipodefecto   t   on a.idtipodefecto = t.idtipodefecto 
				 	  	where 
				 	  	    (a.fechavencimiento  >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				            a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				            --and
				 	  	    --a.iddefectofundicion = iddefectofuncioni
				 	  	    )
				 	loop 

					sp_cantidad := 0;
--				    select count(*)
--				      into sp_cantidad
--				      from mct_defectofundicion md 
--				     where idcomponente = rec1.idcomponente;
--				    
				    select count(*)
				      into sp_cantidad
				      from mct_defectofundicion a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				      
				     
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_defectofundicion a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
						

				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_defectofundicion a,
				           mct_defectocausa b,
				           mct_defectocausaaccion c,
				           mct_defectocausaaccionpdf d
				     where a.iddefectofundicion = rec1.iddefectofundicion
				       and a.iddefectofundicion = b.iddefectofundicion 
				       and b.iddefectocausa = c.iddefectocausa 
				       and c.iddefectocausaaccion = d.iddefectocausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_defectofundicion a,
				           mct_defectocausa b,
				           mct_defectocausaaccion c,
				           mct_defectocausaaccionpdf d
				     where a.iddefectofundicion = rec1.iddefectofundicion
				       and a.iddefectofundicion = b.iddefectofundicion 
				       and b.iddefectocausa = c.iddefectocausa 
				       and c.iddefectocausaaccion = d.iddefectocausaaccion
				       and (length(d.tipo) > 0);
				      
				         item 							:= rec1.item;
				         iddefectofundicion 			:= rec1.iddefectofundicion;
				         codhojaruta 					:= rec1.codhojaruta;
				         nombrecomponente 				:= rec1.nombrecomponente;
				         planocomponente 				:= rec1.planocomponente;
				         equipo 						:= rec1.equipo;
				         planogeneral 					:= rec1.planogeneral;
				         critica 						:= rec1.critica;
				         sigla 							:= rec1.sigla;
				         material 						:= rec1.nombrematerial;
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
				         comentariofundicion			:= rec1.comentariofundicion;
						 idestadodefecto				:= rec1.idestadodefecto;
						 idusuario 						:= rec1.idusuario;
						 nombreusuario 					:= rec1.nombreusuario; 
						 iddefecto 						:= rec1.iddefecto;
						 nombredefecto 					:= rec1.nombredefecto;
						 idmaquina 						:= rec1.idmaquina;
						 nombremaquina 					:= rec1.nombremaquina;
						 idsubseccion 					:= rec1.idsubseccion; 
						 nombresubseccion 				:= rec1.nombresubseccion; 
						 iddefectofundicionorigen 	  	:= rec1.iddefectofundicionorigen;
						 nombredefectofundicionorigen 	:= rec1.nombre; 
						 usuariocreacion			  	:= rec1.usuariocreacion;
						 fechacreacion 					:= rec1.fechacreacion; 
						 usuariomodificacion 			:= rec1.usuariomodificacion;
						 fechamodificacion 				:= rec1.fechamodificacion; 
						 idcierre 						:= rec1.idcierre; 
						 correlativo 					:= rec1.correlativo;
				         iddebaja 						:= rec1.iddebaja;
				         nombredebaja					:= rec1.nombredebaja;
				         iddetectadefecto 				:= rec1.iddetectadefecto;
				         nombredetectadefecto			:= rec1.nombredetectadefecto;
				         imagen							:= rec1.archivoadjunto;
				         urgente						:= rec1.urgente;
						 dardebaja						:= rec1.dardebaja;
						 observacion					:= rec1.observacion;
						 defectovalidado				:= rec1.defectovalidado;
				         fechavalidaciondefecto			:= rec1.fechavalidaciondefecto;
				                
				         idtipodefecto					:= rec1.idtipodefecto;
				         nombretipodefecto				:= rec1.nombretipodefecto;
				         descripciongeneraldefecto		:= rec1.descripciongeneraldefecto;
				        		
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;      
				        
				         atrasovalidacion	:= false;
				         if (rec1.defectovalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciondefecto)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriadefectovalido a,
						           mct_defectofundicion b
						     where b.iddefectofundicion = rec1.iddefectofundicion
						       and a.iddefectofundicion = b.iddefectofundicion ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;						   
--						    if (sp_horas > 0) then
--						    	atrasovalidacion	:= true;						    
--						    end if;
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_defectocausa a,
				                mct_defectocausaaccion b,
				                mct_defectocausaaccionpdf c
				          where a.iddefectofundicion = rec1.iddefectofundicion
				            and a.iddefectocausa  = b.iddefectocausa 
				            and b.iddefectocausaaccion = c.iddefectocausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;			
				        
				         jsontipodefecto	:= rec1.jsontipodefecto;
				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	:= sp_fechavenc;
                         --fechavencimiento	:= rec1.fechavencimiento;
						 nota 				:= rec1.nota;
				 	
				 	return next;
				 
				 	end loop;
		     end if;
		 
END;
$$;


ALTER FUNCTION traking.evtlistdefectofundicion(idot bigint, startdate character varying, enddate character varying) OWNER TO postgres;

