-- Name: evtlistdeffunscandata(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdeffunscandata(scancode character varying) RETURNS TABLE(idworkorder bigint, idcomponent bigint, idclient bigint, idproduct bigint, productname character varying, customername character varying, componentname character varying, iddefectofundicion bigint, iddefecto bigint, idsubseccion bigint, idmaquina bigint, iddebaja bigint, iddetectadefecto bigint, iddefectofundicionorigen bigint, idcierre bigint, urgente boolean, dardebaja boolean, observacion character varying)
    LANGUAGE plpgsql
    AS $$
declare

	sp_producto		integer;
    sp_idot			integer;
begin
	
	sp_producto	:= 0;
    sp_idot		:= 0;

	select idproducto 
	  into sp_producto
	  from mct_ordentrabajo mo 
	 where idordentrabajo = to_number(substring(scancode, 2, 5), '99999');

	if ( sp_producto in (10,11,12,13,14,15,16,17) ) then
	
		return QUERY
		select  
				d.idordentrabajo,
				c.idcomponente,
				e.idcliente,
				d.idproducto,
				f.nombreproductonepcast ,
				e.nombrecliente, 
		        c.nombrecomponente,   
		        coalesce(g.iddefectofundicion ,0) as iddefectofundicion,
		        coalesce(g.iddefecto ,0) as iddefecto,
--		        case 
--		           when g.idcierre = 0 then coalesce(g.idsubseccion,0)
--		           else 0
--		        end as idsubseccion,
		        coalesce(g.idsubseccion,0),
		        coalesce(g.idmaquina ,0) as idmaquina,
		        coalesce(g.iddebaja ,0) as iddebaja,
		        coalesce(g.iddetectadefecto ,0) as iddetectadefecto,
		        coalesce(g.iddefectofundicionorigen,0) ,
		        coalesce(g.idcierre,0) ,
		        g.urgente ,
		        g.dardebaja ,
		        g.observacion 	        
		  from mct_detallehojarutatemp a,
		       mct_hojarutatemp b,
		       mct_componente c,
		       mct_ordentrabajo d,
		       mct_cliente e,
		       mct_productonepcast f
		--left join  traking.mct_defectofundicion g on (  g.codhojaruta = '03108613309001' and g.idcierre = 0 )
		left join  traking.mct_defectofundicion g on (  g.codhojaruta = scancode and g.iddefectofundicion = (select max(b.iddefectofundicion) from mct_defectofundicion b where b.codhojaruta = scancode ) )
		where a.codhojaruta = scancode
		   and a.idhojarutatemp = b.idhojarutatemp 
		   and b.idcomponente = c.idcomponente
		   and b.idordentrabajo = d.idordentrabajo 
		   and e.idcliente = d.idcliente 
		   and f.idproductonepcast = d.idproducto
		   ;	
	
	else
	
		return QUERY
		
		select  
				d.idordentrabajo,
				c.idcomponente,
				e.idcliente,
				f.idproducto,
				f.nombreproducto,
				e.nombrecliente, 
		        c.nombrecomponente,   
		        coalesce(g.iddefectofundicion ,0) as iddefectofundicion,
		        coalesce(g.iddefecto ,0) as iddefecto,
--		        case 
--		           when g.idcierre = 0 then coalesce(g.idsubseccion,0)
--		           else 0
--		        end as idsubseccion,
		        coalesce(g.idsubseccion,0),
		        coalesce(g.idmaquina ,0) as idmaquina,
		        coalesce(g.iddebaja ,0) as iddebaja,
		        coalesce(g.iddetectadefecto ,0) as iddetectadefecto,
		        coalesce(g.iddefectofundicionorigen,0) ,
		        coalesce(g.idcierre,0) ,
		        g.urgente ,
		        g.dardebaja ,
		        g.observacion 	        
		  from mct_detallehojarutatemp a,
		       mct_hojarutatemp b,
		       mct_componente c,
		       mct_ordentrabajo d,
		       mct_cliente e,
		       mct_producto f
		--left join  traking.mct_defectofundicion g on (  g.codhojaruta = '03108613309001' and g.idcierre = 0 )
		left join  traking.mct_defectofundicion g on (  g.codhojaruta = scancode and g.iddefectofundicion = (select max(b.iddefectofundicion) from mct_defectofundicion b where b.codhojaruta = scancode ) )
		where a.codhojaruta = scancode
		   and a.idhojarutatemp = b.idhojarutatemp 
		   and b.idcomponente = c.idcomponente
		   and b.idordentrabajo = d.idordentrabajo 
		   and e.idcliente = d.idcliente 
		   and f.idproducto = d.idproducto
		   ;	
	
	
	end if;



   END;
$$;


