--
-- TOC entry 2083 (class 1255 OID 16970)
-- Name: evtlistdesgastegrafico(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdesgastegrafico(idfamily bigint, startdate character varying, enddate character varying) RETURNS TABLE(texto character varying, dato bigint)
    LANGUAGE plpgsql
    AS $$
    
BEGIN 
	
	if ( idfamily = 8 ) then

		return QUERY
	
--			select f.nombrecorto ,       
--			       cast(sum(a.montorepfab) as bigint)
--			  from mct_ordentrabajo a
--			  left join  mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
--	          left join  mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
--			  left join  mct_despachopartedetalle d on c.iddespachopartecabecera = d.iddespachopartecabecera and b.idordentrabajorepuesto = d.idordentrabajoparte
--			  left join	 mct_cliente f on a.idcliente = f.idcliente
--			 where a.fechaentrega >= to_date('2021-01-01','yyyy-mm-dd') 
--			   and a.fechaentrega <= to_date('2021-10-03','yyyy-mm-dd') 
--			   and a.idfamilia = 8 
--			   and a.idordentrabajo >= 30000
--			   group by f.nombrecorto; 
		
			select 
			       f.nombrecorto ,       
			       cast(sum(b.costo*d.qdespacho) as bigint)
			  from mct_ordentrabajo a
			  left join  mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
	          left join  mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			  left join  mct_despachopartedetalle d on c.iddespachopartecabecera = d.iddespachopartecabecera and b.idordentrabajorepuesto = d.idordentrabajoparte
			   join	 mct_cliente f on a.idcliente = f.idcliente
			 where c.fechadespacho >= to_date(startdate,'yyyy-mm-dd') 
			   and c.fechadespacho <= to_date(enddate,'yyyy-mm-dd') 
			   and a.idfamilia = 8 
			   and a.idordentrabajo >= 30000
			   --and a.idcliente = 83
			   group by f.nombrecorto; 				  
			  
	else

		return QUERY
	
--			select d.nombrecorto ,       
--			       cast(sum(b.costo) as bigint)
--			  from mct_ordentrabajo a,
--			       mct_ordentrabajorepuesto b,
--			       mct_cliente d
--			 where a.fechaentrega >= to_date(startdate,'yyyy-mm-dd') 
--			   and a.fechaentrega <= to_date(enddate,'yyyy-mm-dd') 
--			   and a.idfamilia = idfamily
--			   and a.idordentrabajo = b.idordentrabajo 
--			   and a.idcliente = d.idcliente  
--			   group by d.nombrecorto; 
			  
			select f.nombrecorto ,       
			       cast(sum(b.costo*d.qdespacho) as bigint)
			  from mct_ordentrabajo a
			  left join  mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
	          left join  mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo
			  left join  mct_despachopartedetalle d on c.iddespachopartecabecera = d.iddespachopartecabecera and b.idordentrabajorepuesto = d.idordentrabajoparte
			   join	 mct_cliente f on a.idcliente = f.idcliente
			 where c.fechadespacho >= to_date(startdate,'yyyy-mm-dd') 
			   and c.fechadespacho <= to_date(enddate,'yyyy-mm-dd') 
			   and a.idfamilia = idfamily 
			   and a.idordentrabajo >= 30000
			   --and a.idcliente = 83
			   group by f.nombrecorto; 			  
			  
	end if;
				  
END;
$$;


