--
-- TOC entry 1369 (class 1255 OID 16971)
-- Name: evtlistdesgastegraficobarra(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdesgastegraficobarra(idfamily bigint, startdate character varying, enddate character varying) RETURNS TABLE(id bigint, mesano character varying, cliente character varying, monto bigint)
    LANGUAGE plpgsql
    AS $$
declare

	sp_idcliente    integer;
	sp_periodo		varchar;
	sp_mes			integer;

	rec_per         RECORD;
	rec_mes         RECORD;	

	sal_periodo		varchar;
	sal_ano			integer;
	sal_mes			integer;
	sal_cliente		varchar;
	sal_monto 		integer;    
					    
    
BEGIN 
	
	if ( idfamily = 8 ) then

	   FOR rec_per IN (   
	   				-- Paso 1
	 				   select distinct d.nombrecorto, 
	 				          d.idcliente
						 from mct_ordentrabajo a
					     left join mct_cliente d on a.idcliente = d.idcliente
					     left join mct_despachopartecabecera c on a.idordentrabajo = c.idordentrabajo 
					    where c.fechadespacho >= to_date(startdate,'yyyy-mm-dd') 
					      and c.fechadespacho <= to_date(enddate,'yyyy-mm-dd') 
					      and a.idfamilia = idfamily
					    order by d.idcliente asc
         		       )
					
	   		loop 

	   			   FOR rec_mes IN (  
	   			   	   -- Paso 2
					   select * from (   
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '5 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '5 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '5 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '4 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '4 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '4 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '3 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '3 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '3 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '2 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '2 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '2 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '1 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '1 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '1 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '0 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '0 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '0 month', 'Mon') as mespar
								) tabla
						order by 1 asc	   			   
	   			                  )
	   			       loop 
						   sal_periodo	:= '';
						   sal_ano		:= 0;
						   sal_mes		:= 0;
						   sal_cliente	:= '';
						   sal_monto 	:= 0;
							      
	   			       	   -- Paso 3
	--					   select to_char(a.fechaentrega, 'Mon-yyyy') , 
	--						      cast(to_char(a.fechaentrega, 'yyyy') as bigint),
	--						      cast(to_char(a.fechaentrega, 'MM') as bigint),
	--						      d.nombrecorto , 
	--						      coalesce (cast(sum(a.montorepfab) as bigint), 0)
	--						 into sal_periodo,
	--						      sal_ano,
	--						      sal_mes,
	--						      sal_cliente,
	--						      sal_monto
	--						 from mct_ordentrabajo a
	--				  	     left join mct_cliente d on a.idcliente = d.idcliente
	--		   	     		where to_char(a.fechaentrega, 'yyyy-MM') = rec_mes.periodo
	--		   	     		  and a.idcliente = rec_per.idcliente
	--				  	      and a.idfamilia = idfamily
	--			  	       group by to_char(a.fechaentrega, 'Mon-yyyy'), 
	--					            d.nombrecorto ,  
	--					            cast(to_char(a.fechaentrega, 'yyyy') as bigint), 
	--				                to_char(a.fechaentrega, 'MM'), 
	--				                to_char(a.fechaentrega, 'yyyy-MM')
	--			  	       order by d.nombrecorto asc ,to_char(a.fechaentrega, 'yyyy-MM') asc;	  
				  	      
				  	       select    
			      				 d.nombrecorto ,       
			       				cast(sum(b.costo*h.qdespacho) as bigint)
			       			into
			       			   sal_cliente,
			       			   sal_monto
			       			
			  				from mct_ordentrabajo a
			 					left join  mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
			  					left join  mct_cliente d on a.idcliente = d.idcliente
			  					left join  mct_despachopartecabecera g on a.idordentrabajo = g.idordentrabajo
			  					left join  mct_despachopartedetalle h on g.iddespachopartecabecera = h.iddespachopartecabecera 
			            					 and b.idordentrabajorepuesto = h.idordentrabajoparte
							where  
							     to_char(g.fechadespacho, 'yyyy-MM') = rec_mes.periodo
								 and   g.fechadespacho <= to_date(enddate,'yyyy-mm-dd') 
								 and a.idcliente = rec_per.idcliente
								 and a.idfamilia = idfamily
								 and a.idordentrabajo >= 30000
								 group by d.nombrecorto;
	  	      
	   			    
				  	       id		:= idfamily;
				  	       mesano	:= rec_mes.periodo;
                           cliente	:= rec_per.nombrecorto;
                           monto	:= coalesce(sal_monto,0);  
          	   	   
	   			       	   RETURN next;
	   			       	   	    				  
				   END LOOP;	
	   			     
	   END LOOP;		
	
	
	else
	
	   FOR rec_per IN (   
	   				-- Paso 1
	 				   select distinct d.nombrecorto, 
	 				          d.idcliente
						 from mct_ordentrabajo a
						 left join mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
					     left join mct_cliente d on a.idcliente = d.idcliente
					     left join mct_despachopartecabecera e on a.idordentrabajo = e.idordentrabajo 
					    where a.fechaentrega >= to_date(startdate,'yyyy-mm-dd') 
					      and a.fechaentrega <= to_date(enddate,'yyyy-mm-dd') 
					      and a.idfamilia = idfamily   
					    order by d.idcliente asc
         		       )
					
	   		loop 

	   			   FOR rec_mes IN (  
	   			   	   -- Paso 2
					   select * from (   
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '5 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '5 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '5 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '4 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '4 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '4 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '3 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '3 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '3 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '2 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '2 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '2 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '1 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '1 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '1 month', 'Mon') as mespar
								union 
								select to_char(to_date(enddate,'yyyy-mm-dd') - interval '0 month', 'yyyy-MM') as periodo, to_char(to_date(enddate,'yyyy-mm-dd') - interval '0 month', 'MM') as mes, to_char(to_date(enddate,'yyyy-mm-dd') - interval '0 month', 'Mon') as mespar
								) tabla
						order by 1 asc	   			   
	   			                  )
	   			       loop 
						   sal_periodo	:= '';
						   sal_ano		:= 0;
						   sal_mes		:= 0;
						   sal_cliente	:= '';
						   sal_monto 	:= 0;
							      
	   			       	   -- Paso 3
						--  select to_char(a.fechaentrega, 'Mon-yyyy') , 
						--	      cast(to_char(a.fechaentrega, 'yyyy') as bigint),
						--	      cast(to_char(a.fechaentrega, 'MM') as bigint),
						--	      d.nombrecorto , 
						--	      coalesce (cast(sum(b.costo) as bigint), 0)
						--	 into sal_periodo,
						--	      sal_ano,
						--	      sal_mes,
						--	      sal_cliente,
						--	      sal_monto
						--	 from mct_ordentrabajo a
						--     left join mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo 
					  	--     left join mct_cliente d on a.idcliente = d.idcliente
			   	     	--	where to_char(a.fechaentrega, 'yyyy-MM') = rec_mes.periodo
						--		  -- and a.fechacreacion <= to_date(enddate,'yyyy-mm-dd') 
			   	     	--	  and a.idcliente = rec_per.idcliente
					  	--      and a.idfamilia = idfamily
						     -- and a.idordentrabajo = b.idordentrabajo 
						      --and a.idcliente = d.idcliente  
				  	    --   group by to_char(a.fechaentrega, 'Mon-yyyy'), 
						--            d.nombrecorto ,  
						--            cast(to_char(a.fechaentrega, 'yyyy') as bigint), 
					    --            to_char(a.fechaentrega, 'MM'), 
					    --            to_char(a.fechaentrega, 'yyyy-MM')
				  	    --   order by d.nombrecorto asc ,to_char(a.fechaentrega, 'yyyy-MM') asc;	   	
				  	      
				  	       select    
			      				 d.nombrecorto ,       
			       				cast(sum(b.costo*h.qdespacho) as bigint)
			       			into
			       			   sal_cliente,
			       			   sal_monto
			       			
			  				from mct_ordentrabajo a
			 					left join  mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
			  					left join  mct_cliente d on a.idcliente = d.idcliente
			  					left join  mct_despachopartecabecera g on a.idordentrabajo = g.idordentrabajo
			  					left join  mct_despachopartedetalle h on g.iddespachopartecabecera = h.iddespachopartecabecera 
			            					 and b.idordentrabajorepuesto = h.idordentrabajoparte
							where  
							     to_char(g.fechadespacho, 'yyyy-MM') = rec_mes.periodo
								 and g.fechadespacho <= to_date(enddate,'yyyy-mm-dd') 
								 and a.idcliente = rec_per.idcliente
								 and a.idfamilia = idfamily
								 and a.idordentrabajo >= 30000
								 group by d.nombrecorto;
								  			    
				  	       id		:= idfamily;
				  	       mesano	:= rec_mes.periodo;
                           cliente	:= rec_per.nombrecorto;
                           monto	:= coalesce(sal_monto,0);  
          	   	   
	   			       	   RETURN next;
	   			       	   	    				  
				   END LOOP;	
	   			     
	   END LOOP;		
	
	end if;

	

END;
$$;


ALTER FUNCTION traking.evtlistdesgastegraficobarra(idfamily bigint, startdate character varying, enddate character varying) OWNER TO postgres;

--
-- TOC entry 1457 (class 1255 OID 16973)
-- Name: evtlistdetasolcomp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistdetasolcomp(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idpart bigint, partname character varying, blueprintname character varying, quantity bigint, soldate text, soltime text, reqdate text, reqtime text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		select --a.idordentrabajoparte ,
		       b.idordentrabajo , 
		       b.idparte , 
		       c.nombreparte , 
		       --c.idtipoparte , 
		       --c.idplano ,
		       e.nombreplano ,
		       --b.itemparte , 
		       --a.idtipotrabajo , 
		       a.cantidadcompra , 
		       --a.idreparafabrica ,
		       to_char(now(),'dd-mm-yyyy') ,
			   to_char(now(),'HH24:mi:ss') ,
			   to_char(now() + interval '14 day','dd-mm-yyyy') ,
			   to_char(now() + interval '14 day','HH24:mi:ss') 
		from mct_evaluacion a,
		     mct_ordentrabajoparte b,
		     mct_parte c,
		     mct_componente d,
		     mct_plano e
		where a.idordentrabajoparte = b.idordentrabajoparte 
		and b.idparte = c.idparte 
		and c.idcomponente = d.idcomponente 
		and c.idplano = e.idplano 
		and c.idtipoparte = 17
		and a.cantidadcompra > 0
		and b.idordentrabajo  = idworkorders;

END;
$$;


