--
-- TOC entry 1342 (class 1255 OID 16976)
-- Name: evtlistfabenfab(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistfabenfab(idcustomer bigint) RETURNS TABLE(id bigint, ot bigint, fechar character varying, fechaa character varying, fechae character varying, tipo character varying, modelo character varying, avance bigint, monto bigint, otcliente character varying, recicla bigint, reciclado bigint, ahorro character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_id      integer;
    sp_ot      integer;
    sp_fechar  varchar;
    sp_fechaa  timestamp;
    sp_fechae  varchar;
    sp_tipo    varchar;
    sp_modelo  varchar;
    sp_avance  numeric;
    sp_monto   integer;
    sp_estado  integer;
   
    sp_fechat  varchar;
    sp_dias    integer;
    sp_diast   integer;
    sp_porc    integer;
         
    sp_dife    integer;
   
   -- Reciclaje
    sp_reciclado    integer;
    sp_tot_piezasr  integer;
    sp_tot_recic    integer;   
      
    rec1 	   record;
   
BEGIN

	if ( idcustomer = 77 ) then
	
		FOR rec1 IN (   
		       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
		              a.idordentrabajo as sp_ot,
		              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
		              --to_char(a.fechaentrega, 'dd-mm-yyyy') as sp_fechae, -- Esto se cambia para igualar a prioridades
	                  to_char(a.fechafaceclte, 'dd-mm-yyyy') as sp_fechae,
		              d.sigla as sp_tipo,
		              d.sigla||' '||c.nombremodelo as sp_modelo,
		              coalesce (a.montorepfab, 0) as sp_monto ,
		              a.ordencompra  ,
		              --coalesce (b.tonelada , 4.5) as tonelada
		              case
						when idlineadiseno = 3 then 0 
						when idlineadiseno in (1,2) then coalesce (b.tonelada, 4.5)
					  end as tonelada
		         from mct_ordentrabajo a,
		              mct_producto b,
		              mct_modelo c,
		              mct_subfamilia d
		        where a.idordentrabajo >= 30000
		          --and a.idcliente = idcustomer
		          and a.idtipoorden = 2
		          and a.idfamilia in (8, 15)
		          and a.flagapp = 1
		          and a.idestadoorden > 4 and a.idestadoorden < 9
		          and a.idproducto = b.idproducto 
		          and b.idmodelo = c.idmodelo 
		          and c.idsubfamilia = d.idsubfamilia 
		          and a.ordencompra > 0
          )
		loop           
         
		       select coalesce (fecha_autoriza_cliente, fecha_real_termino )
		         into sp_fechaa
		         from mct_progavisos mp 
		        where idsla = 5
		          and idordentrabajo = rec1.sp_ot;   
		         
		         
		        sp_avance  := 0;
			    sp_fechat  := '';
			    sp_dias    := 0;
			    sp_dife    := 0;
			    sp_diast   := 0;
		         
		        if ( now() < to_date(rec1.sp_fechae,'dd-mm-yyyy')) then
		           	
		            sp_diast := date_part('day', to_date(rec1.sp_fechae,'dd-mm-yyyy') - sp_fechaa)  ;
		            sp_dias  := date_part('day', now() - sp_fechaa ) ;
		           	--sp_dias  := 50;
		        --   
		            sp_dife   := sp_diast - sp_dias;
		            sp_avance := 100 - (round( (sp_dife * 100)/sp_diast  ));

		        else
		        
		          	sp_avance := 100;
		          
		        end if;
		           
			   	sp_tot_piezasr := 0;
			    sp_tot_recic   := 0;
			  
			   
			     -- % de reciclaje
			    select sum(cantidad)
			      into sp_tot_piezasr
				  from mct_checklistinftecvalido mc 
				 where idordentrabajo = rec1.sp_ot
				   and upper(criterio) not in ('RPO')
				   and upper(nombreparte) not like '%CHAVE%'
				   and upper(nombreparte) not like '%RRAGO%'
				   and upper(nombreparte) not like '%CORTAGO%'
				   and upper(nombreparte) not like '%PERNO%'	
				   and upper(nombreparte) not like '%GOLILL%'		
				   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
				   and upper(nombreparte) not like '%NIPL%'			   
				  ;
				   
				select  sum(cantidad)*100
				  into sp_tot_recic
				  from mct_checklistinftecvalido mc 
				 where idordentrabajo = rec1.sp_ot
				   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
				   and upper(criterio) not like 'REM%';
			     
				  
				sp_reciclado := 0;
			    sp_reciclado := round(sp_tot_recic / sp_tot_piezasr);		       
		         
			    id      	:= rec1.sp_id;
			    ot      	:= rec1.sp_ot;
			    fechar  	:= rec1.sp_fechar;
			    fechaa  	:= to_char(sp_fechaa,'dd-mm-yyyy');
			    fechae  	:= rec1.sp_fechae;
			    tipo    	:= rec1.sp_tipo;
			    modelo  	:= rec1.sp_modelo;
			    avance  	:= sp_avance;
			    monto   	:= rec1.sp_monto;
			   -- otcliente	:= 'OC '||rec1.ordencompra;
			    otcliente   := rec1.ordencompra;
			    recicla		:= 0;
			    reciclado	:= coalesce(sp_reciclado,0);
			    --ahorro      := 4.5;
			   	ahorro      := round(rec1.tonelada,1);
			    
		     
		      RETURN next;
		     
		END LOOP;		
	
	else
	
		FOR rec1 IN (   
	       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
	              a.idordentrabajo as sp_ot,
	              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
	              --to_char(a.fechaentrega, 'dd-mm-yyyy') as sp_fechae, -- Esto se cambia para igualar a prioridades
	              to_char(a.fechafaceclte, 'dd-mm-yyyy') as sp_fechae,
	              d.sigla as sp_tipo,
	              d.sigla||' '||c.nombremodelo as sp_modelo,
	              coalesce (a.montorepfab, 0) as sp_monto ,
	              a.ordencompra  ,
	              --coalesce (b.tonelada , 4.5) as tonelada
	              case
					when idlineadiseno = 3 then 0 
					when idlineadiseno in (1,2) then coalesce (b.tonelada, 4.5)
				  end as tonelada
	         from mct_ordentrabajo a,
	              mct_producto b,
	              mct_modelo c,
	              mct_subfamilia d
	        where a.idordentrabajo >= 30000
	          and a.idcliente = idcustomer
	          and a.idtipoorden = 2
	          and a.idfamilia in (8, 15)
	          and a.flagapp = 1
	          and a.idestadoorden > 4 and a.idestadoorden < 9
	          and a.idproducto = b.idproducto 
	          and b.idmodelo = c.idmodelo 
	          and c.idsubfamilia = d.idsubfamilia 
	          and a.ordencompra > 0
          )
		loop           
         
		       select fecha_autoriza_cliente
		         into sp_fechaa
		         from mct_progavisos mp 
		        where idsla = 5
		          and idordentrabajo = rec1.sp_ot;   
		         
		         
		        sp_avance  := 0;
			    sp_fechat  := '';
			    sp_dias    := 0;
			    sp_dife    := 0;
			    sp_diast   := 0;
		         
		        if ( now() < to_date(rec1.sp_fechae,'dd-mm-yyyy')) then
		           	
		            sp_diast := date_part('day', to_date(rec1.sp_fechae,'dd-mm-yyyy') - sp_fechaa)  ;
		            sp_dias  := date_part('day', now() - sp_fechaa ) ;
		           	--sp_dias  := 50;
		        --   
		            sp_dife   := sp_diast - sp_dias;
		            sp_avance := 100 - (round( (sp_dife * 100)/sp_diast ));
		        else
		        
		          	sp_avance := 100;
		        
		        end if;
		           
			   	sp_tot_piezasr := 0;
			    sp_tot_recic   := 0;
			  
			   
				-- % de reciclaje
			    select sum(cantidad)
			      into sp_tot_piezasr
				  from mct_checklistinftecvalido mc 
				 where idordentrabajo = rec1.sp_ot
				   and upper(criterio) not in ('RPO')
				   and upper(nombreparte) not like '%CHAVE%'
				   and upper(nombreparte) not like '%RRAGO%'
				   and upper(nombreparte) not like '%CORTAGO%'
				   and upper(nombreparte) not like '%PERNO%'	
				   and upper(nombreparte) not like '%GOLILL%'		
				   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
				   and upper(nombreparte) not like '%NIPL%'			   
				  ;
					   
				select sum(cantidad)*100
				  into sp_tot_recic
				  from mct_checklistinftecvalido mc 
				 where idordentrabajo = rec1.sp_ot
				   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
				   and upper(criterio) not like 'REM%';
			     
				  
				sp_reciclado := 0;
			    sp_reciclado := round(sp_tot_recic / sp_tot_piezasr);		       
		         
			    id      	:= rec1.sp_id;
			    ot      	:= rec1.sp_ot;
			    fechar  	:= rec1.sp_fechar;
			    fechaa  	:= to_char(sp_fechaa,'dd-mm-yyyy');
			    fechae  	:= rec1.sp_fechae;
			    tipo    	:= rec1.sp_tipo;
			    modelo  	:= rec1.sp_modelo;
			    avance  	:= sp_avance;
			    monto   	:= rec1.sp_monto;
			   -- otcliente	:= 'OC '||rec1.ordencompra;
			    otcliente   := rec1.ordencompra;
			    recicla		:= 0;
			    reciclado	:= coalesce(sp_reciclado,0);
			    --ahorro      := 4.5;
			   	ahorro      := round(rec1.tonelada,1);
			    
		     
		      RETURN next;
		     
		END LOOP;		
	
	end if;
	
	
END;
$$;


ALTER FUNCTION traking.evtlistfabenfab(idcustomer bigint) OWNER TO postgres;

--
-- TOC entry 1992 (class 1255 OID 16978)
-- Name: evtlistfabsina(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistfabsina(idcustomer bigint) RETURNS TABLE(id bigint, ot bigint, fechar character varying, fechaa character varying, fechae character varying, tipo character varying, modelo character varying, avance bigint, monto bigint)
    LANGUAGE plpgsql
    AS $$
declare

    sp_id      integer;
    sp_ot      integer;
    sp_fechar  varchar;
    sp_fechaa  varchar;
    sp_fechae  varchar;
    sp_tipo    varchar;
    sp_modelo  varchar;
    sp_avance  integer;
    sp_monto   integer;
    rec1 	   record;
   
BEGIN

	FOR rec1 IN (   
       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
              a.idordentrabajo as sp_ot,
              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
              --to_char(a.fechaentrega, 'dd-mm-yyyy') as sp_fechae, -- Esto se cambia para igualar a prioridades
	          to_char(a.fechafaceclte, 'dd-mm-yyyy') as sp_fechae,
              d.sigla as sp_tipo,
              d.sigla||' '||c.nombremodelo as sp_modelo,
              coalesce (a.montorepfab, 0) as sp_monto 
         from mct_ordentrabajo a,
              mct_producto b,
              mct_modelo c,
              mct_subfamilia d
        where a.idordentrabajo >= 30000
          and a.idcliente = idcustomer
          and a.idtipoorden = 2
          and a.idfamilia = 8
          and a.idestadoorden <= 4
          and a.idproducto = b.idproducto 
          and b.idmodelo = c.idmodelo 
          and c.idsubfamilia = d.idsubfamilia 
          )
		loop           
         
		       select coalesce (to_char(fecha_autoriza_cliente,'dd-mm-yyyy'),'')
		         into sp_fechaa
		         from mct_progavisos mp 
		        where idsla = 5
		          and idordentrabajo = rec1.sp_ot;   
		         
			    id      := rec1.sp_id;
			    ot      := rec1.sp_ot;
			    fechar  := rec1.sp_fechar;
			    fechaa  := sp_fechaa;
			    fechae  := rec1.sp_fechae;
			    tipo    := rec1.sp_tipo;
			    modelo  := rec1.sp_modelo;
			    avance  := 10;
			    monto   := rec1.sp_monto;
			    
		     
		      RETURN next;
		     
		END LOOP;		     

END;
$$;


ALTER FUNCTION traking.evtlistfabsina(idcustomer bigint) OWNER TO postgres;

--
-- TOC entry 2278 (class 1255 OID 16979)
-- Name: evtlistfaconline(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistfaconline(startdate character varying, enddate character varying, tipografico bigint) RETURNS TABLE(id bigint, nombre character varying, valor bigint)
    LANGUAGE plpgsql
    AS $$
declare
     sp_nombre      varchar;
     rec_lista      RECORD;	
     idot           numeric;
    
BEGIN  
	
	 
	    if ( tipografico = 1) then
	        RETURN QUERY
				select  i.idtipoorden as id, i.nombretipoorden as nombre, cast(sum(b.costo*h.qdespacho) as bigint) as valor			
				from mct_ordentrabajo a
				left join  mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
				left join  mct_cliente d on a.idcliente = d.idcliente
				left join  mct_despachopartecabecera g on a.idordentrabajo = g.idordentrabajo
				left join  mct_despachopartedetalle h on ( g.iddespachopartecabecera = h.iddespachopartecabecera 
				            					 and b.idordentrabajorepuesto = h.idordentrabajoparte)
				left join  mct_tipoorden i on a.idtipoorden = i.idtipoorden
				            		
			 where  
				g.fechadespacho >= to_date(startdate,'yyyy-mm-dd')
				and g.fechadespacho <= to_date(enddate,'yyyy-mm-dd') 
				and a.idordentrabajo >= 30000
			group by i.idtipoorden, i.nombretipoorden
			having cast(sum(b.costo*h.qdespacho) as bigint) > 0;
		
		elseif ( tipografico = 2) then
		
			   RETURN QUERY
			      select  k.idsubfamilia as id, k.sigla as nombre, cast(sum(b.costo * b.cantidad) as bigint) as valor 
				     from mct_ordentrabajo a 
				       left join  mct_ordentrabajorepuesto b  on a.idordentrabajo = b.idordentrabajo
				   -- left join  mct_despachopartecabecera g on a.idordentrabajo = g.idordentrabajo
					   inner join mct_producto i               on ( a.idproducto = i.idproducto )
				       inner join mct_modelo j                 on ( i.idmodelo = j.idmodelo )
				       inner join mct_subfamilia k             on ( k.idsubfamilia = j.idsubfamilia )
				   where 
				 		b.fechacreacion >= to_date(startdate,'yyyy-mm-dd')
				        and b.fechacreacion <= to_date(enddate,'yyyy-mm-dd')
				        and a.idfamilia = 8
				        and a.idordentrabajo >= 30000
			     group by  k.idsubfamilia, k.sigla
			having cast(sum(b.costo * b.cantidad) as bigint) > 0;
		
		elseif ( tipografico = 3) then
		
			   RETURN QUERY
			   
			   		select  j.idproductonepcast as id, j.nombreproductonepcast as nombre, cast(sum(b.costo*h.qdespacho) as bigint) as valor			
				from mct_ordentrabajo a
				left join  mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
				left join  mct_despachopartecabecera g on a.idordentrabajo = g.idordentrabajo
				left join  mct_despachopartedetalle h on ( g.iddespachopartecabecera = h.iddespachopartecabecera 
				            					 and b.idordentrabajorepuesto = h.idordentrabajoparte)
				left join   traking.mct_productonepcast j on   ( j.idproductonepcast =  b.idproductonepcast)
				            		
			 where  
				g.fechadespacho >= to_date(startdate,'yyyy-mm-dd')
				and g.fechadespacho <= to_date(enddate,'yyyy-mm-dd') 
				and a.idfamilia = 11
				and a.idordentrabajo >= 30000
			group by j.idproductonepcast, j.nombreproductonepcast
			having cast(sum(b.costo*h.qdespacho) as bigint) > 0;
		
	  end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistfaconline(startdate character varying, enddate character varying, tipografico bigint) OWNER TO postgres;

--
-- TOC entry 2033 (class 1255 OID 16980)
-- Name: evtlistfamiliadesgaste(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistfamiliadesgaste(iduser bigint) RETURNS TABLE(idfamilydesgaste bigint, namefamilydesgaste character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    
    if ( iduser = 53 ) then

        RETURN QUERY
        
		select * from (
			select traking.mct_familia.idfamilia , 
			       traking.mct_familia.nombrefamilia 
			  from traking.mct_familia
			 where traking.mct_familia.idfamilia in (11)
		) fam
		order by fam.nombrefamilia ;
	    
   
    elsif ( iduser = 54 ) then

        RETURN QUERY
        
		select * from (
			select traking.mct_familia.idfamilia , 
			       traking.mct_familia.nombrefamilia 
			  from traking.mct_familia
			 where traking.mct_familia.idfamilia in (10, 8)
		) fam
		order by fam.nombrefamilia ;
	
    else

        RETURN QUERY
        
		select * from (
			select traking.mct_familia.idfamilia , 
			       traking.mct_familia.nombrefamilia 
			  from traking.mct_familia
			 where traking.mct_familia.idfamilia in (11,10, 8)
			union 
			select 9999, 'TODOS'
		) fam
		order by fam.nombrefamilia ;
	
    end if;
   

END;
$$;


