--
-- TOC entry 2200 (class 1255 OID 16982)
-- Name: evtlistfundicioncalendarioscreen(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistfundicioncalendarioscreen() RETURNS TABLE(idordentrabajo bigint, idfamilia bigint, producto character varying, dias bigint, nombrecliente character varying, siglatipoorden character varying, siglafamilia character varying, fechafundicion character varying, plano character varying, cantidadtotal bigint, recepcionada bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;
   
begin
	 
		RETURN QUERY	
		
		select a.idordentrabajo,
		       a.idfamilia,
		       cast(case 
				  when a.idfamilia = 11 then c.nombreproducto
			      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
			   end as varchar) as producto,
			   cast(date_part('day', a.fechafundicion2 - now()) as bigint),
			   b.nombrecorto ,
			   d.sigla as siglatipo,
			   e.sigla as siglafam,
			   cast(to_char(a.fechafundicion2, 'yyyy-mm-dd hh24:mi:ss') as varchar),
			   cast(replace (split_part(k.plano,'-', 1), ' ','') as varchar),
			   cast(sum(k.cantidad) as bigint),
			   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada
		  from mct_ordentrabajo a
		  left join  mct_cliente b         		 on a.idcliente = b.idcliente
		  left join  mct_producto c        		 on a.idproducto = c.idproducto 
		  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
		  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
		  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
		  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
		  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
		  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
		  left join  mct_usuario j               on a.idusuario = j.idusuario
		  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL') 
		  left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and k.codigoqr = l.codigoqr 
		  left join  mct_componente m            on k.idcomponente = m.idcomponente 
		  left join  mct_usuario n               on m.idresponsablefundicion = n.idusuario 
		 where a.idordentrabajo >= 30000
	       and a.idestadoorden  >= 5 and a.idestadoorden < 9
		   and a.idfamilia = 8
	       and a.flagfacturacion is true
		   and a.debaja < 1
		   and a.checklistvalido = true
		 group by a.idordentrabajo,
		       a.idfamilia,
			   cast(case 
				  when a.idfamilia = 11 then c.nombreproducto
			      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
			   end as varchar),
			   b.nombrecorto ,
			   d.sigla,
			   e.sigla,
			   to_char(a.fechafundicion2, 'yyyy-mm-dd hh24:mi:ss'),
			   cast(replace (split_part(k.plano,'-', 1), ' ','') as varchar)
		 having sum(k.cantidad) >= coalesce(sum(l.cantidad),0)	   
		 order by a.fechafundicion2 asc, a.idordentrabajo ;
		   
	 
END;
$$;


