						  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
						       c.nombreproducto
						  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				    end as varchar) ,
					b.nombrecorto ,
					cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) ,
					cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) ,	
					cast(date_part('day', a.fechafacetm - current_date) as bigint),
					cast(date_part('day', a.fechaentrega - current_date) as bigint),	
					a.idmodalidadcreacion ,
					case
		 	   	   		when sp_mec = 1 then
							'SEBASTIAN CUADRA'
		       	   		else
		           	    	j.nombre 
		       		end ,
					a.flagfacturacion ,
					d.sigla ,
					case
						when a.idproyecto = 1 then
						     e.sigla||'_PYTO'
						else
						     e.sigla
					end,
					--cast(to_char(a.fechaentrega - interval '14 days','dd-mm-yyyy') as varchar),
					cast(to_char(a.fechafaceclte - interval '10 days' ,'dd-mm-yyyy') as varchar),
					k.nombreparte ,
					k.plano ,
					case
				 	   	when sp_mec = 1 then
					 		 'SEBASTIAN CUADRA'
				       	else
				       	 	 j.nombre
				    end ,	
				    cast(date_part('day', fechafundicion2 - now() ) as bigint),
				    k.idchecklistinftec,
			   		k.cantidad
			 having k.cantidad > coalesce(sum(l.cantidad),0)	
			 --order by (a.fechaentrega - interval '14 days') asc, a.idordentrabajo ;	 
			 order by a.fechafundicion2 asc, a.idordentrabajo ;
		   
	elseif ( desde != 'NA' and hasta != 'NA') then

			RETURN QUERY
			
			  select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
			         ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
				     a.idordentrabajo ,
			         d.nombretipoorden ,
				     e.nombrefamilia ,
				     cast(case 
						  when a.idproducto in (10,11,12,13,14,15,16,17) then 
						       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
						  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
						       c.nombreproducto
						  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				     end as varchar) as producto,
					 b.nombrecorto ,
					 cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) as fechaentregatm ,
					 cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) as fechaentregaclte ,	
				     cast(date_part('day', a.fechafacetm - current_date) as bigint) as dias,
					 cast(date_part('day', a.fechaentrega - current_date) as bigint) as diascliente,	
					 a.idmodalidadcreacion ,
					 case
		 	   	   		when sp_mec = 1 then
							'SEBASTIAN CUADRA'
		       	  		 else
		               		j.nombre 
		       		 end ,
					 a.flagfacturacion ,
					 d.sigla as siglatipo,
					 case
						 when a.idproyecto = 1 then
					   		  e.sigla||'_PYTO'
				       	 else
					          e.sigla
					 end as siglafam,
					 --cast(to_char(a.fechaentrega - interval '14 days','dd-mm-yyyy') as varchar) as fechafundicion,
					 cast(to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy') as varchar) as fechafundicion,
					 k.nombreparte ,
					 k.plano ,
					 case
		 	   	   		when sp_mec = 1 then
							'SEBASTIAN CUADRA'
		       	  		 else
		               		j.nombre 
		       		 end ,	
		       		 --cast(date_part('day', fechafundicion2 - now() ) as bigint),
		       		 cast(date_part('day', a.fechafaceclte - interval '10 days' - current_date ) as bigint),
		       		 k.idchecklistinftec,
					 k.cantidad as total,
					 cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
			         cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes
			    from mct_ordentrabajo a
			    left join  mct_cliente b      on a.idcliente = b.idcliente
			    left join  mct_producto c     on a.idproducto = c.idproducto
			    left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
			    left join  mct_familia e      on a.idfamilia = e.idfamilia
			    left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
			    left join  mct_modelo g       on c.idmodelo = g.idmodelo 
			    left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
			    left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
		  	    left join  mct_usuario j      on a.idusuario = j.idusuario 
			    left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
				left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr	  
				 where a.idordentrabajo > 30000
				   and a.idestadoorden  >= 6 and a.idestadoorden < 9
				   and a.idfamilia = sp_fami
				   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = sp_mec)
				   and a.flagfacturacion is true
				   --and ((a.fechaentrega - interval '14 days') >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and (a.fechaentrega - interval '14 days') <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				   and (a.fechafaceclte - interval '10 days' >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte - interval '10 days' <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				   and a.debaja < 1
				   and not exists (select 'x' from mct_ordentrabajorepuesto  aa, mct_clasificafundicion b
												where a.idordentrabajo = aa.idordentrabajo 
												  and aa.nombreplano = b.plano 
												  and b.recocido = true )
				   group by a.idordentrabajo ,
				 	        d.nombretipoorden ,
							e.nombrefamilia ,
							cast(case 
								  when a.idproducto in (10,11,12,13,14,15,16,17) then 
								       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
								  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
								       c.nombreproducto
								  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						    end as varchar) ,
							b.nombrecorto ,
							cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) ,
							cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) ,	
							cast(date_part('day', a.fechafacetm - current_date) as bigint),
							cast(date_part('day', a.fechaentrega - current_date) as bigint),	
							a.idmodalidadcreacion ,
							case
		 	   	   				when sp_mec = 1 then
									'SEBASTIAN CUADRA'
		       	   				else
		           	    			j.nombre 
		       				end ,
							a.flagfacturacion ,
							d.sigla ,
							case
								when a.idproyecto = 1 then
								     e.sigla||'_PYTO'
								else
								     e.sigla
							end,
							--cast(to_char(a.fechaentrega - interval '14 days','dd-mm-yyyy') as varchar),
							cast(to_char(a.fechafaceclte - interval '10 days' ,'dd-mm-yyyy') as varchar),
							k.nombreparte ,
							k.plano,
							case
				 	   	    	when sp_mec = 1 then
							   		 'SEBASTIAN CUADRA'
				       	  		else
				              	 	 j.nombre
				            end ,	
				            cast(date_part('day', fechafundicion2 - now() ) as bigint),
				            k.idchecklistinftec,
					   		k.cantidad
					 having k.cantidad > coalesce(sum(l.cantidad),0)	
					 --order by (a.fechaentrega - interval '14 days') asc, a.idordentrabajo ;
					 order by a.fechafundicion2 asc, a.idordentrabajo ;
	
	else
	
		RETURN QUERY	
		
		select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
		       ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
			   a.idordentrabajo ,
			   d.nombretipoorden ,
			   e.nombrefamilia ,
			   cast(case 
					  when a.idproducto in (10,11,12,13,14,15,16,17) then 
					       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
					  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
					       c.nombreproducto
					  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
			   end as varchar) as producto,
		       b.nombrecorto ,
		       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) as fechaentregatm ,
		       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) as fechaentregaclte ,	
		       cast(date_part('day', a.fechafacetm - current_date) as bigint) as dias,
		       cast(date_part('day', a.fechaentrega - current_date) as bigint) as diascliente,	
		       a.idmodalidadcreacion ,
		       case
		 	   	    when sp_mec = 1 then
					     'SEBASTIAN CUADRA'
		       	  	else
		               	 j.nombre
		       end ,
		       a.flagfacturacion ,
		       d.sigla as siglatipo,
		       case
		 	   	   when a.idproyecto = 1 then
						e.sigla||'_PYTO'
		       	   else
		                e.sigla
		       end as siglafam,
		       --cast(to_char(a.fechaentrega - interval '14 days','dd-mm-yyyy') as varchar) as fechafundicion,
		       cast(to_char(a.fechafaceclte - interval '10 days' ,'dd-mm-yyyy') as varchar) as fechafundicion,
		       k.nombreparte ,
		       k.plano ,
		       case
		 	   	    when sp_mec = 1 then
					     'SEBASTIAN CUADRA'
		       	  	else
		               	 j.nombre
		       end ,
		       --cast(date_part('day', fechafundicion2 - now() ) as bigint),
		       cast(date_part('day', a.fechafaceclte - interval '10 days' - current_date ) as bigint),
		       k.idchecklistinftec ,
			   k.cantidad as total,
			   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
			   cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes
		  from mct_ordentrabajo a
		  left join  mct_cliente b      on a.idcliente = b.idcliente
		  left join  mct_producto c     on a.idproducto = c.idproducto
		  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
		  left join  mct_familia e      on a.idfamilia = e.idfamilia
		  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
		  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
		  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
		  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
		  left join  mct_usuario j      on a.idusuario = j.idusuario 
		  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr	  
		 where a.idordentrabajo >= 30000
		   and a.idestadoorden  >= 6 and a.idestadoorden < 9
		   and a.idfamilia       = sp_fami
	       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = sp_mec)
		   and a.flagfacturacion is true
		   and a.debaja < 1
		   and not exists (select 'x' from mct_ordentrabajorepuesto  aa, mct_clasificafundicion b
												where a.idordentrabajo = aa.idordentrabajo 
												  and aa.nombreplano = b.plano 
												  and b.recocido = true )
		   group by a.idordentrabajo ,
		 	        d.nombretipoorden ,
					e.nombrefamilia ,
					cast(case 
						  when a.idproducto in (10,11,12,13,14,15,16,17) then 
						       (select ltrim(nombreproductonepcast) from mct_productonepcast mp where mp.idproductonepcast = a.idproducto)
						  when a.idfamilia = 11 and a.idproducto in (10,11,12,13,14,15,16,17) then 
						       c.nombreproducto
						  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				    end as varchar) ,
					b.nombrecorto ,
					cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) ,
					cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) ,	
					cast(date_part('day', a.fechafacetm - current_date) as bigint),
					cast(date_part('day', a.fechaentrega - current_date) as bigint),	
					a.idmodalidadcreacion ,
					case
		 	   	   		when sp_mec = 1 then
							'SEBASTIAN CUADRA'
		       	   		else
		           	    	j.nombre 
		       		end ,
					a.flagfacturacion ,
					d.sigla ,
					case
						when a.idproyecto = 1 then
						     e.sigla||'_PYTO'
						else
						     e.sigla
					end,
					--cast(to_char(a.fechaentrega - interval '14 days','dd-mm-yyyy') as varchar),
					cast(to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy') as varchar),
					k.nombreparte ,
					k.plano,
					case
		 	   	    	when sp_mec = 1 then
					   		 'SEBASTIAN CUADRA'
		       	  		else
		              	 	 j.nombre
		            end ,
		            cast(date_part('day', fechafundicion2 - now() ) as bigint),
		            k.idchecklistinftec,
			   		k.cantidad
			 having k.cantidad > coalesce(sum(l.cantidad),0)	
			 --order by (a.fechaentrega - interval '14 days') asc, a.idordentrabajo ;	 
			 order by a.fechafundicion2 asc, a.idordentrabajo;
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistfundiciondesgastescreensr(idfamily bigint, idworkorders bigint, idusers bigint, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1835 (class 1255 OID 16989)
-- Name: evtlistfundicionscreen(bigint, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistfundicionscreen(idfamilys bigint, idworkorders bigint, idusers bigint, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, nombretipoorden character varying, nombrefamilia character varying, producto character varying, nombrecliente character varying, fechaentregatm character varying, fechaentregaclte character varying, diastm bigint, diascliente bigint, idmodalidadcreacion bigint, nombreusuario character varying, flagfacturacion boolean, siglatipoorden character varying, siglafamilia character varying, fechafundicion character varying, nombreparte character varying, plano character varying, responsablefundicion character varying, dias bigint, idchecklistinftec bigint, cantidadtotal bigint, recepcionada bigint, faltantes bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;
   
begin
	 
	if (idusers > 0 and desde != 'NA' and hasta != 'NA') then

			RETURN QUERY	
			
			select --ROW_NUMBER() OVER (ORDER BY (a.fechafaceclte - interval '19 days') asc, a.idordentrabajo) AS item,
		       ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
			   a.idordentrabajo ,
			   d.nombretipoorden ,
			   e.nombrefamilia ,
			   cast(case 
				  when a.idfamilia = 11 then c.nombreproducto
			      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
			   end as varchar) as producto,
			   b.nombrecorto ,
			   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) as fechaentregatm ,
			   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar) as fechaentregaclte ,				       
			   cast(date_part('day', a.fechafacetm - current_date) as bigint) as dias,
			   cast(date_part('day', a.fechafaceclte - current_date) as bigint) as diascliente,	
			   a.idmodalidadcreacion ,
			   j.nombre ,
			   a.flagfacturacion ,
			   d.sigla as siglatipo,
			   e.sigla as siglafam,
			   --cast(to_char(a.fechafaceclte - interval '19 days','dd-mm-yyyy') as varchar) as fechafundicion,
			   cast(to_char(a.fechafaceclte - interval '15 days' ,'dd-mm-yyyy') as varchar) as fechafundicion,
			   k.nombreparte ,
			   k.plano,
			   n.nombre ,
			   --cast(date_part('day', a.fechafacetm - current_date ) as bigint),
			   --cast(date_part('day', a.fechafundicion  - current_date ) as bigint) as diasfund, -- Se cambia a peticion de Roberto 23/07/2024
			   cast(date_part('day', (a.fechafaceclte - interval '15 days')  - current_date ) as bigint) as diasfund,
			   k.idchecklistinftec,
			   k.cantidad as total,
			   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
			   cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes
		  from mct_ordentrabajo a
		  left join  mct_cliente b         		 on a.idcliente = b.idcliente
		  left join  mct_producto c        		 on a.idproducto = c.idproducto 
		  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
		  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
		  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
		  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
		  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
		  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
		  left join  mct_usuario j               on a.idusuario = j.idusuario
		  left join  mct_checklistinftecvalido  k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
		  left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr
		  left join  mct_componente m            on k.idcomponente = m.idcomponente 
		  left join  mct_usuario n               on m.idresponsablefundicion = n.idusuario
		 where a.idordentrabajo >= 30000
	       and a.idestadoorden  >= 6 and a.idestadoorden < 9
		   --and a.idfamilia = idfamilys
		   and case 
                   WHEN idfamilys = 10 THEN 
                        a.idfamilia in (10) and a.idlineadiseno in (1,2,4)
                   WHEN idfamilys = 102 THEN  
                        a.idfamilia in (10) and a.idlineadiseno in (3) 
                   ELSE 
                        a.idfamilia = idfamilys
              end
	       and a.flagfacturacion is true
	       --and ((a.fechafaceclte - interval '19 days') >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and (a.fechafaceclte - interval '19 days') <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
		   and (a.fechafaceclte - interval '15 days' >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte - interval '15 days' <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
		   and a.debaja < 1
		   and n.idusuario = idusers
		   and a.checklistvalido = true
		 group by a.idordentrabajo ,
			   d.nombretipoorden ,
			   e.nombrefamilia ,
			   cast(case 
				  when a.idfamilia = 11 then c.nombreproducto
			      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
			   end as varchar),
			   b.nombrecorto ,
			   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar),
			   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar),				       
			   cast(date_part('day', a.fechafacetm - current_date) as bigint),
			   cast(date_part('day', a.fechafaceclte - current_date) as bigint),	
			   a.idmodalidadcreacion ,
			   j.nombre ,
			   a.flagfacturacion ,
			   d.sigla,
			   e.sigla,
			   --cast(to_char(a.fechafaceclte - interval '19 days','dd-mm-yyyy') as varchar),
			   cast(to_char(a.fechafaceclte - interval '15 days' ,'dd-mm-yyyy') as varchar),
			   k.nombreparte ,
			   k.plano,
			   n.nombre ,
			   --cast(date_part('day', a.fechafacetm - current_date ) as bigint),
			   cast(date_part('day', a.fechafundicion  - current_date ) as bigint),
			   k.idchecklistinftec,
			   k.cantidad  
		 having k.cantidad > coalesce(sum(l.cantidad),0)	   
		 --order by (a.fechafaceclte - interval '19 days') asc, a.idordentrabajo ;
		 order by a.fechafundicion2 asc, a.idordentrabajo ;
		
	elsif (idusers > 0) then

		RETURN QUERY	
		
		select --ROW_NUMBER() OVER (ORDER BY (a.fechafaceclte  - interval '19 days') asc, a.idordentrabajo) AS item,
		       ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
			   a.idordentrabajo ,
			   d.nombretipoorden ,
