-- Name: evtlistgestionncf(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncf(idot bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, idgestionncf bigint, codhojaruta character varying, idoperador bigint, nombreoperador character varying, idorigenncf bigint, nombreorigenncf character varying, idaccionncf bigint, nombreaccionncf character varying, correlativo bigint, idcomponente bigint, nombrecomponente character varying, idordentrabajo bigint, comentariofundicion character varying, nombreplano character varying, idestadogestionncf bigint, iddebaja bigint, nombredebaja character varying, urgente boolean, dardebaja boolean, observacion character varying, gestionncfvalidado boolean, fechavalidaciongestionncf character varying, idtipogestionncf bigint, nombretipogestionncf character varying, descripciongeneralgestionncf character varying, jsontipogestionncf character varying, nota bigint, idcierre bigint, fechavencimiento character varying, usuariocreacion character varying, fechacreacion character varying, usuariomodificacion character varying, fechamodificacion timestamp without time zone, equipo character varying, planogeneral character varying, critica character varying, sigla character varying, material character varying, cantidad bigint, repetitividad bigint, pendientecarga boolean, atrasovalidacion boolean, atrasocarga boolean, idmecanizadooperador bigint, nombremecanizadooperador character varying, idsuborigen bigint, nombresuborigen character varying)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;
    
    sp_totalrespaldos 	bigint;
    sp_totalcargas		bigint;
   
    sp_horas			bigint;
    sp_atrasocarga		bigint;
    sp_diasem			bigint;
   
    sp_fechavenc		varchar;

BEGIN
-- iddefectoi = -1: Todos
     
	     
		 IF ( idot > 0 )  THEN 
	     -- Todos

	      	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncf,
								a.codhojaruta,
								a.idorigenncf ,
								s.nombreorigen ,
								a.idaccionncf ,
								t.nombreaccion ,
								a.correlativo ,
								h.idcomponente ,
								i.nombrecomponente ,
								a.idordentrabajo ,
								a.comentariofundicion ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
								a.idestadogestionncf ,
								a.iddebaja ,
								r.nombredebaja ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.gestionncfvalidado ,
								cast(to_char(a.fechavalidaciongestionncf , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciongestionncf,
								a.idtipogestionncf ,
								u.nombretipogestionncf ,
								a.descripciongeneralgestionncf,
								a.jsontipogestionncf,
								a.nota ,
								a.idcierre,
								cast('' as varchar) as fechavencimiento,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2, 
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
								case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
							    a.idoperador ,
							    c.nombreoperador ,
							    a.idmecanizadooperador,
							    cast('' as varchar) as nombremecanizadooperador,
							    a.idsuborigenncf,
							    v.nombresuborigen
				 	 	    FROM traking.mct_gestionncf a
							left join  traking.mct_operador  c  	   on c.idoperador  = a.idoperador  
							left join  traking.mct_detallehojarutatemp g on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	   on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	   on h.idcomponente = i.idcomponente 
							left join  traking.mct_material j 		   on h.idmaterial = j.idmaterial 
							left join  traking.mct_ordentrabajo k 	   on h.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		   on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		   on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	   on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o           on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p   on replace(l.planogeneral,' ','') = p.plano 
							left join  traking.mct_gestionncfadjunto q on a.idgestionncf = q.idgestionncf  and q.correlativo = 0
							left join  traking.mct_debaja r			   on a.iddebaja = r.iddebaja 
							left join  traking.mct_origenncf s		   on s.idorigenncf = a.idorigenncf 
							left join  traking.mct_accionncf  t		   on t.idaccionncf = a.idaccionncf 
							left join  traking.mct_tipogestionncf  u   on u.idtipogestionncf = a.idtipogestionncf
							left join  traking.mct_suborigenncf v      on v.idsuborigenncf = a.idsuborigenncf
						   where a.idordentrabajo = idot
				        order by a.idgestionncf
					)
				loop
				
					sp_cantidad := 0;

				    select count(*)
				      into sp_cantidad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				        
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
				
				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion
				       and (length(d.tipo) > 0);
   
				   
				         item 							:= rec1.item;
				         idgestionncf 			        := rec1.idgestionncf;
				         codhojaruta 					:= rec1.codhojaruta;	
				         idoperador						:= rec1.idoperador;
				         nombreoperador					:= rec1.nombreoperador;
				         idorigenncf 					:= rec1.idorigenncf;
         				 nombreorigenncf 				:= rec1.nombreorigen;
         				 idaccionncf 					:= rec1.idaccionncf;
         				 nombreaccionncf 				:= rec1.nombreaccion;
         				 correlativo 					:= rec1.correlativo;
         				 idcomponente 					:= rec1.idcomponente;
         				 nombrecomponente 				:= rec1.nombrecomponente;
				         idordentrabajo 				:= rec1.idordentrabajo;
         				 comentariofundicion 			:= rec1.comentariofundicion;
         				 nombreplano 					:= rec1.planocomponente; 
         				 idestadogestionncf 			:= rec1.idestadogestionncf;
         				 iddebaja 						:= rec1.iddebaja; 
         				 nombredebaja 					:= rec1.nombredebaja;
         				 urgente 						:= rec1.urgente;
         				 dardebaja 						:= rec1.dardebaja;
         				 observacion 					:= rec1.observacion; 
         				 gestionncfvalidado 			:= rec1.gestionncfvalidado; 
         				 fechavalidaciongestionncf 		:= rec1.fechavalidaciongestionncf;
                         idtipogestionncf 				:= rec1.idtipogestionncf;
         				 nombretipogestionncf 			:= rec1.nombretipogestionncf; 
         				 descripciongeneralgestionncf 	:= rec1.descripciongeneralgestionncf;
         				 jsontipogestionncf 			:= rec1.jsontipogestionncf;
         				 --nota 							:= rec1.nota;
         				 idcierre 						:= rec1.idcierre;
         				 usuariocreacion				:= rec1.usuariocreacion;
				         fechacreacion 					:= rec1.fechacreacion; 
				         usuariomodificacion 			:= rec1.usuariomodificacion;
				         fechamodificacion 				:= rec1.fechamodificacion;
				         equipo 						:= rec1.equipo; 
         				 planogeneral 					:= rec1.planogeneral; 
         				 critica 						:= rec1.critica; 
         				 sigla 							:= rec1.sigla; 
         				 material 						:= rec1.nombrematerial; 						
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
				      				        
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;   
				        				        		 
				         atrasovalidacion	:= false;
				         if (rec1.gestionncfvalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciongestionncf)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriagestionncfvalido a,
						           mct_gestionncf b
						     where b.idgestionncf = rec1.idgestionncf
						       and a.idgestionncf = b.idgestionncf ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;
						   
--						    if (sp_horas > 0) then
--						    	atrasovalidacion	:= true;						    
--						    end if;
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_gestionncfcausa a,
				                mct_gestionncfcausaaccion b,
				                mct_gestionncfcausaaccionpdf c
				          where a.idgestionncf = rec1.idgestionncf
				            and a.idgestionncfcausa  = b.idgestionncfcausa 
				            and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;

				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	:= sp_fechavenc;
                         --fechavencimiento	:= rec1.fechavencimiento;
						 nota 				:= rec1.nota;
						 idmecanizadooperador		:= rec1.idmecanizadooperador;
						 nombremecanizadooperador	:= rec1.nombremecanizadooperador;
						 idsuborigen				:= rec1.idsuborigenncf;
						 nombresuborigen			:= rec1.nombresuborigen;
         			
				return next;
			
				end loop;

				
		 elsif ( startdate != 'NA' and enddate != 'NA'  ) then
		 
		 		--RETURN QUERY
		 	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncf,
								a.codhojaruta,
								a.idorigenncf ,
								s.nombreorigen ,
								a.idaccionncf ,
								t.nombreaccion ,
								a.correlativo ,
								h.idcomponente ,
								i.nombrecomponente ,
								a.idordentrabajo ,
								a.comentariofundicion ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
								a.idestadogestionncf ,
								a.iddebaja ,
								r.nombredebaja ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.gestionncfvalidado ,
								cast(to_char(a.fechavalidaciongestionncf , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciongestionncf,
								a.idtipogestionncf ,
								u.nombretipogestionncf ,
								a.descripciongeneralgestionncf,
								a.jsontipogestionncf,
								a.nota ,
								a.idcierre,
								cast('' as varchar) as fechavencimiento,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2, 
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
								case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
							    a.idoperador ,
							    c.nombreoperador ,
							    a.idmecanizadooperador,
							    cast('' as varchar) as nombremecanizadooperador,
							    a.idsuborigenncf,
							    v.nombresuborigen
				 	 	    FROM traking.mct_gestionncf a
							left join  traking.mct_operador  c  	   on c.idoperador  = a.idoperador  
							left join  traking.mct_detallehojarutatemp g on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	   on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	   on h.idcomponente = i.idcomponente 
							left join  traking.mct_material j 		   on h.idmaterial = j.idmaterial 
							left join  traking.mct_ordentrabajo k 	   on h.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		   on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		   on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	   on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o           on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p   on replace(l.planogeneral,' ','') = p.plano 
							left join  traking.mct_gestionncfadjunto q on a.idgestionncf = q.idgestionncf  and q.correlativo = 0
							left join  traking.mct_debaja r			   on a.iddebaja = r.iddebaja 
							left join  traking.mct_origenncf s		   on s.idorigenncf = a.idorigenncf 
							left join  traking.mct_accionncf  t		   on t.idaccionncf = a.idaccionncf 
							left join  traking.mct_tipogestionncf  u   on u.idtipogestionncf = a.idtipogestionncf 
							left join  traking.mct_suborigenncf v      on v.idsuborigenncf = a.idsuborigenncf
				 	  	where 
				 	  	    (a.fechavencimiento  >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				            a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				            --and
				 	  	    --a.iddefectofundicion = iddefectofuncioni
				 	  	    )
				 	loop 

					sp_cantidad := 0;
--				    select count(*)
--				      into sp_cantidad
--				      from mct_defectofundicion md 
--				     where idcomponente = rec1.idcomponente;
--				    
				    select count(*)
				      into sp_cantidad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				      
				     
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
						

				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion
				       and (length(d.tipo) > 0);
				      
				         item 							:= rec1.item;
				         idgestionncf 			        := rec1.idgestionncf;
				         codhojaruta 					:= rec1.codhojaruta;
				         idoperador						:= rec1.idoperador;
				         nombreoperador					:= rec1.nombreoperador;
				         idorigenncf 					:= rec1.idorigenncf;
         				 nombreorigenncf 				:= rec1.nombreorigen;
         				 idaccionncf 					:= rec1.idaccionncf;
         				 nombreaccionncf 				:= rec1.nombreaccion;
         				 correlativo 					:= rec1.correlativo;
         				 idcomponente 					:= rec1.idcomponente;
         				 nombrecomponente 				:= rec1.nombrecomponente;
				         idordentrabajo 				:= rec1.idordentrabajo;
         				 comentariofundicion 			:= rec1.comentariofundicion;
         				 nombreplano 					:= rec1.planocomponente; 
         				 idestadogestionncf 			:= rec1.idestadogestionncf;
         				 iddebaja 						:= rec1.iddebaja; 
         				 nombredebaja 					:= rec1.nombredebaja;
         				 urgente 						:= rec1.urgente;
         				 dardebaja 						:= rec1.dardebaja;
         				 observacion 					:= rec1.observacion; 
         				 gestionncfvalidado 			:= rec1.gestionncfvalidado; 
         				 fechavalidaciongestionncf 		:= rec1.fechavalidaciongestionncf;
                         idtipogestionncf 				:= rec1.idtipogestionncf;
         				 nombretipogestionncf 			:= rec1.nombretipogestionncf; 
         				 descripciongeneralgestionncf 	:= rec1.descripciongeneralgestionncf;
         				 jsontipogestionncf 			:= rec1.jsontipogestionncf;
         				 --nota 							:= rec1.nota;
         				 idcierre 						:= rec1.idcierre;
         				 usuariocreacion				:= rec1.usuariocreacion;
				         fechacreacion 					:= rec1.fechacreacion; 
				         usuariomodificacion 			:= rec1.usuariomodificacion;
				         fechamodificacion 				:= rec1.fechamodificacion;
				         equipo 						:= rec1.equipo; 
         				 planogeneral 					:= rec1.planogeneral; 
         				 critica 						:= rec1.critica; 
         				 sigla 							:= rec1.sigla; 
         				 material 						:= rec1.nombrematerial; 						
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
				        		
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;      
				        
				         atrasovalidacion	:= false;
				         if (rec1.gestionncfvalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciongestionncf)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriagestionncfvalido a,
						           mct_gestionncf b
						     where b.idgestionncf = rec1.idgestionncf
						       and a.idgestionncf = b.idgestionncf ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;						   
--						    if (sp_horas > 0) then
--						    	atrasovalidacion	:= true;						    
--						    end if;
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_gestionncfcausa a,
				                mct_gestionncfcausaaccion b,
				                mct_gestionncfcausaaccionpdf c
				          where a.idgestionncf = rec1.idgestionncf
				            and a.idgestionncfcausa  = b.idgestionncfcausa 
				            and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;			
				        
				         jsontipogestionncf	:= rec1.jsontipogestionncf;
				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	:= sp_fechavenc;
                         --fechavencimiento	:= rec1.fechavencimiento;
						 nota 				:= rec1.nota;
						 idmecanizadooperador		:= rec1.idmecanizadooperador;
						 nombremecanizadooperador	:= rec1.nombremecanizadooperador;
				 		 idsuborigen				:= rec1.idsuborigenncf;
				 		 nombresuborigen			:= rec1.nombresuborigen;
				 
				 	return next;
				 
				 	end loop;
		     end if;
		 
END;
$$;


ALTER FUNCTION traking.evtlistgestionncf(idot bigint, startdate character varying, enddate character varying) OWNER TO postgres;

