--
-- TOC entry 1253 (class 1255 OID 16995)
-- Name: evtlistgestionncfadjuntov2(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncfadjuntov2(idgestionncfi bigint, tipos bigint) RETURNS TABLE(idgestionncfpdf bigint, idgestionncf bigint, archivo text, nombrearchivo character varying, tipo character varying, correlativo bigint, urlfirebase character varying, idtipoarchivogestionncf bigint, nombretipoarchivogestionncf character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying, observacion character varying, fechacompromiso character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	    RETURN QUERY
	    
		SELECT a.idgestionncfpdf ,
			   a.idgestionncf,
			   a.archivo ,
			   a.nombrearchivo ,
			   a.tipo ,
			   a.correlativo,
			   cast(a.urlfirebase as varchar) ,
			   a.idtipoarchivogestionncf ,
			   b.nombretipoarchivogestionncf ,
			   a.fechacreacion as dateCreate,
			   a.usuariocreacion as userCreate,
			   a.fechamodificacion as dateUpdate,
			   a.usuariomodificacion as userUpdate,
			   a.observacion ,
			   cast(to_char(a.fechacompromiso,'dd-mm-yyyy') as varchar) as fechacompromiso
		  FROM traking.mct_gestionncfpdf a
		  left join mct_tipoarchivogestionncf b on a.idtipoarchivogestionncf = b.idtipoarchivogestionncf 
		 where a.idgestionncf = idgestionncfi
		   and a.idtipoarchivogestionncf = tipos;
		     				
END;
$$;


