--
-- TOC entry 1521 (class 1255 OID 16996)
-- Name: evtlistgestionncfbyroadmaporigen(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncfbyroadmaporigen(roadmapcodes character varying, idgestionncfs bigint) RETURNS TABLE(item bigint, idgestionncf bigint, codhojaruta character varying, idorigenncf bigint, nombreorigenncf character varying, idaccionncf bigint, nombreaccionncf character varying, correlativo bigint, idcomponente bigint, nombrecomponente character varying, idordentrabajo bigint, comentariofundicion character varying, nombreplano character varying, idestadogestionncf bigint, iddebaja bigint, nombredebaja character varying, urgente boolean, dardebaja boolean, observacion character varying, gestionncfvalidado boolean, fechavalidaciongestionncf character varying, idtipogestionncf bigint, nombretipogestionncf character varying, descripciongeneralgestionncf character varying, jsontipogestionncf character varying, nota bigint, idcierre bigint, fechavencimiento character varying, usuariocreacion character varying, fechacreacion character varying, usuariomodificacion character varying, fechamodificacion timestamp without time zone, equipo character varying, planogeneral character varying, critica character varying, sigla character varying, material character varying, cantidad bigint, repetitividad bigint, pendientecarga boolean, atrasovalidacion boolean, atrasocarga boolean)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;

    sp_totalrespaldos 	bigint;
    sp_totalcargas		bigint;

    sp_horas			bigint;
    sp_atrasocarga		bigint;
    sp_diasem			bigint;
   
    sp_fechavenc		bigint;
   
BEGIN
-- iddefectoi = -1: Todos

	      		
	      	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncf,
								a.codhojaruta,
								a.idorigenncf ,
								-- aca el nombre
								a.idaccionncf ,
								-- aca va el nombre
								a.correlativo ,
								h.idcomponente ,
								i.nombrecomponente ,
								a.idordentrabajo ,
								a.comentariofundicion ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
								a.idestadogestionncf ,
								a.iddebaja ,
								r.nombredebaja ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.gestionncfvalidado ,
								cast(to_char(a.fechavalidaciongestionncf , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciongestionncf,
								a.idtipogestionncf ,
								--t.nombretipodefecto,
								a.descripciongeneralgestionncf,
								a.jsontipogestionncf,
								a.nota ,
								a.idcierre,
								cast('' as varchar) as fechavencimiento,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2, 
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
								case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
							    a.idoperador ,
							    c.nombreoperador 
				 	 	    FROM traking.mct_gestionncf a
							left join  traking.mct_operador  c  	   on c.idoperador  = a.idoperador  
							left join  traking.mct_detallehojarutatemp g on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	   on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	   on h.idcomponente = i.idcomponente 
							left join  traking.mct_material j 		   on h.idmaterial = j.idmaterial 
							left join  traking.mct_ordentrabajo k 	   on h.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		   on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		   on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	   on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o           on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p   on replace(l.planogeneral,' ','') = p.plano 
							left join  traking.mct_gestionncfadjunto q on a.idgestionncf = q.idgestionncf  and q.correlativo = 0
							left join  traking.mct_debaja r			   on a.iddebaja = r.iddebaja 
						   where a.codhojaruta  = roadmapcodes  
				             and a.idorigenncf  = idgestionncfs
				        order by a.idgestionncf
					)
				loop
				
					sp_cantidad := 0;

--				    
				    select count(*)
				      into sp_cantidad
				      from mct_defectofundicion a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				        
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_defectofundicion a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
				

				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_defectofundicion a,
				           mct_defectocausa b,
				           mct_defectocausaaccion c,
				           mct_defectocausaaccionpdf d
				     where a.iddefectofundicion = rec1.iddefectofundicion
				       and a.iddefectofundicion = b.iddefectofundicion 
				       and b.iddefectocausa = c.iddefectocausa 
				       and c.iddefectocausaaccion = d.iddefectocausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_defectofundicion a,
				           mct_defectocausa b,
				           mct_defectocausaaccion c,
				           mct_defectocausaaccionpdf d
				     where a.iddefectofundicion = rec1.iddefectofundicion
				       and a.iddefectofundicion = b.iddefectofundicion 
				       and b.iddefectocausa = c.iddefectocausa 
				       and c.iddefectocausaaccion = d.iddefectocausaaccion
				       and (length(d.tipo) > 0);
				      
				         item 							:= rec1.item;
				         idgestionncf 			        := rec1.iddefectofundicion;
				         codhojaruta 					:= rec1.codhojaruta;				        
				         idorigenncf 					:= rec1.idorigenncf;
         				 nombreorigenncf 				:= rec1.nombreorigenncf;
         				 idaccionncf 					:= rec1.idaccionncf;
         				 nombreaccionncf 				:= rec1.nombreaccionncf;
         				 correlativo 					:= rec1.correlativo;
         				 idcomponente 					:= rec1.idcomponente;
         				 nombrecomponente 				:= rec1.nombrecomponente;
				         idordentrabajo 				:= rec1.idordentrabajo;
         				 comentariofundicion 			:= rec1.comentariofundicion;
         				 nombreplano 					:= rec1.nombreplano; 
         				 idestadogestionncf 			:= rec1.idestadogestionncf;
         				 iddebaja 						:= rec1.iddebaja; 
         				 nombredebaja 					:= rec1.nombredebaja;
         				 urgente 						:= rec1.urgente;
         				 dardebaja 						:= rec1.dardebaja;
         				 observacion 					:= rec1.observacion; 
         				 gestionncfvalidado 			:= rec1.gestionncfvalidado; 
         				 fechavalidaciongestionncf 		:= rec1.fechavalidaciondefecto;
                         idtipogestionncf 				:= rec1.idtipogestionncf;
         				 nombretipogestionncf 			:= rec1.nombretipogestionncf; 
         				 descripciongeneralgestionncf 	:= rec1.descripciongeneralgestionncf;
         				 jsontipogestionncf 			:= rec1.jsontipogestionncf;
         				 --nota 							:= rec1.nota;
         				 idcierre 						:= rec1.idcierre;
         				 usuariocreacion				:= rec1.usuariocreacion;
				         fechacreacion 					:= rec1.fechacreacion; 
				         usuariomodificacion 			:= rec1.usuariomodificacion;
				         fechamodificacion 				:= rec1.fechamodificacion;
				         equipo 						:= rec1.equipo; 
         				 planogeneral 					:= rec1.planogeneral; 
         				 critica 						:= rec1.critica; 
         				 sigla 							:= rec1.sigla; 
         				 material 						:= rec1.nombrematerial; 						
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
         
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;      
				        
				         atrasovalidacion	:= false;
				         if (rec1.gestionncfvalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciongestionncf)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriagestionncfvalido a,
						           mct_gestionncf b
						     where b.idgestionncf = rec1.idgestionncf
						       and a.idgestionncf = b.idgestionncf ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;						   
--						    if (sp_horas > 0) then
--						    	atrasovalidacion	:= true;						    
--						    end if;
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_gestionncfcausa a,
				                mct_gestionncfcausaaccion b,
				                mct_gestionncfcausaaccionpdf c
				          where a.idgestionncf = rec1.idgestionncf
				            and a.idgestionncfcausa  = b.idgestionncfcausa 
				            and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;			
				        
				         jsontipogestionncf	:= rec1.jsontipogestionncf;
				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	:= sp_fechavenc;
                         --fechavencimiento	:= rec1.fechavencimiento;
						 nota 				:= rec1.nota;
				        		
				return next;
			
				end loop;

				
END;
$$;


ALTER FUNCTION traking.evtlistgestionncfbyroadmaporigen(roadmapcodes character varying, idgestionncfs bigint) OWNER TO postgres;

--
-- TOC entry 2239 (class 1255 OID 16998)
-- Name: evtlistgestionncfcausaacciontotales(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncfcausaacciontotales(idgestionncfs bigint) RETURNS TABLE(idgestionncf bigint, idgestionncfcausa bigint, totalcausa bigint, totalaccion bigint)
    LANGUAGE plpgsql
    AS $$
	
declare
begin
	
	return query
	
	select a.idgestionncf,
	       a.idgestionncfcausa ,
	       cast(count(a.*) as bigint) as cantcausa, 
	       cast(count(b.*) as bigint) as cantaccion
      from mct_gestionncfcausa a
      left join mct_gestionncfcausaaccion b on b.idgestionncfcausa = a.idgestionncfcausa
     where a.idgestionncf = idgestionncfs
     group by a.idgestionncf, a.idgestionncfcausa;

END			
$$;


ALTER FUNCTION traking.evtlistgestionncfcausaacciontotales(idgestionncfs bigint) OWNER TO postgres;

--
-- TOC entry 1932 (class 1255 OID 16999)
-- Name: evtlistgestionncfcliente(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncfcliente(idot bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, idgestionncfcliente bigint, idordentrabajo bigint, idusuario bigint, nombreusuario character varying, idcliente bigint, nombrecliente character varying, nombrecorto character varying, idorigenncf bigint, nombreorigenncf character varying, idcomponente bigint, nombrecomponente character varying, idmaterial bigint, nombrematerial character varying, observacion character varying, nombreplano character varying, usuariocreacion character varying, fechacreacion character varying, usuariomodificacion character varying, fechamodificacion character varying)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;
    
    sp_totalrespaldos 	bigint;
    sp_totalcargas		bigint;
   
    sp_horas			bigint;
    sp_atrasocarga		bigint;
    sp_diasem			bigint;
   
    sp_fechavenc		varchar;

BEGIN
-- iddefectoi = -1: Todos
     
	     
		 IF ( idot > 0 )  THEN 
	     -- Todos
		 
         

	      	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncfcliente,
								a.idordentrabajo,
								a.idusuario,
								c.nombre as nombreusuario,
								a.idcliente,
								b.nombrecliente,
								b.nombrecorto,
								a.idorigenncf ,
								f.nombreorigen as nombreorigenncf,
								a.idcomponente ,
								d.nombrecomponente ,
								a.idmaterial ,
								e.nombrematerial ,
								a.observacion,
								a.nombreplano  ,
								a.usuariocreacion ,
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								cast(to_char(a.fechamodificacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechamodificacion
				 	 	    FROM traking.mct_gestionncfcliente a
							left join  traking.mct_cliente  b  	 on b.idcliente  = a.idcliente  
							left join  traking.mct_usuario  c  	 on c.idusuario  = a.idusuario  
							left join  traking.mct_componente d  on d.idcomponente = a.idcomponente 
							left join  traking.mct_material e 	 on e.idmaterial = a.idmaterial 
							left join  traking.mct_origenncf f   on f.idorigenncf = a.idorigenncf 
						   where a.idordentrabajo = idot
				        order by a.idgestionncfcliente
					)
				loop
				   
			         item 					:= rec1.item;
			         idgestionncfcliente 	:= rec1.idgestionncfcliente;
			         idordentrabajo 		:= rec1.idordentrabajo;
			         idusuario 				:= rec1.idusuario;
			         nombreusuario 			:= rec1.nombreusuario;
			         idcliente 				:= rec1.idcliente;
			         nombrecliente 			:= rec1.nombrecliente;
			         idorigenncf 			:= rec1.idorigenncf;
			         nombreorigenncf 		:= rec1.nombreorigenncf;
			         idcomponente 			:= rec1.idcomponente;
			         nombrecomponente 		:= rec1.nombrecomponente;
			         idmaterial 			:= rec1.idmaterial;
			         nombrematerial 		:= rec1.nombrematerial;
			         observacion 			:= rec1.observacion;
			         nombreplano 			:= rec1.nombreplano;
			         usuariocreacion 		:= rec1.usuariocreacion;
			         fechacreacion 			:= rec1.fechacreacion;
			         usuariomodificacion 	:= rec1.usuariomodificacion;
			         fechamodificacion 		:= rec1.fechamodificacion;

         			
				return next;
			
				end loop;

				
		 elsif ( startdate != 'NA' and enddate != 'NA'  ) then
		 
		 		--RETURN QUERY
		 	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncfcliente,
								a.idordentrabajo,
								a.idusuario,
								c.nombre as nombreusuario,
								a.idcliente,
								b.nombrecliente,
								b.nombrecorto,
								a.idorigenncf ,
								f.nombreorigen as nombreorigenncf,
								a.idcomponente ,
								d.nombrecomponente ,
								a.idmaterial ,
								e.nombrematerial ,
								a.observacion,
								a.nombreplano  ,
								a.usuariocreacion ,
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								cast(to_char(a.fechamodificacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechamodificacion
				 	 	    FROM traking.mct_gestionncfcliente a
							left join  traking.mct_cliente  b  	 on b.idcliente  = a.idcliente  
							left join  traking.mct_usuario  c  	 on c.idusuario  = a.idusuario  
							left join  traking.mct_componente d  on d.idcomponente = a.idcomponente 
							left join  traking.mct_material e 	 on e.idmaterial = a.idmaterial 
							left join  traking.mct_origenncf f   on f.idorigenncf = a.idorigenncf 
				 	  	where 
				 	  	    (a.fechacreacion  >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				            a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				            --and
				 	  	    --a.iddefectofundicion = iddefectofuncioni
				 	  	    )
				 	loop 

				         item 					:= rec1.item;
				         idgestionncfcliente 	:= rec1.idgestionncfcliente;
				         idordentrabajo 		:= rec1.idordentrabajo;
				         idusuario 				:= rec1.idusuario;
				         nombreusuario 			:= rec1.nombreusuario;
				         idcliente 				:= rec1.idcliente;
				         nombrecliente 			:= rec1.nombrecliente;
				         idorigenncf 			:= rec1.idorigenncf;
				         nombreorigenncf 		:= rec1.nombreorigenncf;
				         idcomponente 			:= rec1.idcomponente;
				         nombrecomponente 		:= rec1.nombrecomponente;
				         idmaterial 			:= rec1.idmaterial;
				         nombrematerial 		:= rec1.nombrematerial;
				         observacion 			:= rec1.observacion;
				         nombreplano 			:= rec1.nombreplano;
				         usuariocreacion 		:= rec1.usuariocreacion;
				         fechacreacion 			:= rec1.fechacreacion;
				         usuariomodificacion 	:= rec1.usuariomodificacion;
				         fechamodificacion 		:= rec1.fechamodificacion;
				 
				 	return next;
				 
				 	end loop;
		     end if;
		 
END;
$$;


ALTER FUNCTION traking.evtlistgestionncfcliente(idot bigint, startdate character varying, enddate character varying) OWNER TO postgres;

--
-- TOC entry 1243 (class 1255 OID 17000)
-- Name: evtlistgestionncfclienteadjunto(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncfclienteadjunto(idgestionncfclientes bigint) RETURNS TABLE(idgestionncfclienteadjunto bigint, idgestionncfcliente bigint, archivo text, nombrearchivo character varying, tipo character varying, correlativo bigint, urlfirebase character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
	
declare

begin
	
	    RETURN QUERY
	    
	    select a.idgestionncfclienteadjunto,
			   a.idgestionncfcliente,
			   a.archivo,
			   a.nombrearchivo,
			   a.tipo,
			   a.correlativo,
			   cast(a.urlfirebase as varchar),
			   a.fechacreacion as dateCreate,
			   a.usuariocreacion as userCreate,
			   a.fechamodificacion as dateUpdate,
			   a.usuariomodificacion as userUpdate   
	           --split_part(a.archivoadjunto,'data:image/jpeg;base64,',2)
	      from mct_gestionncfclienteadjunto a
	     where a.idgestionncfcliente = idgestionncfclientes;
	    
		  	 
END
$$;


ALTER FUNCTION traking.evtlistgestionncfclienteadjunto(idgestionncfclientes bigint) OWNER TO postgres;

--
-- TOC entry 1075 (class 1255 OID 17001)
-- Name: evtlistgestionncfresumen(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncfresumen(idgestionncfi bigint, startdate character varying, enddate character varying) RETURNS TABLE(idcomponente character varying, nombrecomponente character varying, planocomponente character varying, equipo character varying, planogeneral character varying, critica character varying, sigla character varying, maximafecha character varying, countagrupacion bigint, cantidad bigint, repetitividad bigint, cantidaddebaja bigint, cantidadutiliza bigint)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;
    sp_cantidaddebaja	bigint;
    sp_cantidadutiliza	bigint;

BEGIN
-- iddefectoi = -1: Todos

	      		
	      	    FOR rec1 IN (   
						SELECT  h.idcomponente ,
								i.nombrecomponente ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
							    cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
							    case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    count(*) as countagrupacion
				 	 	    FROM traking.mct_gestionncf a
							left join  traking.mct_detallehojarutatemp g 	on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	 on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	 on h.idcomponente = i.idcomponente 
							left join  traking.mct_ordentrabajo k 	 on h.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		 on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		 on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	 on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o         on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p on replace(l.planogeneral,' ','') = p.plano 
						   WHERE
						   (a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				            a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				            group by h.idcomponente ,
								i.nombrecomponente ,
								cast(replace(h.nombreplano,' ', '') as varchar),
							    cast(n.sigla ||' '||m.nombremodelo as varchar),
							    cast(replace(l.planogeneral,' ','') as varchar),
							    case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end ,
							    o.sigla 
				        --order by a.iddefecto, a.iddefectofundicion
					)
				loop


				
					sp_cantidad := 0;
    
				      select count(*)
				        into sp_cantidad
				        from mct_gestionncf md
				        where nombreplano = rec1.planocomponente;
				      
				      sp_repetitividad := 0;
				      select count(distinct(substring(codhojaruta,1,6)))
				        into sp_repetitividad
				        from mct_gestionncf md
				      where nombreplano = rec1.planocomponente;
				     
				      sp_cantidaddebaja := 0;
				      select count(distinct(substring(codhojaruta,1,6)))
				        into sp_cantidaddebaja
				        from mct_gestionncf md
				      where nombreplano = rec1.planocomponente
				        and iddebaja = 1;
				       
				      sp_cantidadutiliza := 0;
				      select count(distinct(substring(codhojaruta,1,6)))
				        into sp_cantidaddebaja
				        from mct_gestionncf md
				      where nombreplano = rec1.planocomponente
				        and iddebaja = 3; 
				    
				       
				     select to_char(max(fechacreacion), 'dd-mm-yyyy')
				       into maximafecha
				       from mct_gestionncf md 
				      where nombreplano = rec1.planocomponente;
				
				    
				     idcomponente 			:= rec1.idcomponente;
				     nombrecomponente 		:= rec1.nombrecomponente;
				     planocomponente 		:= rec1.planocomponente;
				     equipo 				:= rec1.equipo;
				     planogeneral 			:= rec1.planogeneral;
				     critica 				:= rec1.critica;
				     sigla 					:= rec1.sigla;
				     countagrupacion		:= rec1.countagrupacion;
				     cantidad 				:= sp_cantidad;
				     repetitividad			:= sp_repetitividad;
				     cantidaddebaja			:= sp_cantidaddebaja;
				     cantidadutiliza		:= sp_cantidadutiliza;
				               
         			
				return next;
			
				end loop;
		
		 
END;
$$;


ALTER FUNCTION traking.evtlistgestionncfresumen(idgestionncfi bigint, startdate character varying, enddate character varying) OWNER TO postgres;

--
-- TOC entry 2206 (class 1255 OID 17002)
-- Name: evtlistgestionncfv2(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncfv2(idot bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, idgestionncf bigint, codhojaruta character varying, idoperador bigint, nombreoperador character varying, idorigenncf bigint, nombreorigenncf character varying, idaccionncf bigint, nombreaccionncf character varying, correlativo bigint, idcomponente bigint, nombrecomponente character varying, idordentrabajo bigint, comentariofundicion character varying, nombreplano character varying, idestadogestionncf bigint, iddebaja bigint, nombredebaja character varying, urgente boolean, dardebaja boolean, observacion character varying, gestionncfvalidado boolean, fechavalidaciongestionncf character varying, idtipogestionncf bigint, nombretipogestionncf character varying, descripciongeneralgestionncf character varying, jsontipogestionncf character varying, nota bigint, idcierre bigint, fechavencimiento character varying, usuariocreacion character varying, fechacreacion character varying, usuariomodificacion character varying, fechamodificacion timestamp without time zone, equipo character varying, planogeneral character varying, critica character varying, sigla character varying, material character varying, cantidad bigint, repetitividad bigint, pendientecarga boolean, atrasovalidacion boolean, atrasocarga boolean, idmecanizadooperador bigint, nombremecanizadooperador character varying, idsuborigen bigint, nombresuborigen character varying, subeest bigint, subeestentiempo bigint, suberes bigint, suberesentiempo bigint, subeacc bigint, subeaccentiempo bigint, subekpi bigint, subekpientiempo bigint)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;
    
    sp_totalrespaldos 	bigint;
    sp_totalcargas		bigint;
   
    sp_horas			bigint;
    sp_atrasocarga		bigint;
    sp_diasem			bigint;
   
    sp_fechavenc		varchar;
   
    sp_fechasubepdf		timestamp;

BEGIN
-- iddefectoi = -1: Todos
     
	     
		 IF ( idot > 0 )  THEN 
	     -- Todos

	      	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncf,
								a.codhojaruta,
								a.idorigenncf ,
								s.nombreorigen ,
								a.idaccionncf ,
								t.nombreaccion ,
								a.correlativo ,
								h.idcomponente ,
								i.nombrecomponente ,
								a.idordentrabajo ,
								a.comentariofundicion ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
								a.idestadogestionncf ,
								a.iddebaja ,
								r.nombredebaja ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.gestionncfvalidado ,
								cast(to_char(a.fechavalidaciongestionncf , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciongestionncf,
								a.idtipogestionncf ,
								u.nombretipogestionncf ,
								a.descripciongeneralgestionncf,
								a.jsontipogestionncf,
								a.nota ,
								a.idcierre,
								cast('' as varchar) as fechavencimiento,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2, 
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
								case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
							    a.idoperador ,
							    c.nombreoperador ,
							    a.idmecanizadooperador,
							    cast('' as varchar) as nombremecanizadooperador,
							    a.idsuborigenncf,
							    v.nombresuborigen
				 	 	    FROM traking.mct_gestionncf a
							left join  traking.mct_operador  c  	   on c.idoperador  = a.idoperador  
							left join  traking.mct_detallehojarutatemp g on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	   on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	   on h.idcomponente = i.idcomponente 
							left join  traking.mct_material j 		   on h.idmaterial = j.idmaterial 
							left join  traking.mct_ordentrabajo k 	   on h.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		   on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		   on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	   on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o           on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p   on replace(l.planogeneral,' ','') = p.plano 
							left join  traking.mct_gestionncfadjunto q on a.idgestionncf = q.idgestionncf  and q.correlativo = 0
							left join  traking.mct_debaja r			   on a.iddebaja = r.iddebaja 
							left join  traking.mct_origenncf s		   on s.idorigenncf = a.idorigenncf 
							left join  traking.mct_accionncf  t		   on t.idaccionncf = a.idaccionncf 
							left join  traking.mct_tipogestionncf  u   on u.idtipogestionncf = a.idtipogestionncf
							left join  traking.mct_suborigenncf v      on v.idsuborigenncf = a.idsuborigenncf
						   where a.idordentrabajo = idot
				        order by a.idgestionncf
					)
				loop
				
					sp_cantidad := 0;

				    select count(*)
				      into sp_cantidad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				        
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
				
				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion
				       and (length(d.tipo) > 0);
   
				   
				         item 							:= rec1.item;
				         idgestionncf 			        := rec1.idgestionncf;
				         codhojaruta 					:= rec1.codhojaruta;	
				         idoperador						:= rec1.idoperador;
				         nombreoperador					:= rec1.nombreoperador;
				         idorigenncf 					:= rec1.idorigenncf;
         				 nombreorigenncf 				:= rec1.nombreorigen;
         				 idaccionncf 					:= rec1.idaccionncf;
         				 nombreaccionncf 				:= rec1.nombreaccion;
         				 correlativo 					:= rec1.correlativo;
         				 idcomponente 					:= rec1.idcomponente;
         				 nombrecomponente 				:= rec1.nombrecomponente;
				         idordentrabajo 				:= rec1.idordentrabajo;
         				 comentariofundicion 			:= rec1.comentariofundicion;
         				 nombreplano 					:= rec1.planocomponente; 
         				 idestadogestionncf 			:= rec1.idestadogestionncf;
         				 iddebaja 						:= rec1.iddebaja; 
         				 nombredebaja 					:= rec1.nombredebaja;
         				 urgente 						:= rec1.urgente;
         				 dardebaja 						:= rec1.dardebaja;
         				 observacion 					:= rec1.observacion; 
         				 gestionncfvalidado 			:= rec1.gestionncfvalidado; 
         				 fechavalidaciongestionncf 		:= rec1.fechavalidaciongestionncf;
                         idtipogestionncf 				:= rec1.idtipogestionncf;
         				 nombretipogestionncf 			:= rec1.nombretipogestionncf; 
         				 descripciongeneralgestionncf 	:= rec1.descripciongeneralgestionncf;
         				 jsontipogestionncf 			:= rec1.jsontipogestionncf;
         				 --nota 							:= rec1.nota;
         				 idcierre 						:= rec1.idcierre;
         				 usuariocreacion				:= rec1.usuariocreacion;
				         fechacreacion 					:= rec1.fechacreacion; 
				         usuariomodificacion 			:= rec1.usuariomodificacion;
				         fechamodificacion 				:= rec1.fechamodificacion;
				         equipo 						:= rec1.equipo; 
         				 planogeneral 					:= rec1.planogeneral; 
         				 critica 						:= rec1.critica; 
         				 sigla 							:= rec1.sigla; 
         				 material 						:= rec1.nombrematerial; 						
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
				      				        
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;   
				        				        		 
				         atrasovalidacion	:= false;
				         if (rec1.gestionncfvalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciongestionncf)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriagestionncfvalido a,
						           mct_gestionncf b
						     where b.idgestionncf = rec1.idgestionncf
						       and a.idgestionncf = b.idgestionncf ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;						  
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_gestionncfcausa a,
				                mct_gestionncfcausaaccion b,
				                mct_gestionncfcausaaccionpdf c
				          where a.idgestionncf = rec1.idgestionncf
				            and a.idgestionncfcausa  = b.idgestionncfcausa 
				            and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;

				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	:= sp_fechavenc;
						 nota 				:= rec1.nota;
						 idmecanizadooperador		:= rec1.idmecanizadooperador;
						 nombremecanizadooperador	:= rec1.nombremecanizadooperador;
						 idsuborigen				:= rec1.idsuborigenncf;
						 nombresuborigen			:= rec1.nombresuborigen;
						
						 --to_char(rec1.fechacreacion::TIMESTAMP + '24 hr'::interval, 'yyyy-mm-dd hh24:mi:ss'); -- suma 24 horas desde creada la ot
						 
						 -- Estrategia
						
						 select max(b.fechacreacion)
						   into sp_fechasubepdf
						 from mct_gestionncfpdf b 
						 where b.idgestionncf = rec1.idgestionncf
						   and b.idtipoarchivogestionncf = 1;
						 
						 if (sp_fechasubepdf <= rec1.fechacreacion2::TIMESTAMP + '96 hr'::interval) then
						 
						 	if (select 1
						 	      from mct_gestionncfpdf  
						 	     where idgestionncf = rec1.idgestionncf
						 	       and idtipoarchivogestionncf = 1) then   
						 
								 subeest 					:= cast(1 as bigint);
							     subeestentiempo 			:= cast(1 as bigint);
						    
						    else
						    
						    	 subeest 					:= cast(0 as bigint);
							     subeestentiempo 			:= cast(0 as bigint);
						    
						    end if;
						 
						 else
						 
						 	if (select 1
						 	      from mct_gestionncfpdf  
						 	     where idgestionncf = rec1.idgestionncf
						 	       and idtipoarchivogestionncf = 1) then   
						 
								 subeest 					:= cast(1 as bigint);
							     subeestentiempo 			:= cast(0 as bigint);
						    
						    else
						    
						    	 subeest 					:= cast(0 as bigint);
							     subeestentiempo 			:= cast(0 as bigint);
						    
						    end if;						 
						 
						 end if;
						
						
						 -- Resultados y datos
						
						 select max(b.fechacreacion)
						   into sp_fechasubepdf
						 from mct_gestionncfpdf b 
						 where b.idgestionncf = rec1.idgestionncf
						   and b.idtipoarchivogestionncf = 2;
						  
						 if (sp_fechasubepdf <= rec1.fechacreacion2::TIMESTAMP + '96 hr'::interval) then
						 
						 	if (select 1
						 	      from mct_gestionncfpdf a 
						 	     where a.idgestionncf = rec1.idgestionncf
						 	       and a.idtipoarchivogestionncf = 2) then   
						 
								 suberes 					:= cast(1 as bigint);
							     suberesentiempo 			:= cast(1 as bigint);
						    
						    else
						    
						    	 suberes 					:= cast(0 as bigint);
							     suberesentiempo 			:= cast(0 as bigint);
						    
						    end if;
						 
						 else
						 
						 	if (select 1
						 	      from mct_gestionncfpdf a  
						 	     where a.idgestionncf = rec1.idgestionncf
						 	       and a.idtipoarchivogestionncf = 2) then   
						 
								 suberes 					:= cast(1 as bigint);
							     suberesentiempo 			:= cast(0 as bigint);
						    
						    else
						    
						    	 suberes 					:= cast(0 as bigint);
							     suberesentiempo 			:= cast(0 as bigint);
						    
						    end if;						 
						 
						 end if;
						
					    
						 if (select 1
						 	   from mct_gestionncfpdf  a 
						 	  where a.idgestionncf = rec1.idgestionncf
						        and a.idtipoarchivogestionncf = 3) then   
						 
								subeacc 					:= cast(1 as bigint);
						     	subeaccentiempo 			:= cast(1 as bigint);
						    
						 else
						    
								subeacc 					:= cast(0 as bigint);
						     	subeaccentiempo 			:= cast(0 as bigint);
						    
						 end if;
						  
						 if (select 1
						 	   from mct_gestionncfpdf  a
						 	  where a.idgestionncf = rec1.idgestionncf
						        and a.idtipoarchivogestionncf = 4) then   
						 
								subekpi 					:= cast(1 as bigint);
						     	subekpientiempo 			:= cast(1 as bigint);
						    
						 else
						    
								subekpi 					:= cast(0 as bigint);
						     	subekpientiempo 			:= cast(0 as bigint);
						    
						 end if;
						
         			
					return next;
			
				end loop;

				
		 elsif ( startdate != 'NA' and enddate != 'NA'  ) then
		 
		 		--RETURN QUERY
		 	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncf,
								a.codhojaruta,
								a.idorigenncf ,
								s.nombreorigen ,
								a.idaccionncf ,
								t.nombreaccion ,
								a.correlativo ,
								h.idcomponente ,
								i.nombrecomponente ,
								a.idordentrabajo ,
								a.comentariofundicion ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
								a.idestadogestionncf ,
								a.iddebaja ,
								r.nombredebaja ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.gestionncfvalidado ,
								cast(to_char(a.fechavalidaciongestionncf , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciongestionncf,
								a.idtipogestionncf ,
								u.nombretipogestionncf ,
								a.descripciongeneralgestionncf,
								a.jsontipogestionncf,
								a.nota ,
								a.idcierre,
								cast('' as varchar) as fechavencimiento,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2, 
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
								case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
							    a.idoperador ,
							    c.nombreoperador ,
							    a.idmecanizadooperador,
							    cast('' as varchar) as nombremecanizadooperador,
							    a.idsuborigenncf,
							    v.nombresuborigen
				 	 	    FROM traking.mct_gestionncf a
							left join  traking.mct_operador  c  	   on c.idoperador  = a.idoperador  
							left join  traking.mct_detallehojarutatemp g on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	   on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	   on h.idcomponente = i.idcomponente 
							left join  traking.mct_material j 		   on h.idmaterial = j.idmaterial 
							left join  traking.mct_ordentrabajo k 	   on h.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		   on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		   on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	   on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o           on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p   on replace(l.planogeneral,' ','') = p.plano 
							left join  traking.mct_gestionncfadjunto q on a.idgestionncf = q.idgestionncf  and q.correlativo = 0
							left join  traking.mct_debaja r			   on a.iddebaja = r.iddebaja 
							left join  traking.mct_origenncf s		   on s.idorigenncf = a.idorigenncf 
							left join  traking.mct_accionncf  t		   on t.idaccionncf = a.idaccionncf 
							left join  traking.mct_tipogestionncf  u   on u.idtipogestionncf = a.idtipogestionncf 
							left join  traking.mct_suborigenncf v      on v.idsuborigenncf = a.idsuborigenncf
				 	  	where 
				 	  	    (a.fechavencimiento  >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				            a.fechavencimiento <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				            --and
				 	  	    --a.iddefectofundicion = iddefectofuncioni
				 	  	    )
				 	loop 

					sp_cantidad := 0;
--				    select count(*)
--				      into sp_cantidad
--				      from mct_defectofundicion md 
--				     where idcomponente = rec1.idcomponente;
--				    
				    select count(*)
				      into sp_cantidad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				      
				     
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
						

				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion
				       and (length(d.tipo) > 0);
				      
				         item 							:= rec1.item;
				         idgestionncf 			        := rec1.idgestionncf;
				         codhojaruta 					:= rec1.codhojaruta;
				         idoperador						:= rec1.idoperador;
				         nombreoperador					:= rec1.nombreoperador;
				         idorigenncf 					:= rec1.idorigenncf;
         				 nombreorigenncf 				:= rec1.nombreorigen;
         				 idaccionncf 					:= rec1.idaccionncf;
         				 nombreaccionncf 				:= rec1.nombreaccion;
         				 correlativo 					:= rec1.correlativo;
         				 idcomponente 					:= rec1.idcomponente;
         				 nombrecomponente 				:= rec1.nombrecomponente;
				         idordentrabajo 				:= rec1.idordentrabajo;
         				 comentariofundicion 			:= rec1.comentariofundicion;
         				 nombreplano 					:= rec1.planocomponente; 
         				 idestadogestionncf 			:= rec1.idestadogestionncf;
         				 iddebaja 						:= rec1.iddebaja; 
         				 nombredebaja 					:= rec1.nombredebaja;
         				 urgente 						:= rec1.urgente;
         				 dardebaja 						:= rec1.dardebaja;
         				 observacion 					:= rec1.observacion; 
         				 gestionncfvalidado 			:= rec1.gestionncfvalidado; 
         				 fechavalidaciongestionncf 		:= rec1.fechavalidaciongestionncf;
                         idtipogestionncf 				:= rec1.idtipogestionncf;
         				 nombretipogestionncf 			:= rec1.nombretipogestionncf; 
         				 descripciongeneralgestionncf 	:= rec1.descripciongeneralgestionncf;
         				 jsontipogestionncf 			:= rec1.jsontipogestionncf;
         				 --nota 							:= rec1.nota;
         				 idcierre 						:= rec1.idcierre;
         				 usuariocreacion				:= rec1.usuariocreacion;
				         fechacreacion 					:= rec1.fechacreacion; 
				         usuariomodificacion 			:= rec1.usuariomodificacion;
				         fechamodificacion 				:= rec1.fechamodificacion;
				         equipo 						:= rec1.equipo; 
         				 planogeneral 					:= rec1.planogeneral; 
         				 critica 						:= rec1.critica; 
         				 sigla 							:= rec1.sigla; 
         				 material 						:= rec1.nombrematerial; 						
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
				        		
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;      
				        
				         atrasovalidacion	:= false;
				         if (rec1.gestionncfvalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciongestionncf)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriagestionncfvalido a,
						           mct_gestionncf b
						     where b.idgestionncf = rec1.idgestionncf
						       and a.idgestionncf = b.idgestionncf ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;						   
--						    if (sp_horas > 0) then
--						    	atrasovalidacion	:= true;						    
--						    end if;
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_gestionncfcausa a,
				                mct_gestionncfcausaaccion b,
				                mct_gestionncfcausaaccionpdf c
				          where a.idgestionncf = rec1.idgestionncf
				            and a.idgestionncfcausa  = b.idgestionncfcausa 
				            and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;			
				        
				         jsontipogestionncf	:= rec1.jsontipogestionncf;
				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	:= sp_fechavenc;
                         --fechavencimiento	:= rec1.fechavencimiento;
						 nota 				:= rec1.nota;
						 idmecanizadooperador		:= rec1.idmecanizadooperador;
						 nombremecanizadooperador	:= rec1.nombremecanizadooperador;
				 		 idsuborigen				:= rec1.idsuborigenncf;
				 		 nombresuborigen			:= rec1.nombresuborigen;
				 		
						 -- Estrategia
						 select max(b.fechacreacion)
						   into sp_fechasubepdf
						 from mct_gestionncfpdf b 
						 where b.idgestionncf = rec1.idgestionncf
						   and b.idtipoarchivogestionncf = 1;
						 
						 if (sp_fechasubepdf <= rec1.fechacreacion2::TIMESTAMP + '96 hr'::interval) then
						 
						 	if (select 1
						 	      from mct_gestionncfpdf a 
						 	     where a.idgestionncf = rec1.idgestionncf
						 	       and a.idtipoarchivogestionncf = 1) then   
						 
								 subeest 					:= cast(1 as bigint);
							     subeestentiempo 			:= cast(1 as bigint);
						    
						    else
						    
						    	 subeest 					:= cast(0 as bigint);
							     subeestentiempo 			:= cast(0 as bigint);
						    
						    end if;
						 
						 else
						 
						 	if (select 1
						 	      from mct_gestionncfpdf  a
						 	     where a.idgestionncf = rec1.idgestionncf
						 	       and a.idtipoarchivogestionncf = 1) then   
						 
								 subeest 					:= cast(1 as bigint);
							     subeestentiempo 			:= cast(0 as bigint);
						    
						    else
						    
						    	 subeest 					:= cast(0 as bigint);
							     subeestentiempo 			:= cast(0 as bigint);
						    
						    end if;						 
						 
						 end if;
						
						 -- Resultados y datos
						 select max(b.fechacreacion)
						   into sp_fechasubepdf
						 from mct_gestionncfpdf b 
						 where b.idgestionncf = rec1.idgestionncf
						   and b.idtipoarchivogestionncf = 2;
						  
						 if (sp_fechasubepdf <= rec1.fechacreacion2::TIMESTAMP + '96 hr'::interval) then
						 
						 	if (select 1
						 	      from mct_gestionncfpdf  a
						 	     where a.idgestionncf = rec1.idgestionncf
						 	       and a.idtipoarchivogestionncf = 2) then   
						 
								 suberes 					:= cast(1 as bigint);
							     suberesentiempo 			:= cast(1 as bigint);
						    
						    else
						    
						    	 suberes 					:= cast(0 as bigint);
							     suberesentiempo 			:= cast(0 as bigint);
						    
						    end if;
						 
						 else
						 
						 	if (select 1
						 	      from mct_gestionncfpdf  a
						 	     where a.idgestionncf = rec1.idgestionncf
						 	       and a.idtipoarchivogestionncf = 2) then   
						 
								 suberes 					:= cast(1 as bigint);
							     suberesentiempo 			:= cast(0 as bigint);
						    
						    else
						    
						    	 suberes 					:= cast(0 as bigint);
							     suberesentiempo 			:= cast(0 as bigint);
						    
						    end if;						 
						 
						 end if;
						
					    
						 if (select 1
						 	   from mct_gestionncfpdf  a
						 	  where a.idgestionncf = rec1.idgestionncf
						        and a.idtipoarchivogestionncf = 3) then   
						 
								subeacc 					:= cast(1 as bigint);
						     	subeaccentiempo 			:= cast(1 as bigint);
						    
						 else
						    
								subeacc 					:= cast(0 as bigint);
						     	subeaccentiempo 			:= cast(0 as bigint);
						    
						 end if;
						  
						 if (select 1
						 	   from mct_gestionncfpdf  a
						 	  where a.idgestionncf = rec1.idgestionncf
						        and a.idtipoarchivogestionncf = 4) then   
						 
								subekpi 					:= cast(1 as bigint);
						     	subekpientiempo 			:= cast(1 as bigint);
						    
						 else
						    
								subekpi 					:= cast(0 as bigint);
						     	subekpientiempo 			:= cast(0 as bigint);
						    
						 end if;
		
				 
				 	return next;
				 
				 	end loop;
		     end if;
		 
END;
$$;


ALTER FUNCTION traking.evtlistgestionncfv2(idot bigint, startdate character varying, enddate character varying) OWNER TO postgres;

--
-- TOC entry 1904 (class 1255 OID 17004)
-- Name: evtlistgestionncfv3(bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistgestionncfv3(idot bigint, startdate character varying, enddate character varying, origenes character varying) RETURNS TABLE(item bigint, idgestionncf bigint, codhojaruta character varying, idoperador bigint, nombreoperador character varying, idorigenncf bigint, nombreorigenncf character varying, idaccionncf bigint, nombreaccionncf character varying, correlativo bigint, idcomponente bigint, nombrecomponente character varying, idordentrabajo bigint, comentariofundicion character varying, nombreplano character varying, idestadogestionncf bigint, iddebaja bigint, nombredebaja character varying, urgente boolean, dardebaja boolean, observacion character varying, gestionncfvalidado boolean, fechavalidaciongestionncf character varying, idtipogestionncf bigint, nombretipogestionncf character varying, descripciongeneralgestionncf character varying, jsontipogestionncf character varying, nota bigint, idcierre bigint, fechavencimiento character varying, usuariocreacion character varying, fechacreacion character varying, usuariomodificacion character varying, fechamodificacion timestamp without time zone, equipo character varying, planogeneral character varying, critica character varying, sigla character varying, material character varying, cantidad bigint, repetitividad bigint, pendientecarga boolean, atrasovalidacion boolean, atrasocarga boolean, idmecanizadooperador bigint, nombremecanizadooperador character varying, idsuborigen bigint, nombresuborigen character varying, cursadaa character varying, idcliente bigint, nombrecliente character varying)
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;
    
    sp_totalrespaldos 	bigint;
    sp_totalcargas		bigint;
   
    sp_horas			bigint;
    sp_atrasocarga		bigint;
    sp_diasem			bigint;
   
    sp_fechavenc		varchar;

    v_ids               int[];

BEGIN
-- iddefectoi = -1: Todos
     
   v_ids := regexp_split_to_array(origenes, '\s*,\s*')::int[];
	     
		 IF ( idot > 0 )  THEN 
	     -- Todos

	      	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncf,
								a.codhojaruta,
								a.idorigenncf ,
								--s.nombreorigen ,
                                s.alias as nombreorigen,
								a.idaccionncf ,
								t.nombreaccion ,
								a.correlativo ,
								h.idcomponente ,
								i.nombrecomponente ,
								a.idordentrabajo ,
								a.comentariofundicion ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
								a.idestadogestionncf ,
								a.iddebaja ,
								r.nombredebaja ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.gestionncfvalidado ,
								cast(to_char(a.fechavalidaciongestionncf , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciongestionncf,
								a.idtipogestionncf ,
								u.nombretipogestionncf ,
								a.descripciongeneralgestionncf,
								a.jsontipogestionncf,
								a.nota ,
								a.idcierre,
								cast('' as varchar) as fechavencimiento,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2, 
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
								case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
							    a.idoperador ,
							    c.nombreoperador ,
							    a.idmecanizadooperador,
							    cast('' as varchar) as nombremecanizadooperador,
							    a.idsuborigenncf,
							    v.nombresuborigen,
                                s.responsable as cursadaa,
                                k.idcliente,
                                vv.nombrecliente
				 	 	    FROM traking.mct_gestionncf a
							left join  traking.mct_operador  c  	   on c.idoperador  = a.idoperador  
							left join  traking.mct_detallehojarutatemp g on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	   on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	   on h.idcomponente = i.idcomponente 
							left join  traking.mct_material j 		   on h.idmaterial = j.idmaterial 
							left join  traking.mct_ordentrabajo k 	   on a.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		   on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		   on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	   on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o           on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p   on replace(l.planogeneral,' ','') = p.plano 
							left join  traking.mct_gestionncfadjunto q on a.idgestionncf = q.idgestionncf  and q.correlativo = 0
							left join  traking.mct_debaja r			   on a.iddebaja = r.iddebaja 
							left join  traking.mct_origenncf s		   on s.idorigenncf = a.idorigenncf 
							left join  traking.mct_accionncf  t		   on t.idaccionncf = a.idaccionncf 
							left join  traking.mct_tipogestionncf  u   on u.idtipogestionncf = a.idtipogestionncf
							left join  traking.mct_suborigenncf v      on v.idsuborigenncf = a.idsuborigenncf
                            left join  traking.mct_cliente vv          on vv.idcliente = k.idcliente
						   where a.idordentrabajo = idot
                             and a.idorigenncf = ANY(v_ids)
				        order by a.idgestionncf
					)
				loop
				
					sp_cantidad := 0;

				    select count(*)
				      into sp_cantidad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				        
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
				
				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion
				       and (length(d.tipo) > 0);
   
				   
				         item 							:= rec1.item;
				         idgestionncf 			        := rec1.idgestionncf;
				         codhojaruta 					:= rec1.codhojaruta;	
				         idoperador						:= rec1.idoperador;
				         nombreoperador					:= rec1.nombreoperador;
				         idorigenncf 					:= rec1.idorigenncf;
         				 nombreorigenncf 				:= rec1.nombreorigen;
         				 idaccionncf 					:= rec1.idaccionncf;
         				 nombreaccionncf 				:= rec1.nombreaccion;
         				 correlativo 					:= rec1.correlativo;
         				 idcomponente 					:= rec1.idcomponente;
         				 nombrecomponente 				:= rec1.nombrecomponente;
				         idordentrabajo 				:= rec1.idordentrabajo;
         				 comentariofundicion 			:= rec1.comentariofundicion;
         				 nombreplano 					:= rec1.planocomponente; 
         				 idestadogestionncf 			:= rec1.idestadogestionncf;
         				 iddebaja 						:= rec1.iddebaja; 
         				 nombredebaja 					:= rec1.nombredebaja;
         				 urgente 						:= rec1.urgente;
         				 dardebaja 						:= rec1.dardebaja;
         				 observacion 					:= rec1.observacion; 
         				 gestionncfvalidado 			:= rec1.gestionncfvalidado; 
         				 fechavalidaciongestionncf 		:= rec1.fechavalidaciongestionncf;
                         idtipogestionncf 				:= rec1.idtipogestionncf;
         				 nombretipogestionncf 			:= rec1.nombretipogestionncf; 
         				 descripciongeneralgestionncf 	:= rec1.descripciongeneralgestionncf;
         				 jsontipogestionncf 			:= rec1.jsontipogestionncf;
         				 --nota 							:= rec1.nota;
         				 idcierre 						:= rec1.idcierre;
         				 usuariocreacion				:= rec1.usuariocreacion;
				         fechacreacion 					:= rec1.fechacreacion; 
				         usuariomodificacion 			:= rec1.usuariomodificacion;
				         fechamodificacion 				:= rec1.fechamodificacion;
				         equipo 						:= rec1.equipo; 
         				 planogeneral 					:= rec1.planogeneral; 
         				 critica 						:= rec1.critica; 
         				 sigla 							:= rec1.sigla; 
         				 material 						:= rec1.nombrematerial; 						
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
				      				        
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;   
				        				        		 
				         atrasovalidacion	:= false;
				         if (rec1.gestionncfvalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciongestionncf)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriagestionncfvalido a,
						           mct_gestionncf b
						     where b.idgestionncf = rec1.idgestionncf
						       and a.idgestionncf = b.idgestionncf ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;
						   
--						    if (sp_horas > 0) then
--						    	atrasovalidacion	:= true;						    
--						    end if;
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_gestionncfcausa a,
				                mct_gestionncfcausaaccion b,
				                mct_gestionncfcausaaccionpdf c
				          where a.idgestionncf = rec1.idgestionncf
				            and a.idgestionncfcausa  = b.idgestionncfcausa 
				            and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;

				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	:= sp_fechavenc;
                         --fechavencimiento	:= rec1.fechavencimiento;
						 nota 				:= rec1.nota;
						 idmecanizadooperador		:= rec1.idmecanizadooperador;
						 nombremecanizadooperador	:= rec1.nombremecanizadooperador;
						 idsuborigen				:= rec1.idsuborigenncf;
						 nombresuborigen			:= rec1.nombresuborigen;
                         cursadaa					:= rec1.cursadaa;

                         idcliente					:= rec1.idcliente;
                         nombrecliente				:= rec1.nombrecliente;
         			
				return next;
			
				end loop;

				
		 elsif ( startdate != 'NA' and enddate != 'NA'  ) then
		 
		 		--RETURN QUERY
		 	    FOR rec1 IN (   
						SELECT  ROW_NUMBER() OVER (ORDER BY a.fechacreacion asc) AS item,
								a.idgestionncf,
								a.codhojaruta,
								a.idorigenncf ,
								--s.nombreorigen ,
                                s.alias as nombreorigen,
								a.idaccionncf ,
								t.nombreaccion ,
								a.correlativo ,
								h.idcomponente ,
								i.nombrecomponente ,
								a.idordentrabajo ,
								a.comentariofundicion ,
								cast(replace(h.nombreplano,' ', '') as varchar) as planocomponente,
								a.idestadogestionncf ,
								a.iddebaja ,
								r.nombredebaja ,
								a.urgente ,
								a.dardebaja ,
								a.observacion  ,
								a.gestionncfvalidado ,
								cast(to_char(a.fechavalidaciongestionncf , 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechavalidaciongestionncf,
								a.idtipogestionncf ,
								u.nombretipogestionncf ,
								a.descripciongeneralgestionncf,
								a.jsontipogestionncf,
								a.nota ,
								a.idcierre,
								cast('' as varchar) as fechavencimiento,
								a.usuariocreacion ,
								a.fechacreacion as fechacreacion2, 
								cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
								a.usuariomodificacion,
								a.fechamodificacion,
								cast(n.sigla ||' '||m.nombremodelo as varchar) as equipo,
							    cast(replace(l.planogeneral,' ','') as varchar) as planogeneral,
								case
							      when p.plano != '' then 
							           cast('BBA_CRI' as varchar)
							      when (p.plano = '' or p.plano is null) and o.sigla = 'REP' then
							           cast('BBA_REP' as varchar)
							      else cast('BBA_OTR' as varchar)
							    end as critica,
							    o.sigla ,
							    j.nombrematerial ,
							    a.idoperador ,
							    c.nombreoperador ,
							    a.idmecanizadooperador,
							    cast('' as varchar) as nombremecanizadooperador,
							    a.idsuborigenncf,
							    v.nombresuborigen,
                                s.responsable as cursadaa,
                                k.idcliente,
                                vv.nombrecliente
				 	 	    FROM traking.mct_gestionncf a
							left join  traking.mct_operador  c  	   on c.idoperador  = a.idoperador  
							left join  traking.mct_detallehojarutatemp g on a.codhojaruta = g.codhojaruta 
							left join  traking.mct_hojarutatemp h 	   on g.idhojarutatemp = h.idhojarutatemp 
							left join  traking.mct_componente i 	   on h.idcomponente = i.idcomponente 
							left join  traking.mct_material j 		   on h.idmaterial = j.idmaterial 
							left join  traking.mct_ordentrabajo k 	   on a.idordentrabajo = k.idordentrabajo 
							left join  traking.mct_producto l 		   on k.idproducto = l.idproducto 
							left join  traking.mct_modelo m 		   on l.idmodelo = m.idmodelo 
							left join  traking.mct_subfamilia n 	   on m.idsubfamilia = n.idsubfamilia 
					    	left join  traking.mct_familia o           on n.idfamilia = o.idfamilia 
							left join  traking.mct_planobbacritica p   on replace(l.planogeneral,' ','') = p.plano 
							left join  traking.mct_gestionncfadjunto q on a.idgestionncf = q.idgestionncf  and q.correlativo = 0
							left join  traking.mct_debaja r			   on a.iddebaja = r.iddebaja 
							left join  traking.mct_origenncf s		   on s.idorigenncf = a.idorigenncf 
							left join  traking.mct_accionncf  t		   on t.idaccionncf = a.idaccionncf 
							left join  traking.mct_tipogestionncf  u   on u.idtipogestionncf = a.idtipogestionncf 
							left join  traking.mct_suborigenncf v      on v.idsuborigenncf = a.idsuborigenncf
                            left join  traking.mct_cliente vv          on vv.idcliente = k.idcliente
				 	  	where 
				 	  	    (a.fechacreacion  >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				            a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
                          and a.idorigenncf = ANY(v_ids)
				            --and
				 	  	    --a.iddefectofundicion = iddefectofuncioni
				 	  	    )
				 	loop 

					sp_cantidad := 0;
--				    select count(*)
--				      into sp_cantidad
--				      from mct_defectofundicion md 
--				     where idcomponente = rec1.idcomponente;
--				    
				    select count(*)
				      into sp_cantidad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente;
				      
				      
				     
				    sp_repetitividad := 0;
				    select count(*)
				      into sp_repetitividad
				      from mct_gestionncf a,
				           mct_detallehojarutatemp b,
				           mct_hojarutatemp c
				     where a.codhojaruta = b.codhojaruta
				       and b.idhojarutatemp = c.idhojarutatemp 
				       and replace(c.nombreplano, ' ', '') = rec1.planocomponente
				       and c.idordentrabajo = rec1.idordentrabajo;
						

				    select count(d.*)
				      into sp_totalrespaldos
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion ;
				    
				    select count(d.*)
				      into sp_totalcargas
				      from mct_gestionncf a,
				           mct_gestionncfcausa b,
				           mct_gestionncfcausaaccion c,
				           mct_gestionncfcausaaccionpdf d
				     where a.idgestionncf = rec1.idgestionncf
				       and a.idgestionncf = b.idgestionncf 
				       and b.idgestionncfcausa = c.idgestionncfcausa 
				       and c.idgestionncfcausaaccion = d.idgestionncfcausaaccion
				       and (length(d.tipo) > 0);
				      
				         item 							:= rec1.item;
				         idgestionncf 			        := rec1.idgestionncf;
				         codhojaruta 					:= rec1.codhojaruta;
				         idoperador						:= rec1.idoperador;
				         nombreoperador					:= rec1.nombreoperador;
				         idorigenncf 					:= rec1.idorigenncf;
         				 nombreorigenncf 				:= rec1.nombreorigen;
         				 idaccionncf 					:= rec1.idaccionncf;
         				 nombreaccionncf 				:= rec1.nombreaccion;
         				 correlativo 					:= rec1.correlativo;
         				 idcomponente 					:= rec1.idcomponente;
         				 nombrecomponente 				:= rec1.nombrecomponente;
				         idordentrabajo 				:= rec1.idordentrabajo;
         				 comentariofundicion 			:= rec1.comentariofundicion;
         				 nombreplano 					:= rec1.planocomponente; 
         				 idestadogestionncf 			:= rec1.idestadogestionncf;
         				 iddebaja 						:= rec1.iddebaja; 
         				 nombredebaja 					:= rec1.nombredebaja;
         				 urgente 						:= rec1.urgente;
         				 dardebaja 						:= rec1.dardebaja;
         				 observacion 					:= rec1.observacion; 
         				 gestionncfvalidado 			:= rec1.gestionncfvalidado; 
         				 fechavalidaciongestionncf 		:= rec1.fechavalidaciongestionncf;
                         idtipogestionncf 				:= rec1.idtipogestionncf;
         				 nombretipogestionncf 			:= rec1.nombretipogestionncf; 
         				 descripciongeneralgestionncf 	:= rec1.descripciongeneralgestionncf;
         				 jsontipogestionncf 			:= rec1.jsontipogestionncf;
         				 --nota 							:= rec1.nota;
         				 idcierre 						:= rec1.idcierre;
         				 usuariocreacion				:= rec1.usuariocreacion;
				         fechacreacion 					:= rec1.fechacreacion; 
				         usuariomodificacion 			:= rec1.usuariomodificacion;
				         fechamodificacion 				:= rec1.fechamodificacion;
				         equipo 						:= rec1.equipo; 
         				 planogeneral 					:= rec1.planogeneral; 
         				 critica 						:= rec1.critica; 
         				 sigla 							:= rec1.sigla; 
         				 material 						:= rec1.nombrematerial; 						
				         cantidad 						:= sp_cantidad;
				         repetitividad					:= sp_repetitividad;
				        		
				         pendientecarga	:= false;
				         if (sp_totalrespaldos > 0) then		
				             if (sp_totalcargas < sp_totalrespaldos ) then 
				                 pendientecarga	:= true;
				             end if;
				         else
				             pendientecarga	:= true;
				         end if;      
				        
				         atrasovalidacion	:= false;
				         if (rec1.gestionncfvalidado is true) then
				         
							SELECT coalesce(round(( EXTRACT(EPOCH FROM b.fechavalidaciongestionncf)-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600), 0) as hours ,
							       date_part('dow', a.fechacreacion) as diasem
							       --a.fechacreacion
						      into sp_horas,
						           sp_diasem
						      from mct_auditoriagestionncfvalido a,
						           mct_gestionncf b
						     where b.idgestionncf = rec1.idgestionncf
						       and a.idgestionncf = b.idgestionncf ;
						   
						    if (sp_diasem = 5) then
						        if sp_horas > 144 then
						           atrasovalidacion	:= true;
						        end if;
						    elsif (sp_diasem = 4) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    elsif (sp_diasem = 3) then
						           if sp_horas > 120 then
						              atrasovalidacion	:= true;
						           end if;
						    else
						         if sp_horas > 72 then
						              atrasovalidacion	:= true;
						         end if;
						    end if;						   
--						    if (sp_horas > 0) then
--						    	atrasovalidacion	:= true;						    
--						    end if;
				         
				         end if;
				        
				         atrasocarga	:= false;
				        
				         select count(*)
				           into sp_atrasocarga
				           from mct_gestionncfcausa a,
				                mct_gestionncfcausaaccion b,
				                mct_gestionncfcausaaccionpdf c
				          where a.idgestionncf = rec1.idgestionncf
				            and a.idgestionncfcausa  = b.idgestionncfcausa 
				            and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
				            and c.fechamodificacion > b.fechaejecucion ;
				    				        
				         if (sp_atrasocarga > 0) then
				             atrasocarga	:= true;
				         end if;			
				        
				         jsontipogestionncf	:= rec1.jsontipogestionncf;
				        
				         select *
	                       into sp_fechavenc
	                       from traking.calculavencimientodefecto(rec1.fechacreacion2);
	      
                         fechavencimiento	        := sp_fechavenc;
                         --fechavencimiento	          := rec1.fechavencimiento;
						 nota 				        := rec1.nota;
						 idmecanizadooperador		:= rec1.idmecanizadooperador;
						 nombremecanizadooperador	:= rec1.nombremecanizadooperador;
				 		 idsuborigen				:= rec1.idsuborigenncf;
				 		 nombresuborigen			:= rec1.nombresuborigen;
                         cursadaa					:= rec1.cursadaa;
 
                         idcliente					:= rec1.idcliente;
                         nombrecliente				:= rec1.nombrecliente;
				 
				 	return next;
				 
				 	end loop;
		     end if;
		 
END;
$$;


ALTER FUNCTION traking.evtlistgestionncfv3(idot bigint, startdate character varying, enddate character varying, origenes character varying) OWNER TO postgres;

--
-- TOC entry 2150 (class 1255 OID 17006)
-- Name: evtlistguiadesppdfapp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistguiadesppdfapp(idworkorders bigint) RETURNS TABLE(idworkorder bigint, picfile text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
			select a.idordentrabajo ,
			       --split_part(archivoadjunto,'data:image/jpeg;base64,',2)
			        replace (a.archivoadjunto,'data:application/pdf;base64,','') 
			  from mct_infcotipdf a
			 where a.idordentrabajo = idworkorders 
			   and a.nombrearchivo like 'GDS_%'
			   and a.idproceso in ( 3,10, 9);
END;
$$;


ALTER FUNCTION traking.evtlistguiadesppdfapp(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1122 (class 1255 OID 17007)
-- Name: evtlistguiaepdfapp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistguiaepdfapp(idworkorders bigint) RETURNS TABLE(idworkorder bigint, picfile text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
			select a.idordentrabajo ,
			       --split_part(archivoadjunto,'data:image/jpeg;base64,',2)
			        replace (a.archivoadjunto,'data:application/pdf;base64,','') 
			  from mct_infcotipdf a
			 where a.idordentrabajo = idworkorders 
			   and a.nombrearchivo like 'GDE_%'
			   and a.infcoti = 20
			   and a.idproceso = 2;
END;
$$;


