ALTER FUNCTION traking.evtlistguiaspdfapp(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 2140 (class 1255 OID 17009)
-- Name: evtlistheadtracing(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistheadtracing(idworkorders bigint) RETURNS TABLE(workordername character varying, blueprintname character varying, idproduct bigint, productname character varying, purchase bigint, quotation bigint, deliverydate timestamp without time zone, idorderstatus bigint, orderstatusname character varying, timedelay integer, quantitytot integer, quantitylcc integer, quantityrtm integer, percentlcc character varying, percentrtm character varying)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombreordentrabajo   varchar; 
		sp_planogeneral 		varchar;
		sp_idproducto           integer;
		sp_nombreproducto		varchar;
		sp_ordencompra          bigint;
		sp_idcotizacion         integer;
		sp_fechaentrega			timestamp;
		sp_idestadoorden        integer;
		sp_nombreestado         varchar;
		sp_minutos              integer;	       
		sp_cantidadtot          integer;
	   
	    sp_cantidadlcc			integer;
	    sp_cantidadrtm			integer;
	   
	    sp_porcentajelcc		varchar;
	   	sp_porcentajertm		varchar;
	   
	    sp_piezas               integer;
	    
	    sp_idot					integer;
	    sp_idproductonep		integer;
	    --sp_nombreordentrabajo	varchar;
	    sp_idfamilia			integer;
	   
	    sp_sumatotallcc			integer;
	    sp_canthr				integer;
	    sp_liberadascc			integer;

	    sp_avance				numeric;
	    sp_avancetm				numeric;
	    rec_lcc      			RECORD;
	   
	    sp_textoout				varchar;
	   
	    sp_imprime				bigint;
			       
BEGIN

   -- RETURN QUERY
			  
			--  select count(*)
			--    into sp_piezas
			--    from mct_ordentrabajo a,
			--         mct_productoparte b
			--   where idordentrabajo = idworkorders
			--     and a.idproducto  = b.idproducto ;
	
	        select idordentrabajo ,
	               idproducto ,
	               --nombreordentrabajo ,
	               idfamilia 
	          into sp_idot,
	               sp_idproductonep,
	               --sp_nombreordentrabajo,
	               sp_idfamilia
	          from mct_ordentrabajo 
	         where idordentrabajo = idworkorders;
	         
			sp_piezas := 0;

			if ( sp_piezas > 1 ) then

					select a.nombreordentrabajo, 
					       b.planogeneral ,
					       a.idproducto,
					       b.nombreproducto,
					       a.ordencompra, 
					       a.idcotizacion, 
					       a.fechafacetm ,
					       a.idestadoorden, 
					       c.nombreestado,
					       cast(date_part('day',  now() - a.fechafacetm ) as integer),
					       sum(d.cantidad)
					  into sp_nombreordentrabajo, 
					       sp_planogeneral,
					       sp_idproducto,
					       sp_nombreproducto,
					       sp_ordencompra, 
					       sp_idcotizacion, 
					       sp_fechaentrega,
					       sp_idestadoorden, 
					       sp_nombreestado,
					       sp_minutos,
					       sp_cantidadtot
					  from mct_ordentrabajo a,
					       mct_producto b,
					       mct_estadoorden c,
					       mct_productoparte d
					where a.idordentrabajo = idworkorders
					  and a.idproducto     = b.idproducto
					  and a.idestadoorden  = c.idestadoorden
					  and a.idproducto     = d.idproducto 
			     group by a.nombreordentrabajo, 
					      b.planogeneral ,
					      a.idproducto,
					      b.nombreproducto,
					      a.ordencompra, 
					      a.idcotizacion, 
					      a.fechafacetm,
					      a.idestadoorden, 
					      c.nombreestado;
			        
			else
						
			     if ( sp_idfamilia = 11 and sp_idproductonep in (10,11,12,13,14,15,16,17) ) then

						select a.nombreordentrabajo, 
						       cast('NE9999' as varchar) ,
						       a.idproducto,
						       b.nombreproductonepcast ,
						       a.ordencompra, 
						       a.idcotizacion, 
						       a.fechafacetm,
						       a.idestadoorden, 
						       c.nombreestado,
						       cast(date_part('day',  now() - a.fechafacetm ) as integer),
						       sum(d.cantidad)
						  into sp_nombreordentrabajo, 
						       sp_planogeneral ,
						       sp_idproducto,
						       sp_nombreproducto,
						       sp_ordencompra, 
						       sp_idcotizacion, 
						       sp_fechaentrega,
						       sp_idestadoorden, 
						       sp_nombreestado,
						       sp_minutos,
						       sp_cantidadtot     
						  from mct_ordentrabajo a,
						       mct_productonepcast b,
						       mct_estadoorden c,
						       mct_hojarutatemp d
						where a.idordentrabajo = idworkorders
						  and a.idproducto     = b.idproductonepcast 
						  and a.idestadoorden  = c.idestadoorden
						  and a.idordentrabajo = d.idordentrabajo 
				     group by a.nombreordentrabajo, 
						      --b.planogeneral ,
						      a.idproducto,
						      b.nombreproductonepcast ,
						      a.ordencompra, 
						      a.idcotizacion, 
						      a.fechafacetm,
						      a.idestadoorden, 
						      c.nombreestado;			     
			     
			     else
			     
						select a.nombreordentrabajo, 
						       b.planogeneral ,
						       a.idproducto,
						       b.nombreproducto,
						       a.ordencompra, 
						       a.idcotizacion, 
						       a.fechafacetm,
						       a.idestadoorden, 
						       c.nombreestado,
						       cast(date_part('day',  now() - a.fechafacetm ) as integer),
						       sum(d.cantidad)
						  into sp_nombreordentrabajo, 
						       sp_planogeneral ,
						       sp_idproducto,
						       sp_nombreproducto,
						       sp_ordencompra, 
						       sp_idcotizacion, 
						       sp_fechaentrega,
						       sp_idestadoorden, 
						       sp_nombreestado,
						       sp_minutos,
						       sp_cantidadtot     
						  from mct_ordentrabajo a,
						       mct_producto b,
						       mct_estadoorden c,
						       mct_hojarutatemp d
						where a.idordentrabajo = idworkorders
						  and a.idproducto     = b.idproducto
						  and a.idestadoorden  = c.idestadoorden
						  and a.idordentrabajo = d.idordentrabajo 
				     group by a.nombreordentrabajo, 
						      b.planogeneral ,
						      a.idproducto,
						      b.nombreproducto,
						      a.ordencompra, 
						      a.idcotizacion, 
						      a.fechafacetm,
						      a.idestadoorden, 
						      c.nombreestado;			     
			     end if;
					     			
			end if;


--		select * from mct_movimientoordentrabajo mm 
--		where codhojaruta = '03176432850001'
--		
			
		    -- desde aca el nuevo calculo
			sp_sumatotallcc  := 0;
		    sp_avance		 := 0;
		    sp_avancetm		 := 0;
		   
		    sp_imprime		 := 0;
		   
			FOR rec_lcc IN (   
					select distinct b.idhojarutatemp, b.codhojaruta 
					  from mct_movimientoordentrabajo a,
					       mct_hojaruta b
					 where a.codigoaccion in ('L_CC','R_TM')
				       and a.idordentrabajo = idworkorders
				       and a.idhojaruta = b.idhojaruta 
				       order by 1 asc
						)
	    		loop 	
		    		
		    		
				      sp_liberadascc	:= 0;
								   
				      select a.idimprimehojas
				        into sp_imprime
				        from mct_hojarutatemp a 
				       where a.idhojarutatemp = rec_lcc.idhojarutatemp;
				     
				      if (sp_imprime = 2) then --individuales
				      
					      select count(b.*)      
				  	        into sp_liberadascc
				  	        from mct_hojarutatemp a,
				  	             mct_detallehojarutatemp b
					       where a.idhojarutatemp = rec_lcc.idhojarutatemp
					         and a.idhojarutatemp = b.idhojarutatemp 
					         and b.codhojaruta = rec_lcc.codhojaruta
					         and a.idboleano = 1
					         and a.aplicahojaruta is true
					         and a.idcriterioevaluacion != 7
					         and a.idareaclasificacion in (0,1,2,3,4,5,8);				      
				      
				      else
				      
					      select coalesce (sum(a.cantidad),0)      
				  	        into sp_liberadascc
				  	        from mct_hojarutatemp a,
				  	             mct_detallehojarutatemp b
					       where a.idhojarutatemp = rec_lcc.idhojarutatemp
					         and a.idhojarutatemp = b.idhojarutatemp 
					         and b.codhojaruta = rec_lcc.codhojaruta
					         and a.idboleano = 1
					         and a.aplicahojaruta is true
					         and a.idcriterioevaluacion != 7
					         and a.idareaclasificacion in (0,1,2,3,4,5,8);				      
				      
				      
				      end if;
				     

						     
--					  sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
				        
					  if ( select 1
						     from mct_movimientoordentrabajo a,
				                  mct_hojaruta b,
			  	                  mct_detallehojarutatemp c
			                where b.idhojarutatemp = rec_lcc.idhojarutatemp
			                  and b.idhojarutatemp = c.idhojarutatemp 
				              and c.codhojaruta = rec_lcc.codhojaruta
			                  and a.idhojaruta = b.idhojaruta 
				              and (a.codigoaccion = 'NC_MECCCC' or a.codigoaccion = 'NC_FUUUU') ) then
					                   
			              if ( select 1
				                 from mct_movimientoordentrabajo a,
				                      mct_hojaruta b,
				                      mct_detallehojarutatemp c
				                where b.idhojarutatemp = rec_lcc.idhojarutatemp
				                  and a.idhojaruta = b.idhojaruta 
				                  and b.idhojarutatemp = c.idhojarutatemp 
				                  and c.codhojaruta = rec_lcc.codhojaruta
				                  and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
						                                              from mct_movimientoordentrabajo b
						                                             where a.idhojaruta = b.idhojaruta 
						                                               and a.codigoaccion = 'L_CC' ) ) then

							 sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						                  
						     sp_textoout := idworkorders||' 1- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
						     raise notice '%', sp_textoout;
						                   
						  else
						                              
					         sp_sumatotallcc := sp_sumatotallcc + 0;
						                  
						     sp_textoout := idworkorders||' 2- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
						     raise notice '%', sp_textoout;
					                  
				         end if;
						                               
					  else
					      sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
					                  
					      sp_textoout := idworkorders||' 3- '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc||' - '||rec_lcc.codhojaruta;
					      raise notice '%', sp_textoout;
					                  
					  end if;				        
						           
			END LOOP;
				  		
		    sp_sumatotallcc := sp_sumatotallcc * 100;
		    -- hasta aca el nuevo calculo
				  	   		   			  
			-- aca sacamos la cantidad de piezas totales
		    select coalesce ( sum(cantidad), 0)
		      into sp_canthr
		      from mct_hojarutatemp mh
		     where idordentrabajo = idworkorders
		       and idboleano = 1
		       and aplicahojaruta is true
		       and idcriterioevaluacion != 7
		       and idareaclasificacion in (0,1,2,3,4,5,8);
					     
		    -- aca sacamos la cantidad de piezas liberadas de control de calidad
--		    select count(*)
--			  into sp_liberadascc
--			  from mct_movimientoordentrabajo
--		     where codigoaccion = 'L_CC'
--		       and idordentrabajo = idworkorders; 
					      
		    if ( sp_canthr = 0) then
			     sp_avance := 0;
		    else
				--sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
				sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
		    end if;

		    select sum(cantidad)
		      into sp_cantidadrtm
		      from (
			     select sum(cantidad) * 100 as cantidad
			       --into sp_cantidadrtm
			       from (
	             select distinct (c.*)
	             --select count (d.*)
	               --into sp_cantidadrtm
	               from mct_movimientoordentrabajo a,
	                    mct_hojaruta b,
	                    mct_hojarutatemp c,
	                    mct_detallehojarutatemp d
	              where a.idordentrabajo = idworkorders 
	                and a.codigoaccion = 'R_TM'
	                and a.idhojaruta = b.idhojaruta 
	                and b.idhojarutatemp = c.idhojarutatemp 
	                and a.codhojaruta = d.codhojaruta
	                and c.idhojarutatemp = d.idhojarutatemp
	                and c.idimprimehojas = 1
	                and c.idcriterioevaluacion != 7
	                and c.idareaclasificacion in (0,1,2,3,4,5,8)) tabla
	             union   
	               select count(d.*) * 100  as cantidad
	               --into sp_cantidadrtm
	               from mct_movimientoordentrabajo a,
	                    mct_hojaruta b,
	                    mct_hojarutatemp c,
	                    mct_detallehojarutatemp d
	              where a.idordentrabajo = idworkorders 
	                and a.codigoaccion = 'R_TM'
	                and a.idhojaruta = b.idhojaruta 
	                and b.idhojarutatemp = c.idhojarutatemp 
	                and a.codhojaruta = d.codhojaruta
	                and c.idhojarutatemp = d.idhojarutatemp
	                and c.idimprimehojas = 2
	                and c.idcriterioevaluacion != 7
	                and c.idareaclasificacion in (0,1,2,3,4,5,8)
                ) tabla2;              
               
              
              if ( sp_canthr = 0 or sp_cantidadrtm = 0) then
			     sp_avancetm := 0;
		      else
				--sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
				sp_avancetm := coalesce (round(sp_cantidadrtm / sp_canthr), 0); 
		      end if;
		   
              workordername 	:= sp_nombreordentrabajo;
              blueprintname 	:= sp_planogeneral;
              idproduct 		:= sp_idproducto;
              productname 		:= sp_nombreproducto;
              purchase 			:= sp_ordencompra;
              quotation 		:= sp_idcotizacion;
              deliverydate 		:= sp_fechaentrega;
              idorderstatus 	:= sp_idestadoorden;
              orderstatusname 	:= sp_nombreestado;
              timedelay 		:= sp_minutos;
              --quantitytot 		:= sp_cantidadtot;
              quantitytot		:= sp_canthr;
              --quantitylcc 		:= sp_cantidadlcc;
              quantitylcc 		:= coalesce(sp_sumatotallcc/100 , 0);
              quantityrtm		:= coalesce(sp_cantidadrtm/100 , 0);
              --percentlcc 		:= sp_porcentajelcc;
              percentlcc 		:= cast(round(sp_avance) as varchar);
              --percentrtm 		:= sp_porcentajertm;
              percentrtm 		:= cast(round(sp_avancetm) as varchar);
              
		RETURN NEXT;

END;
$$;


ALTER FUNCTION traking.evtlistheadtracing(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 2313 (class 1255 OID 17011)
-- Name: evtlistheadtracing_pruebasq(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistheadtracing_pruebasq(idworkorders bigint) RETURNS TABLE(workordername character varying, blueprintname character varying, idproduct bigint, productname character varying, purchase bigint, quotation bigint, deliverydate timestamp without time zone, idorderstatus bigint, orderstatusname character varying, timedelay integer, quantitytot integer, quantitylcc integer, quantityrtm integer, percentlcc character varying, percentrtm character varying)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombreordentrabajo   varchar; 
		sp_planogeneral 		varchar;
		sp_idproducto           integer;
		sp_nombreproducto		varchar;
		sp_ordencompra          bigint;
		sp_idcotizacion         integer;
		sp_fechaentrega			timestamp;
		sp_idestadoorden        integer;
		sp_nombreestado         varchar;
		sp_minutos              integer;	       
		sp_cantidadtot          integer;
	   
	    sp_cantidadlcc			integer;
	    sp_cantidadrtm			integer;
	   
	    sp_porcentajelcc		varchar;
	   	sp_porcentajertm		varchar;
	   
	    sp_piezas               integer;
	    
	    sp_idot					integer;
	    sp_idproductonep		integer;
	    --sp_nombreordentrabajo	varchar;
	    sp_idfamilia			integer;
	   
	    sp_sumatotallcc			integer;
	    sp_canthr				integer;
	    sp_liberadascc			integer;

	    sp_avance				numeric;
	    sp_avancetm				numeric;
	    rec_lcc      			RECORD;
	   
	    sp_textoout				varchar;
			       
BEGIN

   -- RETURN QUERY
			  
			--  select count(*)
			--    into sp_piezas
			--    from mct_ordentrabajo a,
			--         mct_productoparte b
			--   where idordentrabajo = idworkorders
			--     and a.idproducto  = b.idproducto ;
	
	        select idordentrabajo ,
	               idproducto ,
	               --nombreordentrabajo ,
	               idfamilia 
	          into sp_idot,
	               sp_idproductonep,
	               --sp_nombreordentrabajo,
	               sp_idfamilia
	          from mct_ordentrabajo 
	         where idordentrabajo = idworkorders;
	         
			sp_piezas := 0;

			if ( sp_piezas > 1 ) then

					select a.nombreordentrabajo, 
					       b.planogeneral ,
					       a.idproducto,
					       b.nombreproducto,
					       a.ordencompra, 
					       a.idcotizacion, 
					       a.fechafaceclte ,
					       a.idestadoorden, 
					       c.nombreestado,
					       cast(date_part('day',  now() - a.fechafaceclte ) as integer),
					       sum(d.cantidad)
					  into sp_nombreordentrabajo, 
					       sp_planogeneral,
					       sp_idproducto,
					       sp_nombreproducto,
					       sp_ordencompra, 
					       sp_idcotizacion, 
					       sp_fechaentrega,
					       sp_idestadoorden, 
					       sp_nombreestado,
					       sp_minutos,
					       sp_cantidadtot
					  from mct_ordentrabajo a,
					       mct_producto b,
					       mct_estadoorden c,
					       mct_productoparte d
					where a.idordentrabajo = idworkorders
					  and a.idproducto     = b.idproducto
					  and a.idestadoorden  = c.idestadoorden
					  and a.idproducto     = d.idproducto 
			     group by a.nombreordentrabajo, 
					      b.planogeneral ,
					      a.idproducto,
					      b.nombreproducto,
					      a.ordencompra, 
					      a.idcotizacion, 
					      a.fechafaceclte,
					      a.idestadoorden, 
					      c.nombreestado;
			        
			else
						
			     if ( sp_idfamilia = 11 and sp_idproductonep in (10,11,12,13,14,15,16,17) ) then

						select a.nombreordentrabajo, 
						       cast('NE9999' as varchar) ,
						       a.idproducto,
						       b.nombreproductonepcast ,
						       a.ordencompra, 
						       a.idcotizacion, 
						       a.fechafaceclte,
						       a.idestadoorden, 
						       c.nombreestado,
						       cast(date_part('day',  now() - a.fechafaceclte ) as integer),
						       sum(d.cantidad)
						  into sp_nombreordentrabajo, 
						       sp_planogeneral ,
						       sp_idproducto,
						       sp_nombreproducto,
						       sp_ordencompra, 
						       sp_idcotizacion, 
						       sp_fechaentrega,
						       sp_idestadoorden, 
						       sp_nombreestado,
						       sp_minutos,
						       sp_cantidadtot     
						  from mct_ordentrabajo a,
						       mct_productonepcast b,
						       mct_estadoorden c,
						       mct_hojarutatemp d
						where a.idordentrabajo = idworkorders
						  and a.idproducto     = b.idproductonepcast 
						  and a.idestadoorden  = c.idestadoorden
						  and a.idordentrabajo = d.idordentrabajo 
				     group by a.nombreordentrabajo, 
						      --b.planogeneral ,
						      a.idproducto,
						      b.nombreproductonepcast ,
						      a.ordencompra, 
						      a.idcotizacion, 
						      a.fechafaceclte,
						      a.idestadoorden, 
						      c.nombreestado;			     
			     
			     else
			     
						select a.nombreordentrabajo, 
						       b.planogeneral ,
						       a.idproducto,
						       b.nombreproducto,
						       a.ordencompra, 
						       a.idcotizacion, 
						       a.fechafaceclte,
						       a.idestadoorden, 
						       c.nombreestado,
						       cast(date_part('day',  now() - a.fechafaceclte ) as integer),
						       sum(d.cantidad)
						  into sp_nombreordentrabajo, 
						       sp_planogeneral ,
						       sp_idproducto,
						       sp_nombreproducto,
						       sp_ordencompra, 
						       sp_idcotizacion, 
						       sp_fechaentrega,
						       sp_idestadoorden, 
						       sp_nombreestado,
						       sp_minutos,
						       sp_cantidadtot     
						  from mct_ordentrabajo a,
						       mct_producto b,
						       mct_estadoorden c,
						       mct_hojarutatemp d
						where a.idordentrabajo = idworkorders
						  and a.idproducto     = b.idproducto
						  and a.idestadoorden  = c.idestadoorden
						  and a.idordentrabajo = d.idordentrabajo 
				     group by a.nombreordentrabajo, 
						      b.planogeneral ,
						      a.idproducto,
						      b.nombreproducto,
						      a.ordencompra, 
						      a.idcotizacion, 
						      a.fechafaceclte,
						      a.idestadoorden, 
						      c.nombreestado;			     
			     end if;
					     			
			end if;
	
----
		    -- desde aca el nuevo calculo
			sp_sumatotallcc  := 0;
		    sp_avance		 := 0;
		    sp_avancetm		 := 0;
				  	   		   			  
			-- aca sacamos la cantidad de piezas totales
		    select coalesce ( sum(cantidad), 0)
		      into sp_canthr
		      from mct_hojarutatemp mh
		     where idordentrabajo = idworkorders
		       and idboleano = 1
		       and idareaclasificacion in (0,1,2,3,4,5);
					      
		    if ( sp_canthr = 0) then
			     sp_avance := 0;
		    else
				--sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
				sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
		    end if;

		    select sum(cantidad)
		      into sp_cantidadrtm
		      from (
			     select sum(cantidad) * 100 as cantidad
			       --into sp_cantidadrtm
			       from (
	             select distinct (c.*)
	             --select count (d.*)
	               --into sp_cantidadrtm
	               from mct_movimientoordentrabajo a,
	                    mct_hojaruta b,
	                    mct_hojarutatemp c,
	                    mct_detallehojarutatemp d
	              where a.idordentrabajo = idworkorders 
	                and a.codigoaccion = 'R_TM'
	                and a.idhojaruta = b.idhojaruta 
	                and b.idhojarutatemp = c.idhojarutatemp 
	                and a.codhojaruta = d.codhojaruta
	                and c.idhojarutatemp = d.idhojarutatemp
	                and c.idimprimehojas = 1
	                and c.idareaclasificacion in (0,1,2,3,4,5)) tabla
	             union   
	               select count(d.*) * 100  as cantidad
	               --into sp_cantidadrtm
	               from mct_movimientoordentrabajo a,
	                    mct_hojaruta b,
	                    mct_hojarutatemp c,
	                    mct_detallehojarutatemp d
	              where a.idordentrabajo = idworkorders 
	                and a.codigoaccion = 'R_TM'
	                and a.idhojaruta = b.idhojaruta 
	                and b.idhojarutatemp = c.idhojarutatemp 
	                and a.codhojaruta = d.codhojaruta
	                and c.idhojarutatemp = d.idhojarutatemp
	                and c.idimprimehojas = 2
	                and c.idareaclasificacion in (0,1,2,3,4,5)
                ) tabla2;              
               
              sp_avancetm := coalesce (round(sp_cantidadrtm / sp_canthr), 0); 

			    select sum(cantidad)
			      into sp_sumatotallcc
			      from (
				     select sum(cantidad) * 100 as cantidad
				       --into sp_cantidadrtm
				       from (
		             select distinct (c.*)
		             --select count (d.*)
		               --into sp_cantidadrtm
		               from mct_movimientoordentrabajo a,
		                    mct_hojaruta b,
		                    mct_hojarutatemp c,
		                    mct_detallehojarutatemp d
		              where a.idordentrabajo = idworkorders 
		                and a.codigoaccion = 'L_CC'
		                and a.idhojaruta = b.idhojaruta 
		                and b.idhojarutatemp = c.idhojarutatemp 
		                and a.codhojaruta = d.codhojaruta
		                and c.idhojarutatemp = d.idhojarutatemp
		                and c.idimprimehojas = 1
		                and c.idareaclasificacion in (0,1,2,3,4,5)) tabla
		             union   
		               select count(d.*) * 100  as cantidad
		               --into sp_cantidadrtm
		               from mct_movimientoordentrabajo a,
		                    mct_hojaruta b,
		                    mct_hojarutatemp c,
		                    mct_detallehojarutatemp d
		              where a.idordentrabajo = idworkorders 
		                and a.codigoaccion = 'L_CC'
		                and a.idhojaruta = b.idhojaruta 
		                and b.idhojarutatemp = c.idhojarutatemp 
		                and a.codhojaruta = d.codhojaruta
		                and c.idhojarutatemp = d.idhojarutatemp
		                and c.idimprimehojas = 2
		                and c.idareaclasificacion in (0,1,2,3,4,5)
	                ) tabla2;     
					  		
--			    sp_sumatotallcc := sp_sumatotallcc * 100;
			    -- hasta aca el nuevo calculo
			    sp_avance := coalesce (round(sp_sumatotallcc / sp_canthr), 0); 
		                 
              workordername 	:= sp_nombreordentrabajo;
              blueprintname 	:= sp_planogeneral;
              idproduct 		:= sp_idproducto;
              productname 		:= sp_nombreproducto;
              purchase 			:= sp_ordencompra;
              quotation 		:= sp_idcotizacion;
              deliverydate 		:= sp_fechaentrega;
              idorderstatus 	:= sp_idestadoorden;
              orderstatusname 	:= sp_nombreestado;
              timedelay 		:= sp_minutos;
              --quantitytot 		:= sp_cantidadtot;
              quantitytot		:= sp_canthr;
              --quantitylcc 		:= sp_cantidadlcc;
              quantitylcc 		:= coalesce(sp_sumatotallcc/100 , 0);
              quantityrtm		:= coalesce(sp_cantidadrtm/100 , 0);
              --percentlcc 		:= sp_porcentajelcc;
              percentlcc 		:= cast(round(sp_avance) as varchar);
              --percentrtm 		:= sp_porcentajertm;
              percentrtm 		:= cast(round(sp_avancetm) as varchar);
              
		RETURN NEXT;

END;
$$;


ALTER FUNCTION traking.evtlistheadtracing_pruebasq(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 2110 (class 1255 OID 17013)
-- Name: evtlistheadtracing_respnicolas(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistheadtracing_respnicolas(idworkorders bigint) RETURNS TABLE(workordername character varying, blueprintname character varying, idproduct bigint, productname character varying, purchase bigint, quotation bigint, deliverydate timestamp without time zone, idorderstatus bigint, orderstatusname character varying, timedelay integer, quantitytot integer, quantitylcc integer, quantityrtm integer, percentlcc character varying, percentrtm character varying)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombreordentrabajo   varchar; 
		sp_planogeneral 		varchar;
		sp_idproducto           integer;
		sp_nombreproducto		varchar;
		sp_ordencompra          bigint;
		sp_idcotizacion         integer;
		sp_fechaentrega			timestamp;
		sp_idestadoorden        integer;
		sp_nombreestado         varchar;
		sp_minutos              integer;	       
		sp_cantidadtot          integer;
	   
	    sp_cantidadlcc			integer;
	    sp_cantidadrtm			integer;
	   
	    sp_porcentajelcc		varchar;
	   	sp_porcentajertm		varchar;
	   
	    sp_piezas               integer;
	    
	    sp_idot					integer;
	    sp_idproductonep		integer;
	    --sp_nombreordentrabajo	varchar;
	    sp_idfamilia			integer;
	   
	    sp_sumatotallcc			integer;
	    sp_canthr				integer;
	    sp_liberadascc			integer;

	    sp_avance				numeric;
	    sp_avancetm				numeric;
	    rec_lcc      			RECORD;
	   
	    sp_textoout				varchar;
			       
BEGIN

   -- RETURN QUERY
			  
			--  select count(*)
			--    into sp_piezas
			--    from mct_ordentrabajo a,
			--         mct_productoparte b
			--   where idordentrabajo = idworkorders
			--     and a.idproducto  = b.idproducto ;
	
	        select idordentrabajo ,
	               idproducto ,
	               --nombreordentrabajo ,
	               idfamilia 
	          into sp_idot,
	               sp_idproductonep,
	               --sp_nombreordentrabajo,
	               sp_idfamilia
	          from mct_ordentrabajo 
	         where idordentrabajo = idworkorders;
	         
			sp_piezas := 0;

			if ( sp_piezas > 1 ) then

					select a.nombreordentrabajo, 
					       b.planogeneral ,
					       a.idproducto,
					       b.nombreproducto,
					       a.ordencompra, 
					       a.idcotizacion, 
					       a.fechafaceclte ,
					       a.idestadoorden, 
					       c.nombreestado,
					       cast(date_part('day',  now() - a.fechafaceclte ) as integer),
					       sum(d.cantidad)
					  into sp_nombreordentrabajo, 
					       sp_planogeneral,
					       sp_idproducto,
					       sp_nombreproducto,
					       sp_ordencompra, 
					       sp_idcotizacion, 
					       sp_fechaentrega,
					       sp_idestadoorden, 
					       sp_nombreestado,
					       sp_minutos,
					       sp_cantidadtot
					  from mct_ordentrabajo a,
					       mct_producto b,
					       mct_estadoorden c,
					       mct_productoparte d
					where a.idordentrabajo = idworkorders
					  and a.idproducto     = b.idproducto
					  and a.idestadoorden  = c.idestadoorden
					  and a.idproducto     = d.idproducto 
			     group by a.nombreordentrabajo, 
					      b.planogeneral ,
					      a.idproducto,
					      b.nombreproducto,
					      a.ordencompra, 
					      a.idcotizacion, 
					      a.fechafaceclte,
					      a.idestadoorden, 
					      c.nombreestado;
			        
			else
						
			     if ( sp_idfamilia = 11 and sp_idproductonep in (10,11,12,13,14,15,16,17) ) then

						select a.nombreordentrabajo, 
						       cast('NE9999' as varchar) ,
						       a.idproducto,
						       b.nombreproductonepcast ,
						       a.ordencompra, 
						       a.idcotizacion, 
						       a.fechafaceclte,
						       a.idestadoorden, 
						       c.nombreestado,
						       cast(date_part('day',  now() - a.fechafaceclte ) as integer),
						       sum(d.cantidad)
						  into sp_nombreordentrabajo, 
						       sp_planogeneral ,
						       sp_idproducto,
						       sp_nombreproducto,
						       sp_ordencompra, 
						       sp_idcotizacion, 
						       sp_fechaentrega,
						       sp_idestadoorden, 
						       sp_nombreestado,
						       sp_minutos,
						       sp_cantidadtot     
						  from mct_ordentrabajo a,
						       mct_productonepcast b,
						       mct_estadoorden c,
						       mct_hojarutatemp d
						where a.idordentrabajo = idworkorders
						  and a.idproducto     = b.idproductonepcast 
						  and a.idestadoorden  = c.idestadoorden
						  and a.idordentrabajo = d.idordentrabajo 
				     group by a.nombreordentrabajo, 
						      --b.planogeneral ,
						      a.idproducto,
						      b.nombreproductonepcast ,
						      a.ordencompra, 
						      a.idcotizacion, 
						      a.fechafaceclte,
						      a.idestadoorden, 
						      c.nombreestado;			     
			     
			     else
			     
						select a.nombreordentrabajo, 
						       b.planogeneral ,
						       a.idproducto,
						       b.nombreproducto,
						       a.ordencompra, 
						       a.idcotizacion, 
						       a.fechafaceclte,
						       a.idestadoorden, 
						       c.nombreestado,
						       cast(date_part('day',  now() - a.fechafaceclte ) as integer),
						       sum(d.cantidad)
						  into sp_nombreordentrabajo, 
						       sp_planogeneral ,
						       sp_idproducto,
						       sp_nombreproducto,
						       sp_ordencompra, 
						       sp_idcotizacion, 
						       sp_fechaentrega,
						       sp_idestadoorden, 
						       sp_nombreestado,
						       sp_minutos,
						       sp_cantidadtot     
						  from mct_ordentrabajo a,
						       mct_producto b,
						       mct_estadoorden c,
						       mct_hojarutatemp d
						where a.idordentrabajo = idworkorders
						  and a.idproducto     = b.idproducto
						  and a.idestadoorden  = c.idestadoorden
						  and a.idordentrabajo = d.idordentrabajo 
				     group by a.nombreordentrabajo, 
						      b.planogeneral ,
						      a.idproducto,
						      b.nombreproducto,
						      a.ordencompra, 
						      a.idcotizacion, 
						      a.fechafaceclte,
						      a.idestadoorden, 
						      c.nombreestado;			     
			     end if;
					     			
			end if;
	

		    -- desde aca el nuevo calculo
			sp_sumatotallcc  := 0;
		    sp_avance		 := 0;
		    sp_avancetm		 := 0;
		   
			FOR rec_lcc IN (   
					select distinct b.idhojarutatemp
					  from mct_movimientoordentrabajo a,
					       mct_hojaruta b
					 where a.codigoaccion = 'L_CC'
				       and a.idordentrabajo = idworkorders
				       and a.idhojaruta = b.idhojaruta 
						)
	    		loop 	

				      sp_liberadascc	:= 0;
								   
				      select coalesce (sum(cantidad),0)
			  	        into sp_liberadascc
			  	        from mct_hojarutatemp
				       where idhojarutatemp = rec_lcc.idhojarutatemp
				         and idboleano = 1
				         and idareaclasificacion in (0,1,2,3,4,5);
						     
--					  sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
				        
					                if ( select 1
						                  from mct_movimientoordentrabajo a,
						                       mct_hojaruta b
						                 where b.idhojarutatemp = rec_lcc.idhojarutatemp
						                   and a.idhojaruta = b.idhojaruta 
						                   and (a.codigoaccion = 'NC_MEC' or a.codigoaccion = 'NC_FU') ) then
					                   
						                if ( select 1
						                  from mct_movimientoordentrabajo a,
						                       mct_hojaruta b
						                 where b.idhojarutatemp = rec_lcc.idhojarutatemp
						                   and a.idhojaruta = b.idhojaruta 
						                   and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
						                                                       from mct_movimientoordentrabajo b
						                                                      where a.idhojaruta = b.idhojaruta 
						                                                        and a.codigoaccion = 'L_CC' ) ) then

							                sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						                  
						                    sp_textoout := idworkorders||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
						                    raise notice '%', sp_textoout;
						                   
						                else
						                
						                
							                sp_sumatotallcc := sp_sumatotallcc + 0;
						                  
						                    sp_textoout := idworkorders||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
						                    raise notice '%', sp_textoout;
					                  
						                end if;
						                   
					                   
					               
					                else
					                   sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
					                  
					                   sp_textoout := idworkorders||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
					                   raise notice '%', sp_textoout;
					                  
					                end if;				        
						           
				END LOOP;
				  		
		    sp_sumatotallcc := sp_sumatotallcc * 100;
		    -- hasta aca el nuevo calculo
				  	   		   			  
			-- aca sacamos la cantidad de piezas totales
		    select coalesce ( sum(cantidad), 0)
		      into sp_canthr
		      from mct_hojarutatemp mh
		     where idordentrabajo = idworkorders
		       and idboleano = 1
		       and idareaclasificacion in (0,1,2,3,4,5);
					     
		    -- aca sacamos la cantidad de piezas liberadas de control de calidad
--		    select count(*)
--			  into sp_liberadascc
--			  from mct_movimientoordentrabajo
--		     where codigoaccion = 'L_CC'
--		       and idordentrabajo = idworkorders; 
					      
		    if ( sp_canthr = 0) then
			     sp_avance := 0;
		    else
				--sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
				sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
		    end if;

		     select sum(cantidad) * 100
		       into sp_cantidadrtm
		       from (
             select distinct (c.*)
               --into sp_cantidadrtm
               from mct_movimientoordentrabajo a,
                    mct_hojaruta b,
                    mct_hojarutatemp c,
                    mct_detallehojarutatemp d
              where a.idordentrabajo = idworkorders 
                and a.codigoaccion = 'R_TM'
                and a.idhojaruta = b.idhojaruta 
                and b.idhojarutatemp = c.idhojarutatemp 
                and a.codhojaruta = d.codhojaruta
                and c.idhojarutatemp = d.idhojarutatemp
                and c.idareaclasificacion in (0,1,2,3,4,5)) tabla;
               
              sp_avancetm := coalesce (round(sp_cantidadrtm / sp_canthr), 0); 
			       
              workordername 	:= sp_nombreordentrabajo;
              blueprintname 	:= sp_planogeneral;
              idproduct 		:= sp_idproducto;
              productname 		:= sp_nombreproducto;
              purchase 			:= sp_ordencompra;
              quotation 		:= sp_idcotizacion;
              deliverydate 		:= sp_fechaentrega;
              idorderstatus 	:= sp_idestadoorden;
              orderstatusname 	:= sp_nombreestado;
              timedelay 		:= sp_minutos;
              --quantitytot 		:= sp_cantidadtot;
              quantitytot		:= sp_canthr;
              --quantitylcc 		:= sp_cantidadlcc;
              quantitylcc 		:= coalesce(sp_sumatotallcc/100 , 0);
              quantityrtm		:= coalesce(sp_cantidadrtm/100 , 0);
              --percentlcc 		:= sp_porcentajelcc;
              percentlcc 		:= cast(round(sp_avance) as varchar);
              --percentrtm 		:= sp_porcentajertm;
              percentrtm 		:= cast(round(sp_avancetm) as varchar);
              
		RETURN NEXT;

END;
$$;


ALTER FUNCTION traking.evtlistheadtracing_respnicolas(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1292 (class 1255 OID 17015)
-- Name: evtlisthistbajachart(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthistbajachart(idcustomer bigint) RETURNS TABLE(task text, taskvalue bigint, colorval text)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idcustomer = 77 ) then
	
    RETURN QUERY

	    select case 
					when d.sigla = 'HA' then 'HA Bomba Horizontal Carcasa Partida Axial'
					when d.sigla = 'VTP' then 'VTP Bomba Vertical Tipo Turbina             '
					when d.sigla = 'HR' then 'HR Bomba Horizontal Carcasa Partida Radial'
					when d.sigla = 'HV' then 'HV Bomba Horizontal de Voluta'
					when d.sigla = 'SM' then 'SM Bomba Sumergible'
					when d.sigla = 'VS' then 'SM Bomba Sumergible'
				else 'OT Otros modelos'
			   end ,
			   count(*),
			   case 
					when d.sigla = 'HA' then '0xff31D259'
					when d.sigla = 'VTP' then '0xff0A84FF'
					when d.sigla = 'HR' then '0xffBF5AF2'
					when d.sigla = 'HV' then '0xff5F5DE6'
					when d.sigla = 'SM' then '0xffFF9F0B'
					when d.sigla = 'VS' then '0xffFF9F0B'
				else '0xff0A84FF'
			   end 
	    from mct_ordentrabajo a,
	         mct_producto b,
	         mct_modelo c,
	         mct_subfamilia d
	    where a.idordentrabajo >= 30000
	      --and a.idcliente = idcustomer
	      and a.idfamilia = 8
	      and a.idtipoorden = 1
	      and a.idestadoorden = 9
          and a.flagapp = 1
	      and a.debaja = 1
	      and a.idproducto = b.idproducto 
	      and b.idmodelo = c.idmodelo 
	      and c.idsubfamilia = d.idsubfamilia 
	    group by d.sigla
	    order by d.sigla asc;	
	
	else
	
    RETURN QUERY

	    select case 
					when d.sigla = 'HA' then 'HA Bomba Horizontal Carcasa Partida Axial'
					when d.sigla = 'VTP' then 'VTP Bomba Vertical Tipo Turbina             '
					when d.sigla = 'HR' then 'HR Bomba Horizontal Carcasa Partida Radial'
					when d.sigla = 'HV' then 'HV Bomba Horizontal de Voluta'
					when d.sigla = 'SM' then 'SM Bomba Sumergible'	
					when d.sigla = 'VS' then 'SM Bomba Sumergible'
				else 'OT Otros modelos'
			   end ,
			   count(*),
			   case 
					when d.sigla = 'HA' then '0xff31D259'
					when d.sigla = 'VTP' then '0xff0A84FF'
					when d.sigla = 'HR' then '0xffBF5AF2'
					when d.sigla = 'HV' then '0xff5F5DE6'
					when d.sigla = 'SM' then '0xffFF9F0B'
					when d.sigla = 'VS' then '0xffFF9F0B'
				else '0xff0A84FF'
			   end 
	    from mct_ordentrabajo a,
	         mct_producto b,
	         mct_modelo c,
	         mct_subfamilia d
	    where a.idordentrabajo >= 30000
	      and a.idcliente = idcustomer
	      and a.idfamilia = 8
	      and a.idtipoorden = 1
	      and a.idestadoorden = 9
          and a.flagapp = 1
	      and a.debaja = 1
	      and a.idproducto = b.idproducto 
	      and b.idmodelo = c.idmodelo 
	      and c.idsubfamilia = d.idsubfamilia 
	    group by d.sigla
	    order by d.sigla asc;	
	
	end if;
	
	

  	
END;
$$;


ALTER FUNCTION traking.evtlisthistbajachart(idcustomer bigint) OWNER TO postgres;

--
-- TOC entry 1381 (class 1255 OID 17016)
-- Name: evtlisthistfabchart(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthistfabchart(idcustomer bigint) RETURNS TABLE(task text, taskvalue bigint, colorval text)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if (idcustomer = 77) then
	
    RETURN QUERY

	    select case 
					when d.sigla = 'HA' then 'HA Bomba Horizontal Carcasa Partida Axial'
					when d.sigla = 'VTP' then 'VTP Bomba Vertical Tipo Turbina           '
					when d.sigla = 'HR' then 'HR Bomba Horizontal Carcasa Partida Radial'
					when d.sigla = 'HV' then 'HV Bomba Horizontal de Voluta'
					when d.sigla = 'SM' then 'SM Bomba Sumergible'				
				else 'OT Otros modelos'
			   end ,
			   count(*),
			   case 
					when d.sigla = 'HA' then '0xff31D259'
					when d.sigla = 'VTP' then '0xff0A84FF'
					when d.sigla = 'HR' then '0xffBF5AF2'
					when d.sigla = 'HV' then '0xff5F5DE6'
					when d.sigla = 'SM' then '0xffFF9F0B'				
				else '0xffffac1f'
			   end 
	    from mct_ordentrabajo a,
	         mct_producto b,
	         mct_modelo c,
	         mct_subfamilia d
	    where a.idordentrabajo >= 30000
	      --and a.idcliente = idcustomer
	      and a.idfamilia = 8
	      and a.idtipoorden = 2
	      and a.idestadoorden = 9
	      and a.idproducto = b.idproducto 
	      and b.idmodelo = c.idmodelo 
	      and c.idsubfamilia = d.idsubfamilia 
	    group by d.sigla
	    order by d.sigla asc;	
	
	else
	
    RETURN QUERY

	    select case 
					when d.sigla = 'HA' then 'HA Bomba Horizontal Carcasa Partida Axial'
					when d.sigla = 'VTP' then 'VTP Bomba Vertical Tipo Turbina           '
					when d.sigla = 'HR' then 'HR Bomba Horizontal Carcasa Partida Radial'
					when d.sigla = 'HV' then 'HV Bomba Horizontal de Voluta'
					when d.sigla = 'SM' then 'SM Bomba Sumergible'				
				else 'OT Otros modelos'
			   end ,
			   count(*),
			   case 
					when d.sigla = 'HA' then '0xff31D259'
					when d.sigla = 'VTP' then '0xff0A84FF'
					when d.sigla = 'HR' then '0xffBF5AF2'
					when d.sigla = 'HV' then '0xff5F5DE6'
					when d.sigla = 'SM' then '0xffFF9F0B'				
				else '0xffffac1f'
			   end 
	    from mct_ordentrabajo a,
	         mct_producto b,
	         mct_modelo c,
	         mct_subfamilia d
	    where a.idordentrabajo >= 30000
	      and a.idcliente = idcustomer
	      and a.idfamilia = 8
	      and a.idtipoorden = 2
	      and a.idestadoorden = 9
	      and a.idproducto = b.idproducto 
	      and b.idmodelo = c.idmodelo 
	      and c.idsubfamilia = d.idsubfamilia 
	    group by d.sigla
	    order by d.sigla asc;	
	
	end if;


  
		
END;
$$;


