              --round(coalesce (a.montorepfab, 0)/(date_part('day', now() - a.fechadespacho) * 24 ) * 0.9) as costohora
         from mct_ordentrabajo a,
              mct_producto b,
              mct_modelo c,
              mct_subfamilia d
        where a.idordentrabajo >= 30000
          and a.idcliente = idcustomer
          and a.idtipoorden in (1,3)
          and a.idfamilia = 8
          and a.idestadoorden = 9
          and a.flagapp = 1
          and a.debaja = 1
          and a.idproducto = b.idproducto 
