          --and a.ordencompra is not null
          --and a.ordencompra > 0
          order by a.fechadespacho desc
          )
		loop           
        
		       select fecha_autoriza_cliente
		         into sp_fechaa
		         from mct_progavisos mp 
		        where idsla = 5
		          and idordentrabajo = rec1.sp_ot;   

			   	sp_tot_piezasr := 0;
			    sp_tot_recic   := 0;
			  
			   
			     -- % de reciclaje
		    select sum(cantidad)
		      into sp_tot_piezasr
			  from mct_checklistinftec mc 
			 where idordentrabajo = rec1.sp_ot
			   and upper(criterio) not in ('RPO')
			   and upper(nombreparte) not like '%CHAVE%'
			   and upper(nombreparte) not like '%RRAGO%'
			   and upper(nombreparte) not like '%CORTAGO%'
			   and upper(nombreparte) not like '%PERNO%'	
			   and upper(nombreparte) not like '%GOLILL%'		
			   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
			   and upper(nombreparte) not like '%NIPL%'			   
			  ;
				   
				select sum(cantidad)
				  into sp_tot_recic
				  from mct_checklistinftec mc 
				 where idordentrabajo = rec1.sp_ot
				   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
				   and upper(criterio) not like 'REM%';
			     
				  
				sp_reciclado := 0;
			    sp_reciclado := round( (sp_tot_recic * 100) / sp_tot_piezasr);		         
		         
			    id      	:= rec1.sp_id;
			    ot      	:= rec1.sp_ot;
			    fechar  	:= rec1.sp_fechar;
			    fechaa  	:= to_char(sp_fechaa,'dd-mm-yyyy');
			    fechae  	:= rec1.sp_fechae;
			    tipo    	:= replace(to_char(rec1.costohora,'$'||'LFM999,999,999'),',','.');
			    modelo  	:= rec1.sp_modelo;
			    avance  	:= to_char(rec1.horas,'LFM999,999,999');
			    monto   	:= replace(to_char(rec1.sp_monto,'$'||'LFM999,999,999'),',','.');
			    otcliente	:= rec1.ordencompra;
			    recicla		:= 0;
			    reciclado   := coalesce(sp_reciclado,0);
			    --ahorro      := 4.5;
			   	ahorro      := round(rec1.tonelada,1);
			   
			   --select to_char(rec1.sp_monto,'$'||'LFM999,999,999') as formato;
			    
		     
		      RETURN next;
		     
		END LOOP;		
	
	else

	FOR rec1 IN (   
       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
              a.idordentrabajo as sp_ot,
              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
              to_char(a.fechadespacho, 'dd-mm-yyyy') as sp_fechae,
              d.sigla as sp_tipo,
              case 
                when idlineadiseno = 1 then 'DE DISEÑO'
                when idlineadiseno = 2 then 'DE LINEA'
                when idlineadiseno = 3 then 'DE LINEA'
              end||' - '||d.sigla||' '||c.nombreneptuno as sp_modelo,
              coalesce (a.montorepfab, 0) as sp_monto,
              --round((date_part('day', now() - a.fechadespacho) * 24 ) * 0.9) as horas,
              --round(coalesce (a.montorepfab, 0)/(date_part('day', now() - a.fechadespacho) * 24 ) * 0.9) as costohora
              0 as horas,
              0 as costohora,
              a.ordencompra  ,
              --coalesce (b.tonelada , 4.5) as tonelada
              case
				when idlineadiseno = 3 then 0 
				when idlineadiseno in (1,2) then coalesce (b.tonelada, 4.5)
			  end as tonelada
         from mct_ordentrabajo a,
              mct_producto b,
              mct_modelo c,
              mct_subfamilia d
        where a.idordentrabajo >= 30000
          and a.idcliente = idcustomer
          and a.idtipoorden in (2)
          and a.idfamilia = 8
          and a.flagapp = 1
          and a.idestadoorden = 9
          and a.idproducto = b.idproducto 
          and b.idmodelo = c.idmodelo 
          and c.idsubfamilia = d.idsubfamilia 
          --and a.ordencompra is not null
          --and a.ordencompra > 0
          order by a.fechadespacho desc
          )
		loop           
        
		       select fecha_autoriza_cliente
		         into sp_fechaa
		         from mct_progavisos mp 
		        where idsla = 5
		          and idordentrabajo = rec1.sp_ot;   

			   	sp_tot_piezasr := 0;
			    sp_tot_recic   := 0;
			  
			   
			     -- % de reciclaje
		    select sum(cantidad)
		      into sp_tot_piezasr
			  from mct_checklistinftec mc 
			 where idordentrabajo = rec1.sp_ot
			   and upper(criterio) not in ('RPO')
			   and upper(nombreparte) not like '%CHAVE%'
			   and upper(nombreparte) not like '%RRAGO%'
			   and upper(nombreparte) not like '%CORTAGO%'
			   and upper(nombreparte) not like '%PERNO%'	
			   and upper(nombreparte) not like '%GOLILL%'		
			   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
			   and upper(nombreparte) not like '%NIPL%'			   
			  ;
				   
				select sum(cantidad)
				  into sp_tot_recic
				  from mct_checklistinftec mc 
				 where idordentrabajo = rec1.sp_ot
				   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
				   and upper(criterio) not like 'REM%';
			     
				  
				sp_reciclado := 0;
			    sp_reciclado := round( (sp_tot_recic * 100) / sp_tot_piezasr);		         
		         
			    id      	:= rec1.sp_id;
			    ot      	:= rec1.sp_ot;
			    fechar  	:= rec1.sp_fechar;
			    fechaa  	:= to_char(sp_fechaa,'dd-mm-yyyy');
			    fechae  	:= rec1.sp_fechae;
			    tipo    	:= replace(to_char(rec1.costohora,'$'||'LFM999,999,999'),',','.');
			    modelo  	:= rec1.sp_modelo;
			    avance  	:= to_char(rec1.horas,'LFM999,999,999');
			    monto   	:= replace(to_char(rec1.sp_monto,'$'||'LFM999,999,999'),',','.');
			    otcliente	:= rec1.ordencompra;
			    recicla		:= 0;
			    reciclado   := coalesce(sp_reciclado,0);
			    --ahorro      := 4.5;
			   	ahorro      := round(rec1.tonelada,1);
			   
			   --select to_char(rec1.sp_monto,'$'||'LFM999,999,999') as formato;
			    
		     
		      RETURN next;
		     
		END LOOP;		
	
	end if;

	     

END;
$_$;


ALTER FUNCTION traking.evtlisthistoricofabapp(idcustomer bigint) OWNER TO postgres;

--
-- TOC entry 1390 (class 1255 OID 17020)
-- Name: evtlisthistoricorepapp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthistoricorepapp(idcustomer bigint) RETURNS TABLE(id bigint, ot bigint, fechar character varying, fechaa character varying, fechae character varying, tipo character varying, modelo character varying, avance bigint, monto character varying, otcliente character varying, recicla bigint, reciclado bigint, ahorro character varying, ciclo character varying)
    LANGUAGE plpgsql
    AS $_$
declare

    sp_id      		integer;
    sp_ot      		integer;
    sp_fechar  		varchar;
    sp_fechaa  		timestamp;
    sp_fechae  		varchar;
    sp_tipo    		varchar;
    sp_modelo  		varchar;
    sp_avance  		numeric;
    sp_monto   		integer;
    sp_estado  		integer;
   
    sp_fechat 		varchar;
    sp_dias    		integer;
    sp_diast   		integer;
    sp_porc    		integer;
   
   -- Reutilizacion
    sp_recicla      integer;
    sp_tot_piezas   integer;
    sp_tot_reci     integer;
   
   -- Reciclaje
    sp_reciclado    integer;
    sp_tot_piezasr  integer;
    sp_tot_recic    integer;
   
    tot_ciclos		integer;         
    rec1 	   record;
   
BEGIN
	
	
	if ( idcustomer = 77 ) then 
	
		FOR rec1 IN (   
	       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
	              a.idordentrabajo as sp_ot,
	              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
	              to_char(a.fechadespacho, 'dd-mm-yyyy') as sp_fechae,
	              d.sigla as sp_tipo,
	              case 
	                when idlineadiseno = 1 then 'DE DISEÑO'
	                when idlineadiseno = 2 then 'DE LINEA'
	              end||' - '||d.sigla||' '||c.nombreneptuno as sp_modelo,
	              coalesce (a.montorepfab, 0) as sp_monto,
	              --round((date_part('day', now() - a.fechadespacho) * 24 ) * 0.9) as horas,
	              --round(coalesce (a.montorepfab, 0)/(date_part('day', now() - a.fechadespacho) * 24 ) * 0.9) as costohora
	              0 as horas,
	              0 as costohora,
	              a.otcliente ,
	              coalesce (b.tonelada , 4.5) as tonelada
	         from mct_ordentrabajo a,
	              mct_producto b,
	              mct_modelo c,
	              mct_subfamilia d
	        where a.idordentrabajo >= 30000 
	          -- Eliminar cuando se regularice
	          and a.idordentrabajo not in (30022, 30009)
	          --and a.idcliente = idcustomer
	          and a.idtipoorden in (1,3)
	          and a.idfamilia in (8,11)
	          and a.idestadoorden = 9
	          and a.flagapp = 1
	          and a.debaja != 1
	          and a.idproducto = b.idproducto 
	          and b.idmodelo = c.idmodelo 
	          and c.idsubfamilia = d.idsubfamilia 
	          --and a.ordencompra is not null
	          --and a.ordencompra > 0   
	          order by a.fechadespacho desc    
	          )
			loop           
	        
			       select fecha_autoriza_cliente
			         into sp_fechaa
			         from mct_progavisos mp 
			        where idsla = 5
			          and idordentrabajo = rec1.sp_ot;   
	
				    -- % de reutilización
				    select sum(cantidad)
				      into sp_tot_piezas
					  from mct_checklistinftec mc 
					 where idordentrabajo = rec1.sp_ot
					   and upper(criterio) not in ('RPO');
					   
					select sum(cantidad)
					  into sp_tot_reci
					  from mct_checklistinftec mc 
					 where idordentrabajo = rec1.sp_ot
					   and upper(criterio) not in ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO');
					  
					if (sp_tot_piezas = 0) then
					   sp_tot_piezas := 1;
					end if;
				
					sp_recicla := 0;
				 
				    sp_recicla := round( (sp_tot_reci * 100) / sp_tot_piezas);		         
			         
			       
				   	sp_tot_piezasr := 0;
				    sp_tot_recic   := 0;
				     
				     -- % de reciclaje
				    select sum(cantidad)
				      into sp_tot_piezasr
					  from mct_checklistinftec mc 
					 where idordentrabajo = rec1.sp_ot
					   and upper(criterio) not in ('RPO')
					   and upper(nombreparte) not like '%CHAVE%'
					   and upper(nombreparte) not like '%RRAGO%'
					   and upper(nombreparte) not like '%CORTAGO%'
					   and upper(nombreparte) not like '%PERNO%'	
					   and upper(nombreparte) not like '%GOLILL%'		
					   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
					   and upper(nombreparte) not like '%NIPL%'			   
					  ;
					   
					select sum(cantidad)
					  into sp_tot_recic
					  from mct_checklistinftec mc 
					 where idordentrabajo = rec1.sp_ot
					   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
					   and upper(criterio) not like 'REM%';
				     
					  
					sp_reciclado := 0;
				    sp_reciclado := round( (sp_tot_recic * 100) / sp_tot_piezasr);
			   
				    id      	:= rec1.sp_id;
				    ot      	:= rec1.sp_ot;
				    fechar  	:= rec1.sp_fechar;
				    fechaa  	:= to_char(sp_fechaa,'dd-mm-yyyy');
				    fechae  	:= rec1.sp_fechae;
				    tipo    	:= replace(to_char(rec1.costohora,'$'||'LFM999,999,999'),',','.');
				    modelo  	:= coalesce(rec1.sp_modelo,'S/M');
				    avance  	:= to_char(rec1.horas,'LFM999,999,999');
				    monto   	:= replace(to_char(rec1.sp_monto,'$'||'LFM999,999,999'),',','.');
				    otcliente	:= rec1.otcliente;
				    recicla		:= coalesce(sp_recicla,0);
				    reciclado	:= coalesce(sp_reciclado,0);
				    --ahorro      := 4.5;
				   	ahorro      := round(rec1.tonelada,1);
				   --select to_char(rec1.sp_monto,'$'||'LFM999,999,999') as formato;
				    if ( rec1.sp_ot in (30652, 30947, 30925, 31184) ) then
				   		recicla     := coalesce(33,0);
				    	reciclado   := coalesce(67,0);
				        ahorro		:= coalesce(47.3,0);
				    end if;					   
				    --tot_ciclos	:= traking.evtgetcantidadcicloshist(rec1.sp_ot);
				    tot_ciclos	:= 0;
			        if (tot_ciclos = 0) then
					    ciclo	:= '-';	        
			        else
				    	ciclo	:= tot_ciclos;		        
			        end if;					    
			     
			      RETURN next;
			     
			END LOOP;		
	
	else

		FOR rec1 IN (   
	       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
	              a.idordentrabajo as sp_ot,
	              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
	              to_char(a.fechadespacho, 'dd-mm-yyyy') as sp_fechae,
	              d.sigla as sp_tipo,
	              case 
	                when idlineadiseno = 1 then 'DE DISEÑO'
	                when idlineadiseno = 2 then 'DE LINEA'
	              end||' - '||d.sigla||' '||c.nombreneptuno as sp_modelo,
	              coalesce (a.montorepfab, 0) as sp_monto,
	              --round((date_part('day', now() - a.fechadespacho) * 24 ) * 0.9) as horas,
	              --round(coalesce (a.montorepfab, 0)/(date_part('day', now() - a.fechadespacho) * 24 ) * 0.9) as costohora
	              0 as horas,
	              0 as costohora,
	              a.otcliente ,
	              coalesce (b.tonelada , 4.5) as tonelada
	         from mct_ordentrabajo a,
	              mct_producto b,
	              mct_modelo c,
	              mct_subfamilia d
	        where a.idordentrabajo >= 30000
	          -- Eliminar cuando se regularice
	          and a.idordentrabajo not in (30022, 30009)        
	          and a.idcliente = idcustomer
	          and a.idtipoorden in (1,3)
	          and a.idfamilia in (8,11)
	          and a.idestadoorden = 9
	          and a.flagapp = 1
	          and a.debaja != 1
	          and a.idproducto = b.idproducto 
	          and b.idmodelo = c.idmodelo 
	          and c.idsubfamilia = d.idsubfamilia 
	          --and a.ordencompra is not null
	          --and a.ordencompra > 0
	          order by a.fechadespacho desc
	          )
			loop           
	        
			       select fecha_autoriza_cliente
			         into sp_fechaa
			         from mct_progavisos mp 
			        where idsla = 5
			          and idordentrabajo = rec1.sp_ot;   
	
				    -- % de reutilización
				    select sum(cantidad)
				      into sp_tot_piezas
					  from mct_checklistinftec mc 
					 where idordentrabajo = rec1.sp_ot
					   and upper(criterio) not in ('RPO');
					   
					select sum(cantidad)
					  into sp_tot_reci
					  from mct_checklistinftec mc 
					 where idordentrabajo = rec1.sp_ot
					   and upper(criterio) not in ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO');
					  
					if (sp_tot_piezas = 0) then
					   sp_tot_piezas := 1;
					end if;
				
					sp_recicla := 0;
				 
				    sp_recicla := round( (sp_tot_reci * 100) / sp_tot_piezas);		         
			         
			       
				   
				   	sp_tot_piezasr := 0;
				    sp_tot_recic   := 0;
				     
				     -- % de reciclaje
				    select sum(cantidad)
				      into sp_tot_piezasr
					  from mct_checklistinftec mc 
					 where idordentrabajo = rec1.sp_ot
					   and upper(criterio) not in ('RPO')
					   and upper(nombreparte) not like '%CHAVE%'
					   and upper(nombreparte) not like '%RRAGO%'
					   and upper(nombreparte) not like '%CORTAGO%'
					   and upper(nombreparte) not like '%PERNO%'	
					   and upper(nombreparte) not like '%GOLILL%'		
					   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
					   and upper(nombreparte) not like '%NIPL%'			   
					  ;
					   
					select sum(cantidad)
					  into sp_tot_recic
					  from mct_checklistinftec mc 
					 where idordentrabajo = rec1.sp_ot
					   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
					   and upper(criterio) not like 'REM%';
				     
					  
					sp_reciclado := 0;
				    sp_reciclado := round( (sp_tot_recic * 100) / sp_tot_piezasr);
			   
				    id      	:= rec1.sp_id;
				    ot      	:= rec1.sp_ot;
				    fechar  	:= rec1.sp_fechar;
				    fechaa  	:= to_char(sp_fechaa,'dd-mm-yyyy');
				    fechae  	:= rec1.sp_fechae;
				    tipo    	:= replace(to_char(rec1.costohora,'$'||'LFM999,999,999'),',','.');
				    modelo  	:= coalesce(rec1.sp_modelo,'S/M');
				    avance  	:= to_char(rec1.horas,'LFM999,999,999');
				    monto   	:= replace(to_char(rec1.sp_monto,'$'||'LFM999,999,999'),',','.');
				    otcliente	:= rec1.otcliente;
				    recicla		:= coalesce(sp_recicla,0);
				    reciclado	:= coalesce(sp_reciclado,0);
				    --ahorro      := 4.5;
				   	ahorro      := round(rec1.tonelada,1);
				    if ( rec1.sp_ot in (30652, 30947, 30925, 31184) ) then
				   		recicla     := coalesce(33,0);
				    	reciclado   := coalesce(67,0);
				        ahorro		:= coalesce(47.3,0);
				    end if;						 			  
				    --tot_ciclos	:= traking.evtgetcantidadcicloshist(rec1.sp_ot);
				    tot_ciclos	:= 0;
			        if (tot_ciclos = 0) then
					    ciclo	:= '-';	        
			        else
				    	ciclo	:= tot_ciclos;		        
			        end if;		
			       
				   --select to_char(rec1.sp_monto,'$'||'LFM999,999,999') as formato;
				    
			      RETURN next;
			     
			END LOOP;		
	
	end if;

	     

END;
$_$;


