--
-- TOC entry 972 (class 1255 OID 17022)
-- Name: evtlisthistrepchart(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthistrepchart(idcustomer bigint) RETURNS TABLE(task text, taskvalue bigint, colorval text)
    LANGUAGE plpgsql
    AS $$
begin
	
	if ( idcustomer = 77 ) then
	
    RETURN QUERY

	    select case 
					when d.sigla = 'HA' then 'HA Bomba Horizontal Carcasa Partida Axial'
					when d.sigla = 'VTP' then 'VTP Bomba Vertical Tipo Turbina'
					when d.sigla = 'HR' then 'HR Bomba Horizontal Carcasa Partida Radial'
					when d.sigla = 'HV' then 'HV Bomba Horizontal de Voluta'
					when d.sigla = 'SM' then 'SM Bomba Sumergible'
					when d.sigla = 'VERT' then 'Tornillos Vertimil'
				else 'OT Otros modelos'
			   end ,
			   count(*),
			   case 
					when d.sigla = 'HA' then '0xff31D259'
					when d.sigla = 'VTP' then '0xff0A84FF'
					when d.sigla = 'HR' then '0xffBF5AF2'
					when d.sigla = 'HV' then '0xff5F5DE6'
					when d.sigla = 'SM' then '0xffFF9F0B'	
					when d.sigla = 'VERT' then '0xffFF9E06'
				else '0xffFC4736'
			   end 
	    from mct_ordentrabajo a,
	         mct_producto b,
	         mct_modelo c,
	         mct_subfamilia d
	    where a.idordentrabajo >= 30000
	      --and a.idcliente = idcustomer
	      and a.idfamilia in (8,11)
	      and a.idtipoorden = 1
	      and a.idestadoorden = 9
          and a.flagapp = 1
          and a.debaja != 1
	      and a.idproducto = b.idproducto 
	      and b.idmodelo = c.idmodelo 
	      and c.idsubfamilia = d.idsubfamilia 
	    group by d.sigla
	    order by d.sigla asc;	
	
	else
	
    RETURN QUERY

	    select case 
					when d.sigla = 'HA' then 'HA Bomba Horizontal Carcasa Partida Axial'
					when d.sigla = 'VTP' then 'VTP Bomba Vertical Tipo Turbina'
					when d.sigla = 'HR' then 'HR Bomba Horizontal Carcasa Partida Radial'
					when d.sigla = 'HV' then 'HV Bomba Horizontal de Voluta'
					when d.sigla = 'SM' then 'SM Bomba Sumergible'	
					when d.sigla = 'VERT' then 'Tornillos Vertimil'
				else 'OT Otros modelos'
			   end ,
			   count(*),
			   case 
					when d.sigla = 'HA' then '0xff31D259'
					when d.sigla = 'VTP' then '0xff0A84FF'
					when d.sigla = 'HR' then '0xffBF5AF2'
					when d.sigla = 'HV' then '0xff5F5DE6'
					when d.sigla = 'SM' then '0xffFF9F0B'	
					when d.sigla = 'VERT' then '0xffFF9E06'
				else '0xffFC4736'
			   end 
	    from mct_ordentrabajo a,
	         mct_producto b,
	         mct_modelo c,
	         mct_subfamilia d
	    where a.idordentrabajo >= 30000
	      and a.idcliente = idcustomer
	      and a.idfamilia in (8,11)
	      and a.idtipoorden = 1
	      and a.idestadoorden = 9
          and a.flagapp = 1
          and a.debaja != 1
	      and a.idproducto = b.idproducto 
	      and b.idmodelo = c.idmodelo 
	      and c.idsubfamilia = d.idsubfamilia 
	    group by d.sigla
	    order by d.sigla asc;	
	
	end if;


  	
END;
$$;


ALTER FUNCTION traking.evtlisthistrepchart(idcustomer bigint) OWNER TO postgres;

