-- Name: evtlisthomefabchart(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthomefabchart(idcustomer bigint) RETURNS TABLE(task character varying, taskvalue bigint, colorval character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

		-- En fabricacion
		select cast('En Fabricación' as varchar), count(*), cast('0xffBF5AF2' as varchar)
		  from mct_ordentrabajo
		 where idordentrabajo >= 30000
		   and flagapp = 1
		   and idfamilia = 8
		   and idestadoorden > 4 and idestadoorden < 9
		   and idcliente = idcustomer
		   and idtipoorden = 2
		   and ordencompra > 0
		   having count(*) > 0;
  
		
END;
$$;


