--
-- TOC entry 1194 (class 1255 OID 17024)
-- Name: evtlisthomereciclaahorroapp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthomereciclaahorroapp(idcustomer bigint) RETURNS TABLE(reciclatot character varying, ahorrotot character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_reciclado    integer;
    sp_tot_piezasr  integer;
    sp_tot_recic    integer;
   
    sp_suma_tot     numeric;
    sp_suma_rec     numeric;
    sp_suma_ahorro  numeric;

    rec1 	   		record;
   
BEGIN

	sp_reciclado   := 0;
	sp_tot_piezasr := 0; 
	sp_tot_recic   := 0;	 
	sp_suma_tot    := 0;
	sp_suma_rec    := 0;
	sp_suma_ahorro := 0;
	 
	if ( idcustomer = 77 ) then
	
	   --RETURN QUERY
	   
	  FOR rec1 IN (	  
				   select a.idordentrabajo ,
				          case
					          when idlineadiseno = 3 then 0 
					          when idlineadiseno in (1,2) then coalesce (b.tonelada, 4.5)
					      end as tonelada,
				          case
					          when idlineadiseno = 3 then 0 
					          when idlineadiseno in (1,2) then coalesce (b.pesototal, 4.5)
					      end as pesotot					      
				          --coalesce (b.tonelada, 0) as tonelada,
				          --coalesce (b.pesototal, 0) as pesotot
				     from mct_ordentrabajo a,
				          mct_producto b 
				    where a.idestadoorden in (6,7,8,9)
				     -- and a.idcliente = 6
				 	  and a.flagapp = 1
			 		  and a.idfamilia = 8
					  and a.idproducto = b.idproducto
				      and a.idordentrabajo >= 30000
				      and a.debaja != 1	
				      and a.ordencompra > 0				      
				     -- order by a.idordentrabajo desc
	      
	        )
	  		loop  

		  		-- % de reciclaje
			    select sum(cantidad)
			      into sp_tot_piezasr
				  from mct_checklistinftec mc 
				 where idordentrabajo = rec1.idordentrabajo
				   and upper(criterio) not in ('RPO')
				   and upper(nombreparte) not like '%CHAVE%'
				   and upper(nombreparte) not like '%RRAGO%'
				   and upper(nombreparte) not like '%CORTAGO%'
				   and upper(nombreparte) not like '%PERNO%'	
				   and upper(nombreparte) not like '%GOLILL%'		
				   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
				   and upper(nombreparte) not like '%NIPL%'	;
				   
				select sum(cantidad)
				  into sp_tot_recic
				  from mct_checklistinftec mc 
				 where idordentrabajo = rec1.idordentrabajo
				   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
				   and upper(criterio) not like 'REM%';
	
				  
				sp_reciclado := 0;			   
			    sp_reciclado := coalesce (round( (sp_tot_recic * 100) / sp_tot_piezasr), 0);
		
			   	sp_suma_rec	 := 0;
			    
			    if ( rec1.pesotot > 0 ) then
			         sp_suma_rec  := rec1.pesotot * round((sp_tot_recic * 100) / sp_tot_piezasr)/100::numeric;		   
			    end if;
			   
			    sp_suma_ahorro :=  sp_suma_ahorro + sp_suma_rec;
			   
			    sp_suma_tot  := sp_suma_tot::numeric + rec1.tonelada::numeric;
			    --reciclatot := cast(round(rec1.tonelada/1000,2) as varchar );
		
	  		end loop;
	
	  			reciclatot := cast(round(sp_suma_ahorro/1000,3) as varchar );			   
			    ahorrotot  := cast(round(sp_suma_tot/1000,3) as varchar );
			   
			    --pesotot    := cast(rec1.pesotot as varchar );
			    --tonelada   := cast(rec1.tonelada as varchar );
			    --idot       := rec1.idordentrabajo;
			    --porcen	   := cast(sp_reciclado as varchar );
			   
			RETURN next;
		   
	else
	
	  FOR rec1 IN (	  
				   select a.idordentrabajo ,
				          case
					          when idlineadiseno = 3 then 0 
					          when idlineadiseno in (1,2) then coalesce (b.tonelada, 4.5)
					      end as tonelada,
				          case
					          when idlineadiseno = 3 then 0 
					          when idlineadiseno in (1,2) then coalesce (b.pesototal, 4.5)
					      end as pesotot					      
				          --coalesce (b.tonelada, 0) as tonelada,
				          --coalesce (b.pesototal, 0) as pesotot
				     from mct_ordentrabajo a,
				          mct_producto b 
				    where a.idestadoorden in (6,7,8,9)
				      and a.idcliente = idcustomer
				 	  and a.flagapp = 1
			 		  and a.idfamilia = 8
					  and a.idproducto = b.idproducto
				      and a.idordentrabajo >= 30000
				      and a.debaja != 1	
				      and a.ordencompra > 0
				     -- order by a.idordentrabajo desc
	      
	        )
	  		loop  

		  		-- % de reciclaje
			    select sum(cantidad)
			      into sp_tot_piezasr
				  from mct_checklistinftec mc 
				 where idordentrabajo = rec1.idordentrabajo
				   and upper(criterio) not in ('RPO')
				   and upper(nombreparte) not like '%CHAVE%'
				   and upper(nombreparte) not like '%RRAGO%'
				   and upper(nombreparte) not like '%CORTAGO%'
				   and upper(nombreparte) not like '%PERNO%'	
				   and upper(nombreparte) not like '%GOLILL%'		
				   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
				   and upper(nombreparte) not like '%NIPL%'	;
				   
				select sum(cantidad)
				  into sp_tot_recic
				  from mct_checklistinftec mc 
				 where idordentrabajo = rec1.idordentrabajo
				   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
				   and upper(criterio) not like 'REM%';
	
				  
				sp_reciclado := 0;			   
			    sp_reciclado := coalesce (round( (sp_tot_recic * 100) / sp_tot_piezasr), 0);
		
			   	sp_suma_rec	 := 0;
			    
			    if ( rec1.pesotot > 0 ) then
			         sp_suma_rec  := rec1.pesotot * round((sp_tot_recic * 100) / sp_tot_piezasr)/100::numeric;		   
			    end if;
			   
			    sp_suma_ahorro :=  sp_suma_ahorro + sp_suma_rec;
			   
			    sp_suma_tot  := sp_suma_tot::numeric + rec1.tonelada::numeric;
			    --reciclatot := cast(round(rec1.tonelada/1000,2) as varchar );
 
		
	  		end loop;
	
	  			reciclatot := cast(round(sp_suma_ahorro/1000,3) as varchar );			   
			    ahorrotot  := cast(round(sp_suma_tot/1000,3) as varchar );
			   
			    --pesotot    := cast(rec1.pesotot as varchar );
			    --tonelada   := cast(rec1.tonelada as varchar );
			    --idot       := rec1.idordentrabajo;
			    --porcen	   := cast(sp_reciclado as varchar );
			   
			RETURN next;
	

	end if;     
		
END;
$$;


ALTER FUNCTION traking.evtlisthomereciclaahorroapp(idcustomer bigint) OWNER TO postgres;

--
-- TOC entry 949 (class 1255 OID 17025)
-- Name: evtlisthomereciclaahorroapp_respaldo(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthomereciclaahorroapp_respaldo(idcustomer bigint) RETURNS TABLE(reciclatot character varying, ahorrotot character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idcustomer = 77 ) then
	
	   RETURN QUERY
	   
	   select cast(round(sum(coalesce (b.tonelada, 4.5)*0.20)/1000,2) as varchar ) ,
	          cast(round(sum(coalesce (b.tonelada, 4.5)/1000),2) as varchar )
	     from mct_ordentrabajo a,
	          mct_producto b 
	    where a.idestadoorden = 9
	 	  and a.flagapp = 1
 		  and a.idfamilia = 8
		  and a.idproducto = b.idproducto
	      and a.idordentrabajo >= 30000
	      and a.debaja != 1;	
		
	
	else
	
	   RETURN QUERY
	   
	   select 
	          cast(round(sum(coalesce (b.tonelada, 4.5)*0.20)/1000,2) as varchar ) ,
	          cast(round(sum(coalesce (b.tonelada, 4.5)/1000),2) as varchar )
	     from mct_ordentrabajo a,
	          mct_producto b 
	    where a.idcliente = idcustomer
	      and a.idestadoorden = 9
		  and a.flagapp = 1
		  and a.idfamilia = 8
		  and a.idproducto = b.idproducto 
		  and a.idordentrabajo >= 30000
		  and a.debaja != 1;	
	
				
	end if;     
		
END;
$$;


ALTER FUNCTION traking.evtlisthomereciclaahorroapp_respaldo(idcustomer bigint) OWNER TO postgres;

