				      --and (a.fechadespacho >= TO_TIMESTAMP('2020-11-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechadespacho <= TO_TIMESTAMP('2021-12-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				      and a.idcliente = idcustomer
				 	  and a.flagapp = 1
			 		  and a.idfamilia in (8,11)
					  and a.idproducto = b.idproducto
				      and a.idordentrabajo >= 30000
				      and a.debaja != 1	
				      and a.ordencompra > 0
				      and a.idtipoorden = 1
				      --and a.idordentrabajo not in (30709)
				     -- order by a.idordentrabajo desc
	      
	        )
	  		loop  

	  			sp_suma_bombas := sp_suma_bombas + 1;
	  		
		  		-- % de reciclaje
			    select sum(cantidad)
			      into sp_tot_piezasr
				  from mct_checklistinftec mc 
