ALTER FUNCTION traking.evtlisthomereciclaahorroapp_testdesk(idcustomer bigint, sdate character varying, edate character varying) OWNER TO postgres;

--
-- TOC entry 1951 (class 1255 OID 17029)
-- Name: evtlisthomereciclaahorroapp_testdeskbyot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthomereciclaahorroapp_testdeskbyot(idworkorders bigint) RETURNS TABLE(id bigint, ot bigint, customername character varying, fechar character varying, fechaa character varying, fechae character varying, tipo character varying, modelo character varying, avance bigint, monto bigint, otcliente character varying, recicla bigint, reciclado bigint, ahorro character varying, ciclo character varying)
    LANGUAGE plpgsql
    AS $$
declare

--	variable recicla es para reutilizacion
--	variable reciclado es para reciclaje

    sp_id      		integer;
    sp_ot      		integer;
    sp_fechar  		varchar;
    sp_fechaa  		timestamp;
    sp_fechae  		varchar;
    sp_tipo    		varchar;
    sp_modelo  		varchar;
    sp_avance  		numeric;
    sp_monto   		integer;
    sp_estado  		integer;
   
    sp_fechat  		varchar;
    sp_dias    		integer;
    sp_diast   		integer;
    sp_porc    		integer;
   
   -- Reutilizacion
    sp_recicla      integer;
    sp_tot_piezas   integer;
    sp_tot_reci     integer;
   
    sp_reciclado    integer;
    sp_tot_piezasr  integer;
    sp_tot_recic    integer;
   
    sp_dife    		integer;
   
    sp_diassla 		integer;
    cuenta_habiles	integer;
	sp_i            integer;
	dia_dow         integer;
    new_fechae      varchar;
    fecha_paso      timestamp;
    intervalo    	varchar;
    tot_ciclos		integer;
   
    sp_customer_name varchar;
   
    rec1 	   		record;
   
BEGIN

	select nombrecliente 
      into sp_customer_name
      from mct_ordentrabajo a,
           mct_cliente b
     where a.idordentrabajo = idworkorders
       and a.idcliente = b.idcliente;
	
	FOR rec1 IN (   
       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
              a.idordentrabajo as sp_ot,
              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
              to_char(a.fechaentrega, 'dd-mm-yyyy') as sp_fechae,
              d.sigla as sp_tipo,
              case 
                when idlineadiseno = 1 then 'DE DISEÑO'
                when idlineadiseno = 2 then 'DE LINEA'
              end||' - '||d.sigla||' '||c.nombreneptuno as sp_modelo,
              coalesce (a.montorepfab, 0) as sp_monto,
              a.idlineadiseno,
              a.otcliente ,
              coalesce (b.tonelada , 4.5) as tonelada,
              a.idestadoorden as estado
         from mct_ordentrabajo a,
              mct_producto b,
              mct_modelo c,
              mct_subfamilia d
        where a.idordentrabajo = idworkorders
          and a.idproducto = b.idproducto 
          and b.idmodelo = c.idmodelo 
          and c.idsubfamilia = d.idsubfamilia 
          
          )
		loop           
		
		   if ( rec1.idlineadiseno = 1 ) then
		   
		      select rembbadiseno
		        into sp_diassla
		        from mct_sla 
		       where idsla = 8;
		      
		   else 
		   
		      select rembbalinea 
		        into sp_diassla
		        from mct_sla 
		       where idsla = 8;
		     
		   end if;
		  
		   select fecha_autoriza_cliente
		     into sp_fechaa
		     from mct_progavisos mp 
		    where idsla = 5
		      and idordentrabajo = rec1.sp_ot;     
		         
		    sp_tot_piezas := 0;
		    sp_tot_reci   := 0;
		   
		    -- % de reutilización
		    select sum(cantidad)
		      into sp_tot_piezas
			  from mct_checklistinftec mc 
			 where idordentrabajo = rec1.sp_ot
			   and upper(criterio) not in ('RPO');
			   
			select sum(cantidad)
			  into sp_tot_reci
			  from mct_checklistinftec mc 
			 where idordentrabajo = rec1.sp_ot
			   and upper(criterio) not in ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO');
			  
			if (sp_tot_piezas = 0) then
			   sp_tot_piezas := 1;
			end if;
		
			sp_recicla := 0;
		 
		    sp_recicla := round( (sp_tot_reci * 100) / sp_tot_piezas);
		     
		   
		   	sp_tot_piezasr := 0;
		    sp_tot_recic   := 0;
		  
		   
		     -- % de reciclaje
		    select sum(cantidad)
		      into sp_tot_piezasr
			  from mct_checklistinftec mc 
			 where idordentrabajo = rec1.sp_ot
			   and upper(criterio) not in ('RPO')
			   and upper(nombreparte) not like '%CHAVE%'
			   and upper(nombreparte) not like '%RRAGO%'
			   and upper(nombreparte) not like '%CORTAGO%'
			   and upper(nombreparte) not like '%PERNO%'	
			   and upper(nombreparte) not like '%GOLILL%'		
			   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
			   and upper(nombreparte) not like '%NIPL%'			   
			  ;
			   
			select sum(cantidad)
			  into sp_tot_recic
			  from mct_checklistinftec mc 
			 where idordentrabajo = rec1.sp_ot
			   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
			   and upper(criterio) not like 'REM%';
		     
			  
			sp_reciclado := 0;
		    sp_reciclado := round( (sp_tot_recic * 100) / sp_tot_piezasr);
		   
			sp_i := 1;
		    cuenta_habiles := 0;
	
		    fecha_paso := sp_fechaa;
	  
	    
	        while ( sp_i <= sp_diassla) loop
	              
	              fecha_paso := fecha_paso + interval '1 day';
	             
	              dia_dow := date_part('dow', fecha_paso);
	              if ( dia_dow in (1,2,3,4,5) ) then
	              	  sp_i := sp_i + 1;	  
	              end if;
	              cuenta_habiles := cuenta_habiles + 1;	              

	        end loop;
	       
	       	--cuenta_habiles := cuenta_habiles + 1;
		   
		   	intervalo := ''''||cuenta_habiles||' day';
				
			select to_char(sp_fechaa + intervalo::interval, 'dd-mm-yyyy') into new_fechae;
		    	       
		    sp_avance  := 0;
		    --sp_fechat  := '';
		    sp_dias    := 0;
		    sp_dife    := 0;
		    sp_diast   := 0;
		    sp_porc    := 0;
		      

		       select to_char(fecha_termino,'dd-mm-yyyy'),
		              estado
		         into sp_fechae,
		              sp_estado
		         from mct_progavisos mp 
		        where idsla = 8
		          and idordentrabajo = rec1.sp_ot;  
		         
		         
		        if ( now() >= to_date(new_fechae,'dd-mm-yyyy')) then
		        
		           sp_avance := 100;
		        
		        end if;
		       
		        if ( now() < to_date(new_fechae,'dd-mm-yyyy')) then
		        
		           	
		            sp_diast := date_part('day', to_date(new_fechae,'dd-mm-yyyy') - sp_fechaa)  ;
		            sp_dias  := date_part('day', now() - sp_fechaa ) ;
		        --   
		            sp_dife   := sp_diast - sp_dias;
		            --sp_avance := round( (sp_dife * 100)/sp_diast  );
		           	sp_avance := 100 - (round( (sp_dife * 100)/sp_diast  ));	
		           
		        else
		        
		           sp_dias := 1;		           
		        
		        end if;
		       
		        if (sp_dias = 0) then
		        
		           sp_avance := 0;
		        
		        end if;

		       	if (sp_avance > 100) then
		        
		           sp_avance := 100;
		        
		        end if;
		       

		         
			    id      	:= rec1.sp_id;
			    ot      	:= rec1.sp_ot;
			    customername	:= sp_customer_name;
			    fechar  	:= rec1.sp_fechar;
			    fechaa  	:= to_char(sp_fechaa,'dd-mm-yyyy');
			    --fechae  := rec1.sp_fechae;
			    fechae  	:= new_fechae;
			    tipo    	:= rec1.sp_tipo;
			    modelo  	:= rec1.sp_modelo;
			    avance  	:= sp_avance;
			    monto   	:= rec1.sp_monto;
			    otcliente 	:= rec1.otcliente;
			    recicla     := coalesce(sp_recicla,0);
			    reciclado   := coalesce(sp_reciclado,0);
			   -- ahorro      := 9.3;
			    ahorro      := round(rec1.tonelada,1);
			    --ciclo		:= '5';

			   -- Ot de vertimil
			   if ( rec1.sp_ot = 30652 ) then
			   		recicla     := coalesce(33,0);
			    	reciclado   := coalesce(67,0);
			        ahorro		:= coalesce(43.8,0);
			   end if;
			  
			   if ( rec1.sp_ot = 30947 ) then
			   		recicla     := coalesce(33,0);
			    	reciclado   := coalesce(67,0);
			        ahorro		:= coalesce(43.8,0);
			   end if;
			  
			   if ( rec1.sp_ot = 30925 ) then
			   		recicla     := coalesce(33,0);
			    	reciclado   := coalesce(67,0);
			        ahorro		:= coalesce(43.8,0);
			   end if;
			   -- Saca ciclos
			   if ( rec1.estado = 9) then
			      tot_ciclos	:= traking.evtgetcantidadcicloshist(rec1.sp_ot);
			   else
			      tot_ciclos	:= traking.evtgetcantidadciclos(rec1.sp_ot);
			   end if;
		       
		       if (tot_ciclos = 0) then
				   ciclo	:= '-';	        
		       else
			       ciclo	:= tot_ciclos;		        
		       end if;

		      RETURN next;
		     
		END LOOP;		
		     

END;
$$;


ALTER FUNCTION traking.evtlisthomereciclaahorroapp_testdeskbyot(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 2374 (class 1255 OID 17031)
-- Name: evtlisthomerepchart(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisthomerepchart(idcustomer bigint) RETURNS TABLE(task text, taskvalue bigint, colorval text)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idcustomer = 77 ) then
	
	   RETURN QUERY

       select tipo, cantidad, color 
       from (
		-- En evaluacion
		select  2 as indice, 'En Evaluación' as tipo,count(*) as cantidad, '0xff31D259' as color
		  from mct_ordentrabajo mo 
		 where idordentrabajo >= 30000
		   and idestadoorden <= 4 and idestadoorden > 0
		  -- and idcliente = idcustomer
		   and idtipoorden = 1
		   and flagapp = 1
		   and idfamilia in (8)
		   and debaja < 1
		   having count(*) > 0  		   
		union   
		-- En reparacion se agrega flag 11 por vertimil
		select  1 as indice, 'En Remanufactura' as tipo,count(*) as cantidad, '0xff0A84FF' as color
		  from mct_ordentrabajo mo 
		 where idordentrabajo >= 30000
		   and idestadoorden >= 6 and idestadoorden < 9
		  -- and idcliente = idcustomer  
		   and idtipoorden = 1
		   and flagapp = 1
		   --and idfamilia = 8
		   and idfamilia in (8,11)
		   and ordencompra is not null 
		   and ordencompra > 0
		   and debaja < 1
		   having count(*) > 0   
		  union   	  
		-- Sin autorizacion
		select  3 as indice, 'Sin Autorización' as tipo,count(*) as cantidad, '0xffFF3760' as color
		  from mct_ordentrabajo mo 
		 where idordentrabajo >= 30000
           and idestadoorden in (5,6,7,8)
		  -- and idcliente = idcustomer  
		   and idtipoorden = 1
		   and flagapp = 1
		   and idfamilia in (8,11)
		   and (ordencompra is null or ordencompra = 0 or ordencompra < 0)
		   and debaja < 1
		  having count(*) > 0
		 union  		
		 -- En fabricacion
	   select 4 as indice, 'En Fabricación' as tipo, count(*) as cantidad, '0xffBF5AF2' as color
		 from mct_ordentrabajo
		where idordentrabajo >= 30000
	      and flagapp = 1
		  and idfamilia in (8, 15)
		  and idestadoorden > 4 and idestadoorden < 9
		 -- and idcliente = idcustomer
		  and idtipoorden = 2
		  and ordencompra > 0
		  and debaja < 1
		  having count(*) > 0
		  ) as a
		  order by indice asc;
		 
	
	else
	
	   RETURN QUERY

       select tipo, cantidad, color 
       from (
		-- En evaluacion
		select  2 as indice, 'En Evaluación' as tipo,count(*) as cantidad, '0xff31D259' as color
		  from mct_ordentrabajo mo 
		 where idordentrabajo >= 30000
		   and idestadoorden <= 4 and idestadoorden > 0
		   and idcliente = idcustomer
		   and idtipoorden = 1
		   and flagapp = 1
		   and idfamilia in (8)
		   having count(*) > 0  		   
		union   
		-- En reparacion se incluye flag 11 oara vertimil
		select  1 as indice, 'En Remanufactura' as tipo,count(*) as cantidad, '0xff0A84FF' as color
		  from mct_ordentrabajo mo 
		 where idordentrabajo >= 30000
		   and idestadoorden >= 6 and idestadoorden < 9
		   and idcliente = idcustomer  
		   and idtipoorden = 1
		   and flagapp = 1
		   --and idfamilia = 8		   
		   and idfamilia in (8,11)
		   and ordencompra is not null 
		   and ordencompra > 0
		   having count(*) > 0   
		union   
		-- Sin autorizacion
		select  3 as indice, 'Sin Autorización' as tipo,count(*) as cantidad, '0xffFF3760' as color
		  from mct_ordentrabajo mo 
		 where idordentrabajo >= 30000
           and idestadoorden in (5,6,7,8)
		   and idcliente = idcustomer  
		   and idtipoorden = 1
		   and flagapp = 1
		   and idfamilia in (8,11)
		   and (ordencompra is null or ordencompra = 0 or ordencompra < 0)
		  having count(*) > 0
	   union  		
	   -- En fabricacion
	   select 4 as indice, 'En Fabricación' as tipo, count(*) as cantidad, '0xffBF5AF2' as color
		 from mct_ordentrabajo
		where idordentrabajo >= 30000
	      and flagapp = 1
		  and idfamilia in (8, 15)
		  and idestadoorden > 4 and idestadoorden < 9
		  and idcliente = idcustomer
		  and idtipoorden = 2
		  and ordencompra > 0
		  having count(*) > 0	  
		  ) as a
		  order by indice asc;
	
	end if;
		
END;
$$;


