--
-- TOC entry 1727 (class 1255 OID 17034)
-- Name: evtlistinftecchecklist(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistinftecchecklist(idworkorders bigint) RETURNS TABLE(idpart bigint, partname character varying, materialname character varying, sigla character varying, description character varying, blueprintname character varying, principal bigint, quantity bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
			select b.idparte ,
			       c.nombreparte ,
			       e.nombrematerial ,
			       g.sigla ,
			       h.descripciontexto ,
			       f.nombreplano ,
			       c.esprincipal ,
			       count(*)
			from mct_ordentrabajo a,
			     mct_ordentrabajoparte b,
			     mct_parte c,
			     mct_evaluacion d,
			     mct_material e,
			     mct_plano f,
			     mct_tipotrabajo g,
			     mct_componentetipotrabajo h
			where a.idordentrabajo 	= idworkorders
			and a.idordentrabajo 	= b.idordentrabajo 
			and b.idparte  			= c.idparte 
			and b.idordentrabajoparte = d.idordentrabajoparte 
			and c.idmaterial 		= e.idmaterial 
			and c.idplano 			= f.idplano 
			and d.idtipotrabajo 	= g.idtipotrabajo 
			and c.idcomponente  	= h.idcomponente 
			and h.idtipotrabajo 	= d.idtipotrabajo 
			group by b.idparte ,
			         c.nombreparte ,
			         e.nombrematerial ,
			         g.sigla ,
			         h.descripciontexto ,
			         f.nombreplano ,
			         c.esprincipal 
			order by c.esprincipal asc, b.idparte  asc;
		
END;
$$;


