CREATE FUNCTION traking.evtlistinftecheadpdf(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idproduct bigint, productname character varying, idmanufacturer bigint, manufacturername character varying, idmodel bigint, modelname character varying, flowval bigint, rpmval bigint, heightval bigint, powerval bigint, idcustomer bigint, customername character varying, workordername character varying, idordertype bigint, ordertypename character varying, iduser bigint, username character varying, generalplan character varying, conclusion character varying, recomendation character varying, inputguide bigint, idworkorderprev bigint, receptiondate timestamp without time zone, picfile text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		select a.idordentrabajo, a.idproducto, b.nombreproducto, b.idfabricante, c.nombrefabricante, b.idmodelo,
		       d.nombremodelo, b.caudal, b.rpm, b.altura, b.potencia,  
		       a.idcliente, e.nombrecliente, a.nombreordentrabajo, a.idtipoorden, f.nombretipoorden, a.idusuario,
		       g.nombre, b.planogeneral, a.conclusion, a.recomendacion, a.guiaentrante , a.idordentrabajoanterior ,
		       a.fecharecepcion , h.archivoadjunto
		  from mct_ordentrabajo a,
		       mct_producto b,
		       mct_fabricante c,
		       mct_modelo d,
		       mct_cliente e,
		       mct_tipoorden f,
		       mct_usuario g,
		       mct_ordentrabajotipoadjunto h
		       --,
		      -- mct_productoplano h--,
		       --mct_plano j
		 where a.idordentrabajo = idworkorders
		   and a.idproducto     = b.idproducto
		   and b.idfabricante   = c.idfabricante
		   and b.idmodelo       = d.idmodelo
		   and a.idcliente      = e.idcliente
		   and a.idtipoorden    = f.idtipoorden 
		   and a.idusuario      = g.idusuario
		   and a.idordentrabajo = h.idordentrabajo
		   and h.idtipoadjunto  = 2
		   and h.correlativo    = 0
		   and h.idcategoriaadjunto = 1;
		   --and a.idproducto     = h.idproducto
		  -- and h.idplano        = j.idplano;

   END;
$$;


