CREATE FUNCTION traking.evtlistinputotdetail(periods character varying) RETURNS TABLE(idworkorder bigint, workordername character varying, deliverydate character varying, receptiondate character varying, statusname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		 
			select a.idordentrabajo ,
			       c.nombreproducto ,
			       cast(to_char(a.fechaentrega, 'dd-mm-yyyy') as varchar) ,
			       cast(to_char(a.fecharecepcion,'dd-mm-yyyy') as varchar),
			       b.nombreestado 
			  from mct_ordentrabajo a,
			       mct_estadoorden b,
			       mct_producto c
			 where to_date(to_char(a.fecharecepcion , 'yyyy-mm'),'yyyy-mm') = to_date(periods, 'yyyy-mm')
			   and a.idestadoorden = b.idestadoorden 
			   and a.idproducto    = c.idproducto 
			 order by a.idordentrabajo ;

END;
$$;


