--
-- TOC entry 1849 (class 1255 OID 17039)
-- Name: evtlistinputoutput(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistinputoutput(startdate character varying, enddate character varying) RETURNS TABLE(monthtext text, monthio integer, yeario integer, periodot character varying, inputot integer, outputot integer, deviationot integer)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		 
		    select mestexto,
		           mes, 
		           ano, 
		           periodo, 
		           cast(sum(ingreso) 		as integer), 
		           cast(sum(salida) 		as integer), 
		           cast(sum(ingreso-salida) as integer)
		    from (
					 select case 
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 1 then 'Enero'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 2 then 'Febrero'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 3 then 'Marzo'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 4 then 'Abril'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 5 then 'Mayo'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 6 then 'Junio'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 7 then 'Julio'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 8 then 'Agosto'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 9 then 'Septiembre'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 10 then 'Octubre'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 11 then 'Noviembre'
				               when cast(to_char(fecharecepcion ,'mm' ) as integer) = 12 then 'Diciembre'
	                        end as mestexto,
	                         cast(to_char(fecharecepcion ,'mm' ) 	as integer)	as mes,
					         cast(to_char(fecharecepcion ,'YYYY' )	as integer) as ano,
					         cast(to_char(fecharecepcion,'Month / YYYY' ) as varchar)	as periodo,
					         cast(count(*) as integer)	as ingreso,
					         cast(0 as integer)			as salida,
					         cast(0 as integer)			as desviacion
						from mct_ordentrabajo mo 
					   where fecharecepcion >= to_date(startdate,'yyyy-mm-dd') 
					     and fecharecepcion <= to_date(enddate,'yyyy-mm-dd')
					group by to_char(fecharecepcion ,'mm' ) ,
					         to_char(fecharecepcion ,'YYYY' ),
					         to_char(fecharecepcion,'Month / YYYY')
					--order by to_char(fecharecepcion ,'mm' ), to_char(fecharecepcion ,'YYYY' ) asc
				      UNION
				      select case 
							   when cast(to_char(fechadespacho ,'mm' ) as integer) = 1 then 'Enero'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 2 then 'Febrero'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 3 then 'Marzo'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 4 then 'Abril'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 5 then 'Mayo'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 6 then 'Junio'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 7 then 'Julio'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 8 then 'Agosto'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 9 then 'Septiembre'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 10 then 'Octubre'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 11 then 'Noviembre'
				               when cast(to_char(fechadespacho ,'mm' ) as integer) = 12 then 'Diciembre'
			                 end as mestexto,
	                         cast(to_char(fechadespacho ,'mm' ) 	as integer)	as mes,
				      		 cast(to_char(fechadespacho ,'YYYY' )	as integer) as ano,
				             cast(to_char(fechadespacho ,'Month / YYYY' ) as varchar)	as periodo,
				             cast(0 as integer)			as ingreso,
					         cast(count(*) as integer)	as salida, 
					         cast(0 as integer)			as desviacion
						from mct_ordentrabajo 
					   where idestadoorden = 7
					   	 and fechadespacho >= to_date(startdate,'yyyy-mm-dd') 
					   	 and fechadespacho <= to_date(enddate,'yyyy-mm-dd')
					group by to_char(fechadespacho ,'mm' ) ,
					         to_char(fechadespacho ,'YYYY' ),
					         to_char(fechadespacho,'Month / YYYY')
					         ) tabla
			group by mestexto, mes, ano, periodo
			order by mes, ano asc;


END;
$$;


ALTER FUNCTION traking.evtlistinputoutput(startdate character varying, enddate character varying) OWNER TO postgres;

--
-- TOC entry 1704 (class 1255 OID 17040)
-- Name: evtlistinsp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistinsp(idot bigint) RETURNS TABLE(item bigint, idinsp bigint, idordentrabajo bigint, codhojaruta character varying, idusuario bigint, nombreusuario character varying, idtipoinsp bigint, nombretipo character varying, idcomponente bigint, nombrecomponente character varying, numeroinsp bigint, nombreplano character varying, cantidad bigint, lastactivity character varying)
    LANGUAGE plpgsql
    AS $$
declare

     sp_nombre      varchar;
     sp_lastacti    varchar;
     
     rec_lista      RECORD;	
    
begin
	
		                                         
	FOR rec_lista IN (                               
			select ROW_NUMBER() OVER (ORDER BY a.numeroinsp asc) AS item,
			       a.idinsp ,
			       a.idordentrabajo ,
			       a.codhojaruta , 
			       a.idusuario ,
			       b.nombre ,
			       a.idtipoinsp ,
			       c.nombretipo ,
			       a.idcomponente ,
			       d.nombrecomponente ,
			       a.numeroinsp ,
			       a.nombreplano ,
			       a.cantidad
			  from mct_insp a ,
			       mct_usuario b,
			       mct_tipoinsp c,
			       mct_componente d
			 where a.idordentrabajo = idot
			   and a.idusuario = b.idusuario 
			   and a.idtipoinsp = c.idtipoinsp 
			   and a.idcomponente = d.idcomponente 
               and a.idtipoinsp not in (4,5,6)
			   )
   
		 loop 	
		
			 
				sp_lastacti := '';
			
				select codigoaccion
				  into sp_lastacti 
				  from mct_movimientoordentrabajo mm
				 where idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
					                                 from mct_movimientoordentrabajo b 
					                                where b.codhojaruta = rec_lista.codhojaruta );   	
					                               
					                   
				 item				:= rec_lista.item;
		         idinsp 			:= rec_lista.idinsp;
		         idordentrabajo 	:= rec_lista.idordentrabajo;
		         codhojaruta 		:= rec_lista.codhojaruta;
		         idusuario 			:= rec_lista.idusuario; 
		         nombreusuario		:= rec_lista.nombre;
		         idtipoinsp 		:= rec_lista.idtipoinsp;
		         nombretipo 		:= rec_lista.nombretipo;
		         idcomponente 		:= rec_lista.idcomponente;        
		         nombrecomponente 	:= rec_lista.nombrecomponente;
		         numeroinsp			:= rec_lista.numeroinsp;
		         nombreplano 		:= rec_lista.nombreplano; 
		         cantidad 			:= rec_lista.cantidad; 
		         lastactivity 		:= sp_lastacti;                         
			      
		         				
				 RETURN next;	
							     
				
		   end loop;
		                                         
END;
$$;


ALTER FUNCTION traking.evtlistinsp(idot bigint) OWNER TO postgres;

