--
-- TOC entry 1815 (class 1255 OID 17043)
-- Name: evtlistinspgrafico(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistinspgrafico(idots bigint, grafico bigint) RETURNS TABLE(texto1 character varying, texto2 character varying, dato1 bigint, dato2 bigint)
    LANGUAGE plpgsql
    AS $$
declare

     sp_texto1  varchar;
     sp_texto2  varchar;
     sp_dato1   integer;
     sp_dato2   integer;
    
BEGIN 
	
	sp_texto1 := '';
    sp_texto2 := '';
    sp_dato1  := 0;
    sp_dato2  := 0;
   
	if ( grafico = 1) then
	  -- Liberacion
	
	    sp_texto1 := 'Componentes Liberados';
	     -- Componente Liberado
 		select count(*)
 		  into sp_dato1
		  from mct_movimientoordentrabajo a
		 where a.idordentrabajo = idots
		   and a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
			                                   from mct_movimientoordentrabajo b 
		  	                                  where b.codhojaruta = a.codhojaruta )
		   and a.codigoaccion in ('L_CC', 'R_TM', 'R/E_TM');


	    sp_texto2 := 'Componentes en Proceso';		  
	     -- Componente en proceso
 		select count(*)
 		  into sp_dato2 		
		  from mct_movimientoordentrabajo a
		 where a.idordentrabajo = idots
		   and a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
			                                   from mct_movimientoordentrabajo b 
		  	                                  where b.codhojaruta = a.codhojaruta )
		   and a.codigoaccion not in ('L_CC', 'R_TM', 'R/E_TM');
		  
	
	elsif ( grafico = 2) then
	  -- Recepcion

		sp_texto1 := 'Recepción Taller Mecánico';
	     -- Componente Liberado
 		select count(*)
 		  into sp_dato1
		  from mct_movimientoordentrabajo a
		 where a.idordentrabajo = idots
		   and a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
			                                   from mct_movimientoordentrabajo b 
		  	                                  where b.codhojaruta = a.codhojaruta )
		   and a.codigoaccion in ('R_TM', 'R/E_TM');


		sp_texto2 := 'Componentes en Proceso';
		-- Componente en proceso
 		select count(*)
 		  into sp_dato2 		
		  from mct_movimientoordentrabajo a
		 where a.idordentrabajo = idots
		   and a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
			                                   from mct_movimientoordentrabajo b 
		  	                                  where b.codhojaruta = a.codhojaruta )
		   and a.codigoaccion not in ('R_TM', 'R/E_TM');	
	
	
	elsif ( grafico = 3) then
	  -- Seguimiento
	
		sp_texto1 := 'Componente sin Control de HR';	
		 -- Sin movimiento HR
		 select count(*)
		   into sp_dato1
		   from mct_hojarutatemp a,
		        mct_detallehojarutatemp b
		  where a.idordentrabajo = idots
		    and a.idhojarutatemp = b.idhojarutatemp 
		    and not exists ( select 'x' 
		                       from mct_movimientoordentrabajo c
		                      where b.codhojaruta = c.codhojaruta )  ;

		sp_texto2 := 'Componente Con Movimientos de HR';	
		-- Con movimiento HR
		 select count(*)
		   into sp_dato2
		   from mct_hojarutatemp a,
		        mct_detallehojarutatemp b
		  where a.idordentrabajo = idots
		    and a.idhojarutatemp = b.idhojarutatemp 
		    and  exists ( select 'x' 
		                       from mct_movimientoordentrabajo c
		                      where b.codhojaruta = c.codhojaruta )  ;		                     
		                     
	end if;

    texto1  := sp_texto1;
    texto2  := sp_texto2;
	dato1	:= sp_dato1; 
    dato2 	:= sp_dato2;

    return next;

				  
END;
$$;


