--
-- TOC entry 2098 (class 1255 OID 17046)
-- Name: evtlistinventarioinsumo(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistinventarioinsumo(idmarcas bigint) RETURNS TABLE(idinsumo bigint, idtipoinsumo bigint, nombretipoinsumo character varying, nombreinsumo character varying, codigobarras character varying, codigoplaca character varying, calidad character varying, idmarca bigint, nombremarca character varying, stockminimo bigint, stockcritico bigint, estado bigint, ingresostotales bigint, egresostotales bigint, stockdisponible bigint)
    LANGUAGE plpgsql
    AS $$  
declare 
      
	sp_stockingreso		integer;
	sp_stockegreso		integer;
	sp_disponible		integer;
	  
	rec_trab       		RECORD;	
	   
BEGIN

	 sp_stockingreso	:= 0;
	 sp_stockegreso		:= 0;
	 sp_disponible		:= 0;
	
	 if ( idmarcas = 0 ) then
	 
	 FOR rec_trab IN (   
      
					select a.idinsumo 			as idinsumo,
					       a.idtipoinsumo 		as idtipoinsumo,
					       b.nombretipoinsumo 	as nombretipoinsumo,
					       a.nombreinsumo 		as nombreinsumo,
					       a.codigobarras 		as codigobarras,
					       a.codigoplaca 		as codigoplaca,
					       a.calidad 			as calidad,
					       a.idmarca 			as idmarca,
					       c.nombremarca 		as nombremarca,
					       a.stockminimo 		as stockminimo,
					       a.stockcritico 		as stockcritico,
					       a.estado  			as estado
					  from mct_insumo a,
					       mct_tipoinsumo b,
					       mct_marca c
					 where a.idtipoinsumo = b.idtipoinsumo 
					   and a.idmarca = c.idmarca 
                       
         		       )
 
		loop 	

			select coalesce (a.stock, 0)
			  into sp_stockingreso
			  from mct_insumoingreso a
			 where a.codigobarras = rec_trab.codigobarras;
			
			
			select coalesce (b.stock, 0)
			  into sp_stockegreso
			  from mct_insumoegreso b
			 where b.codigobarras = rec_trab.codigobarras;
			         
		
			sp_disponible		:= 0;
		    sp_disponible		:= coalesce(sp_stockingreso,0) - coalesce(sp_stockegreso);
   
		   	idinsumo 			:= rec_trab.idinsumo;
		 	idtipoinsumo 		:= rec_trab.idtipoinsumo;
			nombretipoinsumo 	:= rec_trab.nombretipoinsumo;
			nombreinsumo 		:= rec_trab.nombreinsumo;
			codigobarras 		:= rec_trab.codigobarras;
			codigoplaca 		:= rec_trab.codigoplaca;
			calidad 			:= rec_trab.calidad;
			idmarca 			:= rec_trab.idmarca;
			nombremarca 		:= rec_trab.nombremarca;
			stockminimo 		:= rec_trab.stockminimo;
			stockcritico 		:= rec_trab.stockcritico;
			estado 				:= rec_trab.estado;
			ingresostotales 	:= coalesce(sp_stockingreso, 0);
			egresostotales 		:= coalesce(sp_stockegreso, 0);
			stockdisponible 	:= coalesce(sp_disponible, 0);
			
   			RETURN next;	
					 			     
		           
	  END LOOP;
	 
	 else

		 FOR rec_trab IN (   
	      
						select a.idinsumo 			as idinsumo,
						       a.idtipoinsumo 		as idtipoinsumo,
						       b.nombretipoinsumo 	as nombretipoinsumo,
						       a.nombreinsumo 		as nombreinsumo,
						       a.codigobarras 		as codigobarras,
						       a.codigoplaca 		as codigoplaca,
						       a.calidad 			as calidad,
						       a.idmarca 			as idmarca,
						       c.nombremarca 		as nombremarca,
						       a.stockminimo 		as stockminimo,
						       a.stockcritico 		as stockcritico,
						       a.estado  			as estado
						  from mct_insumo a,
						       mct_tipoinsumo b,
						       mct_marca c
						 where a.idmarca = idmarcas
						   and a.idtipoinsumo = b.idtipoinsumo 
						   and a.idmarca = c.idmarca 
	                       
	         		       )
	 
			loop 	
	
				select coalesce (a.stock, 0)
				  into sp_stockingreso
				  from mct_insumoingreso a
				 where a.codigobarras = rec_trab.codigobarras;
				
				
				select coalesce (b.stock, 0)
				  into sp_stockegreso
				  from mct_insumoegreso b
				 where b.codigobarras = rec_trab.codigobarras;
				         
			
				sp_disponible		:= 0;
			    sp_disponible		:= coalesce(sp_stockingreso,0) - coalesce(sp_stockegreso);
	   
			   	idinsumo 			:= rec_trab.idinsumo;
			 	idtipoinsumo 		:= rec_trab.idtipoinsumo;
				nombretipoinsumo 	:= rec_trab.nombretipoinsumo;
				nombreinsumo 		:= rec_trab.nombreinsumo;
				codigobarras 		:= rec_trab.codigobarras;
				codigoplaca 		:= rec_trab.codigoplaca;
				calidad 			:= rec_trab.calidad;
				idmarca 			:= rec_trab.idmarca;
				nombremarca 		:= rec_trab.nombremarca;
				stockminimo 		:= rec_trab.stockminimo;
				stockcritico 		:= rec_trab.stockcritico;
				estado 				:= rec_trab.estado;
				ingresostotales 	:= coalesce(sp_stockingreso, 0);
				egresostotales 		:= coalesce(sp_stockegreso, 0);
				stockdisponible 	:= coalesce(sp_disponible, 0);
				
	   			RETURN next;	
						 			     
			           
		  END LOOP;	 
	 
	 end if;
	
   END
$$;


ALTER FUNCTION traking.evtlistinventarioinsumo(idmarcas bigint) OWNER TO postgres;

--
-- TOC entry 1308 (class 1255 OID 17047)
-- Name: evtlistinventarioinsumocotizacion(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistinventarioinsumocotizacion(idmarcas bigint) RETURNS TABLE(idinsumo bigint, idtipoinsumo bigint, nombretipoinsumo character varying, nombreinsumo character varying, codigobarras character varying, codigoplaca character varying, calidad character varying, idmarca bigint, nombremarca character varying, stockminimo bigint, stockcritico bigint, estado bigint, ingresostotales bigint, egresostotales bigint, stockdisponible bigint)
    LANGUAGE plpgsql
    AS $$  
declare 
      
	sp_stockingreso		integer;
	sp_stockegreso		integer;
	sp_disponible		integer;
	  
	rec_trab       		RECORD;	
	   
BEGIN

	 sp_stockingreso	:= 0;
	 sp_stockegreso		:= 0;
	 sp_disponible		:= 0;
	

		 FOR rec_trab IN (   
	      
						select a.idinsumo 			as idinsumo,
						       a.idtipoinsumo 		as idtipoinsumo,
						       b.nombretipoinsumo 	as nombretipoinsumo,
						       a.nombreinsumo 		as nombreinsumo,
						       a.codigobarras 		as codigobarras,
						       a.codigoplaca 		as codigoplaca,
						       a.calidad 			as calidad,
						       a.idmarca 			as idmarca,
						       c.nombremarca 		as nombremarca,
						       a.stockminimo 		as stockminimo,
						       a.stockcritico 		as stockcritico,
						       a.estado  			as estado
						  from mct_insumo a,
						       mct_tipoinsumo b,
						       mct_marca c
						 where a.idmarca = idmarcas
						   and a.idtipoinsumo = b.idtipoinsumo 
						   and a.idmarca = c.idmarca 
	                       
	         		       )
	 
			loop 	
	
				select coalesce (a.stock, 0)
				  into sp_stockingreso
				  from mct_insumoingreso a
				 where a.codigobarras = rec_trab.codigobarras;
				
				
				select coalesce (b.stock, 0)
				  into sp_stockegreso
				  from mct_insumoegreso b
				 where b.codigobarras = rec_trab.codigobarras;
				         
			
				sp_disponible		:= 0;
			    sp_disponible		:= coalesce(sp_stockingreso,0) - coalesce(sp_stockegreso);
	   
			    if ( coalesce(sp_disponible, 0) < rec_trab.stockminimo) then

				    idinsumo 			:= rec_trab.idinsumo;
				 	idtipoinsumo 		:= rec_trab.idtipoinsumo;
					nombretipoinsumo 	:= rec_trab.nombretipoinsumo;
					nombreinsumo 		:= rec_trab.nombreinsumo;
					codigobarras 		:= rec_trab.codigobarras;
					codigoplaca 		:= rec_trab.codigoplaca;
					calidad 			:= rec_trab.calidad;
					idmarca 			:= rec_trab.idmarca;
					nombremarca 		:= rec_trab.nombremarca;
					stockminimo 		:= rec_trab.stockminimo;
					stockcritico 		:= rec_trab.stockcritico;
					estado 				:= rec_trab.estado;
					ingresostotales 	:= coalesce(sp_stockingreso, 0);
					egresostotales 		:= coalesce(sp_stockegreso, 0);
					stockdisponible 	:= coalesce(sp_disponible, 0);
				
	   			RETURN next;	
	   		
			    end if;

						 			     
			           
		  END LOOP;	 
	 
	
   END
$$;


ALTER FUNCTION traking.evtlistinventarioinsumocotizacion(idmarcas bigint) OWNER TO postgres;

--
-- TOC entry 1453 (class 1255 OID 17048)
-- Name: evtlistkpihistrepapp(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistkpihistrepapp(idcustomer bigint) RETURNS TABLE(kpiinf bigint, kpirep bigint, kpiclte bigint)
    LANGUAGE plpgsql
    AS $$
declare
   
    sp_kpiinf   integer;
    sp_kpirep   integer;
    sp_kpiclte  integer;
   
BEGIN     
        
	sp_kpiinf    := 0;
	sp_kpirep    := 0;
	sp_kpiclte   := 0;
	

    if ( idcustomer = 77 ) then

    -- Esto se debe arreglar cuando heraldo lo pida
    --select round(avg(date_part('day', b.fecha_real_termino - a.fecharecepcion ) ))
    select round(avg(date_part('day', b.fecha_termino - a.fecharecepcion ) ))
      into sp_kpiinf
      from mct_ordentrabajo a,
           mct_progavisos b
     where a.idordentrabajo >= 30000
       --and a.idestadoorden < 99
       and a.idestadoorden > 0
       and a.idestadoorden = 9
       and a.idtipoorden = 1
       and a.idfamilia = 8
       and a.flagapp = 1
       and a.debaja != 1
       and a.idordentrabajo = b.idordentrabajo 
       and b.idsla = 3
       and b.estado = 1;

    select --a.idordentrabajo ,
           --a.fecharecepcion,
           --b.fecha_termino,
           --date_part('day', b.fecha_termino - a.fecharecepcion )
           round(avg(date_part('day', a.fechadespacho - b.fecha_autoriza_cliente ) ))
      into sp_kpirep
      from mct_ordentrabajo a,
           mct_progavisos b
     where a.idordentrabajo >= 30000
       and a.idestadoorden < 99
       and a.idestadoorden > 0
       and a.idtipoorden = 1
       and a.idfamilia = 8
       and a.flagapp = 1
       and a.debaja != 1       
       and a.idordentrabajo = b.idordentrabajo 
       and b.idsla = 5;
       --and b.estado = 1;
  
    select --a.idordentrabajo ,
           --b.fecha_inicio,
           --b.fecha_real_termino ,
           --date_part('day', b.fecha_real_termino - b.fecha_inicio )
           round(avg(date_part('day', b.fecha_autoriza_cliente - b.fecha_inicio ) ))
      into sp_kpiclte
      from mct_ordentrabajo a,
           mct_progavisos b
     where a.idordentrabajo >= 30000
       and a.idestadoorden < 99
       and a.idestadoorden > 0
       and a.idtipoorden = 1
       and a.idfamilia = 8
       and a.flagapp = 1
       and a.debaja != 1       
       and a.ordencompra is not null and ordencompra > 0
       and a.idordentrabajo = b.idordentrabajo 
       and b.idsla in (4,5);     
      
    else

    -- Esto se debe arreglar cuando heraldo lo pida
    --select round(avg(date_part('day', b.fecha_real_termino - a.fecharecepcion ) ))
    select round(avg(date_part('day', b.fecha_termino - a.fecharecepcion ) ))
      into sp_kpiinf
      from mct_ordentrabajo a,
           mct_progavisos b
     where a.idcliente = idcustomer
       and a.idordentrabajo >= 30000
       --and a.idestadoorden < 99
       and a.idestadoorden > 0
       and a.idestadoorden = 9
       and a.idtipoorden = 1
       and a.idfamilia = 8
       and a.flagapp = 1
       and a.debaja != 1
       and a.idordentrabajo = b.idordentrabajo 
       and b.idsla = 3
       and b.estado = 1;

    select --a.idordentrabajo ,
           --a.fecharecepcion,
           --b.fecha_termino,
           --date_part('day', b.fecha_termino - a.fecharecepcion )
           round(avg(date_part('day', a.fechadespacho - b.fecha_autoriza_cliente ) ))
      into sp_kpirep
      from mct_ordentrabajo a,
           mct_progavisos b
     where a.idcliente = idcustomer
       and a.idordentrabajo >= 30000
       and a.idestadoorden < 99
       and a.idestadoorden > 0
       and a.idtipoorden = 1
       and a.idfamilia = 8
       and a.flagapp = 1
       and a.debaja != 1       
       and a.idordentrabajo = b.idordentrabajo 
       and b.idsla = 5;
       --and b.estado = 1;
  
    select --a.idordentrabajo ,
           --b.fecha_inicio,
           --b.fecha_real_termino ,
           --date_part('day', b.fecha_real_termino - b.fecha_inicio )
           round(avg(date_part('day', b.fecha_autoriza_cliente - b.fecha_inicio ) ))
      into sp_kpiclte
      from mct_ordentrabajo a,
           mct_progavisos b
     where a.idcliente = idcustomer
       and a.idordentrabajo >= 30000
       and a.idestadoorden < 99
       and a.idestadoorden > 0
       and a.idtipoorden = 1
       and a.idfamilia = 8
       and a.flagapp = 1
       and a.debaja != 1       
       and a.ordencompra is not null and ordencompra > 0
       and a.idordentrabajo = b.idordentrabajo 
       and b.idsla in (4,5);         
    
    end if;

             
	kpiinf    := sp_kpiinf;
	kpirep    := sp_kpirep;
	kpiclte   := sp_kpiclte;
			    	     
    RETURN next;

END;
$$;


ALTER FUNCTION traking.evtlistkpihistrepapp(idcustomer bigint) OWNER TO postgres;

--
-- TOC entry 1818 (class 1255 OID 17049)
-- Name: evtlistlastseqcategoriaadjunto(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistlastseqcategoriaadjunto(idworkorders bigint) RETURNS TABLE(idcategoriaadjunto bigint, nombrecategoriaadjunto character varying, lastseq bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

	RETURN QUERY
	
	select a.idcategoriaadjunto, a.nombrecategoriaadjunto, coalesce (max(b.correlativo), 0)
	  from mct_categoriaadjunto a
	  left join mct_ordentrabajotipoadjunto b on b.idcategoriaadjunto = a.idcategoriaadjunto and b.idordentrabajo = idworkorders
	 where a.estado = 1
	group by a.idcategoriaadjunto, 
	         a.nombrecategoriaadjunto
	order by a.idcategoriaadjunto asc  ;
  
END;
$$;


