--
-- TOC entry 1570 (class 1255 OID 17051)
-- Name: evtlistlimpiezamaquina(bigint, character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistlimpiezamaquina(idoperadori bigint, startdate character varying, enddate character varying, iddefectoi bigint) RETURNS TABLE(idlimpiezamaquina bigint, idusuario bigint, nombreusuario character varying, idsubseccion bigint, nombresubseccion character varying, idmaquina bigint, nombremaquina character varying, idoperator bigint, operatorname character varying, iddefecto bigint, nombredefecto character varying, usuariocreacion character varying, fechacreacion timestamp without time zone, usuariomodificacion character varying, fechamodificacion timestamp without time zone, idcierre bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN


	IF ( idoperadori = 0 and iddefectoi = 0) 
	     THEN 
	     -- Todos

	     	RETURN QUERY
			SELECT 
				a.idlimpiezamaquina,
				a.idusuario,
				b.nombre as nombreusuario,
				a.idsubseccion ,
				f.nombresubseccion ,
				a.idmaquina,
				c.nombremaquina,
				a.idoperador,
				e.nombreoperador,
				a.iddefecto,
				d.nombre  as nombredefecto,		
				a.usuariocreacion ,
				a.fechacreacion,
				a.usuariomodificacion,
				a.fechamodificacion,
				a.idcierre
			FROM traking.mct_limpiezamaquina  a
				left join  traking.mct_usuario b   on b.idusuario = a.idusuario 
				left join  traking.mct_maquina c   on c.idmaquina = a.idmaquina 
				left join  traking.mct_defecto d   on d.iddefecto = a.iddefecto 
				left join  traking.mct_operador e  on e.idoperador = a.idoperador
				left join  traking.mct_subseccion f on a.idsubseccion = f.idsubseccion 
			WHERE
				(a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'));
	
	elsif ( idoperadori > 0  and iddefectoi = 0) then

	     	RETURN QUERY
			SELECT 
				a.idlimpiezamaquina,
				a.idusuario,
				b.nombre as nombreusuario,
				a.idsubseccion ,
				f.nombresubseccion ,
				a.idmaquina,
				c.nombremaquina,
				a.idoperador,
				e.nombreoperador,
				a.iddefecto,
				d.nombre  as nombredefecto,		
				a.usuariocreacion ,
				a.fechacreacion,
				a.usuariomodificacion,
				a.fechamodificacion,
				a.idcierre
			FROM traking.mct_limpiezamaquina  a
				left join  traking.mct_usuario b   on b.idusuario = a.idusuario 
				left join  traking.mct_maquina c   on c.idmaquina = a.idmaquina 
				left join  traking.mct_defecto d   on d.iddefecto = a.iddefecto 
				left join  traking.mct_operador e  on e.idoperador = a.idoperador
				left join  traking.mct_subseccion f on a.idsubseccion = f.idsubseccion 
			WHERE
				(a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) and 
			    a.idoperador = idoperadori;	
			   
	elsif ( idoperadori = 0  and iddefectoi > 0) then

	     	RETURN QUERY
			SELECT 
				a.idlimpiezamaquina,
				a.idusuario,
				b.nombre as nombreusuario,
				a.idsubseccion ,
				f.nombresubseccion ,
				a.idmaquina,
				c.nombremaquina,
				a.idoperador,
				e.nombreoperador,
				a.iddefecto,
				d.nombre  as nombredefecto,		
				a.usuariocreacion ,
				a.fechacreacion,
				a.usuariomodificacion,
				a.fechamodificacion,
				a.idcierre
			FROM traking.mct_limpiezamaquina  a
				left join  traking.mct_usuario b   on b.idusuario = a.idusuario 
				left join  traking.mct_maquina c   on c.idmaquina = a.idmaquina 
				left join  traking.mct_defecto d   on d.iddefecto = a.iddefecto 
				left join  traking.mct_operador e  on e.idoperador = a.idoperador
				left join  traking.mct_subseccion f on a.idsubseccion = f.idsubseccion 
			WHERE
				(a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) and 
			    a.iddefecto = iddefectoi;	
			   
		elsif ( idoperadori > 0  and iddefectoi > 0) then

	     	RETURN QUERY
			SELECT 
				a.idlimpiezamaquina,
				a.idusuario,
				b.nombre as nombreusuario,
				a.idsubseccion ,
				f.nombresubseccion ,
				a.idmaquina,
				c.nombremaquina,
				a.idoperador,
				e.nombreoperador,
				a.iddefecto,
				d.nombre  as nombredefecto,		
				a.usuariocreacion ,
				a.fechacreacion,
				a.usuariomodificacion,
				a.fechamodificacion,
				a.idcierre
			FROM traking.mct_limpiezamaquina  a
				left join  traking.mct_usuario b   on b.idusuario = a.idusuario 
				left join  traking.mct_maquina c   on c.idmaquina = a.idmaquina 
				left join  traking.mct_defecto d   on d.iddefecto = a.iddefecto 
				left join  traking.mct_operador e  on e.idoperador = a.idoperador
				left join  traking.mct_subseccion f on a.idsubseccion = f.idsubseccion 
			WHERE
				(a.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				a.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) and 
			    a.idoperador = idoperadori and 
			    a.iddefecto = iddefectoi;	
			   
	end if;
		     				
		 
END;
$$;


