--
-- TOC entry 1898 (class 1255 OID 17052)
-- Name: evtlistmachinetimequeue(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmachinetimequeue(machine character varying) RETURNS TABLE(orderroadmap integer, coderoadmap character varying, idworkorder bigint, partname character varying, blueprintname character varying, timehistory numeric, timereal numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
	   
	    RETURN QUERY
	    
		select coalesce(a.orden,0), b.codhojaruta, c.idordentrabajo, d.nombreparte,f.nombreplano, sum(e.tiempohistorico), sum(e.tiempoproduccion)
		from mct_colatrabajo a,
		     mct_hojaruta b,
		     mct_ordentrabajoparte c,
		     mct_parte d,
		     mct_parteactividad e,
		     mct_plano f, 
		     mct_maquina g
		where g.nombremaquina = machine
		  and a.idmaquina = g.idmaquina
		  and a.idhojaruta = b.idhojaruta
		  and b.idordentrabajoparte = c.idordentrabajoparte
		  and c.idparte = d.idparte
		  and d.idparte = e.idparte
		  and d.idplano = f.idplano
		  group by a.orden, b.codhojaruta, c.idordentrabajo, d.nombreparte,f.nombreplano;

END;
$$;


ALTER FUNCTION traking.evtlistmachinetimequeue(machine character varying) OWNER TO postgres;

--
-- TOC entry 1359 (class 1255 OID 17053)
-- Name: evtlistmaestranza(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaestranza() RETURNS TABLE(sectionname character varying, codesection character varying, subsectionname character varying, machinename character varying, status bigint, operatorname character varying, tpoacum integer, tpoproc integer, tpodet integer, roadmapcode character varying, partname character varying, blueprintname character varying, ordertype character varying, productname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

    select *
    from (
			select --a.idmaquina , 
			       --a.idsubseccion , 
			       c.nombreseccion ,
			       c.codigoseccion ,
			       b.nombresubseccion ,
			       --b.idseccion ,
			       a.nombremaquina ,
			       d.estadoactividad ,
			       --d.idoperador ,
			       e.nombreoperador ,
			       cast(10 as integer),
			       case
						 when fechatermino is null then
							  cast((date_part('day', now()::timestamp - (fechainicio)::timestamp ) * 1440 + 
									date_part('hour', now()::timestamp - (fechainicio)::timestamp ) * 60 + 
									date_part('minute', now()::timestamp - (fechainicio)::timestamp )) as integer)
						 when fechatermino is not null then 
						      cast((date_part('day', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 1440 + 
								    date_part('hour', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 60 + 
								    date_part('minute', (fechatermino)::timestamp - (fechainicio)::timestamp )) as integer)		          
				   end,
			       cast(44 as integer),
			       d.codhojaruta ,
			       --d.idparte ,
			       f.nombrecomponente ,
			       --f.idplano ,
			       k.nombreplano ,
			       --d.idordentrabajo ,
			       --h.idtipoorden ,
			       j.nombretipoorden ,
			       i.nombreproducto 
			  from mct_maquina a
			  left join mct_subseccion b on a.idsubseccion = b.idsubseccion
			  left join mct_seccion c on b.idseccion = c.idseccion
			  left join mct_movimientoordentrabajo d on a.idmaquina  = d.idmaquina  and d.idoperador = d.idoperador and d.estadoactividad = 1
			  left join mct_operador e on d.idoperador = e.idoperador 
			  left join mct_componente f on d.idparte = f.idcomponente 
			  left join mct_ordentrabajo h on d.idordentrabajo = h.idordentrabajo 
			  left join mct_producto i on h.idproducto = i.idproducto 
			  left join mct_tipoorden j on h.idtipoorden = j.idtipoorden 
			  left join mct_detallehojarutatemp l on l.codhojaruta = d.codhojaruta 
			  left join mct_hojarutatemp k on k.idhojarutatemp = l.idhojarutatemp 
			  where a.estado  = 1
			    and c.estado = 1
			    and c.idseccion not in (11, 15, 32)
			  --and d.estadoactividad = 1
--			order by c.idseccion asc, 
--			         a.idsubseccion asc,
--			         a.nombremaquina asc
	   union
			select cast('SOLDADORES' as varchar) ,
			       cast('SL' as varchar) ,
			       cast('SOLDADORES' as varchar) ,
			       a.nombreoperador ,
			       d.estadoactividad ,
			       a.nombreoperador ,
			       cast(10 as integer),
			       case
						 when fechatermino is null then
							  cast((date_part('day', now()::timestamp - (fechainicio)::timestamp ) * 1440 + 
									date_part('hour', now()::timestamp - (fechainicio)::timestamp ) * 60 + 
									date_part('minute', now()::timestamp - (fechainicio)::timestamp )) as integer)
						 when fechatermino is not null then 
						      cast((date_part('day', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 1440 + 
								    date_part('hour', (fechatermino)::timestamp - (fechainicio)::timestamp ) * 60 + 
								    date_part('minute', (fechatermino)::timestamp - (fechainicio)::timestamp )) as integer)		          
				   end,
			       cast(44 as integer),
			       d.codhojaruta ,
			       f.nombrecomponente ,
			       k.nombreplano ,
			       j.nombretipoorden ,
			       i.nombreproducto 
			  from mct_operador a
--			  left join mct_subseccion b             on a.idsubseccion = b.idsubseccion
--			  left join mct_seccion c                on b.idseccion = c.idseccion
			  left join mct_movimientoordentrabajo d on d.idoperador = d.idoperador and d.estadoactividad = 1
--			  left join mct_operador e               on d.idoperador = e.idoperador 
			  left join mct_componente f             on d.idparte = f.idcomponente 
			  left join mct_ordentrabajo h           on d.idordentrabajo = h.idordentrabajo 
			  left join mct_producto i               on h.idproducto = i.idproducto 
			  left join mct_tipoorden j              on h.idtipoorden = j.idtipoorden 
			  left join mct_detallehojarutatemp l    on l.codhojaruta = d.codhojaruta 
			  left join mct_hojarutatemp k           on k.idhojarutatemp = l.idhojarutatemp 
			  where a.estado  = 1
--			    and c.estado = 1
--			    and c.idseccion in (13)
			    and a.idoperador in (46,114,289,283,184,231,276)
			    ) tabla
			    order by 1 asc, 
			             2 asc,
			             3 asc,
			             4 asc;

END;
$$;


ALTER FUNCTION traking.evtlistmaestranza() OWNER TO postgres;

--
-- TOC entry 1462 (class 1255 OID 17054)
-- Name: evtlistmaildist(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildist(idnotif bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
		
		  select b.asunto,  b.cuerpo, e.emaildestino
			from mct_notificacion a
			LEFT JOIN mct_cuerpomensaje  b    ON ( b.idnotificacion = a.idnotificacion)
			LEFT JOIN mct_notificacionlista c ON ( c.idnotificacion = a.idnotificacion)
			LEFT JOIN mct_listaemail d        ON ( d.idlista = c.idlista)
			LEFT JOIN mct_email e             ON ( d.idemail = e.idemail)
			WHERE a.idnotificacion= idnotif;
END;
$$;


ALTER FUNCTION traking.evtlistmaildist(idnotif bigint) OWNER TO postgres;

--
-- TOC entry 2113 (class 1255 OID 17055)
-- Name: evtlistmaildistemergenciaot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistemergenciaot(idots bigint) RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_salida				integer;
	   
	    sp_ot					bigint;
		sp_nombrecomp			varchar;
		sp_nombremat			varchar;
		sp_responsable			varchar;
	
	    sp_horas				bigint;
	   
	    sp_idusuario 			bigint;
		sp_nombremodelo			varchar;
		sp_sigla				varchar;
		sp_nombrebomba			varchar;
		sp_cliente				varchar;
		sp_idtipoorden			bigint;
		sp_idfamilia			bigint;
		sp_idproducto			bigint;
	
	    sp_fechaentrega			varchar;
	    sp_fechaemenos7			varchar;
         						    
begin
	
	  sp_salida := 0;
	 
	 	select coalesce (a.idusuario, 0) ,
		       coalesce (d.nombremodelo , 'SIN NOMBRE MO') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto ,
		       to_char(a.fechafaceclte , 'dd-mm-yyyy') as fechaentregaclte,
		       to_char(a.fechafaceclte - interval '7 days', 'dd-mm-yyyy') as fechaemenos7
		  into sp_idusuario ,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto,
		       sp_fechaentrega,
		       sp_fechaemenos7
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = idots;  
		
				
		sp_lista := '';
					   
		FOR rec_email IN (   
					select distinct c.emaildestino 
				      from mct_notificacionlista a,
			   			   mct_listaemail b,
	   		               mct_email c
				     where a.idnotificacion = 83
			           and a.idlista = b.idlista
				       and b.idemail = c.idemail 
			 	)
		    loop 	
						
				sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	    end loop;
		    
		sp_asunto := '';
		sp_texto  := '';
				 				 
		-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		select b.cuerpo,
	           b.asunto
		  into sp_texto,
	           sp_asunto
		  from mct_notificacion a
	      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
         WHERE a.idnotificacion= 83;
			      
        sp_texto  := REPLACE(sp_texto,'_valor_ot',idots::varchar);
        sp_texto  := REPLACE(sp_texto,'_valor_equipo',sp_nombrebomba::varchar);			   
        sp_texto  := REPLACE(sp_texto,'_valor_cliente',sp_cliente::varchar);

		sp_texto  := REPLACE(sp_texto,'_val_fecha_prioridades',sp_fechaentrega);
	    sp_texto  := REPLACE(sp_texto,'_val_fecha_menos7',sp_fechaemenos7);
       
		sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
							     
		sp_asunto  := REPLACE(sp_asunto,'_valor_ot',idots::varchar);
			 
		orden        :=  idots;
		asunto       :=  sp_asunto;
		cuerpo       :=  sp_texto; 
		emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
		codigonotf   :=  0; 


	    RETURN next;						    
		     
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistemergenciaot(idots bigint) OWNER TO postgres;

--
-- TOC entry 1561 (class 1255 OID 17056)
-- Name: evtlistmaildistgestionncf_tablet(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistgestionncf_tablet(idgestionncfs bigint, roadmapcodes character varying) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

    sp_idusuario			integer;
    sp_nombreingeniero		varchar;
    sp_nombreproducto		varchar;
    sp_nombremodelo			varchar;
    sp_sigla				varchar;
    sp_nombrebomba			varchar;
   
    sp_ot                   integer;
    sp_nombrecomp			varchar;
    sp_nombremat			varchar;
    sp_nombress				varchar;
    sp_nombremaq			varchar;
   
	sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
    sp_anno_hoy             VARCHAR=to_char(now(),'YYYY');
    sp_lista                varchar;
   
    sp_texto                varchar;
    sp_asunto               varchar;
    sp_senor                varchar;
   
    sp_intext				integer;
   
    sp_corr					integer;
    sp_notif				integer;
   
    sp_textostring			varchar;
    sp_fundicionorigen		varchar;
    sp_detectadefecto		varchar;
    sp_cliente				varchar;
    sp_detecta				integer;
   
   	sp_idtipoorden			integer;
    sp_idfamilia			integer;
    sp_idproducto			integer;
    
    sp_prod					integer;
   
    sp_textoubicacion		varchar;
   
    sp_textostringfoto		varchar;
    sp_plano				varchar;
    sp_idgestionncf			bigint;
   
    sp_nombreoperador		varchar;
    sp_nombreorigen		    varchar;
    sp_nombreaccion		    varchar;
    sp_observacion		    varchar;
    sp_nombrearea		    varchar;
    sp_nombreseccion		varchar;
    sp_nombrecargo		    varchar;
    sp_nombreorigenotro		varchar;

    sp_idoperador		    bigint;
   
    sp_responsable					varchar;
    sp_nombremecanizadooperador		varchar;
    sp_idmecanizadooperador			bigint;
    sp_listamail					bigint;
   
    sp_origenresponsable			varchar;
    sp_evaluador					varchar;
    sp_idorigenncf					bigint;
    sp_idsuborigenncf				bigint;
    sp_nombresuborigen				varchar;
   
    sp_codigonotf					bigint;
    sp_idareaapp					bigint;
   
    sp_textofinal					varchar;

    sp_emailevaluador				varchar;

	rec_email      					RECORD;
    rec_trab       					RECORD;					           
         						    
begin

    sp_responsable		:= '';
    sp_textoubicacion	:= '';
    sp_fundicionorigen	:= '';
    sp_observacion		:= '';
    sp_detectadefecto	:= '';
    sp_cliente			:= '';
    sp_detecta			:= 0;
    sp_textostring		:= '';
    sp_idgestionncf		:= 0;
    sp_idorigenncf		:= 0;
    sp_idsuborigenncf	:= 0;
    sp_nombremecanizadooperador	:= '';
    sp_evaluador		:= '';
   
    sp_prod				:= 0;
   
    sp_textofinal		:= '';

    select --a.idgestionncf,
           a.idoperador,
           b.nombreoperador,
           --a.idorigenncf,
           c.nombreorigen,
           --a.idaccionncf,
           d.nombreaccion,
           a.observacion,
           --b.idareaapp,
           e.nombrearea,
           --b.idseccionapp,
           f.nombreseccion,
           --b.idcargoapp,
           g.nombrecargo,
           c.responsable,
           c.listamail,
           a.idmecanizadooperador,
           j.nombre ,
           a.idorigenncf,
           coalesce(a.idsuborigenncf, 0),
           k.nombresuborigen,
           b.idareaapp 
      into sp_idoperador,
           sp_nombreoperador,
           sp_nombreorigen,
           sp_nombreaccion,
           sp_observacion,
           sp_nombrearea,
           sp_nombreseccion,
           sp_nombrecargo,
           sp_responsable,
           sp_listamail,
           sp_idmecanizadooperador,
           sp_evaluador,
           sp_idorigenncf,
           sp_idsuborigenncf,
           sp_nombresuborigen,
           sp_idareaapp
      from mct_gestionncf a
      left join mct_operador b   	on b.idoperador = a.idoperador
      left join mct_origenncf c  	on c.idorigenncf = a.idorigenncf
      left join mct_accionncf d  	on d.idaccionncf = a.idaccionncf
      left join mct_area e       	on e.idarea = b.idareaapp
      left join mct_seccion f    	on f.idseccion = b.idseccionapp
      left join mct_cargo g      	on g.idcargo = b.idcargoapp
      left join mct_ordentrabajo h	on h.idordentrabajo = a.idordentrabajo
      left join mct_usuario j       on j.idusuario = h.idusuario
      left join mct_suborigenncf k	on k.idsuborigenncf = a.idsuborigenncf
     where a.idgestionncf = idgestionncfs;

   	select a.nombreoperador||' ('||b.sigla||')'
      into sp_nombremecanizadooperador
      from mct_operador a 
      left join mct_cargo b on a.idcargoapp = b.idcargo
     where a.idoperador = sp_idmecanizadooperador;
        
	select coalesce (b.idordentrabajo , 0),
	       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
	       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
	       --coalesce (d.nombre , 'SIN RESPONSABLE'),
	       coalesce (b.nombreplano  , 'SIN RESPONSABLE')
	  into sp_ot,
	       sp_nombrecomp,
	       sp_nombremat,
	       --sp_responsable,
	       sp_plano
	  from mct_detallehojarutatemp a
	  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
	  join mct_componente c   on b.idcomponente = c.idcomponente
	  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
	 where a.codhojaruta = roadmapcodes;
	  
    select idproducto
      into sp_prod
      from mct_ordentrabajo mo 
     where idordentrabajo = sp_ot;
      
   -- sp_nombremecanizadooperador	:= 'N/A';
    if ( sp_idorigenncf = 4 ) then
    
    	sp_nombremecanizadooperador	:= sp_evaluador;
    
    elsif ( sp_idorigenncf = 1 ) then
    
    	sp_nombremecanizadooperador	:= sp_nombremecanizadooperador;
    
    elsif ( sp_idorigenncf in (2,3,5,6,7) ) then
    
    	sp_nombremecanizadooperador	:= sp_responsable;
    
    end if;
   
   
    if ( sp_prod in (10,11,12,13,14,15,16,17)) then
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE P') ,
		       'SIN NOMBRE MO' ,
		       'SIN NOMBRE SIG' ,
		       coalesce (c.nombreproductonepcast  , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto ,
               b.email
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto ,
               sp_emailevaluador
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_productonepcast c on a.idproducto = c.idproductonepcast 
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    else
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') as producto,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto ,
               b.email
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto ,
               sp_emailevaluador
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    end if;
   
    if (sp_idsuborigenncf = 0) then
	    sp_corr := nextval('mct_gestionncfcorr_seq');
	
		update mct_gestionncf
		   set correlativo = sp_corr
		 where idgestionncf = idgestionncfs;
		
		sp_nombresuborigen	:= 'NO APLICA';
	
    end if;
   
    --sp_codigonotf	:= 82;

    --sp_codigonotf	:= 86;
    --sp_codigonotf	:= 99;

    sp_codigonotf	:= 100;
    sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 96 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y ANÁLISIS DE DATA(MAGMA) PARA DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	if (sp_idorigenncf = 2) then

   		if (sp_idsuborigenncf > 0) then
   			--sp_codigonotf	:= 99;
            sp_codigonotf	:= 86;
   			--sp_listamail	:= 93;
   		    --sp_nombreorigen	:= sp_nombreorigen||' (PROCESO INTERNO)';
            --sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
   		else
   			sp_codigonotf	:= 100;
   		    --sp_nombreorigen	:= sp_nombreorigen||' (CONTROL INTERNO)';
            --sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
   		end if;

    elsif (sp_idorigenncf = 9) then
		sp_codigonotf	:= 101;
    end if;

  	if (sp_idareaapp != 10) then
		--sp_nombreorigen	:= sp_nombreorigen||' (CLIENTE INTERNO)';
		--sp_nombreorigen := replace(sp_nombreorigen,'(PROCESO INTERNO)','');
		--sp_nombreorigen := replace(sp_nombreorigen,'(CONTROL INTERNO)','');
        --sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
	end if;

--   	if (sp_idsuborigenncf = 2) then
--   	        sp_nombremecanizadooperador	:= 'RENZO CUELLAR';
--   	    	--sp_responsable	:= 'RENZO CUELLAR';
--   	    elsif (sp_idsuborigenncf = 1) then
--   	        sp_nombremecanizadooperador	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
--   	      	--sp_responsable	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
--   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	    elsif (sp_idsuborigenncf = 1) then
--   	        sp_nombremecanizadooperador	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
--   	      	--sp_responsable	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
--   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	    elsif (sp_idsuborigenncf = 3) then
--   	        sp_nombremecanizadooperador	:= 'ROBERTO NAVALON - RENZO CUELLAR';
--   	    	--sp_responsable	:= 'IVÁN COLLANTE';
--   	    elsif (sp_idsuborigenncf = 4) then
--   	        sp_nombremecanizadooperador	:= 'ROBERTO NAVALON - ERIK IRRAZABAL';
--   	    	--sp_responsable	:= 'ROBERTO NAVALON - ERIK IRRAZABAL';
--   	    	--sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	    elsif (sp_idsuborigenncf = 5) then
--   	        sp_nombremecanizadooperador	:= 'IVÁN COLLANTE - RENZO CUELLAR';
--   	      	--sp_responsable	:= 'ROBERTO NAVALON';
--   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	    elsif (sp_idsuborigenncf = 6) then
--   	        sp_nombremecanizadooperador	:= 'IVÁN COLLANTE - ROBERTO NAVALON';
--   	      	--sp_responsable	:= 'ROBERTO NAVALON';
--   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	   
--   	end if;
   	
   
	sp_lista := '';
					   
	FOR rec_email IN (   
	    select distinct c.emaildestino 
		  from mct_listaemail b,
		       mct_email c
	     where b.idlista = sp_listamail
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;

--    if (sp_idsuborigenncf > 0) then
--    	sp_lista := 'squijada2703@gmail.com,scuadra@neplocal.cl,';
--    end if;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion = sp_codigonotf;
			      
     if (sp_idorigenncf = 2) then

         if (sp_idoperador in (467,526) ) then

			--sp_nombreorigen := 'PL A FUNDICION 01';
            sp_nombreorigen := 'FUNDICION 01';
		 else
			sp_nombreorigen := 'FUNDICION 01';
         end if;

	     sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));

	     sp_texto   := REPLACE(sp_texto,'_valor_comp',coalesce(sp_nombrecomp,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_material',coalesce(sp_nombremat,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_producto',coalesce(sp_nombrebomba,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_cliente',coalesce(sp_cliente,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_descripcion',coalesce(sp_observacion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_accion',coalesce(sp_nombreaccion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable,sp_evaluador));
	     sp_texto   := REPLACE(sp_texto,'_valor_operador',coalesce(sp_nombremecanizadooperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_suborigen',coalesce(sp_nombresuborigen,'N/A'));	    
		 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
	     sp_texto   := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
         sp_texto   := REPLACE(sp_texto,'_valor_anno',sp_anno_hoy::varchar);
		
		 sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
				 
		 asunto       :=  cast(sp_asunto as varchar);
		 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
		 if (sp_listamail in (85,91,90,84,105,106)) then
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||','||sp_emailevaluador;
		 else
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);	
		 end if;
		 codigonotf   :=  sp_codigonotf; 
					 
		 RETURN next;

     elsif (sp_idorigenncf = 8) then

			if (sp_idorigenncf = 1) then
				sp_nombreorigenotro	:= 'MECANIZADO CONVENCIONAL';
			elsif (sp_idorigenncf = 3) then
			   sp_nombreorigenotro	:= 'CALDERERÍA';
			elsif (sp_idorigenncf = 4) then
			   sp_nombreorigenotro	:= 'INGENIERÍA';
			elsif (sp_idorigenncf = 5) then
			   sp_nombreorigenotro	:= 'TALLER MECANICO';
			elsif (sp_idorigenncf = 6) then
			   sp_nombreorigenotro	:= 'CONTROL DE CALIDAD';
			elsif (sp_idorigenncf = 8) then
			   sp_nombreorigenotro	:= 'MECANIZADO CNC';
			end if;
	
	         if (sp_idoperador in (467,526) ) then -- PLANIFICACION
	
				--sp_nombreorigen := 'PL a '||sp_nombreorigenotro;
                sp_nombreorigen := sp_nombreorigenotro;
	
	         elsif (sp_idoperador in (42,495,8,497,521,498,496,2,549) ) then -- TALLER MECANICO
	
				--sp_nombreorigen := 'TM a '||sp_nombreorigenotro;
	            sp_nombreorigen := sp_nombreorigenotro;
	
			 elsif (sp_idoperador in (513) ) then -- CALDERERIA
	
				--sp_nombreorigen := 'CAL a '||sp_nombreorigenotro;
	            sp_nombreorigen := sp_nombreorigenotro;
	
			 elsif (sp_idoperador in (454,537,529,477,218) ) then -- CONTROL DE CALIDAD
	
				--sp_nombreorigen := 'CC a '||sp_nombreorigenotro;
	            sp_nombreorigen := sp_nombreorigenotro;
	
			 elsif (sp_idoperador in (358) ) then -- MECANIZADO
	
				--sp_nombreorigen := 'MEC a '||sp_nombreorigenotro;
	            sp_nombreorigen := sp_nombreorigenotro;
	
			 elsif (sp_idoperador in (50) ) then -- MECANIZADO CNC
	
				--sp_nombreorigen := 'MEC-CNC a '||sp_nombreorigenotro;
	            sp_nombreorigen := sp_nombreorigenotro;
	
	         elsif (sp_idoperador in (26,63) ) then -- GERENCIA
	
				--sp_nombreorigen := 'GERENCIA a '||sp_nombreorigenotro;
	            sp_nombreorigen := sp_nombreorigenotro;
	
	         end if;
	
             if (sp_idorigenncf = 4) then
				sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable||' / '||sp_evaluador,sp_evaluador));

             elsif (sp_idorigenncf in (1,8)) then
				sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable||' / '||sp_nombremecanizadooperador,sp_responsable));

             else
				sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable,sp_evaluador));
             end if;
		     
		     sp_texto   := REPLACE(sp_texto,'_valor_comp',coalesce(sp_nombrecomp,'N/A'));
		     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'N/A'));
		     sp_texto   := REPLACE(sp_texto,'_valor_material',coalesce(sp_nombremat,'N/A'));
		     sp_texto   := REPLACE(sp_texto,'_valor_producto',coalesce(sp_nombrebomba,'N/A'));
		     sp_texto   := REPLACE(sp_texto,'_valor_cliente',coalesce(sp_cliente,'N/A'));
	         sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));
		     sp_texto   := REPLACE(sp_texto,'_valor_suborigen',coalesce(sp_nombresuborigen,'N/A'));	    
			 sp_texto   := REPLACE(sp_texto,'_valor_descripcion',coalesce(sp_observacion,'N/A'));
		     sp_texto   := REPLACE(sp_texto,'_valor_accion',coalesce(sp_nombreaccion,'N/A'));
		     sp_texto   := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
	         sp_texto   := REPLACE(sp_texto,'_valor_anno',sp_anno_hoy::varchar);
			
		     sp_texto   := REPLACE(sp_texto,'_valor_textofinal',coalesce(sp_textofinal,'N/A'));		
			 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);		
					 
			 sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
	
			 asunto       :=  cast(sp_asunto as varchar);
			 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
			 if (sp_listamail in (85,91,90,84,105,106)) then
		        emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||','||sp_emailevaluador;
             else
			    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);	
			 end if;
			 codigonotf   :=  sp_codigonotf; 
						 
			 RETURN next;	      

     else

		if (sp_idorigenncf = 1) then
			sp_nombreorigenotro	:= 'MECANIZADO CONVENCIONAL';
		elsif (sp_idorigenncf = 3) then
		   sp_nombreorigenotro	:= 'CALDERERÍA';
		elsif (sp_idorigenncf = 4) then
		   sp_nombreorigenotro	:= 'INGENIERÍA';
		elsif (sp_idorigenncf = 5) then
		   sp_nombreorigenotro	:= 'TALLER MECANICO';
		elsif (sp_idorigenncf = 6) then
		   sp_nombreorigenotro	:= 'CONTROL DE CALIDAD';
		elsif (sp_idorigenncf = 8) then
		   sp_nombreorigenotro	:= 'MECANIZADO CNC';
        elsif (sp_idorigenncf = 9) then
		   sp_nombreorigenotro	:= sp_nombreorigen;
		end if;

         if (sp_idoperador in (467,526) ) then -- PLANIFICACION

				--sp_nombreorigen := 'PL a '||sp_nombreorigenotro;
                sp_nombreorigen := sp_nombreorigenotro;

         elsif (sp_idoperador in (42,495,8,497,521,498,496,2,549) ) then -- TALLER MECANICO

			--sp_nombreorigen := 'TM a '||sp_nombreorigenotro;
            sp_nombreorigen := sp_nombreorigenotro;

		 elsif (sp_idoperador in (513) ) then -- CALDERERIA

			--sp_nombreorigen := 'CAL a '||sp_nombreorigenotro;
            sp_nombreorigen := sp_nombreorigenotro;

		 elsif (sp_idoperador in (454,537,529,477,218) ) then -- CONTROL DE CALIDAD

			--sp_nombreorigen := 'CC a '||sp_nombreorigenotro;
            sp_nombreorigen := sp_nombreorigenotro;

		 elsif (sp_idoperador in (358) ) then -- MECANIZADO

			--sp_nombreorigen := 'MEC a '||sp_nombreorigenotro;
            sp_nombreorigen := sp_nombreorigenotro;

		 elsif (sp_idoperador in (50) ) then -- MECANIZADO CNC

			--sp_nombreorigen := 'MEC-CNC a '||sp_nombreorigenotro;
            sp_nombreorigen := sp_nombreorigenotro;

         elsif (sp_idoperador in (26,63) ) then -- GERENCIA

			--sp_nombreorigen := 'GERENCIA a '||sp_nombreorigenotro;
            sp_nombreorigen := sp_nombreorigenotro;

         end if;

             if (sp_idorigenncf = 4) then
				sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable||' / '||sp_evaluador,sp_evaluador));

             elsif (sp_idorigenncf in (1,8)) then
				sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable||' / '||sp_nombremecanizadooperador,sp_responsable));

             else
				sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable,sp_evaluador));
             end if;

	     sp_texto   := REPLACE(sp_texto,'_valor_comp',coalesce(sp_nombrecomp,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_material',coalesce(sp_nombremat,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_producto',coalesce(sp_nombrebomba,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_cliente',coalesce(sp_cliente,'N/A'));
         sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_suborigen',coalesce(sp_nombresuborigen,'N/A'));	    
		 sp_texto   := REPLACE(sp_texto,'_valor_descripcion',coalesce(sp_observacion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_accion',coalesce(sp_nombreaccion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
         sp_texto   := REPLACE(sp_texto,'_valor_anno',sp_anno_hoy::varchar);
		
	     sp_texto   := REPLACE(sp_texto,'_valor_textofinal',coalesce(sp_textofinal,'N/A'));		
		 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);		
				 
         if (sp_idorigenncf = 9) then
		     sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigenotro::varchar,'N/A'));
         else
             sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
		 end if;
		 

		 asunto       :=  cast(sp_asunto as varchar);
		 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
		 if (sp_listamail in (85,91,90,84,105,106)) then
	        emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||','||sp_emailevaluador;
		 else
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);	
		 end if;
		 codigonotf   :=  sp_codigonotf; 
					 
		 RETURN next;	      

     end if;
	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistgestionncf_tablet(idgestionncfs bigint, roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 1141 (class 1255 OID 17058)
-- Name: evtlistmaildistgestionncf_tablet_cambioformato(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistgestionncf_tablet_cambioformato(idgestionncfs bigint, roadmapcodes character varying) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

    sp_idusuario			integer;
    sp_nombreingeniero		varchar;
    sp_nombreproducto		varchar;
    sp_nombremodelo			varchar;
    sp_sigla				varchar;
    sp_nombrebomba			varchar;
   
    sp_ot                   integer;
    sp_nombrecomp			varchar;
    sp_nombremat			varchar;
    sp_nombress				varchar;
    sp_nombremaq			varchar;
   
	sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
    sp_anno_hoy             VARCHAR=to_char(now(),'YYYY');
    sp_lista                varchar;
   
    sp_texto                varchar;
    sp_asunto               varchar;
    sp_senor                varchar;
   
    sp_intext				integer;
   
    sp_corr					integer;
    sp_notif				integer;
   
    sp_textostring			varchar;
    sp_fundicionorigen		varchar;
    sp_detectadefecto		varchar;
    sp_cliente				varchar;
    sp_detecta				integer;
   
   	sp_idtipoorden			integer;
    sp_idfamilia			integer;
    sp_idproducto			integer;
    
    sp_prod					integer;
   
    sp_textoubicacion		varchar;
   
    sp_textostringfoto		varchar;
    sp_plano				varchar;
    sp_idgestionncf			bigint;
   
    sp_nombreoperador		varchar;
    sp_nombreorigen		    varchar;
    sp_nombreaccion		    varchar;
    sp_observacion		    varchar;
    sp_nombrearea		    varchar;
    sp_nombreseccion		varchar;
    sp_nombrecargo		    varchar;
   
    sp_responsable					varchar;
    sp_nombremecanizadooperador		varchar;
    sp_idmecanizadooperador			bigint;
    sp_listamail					bigint;
   
    sp_origenresponsable			varchar;
    sp_evaluador					varchar;
    sp_idorigenncf					bigint;
    sp_idsuborigenncf				bigint;
    sp_nombresuborigen				varchar;
   
    sp_codigonotf					bigint;
    sp_idareaapp					bigint;
   
    sp_textofinal					varchar;

	rec_email      RECORD;
    rec_trab       RECORD;					           
         						    
begin

    sp_responsable		:= '';
    sp_textoubicacion	:= '';
    sp_fundicionorigen	:= '';
    sp_observacion		:= '';
    sp_detectadefecto	:= '';
    sp_cliente			:= '';
    sp_detecta			:= 0;
    sp_textostring		:= '';
    sp_idgestionncf		:= 0;
    sp_idorigenncf		:= 0;
    sp_idsuborigenncf	:= 0;
    sp_nombremecanizadooperador	:= '';
    sp_evaluador		:= '';
   
    sp_prod				:= 0;
   
    sp_textofinal		:= '';

    select --a.idgestionncf,
           --a.idoperador,
           b.nombreoperador,
           --a.idorigenncf,
           c.nombreorigen,
           --a.idaccionncf,
           d.nombreaccion,
           a.observacion,
           --b.idareaapp,
           e.nombrearea,
           --b.idseccionapp,
           f.nombreseccion,
           --b.idcargoapp,
           g.nombrecargo,
           c.responsable,
           c.listamail,
           a.idmecanizadooperador,
           j.nombre ,
           a.idorigenncf,
           coalesce(a.idsuborigenncf, 0),
           k.nombresuborigen,
           b.idareaapp 
      into sp_nombreoperador,
           sp_nombreorigen,
           sp_nombreaccion,
           sp_observacion,
           sp_nombrearea,
           sp_nombreseccion,
           sp_nombrecargo,
           sp_responsable,
           sp_listamail,
           sp_idmecanizadooperador,
           sp_evaluador,
           sp_idorigenncf,
           sp_idsuborigenncf,
           sp_nombresuborigen,
           sp_idareaapp
      from mct_gestionncf a
      left join mct_operador b   	on b.idoperador = a.idoperador
      left join mct_origenncf c  	on c.idorigenncf = a.idorigenncf
      left join mct_accionncf d  	on d.idaccionncf = a.idaccionncf
      left join mct_area e       	on e.idarea = b.idareaapp
      left join mct_seccion f    	on f.idseccion = b.idseccionapp
      left join mct_cargo g      	on g.idcargo = b.idcargoapp
      left join mct_ordentrabajo h	on h.idordentrabajo = a.idordentrabajo
      left join mct_usuario j       on j.idusuario = h.idusuario
      left join mct_suborigenncf k	on k.idsuborigenncf = a.idsuborigenncf
     where a.idgestionncf = idgestionncfs;
    
    select nombreoperador
      into sp_nombremecanizadooperador
      from mct_operador mo 
     where idoperador = sp_idmecanizadooperador;
        
	select coalesce (b.idordentrabajo , 0),
	       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
	       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
	       --coalesce (d.nombre , 'SIN RESPONSABLE'),
	       coalesce (b.nombreplano  , 'SIN RESPONSABLE')
	  into sp_ot,
	       sp_nombrecomp,
	       sp_nombremat,
	       --sp_responsable,
	       sp_plano
	  from mct_detallehojarutatemp a
	  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
	  join mct_componente c   on b.idcomponente = c.idcomponente
	  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
	 where a.codhojaruta = roadmapcodes;
	  
    select idproducto
      into sp_prod
      from mct_ordentrabajo mo 
     where idordentrabajo = sp_ot;
      
   -- sp_nombremecanizadooperador	:= 'N/A';
    if ( sp_idorigenncf = 4 ) then
    
    	sp_nombremecanizadooperador	:= sp_evaluador;
    
    elsif ( sp_idorigenncf = 1 ) then
    
    	sp_nombremecanizadooperador	:= sp_nombremecanizadooperador;
    
    elsif ( sp_idorigenncf in (2,3,5,6,7) ) then
    
    	sp_nombremecanizadooperador	:= sp_responsable;
    
    end if;
   
   
    if ( sp_prod in (10,11,12,13,14,15,16,17)) then
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE P') ,
		       'SIN NOMBRE MO' ,
		       'SIN NOMBRE SIG' ,
		       coalesce (c.nombreproductonepcast  , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_productonepcast c on a.idproducto = c.idproductonepcast 
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    else
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') as producto,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    end if;
   
    if (sp_idsuborigenncf = 0) then
	    sp_corr := nextval('mct_gestionncfcorr_seq');
	
		--update mct_gestionncf
		--   set correlativo = sp_corr
		-- where idgestionncf = idgestionncfs;
		
		sp_nombresuborigen	:= 'NO APLICA';

	
    end if;
   
    sp_codigonotf	:= 86;
    --sp_codigonotf	:= 99;
    sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 96 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y ANÁLISIS DE DATA(MAGMA) PARA DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	if (sp_idorigenncf = 2) then

   		if (sp_idsuborigenncf > 0) then
   			--sp_codigonotf	:= 99;
            sp_codigonotf	:= 86;
   			sp_listamail	:= 93;
   		    sp_nombreorigen	:= sp_nombreorigen||' (PROCESO INTERNO)';
   		else
   			sp_codigonotf	:= 82;
   		    sp_nombreorigen	:= sp_nombreorigen||' (CONTROL INTERNO)';
   		end if;
   		
   	end if;

  	if (sp_idareaapp != 10) then
		sp_nombreorigen	:= sp_nombreorigen||' (CLIENTE INTERNO)';
		sp_nombreorigen := replace(sp_nombreorigen,'(PROCESO INTERNO)','');
		sp_nombreorigen := replace(sp_nombreorigen,'(CONTROL INTERNO)','');
	end if;
   

   	if (sp_idsuborigenncf = 2) then
   	        sp_nombremecanizadooperador	:= 'RENZO CUELLAR';
   	    	sp_responsable	:= 'RENZO CUELLAR';
   	    elsif (sp_idsuborigenncf = 1) then
   	        sp_nombremecanizadooperador	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
   	      	sp_responsable	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	    elsif (sp_idsuborigenncf = 1) then
   	        sp_nombremecanizadooperador	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
   	      	sp_responsable	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	    elsif (sp_idsuborigenncf = 3) then
   	        sp_nombremecanizadooperador	:= 'ROBERTO NAVALON - RENZO CUELLAR';
   	    	sp_responsable	:= 'IVÁN COLLANTE';
   	    elsif (sp_idsuborigenncf = 4) then
   	        sp_nombremecanizadooperador	:= 'ROBERTO NAVALON - ERIK IRRAZABAL';
   	    	sp_responsable	:= 'ROBERTO NAVALON - ERIK IRRAZABAL';
   	    	--sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	    elsif (sp_idsuborigenncf = 5) then
   	        sp_nombremecanizadooperador	:= 'IVÁN COLLANTE - RENZO CUELLAR';
   	      	sp_responsable	:= 'ROBERTO NAVALON';
   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	    elsif (sp_idsuborigenncf = 6) then
   	        sp_nombremecanizadooperador	:= 'IVÁN COLLANTE - ROBERTO NAVALON';
   	      	sp_responsable	:= 'ROBERTO NAVALON';
   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	   
   	end if;
   	
   
	sp_lista := '';
					   
	FOR rec_email IN (   
	    select distinct c.emaildestino 
		  from mct_listaemail b,
		       mct_email c
	     where b.idlista = sp_listamail
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;

--    if (sp_idsuborigenncf > 0) then
--    	sp_lista := 'squijada2703@gmail.com,scuadra@neplocal.cl,';
--    end if;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion = sp_codigonotf;
			      
     if (sp_idorigenncf = 2) then

	     sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));

	     sp_texto   := REPLACE(sp_texto,'_valor_comp',coalesce(sp_nombrecomp,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_material',coalesce(sp_nombremat,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_producto',coalesce(sp_nombrebomba,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_cliente',coalesce(sp_cliente,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_descripcion',coalesce(sp_observacion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_accion',coalesce(sp_nombreaccion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable,sp_evaluador));
	     sp_texto   := REPLACE(sp_texto,'_valor_operador',coalesce(sp_nombremecanizadooperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_suborigen',coalesce(sp_nombresuborigen,'N/A'));	    
		 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
	     sp_texto   := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
         sp_texto   := REPLACE(sp_texto,'_valor_anno',sp_anno_hoy::varchar);
		
		 sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
				 
		 asunto       :=  cast(sp_asunto as varchar);
		 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
		 if (sp_idsuborigenncf > 0) then
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||',ccifuentes@neplocal.cl, cibanez@neplocal.cl, jcatalan@neplocal.cl, karevalo@neplocal.cl';
		 else
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);	
		 end if;
		 codigonotf   :=  sp_codigonotf; 
					 
		 RETURN next;

     else 

	     sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_origen',coalesce(sp_nombreorigen,'N/A'));
	     
	     sp_texto   := REPLACE(sp_texto,'_valor_comp',coalesce(sp_nombrecomp,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_material',coalesce(sp_nombremat,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_producto',coalesce(sp_nombrebomba,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_descripcion',coalesce(sp_observacion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_accion',coalesce(sp_nombreaccion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable,sp_evaluador));
	     sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_operador',coalesce(sp_nombremecanizadooperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_suborigen',coalesce(sp_nombresuborigen,'N/A'));
	    
	     sp_texto   := REPLACE(sp_texto,'_valor_textofinal',coalesce(sp_textofinal,'N/A'));
		
		 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
		
		 sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
				 
		 asunto       :=  cast(sp_asunto as varchar);
		 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
		 if (sp_idsuborigenncf > 0) then
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||',ccifuentes@neplocal.cl, cibanez@neplocal.cl, jcatalan@neplocal.cl, karevalo@neplocal.cl';
		 else
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);	
		 end if;
		 codigonotf   :=  sp_codigonotf; 
					 
		 RETURN next;	      

     end if;
	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistgestionncf_tablet_cambioformato(idgestionncfs bigint, roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 1060 (class 1255 OID 17060)
-- Name: evtlistmaildistgestionncf_tablet_prueba(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistgestionncf_tablet_prueba(idgestionncfs bigint, roadmapcodes character varying) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

    sp_idusuario			integer;
    sp_nombreingeniero		varchar;
    sp_nombreproducto		varchar;
    sp_nombremodelo			varchar;
    sp_sigla				varchar;
    sp_nombrebomba			varchar;
   
    sp_ot                   integer;
    sp_nombrecomp			varchar;
    sp_nombremat			varchar;
    sp_nombress				varchar;
    sp_nombremaq			varchar;
   
	sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
    sp_anno_hoy             VARCHAR=to_char(now(),'YYYY');
    sp_lista                varchar;
   
    sp_texto                varchar;
    sp_asunto               varchar;
    sp_senor                varchar;
   
    sp_intext				integer;
   
    sp_corr					integer;
    sp_notif				integer;
   
    sp_textostring			varchar;
    sp_fundicionorigen		varchar;
    sp_detectadefecto		varchar;
    sp_cliente				varchar;
    sp_detecta				integer;
   
   	sp_idtipoorden			integer;
    sp_idfamilia			integer;
    sp_idproducto			integer;
    
    sp_prod					integer;
   
    sp_textoubicacion		varchar;
   
    sp_textostringfoto		varchar;
    sp_plano				varchar;
    sp_idgestionncf			bigint;
   
    sp_nombreoperador		varchar;
    sp_nombreorigen		    varchar;
    sp_nombreaccion		    varchar;
    sp_observacion		    varchar;
    sp_nombrearea		    varchar;
    sp_nombreseccion		varchar;
    sp_nombrecargo		    varchar;
    sp_nombreorigenotro		varchar;

    sp_idoperador		    bigint;
   
    sp_responsable					varchar;
    sp_nombremecanizadooperador		varchar;
    sp_idmecanizadooperador			bigint;
    sp_listamail					bigint;
   
    sp_origenresponsable			varchar;
    sp_evaluador					varchar;
    sp_idorigenncf					bigint;
    sp_idsuborigenncf				bigint;
    sp_nombresuborigen				varchar;
   
    sp_codigonotf					bigint;
    sp_idareaapp					bigint;
   
    sp_textofinal					varchar;

	rec_email      					RECORD;
    rec_trab       					RECORD;					           
         						    
begin

    sp_responsable		:= '';
    sp_textoubicacion	:= '';
    sp_fundicionorigen	:= '';
    sp_observacion		:= '';
    sp_detectadefecto	:= '';
    sp_cliente			:= '';
    sp_detecta			:= 0;
    sp_textostring		:= '';
    sp_idgestionncf		:= 0;
    sp_idorigenncf		:= 0;
    sp_idsuborigenncf	:= 0;
    sp_nombremecanizadooperador	:= '';
    sp_evaluador		:= '';
   
    sp_prod				:= 0;
   
    sp_textofinal		:= '';

    select --a.idgestionncf,
           a.idoperador,
           b.nombreoperador,
           --a.idorigenncf,
           c.nombreorigen,
           --a.idaccionncf,
           d.nombreaccion,
           a.observacion,
           --b.idareaapp,
           e.nombrearea,
           --b.idseccionapp,
           f.nombreseccion,
           --b.idcargoapp,
           g.nombrecargo,
           c.responsable,
           c.listamail,
           a.idmecanizadooperador,
           j.nombre ,
           a.idorigenncf,
           coalesce(a.idsuborigenncf, 0),
           k.nombresuborigen,
           b.idareaapp 
      into sp_idoperador,
           sp_nombreoperador,
           sp_nombreorigen,
           sp_nombreaccion,
           sp_observacion,
           sp_nombrearea,
           sp_nombreseccion,
           sp_nombrecargo,
           sp_responsable,
           sp_listamail,
           sp_idmecanizadooperador,
           sp_evaluador,
           sp_idorigenncf,
           sp_idsuborigenncf,
           sp_nombresuborigen,
           sp_idareaapp
      from mct_gestionncf a
      left join mct_operador b   	on b.idoperador = a.idoperador
      left join mct_origenncf c  	on c.idorigenncf = a.idorigenncf
      left join mct_accionncf d  	on d.idaccionncf = a.idaccionncf
      left join mct_area e       	on e.idarea = b.idareaapp
      left join mct_seccion f    	on f.idseccion = b.idseccionapp
      left join mct_cargo g      	on g.idcargo = b.idcargoapp
      left join mct_ordentrabajo h	on h.idordentrabajo = a.idordentrabajo
      left join mct_usuario j       on j.idusuario = h.idusuario
      left join mct_suborigenncf k	on k.idsuborigenncf = a.idsuborigenncf
     where a.idgestionncf = idgestionncfs;

   	select a.nombreoperador||' ('||b.sigla||')'
      into sp_nombremecanizadooperador
      from mct_operador a 
      left join mct_cargo b on a.idcargoapp = b.idcargo
     where a.idoperador = sp_idmecanizadooperador;
        
	select coalesce (b.idordentrabajo , 0),
	       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
	       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
	       --coalesce (d.nombre , 'SIN RESPONSABLE'),
	       coalesce (b.nombreplano  , 'SIN RESPONSABLE')
	  into sp_ot,
	       sp_nombrecomp,
	       sp_nombremat,
	       --sp_responsable,
	       sp_plano
	  from mct_detallehojarutatemp a
	  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
	  join mct_componente c   on b.idcomponente = c.idcomponente
	  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
	 where a.codhojaruta = roadmapcodes;
	  
    select idproducto
      into sp_prod
      from mct_ordentrabajo mo 
     where idordentrabajo = sp_ot;
      
   -- sp_nombremecanizadooperador	:= 'N/A';
    if ( sp_idorigenncf = 4 ) then
    
    	sp_nombremecanizadooperador	:= sp_evaluador;
    
    elsif ( sp_idorigenncf = 1 ) then
    
    	sp_nombremecanizadooperador	:= sp_nombremecanizadooperador;
    
    elsif ( sp_idorigenncf in (2,3,5,6,7) ) then
    
    	sp_nombremecanizadooperador	:= sp_responsable;
    
    end if;
   
   
    if ( sp_prod in (10,11,12,13,14,15,16,17)) then
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE P') ,
		       'SIN NOMBRE MO' ,
		       'SIN NOMBRE SIG' ,
		       coalesce (c.nombreproductonepcast  , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_productonepcast c on a.idproducto = c.idproductonepcast 
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    else
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') as producto,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    end if;
   
    if (sp_idsuborigenncf = 0) then
	    sp_corr := nextval('mct_gestionncfcorr_seq');
	
		--update mct_gestionncf
		--   set correlativo = sp_corr
		-- where idgestionncf = idgestionncfs;
		
		sp_nombresuborigen	:= 'NO APLICA';
	
    end if;
   
    --sp_codigonotf	:= 82;

    --sp_codigonotf	:= 86;
    --sp_codigonotf	:= 99;

    sp_codigonotf	:= 100;
    sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 96 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y ANÁLISIS DE DATA(MAGMA) PARA DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	if (sp_idorigenncf = 2) then

   		if (sp_idsuborigenncf > 0) then
   			--sp_codigonotf	:= 99;
            sp_codigonotf	:= 86;
   			sp_listamail	:= 93;
   		    --sp_nombreorigen	:= sp_nombreorigen||' (PROCESO INTERNO)';
            --sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
   		else
   			sp_codigonotf	:= 100;
   		    --sp_nombreorigen	:= sp_nombreorigen||' (CONTROL INTERNO)';
            --sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
   		end if;

    elsif (sp_idorigenncf = 9) then
		sp_codigonotf	:= 101;
    end if;

  	if (sp_idareaapp != 10) then
		--sp_nombreorigen	:= sp_nombreorigen||' (CLIENTE INTERNO)';
		--sp_nombreorigen := replace(sp_nombreorigen,'(PROCESO INTERNO)','');
		--sp_nombreorigen := replace(sp_nombreorigen,'(CONTROL INTERNO)','');
        --sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
	end if;

--   	if (sp_idsuborigenncf = 2) then
--   	        sp_nombremecanizadooperador	:= 'RENZO CUELLAR';
--   	    	--sp_responsable	:= 'RENZO CUELLAR';
--   	    elsif (sp_idsuborigenncf = 1) then
--   	        sp_nombremecanizadooperador	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
--   	      	--sp_responsable	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
--   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	    elsif (sp_idsuborigenncf = 1) then
--   	        sp_nombremecanizadooperador	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
--   	      	--sp_responsable	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
--   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	    elsif (sp_idsuborigenncf = 3) then
--   	        sp_nombremecanizadooperador	:= 'ROBERTO NAVALON - RENZO CUELLAR';
--   	    	--sp_responsable	:= 'IVÁN COLLANTE';
--   	    elsif (sp_idsuborigenncf = 4) then
--   	        sp_nombremecanizadooperador	:= 'ROBERTO NAVALON - ERIK IRRAZABAL';
--   	    	--sp_responsable	:= 'ROBERTO NAVALON - ERIK IRRAZABAL';
--   	    	--sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	    elsif (sp_idsuborigenncf = 5) then
--   	        sp_nombremecanizadooperador	:= 'IVÁN COLLANTE - RENZO CUELLAR';
--   	      	--sp_responsable	:= 'ROBERTO NAVALON';
--   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	    elsif (sp_idsuborigenncf = 6) then
--   	        sp_nombremecanizadooperador	:= 'IVÁN COLLANTE - ROBERTO NAVALON';
--   	      	--sp_responsable	:= 'ROBERTO NAVALON';
--   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
--   	   
--   	end if;
   	
   
	sp_lista := '';
					   
	FOR rec_email IN (   
	    select distinct c.emaildestino 
		  from mct_listaemail b,
		       mct_email c
	     where b.idlista = sp_listamail
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;

--    if (sp_idsuborigenncf > 0) then
--    	sp_lista := 'squijada2703@gmail.com,scuadra@neplocal.cl,';
--    end if;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion = sp_codigonotf;
			      
     if (sp_idorigenncf = 2) then

         if (sp_idoperador in (467,526) ) then

			--sp_nombreorigen := 'PL A FUNDICION 01';
            sp_nombreorigen := 'FUNDICION 01';
		 else
			sp_nombreorigen := 'FUNDICION 01';
         end if;

	     sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));

	     sp_texto   := REPLACE(sp_texto,'_valor_comp',coalesce(sp_nombrecomp,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_material',coalesce(sp_nombremat,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_producto',coalesce(sp_nombrebomba,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_cliente',coalesce(sp_cliente,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_descripcion',coalesce(sp_observacion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_accion',coalesce(sp_nombreaccion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable,sp_evaluador));
	     sp_texto   := REPLACE(sp_texto,'_valor_operador',coalesce(sp_nombremecanizadooperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_suborigen',coalesce(sp_nombresuborigen,'N/A'));	    
		 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
	     sp_texto   := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
         sp_texto   := REPLACE(sp_texto,'_valor_anno',sp_anno_hoy::varchar);
		
		 sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
				 
		 asunto       :=  cast(sp_asunto as varchar);
		 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
		 if (sp_idsuborigenncf > 0) then
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||',ccifuentes@neplocal.cl, cibanez@neplocal.cl, jcatalan@neplocal.cl, karevalo@neplocal.cl';
		 else
