			 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);		
					 
			 sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
	
