ALTER FUNCTION traking.evtlistmaildistgestionncf_tablet_prueba(idgestionncfs bigint, roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 1720 (class 1255 OID 17062)
-- Name: evtlistmaildistgestionncf_tablet_resp18022026(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistgestionncf_tablet_resp18022026(idgestionncfs bigint, roadmapcodes character varying) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

    sp_idusuario			integer;
    sp_nombreingeniero		varchar;
    sp_nombreproducto		varchar;
    sp_nombremodelo			varchar;
    sp_sigla				varchar;
    sp_nombrebomba			varchar;
   
    sp_ot                   integer;
    sp_nombrecomp			varchar;
    sp_nombremat			varchar;
    sp_nombress				varchar;
    sp_nombremaq			varchar;
   
	sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
    sp_anno_hoy             VARCHAR=to_char(now(),'YYYY');
    sp_lista                varchar;
   
    sp_texto                varchar;
    sp_asunto               varchar;
    sp_senor                varchar;
   
    sp_intext				integer;
   
    sp_corr					integer;
    sp_notif				integer;
   
    sp_textostring			varchar;
    sp_fundicionorigen		varchar;
    sp_detectadefecto		varchar;
    sp_cliente				varchar;
    sp_detecta				integer;
   
   	sp_idtipoorden			integer;
    sp_idfamilia			integer;
    sp_idproducto			integer;
    
    sp_prod					integer;
   
    sp_textoubicacion		varchar;
   
    sp_textostringfoto		varchar;
    sp_plano				varchar;
    sp_idgestionncf			bigint;
   
    sp_nombreoperador		varchar;
    sp_nombreorigen		    varchar;
    sp_nombreaccion		    varchar;
    sp_observacion		    varchar;
    sp_nombrearea		    varchar;
    sp_nombreseccion		varchar;
    sp_nombrecargo		    varchar;

    sp_idoperador		    bigint;
   
    sp_responsable					varchar;
    sp_nombremecanizadooperador		varchar;
    sp_idmecanizadooperador			bigint;
    sp_listamail					bigint;
   
    sp_origenresponsable			varchar;
    sp_evaluador					varchar;
    sp_idorigenncf					bigint;
    sp_idsuborigenncf				bigint;
    sp_nombresuborigen				varchar;
   
    sp_codigonotf					bigint;
    sp_idareaapp					bigint;
   
    sp_textofinal					varchar;

	rec_email      RECORD;
    rec_trab       RECORD;					           
         						    
begin

    sp_responsable		:= '';
    sp_textoubicacion	:= '';
    sp_fundicionorigen	:= '';
    sp_observacion		:= '';
    sp_detectadefecto	:= '';
    sp_cliente			:= '';
    sp_detecta			:= 0;
    sp_textostring		:= '';
    sp_idgestionncf		:= 0;
    sp_idorigenncf		:= 0;
    sp_idsuborigenncf	:= 0;
    sp_nombremecanizadooperador	:= '';
    sp_evaluador		:= '';
   
    sp_prod				:= 0;
   
    sp_textofinal		:= '';

    select --a.idgestionncf,
           a.idoperador,
           b.nombreoperador,
           --a.idorigenncf,
           c.nombreorigen,
           --a.idaccionncf,
           d.nombreaccion,
           a.observacion,
           --b.idareaapp,
           e.nombrearea,
           --b.idseccionapp,
           f.nombreseccion,
           --b.idcargoapp,
           g.nombrecargo,
           c.responsable,
           c.listamail,
           a.idmecanizadooperador,
           j.nombre ,
           a.idorigenncf,
           coalesce(a.idsuborigenncf, 0),
           k.nombresuborigen,
           b.idareaapp 
      into sp_idoperador,
           sp_nombreoperador,
           sp_nombreorigen,
           sp_nombreaccion,
           sp_observacion,
           sp_nombrearea,
           sp_nombreseccion,
           sp_nombrecargo,
           sp_responsable,
           sp_listamail,
           sp_idmecanizadooperador,
           sp_evaluador,
           sp_idorigenncf,
           sp_idsuborigenncf,
           sp_nombresuborigen,
           sp_idareaapp
      from mct_gestionncf a
      left join mct_operador b   	on b.idoperador = a.idoperador
      left join mct_origenncf c  	on c.idorigenncf = a.idorigenncf
      left join mct_accionncf d  	on d.idaccionncf = a.idaccionncf
      left join mct_area e       	on e.idarea = b.idareaapp
      left join mct_seccion f    	on f.idseccion = b.idseccionapp
      left join mct_cargo g      	on g.idcargo = b.idcargoapp
      left join mct_ordentrabajo h	on h.idordentrabajo = a.idordentrabajo
      left join mct_usuario j       on j.idusuario = h.idusuario
      left join mct_suborigenncf k	on k.idsuborigenncf = a.idsuborigenncf
     where a.idgestionncf = idgestionncfs;

   	select nombreoperador
      into sp_nombremecanizadooperador
      from mct_operador mo 
     where idoperador = sp_idmecanizadooperador;
        
	select coalesce (b.idordentrabajo , 0),
	       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
	       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
	       --coalesce (d.nombre , 'SIN RESPONSABLE'),
	       coalesce (b.nombreplano  , 'SIN RESPONSABLE')
	  into sp_ot,
	       sp_nombrecomp,
	       sp_nombremat,
	       --sp_responsable,
	       sp_plano
	  from mct_detallehojarutatemp a
	  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
	  join mct_componente c   on b.idcomponente = c.idcomponente
	  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
	 where a.codhojaruta = roadmapcodes;
	  
    select idproducto
      into sp_prod
      from mct_ordentrabajo mo 
     where idordentrabajo = sp_ot;
      
   -- sp_nombremecanizadooperador	:= 'N/A';
    if ( sp_idorigenncf = 4 ) then
    
    	sp_nombremecanizadooperador	:= sp_evaluador;
    
    elsif ( sp_idorigenncf = 1 ) then
    
    	sp_nombremecanizadooperador	:= sp_nombremecanizadooperador;
    
    elsif ( sp_idorigenncf in (2,3,5,6,7) ) then
    
    	sp_nombremecanizadooperador	:= sp_responsable;
    
    end if;
   
   
    if ( sp_prod in (10,11,12,13,14,15,16,17)) then
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE P') ,
		       'SIN NOMBRE MO' ,
		       'SIN NOMBRE SIG' ,
		       coalesce (c.nombreproductonepcast  , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_productonepcast c on a.idproducto = c.idproductonepcast 
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    else
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') as producto,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    end if;
   
    if (sp_idsuborigenncf = 0) then
	    sp_corr := nextval('mct_gestionncfcorr_seq');
	
		update mct_gestionncf
		   set correlativo = sp_corr
		 where idgestionncf = idgestionncfs;
		
		sp_nombresuborigen	:= 'NO APLICA';
	
    end if;
   
    sp_codigonotf	:= 82;
    --sp_codigonotf	:= 86;
    --sp_codigonotf	:= 99;
    sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 96 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y ANÁLISIS DE DATA(MAGMA) PARA DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	if (sp_idorigenncf = 2) then

   		if (sp_idsuborigenncf > 0) then
   			--sp_codigonotf	:= 99;
            sp_codigonotf	:= 86;
   			sp_listamail	:= 93;
   		    --sp_nombreorigen	:= sp_nombreorigen||' (PROCESO INTERNO)';
            sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
   		else
   			sp_codigonotf	:= 82;
   		    --sp_nombreorigen	:= sp_nombreorigen||' (CONTROL INTERNO)';
            sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
   		end if;
   		
   	end if;

  	if (sp_idareaapp != 10) then
		--sp_nombreorigen	:= sp_nombreorigen||' (CLIENTE INTERNO)';
		--sp_nombreorigen := replace(sp_nombreorigen,'(PROCESO INTERNO)','');
		--sp_nombreorigen := replace(sp_nombreorigen,'(CONTROL INTERNO)','');
        sp_nombreorigen	:= 'INTERNA - '||sp_nombreorigen;
	end if;


   	if (sp_idsuborigenncf = 2) then
   	        sp_nombremecanizadooperador	:= 'RENZO CUELLAR';
   	    	--sp_responsable	:= 'RENZO CUELLAR';
   	    elsif (sp_idsuborigenncf = 1) then
   	        sp_nombremecanizadooperador	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
   	      	--sp_responsable	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	    elsif (sp_idsuborigenncf = 1) then
   	        sp_nombremecanizadooperador	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
   	      	--sp_responsable	:= 'CRISTIAN CANAVIRI - RENZO CUELLAR';
   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	    elsif (sp_idsuborigenncf = 3) then
   	        sp_nombremecanizadooperador	:= 'ROBERTO NAVALON - RENZO CUELLAR';
   	    	--sp_responsable	:= 'IVÁN COLLANTE';
   	    elsif (sp_idsuborigenncf = 4) then
   	        sp_nombremecanizadooperador	:= 'ROBERTO NAVALON - ERIK IRRAZABAL';
   	    	--sp_responsable	:= 'ROBERTO NAVALON - ERIK IRRAZABAL';
   	    	--sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	    elsif (sp_idsuborigenncf = 5) then
   	        sp_nombremecanizadooperador	:= 'IVÁN COLLANTE - RENZO CUELLAR';
   	      	--sp_responsable	:= 'ROBERTO NAVALON';
   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	    elsif (sp_idsuborigenncf = 6) then
   	        sp_nombremecanizadooperador	:= 'IVÁN COLLANTE - ROBERTO NAVALON';
   	      	--sp_responsable	:= 'ROBERTO NAVALON';
   	    	sp_textofinal	:= 'A PARTIR DE ESTE MINUTO, UD TIENE 72 HORAS COMO MÁXIMO PARA REALIZAR UNA EFECTIVA ESTRATEGIA Y DETERMINAR LAS ACCIONES NECESARIAS PARA QUE LA PRESENTE NO CONFORMIDAD NO VUELVA A OCURRIR EN EL FUTURO';
   	   
   	end if;
   	
   
	sp_lista := '';
					   
	FOR rec_email IN (   
	    select distinct c.emaildestino 
		  from mct_listaemail b,
		       mct_email c
	     where b.idlista = sp_listamail
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;

--    if (sp_idsuborigenncf > 0) then
--    	sp_lista := 'squijada2703@gmail.com,scuadra@neplocal.cl,';
--    end if;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion = sp_codigonotf;
			      
     if (sp_idorigenncf = 2) then

         if (sp_idoperador in (467,526) ) then

			sp_nombreorigen := 'PL A FUNDICION 01';

         end if;

	     sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));

	     sp_texto   := REPLACE(sp_texto,'_valor_comp',coalesce(sp_nombrecomp,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_material',coalesce(sp_nombremat,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_producto',coalesce(sp_nombrebomba,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_cliente',coalesce(sp_cliente,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_descripcion',coalesce(sp_observacion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_accion',coalesce(sp_nombreaccion,'N/A'));
