	     sp_texto   := REPLACE(sp_texto,'_valor_operador',coalesce(sp_nombremecanizadooperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_suborigen',coalesce(sp_nombresuborigen,'N/A'));	    
		 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
	     sp_texto   := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
         sp_texto   := REPLACE(sp_texto,'_valor_anno',sp_anno_hoy::varchar);
		
		 sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
				 
		 asunto       :=  cast(sp_asunto as varchar);
		 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
		 if (sp_idsuborigenncf > 0) then
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||',ccifuentes@neplocal.cl, cibanez@neplocal.cl, jcatalan@neplocal.cl, karevalo@neplocal.cl';
		 else
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);	
		 end if;
		 codigonotf   :=  sp_codigonotf; 
					 
		 RETURN next;

     else 

	     sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_origen',coalesce(sp_nombreorigen,'N/A'));
	     
	     sp_texto   := REPLACE(sp_texto,'_valor_comp',coalesce(sp_nombrecomp,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_material',coalesce(sp_nombremat,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_producto',coalesce(sp_nombrebomba,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_descripcion',coalesce(sp_observacion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_accion',coalesce(sp_nombreaccion,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_responsable',coalesce(sp_responsable,sp_evaluador));
	     sp_texto   := REPLACE(sp_texto,'_valor_usuario',coalesce(sp_nombreoperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_operador',coalesce(sp_nombremecanizadooperador,'N/A'));
	     sp_texto   := REPLACE(sp_texto,'_valor_suborigen',coalesce(sp_nombresuborigen,'N/A'));
	    
	     sp_texto   := REPLACE(sp_texto,'_valor_textofinal',coalesce(sp_textofinal,'N/A'));
		
		 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
		
		 sp_asunto  := REPLACE(sp_asunto,'_valor_origen',coalesce(sp_nombreorigen::varchar,'N/A'));
				 
		 asunto       :=  cast(sp_asunto as varchar);
		 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
		 if (sp_idsuborigenncf > 0) then
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||',ccifuentes@neplocal.cl, cibanez@neplocal.cl, jcatalan@neplocal.cl, karevalo@neplocal.cl';
		 else
		    emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);	
		 end if;
		 codigonotf   :=  sp_codigonotf; 
					 
		 RETURN next;	      

     end if;
	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistgestionncf_tablet_resp18022026(idgestionncfs bigint, roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 2226 (class 1255 OID 17064)
-- Name: evtlistmaildistlistadosnack(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistlistadosnack(idnotif bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying, fechafile character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY');
	    sp_fechafile            VARCHAR=to_char(now(),'yyyy-mm-dd');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin


	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = idnotif
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo ,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion= idnotif;

			      
	 sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
	 sp_asunto  := REPLACE(sp_asunto,'_valor_fecha',sp_fecha_hoy);
			 
	 asunto       :=  sp_asunto;
	 cuerpo       :=  sp_texto; 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  idnotif; 
	 fechafile    :=  sp_fechafile;  
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistlistadosnack(idnotif bigint) OWNER TO postgres;

--
-- TOC entry 2220 (class 1255 OID 17065)
-- Name: evtlistmaildistot(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistot(idnotif bigint, idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, nombreordentrabajo character varying, nombrecliente character varying, nombreproducto character varying, fechaentrega character varying, fecharecepcion timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

		sp_idtipoorden    	      integer;
	    sp_nombretipoorden        varchar;
		sp_nombreordentrabajo 	  VARCHAR;
		sp_nombrecliente		  VARCHAR;
		sp_nombreproducto		  VARCHAR;
		sp_fechaentrega           varchar;
		sp_fecharecepcion         TIMESTAMP;

	    sp_idusuario              integer;
	    sp_planogeneral           varchar;
	    sp_nombreusuario          varchar;                
	    sp_fechacreacion          timestamp;
	    sp_idlineadiseno          integer;
	    sp_nomlineadiseno         varchar;	   
	    sp_idfamilia              integer;
	    sp_nomfamilia             varchar;
	       
		sp_fecha_hoy              VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                  varchar;
	   
	    sp_texto                  varchar;
	
		rec_email      RECORD;
        cur_email      CURSOR(sp_idnoti integer)
                    		  FOR select distinct c.emaildestino 
         						    from mct_notificacionlista a,
         						         mct_listaemail b,
         						         mct_email c
         						   where a.idnotificacion = idnotif
         					         and a.idlista = b.idlista
         						     and b.idemail = c.idemail ;
         						           
		
        sp_dias                integer;
       
        sp_valor_diseno        varchar;

       -- Para el calculo de la fecha de entrega
        intervalo    			varchar;
        sp_fecha_entrega     	varchar;
        indice       			integer;
        dias_totales			integer;
        dia_inicial  			integer;
       
       -- Para los KPi
		sp_inicio               varchar;
		sp_termino              varchar;
		sp_terminoreal          varchar;
		sp_demora               varchar;
		sp_diasplanificados     varchar;		
		sp_diasreales           varchar;
	    
	    sp_idsla                integer;
	   
	    sp_fechacotiza			timestamp;
	    sp_fechaautoriza		timestamp;
	   
	    sp_diasautoriza			integer;

        sp_email				varchar;

        sp_nombrebomba			varchar;

		sp_solped				varchar;
		sp_tag					varchar;
		sp_serieequipo			varchar;
        sp_idcliente			bigint;

		sp_filatxt				varchar;
   
         						    
begin
	sp_idsla := 0;
	
	if ( idnotif in (92) ) then 
	     sp_idsla := 10;
	elsif ( idnotif in (51, 88, 89) ) then 
	     sp_idsla := 10;
	elsif ( idnotif = 24 ) then 
	     sp_idsla := 6;
	elsif ( idnotif = 6 ) then 
		    sp_idsla := 7;
	elsif ( idnotif = 7 ) then 
		    sp_idsla := 8;
	elsif ( idnotif = 8 ) then 
		    sp_idsla := 9;
	elsif ( idnotif = 43 ) then 
		    sp_idsla := 2;
	elsif ( idnotif = 91 ) then 
		    sp_idsla := 3;
	else 
		    sp_idsla := idnotif;		   
    end if;
   
    
    ---- Esto es para el mail de autorizacion
    if (idnotif = 5) then
    
       sp_fechacotiza	:= null;
       sp_fechaautoriza	:= null;
      
       select fecha_real_termino
         into sp_fechacotiza
         from mct_progavisos
        where idordentrabajo = idot
          and idsla = 4;
      
       select fecha_autoriza_cliente
         into sp_fechaautoriza
         from mct_progavisos
        where idordentrabajo = idot
          and idsla = 5;
       
       sp_diasautoriza := date_part('day',sp_fechaautoriza - sp_fechacotiza);
        
    end if;
   

    select idfamilia,
           fechacreacion
      into sp_idfamilia,
           sp_fechacreacion
      from mct_ordentrabajo mo 
     where idordentrabajo = idot;
    

    if (sp_idfamilia = 11 and sp_fechacreacion > '2022-07-17') then
    
	    	select a.idtipoorden ,
		       a.nombreordentrabajo,  
		       b.nombrecliente, 
	  	       c.nombreproductonepcast , 
	 	       to_char(a.fechaentrega, 'dd-mm-yyyy'), 
		       a.fecharecepcion,
		       a.idusuario ,
		       'N/A' ,
		       d.nombre ,
		       a.fechacreacion ,
		       a.idlineadiseno ,
		       a.idfamilia ,
		       case
		          when a.idlineadiseno = 1 then 'DE DISEÑO'
		          when a.idlineadiseno = 2 then 'DE LÍNEA'
		          when a.idlineadiseno = 3 then 'COMERCIAL'
		       end,
		       e.nombrefamilia ,
		       f.nombretipoorden ,
               d.email, 
               coalesce(a.solped,'0'),
		       coalesce(a.tag,'S/T'),
		       coalesce(a.serieequipo, 'S/S'),
               a.idcliente
		  INTO sp_idtipoorden,
		       sp_nombreordentrabajo,
		       sp_nombrecliente,
		       sp_nombreproducto,
		       sp_fechaentrega,
		       sp_fecharecepcion,
		       sp_idusuario ,
		       sp_planogeneral ,
		       sp_nombreusuario ,
		       sp_fechacreacion ,
		       sp_idlineadiseno ,
		       sp_idfamilia ,
		       sp_nomlineadiseno,
		       sp_nomfamilia,
		       sp_nombretipoorden,
               sp_email, 
               sp_solped,
		       sp_tag,
		       sp_serieequipo,
               sp_idcliente
		  from mct_ordentrabajo a
		  LEFT JOIN mct_cliente  b    ON ( b.idcliente = a.idcliente)
		  LEFT JOIN mct_productonepcast c    ON ( c.idproductonepcast = a.idproducto)
		  left join mct_usuario d     on ( a.idusuario = d.idusuario )
		  left join mct_familia e     on ( a.idfamilia = e.idfamilia )
		  left join mct_tipoorden f   on ( a.idtipoorden = f.idtipoorden )	  
		  WHERE a.idordentrabajo= idot;
	 
    else

	    select a.idtipoorden ,
		       a.nombreordentrabajo,  
		       b.nombrecliente, 
	  	       c.nombreproducto, 
	 	       to_char(a.fechaentrega, 'dd-mm-yyyy'), 
		       a.fecharecepcion,
		       a.idusuario ,
		       c.planogeneral ,
		       d.nombre ,
		       a.fechacreacion ,
		       a.idlineadiseno ,
		       a.idfamilia ,
		       case
		          when a.idlineadiseno = 1 then 'DE DISEÑO'
		          when a.idlineadiseno = 2 then 'DE LÍNEA'
		          when a.idlineadiseno = 3 then 'COMERCIAL'
		       end,
		       e.nombrefamilia ,
		       f.nombretipoorden ,
               d.email, 
               coalesce(a.solped,'0'),
		       coalesce(a.tag,'S/T'),
		       coalesce(a.serieequipo, 'S/S'),
               a.idcliente
		  INTO sp_idtipoorden,
		       sp_nombreordentrabajo,
		       sp_nombrecliente,
		       sp_nombreproducto,
		       sp_fechaentrega,
		       sp_fecharecepcion,
		       sp_idusuario ,
		       sp_planogeneral ,
		       sp_nombreusuario ,
		       sp_fechacreacion ,
		       sp_idlineadiseno ,
		       sp_idfamilia ,
		       sp_nomlineadiseno,
		       sp_nomfamilia,
		       sp_nombretipoorden,
               sp_email, 
               sp_solped,
		       sp_tag,
		       sp_serieequipo,
               sp_idcliente
		  from mct_ordentrabajo a
		  LEFT JOIN mct_cliente  b    ON ( b.idcliente = a.idcliente)
		  LEFT JOIN mct_producto c    ON ( c.idproducto = a.idproducto)
		  left join mct_usuario d     on ( a.idusuario = d.idusuario )
		  left join mct_familia e     on ( a.idfamilia = e.idfamilia )
		  left join mct_tipoorden f   on ( a.idtipoorden = f.idtipoorden )	  
		  WHERE a.idordentrabajo = idot;
	 
    
    end if;

    if (sp_idfamilia in (8,10) ) then

		select e.sigla||' '||d.nombremodelo||' '||f.nombreparam
		  into sp_nombrebomba
		  from mct_ordentrabajo a
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
	  	 where a.idordentrabajo = idot;

    end if;

	  sp_fecha_entrega := '';
	  sp_inicio:= '';
	  sp_termino:= '';
	  sp_terminoreal:= '';
	  sp_demora:= '';
	  sp_diasplanificados:= '';       
	  sp_diasreales:= '';

	  if ( sp_idtipoorden in (1,3)) then
	 
		 	select to_char(fecha_termino, 'dd-mm-yyyy'),
		 	       to_char(fecha_inicio, 'dd-mm-yyyy') as inicio,
		 	       to_char(fecha_termino, 'dd-mm-yyyy') as termino,
		 	       to_char(fecha_real_termino, 'dd-mm-yyyy') as terminoreal,
		 	       date_part('day',fecha_real_termino - fecha_termino) as demora,
		 	       date_part('day',fecha_termino - fecha_inicio) as diasplanificados,
		 	       date_part('day',fecha_real_termino - fecha_inicio) as diasreales 	
		 	  into sp_fecha_entrega,
			       sp_inicio,
			       sp_termino,
			       sp_terminoreal,
			       sp_demora,
			       sp_diasplanificados,		       
			       sp_diasreales
			  from mct_progavisos 
			 where idsla = sp_idsla
			   and idordentrabajo = idot;
		  
	  else
	  
	  	  if ( idnotif = 2) then
	  	  
			 	select to_char(fecha_termino, 'dd-mm-yyyy'),
			 	       to_char(fecha_inicio, 'dd-mm-yyyy') as inicio,
			 	       to_char(fecha_termino, 'dd-mm-yyyy') as termino,
			 	       to_char(fecha_real_termino, 'dd-mm-yyyy') as terminoreal,
			 	       date_part('day',fecha_real_termino - fecha_termino) as demora,
			 	       date_part('day',fecha_termino - fecha_inicio) as diasplanificados,
			 	       date_part('day',fecha_real_termino - fecha_inicio) as diasreales	 	
			 	  into sp_fecha_entrega,
				       sp_inicio,
				       sp_termino,
				       sp_terminoreal,
				       sp_demora,
				       sp_diasplanificados,		       
				       sp_diasreales
			 	  from mct_progavisos 
				 where idsla = 6
				   and idordentrabajo = idot;
		  else

		  	select to_char(fecha_termino, 'dd-mm-yyyy'),
		 	       to_char(fecha_inicio, 'dd-mm-yyyy') as inicio,
		 	       to_char(fecha_termino, 'dd-mm-yyyy') as termino,
		 	       to_char(fecha_real_termino, 'dd-mm-yyyy') as terminoreal,
		 	       date_part('day',fecha_real_termino - fecha_termino) as demora,
		 	       date_part('day',fecha_termino - fecha_inicio) as diasplanificados,
		 	       date_part('day',fecha_real_termino - fecha_inicio) as diasreales 	
		 	  into sp_fecha_entrega,
			       sp_inicio,
			       sp_termino,
			       sp_terminoreal,
			       sp_demora,
			       sp_diasplanificados,		       
			       sp_diasreales
			  from mct_progavisos 
			 where idsla = sp_idsla
			   and idordentrabajo = idot;
			  
		  end if;
		  
	  end if;
	
	  sp_valor_diseno := '';
	 
	  -- Para Remanufactura de Bomba de DISEÑO
	  if ( sp_idtipoorden in (1,3) and sp_idfamilia in (8,15) and sp_idlineadiseno = 1  ) then
	     sp_valor_diseno := 'EQUIPO NUEVO - REQUIERE LEVANTAMIENTO DE COMPONENTES Y GENERACIÓN DE PLANOS';
	  end if;
	
	  -- Para Remanufactura de Repuesto LINEA
	  if ( sp_idtipoorden in (1,3) and sp_idfamilia in (10,11) and sp_idlineadiseno = 2  ) then
	     sp_nombreordentrabajo := sp_nombretipoorden||' de '||sp_nomfamilia||' - '||sp_nombreproducto||' , Nº Plano General '||sp_planogeneral;
	  end if;
	
	  -- Para Remanufactura de Repuesto DE DISEÑO
	  if ( sp_idtipoorden in (1,3) and sp_idfamilia in (10,11) and sp_idlineadiseno = 1  ) then
	  	 sp_valor_diseno := 'COMPONENTE DE EQUIPO NUEVO - REQUIERE LEVANTAMIENTO DE COMPONENTES Y GENERACIÓN DE PLANOS';
	     sp_nombreordentrabajo := sp_nombretipoorden||' de '||sp_nomfamilia||' - '||sp_nombreproducto;
	  end if;
	 
	 	  -- Para Remanufactura de Bomba de DISEÑO
	  if ( sp_idtipoorden = 2 and sp_idfamilia in (8,15) and sp_idlineadiseno = 1  ) then
	     sp_valor_diseno := 'EQUIPO NUEVO - REQUIERE LEVANTAMIENTO DE COMPONENTES Y GENERACIÓN DE PLANOS';
	  end if;
	
	  -- Para Remanufactura de Repuesto LINEA
	  if ( sp_idtipoorden = 2 and sp_idfamilia in (10,11) and sp_idlineadiseno = 2  ) then
	     sp_nombreordentrabajo := sp_nombretipoorden||' de '||sp_nomfamilia||' - '||sp_nombreproducto||' , Nº Plano General '||sp_planogeneral;
	  end if;
	
	  -- Para Remanufactura de Repuesto DE DISEÑO
	  if ( sp_idtipoorden = 2 and sp_idfamilia in (10,11) and sp_idlineadiseno = 1  ) then
	  	 sp_valor_diseno := 'COMPONENTE DE EQUIPO NUEVO - REQUIERE LEVANTAMIENTO DE COMPONENTES Y GENERACIÓN DE PLANOS';
	     sp_nombreordentrabajo := sp_nombretipoorden||' de '||sp_nomfamilia||' - '||sp_nombreproducto;
	  end if;
	 
	  sp_lista := '';
	   
      FOR rec_email IN (   
					select distinct c.emaildestino 
         			  from mct_notificacionlista a,
         				   mct_listaemail b,
         		           mct_email c
         		     where a.idnotificacion = idnotif
         	           and a.idlista = b.idlista
         		       and b.idemail = c.idemail 
					)
		loop 	
		
		     if ( sp_idfamilia = 11 ) then 
		     
		        if (rec_email.emaildestino not in ('ksoto@neptuno.cl','jperalta@neplocal.cl', 'rvernal@neplocal.cl', 'jcatalan@neplocal.cl') ) then 
		        
		             sp_lista := rec_email.emaildestino||','||sp_lista;
		        		       
		        end if;
		     
		     else 
		     
		        sp_lista := rec_email.emaildestino||','||sp_lista;
		     		    
		     end if;
		           
	  END LOOP;
             
	  if ( sp_idfamilia = 11 and sp_idlineadiseno = 3 ) then 

	      sp_lista := 'squijada@ndx.cl, squijada2703@gmail.com, hcarrera@neptuno.cl, administracion@neptuno.cl, compras@neptuno.cl';
	  
	  end if;
	     
      if (sp_idtipoorden in (1,3)) then
      
      	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_nombre',sp_nombreordentrabajo),'_valor_ot',idot::varchar),'_valor_cliente',sp_nombrecliente)::varchar 
		    into sp_texto
			from mct_notificacion a
		    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	       WHERE a.idnotificacion = idnotif;
	      
raise notice '%', sp_texto;


	      if ( idnotif = 2 ) then
		      select to_char(fecha_termino,'dd-mm-yyyy')
		        into sp_fecha_entrega
		        from mct_progavisos 
		       where idordentrabajo = idot
		         and idsla = 3;
	      end if;
	     
		  sp_texto := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreusuario);
		  sp_texto := REPLACE(sp_texto,'_fecha_entrega',sp_fecha_entrega);
		  sp_texto := REPLACE(sp_texto,'_valor_diseno',sp_valor_diseno);
	  else
	  
	  	  if ( idnotif = 2 ) then
		  	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
			  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_nombre',sp_nombreordentrabajo),'_valor_ot',idot::varchar),'_valor_cliente',sp_nombrecliente)::varchar 
			    into sp_texto
				from mct_notificacion a
			    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		       WHERE a.idnotificacion = 9;
	      else
	          if ( idnotif = 5 ) then
	          
	          	  -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
				  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_nombre',sp_nombreordentrabajo),'_valor_ot',idot::varchar),'_valor_cliente',sp_nombrecliente)::varchar 
				    into sp_texto
					from mct_notificacion a
				    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
			       WHERE a.idnotificacion = 5;
		      
	          else
	          
	             if ( idnotif = 51 ) then
	 
	             	  -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
					  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_nombre',sp_nombreordentrabajo),'_valor_ot',idot::varchar),'_valor_cliente',sp_nombrecliente)::varchar 
					    into sp_texto
						from mct_notificacion a
					    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
				       WHERE a.idnotificacion = 51;
			      
	             elsif ( idnotif = 92 ) then
	 
	             	  -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
					  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_nombre',sp_nombreordentrabajo),'_valor_ot',idot::varchar),'_valor_cliente',sp_nombrecliente)::varchar 
					    into sp_texto
						from mct_notificacion a
					    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
				       WHERE a.idnotificacion = 92;
			      
	             elsif ( idnotif = 88 ) then
	 
	             	  -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
					  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_nombre',sp_nombreordentrabajo),'_valor_ot',idot::varchar),'_valor_cliente',sp_nombrecliente)::varchar 
					    into sp_texto
						from mct_notificacion a
					    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
				       WHERE a.idnotificacion = 88;
			      
	             else
	             
			          -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
					  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_nombre',sp_nombreordentrabajo),'_valor_ot',idot::varchar),'_valor_cliente',sp_nombrecliente)::varchar 
					    into sp_texto
						from mct_notificacion a
					    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
				       WHERE a.idnotificacion = 43;
	             
	             end if;

		      
	          end if;

		      
	      end if;

		  sp_texto := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreusuario);
		  sp_texto := REPLACE(sp_texto,'_fecha_entrega_carpeta',sp_fecha_entrega);
		  sp_texto := REPLACE(sp_texto,'_fecha_entrega_cliente',sp_fechaentrega);		 
		  sp_texto := REPLACE(sp_texto,'_valor_diseno',sp_valor_diseno);	
		 
	  end if;
	 
raise notice '%', sp_diasreales;
raise notice '%', sp_demora;

	  if ( idnotif in (3, 4, 7, 8, 51, 88, 89, 91, 92 ) ) then
	      sp_texto := REPLACE(sp_texto,'_tiempo_dias',coalesce(sp_diasreales,'0'));	
	  	  sp_texto := REPLACE(sp_texto,'_dias_kpi',coalesce(sp_demora,'0'));
          
	  end if;
	 
	  if ( idnotif in (5 ) ) then
	      sp_texto := REPLACE(sp_texto,'_fecha_plano',sp_termino);	
	  	  sp_texto := REPLACE(sp_texto,'_dias_kpi',sp_demora);
	  	  sp_texto := REPLACE(sp_texto,'_valor_dias',coalesce(sp_diasautoriza,0)::varchar);
	  	 
	  end if;

	  if ( idnotif in (6, 24 ) ) then
	      sp_texto := REPLACE(sp_texto,'_fecha_cliente',sp_termino);
	  end if; 

	  if ( sp_idcliente in (49,50) ) then
		
		  sp_filatxt	:= 'Solped.                    :  '||sp_solped||E'\nTag.                          :  '||sp_tag||E'\nSerie Equipo.           :  '||sp_serieequipo||E'\n';

		  sp_texto := REPLACE(sp_texto,'_valorplaca',sp_filatxt::varchar);

	  else

		  sp_texto := REPLACE(sp_texto,'_valorplaca','');

      end if;
	 
	 
      RETURN QUERY
		
		  select --replace(REPLACE(b.asunto,'_valor_ot',idot::varchar)::varchar,'_valbomba',coalesce(sp_nombrebomba,'NA')::varchar) as asunto,
                 --REPLACE(b.asunto,'_valor_ot',idot::varchar)::varchar as asunto,   	
                 CAST(replace(REPLACE(b.asunto,'_valor_ot',idot::varchar)::varchar,'_valbomba',coalesce(sp_nombrebomba,'NA')::varchar) AS VARCHAR) as asunto,	
			     sp_texto,
			     cast(substring(sp_lista,1,length(sp_lista)-1)||','||sp_email as varchar),
			     sp_nombreordentrabajo,
			     sp_nombrecliente, 
			     sp_nombreproducto, 
			     sp_fechaentrega, 
			     sp_fecharecepcion
		    from mct_notificacion a
			JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		   WHERE a.idnotificacion= idnotif;
		

END;
$$;


