--
-- TOC entry 1683 (class 1255 OID 17067)
-- Name: evtlistmaildistot_rtm(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistot_rtm(hojaruta character varying) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

		sp_idordentrabajo       bigint;
		sp_idcliente            bigint;
  	    sp_nombrecorto          varchar;
  	    sp_idproducto           bigint;
  	    sp_idhojaruta           bigint;
  	    sp_idparte              bigint;
  	    sp_nombrecomponente     varchar;
  	    sp_idseccion            bigint;
  	    sp_idaccion             bigint;
  	    sp_nombreaccion         varchar;
  	    sp_idmaterial           bigint;
  	    sp_nombrematerial       varchar;
  	    
  	    sp_nombreproducto       varchar;
  	   
  	    sp_notif				bigint;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	   
	    sp_textolargo           varchar;
	
		rec_email               RECORD;
	    rec_trab                RECORD;					           
         						    
begin  	
  	
  	select a.idordentrabajo,
  	       c.idcliente,
  	       d.nombrecorto,
  	       c.idproducto,
  	       a.idhojaruta,
  	       a.idparte,
  	       e.nombrecomponente,
  	       a.idseccion,
  	       a.idaccion,
  	       f.nombreaccion,
  	       h.idmaterial,
  	       h.nombrematerial
  	  into sp_idordentrabajo,
		   sp_idcliente,
  	       sp_nombrecorto,
  	       sp_idproducto,
  	       sp_idhojaruta,
  	       sp_idparte,
  	       sp_nombrecomponente,
  	       sp_idseccion,
  	       sp_idaccion,
  	       sp_nombreaccion,
  	       sp_idmaterial,
  	       sp_nombrematerial
  	  from mct_movimientoordentrabajo a
  	  left join mct_ordentrabajo c on a.idordentrabajo = c.idordentrabajo
  	  left join mct_cliente d      on c.idcliente = d.idcliente
      left join mct_componente e   on a.idparte = e.idcomponente
      left join mct_accion f       on a.idaccion = f.idaccion
      left join mct_hojaruta g     on a.idhojaruta = g.idhojaruta
      left join mct_hojarutatemp h on g.idhojarutatemp = h.idhojarutatemp
      where a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo)
  	                                       from mct_movimientoordentrabajo b
  	                                      where b.codhojaruta = hojaruta);
	

	sp_nombreproducto	:= '';
    sp_textolargo		:= '';
    sp_notif			:= 0;
   
	if ( sp_idproducto in (10,11,12,13,14,15,16,17) ) then 
				 
		select nombreproductonepcast 
	      into sp_nombreproducto
	      from mct_productonepcast
		 where idproductonepcast = sp_idproducto;

	else
 
	     select c.sigla||' '||b.nombremodelo||' '||e.nombreparam
	       into sp_nombreproducto
	       from mct_producto a 
	       left join mct_modelo b     on a.idmodelo = b.idmodelo 
	       left join mct_subfamilia c on b.idsubfamilia = c.idsubfamilia  
	       left join mct_familia d    on c.idfamilia = d.idfamilia 
	       left join mct_etapaparam e on a.idetapaparam = e.idetapaparam 
	      where a.idproducto = sp_idproducto;
	    
	end if;

	sp_textolargo	:= sp_nombrecomponente||' - '||sp_nombrematerial||' - '||sp_nombrecorto;

    if ( sp_idaccion = 138) then
    	sp_notif	:= 69;
    elsif ( sp_idaccion = 139) then
    	sp_notif	:= 70;    
    end if;
   
    sp_lista := '';
	FOR rec_email IN (   
				select distinct c.emaildestino 
		          from mct_notificacionlista a,
		               mct_listaemail b,
				   	   mct_email c
		         where a.idnotificacion = sp_notif
		           and a.idlista = b.idlista
		           and b.idemail = c.idemail 
		  	)
		loop 	
						
			sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	    END LOOP;
		    
	 sp_asunto := '';
	 sp_texto  := '';
				 
				 
	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	 select REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valot',sp_idordentrabajo::varchar)::varchar ,
		    REPLACE(b.asunto,'_roadmapcode',hojaruta::varchar)
	   into sp_texto,
		    sp_asunto
	   from mct_notificacion a
	   JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
      WHERE a.idnotificacion = sp_notif;
			      
      sp_texto := REPLACE(sp_texto,'_valequipo',sp_textolargo);	
      sp_texto := REPLACE(sp_texto,'_accion',sp_nombreaccion);
    
	  asunto       :=  sp_asunto;
	  cuerpo       :=  sp_texto; 
	  emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	  codigonotf   :=  10; 
				 
	  RETURN next;	
		     
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistot_rtm(hojaruta character varying) OWNER TO postgres;

--
-- TOC entry 2055 (class 1255 OID 17068)
-- Name: evtlistmaildistotavancemecanizado100(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotavancemecanizado100() RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_ot                   integer;
	    sp_nombrecomp			varchar;
	    sp_nombremat			varchar;
	    sp_nombress				varchar;
	    sp_nombremaq			varchar;
	    sp_idtipoorden			integer;
	    sp_nombreordentrabajo	varchar;
	    sp_nombrecliente		varchar;
	    sp_idfamilia			integer;
	   
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	    sp_avance				numeric;
	   
	    sp_intext				integer;
	   
	    sp_corr					integer;
	    sp_notif				integer;
	   
	    sp_canthr				integer;
	    sp_liberadascc			integer;
	    sp_sumatotallcc         integer;
	
		rec_email      			RECORD;
	    rec_trab      			RECORD;	
	    rec_lcc					RECORD;
         						    
begin

	FOR rec_trab IN (   
				select a.idordentrabajo , a.idfamilia, a.idcliente, a.idusuario 
				  from mct_ordentrabajo a
			 	 where a.idordentrabajo >= 3000
				   and a.idestadoorden >=6 and a.idestadoorden < 9
				   and not exists (select 'x' 
				                     from mct_controlenviomail b 
					                where a.idordentrabajo = b.idordentrabajo 
					                  and b.envioavancemecanizado = true)
				)
		loop 	
				
			
				-- aca sacamos la cantidad de piezas totales
				select coalesce ( sum(cantidad), 0)
			      into sp_canthr
			      from mct_hojarutatemp mh
			     where idordentrabajo = rec_trab.idordentrabajo
			       and idboleano = 1
		           and idareaclasificacion in (0,1,2,3,4,5);
						     
			   			   -- desde aca el nuevo calculo
				sp_sumatotallcc  := 0;
				   			   
				FOR rec_lcc IN (   
							  select distinct b.idhojarutatemp
				   			    from mct_movimientoordentrabajo a,
							         mct_hojaruta b
							   where a.codigoaccion = 'L_CC'
								 and a.idordentrabajo = rec_trab.idordentrabajo
							     and a.idhojaruta = b.idhojaruta 
								)
					     loop 	
	
					     	sp_liberadascc	:= 0;
									   
					     	select coalesce (sum(cantidad),0)
			  			      into sp_liberadascc
						      from mct_hojarutatemp
							 where idhojarutatemp = rec_lcc.idhojarutatemp
						       and idboleano = 1
					           and idareaclasificacion in (0,1,2,3,4,5);
							     
							sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
							           
				END LOOP;
					  		
				sp_sumatotallcc := sp_sumatotallcc * 100;
						      
				if ( sp_canthr = 0) then
			         sp_avance := 0;
			    else
				    sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			    end if;

			    if ( sp_avance >= 100) then
			    
			  		select a.idtipoorden ,
				           a.nombreordentrabajo,  
				           b.nombrecliente, 
			  	           c.nombreproducto,
			  	           coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B'),
			  	           g.nombre ,
			  	           a.idfamilia 
					  INTO sp_idtipoorden,
					       sp_nombreordentrabajo,
					       sp_nombrecliente,
					       sp_nombreproducto,
					       sp_nombrebomba,
					       sp_nombreingeniero,
			  	           sp_idfamilia
					  from mct_ordentrabajo a
					  join mct_cliente b         on a.idcliente  = b.idcliente  
					  join mct_producto c        on a.idproducto = c.idproducto
					  join mct_modelo d          on c.idmodelo = d.idmodelo
					  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
					  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
					  join mct_usuario g         on g.idusuario = a.idusuario
				  	 where a.idordentrabajo = rec_trab.idordentrabajo;
			
				  	
					if (sp_idfamilia = 8) then
				
						sp_lista := '';
										   
						FOR rec_email IN (   
							select distinct c.emaildestino 
							  from mct_notificacionlista a,
							       mct_listaemail b,
							       mct_email c
						     where a.idnotificacion = 59
							   and a.idlista = b.idlista
							   and b.idemail = c.idemail 
								)
						    loop 	
											
							    sp_lista := rec_email.emaildestino||','||sp_lista;
											           
						END LOOP;
							    
						sp_asunto := '';
						sp_texto  := '';
									 
						-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
						select b.cuerpo,
							   b.asunto
						  into sp_texto,
							   sp_asunto
						  from mct_notificacion a
					      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
						 WHERE a.idnotificacion = 59;
								      
						 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
						 sp_texto   := REPLACE(sp_texto,'_valor_ot',rec_trab.idordentrabajo::varchar);
						 sp_texto   := REPLACE(sp_texto,'_valor_nombre',sp_nombreordentrabajo::varchar);
						 sp_texto   := REPLACE(sp_texto,'_valor_cliente',sp_nombrecliente::varchar);
						 sp_texto   := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero::varchar);
						
						 sp_asunto    :=  REPLACE(sp_asunto,'_valor_ot',rec_trab.idordentrabajo::varchar);
								 
						 asunto       :=  cast(sp_asunto as varchar);
						 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
						 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
					--	 codigonotf   :=  sp_notif; 
									 
						 insert into traking.mct_controlenviomail
						    values (nextval('traking.mct_controlenviomail_seq'), rec_trab.idordentrabajo, true, false);
						 RETURN next;	  	
					
					end if;					    
			    
			    end if;	
			
							           
	END LOOP;
	      
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotavancemecanizado100() OWNER TO postgres;

--
-- TOC entry 1715 (class 1255 OID 17070)
-- Name: evtlistmaildistotavancemecanizado100(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotavancemecanizado100(idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_ot                   integer;
	    sp_nombrecomp			varchar;
	    sp_nombremat			varchar;
	    sp_nombress				varchar;
	    sp_nombremaq			varchar;
	    sp_idtipoorden			integer;
	    sp_nombreordentrabajo	varchar;
	    sp_nombrecliente		varchar;
	    sp_idfamilia			integer;
	   
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	    sp_avance				integer;
	   
	    sp_intext				integer;
	   
	    sp_corr					integer;
	    sp_notif				integer;
	   
	    sp_canthr				integer;
	    sp_liberadascc			integer;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin

	FOR rec_trab IN (   
				select a.idordentrabajo , a.idfamilia, a.idcliente, a.idusuario 
				  from mct_ordentrabajo a
			 	 where a.idordentrabajo >= 3000
				   and a.idestadoorden >=6 and a.idestadoorden < 9
				   and not exists (select 'x' 
				                     from mct_controlenviomail b 
					                where a.idordentrabajo = b.idordentrabajo 
					                  and b.envioavancemecanizado = true)
				)
		loop 	
				
				-- aca sacamos la cantidad de piezas totales
				select coalesce ( sum(cantidad), 0)
			      into sp_canthr
			      from mct_hojarutatemp mh
			     where idordentrabajo = rec_trab.idordentrabajo
			       and idboleano = 1
		           and idareaclasificacion in (0,1,2,3,4,5);
						     
			    -- aca sacamos la cantidad de piezas liberadas de control de calidad
				select count(*)
			      into sp_liberadascc
			      from mct_movimientoordentrabajo
		         where codigoaccion = 'L_CC'
			       and idordentrabajo = rec_trab.idordentrabajo; 
						      
				if ( sp_canthr = 0) then
			         sp_avance := 0;
			    else
				    sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			    end if;

			    if ( sp_avance >= 100) then
			    
			  		select a.idtipoorden ,
				           a.nombreordentrabajo,  
				           b.nombrecliente, 
			  	           c.nombreproducto,
			  	           coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B'),
			  	           g.nombre ,
			  	           a.idfamilia 
					  INTO sp_idtipoorden,
					       sp_nombreordentrabajo,
					       sp_nombrecliente,
					       sp_nombreproducto,
					       sp_nombrebomba,
					       sp_nombreingeniero,
			  	           sp_idfamilia
					  from mct_ordentrabajo a
					  join mct_cliente b         on a.idcliente  = b.idcliente  
					  join mct_producto c        on a.idproducto = c.idproducto
					  join mct_modelo d          on c.idmodelo = d.idmodelo
					  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
					  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
					  join mct_usuario g         on g.idusuario = a.idusuario
				  	 where a.idordentrabajo = idot;
			
				  	
					if (sp_idfamilia = 8) then
				
						sp_lista := '';
										   
						FOR rec_email IN (   
							select distinct c.emaildestino 
							  from mct_notificacionlista a,
							       mct_listaemail b,
							       mct_email c
						     where a.idnotificacion = 59
							   and a.idlista = b.idlista
							   and b.idemail = c.idemail 
								)
						    loop 	
											
							    sp_lista := rec_email.emaildestino||','||sp_lista;
											           
						END LOOP;
							    
						sp_asunto := '';
						sp_texto  := '';
									 
						-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
						select b.cuerpo,
							   b.asunto
						  into sp_texto,
							   sp_asunto
						  from mct_notificacion a
					      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
						 WHERE a.idnotificacion = 59;
								      
						 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
						 sp_texto   := REPLACE(sp_texto,'_valor_ot',idot::varchar);
						 sp_texto   := REPLACE(sp_texto,'_valor_nombre',sp_nombreordentrabajo::varchar);
						 sp_texto   := REPLACE(sp_texto,'_valor_cliente',sp_nombrecliente::varchar);
						 sp_texto   := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero::varchar);
						
						 sp_asunto    :=  REPLACE(sp_asunto,'_valor_ot',idot::varchar);
								 
						 asunto       :=  cast(sp_asunto as varchar);
						 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
						 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
					--	 codigonotf   :=  sp_notif; 
									 
						 RETURN next;	  	
					
					end if;					    
			    
			    end if;	
			
							           
	END LOOP;
	      
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotavancemecanizado100(idot bigint) OWNER TO postgres;

