--
-- TOC entry 1013 (class 1255 OID 17078)
-- Name: evtlistmaildistotavisofechacompraanterior(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotavisofechacompraanterior() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
        sp_anno_hoy            	VARCHAR=to_char(now(),'YYYY');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_salida				integer;
        sp_avance				numeric;

	    -- Variable para compras
	    sp_cantidad_co         integer; 
		sp_codigoqr_co         varchar;  
		sp_fecharequerida_co   timestamp;
	    sp_recept_co           integer;
	    sp_maxfecha_co         timestamp;   
	    sp_dias_atraso_co      integer;  
	    sp_avance_co           numeric;
	    sp_atraso_co           integer;   
	    sp_color_co            integer;
	    sp_dias_co             integer;
         						    
begin
	
	  sp_salida := 0;
	 
      FOR rec_trab IN (   
                    select a.idordentrabajo,
                           b.nombre,
                           b.email,
                           d.nombrecliente,
                           d.nombrecorto,
                           a.idproducto,
                           g.sigla||' '||f.nombreneptuno||' '||h.nombreparam as bomba,
                           to_char(a.fechachecklistvalido, 'dd-mm-yyyy') as fechavalidacheck,
                           CURRENT_DATE - a.fechachecklistvalido::date as diaschek
                      from mct_ordentrabajo a,
                           mct_usuario b,
                           mct_cliente d,                           
                           mct_producto e,
                           mct_modelo f,
                           mct_subfamilia g,
                           mct_etapaparam h
                     where a.fechafacetm = current_date - interval '1 day'
                       and a.idcliente = d.idcliente 
                       and a.idproducto = e.idproducto
                       and e.idmodelo = f.idmodelo
                       and f.idsubfamilia = g.idsubfamilia 
                       and e.idetapaparam = h.idetapaparam 
                       and a.idestadoorden  >= 6 and a.idestadoorden < 9
                       and a.flagfacturacion is true
                       and a.debaja < 1
                       and a.idusuario = b.idusuario
                       and a.idfamilia = 8
                       and a.idtipoorden in (1,2)
					)
				
		loop 	

			   -- Compras
			   -- aca sacamos las piezas totales solicitadas a compras  
			   select coalesce ( sum(cantidad), 0),
			          codigoqr, 
			          fecharequerida
			     into sp_cantidad_co,
			          sp_codigoqr_co,
			          sp_fecharequerida_co				          
			     from mct_checklistinftecvalido mc 
			    where tipotrabajostd = 'RPO'
			      and idordentrabajo = rec_trab.idordentrabajo
                  and noaplicasolicitud is false
			    group by codigoqr, fecharequerida;
			   
			   -- aca sacamos el total de piezas recepcionadas   
			   select coalesce ( sum(cantidad), 0),
			          max(fechacreacion)
			     into sp_recept_co,
			          sp_maxfecha_co	 			   
			     from mct_checklistinftecrecept
			    where codigoqr = sp_codigoqr_co;			    			   
			   
			    sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);		

				if (sp_avance_co < 100) then

			      	sp_lista := '';
					   
				  	FOR rec_email IN (   
									select distinct c.emaildestino 
				         			  from mct_notificacionlista a,
				         				   mct_listaemail b,
				         		           mct_email c
				         		     where a.idnotificacion = 105
				         	           and a.idlista = b.idlista
				         		       and b.idemail = c.idemail 
									)
				     		loop 	
						
						 sp_lista := rec_email.emaildestino||','||sp_lista;
						           
				  	END LOOP;
		    
				  	sp_asunto := '';
				  	sp_texto  := '';
	
		          	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
				  	select b.cuerpo,	
				           b.asunto
				      into sp_texto,
				           sp_asunto
					  from mct_notificacion a
				      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
			         WHERE a.idnotificacion = 105;
			      
			      	sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
			      	sp_texto  := REPLACE(sp_texto,'_valor_ot',rec_trab.idordentrabajo::varchar);
			      	sp_texto  := REPLACE(sp_texto,'_valor_bba',rec_trab.bomba::varchar);
	                sp_texto  := REPLACE(sp_texto,'_valor_cliente',rec_trab.nombrecliente::varchar);
	                sp_texto  := REPLACE(sp_texto,'_valor_porcentaje',sp_avance_co::varchar);
                    sp_texto  := REPLACE(sp_texto,'_valor_checklistfecha',rec_trab.fechavalidacheck::varchar);
                    sp_texto  := REPLACE(sp_texto,'_valor_diasfechachecklist',rec_trab.diaschek::varchar);
			      	sp_texto  := REPLACE(sp_texto,'_val_anno',sp_anno_hoy);
			     
			      	sp_asunto  := REPLACE(sp_asunto,'_valor_ot',rec_trab.idordentrabajo::varchar);
	                sp_asunto  := REPLACE(sp_asunto,'_valor_bba',rec_trab.bomba::varchar);
			 
				  	orden        :=  rec_trab.idordentrabajo;
				  	asunto       :=  sp_asunto;
				  	cuerpo       :=  sp_texto; 
				  	emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1)||','||rec_trab.email as varchar);
				  	codigonotf   :=  0; 
	
			      	RETURN next;	

				end if;

			  
	  END LOOP;
             
END;
$$;


