			if (sp_avance < 100) then

		      	sp_lista := '';
				   
			  	FOR rec_email IN (   
								select distinct c.emaildestino 
			         			  from mct_notificacionlista a,
			         				   mct_listaemail b,
			         		           mct_email c
			         		     where a.idnotificacion = 102
			         	           and a.idlista = b.idlista
			         		       and b.idemail = c.idemail 
								)
			     		loop 	
					
					 sp_lista := rec_email.emaildestino||','||sp_lista;
					           
			  	END LOOP;
	    
			  	sp_asunto := '';
			  	sp_texto  := '';

	          	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
			  	select b.cuerpo,	
			           b.asunto
			      into sp_texto,
			           sp_asunto
				  from mct_notificacion a
			      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		         WHERE a.idnotificacion = 102;
		      
		      	sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
		      	sp_texto  := REPLACE(sp_texto,'_valor_ot',rec_trab.idordentrabajo::varchar);
		      	sp_texto  := REPLACE(sp_texto,'_valor_bba',rec_trab.bomba::varchar);
		      	sp_texto  := REPLACE(sp_texto,'_val_anno',sp_anno_hoy);
		     
		      	sp_asunto  := REPLACE(sp_asunto,'_valor_ot',rec_trab.idordentrabajo::varchar);
                sp_asunto  := REPLACE(sp_asunto,'_valor_bba',rec_trab.bomba::varchar);
		 
			  	orden        :=  rec_trab.idordentrabajo;
			  	asunto       :=  sp_asunto;
			  	cuerpo       :=  sp_texto; 
			  	emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1)||','||rec_trab.email as varchar);
			  	codigonotf   :=  0; 

		      	RETURN next;	

				--update traking.mct_ordentrabajo
                --   set fechafacetmaviso = fechafacetm
                -- where a.idordentrabajo = rec_trab.idordentrabajo;

			end if; 
			  
	  END LOOP;
             
END;
$$;


