--
-- TOC entry 2384 (class 1255 OID 17082)
-- Name: evtlistmaildistotchecklist(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotchecklist(idot bigint, idnotif bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin

	select a.idusuario ,
	       b.nombre ,
	       c.nombreproducto ,
	       d.nombremodelo ,
	       e.sigla ,
	       e.sigla||' '||d.nombremodelo||' '||f.nombreparam 
	  into sp_idusuario ,
	       sp_nombreingeniero,
	       sp_nombreproducto,
	       sp_nombremodelo,
	       sp_sigla,
	       sp_nombrebomba
	  from mct_ordentrabajo a
	  join mct_usuario b         on a.idusuario = b.idusuario 
	  join mct_producto c        on a.idproducto = c.idproducto
	  join mct_modelo d          on c.idmodelo = d.idmodelo
	  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
	  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
  	 where a.idordentrabajo = idot;
	

	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = idnotif
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_val_fecha',sp_fecha_hoy),'_valor_responsable',sp_nombreingeniero),'_valor_ot',idot::varchar),'_valor_modelo',sp_nombrebomba)::varchar ,
		   REPLACE(REPLACE(b.asunto,'_valor_ot',idot::varchar),'_valor_modelo',sp_nombrebomba)
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion= idnotif;
			      
	-- sp_texto  := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero);
	 sp_asunto  := REPLACE(sp_asunto,'_valor_modelo',sp_nombrebomba);
			 
	 asunto       :=  sp_asunto;
	 cuerpo       :=  sp_texto; 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  idnotif; 
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotchecklist(idot bigint, idnotif bigint) OWNER TO postgres;

