		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin

	--sp_urgente	    	:= 0;
    sp_responsable		:= '';
    sp_textoubicacion	:= '';
    sp_fundicionorigen	:= '';
    sp_observacion		:= '';
    sp_detectadefecto	:= '';
    sp_cliente			:= '';
    sp_detecta			:= 0;
    sp_textostring		:= '';
    sp_iddefecto		:= 0;
   
    sp_prod				:= 0;

	select coalesce (b.idordentrabajo , 0),
	       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
	       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
	       coalesce (d.nombre , 'SIN RESPONSABLE')
	  into sp_ot,
	       sp_nombrecomp,
	       sp_nombremat,
	       sp_responsable
	  from mct_detallehojarutatemp a
	  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
	  join mct_componente c   on b.idcomponente = c.idcomponente
	  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
	 where a.codhojaruta = roadmapcodes;
	  
    select idproducto
      into sp_prod
      from mct_ordentrabajo mo 
     where idordentrabajo = sp_ot;
    
	select coalesce (b.nombresubseccion , 'SIN AREA') ,
	       coalesce (c.nombremaquina , 'SIN MAQ'),
	       a.iddefectofundicionorigen,
	       e.nombre ,
	       case 
		       when a.urgente is true then
		           1
		       else
		           0
		   end,
	       d.nombredetectadefecto ,
	       coalesce (a.observacion , 'SIN OBS'),
	       a.iddetectadefecto ,
	       a.nombreplano ,
	       a.iddefectofundicion 
	  into sp_nombress,
	       sp_nombremaq,
	       sp_intext,
	       sp_fundicionorigen,
	       sp_urgente,
	       sp_detectadefecto,
	       sp_observacion,
	       sp_detecta,
	       sp_plano,
	       sp_iddefecto
	  from mct_defectofundicion a
	  left join mct_subseccion b on a.idsubseccion = b.idsubseccion
	  left join mct_maquina c on a.idmaquina = c.idmaquina
	  left join mct_detectadefecto d on a.iddetectadefecto = d.iddetectadefecto
	  left join mct_defectofundicionorigen e on a.iddefectofundicionorigen = e.iddefectofundicionorigen 
	 where codhojaruta = roadmapcodes 
       and a.iddefectofundicion = (select max(iddefectofundicion) from mct_defectofundicion md );

    if (sp_detecta = 1) then
        sp_textoubicacion	:= sp_nombress||'-'||sp_nombremaq;
    elsif (sp_detecta in (5,6)) then
        sp_textoubicacion	:= sp_detectadefecto;
    end if;
  

    if ( sp_prod in (10,11,12,13,14,15,16,17)) then
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE P') ,
		       'SIN NOMBRE MO' ,
		       'SIN NOMBRE SIG' ,
		       coalesce (c.nombreproductonepcast  , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_productonepcast c on a.idproducto = c.idproductonepcast 
		  --join mct_modelo d          on c.idmodelo = d.idmodelo
		  --join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  --left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    else
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproducto , 'SIN NOMBRE P') ,
		       coalesce (d.nombremodelo , 'SIN NOMBRE MO') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    end if;


	if ( sp_intext = 2 ) then
	      sp_corr 		:= nextval('mct_defectoscorr_seq');
	      --sp_corr 	:= 999;
	      if ( sp_urgente = 1 ) then
	          sp_notif	:= 66;
	      else
	          sp_notif	:= 55;
	      end if;
	      
	 else 
	      sp_corr 		:= nextval('mct_defectoscorrext_seq');
	      --sp_corr 	:= 999;
	      if ( sp_urgente = 1 ) then
	          sp_notif	:= 65;
	      else
	          sp_notif	:= 56;
	      end if;
	 end if;
	
	update mct_defectofundicion
	   set correlativo = sp_corr
	 where iddefectofundicion = sp_iddefecto;
	 
	if (sp_idfamilia = 11) then
	
	   if (sp_idproducto in (10,11,12,13,14,15,16,17) ) then
	   
	      select nombreproductonepcast 
	        into sp_nombrecomp
	        from mct_productonepcast a
	       where a.idproductonepcast = sp_idproducto;
	       
	   end if;
	  
	    sp_textostring 		:= sp_fundicionorigen||'-OT '||sp_ot||'-'||sp_nombrecomp||'-'||sp_nombremat||'-'||sp_cliente;
	    
	    sp_textostringfoto 	:= sp_corr||'-OT '||sp_ot||'-'||sp_nombrecomp||'-'||sp_nombremat||'-Plano '||sp_plano;
	else
	
		sp_textostring 		:= sp_fundicionorigen||'-OT '||sp_ot||'-'||sp_nombrebomba||'-'||sp_nombrecomp||'-'||sp_nombremat||'-'||sp_cliente;
	
	    sp_textostringfoto 	:= sp_corr||'-OT '||sp_ot||'-'||sp_nombrecomp||'-'||sp_nombremat||'-Plano '||sp_plano;
	
	end if;	

    update mct_defectofundicionadjunto
       set nombrearchivo = sp_textostringfoto||'-'||correlativo
     where iddefectofundicion = sp_iddefecto;
    
    --sp_textostring := sp_fundicionorigen||'-OT '||sp_ot||'-'||sp_nombrebomba||'-'||sp_nombrecomp||'-'||sp_nombremat||'-'||sp_cliente;
   
	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = sp_notif
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion = sp_notif;
			      
     sp_texto   := REPLACE(sp_texto,'_val_ingeniero',sp_responsable);
     sp_texto   := REPLACE(sp_texto,'_val_ubicacion',sp_textoubicacion);
     sp_texto   := REPLACE(sp_texto,'_val_area',sp_detectadefecto);
     sp_texto   := REPLACE(sp_texto,'_val_componente',sp_textostring);
     sp_texto   := REPLACE(sp_texto,'_val_observacion',sp_observacion);
	
	 sp_texto   := REPLACE(sp_texto,'_val_fecha',sp_fecha_hoy);
	
	
--	 sp_texto   := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_componente',sp_nombrecomp::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_material',sp_nombremat::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_seccion',sp_nombress::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_maquina',sp_nombremaq::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_producto',sp_nombreproducto::varchar);
	

	 --sp_asunto  := REPLACE(sp_asunto,'_val_correlativo',nextval('mct_defectoscorr_seq')::varchar);
	 sp_asunto  := REPLACE(sp_asunto,'_val_correlativo',sp_corr::varchar);
			 
	 asunto       :=  cast(sp_asunto as varchar);
	 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  sp_notif; 
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotdefecto(roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 1173 (class 1255 OID 17085)
-- Name: evtlistmaildistotdefectoanalisispdf(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotdefectoanalisispdf(iddefectofundicions bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf bigint)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    size 						integer := 0;
	    arreglo text[] 				:= array[]::text[];
	    arregloString  				varchar(2000);
	   
		sp_fecha_hoy            	VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                	varchar;
	   
	    sp_texto                	varchar;
	    sp_asunto              	 	varchar;
	    sp_senor                	varchar;
	
		rec_email      				RECORD;
	    rec_trab       				RECORD;	

		sp_iddefectofundicion		bigint;
		sp_correlativo				bigint;
		sp_codhojaruta				varchar;
	
	    sp_ot						bigint;
		sp_nombrecomp				varchar;
		sp_nombremat				varchar;
		sp_responsable				varchar;
	            						    
begin

		sp_iddefectofundicion	:= 0;
		sp_correlativo			:= 0;
		sp_codhojaruta			:= '';   
	    
        select a.iddefectofundicion  ,
               a.correlativo,
               a.codhojaruta
          into sp_iddefectofundicion,
               sp_correlativo,
               sp_codhojaruta
          from mct_defectofundicion a
         where a.iddefectofundicion = iddefectofundicions;

		select coalesce (b.idordentrabajo , 0),
		       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
		       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
		       coalesce (d.nombre , 'SIN RESPONSABLE')
		  into sp_ot,
		       sp_nombrecomp,
		       sp_nombremat,
		       sp_responsable
		  from mct_detallehojarutatemp a
		  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
		  join mct_componente c   on b.idcomponente = c.idcomponente
		  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
		 where a.codhojaruta = sp_codhojaruta;
				
		sp_lista := '';
							   
		FOR rec_email IN (   
			select distinct c.emaildestino 
			  from mct_notificacionlista a,
				   mct_listaemail b,
			       mct_email c
		     where a.idnotificacion = 73
		       and a.idlista = b.idlista
			   and b.idemail = c.idemail 
				)
		    loop 	
								
			    sp_lista := rec_email.emaildestino||','||sp_lista;
								           
		END LOOP;
				    
		sp_asunto := '';
		sp_texto  := '';
						 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		select b.cuerpo,
			   b.asunto
		  into sp_texto,
		       sp_asunto
		  from mct_notificacion a
	      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		 WHERE a.idnotificacion = 73;
					      
		 sp_texto  := REPLACE(sp_texto,'_val_ingeniero',sp_responsable);
		 sp_texto  := REPLACE(sp_texto,'_val_componente',sp_nombrecomp);
		 sp_texto  := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
	     sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);

		 sp_asunto := REPLACE(sp_asunto,'_val_def',sp_correlativo::varchar);
				 
		 asunto       :=  sp_asunto;
		 cuerpo       :=  sp_texto; 
		 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
		 codigonotf   :=  0; 
						 
		 RETURN next;	  	
		
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotdefectoanalisispdf(iddefectofundicions bigint) OWNER TO postgres;

--
-- TOC entry 1604 (class 1255 OID 17086)
-- Name: evtlistmaildistotdefectocargarespaldo(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotdefectocargarespaldo(iddefectocausaaccionpdfs bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf bigint)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    size 						integer := 0;
	    arreglo text[] 				:= array[]::text[];
	    arregloString  				varchar(2000);
	   
		sp_fecha_hoy            	VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                	varchar;
	   
	    sp_texto                	varchar;
	    sp_asunto              	 	varchar;
	    sp_senor                	varchar;
	
		rec_email      				RECORD;
	    rec_trab       				RECORD;	

		sp_iddefectocausaaccionpdf	bigint;
		sp_iddefectocausaaccion		bigint;
		sp_correlativo				bigint;
		sp_codhojaruta				varchar;
		sp_descripcion				varchar;
		sp_nombrerespaldo			varchar;
	
	    sp_ot						bigint;
		sp_nombrecomp				varchar;
		sp_nombremat				varchar;
		sp_responsable				varchar;
	            						    
begin

		sp_iddefectocausaaccionpdf	:= 0;
		sp_iddefectocausaaccion		:= 0;
		sp_correlativo				:= 0;
		sp_codhojaruta				:= '';
		sp_descripcion				:= '';
		sp_nombrerespaldo			:= '';
   
	    
        select b.iddefectocausaaccionpdf  ,
               b.iddefectocausaaccion  ,
               e.correlativo,
               e.codhojaruta,
               c.descripcion,
               b.nombrerespaldo
          into sp_iddefectocausaaccionpdf,
               sp_iddefectocausaaccion,
               sp_correlativo,
               sp_codhojaruta,
               sp_descripcion,
               sp_nombrerespaldo
          from mct_defectocausaaccionpdf b,
               mct_defectocausaaccion c,
               mct_defectocausa d,
               mct_defectofundicion e
         where b.iddefectocausaaccionpdf = iddefectocausaaccionpdfs
           and b.iddefectocausaaccion = c.iddefectocausaaccion 
           and c.iddefectocausa = d.iddefectocausa 
           and d.iddefectofundicion = e.iddefectofundicion ;

		select coalesce (b.idordentrabajo , 0),
		       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
		       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
		       coalesce (d.nombre , 'SIN RESPONSABLE')
		  into sp_ot,
		       sp_nombrecomp,
		       sp_nombremat,
		       sp_responsable
		  from mct_detallehojarutatemp a
		  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
		  join mct_componente c   on b.idcomponente = c.idcomponente
		  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
		 where a.codhojaruta = sp_codhojaruta;
				
		sp_lista := '';
							   
		FOR rec_email IN (   
			select distinct c.emaildestino 
			  from mct_notificacionlista a,
				   mct_listaemail b,
			       mct_email c
		     where a.idnotificacion = 75
		       and a.idlista = b.idlista
			   and b.idemail = c.idemail 
				)
		    loop 	
								
			    sp_lista := rec_email.emaildestino||','||sp_lista;
								           
		END LOOP;
				    
		sp_asunto := '';
		sp_texto  := '';
						 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		select b.cuerpo,
			   b.asunto
		  into sp_texto,
		       sp_asunto
		  from mct_notificacion a
	      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		 WHERE a.idnotificacion = 75;
					      
		 sp_texto  := REPLACE(sp_texto,'_val_accion',sp_descripcion);
		 sp_texto  := REPLACE(sp_texto,'_val_respaldo',sp_nombrerespaldo);
		 sp_texto  := REPLACE(sp_texto,'_val_componente',sp_nombrecomp);
		 sp_texto  := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
	     sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);

		 sp_asunto := REPLACE(sp_asunto,'_val_def',sp_correlativo::varchar);
				 
		 asunto       :=  sp_asunto;
		 cuerpo       :=  sp_texto; 
		 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
		 codigonotf   :=  0; 
						 
		 RETURN next;	  	
		
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotdefectocargarespaldo(iddefectocausaaccionpdfs bigint) OWNER TO postgres;

--
-- TOC entry 987 (class 1255 OID 17087)
-- Name: evtlistmaildistotdefectocargarespaldovalidate(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotdefectocargarespaldovalidate() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_salida				integer;
	   
	    sp_ot					bigint;
		sp_nombrecomp			varchar;
		sp_nombremat			varchar;
		sp_responsable			varchar;
         						    
begin
	
	  sp_salida := 0;
	
      FOR rec_trab IN (   
                    select a.idauditoriadefectocargarespaldo  ,
                           a.iddefectocausaaccionpdf  ,
                           a.estado,
                           a.contador,
                           a.fechacreacion,
                           a.fechaejecucion ,
                           e.correlativo,
                           e.codhojaruta,
                           c.descripcion,
                           b.nombrerespaldo
                      from mct_auditoriadefectocargarespaldo a,
                           mct_defectocausaaccionpdf b,
                           mct_defectocausaaccion c,
                           mct_defectocausa d,
                           mct_defectofundicion e
                     where a.estado = 1
                       and a.iddefectocausaaccionpdf = b.iddefectocausaaccionpdf 
                       and b.iddefectocausaaccion = c.iddefectocausaaccion 
                       and c.iddefectocausa = d.iddefectocausa 
                       and d.iddefectofundicion = e.iddefectofundicion 
                       and current_date > c.fechaejecucion
					)
				
					
		loop 	
			     			
				select coalesce (b.idordentrabajo , 0),
				       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
				       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
				       coalesce (d.nombre , 'SIN RESPONSABLE')
				  into sp_ot,
				       sp_nombrecomp,
				       sp_nombremat,
				       sp_responsable
				  from mct_detallehojarutatemp a
				  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
				  join mct_componente c   on b.idcomponente = c.idcomponente
				  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
				 where a.codhojaruta = rec_trab.codhojaruta;
	
			sp_lista := '';
						   
			FOR rec_email IN (   
						select distinct c.emaildestino 
					      from mct_notificacionlista a,
				   			   mct_listaemail b,
		   		               mct_email c
					     where a.idnotificacion = 74
				           and a.idlista = b.idlista
					       and b.idemail = c.idemail 
				 	)
			    loop 	
							
					sp_lista := rec_email.emaildestino||','||sp_lista;
							           
		    end loop;
			    
			sp_asunto := '';
			sp_texto  := '';
					 
					 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
			select b.cuerpo,
		           b.asunto
			  into sp_texto,
		           sp_asunto
			  from mct_notificacion a
 		      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	         WHERE a.idnotificacion= 74;
				      
	        
	        sp_texto  := REPLACE(sp_texto,'_aviso',rec_trab.contador::varchar);
			sp_texto  := REPLACE(sp_texto,'_val_ingeniero',sp_responsable);
		    sp_texto  := REPLACE(sp_texto,'_val_accion',rec_trab.descripcion);
		    sp_texto  := REPLACE(sp_texto,'_val_respaldo',rec_trab.nombrerespaldo);
		    sp_texto  := REPLACE(sp_texto,'_val_componente',sp_nombrecomp);
		    sp_texto  := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
			sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
					
				     
			--sp_asunto  := REPLACE(sp_asunto,'_aviso',rec_trab.contador::varchar);
		    sp_asunto  := REPLACE(sp_asunto,'_val_def',rec_trab.correlativo::varchar);
				 
			orden        :=  rec_trab.iddefectocausaaccionpdf;
			asunto       :=  sp_asunto;
			cuerpo       :=  sp_texto; 
			emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
			codigonotf   :=  0; 
	
	
		    RETURN next;	
				     
			update mct_auditoriadefectocargarespaldo  
		       set contador = contador + 1
		     where idauditoriadefectocargarespaldo  = rec_trab.idauditoriadefectocargarespaldo;			     
			    		           
			  
	  END LOOP;
             
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotdefectocargarespaldovalidate() OWNER TO postgres;

--
-- TOC entry 1620 (class 1255 OID 17088)
-- Name: evtlistmaildistotdefectodebaja(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotdefectodebaja(iddefectofundicions bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	    sp_cliente				varchar;
	   
	    sp_ot                   integer;
	    sp_nombrecomp			varchar;
	    sp_nombremat			varchar;
	    sp_nombress				varchar;
	    sp_nombremaq			varchar;
	   
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	   
	    sp_intext				integer;
	   
	    sp_corr					integer;
	    sp_notif				integer;
	   
	    sp_roadmapcode			varchar;
	   
	    sp_textostring			varchar;
	   
	    sp_prod					integer;
	
		rec_email               RECORD;
	    rec_trab                RECORD;					           
         						    
begin

	sp_textostring := '';

	select codhojaruta 
	  into sp_roadmapcode
	  from mct_defectofundicion 
	 where iddefectofundicion = iddefectofundicions;
	
	select coalesce (b.idordentrabajo , 0),
	       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
	       coalesce (b.nombrematerial ,'SIN NOMBRE M')
	  into sp_ot,
	       sp_nombrecomp,
	       sp_nombremat
	  from mct_detallehojarutatemp a,
	       mct_hojarutatemp b,
	       mct_componente c
	 where a.codhojaruta = sp_roadmapcode
	   and a.idhojarutatemp = b.idhojarutatemp 
	   and b.idcomponente = c.idcomponente ;
	  
    select idproducto
      into sp_prod
      from mct_ordentrabajo mo 
     where idordentrabajo = sp_ot;
    
	select coalesce (b.nombresubseccion , 'SIN NOMBRE SS') ,
	       coalesce (c.nombremaquina , 'SIN NOMBRE MA'),
	       a.iddefectofundicionorigen
	  into sp_nombress,
	       sp_nombremaq,
	       sp_intext
	  from mct_defectofundicion a
	  left join mct_subseccion b on a.idsubseccion = b.idsubseccion
	  left join mct_maquina c on a.idmaquina = c.idmaquina
	 where codhojaruta = sp_roadmapcode
       and a.iddefectofundicion = (select max(iddefectofundicion) from mct_defectofundicion md );
      --and a.iddefectofundicion = 90;

    if ( sp_prod in (10,11,12,13,14,15,16,17)) then
    
  		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE P') ,
		       'SIN NOMBRE MO' ,
		       'SIN NOMBRE SIG' ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE B') ,
		       g.nombrecorto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_productonepcast c on a.idproducto = c.idproductonepcast
		 -- join mct_modelo d          on c.idmodelo = d.idmodelo
		  --join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  join mct_cliente g         on a.idcliente = g.idcliente 
		  --left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
  		 where a.idordentrabajo = sp_ot;
  		
    else
    
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproducto , 'SIN NOMBRE P') ,
		       coalesce (d.nombremodelo , 'SIN NOMBRE MO') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') ,
		       g.nombrecorto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  join mct_cliente g         on a.idcliente = g.idcliente 
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
  		 where a.idordentrabajo = sp_ot;
     
  	 end if;
	
  	 sp_textostring := sp_nombrebomba||'-'||sp_nombrecomp||'-'||sp_nombremat||'-OT '||sp_ot||'-'||sp_cliente;

--     if ( sp_intext = 2 ) then
--	      sp_corr 	:= nextval('mct_defectoscorr_seq');
--	      sp_notif	:= 55;
--	 else 
--	      sp_corr 	:= nextval('mct_defectoscorrext_seq');
--	      sp_notif	:= 56;
--	 end if;
	
--	update mct_defectofundicion
--	   set correlativo = sp_corr
--	 where codhojaruta = roadmapcodes
--      and iddefectofundicion = (select max(iddefectofundicion) from mct_defectofundicion md );
	 
	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = 64
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion = 64;
			      
	 sp_texto   := REPLACE(sp_texto,'_val_fecha',sp_fecha_hoy);
	 sp_texto   := REPLACE(sp_texto,'_val_componente',sp_textostring::varchar);

	 --sp_asunto  := REPLACE(sp_asunto,'_val_correlativo',nextval('mct_defectoscorr_seq')::varchar);
	 sp_asunto  := REPLACE(sp_asunto,'_val_roadmapcode',sp_roadmapcode::varchar);
			 
	 asunto       :=  cast(sp_asunto as varchar);
	 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  64; 
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotdefectodebaja(iddefectofundicions bigint) OWNER TO postgres;

--
-- TOC entry 1151 (class 1255 OID 17090)
-- Name: evtlistmaildistotdefectovalidate(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotdefectovalidate() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;		
	   
	    sp_salida				integer;
	   
	    sp_ot					bigint;
		sp_nombrecomp			varchar;
		sp_nombremat			varchar;
		sp_responsable			varchar;
	
	    sp_horas				bigint;
         						    
begin
	
	  sp_salida := 0;
  
	  FOR rec_trab IN (   
                    select a.idauditoriadefectovalido ,
                           a.iddefectofundicion ,
                           a.estado,
                           a.contador,
                           a.fechacreacion,
                           date_part('dow', a.fechacreacion) as diasem,
                           date_part('day', now() - a.fechacreacion ) as dife,
                           round(( EXTRACT(EPOCH FROM now())-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600) as horas,
                           date_part('day', now() - a.fechacreacion) as dias,
                           b.codhojaruta,
                           b.correlativo
                      from mct_auditoriadefectovalido a,
                           mct_defectofundicion b
                     where a.estado = 1
                       and a.iddefectofundicion = b.iddefectofundicion
					)
								
		loop 	
			     
		    sp_horas	:= 72;
		   
		    if (rec_trab.diasem = 5) then
		        sp_horas = 144;
		    elsif (rec_trab.diasem = 4) then
		           sp_horas = 120;
		    elsif (rec_trab.diasem = 3) then
		           sp_horas = 120;
		    end if;
		   
		    if (rec_trab.horas >= sp_horas) then
		
				select coalesce (b.idordentrabajo , 0),
				       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
				       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
				       coalesce (d.nombre , 'SIN RESPONSABLE')
				  into sp_ot,
				       sp_nombrecomp,
				       sp_nombremat,
				       sp_responsable
				  from mct_detallehojarutatemp a
				  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
				  join mct_componente c   on b.idcomponente = c.idcomponente
				  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
				 where a.codhojaruta = rec_trab.codhojaruta;
		
				sp_lista := '';
							   
				FOR rec_email IN (   
							select distinct c.emaildestino 
						      from mct_notificacionlista a,
					   			   mct_listaemail b,
			   		               mct_email c
						     where a.idnotificacion = 72
					           and a.idlista = b.idlista
						       and b.idemail = c.idemail 
					 	)
				    loop 	
								
						sp_lista := rec_email.emaildestino||','||sp_lista;
								           
			    end loop;
				    
				sp_asunto := '';
				sp_texto  := '';
						 
						 
				-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
				select b.cuerpo,
			           b.asunto
				  into sp_texto,
			           sp_asunto
				  from mct_notificacion a
	 		      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		         WHERE a.idnotificacion= 72;
					      
		        
		        sp_texto  := REPLACE(sp_texto,'_aviso',rec_trab.contador::varchar);
				sp_texto  := REPLACE(sp_texto,'_val_ingeniero',sp_responsable);
			    sp_texto  := REPLACE(sp_texto,'_val_componente',sp_nombrecomp);
			    sp_texto  := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
				sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
						
					     
				sp_asunto  := REPLACE(sp_asunto,'_aviso',rec_trab.contador::varchar);
			    sp_asunto  := REPLACE(sp_asunto,'_val_def',rec_trab.correlativo::varchar);
					 
				orden        :=  rec_trab.iddefectofundicion;
				asunto       :=  sp_asunto;
				cuerpo       :=  sp_texto; 
				emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
				codigonotf   :=  0; 
		
		
			    RETURN next;	
					     
				update mct_auditoriadefectovalido 
			       set contador = contador + 1
			     where idauditoriadefectovalido = rec_trab.idauditoriadefectovalido;
		    
		    end if;
					     
			    		           
			  
	  END LOOP;
             
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotdefectovalidate() OWNER TO postgres;

--
-- TOC entry 1125 (class 1255 OID 17091)
-- Name: evtlistmaildistotdesarme(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotdesarme(idnotif bigint, idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
        sp_nombrecliente		varchar;
		rec_email      			RECORD;
	    rec_trab       			RECORD;	

        sp_email				varchar;				           
         						    
begin

	select a.idusuario ,
	       b.nombre ,
	       c.nombreproducto ,
	       d.nombremodelo ,
	       e.sigla ,
	       e.sigla||' '||d.nombremodelo||' '||f.nombreparam ,
           g.nombrecliente,
           b.email
	  into sp_idusuario ,
	       sp_nombreingeniero,
	       sp_nombreproducto,
	       sp_nombremodelo,
	       sp_sigla,
	       sp_nombrebomba,
           sp_nombrecliente,
           sp_email
	  from mct_ordentrabajo a
	  join mct_usuario b         on a.idusuario = b.idusuario 
	  join mct_producto c        on a.idproducto = c.idproducto
	  join mct_modelo d          on c.idmodelo = d.idmodelo
	  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
	  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
      LEFT JOIN mct_cliente  g   on ( g.idcliente = a.idcliente)
  	 where a.idordentrabajo = idot;
	

	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = idnotif
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select REPLACE(b.cuerpo,'_valor_ot',idot::varchar),
		   REPLACE(b.asunto,'_valor_ot',idot::varchar)
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion= idnotif;

			      
	 sp_texto  	:= REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
     sp_texto  	:= REPLACE(sp_texto,'_valor_nombre',sp_nombreproducto);
     sp_texto  	:= REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero);
     sp_texto  	:= REPLACE(sp_texto,'_valor_cliente',sp_nombrecliente);
			 
	 asunto       :=  sp_asunto;
	 cuerpo       :=  sp_texto; 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1)||','||sp_email as varchar);
	 codigonotf   :=  idnotif; 
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotdesarme(idnotif bigint, idot bigint) OWNER TO postgres;

--
-- TOC entry 1143 (class 1255 OID 17092)
-- Name: evtlistmaildistotdespacho(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotdespacho(idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_ot                   integer;
	    sp_nombrecomp			varchar;
	    sp_nombremat			varchar;
	    sp_nombress				varchar;
	    sp_nombremaq			varchar;
	    sp_idtipoorden			integer;
	    sp_nombreordentrabajo	varchar;
	    sp_nombrecliente		varchar;
	    sp_idfamilia			integer;
	   
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	   
	    sp_intext				integer;
	   
	    sp_corr					integer;
	    sp_notif				integer;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin
  	
  		select a.idtipoorden ,
	           a.nombreordentrabajo,  
	           b.nombrecliente, 
  	           c.nombreproducto,
  	           coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B'),
  	           g.nombre ,
  	           a.idfamilia 
		  INTO sp_idtipoorden,
		       sp_nombreordentrabajo,
		       sp_nombrecliente,
		       sp_nombreproducto,
		       sp_nombrebomba,
		       sp_nombreingeniero,
  	           sp_idfamilia
		  from mct_ordentrabajo a
		  join mct_cliente b         on a.idcliente  = b.idcliente  
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  join mct_usuario g         on g.idusuario = a.idusuario
	  	 where a.idordentrabajo = idot;

	  	
	if (sp_idfamilia = 8) then

		sp_lista := '';
						   
		FOR rec_email IN (   
			select distinct c.emaildestino 
			  from mct_notificacionlista a,
			       mct_listaemail b,
			       mct_email c
		     where a.idnotificacion = 8
			   and a.idlista = b.idlista
			   and b.idemail = c.idemail 
				)
		    loop 	
							
			    sp_lista := rec_email.emaildestino||','||sp_lista;
							           
		END LOOP;
			    
		sp_asunto := '';
		sp_texto  := '';
					 
		-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		select b.cuerpo,
			   b.asunto
		  into sp_texto,
			   sp_asunto
		  from mct_notificacion a
	      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		 WHERE a.idnotificacion = 8;
				      
		 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
		 sp_texto   := REPLACE(sp_texto,'_valor_ot',idot::varchar);
		 sp_texto   := REPLACE(sp_texto,'_valor_nombre',sp_nombreordentrabajo::varchar);
		 sp_texto   := REPLACE(sp_texto,'_valor_cliente',sp_nombrecliente::varchar);
		 sp_texto   := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero::varchar);
		
		 sp_asunto    :=  REPLACE(sp_asunto,'_valor_ot',idot::varchar);
				 
		 asunto       :=  cast(sp_asunto as varchar);
		 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
		 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	--	 codigonotf   :=  sp_notif; 
					 
		 RETURN next;	  	
	
	end if;
	  	
      
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotdespacho(idot bigint) OWNER TO postgres;

--
-- TOC entry 1431 (class 1255 OID 17093)
-- Name: evtlistmaildistotexcelcotiza(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotexcelcotiza(idnotif bigint, idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
		sp_agno_hoy             VARCHAR=to_char(now(),'YYYY');

	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
        sp_nombrecliente		varchar;
		rec_email      			RECORD;
	    rec_trab       			RECORD;	
        sp_email				varchar;				           
         						    
begin

	select a.idusuario ,
	       b.nombre ,
	       c.nombreproducto ,
	       d.nombremodelo ,
	       e.sigla ,
	       e.sigla||' '||d.nombremodelo||' '||f.nombreparam ,
           g.nombrecliente,
           b.email
	  into sp_idusuario ,
	       sp_nombreingeniero,
	       sp_nombreproducto,
	       sp_nombremodelo,
	       sp_sigla,
	       sp_nombrebomba,
           sp_nombrecliente,
           sp_email
	  from mct_ordentrabajo a
	  join mct_usuario b         on a.idusuario = b.idusuario 
	  join mct_producto c        on a.idproducto = c.idproducto
	  join mct_modelo d          on c.idmodelo = d.idmodelo
	  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
	  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
      LEFT JOIN mct_cliente  g   on ( g.idcliente = a.idcliente)
  	 where a.idordentrabajo = idot;
	

	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = idnotif
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select REPLACE(b.cuerpo,'_valor_ot',idot::varchar),
		   REPLACE(b.asunto,'_valor_ot',idot::varchar)
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion= idnotif;

			      
	 sp_texto  	:= REPLACE(sp_texto,'_valor_agno',sp_agno_hoy::varchar);
	 sp_texto  	:= REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
     sp_texto  	:= REPLACE(sp_texto,'_valor_nombre',sp_nombreproducto);
     sp_texto  	:= REPLACE(sp_texto,'_valor_cliente',sp_nombrecliente);


     sp_asunto  := REPLACE(sp_asunto,'_valbomba',sp_nombrebomba);
			 
	 asunto       :=  sp_asunto;
	 cuerpo       :=  sp_texto; 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1)||','||sp_email as varchar);
	 codigonotf   :=  idnotif; 
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotexcelcotiza(idnotif bigint, idot bigint) OWNER TO postgres;

--
-- TOC entry 954 (class 1255 OID 17094)
-- Name: evtlistmaildistotgestionncf(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotgestionncf(roadmapcodes character varying) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_ot                   integer;
	    sp_nombrecomp			varchar;
	    sp_nombremat			varchar;
	    sp_nombress				varchar;
	    sp_nombremaq			varchar;
	   
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	   
	    sp_intext				integer;
	   
	    sp_corr					integer;
	    sp_notif				integer;
	   
	    sp_textostring			varchar;
	    sp_urgente				integer;
	    sp_responsable			varchar;
	    sp_fundicionorigen		varchar;
	    sp_observacion			varchar;
	    sp_detectadefecto		varchar;
	    sp_cliente				varchar;
	    sp_detecta				integer;
	   
	   	sp_idtipoorden			integer;
	    sp_idfamilia			integer;
	    sp_idproducto			integer;
	    
	    sp_prod					integer;
	   
	    sp_textoubicacion		varchar;
	   
	    sp_textostringfoto		varchar;
	    sp_plano				varchar;
	    sp_idgestionncf			bigint;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin

	--sp_urgente	    	:= 0;
    sp_responsable		:= '';
    sp_textoubicacion	:= '';
    sp_fundicionorigen	:= '';
    sp_observacion		:= '';
    sp_detectadefecto	:= '';
    sp_cliente			:= '';
    sp_detecta			:= 0;
    sp_textostring		:= '';
    sp_idgestionncf		:= 0;
   
    sp_prod				:= 0;

	select coalesce (b.idordentrabajo , 0),
	       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
	       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
	       coalesce (d.nombre , 'SIN RESPONSABLE')
	  into sp_ot,
	       sp_nombrecomp,
	       sp_nombremat,
	       sp_responsable
	  from mct_detallehojarutatemp a
	  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
	  join mct_componente c   on b.idcomponente = c.idcomponente
	  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
	 where a.codhojaruta = roadmapcodes;
	  
    select idproducto
      into sp_prod
      from mct_ordentrabajo mo 
     where idordentrabajo = sp_ot;
    
	select coalesce (b.nombresubseccion , 'SIN AREA') ,
	       coalesce (c.nombremaquina , 'SIN MAQ'),
	       a.id,
	       e.nombre ,
	       case 
		       when a.urgente is true then
		           1
		       else
		           0
		   end,
	       d.nombredetectadefecto ,
	       coalesce (a.observacion , 'SIN OBS'),
	       --a.iddetectadefecto ,
	       a.nombreplano ,
	       a.idgestionncf 
	  into sp_nombress,
	       sp_nombremaq,
	       sp_intext,
	       sp_fundicionorigen,
	       sp_urgente,
	       --sp_detectadefecto,
	       sp_observacion,
	       sp_detecta,
	       sp_plano,
	       sp_idgestionncf
	  from mct_gestionncf a
	  left join mct_subseccion b on a.idsubseccion = b.idsubseccion
	  left join mct_maquina c on a.idmaquina = c.idmaquina
	  --left join mct_detectadefecto d on a.iddetectadefecto = d.iddetectadefecto
	  left join mct_gestionncforigen e on a.idgestionncforigen = e.idgestionncforigen 
	 where codhojaruta = roadmapcodes 
       and a.idgestionncf = (select max(idgestionncf) from mct_gestionncf md );

    if (sp_detecta = 1) then
        sp_textoubicacion	:= sp_nombress||'-'||sp_nombremaq;
    elsif (sp_detecta in (5,6)) then
        sp_textoubicacion	:= 'xxxxxxxxx';
    end if;
  

    if ( sp_prod in (10,11,12,13,14,15,16,17)) then
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE P') ,
		       'SIN NOMBRE MO' ,
		       'SIN NOMBRE SIG' ,
		       coalesce (c.nombreproductonepcast  , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_productonepcast c on a.idproducto = c.idproductonepcast 
		  --join mct_modelo d          on c.idmodelo = d.idmodelo
		  --join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  --left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    else
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproducto , 'SIN NOMBRE P') ,
		       coalesce (d.nombremodelo , 'SIN NOMBRE MO') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') ,
		       g.nombrecorto ,
		       a.idtipoorden ,
		       a.idfamilia ,
		       a.idproducto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente,
		       sp_idtipoorden ,
		       sp_idfamilia ,
		       sp_idproducto
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  left join mct_cliente g    on a.idcliente = g.idcliente 
		 where a.idordentrabajo = sp_ot;    
    
    end if;


	if ( sp_intext = 2 ) then
	      sp_corr 		:= nextval('mct_gestionncfcorr_seq');
	      --sp_corr 	:= 999;
	      if ( sp_urgente = 1 ) then
	          sp_notif	:= 66;
	      else
	          sp_notif	:= 55;
	      end if;
	      
	 else 
	      sp_corr 		:= nextval('mct_gestionncfcorr_seq');
	      --sp_corr 	:= 999;
	      if ( sp_urgente = 1 ) then
	          sp_notif	:= 65;
	      else
	          sp_notif	:= 56;
	      end if;
	 end if;
	
	update mct_gestionncf
	   set correlativo = sp_corr
	 where idgestionncf = sp_idgestionncf;
	 
	if (sp_idfamilia = 11) then
	
	   if (sp_idproducto in (10,11,12,13,14,15,16,17) ) then
	   
	      select nombreproductonepcast 
	        into sp_nombrecomp
	        from mct_productonepcast a
	       where a.idproductonepcast = sp_idproducto;
	       
	   end if;
	  
	    sp_textostring 		:= sp_fundicionorigen||'-OT '||sp_ot||'-'||sp_nombrecomp||'-'||sp_nombremat||'-'||sp_cliente;
	    
	    sp_textostringfoto 	:= sp_corr||'-OT '||sp_ot||'-'||sp_nombrecomp||'-'||sp_nombremat||'-Plano '||sp_plano;
	else
	
		sp_textostring 		:= sp_fundicionorigen||'-OT '||sp_ot||'-'||sp_nombrebomba||'-'||sp_nombrecomp||'-'||sp_nombremat||'-'||sp_cliente;
	
	    sp_textostringfoto 	:= sp_corr||'-OT '||sp_ot||'-'||sp_nombrecomp||'-'||sp_nombremat||'-Plano '||sp_plano;
	
	end if;	

    update mct_gestionncfadjunto
       set nombrearchivo = sp_textostringfoto||'-'||correlativo
     where idgestionncf = sp_idgestionncf;
    
    --sp_textostring := sp_fundicionorigen||'-OT '||sp_ot||'-'||sp_nombrebomba||'-'||sp_nombrecomp||'-'||sp_nombremat||'-'||sp_cliente;
   
	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = sp_notif
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion = sp_notif;
			      
     sp_texto   := REPLACE(sp_texto,'_val_ingeniero',sp_responsable);
     sp_texto   := REPLACE(sp_texto,'_val_ubicacion',sp_textoubicacion);
     --sp_texto   := REPLACE(sp_texto,'_val_area',sp_detectadefecto);
     sp_texto   := REPLACE(sp_texto,'_val_componente',sp_textostring);
     sp_texto   := REPLACE(sp_texto,'_val_observacion',sp_observacion);
	
	 sp_texto   := REPLACE(sp_texto,'_val_fecha',sp_fecha_hoy);
	
	
--	 sp_texto   := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_componente',sp_nombrecomp::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_material',sp_nombremat::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_seccion',sp_nombress::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_maquina',sp_nombremaq::varchar);
--	 sp_texto   := REPLACE(sp_texto,'_valor_producto',sp_nombreproducto::varchar);
	

	 --sp_asunto  := REPLACE(sp_asunto,'_val_correlativo',nextval('mct_defectoscorr_seq')::varchar);
	 sp_asunto  := REPLACE(sp_asunto,'_val_correlativo',sp_corr::varchar);
			 
	 asunto       :=  cast(sp_asunto as varchar);
	 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  sp_notif; 
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotgestionncf(roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 883 (class 1255 OID 17096)
-- Name: evtlistmaildistotgestionncfanalisispdf(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotgestionncfanalisispdf(idgestionncfs bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf bigint)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    size 						integer := 0;
	    arreglo text[] 				:= array[]::text[];
	    arregloString  				varchar(2000);
	   
		sp_fecha_hoy            	VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                	varchar;
	   
	    sp_texto                	varchar;
	    sp_asunto              	 	varchar;
	    sp_senor                	varchar;
	
		rec_email      				RECORD;
	    rec_trab       				RECORD;	

		sp_idgestionncf				bigint;
		sp_correlativo				bigint;
		sp_codhojaruta				varchar;
	
	    sp_ot						bigint;
		sp_nombrecomp				varchar;
		sp_nombremat				varchar;
		sp_responsable				varchar;
	            						    
begin

		sp_idgestionncf			:= 0;
		sp_correlativo			:= 0;
		sp_codhojaruta			:= '';   
	    
        select a.idgestionncf  ,
               a.correlativo,
               a.codhojaruta
          into sp_idgestionncf,
               sp_correlativo,
               sp_codhojaruta
          from mct_gestionncf a
         where a.idgestionncf = idgestionncfs;

		select coalesce (b.idordentrabajo , 0),
		       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
		       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
		       coalesce (d.nombre , 'SIN RESPONSABLE')
		  into sp_ot,
		       sp_nombrecomp,
		       sp_nombremat,
		       sp_responsable
		  from mct_detallehojarutatemp a
		  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
		  join mct_componente c   on b.idcomponente = c.idcomponente
		  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
		 where a.codhojaruta = sp_codhojaruta;
				
		sp_lista := '';
							   
		FOR rec_email IN (   
			select distinct c.emaildestino 
			  from mct_notificacionlista a,
				   mct_listaemail b,
			       mct_email c
		     where a.idnotificacion = 73
		       and a.idlista = b.idlista
			   and b.idemail = c.idemail 
				)
		    loop 	
								
			    sp_lista := rec_email.emaildestino||','||sp_lista;
								           
		END LOOP;
				    
		sp_asunto := '';
		sp_texto  := '';
						 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		select b.cuerpo,
			   b.asunto
		  into sp_texto,
		       sp_asunto
		  from mct_notificacion a
	      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		 WHERE a.idnotificacion = 73;
					      
		 sp_texto  := REPLACE(sp_texto,'_val_ingeniero',sp_responsable);
		 sp_texto  := REPLACE(sp_texto,'_val_componente',sp_nombrecomp);
		 sp_texto  := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
	     sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);

		 sp_asunto := REPLACE(sp_asunto,'_val_def',sp_correlativo::varchar);
				 
		 asunto       :=  sp_asunto;
		 cuerpo       :=  sp_texto; 
		 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
		 codigonotf   :=  0; 
						 
		 RETURN next;	  	
		
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotgestionncfanalisispdf(idgestionncfs bigint) OWNER TO postgres;

--
-- TOC entry 1147 (class 1255 OID 17097)
-- Name: evtlistmaildistotgestionncfcargarespaldo(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotgestionncfcargarespaldo(idgestionncfcausaaccionpdfs bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf bigint)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    size 						integer := 0;
	    arreglo text[] 				:= array[]::text[];
	    arregloString  				varchar(2000);
	   
		sp_fecha_hoy            	VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                	varchar;
	   
	    sp_texto                	varchar;
	    sp_asunto              	 	varchar;
	    sp_senor                	varchar;
	
		rec_email      				RECORD;
	    rec_trab       				RECORD;	

		sp_idgestionncfcausaaccionpdf	bigint;
		sp_idgestionncfcausaaccion		bigint;
		sp_correlativo				bigint;
		sp_codhojaruta				varchar;
		sp_descripcion				varchar;
		sp_nombrerespaldo			varchar;
	
	    sp_ot						bigint;
		sp_nombrecomp				varchar;
		sp_nombremat				varchar;
		sp_responsable				varchar;
	            						    
begin

		sp_idgestionncfcausaaccionpdf	:= 0;
		sp_idgestionncfcausaaccion		:= 0;
		sp_correlativo				:= 0;
		sp_codhojaruta				:= '';
		sp_descripcion				:= '';
		sp_nombrerespaldo			:= '';
   
	    
        select b.idgestionncfcausaaccionpdf  ,
               b.idgestionncfcausaaccion  ,
               e.correlativo,
               e.codhojaruta,
               c.descripcion,
               b.nombrerespaldo
          into sp_idgestionncfcausaaccionpdf,
               sp_idgestionncfcausaaccion,
               sp_correlativo,
               sp_codhojaruta,
               sp_descripcion,
               sp_nombrerespaldo
          from mct_gestionncfcausaaccionpdf b,
               mct_gestionncfcausaaccion c,
               mct_gestionncfcausa d,
               mct_gestionncf e
         where b.idgestionncfcausaaccionpdf = idgestionncfcausaaccionpdfs
           and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
           and c.idgestionncfcausa = d.idgestionncfcausa 
           and d.idgestionncf = e.idgestionncf ;

		select coalesce (b.idordentrabajo , 0),
		       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
		       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
		       coalesce (d.nombre , 'SIN RESPONSABLE')
		  into sp_ot,
		       sp_nombrecomp,
		       sp_nombremat,
		       sp_responsable
		  from mct_detallehojarutatemp a
		  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
		  join mct_componente c   on b.idcomponente = c.idcomponente
		  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
		 where a.codhojaruta = sp_codhojaruta;
				
		sp_lista := '';
							   
		FOR rec_email IN (   
			select distinct c.emaildestino 
			  from mct_notificacionlista a,
				   mct_listaemail b,
			       mct_email c
		     where a.idnotificacion = 75
		       and a.idlista = b.idlista
			   and b.idemail = c.idemail 
				)
		    loop 	
								
			    sp_lista := rec_email.emaildestino||','||sp_lista;
								           
		END LOOP;
				    
		sp_asunto := '';
		sp_texto  := '';
						 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		select b.cuerpo,
			   b.asunto
		  into sp_texto,
		       sp_asunto
		  from mct_notificacion a
	      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		 WHERE a.idnotificacion = 75;
					      
		 sp_texto  := REPLACE(sp_texto,'_val_accion',sp_descripcion);
		 sp_texto  := REPLACE(sp_texto,'_val_respaldo',sp_nombrerespaldo);
		 sp_texto  := REPLACE(sp_texto,'_val_componente',sp_nombrecomp);
		 sp_texto  := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
	     sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);

		 sp_asunto := REPLACE(sp_asunto,'_val_def',sp_correlativo::varchar);
				 
		 asunto       :=  sp_asunto;
		 cuerpo       :=  sp_texto; 
		 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
		 codigonotf   :=  0; 
						 
		 RETURN next;	  	
		
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotgestionncfcargarespaldo(idgestionncfcausaaccionpdfs bigint) OWNER TO postgres;

--
-- TOC entry 1588 (class 1255 OID 17098)
-- Name: evtlistmaildistotgestionncfcargarespaldovalidate(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotgestionncfcargarespaldovalidate() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_salida				integer;
	   
	    sp_ot					bigint;
		sp_nombrecomp			varchar;
		sp_nombremat			varchar;
		sp_responsable			varchar;
         						    
begin
	
	  sp_salida := 0;
	
      FOR rec_trab IN (   
                    select a.idauditoriagestionncfcargarespaldo  ,
                           a.idgestionncfcausaaccionpdf  ,
                           a.estado,
                           a.contador,
                           a.fechacreacion,
                           a.fechaejecucion ,
                           e.correlativo,
                           e.codhojaruta,
                           c.descripcion,
                           b.nombrerespaldo
                      from mct_auditoriagestionncfcargarespaldo a,
                           mct_gestionncfcausaaccionpdf b,
                           mct_gestionncfcausaaccion c,
                           mct_gestionncfcausa d,
                           mct_gestionncf e
                     where a.estado = 1
                       and a.idgestionncfcausaaccionpdf = b.idgestionncfcausaaccionpdf 
                       and b.idgestionncfcausaaccion = c.idgestionncfcausaaccion 
                       and c.idgestionncfcausa = d.idgestionncfcausa 
                       and d.idgestionncffundicion = e.idgestionncffundicion 
                       and current_date > c.fechaejecucion
					)
				
					
		loop 	
			     			
				select coalesce (b.idordentrabajo , 0),
				       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
				       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
				       coalesce (d.nombre , 'SIN RESPONSABLE')
				  into sp_ot,
				       sp_nombrecomp,
				       sp_nombremat,
				       sp_responsable
				  from mct_detallehojarutatemp a
				  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
				  join mct_componente c   on b.idcomponente = c.idcomponente
				  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
				 where a.codhojaruta = rec_trab.codhojaruta;
	
			sp_lista := '';
						   
			FOR rec_email IN (   
						select distinct c.emaildestino 
					      from mct_notificacionlista a,
				   			   mct_listaemail b,
		   		               mct_email c
					     where a.idnotificacion = 74
				           and a.idlista = b.idlista
					       and b.idemail = c.idemail 
				 	)
			    loop 	
							
					sp_lista := rec_email.emaildestino||','||sp_lista;
							           
		    end loop;
			    
			sp_asunto := '';
			sp_texto  := '';
					 
					 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
			select b.cuerpo,
		           b.asunto
			  into sp_texto,
		           sp_asunto
			  from mct_notificacion a
 		      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	         WHERE a.idnotificacion= 74;
				      
	        
	        sp_texto  := REPLACE(sp_texto,'_aviso',rec_trab.contador::varchar);
			sp_texto  := REPLACE(sp_texto,'_val_ingeniero',sp_responsable);
		    sp_texto  := REPLACE(sp_texto,'_val_accion',rec_trab.descripcion);
		    sp_texto  := REPLACE(sp_texto,'_val_respaldo',rec_trab.nombrerespaldo);
		    sp_texto  := REPLACE(sp_texto,'_val_componente',sp_nombrecomp);
		    sp_texto  := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
			sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
					
				     
			--sp_asunto  := REPLACE(sp_asunto,'_aviso',rec_trab.contador::varchar);
		    sp_asunto  := REPLACE(sp_asunto,'_val_def',rec_trab.correlativo::varchar);
				 
			orden        :=  rec_trab.idgestionncfcausaaccionpdf;
			asunto       :=  sp_asunto;
			cuerpo       :=  sp_texto; 
			emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
			codigonotf   :=  0; 
	
	
		    RETURN next;	
				     
			update mct_auditoriagestionncfcargarespaldo  
		       set contador = contador + 1
		     where idauditoriagestionncfcargarespaldo  = rec_trab.idauditoriagestionncfcargarespaldo;			     
			    		           
			  
	  END LOOP;
             
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotgestionncfcargarespaldovalidate() OWNER TO postgres;

--
-- TOC entry 2026 (class 1255 OID 17099)
-- Name: evtlistmaildistotgestionncfdebaja(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotgestionncfdebaja(idgestionncfs bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	    sp_cliente				varchar;
	   
	    sp_ot                   integer;
	    sp_nombrecomp			varchar;
	    sp_nombremat			varchar;
	    sp_nombress				varchar;
	    sp_nombremaq			varchar;
	   
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	   
	    sp_intext				integer;
	   
	    sp_corr					integer;
	    sp_notif				integer;
	   
	    sp_roadmapcode			varchar;
	   
	    sp_textostring			varchar;
	   
	    sp_prod					integer;
	
		rec_email               RECORD;
	    rec_trab                RECORD;					           
         						    
begin

	sp_textostring := '';

	select codhojaruta 
	  into sp_roadmapcode
	  from mct_gestionncf 
	 where idgestionncf = idgestionncfs;
	
	select coalesce (b.idordentrabajo , 0),
	       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
	       coalesce (b.nombrematerial ,'SIN NOMBRE M')
	  into sp_ot,
	       sp_nombrecomp,
	       sp_nombremat
	  from mct_detallehojarutatemp a,
	       mct_hojarutatemp b,
	       mct_componente c
	 where a.codhojaruta = sp_roadmapcode
	   and a.idhojarutatemp = b.idhojarutatemp 
	   and b.idcomponente = c.idcomponente ;
	  
    select idproducto
      into sp_prod
      from mct_ordentrabajo mo 
     where idordentrabajo = sp_ot;
    
	select coalesce (b.nombresubseccion , 'SIN NOMBRE SS') ,
	       coalesce (c.nombremaquina , 'SIN NOMBRE MA'),
	       a.idorigenncf 
	  into sp_nombress,
	       sp_nombremaq,
	       sp_intext
	  from mct_gestionncf a
	  left join mct_subseccion b on a.idsubseccion = b.idsubseccion
	  left join mct_maquina c on a.idmaquina = c.idmaquina
	 where codhojaruta = sp_roadmapcode
       and a.idgestionncf = (select max(idgestionncf) from mct_gestionncf md );
      --and a.iddefectofundicion = 90;

    if ( sp_prod in (10,11,12,13,14,15,16,17)) then
    
  		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE P') ,
		       'SIN NOMBRE MO' ,
		       'SIN NOMBRE SIG' ,
		       coalesce (c.nombreproductonepcast , 'SIN NOMBRE B') ,
		       g.nombrecorto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_productonepcast c on a.idproducto = c.idproductonepcast
		 -- join mct_modelo d          on c.idmodelo = d.idmodelo
		  --join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  join mct_cliente g         on a.idcliente = g.idcliente 
		  --left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
  		 where a.idordentrabajo = sp_ot;
  		
    else
    
    
		select coalesce (a.idusuario, 0) ,
		       coalesce (b.nombre , 'SIN NOMBRE U') ,
		       coalesce (c.nombreproducto , 'SIN NOMBRE P') ,
		       coalesce (d.nombremodelo , 'SIN NOMBRE MO') ,
		       coalesce (e.sigla , 'SIN NOMBRE SIG') ,
		       coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B') ,
		       g.nombrecorto 
		  into sp_idusuario ,
		       sp_nombreingeniero,
		       sp_nombreproducto,
		       sp_nombremodelo,
		       sp_sigla,
		       sp_nombrebomba,
		       sp_cliente
		  from mct_ordentrabajo a
		  join mct_usuario b         on a.idusuario = b.idusuario 
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  join mct_cliente g         on a.idcliente = g.idcliente 
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
  		 where a.idordentrabajo = sp_ot;
     
  	 end if;
	
  	 sp_textostring := sp_nombrebomba||'-'||sp_nombrecomp||'-'||sp_nombremat||'-OT '||sp_ot||'-'||sp_cliente;

--     if ( sp_intext = 2 ) then
--	      sp_corr 	:= nextval('mct_defectoscorr_seq');
--	      sp_notif	:= 55;
--	 else 
--	      sp_corr 	:= nextval('mct_defectoscorrext_seq');
--	      sp_notif	:= 56;
--	 end if;
	
--	update mct_defectofundicion
--	   set correlativo = sp_corr
--	 where codhojaruta = roadmapcodes
--      and iddefectofundicion = (select max(iddefectofundicion) from mct_defectofundicion md );
	 
	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = 64
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select b.cuerpo,
		   b.asunto
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion = 64;
			      
	 sp_texto   := REPLACE(sp_texto,'_val_fecha',sp_fecha_hoy);
	 sp_texto   := REPLACE(sp_texto,'_val_componente',sp_textostring::varchar);

	 --sp_asunto  := REPLACE(sp_asunto,'_val_correlativo',nextval('mct_defectoscorr_seq')::varchar);
	 sp_asunto  := REPLACE(sp_asunto,'_val_roadmapcode',sp_roadmapcode::varchar);
			 
	 asunto       :=  cast(sp_asunto as varchar);
	 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  64; 
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotgestionncfdebaja(idgestionncfs bigint) OWNER TO postgres;

--
-- TOC entry 2371 (class 1255 OID 17101)
-- Name: evtlistmaildistotgestionncfvalidate(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotgestionncfvalidate() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;		
	   
	    sp_salida				integer;
	   
	    sp_ot					bigint;
		sp_nombrecomp			varchar;
		sp_nombremat			varchar;
		sp_responsable			varchar;
	
	    sp_horas				bigint;
         						    
begin
	
	  sp_salida := 0;
  
	  FOR rec_trab IN (   
                    select a.idauditoriagestionncfvalido ,
                           a.idgestionncf ,
                           a.estado,
                           a.contador,
                           a.fechacreacion,
                           date_part('dow', a.fechacreacion) as diasem,
                           date_part('day', now() - a.fechacreacion ) as dife,
                           round(( EXTRACT(EPOCH FROM now())-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600) as horas,
                           date_part('day', now() - a.fechacreacion) as dias,
                           b.codhojaruta,
                           b.correlativo
                      from mct_auditoriagestionncfvalido a,
                           mct_gestionncf b
                     where a.estado = 1
                       and a.idgestionncf = b.idgestionncf
					)
								
		loop 	
			     
		    sp_horas	:= 72;
		   
		    if (rec_trab.diasem = 5) then
		        sp_horas = 144;
		    elsif (rec_trab.diasem = 4) then
		           sp_horas = 120;
		    elsif (rec_trab.diasem = 3) then
		           sp_horas = 120;
		    end if;
		   
		    if (rec_trab.horas >= sp_horas) then
		
				select coalesce (b.idordentrabajo , 0),
				       coalesce (c.nombrecomponente,'SIN NOMBRE C') ,
				       coalesce (b.nombrematerial ,'SIN NOMBRE M'),
				       coalesce (d.nombre , 'SIN RESPONSABLE')
				  into sp_ot,
				       sp_nombrecomp,
				       sp_nombremat,
				       sp_responsable
				  from mct_detallehojarutatemp a
				  join mct_hojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
				  join mct_componente c   on b.idcomponente = c.idcomponente
				  left join mct_usuario d on c.idresponsablefundicion = d.idusuario 
				 where a.codhojaruta = rec_trab.codhojaruta;
		
				sp_lista := '';
							   
				FOR rec_email IN (   
							select distinct c.emaildestino 
						      from mct_notificacionlista a,
					   			   mct_listaemail b,
			   		               mct_email c
						     where a.idnotificacion = 72
					           and a.idlista = b.idlista
						       and b.idemail = c.idemail 
					 	)
				    loop 	
								
						sp_lista := rec_email.emaildestino||','||sp_lista;
								           
			    end loop;
				    
				sp_asunto := '';
				sp_texto  := '';
						 
						 
				-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
				select b.cuerpo,
			           b.asunto
				  into sp_texto,
			           sp_asunto
				  from mct_notificacion a
	 		      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		         WHERE a.idnotificacion= 72;
					      
		        
		        sp_texto  := REPLACE(sp_texto,'_aviso',rec_trab.contador::varchar);
				sp_texto  := REPLACE(sp_texto,'_val_ingeniero',sp_responsable);
			    sp_texto  := REPLACE(sp_texto,'_val_componente',sp_nombrecomp);
			    sp_texto  := REPLACE(sp_texto,'_valor_ot',sp_ot::varchar);
				sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
						
					     
				sp_asunto  := REPLACE(sp_asunto,'_aviso',rec_trab.contador::varchar);
			    sp_asunto  := REPLACE(sp_asunto,'_val_def',rec_trab.correlativo::varchar);
					 
				orden        :=  rec_trab.idgestionncf;
				asunto       :=  sp_asunto;
				cuerpo       :=  sp_texto; 
				emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
				codigonotf   :=  0; 
		
		
			    RETURN next;	
					     
				update mct_auditoriagestionncfvalido 
			       set contador = contador + 1
			     where idauditoriagestionncfvalido = rec_trab.idauditoriagestionncfvalido;
		    
		    end if;
					     
			    		           
			  
	  END LOOP;
             
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotgestionncfvalidate() OWNER TO postgres;

--
-- TOC entry 1071 (class 1255 OID 17102)
-- Name: evtlistmaildistotinterna(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotinterna(idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin

	select a.idusuario ,
	       b.nombre ,
	       c.nombreproducto ,
	       d.nombremodelo ,
	       e.sigla ,
	       e.sigla||' '||d.nombremodelo||' '||f.nombreparam 
	  into sp_idusuario ,
	       sp_nombreingeniero,
	       sp_nombreproducto,
	       sp_nombremodelo,
	       sp_sigla,
	       sp_nombrebomba
	  from mct_ordentrabajo a
	  join mct_usuario b         on a.idusuario = b.idusuario 
	  join mct_producto c        on a.idproducto = c.idproducto
	  join mct_modelo d          on c.idmodelo = d.idmodelo
	  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
	  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
  	 where a.idordentrabajo = idot;
	
				
      sp_lista := '';
	  FOR rec_email IN (   
						select distinct c.emaildestino 
				          from mct_notificacionlista a,
				               mct_listaemail b,
				         	   mct_email c
				         where a.idnotificacion = 44
				           and a.idlista = b.idlista
				           and b.idemail = c.idemail 
		  			  )
				   loop 	
						
						 sp_lista := rec_email.emaildestino||','||sp_lista;
						           
				  END LOOP;
		    
	 sp_asunto := '';
	 sp_texto  := '';
				 
				 
	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	 select REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_ot',idot::varchar)::varchar ,
		    REPLACE(b.asunto,'_valor_ot',idot::varchar)
	   into sp_texto,
		    sp_asunto
	   from mct_notificacion a
	   JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
      WHERE a.idnotificacion= 44;
			      
	  asunto       :=  sp_asunto;
	  cuerpo       :=  sp_texto; 
	  emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	  codigonotf   :=  10; 
				 
	  RETURN next;	
		     
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotinterna(idot bigint) OWNER TO postgres;

--
-- TOC entry 2155 (class 1255 OID 17103)
-- Name: evtlistmaildistotkpi(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotkpi(idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf bigint)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    size 					integer := 0;
	    arreglo text[] 			:= array[]::text[];
	    arregloString  			varchar(2000);
   
	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_ot                   integer;
	    sp_nombrecomp			varchar;
	    sp_nombremat			varchar;
	    sp_nombress				varchar;
	    sp_nombremaq			varchar;
	    sp_idtipoorden			integer;
	    sp_nombreordentrabajo	varchar;
	    sp_nombrecliente		varchar;
	    sp_idfamilia			integer;
	   
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	   
	    sp_intext				integer;
	   
	    sp_corr					integer;
	    sp_notif				integer;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;	

			 
		sp_valorir				varchar;
		sp_desarme				varchar;
		sp_it					varchar;
		sp_check				varchar;
	    sp_plano				varchar;
		sp_obscheck				varchar;
		sp_obsplano				varchar;
		sp_if					varchar;
		sp_general				varchar;   
	    sp_fechacotiza			timestamp;
	    sp_fechaautoriza		timestamp;
	   
	    sp_diasautoriza			integer;
	    sp_ok					integer;
	    sp_nok					integer;
	    sp_result				numeric;
	    sp_suma					integer;
	    sp_sumatotal			integer;
	   
         						    
begin

		sp_valorir	:= '';
		sp_desarme	:= '';
		sp_it		:= '';
		sp_check	:= '';
		sp_plano	:= '';
		sp_obscheck	:= '';
		sp_obsplano	:= '';
		sp_if		:= '';
		sp_general	:= ''; 	
	
	    sp_ok		:= 0;
	    sp_nok		:= 0;
	    sp_result	:= 0;
	    sp_suma		:= 0;
	    sp_sumatotal	:= 0;
	
		arregloString 	:=	traking.evtlistcontrolequipo_kpi(-1, idot, 'NA', 'NA');
	    arregloString 	:=  replace(arregloString, '(', '');
	    arregloString 	:=  replace(arregloString, ')', '');
	    arreglo 	  	:=	string_to_array(arregloString,',');
	    size 			:= 	array_length(arreglo,1);

	    -- Esto para IR
	    if (arreglo[12]::integer = 1) then
	    	sp_valorir	:= 'En tiempo';
	        sp_ok		:= sp_ok + 1;
	    else
		    sp_valorir 	:= 'Atraso - '||replace(arreglo[11], '"', '');
		    sp_nok		:= sp_nok + 1;
		end if;	
			   
	    -- Esto para Desarme
	    if (arreglo[17]::integer = 1) then
	    	sp_desarme	:= 'En tiempo';
	        sp_ok		:= sp_ok + 1;
	    else
		    sp_desarme 	:= 'Atraso - '||replace(arreglo[16], '"', '');
		    sp_nok		:= sp_nok + 1;
		end if;
	
 	    -- Esto para IT
	    if (arreglo[22]::integer = 1) then
	    	sp_it		:= 'En tiempo';
	        sp_ok		:= sp_ok + 1;
	    else
		    sp_it 		:= 'Atraso - '||replace(arreglo[21], '"', '');
		    sp_nok		:= sp_nok + 1;
		end if;

 	    -- Esto para IT
	    if (arreglo[31]::integer = 1) then
	    	sp_check	:= 'En tiempo';
	        sp_ok		:= sp_ok + 1;
	    else
		    sp_check 	:= 'Atraso - '||replace(arreglo[30], '"', '');
		    sp_nok		:= sp_nok + 1;
		end if;

 	    -- Esto para IT
	    if (arreglo[36]::integer = 1) then
	    	sp_plano	:= 'En tiempo';
	        sp_ok		:= sp_ok + 1;
	    else
		    sp_plano 	:= 'Atraso - '||replace(arreglo[35], '"', '');
		    sp_nok		:= sp_nok + 1;
		end if;
	
 	    -- Esto para IF
	    if (arreglo[43]::integer = 1) then
	    	sp_if		:= 'En tiempo';
	        sp_ok		:= sp_ok + 1;
	    else
		    sp_if 		:= 'Atraso - '||replace(arreglo[42], '"', '');
		    sp_nok		:= sp_nok + 1;
		end if;

		sp_sumatotal 	:= sp_ok * 100;	
	    sp_suma	 		:= sp_ok + sp_nok;
	    sp_result 		:= round(sp_sumatotal / sp_suma , 2);
--	    sp_result		:= sp_result * 100;
				   
	    sp_obscheck		:= 'Sin observaciones';
	    sp_obsplano		:= 'Sin observaciones';
	    sp_general		:= cast(sp_ok||'/'||(sp_ok+sp_nok)||' = '||sp_result::varchar||'% Cumplimiento' as varchar);

	   
	    -- Para sacar los dias de autorización
	    sp_diasautoriza	:= 0;
	    
	    sp_fechacotiza	:= null;
	    sp_fechaautoriza	:= null;
	      
	       select fecha_real_termino
	         into sp_fechacotiza
	         from mct_progavisos
	        where idordentrabajo = idot
	          and idsla = 4;
	      
	       select fecha_autoriza_cliente
	         into sp_fechaautoriza
	         from mct_progavisos
	        where idordentrabajo = idot
	          and idsla = 5;
	       
	    sp_diasautoriza := date_part('day',sp_fechaautoriza - sp_fechacotiza);
	        
   
  		select a.idtipoorden ,
	           a.nombreordentrabajo,  
	           b.nombrecliente, 
  	           c.nombreproducto,
  	           coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B'),
  	           g.nombre ,
  	           a.idfamilia 
		  INTO sp_idtipoorden,
		       sp_nombreordentrabajo,
		       sp_nombrecliente,
		       sp_nombreproducto,
		       sp_nombrebomba,
		       sp_nombreingeniero,
  	           sp_idfamilia
		  from mct_ordentrabajo a
		  join mct_cliente b         on a.idcliente  = b.idcliente  
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  join mct_usuario g         on g.idusuario = a.idusuario
	  	 where a.idordentrabajo = idot;

	  	
		if (sp_idfamilia = 8) then
	
			sp_lista := '';
							   
			FOR rec_email IN (   
				select distinct c.emaildestino 
				  from mct_notificacionlista a,
				       mct_listaemail b,
				       mct_email c
			     where a.idnotificacion = 60
				   and a.idlista = b.idlista
				   and b.idemail = c.idemail 
					)
			    loop 	
								
				    sp_lista := rec_email.emaildestino||','||sp_lista;
								           
			END LOOP;
				    
			sp_asunto := '';
			sp_texto  := '';
						 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
			select b.cuerpo,
				   b.asunto
			  into sp_texto,
				   sp_asunto
			  from mct_notificacion a
		      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
			 WHERE a.idnotificacion = 60;
					      
			 sp_texto   := REPLACE(sp_texto,'_valor_fecha',coalesce(sp_fecha_hoy,'SF'));
			 raise notice '%', '1'||sp_texto;
			 sp_texto   := REPLACE(sp_texto,'_valor_ot',idot::varchar);
			raise notice '%', '2'||sp_texto;
			 sp_texto   := REPLACE(sp_texto,'_valor_ingeniero',coalesce(sp_nombreingeniero,'SF')::varchar);
			raise notice '%', '3'||sp_texto;
			 sp_texto   := REPLACE(sp_texto,'_valor_nombre',coalesce(sp_nombreordentrabajo,'SF')::varchar);
			raise notice '%', '4'||sp_texto;
			 sp_texto   := REPLACE(sp_texto,'_valor_cliente',coalesce(sp_nombrecliente,'SF')::varchar);
			raise notice '%', '5'||sp_texto;
			 
			 sp_texto   := REPLACE(sp_texto,'_valor_ir',coalesce(sp_valorir,'0')::varchar);
			raise notice '%', '6'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_desarme',coalesce(sp_desarme,'0')::varchar);
		    raise notice '%', '7'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_it',coalesce(sp_it,'0')::varchar);
		    raise notice '%', '8'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_check',coalesce(sp_check,'0')::varchar);
		    raise notice '%', '9'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_plano',coalesce(sp_plano,'0')::varchar);
		    raise notice '%', '10'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_obscheck',coalesce(sp_obscheck,'0')::varchar);
		    raise notice '%', '11'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_obsplano',coalesce(sp_obsplano,'0')::varchar);
		    raise notice '%', '12'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_if',coalesce(sp_if,'0')::varchar);
		    raise notice '%', '13'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_general',coalesce(sp_general,'0')::varchar);
		    raise notice '%', '14'||sp_texto;
		     sp_texto   := REPLACE(sp_texto,'_valor_dias',coalesce(sp_diasautoriza,0)::varchar);
		    raise notice '%', '15'||sp_texto;
			
			 sp_asunto    :=  REPLACE(sp_asunto,'_valor_ot',idot::varchar);
					 
			 asunto       :=  cast(sp_asunto as varchar);
			 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
			 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
			 codigonotf   :=  99; 
						 
			 RETURN next;	  	
		
		end if;
	  	
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotkpi(idot bigint) OWNER TO postgres;

--
-- TOC entry 1682 (class 1255 OID 17105)
-- Name: evtlistmaildistotncftablet(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotncftablet(idnotif bigint, idnoconformidadf bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying)
    LANGUAGE plpgsql
    AS $$
	
declare
	       
		sp_fecha_hoy   			VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista       			varchar;
	   
		rec_email     			RECORD;
   
		sp_texto       			varchar;

	   
		sp_idordentrabajo       varchar;
		sp_componente           varchar;
		sp_inspector            varchar;
		sp_origen            	varchar;
		sp_detalle             	varchar;
		sp_seccion             	varchar;
		sp_operador             varchar;
		sp_descripcion          varchar;
		sp_accion             	varchar;
		sp_fechancf             varchar;
		sp_producto             varchar;
		sp_cliente             	varchar;
	    sp_plano				varchar;
	   
	    sp_idorigen             integer;
         						    
begin
	
	
			select 
			       a.idordentrabajo ,
			       cast(d.nombrecomponente||' - '||a.codhojaruta as varchar) as nombrecomponente,
			       e.nombre ,
			       f.nombreorigen,
			       f.detalleorigen,
			       h.nombreseccion ,
			       --i.nombreoperador||' - '||f.nombreorigen||' - '||h.nombreseccion ,
			       coalesce (i.nombreoperador||' - '||f.nombreorigen||' - '||h.nombreseccion, i.nombreoperador) ,
			       upper(a.descripcion) ,
			       j.nombreaccion ,
			       cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
			       cast(n.sigla||' '||m.nombremodelo as varchar) as productname,
			       p.nombrecorto as customername,
			       c.nombreplano ,
			       a.idorigenncf 
			  into sp_idordentrabajo ,
			       sp_componente ,
			       sp_inspector ,
			       sp_origen ,
			       sp_detalle ,
			       sp_seccion ,
			       sp_operador ,
			       sp_descripcion ,
			       sp_accion,
			       sp_fechancf ,
			       sp_producto,
			       sp_cliente,
			       sp_plano,
			       sp_idorigen
			  from mct_noconformidad a 
			  left join mct_detallehojarutatemp b on a.codhojaruta = b.codhojaruta
			  left join mct_hojarutatemp c        on b.idhojarutatemp = c.idhojarutatemp 
			  left join mct_componente d          on c.idcomponente = d.idcomponente 
			  left join mct_usuario e             on a.idusuario = e.idusuario
			  left join mct_origenncf f           on a.idorigenncf = f.idorigenncf
			  left join mct_seccionncf g          on a.idseccionncf = g.idseccionncf
			  --left join mct_seccion h             on g.idseccion = h.idseccion 
			  left join mct_seccion h             on a.idseccionncf = h.idseccion 
			  left join mct_operador i            on a.idusuarioseccion = i.idoperador 
			  left join mct_accionncf j           on a.idaccionncf = j.idaccionncf 
			  left join mct_ordentrabajo k        on k.idordentrabajo = a.idordentrabajo
			  left join mct_producto l            on k.idproducto = l.idproducto
			  left join mct_modelo m              on l.idmodelo = m.idmodelo 
			  left join mct_subfamilia n          on m.idsubfamilia = n.idsubfamilia
			  left join mct_cliente p             on k.idcliente = p.idcliente 
			 where a.idnoconformidad = idnoconformidadf ;
			            
			 
		  sp_lista := '';
		   
	      FOR rec_email IN (   
						select distinct c.emaildestino 
	         			  from mct_notificacionlista a,
	         				   mct_listaemail b,
	         		           mct_email c
	         		     where a.idnotificacion = idnotif
	         	           and a.idlista = b.idlista
	         		       and b.idemail = c.idemail 
						)
			loop 	
			
			     sp_lista := rec_email.emaildestino||','||sp_lista;
			           
		  END LOOP;
		
		   select b.cuerpo--REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_val_producto',sp_nombreordentrabajo),'_val_ot',sp_idordentrabajo::varchar),'_id_mov',sp_idmovimientoordentrabajo::varchar)::varchar 
		     into sp_texto
			 from mct_notificacion a
			 JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
			WHERE a.idnotificacion = idnotif;
		       

		  if ( sp_idorigen = 2 ) then
		     
		     sp_operador := 'EDISON NEIRA';
		  
		  end if;
		 
		  if ( sp_idorigen = 3 ) then
		     
		     sp_operador := 'LENIN FORTTE';
		  
		  end if;
		 
		  if ( sp_idorigen = 5 ) then
		     
		     sp_operador := 'MAURICIO ROJAS';
		  
		  end if;

		  sp_texto := REPLACE(sp_texto,'_valor_fecha',cast(sp_fecha_hoy as varchar));
	                                        
		--  sp_texto := REPLACE(sp_texto,'_val_fechancf',cast(sp_fechancf as varchar));
		  sp_texto := REPLACE(sp_texto,'_val_ot',sp_idordentrabajo::varchar)::varchar;
		  sp_texto := REPLACE(sp_texto,'_val_producto',coalesce(sp_producto,'SP'));		
		  sp_texto := REPLACE(sp_texto,'_val_componente',coalesce(sp_componente,'SC'));	
		  sp_texto := REPLACE(sp_texto,'_val_plano',coalesce(sp_plano,'SP'));	
		  sp_texto := REPLACE(sp_texto,'_val_cliente',coalesce(sp_cliente,'SC'));			 
		 
		  sp_texto := REPLACE(sp_texto,'_val_responsable',coalesce(sp_operador,'SO'));	
		  sp_texto := REPLACE(sp_texto,'_val_causa',coalesce(sp_detalle,'SD'));	
		  sp_texto := REPLACE(sp_texto,'_val_detalle',coalesce(sp_descripcion,'SD'));	
		  sp_texto := REPLACE(sp_texto,'_val_accion',coalesce(sp_accion,'SA'));	
		  sp_texto := REPLACE(sp_texto,'_val_inspector',coalesce(sp_inspector,'SI'));			 
		 

      	  RETURN QUERY
		
		  select REPLACE(b.asunto,'_val_ot',sp_idordentrabajo::varchar)::varchar as asunto,  		
			     sp_texto,
			     cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)
		    from mct_notificacion a
			JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		   WHERE a.idnotificacion= idnotif;
		

END;
$$;


ALTER FUNCTION traking.evtlistmaildistotncftablet(idnotif bigint, idnoconformidadf bigint) OWNER TO postgres;

--
-- TOC entry 1339 (class 1255 OID 17107)
-- Name: evtlistmaildistotqr(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotqr(idnotif bigint, idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, nombreordentrabajo character varying, nombrecliente character varying, nombreproducto character varying, fechaentrega character varying, fecharecepcion timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

		sp_idtipoorden    	      integer;
	    sp_nombretipoorden        varchar;
		sp_nombreordentrabajo 	  VARCHAR;
		sp_nombrecliente		  VARCHAR;
		sp_nombreproducto		  VARCHAR;
		sp_fechaentrega           varchar;
		sp_fecharecepcion         TIMESTAMP;

	    sp_idusuario              integer;
	    sp_planogeneral           varchar;
	    sp_nombreusuario          varchar;                
	    sp_fechacreacion          timestamp;
	    sp_idlineadiseno          integer;
	    sp_nomlineadiseno         varchar;	   
	    sp_idfamilia              integer;
	    sp_nomfamilia             varchar;
	       
		sp_fecha_hoy              VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                  varchar;
	   
	    sp_texto                  varchar;
	
		rec_email      RECORD;
        cur_email      CURSOR(sp_idnoti integer)
                    		  FOR select distinct c.emaildestino 
         						    from mct_notificacionlista a,
         						         mct_listaemail b,
         						         mct_email c
         						   where a.idnotificacion = idnotif
         					         and a.idlista = b.idlista
         						     and b.idemail = c.idemail ;
         						           
		
        sp_dias                integer;
       
        sp_valor_diseno        varchar;

       -- Para el calculo de la fecha de entrega
        intervalo    			varchar;
        sp_fecha_entrega     	varchar;
        indice       			integer;
        dias_totales			integer;
        dia_inicial  			integer;
       
       -- Para los KPi
		sp_inicio               varchar;
		sp_termino              varchar;
		sp_terminoreal          varchar;
		sp_demora               varchar;
		sp_diasplanificados     varchar;		
		sp_diasreales           varchar;
	    
	    sp_idsla                integer;
   
         						    
begin

    sp_idsla := idnotif;		   
   
   
	select a.idtipoorden ,
	       a.nombreordentrabajo,  
	       b.nombrecliente, 
  	       c.nombreproducto, 
 	       to_char(a.fechaentrega, 'dd-mm-yyyy'), 
	       a.fecharecepcion,
	       a.idusuario ,
	       c.planogeneral ,
	       d.nombre ,
	       a.fechacreacion ,
	       a.idlineadiseno ,
	       a.idfamilia ,
	       case
	          when a.idlineadiseno = 1 then 'DE DISEÑO'
	          when a.idlineadiseno = 2 then 'DE LÍNEA'
	          when a.idlineadiseno = 3 then 'COMERCIAL'
	       end,
	       e.nombrefamilia ,
	       f.nombretipoorden 
	  INTO sp_idtipoorden,
	       sp_nombreordentrabajo,
	       sp_nombrecliente,
	       sp_nombreproducto,
	       sp_fechaentrega,
	       sp_fecharecepcion,
	       sp_idusuario ,
	       sp_planogeneral ,
	       sp_nombreusuario ,
	       sp_fechacreacion ,
	       sp_idlineadiseno ,
	       sp_idfamilia ,
	       sp_nomlineadiseno,
	       sp_nomfamilia,
	       sp_nombretipoorden
	  from mct_ordentrabajo a
	  LEFT JOIN mct_cliente  b    ON ( b.idcliente = a.idcliente)
	  LEFT JOIN mct_producto c    ON ( c.idproducto = a.idproducto)
	  left join mct_usuario d     on ( a.idusuario = d.idusuario )
	  left join mct_familia e     on ( a.idfamilia = e.idfamilia )
	  left join mct_tipoorden f   on ( a.idtipoorden = f.idtipoorden )	  
	  WHERE a.idordentrabajo= idot;

	  sp_fecha_entrega := '';
	  sp_inicio:= '';
	  sp_termino:= '';
	  sp_terminoreal:= '';
	  sp_demora:= '';
	  sp_diasplanificados:= '';       
	  sp_diasreales:= '';

	  sp_lista := '';
	   
	  if ( sp_idfamilia = 8 ) then
	 
	        FOR rec_email IN (   
					select distinct c.emaildestino 
         			  from mct_notificacionlista a,
         				   mct_listaemail b,
         		           mct_email c
         		     where a.idnotificacion = idnotif
         	           and a.idlista = b.idlista
         		       and b.idemail = c.idemail 
					)
				loop 	
		     
				    sp_lista := rec_email.emaildestino||','||sp_lista;
		           
			  END LOOP;
             
      
      	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_nombre',sp_nombreordentrabajo),'_valor_ot',idot::varchar),'_valor_cliente',sp_nombrecliente)::varchar 
		    into sp_texto
			from mct_notificacion a
		    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	       WHERE a.idnotificacion= idnotif;
	     
	      sp_texto := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
		  sp_texto := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreusuario);
		  sp_texto := REPLACE(sp_texto,'_valor_ot',idot::varchar);
	 
	 
      RETURN QUERY
		
		  select REPLACE(b.asunto,'_valor_ot',idot::varchar)::varchar as asunto,  		
			     sp_texto,
			     cast(substring(sp_lista,1,length(sp_lista)-1) as varchar),
			     sp_nombreordentrabajo,
			     sp_nombrecliente, 
			     sp_nombreproducto, 
			     sp_fechaentrega, 
			     sp_fecharecepcion
		    from mct_notificacion a
			JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		   WHERE a.idnotificacion= idnotif;
		  
	  end if;
	 	

END;
$$;


ALTER FUNCTION traking.evtlistmaildistotqr(idnotif bigint, idot bigint) OWNER TO postgres;

--
-- TOC entry 947 (class 1255 OID 17109)
-- Name: evtlistmaildistotrechncf(bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotrechncf(idnotif bigint, itrechancf bigint, idmov bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying)
    LANGUAGE plpgsql
    AS $$
	
declare
	       
		sp_fecha_hoy   VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista       varchar;
	   
		rec_email      RECORD;
   
		sp_texto       					varchar;
		sp_idordentrabajo 				integer;
		sp_idmovimientoordentrabajo		integer;
		sp_codhojaruta 					varchar;
			       --a.idoperador ,
		sp_idparte 						integer;
		sp_nombreaccion 				varchar;
		sp_fechainicio 					varchar;
		sp_fechatermino 				varchar;
		sp_nombreordentrabajo 			varchar;
		sp_idmodalidadcreacion 			integer;
		sp_nombreoperador 				varchar;
		sp_nombremaquina 				varchar;
		sp_descripcioncc 				varchar;
		sp_observacion 					varchar;
		sp_nombreparte					varchar;
	    sp_nombreplano					varchar;
	    sp_idmodalidad                  integer;
	    sp_pega_observacion             varchar;
	   
	   	sp_obs_ant						varchar;
		sp_ope_ant						varchar;
		sp_inicio						varchar;
		sp_termino						varchar;
		sp_dife							varchar;
	    sp_ultimo						varchar;
         						    
begin
	
	
		if ( itrechancf = 43 ) then
		
			select a.idordentrabajo ,
			       a.idmovimientoordentrabajo ,
			       a.codhojaruta ,
			       --a.idoperador ,
			       a.idparte ,
			       b.nombreaccion ,
			       a.fechainicio ,
			       a.fechatermino ,
			       c.nombreordentrabajo ,
			       c.idmodalidadcreacion ,
			       d.nombreoperador ,
			       e.nombremaquina ,
			       a.descripcioncc ,
			       a.observacion 
			  into sp_idordentrabajo ,
			       sp_idmovimientoordentrabajo ,
			       sp_codhojaruta ,
			       --a.idoperador ,
			       sp_idparte ,
			       sp_nombreaccion ,
			       sp_fechainicio ,
			       sp_fechatermino ,
			       sp_nombreordentrabajo ,
			       sp_idmodalidadcreacion ,
			       sp_nombreoperador ,
			       sp_nombremaquina ,
			       sp_descripcioncc ,
			       sp_observacion 
			  from mct_movimientoordentrabajo a,
			       mct_accion b,
			       mct_ordentrabajo c,
			       mct_operador d,
			       mct_maquina e
			 where  idmovimientoordentrabajo = idmov
			   and a.idcausacierre = b.idaccion 
			   and a.idordentrabajo = c.idordentrabajo 
			   and a.idoperador = d.idoperador 
			   and a.idmaquina = e.idmaquina ;
		
		end if;

		if ( itrechancf = 81 ) then
		
			select a.idordentrabajo ,
			       a.idmovimientoordentrabajo ,
			       a.codhojaruta ,
			       a.idparte ,
			       b.nombreaccion ,
			       a.fechainicio ,
			       a.fechatermino ,
			       c.nombreordentrabajo ,
			       c.idmodalidadcreacion ,
			       d.nombreoperador ,
			       a.descripcioncc ,
			       a.observacion 	 
			  into sp_idordentrabajo ,
			       sp_idmovimientoordentrabajo ,
			       sp_codhojaruta ,
			       --a.idoperador ,
			       sp_idparte ,
			       sp_nombreaccion ,
			       sp_fechainicio ,
			       sp_fechatermino ,
			       sp_nombreordentrabajo ,
			       sp_idmodalidadcreacion ,
			       sp_nombreoperador ,
			       sp_descripcioncc ,
			       sp_observacion 			       
			  from mct_movimientoordentrabajo a,
			       mct_accion b,
			       mct_ordentrabajo c,
			       mct_operador d
			 where idmovimientoordentrabajo = idmov
			   and a.idcausacierre = b.idaccion 
			   and a.idordentrabajo = c.idordentrabajo 
			   and a.idoperador = d.idoperador ;

		
		end if;
	
	
	    if ( sp_idmodalidadcreacion = 1 ) then
	    
	      select nombrecomponente 
	        into sp_nombreparte
	    	from mct_componente 
	       where idcomponente = sp_idparte;
	      
	      select nombreplano 
	      	into sp_nombreplano
	        from mct_hojarutatemp mh 
	      where idordentrabajo = sp_idordentrabajo
	        and idcomponente = sp_idparte;
	      
	    elsif ( sp_idmodalidadcreacion = 2 ) then
	    
	      select a.nombreparte, 
	             b.nombreplano 
	        into sp_nombreparte,
	             sp_nombreplano
	    	from mct_parte a, 
	    	     mct_plano b
	       where idparte = sp_idparte
	         and a.idplano = b.idplano ;
	    
	    end if;
	
	 
	  sp_lista := '';
	   
      FOR rec_email IN (   
					select distinct c.emaildestino 
         			  from mct_notificacionlista a,
         				   mct_listaemail b,
         		           mct_email c
         		     where a.idnotificacion = idnotif
         	           and a.idlista = b.idlista
         		       and b.idemail = c.idemail 
					)
		loop 	
		
		     sp_lista := rec_email.emaildestino||','||sp_lista;
		           
	  END LOOP;
	
	   select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_val_producto',sp_nombreordentrabajo),'_val_ot',sp_idordentrabajo::varchar),'_id_mov',sp_idmovimientoordentrabajo::varchar)::varchar 
	     into sp_texto
		 from mct_notificacion a
		 JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		WHERE a.idnotificacion = 16;
	      
             

	  if ( itrechancf = 43 ) then
	  
		  sp_texto := REPLACE(sp_texto,'_val_idparte',cast(sp_idparte as varchar));
		  sp_texto := REPLACE(sp_texto,'_val_plano',coalesce(sp_nombreplano, 'SD'));
		  sp_texto := REPLACE(sp_texto,'_val_obs',coalesce(sp_pega_observacion,'SD'));		
		  sp_texto := REPLACE(sp_texto,'_val_hr',coalesce(sp_codhojaruta,'SD'));	
		  sp_texto := REPLACE(sp_texto,'_val_motivo',coalesce(sp_nombreoperador,'SD'));	
		 
	  end if;
	 
	  if ( itrechancf = 81 ) then
	  		  
	  		sp_obs_ant  := '';
			sp_ope_ant  := '';
			sp_inicio  := '';
			sp_termino  := '';
			sp_dife  := '';
		
		  	select a.observacion,
			       b.nombreoperador ,
			       to_char(a.fechainicio,'dd-mm-yyyy hh24:mi:ss') ,
			       to_char(a.fechatermino,'dd-mm-yyyy hh24:mi:ss') ,
			       cast(round(extract(Epoch from (a.fechatermino::timestamp - a.fechainicio::timestamp))/60) as varchar)
			  into sp_obs_ant,
			       sp_ope_ant,
			       sp_inicio,
			       sp_termino,
			       sp_dife
			  from mct_movimientoordentrabajo a,
			       mct_operador b
			 where idmovimientoordentrabajo  =  (select max(idmovimientoordentrabajo) 
													  from mct_movimientoordentrabajo 
													 where codhojaruta = sp_codhojaruta
													   and idmovimientoordentrabajo in ( select max(idmovimientoordentrabajo) 
													                                           from mct_movimientoordentrabajo 
													                                          where codhojaruta = sp_codhojaruta
													                                            and idseccion != 14))
			   and a.idoperador = b.idoperador;
			  
		  sp_ultimo := '';	  
	      sp_ultimo := sp_ope_ant||' Inicio : '||sp_inicio||' / Termino : '||sp_termino||' , Duró : '||sp_dife||' min(s)';

	                                        
		  sp_texto := REPLACE(sp_texto,'_val_idparte',cast(sp_idparte as varchar));
		  sp_texto := REPLACE(sp_texto,'_val_plano',coalesce(sp_nombreplano,'SD'));
		  sp_texto := REPLACE(sp_texto,'_val_obs',coalesce(sp_observacion,'SD'));		
		  sp_texto := REPLACE(sp_texto,'_val_inspector',coalesce(sp_nombreoperador,'SD'));	
		  sp_texto := REPLACE(sp_texto,'_val_hr',coalesce(sp_codhojaruta,'SD'));	
		  sp_texto := REPLACE(sp_texto,'_val_ultimo',coalesce(sp_ultimo,'SD'));			 
		  sp_texto := REPLACE(sp_texto,'_val_motivo',coalesce(sp_nombreoperador,'SD'));	
		 
	  end if;
	 
	 
      RETURN QUERY
		
		  select REPLACE(b.asunto,'_val_ot',sp_idordentrabajo::varchar)::varchar as asunto,  		
			     sp_texto,
			     cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)
		    from mct_notificacion a
			JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		   WHERE a.idnotificacion= idnotif;
		

END;
$$;


ALTER FUNCTION traking.evtlistmaildistotrechncf(idnotif bigint, itrechancf bigint, idmov bigint) OWNER TO postgres;

--
-- TOC entry 1371 (class 1255 OID 17111)
-- Name: evtlistmaildistotsellom(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotsellom(idnotif bigint, idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin

	select a.idusuario ,
	       b.nombre ,
	       c.nombreproducto ,
	       d.nombremodelo ,
	       e.sigla ,
	       e.sigla||' '||d.nombremodelo||' '||f.nombreparam 
	  into sp_idusuario ,
	       sp_nombreingeniero,
	       sp_nombreproducto,
	       sp_nombremodelo,
	       sp_sigla,
	       sp_nombrebomba
	  from mct_ordentrabajo a
	  join mct_usuario b         on a.idusuario = b.idusuario 
	  join mct_producto c        on a.idproducto = c.idproducto
	  join mct_modelo d          on c.idmodelo = d.idmodelo
	  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
	  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
  	 where a.idordentrabajo = idot;
	

	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = idnotif
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_val_fecha',sp_fecha_hoy),'_val_responsable',sp_nombreingeniero),'_val_ot',idot::varchar),'_val_modelo',sp_nombrebomba)::varchar ,
		   REPLACE(REPLACE(b.asunto,'_val_ot',idot::varchar),'_val_modelo',sp_nombrebomba)
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion= idnotif;

			      
	 sp_texto  := REPLACE(sp_texto,'_val_ingeniero',sp_nombreingeniero);
	 sp_asunto  := REPLACE(sp_asunto,'_val_modelo',sp_nombrebomba);
			 
	 asunto       :=  sp_asunto;
	 cuerpo       :=  sp_texto; 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  idnotif; 
				 
	 RETURN next;	        
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotsellom(idnotif bigint, idot bigint) OWNER TO postgres;

--
-- TOC entry 1762 (class 1255 OID 17112)
-- Name: evtlistmaildistotsolfund(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotsolfund(idworkorders bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf bigint)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    size 					integer := 0;
	    arreglo text[] 			:= array[]::text[];
	    arregloString  			varchar(2000);
   
	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_ot                   integer;
	    sp_nombrecomp			varchar;
	    sp_nombremat			varchar;
	    sp_nombress				varchar;
	    sp_nombremaq			varchar;
	    sp_idtipoorden			integer;
	    sp_nombreordentrabajo	varchar;
	    sp_nombrecliente		varchar;
	    sp_idfamilia			integer;
	   
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	   
	    sp_intext				integer;
	   
	    sp_corr					integer;
	    sp_notif				integer;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;	

		sp_valorir				varchar;
		sp_desarme				varchar;
		sp_it					varchar;
		sp_check				varchar;
	    sp_plano				varchar;
		sp_obscheck				varchar;
		sp_obsplano				varchar;
		sp_if					varchar;
		sp_general				varchar;   

	    sp_fechafundicion		varchar;
	    sp_idot					integer;
	   
         						    
begin

		sp_valorir	:= '';
		sp_desarme	:= '';
		sp_it		:= '';
		sp_check	:= '';
		sp_plano	:= '';
		sp_obscheck	:= '';
		sp_obsplano	:= '';
		sp_if		:= '';
		sp_general	:= ''; 
	    sp_fechafundicion	:= '';
	    sp_idot		:= 0;
   
--	    select idordentrabajo 
--	      into sp_idot 
--	      from mct_checklistinftecfundcab mc
--         where idchecklistinftecfundcab = idchecklistinftecfundcabs;
	    
	    select a.idtipoorden ,
	           a.nombreordentrabajo,  
	           b.nombrecliente, 
  	           c.nombreproducto,
  	           coalesce (e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'SIN NOMBRE B'),
  	           g.nombre ,
  	           a.idfamilia ,
  	           --a.fechaentrega,
  	           --to_char(a.fechaentrega - interval '21 days','dd-mm-yyyy') as fechafundicion
  	           case
		           when a.idestadoorden < 6 then
		                cast(to_char(now() + interval '9 days','dd-mm-yyyy') as varchar)
		           else
		                to_char(a.fechaentrega - interval '21 days','dd-mm-yyyy')
	       	   end  as fechafundicion
		  INTO sp_idtipoorden,
		       sp_nombreordentrabajo,
		       sp_nombrecliente,
		       sp_nombreproducto,
		       sp_nombrebomba,
		       sp_nombreingeniero,
  	           sp_idfamilia,
  	           sp_fechafundicion
		  from mct_ordentrabajo a
		  join mct_cliente b         on a.idcliente  = b.idcliente  
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
		  join mct_usuario g         on g.idusuario = a.idusuario
	  	 where a.idordentrabajo = idworkorders;

	  	
			sp_lista := '';
							   
			FOR rec_email IN (   
				select distinct c.emaildestino 
				  from mct_notificacionlista a,
				       mct_listaemail b,
				       mct_email c
			     where a.idnotificacion = 61
				   and a.idlista = b.idlista
				   and b.idemail = c.idemail 
					)
			    loop 	
								
				    sp_lista := rec_email.emaildestino||','||sp_lista;
								           
			END LOOP;
				    
			sp_asunto := '';
			sp_texto  := '';
						 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
			select b.cuerpo,
				   b.asunto
			  into sp_texto,
				   sp_asunto
			  from mct_notificacion a
		      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
			 WHERE a.idnotificacion = 61;
					      
			 sp_texto   := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
			 sp_texto   := REPLACE(sp_texto,'_valor_ot',idworkorders::varchar);
			 sp_texto   := REPLACE(sp_texto,'_valor_modelo',sp_nombrebomba::varchar);
			 sp_texto   := REPLACE(sp_texto,'_valor_entrega',sp_fechafundicion::varchar);
			 sp_texto   := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero::varchar);
			 --sp_texto   := REPLACE(sp_texto,'_valor_nombre',sp_nombreordentrabajo::varchar);
			 --sp_texto   := REPLACE(sp_texto,'_valor_cliente',sp_nombrecliente::varchar);
			
			 sp_asunto    :=  REPLACE(sp_asunto,'_valor_ot',idworkorders::varchar);
			 sp_asunto    :=  REPLACE(sp_asunto,'_valor_modelo',sp_nombrebomba::varchar);
					 
			 asunto       :=  cast(sp_asunto as varchar);
			 cuerpo       :=  coalesce(cast(sp_texto as varchar), 'SIN CUERPO'); 
			 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
			 codigonotf   :=  99; 
						 
			 RETURN next;	  	
		
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistotsolfund(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 2230 (class 1255 OID 17114)
-- Name: evtlistmaildistotsolicitudesgeneradas(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistotsolicitudesgeneradas(idot bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_esperadas		integer;
	    sp_generadas		integer;

		sp_fecha_hoy        VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista            varchar;
	   
	    sp_texto            varchar;
	    sp_asunto           varchar;
	
		rec_email      		RECORD;				           
         						    
begin

	select count(distinct (codigoqr))
	  into sp_esperadas
	  from mct_checklistinftecvalido mc 
	 where idordentrabajo = idot;

	select count(*) 
	  into sp_generadas
	  from mct_infcotipdf mi 
	 where idordentrabajo = idot
	   and idproceso = 100;

	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = 71
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select --REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_val_fecha',sp_fecha_hoy),'_valor_responsable',sp_nombreingeniero),'_valor_ot',idot::varchar),'_valor_modelo',sp_nombrebomba)::varchar ,
		   REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),
	       REPLACE(b.asunto,'_valot',idot::varchar)
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion= 71;
			      
	 sp_texto   := REPLACE(sp_texto,'_val_esperadas',sp_esperadas::varchar);
	 sp_texto   := REPLACE(sp_texto,'_val_generadas',sp_generadas::varchar);
	 sp_texto   := REPLACE(sp_texto,'_valot',idot::varchar);

			 
	 asunto       :=  sp_asunto;
	 cuerpo       :=  sp_texto; 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  71; 
				 
	 RETURN next;	        
	     
END;
$$;


