ALTER FUNCTION traking.evtlistmaildistottrabajosrp(idot bigint) OWNER TO postgres;

--
-- TOC entry 1197 (class 1255 OID 17118)
-- Name: evtlistmaildistottrabajosrpsol(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistottrabajosrpsol() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin
	
	   
      FOR rec_trab IN (   
					select distinct f.idordentrabajo ,
					       --d.idnotificacion,
					       --d.codigoarchivoinftecpdf ,
					       --d.idusuarioresp ,
					       --d.sigla ,
					       --e.nombre,
					       to_char(f.fecha_termino,'dd-mm-yyyy') as fecha_termino
         			  from mct_notificacionlista a
         		      join mct_tipotrabajochecklist d on a.idnotificacion = d.idnotificacion
         		      left join mct_usuario e         on d.idusuarioresp  = e.idusuario 
         		      left join mct_progavisoschecklist f on d.sigla = f.sigla --and f.idordentrabajo in (30123,30184,30185,30163,30164)
         		      join mct_progavisos g on g.idordentrabajo = f.idordentrabajo and g.idsla = 5 and g.estado = 1 and g.enviosolicitudpla = 0
         		     where to_timestamp(to_char(fechaenviosolicitud, 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd') and enviosolicitud = 1
         		       --and f.idordentrabajo = 30155
         		       and d.codigoarchivoinftecpdf in ( select cast(infcoti as varchar) from mct_infcotipdf where idordentrabajo = f.idordentrabajo and idproceso = 100)
					)
				
		loop 	

		
				select a.idusuario ,
				       b.nombre ,
				       c.nombreproducto ,
				       d.nombremodelo ,
				       e.sigla ,
				       coalesce(e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'S/N'),
				       a.idfamilia 
				  into sp_idusuario ,
				       sp_nombreingeniero,
				       sp_nombreproducto,
				       sp_nombremodelo,
				       sp_sigla,
				       sp_nombrebomba,
				       sp_familia
				  from mct_ordentrabajo a
				  join mct_usuario b         on a.idusuario = b.idusuario 
				  join mct_producto c        on a.idproducto = c.idproducto
				  join mct_modelo d          on c.idmodelo = d.idmodelo
				  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
				  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
			  	 where a.idordentrabajo = rec_trab.idordentrabajo;
  	
			 if ( sp_familia != 11) then
			
			      sp_lista := '';
					   
				  FOR rec_email IN (   
									select distinct c.emaildestino 
				         			  from mct_notificacionlista a,
				         				   mct_listaemail b,
				         		           mct_email c
				         		     where a.idnotificacion = 25
				         	           and a.idlista = b.idlista
				         		       and b.idemail = c.idemail 
									)
				     loop 	
						
						 sp_lista := rec_email.emaildestino||','||sp_lista;
						           
				  END LOOP;
		    
				  sp_asunto := '';
				  sp_texto  := '';
				 
				--  if ( rec_trab.codigoarchivoinftecpdf = '50' ) then
			        sp_senor := sp_nombreingeniero;
				--  else
				--     sp_senor := rec_trab.nombre;
				 -- end if;
				 
		          	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
				  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_responsable',sp_senor),'_val_ot',rec_trab.idordentrabajo::varchar),'_valor_modelo',sp_nombrebomba)::varchar ,
				         REPLACE(REPLACE(b.asunto,'_val_ot',rec_trab.idordentrabajo::varchar),'_val_modelo',sp_nombrebomba)
				    into sp_texto,
				         sp_asunto
					from mct_notificacion a
				    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
			       WHERE a.idnotificacion= 25;
			      
			      sp_texto  := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero);
				  sp_texto  := REPLACE(sp_texto,'_valor_entrega',rec_trab.fecha_termino);
			 
				  orden        :=  rec_trab.idordentrabajo;
				  asunto       :=  sp_asunto;
				  cuerpo       :=  sp_texto; 
				  emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
				  codigonotf   :=  0; 

				  update mct_progavisos 
			         set enviosolicitudpla = 1,
			             fechaenviosolicitudpla = now()
			       where idordentrabajo =  rec_trab.idordentrabajo
			         and idsla = 5;
				 
			      RETURN next;	
			           
			   end if;
			  
	  END LOOP;
             
	     
END;
$$;


