    	sp_fechatms				timestamp;
    	sp_fecha				varchar;
		intervalo               varchar;
	
	    fecha_mail				varchar;
         						    
begin
	
	
      FOR rec_trab IN (   
      
					select f.idordentrabajo ,
					       d.idnotificacion,
					       d.codigoarchivoinftecpdf ,
					       d.idusuarioresp ,
					       d.sigla ,
					       e.nombre,
					       to_char(f.fecha_termino,'dd-mm-yyyy') as fecha_termino,
					       date_part('day', now() - g.fecha_real_termino ),
					       g.fecha_autoriza_cliente ,
					       h.idordentrabajo ,
					       h.debaja ,
					       h.idfamilia ,
					       h.checklistvalido ,
					       g.fechaenviosolicitud
         			  from mct_notificacionlista a
         		      join mct_tipotrabajochecklist d on a.idnotificacion = d.idnotificacion
         		      left join mct_usuario e         on d.idusuarioresp  = e.idusuario 
         		      left join mct_progavisoschecklist f on d.sigla = f.sigla --and f.idordentrabajo in (30123,30184,30185,30163,30164)
         		      join mct_progavisos g on g.idordentrabajo = f.idordentrabajo and g.idsla = 5 and g.estado = 1 and g.enviosolicitud = 0 and date_part('day', now() - g.fecha_real_termino ) >= 0
         		      left join mct_ordentrabajo h on g.idordentrabajo = h.idordentrabajo 
         		     where a.idnotificacion in (19,20,21,22,23,47,48,50)
         		       and f.idordentrabajo >= 30000 
         		       --and f.idordentrabajo not in (30463, 30530,30531)
         		       and f.idordentrabajo not in (30463, 30530,30531, 31028, 31027, 31064)
         		       --and d.codigoarchivoinftecpdf in ( select cast(infcoti as varchar) from mct_infcotipdf where idordentrabajo = f.idordentrabajo and idproceso = 100)
          	           and ( (d.codigoarchivoinftecpdf in ( select cast(infcoti as varchar) from mct_infcotipdf where idordentrabajo = f.idordentrabajo and idproceso = 100))
         		           --or (h.idestadoorden != 9 and h.idordentrabajo not in (30679,30706,30805) )
         		           )
         		       and h.idfamilia != 11
                       and h.debaja < 1
                       and f.idordentrabajo = 34374    -- Cambiar OT aca SQZ
                       
         		       )
				
 
		loop 	

				select a.idusuario ,
				       b.nombre ,
				       c.nombreproducto ,
				       d.nombremodelo ,
				       e.sigla ,
				       coalesce(e.sigla||' '||d.nombremodelo||' '||f.nombreparam , 'S/N'),
				       a.idfamilia 
				  into sp_idusuario ,
				       sp_nombreingeniero,
				       sp_nombreproducto,
				       sp_nombremodelo,
				       sp_sigla,
				       sp_nombrebomba,
				       sp_familia
				  from mct_ordentrabajo a
				  join mct_usuario b         on a.idusuario = b.idusuario 
				  join mct_producto c        on a.idproducto = c.idproducto
				  join mct_modelo d          on c.idmodelo = d.idmodelo
				  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
				  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
			  	 where a.idordentrabajo = rec_trab.idordentrabajo;
  	
			   if ( sp_familia != 11) then
			   
			      sp_carga	:= 'SI';

			      select count(*)
			        into sp_cuentaaudit
			        from mct_auditoriachecklistvalido
			       where idordentrabajo = rec_trab.idordentrabajo;
			          			     
			      if (rec_trab.checklistvalido = false) then

			      	 sp_carga := 'NO';
			      					   
			         if ( sp_cuentaaudit = 0 ) then
			         
			            insert into mct_auditoriachecklistvalido  
			                   (idauditoriachecklistvalido,
							    idordentrabajo,
							    estado,
							    contador,
							    fechacreacion
							   )
							values 
							   (
								nextval('mct_auditoriachecklistvalido_seq'),
								rec_trab.idordentrabajo,
								1,
								1,
								now()
							   );
							
			         end if;
			      
			      else
			      
			          if ( sp_cuentaaudit > 0 ) then
			          
			             update mct_auditoriachecklistvalido
			                set estado = 0
			              where idordentrabajo = rec_trab.idordentrabajo;
			       	  
			          end if;
			      
			      end if;
			   
			      if ( sp_carga = 'SI') then

				   	  sp_lista := '';
						   
					  FOR rec_email IN (   
										select distinct c.emaildestino 
					         			  from mct_notificacionlista a,
					         				   mct_listaemail b,
					         		           mct_email c
					         		     where a.idnotificacion = rec_trab.idnotificacion
					         	           and a.idlista = b.idlista
					         		       and b.idemail = c.idemail 
										)
					     loop 	
							
							 sp_lista := rec_email.emaildestino||','||sp_lista;
							           
					  END LOOP;
			    
					  sp_asunto := '';
					  sp_texto  := '';
					 
					  if ( rec_trab.codigoarchivoinftecpdf = '50' ) then
					     sp_senor := sp_nombreingeniero;
					  else
					     sp_senor := rec_trab.nombre;
					  end if;
	
					  -- Para sacar fecha de compras y pañol
					  select round(salhorav) 
					    into sp_horas
					    from traking.calculahorasincumplimientos_test_v1(sp_fecha_hoy_ts, 79);
					 
					  intervalo := ''''||sp_horas||' hours';
					   
					  --select rec_trab.fechaenviosolicitud + intervalo::interval
					  select sp_fecha_hoy_ts + intervalo::interval
					    into sp_fechatms;
					   
					  fecha_mail	:= rec_trab.fecha_termino;
					  if (rec_trab.sigla in ('RPO','FAB_PA')) then
					      fecha_mail	:= to_char(sp_fechatms,'dd-mm-yyyy');
					  end if;
     
			          -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
					  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_responsable',sp_senor),'_val_ot',rec_trab.idordentrabajo::varchar),'_valor_modelo',sp_nombrebomba)::varchar ,
					         REPLACE(REPLACE(b.asunto,'_val_ot',rec_trab.idordentrabajo::varchar),'_val_modelo',sp_nombrebomba)
					    into sp_texto,
					         sp_asunto
						from mct_notificacion a
					    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
				       WHERE a.idnotificacion= rec_trab.idnotificacion;
				      
				      sp_texto  := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero);
					 -- sp_texto  := REPLACE(sp_texto,'_valor_entrega',rec_trab.fecha_termino);
					  sp_texto  := REPLACE(sp_texto,'_valor_entrega',fecha_mail);
				 
					  orden        :=  rec_trab.idordentrabajo;
					  asunto       :=  sp_asunto;
					  cuerpo       :=  sp_texto; 
					  emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
					 -- emaildestino := 'squijada@ndx.cl';
					  codigonotf   :=  rec_trab.codigoarchivoinftecpdf; 
					 
				  update mct_progavisos 
			         set enviosolicitud = 1,
			             --fechaenviosolicitud = now() sp_fecha_hoy_ts
			             fechaenviosolicitud = sp_fecha_hoy_ts
			       where idordentrabajo =  rec_trab.idordentrabajo
			        and idsla = 5;
			 			      
			      
				  RETURN next;	
					 			     
			    end if;
			     
			   
			end if;
		           
	  END LOOP;
      	 
 -- Esto inserta los registros en la tabla principal de Hojarutatemp
	  insert into mct_hojarutatemp (
	               idhojarutatemp, 
		           idordentrabajo, 
		           nombreplano, 
		           cantidad, 
		           usuariocreacion, 
		           fechacreacion, 
		           idimprimehojas, 
		           idboleano, 
		           idcriterioevaluacion, 
		           materialchecklist, 
		           componentechecklist,
		           textoadicional,
		           idcomponente ,
		           idmaterial ,
		           nombrematerial ,
		           idareaclasificacion,
		           nombrezona ,
		           idchecklistinftecvalido
		         )
			     select nextval('mct_hojarutatemp_seq'),
			            a.idordentrabajo ,
			            a.plano,
			            a.cantidad,
			            'admin',
			            now(),
			            2,
			            1,
			            b.idcriterioevaluacion ,
			            a.material,
			            a.nombreparte,
			            'N/A',
			            a.idcomponente ,
			            a.idmaterial ,
			            a.nombrematerial ,
			            coalesce (d.idareaclasificacion, 0) ,
			            a.nombrezona ,
			            a.idchecklistinftecvalido
			       from mct_checklistinftecvalido a
			       left join mct_criterioevaluacion b on a.criterio = b.nombrecriterioevaluacion
			       join mct_progavisos c on c.idordentrabajo = a.idordentrabajo and c.idsla = 5 and c.estado = 1 
			       left join mct_componente d on a.idcomponente = d.idcomponente 
			      where b.idcriterioevaluacion not in (5, 6)
			        and to_timestamp(to_char(c.fechaenviosolicitud, 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd') and c.enviosolicitud = 1 
			        and a.flagtraeurgente = false
			        and a.idordentrabajo = 34374    -- Cambiar OT aca SQZ
			        and not exists ( select 'x' from mct_hojarutatemp mh where idordentrabajo = a.idordentrabajo);
			   
	 FOR rec_hr IN (   
					 select distinct idordentrabajo 
					   from mct_hojarutatemp mh 
					  where to_timestamp(to_char(fechacreacion , 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd')
					  and mh.idordentrabajo = 34374    -- Cambiar OT aca SQZ
       		       )
					
		loop 
			
			
		    FOR rec_hr IN (   
							 select ROW_NUMBER() OVER (ORDER BY idareaclasificacion asc) + 3 AS item,
							        idhojarutatemp ,
							        idordentrabajo ,
							        idcomponente ,
							        cantidad ,
							        idimprimehojas ,
							        idareaclasificacion ,
							        idordentrabajo
							   from mct_hojarutatemp mh 
							  where idordentrabajo = rec_hr.idordentrabajo
							  --where to_timestamp(to_char(fechacreacion , 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd')	 		                       
		       		       )
							
				loop 	
				
					insert into mct_hojarutaactividadtemp 
			                (
			                idhojarutaactividadtemp ,
			                idhojarutatemp ,
			                idactividad ,
			                tiempoproduccion ,
			                orden 
			                )        	     
							select nextval('mct_hojarutaactividadtemp_seq'),
							       rec_hr.idhojarutatemp,
							       a.idactividad , 
							       a.tiempoproduccion , 
							       a.orden 
							  from mct_partetipotrabajoactividad a 
							 where a.idpartetipotrabajo = ( select idcomponentetipotrabajo 
													        from mct_componentetipotrabajo 
													       where idcomponente  = rec_hr.idcomponente
													         and idtipotrabajo in (21))
							order by idpartetipotrabajoactividad  asc, orden asc;
				
		
						
				    if ( rec_hr.idimprimehojas = 1 ) then
			    
				       tope  := 1;
				      
				    else
				 
				    	tope := coalesce(rec_hr.cantidad,0);
				    
				    end if;
		 
				    sp_idmaxcorr := 0;
				   				
				   
				    if ( sp_idmaxcorr > 0 ) then
				        indice := sp_idmaxcorr + 1;
				    else
						indice := 1;
		            end if;
				
					loop						
					
						sp_hrchar   := LPAD(rec_hr.idordentrabajo::integer::text::varchar, 6, '0');  
						sp_partchar := LPAD(rec_hr.idcomponente::integer::text::varchar, 3, '0');
						sp_itemchar := LPAD(rec_hr.item::integer::text::varchar, 2, '0'); 	
						sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
						
						insert into mct_detallehojarutatemp 
						           (iddetallehojarutatemp 
						           ,idhojarutatemp 
						           ,codhojaruta 
						           ,correlativoparte
						           ,item
						           )
						     VALUES
						           (nextval('traking.mct_detallehojarutatemp_seq')
						           ,rec_hr.idhojarutatemp
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,indice
						           ,rec_hr.item
						           );                     
				
						         
						sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
					
						insert into mct_ordentrabajoparte 
						           (idordentrabajoparte 
						           ,idordentrabajo 
						           ,idcomponente 
						           ,itemparte
						           ,itemcorr 
						           )
						     VALUES
						           (sp_idpwo
						           ,rec_hr.idordentrabajo
						           ,rec_hr.idcomponente 
						           ,indice
						           ,rec_hr.item
						           );   
				
		 				-- Esto es para igualar la tabla Hoja Ruta
					    insert into mct_hojaruta 
						           (idhojaruta 
						           ,idordentrabajoparte 
						           ,codhojaruta 
						           ,usuariocreacion 
						           ,fechacreacion
						           ,modalidad 
						           ,idhojarutatemp 
						           )
						     VALUES
						           (nextval('traking.mct_hojaruta_seq')
						           ,sp_idpwo
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,'admin' 
						           ,now()
						           ,1
						           ,rec_hr.idhojarutatemp
						           ); 
						          
						 indice := indice + 1; 
						                           				   
						 EXIT when indice > tope;
						                    
					END loop;  		
				
				
			  	END LOOP;				
			
		end loop;
		 		       			       
END;
$$;


ALTER FUNCTION traking.evtlistmaildistottrabajossol() OWNER TO postgres;

--
-- TOC entry 2316 (class 1255 OID 17122)
-- Name: evtlistmaildistottrabajossol_manual(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistottrabajossol_manual(idordentrabajos bigint) RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;			
	   
	   -- Desde aca para generar las Hojas de rutas automaticas
	    rec_hr					RECORD;
	   
        indice   				INTEGER;
        tope	   				INTEGER;	
  
        sp_hrchar               TEXT;
        sp_partchar             TEXT;
        sp_itemchar             TEXT;
        sp_corrchar             TEXT;
       
        sp_idpwo   				INTEGER;     
        sp_idmaxcorr			integer;
       
       	sp_carga				varchar;
        sp_cuentaaudit			integer;
         						    
begin
	 
-- Esto inserta los registros en la tabla principal de Hojarutatemp
	  insert into mct_hojarutatemp (
	               idhojarutatemp, 
		           idordentrabajo, 
		           nombreplano, 
		           cantidad, 
		           usuariocreacion, 
		           fechacreacion, 
		           idimprimehojas, 
		           idboleano, 
		           idcriterioevaluacion, 
		           materialchecklist, 
		           componentechecklist,
		           textoadicional,
		           idcomponente ,
		           idmaterial ,
		           nombrematerial ,
		           idareaclasificacion,
		           nombrezona ,
		           idchecklistinftecvalido
		         )
			     select nextval('mct_hojarutatemp_seq'),
			            a.idordentrabajo ,
			            a.plano,
			            a.cantidad,
			            'admin',
			            now(),
			            2,
			            1,
			            b.idcriterioevaluacion ,
			            a.material,
			            a.nombreparte,
			            'N/A',
			            a.idcomponente ,
			            a.idmaterial ,
			            a.nombrematerial ,
			            coalesce (d.idareaclasificacion, 0) ,
			            a.nombrezona ,
			            a.idchecklistinftecvalido
			       from mct_checklistinftecvalido a
			       left join mct_criterioevaluacion b on a.criterio = b.nombrecriterioevaluacion
			       join mct_progavisos c on c.idordentrabajo = a.idordentrabajo and c.idsla = 5 and c.estado = 1 
			       left join mct_componente d on a.idcomponente = d.idcomponente 
			      where b.idcriterioevaluacion not in (5, 6)
			        --and to_timestamp(to_char(c.fechaenviosolicitud, 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd') and c.enviosolicitud = 1 
			        and a.flagtraeurgente = false
			        and a.idordentrabajo = idordentrabajos;
			        --and not exists ( select 'x' from mct_hojarutatemp mh where idordentrabajo = a.idordentrabajo);
			   
	 FOR rec_hr IN (   
					 select distinct idordentrabajo
					   from mct_hojarutatemp mh 
					  where mh.idordentrabajo = idordentrabajos
       		       )
					
		loop 
			
			
		    FOR rec_hr IN (   
							 select ROW_NUMBER() OVER (ORDER BY idareaclasificacion asc) + 3 AS item,
							        idhojarutatemp ,
							        idordentrabajo ,
							        idcomponente ,
							        cantidad ,
							        idimprimehojas ,
							        idareaclasificacion ,
							        idordentrabajo
							   from mct_hojarutatemp mh 
							  where idordentrabajo = rec_hr.idordentrabajo
							  --where to_timestamp(to_char(fechacreacion , 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd')	 		                       
		       		       )
							
				loop 	
				
					insert into mct_hojarutaactividadtemp 
			                (
			                idhojarutaactividadtemp ,
			                idhojarutatemp ,
			                idactividad ,
			                tiempoproduccion ,
			                orden 
			                )        	     
							select nextval('mct_hojarutaactividadtemp_seq'),
							       rec_hr.idhojarutatemp,
							       a.idactividad , 
							       a.tiempoproduccion , 
							       a.orden 
							  from mct_partetipotrabajoactividad a 
							 where a.idpartetipotrabajo = ( select idcomponentetipotrabajo 
													        from mct_componentetipotrabajo 
													       where idcomponente  = rec_hr.idcomponente
													         and idtipotrabajo in (21))
							order by idpartetipotrabajoactividad  asc, orden asc;
				
		
						
				    if ( rec_hr.idimprimehojas = 1 ) then
			    
				       tope  := 1;
				      
				    else
				 
				       tope := coalesce(rec_hr.cantidad,0);
				    
				    end if;
		 
					indice := 1;
				
					loop						
					
						sp_hrchar   := LPAD(rec_hr.idordentrabajo::integer::text::varchar, 6, '0');  
						sp_partchar := LPAD(rec_hr.idcomponente::integer::text::varchar, 3, '0');
						sp_itemchar := LPAD(rec_hr.item::integer::text::varchar, 2, '0'); 	
						sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
						
						insert into mct_detallehojarutatemp 
						           (iddetallehojarutatemp 
						           ,idhojarutatemp 
						           ,codhojaruta 
						           ,correlativoparte
						           ,item
						           )
						     VALUES
						           (nextval('traking.mct_detallehojarutatemp_seq')
						           ,rec_hr.idhojarutatemp
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,indice
						           ,rec_hr.item
						           );                     
				
						         
						sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
					
						insert into mct_ordentrabajoparte 
						           (idordentrabajoparte 
						           ,idordentrabajo 
						           ,idcomponente 
						           ,itemparte
						           ,itemcorr 
						           )
						     VALUES
						           (sp_idpwo
						           ,rec_hr.idordentrabajo
						           ,rec_hr.idcomponente 
						           ,indice
						           ,rec_hr.item
						           );   
				
		 				--Esto es para igualar la tabla Hoja Ruta
					    insert into mct_hojaruta 
						           (idhojaruta 
						           ,idordentrabajoparte 
						           ,codhojaruta 
						           ,usuariocreacion 
						           ,fechacreacion
						           ,modalidad 
						           ,idhojarutatemp 
						           )
						     VALUES
						           (nextval('traking.mct_hojaruta_seq')
						           ,sp_idpwo
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,'admin' 
						           ,now()
						           ,1
						           ,rec_hr.idhojarutatemp
						           ); 
						          
						 indice := indice + 1;
						                           				   
						 EXIT when indice > tope;
						                    
					END loop;  		
				
				
			  	END LOOP;				
			
		end loop;
		
 		     	       
END;
$$;


ALTER FUNCTION traking.evtlistmaildistottrabajossol_manual(idordentrabajos bigint) OWNER TO postgres;

--
-- TOC entry 1140 (class 1255 OID 17124)
-- Name: evtlistmaildistottrabajossol_pruebaduplicado(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistottrabajossol_pruebaduplicado() RETURNS void
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;			
	   
	   -- Desde aca para generar las Hojas de rutas automaticas
	    rec_hr					RECORD;
	   
	    rec_ot					RECORD;
	   
        indice   				INTEGER;
        tope	   				INTEGER;	
  
        sp_hrchar               TEXT;
        sp_partchar             TEXT;
        sp_itemchar             TEXT;
        sp_corrchar             TEXT;
       
        sp_idpwo   				INTEGER;     
        sp_idmaxcorr			integer;
       
       	sp_carga				varchar;
        sp_cuentaaudit			integer;
       
        sp_idot					integer;
         						    
begin
	
	 FOR rec_hr IN (   
					 select distinct idordentrabajo
					   from mct_hojarutatemp mh 
					  where to_timestamp(to_char(fechacreacion , 'yyyy-mm-dd'), 'yyyy-mm-dd') = '2022-05-09'
       		       )
					
		loop 
			

		    FOR rec_hr IN (   
							 select ROW_NUMBER() OVER (ORDER BY idordentrabajo asc, idareaclasificacion asc) + 3 AS item,
							        idhojarutatemp ,
							        idordentrabajo ,
							        idcomponente ,
							        cantidad ,
							        idimprimehojas ,
							        idareaclasificacion ,
							        idordentrabajo
							   from mct_hojarutatemp mh 
							  where idordentrabajo = rec_hr.idordentrabajo--to_timestamp(to_char(fechacreacion , 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd')	 c
		       		       )
							
				loop 	
						
				    if ( rec_hr.idimprimehojas = 1 ) then
			    
				       tope  := 1;
				      
				    else
				 
				    	tope := coalesce(rec_hr.cantidad,0);
				    
				    end if;
		 
				    --sp_idmaxcorr := 0;
				   				
				   
				    --if ( sp_idmaxcorr > 0 ) then
				    --    indice := sp_idmaxcorr + 1;
				    --else
						indice := 1;
		            --end if;
				
					loop						
					
						sp_hrchar   := LPAD(rec_hr.idordentrabajo::integer::text::varchar, 6, '0');  
						sp_partchar := LPAD(rec_hr.idcomponente::integer::text::varchar, 3, '0');
						sp_itemchar := LPAD(rec_hr.item::integer::text::varchar, 2, '0'); 	
						sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
						
						insert into mct_detallehojarutatemp_pruebaduplicado 
						           (iddetallehojarutatemp 
						           ,idhojarutatemp 
						           ,codhojaruta 
						           ,correlativoparte
						           ,item
						           )
						     VALUES
						           (nextval('traking.mct_detallehojarutatemp_pruebaduplicado_seq')
						           ,rec_hr.idhojarutatemp
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,indice
						           ,rec_hr.item
						           );                     
				
						          
						 indice := indice + 1;
						                           				   
						 EXIT when indice > tope;
						                    
					END loop;  		
				
				
			  	END LOOP;					
			
			
		end loop;
		
	  
 	       
			       
END;
$$;


ALTER FUNCTION traking.evtlistmaildistottrabajossol_pruebaduplicado() OWNER TO postgres;

--
-- TOC entry 1396 (class 1255 OID 17125)
-- Name: evtlistmaildistottrabajossol_testsq(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistottrabajossol_testsq() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;			
	   
	   -- Desde aca para generar las Hojas de rutas automaticas
	    rec_hr					RECORD;
	   
        indice   				INTEGER;
        tope	   				INTEGER;	
  
        sp_hrchar               TEXT;
        sp_partchar             TEXT;
        sp_itemchar             TEXT;
        sp_corrchar             TEXT;
       
        sp_idpwo   				INTEGER;     
        sp_idmaxcorr			integer;
       
       	sp_carga				varchar;
        sp_cuentaaudit			integer;
         						    
begin
	
	
      FOR rec_trab IN (   
      
					select f.idordentrabajo ,
					       d.idnotificacion,
					       d.codigoarchivoinftecpdf ,
					       d.idusuarioresp ,
					       d.sigla ,
					       e.nombre,
					       to_char(f.fecha_termino,'dd-mm-yyyy') as fecha_termino,
					       date_part('day', now() - g.fecha_real_termino ),
					       g.fecha_autoriza_cliente ,
					       h.idordentrabajo ,
					       h.debaja ,
					       h.idfamilia ,
					       h.checklistvalido 
         			  from mct_notificacionlista a
         		      join mct_tipotrabajochecklist d on a.idnotificacion = d.idnotificacion
         		      left join mct_usuario e         on d.idusuarioresp  = e.idusuario 
         		      left join mct_progavisoschecklist f on d.sigla = f.sigla --and f.idordentrabajo in (30123,30184,30185,30163,30164)
         		      join mct_progavisos g on g.idordentrabajo = f.idordentrabajo and g.idsla = 5 and g.estado = 1 and g.enviosolicitud = 0 and date_part('day', now() - g.fecha_real_termino ) >= 0
         		      left join mct_ordentrabajo h on g.idordentrabajo = h.idordentrabajo 
         		     where a.idnotificacion in (19,20,21,22,23,47,48)
         		       and f.idordentrabajo >= 30000 
         		       --and f.idordentrabajo not in (30463, 30530,30531)
         		       and f.idordentrabajo not in (30463, 30530,30531, 31028, 31027, 31064)
         		       --and d.codigoarchivoinftecpdf in ( select cast(infcoti as varchar) from mct_infcotipdf where idordentrabajo = f.idordentrabajo and idproceso = 100)
          	           and ( (d.codigoarchivoinftecpdf in ( select cast(infcoti as varchar) from mct_infcotipdf where idordentrabajo = f.idordentrabajo and idproceso = 100))
         		           --or (h.idestadoorden != 9 and h.idordentrabajo not in (30679,30706,30805) )
         		           )
         		       and h.idfamilia != 11
                       and h.debaja < 1
                       and f.idordentrabajo = 31640
                       
         		       )
				
 
		loop 	

				select a.idusuario ,
				       b.nombre ,
				       c.nombreproducto ,
				       d.nombremodelo ,
				       e.sigla ,
				       e.sigla||' '||d.nombremodelo||' '||f.nombreparam ,
				       a.idfamilia 
				  into sp_idusuario ,
				       sp_nombreingeniero,
				       sp_nombreproducto,
				       sp_nombremodelo,
				       sp_sigla,
				       sp_nombrebomba,
				       sp_familia
				  from mct_ordentrabajo a
				  join mct_usuario b         on a.idusuario = b.idusuario 
				  join mct_producto c        on a.idproducto = c.idproducto
				  join mct_modelo d          on c.idmodelo = d.idmodelo
				  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
				  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
			  	 where a.idordentrabajo = rec_trab.idordentrabajo;
  	
			   if ( sp_familia != 11) then
			   
			      sp_carga	:= 'SI';

			      select count(*)
			        into sp_cuentaaudit
			        from mct_auditoriachecklistvalido
			       where idordentrabajo = rec_trab.idordentrabajo;
			          			     
			      if (rec_trab.checklistvalido = false) then

			      	 sp_carga := 'NO';
			      					   
			         if ( sp_cuentaaudit = 0 ) then
			         
			            insert into mct_auditoriachecklistvalido  
			                   (idauditoriachecklistvalido,
							    idordentrabajo,
							    estado,
							    contador,
							    fechacreacion
							   )
							values 
							   (
								nextval('mct_auditoriachecklistvalido_seq'),
								rec_trab.idordentrabajo,
								1,
								1,
								now()
							   );
							
			         end if;
			      
			      else
			      
			          if ( sp_cuentaaudit > 0 ) then
			          
			             update mct_auditoriachecklistvalido
			                set estado = 0
			              where idordentrabajo = rec_trab.idordentrabajo;
			       	  
			          end if;
			      
			      end if;
			   
			      if ( sp_carga = 'SI') then

				   	  sp_lista := '';
						   
					  FOR rec_email IN (   
										select distinct c.emaildestino 
					         			  from mct_notificacionlista a,
					         				   mct_listaemail b,
					         		           mct_email c
					         		     where a.idnotificacion = rec_trab.idnotificacion
					         	           and a.idlista = b.idlista
					         		       and b.idemail = c.idemail 
										)
					     loop 	
							
							 sp_lista := rec_email.emaildestino||','||sp_lista;
							           
					  END LOOP;
			    
					  sp_asunto := '';
					  sp_texto  := '';
					 
					  if ( rec_trab.codigoarchivoinftecpdf = '50' ) then
					     sp_senor := sp_nombreingeniero;
					  else
					     sp_senor := rec_trab.nombre;
					  end if;
	
			          	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
					  select REPLACE(REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_valor_responsable',sp_senor),'_val_ot',rec_trab.idordentrabajo::varchar),'_valor_modelo',sp_nombrebomba)::varchar ,
					         REPLACE(REPLACE(b.asunto,'_val_ot',rec_trab.idordentrabajo::varchar),'_val_modelo',sp_nombrebomba)
					    into sp_texto,
					         sp_asunto
						from mct_notificacion a
					    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
				       WHERE a.idnotificacion= rec_trab.idnotificacion;
				      
				      sp_texto  := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero);
					  sp_texto  := REPLACE(sp_texto,'_valor_entrega',rec_trab.fecha_termino);
				 
					  orden        :=  rec_trab.idordentrabajo;
					  asunto       :=  sp_asunto;
					  cuerpo       :=  sp_texto; 
					  emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
					 -- emaildestino := 'squijada@ndx.cl';
					  codigonotf   :=  rec_trab.codigoarchivoinftecpdf; 
					 
				  update mct_progavisos 
			         set enviosolicitud = 1,
			             fechaenviosolicitud = now()
			       where idordentrabajo =  rec_trab.idordentrabajo
			        and idsla = 5;
	--				 			      
			      
					  RETURN next;	
					 			     
			      end if;
			     
			   
			   end if;
		           
	  END LOOP;
      
	 
-- Esto inserta los registros en la tabla principal de Hojarutatemp
	  insert into mct_hojarutatemp (
	               idhojarutatemp, 
		           idordentrabajo, 
		           nombreplano, 
		           cantidad, 
		           usuariocreacion, 
		           fechacreacion, 
		           idimprimehojas, 
		           idboleano, 
		           idcriterioevaluacion, 
		           materialchecklist, 
		           componentechecklist,
		           textoadicional,
		           idcomponente ,
		           idmaterial ,
		           nombrematerial ,
		           idareaclasificacion,
		           nombrezona 
		         )
			     select nextval('mct_hojarutatemp_seq'),
			            a.idordentrabajo ,
			            a.plano,
			            a.cantidad,
			            'admin',
			            now(),
			            2,
			            1,
			            b.idcriterioevaluacion ,
			            a.material,
			            a.nombreparte,
			            'N/A',
			            a.idcomponente ,
			            a.idmaterial ,
			            a.nombrematerial ,
			            coalesce (d.idareaclasificacion, 0) ,
			            a.nombrezona 
			       from mct_checklistinftecvalido a
			       left join mct_criterioevaluacion b on a.criterio = b.nombrecriterioevaluacion
			       join mct_progavisos c on c.idordentrabajo = a.idordentrabajo and c.idsla = 5 and c.estado = 1 
			       left join mct_componente d on a.idcomponente = d.idcomponente 
			      where b.idcriterioevaluacion not in (5, 6)
			        and to_timestamp(to_char(c.fechaenviosolicitud, 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd') and c.enviosolicitud = 1 
			        and a.flagtraeurgente = false
			        and a.idordentrabajo = 31640
			        and not exists ( select 'x' from mct_hojarutatemp mh where idordentrabajo = a.idordentrabajo);
			   
	 FOR rec_hr IN (   
					 select distinct idordentrabajo
					   from mct_hojarutatemp mh 
					  where to_timestamp(to_char(fechacreacion , 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd')
					  and mh.idordentrabajo = 31640
       		       )
					
		loop 
			
			
		    FOR rec_hr IN (   
							 select ROW_NUMBER() OVER (ORDER BY idareaclasificacion asc) + 3 AS item,
							        idhojarutatemp ,
							        idordentrabajo ,
							        idcomponente ,
							        cantidad ,
							        idimprimehojas ,
							        idareaclasificacion ,
							        idordentrabajo
							   from mct_hojarutatemp mh 
							  where idordentrabajo = rec_hr.idordentrabajo
							  --where to_timestamp(to_char(fechacreacion , 'yyyy-mm-dd'), 'yyyy-mm-dd') = to_timestamp(to_char(current_date, 'yyyy-mm-dd'), 'yyyy-mm-dd')	 		                       
		       		       )
							
				loop 	
				
					insert into mct_hojarutaactividadtemp 
			                (
			                idhojarutaactividadtemp ,
			                idhojarutatemp ,
			                idactividad ,
			                tiempoproduccion ,
			                orden 
			                )        	     
							select nextval('mct_hojarutaactividadtemp_seq'),
							       rec_hr.idhojarutatemp,
							       a.idactividad , 
							       a.tiempoproduccion , 
							       a.orden 
							  from mct_partetipotrabajoactividad a 
							 where a.idpartetipotrabajo = ( select idcomponentetipotrabajo 
													        from mct_componentetipotrabajo 
													       where idcomponente  = rec_hr.idcomponente
													         and idtipotrabajo in (21))
							order by idpartetipotrabajoactividad  asc, orden asc;
				
		
						
				    if ( rec_hr.idimprimehojas = 1 ) then
			    
				       tope  := 1;
				      
				    else
				 
				    	tope := coalesce(rec_hr.cantidad,0);
				    
				    end if;
		 
				    --sp_idmaxcorr := 0;
				   				
				   
				    --if ( sp_idmaxcorr > 0 ) then
				    --    indice := sp_idmaxcorr + 1;
				    --else
						indice := 1;
		            --end if;
				
					loop						
					
						sp_hrchar   := LPAD(rec_hr.idordentrabajo::integer::text::varchar, 6, '0');  
						sp_partchar := LPAD(rec_hr.idcomponente::integer::text::varchar, 3, '0');
						sp_itemchar := LPAD(rec_hr.item::integer::text::varchar, 2, '0'); 	
						sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
						
						insert into mct_detallehojarutatemp 
						           (iddetallehojarutatemp 
						           ,idhojarutatemp 
						           ,codhojaruta 
						           ,correlativoparte
						           ,item
						           )
						     VALUES
						           (nextval('traking.mct_detallehojarutatemp_seq')
						           ,rec_hr.idhojarutatemp
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,indice
						           ,rec_hr.item
						           );                     
				
						         
						sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
					
						insert into mct_ordentrabajoparte 
						           (idordentrabajoparte 
						           ,idordentrabajo 
						           ,idcomponente 
						           ,itemparte
						           ,itemcorr 
						           )
						     VALUES
						           (sp_idpwo
						           ,rec_hr.idordentrabajo
						           ,rec_hr.idcomponente 
						           ,indice
						           ,rec_hr.item
						           );   
				
		 				--Esto es para igualar la tabla Hoja Ruta
					    insert into mct_hojaruta 
						           (idhojaruta 
						           ,idordentrabajoparte 
						           ,codhojaruta 
						           ,usuariocreacion 
						           ,fechacreacion
						           ,modalidad 
						           ,idhojarutatemp 
						           )
						     VALUES
						           (nextval('traking.mct_hojaruta_seq')
						           ,sp_idpwo
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,'admin' 
						           ,now()
						           ,1
						           ,rec_hr.idhojarutatemp
						           ); 
						          
						 indice := indice + 1;
						                           				   
						 EXIT when indice > tope;
						                    
					END loop;  		
				
				
			  	END LOOP;				
			
		end loop;
		
 		       
			       
END;
$$;


ALTER FUNCTION traking.evtlistmaildistottrabajossol_testsq() OWNER TO postgres;

--
-- TOC entry 1557 (class 1255 OID 17127)
-- Name: evtlistmaildistottrabajossolvalidate(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistottrabajossolvalidate() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;		
	   
	    sp_salida				integer;
         						    
begin
	
	  sp_salida := 0;
	 
      FOR rec_trab IN (   
                    select a.idauditoriachecklistvalido,
                           a.idordentrabajo,
                           a.estado,
                           a.contador,
                           a.fechacreacion,
                           date_part('dow', a.fechacreacion) as diasem,
                           date_part('day', now() - a.fechacreacion ) as dife,
                           ( EXTRACT(EPOCH FROM now())-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600 as horas,
                           date_part('day', now() - a.fechacreacion) as dias,
                           c.nombre ,
                           d.nombrecliente,
                           b.idproducto,
                           g.sigla||' '||f.nombreneptuno||' '||h.nombreparam as bomba
                      from mct_auditoriachecklistvalido a,
                           mct_ordentrabajo b,
                           mct_usuario c,
                           mct_cliente d,                           
                           mct_producto e,
                           mct_modelo f,
                           mct_subfamilia g,
                           mct_etapaparam h
                     where a.estado = 1
                       and a.idordentrabajo = b.idordentrabajo
                       and a.idordentrabajo not in (32246, 32247)
                       and b.idusuario = c.idusuario 
                       and b.idcliente = d.idcliente 
                       and b.idproducto = e.idproducto
                       and e.idmodelo = f.idmodelo
                       and f.idsubfamilia = g.idsubfamilia 
                       and e.idetapaparam = h.idetapaparam 
                       and b.idestadoorden < 9
                       and b.idtipoorden in (1,2)
					)
				
		loop 	
  	
			      if (rec_trab.diasem in (0,1,2,3,4)) then
			      
			         --if (rec_trab.horas >= 48) then
			         if (rec_trab.dias >= 2) then
			            
			             sp_salida := 1;
			         
			         else
			          
			             sp_salida := 0;
			         
			         end if;
			      
			      elsif (rec_trab.diasem in (5,6)) then
			      
					 --if (rec_trab.horas >= 72) then
					 if (rec_trab.dias >= 3) then
			            
			             sp_salida := 1;
			         
			         else
			          
			             sp_salida := 0;
			         
			         end if;			      
			      
			      end if;

			     if (sp_salida = 1) then
			     
				      sp_lista := '';
						   
					  FOR rec_email IN (   
										select distinct c.emaildestino 
					         			  from mct_notificacionlista a,
					         				   mct_listaemail b,
					         		           mct_email c
					         		     where a.idnotificacion = 54
					         	           and a.idlista = b.idlista
					         		       and b.idemail = c.idemail 
										)
					     loop 	
							
							 sp_lista := rec_email.emaildestino||','||sp_lista;
							           
					  END LOOP;
			    
					  sp_asunto := '';
					  sp_texto  := '';
					 
					 
			          	 -- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
					  select b.cuerpo,
					         REPLACE(b.asunto,'_valor_ot',rec_trab.idordentrabajo::varchar)
					    into sp_texto,
					         sp_asunto
						from mct_notificacion a
					    JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
				       WHERE a.idnotificacion= 54;
				      
				      sp_texto  := REPLACE(sp_texto,'_valor_ingeniero',rec_trab.nombre);
				      sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
				      sp_texto  := REPLACE(sp_texto,'_valor_ot',rec_trab.idordentrabajo::varchar);
				      sp_texto  := REPLACE(sp_texto,'_aviso',rec_trab.contador::varchar);
				      sp_texto  := REPLACE(sp_texto,'_valor_cliente',rec_trab.nombrecliente::varchar);
				      sp_texto  := REPLACE(sp_texto,'_valor_producto',rec_trab.bomba::varchar);
				     
				      sp_asunto  := REPLACE(sp_asunto,'_aviso',rec_trab.contador::varchar);
				 
					  orden        :=  rec_trab.idordentrabajo;
					  asunto       :=  sp_asunto;
					  cuerpo       :=  sp_texto; 
					  emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
					  codigonotf   :=  0; 
	
	
				      RETURN next;	
				     
				      update mct_auditoriachecklistvalido
				         set contador = contador + 1
				       where idauditoriachecklistvalido = rec_trab.idauditoriachecklistvalido;			     
			     
			     end if;
			           
			  
	  END LOOP;
             
	     
END;
$$;


ALTER FUNCTION traking.evtlistmaildistottrabajossolvalidate() OWNER TO postgres;

--
-- TOC entry 1733 (class 1255 OID 17128)
-- Name: evtlistmaildistpendientedespacho(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistpendientedespacho() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying, archivo text, nombrearchivo character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
        sp_anno                 VARCHAR=to_char(now(),'YYYY');

	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_salida				integer;
	   
	    sp_ot					bigint;
		sp_nombrecomp			varchar;
		sp_nombremat			varchar;
		sp_responsable			varchar;
	
	    sp_horas				bigint;
	   
	    sp_idusuario 			bigint;
		sp_nombremodelo			varchar;
		sp_sigla				varchar;
		sp_nombrebomba			varchar;
		sp_cliente				varchar;
		sp_idtipoorden			bigint;
		sp_idfamilia			bigint;
		sp_idproducto			bigint;
	
	    sp_fechaentrega			varchar;
	    sp_fechaemenos7			varchar;
	   
	    sp_fechapendientedesp	timestamp;
        sp_fechaclte			timestamp;
	    sp_fechamail			varchar;

		sp_dias					bigint;
        sp_status				varchar;
	   
	    sp_origen				varchar;
	   	sp_elementod			varchar;
	   
	    sp_archivo				text;
	    sp_nombrearchivo		varchar;

        sp_evaluador			varchar;

		sp_notif				bigint;
         						    
begin

	  sp_salida := 0;	 
	 
	  FOR rec_trab IN (   
				select idworkorder,
				       username,
				       ordertypename||'_'||familyname as origen,
				       productname,
				       customername,
				       advance,
				       itemot,
				       statusdispatch, 
				       statuscliente 
		          from traking.evtlistmanagerscreenfamiliafacturacion_pendientedespacho(-1, 'NA', 'NA')
		 	)
	       loop
		    
		       select replace(a.archivoadjunto , 'data:application/pdf;base64,',''),
		              a.nombrearchivo 
		         into sp_archivo,
	                  sp_nombrearchivo
		         from mct_infcotipdf a 
		        where a.idordentrabajo = rec_trab.idworkorder
		          and a.infcoti = 10
		          and a.idproceso = 2;
		       

		       select a.fechamarcapendientedespacho,
                      --fechafaceclte,
                      --cast(date_part('days', fechafaceclte - coalesce(fechamarcapendientedespacho,current_date)) as bigint),
		              a.idfamilia,
                      b.email
		         into sp_fechapendientedesp,
                      --sp_fechaclte,
                      --sp_dias,
		              sp_idfamilia,
                      sp_evaluador
		         from mct_ordentrabajo a 
                 left join mct_usuario b on a.idusuario = b.idusuario
		        where a.idordentrabajo = rec_trab.idworkorder;

			   --if (sp_dias >= 0) then
				--	sp_status := 'EN TIEMPO';
			   --else
				--	sp_status := 'ATRASADA';
			   --end if;

		       raise notice '%', sp_fechapendientedesp;
		       if sp_fechapendientedesp is null then
		          update mct_ordentrabajo 
		             set fechamarcapendientedespacho = current_date,
		                 fecha100tm = now(),
		                 dias100tm = rec_trab.statusdispatch,
		                 dias100clte = rec_trab.statuscliente
		           where idordentrabajo = rec_trab.idworkorder;
		          
		          sp_fechapendientedesp	:= current_date;
		         
		       end if;
		      
		       select coalesce(fechamarcapendientedespacho,current_date),
                      fechafaceclte,
                      cast(date_part('days', fechafaceclte - coalesce(fechamarcapendientedespacho,current_date)) as bigint),
		              idfamilia
		         into sp_fechapendientedesp,
                      sp_fechaclte,
                      sp_dias,
		              sp_idfamilia
		         from mct_ordentrabajo mo 
		        where idordentrabajo = rec_trab.idworkorder;

			   if (sp_dias >= 0) then
					sp_status := 'EN TIEMPO';
			   else
					sp_status := 'ATRASADA';
			   end if;

		       sp_origen	:= '';
		       if sp_idfamilia in (8,10) then 
		          select to_char(sp_fechapendientedesp + interval '5 days', 'dd/mm/yyyy')
		            into sp_fechamail;

				  sp_notif := 84;

		       else
		          select to_char(sp_fechapendientedesp + interval '3 days', 'dd/mm/yyyy')
		            into sp_fechamail;

				  sp_notif := 96;

		       end if;
		      
		       -- Lista de correos
		       sp_lista 	:= '';
					   
			   FOR rec_email IN (   
							select distinct c.emaildestino 
						      from mct_notificacionlista a,
					   			   mct_listaemail b,
			   		               mct_email c
						     where a.idnotificacion = sp_notif
					           and a.idlista = b.idlista
						       and b.idemail = c.idemail 
					 	)
				    loop 	
								
						sp_lista := rec_email.emaildestino||','||sp_lista;
								           
			   end loop;
				    
			   sp_asunto := '';
			   sp_texto  := '';
			  
			   -- Saca datos del mail
			   select b.cuerpo,
			          b.asunto
				 into sp_texto,
			          sp_asunto
				 from mct_notificacion a
			     JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		        WHERE a.idnotificacion = sp_notif;
	
		       sp_elementod	:= '';
		      
		       if (sp_idfamilia = 11) then
		       
		           select '/ '||textoadicional 
		             into sp_elementod
		             from mct_hojarutatemp mh 
				    where idordentrabajo = rec_trab.idworkorder;
		        		       		
		       end if;
		       
		       sp_texto  := REPLACE(sp_texto,'_valor_ot',rec_trab.idworkorder::varchar);
		       sp_texto  := REPLACE(sp_texto,'_valor_equipo',rec_trab.productname::varchar);			   
		       sp_texto  := REPLACE(sp_texto,'_valor_cliente',rec_trab.customername::varchar);
		       sp_texto  := REPLACE(sp_texto,'_valor_ed',sp_elementod::varchar);
		
			   sp_texto  := REPLACE(sp_texto,'_val_fecha_despacho',sp_fechamail);
		       
			   sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);

			   sp_texto  := REPLACE(sp_texto,'_val_fechaclte',to_char(sp_fechaclte, 'dd/mm/yyyy'));
               sp_texto  := REPLACE(sp_texto,'_val_fecha_mec',to_char(sp_fechapendientedesp, 'dd/mm/yyyy'));
               sp_texto  := REPLACE(sp_texto,'_val_dias',sp_dias::varchar);
               sp_texto  := REPLACE(sp_texto,'_val_estatus',sp_status);
									     
			   sp_asunto  := REPLACE(sp_asunto,'_valor_bba_ed',rec_trab.origen::varchar);
			   sp_asunto  := REPLACE(sp_asunto,'_valor_ot',rec_trab.idworkorder::varchar);

			   sp_asunto  := REPLACE(sp_asunto,'_val_anno',sp_anno::varchar);
	
			   orden        	:=  rec_trab.idworkorder;
		  	   asunto       	:=  sp_asunto;
			   cuerpo       	:=  sp_texto; 
			   emaildestino 	:=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar)||','||sp_evaluador;
			   codigonotf   	:=  sp_notif; 
			   archivo			:=  sp_archivo;
			   nombrearchivo	:= sp_nombrearchivo;
	
		    RETURN next;	
   
	  end loop;
		        
END;
$$;


ALTER FUNCTION traking.evtlistmaildistpendientedespacho() OWNER TO postgres;

--
-- TOC entry 1345 (class 1255 OID 17130)
-- Name: evtlistmaildistpendientedespachoincumplimiento(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistpendientedespachoincumplimiento() RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE
	   
	    sp_familia              integer;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_salida				integer;
	   
	    sp_ot					bigint;
		sp_nombrecomp			varchar;
		sp_nombremat			varchar;
		sp_responsable			varchar;
	
	    sp_horas				bigint;
	   
	    sp_idusuario 			bigint;
		sp_nombremodelo			varchar;
		sp_sigla				varchar;
		sp_nombrebomba			varchar;
		sp_cliente				varchar;
		sp_idtipoorden			bigint;
		sp_idfamilia			bigint;
		sp_idproducto			bigint;
	
	    sp_fechaentrega			varchar;
	    sp_fechaemenos7			varchar;
	   
	    sp_fechapendientedesp	timestamp;
	    sp_fechavcto			timestamp;
	    sp_fechamail			varchar;
	   
	    sp_origen				varchar;
	   	sp_elementod			varchar;
	   
	    sp_diferencia			bigint;
         						    
begin
	
	  sp_salida := 0;	 
	 
	  FOR rec_trab IN (   
				select idworkorder,
				       username,
				       ordertypename||'_'||familyname as origen,
				       productname,
				       customername,
				       advance,
				       itemot
		          from traking.evtlistmanagerscreenfamiliafacturacion_pendientedespacho(-1, 'NA', 'NA')
		 	)
	       loop
		    
		       select fechamarcapendientedespacho ,
		              idfamilia
		         into sp_fechapendientedesp,
		              sp_idfamilia
		         from mct_ordentrabajo mo 
		        where idordentrabajo = rec_trab.idworkorder;
		       
		       if (sp_fechapendientedesp is not null) then
		      
				    if sp_idfamilia in (8,10) then 
				          select to_char(sp_fechapendientedesp + interval '5 days', 'dd/mm/yyyy'),
				                 sp_fechapendientedesp + interval '5 days'
				            into sp_fechamail,
				                 sp_fechavcto;
				    else
				          select to_char(sp_fechapendientedesp + interval '3 days', 'dd/mm/yyyy'),
				                 sp_fechapendientedesp + interval '3 days'
				            into sp_fechamail,
				                 sp_fechavcto;
				    end if;
				      
		       		sp_diferencia	:= cast(date_part('day', now() - sp_fechavcto )  as bigint);
		       	
		       	    if (sp_diferencia > 0) then
				      		      
				       -- Lista de correos
				       sp_lista 	:= '';
							   
					   FOR rec_email IN (   
									select distinct c.emaildestino 
								      from mct_notificacionlista a,
							   			   mct_listaemail b,
					   		               mct_email c
								     where a.idnotificacion = 85
							           and a.idlista = b.idlista
								       and b.idemail = c.idemail 
							 	)
						    loop 	
										
								sp_lista := rec_email.emaildestino||','||sp_lista;
										           
					   end loop;
						    
					   sp_asunto := '';
					   sp_texto  := '';
					  
					   -- Saca datos del mail
					   select b.cuerpo,
					          b.asunto
						 into sp_texto,
					          sp_asunto
						 from mct_notificacion a
					     JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
				        WHERE a.idnotificacion = 85;
			
				       sp_elementod	:= '';
				      
				       if (sp_idfamilia = 11) then
				       
				           select '/ '||textoadicional 
				             into sp_elementod
				             from mct_hojarutatemp mh 
						    where idordentrabajo = rec_trab.idworkorder;
				        		       		
				       end if;
				       
				       sp_texto  := REPLACE(sp_texto,'_valor_ot',rec_trab.idworkorder::varchar);
				       sp_texto  := REPLACE(sp_texto,'_valor_equipo',rec_trab.productname::varchar);			   
				       sp_texto  := REPLACE(sp_texto,'_valor_cliente',rec_trab.customername::varchar);
				       sp_texto  := REPLACE(sp_texto,'_valor_ed',sp_elementod::varchar);
				       sp_texto  := REPLACE(sp_texto,'_valor_dias_atraso',sp_diferencia::varchar);
				      
				
					   sp_texto  := REPLACE(sp_texto,'_val_fecha_despacho',sp_fechamail);
				       
					   sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
											     
					   sp_asunto  := REPLACE(sp_asunto,'_valor_bba_ed',rec_trab.origen::varchar);
					   sp_asunto  := REPLACE(sp_asunto,'_valor_ot',rec_trab.idworkorder::varchar);
			
					   orden        :=  rec_trab.idworkorder;
				  	   asunto       :=  sp_asunto;
					   cuerpo       :=  sp_texto; 
					   emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
					   codigonotf   :=  85; 
			
				       RETURN next; 		       	    
		       	    
		       	    end if;
		       
		       
		       end if;	
   
	  end loop;
		        
END;
$$;


