		              sp_idfamilia
		         from mct_ordentrabajo mo 
		        where idordentrabajo = rec_trab.idworkorder;

			   if (sp_dias >= 0) then
					sp_status := 'EN TIEMPO';
			   else
					sp_status := 'ATRASADA';
			   end if;

		       sp_origen	:= '';
		       if sp_idfamilia in (8,10) then 
