			   sp_texto  := REPLACE(sp_texto,'_val_fechamec',to_char(sp_fechatm, 'dd/mm/yyyy'));
               sp_texto  := REPLACE(sp_texto,'_val_fecha_zona1',to_char(sp_fechapendientedespz1, 'dd/mm/yyyy'));
