    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY');
	    sp_fechafile            VARCHAR=to_char(now(),'yyyy-mm-dd');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin


	if (select 1 
	      from mct_operadorturno a,
	           mct_operador b
         where to_char(fechaturno,'yyyy-mm-dd') = sp_fechafile
           and turnootro = true
           and a.idoperador = b.idoperador 
           and b.movilizacionpropia = false) then
	
		sp_lista := '';
						   
		FOR rec_email IN (   
			select distinct c.emaildestino 
			  from mct_notificacionlista a,
			       mct_listaemail b,
			       mct_email c
		     where a.idnotificacion = idnotif
			   and a.idlista = b.idlista
			   and b.idemail = c.idemail 
				)
		    loop 	
							
			    sp_lista := rec_email.emaildestino||','||sp_lista;
							           
		END LOOP;
			    
		sp_asunto := '';
		sp_texto  := '';
					 
		-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
		select b.cuerpo ,
			   b.asunto
		  into sp_texto,
			   sp_asunto
		  from mct_notificacion a
	      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
		 WHERE a.idnotificacion= 57;
	
				      
		 sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
		 sp_asunto  := REPLACE(sp_asunto,'_valor_fecha',sp_fecha_hoy);
				 
		 asunto       :=  sp_asunto;
		 cuerpo       :=  sp_texto; 
		 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
		 codigonotf   :=  idnotif; 
		 fechafile    :=  sp_fechafile;  
					 
		 RETURN next;	  	
	
	end if;

	    
END;
$$;


