--
-- TOC entry 1270 (class 1255 OID 17137)
-- Name: evtlistmaildistsolcompmanual(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmaildistsolcompmanual(idsol bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	   
	    sp_idsolcomp			bigint;
	    sp_ot					bigint;
	    sp_idusuario			bigint;
	    sp_observacion			varchar;
	    sp_fechareq				varchar;
	   
	
		rec_email      RECORD;
	    rec_trab       RECORD;					           
         						    
begin

	select a.idsolcompcabecera ,
	       a.idordentrabajo ,
	       a.idusuario ,
	       a.observacion ,
	       to_char(a.fecharequerida , 'dd-mm-yyyy')
	  into sp_idsolcomp ,
	       sp_ot,
	       sp_idusuario,
	       sp_observacion,
	       sp_fechareq
	  from mct_solcompcabecera a
  	 where a.idsolcompcabecera = idsol;
	

	sp_lista := '';
					   
	FOR rec_email IN (   
		select distinct c.emaildestino 
		  from mct_notificacionlista a,
		       mct_listaemail b,
		       mct_email c
	     where a.idnotificacion = 87
		   and a.idlista = b.idlista
		   and b.idemail = c.idemail 
			)
	    loop 	
						
		    sp_lista := rec_email.emaildestino||','||sp_lista;
						           
	END LOOP;
		    
	sp_asunto := '';
	sp_texto  := '';
				 
	-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
	select REPLACE(REPLACE(REPLACE(b.cuerpo,'_valor_fecha',sp_fecha_hoy),'_val_solcomp',sp_idsolcomp::varchar),'_val_observacion',sp_observacion::varchar) ,
		   REPLACE(b.asunto,'_val_solcomp',sp_idsolcomp::varchar)
	  into sp_texto,
		   sp_asunto
	  from mct_notificacion a
      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	 WHERE a.idnotificacion= 87;
			      
	-- sp_texto  := REPLACE(sp_texto,'_valor_ingeniero',sp_nombreingeniero);
	 --sp_asunto  := REPLACE(sp_asunto,'_val_solcomp',sp_idsolcomp);
	
	 --sp_texto   := REPLACE(sp_texto,'_val_solcomp',sp_idsolcomp);
			 
	 asunto       :=  sp_asunto;
	 cuerpo       :=  sp_texto; 
	 emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
	 codigonotf   :=  87; 
				 
	 RETURN next;	        
	     
END;
$$;


