--
-- TOC entry 1711 (class 1255 OID 17138)
-- Name: evtlistmailgestionncfimputacion(bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmailgestionncfimputacion(p_idgestionncf bigint, p_codhojaruta character varying, p_idgestionncfimputacion bigint) RETURNS TABLE(asunto character varying, cuerpo character varying, emaildestino character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$

DECLARE

    sp_ot                    bigint;

    sp_identificacion        varchar;
    sp_equipo                varchar;
    sp_cliente               varchar;
    sp_emisor                varchar;

    sp_descripcion           varchar;
    sp_usuario               varchar;
    sp_fechaimputacion       timestamp;

    sp_areas                 text;

    sp_listamail             bigint;
    sp_lista                 text;

    sp_emailevaluador        varchar;

BEGIN

    /*
     * ==============================================================
     * 1. VALIDAR Y OBTENER LA IMPUTACION
     * ==============================================================
     */

    SELECT
        i.descripcion,
        i.usuario,
        i.fechaimputacion

      INTO
        sp_descripcion,
        sp_usuario,
        sp_fechaimputacion

      FROM mct_gestionncfimputacion i

     WHERE i.idgestionncfimputacion =
           p_idgestionncfimputacion

       AND i.idgestionncf =
           p_idgestionncf;


    IF NOT FOUND THEN
        RETURN;
    END IF;


    /*
     * ==============================================================
     * 2. DATOS DEL RECHAZO
     *
     * Reutilizamos la funcion que ya probamos.
     * ==============================================================
     */

    SELECT
        x.ot,
        x.identificacion,
        x.equipo,
        x.cliente,
        x.emisor

      INTO
        sp_ot,
        sp_identificacion,
        sp_equipo,
        sp_cliente,
        sp_emisor

      FROM traking.evtgetgestionncfimputacion_tablet(
            p_idgestionncf,
            p_codhojaruta
      ) x

     LIMIT 1;


    IF NOT FOUND THEN
        RETURN;
    END IF;


    /*
     * ==============================================================
     * 3. ARMAR LISTA DE AREAS / SUBAREAS IMPUTADAS
     * ==============================================================
     */

    SELECT
        string_agg(
            (
                '- ' ||
                a.nombre ||
                CASE
                    WHEN d.idsubareaimputacionrechazo IS NOT NULL
                    THEN ' / ' || s.nombre
                    ELSE ''
                END
            ),
            E'\n'
        )

      INTO sp_areas

      FROM mct_gestionncfimputaciondetalle d

      JOIN mct_areaimputacionrechazo a
        ON a.idareaimputacionrechazo =
           d.idareaimputacionrechazo

      LEFT JOIN mct_subareaimputacionrechazo s
        ON s.idsubareaimputacionrechazo =
           d.idsubareaimputacionrechazo

     WHERE d.idgestionncfimputacion =
           p_idgestionncfimputacion;


    /*
     * ==============================================================
     * 4. RECUPERAR LISTA DE DISTRIBUCION ORIGINAL
     * ==============================================================
     */

    SELECT
        o.listamail

      INTO sp_listamail

      FROM mct_gestionncf g

      LEFT JOIN mct_origenncf o
        ON o.idorigenncf = g.idorigenncf

     WHERE g.idgestionncf =
           p_idgestionncf;


    /*
     * ==============================================================
     * 5. DESTINATARIOS DE LA LISTA
     * ==============================================================
     */

    SELECT
        string_agg(
            DISTINCT e.emaildestino,
            ','
        )

      INTO sp_lista

      FROM mct_listaemail l

      JOIN mct_email e
        ON e.idemail = l.idemail

     WHERE l.idlista =
           sp_listamail;


    /*
     * ==============================================================
     * 6. EMAIL DEL EVALUADOR DE LA OT
     * ==============================================================
     */

    SELECT
        u.email

      INTO sp_emailevaluador

      FROM mct_ordentrabajo ot

      JOIN mct_usuario u
        ON u.idusuario = ot.idusuario

     WHERE ot.idordentrabajo =
           sp_ot;


    /*
     * ==============================================================
     * 7. MISMA REGLA DEL MAIL ORIGINAL PARA AGREGAR EVALUADOR
     * ==============================================================
     */

    IF sp_listamail IN (
        85,
        91,
        90,
        84,
        105,
        106
    ) THEN

        IF sp_emailevaluador IS NOT NULL
           AND LENGTH(TRIM(sp_emailevaluador)) > 0 THEN

            IF sp_lista IS NULL
               OR LENGTH(TRIM(sp_lista)) = 0 THEN

                sp_lista :=
                    sp_emailevaluador;

            ELSE

                /*
                 * Evitamos agregarlo nuevamente
                 * si ya está en la lista.
                 */

                IF POSITION(
                    LOWER(sp_emailevaluador)
                    IN LOWER(sp_lista)
                ) = 0 THEN

                    sp_lista :=
                        sp_lista ||
                        ',' ||
                        sp_emailevaluador;

                END IF;

            END IF;

        END IF;

    END IF;


    /*
     * ==============================================================
     * 8. ASUNTO
     * ==============================================================
     */

    asunto :=
        'RECHAZO IMPUGNADO AL ORIGEN';


    /*
     * ==============================================================
     * 9. CUERPO
     * ==============================================================
     */

    cuerpo :=

        'Identificación: ' ||
        COALESCE(
            sp_identificacion,
            'N/A'
        ) ||

        E'\n\n' ||

        'Equipo: ' ||
        COALESCE(
            sp_equipo,
            'N/A'
        ) ||
        ' / ' ||
        COALESCE(
            sp_cliente,
            'N/A'
        ) ||

        E'\n\n' ||

        'OT: ' ||
        COALESCE(
            sp_ot::varchar,
            'N/A'
        ) ||

        E'\n\n' ||

        'Emisor: ' ||
        COALESCE(
            sp_emisor,
            'N/A'
        ) ||

        E'\n\n' ||

        'ÁREA(S) IMPUGNADA(S):' ||

        E'\n' ||

        COALESCE(
            sp_areas,
            'N/A'
        ) ||

        E'\n\n' ||

        'RESUMEN DEL ANÁLISIS:' ||

        E'\n' ||

        COALESCE(
            sp_descripcion,
            'N/A'
        ) ||

        E'\n\n' ||

        'Imputación realizada por: ' ||
        COALESCE(
            sp_usuario,
            'N/A'
        ) ||

        E'\n' ||

        'Fecha: ' ||
        COALESCE(
            to_char(
                sp_fechaimputacion,
                'DD-MM-YYYY HH24:MI'
            ),
            'N/A'
        );


    /*
     * ==============================================================
     * 10. DESTINATARIOS
     * ==============================================================
     */

    emaildestino :=
        COALESCE(
            sp_lista,
            ''
        )::varchar;


    /*
     * Solo para mantener compatibilidad con MctListDistMail.
     */
    codigonotf :=
        'IMPUTACION_RECHAZO';


    RETURN NEXT;
    RETURN;

END;

$$;


ALTER FUNCTION traking.evtlistmailgestionncfimputacion(p_idgestionncf bigint, p_codhojaruta character varying, p_idgestionncfimputacion bigint) OWNER TO postgres;

--
-- TOC entry 1351 (class 1255 OID 17140)
-- Name: evtlistmailgestionsinvalidar(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmailgestionsinvalidar(idnotificacion bigint) RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
        sp_anno_hoy             VARCHAR=to_char(now(),'YYYY');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;	    
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_salida				bigint;
	   
begin 
	
	 sp_salida := 0;

  	  raise notice '%', 'Es Inf. Recepcion';
 
	  FOR rec_trab IN (  
 
			select a.idactividadgestion,
			       a.idusuario,
			       b.nombre,
			       to_char(a.fechaactividad,'dd-mm-yyyy') as fechaactividad,
			       cast(a.horaactividad as varchar) as horaactividad,
			       (a.correlativoaviso + 1) as correlativoaviso,
                   b.email
			  from traking.mct_actividadgestion a
			  left join traking.mct_usuario b on a.idusuario = b.idusuario
			 where a.fechaactividad < current_date
			   and (a.idestadoactividadgestion < 1 or a.idestadoactividadgestion is null)

					)
								
		loop 	
        
			sp_lista := '';
						   
			FOR rec_email IN (   
						select distinct c.emaildestino 
					      from mct_notificacionlista a,
				   			   mct_listaemail b,
		   		               mct_email c
					     where a.idnotificacion = 98 -- Notificacion Valiacion Agenda Comercial
				           and a.idlista = b.idlista
					       and b.idemail = c.idemail 
				 	)
			    loop 	
							
					sp_lista := rec_email.emaildestino||','||sp_lista;
							           
		    end loop;
			    
			sp_asunto := '';
			sp_texto  := '';
					 	 
			-- aca sacamnos los datos que vamos a trabajar del cuerpo del mensaje
			select b.cuerpo,
		           b.asunto
			  into sp_texto,
		           sp_asunto
			  from mct_notificacion a
 		      JOIN mct_cuerpomensaje  b ON ( b.idnotificacion = a.idnotificacion)
	         WHERE a.idnotificacion= 98;
			
			sp_asunto  := REPLACE(sp_asunto,'_valcorr',rec_trab.correlativoaviso::varchar);
	        
	        sp_texto  := REPLACE(sp_texto,'_valcorr',rec_trab.correlativoaviso::varchar);
			sp_texto  := REPLACE(sp_texto,'_valvendedor',rec_trab.nombre);
		    sp_texto  := REPLACE(sp_texto,'_valfechaactividad',rec_trab.fechaactividad);
		    sp_texto  := REPLACE(sp_texto,'_valhoraactividad',rec_trab.horaactividad);
			sp_texto  := REPLACE(sp_texto,'_valor_fecha',sp_fecha_hoy);
            sp_texto  := REPLACE(sp_texto,'_valor_agno',sp_anno_hoy);
					 
			orden        :=  0;
			asunto       :=  sp_asunto;
			cuerpo       :=  sp_texto; 
			emaildestino :=  cast(substring(sp_lista,1,length(sp_lista)-1)||','||rec_trab.email as varchar);
			codigonotf   :=  98; 
	
		    RETURN next;	
		           
            update traking.mct_actividadgestion
               set correlativoaviso = correlativoaviso + 1
             where idactividadgestion = rec_trab.idactividadgestion;
			  
	  END LOOP;	 
	
        	     
END;
$$;


ALTER FUNCTION traking.evtlistmailgestionsinvalidar(idnotificacion bigint) OWNER TO postgres;

--
-- TOC entry 2123 (class 1255 OID 17141)
-- Name: evtlistmailincumplimientos(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmailincumplimientos(idnotificacion bigint) RETURNS TABLE(orden bigint, emaildestino character varying, asunto character varying, cuerpo character varying, codigonotf character varying)
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			bigint;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              bigint;	   
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;	    
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_salida				bigint;
	   
	    sp_ot					bigint;
		sp_nombrecomp			varchar;
		sp_nombremat			varchar;
		sp_responsable			varchar;
	
	    sp_horas				bigint;
	    sp_dias					bigint;
		sp_funcav				numeric;	  
	
	    sp_existeaudit			bigint	:= 0;
	    sp_contador				bigint	:= 0;
         						    
	    sp_idcumpl				bigint;
	   
	    sp_cantidad_co			bigint	:= 0;
	    sp_recept_co			bigint	:= 0;
		sp_codigoqr_co			varchar	:= '';
	    sp_avance_co			numeric	:= 0;
	   
	    sp_frecuencia			bigint	:= 0;
	    sp_ultimoenvio			timestamp;
	   
	    sp_horasejecutamail		bigint	:= 0;
	    sp_enviamail			bigint	:= 0;
begin 
	
	 sp_salida := 0;
	 
	 if (idnotificacion = 76) then
	 
	      select a.frecuencia * 60
	        into sp_frecuencia
	        from mct_agendamientomail a
	       where a.idnotificacion = 76 ;

	  	  raise notice '%', 'Es Inf. Recepcion';
	 
		  FOR rec_trab IN (   
		  
					 select a.idordentrabajo ,
					        a.idestadoorden ,
					        a.idfamilia ,
					        a.fecharecepcion ,
					        a.fechacreacion ,
					        b.idsla ,
					        b.estado ,
					        round(( EXTRACT(EPOCH FROM now())-EXTRACT(EPOCH FROM a.fechacreacion)) / 3600) as horas,
					        round(( EXTRACT(EPOCH FROM now())-EXTRACT(EPOCH FROM a.fechacreacion)) / 86400) as dias,
					        cc.nombre ,
					        --c.nombreproducto ,
					        d.nombremodelo ,
					        e.sigla ,
					        case
						        when a.idfamilia = 8 then
						             'BOMBAS - '||e.sigla||' '||d.nombremodelo||' '||f.nombreparam
						        when a.idfamilia = 10 then
						             'REPUESTOS - '||e.sigla||' '||d.nombremodelo||' '||f.nombreparam
						    end as nombreproducto,
					        --e.sigla||' '||d.nombremodelo||' '||f.nombreparam as nombreproducto,
					        coalesce(g.nombrecorto , 'S/N') as nombrecorto  
					   from mct_ordentrabajo a
					   left join mct_progavisos b  on a.idordentrabajo = b.idordentrabajo
					   left join mct_usuario cc    on a.idusuario = cc.idusuario 
					   left join mct_producto c    on a.idproducto = c.idproducto
	                   left join mct_modelo d      on c.idmodelo = d.idmodelo
