	                  left join mct_etapaparam h on e.idetapaparam = h.idetapaparam
	                  left join mct_cliente i    on i.idcliente = b.idcliente 		        
		       where a.criterio in ('Rpo') 
		         and b.idestadoorden < 9
		         and b.idfamilia in (8,10)
				 --and b.idfamilia in (8)
		         and b.idtipoorden in (1,2)
		         and b.idordentrabajo >= 30000		           
		         and d.idsla = 5
			     and d.estado = 1
			     and d.enviosolicitud = 1
			     and a.idestadoorden < 11
			     --and a.idordentrabajo = 32110
			     and b.idordentrabajo not in (
					        32246
					        , 32247
					        , 32335
					        , 32462
					        , 32493
					        , 32495
					        , 32533
					        , 32481
					        , 32524
					        , 32561
					        , 32521
					        ,32613
							,32614
							,32615
							,32619
							,32620
							,32621
							,32622
							,32623
							,62624
							,62625
							,32626
							,32627
							,32672)
			     and b.fecharecepcion >= '2023-08-15 00:00:00'
		       group by a.idordentrabajo ,
		                d.fechaenviosolicitud,
		                cc.nombre,
		                g.sigla||' '||f.nombremodelo||' '||h.nombreparam,
			            coalesce(i.nombrecorto , 'S/N'),
			            b.idfamilia
			)
									
			loop 	
				     
			    --sp_dias	:= 10;
			    sp_horas	:= 0;
			    select round(salhorav) 
                  into sp_horas
                  from traking.calculahorasincumplimientos_test_v1(rec_trab.fechaenviosolicitud, 79);
			   
			    --if (rec_trab.dias > sp_dias and rec_trab.total > rec_trab.recepcionada ) then
			    if (rec_trab.horas > sp_horas and rec_trab.total > rec_trab.recepcionada ) then
			
			        sp_existeaudit	:= 0;
			        sp_enviamail	:= 0;
			        
			        select coalesce(a.contador , 0),
			               a.idauditoriaincumplimiento ,
			               a.ultimoenvio 
			          into sp_contador,
			               sp_idcumpl,
			               sp_ultimoenvio
			          from mct_auditoriaincumplimiento a
			         where a.idordentrabajo = rec_trab.idordentrabajo
			           and a.idnotificacion = 79; 
			          
			        if (sp_contador > 0) then
			        
			        	select round(( EXTRACT(EPOCH FROM now()::timestamp)-EXTRACT(EPOCH FROM sp_ultimoenvio::timestamp)) / 3600)*60
			        	  into sp_horasejecutamail;
			        	 
			        	raise notice '%', 'Ultimo envio '||sp_ultimoenvio;
			        	raise notice '%', 'Horas para enviar '||sp_horasejecutamail;
			         
				        if (sp_horasejecutamail >= sp_frecuencia ) then
				            sp_enviamail	:= 1;
				           
				            update mct_auditoriaincumplimiento 
						       set ultimoenvio = now()
						     where idauditoriaincumplimiento = sp_idcumpl;
				        else
				            sp_enviamail	:= 0;
				        end if;			        	
			        
			        end if;
			       
			        if (sp_contador > 0) then
			        
			            if (sp_enviamail = 1) then
			            
							update mct_auditoriaincumplimiento 
						       set contador = contador + 1
						     where idauditoriaincumplimiento = sp_idcumpl;			        
			        
					    end if;
					   
			        else
			        
			            sp_enviamail	:= 1;
			            sp_contador		:= 1;
			           
			       	 	INSERT INTO traking.mct_auditoriaincumplimiento
							(idauditoriaincumplimiento, idordentrabajo, idnotificacion, estado, contador, fechacreacion, ultimoenvio)
							VALUES(nextval('traking.mct_auditoriaincumplimiento_seq'), rec_trab.idordentrabajo, 79, 0, sp_contador+1, now(), now());
			        
			        end if;
			       
			        if (sp_enviamail = 1) then

				    	sp_lista := '';
									   
						FOR rec_email IN (   
									select distinct c.emaildestino 
								      from mct_notificacionlista a,
							   			   mct_listaemail b,
