				        sp_texto  := REPLACE(sp_texto,'_aviso',sp_contador::varchar);
				        sp_texto  := REPLACE(sp_texto,'_valor_porcentaje',sp_avance_co::varchar);
						sp_texto  := REPLACE(sp_texto,'_valor_ingeniero',rec_trab.nombre);
					    sp_texto  := REPLACE(sp_texto,'_valor_producto',rec_trab.nombreproducto);
					    sp_texto  := REPLACE(sp_texto,'_valor_ot',replace(trim(to_char(rec_trab.idordentrabajo, '999G999')),',','.')::varchar);
