	                   left join mct_modelo d          on c.idmodelo = d.idmodelo
	                   left join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
	                   left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
	                   left join mct_cliente g    on a.idcliente = g.idcliente 
					  where a.idordentrabajo >= 30000
					    and a.idfamilia in (8,10)
					    --and a.idfamilia in (8)
					    and a.debaja < 1
					    and a.idtipoorden = 1
					    and a.idestadoorden < 9 and a.idestadoorden > 5
