END;
$$;


ALTER FUNCTION traking.evtlistmailincumplimientos(idnotificacion bigint) OWNER TO postgres;

--
-- TOC entry 1809 (class 1255 OID 17143)
-- Name: evtlistmanagerscreen(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmanagerscreen() RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, customername character varying, deliverydate character varying, statusdispatch bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_canthr        integer;
    sp_liberadascc   integer;
   
    rec_ord          record;

    -- Variable para fundicion
    sp_cantidad_fu         integer; 
	sp_codigoqr_fu         varchar;  
	sp_fecharequerida_fu   timestamp;

    -- Variable para pañol
    sp_cantidad_pa         integer; 
	sp_codigoqr_pa         varchar;  
	sp_fecharequerida_pa   timestamp;

    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
   
begin
	
	  FOR rec_ord IN (   
				select ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
				       a.idordentrabajo ,
				       case 
				          when a.ordencompra > 0 then 'OC'
				          when a.ordencompra = 0 then 'OI'
				          else 'OI'
				       end as tipoautoriza,   
				       d.nombretipoorden ,
				       e.nombrefamilia ,
				       h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
				       b.nombrecorto ,
				       to_char(a.fechaentrega,'dd-mm-yyyy') as fechaentrega ,
				       date_part('day', fechaentrega - now()) as dias,
				       a.idmodalidadcreacion ,
				       j.nombre 
				  from mct_ordentrabajo a,
				       mct_cliente b,
				       mct_producto c,
				       mct_tipoorden d,
				       mct_familia e,
				       mct_estadoorden f,
				       mct_modelo g,
				       mct_subfamilia h,
				       mct_etapaparam i,
				       mct_usuario j
				 where a.idcliente = b.idcliente 
				   and a.idproducto = c.idproducto 
				   and a.idtipoorden = d.idtipoorden 
				   and a.idfamilia = e.idfamilia
				   and a.idestadoorden = f.idestadoorden 
				   and c.idmodelo = g.idmodelo 
				   and g.idsubfamilia = h.idsubfamilia 
				   and c.idetapaparam = i.idetapaparam 
				   and a.idordentrabajo >= 30000
				   and a.idusuario = j.idusuario 
				   and a.idestadoorden  >= 6
				   and a.idestadoorden  < 9
				   order by a.fechaentrega asc
					)
		loop 	
		
		       -- colores seran
		       -- 1 : verde
		       -- 2 : amarillo
		       -- 3 : rojo
		       
		       -- sacamos el rango de fechas para el color de entrega
   
               select min(fecha_inicio), 
                      max(fecha_termino),
                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
                      date_part('day', max(fecha_termino) - now() ) ,
                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
                 into sp_fecha_auto,
                      sp_fecha_entdes,
                      dias_entrega,
                      dias_resto,
                      dias_calculo
                 from mct_progavisos 
                where idordentrabajo = rec_ord.idordentrabajo
                  and idsla in (5,8);
                 
               if (dias_resto = 0 ) then
                   dias_resto := 1;
               end if;

              
   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
   			   
   			   if now() > sp_fecha_entdes then 
   			      sp_color_item    := 3;
   			      sp_color_entrega := 3;
   			   elsif sp_calculo_itement < 80 then
	   			      sp_color_item    := 1;
	   			      sp_color_entrega := 1;   			   
   			   elsif sp_calculo_itement >= 80 then
 	   			      sp_color_item    := 2;
	   			      sp_color_entrega := 2;     			   
   			   end if; 
                  
		
		       -- aca sacamos la cantidad de piezas totales
			   select coalesce ( sum(cantidad), 0)
			     into sp_canthr
			     from mct_hojarutatemp mh
			    where idordentrabajo = rec_ord.idordentrabajo;
			   
			   -- aca sacamos la cantidad de piezas liberadas de control de calidad
			   select count(*) 
			     into sp_liberadascc
			     from mct_movimientoordentrabajo
			    where codigoaccion = 'L_CC'
			      and idordentrabajo = rec_ord.idordentrabajo; 
			      
			   if ( sp_canthr = 0) then
			       sp_avance := 0;
			   else
			       sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
               end if;

               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
                 			     
               if sp_dias_atraso_status < 0 then 
                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
               end if;
              
   			   if now() > sp_fecha_entdes then 
   			      sp_color_status  := 3;
   			   elsif sp_calculo_itement < 80 then
   			      sp_color_status  := 1;  
   			   else
   			      sp_color_status  := 1;  
   			   end if;

              
			   -- Fundicion
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_fu,
				          sp_codigoqr_fu,
				          sp_fecharequerida_fu
				     from mct_checklistinftec
				    where tipotrabajostd = 'FAB_FU'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				     
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_fu,
				          sp_maxfecha_fu
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_fu; 

			   if (sp_cantidad_fu = 0 ) then
                   sp_cantidad_fu := 1;
               end if;
              
			   sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
			   
			   if ( sp_maxfecha_fu > sp_fecharequerida_fu ) then
			       sp_atraso_fu  := date_part('day', sp_maxfecha_fu -  sp_fecharequerida_fu );
			       sp_color_fu   := 3;
			   else
			       sp_color_fu   := 1;			   
			   end if;
			  
			  
			   -- Pañol
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_pa,
				          sp_codigoqr_pa,
				          sp_fecharequerida_pa				          
				     from mct_checklistinftec
				    where tipotrabajostd = 'FAB_PA'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_pa,
				          sp_maxfecha_pa		   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_pa;

			  if (sp_cantidad_pa = 0 ) then
                   sp_cantidad_pa := 1;
               end if;
              
				  sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    

				   if ( sp_maxfecha_pa > sp_fecharequerida_pa ) then
				       sp_atraso_pa  := date_part('day', sp_maxfecha_pa -  sp_fecharequerida_pa );
				       sp_color_pa   := 3;
				   else
				       sp_color_pa   := 1;			   
				   end if;				 
			  
			   -- Caldereria
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_ca,
				          sp_codigoqr_ca,
				          sp_fecharequerida_ca				          
				     from mct_checklistinftec
				    where tipotrabajostd = 'FAB_CA'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_ca,
				          sp_maxfecha_ca	   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_ca; 

			  if (sp_cantidad_ca = 0 ) then
                   sp_cantidad_ca := 1;
               end if;
              
				  sp_avance_ca := round((sp_recept_ca * 100.00 ) / sp_cantidad_ca , 2);

				   if ( sp_maxfecha_ca > sp_fecharequerida_ca ) then
				       sp_atraso_ca  := date_part('day', sp_maxfecha_ca -  sp_fecharequerida_ca );
				       sp_color_ca   := 3;
				   else
				       sp_color_ca   := 1;			   
				   end if;					 
				 
			   -- Compras
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          max(fecharequerida)
				     into sp_cantidad_co,
				          sp_codigoqr_co,
				          sp_fecharequerida_co				          
				     from mct_checklistinftec
				    where tipotrabajostd = 'RPO'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_co,
				          sp_maxfecha_co	 			   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_co;			    

			  if (sp_cantidad_co = 0 ) then
                   sp_cantidad_co := 1;
               end if;				   
				   
				  sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			

				   if ( sp_maxfecha_co > sp_fecharequerida_co ) then
				       sp_atraso_co  := date_part('day', sp_maxfecha_co -  sp_fecharequerida_co );
				       sp_color_co   := 3;
				   else
				       sp_color_co   := 1;			   
				   end if;					 
				 
			   -- Taller Mecanico
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_ot,
				          sp_codigoqr_ot,
				          sp_fecharequerida_ot				          
				     from mct_checklistinftec
				    where tipotrabajostd = 'OTROS'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_ot,
				          sp_maxfecha_ot				   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_ot;					    

			  if (sp_cantidad_ot = 0 ) then
                   sp_cantidad_ot := 1;
               end if;					   
				   
				  sp_avance_ot := round((sp_recept_ot * 100.00 ) / sp_cantidad_ot , 2);						    

				   if ( sp_maxfecha_ot > sp_fecharequerida_ot ) then
				       sp_atraso_ot  := date_part('day', sp_maxfecha_ot - sp_fecharequerida_ot );
				       sp_color_ot   := 3;
				   else
				       sp_color_ot   := 1;			   
				   end if;					 
				 
	      --  sp_dias_av := date_part('day' , rec_ord.fechaentrega - now() )
	        
		    itemot         := rec_ord.item;
		    idworkorder    := rec_ord.idordentrabajo;
			auttype        := rec_ord.tipoautoriza;	    
			ordertypename  := rec_ord.nombretipoorden;
			username       := rec_ord.nombre;
		    familyname     := rec_ord.nombrefamilia;
			productname    := rec_ord.producto;
			customername   := rec_ord.nombrecorto;
			deliverydate   := to_char(sp_fecha_entdes,'dd-mm-yyyy');
			statusdispatch := sp_dias_atraso_status;
			advance        := sp_avance;
			advancefu      := coalesce(sp_avance_fu,0);
			advancepa      := coalesce(sp_avance_pa,0);
			advanceca      := coalesce(sp_avance_ca,0);
			advanceco      := coalesce(sp_avance_co,0);
			advanceot      := coalesce(sp_avance_ot,0);
			itemcolor      := coalesce(sp_color_item,0);
   			statuscolor    := coalesce(sp_color_status,0);   		
			fucolor        := sp_color_fu;
			pacolor        := sp_color_pa;
			cacolor        := sp_color_ca;		
			cocolor        := sp_color_co;
			otcolor        := sp_color_ot;	
			delayfu        := coalesce(sp_atraso_fu,0); 
			delaypa        := coalesce(sp_atraso_pa,0); 
			delayca        := coalesce(sp_atraso_ca,0); 
			delayco        := coalesce(sp_atraso_co,0); 
			delayot        := coalesce(sp_atraso_ot,0); 
				    
		return next;

		END LOOP;

END;
$$;


ALTER FUNCTION traking.evtlistmanagerscreen() OWNER TO postgres;

--
-- TOC entry 2308 (class 1255 OID 17145)
-- Name: evtlistmanagerscreenbyuser(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmanagerscreenbyuser(idfamily bigint, iduser bigint) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_canthr        integer;
    sp_liberadascc   integer;
   
    rec_ord          record;

    -- nepcast
    sp_cantidad            integer;
    sp_subproducto         varchar;
    -- Variable para fundicion
    sp_cantidad_fu         integer; 
	sp_codigoqr_fu         varchar;  
	sp_fecharequerida_fu   timestamp;

    -- Variable para pañol
    sp_cantidad_pa         integer; 
	sp_codigoqr_pa         varchar;  
	sp_fecharequerida_pa   timestamp;

    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
   
begin
	 
	if ( idfamily = 99 ) then 

		FOR rec_ord IN (   
				select ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
				       a.idordentrabajo ,
				       case 
				          when a.ordencompra > 0 then 'S/A'
				          when a.ordencompra = 0 then 'S/A'
				          else 'S/A'
				       end as tipoautoriza,   
				       d.nombretipoorden ,
				       e.nombrefamilia ,
				       h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
				       b.nombrecorto ,
				       to_char(a.fechaentrega - interval '7 days','dd-mm-yyyy') as fechaentregatm ,
				       to_char(a.fechaentrega,'dd-mm-yyyy') as fechaentregaclte ,				       
				       date_part('day', a.fechaentrega - now()) as dias,
				       a.idmodalidadcreacion ,
				       j.nombre 
				  from mct_ordentrabajo a,
				       mct_cliente b,
				       mct_producto c,
				       mct_tipoorden d,
				       mct_familia e,
				       mct_estadoorden f,
				       mct_modelo g,
				       mct_subfamilia h,
				       mct_etapaparam i,
				       mct_usuario j
				 where a.idcliente = b.idcliente 
				   and a.idproducto = c.idproducto 
				   and a.idtipoorden = d.idtipoorden 
				   and a.idfamilia = e.idfamilia
				   and a.idestadoorden = f.idestadoorden 
				   and c.idmodelo = g.idmodelo 
				   and g.idsubfamilia = h.idsubfamilia 
				   and c.idetapaparam = i.idetapaparam 
				   and a.idordentrabajo >= 30000
				   and a.idusuario = j.idusuario 
				   and a.idestadoorden  = 4
				   and a.idfamilia = 8
				   and a.idusuario = iduser
				   order by a.fechaentrega asc
					)
		loop 	
		
		       -- colores seran
		       -- 1 : verde
		       -- 2 : amarillo
		       -- 3 : rojo
		       
		       -- sacamos el rango de fechas para el color de entrega
   
               select min(fecha_inicio), 
                      max(fecha_termino),
                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
                      date_part('day', max(fecha_termino) - now() ) ,
                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
                 into sp_fecha_auto,
                      sp_fecha_entdes,
                      dias_entrega,
                      dias_resto,
                      dias_calculo
                 from mct_progavisos 
                where idordentrabajo = rec_ord.idordentrabajo
                  and idsla in (5,8,9);
                 
               if (dias_resto = 0 ) then
                   dias_resto := 1;
               end if;

              
   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
   			   
   			   if now() > sp_fecha_entdes then 
   			      sp_color_item    := 3;
   			      sp_color_entrega := 3;
   			   elsif sp_calculo_itement < 80 then
	   			      sp_color_item    := 1;
	   			      sp_color_entrega := 1;   			   
   			   elsif sp_calculo_itement >= 80 then
 	   			      sp_color_item    := 2;
	   			      sp_color_entrega := 2;     			   
   			   end if; 
                  
		
		       -- aca sacamos la cantidad de piezas totales
			   select coalesce ( sum(cantidad), 0)
			     into sp_canthr
			     from mct_hojarutatemp mh
			    where idordentrabajo = rec_ord.idordentrabajo;
			   
			   -- aca sacamos la cantidad de piezas liberadas de control de calidad
			   select count(*) 
			     into sp_liberadascc
			     from mct_movimientoordentrabajo
			    where codigoaccion = 'L_CC'
			      and idordentrabajo = rec_ord.idordentrabajo; 
			      
			   if ( sp_canthr = 0) then
			       sp_avance := 0;
			   else
			       sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
               end if;

               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
                 			     
               if sp_dias_atraso_status < 0 then 
                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
               end if;
              
   			   if now() > sp_fecha_entdes then 
   			      sp_color_status  := 3;
   			   elsif sp_calculo_itement < 80 then
   			      sp_color_status  := 1;  
   			   else
   			      sp_color_status  := 1;  
   			   end if;

              
			   -- Fundicion
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_fu,
				          sp_codigoqr_fu,
				          sp_fecharequerida_fu
				     from mct_checklistinftec
				    where tipotrabajostd = 'FAB_FU'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				     
				   -- aca sacamos el total de piezas recepcionadas   
