		        montoarrastre	:= montototalot - montoarrastre;

	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	end if;	    
	         
	         else
	         
	         	montototalot	:= 0;
	         
	         end if;
	        
	        --montoarrastre	:= 0;
				        
		return next;

		END LOOP;	    
	   
END;
$$;


ALTER FUNCTION traking.evtlistmanagerscreenfacturacioncalendario_consolidado_2(periodo character varying, agno bigint) OWNER TO postgres;

--
-- TOC entry 2112 (class 1255 OID 17151)
-- Name: evtlistmanagerscreenfacturacioncalendario_consolidadosumaanteri(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmanagerscreenfacturacioncalendario_consolidadosumaanteri(periodo character varying, agno bigint) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying, piezas character varying, estaenproceso bigint, montototalot bigint, montototaldesp bigint, montoarrastre bigint)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_funcav			   numeric;
    sp_canthr              integer;
    sp_liberadascc         integer;
   
    rec_ord          	   record;
   
   	sp_fechamaxlcc         timestamp;
	sp_dias_lcc            integer;

    -- nepcast
    sp_cantidad            integer;
    sp_subproducto         varchar;
    -- Variable para fundicion
    sp_cantidad_fu         integer; 
	sp_codigoqr_fu         varchar;  
	sp_fecharequerida_fu   timestamp;

    -- Variable para pañol
    sp_cantidad_pa         integer; 
	sp_codigoqr_pa         varchar;  
	sp_fecharequerida_pa   timestamp;
 
    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    -- Variable para stock cc
    sp_cantidad_cc         integer; 
	sp_codigoqr_cc         varchar;  
	sp_fecharequerida_cc   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
    sp_avance_cc           numeric;
    sp_atraso_cc           integer;  
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
    sp_recept_cc           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
    sp_color_cc            integer;   
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
    sp_dias_cc             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
    sp_dias_atraso_cc      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
    sp_maxfecha_cc         timestamp;
   
    sp_muestraorden		   integer;
    sp_countcheck		   integer;
    
    sp_indice              integer;
   
    sp_sumatotallcc        integer;
   
    rec_lcc      			RECORD;
   
    sp_restanc			   integer;
    sp_textoout            varchar;
   
    sp_estaenproceso       bigint;
   
    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;   
    
    sp_montoadicional		bigint;
    
begin
	 
	sp_estaenproceso	:= 0;

	select to_char(now(),'yyyy')
	  into ano;
	 
	select lpad(periodo, 2,'0')
	  into mes;
	 
	fechadesde	:= agno||'-'||mes||'-01';

    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'dd'),
           to_date(fechadesde,'yyyy-mm-dd') + interval '1 month',
           to_char( to_date(fechadesde,'yyyy-mm-dd') + interval '1 month', 'yyyy-mm')||'-'||to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'dd')
	  into ultimodia,
	       fechadesde,
	       fechahasta;
	 
	select to_char(now(),'yyyy')
	  into anofin;
	 
	--fechahasta	:= agno||'-'||mes||'-'||ultimodia;
	

		FOR rec_ord IN (   
				select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc) AS item,
				       a.idordentrabajo ,
				       a.idestadoorden ,
				       case 
				          when a.ordencompra > 0 then 'OC'
				          when a.ordencompra = 0 then 'OI'
				          else 'OI'
				       end as tipoautoriza,   
				       d.nombretipoorden ,
				       e.nombrefamilia||'_'||a.idestadoorden ,
					   --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
					   case 
						  when a.idfamilia = 11 then c.nombreproducto
						  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
					   end as producto,
				       b.nombrecorto ,
				       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
				       fechafacetm,
				       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
				       --date_part('day', a.fechafaceclte - now()) as dias,
				       date_part('day', a.fechafacetm - current_date) as dias,
				       date_part('day', a.fechafaceclte - current_date) as diascliente,	
				       a.idmodalidadcreacion ,
				       j.nombre ,
				       a.flagfacturacion ,
				       d.sigla as siglatipo,
				       e.sigla||'_'||a.idestadoorden as siglafam,
				       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion,
				       coalesce (to_char(a.fechafundicion2, 'dd-mm-yyyy'), to_char(a.fechafacetm - interval '21 days','dd-mm-yyyy')) as fechafundicion,
		               a.checklistvalido ,
		               a.idfamilia 
				  from mct_ordentrabajo a,
				       mct_cliente b,
				       mct_producto c,
				       mct_tipoorden d,
				       mct_familia e,
				       mct_estadoorden f,
				       mct_modelo g,
				       mct_subfamilia h,
				       mct_etapaparam i,
				       mct_usuario j
				 where a.idcliente = b.idcliente 
				   and a.idproducto = c.idproducto 
				   and a.idtipoorden = d.idtipoorden 
				   and a.idfamilia = e.idfamilia
				   and a.idestadoorden = f.idestadoorden 
				   and c.idmodelo = g.idmodelo 
				   and g.idsubfamilia = h.idsubfamilia 
				   and c.idetapaparam = i.idetapaparam 
				   and a.idordentrabajo >= 30000
				   and a.idusuario = j.idusuario 
				   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
				   and a.idfamilia in (8,10,15)
				   --and a.flagfacturacion is true
				   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				   and a.debaja < 1
				   order by a.fechafaceclte asc
				   
					)
		loop 	
		
		       -- colores seran
		       -- 1 : verde
		       -- 2 : amarillo
		       -- 3 : rojo
		       
		       -- sacamos el rango de fechas para el color de entrega
   
               select min(fecha_inicio), 
                      max(fecha_termino),
                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
                      date_part('day', max(fecha_termino) - now() ) ,
                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
                 into sp_fecha_auto,
                      sp_fecha_entdes,
                      dias_entrega,
                      dias_resto,
                      dias_calculo
                 from mct_progavisos 
                where idordentrabajo = rec_ord.idordentrabajo
                  and idsla in (5,8,9);
                 
               if (dias_resto = 0 ) then
                   dias_resto := 1;
               end if;

              
   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
   			   
   			   if now() > sp_fecha_entdes then 
   			      sp_color_item    := 3;
   			      sp_color_entrega := 3;
   			   elsif sp_calculo_itement < 80 then
	   			      sp_color_item    := 1;
	   			      sp_color_entrega := 1;   			   
   			   elsif sp_calculo_itement >= 80 then
 	   			      sp_color_item    := 2;
	   			      sp_color_entrega := 2;     			   
   			   end if; 
                  

   			   -- desde aca el nuevo calculo
	   		   sp_sumatotallcc  := 0;
	   			   
	   		   FOR rec_lcc IN (   
							select distinct b.idhojarutatemp
							  from mct_movimientoordentrabajo a,
							       mct_hojaruta b,
							       mct_hojarutatemp c
							 where a.codigoaccion = 'L_CC'
						       and a.idordentrabajo = rec_ord.idordentrabajo 
						       and a.idhojaruta = b.idhojaruta 
						       and b.idhojarutatemp = c.idhojarutatemp 
						       and c.idboleano = 1
			                   and c.idareaclasificacion in (0,1,2,3,4,5)
							)
		     		loop 	

		     			   sp_liberadascc	:= 0;
						     
		     			   select case
			     			         when idimprimehojas = 1 then
			     			              coalesce (count(*),0)
			     			         when idimprimehojas = 2 then
			     			              coalesce (sum(cantidad),0)     
			     			         else
			     			              0
			     			      end
						     into sp_liberadascc
						     from mct_hojarutatemp
						    where idhojarutatemp = rec_lcc.idhojarutatemp
						      and idboleano = 1
			                  and idareaclasificacion in (0,1,2,3,4,5)
			                 group by idimprimehojas;
				     
			                if ( select distinct 1
				                  from mct_movimientoordentrabajo a,
				                       mct_hojaruta b
				                 where b.idhojarutatemp = rec_lcc.idhojarutatemp
				                   and a.idhojaruta = b.idhojaruta 
				                   and (a.codigoaccion = 'NC_MEC' or a.codigoaccion = 'NC_FU') ) then
			                   
				                if ( select distinct 1
				                  from mct_movimientoordentrabajo a,
				                       mct_hojaruta b
				                 where b.idhojarutatemp = rec_lcc.idhojarutatemp
				                   and a.idhojaruta = b.idhojaruta 
				                   and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
				                                                       from mct_movimientoordentrabajo b
				                                                      where a.idhojaruta = b.idhojaruta 
				                                                        and ( a.codigoaccion = 'L_CC' or
				                                                              a.codigoaccion = 'R_TM' ) ) ) then

					                sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
				                  
				                    sp_textoout := rec_ord.idordentrabajo||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
				                    raise notice '%', sp_textoout;
				                   
				                else
				                
				                
					                sp_sumatotallcc := sp_sumatotallcc + 0;
				                  
				                    sp_textoout := rec_ord.idordentrabajo||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
				                    raise notice '%', sp_textoout;
			                  
				                end if;
				                   
			                   
			               
			                else
			                   sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
			                  
			                   sp_textoout := rec_ord.idordentrabajo||' - '||sp_liberadascc||' - '||rec_lcc.idhojarutatemp||' - '||sp_sumatotallcc;
			                   raise notice '%', sp_textoout;
			                  
			                end if;
				           
		  			END LOOP;
		  		
		  	   sp_sumatotallcc := sp_sumatotallcc * 100;
		  	   -- hasta aca el nuevo calculo
		  		

			   if (rec_ord.idordentrabajo = 31912) then
			   
				    select count(distinct a.idhojarutatemp)
				      into sp_canthr
					  from mct_hojarutatemp a,
					       mct_hojaruta b
					 where a.idordentrabajo = rec_ord.idordentrabajo
					   and b.idhojarutatemp = b.idhojarutatemp
					   and a.idboleano = 1   
					   and a.idareaclasificacion in (0,1,2,3,4,5);
			   else
			   
				   select sum(total)
				     from (
						   select case 
							        when idimprimehojas = 1 then
						     			 coalesce (count(*),0)
						     	    when idimprimehojas = 2 then
						     			 coalesce (sum(cantidad),0)     
						     		else
						     			 0	
						          end as total
						     from mct_hojarutatemp mh
						    where idordentrabajo = rec_ord.idordentrabajo
						      and idboleano = 1
						      and idareaclasificacion in (0,1,2,3,4,5)
						     group by idimprimehojas
					    ) as tabla
				   into sp_canthr;
			  
			   end if;	
			     
			   -- aca sacamos la cantidad de piezas liberadas de control de calidad
			   select count(*) , 
                      max(fechatermino)
			     into sp_liberadascc,
			          sp_fechamaxlcc
			     from mct_movimientoordentrabajo
			    where codigoaccion = 'L_CC'
			      and idordentrabajo = rec_ord.idordentrabajo; 
			     
			   sp_dias_lcc := 0;
			   sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
			      
			   if ( sp_canthr = 0) then
			       sp_avance := 0;
			   else
			       --sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
				   sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			       if (sp_avance >= 100 ) then
			           sp_color_status  := 1;
			       end if;
               end if;

               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
                 			     
               if sp_dias_atraso_status < 0 then 
                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
               end if;
              
   			   --if now() > sp_fecha_entdes then 
   			   --   sp_color_status  := 3;
   			   --elsif sp_calculo_itement < 80 then
   			   --   sp_color_status  := 1;  
   			   --else
   			   --   sp_color_status  := 1;  
   			   --end if;

              
		
			   -- Fundicion
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          --codigoqr, 
				          max(fecharequerida)
				     into sp_cantidad_fu,
				    --      sp_codigoqr_fu,
				          sp_fecharequerida_fu
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd in ('FAB_FU','FAB_FUPL')
				      and idordentrabajo = rec_ord.idordentrabajo;
				      --group by fecharequerida;
				     
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_fu,
				          sp_maxfecha_fu
				     from mct_checklistinftecrecept
				    where codigoqr = rec_ord.idordentrabajo||'FAB_FU' or 
				          codigoqr = rec_ord.idordentrabajo||'FAB_FUPL'; 				     

				   if (sp_cantidad_fu = 0 ) then
	                   sp_cantidad_fu := 1;
	               end if;
	              
				   sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
				   sp_atraso_fu := 0;
				  
				   sp_color_fu  := 0;
				   if ( sp_avance_fu >= 100) then
				       sp_color_fu   := 1;
				   end if;
				  
				   if ( sp_cantidad_fu = 0 ) then
				       sp_avance_fu = 999;
				   end if;
				 
			  
			  
			   -- Pañol
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_pa,
				          sp_codigoqr_pa,
				          sp_fecharequerida_pa				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'FAB_PA'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_pa,
				          sp_maxfecha_pa		   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_pa;

			       if (sp_cantidad_pa = 0 ) then
                       sp_cantidad_pa := 1;
                   end if;
              
				   sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    
			       sp_atraso_pa := 0;

				   sp_color_pa  := 0;			      
			       if ( sp_avance_pa >= 100) then
				       sp_color_pa   := 1;
				   end if;
				  
				   --if ( sp_maxfecha_pa > sp_fecharequerida_pa ) then
				   --    sp_atraso_pa  := date_part('day', sp_maxfecha_pa -  sp_fecharequerida_pa );
				   --    sp_color_pa   := 3;
				   --else
				   --    sp_color_pa   := 1;			   
				   --end if;				 
			  
			   -- Caldereria
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_ca,
				          sp_codigoqr_ca,
				          sp_fecharequerida_ca				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'FAB_CA'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_ca,
				          sp_maxfecha_ca	   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_ca; 

			       if (sp_cantidad_ca = 0 ) then
                      sp_cantidad_ca := 1;
                   end if;
              
				   sp_avance_ca := round((sp_recept_ca * 100.00 ) / sp_cantidad_ca , 2);

				   sp_color_ca  := 0;					  
			       if ( sp_avance_ca >= 100) then
				       sp_color_ca   := 1;
				   end if;				  
				  
				   --if ( sp_maxfecha_ca > sp_fecharequerida_ca ) then
				   --    sp_atraso_ca  := date_part('day', sp_maxfecha_ca -  sp_fecharequerida_ca );
				   --    sp_color_ca   := 3;
				   --else
				   --    sp_color_ca   := 1;			   
				   --end if;					 
				 
			   -- Compras
				   -- aca sacamos las piezas totales solicitadas a compras  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_co,
				          sp_codigoqr_co,
				          sp_fecharequerida_co				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'RPO'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_co,
				          sp_maxfecha_co	 			   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_co;			    

			       sp_atraso_co := 0;
			       if (sp_cantidad_co = 0 ) then
                       sp_cantidad_co := 1;
                   end if;				   
				   
				   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			

				   sp_color_co  := 0;				  
			       if ( sp_avance_co >= 100) then
				       sp_color_co   := 1;
				   end if;	
				  
				   --if ( sp_maxfecha_co > sp_fecharequerida_co ) then
				   --    sp_atraso_co  := date_part('day', sp_maxfecha_co -  sp_fecharequerida_co );
				   --    sp_color_co   := 3;
				   --else
				   --    sp_color_co   := 1;			   
				   --end if;					 
				 
			   -- Taller Mecanico
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_ot,
				          sp_codigoqr_ot,
				          sp_fecharequerida_ot				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'OTROS'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_ot,
				          sp_maxfecha_ot				   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_ot;					    

			       if (sp_cantidad_ot = 0 ) then
                       sp_cantidad_ot := 1;
                   end if;					   
				   
				   sp_avance_ot := round((sp_recept_ot * 100.00 ) / sp_cantidad_ot , 2);						    
			       sp_atraso_ot := 0;

				   sp_color_ot  := 0;				      
			       if ( sp_avance_ot >= 100) then
				       sp_color_ot   := 1;
				   end if;	
				  
				   --if ( sp_maxfecha_ot > sp_fecharequerida_ot ) then
				   --    sp_atraso_ot  := date_part('day', sp_maxfecha_ot - sp_fecharequerida_ot );
				   --    sp_color_ot   := 3;
				   --else
				   --    sp_color_ot   := 1;			   
				   --end if;					 

			   -- Stock Cc
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_cc,
				          sp_codigoqr_cc,
				          sp_fecharequerida_cc				          
				     from mct_checklistinftecvalido mc 
				    where tipotrabajostd = 'STOCK_CC'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_cc,
				          sp_maxfecha_cc				   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_ot;					    

			       if (sp_cantidad_cc = 0 ) then
                       sp_cantidad_cc := 1;
                   end if;					   
				   
				   sp_avance_cc := round((sp_recept_cc * 100.00 ) / sp_cantidad_cc , 2);						    
			       sp_atraso_cc := 0;

				   sp_color_cc  := 0;			      
			       if ( sp_avance_cc >= 100) then
				       sp_color_cc   := 1;
				   end if;	
				  					  
				  
				   --if ( sp_maxfecha_cc > sp_fecharequerida_cc ) then
				   --    sp_atraso_cc  := date_part('day', sp_maxfecha_cc - sp_fecharequerida_cc );
				   --    sp_color_cc   := 3;
				   --else
				   --    sp_color_cc   := 1;			   
				   --end if;
				  
	      --  sp_dias_av := date_part('day' , rec_ord.fechaentrega - now() )
	      
	      --  Para elementos de desgaste
	        sp_subproducto := '';
	        sp_cantidad := 0;
	      
		    if rec_ord.idfamilia = 11 then
		   
		        select count(distinct b.nombreproductonepcast)
		          into sp_cantidad
				  from mct_ordentrabajorepuesto a,
					   mct_productonepcast b
				 where a.idordentrabajo = rec_ord.idordentrabajo
				   and a.idproductonepcast  = b.idproductonepcast ;


				if sp_cantidad > 1 then
				
					sp_subproducto := 'Varios';
				else
				
					select distinct b.nombreproductonepcast
			          into sp_subproducto
					  from mct_ordentrabajorepuesto a,
						   mct_productonepcast b
					 where a.idordentrabajo = rec_ord.idordentrabajo
					   and a.idproductonepcast  = b.idproductonepcast ;
				  
				end if;
		   
	       
	        end if;
	       
		    itemot         := rec_ord.item;
		    idworkorder    := rec_ord.idordentrabajo;
			auttype        := rec_ord.tipoautoriza;	    
			--ordertypename  := rec_ord.nombretipoorden;
			ordertypename  := rec_ord.siglatipo;		
			username       := rec_ord.nombre;
		    --familyname     := rec_ord.nombrefamilia;
		    familyname     := rec_ord.siglafam;	
			productname    := rec_ord.producto;
			subproductname := sp_subproducto;
		    customername   := rec_ord.nombrecorto;
	        --deliverydatetm     := to_char(sp_fecha_entdes - interval '7 days','dd-mm-yyyy');
			--deliverydateclte   := to_char(sp_fecha_entdes,'dd-mm-yyyy');
			
		    deliverydatetm := rec_ord.fechaentregatm;
		    deliverydateclte := coalesce(rec_ord.fechaentregaclte,'S/F');
		   
		    --statusdispatch := sp_dias_atraso_status;
			  
			    if (rec_ord.idordentrabajo in (30322,30374) ) then
			       sp_avance   := 100;
			       sp_color_status := 1;
			    else
			       sp_color_status := 0;		    
			    end if;
			   
			    if (sp_avance >= 100) then
			        statusdispatch  := sp_dias_lcc;
			    else
			    	statusdispatch  := rec_ord.dias;
			    end if;
			   
			   	if ( sp_cantidad_fu is null) then
			        sp_avance_fu := 999;
			    end if;
			    if ( sp_cantidad_pa is null) then
			        sp_avance_pa := 999;
			    end if;
			   	if ( sp_cantidad_ca is null) then
			        sp_avance_ca := 999;
			    end if;
			    if ( sp_cantidad_co is null) then
			        sp_avance_co := 999;
			    end if;
			   	if ( sp_cantidad_ot is null) then
			        sp_avance_ot := 999;
			    end if;
			   	if ( sp_cantidad_cc is null) then
			        sp_avance_cc := 999;
			    end if;
			   
	
			    if (rec_ord.checklistvalido = false) then
			        sp_avance_fu := 888;
			        sp_avance_pa := 888;
			        sp_avance_ca := 888;
			        sp_avance_co := 888;
			        sp_avance_ot := 888;
			        sp_avance_cc := 888;				    
			    end if;
			    statuscliente  := rec_ord.diascliente;	
			   
			    select coalesce (salav)
                  into sp_funcav 
                  from traking.calcularavancemecanizado(rec_ord.idordentrabajo);
 
				advance        := sp_funcav;
			    --advance        := sp_avance;
			
		    advancefu      := coalesce(sp_avance_fu,0);
			advancepa      := coalesce(sp_avance_pa,0);
			advanceca      := coalesce(sp_avance_ca,0);
			advanceco      := coalesce(sp_avance_co,0);
			advanceot      := coalesce(sp_avance_ot,0);
			advancecc      := coalesce(sp_avance_cc,0);		
			itemcolor      := coalesce(sp_color_item,0);
   			statuscolor    := coalesce(sp_color_status,0);   		
			fucolor        := sp_color_fu;
			pacolor        := sp_color_pa;
			cacolor        := sp_color_ca;		
			cocolor        := sp_color_co;
			otcolor        := sp_color_ot;	
			cccolor        := sp_color_cc;			
			delayfu        := coalesce(sp_atraso_fu,0); 
			delaypa        := coalesce(sp_atraso_pa,0); 
			delayca        := coalesce(sp_atraso_ca,0); 
			delayco        := coalesce(sp_atraso_co,0); 
			delayot        := coalesce(sp_atraso_ot,0); 
			delaycc        := coalesce(sp_atraso_cc,0); 		
		    flagfact       := rec_ord.flagfacturacion;
		    fundiciondate  := rec_ord.fechafundicion;
		   
		    select count(*)
		      into sp_estaenproceso
		      from traking.mct_movimientoordentrabajo a
		     where a.idordentrabajo = rec_ord.idordentrabajo
		       and a.estadoactividad = 1;
		      
		    estaenproceso  := sp_estaenproceso;
		   
		    piezas		   := cast('' as varchar);
			
		    montototaldesp	:= 0;
		    montoarrastre	:= 0;
		   
	         if (rec_ord.idfamilia = 8) then
	         
	         	select coalesce(sum(montorepfab),0)
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	    --montoarrastre	:= montototalot - montototaldesp;
	         	    montoarrastre	:= montototalot;
	         	
	         	else
	         	
	         		montoarrastre	:= montototalot - montototaldesp;
	         	
	         	end if;	         	
	         
	         elsif (rec_ord.idfamilia = 11) then
	         
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into montototalot
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select sum(b.qdespacho * c.costo ) 
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
	         	
		        select sum(b.qdespacho * c.costo ) 
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		        montoarrastre	:= montototalot - montoarrastre;
		         	    	  
	         elsif (rec_ord.idfamilia = 10 or rec_ord.idfamilia = 15) then
	
	           	select coalesce(sum(montorepfab),0) 
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into sp_montoadicional
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	montototalot	:= montototalot + sp_montoadicional;
	         
	            select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		         	  
		        select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	    	
		        montoarrastre	:= montototalot - montoarrastre;

	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	end if;	    
	         
	         else
	         
	         	montototalot	:= 0;
	         
	         end if;
	        
	        --montoarrastre	:= 0;
				        
	        if (montototalot > montoarrastre) then
	        
	        	return next;
	       
	        end if;

		END LOOP;	    
	   
END;
$$;


ALTER FUNCTION traking.evtlistmanagerscreenfacturacioncalendario_consolidadosumaanteri(periodo character varying, agno bigint) OWNER TO postgres;

--
-- TOC entry 2234 (class 1255 OID 17153)
-- Name: evtlistmanagerscreenfacturacioncalendariodesgaste_consolidado(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmanagerscreenfacturacioncalendariodesgaste_consolidado(periodo character varying, agno bigint) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying, piezas character varying, estaenproceso bigint, montototalot bigint, montototaldesp bigint, montoarrastre bigint, montodespachadosanteriores bigint, montodespachadoporguia bigint)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_funcav			   numeric;
   
    sp_canthr              integer;
    sp_liberadascc         integer;
   
    rec_ord          	   record;
   
    rec_ordcomp            record;
   
    sp_lista			   varchar;
   
   	sp_fechamaxlcc         timestamp;
	sp_dias_lcc            integer;

    -- nepcast
    sp_cantidad            integer;
    sp_subproducto         varchar;
    -- Variable para fundicion
    sp_cantidad_fu         integer; 
	sp_codigoqr_fu         varchar;  
	sp_fecharequerida_fu   timestamp;

    -- Variable para pañol
    sp_cantidad_pa         integer; 
	sp_codigoqr_pa         varchar;  
	sp_fecharequerida_pa   timestamp;

    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    -- Variable para stock cc
    sp_cantidad_cc         integer; 
	sp_codigoqr_cc         varchar;  
	sp_fecharequerida_cc   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
    sp_avance_cc           numeric;
    sp_atraso_cc           integer;  
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
    sp_recept_cc           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
    sp_color_cc            integer;   
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
    sp_dias_cc             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
    sp_dias_atraso_cc      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
    sp_maxfecha_cc         timestamp;
   
    sp_nombreproducto	   varchar;
   
    sp_muestraorden		   integer;
    sp_countcheck		   integer;
    
    sp_indice              integer;
   
    sp_sumatotallcc        integer;
   
    rec_lcc      			RECORD;
   
    sp_fami					integer;
    sp_mec					integer;
   
    sp_estaenproceso        bigint;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar; 
   
    sp_montoadicional		bigint;
   
begin
	 
	sp_estaenproceso	:= 0;

--	if ( idfamily = 111) then
	   sp_fami = 11;
	   sp_mec = 1;
--	elsif ( idfamily = 112) then
--	   sp_fami = 11;
--	   sp_mec = 2;	
--	end if;
	

	select to_char(now(),'yyyy')
	  into ano;
	 
	select lpad(periodo, 2,'0')
	  into mes;
	 
	fechadesde	:= agno||'-'||mes||'-01';

    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
	  into ultimodia;
	 
	select to_char(now(),'yyyy')
	--select to_char(now() + interval '1 year','yyyy')
	  into anofin;
	 
	fechahasta	:= agno||'-'||mes||'-'||ultimodia;

    --fechadesde	:= '2023-10-24';

	  --  if ( desde != 'NA' and hasta != 'NA') then

				FOR rec_ord IN (   
				
				        select ROW_NUMBER() OVER (ORDER BY fechaentrega asc) AS item,
				               idproducto,
				               idordentrabajo,
				               idestadoorden,
				               tipoautoriza,
				               nombretipoorden,
				               nombrefamilia,
				               producto,
				               nombrecorto,
				               fechaentrega,
				               fechaentregatm,
				               fechafacetm,
				               fechaentregaclte,
				               dias,
				               diascliente,
				               idmodalidadcreacion,
				               nombre,
				               flagfacturacion,
				               siglatipo,
				               siglafam,
				               fechafundicion,
				               idfamilia
				          from (
								select a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_CON'||'_'||a.idestadoorden as nombrefamilia,
								       --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
								       case 
								          when a.idfamilia = 11 then c.nombreproducto
								          else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
								       end as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       j.nombre ,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_CON'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy')) as fechafundicion,
--									       when sp_mec = 2 then 
--									            to_char(a.fechafundicion ,'dd-mm-yyyy')
--									   end as fechafundicion,
									   a.idfamilia	
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_producto c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_modelo g,
								       mct_subfamilia h,
								       mct_etapaparam i,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproducto 
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and c.idmodelo = g.idmodelo 
								   and g.idsubfamilia = h.idsubfamilia 
								   and c.idetapaparam = i.idetapaparam 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   and a.idusuario = j.idusuario 
								   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
								   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           --and (a.fechafundicion2 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           --and a.flagfacturacion is true
								   and a.debaja < 1
								   --order by a.fechafaceclte asc

							union 
								select --ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
								       a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_CON'||'_'||a.idestadoorden as nombrefamilia,
	                                   c.nombreproductonepcast  as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       j.nombre ,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_CON'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy')) as fechafundicion,
--									       when sp_mec = 2 then 
--									            to_char(a.fechafundicion ,'dd-mm-yyyy')
--									   end as fechafundicion,
									   a.idfamilia
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_productonepcast c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproductonepcast  
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   and c.idresponsable = j.idusuario 
								   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
								   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           --and (a.fechafundicion2 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           --and a.flagfacturacion is true
								   and a.debaja < 1							
							--- Desde aca la nueva union
								   
						union
							    select a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_SIN'||'_'||a.idestadoorden as nombrefamilia,
								       --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
								       case 
								          when a.idfamilia = 11 then c.nombreproducto
								          else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
								       end as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       j.nombre ,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_SIN'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
--									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
--									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'))
--									       when sp_mec = 2 then 
									            to_char(a.fechafundicion ,'dd-mm-yyyy') as fechafundicion,
--									   end as fechafundicion,
									   a.idfamilia	
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_producto c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_modelo g,
								       mct_subfamilia h,
								       mct_etapaparam i,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproducto 
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and c.idmodelo = g.idmodelo 
								   and g.idsubfamilia = h.idsubfamilia 
								   and c.idetapaparam = i.idetapaparam 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   and a.idusuario = j.idusuario 
								   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 2)
								   --and (a.fechaentrega >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						           and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						          -- and a.flagfacturacion is true
								   and a.debaja < 1
								   --order by a.fechafaceclte asc

							union 
								select --ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
								       a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_SIN'||'_'||a.idestadoorden as nombrefamilia,
	                                   c.nombreproductonepcast  as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       j.nombre ,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_SIN'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
--									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
--									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'))
--									       when sp_mec = 2 then 
									            to_char(a.fechafundicion ,'dd-mm-yyyy') as fechafundicion,
--									   end as fechafundicion,
									   a.idfamilia
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_productonepcast c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproductonepcast  
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
								   and c.idresponsable = j.idusuario 
								   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
								   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
								   and a.idfamilia = 11
								   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 2)
								   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						          -- and a.flagfacturacion is true
								   and a.debaja < 1	
							 ) tab
						     order by fechaentrega asc
								   
							)
				loop 	
				
				       -- colores seran
				       -- 1 : verde
				       -- 2 : amarillo
				       -- 3 : rojo
				       
				       -- sacamos el rango de fechas para el color de entrega
		   
		               select min(fecha_inicio), 
		                      max(fecha_termino),
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
		                      date_part('day', max(fecha_termino) - now() ) ,
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
		                 into sp_fecha_auto,
		                      sp_fecha_entdes,
		                      dias_entrega,
		                      dias_resto,
		                      dias_calculo
		                 from mct_progavisos 
		                where idordentrabajo = rec_ord.idordentrabajo
		                  and idsla in (5,8,9);
		                 
		               if (dias_resto = 0 ) then
		                   dias_resto := 1;
		               end if;
		
		              
		   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
		   			   
		   			   if now() > sp_fecha_entdes then 
		   			      sp_color_item    := 3;
		   			      sp_color_entrega := 3;
		   			   elsif sp_calculo_itement < 80 then
			   			      sp_color_item    := 1;
			   			      sp_color_entrega := 1;   			   
		   			   elsif sp_calculo_itement >= 80 then
		 	   			      sp_color_item    := 2;
			   			      sp_color_entrega := 2;     			   
		   			   end if; 
		                  

		   			   -- desde aca el nuevo calculo
			   		   sp_sumatotallcc  := 0;
			   			   
			   		   FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec_ord.idordentrabajo
								       and a.idhojaruta = b.idhojaruta 
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
				     			   select coalesce (sum(cantidad),0)
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5);
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  	   		   			  
				       -- aca sacamos la cantidad de piezas totales
					   select coalesce ( sum(cantidad), 0)
					     into sp_canthr
					     from mct_hojarutatemp mh
					    where idordentrabajo = rec_ord.idordentrabajo
					      and idboleano = 1
					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   -- aca sacamos la cantidad de piezas liberadas de control de calidad
					   select count(*) , 
		                      max(fechatermino)
					     into sp_liberadascc,
					          sp_fechamaxlcc
					     from mct_movimientoordentrabajo
					    where codigoaccion = 'L_CC'
					      and idordentrabajo = rec_ord.idordentrabajo; 
					     
					   sp_dias_lcc := 0;
					   sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
					      
					   if ( sp_canthr = 0) then
					       sp_avance := 0;
					   else
					       --sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
						   sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
					       if (sp_avance >= 100 ) then
					           sp_color_status  := 1;
					       end if;
		               end if;
		
		               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
		                 			     
		               if sp_dias_atraso_status < 0 then 
		                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
		               end if;
		                        
					   -- Fundicion
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_fu,
						          sp_codigoqr_fu,
						          sp_fecharequerida_fu
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_FU'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_fu,
						          sp_maxfecha_fu
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_fu; 
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						   sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_atraso_fu := 0;
						  
						   sp_color_fu  := 0;
						   if ( sp_avance_fu >= 100) then
						       sp_color_fu   := 1;
						   end if;
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;
						  
						   --if ( sp_maxfecha_fu > sp_fecharequerida_fu ) then
						   --    sp_atraso_fu  := date_part('day', sp_maxfecha_fu -  sp_fecharequerida_fu );
						   --    sp_color_fu   := 3;
						   --else
						   --    sp_color_fu   := 1;			   
						   --end if;
					  
					  
					   -- Pañol
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_pa,
						          sp_codigoqr_pa,
						          sp_fecharequerida_pa				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_PA'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_pa,
						          sp_maxfecha_pa		   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_pa;
		
					       if (sp_cantidad_pa = 0 ) then
		                       sp_cantidad_pa := 1;
		                   end if;
		              
						   sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    
					       sp_atraso_pa := 0;
		
						   sp_color_pa  := 0;			      
					       if ( sp_avance_pa >= 100) then
						       sp_color_pa   := 1;
						   end if;
						  
						   --if ( sp_maxfecha_pa > sp_fecharequerida_pa ) then
						   --    sp_atraso_pa  := date_part('day', sp_maxfecha_pa -  sp_fecharequerida_pa );
						   --    sp_color_pa   := 3;
						   --else
						   --    sp_color_pa   := 1;			   
						   --end if;				 
					  
					   -- Caldereria
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_ca,
						          sp_codigoqr_ca,
						          sp_fecharequerida_ca				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_CA'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_ca,
						          sp_maxfecha_ca	   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ca; 
		
					       if (sp_cantidad_ca = 0 ) then
		                      sp_cantidad_ca := 1;
		                   end if;
		              
						   sp_avance_ca := round((sp_recept_ca * 100.00 ) / sp_cantidad_ca , 2);
		
						   sp_color_ca  := 0;					  
					       if ( sp_avance_ca >= 100) then
						       sp_color_ca   := 1;
						   end if;				  
				 
						 
					   -- Compras
						   -- aca sacamos las piezas totales solicitadas a compras  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_co,
						          sp_codigoqr_co,
						          sp_fecharequerida_co				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'RPO'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_co,
						          sp_maxfecha_co	 			   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_co;			    
		
					       sp_atraso_co := 0;
					       if (sp_cantidad_co = 0 ) then
		                       sp_cantidad_co := 1;
		                   end if;				   
						   
						   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			
		
						   sp_color_co  := 0;				  
					       if ( sp_avance_co >= 100) then
						       sp_color_co   := 1;
						   end if;				 
						 
					   -- Taller Mecanico
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_ot,
						          sp_codigoqr_ot,
						          sp_fecharequerida_ot				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'OTROS'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_ot,
						          sp_maxfecha_ot				   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ot;					    
		
					       if (sp_cantidad_ot = 0 ) then
		                       sp_cantidad_ot := 1;
		                   end if;					   
						   
						   sp_avance_ot := round((sp_recept_ot * 100.00 ) / sp_cantidad_ot , 2);						    
					       sp_atraso_ot := 0;
		
						   sp_color_ot  := 0;				      
					       if ( sp_avance_ot >= 100) then
						       sp_color_ot   := 1;
						   end if;	

					   -- Stock Cc
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_cc,
						          sp_codigoqr_cc,
						          sp_fecharequerida_cc				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'STOCK_CC'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_cc,
						          sp_maxfecha_cc				   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ot;					    
		
					       if (sp_cantidad_cc = 0 ) then
		                       sp_cantidad_cc := 1;
		                   end if;					   
						   
						   sp_avance_cc := round((sp_recept_cc * 100.00 ) / sp_cantidad_cc , 2);						    
					       sp_atraso_cc := 0;
		
						   sp_color_cc  := 0;			      
					       if ( sp_avance_cc >= 100) then
						       sp_color_cc   := 1;
						   end if;	

			      --  sp_dias_av := date_part('day' , rec_ord.fechaentrega - now() )
			      
			      --  Para elementos de desgaste
			        sp_subproducto := '';
			        sp_cantidad := 0;
			      
				    if rec_ord.idfamilia = 11 then
				   
				        select count(distinct b.nombreproductonepcast)
				          into sp_cantidad
						  from mct_ordentrabajorepuesto a,
							   mct_productonepcast b
						 where a.idordentrabajo = rec_ord.idordentrabajo
						   and a.idproductonepcast  = b.idproductonepcast ;
		
		
						if sp_cantidad > 1 then
						
							sp_subproducto := 'Varios';
						else
						
							select distinct b.nombreproductonepcast
					          into sp_subproducto
							  from mct_ordentrabajorepuesto a,
								   mct_productonepcast b
							 where a.idordentrabajo = rec_ord.idordentrabajo
							   and a.idproductonepcast  = b.idproductonepcast ;
						  
						end if;
				   
			       
			        end if;
			       
				    itemot         := rec_ord.item;
				    idworkorder    := rec_ord.idordentrabajo;
					auttype        := rec_ord.tipoautoriza;	    
					--ordertypename  := rec_ord.nombretipoorden;
					ordertypename  := rec_ord.siglatipo;		
					username       := rec_ord.nombre;
				    --familyname     := rec_ord.nombrefamilia;
				    familyname     := rec_ord.siglafam;	
					productname    := rec_ord.producto;
					subproductname := sp_subproducto;
				    customername   := rec_ord.nombrecorto;
			        --deliverydatetm     := to_char(sp_fecha_entdes - interval '7 days','dd-mm-yyyy');
					--deliverydateclte   := to_char(sp_fecha_entdes,'dd-mm-yyyy');
					
				    deliverydatetm := rec_ord.fechaentregatm;
				    deliverydateclte := rec_ord.fechaentregaclte;
				   
				    --statusdispatch := sp_dias_atraso_status;
				  
				    if (rec_ord.idordentrabajo in (30322,30374) ) then
				       sp_avance   := 100;
				       sp_color_status := 1;
				    else
				       sp_color_status := 0;		    
				    end if;
				   
				    if (sp_avance >= 100) then
				        statusdispatch  := sp_dias_lcc;
				    else
				    	statusdispatch  := rec_ord.dias;
				    end if;
				   
				   	if ( sp_cantidad_fu is null) then
				        sp_avance_fu := 999;
				    end if;
				    if ( sp_cantidad_pa is null) then
				        sp_avance_pa := 999;
				    end if;
				   	if ( sp_cantidad_ca is null) then
				        sp_avance_ca := 999;
				    end if;
				    if ( sp_cantidad_co is null) then
				        sp_avance_co := 999;
				    end if;
				   	if ( sp_cantidad_ot is null) then
				        sp_avance_ot := 999;
				    end if;
				   	if ( sp_cantidad_cc is null) then
				        sp_avance_cc := 999;
				    end if;
				   
		
				    statuscliente  := rec_ord.diascliente;	
				   
					--advance        := sp_avance;
					select coalesce (salav)
	                  into sp_funcav 
	                  from traking.calcularavancemecanizado(rec_ord.idordentrabajo);
	 
					advance        := sp_funcav;
					
				    advancefu      := coalesce(sp_avance_fu,0);
					advancepa      := coalesce(sp_avance_pa,0);
					advanceca      := coalesce(sp_avance_ca,0);
					advanceco      := coalesce(sp_avance_co,0);
					advanceot      := coalesce(sp_avance_ot,0);
					advancecc      := coalesce(sp_avance_cc,0);		
					itemcolor      := coalesce(sp_color_item,0);
		   			statuscolor    := coalesce(sp_color_status,0);   		
					fucolor        := sp_color_fu;
					pacolor        := sp_color_pa;
					cacolor        := sp_color_ca;		
					cocolor        := sp_color_co;
					otcolor        := sp_color_ot;	
					cccolor        := sp_color_cc;			
					delayfu        := coalesce(sp_atraso_fu,0); 
					delaypa        := coalesce(sp_atraso_pa,0); 
					delayca        := coalesce(sp_atraso_ca,0); 
					delayco        := coalesce(sp_atraso_co,0); 
					delayot        := coalesce(sp_atraso_ot,0); 
					delaycc        := coalesce(sp_atraso_cc,0); 		
				    flagfact       := rec_ord.flagfacturacion;
				    fundiciondate  := rec_ord.fechafundicion;
				   
					sp_lista := '(';
									   
					FOR rec_ordcomp IN (   
						select nombrecomponentetemp||'('||cantidad||') '||nombreplano  as pieza
						      from mct_ordentrabajorepuesto mo 
						     where idordentrabajo = rec_ord.idordentrabajo 
							)
					    loop 	
						    
						    sp_lista := rec_ordcomp.pieza||' / '||sp_lista;
										           
					END LOOP;
				
				    piezas		:= cast(substring(sp_lista,1,length(sp_lista)-3) as varchar);
				   
				    select count(*)
				      into sp_estaenproceso
				      from traking.mct_movimientoordentrabajo a
				     where a.idordentrabajo = rec_ord.idordentrabajo
				       and a.estadoactividad = 1;
				      
				    estaenproceso  := sp_estaenproceso;

		    montototaldesp	:= 0;
		    montoarrastre	:= 0;
		   
	         if (rec_ord.idfamilia = 8) then
	         
	         	select coalesce(sum(montorepfab),0)
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	    montoarrastre	:= montototalot - montototaldesp;
	         	
	         	else
	         	
	         		montoarrastre	:= montototalot - montototaldesp;
	         	
	         	end if;	         	
	         
	         elsif (rec_ord.idfamilia = 11) then
	         
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into montototalot
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(b.qdespacho * c.costo ) , 0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
	         	
		        select coalesce(sum(b.qdespacho * c.costo ) , 0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		        montoarrastre	:= montototalot - montoarrastre;
		         	    	  
	         elsif (rec_ord.idfamilia = 10 or rec_ord.idfamilia = 15) then
	
	           	select coalesce(sum(montorepfab),0) 
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into sp_montoadicional
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	montototalot	:= montototalot + sp_montoadicional;
	         
	            select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		         	  
		        select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	    	
		        montoarrastre	:= montototalot - montoarrastre;
	         	
	         else
	         
	         	montototalot	:= 0;
	         
	         
	         end if;	
	        
	        montodespachadosanteriores	:= 0;
	       
	        select coalesce(sum(b.qdespacho * c.costo ) , 0)*-1
         	  into montodespachadosanteriores
         	  from mct_despachopartecabecera a ,
         	       mct_despachopartedetalle b,
         	       mct_ordentrabajorepuesto c
         	 where a.idordentrabajo = rec_ord.idordentrabajo
         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
	        
	        montodespachadoporguia	:= 0;
				       
			return next;
		
			END LOOP;	    
	    
	  --  end if;


END;
$$;


ALTER FUNCTION traking.evtlistmanagerscreenfacturacioncalendariodesgaste_consolidado(periodo character varying, agno bigint) OWNER TO postgres;

--
-- TOC entry 1665 (class 1255 OID 17155)
-- Name: evtlistmanagerscreenfacturacioncalendariodesgaste_consolidado_2(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmanagerscreenfacturacioncalendariodesgaste_consolidado_2(periodo character varying, agno bigint) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying, piezas character varying, estaenproceso bigint, montototalot bigint, montototaldesp bigint, montoarrastre bigint)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_canthr              integer;
    sp_liberadascc         integer;
   
    rec_ord          	   record;
   
    rec_ordcomp            record;
   
    sp_lista			   varchar;
   
   	sp_fechamaxlcc         timestamp;
	sp_dias_lcc            integer;

    -- nepcast
    sp_cantidad            integer;
    sp_subproducto         varchar;
    -- Variable para fundicion
    sp_cantidad_fu         integer; 
	sp_codigoqr_fu         varchar;  
	sp_fecharequerida_fu   timestamp;

    -- Variable para pañol
    sp_cantidad_pa         integer; 
	sp_codigoqr_pa         varchar;  
	sp_fecharequerida_pa   timestamp;

    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    -- Variable para stock cc
    sp_cantidad_cc         integer; 
	sp_codigoqr_cc         varchar;  
	sp_fecharequerida_cc   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
    sp_avance_cc           numeric;
    sp_atraso_cc           integer;  
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
    sp_recept_cc           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
    sp_color_cc            integer;   
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
    sp_dias_cc             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
    sp_dias_atraso_cc      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
    sp_maxfecha_cc         timestamp;
   
    sp_nombreproducto	   varchar;
   
    sp_muestraorden		   integer;
    sp_countcheck		   integer;
    
    sp_indice              integer;
   
    sp_sumatotallcc        integer;
   
    rec_lcc      			RECORD;
   
    sp_fami					integer;
    sp_mec					integer;
   
    sp_estaenproceso       bigint;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar; 
   
    sp_montoadicional		bigint;
   
begin
	 
	sp_estaenproceso	:= 0;

--	if ( idfamily = 111) then
	   sp_fami = 11;
	   sp_mec = 1;
--	elsif ( idfamily = 112) then
--	   sp_fami = 11;
--	   sp_mec = 2;	
--	end if;
	

	select to_char(now(),'yyyy')
	  into ano;
	 
	select lpad(periodo, 2,'0')
	  into mes;
	 
	fechadesde	:= agno||'-'||mes||'-01';

    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
	  into ultimodia;
	 
	select to_char(now(),'yyyy')
	--select to_char(now() + interval '1 year','yyyy')
	  into anofin;
	 
	fechahasta	:= agno||'-'||mes||'-'||ultimodia;

    --fechadesde	:= '2023-10-24';

	  --  if ( desde != 'NA' and hasta != 'NA') then
	    
				FOR rec_ord IN (   
--						select ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
--						       a.idordentrabajo ,
--						       case 
--						          when a.ordencompra > 0 then 'OC'
--						          when a.ordencompra = 0 then 'OI'
--						          else 'OI'
--						       end as tipoautoriza,   
--						       d.nombretipoorden ,
--						       e.nombrefamilia ,
--							   --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
--							   case 
--								  when a.idfamilia = 11 then c.nombreproducto
--								  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
--							   end as producto,
--						       b.nombrecorto ,
--						       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
--						       fechafacetm,
--						       --to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,	
--						       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,
--						       --date_part('day', a.fechafaceclte - now()) as dias,
--						       date_part('day', a.fechafacetm - current_date) as dias,
--						       date_part('day', a.fechafaceclte - current_date) as diascliente,	
--						       a.idmodalidadcreacion ,
--						       j.nombre ,
--						       a.flagfacturacion ,
--						       d.sigla as siglatipo,
--						       case
--						       		when a.idproyecto = 1 then
--						       		  e.sigla||'_PYTO'
--						        	else
--						        	  e.sigla
--						       end as siglafam,
--						       case
--							       when 1 = 1 then
--							            --1 (to_char(a.fechafundicion,'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
--							            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'))
--							       when 1 = 2 then 
--							            to_char(a.fechafundicion ,'dd-mm-yyyy')
--							   end as fechafundicion						       
--						  from mct_ordentrabajo a,
--						       mct_cliente b,
--						       mct_producto c,
--						       mct_tipoorden d,
--						       mct_familia e,
--						       mct_estadoorden f,
--						       mct_modelo g,
--						       mct_subfamilia h,
--						       mct_etapaparam i,
--						       mct_usuario j
--						 where a.idcliente = b.idcliente 
--						   and a.idproducto = c.idproducto 
--						   and a.idtipoorden = d.idtipoorden 
--						   and a.idfamilia = e.idfamilia
--						   and a.idestadoorden = f.idestadoorden 
--						   and c.idmodelo = g.idmodelo 
--						   and g.idsubfamilia = h.idsubfamilia 
--						   and c.idetapaparam = i.idetapaparam 
--						   and a.idordentrabajo >= 30000
--						   and a.idordentrabajo not in (30855)
--						   and a.idusuario = j.idusuario 
--						   --and a.idestadoorden  >= 6 and a.idestadoorden < 9
--						   and a.idestadoorden  >= 6 and a.idestadoorden < 9
--						   and a.idfamilia = 11
--						   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
--						   and a.flagfacturacion is true
--						   --and (a.fechafaceclte >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
--						   and a.debaja < 1
--						   order by a.fechafaceclte asc
						   
				        select ROW_NUMBER() OVER (ORDER BY fechaentrega asc) AS item,
				               idproducto,
				               idordentrabajo,
				               idestadoorden,
				               tipoautoriza,
				               nombretipoorden,
				               nombrefamilia,
				               producto,
				               nombrecorto,
				               fechaentrega,
				               fechaentregatm,
				               fechafacetm,
				               fechaentregaclte,
				               dias,
				               diascliente,
				               idmodalidadcreacion,
				               nombre,
				               flagfacturacion,
				               siglatipo,
				               siglafam,
				               fechafundicion,
				               idfamilia
				          from (
								select a.idproducto ,
								       a.idordentrabajo ,
								       a.idestadoorden ,
								       case 
								          when a.ordencompra > 0 then 'OC'
								          when a.ordencompra = 0 then 'OI'
								          else 'OI'
								       end as tipoautoriza,   
								       d.nombretipoorden ,
								       e.nombrefamilia||'_CON'||'_'||a.idestadoorden as nombrefamilia,
								       --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
								       case 
								          when a.idfamilia = 11 then c.nombreproducto
								          else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
								       end as producto,
								       b.nombrecorto ,
								       a.fechaentrega ,
								       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
								       a.fechafacetm,
								       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
								       --date_part('day', a.fechafaceclte - now()) as dias,
								       date_part('day', a.fechafacetm - current_date) as dias,
								       date_part('day', a.fechafaceclte - current_date) as diascliente,	
								       a.idmodalidadcreacion ,
								       j.nombre ,
								       a.flagfacturacion ,
								       d.sigla as siglatipo,
								       case
								       		when a.idproyecto = 1 then
								       		  e.sigla||'_PYTO'
								        	else
								        	  e.sigla||'_CON'||'_'||a.idestadoorden
								       end as siglafam,
								       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion
--								       case
--									       when sp_mec = 1 then
									            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
									            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy')) as fechafundicion,
--									       when sp_mec = 2 then 
--									            to_char(a.fechafundicion ,'dd-mm-yyyy')
--									   end as fechafundicion,
									   a.idfamilia	
								  from mct_ordentrabajo a,
								       mct_cliente b,
								       mct_producto c,
								       mct_tipoorden d,
								       mct_familia e,
								       mct_estadoorden f,
								       mct_modelo g,
								       mct_subfamilia h,
								       mct_etapaparam i,
								       mct_usuario j
								 where a.idcliente = b.idcliente 
								   and a.idproducto = c.idproducto 
								   and a.idtipoorden = d.idtipoorden 
								   and a.idfamilia = e.idfamilia
								   and a.idestadoorden = f.idestadoorden 
								   and c.idmodelo = g.idmodelo 
								   and g.idsubfamilia = h.idsubfamilia 
								   and c.idetapaparam = i.idetapaparam 
								   and a.idordentrabajo >= 30000
								   and a.idordentrabajo not in (30855)
