				    where tipotrabajostd = 'FAB_PA'
				      and idordentrabajo = rec_ord.idordentrabajo
				      group by codigoqr, fecharequerida;
				   
				   -- aca sacamos el total de piezas recepcionadas   
				   select coalesce ( sum(cantidad), 0),
				          max(fechacreacion)
				     into sp_recept_pa,
				          sp_maxfecha_pa		   
				     from mct_checklistinftecrecept
				    where codigoqr = sp_codigoqr_pa;

			  if (sp_cantidad_pa = 0 ) then
                   sp_cantidad_pa := 1;
               end if;
              
				  sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    
			      sp_atraso_pa := 0;
			  
				   if ( sp_maxfecha_pa > sp_fecharequerida_pa ) then
				       sp_atraso_pa  := date_part('day', sp_maxfecha_pa -  sp_fecharequerida_pa );
				       sp_color_pa   := 3;
				   else
				       sp_color_pa   := 1;			   
				   end if;				 
			  
			   -- Caldereria
				   -- aca sacamos las piezas totales solicitadas a fundicion  
				   select coalesce ( sum(cantidad), 0),
				          codigoqr, 
				          fecharequerida
				     into sp_cantidad_ca,
				          sp_codigoqr_ca,
