-- Name: evtlistmanagerscreenfamiliafacturacion_pendientedespachoz1(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmanagerscreenfamiliafacturacion_pendientedespachoz1(idfamily bigint, desde character varying, hasta character varying) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying, piezas character varying, estaenproceso bigint)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_funcav			   numeric;

	sp_funcavz1				varchar;
   
    rec_ord          	   record;
   
   	sp_fechamaxlcc         timestamp;
	sp_dias_lcc            integer;

    sp_subproducto         varchar;

    sp_avance              numeric;
    
    sp_indice              integer;

    sp_estaenproceso       bigint;
   
begin
	 
	sp_estaenproceso	:= 0;

	sp_indice := 1;

	FOR rec_ord IN (   
	
	        select ROW_NUMBER() OVER (ORDER BY fechaentrega asc) AS item,
