CREATE FUNCTION traking.evtlistmanagerscreenfamiliafacturacion_pruebas(idfamily bigint, desde character varying, hasta character varying) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_canthr              integer;
    sp_liberadascc         integer;
   
    rec_ord          	   record;
   
   	sp_fechamaxlcc         timestamp;
