    -- Variable para caldereria
    sp_cantidad_ca         integer; 
	sp_codigoqr_ca         varchar;  
	sp_fecharequerida_ca   timestamp;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;

    -- Variable para taller mecanico otroa
    sp_cantidad_ot         integer; 
	sp_codigoqr_ot         varchar;  
	sp_fecharequerida_ot   timestamp;

    -- Variable para stock cc
    sp_cantidad_cc         integer; 
	sp_codigoqr_cc         varchar;  
	sp_fecharequerida_cc   timestamp;

    sp_avance              numeric;
    sp_avance_fu           numeric;  --numeric
    sp_atraso_fu           integer;
    sp_avance_pa           numeric;
    sp_atraso_pa           integer;   
    sp_avance_ca           numeric;
    sp_atraso_ca           integer;   
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_avance_ot           numeric;
    sp_atraso_ot           integer;   
    sp_avance_cc           numeric;
    sp_atraso_cc           integer;  
   
    sp_recept_fu           integer;
    sp_recept_pa           integer;
    sp_recept_ca           integer;
    sp_recept_co           integer;
    sp_recept_ot           integer;
    sp_recept_cc           integer;
   
    sp_color_item          integer;
    sp_color_entrega       integer;
    sp_color_status        integer;
    
    sp_color_fu            integer;
    sp_color_pa            integer;
    sp_color_ca            integer;
    sp_color_co            integer;
    sp_color_ot            integer;
    sp_color_cc            integer;   
   
    sp_dias_av             integer;
    sp_dias_fu             integer;
    sp_dias_pa             integer;
    sp_dias_ca             integer;
    sp_dias_co             integer;
    sp_dias_ot             integer;
    sp_dias_cc             integer;
   
    sp_fecha_auto          timestamp;
    sp_fecha_entdes        timestamp;
    dias_entrega           integer;
    dias_resto             integer;   
    dias_calculo           integer;
    sp_calculo_itement     numeric;

    sp_dias_atraso_status  integer;
    sp_dias_atraso_fu      integer;   
    sp_dias_atraso_pa      integer;
    sp_dias_atraso_ca      integer;   
    sp_dias_atraso_co      integer;   
    sp_dias_atraso_ot      integer;   
    sp_dias_atraso_cc      integer;   
   
    sp_maxfecha_fu         timestamp;
    sp_maxfecha_pa         timestamp;
    sp_maxfecha_ca         timestamp;
    sp_maxfecha_co         timestamp;   
    sp_maxfecha_ot         timestamp;
    sp_maxfecha_cc         timestamp;
   
    sp_muestraorden		   integer;
    sp_countcheck		   integer;
    
    sp_indice              integer;
   
    sp_sumatotallcc        integer;
   
    rec_lcc      			RECORD;
   
begin
	 
	if ( idfamily = 99 ) then 

		sp_indice := 1;
	
		FOR rec_ord IN (   
				select ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
				       a.idordentrabajo ,
				       case 
				          when a.ordencompra > 0 then 'S/A'
				          when a.ordencompra = 0 then 'S/A'
				          else 'S/A'
				       end as tipoautoriza,   
				       d.nombretipoorden ,
				       e.nombrefamilia ,
					   --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
					   case 
						  when a.idfamilia = 11 then c.nombreproducto
						  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
					   end as producto,
				       b.nombrecorto ,
				       to_char(a.fechaentrega - interval '7 days','dd-mm-yyyy') as fechaentregatm ,
				       to_char(a.fechafaceclte,'dd-mm-yyyy') as fechaentregaclte ,				       
				       --date_part('day', a.fechaentrega - now()) as dias,
				       date_part('day', a.fechafacetm - current_date) as dias,
				       date_part('day', a.fechafaceclte - current_date) as diascliente,				       
				       a.idmodalidadcreacion ,
				       j.nombre ,
				       a.flagfacturacion,
				       d.sigla as siglatipo,
				       e.sigla as siglafam,
				       a.idfamilia ,
				       --to_char(a.fechaentrega - interval '21 days','dd-mm-yyyy') as fechafundicion,
				       coalesce (to_char(a.fechafundicion2, 'dd-mm-yyyy' ), to_char(a.fechaentrega - interval '21 days','dd-mm-yyyy')) as fechafundicion,
				       a.checklistvalido 
				  from mct_ordentrabajo a,
				       mct_cliente b,
				       mct_producto c,
				       mct_tipoorden d,
				       mct_familia e,
				       mct_estadoorden f,
				       mct_modelo g,
				       mct_subfamilia h,
				       mct_etapaparam i,
				       mct_usuario j
				 where a.idcliente = b.idcliente 
				   and a.idproducto = c.idproducto 
				   and a.idtipoorden = d.idtipoorden 
				   and a.idfamilia = e.idfamilia
				   and a.idestadoorden = f.idestadoorden 
				   and c.idmodelo = g.idmodelo 
				   and g.idsubfamilia = h.idsubfamilia 
				   and c.idetapaparam = i.idetapaparam 
				   and a.idordentrabajo >= 30000
				   and a.idusuario = j.idusuario 
				   --and a.idestadoorden  <= 4
				   and a.idestadoorden  in (2,3,4,5,6)
				   and a.idfamilia in (8,10,15)
				   and a.debaja < 1
				   and a.checklistvalido is not true
				   and a.idordentrabajo not in (30012,30631)
			  order by a.fechaentrega asc
					)
		loop 	
		
		       -- colores seran
		       -- 1 : verde
		       -- 2 : amarillo
		       -- 3 : rojo
		       
		       -- sacamos el rango de fechas para el color de entrega
		
		       sp_muestraorden	:= 1;
		       sp_countcheck	:= 0;
		      
		       if ( rec_ord.idfamilia in (10,15) ) then
		          
		          	select count(*)
		          	  into sp_countcheck
		              from mct_checklistinftec 
		          	 where idordentrabajo = rec_ord.idordentrabajo
		          	   and muestrachecklist is true;
		          	  
		          	if ( sp_countcheck > 0 ) then
		          		
		          		sp_muestraorden	:= 1;
		          	
		          	end if;
		       
		       else
		       
		       		sp_muestraorden := 1;
		       
		       end if;
		
		       if ( sp_muestraorden = 1 ) then 
		       
			       		   select min(fecha_inicio), 
			                      max(fecha_termino),
			                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
			                      date_part('day', max(fecha_termino) - now() ) ,
			                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
			                 into sp_fecha_auto,
			                      sp_fecha_entdes,
			                      dias_entrega,
			                      dias_resto,
			                      dias_calculo
			                 from mct_progavisos 
			                where idordentrabajo = rec_ord.idordentrabajo
			                  and idsla in (5,8,9);
			                 
			               if (dias_resto = 0 ) then
			                   dias_resto := 1;
			               end if;
			
			              
			   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
			   			   
			   			   if now() > sp_fecha_entdes then 
			   			      sp_color_item    := 3;
			   			      sp_color_entrega := 3;
			   			   elsif sp_calculo_itement < 80 then
				   			      sp_color_item    := 1;
				   			      sp_color_entrega := 1;   			   
			   			   elsif sp_calculo_itement >= 80 then
			 	   			      sp_color_item    := 2;
				   			      sp_color_entrega := 2;     			   
			   			   end if; 
			                  
					
			   			   -- desde aca el nuevo calculo
				   		   sp_sumatotallcc  := 0;
				   			   
			   		   FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec_ord.idordentrabajo 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
--				       			   select coalesce (sum(cantidad),0)
--								     into sp_liberadascc
--								     from mct_hojarutatemp
--								    where idhojarutatemp = rec_lcc.idhojarutatemp
--								      and idboleano = 1
--					                  and idareaclasificacion in (0,1,2,3,4,5);
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  		
				  	   -- aca sacamos la cantidad de piezas totales
--					   select coalesce ( sum(cantidad), 0)
--					     into sp_canthr
--					     from mct_hojarutatemp mh
--					    where idordentrabajo = rec_ord.idordentrabajo
--					      and idboleano = 1
--					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   
					   select sum(total)
					     from (
							   select case 
								        when idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when idimprimehojas = 2 then
							     			 coalesce (sum(cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where idordentrabajo = rec_ord.idordentrabajo
							      and idboleano = 1
							      and idareaclasificacion in (0,1,2,3,4,5)
							     group by idimprimehojas
						    ) as tabla
					   into sp_canthr;
						     
						   -- aca sacamos la cantidad de piezas liberadas de control de calidad
						   select count(*) , 
			                      max(fechatermino)
						     into sp_liberadascc,
						          sp_fechamaxlcc
						     from mct_movimientoordentrabajo
						    where codigoaccion = 'L_CC'
						      and idordentrabajo = rec_ord.idordentrabajo; 
						     
						   sp_dias_lcc := 0;
						   sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
						      
						   if ( sp_canthr = 0) then
						       sp_avance := 0;
						   else
						       --sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
							   sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
						       if (sp_avance >= 100 ) then
						           sp_color_status  := 1;
						       end if;
			               end if;
			
			               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
			                 			     
			               if sp_dias_atraso_status < 0 then 
			                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
			               end if;
			              
			
			              
						   -- Fundicion
							   -- aca sacamos las piezas totales solicitadas a fundicion  
--							   select coalesce ( sum(cantidad), 0),
--							          codigoqr, 
--							          fecharequerida
--							     into sp_cantidad_fu,
--							          sp_codigoqr_fu,
--							          sp_fecharequerida_fu
--							     from mct_checklistinftec
--							    where tipotrabajostd = 'FAB_FU'
--							      and idordentrabajo = rec_ord.idordentrabajo
--							      group by codigoqr, fecharequerida;
--							     
--							   -- aca sacamos el total de piezas recepcionadas   
----							   select coalesce ( sum(cantidad), 0),
----							          max(fechacreacion)
----							     into sp_recept_fu,
----							          sp_maxfecha_fu
----							     from mct_checklistinftecrecept
----							    where codigoqr = sp_codigoqr_fu; 
--							   select coalesce ( sum(cantidad), 0) * 100,
--							          max(fechacreacion)
--							     into sp_recept_fu,
--							          sp_maxfecha_fu
--							     from mct_checklistinftecrecept
--							    where codigoqr = rec_ord.idordentrabajo||'FAB_FU' or 
--							          codigoqr = rec_ord.idordentrabajo||'FAB_FUPL'; 	
					   -- Fundicion
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          --codigoqr, 
						          max(fecharequerida)
						     into sp_cantidad_fu,
						    --      sp_codigoqr_fu,
						          sp_fecharequerida_fu
						     from mct_checklistinftec
						    where tipotrabajostd in ('FAB_FU','FAB_FUPL')
						      and idordentrabajo = rec_ord.idordentrabajo;
						      --group by fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0) * 100,
						          max(fechacreacion)
						     into sp_recept_fu,
						          sp_maxfecha_fu
						     from mct_checklistinftecrecept
						    where codigoqr = rec_ord.idordentrabajo||'FAB_FU' or 
						          codigoqr = rec_ord.idordentrabajo||'FAB_FUPL'; 
						         
							   if (sp_cantidad_fu = 0 ) then
				                   sp_cantidad_fu := 1;
				               end if;
				              
							   sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
							   sp_atraso_fu := 0;
							  
							   sp_color_fu  := 0;
							   if ( sp_avance_fu >= 100) then
							       sp_color_fu   := 1;
							   end if;
							  
							   if ( sp_cantidad_fu = 0 ) then
							       sp_avance_fu = 999;
							   end if;
			  
						  
						   -- Pañol
							   -- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(cantidad), 0),
							          codigoqr, 
							          fecharequerida
							     into sp_cantidad_pa,
							          sp_codigoqr_pa,
							          sp_fecharequerida_pa				          
							     from mct_checklistinftec
							    where tipotrabajostd = 'FAB_PA'
							      and idordentrabajo = rec_ord.idordentrabajo
							      group by codigoqr, fecharequerida;
							   
							   -- aca sacamos el total de piezas recepcionadas   
							   select coalesce ( sum(cantidad), 0),
							          max(fechacreacion)
							     into sp_recept_pa,
							          sp_maxfecha_pa		   
							     from mct_checklistinftecrecept
							    where codigoqr = sp_codigoqr_pa;
			
						       if (sp_cantidad_pa = 0 ) then
			                       sp_cantidad_pa := 1;
			                   end if;
			              
							   sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    
						       sp_atraso_pa := 0;
			
							   sp_color_pa  := 0;			      
						       if ( sp_avance_pa >= 100) then
							       sp_color_pa   := 1;
							   end if;
							  

						   -- Caldereria
							   -- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(cantidad), 0),
							          codigoqr, 
							          fecharequerida
							     into sp_cantidad_ca,
							          sp_codigoqr_ca,
							          sp_fecharequerida_ca				          
							     from mct_checklistinftec
							    where tipotrabajostd = 'FAB_CA'
							      and idordentrabajo = rec_ord.idordentrabajo
							      group by codigoqr, fecharequerida;
							   
							   -- aca sacamos el total de piezas recepcionadas   
							   select coalesce ( sum(cantidad), 0),
							          max(fechacreacion)
							     into sp_recept_ca,
							          sp_maxfecha_ca	   
							     from mct_checklistinftecrecept
							    where codigoqr = sp_codigoqr_ca; 
			
						       if (sp_cantidad_ca = 0 ) then
			                      sp_cantidad_ca := 1;
			                   end if;
			              
							   sp_avance_ca := round((sp_recept_ca * 100.00 ) / sp_cantidad_ca , 2);
			
							   sp_color_ca  := 0;					  
						       if ( sp_avance_ca >= 100) then
							       sp_color_ca   := 1;
							   end if;				  
							  				 
							 
						   -- Compras
							   -- aca sacamos las piezas totales solicitadas a compras  
							   select coalesce ( sum(cantidad), 0),
							          codigoqr, 
							          fecharequerida
							     into sp_cantidad_co,
							          sp_codigoqr_co,
							          sp_fecharequerida_co				          
							     from mct_checklistinftec
							    where tipotrabajostd = 'RPO'
							      and idordentrabajo = rec_ord.idordentrabajo
							      group by codigoqr, fecharequerida;
							   
							   -- aca sacamos el total de piezas recepcionadas   
							   select coalesce ( sum(cantidad), 0),
							          max(fechacreacion)
							     into sp_recept_co,
							          sp_maxfecha_co	 			   
							     from mct_checklistinftecrecept
							    where codigoqr = sp_codigoqr_co;			    
			
						       sp_atraso_co := 0;
						       if (sp_cantidad_co = 0 ) then
			                       sp_cantidad_co := 1;
			                   end if;				   
							   
							   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			
			
							   sp_color_co  := 0;				  
						       if ( sp_avance_co >= 100) then
							       sp_color_co   := 1;
							   end if;	
							  				 
							 
						   -- Taller Mecanico
							   -- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(cantidad), 0),
							          codigoqr, 
							          fecharequerida
							     into sp_cantidad_ot,
							          sp_codigoqr_ot,
							          sp_fecharequerida_ot				          
							     from mct_checklistinftec
							    where tipotrabajostd = 'OTROS'
							      and idordentrabajo = rec_ord.idordentrabajo
							      group by codigoqr, fecharequerida;
							   
							   -- aca sacamos el total de piezas recepcionadas   
							   select coalesce ( sum(cantidad), 0),
							          max(fechacreacion)
							     into sp_recept_ot,
							          sp_maxfecha_ot				   
							     from mct_checklistinftecrecept
							    where codigoqr = sp_codigoqr_ot;					    
			
						       if (sp_cantidad_ot = 0 ) then
			                       sp_cantidad_ot := 1;
			                   end if;					   
							   
							   sp_avance_ot := round((sp_recept_ot * 100.00 ) / sp_cantidad_ot , 2);						    
						       sp_atraso_ot := 0;
			
							   sp_color_ot  := 0;				      
						       if ( sp_avance_ot >= 100) then
							       sp_color_ot   := 1;
							   end if;	
							  				 
			
						   -- Stock Cc
							   -- aca sacamos las piezas totales solicitadas a fundicion  
							   sp_cantidad_cc := 0;
							   select coalesce ( sum(cantidad), 0),
							          codigoqr, 
							          fecharequerida
							     into sp_cantidad_cc,
							          sp_codigoqr_cc,
							          sp_fecharequerida_cc				          
							     from mct_checklistinftec
							    where tipotrabajostd = 'STOCK_CC'
							      and idordentrabajo = rec_ord.idordentrabajo
							      group by codigoqr, fecharequerida;
							   
							   -- aca sacamos el total de piezas recepcionadas   
							   select coalesce ( sum(cantidad), 0),
							          max(fechacreacion)
							     into sp_recept_cc,
							          sp_maxfecha_cc				   
							     from mct_checklistinftecrecept
							    where codigoqr = sp_codigoqr_ot;					    
			
						       if (sp_cantidad_cc = 0 ) then
			                       sp_cantidad_cc := 1;
			                   end if;					   
							  
							   sp_avance_cc := round((sp_recept_cc * 100.00 ) / sp_cantidad_cc , 2);
							   sp_atraso_cc := 0;		                   
			
							   sp_color_cc  := 0;			      
						       if ( sp_avance_cc >= 100) then
							       sp_color_cc   := 1;
							   end if;	
						  
							
				      
				      --  Para elementos de desgaste
				        sp_subproducto := '';
				        sp_cantidad := 0;
				      
					    if idfamily = 11 then
					   
					        select count(distinct b.nombreproductonepcast)
					          into sp_cantidad
							  from mct_ordentrabajorepuesto a,
								   mct_productonepcast b
							 where a.idordentrabajo = rec_ord.idordentrabajo
							   and a.idproductonepcast  = b.idproductonepcast ;
			
			
							if sp_cantidad > 1 then
							
								sp_subproducto := 'Varios';
							else
							
								select distinct b.nombreproductonepcast
						          into sp_subproducto
								  from mct_ordentrabajorepuesto a,
									   mct_productonepcast b
								 where a.idordentrabajo = rec_ord.idordentrabajo
								   and a.idproductonepcast  = b.idproductonepcast ;
							  
							end if;
					   
				       
				        end if;
				       
				        itemot		   := sp_indice;
					    idworkorder    := rec_ord.idordentrabajo;
						auttype        := rec_ord.tipoautoriza;	    
						ordertypename  := rec_ord.siglatipo;		
						username       := rec_ord.nombre;
					    familyname     := rec_ord.siglafam;	
						productname    := rec_ord.producto;
						subproductname := sp_subproducto;
					    customername   := rec_ord.nombrecorto;
						
					    deliverydatetm := rec_ord.fechaentregatm;
					    deliverydateclte := rec_ord.fechaentregaclte;
					  
					    if (rec_ord.idordentrabajo in (30322,30374) ) then
					       sp_avance   := 100;
					       sp_color_status := 1;
					    else
					       sp_color_status := 0;		    
					    end if;
					   
					    if (sp_avance >= 100) then
					        statusdispatch  := sp_dias_lcc;
					    else
					    	statusdispatch  := rec_ord.dias;
					    end if;
			
					    if ( sp_cantidad_fu is null or sp_cantidad_fu = 0) then
					        sp_avance_fu := 999;
					    end if;
					    if ( sp_cantidad_pa is null or sp_cantidad_pa = 0) then
					        sp_avance_pa := 999;
					    end if;
					   	if ( sp_cantidad_ca is null or sp_cantidad_ca = 0) then
					        sp_avance_ca := 999;
					    end if;
					    if ( sp_cantidad_co is null or sp_cantidad_co = 0) then
					        sp_avance_co := 999;
					    end if;
					   	if ( sp_cantidad_ot is null or sp_cantidad_ot = 0) then
					        sp_avance_ot := 999;
					    end if;
					   	if ( sp_cantidad_cc is null or sp_cantidad_cc = 0) then
					        sp_avance_cc := 999;
					    end if;
					   
					    if (rec_ord.checklistvalido = false) then
					        sp_avance_fu := 888;
					        sp_avance_pa := 888;
					        sp_avance_ca := 888;
					        sp_avance_co := 888;
					        sp_avance_ot := 888;
					        sp_avance_cc := 888;				    
				        end if;
				   
					    statuscliente  := rec_ord.diascliente;	
					   
						advance        := sp_avance;
						
					    advancefu      := coalesce(sp_avance_fu,0);
						advancepa      := coalesce(sp_avance_pa,0);
						advanceca      := coalesce(sp_avance_ca,0);
						advanceco      := coalesce(sp_avance_co,0);
						advanceot      := coalesce(sp_avance_ot,0);
						advancecc      := coalesce(sp_avance_cc,0);	
						--advancecc      := sp_cantidad_cc;				
						itemcolor      := coalesce(sp_color_item,0);
			   			statuscolor    := coalesce(sp_color_status,0);   		
						fucolor        := sp_color_fu;
						pacolor        := sp_color_pa;
						cacolor        := sp_color_ca;		
						cocolor        := sp_color_co;
						otcolor        := sp_color_ot;	
						cccolor        := sp_color_cc;			
						delayfu        := coalesce(sp_atraso_fu,0); 
						delaypa        := coalesce(sp_atraso_pa,0); 
						delayca        := coalesce(sp_atraso_ca,0); 
						delayco        := coalesce(sp_atraso_co,0); 
						delayot        := coalesce(sp_atraso_ot,0); 
						delaycc        := coalesce(sp_atraso_cc,0); 		
					    flagfact       := rec_ord.flagfacturacion;
					    fundiciondate  := rec_ord.fechafundicion;
					   
					    sp_indice  	   := sp_indice + 1;
			
						return next;
		       
		       end if;
   


		END LOOP;
	
	else
	
	    if ( desde != 'NA' and hasta != 'NA') then
	    
				FOR rec_ord IN (   
						select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc) AS item,
						       a.idordentrabajo ,
						       case 
						          when a.ordencompra > 0 then 'OC'
						          when a.ordencompra = 0 then 'OI'
						          else 'OI'
						       end as tipoautoriza,   
						       d.nombretipoorden ,
						       e.nombrefamilia ,
							   --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
							   case 
								  when a.idfamilia = 11 then c.nombreproducto
								  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
							   end as producto,
						       b.nombrecorto ,
						       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
						       fechafacetm,
						       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
						       --date_part('day', a.fechafaceclte - now()) as dias,
						       date_part('day', a.fechafacetm - current_date) as dias,
						       date_part('day', a.fechafaceclte - current_date) as diascliente,	
						       a.idmodalidadcreacion ,
						       j.nombre ,
						       a.flagfacturacion ,
						       d.sigla as siglatipo,
						       e.sigla as siglafam,
						       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion,
						       coalesce (to_char(a.fechafundicion2, 'dd-mm-yyyy'), to_char(a.fechafacetm - interval '21 days','dd-mm-yyyy')) as fechafundicion,
				               a.checklistvalido 	
						  from mct_ordentrabajo a,
						       mct_cliente b,
						       mct_producto c,
						       mct_tipoorden d,
						       mct_familia e,
						       mct_estadoorden f,
						       mct_modelo g,
						       mct_subfamilia h,
						       mct_etapaparam i,
						       mct_usuario j
						 where a.idcliente = b.idcliente 
						   and a.idproducto = c.idproducto 
						   and a.idtipoorden = d.idtipoorden 
						   and a.idfamilia = e.idfamilia
						   and a.idestadoorden = f.idestadoorden 
						   and c.idmodelo = g.idmodelo 
						   and g.idsubfamilia = h.idsubfamilia 
						   and c.idetapaparam = i.idetapaparam 
						   and a.idordentrabajo >= 30000
						   and a.idusuario = j.idusuario 
						   and a.idestadoorden  >= 6 and a.idestadoorden < 9
						   and a.idfamilia = idfamily
						   and a.flagfacturacion is true
						   and (a.fechafacetm >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafacetm <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
						   and a.debaja < 1
						   order by a.fechafaceclte asc
						   
							)
				loop 	
				
				       -- colores seran
				       -- 1 : verde
				       -- 2 : amarillo
				       -- 3 : rojo
				       
				       -- sacamos el rango de fechas para el color de entrega
		   
		               select min(fecha_inicio), 
		                      max(fecha_termino),
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
		                      date_part('day', max(fecha_termino) - now() ) ,
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() )
		                 into sp_fecha_auto,
		                      sp_fecha_entdes,
		                      dias_entrega,
		                      dias_resto,
		                      dias_calculo
		                 from mct_progavisos 
		                where idordentrabajo = rec_ord.idordentrabajo
		                  and idsla in (5,8,9);
		                 
		               if (dias_resto = 0 ) then
		                   dias_resto := 1;
		               end if;
		
		              
		   			   sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
		   			   
		   			   if now() > sp_fecha_entdes then 
		   			      sp_color_item    := 3;
		   			      sp_color_entrega := 3;
		   			   elsif sp_calculo_itement < 80 then
			   			      sp_color_item    := 1;
			   			      sp_color_entrega := 1;   			   
		   			   elsif sp_calculo_itement >= 80 then
		 	   			      sp_color_item    := 2;
			   			      sp_color_entrega := 2;     			   
		   			   end if; 
		                  

		   			   -- desde aca el nuevo calculo
			   		   sp_sumatotallcc  := 0;
			   			   
			   		   FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec_ord.idordentrabajo 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
--				       			   select coalesce (sum(cantidad),0)
--								     into sp_liberadascc
--								     from mct_hojarutatemp
--								    where idhojarutatemp = rec_lcc.idhojarutatemp
--								      and idboleano = 1
--					                  and idareaclasificacion in (0,1,2,3,4,5);
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  		
				  	   -- aca sacamos la cantidad de piezas totales
--					   select coalesce ( sum(cantidad), 0)
--					     into sp_canthr
--					     from mct_hojarutatemp mh
--					    where idordentrabajo = rec_ord.idordentrabajo
--					      and idboleano = 1
--					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   
					   select sum(total)
					     from (
							   select case 
								        when idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when idimprimehojas = 2 then
							     			 coalesce (sum(cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where idordentrabajo = rec_ord.idordentrabajo
							      and idboleano = 1
							      and idareaclasificacion in (0,1,2,3,4,5)
							     group by idimprimehojas
						    ) as tabla
					   into sp_canthr;
					     
					   -- aca sacamos la cantidad de piezas liberadas de control de calidad
					   select count(*) , 
		                      max(fechatermino)
					     into sp_liberadascc,
					          sp_fechamaxlcc
					     from mct_movimientoordentrabajo
					    where codigoaccion = 'L_CC'
					      and idordentrabajo = rec_ord.idordentrabajo; 
					     
					   sp_dias_lcc := 0;
					   sp_dias_lcc := date_part('day',  sp_fechamaxlcc - now());  
					      
					   if ( sp_canthr = 0) then
					       sp_avance := 0;
					   else
					       --sp_avance := round((sp_liberadascc * 100.00 ) / sp_canthr , 2);
						   sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
					       if (sp_avance >= 100 ) then
					           sp_color_status  := 1;
					       end if;
		               end if;
		
		               sp_dias_atraso_status := date_part('day', now() - sp_fecha_entdes);
		                 			     
		               if sp_dias_atraso_status < 0 then 
		                  sp_dias_atraso_status := sp_dias_atraso_status * -1;
		               end if;
		              
		   			   --if now() > sp_fecha_entdes then 
		   			   --   sp_color_status  := 3;
		   			   --elsif sp_calculo_itement < 80 then
		   			   --   sp_color_status  := 1;  
		   			   --else
		   			   --   sp_color_status  := 1;  
		   			   --end if;
		
		              
					   -- Fundicion
						   -- aca sacamos las piezas totales solicitadas a fundicion  
--						   select coalesce ( sum(cantidad), 0),
--						          codigoqr, 
--						          fecharequerida
--						     into sp_cantidad_fu,
--						          sp_codigoqr_fu,
--						          sp_fecharequerida_fu
--						     from mct_checklistinftec
--						    where tipotrabajostd = 'FAB_FU'
--						      and idordentrabajo = rec_ord.idordentrabajo
--						      group by codigoqr, fecharequerida;
--						     
--						   -- aca sacamos el total de piezas recepcionadas   
----						   select coalesce ( sum(cantidad), 0),
----						          max(fechacreacion)
----						     into sp_recept_fu,
----						          sp_maxfecha_fu
----						     from mct_checklistinftecrecept
----						    where codigoqr = sp_codigoqr_fu; 
--						   select coalesce ( sum(cantidad), 0) * 100,
--						          max(fechacreacion)
--						     into sp_recept_fu,
--						          sp_maxfecha_fu
--						     from mct_checklistinftecrecept
--						    where codigoqr = rec_ord.idordentrabajo||'FAB_FU' or 
--						          codigoqr = rec_ord.idordentrabajo||'FAB_FUPL'; 		
					   -- Fundicion
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          --codigoqr, 
						          max(fecharequerida)
						     into sp_cantidad_fu,
						    --      sp_codigoqr_fu,
						          sp_fecharequerida_fu
						     from mct_checklistinftec
						    where tipotrabajostd in ('FAB_FU','FAB_FUPL')
						      and idordentrabajo = rec_ord.idordentrabajo;
						      --group by fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0) * 100,
						          max(fechacreacion)
						     into sp_recept_fu,
						          sp_maxfecha_fu
						     from mct_checklistinftecrecept
						    where codigoqr = rec_ord.idordentrabajo||'FAB_FU' or 
						          codigoqr = rec_ord.idordentrabajo||'FAB_FUPL'; 				     
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						   sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_atraso_fu := 0;
						  
						   sp_color_fu  := 0;
						   if ( sp_avance_fu >= 100) then
						       sp_color_fu   := 1;
						   end if;
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;
						  
						   --if ( sp_maxfecha_fu > sp_fecharequerida_fu ) then
						   --    sp_atraso_fu  := date_part('day', sp_maxfecha_fu -  sp_fecharequerida_fu );
						   --    sp_color_fu   := 3;
						   --else
						   --    sp_color_fu   := 1;			   
						   --end if;
					  
					  
					   -- Pañol
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_pa,
						          sp_codigoqr_pa,
						          sp_fecharequerida_pa				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_PA'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_pa,
						          sp_maxfecha_pa		   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_pa;
		
					       if (sp_cantidad_pa = 0 ) then
		                       sp_cantidad_pa := 1;
		                   end if;
		              
						   sp_avance_pa := round((sp_recept_pa * 100.00 ) / sp_cantidad_pa , 2);				    
					       sp_atraso_pa := 0;
		
						   sp_color_pa  := 0;			      
					       if ( sp_avance_pa >= 100) then
						       sp_color_pa   := 1;
						   end if;
						  
						   --if ( sp_maxfecha_pa > sp_fecharequerida_pa ) then
						   --    sp_atraso_pa  := date_part('day', sp_maxfecha_pa -  sp_fecharequerida_pa );
						   --    sp_color_pa   := 3;
						   --else
						   --    sp_color_pa   := 1;			   
						   --end if;				 
					  
					   -- Caldereria
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_ca,
						          sp_codigoqr_ca,
						          sp_fecharequerida_ca				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'FAB_CA'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_ca,
						          sp_maxfecha_ca	   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ca; 
		
					       if (sp_cantidad_ca = 0 ) then
		                      sp_cantidad_ca := 1;
		                   end if;
		              
						   sp_avance_ca := round((sp_recept_ca * 100.00 ) / sp_cantidad_ca , 2);
		
						   sp_color_ca  := 0;					  
					       if ( sp_avance_ca >= 100) then
						       sp_color_ca   := 1;
						   end if;				  
						  
						   --if ( sp_maxfecha_ca > sp_fecharequerida_ca ) then
						   --    sp_atraso_ca  := date_part('day', sp_maxfecha_ca -  sp_fecharequerida_ca );
						   --    sp_color_ca   := 3;
						   --else
						   --    sp_color_ca   := 1;			   
						   --end if;					 
						 
					   -- Compras
						   -- aca sacamos las piezas totales solicitadas a compras  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_co,
						          sp_codigoqr_co,
						          sp_fecharequerida_co				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'RPO'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_co,
						          sp_maxfecha_co	 			   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_co;			    
		
					       sp_atraso_co := 0;
					       if (sp_cantidad_co = 0 ) then
		                       sp_cantidad_co := 1;
		                   end if;				   
						   
						   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			
		
						   sp_color_co  := 0;				  
					       if ( sp_avance_co >= 100) then
						       sp_color_co   := 1;
						   end if;	
						  
						   --if ( sp_maxfecha_co > sp_fecharequerida_co ) then
						   --    sp_atraso_co  := date_part('day', sp_maxfecha_co -  sp_fecharequerida_co );
						   --    sp_color_co   := 3;
						   --else
						   --    sp_color_co   := 1;			   
						   --end if;					 
						 
					   -- Taller Mecanico
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_ot,
						          sp_codigoqr_ot,
						          sp_fecharequerida_ot				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'OTROS'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_ot,
						          sp_maxfecha_ot				   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ot;					    
		
					       if (sp_cantidad_ot = 0 ) then
		                       sp_cantidad_ot := 1;
		                   end if;					   
						   
						   sp_avance_ot := round((sp_recept_ot * 100.00 ) / sp_cantidad_ot , 2);						    
					       sp_atraso_ot := 0;
		
						   sp_color_ot  := 0;				      
					       if ( sp_avance_ot >= 100) then
						       sp_color_ot   := 1;
						   end if;	
						  
						   --if ( sp_maxfecha_ot > sp_fecharequerida_ot ) then
						   --    sp_atraso_ot  := date_part('day', sp_maxfecha_ot - sp_fecharequerida_ot );
						   --    sp_color_ot   := 3;
						   --else
						   --    sp_color_ot   := 1;			   
						   --end if;					 
		
					   -- Stock Cc
						   -- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(cantidad), 0),
						          codigoqr, 
						          fecharequerida
						     into sp_cantidad_cc,
						          sp_codigoqr_cc,
						          sp_fecharequerida_cc				          
						     from mct_checklistinftec
						    where tipotrabajostd = 'STOCK_CC'
						      and idordentrabajo = rec_ord.idordentrabajo
						      group by codigoqr, fecharequerida;
						   
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0),
						          max(fechacreacion)
						     into sp_recept_cc,
						          sp_maxfecha_cc				   
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_ot;					    
		
					       if (sp_cantidad_cc = 0 ) then
		                       sp_cantidad_cc := 1;
		                   end if;					   
						   
						   sp_avance_cc := round((sp_recept_cc * 100.00 ) / sp_cantidad_cc , 2);						    
					       sp_atraso_cc := 0;
		
						   sp_color_cc  := 0;			      
					       if ( sp_avance_cc >= 100) then
						       sp_color_cc   := 1;
						   end if;	
						  					  
						  
						   --if ( sp_maxfecha_cc > sp_fecharequerida_cc ) then
						   --    sp_atraso_cc  := date_part('day', sp_maxfecha_cc - sp_fecharequerida_cc );
						   --    sp_color_cc   := 3;
						   --else
						   --    sp_color_cc   := 1;			   
						   --end if;
						  
			      --  sp_dias_av := date_part('day' , rec_ord.fechaentrega - now() )
			      
			      --  Para elementos de desgaste
			        sp_subproducto := '';
			        sp_cantidad := 0;
			      
				    if idfamily = 11 then
				   
				        select count(distinct b.nombreproductonepcast)
				          into sp_cantidad
						  from mct_ordentrabajorepuesto a,
							   mct_productonepcast b
						 where a.idordentrabajo = rec_ord.idordentrabajo
						   and a.idproductonepcast  = b.idproductonepcast ;
		
		
						if sp_cantidad > 1 then
						
							sp_subproducto := 'Varios';
						else
						
							select distinct b.nombreproductonepcast
					          into sp_subproducto
							  from mct_ordentrabajorepuesto a,
								   mct_productonepcast b
							 where a.idordentrabajo = rec_ord.idordentrabajo
							   and a.idproductonepcast  = b.idproductonepcast ;
						  
						end if;
				   
			       
			        end if;
			       
				    itemot         := rec_ord.item;
				    idworkorder    := rec_ord.idordentrabajo;
					auttype        := rec_ord.tipoautoriza;	    
					--ordertypename  := rec_ord.nombretipoorden;
					ordertypename  := rec_ord.siglatipo;		
					username       := rec_ord.nombre;
				    --familyname     := rec_ord.nombrefamilia;
				    familyname     := rec_ord.siglafam;	
					productname    := rec_ord.producto;
					subproductname := sp_subproducto;
				    customername   := rec_ord.nombrecorto;
			        --deliverydatetm     := to_char(sp_fecha_entdes - interval '7 days','dd-mm-yyyy');
					--deliverydateclte   := to_char(sp_fecha_entdes,'dd-mm-yyyy');
					
				    deliverydatetm := rec_ord.fechaentregatm;
				    deliverydateclte := rec_ord.fechaentregaclte;
				   
				    --statusdispatch := sp_dias_atraso_status;
				  
				    if (rec_ord.idordentrabajo in (30322,30374) ) then
				       sp_avance   := 100;
				       sp_color_status := 1;
				    else
				       sp_color_status := 0;		    
				    end if;
				   
				    if (sp_avance >= 100) then
				        statusdispatch  := sp_dias_lcc;
				    else
				    	statusdispatch  := rec_ord.dias;
				    end if;
				   
				   	if ( sp_cantidad_fu is null) then
				        sp_avance_fu := 999;
				    end if;
				    if ( sp_cantidad_pa is null) then
				        sp_avance_pa := 999;
				    end if;
				   	if ( sp_cantidad_ca is null) then
				        sp_avance_ca := 999;
				    end if;
				    if ( sp_cantidad_co is null) then
				        sp_avance_co := 999;
				    end if;
				   	if ( sp_cantidad_ot is null) then
				        sp_avance_ot := 999;
				    end if;
				   	if ( sp_cantidad_cc is null) then
				        sp_avance_cc := 999;
				    end if;
				   
		
				    if (rec_ord.checklistvalido = false) then
				        sp_avance_fu := 888;
				        sp_avance_pa := 888;
				        sp_avance_ca := 888;
				        sp_avance_co := 888;
				        sp_avance_ot := 888;
				        sp_avance_cc := 888;				    
				    end if;
				    statuscliente  := rec_ord.diascliente;	
				   
					advance        := sp_avance;
					
				    advancefu      := coalesce(sp_avance_fu,0);
					advancepa      := coalesce(sp_avance_pa,0);
					advanceca      := coalesce(sp_avance_ca,0);
					advanceco      := coalesce(sp_avance_co,0);
					advanceot      := coalesce(sp_avance_ot,0);
					advancecc      := coalesce(sp_avance_cc,0);		
					itemcolor      := coalesce(sp_color_item,0);
		   			statuscolor    := coalesce(sp_color_status,0);   		
					fucolor        := sp_color_fu;
					pacolor        := sp_color_pa;
					cacolor        := sp_color_ca;		
					cocolor        := sp_color_co;
					otcolor        := sp_color_ot;	
					cccolor        := sp_color_cc;			
					delayfu        := coalesce(sp_atraso_fu,0); 
					delaypa        := coalesce(sp_atraso_pa,0); 
					delayca        := coalesce(sp_atraso_ca,0); 
					delayco        := coalesce(sp_atraso_co,0); 
					delayot        := coalesce(sp_atraso_ot,0); 
					delaycc        := coalesce(sp_atraso_cc,0); 		
				    flagfact       := rec_ord.flagfacturacion;
				    fundiciondate  := rec_ord.fechafundicion;
						    
				return next;
		
				END LOOP;	    
	    
	    else

				FOR rec_ord IN (   
						select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc) AS item,
						       a.idordentrabajo ,
						       case 
						          when a.ordencompra > 0 then 'OC'
						          when a.ordencompra = 0 then 'OI'
						          else 'OI'
						       end as tipoautoriza,   
						       d.nombretipoorden ,
						       e.nombrefamilia ,
						       --h.sigla||' '||g.nombremodelo||' '||i.nombreparam as producto,
						       case 
						          when a.idfamilia = 11 then c.nombreproducto
						          else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						       end as producto,
						       b.nombrecorto ,
						       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
						       fechafacetm,
						       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
						       --date_part('day', a.fechafaceclte - now()) as dias,
						       date_part('day', a.fechafacetm - current_date) as dias,
						       date_part('day', a.fechafaceclte - current_date) as diascliente,	
						       a.idmodalidadcreacion ,
						       j.nombre ,
						       a.flagfacturacion ,
						       d.sigla as siglatipo,
						       e.sigla as siglafam,
						       --to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy') as fechafundicion,
						       coalesce (to_char(a.fechafundicion2, 'dd-mm-yyy' ), to_char(a.fechafacetm - interval '14 days','dd-mm-yyyy')) as fechafundicion,
				               a.checklistvalido 
						  from mct_ordentrabajo a,
						       mct_cliente b,
						       mct_producto c,
						       mct_tipoorden d,
						       mct_familia e,
						       mct_estadoorden f,
						       mct_modelo g,
						       mct_subfamilia h,
						       mct_etapaparam i,
						       mct_usuario j
						 where a.idcliente = b.idcliente 
						   and a.idproducto = c.idproducto 
						   and a.idtipoorden = d.idtipoorden 
						   and a.idfamilia = e.idfamilia
						   and a.idestadoorden = f.idestadoorden 
						   and c.idmodelo = g.idmodelo 
						   and g.idsubfamilia = h.idsubfamilia 
						   and c.idetapaparam = i.idetapaparam 
						   and a.idordentrabajo >= 30000
						   and a.idusuario = j.idusuario 
						   and a.idestadoorden  >= 6 and a.idestadoorden < 9
						   and a.idfamilia = 8
						   and a.flagfacturacion is true
						   and a.debaja < 1
						   order by a.fechafaceclte asc
						   
							)
				loop 	
				
				       -- colores seran
				       -- 1 : verde
				       -- 2 : amarillo
				       -- 3 : rojo
				       
				       -- sacamos el rango de fechas para el color de entrega
		   
		               select min(fecha_inicio), 
		                      max(fecha_termino),
		                      date_part('day', max(fecha_termino) - min(fecha_inicio) ) ,
		                      date_part('day', max(fecha_termino) - now() ) ,
		                      (date_part('day', max(fecha_termino) - min(fecha_inicio) ) - date_part('day', max(fecha_termino) - now() ))*100
		                 into sp_fecha_auto,
		                      sp_fecha_entdes,
		                      dias_entrega,
		                      dias_resto,
		                      dias_calculo
		                 from mct_progavisos 
		                where idordentrabajo = rec_ord.idordentrabajo
		                  and idsla in (5,8,9);
		                 
		               if (dias_resto = 0 ) then
		                   dias_resto := 1;
		               end if;
		
		              
		   			  -- sp_calculo_itement := round((dias_calculo * 100.00 ) / dias_resto , 2);
		   			   sp_calculo_itement := round(dias_calculo / dias_resto , 2);
		   			   
		   			   if now() > sp_fecha_entdes then 
		   			      sp_color_item    := 3;
		   			      sp_color_entrega := 3;
		   			   elsif sp_calculo_itement < 80 then
			   			      sp_color_item    := 1;
			   			      sp_color_entrega := 1;   			   
		   			   elsif sp_calculo_itement >= 80 then
		 	   			      sp_color_item    := 2;
			   			      sp_color_entrega := 2;     			   
		   			   end if; 
		                  

		   			   -- desde aca el nuevo calculo
			   		   sp_sumatotallcc  := 0;
			   			   
			   		   FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
