--
-- TOC entry 1458 (class 1255 OID 17194)
-- Name: evtlistmontoconsolidado_anual(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmontoconsolidado_anual(periodo character varying, agno bigint) RETURNS TABLE(idfamilia bigint, montototalot bigint, montototaldesp bigint, montoarrastre bigint)
    LANGUAGE plpgsql
    AS $$

declare
      
    rec_ord          	   record;
   

--
--    sp_avance              numeric;
--    sp_avance_fu           numeric;  --numeric
--    sp_atraso_fu           integer;
--    sp_avance_pa           numeric;
--    sp_atraso_pa           integer;   
--    sp_avance_ca           numeric;
--    sp_atraso_ca           integer;   
--    sp_avance_co           numeric;
--    sp_atraso_co           integer;   
--    sp_avance_ot           numeric;
--    sp_atraso_ot           integer;   
--    sp_avance_cc           numeric;
--    sp_atraso_cc           integer;  
--   
--    sp_recept_fu           integer;
--    sp_recept_pa           integer;
--    sp_recept_ca           integer;
--    sp_recept_co           integer;
--    sp_recept_ot           integer;
--    sp_recept_cc           integer;
--   
--    sp_color_item          integer;
--    sp_color_entrega       integer;
--    sp_color_status        integer;
--    
--    sp_color_fu            integer;
--    sp_color_pa            integer;
--    sp_color_ca            integer;
--    sp_color_co            integer;
--    sp_color_ot            integer;
--    sp_color_cc            integer;   
--   
--    sp_dias_av             integer;
--    sp_dias_fu             integer;
--    sp_dias_pa             integer;
--    sp_dias_ca             integer;
--    sp_dias_co             integer;
--    sp_dias_ot             integer;
--    sp_dias_cc             integer;
--   
--    sp_fecha_auto          timestamp;
--    sp_fecha_entdes        timestamp;
--    dias_entrega           integer;
--    dias_resto             integer;   
--    dias_calculo           integer;
--    sp_calculo_itement     numeric;
--
--    sp_dias_atraso_status  integer;
--    sp_dias_atraso_fu      integer;   
--    sp_dias_atraso_pa      integer;
--    sp_dias_atraso_ca      integer;   
--    sp_dias_atraso_co      integer;   
--    sp_dias_atraso_ot      integer;   
--    sp_dias_atraso_cc      integer;   
--   
--    sp_maxfecha_fu         timestamp;
--    sp_maxfecha_pa         timestamp;
--    sp_maxfecha_ca         timestamp;
--    sp_maxfecha_co         timestamp;   
--    sp_maxfecha_ot         timestamp;
--    sp_maxfecha_cc         timestamp;
--   
--    sp_muestraorden		   integer;
--    sp_countcheck		   integer;
--    
--    sp_indice              integer;
--   
--    sp_sumatotallcc        integer;
--   
--    rec_lcc      			RECORD;
--   
--    sp_restanc			   integer;
--    sp_textoout            varchar;
   
    sp_estaenproceso       bigint;
   
    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;   
    
    sp_montoadicional		bigint;
    
begin
	 
		sp_estaenproceso	:= 0;
	
		select to_char(now(),'yyyy')
		  into ano;
		 
		select lpad(periodo, 2,'0')
		  into mes;
		 
		fechadesde	:= agno||'-'||mes||'-01';
	
	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'dd'),
	           to_date(fechadesde,'yyyy-mm-dd') + interval '1 month',
	           to_char( to_date(fechadesde,'yyyy-mm-dd') + interval '1 month', 'yyyy-mm')||'-'||to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'dd')
		  into ultimodia,
		       fechadesde,
		       fechahasta;
		 
		select to_char(now(),'yyyy')
		  into anofin;
	 
	    
		FOR rec_ord IN (   
				select a.idordentrabajo ,
				       a.idestadoorden ,
		               a.idfamilia,
		               count(*)
				  from mct_ordentrabajo a 
				 where a.idordentrabajo >= 30000
				   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
				   and a.idfamilia in (8,10,15)
				   --and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				   and (a.fechafaceclte >= TO_TIMESTAMP('2023-12-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP('2023-12-31'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
				   and a.debaja < 1
				   group by a.idordentrabajo ,
				            a.idestadoorden ,
		                    a.idfamilia
				   order by a.idfamilia asc
				   
					)
		loop 	
		
			
		    montototaldesp	:= 0;
		    montoarrastre	:= 0;
		   
		    idfamilia	:= rec_ord.idfamilia;
		   
	         if (rec_ord.idfamilia = 8) then
	         
	         	select coalesce(sum(montorepfab),0)
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	    --montoarrastre	:= montototalot - montototaldesp;
	         	    montoarrastre	:= montototalot;
	         	
	         	else
	         	
	         		montoarrastre	:= montototalot - montototaldesp;
	         	
	         	end if;	         	
	         
	         elsif (rec_ord.idfamilia = 11) then
	         
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into montototalot
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select sum(b.qdespacho * c.costo ) 
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
	         	
		        select sum(b.qdespacho * c.costo ) 
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		        montoarrastre	:= montototalot - montoarrastre;
		         	    	  
	         elsif (rec_ord.idfamilia = 10 or rec_ord.idfamilia = 15) then
	
	           	select coalesce(sum(montorepfab),0) 
	         	  into montototalot
	         	  from mct_ordentrabajo a 
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	select coalesce(sum(cantidad*costo) ,0)
	         	  into sp_montoadicional
	         	  from mct_ordentrabajorepuesto a
	         	 where a.idordentrabajo = rec_ord.idordentrabajo;
	         	
	         	montototalot	:= montototalot + sp_montoadicional;
	         
	            select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montototaldesp
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaguia <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS') ;
		         	  
		         	  
		        select coalesce(sum(b.qdespacho * c.costo) ,0)
		         	  into montoarrastre
		         	  from mct_despachopartecabecera a ,
		         	       mct_despachopartedetalle b,
		         	       mct_ordentrabajorepuesto c
		         	 where a.idordentrabajo = rec_ord.idordentrabajo
		         	   and a.iddespachopartecabecera = b.iddespachopartecabecera 
		         	   and b.idordentrabajoparte = c.idordentrabajorepuesto
		         	   and a.fechaguia < TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') ;
		         	    	
		        montoarrastre	:= montototalot - montoarrastre;

	         	if (rec_ord.idestadoorden = 9) then
	         	
	         		montototaldesp	:= montototalot;
	         	
	         	end if;	    
	         
	         else
	         
	         	montototalot	:= 0;
	         
	         end if;
	        
	        --montoarrastre	:= 0;
				        
	        if (montototalot > montoarrastre) then
	        
	        	return next;
	       
	        end if;

		END LOOP;	    
	   
END;
$$;


ALTER FUNCTION traking.evtlistmontoconsolidado_anual(periodo character varying, agno bigint) OWNER TO postgres;

--
-- TOC entry 1965 (class 1255 OID 17196)
-- Name: evtlistmulticlienteapp(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistmulticlienteapp() RETURNS TABLE(id bigint, nombre character varying, nombrecorto character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
	
	   RETURN QUERY

		select *
		from (select a.idcliente ,
		       cast(substr(a.nombrecliente, 1, 35) as varchar) as nombrecliente,
		       a.nombrecorto 
		  from mct_cliente a 
		 where a.idcliente in (select b.idcliente from mct_ordentrabajo b where b.idfamilia = 8)
		union 
		select c.idcliente ,
		       cast(substr(c.nombrecliente, 1, 35) as varchar) as nombrecliente,
		       c.nombrecorto 
		  from mct_cliente c 
		 where c.idcliente = 77) d
		 order by d.nombrecliente asc;
          
		
END;
$$;


ALTER FUNCTION traking.evtlistmulticlienteapp() OWNER TO postgres;

