--
-- TOC entry 1361 (class 1255 OID 17198)
-- Name: evtlistnoconformidad(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistnoconformidad(idot bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, idnoconformidad bigint, idordentrabajo bigint, codhojaruta character varying, idhojarutatemp bigint, nombrecomponente character varying, idusuario bigint, nombreusuario character varying, idorigenncf bigint, nombreorigen character varying, causaorigen character varying, idseccionncf bigint, nombreseccion character varying, idusuarioseccion bigint, nombreoperador character varying, descripcion character varying, firmauno text, firmados text, idaccionncf bigint, nombreaccion character varying, fechacreacion character varying, productname character varying, customername character varying)
    LANGUAGE plpgsql
    AS $$
declare

     sp_nombre      varchar;
    
     rec_lista      RECORD;	
    
BEGIN
        
	
	  if ( idot > 0 ) then 
	        
                       
	            FOR rec_lista IN ( 
	              
		            select ROW_NUMBER() OVER (ORDER BY a.idnoconformidad asc) AS item,
		                   a.idnoconformidad ,
		                   a.idordentrabajo ,
		                   a.codhojaruta ,
		                   b.idhojarutatemp ,
		                   cast(d.nombrecomponente||' - '||a.codhojaruta as varchar) as nombrecomponente,
		                   a.idusuario ,
		                   e.nombre ,
		                   a.idorigenncf ,
		                   f.nombreorigen,
		                   f.detalleorigen,
		                   a.idseccionncf ,
		                   coalesce (h.nombreseccion, f.nombreorigen ) as  nombreseccion,
		                   a.idusuarioseccion ,
		                   i.nombreoperador ,
		                   a.descripcion ,
		                   a.firmauno ,
		                   a.firmados ,
		                   a.idaccionncf ,
		                   j.nombreaccion ,
		                   cast(to_char(a.fechacreacion, 'dd-mm-yyyy HH24:MI:SS') as varchar) as fechacreacion ,
		                   cast(n.sigla||' '||m.nombremodelo as varchar) as productname,
		                   p.nombrecorto as customername
		              from mct_noconformidad a 
		              left join mct_detallehojarutatemp b on a.codhojaruta = b.codhojaruta
		              left join mct_hojarutatemp c        on b.idhojarutatemp = c.idhojarutatemp 
		              left join mct_componente d          on c.idcomponente = d.idcomponente 
		              left join mct_usuario e             on a.idusuario = e.idusuario
		              left join mct_origenncf f           on a.idorigenncf = f.idorigenncf
		              left join mct_seccionncf g          on a.idseccionncf = g.idseccionncf
		              --left join mct_seccion h             on g.idseccion = h.idseccion 
		              left join mct_seccion h             on a.idseccionncf = h.idseccion 
		              left join mct_operador i            on a.idusuarioseccion = i.idoperador 
		              left join mct_accionncf j           on a.idaccionncf = j.idaccionncf 
		              left join mct_ordentrabajo k        on k.idordentrabajo = a.idordentrabajo
		              left join mct_producto l            on k.idproducto = l.idproducto
		              left join mct_modelo m              on l.idmodelo = m.idmodelo 
		              left join mct_subfamilia n          on m.idsubfamilia = n.idsubfamilia
		              left join mct_cliente p             on k.idcliente = p.idcliente 
		            where a.idordentrabajo = idot
					)
					
		loop 	
		
			  sp_nombre := '';
				      			
		      if ( rec_lista.idorigenncf = 4 ) then 

			        select b.nombre 
			          into sp_nombre
			          from mct_ordentrabajo a,
			               mct_usuario b
			         where a.idordentrabajo = idot 
			           and b.idusuario = a.idusuario ;
		      
		      elsif ( rec_lista.idorigenncf = 2 ) then
		      
				        select nombre 
				          into sp_nombre
				          from mct_usuario aa
				         where aa.idusuario = 23 ;
		      
			  elsif ( rec_lista.idorigenncf = 3 ) then
		      
				        select nombre 
				          into sp_nombre
				          from mct_usuario aa
				         where aa.idusuario = 25 ;
		      		      
			  elsif ( rec_lista.idorigenncf = 5 ) then
		      
				        select nombre 
				          into sp_nombre
				          from mct_usuario aa 
				         where aa.idusuario = 38 ;
		      
		      else
		      
		          sp_nombre := rec_lista.nombreoperador;
		      
		      end if;

		      item 				:= rec_lista.item;
		      idnoconformidad 	:= rec_lista.idnoconformidad; 
		 	  idordentrabajo 	:= rec_lista.idordentrabajo; 
		 	  codhojaruta 		:= rec_lista.codhojaruta; 
		 	  idhojarutatemp 	:= rec_lista.idhojarutatemp; 
		 	  nombrecomponente 	:= rec_lista.nombrecomponente; 
		 	  idusuario 		:= rec_lista.idusuario; 
		 	  nombreusuario 	:= rec_lista.nombre; 
		 	  idorigenncf 		:= rec_lista.idorigenncf; 
		 	  nombreorigen 		:= rec_lista.nombreorigen; 
