                 usuariomodificacion := rec_lista.usuariomodificacion;
		     RETURN next;			     
		end loop;
       elsif ( startdate != 'NA' ) then

       	 FOR rec_lista IN ( 
                   select ROW_NUMBER() OVER (ORDER BY a.idnoconformidadcald asc) AS item,
		                   a.idnoconformidadcald ,
