--
-- TOC entry 2241 (class 1255 OID 17207)
-- Name: evtlistnombrepiezainspapp(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistnombrepiezainspapp(qrcodes character varying) RETURNS TABLE(idordentrabajo bigint, codhojaruta character varying, componentname character varying, customername character varying, productname character varying)
    LANGUAGE plpgsql
    AS $$
declare
	
	sp_codhojaruta		varchar;
    sp_componente		varchar;
    sp_idordentrabajo	bigint;
    sp_idcliente		bigint;
    sp_nombrecliente	varchar;
    sp_idproducto		bigint;
    sp_producto			varchar;


BEGIN
        
		sp_codhojaruta		:= '';
	    sp_componente		:= '';
	    sp_idordentrabajo	:= 0;
	    sp_idcliente		:= 0;
	    sp_nombrecliente	:= '';
	    sp_idproducto		:= 0;
	    sp_producto			:= '';
		--RETURN QUERY
		        
		select a.codhojaruta ,
		       cast(c.nombrecomponente||' - '||b.textoadicional as varchar),
		       b.idordentrabajo ,
		       d.idcliente ,
		       e.nombrecorto ,
		       d.idproducto 
		  into sp_codhojaruta,
		       sp_componente,
		       sp_idordentrabajo,
		       sp_idcliente,
		       sp_nombrecliente,
		       sp_idproducto
		  from mct_detallehojarutatemp a,
		       mct_hojarutatemp b,
		       mct_componente c,
		       mct_ordentrabajo d,
		       mct_cliente e
		 where a.codhojaruta = qrcodes
		   and a.idhojarutatemp = b.idhojarutatemp 
		   and b.idcomponente = c.idcomponente 
		   and b.idordentrabajo = d.idordentrabajo 
		   and d.idcliente = e.idcliente ;
	  
		if ( sp_idproducto in (10,11,12,13,14,15,16,17) ) then
		 
			select nombreproductonepcast 
			  into sp_producto
			  from mct_productonepcast mp 
			 where idproductonepcast = sp_idproducto;
		 
			idordentrabajo 	:= sp_idordentrabajo;
			codhojaruta 	:= sp_codhojaruta;
			componentname 	:= sp_componente;
			customername 	:= sp_nombrecliente;
			productname 	:= sp_producto;
         
		    return next;
		   
		else
		
			select cast(c.sigla||' '||b.nombremodelo||' '||e.nombreparam as varchar)
			  into sp_producto
			  from mct_producto a,
			       mct_modelo b,
			       mct_subfamilia c,
			       mct_familia d,
			       mct_etapaparam e
			 where a.idproducto = sp_idproducto
			   and a.idmodelo = b.idmodelo
			   and b.idsubfamilia = c.idsubfamilia 
			   and c.idfamilia = d.idfamilia 
			   and a.idetapaparam = e.idetapaparam ;			

			idordentrabajo 	:= sp_idordentrabajo;
			codhojaruta 	:= sp_codhojaruta;
			componentname 	:= sp_componente;
			customername 	:= sp_nombrecliente;
			productname 	:= sp_producto;
		
		    return next;
		
		end if;
		   

END;
$$;


ALTER FUNCTION traking.evtlistnombrepiezainspapp(qrcodes character varying) OWNER TO postgres;

--
-- TOC entry 1247 (class 1255 OID 17208)
-- Name: evtlistnombrepiezainspappv2(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistnombrepiezainspappv2(qrcodes character varying) RETURNS TABLE(idordentrabajo bigint, codhojaruta character varying, componentname character varying, customername character varying, productname character varying, plano character varying)
    LANGUAGE plpgsql
    AS $$
declare
	
	sp_codhojaruta		varchar;
    sp_componente		varchar;
    sp_idordentrabajo	bigint;
    sp_idcliente		bigint;
    sp_nombrecliente	varchar;
    sp_idproducto		bigint;
    sp_producto			varchar;
    sp_plano            varchar;


BEGIN
        
		sp_codhojaruta		:= '';
	    sp_componente		:= '';
	    sp_idordentrabajo	:= 0;
	    sp_idcliente		:= 0;
	    sp_nombrecliente	:= '';
	    sp_idproducto		:= 0;
	    sp_producto			:= '';
        sp_plano            := '';
		--RETURN QUERY
		        
		select a.codhojaruta ,
		       cast(c.nombrecomponente||' - '||b.textoadicional as varchar),
		       b.idordentrabajo ,
		       d.idcliente ,
		       e.nombrecorto ,
		       d.idproducto ,
               b.nombreplano
		  into sp_codhojaruta,
		       sp_componente,
		       sp_idordentrabajo,
		       sp_idcliente,
		       sp_nombrecliente,
		       sp_idproducto,
               sp_plano
		  from mct_detallehojarutatemp a,
		       mct_hojarutatemp b,
		       mct_componente c,
		       mct_ordentrabajo d,
		       mct_cliente e
		 where a.codhojaruta = qrcodes
		   and a.idhojarutatemp = b.idhojarutatemp 
		   and b.idcomponente = c.idcomponente 
		   and b.idordentrabajo = d.idordentrabajo 
		   and d.idcliente = e.idcliente ;
	  
		if ( sp_idproducto in (10,11,12,13,14,15,16,17) ) then
		 
			select nombreproductonepcast 
			  into sp_producto
			  from mct_productonepcast mp 
			 where idproductonepcast = sp_idproducto;
		 
			idordentrabajo 	:= sp_idordentrabajo;
			codhojaruta 	:= sp_codhojaruta;
			componentname 	:= sp_componente;
			customername 	:= sp_nombrecliente;
			productname 	:= sp_producto;
            plano			:= sp_plano;
         
		    return next;
		   
		else
		
			select cast(c.sigla||' '||b.nombremodelo||' '||e.nombreparam as varchar)
			  into sp_producto
			  from mct_producto a,
			       mct_modelo b,
			       mct_subfamilia c,
			       mct_familia d,
			       mct_etapaparam e
			 where a.idproducto = sp_idproducto
			   and a.idmodelo = b.idmodelo
			   and b.idsubfamilia = c.idsubfamilia 
			   and c.idfamilia = d.idfamilia 
			   and a.idetapaparam = e.idetapaparam ;			

			idordentrabajo 	:= sp_idordentrabajo;
			codhojaruta 	:= sp_codhojaruta;
			componentname 	:= sp_componente;
			customername 	:= sp_nombrecliente;
			productname 	:= sp_producto;
            plano			:= sp_plano;
		
		    return next;
		
		end if;
		   

END;
$$;


