CREATE FUNCTION traking.evtlistocpdfapp(idworkorders bigint) RETURNS TABLE(idworkorder bigint, picfile text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
			select a.idordentrabajo ,
			       --split_part(archivoadjunto,'data:image/jpeg;base64,',2)
			        replace (a.archivoadjunto,'data:application/pdf;base64,','') 
			  from mct_infcotipdf a
			 where a.idordentrabajo = idworkorders 
