--
-- TOC entry 1155 (class 1255 OID 17211)
-- Name: evtlistoperadorespororigenncf(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistoperadorespororigenncf(idorigens bigint) RETURNS TABLE(idoperador bigint, nombreoperador character varying)
    LANGUAGE plpgsql
    AS $$
    
begin
	 
	if (idorigens = 1) then

		return QUERY
	
		select a.idoperador,cast(a.nombreoperador||' - '||b.sigla  as varchar)
		  from mct_operador a
	  	  left join mct_cargo b on a.idcargoapp = b.idcargo
		 where a.aplicaconvencionalncf is true
		   and a.estado = 1
		 order by b.sigla ;

	elsif (idorigens = 8) then

		return QUERY
	
		select a.idoperador,cast(a.nombreoperador||' - '||b.sigla  as varchar)
		  from mct_operador a
          left join mct_cargo b on a.idcargoapp = b.idcargo
		 where a.aplicacncncf is true
           and a.estado = 1
		 order by b.sigla ;

	end if;


END			
$$;


ALTER FUNCTION traking.evtlistoperadorespororigenncf(idorigens bigint) OWNER TO postgres;

