--
-- TOC entry 2143 (class 1255 OID 17213)
-- Name: evtlistoperatorregisterjob(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistoperatorregisterjob(idworkordermovs bigint) RETURNS TABLE(idoperator bigint, operatorname character varying, idpart bigint, partname character varying, startdatetext text, enddatetext text, timework integer, actioncode character varying, actionname character varying, closename character varying, description character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_codhojaruta       varchar;
    sp_idhojaruta        integer;
    sp_modalidad         integer;
    sp_idoperador        integer;
    sp_estadoactividad   integer;
    sp_idaccion          integer;
    sp_idmotivocierre    integer;
    sp_idcausacierre     integer;

begin 


    select a.codhojaruta ,
           a.idhojaruta ,
           b.modalidad ,
           a.idoperador ,
           a.estadoactividad ,
           a.idaccion ,
           a.idmotivocierre ,
           a.idcausacierre 
      into sp_codhojaruta,
           sp_idhojaruta,
           sp_modalidad,
           sp_idoperador,
           sp_estadoactividad,
           sp_idaccion,
           sp_idmotivocierre,
           sp_idcausacierre
      from mct_movimientoordentrabajo a,
           mct_hojaruta b
     where a.idmovimientoordentrabajo = idworkordermovs
       and a.codhojaruta = b.codhojaruta ;
    

      if ( sp_modalidad = 1) then

          RETURN QUERY
          
      		select a.idoperador ,
			       b.nombreoperador ,
			       a.idparte,
			       d.nombrecomponente ,
			       to_char(a.fechainicio, 'dd-mm-yyyy hh24:mi:ss'),
			       to_char(a.fechatermino, 'dd-mm-yyyy hh24:mi:ss'),
			       case
			          when a.fechatermino is null then
			          	   cast((date_part('day', now()::timestamp - a.fechainicio::timestamp ) * 1440 + 
				         		 date_part('hour', now()::timestamp - a.fechainicio::timestamp ) * 60 + 
						 		 date_part('minute', now()::timestamp - a.fechainicio::timestamp )) as integer)
			          when a.fechatermino is not null then 
			          	   cast((date_part('day', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 1440 + 
				         		 date_part('hour', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 60 + 
						 		 date_part('minute', a.fechatermino::timestamp - a.fechainicio::timestamp )) as integer)		          
			       end,
				   a.codigoaccion ,
				   c.nombreaccion ,
				   e.nombreaccion ,
				   a.observacion
			  from mct_movimientoordentrabajo a
			left join  mct_operador b	on a.idoperador = b.idoperador
			left join  mct_accion c		on a.idaccion = c.idaccion
			left join  mct_componente d on a.idparte  = d.idcomponente 
			left join  mct_accion e		on a.idmotivocierre  = e.idaccion
			where idmovimientoordentrabajo = idworkordermovs;
	
      else

          RETURN QUERY   
          
      		select a.idoperador ,
			       b.nombreoperador ,
			       a.idparte,
			       d.nombreparte ,
			       to_char(a.fechainicio, 'dd-mm-yyyy hh24:mi:ss'),
			       to_char(a.fechatermino, 'dd-mm-yyyy hh24:mi:ss'),
			       case
			          when a.fechatermino is null then
			          	   cast((date_part('day', now()::timestamp - a.fechainicio::timestamp ) * 1440 + 
				         		 date_part('hour', now()::timestamp - a.fechainicio::timestamp ) * 60 + 
						 		 date_part('minute', now()::timestamp - a.fechainicio::timestamp )) as integer)
			          when a.fechatermino is not null then 
			          	   cast((date_part('day', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 1440 + 
				         		 date_part('hour', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 60 + 
						 		 date_part('minute', a.fechatermino::timestamp - a.fechainicio::timestamp )) as integer)		          
			       end,
				   a.codigoaccion ,
				   c.nombreaccion ,
				   e.nombreaccion ,
				   a.observacion
			  from mct_movimientoordentrabajo a
			left join  mct_operador b	on a.idoperador = b.idoperador
			left join  mct_accion c		on a.idaccion = c.idaccion
			left join  mct_parte d 		on a.idparte  = d.idparte
			left join  mct_accion e		on a.idmotivocierre  = e.idaccion
			where idmovimientoordentrabajo = idworkordermovs;
	
      end if;
    
				
END;
$$;


ALTER FUNCTION traking.evtlistoperatorregisterjob(idworkordermovs bigint) OWNER TO postgres;

--
-- TOC entry 1290 (class 1255 OID 17214)
-- Name: evtlistoptionuser(integer); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistoptionuser(id_usuario integer) RETURNS TABLE(path character varying, title character varying, type character varying, icontype character varying, collapse character varying, children character varying)
    LANGUAGE plpgsql
    AS $$
  
  DECLARE
  FIRST       VARCHAR;
  R4          VARCHAR;
  R5          VARCHAR;
  R6          VARCHAR;
  R7          VARCHAR;
  R8          VARCHAR;
  
  C1          VARCHAR;
  C2          VARCHAR;
  C3          VARCHAR;
  C4          VARCHAR;
  C5          VARCHAR;
  C6          VARCHAR;
  fa_path     VARCHAR;
  fa_nom      VARCHAR;
  fa_abr      VARCHAR;
  id_perfil   INTEGER;
  
  json_o      VARCHAR;
  
  CONT01      INTEGER;
  CHILD       INTEGER;
  TOTAL_ROW   INTEGER;
  var_record1 record;
  var_record2 record;
 MENU         VARCHAR[][];

  sp_username  varchar;

BEGIN
  CHILD = 0;

  id_perfil:= 0;
  IF (SELECT 1 FROM mct_usuario
  WHERE mct_usuario.idusuario = id_usuario )  THEN

      SELECT idperfil, usuario INTO id_perfil, sp_username  FROM mct_usuario
      WHERE mct_usuario.idusuario = id_usuario;
      
  ELSE
      id_perfil := 999999;
  END IF;

  SELECT MAX(R0) INTO  TOTAL_ROW from (
      SELECT 
       row_number() over (order by ordenmenu nulls last) as R0,
      C.idmnav as R1, upper(nombremenu) AS R2,ordenmenu AS R3,count(*) as TOTAL
      FROM mct_perfil A
          LEFT JOIN mct_perfilmnav B on A.idperfil=B.idperfil
          LEFT JOIN mct_mnav C on C.idmnav = B.idmnav
          LEFT JOIN mct_mnavfnav D on D.idmnav = C.idmnav
          LEFT JOIN mct_fnav E on E.idfnav =  D.idfnav
      WHERE A.idperfil = 1
      GROUP BY C.ordenmenu,nombremenu,C.idmnav 
      ) AS P;
  
  FOR var_record1 IN (
     select * from (
      SELECT row_number() over (order by ordenmenu nulls last) as R0,
	        C.idmnav as R1, UPPER(nombremenu) AS R2,
	        ordenmenu AS R3, 
	        C.path AS path_menu, 
			C.title AS title_menu, 
			C.icontype AS icontype_menu,  
			C.type AS type_menu, 
			C.setcollapse AS setcollapse_menu, 
			count(*) as TOTAL
      FROM mct_usuario A
          LEFT JOIN mct_perfilmnav B on A.idperfil=B.idperfil
          LEFT JOIN mct_mnav C       on C.idmnav = B.idmnav
          LEFT JOIN mct_mnavfnav D   on D.idmnav = C.idmnav
         LEFT JOIN mct_fnav E       on E.idfnav =  D.idfnav
         LEFT JOIN mct_perfil f     on A.idperfil =f.idperfil
          join mct_usuariofnav g on a.idusuario = g.idusuario and g.idfnav = e.idfnav 
      WHERE A.idusuario = id_usuario
      GROUP BY C.ordenmenu,nombremenu,C.idmnav ) as p
  ORDER BY R3
  )

LOOP

  IF var_record1.TOTAL = 0 then
  
       SELECT  COUNT(*) INTO CONT01
       FROM mct_mnavfnav a,
            mct_usuariofnav b
       WHERE a.idmnav = var_record1.R1
            and a.idfnav = b.idfnav
            and b.idusuario = id_usuario;
      
       IF CONT01 = 0 then
       
			path := var_record1.path_menu;        
			title := var_record1.title_menu;       
			type := var_record1.type_menu;        
			icontype := var_record1.icontype_menu;  
			collapse := var_record1.setcollapse_menu;    
				
			 --path := CONCAT(E'/',CONCAT('pathmnav_',var_record1.R1));
			 --title := CONCAT(var_record1.R2);
			 --type := CONCAT('type_',var_record1.R1);
			 --icontype := CONCAT('icontype_',var_record1.R1); 
			 --collapse := CONCAT('collapse_',var_record1.R1); 
		 
      ELSE    
          
          SELECT  CONCAT('nombremenu_',A.idmnav) INTO R6
          FROM mct_mnav A
                  LEFT JOIN mct_mnavfnav B on A.idmnav =  B.idmnav
                  LEFT JOIN mct_fnav C on C.idfnav =  B.idfnav
          WHERE A.idmnav = var_record1.R1;
          
          SELECT  CONCAT('pathfnav_',A.idmnav) INTO R7
          FROM mct_mnav A
                  LEFT JOIN mct_mnavfnav B on A.idmnav =  B.idmnav
                  LEFT JOIN mct_fnav C on C.idfnav =  B.idfnav
          WHERE A.idmnav = var_record1.R1;
          
          SELECT  CONCAT('abfnav_',A.idmnav) INTO R8
          FROM mct_mnav A
                  LEFT JOIN mct_mnavfnav B on A.idmnav =  B.idmnav
                  LEFT JOIN mct_fnav C on C.idfnav =  B.idfnav
          WHERE A.idmnav = var_record1.R1;
          
		  path := var_record1.path_menu;         
          title := var_record1.title_menu;
          type := var_record1.type_menu; 
          icontype := var_record1.icontype_menu; 
		  collapse := var_record1.setcollapse_menu;    
		 
		 -- path := CONCAT(E'/',CONCAT('pathmnav_',var_record1.R1));
          --title := CONCAT(var_record1.R2);
         -- type := CONCAT('type_',var_record1.R1);
          --icontype := CONCAT('icontype_',var_record1.R1); 
          --collapse := CONCAT('collapse_',var_record1.R1); 		
          --children := CONCAT(children,E'{path: ''',R7,E'''',E', title: ''',R6,E''', ab: ''',R8,E'''},~'); 
				    
          children := 'children: [~"';
          children := CONCAT(children,R6,'~');  
          json_o := ']';
          children := CONCAT(children,json_o);
         
      END IF;
  END IF;
 
  IF var_record1.TOTAL >= 1 then
  
    children := '['; 
	path := var_record1.path_menu; 
    title := var_record1.title_menu;      
    type := var_record1.type_menu;
    icontype := var_record1.icontype_menu; 
    collapse := var_record1.setcollapse_menu; 
   
	--path := CONCAT(E'/',CONCAT('pathmnav_',var_record1.R1));
    --title := CONCAT(var_record1.R2);
    --type := CONCAT('type_',var_record1.R1);
    --icontype := CONCAT('icontype_',var_record1.R1); 
    --collapse := CONCAT('collapse_',var_record1.R1);
   
    
    FOR var_record2 IN (  
      SELECT row_number() over (order by ordenmenu nulls last) as R0,
            ordenmenu AS R2, 
            D.idfnav AS R3, 
            COALESCE(NULLIF(E.nombrefnav,'') , '0' ) AS R4, 
			CONCAT('{path: "',E.path,'", title: "',E.title,'", ab: "',E.ab,'"},') AS R10,
            E.ordenfnav AS R5,
            D.idfnav AS R6
      FROM mct_mnav  A
          LEFT JOIN mct_mnavfnav D    on D.idmnav = A.idmnav
          LEFT JOIN mct_fnav E        on E.idfnav = D.idfnav
           join mct_usuariofnav f on e.idfnav = f.idfnav and f.idusuario = id_usuario
      WHERE A.idmnav = var_record1.R1
      ORDER BY R5 
)
     LOOP
        -- children := CONCAT(children,E'{path: ''',E.path,E'''',E', title: ''',E.title,E''', ab: ''',E.ab,E'''},'); 
         children := CONCAT(children,var_record2.R10);
		--children := CONCAT(children,var_record2.R4,'~');
     END LOOP;
    
     children := substring(children from 1 for (char_length(children) - 1));
     json_o := ']';
     children := CONCAT(children,json_o);   
  END IF;
  CHILD := CHILD +1;
  IF CHILD < TOTAL_ROW THEN
      json_o := '},';
  ELSE
      json_o := '}';
  END IF;
  RETURN NEXT; 
END LOOP; 

if (select 1
      from traking.mct_bitacoraaccesos
     where idusuario = cast(id_usuario as bigint)) then

	update traking.mct_bitacoraaccesos
       set fechaultimaconexion = now()
     where idusuario = cast(id_usuario as bigint);

else

	insert into traking.mct_bitacoraaccesos (
				idusuario,
				usuario,
				fechaultimaconexion)
		values (cast(id_usuario as bigint),
                sp_username,
                now()
			);

end if;


END;
$$;


ALTER FUNCTION traking.evtlistoptionuser(id_usuario integer) OWNER TO postgres;

