--

CREATE FUNCTION traking.evtlistordenesappnc() RETURNS TABLE(ot bigint, cliente character varying, producto character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

	    select a.idordentrabajo ,
	          -- a.idcliente ,
	           b.nombrecliente ,
	          -- a.idproducto ,
	           c.nombreproducto 
	      from mct_ordentrabajo a,
