--
-- TOC entry 1276 (class 1255 OID 17219)
-- Name: evtlistorigenncfappmasing(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistorigenncfappmasing(idot character varying) RETURNS TABLE(idoriginncf bigint, originname character varying, detailname character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying, codigoaccion character varying)
    LANGUAGE plpgsql
    AS $$
declare

	sp_nombre	varchar;

BEGIN

	select b.nombre 
	  into sp_nombre
	  from mct_ordentrabajo a
	  left join mct_usuario b on a.idusuario = b.idusuario
     where a.idordentrabajo = cast(idot as bigint);
    
	RETURN QUERY
    
    select *
    from (
		SELECT a.idorigenncf, 
		       --cast(a.nombreorigen||' / '||a.detalleorigen as varchar), 
		       a.nombreorigen ,
		       a.detalleorigen, 		       
		       a.estado, 
		       b.nombreestado ,
		       a.fechacreacion, 
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion,
		       a.codigoaccion 
	 	  FROM traking.mct_origenncf a,
	 	       traking.mct_estado b
	 	 where a.estado = b.idestado 
           and a.estado = 1
	 	   and a.aplicancfapp is true
	  union 
		SELECT a.idorigenncf, 
		       --cast(a.nombreorigen||' / '||a.detalleorigen as varchar), 
		       a.nombreorigen||' - '||sp_nombre ,
		       a.detalleorigen, 		       
		       a.estado, 
		       b.nombreestado ,
		       a.fechacreacion, 
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion,
		       a.codigoaccion 
	 	  FROM traking.mct_origenncf a,
	 	       traking.mct_estado b
	 	 where a.estado = b.idestado 
	 	   and a.idorigenncf = 4	
		   and a.estado = 1
	 	   ) tabla
	  order by tabla.nombreorigen ;

END;
$$;


ALTER FUNCTION traking.evtlistorigenncfappmasing(idot character varying) OWNER TO postgres;

--
-- TOC entry 965 (class 1255 OID 17220)
