CREATE FUNCTION traking.evtlistorigenncfappmasingfund(idot character varying, idareas character varying) RETURNS TABLE(idoriginncf bigint, originname character varying, detailname character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying, codigoaccion character varying)
    LANGUAGE plpgsql
    AS $$
declare

	sp_nombre	varchar;

BEGIN

	if (cast(idareas as bigint) = 10) then
	
		RETURN QUERY
	
		SELECT a.idorigenncf, 
		       --cast(a.nombreorigen||' / '||a.detalleorigen as varchar), 
		       a.nombreorigen ,
		       a.detalleorigen, 		       
		       a.estado, 
		       b.nombreestado ,
		       a.fechacreacion, 
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion,
		       a.codigoaccion 
	 	  FROM traking.mct_origenncf a,
	 	       traking.mct_estado b
	 	 where a.estado = b.idestado 
	 	   and a.aplicancfapp is true
	 	   and a.idorigenncf = 2;
	 	   
	else
	
		select b.nombre 
		  into sp_nombre
		  from mct_ordentrabajo a
		  left join mct_usuario b on a.idusuario = b.idusuario
	     where a.idordentrabajo = cast(idot as bigint);
	    
		RETURN QUERY
	    
	    select *
	    from (
			SELECT a.idorigenncf, 
			       --cast(a.nombreorigen||' / '||a.detalleorigen as varchar), 
			       a.nombreorigen ,
			       a.detalleorigen, 		       
			       a.estado, 
			       b.nombreestado ,
			       a.fechacreacion, 
			       a.usuariocreacion, 
			       a.fechamodificacion,
			       a.usuariomodificacion,
			       a.codigoaccion 
		 	  FROM traking.mct_origenncf a,
		 	       traking.mct_estado b
		 	 where a.estado = b.idestado 
		 	   and a.aplicancfapp is true
               and a.estado = 1
		  union 
			SELECT a.idorigenncf, 
			       --cast(a.nombreorigen||' / '||a.detalleorigen as varchar), 
			       a.nombreorigen||' - '||'sp_nombre' ,
			       a.detalleorigen, 		       
			       a.estado, 
			       b.nombreestado ,
			       a.fechacreacion, 
			       a.usuariocreacion, 
			       a.fechamodificacion,
			       a.usuariomodificacion,
			       a.codigoaccion 
		 	  FROM traking.mct_origenncf a,
		 	       traking.mct_estado b
		 	 where a.estado = b.idestado 
		 	   and a.idorigenncf = 4	
               and a.estado = 1
		 	   ) tabla
		  order by tabla.nombreorigen ;
		 
	end if;
	

END;
$$;


