--
-- TOC entry 2180 (class 1255 OID 17222)
-- Name: evtlistotanteriordata(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistotanteriordata(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idfamily bigint, idcliente bigint, idproducto bigint, customername character varying, productname character varying, username character varying)
    LANGUAGE plpgsql
    AS $$
declare
	sp_producto		integer;
begin
	
	sp_producto	:= 0;

	select mo.idproducto 
	  into sp_producto
	  from mct_ordentrabajo mo 
	 where mo.idordentrabajo = idworkorders;

	if ( sp_producto in (10,11,12,13,14,15,16,17, 18) ) then
	
    		RETURN QUERY
    
			select a.idordentrabajo ,
			       a.idfamilia ,
                   a.idcliente,
                   a.idproducto,
			       b.nombrecorto ,
			       c.nombreproductonepcast  ,
			       d.nombre 
			  from mct_ordentrabajo a,
			       mct_cliente b,
			       mct_productonepcast c,
			       mct_usuario d
			 where a.idordentrabajo = idworkorders
			   --and a.idestadoorden in (5,6,7)
			   --and a.idfamilia in (8, 10)
			   and a.idcliente = b.idcliente 
			   and a.idproducto = c.idproductonepcast  
			   and a.idusuario = d.idusuario
			 order by a.idordentrabajo ;
			
	else
	
    		RETURN QUERY
    
			select a.idordentrabajo ,
			       a.idfamilia ,
                   a.idcliente,
                   a.idproducto,
			       b.nombrecorto ,
			       c.nombreproducto ,
			       d.nombre 
			  from mct_ordentrabajo a,
			       mct_cliente b,
			       mct_producto c,
			       mct_usuario d
			 where a.idordentrabajo = idworkorders
			   --and a.idestadoorden in (5,6,7)
			   --and a.idfamilia in (8, 10)
			   and a.idcliente = b.idcliente 
			   and a.idproducto = c.idproducto 
			   and a.idusuario = d.idusuario
			 order by a.idordentrabajo ;
			
	end if;



   END;
$$;


ALTER FUNCTION traking.evtlistotanteriordata(idworkorders bigint) OWNER TO postgres;

