--
-- TOC entry 2296 (class 1255 OID 17224)
-- Name: evtlistotdispatch(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistotdispatch(idworkorders bigint) RETURNS TABLE(idpartdispatchhead bigint, datedispatch timestamp without time zone, idworkorder bigint, outputguide bigint, workordername character varying, clientname character varying, orderstatusname character varying, productname character varying, dateguia character varying)
    LANGUAGE plpgsql
    AS $$
declare

	sp_idproducto	integer;

BEGIN

	select idproducto
	  into sp_idproducto
	  from mct_ordentrabajo mo 
	 where idordentrabajo = idworkorders;
	
	if ( sp_idproducto in (10,11,12,13,14,15,16,17,18)) then

	        RETURN QUERY
	            
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar),
			       d.nombrecliente,
			       e.nombreestado,
			       cast(h.nombreproductonepcast  as varchar),
			       cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar)
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_productonepcast h
			     --mct_modelo i,
			     --mct_subfamilia j,
			     --mct_etapaparam k
			where a.idordentrabajo = idworkorders
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  and c.idproducto = h.idproductonepcast
			 order by a.iddespachopartecabecera asc;
			  --and h.idmodelo = i.idmodelo
			  --and i.idsubfamilia = j.idsubfamilia 
			  --and h.idetapaparam = k.idetapaparam ;	
	
	else
	
	        RETURN QUERY
	            
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar),
			       d.nombrecliente,
			       e.nombreestado,
			       cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam as varchar),
			       cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar)
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_producto h,
			     mct_modelo i,
			     mct_subfamilia j,
			     mct_etapaparam k
			where a.idordentrabajo = idworkorders
			  and a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  and c.idproducto = h.idproducto
			  and h.idmodelo = i.idmodelo
			  and i.idsubfamilia = j.idsubfamilia 
			  and h.idetapaparam = k.idetapaparam 
			 order by a.iddespachopartecabecera asc;	
	
	end if;
	

END;
$$;


ALTER FUNCTION traking.evtlistotdispatch(idworkorders bigint) OWNER TO postgres;

