--
-- TOC entry 1747 (class 1255 OID 17227)
-- Name: evtlistotdispatchporoc(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistotdispatchporoc(idocs bigint) RETURNS TABLE(idpartdispatchhead bigint, datedispatch timestamp without time zone, idworkorder bigint, outputguide bigint, workordername character varying, clientname character varying, orderstatusname character varying, productname character varying, dateguia character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN

    ------------------------------------------------------------------
    -- PRODUCTOS NEPCAST
    ------------------------------------------------------------------
    RETURN QUERY

    SELECT
        a.iddespachopartecabecera,
        a.fechadespacho,
        a.idordentrabajo,
        a.guiasaliente,

        CAST(f.sigla || '_' || g.sigla AS varchar),

        d.nombrecliente,
        e.nombreestado,

        CAST(h.nombreproductonepcast AS varchar),

        CAST(
            to_char(a.fechaguia, 'dd-mm-yyyy')
            AS varchar
        )

    FROM mct_despachopartecabecera a,
         mct_ordentrabajo c,
         mct_cliente d,
         mct_estadoorden e,
         mct_tipoorden f,
         mct_familia g,
         mct_productonepcast h

    WHERE a.idordentrabajo = c.idordentrabajo

      -- BUSQUEDA POR OC
      AND c.ordencompra = idocs

      AND c.idcliente = d.idcliente
      AND c.idestadoorden = e.idestadoorden
      AND c.idtipoorden = f.idtipoorden
      AND c.idfamilia = g.idfamilia
      AND c.idordentrabajo >= 30000

      -- PRODUCTOS NEPCAST
      AND c.idproducto IN (10,11,12,13,14,15,16,17,18)

      AND c.idproducto = h.idproductonepcast

    ORDER BY a.iddespachopartecabecera ASC;


    ------------------------------------------------------------------
    -- PRODUCTOS NORMALES
    ------------------------------------------------------------------
    RETURN QUERY

    SELECT
        a.iddespachopartecabecera,
        a.fechadespacho,
        a.idordentrabajo,
        a.guiasaliente,

        CAST(f.sigla || '_' || g.sigla AS varchar),

        d.nombrecliente,
        e.nombreestado,

        CAST(
            j.sigla || ' ' ||
            i.nombremodelo || ' ' ||
            k.nombreparam
            AS varchar
        ),

        CAST(
            to_char(a.fechaguia, 'dd-mm-yyyy')
            AS varchar
        )

    FROM mct_despachopartecabecera a,
         mct_ordentrabajo c,
         mct_cliente d,
         mct_estadoorden e,
         mct_tipoorden f,
         mct_familia g,
         mct_producto h,
         mct_modelo i,
         mct_subfamilia j,
         mct_etapaparam k

    WHERE a.idordentrabajo = c.idordentrabajo

      -- BUSQUEDA POR OC
      AND c.ordencompra = idocs

      AND c.idcliente = d.idcliente
      AND c.idestadoorden = e.idestadoorden
      AND c.idtipoorden = f.idtipoorden
      AND c.idfamilia = g.idfamilia
      AND c.idordentrabajo >= 30000

      -- PRODUCTOS NORMALES
      AND c.idproducto NOT IN (10,11,12,13,14,15,16,17,18)

      AND c.idproducto = h.idproducto
      AND h.idmodelo = i.idmodelo
      AND i.idsubfamilia = j.idsubfamilia
      AND h.idetapaparam = k.idetapaparam

    ORDER BY a.iddespachopartecabecera ASC;

END;

$$;


ALTER FUNCTION traking.evtlistotdispatchporoc(idocs bigint) OWNER TO postgres;

