CREATE FUNCTION traking.evtlistotdispatchporplano(planos character varying) RETURNS TABLE(idpartdispatchhead bigint, datedispatch timestamp without time zone, idworkorder bigint, outputguide bigint, workordername character varying, clientname character varying, orderstatusname character varying, productname character varying, dateguia character varying)
    LANGUAGE plpgsql
    AS $$
declare

	sp_idproducto		bigint;
    sp_idordentrabajo	bigint;

BEGIN

	
	        RETURN QUERY
	            
	  		select a.iddespachopartecabecera,
			       a.fechadespacho,
			       a.idordentrabajo,
			       --c.guiasaliente,
			       a.guiasaliente,
			      -- c.nombreordentrabajo,
			       cast(f.sigla||'_'||g.sigla as varchar),
			       d.nombrecliente,
			       e.nombreestado,
			       cast(j.sigla||' '||i.nombremodelo||' '||k.nombreparam as varchar),
			       cast(to_char(a.fechaguia, 'dd-mm-yyyy') as varchar)
			from mct_despachopartecabecera a,
			     mct_ordentrabajo c,
			     mct_cliente d,
			     mct_estadoorden e,
			     mct_tipoorden f,
			     mct_familia g,
			     mct_producto h,
			     mct_modelo i,
			     mct_subfamilia j,
			     mct_etapaparam k
			where a.idordentrabajo = c.idordentrabajo
			  and c.idcliente = d.idcliente
			  and c.idestadoorden = e.idestadoorden
			  and c.idtipoorden = f.idtipoorden 
			  and c.idfamilia in (8,10) 
			  and c.idfamilia = g.idfamilia 
			  and c.idordentrabajo >= 30000
			  and h.planogeneral like '%'||planos||'%'
			  and c.idproducto = h.idproducto
			  and h.idmodelo = i.idmodelo
			  and i.idsubfamilia = j.idsubfamilia 
			  and h.idetapaparam = k.idetapaparam 
			 order by a.iddespachopartecabecera asc;	
	

END;
$$;


