--

CREATE FUNCTION traking.evtlistotinspdata(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idfamily bigint, customername character varying, productname character varying, username character varying)
    LANGUAGE plpgsql
    AS $$
declare
	sp_producto	   bigint;
    sp_idfamilia   bigint;
begin
	
	sp_producto		:= 0;
    sp_idfamilia	:= 0;

	select idproducto ,
           idfamilia
	  into sp_producto,
           sp_idfamilia
	  from mct_ordentrabajo mo 
	 where idordentrabajo = idworkorders;

	if ( sp_producto in (10,11,12,13,14,15,16,17, 18) and sp_idfamilia = 11 ) then
	
    		RETURN QUERY
    
			select a.idordentrabajo ,
			       a.idfamilia ,
			       b.nombrecorto ,
			       c.nombreproductonepcast  ,
			       d.nombre 
			  from mct_ordentrabajo a,
			       mct_cliente b,
			       mct_productonepcast c,
			       mct_usuario d
			 where a.idordentrabajo = idworkorders
			   --and a.idestadoorden in (5,6,7)
			   --and a.idfamilia in (8, 10)
			   and a.idcliente = b.idcliente 
			   and a.idproducto = c.idproductonepcast  
			   and a.idusuario = d.idusuario
			 order by a.idordentrabajo ;
			
	else
	
    		RETURN QUERY
    
			select a.idordentrabajo ,
			       a.idfamilia ,
			       b.nombrecorto ,
			       c.nombreproducto ,
			       d.nombre 
			  from mct_ordentrabajo a,
			       mct_cliente b,
			       mct_producto c,
			       mct_usuario d
			 where a.idordentrabajo = idworkorders
			   --and a.idestadoorden in (5,6,7)
			   --and a.idfamilia in (8, 10)
			   and a.idcliente = b.idcliente 
			   and a.idproducto = c.idproducto 
			   and a.idusuario = d.idusuario
			 order by a.idordentrabajo ;
			
	end if;



   END;
$$;


