--
-- TOC entry 2372 (class 1255 OID 17232)
-- Name: evtlistotpredispatchdetalle(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistotpredispatchdetalle(idworkorders bigint, iddespachos bigint) RETURNS TABLE(idpart bigint, partname character varying, quantity integer, idworkorderpart bigint, qdispatch bigint, pendiente bigint)
    LANGUAGE plpgsql
    AS $$
declare

		rec_email      			RECORD;
	    rec_trab       			RECORD;		
	   
	    sp_anteriores			bigint;
	   	   
BEGIN
        
		  FOR rec_trab IN (   
		  
		        select a.idordentrabajorepuesto ,
	       			   a.nombrecomponentetemp ,
	      			   cast(a.cantidad as integer) as cantidad,
				       cast(a.idordentrabajorepuesto as bigint) as idordentrabajorepuesto,
				       coalesce (sum(c.qdespacho) , 0) as despachado
	               from mct_ordentrabajorepuesto a
	              left join mct_despachopartecabecera b on a.idordentrabajo = b.idordentrabajo 
	              left join mct_despachopartedetalle c on b.iddespachopartecabecera = c.iddespachopartecabecera  and a.idordentrabajorepuesto = c.idparte
	              where a.idordentrabajo = idworkorders
	                and c.iddespachopartecabecera = iddespachos
	              group by a.idordentrabajorepuesto ,
	       			   a.nombrecomponentetemp ,
	       			   cast(a.cantidad as integer) ,
				       cast(a.idordentrabajorepuesto as bigint)
					)
									
			loop 
				
				idpart 			:= rec_trab.idordentrabajorepuesto;
				partname		:= rec_trab.nombrecomponentetemp;
				quantity		:= rec_trab.cantidad ;
				idworkorderpart	:= rec_trab.idordentrabajorepuesto;
				qdispatch		:= rec_trab.despachado;
			    --pendiente		:= rec_trab.cantidad - rec_trab.despachado;
			
				select coalesce(sum(qdespacho),0)
				  into sp_anteriores
				  from mct_despachopartedetalle
				 where iddespachopartecabecera < iddespachos
				   and idordentrabajoparte = rec_trab.idordentrabajorepuesto;
			   
			    pendiente		:= (rec_trab.cantidad - sp_anteriores) - rec_trab.despachado;
				
				return next;
			
			end loop;
            

END;
$$;


ALTER FUNCTION traking.evtlistotpredispatchdetalle(idworkorders bigint, iddespachos bigint) OWNER TO postgres;

--
-- TOC entry 1107 (class 1255 OID 17233)
-- Name: evtlistotprioridad(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistotprioridad() RETURNS TABLE(idworkorder bigint, namerowkorder character varying, deliverydate timestamp with time zone, funditiondate timestamp with time zone, programerwork character varying, programerlcc character varying, idworktype integer, priority integer, idorderstatus bigint, nameorderstatus character varying, arraystatus character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

		select a.idordentrabajo,
		       a.nombreordentrabajo,
		       coalesce(a.fechaentrega, now()),
		       coalesce(a.fechaentrega, now()),
		       -- Lo anterior es la fecha de fundicion, que no deberia estar aca puesto que debe ser por Hoja de ruta
		       cast('1/12' as varchar),
		       -- Esto sale del count de lo procesado versus la cantidad de Hojas de ruta
		       cast('30/65' as varchar),
		       -- Esto revisar lo enviado por pablo
		       5,
		       -- lo anterior revisar lo entregado por pablo
		       prioridad,
		       a.idestadoorden,
		       b.nombreestado,
		       cast('001101' as varchar)
		from mct_ordentrabajo a
		left join mct_estadoorden b on a.idestadoorden = b.idestadoorden;

END;
$$;


ALTER FUNCTION traking.evtlistotprioridad() OWNER TO postgres;

--
-- TOC entry 2253 (class 1255 OID 17234)
-- Name: evtlistottodispatch(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistottodispatch() RETURNS TABLE(idworkorder bigint, statusname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
			select a.idordentrabajo , 
			       b.nombreestado 
			  from mct_ordentrabajo a,
			       mct_estadoorden b
			 where a.idestadoorden in (0,2,3,4,5,6,7)
			   and a.idestadoorden = b.idestadoorden 
			   and a.idordentrabajo >= 30000
               and a.idtipoorden not in (8,9,10,11)
			  order by a.idordentrabajo asc;

   END;
$$;


ALTER FUNCTION traking.evtlistottodispatch() OWNER TO postgres;

--
-- TOC entry 2080 (class 1255 OID 17235)
-- Name: evtlistoutputotdetail(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistoutputotdetail(periods character varying) RETURNS TABLE(idworkorder bigint, workordername character varying, deliverydate character varying, receptiondate character varying, statusname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		 
			select a.idordentrabajo ,
			       c.nombreproducto ,
			       cast(to_char(a.fechaentrega, 'dd-mm-yyyy') as varchar) ,
			       cast(to_char(a.fecharecepcion,'dd-mm-yyyy') as varchar),
			       b.nombreestado 
			  from mct_ordentrabajo a,
			       mct_estadoorden b,
			       mct_producto c
			 where to_date(to_char(a.fechadespacho , 'yyyy-mm'),'yyyy-mm') = to_date(periods, 'yyyy-mm')
			   and a.idestadoorden = b.idestadoorden 
			   and a.idproducto    = c.idproducto 
			 order by a.idordentrabajo ;

END;
$$;


