--
-- TOC entry 2228 (class 1255 OID 17236)
-- Name: evtlistparbytot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistparbytot(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idpartworkorder bigint, idpart bigint, partchar text, partname character varying, principal character varying, blueprintname character varying, item bigint, idworktype bigint, idreparefab bigint, observation character varying, directevaluation bigint, idparttype bigint, insumocomp bigint, insumorec bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
    select * from (
		select a.idordentrabajo, 
		       a.idordentrabajoparte,
		       a.idparte,
		       LPAD(b.idparte::integer::text::varchar, 3, '0') as partchar,
		       b.nombreparte, 
		       d.nombreboleano,
		       f.nombreplano ,
		       a.itemparte ,
		       e.idtipotrabajo,
		       e.idreparafabrica,
		       e.observacion,
		       cast(coalesce(g.evaluaciondirecta,null,2, g.evaluaciondirecta) as bigint),
		       b.idtipoparte ,
		       e.cantidadcompra ,
		       e.cantidadrecupera 
		     from mct_ordentrabajoparte a
		left join mct_parte b        on a.idparte        = b.idparte 
		left join mct_ordentrabajo c on a.idordentrabajo = c.idordentrabajo
		left join mct_boleano d      on b.esprincipal    = d.idboleano
		left join mct_evaluacion e   on a.idordentrabajoparte = e.idordentrabajoparte
		left join mct_plano  f       on b.idplano  = f.idplano 
		left join mct_componente  g  on b.idcomponente = g.idcomponente 
		where a.idordentrabajo = idworkorders
		 and b.esprincipal = 1
		 --order by 3 asc
		union 
		select a.idordentrabajo, 
		       a.idordentrabajoparte,
		       a.idparte,
		       LPAD(b.idparte::integer::text::varchar, 3, '0') as partchar,
		       b.nombreparte, 
		       d.nombreboleano,
		       f.nombreplano ,
		       a.itemparte ,
		       e.idtipotrabajo,
		       e.idreparafabrica,
		       e.observacion,
		       cast(coalesce(g.evaluaciondirecta,null,2, g.evaluaciondirecta) as bigint),
		       b.idtipoparte ,
		       e.cantidadcompra ,
		       e.cantidadrecupera 
		     from mct_ordentrabajoparte a
		left join mct_parte b        on a.idparte        = b.idparte 
		left join mct_ordentrabajo c on a.idordentrabajo = c.idordentrabajo
		left join mct_boleano d      on b.esprincipal    = d.idboleano
		left join mct_evaluacion e   on a.idordentrabajoparte = e.idordentrabajoparte
		left join mct_plano  f       on b.idplano  = f.idplano 
		left join mct_componente  g  on b.idcomponente = g.idcomponente 
		where a.idordentrabajo = idworkorders
		 and b.esprincipal = 2 ) b
		 order by 6 desc, 3 asc, 8 asc	;	

END;
$$;


ALTER FUNCTION traking.evtlistparbytot(idworkorders bigint) OWNER TO postgres;

--
