		left join mct_parte b        on a.idparte        = b.idparte 
		left join mct_ordentrabajo c on a.idordentrabajo = c.idordentrabajo
		left join mct_boleano d      on b.esprincipal    = d.idboleano
		left join mct_evaluacion e   on a.idordentrabajoparte = e.idordentrabajoparte
		left join mct_plano  f       on b.idplano  = f.idplano 
	    left join mct_componente  g  on g.idcomponente  = b.idcomponente 
		where a.idordentrabajo = idworkorders
		 and b.esprincipal = 1
		 		 order by 6 desc, 3 asc, 8 asc;	

END;
$$;


ALTER FUNCTION traking.evtlistparbytotmovil(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1296 (class 1255 OID 17238)
-- Name: evtlistpartbyotinftec(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistpartbyotinftec(idworkorders bigint) RETURNS TABLE(idpartworkorder bigint, idpart bigint, partname text, picfile1 text, picfile2 text, picfile3 text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		select a.idordentrabajoparte,
		       a.idparte,
		       b.nombreparte||'-'||a.itemparte ,
		       uno.archivoadjunto ,
		       dos.archivoadjunto ,
		       tres.archivoadjunto 
		     from mct_ordentrabajoparte a
		left join mct_parte b        on a.idparte = b.idparte 
		left join mct_evaluacion e   on e.idordentrabajoparte = a.idordentrabajoparte
		left join mct_evaluacionadjunto uno on uno.idevaluacion = e.idevaluacion 
		left join mct_evaluacionadjunto dos on dos.idevaluacion = e.idevaluacion 
		left join mct_evaluacionadjunto tres on tres.idevaluacion = e.idevaluacion 		
		where a.idordentrabajo = idworkorders
		 and b.esprincipal = 1
		 and uno.correlativo = 0
		 and dos.correlativo = 1
		 and tres.correlativo = 2
		 order by a.idordentrabajoparte asc;	

END;
$$;


ALTER FUNCTION traking.evtlistpartbyotinftec(idworkorders bigint) OWNER TO postgres;

