--
-- TOC entry 2334 (class 1255 OID 17242)
-- Name: evtlistpicbycategory(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistpicbycategory(idattachedcategorys bigint, idworkorders bigint) RETURNS TABLE(idworkorderattachedtype bigint, idworkorder bigint, idattachedtype bigint, idattachedcategory bigint, nameattachedcategory character varying, picfile text, correlative bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    if (idattachedcategorys = 0) then
        RETURN QUERY
        
		select a.idordentrabajoadjunto,
		       a.idordentrabajo,
		       a.idtipoadjunto,
		       a.idcategoriaadjunto,
		       b.nombrecategoriaadjunto,
		       '',
	           --a.archivoadjunto,
		       a.correlativo
		  from mct_ordentrabajotipoadjunto a
  	      left join mct_categoriaadjunto b on a.idcategoriaadjunto = b.idcategoriaadjunto
  	     where idtipoadjunto in (2)
  	       and idordentrabajo = idworkorders
		 --order by idtipoadjunto desc, correlativo asc;
		 order by fechacreacion asc, correlativo asc;
    else
        if (idattachedcategorys = 3) then
        
                RETURN QUERY
        
        	    select cast(0 as INT8),
				       a.idordentrabajo , 
				       cast(2 as INT8),
				       cast(3 as INT8),
				       e.nombreparte , 
				       d.archivoadjunto , 
				       cast(0 as INT8) 
				from mct_ordentrabajo a,
				     mct_ordentrabajoparte b,
				     mct_evaluacion c,
				     mct_evaluacionadjunto d,
				     mct_parte e
				where a.idordentrabajo = idworkorders
				and a.idordentrabajo   = b.idordentrabajo 
				and b.idordentrabajoparte = c.idordentrabajoparte 
				and c.idevaluacion = d.idevaluacion 
				and b.idparte      = e.idparte 
				and e.esprincipal  = 1 ;
			
        elsif (idworkorders >= 31518) then--(idworkorders = 200 or idworkorders = 31518 or idworkorders = 31548) then
        
        		RETURN QUERY
          
				select a.idordentrabajoadjunto,
				       a.idordentrabajo,
				       a.idtipoadjunto,
				       a.idcategoriaadjunto,
				       b.nombrecategoriaadjunto,
			           a.archivoadjunto,
				       a.correlativo
				  from mct_ordentrabajotipoadjunto a
		  	      left join mct_categoriaadjunto b on a.idcategoriaadjunto = b.idcategoriaadjunto
		  	     where idtipoadjunto in (2)
		  	       and a.idcategoriaadjunto = idattachedcategorys
		  	       and a.idordentrabajo = idworkorders
				 --order by idtipoadjunto desc, correlativo asc;
				 --order by correlativo asc, fechacreacion asc;
				 order by idcategoriaadjunto asc, secuencia asc;			 
        
        else
		        RETURN QUERY
		        
				select a.idordentrabajoadjunto,
				       a.idordentrabajo,
				       a.idtipoadjunto,
				       a.idcategoriaadjunto,
				       b.nombrecategoriaadjunto,
			           a.archivoadjunto,
				       a.correlativo
				  from mct_ordentrabajotipoadjunto a
		  	      left join mct_categoriaadjunto b on a.idcategoriaadjunto = b.idcategoriaadjunto
		  	     where idtipoadjunto in (2)
		  	       and a.idcategoriaadjunto = idattachedcategorys
		  	       and a.idordentrabajo = idworkorders
				 --order by idtipoadjunto desc, correlativo asc;
				 --order by correlativo asc, fechacreacion asc;
				 order by correlativo asc;
         
         end if;
    end if;

END;
$$;


ALTER FUNCTION traking.evtlistpicbycategory(idattachedcategorys bigint, idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1167 (class 1255 OID 17243)
-- Name: evtlistpicbycategoryconmarcaagua(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistpicbycategoryconmarcaagua(idattachedcategorys bigint, idworkorders bigint) RETURNS TABLE(idworkorderattachedtype bigint, idworkorder bigint, idattachedtype bigint, idattachedcategory bigint, nameattachedcategory character varying, picfile text, correlative bigint, fechatomafoto character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    if (idattachedcategorys = 0) then
        RETURN QUERY
        
		select a.idordentrabajoadjunto,
		       a.idordentrabajo,
		       a.idtipoadjunto,
		       a.idcategoriaadjunto,
		       b.nombrecategoriaadjunto,
		       '',
	           --a.archivoadjunto,
		       a.correlativo,
               cast(
						    to_char(
						        case
						            when extract(dow from a.fechacreacion) = 6
						                then a.fechacreacion - interval '1 day'
						
						            when extract(dow from a.fechacreacion) = 0
						                then a.fechacreacion + interval '1 day'
						
						            else a.fechacreacion
						        end,
						        'yyyy-mm-dd hh24:mi:ss'
						    )
						    as varchar
						) as fechatomafoto
		  from mct_ordentrabajotipoadjunto a
  	      left join mct_categoriaadjunto b on a.idcategoriaadjunto = b.idcategoriaadjunto
  	     where idtipoadjunto in (2)
  	       and idordentrabajo = idworkorders
		 --order by idtipoadjunto desc, correlativo asc;
		 order by fechacreacion asc, correlativo asc;
    else
        if (idattachedcategorys = 3) then
        
                RETURN QUERY
        
        	    select cast(0 as INT8),
				       a.idordentrabajo , 
				       cast(2 as INT8),
				       cast(3 as INT8),
				       e.nombreparte , 
				       d.archivoadjunto , 
				       cast(0 as INT8),
                       cast('' as varchar) as fechatomafoto 
				from mct_ordentrabajo a,
				     mct_ordentrabajoparte b,
				     mct_evaluacion c,
				     mct_evaluacionadjunto d,
				     mct_parte e
				where a.idordentrabajo = idworkorders
				and a.idordentrabajo   = b.idordentrabajo 
				and b.idordentrabajoparte = c.idordentrabajoparte 
				and c.idevaluacion = d.idevaluacion 
				and b.idparte      = e.idparte 
				and e.esprincipal  = 1 ;
			
        elsif (idworkorders >= 31518) then--(idworkorders = 200 or idworkorders = 31518 or idworkorders = 31548) then
        
        		RETURN QUERY
          
				select a.idordentrabajoadjunto,
				       a.idordentrabajo,
				       a.idtipoadjunto,
				       a.idcategoriaadjunto,
				       b.nombrecategoriaadjunto,
			           a.archivoadjunto,
				       a.correlativo,
                       cast(
						    to_char(
						        case
						            when extract(dow from a.fechacreacion) = 6
						                then a.fechacreacion - interval '1 day'
						
						            when extract(dow from a.fechacreacion) = 0
						                then a.fechacreacion + interval '1 day'
						
						            else a.fechacreacion
						        end,
						        'yyyy-mm-dd hh24:mi:ss'
						    )
						    as varchar
						) as fechatomafoto
				  from mct_ordentrabajotipoadjunto a
		  	      left join mct_categoriaadjunto b on a.idcategoriaadjunto = b.idcategoriaadjunto
		  	     where idtipoadjunto in (2)
		  	       and a.idcategoriaadjunto = idattachedcategorys
		  	       and a.idordentrabajo = idworkorders
				 --order by idtipoadjunto desc, correlativo asc;
				 --order by correlativo asc, fechacreacion asc;
				 order by idcategoriaadjunto asc, secuencia asc;			 
        
        else
		        RETURN QUERY
		        
				select a.idordentrabajoadjunto,
				       a.idordentrabajo,
				       a.idtipoadjunto,
				       a.idcategoriaadjunto,
				       b.nombrecategoriaadjunto,
			           a.archivoadjunto,
				       a.correlativo,
                       cast(
						    to_char(
						        case
						            when extract(dow from a.fechacreacion) = 6
						                then a.fechacreacion - interval '1 day'
						
						            when extract(dow from a.fechacreacion) = 0
						                then a.fechacreacion + interval '1 day'
						
						            else a.fechacreacion
						        end,
						        'yyyy-mm-dd hh24:mi:ss'
						    )
						    as varchar
						) as fechatomafoto
				  from mct_ordentrabajotipoadjunto a
		  	      left join mct_categoriaadjunto b on a.idcategoriaadjunto = b.idcategoriaadjunto
		  	     where idtipoadjunto in (2)
		  	       and a.idcategoriaadjunto = idattachedcategorys
		  	       and a.idordentrabajo = idworkorders
				 --order by idtipoadjunto desc, correlativo asc;
				 --order by correlativo asc, fechacreacion asc;
				 order by correlativo asc;
         
         end if;
    end if;

END;
$$;


