--
-- TOC entry 1909 (class 1255 OID 17255)
-- Name: evtlistpicdossierporcategoria(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistpicdossierporcategoria(idworkorders bigint, idcolumnas bigint) RETURNS TABLE(idworkorder bigint, picfile text)
    LANGUAGE plpgsql
    AS $$
BEGIN

	  
	
	  if (idcolumnas = 1) then
	  
	      RETURN QUERY
	     
		  select idordentrabajo ,
			     archivoadjunto
			from mct_ordentrabajotipoadjunto
		   where idordentrabajo = idworkorders
		     and idcategoriaadjunto in (11,13)
	   	   order by correlativo asc;
	
	  elsif (idcolumnas = 3) then

	  	    RETURN QUERY
	  	     
		    select tab.idordentrabajo,
		           tab.archivoadjunto
		      from (
				  	select a.idordentrabajo ,
					       b.archivoadjunto ,
					       b.correlativo 
					  from mct_insp a, 
					       mct_inspadjunto b
					 where a.idordentrabajo = idworkorders
					   and a.idinsp = b.idinsp 
					union
					select a.idordentrabajo,
					       b.archivoadjunto ,
					       b.correlativo 
					  from mct_inspeccionvisual a,
					       mct_inspeccionvisualadjunto b
					 where a.idordentrabajo = idworkorders
					   and a.idinspeccionvisual = b.idinspeccionvisual 	      
		      ) tab
			 order by tab.correlativo ;
		
	  elsif (idcolumnas = 4) then

	  	    RETURN QUERY
	  	   
		  	  select idordentrabajo ,
				     archivoadjunto
				from mct_ordentrabajotipoadjunto
			   where idordentrabajo = idworkorders
			     and idcategoriaadjunto in (17,18, 19, 20)
		   	   order by correlativo asc;
		
	  elsif (idcolumnas = 7) then

	  	  	 RETURN QUERY
	  	  	   
		  	  select idordentrabajo ,
				     archivoadjunto
				from mct_ordentrabajotipoadjunto
			   where idordentrabajo = idworkorders
			     and idcategoriaadjunto in (21, 27)
		   	   order by correlativo asc;
	   	
	  elsif (idcolumnas = 8) then

	  	     RETURN QUERY
	  	  	   
		  	  select idordentrabajo ,
				     archivoadjunto
				from mct_ordentrabajotipoadjunto
			   where idordentrabajo = idworkorders
			     and idcategoriaadjunto in (28)
		   	   order by correlativo asc;
	   	  
	   	  
	  end if ;
        

END;
$$;


ALTER FUNCTION traking.evtlistpicdossierporcategoria(idworkorders bigint, idcolumnas bigint) OWNER TO postgres;

--
-- TOC entry 2053 (class 1255 OID 17256)
-- Name: evtlistpicparbyot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistpicparbyot(idworkorderparts bigint) RETURNS TABLE(idpartworkorder bigint, idpart bigint, partname character varying, idevaluation bigint, picfile text, correlative bigint, idevaluationattached bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		select a.idordentrabajoparte, 
		       a.idparte,
		       d.nombreparte,
		       b.idevaluacion,
		       c.archivoadjunto,
		       c.correlativo,
		       c.idevaluacionadjunto
		  from mct_ordentrabajoparte a
		inner join mct_evaluacion b on a.idordentrabajoparte = b.idordentrabajoparte
		inner join mct_evaluacionadjunto c on b.idevaluacion = c.idevaluacion
		inner join mct_parte d on a.idparte = d.idparte
		where a.idordentrabajoparte = idworkorderparts
		order by c.correlativo asc;

END;
$$;


