    LANGUAGE plpgsql
    AS $$
declare

    sp_funcav				numeric;
   
    sp_fami					bigint;
    sp_mec					bigint;
	rec1      			    record;
    rec_lcc      			RECORD;
	sp_sumatotallcc			bigint;
