    fechahasta            	varchar;
    mes						varchar;
   
    parte1					bigint;
    parte2					bigint;
    parte1_D				bigint;
    parte2_D				bigint;
   
    corte                   bigint;
    sp_total				bigint;
    sp_totrecep				bigint;
   
