			     		      into sp_total
			     		      from mct_checklistinftec a 
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
	    			    
	    			    else
	    			    
	    			    -- Saca totales piezas y totales recepcionados
			     		    select coalesce (sum(cantidad) , 0)
			     		      into sp_total
			     		      from mct_checklistinftecvalido a 
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
	    			    
	    			    end if;
			     		
			     		
			     		select coalesce (sum(cantidad) , 0)
		     		      into sp_totrecep 
		     		      from mct_checklistinftecrecept a
		     		     where a.idordentrabajo = rec1.ot
		     		       and a.codigoqr in (rec1.ot||'FAB_FU', rec1.ot||'FAB_FUPL');
			     	
			     		-- Acumula Totales parte1 y part2 del mes
			     	    --if (rec1.dia > 15 ) then
						if (rec1.siglacorte = sp_siglaanterior) then
	
			     	       if ( corte = 0 and (parte1 > 0 or parte1_D > 0) ) then
			     	       
					     	     item 				:= 0; 
						         idordentrabajo 	:= 0; 
						         nombretipoorden 	:= 0; 
						         producto 			:= 'TOTAL'; 
						         nombrecliente 		:= 0;
						         nombreusuario 		:= 0;
                                 checkdescarte 		:= null;
						         avancefund			:= 0;
						         avancemec			:= 0;
						         montototal 		:= parte1 + parte1_D;
								 fechaentrega	 	:= null;
						         fechaentregaclte	:= null;
                                 observaciondescarte:= null;
								 periodo			:= cast(periodos as bigint);
                                 colordespacho 		:= cast('blue' as varchar);
								 colorotromes 		:= cast('blue' as varchar);
						        
					     		 return next;		

					     	     item 				:= -9; 
						         idordentrabajo 	:= 0; 
						         nombretipoorden 	:= 0; 
						         producto 			:= 'TOTAL DESPACHO'; 
						         nombrecliente 		:= 0;
						         nombreusuario 		:= 0;
                                 checkdescarte 		:= null;
						         avancefund			:= 0;
						         avancemec			:= 0;
						         montototal 		:= parte1 + parte1_D;
								 fechaentrega	 	:= null;
						         fechaentregaclte	:= null;
                                 observaciondescarte:= null;
						         periodo			:= cast(periodos as bigint);
                                 colordespacho 		:= cast('blue' as varchar);
								 colorotromes 		:= cast('blue' as varchar);

					     		 return next;	
					
					     		 corte				:= 1;
					     		 
					     		 if (rec1.idestadoorden = 9) then
					     		    parte2_D := parte2_D + rec1.monto;
					     		 else
					     		    parte2	 := parte2 + rec1.monto;
					     		 end if;

								 sp_siglaanterior	:= rec1.siglacorte;
					     		
					     		 --parte2	 := parte2 + rec1.monto;
			     	       
					       else
			     	       
					     		 if (rec1.idestadoorden = 9) then
					     		    parte2_D := parte2_D + rec1.monto;
					     		 else
					     		    parte2	 := parte2 + rec1.monto;
					     		 end if;
			     	       		
			     	       end if;
	
				     		 
			     	    
				      else

				     		if (rec1.idestadoorden = 9) then
					     		parte1_D := parte1_D + rec1.monto;
					     	else
					     		parte1	 := parte1 + rec1.monto;
					     	end if;

			     	  end if;
			     	   
					  -- calcula avance mecanizado	
			     	  sp_sumatotallcc  := 0;

			     	  FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec1.ot 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								  
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.ot
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;
							     
						-- aca sacamos la cantidad de piezas liberadas de control de calidad
						select count(*)  
					      into sp_liberadascc
					      from mct_movimientoordentrabajo a
					     where a.codigoaccion   = 'L_CC'
					 	   and a.idordentrabajo = rec1.ot; 
							      
							if ( sp_canthr = 0) then
							     sp_avance := 0;
						    else
								 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
				            end if;		
				           
	
				        if ( rec1.idfamilia in (11, 15) ) then
				        
							   -- Fundicion
						       -- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(a.cantidad), 0),
							          a.codigoqr
							     into sp_cantidad_fu,
							          sp_codigoqr_fu
							     from mct_checklistinftec a
							    where a.tipotrabajostd = 'FAB_FU'
							      and a.idordentrabajo = rec1.ot
							      group by a.codigoqr, a.fecharequerida;
							     
							     
				        else
				        
				               -- Fundicion
						       -- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(a.cantidad), 0),
							          a.codigoqr
							     into sp_cantidad_fu,
							          sp_codigoqr_fu
							     from mct_checklistinftecvalido a
							    where a.tipotrabajostd = 'FAB_FU'
							      and a.idordentrabajo = rec1.ot
							      group by a.codigoqr, a.fecharequerida;
							     
				        
				        end if;

							     
					   -- aca sacamos el total de piezas recepcionadas   
					   select coalesce ( sum(cantidad), 0) * 100
					     into sp_recept_fu
					     from mct_checklistinftecrecept
					    where codigoqr = sp_codigoqr_fu; 
	
					   if (sp_cantidad_fu = 0 ) then
		                   sp_cantidad_fu := 1;
		               end if;
		              
					  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
					   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
					  
					   if ( sp_cantidad_fu = 0 ) then
					       sp_avance_fu = 999;
					   end if;
							  
					   if ( rec1.idproducto in (10,11,12,13,14,15,16,17)) then
					     
					     	select nombreproductonepcast 
					     	  into sp_producto
					     	  from mct_productonepcast 
					     	 where idproductonepcast = rec1.idproducto;
					     	  					     
					   else
					     
					     	sp_producto	:= rec1.producto;
					   end if;
							
					   select count(*)
				         into sp_tienedefecto
				         from traking.mct_defectofundicion a
				        where a.idordentrabajo = rec1.ot;

				     
				        item 				:= rec1.item; 
				        idordentrabajo 		:= rec1.ot; 
				        nombretipoorden 	:= rec1.sigla||'_'||rec1.idestadoorden; 
				        producto 			:= sp_producto;
				        nombrecliente 		:= rec1.nombrecorto;
				        nombreusuario 		:= rec1.nombre;
					    checkdescarte 		:= rec1.checkdescarte;
				        avancefund			:= sp_avance_fu;
	
				         --avancemec			:= sp_avance;
				         select coalesce (salav)
			                  into sp_funcav 
			                  from traking.calcularavancemecanizado(rec1.ot);
			 
						 avancemec        := sp_funcav;
						
				         if ( rec1.idfamilia = 11 and rec1.mec = 2) then
				             avancemec		:= 999;
				         end if;
				        
				         montototal 		:= rec1.monto;
						 fechaentrega 		:= rec1.fechaentrega;
				         fechaentregaclte	:= rec1.fechaentregaclte;
                         observaciondescarte:= rec1.observaciondescarte;
                         periodo			:= cast(periodos as bigint);				                
						 
						 if (rec1.idfamilia in (10,15) and rec1.monto = 0) then

							select sum(a.cantidad * a.costo)
                              into montototal
							  from traking.mct_ordentrabajorepuesto a
                             where a.idordentrabajo = rec1.ot;

 						 end if;

						 colordespacho 		:= cast('black' as varchar);
                         if (rec1.idestadoorden = 9 ) then
							colordespacho 		:= cast('lightgreen' as varchar);	
						 end if;

						 colorotromes 		:= cast('black' as varchar);
						 --if (rec1.mesentregaclte <> cast(periodos as bigint) or 
                         --    rec1.mesentregaclteori <> cast(periodos as bigint) ) then
   						
						 raise notice '%', rec1.ot||'-'||rec1.mesentregaclteori||'-'||cast(periodos as bigint); 

						 if (cast(rec1.mesentregaclteori as bigint) > cast(periodos as bigint) ) then
							colorotromes 	:= cast('red' as varchar);	
                         else
							colorotromes 	:= cast('black' as varchar);
						 end if;
  
			     		return next;
		     	
		     		--end if;
			       	       
	     		end loop;
	     		
	     	    item 				:= 0; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				checkdescarte		:= false;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2 + parte2_D;
				fechaentrega	 	:= null;
                fechaentregaclte 	:= null;
				observaciondescarte := null;
                periodo				:= cast(periodos as bigint);
				colordespacho 		:= cast('blue' as varchar);
				colorotromes 		:= cast('blue' as varchar);
		         
				return next;

	     	    item 				:= -9; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				checkdescarte		:= false;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2_D;
				fechaentrega	 	:= null;
                fechaentregaclte 	:= null;
				observaciondescarte := null;
		        periodo				:= cast(periodos as bigint);
				colordespacho 		:= cast('blue' as varchar);
				colorotromes 		:= cast('blue' as varchar);

				return next;			
			
	     	    item 				:= -1; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				checkdescarte		:= false;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1 + parte1_D + parte2 + parte2_D;
				fechaentrega	 	:= null;
                fechaentregaclte 	:= null;
				observaciondescarte := null;
		        periodo				:= cast(periodos as bigint);
				colordespacho 		:= cast('blue' as varchar);
				colorotromes 		:= cast('blue' as varchar);

				return next;	
			
	     	    item 				:= -10; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
                checkdescarte		:= false;				
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1_D + parte2_D;
				fechaentrega	 	:= null;
                fechaentregaclte 	:= null;
				observaciondescarte := null;
		        periodo				:= cast(periodos as bigint);
				colordespacho 		:= cast('blue' as varchar);
				colorotromes 		:= cast('blue' as varchar);

				return next;				
			
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistprogramafacturacionresumen(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 2090 (class 1255 OID 17264)
-- Name: evtlistprogramafacturacionresumenconanno(bigint, bigint, bigint, bigint, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistprogramafacturacionresumenconanno(anno bigint, idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, nombretipoorden character varying, producto character varying, nombrecliente character varying, nombreusuario character varying, checkdescarte boolean, avancefund numeric, avancemec numeric, montototal bigint, fechaentrega character varying, fechaentregaclte character varying, observaciondescarte character varying, periodo bigint, colordespacho character varying, colorotromes character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_funcav				numeric;
   
    sp_fami					bigint;
    sp_mec					bigint;
	rec1      			    record;
    rec_lcc      			RECORD;
	sp_sumatotallcc			bigint;
	sp_liberadascc			bigint;
	sp_canthr				bigint;
    sp_avance				numeric;
   
    sp_cantidad_fu			bigint;
    sp_codigoqr_fu			varchar;
	sp_recept_fu			bigint;
    sp_avance_fu			numeric;
   
    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					bigint;
    parte2					bigint;
    parte1_D				bigint;
    parte2_D				bigint;
   
    corte                   bigint;
    sp_total				bigint;
    sp_totrecep				bigint;
   
    sp_producto				varchar;
   
    sp_tieneregistro		bigint;
   
    sp_tienedefecto			bigint;

    sp_siglaanterior		varchar;

	sp_primeravez			integer;

	sp_montonobba			bigint;
   	     		
begin
		 
	fechadesde			:= '';
    fechahasta			:= '';
    parte1				:= 0;
    parte1_D			:= 0;
   
    parte2				:= 0;
    parte2_D			:= 0;
    corte				:= 0;
    sp_tienedefecto		:= 0;

    sp_primeravez		:= 0;
	sp_siglaanterior	:= '';
    sp_montonobba		:= 0;
   
	if (periodos != '-1') then

		if (anno != -1) then
	
			ano := anno;

		else

			select to_char(now(),'yyyy')
			  into ano;

		end if;


		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '2 month') - interval '1 day')::date, 'yyyy-mm-dd')
		  into fechahasta;
		 
		--select to_char(now() + interval '2 year','yyyy')
		--  into anofin;
		 
		--fechahasta	:= anofin||'-'||mes||'-'||ultimodia;

		raise notice '%', fechadesde||'-'||fechahasta;

		FOR rec1 IN (   
						
		          select ROW_NUMBER() OVER (ORDER BY tabla.siglacorte asc, tabla.fechaentregaclte asc, tabla.ot asc) AS item,
		                 tabla.ot,
					     tabla.idestadoorden,
		                 tabla.mec,
		                 tabla.idfamilia,
                         tabla.siglacorte,
		                 tabla.sigla,
		                 tabla.idproducto,
		                 tabla.producto,
		                 tabla.nombrecorto,
		                 tabla.nombre, 
                         tabla.checkdescarte,
                         to_char(tabla.fechaentrega, 'dd-mm-yyyy') as fechaentrega ,
                         cast(to_char(tabla.fechaentrega, 'mm') as bigint) as mesentregaclteori ,
		                 to_char(tabla.fechaentregaclte, 'dd-mm-yyyy') as fechaentregaclte ,
						 cast(to_char(tabla.fechaentregaclte, 'mm') as bigint) as mesentregaclte ,
		                 cast(to_char(tabla.fechaentregaclte,'dd') as integer) as dia,
		                 tabla.dias,
		                 tabla.avancefund,
		                 tabla.avancemec,
		                 tabla.monto,
                         tabla.observaciondescarte
		            from (
					select a.idordentrabajo as ot,
					       a.idestadoorden,
					       0 as mec,
					       a.idfamilia,					       
						   --d.sigla||'_'||e.sigla as sigla,
                           e.sigla as siglacorte,
                           e.sigla||'_'||d.sigla as sigla,
						   a.idproducto,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   b.nombrecorto ,
						   j.nombre ,
                           k.checkdescarte,
						   --case
						   --		when k.checkdescarte is null then	
						   --			 a.checkdescarte								
                           --     else k.checkdescarte
						   --end as checkdescarte,
                           a.fechaentrega as fechaentrega,
						   a.fechafaceclte as fechaentregaclte,				       
						   cast(date_part('day', fechafaceclte - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(a.montorepfab)                                         as monto,
                           a.observaciondescarte
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
                      left join  mct_programafacturacionresumenfoto k on a.idordentrabajo = k.idordentrabajo and k.periodo = cast(periodos as bigint)
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   and a.idfamilia in (8, 10, 15)
				       --and a.flagfacturacion is true
					   and a.debaja < 1
					   --and a.checklistvalido = true
					   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   and a.fechafaceclte >= '2025-07-01'
 					   --and (a.fechafaceclte >= TO_TIMESTAMP('2025-07-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP('2025-08-30'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 
                  group by a.idordentrabajo ,
					       a.idestadoorden,
                           e.sigla,
					       e.sigla||'_'||d.sigla,
					       a.idproducto,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar),
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar),
						   a.observaciondescarte,
                           k.checkdescarte  
				union 
					select a.idordentrabajo  as ot,
					       a.idestadoorden,
					       k.idesmecanizado as mec,
					       a.idfamilia,
                           e.sigla||'_CON' as siglacorte,
						   e.sigla||'_CON' as sigla,
						   a.idproducto,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       j.nombre as nombre,
                           l.checkdescarte,
                           --case
						   --		when l.checkdescarte is null then	
						   --			 a.checkdescarte								
                           --      else l.checkdescarte
						   --end as checkdescarte,
                           a.fechaentregainicial as fechaentrega,
					       a.fechafaceclte as fechaentregaclte,
					       cast(date_part('day', a.fechafaceclte - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto,
                           a.observaciondescarte
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDC
					  left join  mct_programafacturacionresumenfoto l on a.idordentrabajo = l.idordentrabajo and l.periodo = cast(periodos as bigint)
					 where a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   and a.idfamilia       in (11)
					   --and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   and a.fechafaceclte >= '2025-07-01'
                       --and (a.fechafaceclte >= TO_TIMESTAMP('2025-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP('2025-07-31'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 											   					   
				 group by a.idordentrabajo ,
				            a.idestadoorden,
				            k.idesmecanizado ,
				            a.idfamilia,
				 	        e.sigla||'_CON',
							e.nombrefamilia ,
							a.idproducto,
							c.nombreproducto,
							b.nombrecorto ,
						    j.nombre,
							cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) 	,
							cast(date_part('day', a.fechafaceclte - current_date) as bigint),
						    a.observaciondescarte,
                            l.checkdescarte
				union 
					select a.idordentrabajo  as ot,
					       a.idestadoorden,
					       k.idesmecanizado as mec,
					       a.idfamilia,
                           e.sigla||'_SIN' as siglacorte,
						   e.sigla||'_SIN' as sigla,
						   a.idproducto,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       j.nombre as nombre,
                           l.checkdescarte,
--                           case
--								when l.checkdescarte is null then	
--									 a.checkdescarte								
--                                else l.checkdescarte
--						   end as checkdescarte,
                           a.fechaentregainicial as fechaentrega,
					       a.fechafaceclte as fechaentregaclte,
					       cast(date_part('day', a.fechaentrega - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto,
                           a.observaciondescarte
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDS
					  left join  mct_programafacturacionresumenfoto l on a.idordentrabajo = l.idordentrabajo and l.periodo = cast(periodos as bigint)
					 where a.idordentrabajo >= 30000
					   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   and a.idfamilia       in (11)
					   --and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   and a.fechafaceclte >= '2025-07-01'
                       --and (a.fechaentrega >= TO_TIMESTAMP('2025-06-01'||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP('2025-07-31'||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   
				   group by a.idordentrabajo ,
				            a.idestadoorden,
				            a.idfamilia,
				            k.idesmecanizado ,
				 	        e.sigla||'_SIN',
							e.nombrefamilia ,
							a.idproducto,
							c.nombreproducto,
							b.nombrecorto ,
							j.nombre,
							cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	,
							cast(date_part('day', a.fechaentrega - current_date) as bigint),
						    a.observaciondescarte	,
							l.checkdescarte							
						 ) as tabla
					order by tabla.siglacorte asc,tabla.fechaentregaclte asc, tabla.ot asc
						   						   
					)
	     		loop 

					 if (sp_primeravez = 0) then

						sp_siglaanterior	:= rec1.siglacorte;
						sp_primeravez		:= 1;

                     end if;
		     		 sp_tieneregistro	:= 0;
		     	
		     	     if ( rec1.idfamilia in (11, 15) ) then
		     	    
		     	        select count(*) 
		     	          into sp_tieneregistro
		     		      from mct_checklistinftec a
		     		     where a.idordentrabajo = rec1.ot
		     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
		     	    
		     	     else
		     	    
						select count(*) 
		     	          into sp_tieneregistro
		     		      from mct_checklistinftecvalido a
		     		     where a.idordentrabajo = rec1.ot
		     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');	     	    
		     	    
		     	     end if;
		     		       
		     	     --if ( sp_tieneregistro > 0) then

			     		sp_total	:= 0;
	    				sp_totrecep	:= 0;
	
	    			    if ( rec1.idfamilia in (11, 15) ) then
	    			    
	    			    -- Saca totales piezas y totales recepcionados
			     		    select coalesce (sum(cantidad) , 0)
			     		      into sp_total
			     		      from mct_checklistinftec a 
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
	    			    
	    			    else
	    			    
	    			    -- Saca totales piezas y totales recepcionados
			     		    select coalesce (sum(cantidad) , 0)
			     		      into sp_total
			     		      from mct_checklistinftecvalido a 
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
	    			    
	    			    end if;
			     		
			     		
			     		select coalesce (sum(cantidad) , 0)
		     		      into sp_totrecep 
		     		      from mct_checklistinftecrecept a
		     		     where a.idordentrabajo = rec1.ot
		     		       and a.codigoqr in (rec1.ot||'FAB_FU', rec1.ot||'FAB_FUPL');
			     	
			     		-- Acumula Totales parte1 y part2 del mes
			     	    --if (rec1.dia > 15 ) then
						if (rec1.siglacorte = sp_siglaanterior) then
	
			     	       if ( corte = 0 and (parte1 > 0 or parte1_D > 0) ) then
			     	       
					     	     item 				:= 0; 
						         idordentrabajo 	:= 0; 
						         nombretipoorden 	:= 0; 
						         producto 			:= 'TOTAL'; 
						         nombrecliente 		:= 0;
						         nombreusuario 		:= 0;
                                 checkdescarte 		:= null;
						         avancefund			:= 0;
						         avancemec			:= 0;
						         montototal 		:= parte1 + parte1_D;
								 fechaentrega	 	:= null;
						         fechaentregaclte	:= null;
                                 observaciondescarte:= null;
								 periodo			:= cast(periodos as bigint);
                                 colordespacho 		:= cast('blue' as varchar);
								 colorotromes 		:= cast('blue' as varchar);
						        
					     		 return next;		

					     	     item 				:= -9; 
						         idordentrabajo 	:= 0; 
						         nombretipoorden 	:= 0; 
						         producto 			:= 'TOTAL DESPACHO'; 
						         nombrecliente 		:= 0;
						         nombreusuario 		:= 0;
                                 checkdescarte 		:= null;
						         avancefund			:= 0;
						         avancemec			:= 0;
						         montototal 		:= parte1 + parte1_D;
								 fechaentrega	 	:= null;
						         fechaentregaclte	:= null;
                                 observaciondescarte:= null;
						         periodo			:= cast(periodos as bigint);
                                 colordespacho 		:= cast('blue' as varchar);
								 colorotromes 		:= cast('blue' as varchar);

					     		 return next;	
					
					     		 corte				:= 1;
					     		 
					     		 if (rec1.idestadoorden = 9) then
					     		    parte2_D := parte2_D + rec1.monto;
					     		 else
					     		    parte2	 := parte2 + rec1.monto;
					     		 end if;

								 sp_siglaanterior	:= rec1.siglacorte;
					     		
					     		 --parte2	 := parte2 + rec1.monto;
			     	       
					       else
			     	       
					     		 if (rec1.idestadoorden = 9) then
					     		    parte2_D := parte2_D + rec1.monto;
					     		 else
					     		    parte2	 := parte2 + rec1.monto;
					     		 end if;
			     	       		
			     	       end if;
	
				     		 
			     	    
				      else

				     		if (rec1.idestadoorden = 9) then
					     		parte1_D := parte1_D + rec1.monto;
					     	else
					     		parte1	 := parte1 + rec1.monto;
					     	end if;

			     	  end if;
			     	   
					  -- calcula avance mecanizado	
			     	  sp_sumatotallcc  := 0;

			     	  FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec1.ot 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								  
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.ot
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;
							     
						-- aca sacamos la cantidad de piezas liberadas de control de calidad
						select count(*)  
					      into sp_liberadascc
					      from mct_movimientoordentrabajo a
					     where a.codigoaccion   = 'L_CC'
					 	   and a.idordentrabajo = rec1.ot; 
							      
							if ( sp_canthr = 0) then
							     sp_avance := 0;
						    else
								 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
				            end if;		
				           
	
				        if ( rec1.idfamilia in (11, 15) ) then
				        
							   -- Fundicion
						       -- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(a.cantidad), 0),
							          a.codigoqr
							     into sp_cantidad_fu,
							          sp_codigoqr_fu
							     from mct_checklistinftec a
							    where a.tipotrabajostd = 'FAB_FU'
							      and a.idordentrabajo = rec1.ot
							      group by a.codigoqr, a.fecharequerida;
							     
							     
				        else
				        
				               -- Fundicion
						       -- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(a.cantidad), 0),
							          a.codigoqr
							     into sp_cantidad_fu,
							          sp_codigoqr_fu
							     from mct_checklistinftecvalido a
							    where a.tipotrabajostd = 'FAB_FU'
							      and a.idordentrabajo = rec1.ot
							      group by a.codigoqr, a.fecharequerida;
							     
				        
				        end if;

							     
					   -- aca sacamos el total de piezas recepcionadas   
					   select coalesce ( sum(cantidad), 0) * 100
					     into sp_recept_fu
					     from mct_checklistinftecrecept
					    where codigoqr = sp_codigoqr_fu; 
	
					   if (sp_cantidad_fu = 0 ) then
		                   sp_cantidad_fu := 1;
		               end if;
		              
					  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
					   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
					  
					   if ( sp_cantidad_fu = 0 ) then
					       sp_avance_fu = 999;
					   end if;
							  
					   if ( rec1.idproducto in (10,11,12,13,14,15,16,17) and rec1.idfamilia = 11 ) then
					     
					     	select nombreproductonepcast 
					     	  into sp_producto
					     	  from mct_productonepcast 
					     	 where idproductonepcast = rec1.idproducto;
					     	  					     
					   else
					     
					     	sp_producto	:= rec1.producto;
					   end if;
							
					   select count(*)
				         into sp_tienedefecto
				         from traking.mct_defectofundicion a
				        where a.idordentrabajo = rec1.ot;

				     
				        item 				:= rec1.item; 
				        idordentrabajo 		:= rec1.ot; 
				        nombretipoorden 	:= rec1.sigla||'_'||rec1.idestadoorden; 
				        producto 			:= sp_producto;
				        nombrecliente 		:= rec1.nombrecorto;
				        nombreusuario 		:= rec1.nombre;
					    checkdescarte 		:= rec1.checkdescarte;
				        avancefund			:= sp_avance_fu;
	
				         --avancemec			:= sp_avance;
				         select coalesce (salav)
			                  into sp_funcav 
			                  from traking.calcularavancemecanizado(rec1.ot);
			 
						 avancemec        := sp_funcav;
						
				         if ( rec1.idfamilia = 11 and rec1.mec = 2) then
				             avancemec		:= 999;
				         end if;
				        
				         montototal 		:= rec1.monto;
						 fechaentrega 		:= rec1.fechaentrega;
				         fechaentregaclte	:= rec1.fechaentregaclte;
                         observaciondescarte:= rec1.observaciondescarte;
                         periodo			:= cast(periodos as bigint);				                
						 
						 if (rec1.idfamilia in (10,15) and rec1.monto = 0) then

							select sum(a.cantidad * a.costo)
                              into montototal
							  from traking.mct_ordentrabajorepuesto a
                             where a.idordentrabajo = rec1.ot;

 						 end if;

						 colordespacho 		:= cast('black' as varchar);
                         if (rec1.idestadoorden = 9 ) then
							colordespacho 		:= cast('lightgreen' as varchar);	
						 end if;

						 colorotromes 		:= cast('black' as varchar);
						 --if (rec1.mesentregaclte <> cast(periodos as bigint) or 
                         --    rec1.mesentregaclteori <> cast(periodos as bigint) ) then
   						
						 raise notice '%', rec1.ot||'-'||rec1.mesentregaclteori||'-'||cast(periodos as bigint); 

						 if (cast(rec1.mesentregaclteori as bigint) > cast(periodos as bigint) ) then
							colorotromes 	:= cast('red' as varchar);	
                         else
							colorotromes 	:= cast('black' as varchar);
						 end if;
  
			     		return next;
		     	
		     		--end if;
			       	       
	     		end loop;
	     		
	     	    item 				:= 0; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				checkdescarte		:= false;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2 + parte2_D;
				fechaentrega	 	:= null;
                fechaentregaclte 	:= null;
				observaciondescarte := null;
                periodo				:= cast(periodos as bigint);
				colordespacho 		:= cast('blue' as varchar);
				colorotromes 		:= cast('blue' as varchar);
		         
				return next;

	     	    item 				:= -9; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				checkdescarte		:= false;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2_D;
				fechaentrega	 	:= null;
                fechaentregaclte 	:= null;
				observaciondescarte := null;
		        periodo				:= cast(periodos as bigint);
				colordespacho 		:= cast('blue' as varchar);
				colorotromes 		:= cast('blue' as varchar);

				return next;			
			
	     	    item 				:= -1; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				checkdescarte		:= false;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1 + parte1_D + parte2 + parte2_D;
				fechaentrega	 	:= null;
                fechaentregaclte 	:= null;
				observaciondescarte := null;
		        periodo				:= cast(periodos as bigint);
				colordespacho 		:= cast('blue' as varchar);
				colorotromes 		:= cast('blue' as varchar);

				return next;	
			
	     	    item 				:= -10; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
                checkdescarte		:= false;				
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1_D + parte2_D;
				fechaentrega	 	:= null;
                fechaentregaclte 	:= null;
				observaciondescarte := null;
		        periodo				:= cast(periodos as bigint);
				colordespacho 		:= cast('blue' as varchar);
				colorotromes 		:= cast('blue' as varchar);

				return next;				
			
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistprogramafacturacionresumenconanno(anno bigint, idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1479 (class 1255 OID 17266)
-- Name: evtlistprogramafundicionanalisis(bigint, bigint, bigint, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistprogramafundicionanalisis(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) RETURNS TABLE(item bigint, nombretipoorden character varying, montototal bigint, porcentaje numeric)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;
	rec1      			    record;
    rec_lcc      			RECORD;
	sp_sumatotallcc			integer;
	sp_liberadascc			integer;
	sp_canthr				integer;
    sp_avance				numeric;
   
    sp_cantidad_fu			integer;
    sp_codigoqr_fu			varchar;
	sp_recept_fu			integer;
    sp_avance_fu			numeric;
   
    ultimodia				varchar;
    ano						varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					integer;
    parte2					integer;
    corte                   integer;
   	     		
begin
		 
	fechadesde	:= '';
    fechahasta	:= '';
    parte1		:= 0;
    parte2		:= 0;
    corte		:= 0;
   
	if (periodos != '-1') then

		select to_char(now(),'yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		fechahasta	:= ano||'-'||mes||'-'||ultimodia;
		
		FOR rec1 IN (   
						
		          select ROW_NUMBER() OVER (ORDER BY tabla.sigla asc) AS item,
		                 tabla.sigla,
		                 tabla.monto
		            from (
					select d.sigla||'_'||e.sigla as sigla,
						   sum(a.montorepfab)    as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia in (idfamilysB, idfamilysR)
				       and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.checklistvalido = true
					   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by  d.sigla||'_'||e.sigla
		         
				union 
					select e.sigla||'_CON' as sigla,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
