					   group by e.sigla||'_SIN'						
						 ) as tabla
						   						   
					)
	     		loop 
						  
			         item 				:= rec1.item; 
			         nombretipoorden 	:= rec1.sigla; 
			         montototal 		:= rec1.monto;
			        
			         parte1				:= parte1 + rec1.monto;
         
		     		return next;
			       	       
	     		end loop;
	     	
	     	    item 				:= 0; 
			    nombretipoorden 	:= ''; 
				montototal 			:= parte1;
			    porcentaje			:= 100;
		         
				return next;	
			           
	else
	
		FOR rec1 IN (   
						
		          select ROW_NUMBER() OVER (ORDER BY tabla.sigla asc) AS item,
		                 tabla.sigla,
		                 tabla.monto
		            from (
					select d.sigla||'_'||e.sigla as sigla,
						   sum(a.montorepfab)                                         as monto
					  from mct_ordentrabajo a
