		     		return next;
			       	       
	     		end loop;	
	     	
	     	    item 				:= 0; 
			    nombretipoorden 	:= ''; 
				montototal 			:= parte1;
			    porcentaje			:= 100;
		         
				return next;	     	
			
	end if;
	 
END;
$$;


