					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDS
					 where a.idordentrabajo >= 30000
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   --and a.idfamilia       in (11, idfamilysO)
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechaentrega >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
