--					   and a.idboleano = 1
--					   and a.idareaclasificacion in (0,1,2,3,4,5);
						     
					-- aca sacamos la cantidad de piezas liberadas de control de calidad
					select count(*)  
				      into sp_liberadascc
				      from mct_movimientoordentrabajo a
				     where a.codigoaccion   = 'L_CC'
				 	   and a.idordentrabajo = rec1.ot; 
						      
						if ( sp_canthr = 0) then
						     sp_avance := 0;
					    else
							 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			            end if;		
			           
			           
					-- Fundicion
					-- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(a.cantidad), 0),
						          a.codigoqr
						     into sp_cantidad_fu,
						          sp_codigoqr_fu
						     from mct_checklistinftec a
						    where a.tipotrabajostd = 'FAB_FU'
						      and a.idordentrabajo = rec1.ot
						      group by a.codigoqr, a.fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0) * 100
						     into sp_recept_fu
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_fu; 
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;

						  
			         item 				:= rec1.item; 
			         idordentrabajo 	:= rec1.ot; 
			         nombretipoorden 	:= rec1.sigla; 
			         producto 			:= rec1.producto; 
			         nombrecliente 		:= rec1.nombrecorto;
			         nombreusuario 		:= rec1.nombre;
			         fechaentregaclte 	:= rec1.fechaentregaclte;
			         diascliente 		:= rec1.dias;
			         avancefund			:= sp_avance_fu;

			         avancemec			:= sp_avance;
			         if ( rec1.idfamilia = 11 and rec1.mec = 2) then
			             avancemec		:= 999;
			         end if;
			        
			         montototal 		:= rec1.monto;
         
		     		return next;
			       	       
	     		end loop;	
	     	
	     	    item 				:= 0; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2;
		         
				return next;	     	

				item 				:= -1;  
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1 + parte2;
		         
				return next;
			
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistprogramafundiciondetalle(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1673 (class 1255 OID 17270)
-- Name: evtlistprogramafundiciondetalle_prueba(bigint, bigint, bigint, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistprogramafundiciondetalle_prueba(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, nombretipoorden character varying, producto character varying, nombrecliente character varying, nombreusuario character varying, fechaentregaclte character varying, diascliente bigint, avancefund numeric, avancemec numeric, montototal bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;
	rec1      			    record;
    rec_lcc      			RECORD;
	sp_sumatotallcc			integer;
	sp_liberadascc			integer;
	sp_canthr				integer;
    sp_avance				numeric;
   
    sp_cantidad_fu			integer;
    sp_codigoqr_fu			varchar;
	sp_recept_fu			integer;
    sp_avance_fu			numeric;
   
    ultimodia				varchar;
    ano						varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					integer;
    parte2					integer;
    corte                   integer;
   	     		
begin
		 
	fechadesde	:= '';
    fechahasta	:= '';
    parte1		:= 0;
    parte2		:= 0;
    corte		:= 0;
   
	if (periodos != '-1') then

		select to_char(now(),'yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		fechahasta	:= ano||'-'||mes||'-'||ultimodia;
		
		FOR rec1 IN (   
						
		          select ROW_NUMBER() OVER (ORDER BY tabla.fechaentregaclte asc, tabla.ot asc) AS item,
		                 tabla.ot,
		                 tabla.mec,
		                 tabla.idfamilia,
		                 tabla.sigla,
		                 tabla.producto,
		                 tabla.nombrecorto,
		                 tabla.nombre, 
		                 to_char(tabla.fechaentregaclte, 'dd-mm-yyyy') as fechaentregaclte ,
		                 cast(to_char(tabla.fechaentregaclte,'dd') as integer) as dia,
		                 tabla.dias,
		                 tabla.avancefund,
		                 tabla.avancemec,
		                 tabla.monto
		            from (
					select a.idordentrabajo as ot,
					       0 as mec,
					       a.idfamilia,					       
						   d.sigla||'_'||e.sigla as sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   b.nombrecorto ,
						   j.nombre ,
						   a.fechafaceclte as fechaentregaclte,				       
						   cast(date_part('day', fechafaceclte - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(a.montorepfab)                                         as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   --and a.idfamilia in (idfamilysB, idfamilysR)
					   and a.idfamilia in (idfamilysB)
				       and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.checklistvalido = true
					   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by a.idordentrabajo ,
					       d.sigla||'_'||e.sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar),
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar)
				union 
					select a.idordentrabajo as ot,
					       0 as mec,
					       a.idfamilia,					       
						   d.sigla||'_'||e.sigla as sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   b.nombrecorto ,
						   j.nombre ,
						   a.fechafaceclte as fechaentregaclte,				       
						   cast(date_part('day', fechafaceclte - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(a.montorepfab)                                         as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   --and a.idfamilia in (idfamilysB, idfamilysR)
				       and a.idfamilia in (idfamilysR)
				       and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.checklistvalido = true
					   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by a.idordentrabajo ,
					       d.sigla||'_'||e.sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar),
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar)				
				union 
					select a.idordentrabajo  as ot,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_CON' as sigla,
						   k.nombrecomponentetemp as producto,
					       b.nombrecorto ,
					       'SEBASTIAN CUADRA' as nombre,
					       a.fechafundicion2 as fechaentregaclte,
					       cast(date_part('day', a.fechafundicion2 - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDC
					 where a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechafundicion2 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            k.idesmecanizado ,
					            a.idfamilia,
					 	        e.sigla||'_CON',
								e.nombrefamilia ,
								k.nombrecomponentetemp,
								b.nombrecorto ,
								cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechafundicion2 - current_date) as bigint)
				union 
					select a.idordentrabajo  as ot,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_SIN' as sigla,
						   k.nombrecomponentetemp as producto,
					       b.nombrecorto ,
					       j.nombre as nombre,
					       a.fechaentrega as fechaentregaclte,
					       cast(date_part('day', a.fechaentrega - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDS
					 where a.idordentrabajo >= 30000
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   --and a.idfamilia       in (11, idfamilysO)
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechaentrega >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            a.idfamilia,
					            k.idesmecanizado ,
					 	        e.sigla||'_SIN',
								e.nombrefamilia ,
								k.nombrecomponentetemp,
								b.nombrecorto ,
								j.nombre,
								cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechaentrega - current_date) as bigint)								
						 ) as tabla
						   						   
					)
	     		loop 
		     		

		     		-- Acumula Totales parte1 y part2 del mes
		     		
		     	
		     	    if (rec1.dia > 15 ) then

		     	       if ( corte = 0 and parte1 > 0) then
		     	       
				     	     item 				:= 0; 
					         idordentrabajo 	:= 0; 
					         nombretipoorden 	:= 0; 
					         producto 			:= 'TOTAL'; 
					         nombrecliente 		:= 0;
					         nombreusuario 		:= 0;
					         fechaentregaclte 	:= 0;
					         diascliente 		:= 0;
					         avancefund			:= 0;
					         avancemec			:= 0;
					         montototal 		:= parte1;
		         
					         corte				:= 1;
					        
				     		 return next;		
				     		
				     		 parte2	 := parte2 + rec1.monto;
		     	       
				       else
		     	       
		     	       		 parte2	 := parte2 + rec1.monto;
		     	       		
		     	       end if;

			     		 
		     	    
			     	else
			     		parte1	 := parte1 + rec1.monto;
		     	    end if;
		     	   
				    -- calcula avance mecanizado	
		     	    sp_sumatotallcc  := 0;

			     	 FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec1.ot 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
--				       			   select coalesce (sum(cantidad),0)
--								     into sp_liberadascc
--								     from mct_hojarutatemp
--								    where idhojarutatemp = rec_lcc.idhojarutatemp
--								      and idboleano = 1
--					                  and idareaclasificacion in (0,1,2,3,4,5);
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  		
				  	   -- aca sacamos la cantidad de piezas totales
--					   select coalesce ( sum(cantidad), 0)
--					     into sp_canthr
--					     from mct_hojarutatemp mh
--					    where idordentrabajo = rec_ord.idordentrabajo
--					      and idboleano = 1
--					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.ot
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;
					  
--				    FOR rec_lcc IN (   
--								select distinct b.idhojarutatemp
--								  from mct_movimientoordentrabajo a,
--								       mct_hojaruta b
--								 where a.codigoaccion   = 'L_CC'
--							       and a.idordentrabajo = rec1.ot
--							       and a.idhojaruta     = b.idhojaruta 
--								)
--					     loop 	
--	
--					     	sp_liberadascc	:= 0;
--									   
--					     	select coalesce (sum(cantidad),0)
--					  	      into sp_liberadascc
--				 		      from mct_hojarutatemp
--						     where idhojarutatemp = rec_lcc.idhojarutatemp
--						       and idboleano = 1
--				               and idareaclasificacion in (0,1,2,3,4,5);
--							     
--							sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
--							           
--					END LOOP;
--					  		
--					sp_sumatotallcc := sp_sumatotallcc * 100;
--					-- hasta aca el nuevo calculo
--			   			  
--					-- aca sacamos la cantidad de piezas totales
--					select coalesce ( sum(a.cantidad), 0)
--					  into sp_canthr
--					  from mct_hojarutatemp a
--					 where a.idordentrabajo = rec1.ot
--					   and a.idboleano = 1
--					   and a.idareaclasificacion in (0,1,2,3,4,5);
						     
					-- aca sacamos la cantidad de piezas liberadas de control de calidad
					select count(*)  
				      into sp_liberadascc
				      from mct_movimientoordentrabajo a
				     where a.codigoaccion   = 'L_CC'
				 	   and a.idordentrabajo = rec1.ot; 
						      
						if ( sp_canthr = 0) then
						     sp_avance := 0;
					    else
							 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			            end if;		
			           

					-- Fundicion
					-- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(a.cantidad), 0),
						          a.codigoqr
						     into sp_cantidad_fu,
						          sp_codigoqr_fu
						     from mct_checklistinftec a
						    where a.tipotrabajostd = 'FAB_FU'
						      and a.idordentrabajo = rec1.ot
						      group by a.codigoqr, a.fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0) * 100
						     into sp_recept_fu
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_fu; 
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;

						  
			         item 				:= rec1.item; 
			         idordentrabajo 	:= rec1.ot; 
			         nombretipoorden 	:= rec1.sigla; 
			         producto 			:= rec1.producto; 
			         nombrecliente 		:= rec1.nombrecorto;
			         nombreusuario 		:= rec1.nombre;
			         fechaentregaclte 	:= rec1.fechaentregaclte;
			         diascliente 		:= rec1.dias;
			         --avancefund 		:= rec1.avancefund;
			         avancefund			:= sp_avance_fu;
			         --avancemec 			:= rec1.avancemec;

			         avancemec			:= sp_avance;
			         if ( rec1.idfamilia = 11 and rec1.mec = 2) then
			             avancemec		:= 999;
			         end if;
			        
			         montototal 		:= rec1.monto;
         
		     		return next;
			       	       
	     		end loop;
	     	
	     	    item 				:= 0; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2;
		         
				return next;
			
	     	    item 				:= -1; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1 + parte2;
		         
				return next;			
			           
	else
	
		FOR rec1 IN (   

		          select ROW_NUMBER() OVER (ORDER BY tabla.fechaentregaclte asc, tabla.ot asc) AS item,
		                 tabla.ot,
		                 tabla.mec,
		                 tabla.idfamilia,
		                 tabla.sigla,
		                 tabla.producto,
		                 tabla.nombrecorto,
		                 tabla.nombre, 
		                 to_char(tabla.fechaentregaclte, 'dd-mm-yyyy') as fechaentregaclte ,
		                 cast(to_char(tabla.fechaentregaclte,'dd') as integer) as dia,
		                 tabla.dias,
		                 tabla.avancefund,
		                 tabla.avancemec,
		                 tabla.monto
		            from (
					select a.idordentrabajo as ot,
					       0 as mec,
					       a.idfamilia,					       
						   d.sigla||'_'||e.sigla as sigla,
						   k.nombrecomponentetemp as producto,
						   b.nombrecorto ,
						   j.nombre ,
						   a.fechaentrega as fechaentregaclte,				       
						   cast(date_part('day', a.fechaentrega - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(k.costo  * k.cantidad)                             as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					  left join  mct_ordentrabajorepuesto k  on a.idordentrabajo = k.idordentrabajo  
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   --and a.idfamilia in (idfamilysB, idfamilysR)
				       and a.idfamilia in (idfamilysR)
				       and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.checklistvalido = true
					   and (a.fechaentrega >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by a.idordentrabajo ,
					       d.sigla||'_'||e.sigla,
						   k.nombrecomponentetemp ,
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar)	
				union		   
					select a.idordentrabajo as ot,
					       0 as mec,
					       a.idfamilia,					       
						   d.sigla||'_'||e.sigla as sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   b.nombrecorto ,
						   j.nombre ,
						   a.fechafaceclte as fechaentregaclte,				       
						   cast(date_part('day', fechafaceclte - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(a.montorepfab)                                         as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   --and a.idfamilia in (idfamilysB, idfamilysR)
				       and a.idfamilia in (idfamilysB)
				       and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.checklistvalido = true
					   --and (a.fechafaceclte >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by a.idordentrabajo ,
					       d.sigla||'_'||e.sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar),
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar)				         
				union 
					select a.idordentrabajo  as ot,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_CON' as sigla,
						   --c.nombreproducto  as producto,
						   k.nombrecomponentetemp as producto,
					       b.nombrecorto ,
					       'SEBASTIAN CUADRA' as nombre,
					       a.fechafundicion2 as fechaentregaclte,
					       cast(date_part('day', a.fechafundicion2 - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDC
					 where a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechafundicion2 >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            k.idesmecanizado ,
					            a.idfamilia,
					 	        e.sigla||'_CON',
								e.nombrefamilia ,
								--c.nombreproducto  as producto,
						        k.nombrecomponentetemp ,
								b.nombrecorto ,
								cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechafundicion2 - current_date) as bigint)
				union 
					select a.idordentrabajo  as ot,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_SIN' as sigla,
						   --c.nombreproducto  as producto,
						   k.nombrecomponentetemp as producto,
					       b.nombrecorto ,
					       j.nombre as nombre,
					       a.fechaentrega as fechaentregaclte,
					       cast(date_part('day', a.fechaentrega - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDS
					 where a.idordentrabajo >= 30000
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   --and a.idfamilia       in (11, idfamilysO)
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechaentrega >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            a.idfamilia,
					            k.idesmecanizado ,
					 	        e.sigla||'_SIN',
								e.nombrefamilia ,
								--c.nombreproducto,
								k.nombrecomponentetemp,
								b.nombrecorto ,
								j.nombre,
								cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechaentrega - current_date) as bigint)								
						 ) as tabla
						   						   
					)
	     		loop 
		     		
		     	    if (rec1.dia > 15 ) then

		     	       if ( corte = 0 and parte1 > 0 ) then
		     	       
				     	     item 				:= 0; 
					         idordentrabajo 	:= 0; 
					         nombretipoorden 	:= 0; 
					         producto 			:= 'TOTAL'; 
					         nombrecliente 		:= 0;
					         nombreusuario 		:= 0;
					         fechaentregaclte 	:= 0;
					         diascliente 		:= 0;
					         avancefund			:= 0;
					         avancemec			:= 0;
					         montototal 		:= parte1;
		         
					         corte				:= 1;
					        
				     		 return next;	
				     		
				     		 parte2	 := parte2 + rec1.monto;
		     	       
				       else
		     	       
		     	       		 parte2	 := parte2 + rec1.monto;
		     	       		
		     	       end if;

			     		 
		     	    
			     	else
			     		parte1	 := parte1 + rec1.monto;
		     	    end if;
		     	   
				    -- calcula avance mecanizado	
		     	    sp_sumatotallcc  := 0;

			     	 FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec1.ot 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
--				       			   select coalesce (sum(cantidad),0)
--								     into sp_liberadascc
--								     from mct_hojarutatemp
--								    where idhojarutatemp = rec_lcc.idhojarutatemp
--								      and idboleano = 1
--					                  and idareaclasificacion in (0,1,2,3,4,5);
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  		
				  	   -- aca sacamos la cantidad de piezas totales
--					   select coalesce ( sum(cantidad), 0)
--					     into sp_canthr
--					     from mct_hojarutatemp mh
--					    where idordentrabajo = rec_ord.idordentrabajo
--					      and idboleano = 1
--					      and idareaclasificacion in (0,1,2,3,4,5);
					     
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.ot
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;
					  
--				    FOR rec_lcc IN (   
--								select distinct b.idhojarutatemp
--								  from mct_movimientoordentrabajo a,
--								       mct_hojaruta b
--								 where a.codigoaccion   = 'L_CC'
--							       and a.idordentrabajo = rec1.ot
--							       and a.idhojaruta     = b.idhojaruta 
--								)
--					     loop 	
--	
--					     	sp_liberadascc	:= 0;
--									   
--					     	select coalesce (sum(cantidad),0)
--					  	      into sp_liberadascc
--				 		      from mct_hojarutatemp
--						     where idhojarutatemp = rec_lcc.idhojarutatemp
--						       and idboleano = 1
--				               and idareaclasificacion in (0,1,2,3,4,5);
--							     
--							sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
--							           
--					END LOOP;
--					  		
--					sp_sumatotallcc := sp_sumatotallcc * 100;
--					-- hasta aca el nuevo calculo
--			   			  
--					-- aca sacamos la cantidad de piezas totales
--					select coalesce ( sum(a.cantidad), 0)
--					  into sp_canthr
--					  from mct_hojarutatemp a
--					 where a.idordentrabajo = rec1.ot
--					   and a.idboleano = 1
--					   and a.idareaclasificacion in (0,1,2,3,4,5);
						     
					-- aca sacamos la cantidad de piezas liberadas de control de calidad
					select count(*)  
				      into sp_liberadascc
				      from mct_movimientoordentrabajo a
				     where a.codigoaccion   = 'L_CC'
				 	   and a.idordentrabajo = rec1.ot; 
						      
						if ( sp_canthr = 0) then
						     sp_avance := 0;
					    else
							 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			            end if;		
			           
			           
					-- Fundicion
					-- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(a.cantidad), 0),
						          a.codigoqr
						     into sp_cantidad_fu,
						          sp_codigoqr_fu
						     from mct_checklistinftec a
						    where a.tipotrabajostd = 'FAB_FU'
						      and a.idordentrabajo = rec1.ot
						      group by a.codigoqr, a.fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0) * 100
						     into sp_recept_fu
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_fu; 
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;

						  
			         item 				:= rec1.item; 
			         idordentrabajo 	:= rec1.ot; 
			         nombretipoorden 	:= rec1.sigla; 
			         producto 			:= rec1.producto; 
			         nombrecliente 		:= rec1.nombrecorto;
			         nombreusuario 		:= rec1.nombre;
			         fechaentregaclte 	:= rec1.fechaentregaclte;
			         diascliente 		:= rec1.dias;
			         avancefund			:= sp_avance_fu;

			         avancemec			:= sp_avance;
			         if ( rec1.idfamilia = 11 and rec1.mec = 2) then
			             avancemec		:= 999;
			         end if;
			        
			         montototal 		:= rec1.monto;
         
		     		return next;
			       	       
	     		end loop;	
	     	
	     	    item 				:= 0; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2;
		         
				return next;	     	

				item 				:= -1;  
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1 + parte2;
		         
				return next;
			
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistprogramafundiciondetalle_prueba(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1780 (class 1255 OID 17272)
-- Name: evtlistprogramafundicionsdetallecalendario(bigint, bigint, bigint, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistprogramafundicionsdetallecalendario(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, siglafamilia character varying, producto character varying, nombrecliente character varying, responsablefundicion character varying, fechafundicion timestamp without time zone, nombreparte character varying, plano character varying, diasfund bigint, diascliente bigint, diastm bigint, faltantes bigint, nombretipoorden character varying, nombrefamilia character varying, fechaentregatm character varying, fechaentregaclte character varying, idmodalidadcreacion bigint, nombreusuario character varying, flagfacturacion boolean, idchecklistinftec bigint, cantidadtotal bigint, recepcionada bigint, tienedefecto bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					integer;
    parte2					integer;
    corte                   integer;
    sp_nombreproducto		varchar;
   
   	rec_modelo      		RECORD;
   
    sp_tienedefecto			bigint;
   
begin

	fechadesde			:= '';
    fechahasta			:= '';
    parte1				:= 0;
    parte2				:= 0;
    corte				:= 0;
    sp_tienedefecto		:= 0;
   
	if (periodos != '-1') then

		select to_char(now() - interval '2 year','yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		select to_char(now() + interval '2 year','yyyy')
		  into anofin;
		 
		fechahasta	:= anofin||'-'||mes||'-'||ultimodia;


	      FOR rec_modelo IN (         
	      
	        select ROW_NUMBER() OVER (ORDER BY tabla.fechafundicion asc, tabla.idordentrabajo) as item,
	               tabla.idordentrabajo,
	               tabla.siglafamilia,
	               tabla.idproducto,
	               tabla.producto,
	               tabla.nombrecliente,
	               tabla.responsablefundicion,
	               tabla.fechafundicion,
	               tabla.nombreparte,
	               tabla.plano,
	               tabla.diasfund,
	               tabla.diascliente,
	               tabla.diastm,
	               tabla.faltantes,
	               tabla.nombretipoorden,
	               tabla.nombrefamilia,
	               tabla.fechaentregatm,
	               tabla.fechaentregaclte,
	               tabla.idmodalidadcreacion,
	               tabla.nombreusuario,
	               tabla.flagfacturacion,
	               tabla.idchecklistinftec,
	               tabla.lineadiseno,
	               tabla.adelanta,
	               tabla.cantidadtotal,
	               tabla.recepcionada
	        from (			
				select --ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc, a.idordentrabajo) AS item,
				       a.idordentrabajo 						as idordentrabajo,
				       cast(d.sigla||'_'||e.sigla as varchar) 	as siglafamilia,
				       a.idproducto 		as idproducto,
				       cast(case 
						  when a.idfamilia = 11 then c.nombreproducto
					      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
					   end as varchar) 	as producto,	
					   b.nombrecorto 	as nombrecliente,
					   n.nombre 		as responsablefundicion,			   
					   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) as fechafundicion,
					   a.fechafaceclte - interval '15 days' as fechafundicion,
					   k.nombreparte 	as nombreparte,
			       	   k.plano 			as plano,
					   --cast(date_part('day', (a.fechafaceclte - interval '15 days') - now() ) as bigint) 		as diasfund,
			       	   cast(date_part('day', (a.fechafaceclte - interval '15 days') - coalesce (max(l.fechacreacion), current_date) ) as bigint) 		as diasfund,
					   cast(date_part('day', a.fechafaceclte - current_date) as bigint) as diascliente,	
					   cast(date_part('day', a.fechafacetm - current_date) as bigint) 	as diastm,			   
					   cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
					   d.nombretipoorden 		as nombretipoorden,
				   	   e.nombrefamilia 			as nombrefamilia,	 			   		   
					   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,	   
					   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,
					   --a.idmodalidadcreacion 						as idmodalidadcreacion,
					   case
						   when upper( k.criterio ) = 'FAB_FUPL' then 3
						   else a.idmodalidadcreacion
					   end as idmodalidadcreacion,
					   j.nombre 									as nombreusuario,
				       a.flagfacturacion 							as flagfacturacion,      
				       k.idchecklistinftec 							as idchecklistinftec,
				       cast(case 
						  when a.idlineadiseno = 1 then 'DE DISEÑO'
						  when a.idlineadiseno = 2 then 'DE LÍNEA'
						  when a.idlineadiseno = 3 then 'COMERCIAL'
						  when a.idlineadiseno = 4 then 'STOCK'
					      else 'NO DEFINIDO'
					   end as varchar) 	as lineadiseno,
					   cast(case 
						  when k.adelantafecha = true then 'AD'
						  when k.atrasafecha = true then 'AT'
					      else 'NAD'
					   end as varchar) as adelanta,
					   k.cantidad 									as cantidadtotal,	
					   cast(coalesce(sum(l.cantidad),0) as bigint) 	as recepcionada
				  from mct_ordentrabajo a
				  left join  mct_cliente b         		 on a.idcliente = b.idcliente
				  left join  mct_producto c        		 on a.idproducto = c.idproducto 
				  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
				  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
				  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
				  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
				  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
				  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
				  left join  mct_usuario j               on a.idusuario = j.idusuario
				  join  mct_checklistinftecvalido k on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
				  left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr
				  left join  mct_componente m            on k.idcomponente = m.idcomponente 
				  left join  mct_usuario n               on m.idresponsablefundicion = n.idusuario
				 where a.idordentrabajo >= 30000
			       and a.idestadoorden  >= 6 and a.idestadoorden <= 9
				   --and a.idfamilia in (idfamilysb, idfamilysr)
				   and case 
                           WHEN idfamilysr = 10 THEN 
                                a.idfamilia in (idfamilysb, idfamilysr) and a.idlineadiseno in (1,2,4)
                           WHEN idfamilysr = 102 THEN  
                                a.idfamilia in (idfamilysb, 10) and a.idlineadiseno in (3) 
                           ELSE 
                                a.idfamilia in (idfamilysb, idfamilysr)
                      end
			       and a.flagfacturacion is true
				   and ((a.fechafaceclte - interval '15 days') >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and (a.fechafaceclte - interval '15 days') <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				   and a.debaja < 1
				   --and n.idusuario = idusers
				   and a.checklistvalido = true
				 group by a.idordentrabajo ,
					   d.nombretipoorden ,
					   e.nombrefamilia ,
					   cast(case 
						  when a.idfamilia = 11 then c.nombreproducto
					      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
					   end as varchar),
					   b.nombrecorto ,
					   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar),
					   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar),				       
					   cast(date_part('day', a.fechafacetm - current_date) as bigint),
					   cast(date_part('day', a.fechafaceclte - current_date) as bigint),	
					   --a.idmodalidadcreacion ,
					   case
						   when upper( k.criterio ) = 'FAB_FUPL' then 3
						   else a.idmodalidadcreacion
					   end,
					   j.nombre ,
					   a.flagfacturacion ,
					   d.sigla,
					   e.sigla,
					   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar),
					   a.fechafaceclte,
					   k.nombreparte ,
					   k.plano,
					   n.nombre ,
					   cast(date_part('day', fechafundicion2 - now() ) as bigint),
					   k.idchecklistinftec,
					   a.idlineadiseno ,
					   k.adelantafecha ,
					   k.atrasafecha,
					   k.cantidad  
				 --having k.cantidad > coalesce(sum(l.cantidad),0)	   
				 --order by a.fechafundicion2 asc, a.idordentrabajo ;
			union
			select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
			       --ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
				   a.idordentrabajo 	as idordentrabajo,
			       e.sigla||'_CON' 		as siglafamilia,
			       a.idproducto 		as idproducto,
			       c.nombreproducto 	as producto,
				   b.nombrecorto 		as nombrecliente,
				   cast('SEBASTIAN CUADRA' as varchar)	as responsablefundicion,
			       --a.fechafundicion2,
				   a.fechaentrega - interval '10 days'	as fechafundicion,
			       k.nombreparte 	as nombreparte,
			       k.plano 			as plano ,
			       --cast(date_part('day', (a.fechaentrega - interval '10 days') - current_date) as bigint) 	as diasfund,
			       cast(date_part('day', (a.fechaentrega - interval '10 days') - coalesce (max(l.fechacreacion), current_date) ) as bigint) 	as diasfund,
			       cast(date_part('day', a.fechaentrega - current_date) as bigint) 	as diascliente,
			       cast(date_part('day', fechafundicion2 - now() ) 	as bigint)		as diastm,
			       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
				   d.nombretipoorden 		as nombretipoorden,
				   e.nombrefamilia 			as nombrefamilia ,	       
			       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,
			       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,			       		       	
			       --a.idmodalidadcreacion 					as idmodalidadcreacion,
			       case
					   when upper( k.criterio ) = 'FAB_FUPL' then 3
					   else a.idmodalidadcreacion
				   end as idmodalidadcreacion,
				   cast('SEBASTIAN CUADRA' as varchar)		as nombreusuario,
			       a.flagfacturacion 							as flagfacturacion,      
			       k.idchecklistinftec 							as idchecklistinftec,
			       cast(case 
						  when a.idlineadiseno = 1 then 'DE DISEÑO'
						  when a.idlineadiseno = 2 then 'DE LÍNEA'
						  when a.idlineadiseno = 3 then 'COMERCIAL'
						  when a.idlineadiseno = 4 then 'STOCK'
					      else 'NO DEFINIDO'
				   end as varchar) 	as lineadiseno,
				   cast(case 
						  when k.adelantafecha = true then 'AD'
						  when k.atrasafecha = true then 'AT'
					      else 'NAD'
					   end as varchar) as adelanta,
				   k.cantidad 									as cantidadtotal,			   
				   cast(coalesce(sum(l.cantidad),0) as bigint) 	as recepcionada			   
			  from mct_ordentrabajo a
			  left join  mct_cliente b      on a.idcliente = b.idcliente
			  left join  mct_producto c     on a.idproducto = c.idproducto
			  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e      on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
			  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
			  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j      on a.idusuario = j.idusuario 
			  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
	          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  
			 where a.idestadoorden  >= 6 and a.idestadoorden <= 9
			   and a.idfamilia   in (11, idfamilysO)
		       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = idfamilysdc)
			   and a.flagfacturacion is true
			   and ((a.fechaentrega - interval '10 days') >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and (a.fechaentrega - interval '10 days') <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			   and a.debaja < 1
			   group by a.idordentrabajo ,
			            e.sigla||'_CON',
			            c.nombreproducto,
						b.nombrecorto ,
						--a.fechafundicion2,
						a.fechaentrega,
						k.nombreparte ,
						k.plano ,
			 	        d.nombretipoorden ,
						e.nombrefamilia ,
					    k.idchecklistinftec,
					    case
					       when upper( k.criterio ) = 'FAB_FUPL' then 3
					       else a.idmodalidadcreacion
				        end,  
					    a.idlineadiseno ,
					    k.adelantafecha,
					    k.atrasafecha,
				   		k.cantidad
				 --having k.cantidad > coalesce(sum(l.cantidad),0)	
			union -- Para OT Internas
				select --ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc, a.idordentrabajo) AS item,
				       a.idordentrabajo 						as idordentrabajo,
				       cast(d.sigla||'_'||e.sigla as varchar) 	as siglafamilia,
				       a.idproducto 		as idproducto,
				       cast(case 
						  when a.idfamilia = 11 then c.nombreproducto
					      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
					   end as varchar) 	as producto,	
					   b.nombrecorto 	as nombrecliente,
					   n.nombre 		as responsablefundicion,			   
					   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) as fechafundicion,
					   a.fechafaceclte - interval '15 days' as fechafundicion,
					   k.nombreparte 	as nombreparte,
			       	   k.plano 			as plano,
					   --cast(date_part('day', (a.fechafaceclte - interval '15 days') - now() ) as bigint) 		as diasfund,
			       	   cast(date_part('day', (a.fechafaceclte - interval '15 days') - coalesce (max(l.fechacreacion), current_date) ) as bigint) 		as diasfund,
					   cast(date_part('day', a.fechafaceclte - current_date) as bigint) as diascliente,	
					   cast(date_part('day', a.fechafacetm - current_date) as bigint) 	as diastm,			   
					   cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
					   d.nombretipoorden 		as nombretipoorden,
				   	   e.nombrefamilia 			as nombrefamilia,	 			   		   
					   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,	   
					   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,
					   --a.idmodalidadcreacion 						as idmodalidadcreacion,
					   case
						   when upper( k.criterio ) = 'FAB_FUPL' then 3
						   else a.idmodalidadcreacion
					   end as idmodalidadcreacion,
					   j.nombre 									as nombreusuario,
				       a.flagfacturacion 							as flagfacturacion,      
				       k.idchecklistinftec 							as idchecklistinftec,
				       cast(case 
						  when a.idlineadiseno = 1 then 'DE DISEÑO'
						  when a.idlineadiseno = 2 then 'DE LÍNEA'
						  when a.idlineadiseno = 3 then 'COMERCIAL'
						  when a.idlineadiseno = 4 then 'STOCK'
					      else 'NO DEFINIDO'
					   end as varchar) 	as lineadiseno,
					   cast(case 
						  when k.adelantafecha = true then 'AD'
						  when k.atrasafecha = true then 'AT'
					      else 'NAD'
					   end as varchar) as adelanta,
					   k.cantidad 									as cantidadtotal,	
					   cast(coalesce(sum(l.cantidad),0) as bigint) 	as recepcionada
				  from mct_ordentrabajo a
				  left join  mct_cliente b         		 on a.idcliente = b.idcliente
				  left join  mct_producto c        		 on a.idproducto = c.idproducto 
				  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
				  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
				  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
				  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
				  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
				  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
				  left join  mct_usuario j               on a.idusuario = j.idusuario
				  join  mct_checklistinftecvalido k on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
				  left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr
				  left join  mct_componente m            on k.idcomponente = m.idcomponente 
				  left join  mct_usuario n               on m.idresponsablefundicion = n.idusuario
				 where a.idordentrabajo >= 30000
			       and a.idestadoorden <= 9
			       and a.idfamilia = 19
			       --and a.flagfacturacion is true
				   and ((a.fechafaceclte - interval '15 days') >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and (a.fechafaceclte - interval '15 days') <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
				   and a.debaja < 1
				   --and a.checklistvalido = true
				 group by a.idordentrabajo ,
					   d.nombretipoorden ,
					   e.nombrefamilia ,
					   cast(case 
						  when a.idfamilia = 11 then c.nombreproducto
					      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
					   end as varchar),
					   b.nombrecorto ,
					   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar),
					   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar),				       
					   cast(date_part('day', a.fechafacetm - current_date) as bigint),
					   cast(date_part('day', a.fechafaceclte - current_date) as bigint),	
					   --a.idmodalidadcreacion ,
					   case
						   when upper( k.criterio ) = 'FAB_FUPL' then 3
						   else a.idmodalidadcreacion
					   end,
					   j.nombre ,
					   a.flagfacturacion ,
					   d.sigla,
					   e.sigla,
					   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar),
					   a.fechafaceclte,
					   k.nombreparte ,
					   k.plano,
					   n.nombre ,
					   cast(date_part('day', fechafundicion2 - now() ) as bigint),
					   k.idchecklistinftec,
					   a.idlineadiseno ,
					   k.adelantafecha ,
					   k.atrasafecha,
					   k.cantidad 	   		
			   ) tabla
			   order by tabla.fechafundicion
			 )
			loop 
		
				 sp_nombreproducto	:= rec_modelo.producto;
				 if ( rec_modelo.idproducto in (10,11,12,13,14,15,16,17) ) then 
				 
				    select nombreproductonepcast 
				      into sp_nombreproducto
				      from mct_productonepcast
				     where idproductonepcast = rec_modelo.idproducto;
				 
				 end if;

				 select count(*)
				   into sp_tienedefecto
			       from traking.mct_defectofundicion a
			      where a.idordentrabajo = rec_modelo.idordentrabajo;
				     
		         item 					:= rec_modelo.item;
		         idordentrabajo 		:= rec_modelo.idordentrabajo;
		         siglafamilia 			:= rec_modelo.siglafamilia;
		         --,producto 				:= rec_modelo.producto;
		         producto				:= sp_nombreproducto;
		         nombrecliente 			:= rec_modelo.nombrecliente; 
		         responsablefundicion 	:= rec_modelo.responsablefundicion;
		         fechafundicion 		:= rec_modelo.fechafundicion;
		         --fechafundicion			:= rec_modelo.fechafundicion + interval '2 days';
		         nombreparte 			:= rec_modelo.nombreparte;
		         plano 					:= rec_modelo.plano;
		        
		         if ( rec_modelo.diasfund >= 0 and rec_modelo.cantidadtotal > rec_modelo.recepcionada) then
		         	diasfund			:= cast(date_part('day',rec_modelo.fechafundicion - now()) as bigint);
		         else
		         	diasfund 			:= rec_modelo.diasfund;
		         end if;
--		         diasfund 				:= rec_modelo.diasfund;
--		        
		        
		         diascliente 			:= rec_modelo.diascliente;
		         diastm 				:= rec_modelo.diastm;
		         faltantes 				:= rec_modelo.faltantes;
		         nombretipoorden 		:= rec_modelo.nombretipoorden||'_'||rec_modelo.lineadiseno||'_'||rec_modelo.adelanta;
		         nombrefamilia 			:= rec_modelo.nombrefamilia;
		         fechaentregatm 		:= rec_modelo.fechaentregatm;
		         fechaentregaclte 		:= rec_modelo.fechaentregaclte;
		         idmodalidadcreacion 	:= rec_modelo.idmodalidadcreacion;
		         nombreusuario 			:= rec_modelo.nombreusuario;
		         flagfacturacion 		:= rec_modelo.flagfacturacion;
		         idchecklistinftec 		:= rec_modelo.idchecklistinftec;
		         cantidadtotal 			:= rec_modelo.cantidadtotal;
		         recepcionada 			:= rec_modelo.recepcionada;
		         tienedefecto			:= sp_tienedefecto;
		         
		 
		         return next;				
				
			end loop;
			
			 --order by a.fechafundicion2 asc, a.idordentrabajo 
--       union			
--		select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
--		       ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
--			   a.idordentrabajo ,
--		       e.sigla||'_SIN' as siglafam,
--		       c.nombreproducto as producto,
--			   b.nombrecorto ,
--			   j.nombre ,
--		       a.fechaentrega,
--		       k.nombreparte ,
--		       k.plano ,
--		       cast(date_part('day', fechafundicion2 - now() ) as bigint),
--		       cast(date_part('day', a.fechafacetm - current_date) as bigint) as diasfund,
--		       cast(date_part('day', a.fechaentrega - current_date) as bigint) as diascliente,		       
--		       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes,
--			   d.nombretipoorden ,
--			   e.nombrefamilia ,	       
--		       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) as fechaentregatm ,
--		       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) as fechaentregaclte ,			       		       	
--		       a.idmodalidadcreacion ,
--			   j.nombre ,
--		       a.flagfacturacion ,      
--		       k.idchecklistinftec,
--			   k.cantidad as total,			   
