ALTER FUNCTION traking.evtlistprogramafundicionsdetallecalendario(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1552 (class 1255 OID 17274)
-- Name: evtlistprogramafundicionsdetallecalendariodiario(bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistprogramafundicionsdetallecalendariodiario(idworkorders bigint, productoscharacter character varying, idusers bigint, periodos character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, siglafamilia character varying, producto character varying, nombrecliente character varying, responsablefundicion character varying, fechafundicion timestamp without time zone, nombreparte character varying, plano character varying, diasfund bigint, diascliente bigint, diastm bigint, faltantes bigint, nombretipoorden character varying, nombrefamilia character varying, fechaentregatm character varying, fechaentregaclte character varying, idmodalidadcreacion bigint, nombreusuario character varying, flagfacturacion boolean, idchecklistinftec bigint, cantidadtotal bigint, recepcionada bigint, tienedefecto bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					bigint;
    sp_mec					bigint;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					bigint;
    parte2					bigint;
    corte                   bigint;
   
    sp_tienedefecto			bigint;
   
begin

	fechadesde			:= '';
    fechahasta			:= '';
    parte1				:= 0;
    parte2				:= 0;
    corte				:= 0;
    sp_tienedefecto		:= 0;
   
	if (periodos != '-1') then

		select to_char(now() - interval '2 year','yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		select to_char(now() + interval '2 year','yyyy')
		  into anofin;
		 
		fechahasta	:= anofin||'-'||mes||'-'||ultimodia;


	    RETURN QUERY	
			
			select ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
			       a.idordentrabajo ,
			       cast(d.sigla||'_'||e.sigla as varchar) as siglafam,
			       cast(case 
					  when a.idfamilia = 11 then c.nombreproducto
				      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				   end as varchar) as producto,	
				   b.nombrecorto ,
				   n.nombre ,			   
				   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) as fechafundicion,
				   a.fechafundicion3 as fechafundicion,
				   k.nombreparte ,
				   k.plano,
				   cast(date_part('day', fechafundicion2 - now() ) as bigint) as diasfund,
				   cast(date_part('day', a.fechafaceclte - current_date) as bigint) as diascliente,	
				   cast(date_part('day', a.fechafacetm - current_date) as bigint) as dias,			   
				   cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes,
				   d.nombretipoorden ,
				   e.nombrefamilia ,			   		   
				   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) as fechaentregatm ,	   
				   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar) as fechaentregaclte ,
				   a.idmodalidadcreacion ,
				   j.nombre ,
				   a.flagfacturacion ,
				   k.idchecklistinftec,
				   k.cantidad as total,
				   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
				   cast(0 as bigint)
			  from mct_ordentrabajo a
			  left join  mct_cliente b         		 on a.idcliente = b.idcliente
			  left join  mct_producto c        		 on a.idproducto = c.idproducto 
			  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
			  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
			  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j               on a.idusuario = j.idusuario
			  join  mct_checklistinftecvalido k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
			  left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr
			  left join  mct_componente m            on k.idcomponente = m.idcomponente 
			  left join  mct_usuario n               on m.idresponsablefundicion = n.idusuario
			 where a.idordentrabajo >= 30000
		       and a.idestadoorden  >= 6 and a.idestadoorden < 9
			   and a.idfamilia in (8, 10)
		       and a.flagfacturacion is true
			   and (a.fechafundicion3 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion3 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			   and a.debaja < 1
			   --and n.idusuario = idusers
			   and a.checklistvalido = true
			 group by a.idordentrabajo ,
				   d.nombretipoorden ,
				   e.nombrefamilia ,
				   cast(case 
					  when a.idfamilia = 11 then c.nombreproducto
				      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				   end as varchar),
				   b.nombrecorto ,
				   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar),
				   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar),				       
				   cast(date_part('day', a.fechafacetm - current_date) as bigint),
				   cast(date_part('day', a.fechafaceclte - current_date) as bigint),	
				   a.idmodalidadcreacion ,
				   j.nombre ,
				   a.flagfacturacion ,
				   d.sigla,
				   e.sigla,
				   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar),
				   a.fechafundicion3,
				   k.nombreparte ,
				   k.plano,
				   n.nombre ,
				   cast(date_part('day', fechafundicion2 - now() ) as bigint),
				   k.idchecklistinftec,
				   k.cantidad  
			 having k.cantidad > coalesce(sum(l.cantidad),0)	   
			 --order by a.fechafundicion2 asc, a.idordentrabajo ;
		union
		select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
		       ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
			   a.idordentrabajo ,
		       e.sigla||'_CON' as siglafam,
		       c.nombreproducto as producto,
			   b.nombrecorto ,
			   cast('SEBASTIAN CUADRA' as varchar),
		       a.fechafundicion3,
		       k.nombreparte ,
		       k.plano ,
		       cast(date_part('day', a.fechafacetm - current_date) as bigint) as diasfund,
		       cast(date_part('day', a.fechaentrega - current_date) as bigint) as diascliente,
		       cast(date_part('day', fechafundicion2 - now() ) as bigint),
		       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes,
			   d.nombretipoorden ,
			   e.nombrefamilia ,	       
		       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) as fechaentregatm ,
		       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) as fechaentregaclte ,			       		       	
		       a.idmodalidadcreacion ,
			   cast('SEBASTIAN CUADRA' as varchar),
		       a.flagfacturacion ,      
		       k.idchecklistinftec,
			   k.cantidad as total,			   
			   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada	,
				   cast(0 as bigint)		   
		  from mct_ordentrabajo a
		  left join  mct_cliente b      on a.idcliente = b.idcliente
		  left join  mct_producto c     on a.idproducto = c.idproducto
		  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
		  left join  mct_familia e      on a.idfamilia = e.idfamilia
		  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
		  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
		  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
		  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
		  left join  mct_usuario j      on a.idusuario = j.idusuario 
		  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  
		 where a.idestadoorden  >= 6 and a.idestadoorden < 9
		   and a.idfamilia   = 11
	       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
		   and a.flagfacturacion is true
		   and (a.fechafundicion3 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion3 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
		   and a.debaja < 1
		   group by a.idordentrabajo ,
		            e.sigla||'_CON',
		            c.nombreproducto,
					b.nombrecorto ,
					a.fechafundicion3,
					k.nombreparte ,
					k.plano ,
		 	        d.nombretipoorden ,
					e.nombrefamilia ,
				    k.idchecklistinftec,
			   		k.cantidad
			 having k.cantidad > coalesce(sum(l.cantidad),0)		 
			 --order by a.fechafundicion2 asc, a.idordentrabajo 
       union			
		select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
		       ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
			   a.idordentrabajo ,
		       e.sigla||'_SIN' as siglafam,
		       c.nombreproducto as producto,
			   b.nombrecorto ,
			   j.nombre ,
		       a.fechafundicion3,
		       k.nombreparte ,
		       k.plano ,
		       cast(date_part('day', fechafundicion2 - now() ) as bigint),
		       cast(date_part('day', a.fechafacetm - current_date) as bigint) as diasfund,
		       cast(date_part('day', a.fechaentrega - current_date) as bigint) as diascliente,		       
		       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes,
			   d.nombretipoorden ,
			   e.nombrefamilia ,	       
		       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) as fechaentregatm ,
		       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) as fechaentregaclte ,			       		       	
		       a.idmodalidadcreacion ,
			   j.nombre ,
		       a.flagfacturacion ,      
		       k.idchecklistinftec,
			   k.cantidad as total,			   
			   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada,
				   cast(0 as bigint)			   
		  from mct_ordentrabajo a
		  left join  mct_cliente b      on a.idcliente = b.idcliente
		  left join  mct_producto c     on a.idproducto = c.idproducto
		  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
		  left join  mct_familia e      on a.idfamilia = e.idfamilia
		  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
		  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
		  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
		  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
		  left join  mct_usuario j      on a.idusuario = j.idusuario 
		  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  
		 where a.idestadoorden  >= 6 and a.idestadoorden < 9
		   and a.idfamilia   = 11
	       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 2)
		   and a.flagfacturacion is true
		   and (a.fechafundicion3 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion3 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
		   and a.debaja < 1
		   group by a.idordentrabajo ,
