					j.nombre,
					a.fechafundicion3,
					k.nombreparte ,
					k.plano ,
		 	        d.nombretipoorden ,
					e.nombrefamilia ,
				    k.idchecklistinftec,
			   		k.cantidad
			 having k.cantidad > coalesce(sum(l.cantidad),0);		
	
	end if;
	 
END;
$$;


