    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					integer;
    parte2					integer;
    corte                   integer;
   
