		  					and (k.plano   like 'NE3112-01%'
							or  k.plano   like 'NE3113-04%'
							or  k.plano   like 'NE3111-01%'
							or  k.plano   like 'NE3113-05%'
							or  k.plano   like 'NE3145-19%'
							or  k.plano   like 'NE3145-21%'
							or  k.plano   like 'NE3111-03%'
							or  k.plano   like 'NE3145-11%'
							or  k.plano   like 'NE0713-26%')	  
          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  
          where a.idestadoorden  >= 6 and a.idestadoorden < 9
		   and a.idfamilia   = 11
	       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 1)
		   and a.flagfacturacion is true
		   and (a.fechafundicion2 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
		   and a.debaja < 1
		   group by a.idordentrabajo ,
		            e.sigla||'_CON',
		            c.nombreproducto,
					b.nombrecorto ,
					a.fechafundicion2,
					k.nombreparte ,
					k.plano ,
		 	        d.nombretipoorden ,
					e.nombrefamilia ,
				    k.idchecklistinftec,
			   		k.cantidad
			 having k.cantidad > coalesce(sum(l.cantidad),0)		 
			 --order by a.fechafundicion2 asc, a.idordentrabajo 
       union			
		select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
		       ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
			   a.idordentrabajo ,
		       cast(e.sigla||'_SIN' as varchar) as siglafam,
		       c.nombreproducto as producto,
			   b.nombrecorto ,
			   j.nombre ,
		       a.fechaentrega,
		       k.nombreparte ,
		       k.plano ,
		       cast(date_part('day', fechafundicion2 - now() ) as bigint),
		       cast(date_part('day', a.fechafacetm - current_date) as bigint) as diasfund,
		       cast(date_part('day', a.fechaentrega - current_date) as bigint) as diascliente,		       
		       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) as faltantes,
			   d.nombretipoorden ,
			   e.nombrefamilia ,	       
		       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) as fechaentregatm ,
		       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) as fechaentregaclte ,			       		       	
		       a.idmodalidadcreacion ,
			   j.nombre ,
		       a.flagfacturacion ,      
		       k.idchecklistinftec,
			   k.cantidad as total,			   
			   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada			   
		  from mct_ordentrabajo a
		  left join  mct_cliente b      on a.idcliente = b.idcliente
		  left join  mct_producto c     on a.idproducto = c.idproducto
		  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
		  left join  mct_familia e      on a.idfamilia = e.idfamilia
		  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
		  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
		  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
		  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
		  left join  mct_usuario j      on a.idusuario = j.idusuario 
		  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
		  					and (k.plano   like 'NE3112-01%'
							or  k.plano   like 'NE3113-04%'
							or  k.plano   like 'NE3111-01%'
							or  k.plano   like 'NE3113-05%'
							or  k.plano   like 'NE3145-19%'
							or  k.plano   like 'NE3145-21%'
							or  k.plano   like 'NE3111-03%'
							or  k.plano   like 'NE3145-11%'
							or  k.plano   like 'NE0713-26%')
          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  	
          where a.idestadoorden  >= 6 and a.idestadoorden < 9
		   and a.idfamilia   = 11
	       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = 2)
		   and a.flagfacturacion is true
		   and (a.fechaentrega >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
		   and a.debaja < 1
		   group by a.idordentrabajo ,
		            e.sigla||'_SIN',
		            c.nombreproducto,
					b.nombrecorto ,
					j.nombre,
					a.fechaentrega,
					k.nombreparte ,
					k.plano ,
		 	        d.nombretipoorden ,
					e.nombrefamilia ,
				    k.idchecklistinftec,
			   		k.cantidad
			 having k.cantidad > coalesce(sum(l.cantidad),0);		
	
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistprogramafundicionsdetallecalendariof2_borrar(idworkorders bigint, productoscharacter character varying, idusers bigint, periodos character varying) OWNER TO postgres;

--
-- TOC entry 1573 (class 1255 OID 17284)
-- Name: evtlistprogramafundicionsdetallecalendariomodelo(bigint, bigint, bigint, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistprogramafundicionsdetallecalendariomodelo(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, siglafamilia character varying, producto character varying, nombrecliente character varying, responsablefundicion character varying, fechafundicion timestamp without time zone, nombreparte character varying, plano character varying, diasfund bigint, diascliente bigint, diastm bigint, faltantes bigint, nombretipoorden character varying, nombrefamilia character varying, fechaentregatm character varying, fechaentregaclte character varying, idmodalidadcreacion bigint, nombreusuario character varying, flagfacturacion boolean, idchecklistinftec bigint, cantidadtotal bigint, recepcionada bigint, tienedefecto bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					bigint;
    sp_mec					bigint;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					bigint;
    parte2					bigint;
    corte                   bigint;
    sp_nombreproducto		varchar;
   
   	rec_modelo      		RECORD;
   
    sp_tienedefecto			bigint;
   
begin

	fechadesde			:= '';
    fechahasta			:= '';
    parte1				:= 0;
    parte2				:= 0;
    corte				:= 0;  
    sp_tienedefecto		:= 0;
   
	if (periodos != '-1') then

		select to_char(now() - interval '2 year','yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		select to_char(now() + interval '2 year','yyyy')
		  into anofin;
		 
		fechahasta	:= anofin||'-'||mes||'-'||ultimodia;


	      FOR rec_modelo IN (  
	        select ROW_NUMBER() OVER (ORDER BY tabla.fechafundicion asc, tabla.idordentrabajo) as item,
	               tabla.idordentrabajo,
	               tabla.siglafamilia,
	               tabla.idproducto,
	               tabla.producto,
	               tabla.nombrecliente,
	               tabla.responsablefundicion,
	               tabla.fechafundicion,
	               tabla.nombreparte,
	               tabla.plano,
	               tabla.diasfund,
	               tabla.diascliente,
	               tabla.diastm,
	               tabla.faltantes,
	               tabla.nombretipoorden,
	               tabla.nombrefamilia,
	               tabla.fechaentregatm,
	               tabla.fechaentregaclte,
	               tabla.idmodalidadcreacion,
	               tabla.nombreusuario,
	               tabla.flagfacturacion,
	               tabla.idchecklistinftec,
	               tabla.cantidadtotal,
	               tabla.recepcionada
	        from (	      
			select ROW_NUMBER() OVER (ORDER BY a.fechafaceclte asc, a.idordentrabajo) AS item,
			       a.idordentrabajo 						as idordentrabajo,
			       cast(d.sigla||'_'||e.sigla as varchar) 	as siglafamilia,
			       a.idproducto as idproducto,
			       cast(case 
					  when a.idfamilia = 11 then c.nombreproducto
				      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				   end as varchar) 	as producto,	
				   b.nombrecorto 	as nombrecliente,
				   n.nombre 		as responsablefundicion,			   
				   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) as fechafundicion,
				   a.fechafaceclte - interval '25 days' as fechafundicion,
				   k.nombreparte 	as nombreparte,
				   k.plano			as plano,
				   cast(date_part('day', fechafaceclte - now() ) as bigint) 		as diasfund,
				   cast(date_part('day', a.fechafaceclte - current_date) as bigint) as diascliente,	
				   cast(date_part('day', a.fechafacetm - current_date) as bigint) 	as diastm,			   
				   cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
				   d.nombretipoorden 	as nombretipoorden,
				   e.nombrefamilia 		as nombrefamilia,			   		   
				   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,	   
				   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,
				   a.idmodalidadcreacion 	as idmodalidadcreacion,
				   j.nombre 				as nombreusuario,
				   a.flagfacturacion 		as flagfacturacion,
				   k.idchecklistinftec		as idchecklistinftec,
				   k.cantidad 				as cantidadtotal,
				   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada
			  from mct_ordentrabajo a
			  left join  mct_cliente b         		 on a.idcliente = b.idcliente
			  left join  mct_producto c        		 on a.idproducto = c.idproducto 
			  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
			  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
			  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j               on a.idusuario = j.idusuario
			  left join  mct_checklistinftecvalido k on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
			  left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr
			  left join  mct_componente m            on k.idcomponente = m.idcomponente 
			  left join  mct_usuario n               on m.idresponsablefundicion = n.idusuario
			 where a.idordentrabajo >= 30000
		       and a.idestadoorden  >= 6 and a.idestadoorden < 9
			   and a.idfamilia in (idfamilysb, idfamilysr)
		       and a.flagfacturacion is true
			   and ((a.fechafaceclte - interval '25 days') >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and (a.fechafaceclte - interval '25 days') <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			   and a.debaja < 1
			   --and n.idusuario = idusers
			   and a.checklistvalido = true
			 group by a.idordentrabajo ,
			       a.idproducto ,
				   d.nombretipoorden ,
				   e.nombrefamilia ,
				   cast(case 
					  when a.idfamilia = 11 then c.nombreproducto
				      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				   end as varchar),
				   b.nombrecorto ,
				   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar),
				   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar),				       
				   cast(date_part('day', a.fechafacetm - current_date) as bigint),
				   cast(date_part('day', a.fechafaceclte - current_date) as bigint),	
				   a.idmodalidadcreacion ,
				   j.nombre ,
				   a.flagfacturacion ,
				   d.sigla,
				   e.sigla,
				   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar),
				   a.fechafundicion2,
				   k.nombreparte ,
				   k.plano,
				   n.nombre ,
				   cast(date_part('day', fechafundicion2 - now() ) as bigint),
				   k.idchecklistinftec,
				   k.cantidad  
			 having k.cantidad > coalesce(sum(l.cantidad),0)	   
		    union
		    select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
			       ROW_NUMBER() OVER (ORDER BY a.fechafundicion2 asc, a.idordentrabajo) AS item,
				   a.idordentrabajo 	as idordentrabajo,
			       e.sigla||'_SIN' 		as siglafamilia,
			       a.idproducto 		as idproducto,
			       c.nombreproducto 	as producto,
				   b.nombrecorto 		as nombrecliente,
				   cast('SEBASTIAN CUADRA' as varchar)	as responsablefundicion,
			       --a.fechafundicion2,
				   a.fechaentrega - interval '15 days'	as fechafundicion,
			       k.nombreparte 	as nombreparte,
			       k.plano 			as plano,
			       cast(date_part('day', a.fechafacetm - current_date) as bigint) 	as diasfund,
			       cast(date_part('day', a.fechaentrega - current_date) as bigint) 	as diascliente,
			       cast(date_part('day', fechafundicion2 - now() ) as bigint)		as diastm,
			       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
				   d.nombretipoorden 	as nombretipoorden,
				   e.nombrefamilia 		as nombrefamilia,	       
			       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,
			       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,			       		       	
			       a.idmodalidadcreacion 				as idmodalidadcreacion,
				   cast('SEBASTIAN CUADRA' as varchar)	as nombreusuario,
			       a.flagfacturacion 		as flagfacturacion,      
			       k.idchecklistinftec		as idchecklistinftec,
				   k.cantidad 				as cantidadtotal,			   
				   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada			   
			  from mct_ordentrabajo a
			  left join  mct_cliente b      on a.idcliente = b.idcliente
			  left join  mct_producto c     on a.idproducto = c.idproducto
			  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e      on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
			  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
			  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j      on a.idusuario = j.idusuario 
			  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
	          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  
			 where a.idestadoorden  >= 6 and a.idestadoorden < 9
			   and a.idfamilia   in (11, idfamilysO)
		       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = idfamilysds)
			   and a.flagfacturacion is true
			   and ((a.fechaentrega - interval '15 days') >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and (a.fechaentrega - interval '15 days') <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			   and a.debaja < 1
			   and not exists (select 'x' from mct_clasificafundicion cf where k.plano = cf.plano and cf.fundiciondos = true)
			   group by a.idordentrabajo ,
			            e.sigla||'_SIN',
			            a.idproducto,
			            c.nombreproducto,
						b.nombrecorto ,
						--a.fechafundicion2,
						a.fechaentrega,
						k.nombreparte ,
						k.plano ,
			 	        d.nombretipoorden ,
						e.nombrefamilia ,
					    k.idchecklistinftec,
				   		k.cantidad
				 having k.cantidad > coalesce(sum(l.cantidad),0)
			union
			select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
			       ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc, a.idordentrabajo) AS item,
				   a.idordentrabajo 	as idordentrabajo,
			       e.sigla||'_CONCR' 	as siglafamilia,
			       a.idproducto 		as idproducto,
			       c.nombreproducto 	as producto,
				   b.nombrecorto 		as nombrecliente,
				   cast('SEBASTIAN CUADRA' as varchar)		as responsablefundicion,
			       --a.fechafundicion2,
				   a.fechaentrega - interval '25 days'		as fechafundicion,
			       k.nombreparte 	as nombreparte,
			       k.plano 			as plano,
			       cast(date_part('day', a.fechafacetm - current_date) as bigint) 	as diasfund,
			       cast(date_part('day', a.fechaentrega - current_date) as bigint) 	as diascliente,
			       cast(date_part('day', fechafundicion2 - now() ) as bigint)		as diastm,
			       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
				   d.nombretipoorden 		as nombretipoorden,
				   e.nombrefamilia 			as nombrefamilia,	       
			       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,
			       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,			       		       	
			       a.idmodalidadcreacion 						as idmodalidadcreacion,
				   cast('SEBASTIAN CUADRA' as varchar) 			as nombreusuario,
			       a.flagfacturacion 							as flagfacturacion,      
			       k.idchecklistinftec 							as idchecklistinftec,
				   k.cantidad 									as cantidadtotal,			   
				   cast(coalesce(sum(l.cantidad),0) as bigint) 	as recepcionada			   
			  from mct_ordentrabajo a
			  left join  mct_cliente b      on a.idcliente = b.idcliente
			  left join  mct_producto c     on a.idproducto = c.idproducto
			  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e      on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
			  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
			  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j      on a.idusuario = j.idusuario 
			  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
	          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  
			 where a.idestadoorden  >= 6 and a.idestadoorden < 9
			   and a.idfamilia   in (11, idfamilysO)
		       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = idfamilysdc)
			   and a.flagfacturacion is true
			   and ((a.fechaentrega - interval '25 days') >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and (a.fechaentrega - interval '25 days') <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			   and exists (select 'x' from mct_clasificafundicion cf where k.plano = cf.plano and cf.recocido  = true)
			   and a.debaja < 1
			   group by a.idordentrabajo ,
			            e.sigla||'_CONCR',
			            a.idproducto,
			            c.nombreproducto,
						b.nombrecorto ,
						--a.fechafundicion2,
						a.fechaentrega,
						k.nombreparte ,
						k.plano ,
			 	        d.nombretipoorden ,
						e.nombrefamilia ,
					    k.idchecklistinftec,
				   		k.cantidad
				 having k.cantidad > coalesce(sum(l.cantidad),0)	
			   ) tabla
			   order by tabla.fechafundicion
			 )
			loop 	

				 sp_nombreproducto	:= rec_modelo.producto;
				 if ( rec_modelo.idproducto in (10,11,12,13,14,15,16,17) ) then 
				 
				    select nombreproductonepcast 
				      into sp_nombreproducto
				      from mct_productonepcast
				     where idproductonepcast = rec_modelo.idproducto;
				 
				 end if;
				
				 update traking.mct_ordentrabajo
				    set fechafundicionmodelo = rec_modelo.fechafundicion,
				        fechafundicioncal = rec_modelo.fechafundicion + interval '2 days'
				  where traking.mct_ordentrabajo.idordentrabajo = rec_modelo.idordentrabajo
				    and traking.mct_ordentrabajo.fechafundicioncal is null;
				
				 select count(*)
				   into sp_tienedefecto
				   from traking.mct_defectofundicion a
			      where a.idordentrabajo = rec_modelo.idordentrabajo;
				     
		         item 					:= rec_modelo.item;
		         idordentrabajo 		:= rec_modelo.idordentrabajo;
		         siglafamilia 			:= rec_modelo.siglafamilia;
		         --,producto 				:= rec_modelo.producto;
		         producto				:= sp_nombreproducto;
		         nombrecliente 			:= rec_modelo.nombrecliente; 
		         responsablefundicion 	:= rec_modelo.responsablefundicion;
		         fechafundicion 		:= rec_modelo.fechafundicion;
		         --fechafundicion			:= rec_modelo.fechafundicion + interval '2 days';
		         nombreparte 			:= rec_modelo.nombreparte;
		         plano 					:= rec_modelo.plano;
		         diasfund 				:= rec_modelo.diasfund;
		         diascliente 			:= rec_modelo.diascliente;
		         diastm 				:= rec_modelo.diastm;
		         faltantes 				:= rec_modelo.faltantes;
		         nombretipoorden 		:= rec_modelo.nombretipoorden;
		         nombrefamilia 			:= rec_modelo.nombrefamilia;
		         fechaentregatm 		:= rec_modelo.fechaentregatm;
		         fechaentregaclte 		:= rec_modelo.fechaentregaclte;
		         idmodalidadcreacion 	:= rec_modelo.idmodalidadcreacion;
		         nombreusuario 			:= rec_modelo.nombreusuario;
		         flagfacturacion 		:= rec_modelo.flagfacturacion;
		         idchecklistinftec 		:= rec_modelo.idchecklistinftec;
		         cantidadtotal 			:= rec_modelo.cantidadtotal;
		         recepcionada 			:= rec_modelo.recepcionada;
		         tienedefecto			:= sp_tienedefecto;
		         
		 
		         return next;
         
			end loop;
			
	
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistprogramafundicionsdetallecalendariomodelo(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 2173 (class 1255 OID 17286)
-- Name: evtlistprogramafundicionsdetallecalendariomodelocolada(bigint, bigint, bigint, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistprogramafundicionsdetallecalendariomodelocolada(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, siglafamilia character varying, producto character varying, nombrecliente character varying, responsablefundicion character varying, fechafundicion timestamp without time zone, nombreparte character varying, plano character varying, diasfund bigint, diascliente bigint, diastm bigint, faltantes bigint, nombretipoorden character varying, nombrefamilia character varying, fechaentregatm character varying, fechaentregaclte character varying, idmodalidadcreacion bigint, nombreusuario character varying, flagfacturacion boolean, idchecklistinftec bigint, cantidadtotal bigint, recepcionada bigint, tienedefecto bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					integer;
    parte2					integer;
    corte                   integer;
    sp_nombreproducto		varchar;
   
   	rec_modelo      		RECORD;
   
    sp_tienedefecto			bigint;
   
begin

	fechadesde			:= '';
    fechahasta			:= '';
    parte1				:= 0;
    parte2				:= 0;
    corte				:= 0;
    sp_tienedefecto		:= 0;
   
	if (periodos != '-1') then

		select to_char(now() - interval '2 year','yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		select to_char(now() + interval '2 year','yyyy')
		  into anofin;
		 
		fechahasta	:= anofin||'-'||mes||'-'||ultimodia;


	      FOR rec_modelo IN (         
	      
	        select ROW_NUMBER() OVER (ORDER BY tabla.fechafundicion asc, tabla.idordentrabajo) as item,
	               tabla.idordentrabajo,
	               tabla.siglafamilia,
	               tabla.idproducto,
	               tabla.producto,
	               tabla.nombrecliente,
	               tabla.responsablefundicion,
	               tabla.fechafundicion,
	               tabla.nombreparte,
	               tabla.plano,
	               tabla.diasfund,
	               tabla.diascliente,
	               tabla.diastm,
	               tabla.faltantes,
	               tabla.nombretipoorden,
	               tabla.nombrefamilia,
	               tabla.fechaentregatm,
	               tabla.fechaentregaclte,
	               tabla.idmodalidadcreacion,
	               tabla.nombreusuario,
	               tabla.flagfacturacion,
	               tabla.idchecklistinftec,
	               tabla.cantidadtotal,
	               tabla.recepcionada
	        from (
			select ROW_NUMBER() OVER (ORDER BY a.fechafundicioncal asc, a.idordentrabajo) AS item,
			       a.idordentrabajo 						as idordentrabajo,
			       cast(d.sigla||'_'||e.sigla as varchar) 	as siglafamilia,
			       a.idproducto as idproducto,
			       cast(case 
					  when a.idfamilia = 11 then c.nombreproducto
				      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				   end as varchar) 	as producto,	
				   b.nombrecorto 	as nombrecliente,
				   n.nombre 		as responsablefundicion,			   
				   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) as fechafundicion,
				   a.fechafundicioncal as fechafundicion,
				   k.nombreparte 	as nombreparte,
				   k.plano			as plano,
				   cast(date_part('day', fechafaceclte - now() ) as bigint) 		as diasfund,
				   cast(date_part('day', a.fechafaceclte - current_date) as bigint) as diascliente,	
				   cast(date_part('day', a.fechafacetm - current_date) as bigint) 	as diastm,			   
				   cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
				   d.nombretipoorden 	as nombretipoorden,
				   e.nombrefamilia 		as nombrefamilia,			   		   
				   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,	   
				   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,
				   a.idmodalidadcreacion 	as idmodalidadcreacion,
				   j.nombre 				as nombreusuario,
				   a.flagfacturacion 		as flagfacturacion,
				   k.idchecklistinftec		as idchecklistinftec,
				   k.cantidad 				as cantidadtotal,
				   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada
			  from mct_ordentrabajo a
			  left join  mct_cliente b         		 on a.idcliente = b.idcliente
			  left join  mct_producto c        		 on a.idproducto = c.idproducto 
			  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
			  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
			  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j               on a.idusuario = j.idusuario
			  join  mct_checklistinftecvalido k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
			  left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr
			  left join  mct_componente m            on k.idcomponente = m.idcomponente 
			  left join  mct_usuario n               on m.idresponsablefundicion = n.idusuario
			 where a.idordentrabajo >= 30000
		       and a.idestadoorden  >= 6 and a.idestadoorden < 9
			   and a.idfamilia in (idfamilysb, idfamilysr)
		       and a.flagfacturacion is true
			   and (a.fechafundicioncal >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicioncal <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			   and a.debaja < 1
			   --and n.idusuario = idusers
			   and a.checklistvalido = true
			 group by a.idordentrabajo ,
			       a.idproducto ,
				   d.nombretipoorden ,
				   e.nombrefamilia ,
				   cast(case 
					  when a.idfamilia = 11 then c.nombreproducto
				      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
				   end as varchar),
				   b.nombrecorto ,
				   cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar),
				   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar),				       
				   cast(date_part('day', a.fechafacetm - current_date) as bigint),
				   cast(date_part('day', a.fechafaceclte - current_date) as bigint),	
				   a.idmodalidadcreacion ,
				   j.nombre ,
				   a.flagfacturacion ,
				   d.sigla,
				   e.sigla,
				   --cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar),
				   a.fechafundicioncal,
				   k.nombreparte ,
				   k.plano,
				   n.nombre ,
				   cast(date_part('day', fechafundicion2 - now() ) as bigint),
				   k.idchecklistinftec,
				   k.cantidad  
			 having k.cantidad > coalesce(sum(l.cantidad),0)	   
		    union
		    select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
			       ROW_NUMBER() OVER (ORDER BY a.fechafundicioncal asc, a.idordentrabajo) AS item,
				   a.idordentrabajo 	as idordentrabajo,
			       e.sigla||'_SIN' 		as siglafamilia,
			       a.idproducto 		as idproducto,
			       c.nombreproducto 	as producto,
				   b.nombrecorto 		as nombrecliente,
				   cast('SEBASTIAN CUADRA' as varchar)	as responsablefundicion,
			       --a.fechafundicion2,
				   a.fechafundicioncal	as fechafundicion,
			       k.nombreparte 	as nombreparte,
			       k.plano 			as plano,
			       cast(date_part('day', a.fechafacetm - current_date) as bigint) 	as diasfund,
			       cast(date_part('day', a.fechaentrega - current_date) as bigint) 	as diascliente,
			       cast(date_part('day', fechafundicion2 - now() ) as bigint)		as diastm,
			       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
				   d.nombretipoorden 	as nombretipoorden,
				   e.nombrefamilia 		as nombrefamilia,	       
			       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,
			       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,			       		       	
			       a.idmodalidadcreacion 				as idmodalidadcreacion,
				   cast('SEBASTIAN CUADRA' as varchar)	as nombreusuario,
			       a.flagfacturacion 		as flagfacturacion,      
			       k.idchecklistinftec		as idchecklistinftec,
				   k.cantidad 				as cantidadtotal,			   
				   cast(coalesce(sum(l.cantidad),0) as bigint) as recepcionada			   
			  from mct_ordentrabajo a
			  left join  mct_cliente b      on a.idcliente = b.idcliente
			  left join  mct_producto c     on a.idproducto = c.idproducto
			  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e      on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
			  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
			  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j      on a.idusuario = j.idusuario 
			  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
	          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  
			 where a.idestadoorden  >= 6 and a.idestadoorden < 9
			   and a.idfamilia   in (11, idfamilysO)
		       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = idfamilysds)
			   and a.flagfacturacion is true
			   and (a.fechafundicioncal >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicioncal <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			   and a.debaja < 1
			   and not exists (select 'x' from mct_clasificafundicion cf where k.plano = cf.plano and cf.fundiciondos = true)
			   group by a.idordentrabajo ,
			            e.sigla||'_SIN',
			            a.idproducto,
			            c.nombreproducto,
						b.nombrecorto ,
						--a.fechafundicion2,
						a.fechafundicioncal,
						k.nombreparte ,
						k.plano ,
			 	        d.nombretipoorden ,
						e.nombrefamilia ,
					    k.idchecklistinftec,
				   		k.cantidad
				 having k.cantidad > coalesce(sum(l.cantidad),0)
			union
			select --ROW_NUMBER() OVER (ORDER BY (a.fechaentrega - interval '14 days') asc, a.idordentrabajo) AS item,
			       ROW_NUMBER() OVER (ORDER BY a.fechafundicioncal asc, a.idordentrabajo) AS item,
				   a.idordentrabajo 	as idordentrabajo,
			       e.sigla||'_CONCR' 	as siglafamilia,
			       a.idproducto 		as idproducto,
			       c.nombreproducto 	as producto,
				   b.nombrecorto 		as nombrecliente,
				   cast('SEBASTIAN CUADRA' as varchar)		as responsablefundicion,
			       --a.fechafundicion2,
				   a.fechafundicioncal 		as fechafundicion,
			       k.nombreparte 	as nombreparte,
			       k.plano 			as plano,
			       cast(date_part('day', a.fechafacetm - current_date) as bigint) 	as diasfund,
			       cast(date_part('day', a.fechaentrega - current_date) as bigint) 	as diascliente,
			       cast(date_part('day', fechafundicion2 - now() ) as bigint)		as diastm,
			       cast(k.cantidad - coalesce(sum(l.cantidad),0) as bigint) 		as faltantes,
				   d.nombretipoorden 		as nombretipoorden,
				   e.nombrefamilia 			as nombrefamilia,	       
			       cast(to_char(a.fechafacetm,'dd-mm-yyyy') as varchar) 	as fechaentregatm ,
			       cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	as fechaentregaclte ,			       		       	
			       a.idmodalidadcreacion 						as idmodalidadcreacion,
				   cast('SEBASTIAN CUADRA' as varchar) 			as nombreusuario,
			       a.flagfacturacion 							as flagfacturacion,      
			       k.idchecklistinftec 							as idchecklistinftec,
				   k.cantidad 									as cantidadtotal,			   
				   cast(coalesce(sum(l.cantidad),0) as bigint) 	as recepcionada			   
			  from mct_ordentrabajo a
			  left join  mct_cliente b      on a.idcliente = b.idcliente
			  left join  mct_producto c     on a.idproducto = c.idproducto
			  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
			  left join  mct_familia e      on a.idfamilia = e.idfamilia
			  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
			  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
			  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
			  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
			  left join  mct_usuario j      on a.idusuario = j.idusuario 
			  left join  mct_checklistinftec k       on a.idordentrabajo = k.idordentrabajo and (k.codigoqr = a.idordentrabajo||'FAB_FU' or k.codigoqr = a.idordentrabajo||'FAB_FUPL')
	          left join  mct_checklistinftecrecept l on k.idchecklistinftec = l.idchecklistinftec and (l.codigoqr = a.idordentrabajo||'FAB_FU' or l.codigoqr = a.idordentrabajo||'FAB_FUPL')--k.codigoqr = l.codigoqr 	  
			 where a.idestadoorden  >= 6 and a.idestadoorden < 9
			   and a.idfamilia   in (11, idfamilysO)
		       and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = idfamilysdc)
			   and a.flagfacturacion is true
			   and (a.fechafundicioncal >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicioncal <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			   and exists (select 'x' from mct_clasificafundicion cf where k.plano = cf.plano and cf.recocido  = true)
			   and a.debaja < 1
			   group by a.idordentrabajo ,
			            e.sigla||'_CONCR',
			            a.idproducto,
			            c.nombreproducto,
						b.nombrecorto ,
						--a.fechafundicion2,
						a.fechafundicioncal,
						k.nombreparte ,
						k.plano ,
			 	        d.nombretipoorden ,
						e.nombrefamilia ,
					    k.idchecklistinftec,
				   		k.cantidad
				 having k.cantidad > coalesce(sum(l.cantidad),0)	
			   ) tabla
			   order by tabla.fechafundicion
			 )
			loop 	

				 sp_nombreproducto	:= rec_modelo.producto;
				 if ( rec_modelo.idproducto in (10,11,12,13,14,15,16,17) ) then 
				 
				    select nombreproductonepcast 
				      into sp_nombreproducto
				      from mct_productonepcast
				     where idproductonepcast = rec_modelo.idproducto;
				 
				 end if;
				
--				 update traking.mct_ordentrabajo
--				    set fechafundicionmodelo = rec_modelo.fechafundicion,
--				        fechafundicioncal = rec_modelo.fechafundicion + interval '2 days'
--				  where traking.mct_ordentrabajo.idordentrabajo = rec_modelo.idordentrabajo
--				    and traking.mct_ordentrabajo.fechafundicioncal is null;
				
				 select count(*)
				   into sp_tienedefecto
				   from traking.mct_defectofundicion a
				  where a.idordentrabajo = rec_modelo.idordentrabajo;
				     
		         item 					:= rec_modelo.item;
		         idordentrabajo 		:= rec_modelo.idordentrabajo;
		         siglafamilia 			:= rec_modelo.siglafamilia;
		         --,producto 				:= rec_modelo.producto;
		         producto				:= sp_nombreproducto;
		         nombrecliente 			:= rec_modelo.nombrecliente; 
		         responsablefundicion 	:= rec_modelo.responsablefundicion;
		         fechafundicion 		:= rec_modelo.fechafundicion;
		         --fechafundicion			:= rec_modelo.fechafundicion + interval '2 days';
		         nombreparte 			:= rec_modelo.nombreparte;
		         plano 					:= rec_modelo.plano;
		         diasfund 				:= rec_modelo.diasfund;
		         diascliente 			:= rec_modelo.diascliente;
		         diastm 				:= rec_modelo.diastm;
		         faltantes 				:= rec_modelo.faltantes;
		         nombretipoorden 		:= rec_modelo.nombretipoorden;
		         nombrefamilia 			:= rec_modelo.nombrefamilia;
		         fechaentregatm 		:= rec_modelo.fechaentregatm;
		         fechaentregaclte 		:= rec_modelo.fechaentregaclte;
		         idmodalidadcreacion 	:= rec_modelo.idmodalidadcreacion;
		         nombreusuario 			:= rec_modelo.nombreusuario;
		         flagfacturacion 		:= rec_modelo.flagfacturacion;
		         idchecklistinftec 		:= rec_modelo.idchecklistinftec;
		         cantidadtotal 			:= rec_modelo.cantidadtotal;
		         recepcionada 			:= rec_modelo.recepcionada;
		         tienedefecto			:= sp_tienedefecto;
		         
		 
		         return next;
         
			end loop;
			
	
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistprogramafundicionsdetallecalendariomodelocolada(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1541 (class 1255 OID 17288)
-- Name: evtlistprogramafundicionsresumen(bigint, bigint, bigint, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistprogramafundicionsresumen(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) RETURNS TABLE(item bigint, idordentrabajo bigint, nombretipoorden character varying, producto character varying, nombrecliente character varying, nombreusuario character varying, fechaentregaclte character varying, diascliente bigint, avancefund numeric, avancemec numeric, montototal bigint, fechaentregacltecal timestamp without time zone, totalpieza bigint, totalrecep bigint, tienedefecto bigint)
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;
	rec1      			    record;
    rec_lcc      			RECORD;
	sp_sumatotallcc			integer;
	sp_liberadascc			integer;
	sp_canthr				integer;
    sp_avance				numeric;
   
    sp_cantidad_fu			integer;
    sp_codigoqr_fu			varchar;
	sp_recept_fu			integer;
    sp_avance_fu			numeric;
   
    ultimodia				varchar;
    ano						varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					integer;
    parte2					integer;
    corte                   integer;
    sp_total				integer;
    sp_totrecep				integer;
   
    sp_tienedefecto			bigint;
   	     		
begin
		 
	fechadesde			:= '';
    fechahasta			:= '';
    parte1				:= 0;
    parte2				:= 0;
    corte				:= 0;
    sp_tienedefecto		:= 0;
   
	if (periodos != '-1') then

		select to_char(now(),'yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		fechahasta	:= ano||'-'||mes||'-'||ultimodia;
		
		FOR rec1 IN (   
						
		          select ROW_NUMBER() OVER (ORDER BY tabla.fechaentregaclte asc, tabla.ot asc) AS item,
		                 tabla.ot,
		                 tabla.mec,
		                 tabla.idfamilia,
		                 tabla.sigla,
		                 tabla.producto,
		                 tabla.nombrecorto,
		                 tabla.nombre, 
		                 to_char(tabla.fechaentregaclte, 'dd-mm-yyyy') as fechaentregaclte ,
		                 tabla.fechaentregaclte as fechaentregacltecal,
		                 cast(to_char(tabla.fechaentregaclte,'dd') as integer) as dia,
		                 tabla.dias,
		                 tabla.avancefund,
		                 tabla.avancemec,
		                 tabla.monto
		            from (
					select a.idordentrabajo as ot,
					       0 as mec,
					       a.idfamilia,					       
						   d.sigla||'_'||e.sigla as sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   b.nombrecorto ,
						   j.nombre ,
						   a.fechafaceclte as fechaentregaclte,				       
						   cast(date_part('day', fechafaceclte - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(a.montorepfab)                                         as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia in (idfamilysB, idfamilysR)
				       and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.checklistvalido = true
					   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by a.idordentrabajo ,
					       d.sigla||'_'||e.sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar),
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar)				         
				union 
					select a.idordentrabajo  as ot,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_CON' as sigla,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       'SEBASTIAN CUADRA' as nombre,
					       a.fechafundicion2 as fechaentregaclte,
					       cast(date_part('day', a.fechafundicion2 - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDC
					 where a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechafundicion2 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            k.idesmecanizado ,
					            a.idfamilia,
					 	        e.sigla||'_CON',
								e.nombrefamilia ,
								c.nombreproducto,
								b.nombrecorto ,
								cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechafundicion2 - current_date) as bigint)
				union 
					select a.idordentrabajo  as ot,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_SIN' as sigla,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       j.nombre as nombre,
					       a.fechaentrega as fechaentregaclte,
					       cast(date_part('day', a.fechaentrega - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDS
					 where a.idordentrabajo >= 30000
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechaentrega >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            a.idfamilia,
					            k.idesmecanizado ,
					 	        e.sigla||'_SIN',
								e.nombrefamilia ,
								c.nombreproducto,
								b.nombrecorto ,
								j.nombre,
								cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechaentrega - current_date) as bigint)								
						 ) as tabla
						   						   
					)
	     		loop 
		     		
		     		sp_total	:= 0;
    				sp_totrecep	:= 0;

		     		-- Saca totales piezas y totales recepcionados
		     		if ( rec1.idfamilia = 8) then 
		     		
		     			sp_total	:= 1;
		     		    
		     		else 
		     		
		     		    select coalesce (sum(cantidad) , 0)
		     		      into sp_total
		     		      from mct_ordentrabajorepuesto a 
		     		     where a.idordentrabajo = rec1.ot;
		     		
			     		select coalesce (sum(cantidad) , 0)
		     		      into sp_totrecep 
		     		      from mct_checklistinftecrecept a
		     		     where a. idordentrabajo = rec1.ot;
		     		    
		     		end if;
		     	
		     		-- Acumula Totales parte1 y part2 del mes
		     		
		     	
		     	    if (rec1.dia > 15 ) then

		     	       if ( corte = 0 and parte1 > 0) then
		     	       
				     	     item 				:= 0; 
					         idordentrabajo 	:= 0; 
					         nombretipoorden 	:= 0; 
					         producto 			:= 'TOTAL'; 
					         nombrecliente 		:= 0;
					         nombreusuario 		:= 0;
					         fechaentregaclte 	:= 0;
					         fechaentregacltecal:= null;
					         diascliente 		:= 0;
					         avancefund			:= 0;
					         avancemec			:= 0;
					         montototal 		:= parte1;
			         		 totalpieza			:= 0;
         					 totalrecep			:= 0;
         					 tienedefecto		:= 0;
         					
					         corte				:= 1;
					        
				     		 return next;		
				     		
				     		 parte2	 := parte2 + rec1.monto;
		     	       
				       else
		     	       
		     	       		 parte2	 := parte2 + rec1.monto;
		     	       		
		     	       end if;

			     		 
		     	    
			     	else
			     		parte1	 := parte1 + rec1.monto;
		     	    end if;
		     	   
				    -- calcula avance mecanizado	
		     	    sp_sumatotallcc  := 0;
				   			   
				    FOR rec_lcc IN (   
								select distinct b.idhojarutatemp
								  from mct_movimientoordentrabajo a,
								       mct_hojaruta b
								 where a.codigoaccion   = 'L_CC'
							       and a.idordentrabajo = rec1.ot
							       and a.idhojaruta     = b.idhojaruta 
								)
					     loop 	
	
					     	sp_liberadascc	:= 0;
									   
					     	select coalesce (sum(cantidad),0)
					  	      into sp_liberadascc
				 		      from mct_hojarutatemp
						     where idhojarutatemp = rec_lcc.idhojarutatemp
						       and idboleano = 1
				               and idareaclasificacion in (0,1,2,3,4,5);
							     
							sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
							           
					END LOOP;
					  		
					sp_sumatotallcc := sp_sumatotallcc * 100;
					-- hasta aca el nuevo calculo
			   			  
					-- aca sacamos la cantidad de piezas totales
					select coalesce ( sum(a.cantidad), 0)
					  into sp_canthr
					  from mct_hojarutatemp a
					 where a.idordentrabajo = rec1.ot
					   and a.idboleano = 1
					   and a.idareaclasificacion in (0,1,2,3,4,5);
						     
					-- aca sacamos la cantidad de piezas liberadas de control de calidad
					select count(*)  
				      into sp_liberadascc
				      from mct_movimientoordentrabajo a
				     where a.codigoaccion   = 'L_CC'
				 	   and a.idordentrabajo = rec1.ot; 
						      
						if ( sp_canthr = 0) then
						     sp_avance := 0;
					    else
							 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			            end if;		
			           

					-- Fundicion
					-- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(a.cantidad), 0),
						          a.codigoqr
						     into sp_cantidad_fu,
						          sp_codigoqr_fu
						     from mct_checklistinftec a
						    where a.tipotrabajostd = 'FAB_FU'
						      and a.idordentrabajo = rec1.ot
						      group by a.codigoqr, a.fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0) * 100
						     into sp_recept_fu
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_fu; 
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;

				     select count(*)
				       into sp_tienedefecto
				       from traking.mct_defectofundicion a
				      where a.idordentrabajo = rec1.ot;
						  
			         item 				:= rec1.item; 
			         idordentrabajo 	:= rec1.ot; 
			         nombretipoorden 	:= rec1.sigla; 
			         producto 			:= rec1.producto; 
			         nombrecliente 		:= rec1.nombrecorto;
			         nombreusuario 		:= rec1.nombre;
			         fechaentregaclte 	:= rec1.fechaentregaclte;
			         fechaentregacltecal:= rec1.fechaentregacltecal;
			         diascliente 		:= rec1.dias;
			         --avancefund 		:= rec1.avancefund;
			         avancefund			:= sp_avance_fu;
			         --avancemec 			:= rec1.avancemec;

			         avancemec			:= sp_avance;
			         if ( rec1.idfamilia = 11 and rec1.mec = 2) then
			             avancemec		:= 999;
			         end if;
			        
			         montototal 		:= rec1.monto;
			         totalpieza			:= sp_total;
         			 totalrecep			:= sp_totrecep;
         			 tienedefecto		:= sp_tienedefecto;
         
		     		return next;
			       	       
	     		end loop;
	     	
	     	    item 				:= 0; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
			    fechaentregacltecal := null;
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2;
			    totalpieza			:= 0;
         		totalrecep			:= 0;
         	    tienedefecto		:= 0;
		         
				return next;
			
	     	    item 				:= -1; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
			    fechaentregacltecal := null;
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1 + parte2;
			    totalpieza			:= 0;
         		totalrecep			:= 0;
         	    tienedefecto		:= 0;
         	
				return next;			
			           
	else
	
		FOR rec1 IN (   
						
		          select ROW_NUMBER() OVER (ORDER BY tabla.fechaentregaclte asc, tabla.ot asc) AS item,
		                 tabla.ot,
		                 tabla.mec,
		                 tabla.idfamilia,
		                 tabla.sigla,
		                 tabla.producto,
		                 tabla.nombrecorto,
		                 tabla.nombre, 
		                 to_char(tabla.fechaentregaclte, 'dd-mm-yyyy') as fechaentregaclte ,
		                 tabla.fechaentregaclte as fechaentregacltecal ,
		                 cast(to_char(tabla.fechaentregaclte,'dd') as integer) as dia,
		                 tabla.dias,
		                 tabla.avancefund,
		                 tabla.avancemec,
		                 tabla.monto
		            from (
					select a.idordentrabajo as ot,
					       0 as mec,
					       a.idfamilia,					       
						   d.sigla||'_'||e.sigla as sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   b.nombrecorto ,
						   j.nombre ,
						   a.fechafaceclte as fechaentregaclte,				       
						   cast(date_part('day', fechafaceclte - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(a.montorepfab)                                         as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia in (idfamilysB, idfamilysR)
				       and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.checklistvalido = true
					   and (a.fechafaceclte >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by a.idordentrabajo ,
					       d.sigla||'_'||e.sigla,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar),
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar)				         
				union 
					select a.idordentrabajo  as ot,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_CON' as sigla,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       'SEBASTIAN CUADRA' as nombre,
					       a.fechafundicion2 as fechaentregaclte,
					       cast(date_part('day', a.fechafundicion2 - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDC
					 where a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechafundicion2 >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            k.idesmecanizado ,
					            a.idfamilia,
					 	        e.sigla||'_CON',
								e.nombrefamilia ,
								c.nombreproducto,
								b.nombrecorto ,
								cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechafundicion2 - current_date) as bigint)
				union 
					select a.idordentrabajo  as ot,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_SIN' as sigla,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       j.nombre as nombre,
					       a.fechaentrega as fechaentregaclte,
					       cast(date_part('day', a.fechaentrega - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDS
					 where a.idordentrabajo >= 30000
					   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   and a.idfamilia       in (11, idfamilysO)
					   and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechaentrega >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            a.idfamilia,
					            k.idesmecanizado ,
					 	        e.sigla||'_SIN',
								e.nombrefamilia ,
								c.nombreproducto,
								b.nombrecorto ,
								j.nombre,
								cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechaentrega - current_date) as bigint)								
						 ) as tabla
						   						   
					)
	     		loop 

		     		sp_total	:= 0;
    				sp_totrecep	:= 0;

		     		-- Saca totales piezas y totales recepcionados
		     		if ( rec1.idfamilia = 8) then 
		     		
		     			sp_total	:= 1;
		     		    
		     		else 
		     		
		     		    select coalesce (sum(cantidad) , 0)
		     		      into sp_total
		     		      from mct_ordentrabajorepuesto a 
		     		     where a.idordentrabajo = rec1.ot;
		     		
			     		select coalesce (sum(cantidad) , 0)
		     		      into sp_totrecep 
		     		      from mct_checklistinftecrecept a
		     		     where a. idordentrabajo = rec1.ot;
		     		    
		     		end if;
		     	
		     	    if (rec1.dia > 15 ) then

		     	       if ( corte = 0 and parte1 > 0 ) then
		     	       
				     	     item 				:= 0; 
					         idordentrabajo 	:= 0; 
					         nombretipoorden 	:= 0; 
					         producto 			:= 'TOTAL'; 
					         nombrecliente 		:= 0;
					         nombreusuario 		:= 0;
					         fechaentregaclte 	:= 0;
					         fechaentregacltecal:= null;
					         diascliente 		:= 0;
					         avancefund			:= 0;
					         avancemec			:= 0;
					         montototal 		:= parte1;
			    			 totalpieza			:= 0;
         	    			 totalrecep			:= 0;
         	    			 tienedefecto		:= 0;
		         
					         corte				:= 1;
					        
				     		 return next;	
				     		
				     		 parte2	 := parte2 + rec1.monto;
		     	       
				       else
		     	       
		     	       		 parte2	 := parte2 + rec1.monto;
		     	       		
		     	       end if;

			     		 
		     	    
			     	else
			     		parte1	 := parte1 + rec1.monto;
		     	    end if;
		     	   
				    -- calcula avance mecanizado	
		     	    sp_sumatotallcc  := 0;
				   			   
				    FOR rec_lcc IN (   
								select distinct b.idhojarutatemp
								  from mct_movimientoordentrabajo a,
								       mct_hojaruta b
								 where a.codigoaccion   = 'L_CC'
							       and a.idordentrabajo = rec1.ot
							       and a.idhojaruta     = b.idhojaruta 
								)
					     loop 	
	
					     	sp_liberadascc	:= 0;
									   
					     	select coalesce (sum(cantidad),0)
					  	      into sp_liberadascc
				 		      from mct_hojarutatemp
						     where idhojarutatemp = rec_lcc.idhojarutatemp
						       and idboleano = 1
				               and idareaclasificacion in (0,1,2,3,4,5);
							     
							sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
							           
					END LOOP;
					  		
					sp_sumatotallcc := sp_sumatotallcc * 100;
					-- hasta aca el nuevo calculo
			   			  
					-- aca sacamos la cantidad de piezas totales
					select coalesce ( sum(a.cantidad), 0)
					  into sp_canthr
					  from mct_hojarutatemp a
					 where a.idordentrabajo = rec1.ot
					   and a.idboleano = 1
					   and a.idareaclasificacion in (0,1,2,3,4,5);
						     
					-- aca sacamos la cantidad de piezas liberadas de control de calidad
					select count(*)  
				      into sp_liberadascc
				      from mct_movimientoordentrabajo a
				     where a.codigoaccion   = 'L_CC'
				 	   and a.idordentrabajo = rec1.ot; 
						      
						if ( sp_canthr = 0) then
						     sp_avance := 0;
					    else
							 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
			            end if;		
			           
			           
					-- Fundicion
					-- aca sacamos las piezas totales solicitadas a fundicion  
						   select coalesce ( sum(a.cantidad), 0),
						          a.codigoqr
						     into sp_cantidad_fu,
						          sp_codigoqr_fu
						     from mct_checklistinftec a
						    where a.tipotrabajostd = 'FAB_FU'
						      and a.idordentrabajo = rec1.ot
						      group by a.codigoqr, a.fecharequerida;
						     
						   -- aca sacamos el total de piezas recepcionadas   
						   select coalesce ( sum(cantidad), 0) * 100
						     into sp_recept_fu
						     from mct_checklistinftecrecept
						    where codigoqr = sp_codigoqr_fu; 
		
						   if (sp_cantidad_fu = 0 ) then
			                   sp_cantidad_fu := 1;
			               end if;
			              
						  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
						   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
						  
						   if ( sp_cantidad_fu = 0 ) then
						       sp_avance_fu = 999;
						   end if;

				     select count(*)
				       into sp_tienedefecto
				       from traking.mct_defectofundicion a
				      where a.idordentrabajo = rec1.ot;  
						  
			         item 				:= rec1.item; 
			         idordentrabajo 	:= rec1.ot; 
			         nombretipoorden 	:= rec1.sigla; 
			         producto 			:= rec1.producto; 
			         nombrecliente 		:= rec1.nombrecorto;
			         nombreusuario 		:= rec1.nombre;
			         fechaentregaclte 	:= rec1.fechaentregaclte;
			         fechaentregacltecal:= rec1.fechaentregacltecal;
			         diascliente 		:= rec1.dias;
			         --avancefund 		:= rec1.avancefund;
			         avancefund			:= sp_avance_fu;
			         --avancemec 			:= rec1.avancemec;

			         avancemec			:= sp_avance;
			         if ( rec1.idfamilia = 11 and rec1.mec = 2) then
			             avancemec		:= 999;
			         end if;
			        
			         montototal 		:= rec1.monto;
			         totalpieza			:= sp_total;
         			 totalrecep			:= sp_totrecep;
         			 tienedefecto		:= sp_tienedefecto;
         			
		     		return next;
			       	       
	     		end loop;	
	     	
	     	    item 				:= 0; 
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
			    fechaentregacltecal := null;
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte2;
			    totalpieza			:= 0;
         	    totalrecep			:= 0;
         	    tienedefecto		:= 0;
		         
				return next;	     	

				item 				:= -1;  
			    idordentrabajo 		:= 0; 
			    nombretipoorden 	:= ''; 
				producto 			:= ''; 
				nombrecliente 		:= '';
				nombreusuario 		:= '';
				fechaentregaclte 	:= '';
			    fechaentregacltecal := null;
				diascliente 		:= 0;
				avancefund			:= 0;
				avancemec			:= 0;
				montototal 			:= parte1 + parte2;
			    totalpieza			:= 0;
         	    totalrecep			:= 0;
         	    tienedefecto		:= 0;
		         
				return next;
			
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistprogramafundicionsresumen(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1229 (class 1255 OID 17290)
-- Name: evtlistprogramafundicionsresumen_borrar(bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
