CREATE FUNCTION traking.evtlistproveedorinsumocotizacion(idmarcas bigint) RETURNS TABLE(idproveedor bigint, nombreproveedor character varying, nombrecontacto character varying, telefono character varying, email character varying, direccion character varying, idmarca bigint, nombremarca character varying, cotizacion bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

	RETURN QUERY

		select a.idproveedor ,
		       b.nombreproveedor ,
		       b.nombrecontacto ,
		       coalesce (cast(b.telefono as varchar), 'S/T') ,
		       coalesce (b.email, 'S/E') ,
		       coalesce (b.direccion , 'S/D') ,
		       a.idmarca,
		       c.nombremarca,
		       nextval('mct_cotizacioninsumo_seq') 
		  from mct_proveedormarca a,
		       mct_proveedor b,
		       mct_marca c
		 where a.idmarca = idmarcas
		   and a.idproveedor = b.idproveedor 
		   and a.idmarca = c.idmarca ;

END
$$;


ALTER FUNCTION traking.evtlistproveedorinsumocotizacion(idmarcas bigint) OWNER TO postgres;

