CREATE FUNCTION traking.evtlistqueueroadmapmachine(machinenameup character varying) RETURNS TABLE(roadmap character varying, roadmapstatus character varying, orderroadmap integer)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
          select d.codhojaruta, c.nombreestado, a.orden
			from mct_colatrabajo a 
			left join     mct_maquina b on  a.idmaquina = b.idmaquina
			left join     mct_estadocolatrabajo c on a.idestadocolatrabajo = c.idestadocolatrabajo
			left join     mct_hojaruta d on a.idhojaruta = d.idhojaruta
			where b.nombremaquina = machinenameup
 		order by a.orden asc;
		  
	--	  select d.codhojaruta, c.nombreestado, a.orden
