--
-- TOC entry 1153 (class 1255 OID 17308)
-- Name: evtlistquotationbodypdf(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistquotationbodypdf(idworkoreders bigint) RETURNS TABLE(reparafabricaname character varying, worktypename character varying, partname character varying, quantity integer, totalunit integer, totalpart integer, sigla character varying, observation character varying, idworkorder bigint, blueprint character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
        select uno, tres, cuatro, cinco, seis, siete, ocho, nueve, diez, once
        from (
			select 
			       e.nombrereparafabrica 	as uno,
			       d.idparte 				as dos,
			       b.nombretipotrabajo 		as tres,
			       d.nombreparte 			as cuatro,
			       f.cantidad 				as cinco,
			       (d.costofabricacion * b.factorreparacion)/100 			as seis,
			       f.cantidad*(d.costofabricacion * b.factorreparacion)/100 as siete,
			       b.sigla 			as ocho,
			       a.observacion 	as nueve,
			       g.idordentrabajo as diez,
			       i.nombreplano  as once
			  from traking.mct_evaluacion a,
			       traking.mct_tipotrabajo b,
			       traking.mct_ordentrabajoparte c,
			       traking.mct_parte d,
			       traking.mct_reparafabrica e,
			       traking.mct_productoparte f,
			       traking.mct_ordentrabajo g,
			       traking.mct_boleano h,
			       traking.mct_plano i
			 where a.idtipotrabajo = b.idtipotrabajo
			   and a.idordentrabajoparte = c.idordentrabajoparte
			   and c.idparte = d.idparte
			   and a.idreparafabrica = e.idreparafabrica
			   and c.idparte = f.idparte
			   and c.idordentrabajo = g.idordentrabajo
			   and f.idproducto = g.idproducto
			   and d.esprincipal = h.idboleano
			   and d.idplano = i.idplano 
			   and g.idordentrabajo = idworkoreders
	     union
			  select 'ZReparación' 					as uno,
			         (i.idcostogeneral * 1000000000) 	as dos,
		  	         'Reparacion' 			as tres,
				     i.nombrecostogeneral 	as cuatro,
				     1 						as cinco,
			         b.costogeneral 		as seis,
			 	     b.costogeneral 		as siete,
			 	     '' 					as ocho,
				     i.nombrecostogeneral 	as nueve,      
				     c.idordentrabajo 	as diez,
				     ''                 as once
				from traking.mct_costogeneral i,
			         traking.mct_costogeneralproducto b,
				     traking.mct_ordentrabajo c
			   where c.idordentrabajo = idworkoreders
			     and c.idproducto = b.idproducto
		   	     and b.idcostogeneral = i.idcostogeneral
		   	      ) as tab
		   	     order by dos asc;

END;
$$;


ALTER FUNCTION traking.evtlistquotationbodypdf(idworkoreders bigint) OWNER TO postgres;

--
-- TOC entry 990 (class 1255 OID 17309)
-- Name: evtlistquotationheadpdf(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistquotationheadpdf(idquotations bigint) RETURNS TABLE(idquotation bigint, quotationname character varying, idcustomer bigint, customername character varying, idproduct bigint, productname character varying, idordertype bigint, ordertypename character varying, amountnet bigint, discount bigint, idworkorder bigint, observation character varying, contact character varying, deliveryday bigint, idtransport bigint, idpaycondition bigint, payconditionname character varying, idfamily bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
			select a.idcotizacion,
			       a.nombrecotizacion,
			       a.idcliente,
			       b.nombrecliente,
			       a.idproducto,
			       c.nombreproducto,
			       a.idtipoorden,
			       d.nombretipoorden,
			       a.montoneto,
			       a.descuento,
			       a.idordentrabajo,
			       a.observacion,
			       b.contacto ,
			       a.diasentrega ,
			       a.idtransporte ,
			       a.idcondicionpago ,
			       e.nombrecondicionpago ,
			       g.idfamilia 
			  from traking.mct_cotizacion a,
			       traking.mct_cliente b,
			       traking.mct_producto c,
			       traking.mct_tipoorden d,
			       traking.mct_condicionpago e,			     
			       traking.mct_modelo f,
			       traking.mct_subfamilia g			       
			 where a.idcotizacion = idquotations
			   and a.idcliente = b.idcliente
			   and a.idproducto = c.idproducto
			   and a.idtipoorden = d.idtipoorden
			   and a.idcondicionpago = e.idcondicionpago
			   and c.idmodelo = f.idmodelo 
			   and f.idsubfamilia = g.idsubfamilia ;

END;
$$;


ALTER FUNCTION traking.evtlistquotationheadpdf(idquotations bigint) OWNER TO postgres;

--
-- TOC entry 1006 (class 1255 OID 17310)
-- Name: evtlistrecepcc_noliberado(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistrecepcc_noliberado() RETURNS TABLE(idordentrabajo bigint, codhojaruta character varying, idcomponente bigint, nombrecomponente character varying, nombreplano character varying, componentechecklist character varying, idhojaruta bigint, idcliente bigint, nombrecorto character varying, nombreordentrabajo character varying, fechafaceclte character varying, responsable character varying, tipoorden character varying, avancemecanizado integer, proudcto character varying, accion character varying)
    LANGUAGE plpgsql
    AS $$

declare
   
   
begin
	
	return QUERY
	
	select tabla.idordentrabajo, 
		   tabla.codhojaruta ,
		   tabla.idcomponente ,
		   tabla.nombrecomponente,
		   tabla.nombreplano ,
		   tabla.componentechecklist ,
		   tabla.idhojaruta ,
		   tabla.idcliente ,
		   tabla.nombrecorto  ,
		   tabla.nombreordentrabajo,
		   tabla.fechafaceclte,
		   tabla.responsable,
		   tabla.tipoorden,
		   tabla.avancemecanizado,
		   tabla.producto,
		   tabla.accion           
      from (
		select distinct a.idordentrabajo, 
		       a.codhojaruta ,
		       f.idcomponente ,
		       cast(g.nombrecomponente||' - '||f.textoadicional as varchar) as nombrecomponente,
		       f.nombreplano ,
		       f.componentechecklist ,
		       a.idhojaruta ,
		       c.idcliente ,
		       d.nombrecorto  ,
		       cast(c.nombreordentrabajo as varchar) as  nombreordentrabajo,
		       cast(to_char(c.fechafaceclte , 'dd-mm-yyyy') as varchar) as fechafaceclte,
		       h.nombre as responsable,
		       cast(i.sigla||'_'||j.sigla as varchar) as tipoorden,
		       cast(calcularavancemecanizado(a.idordentrabajo) as integer) as avancemecanizado,
		       cast(case 
				  when c.idfamilia = 11 then k.nombreproducto
				  else m.sigla||' '||l.nombremodelo||' '||n.nombreparam
			   end as varchar) as producto,
			   cast('CC' as varchar) as accion
		from mct_movimientoordentrabajo a 
		left join mct_ordentrabajo c on a.idordentrabajo = c.idordentrabajo 
		left join mct_cliente d on c.idcliente = d.idcliente 
		left join mct_detallehojarutatemp e on a.codhojaruta = e.codhojaruta 
		left join mct_hojarutatemp f on e.idhojarutatemp = f.idhojarutatemp 
		left join mct_componente g on f.idcomponente = g.idcomponente 
		left join mct_usuario h on c.idusuario = h.idusuario 
		left join mct_tipoorden i on c.idtipoorden = i.idtipoorden 
		left join mct_familia j on c.idfamilia = j.idfamilia 	
		left join mct_producto k on c.idproducto = k.idproducto	
		left join mct_modelo l on k.idmodelo = l.idmodelo 
		left join mct_subfamilia m on l.idsubfamilia = m.idsubfamilia 
		left join mct_etapaparam n on k.idetapaparam = n.idetapaparam 					       
		where c.idestadoorden >= 6 and c.idestadoorden < 9
		  and a.idordentrabajo = c.idordentrabajo
		  and a.codigoaccion = 'CC'
		  and not exists ( select 'x' from mct_movimientoordentrabajo b
		                    where a.codhojaruta = b.codhojaruta
		                      and b.codigoaccion in ('L_CC','R_TM'))
	union
		select distinct a.idordentrabajo, 
		       a.codhojaruta ,
		       f.idcomponente ,
		       cast(g.nombrecomponente||' - '||f.textoadicional as varchar) as nombrecomponente,
		       f.nombreplano ,
		       f.componentechecklist ,
		       a.idhojaruta ,
		       c.idcliente ,
		       d.nombrecorto  ,
		       cast(c.nombreordentrabajo as varchar) as  nombreordentrabajo,
		       cast(to_char(c.fechafaceclte , 'dd-mm-yyyy') as varchar) as fechafaceclte,
		       h.nombre as responsable,
		       cast(i.sigla||'_'||j.sigla as varchar) as tipoorden,
		       cast(calcularavancemecanizado(a.idordentrabajo) as integer) as avancemecanizado,
		       cast(case 
				  when c.idfamilia = 11 then k.nombreproducto
				  else m.sigla||' '||l.nombremodelo||' '||n.nombreparam
			   end as varchar) as producto,
			   cast('R_CC' as varchar) as accion
		from mct_movimientoordentrabajo a 
		left join mct_ordentrabajo c on a.idordentrabajo = c.idordentrabajo 
		left join mct_cliente d on c.idcliente = d.idcliente 
		left join mct_detallehojarutatemp e on a.codhojaruta = e.codhojaruta 
		left join mct_hojarutatemp f on e.idhojarutatemp = f.idhojarutatemp 
		left join mct_componente g on f.idcomponente = g.idcomponente 
		left join mct_usuario h on c.idusuario = h.idusuario 
		left join mct_tipoorden i on c.idtipoorden = i.idtipoorden 
		left join mct_familia j on c.idfamilia = j.idfamilia 	
		left join mct_producto k on c.idproducto = k.idproducto	
		left join mct_modelo l on k.idmodelo = l.idmodelo 
		left join mct_subfamilia m on l.idsubfamilia = m.idsubfamilia 
		left join mct_etapaparam n on k.idetapaparam = n.idetapaparam 					       
		where c.idestadoorden >= 6 and c.idestadoorden < 9
		  and a.idordentrabajo = c.idordentrabajo
		  and a.codigoaccion = 'R_CC'
		  and not exists ( select 'x' from mct_movimientoordentrabajo b
		                    where a.codhojaruta = b.codhojaruta
		                      and b.codigoaccion in ('L_CC','R_TM'))
        ) tabla
		order by tabla.accion asc, tabla.fechafaceclte asc , tabla.idordentrabajo asc;

END;
$$;


ALTER FUNCTION traking.evtlistrecepcc_noliberado() OWNER TO postgres;

--
-- TOC entry 1559 (class 1255 OID 17311)
-- Name: evtlistreciclaahorroapp_ciclo(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistreciclaahorroapp_ciclo(idworkorders bigint) RETURNS TABLE(reciclatotnum character varying, reciclatot character varying, ahorrototnum character varying, ahorrotot character varying, autonum character varying, auto character varying, arbolnum character varying, arbol character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_reciclado    integer;
    sp_tot_piezasr  integer;
    sp_tot_recic    integer;
   
    sp_suma_tot     numeric;
    sp_suma_rec     numeric;
    sp_suma_ahorro  numeric;

    rec1 	   		record;
   
BEGIN

	sp_reciclado   := 0;
	sp_tot_piezasr := 0; 
	sp_tot_recic   := 0;	 
	sp_suma_tot    := 0;
	sp_suma_rec    := 0;
	sp_suma_ahorro := 0;
	 
	  FOR rec1 IN (	  
				   select a.idordentrabajo ,
				          case
					          when idlineadiseno = 3 then 0 
					          when idlineadiseno in (1,2) then coalesce (b.tonelada, 4.5)
					      end as tonelada,
				          case
					          when idlineadiseno = 3 then 0 
					          when idlineadiseno in (1,2) then coalesce (b.pesototal, 4.5)
					      end as pesotot,
					      a.idproducto 
				          --coalesce (b.tonelada, 0) as tonelada,
				          --coalesce (b.pesototal, 0) as pesotot
				     from mct_ordentrabajo a,
				          mct_producto b 
				    where --a.idestadoorden in (6,7,8,9)
				     -- and a.idcliente = 6
				 	 -- and a.flagapp = 1
			 		 -- and a.idfamilia = 8
					   a.idproducto = b.idproducto
				      and a.idordentrabajo in (select otanterior from mct_relacionotciclo where ot = idworkorders)
				     -- and a.debaja != 1	
				     -- and a.ordencompra > 0
				     -- order by a.idordentrabajo desc
				      
	      
	        )
	  		loop  

		  		-- % de reciclaje
			    select coalesce (sum(cantidad),0)
			      into sp_tot_piezasr
				  from mct_checklistinftec mc 
				 where idordentrabajo = rec1.idordentrabajo
				   and upper(criterio) not in ('RPO')
				   and upper(nombreparte) not like '%CHAVE%'
				   and upper(nombreparte) not like '%RRAGO%'
				   and upper(nombreparte) not like '%CORTAGO%'
				   and upper(nombreparte) not like '%PERNO%'	
				   and upper(nombreparte) not like '%GOLILL%'		
				   and upper(REPLACE(nombreparte,'ó','o')) not ilike 'TAPON%'	
				   and upper(nombreparte) not like '%NIPL%'	;
				   
				select coalesce (sum(cantidad),0)
				  into sp_tot_recic
				  from mct_checklistinftec mc 
				 where idordentrabajo = rec1.idordentrabajo
				   and upper(criterio) not in ('FAB_PA', 'FAB_CA', 'RPO')
				   and upper(criterio) not like 'REM%';
	
				  
				sp_reciclado := 0;	
			    if ( rec1.pesotot > 0 and sp_tot_piezasr > 0) then
			    	sp_reciclado := coalesce (round( (sp_tot_recic * 100) / sp_tot_piezasr), 0);
			    end if;
		
			   	sp_suma_rec	 := 0;
			    
			    if ( rec1.pesotot > 0 and sp_tot_piezasr > 0) then
			         sp_suma_rec  := rec1.pesotot * round((sp_tot_recic * 100) / sp_tot_piezasr)/100::numeric;
			    else
			         sp_suma_rec  := 0;
			    end if;
			   
			    sp_suma_ahorro :=  coalesce(sp_suma_ahorro + sp_suma_rec, 0);
			   
			    sp_suma_tot  := sp_suma_tot::numeric + rec1.tonelada::numeric;
			    --reciclatot := cast(round(rec1.tonelada/1000,2) as varchar );
 
		
	  		end loop;

	  		reciclatotnum 	:= cast(round(sp_suma_ahorro) as varchar );		
	  		reciclatot 		:= trim(cast(to_char(round(sp_suma_ahorro),'999,999,999') as varchar ));		
	  		
			ahorrototnum  	:= cast(round(sp_suma_tot) as varchar );
			ahorrotot  		:= trim(cast(to_char(round(sp_suma_tot),'999,999,999') as varchar ));
			   
			autonum			:= cast(round(sp_suma_tot*0.25) as varchar );
			auto			:= trim(cast(to_char(round(sp_suma_tot*0.25),'999,999,999') as varchar ));			   
			   
			arbolnum		:= cast(round(sp_suma_tot)*2 as varchar );
			arbol			:= trim(cast(to_char(round(sp_suma_tot)*2,'999,999,999') as varchar ));	
			   
			RETURN next;
  
		
END;
$$;


ALTER FUNCTION traking.evtlistreciclaahorroapp_ciclo(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1714 (class 1255 OID 17312)
-- Name: evtlistregisterjobbyhr(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistregisterjobbyhr(roadmapcodes character varying) RETURNS TABLE(idregisterjob bigint, idmachine bigint, idsection bigint, idsubsection bigint, idactivity bigint, idaction bigint, actioncode character varying, idactivitystatus bigint, idmovetype bigint, tiemwork bigint, startdate text, starttime text, enddate text, endtime text, description character varying, idoperator bigint, operatorname character varying, codesection character varying, idclosemotive bigint, idclosecause bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		select a.idmovimientoordentrabajo ,
		       a.idmaquina ,
		       a.idseccion,
		       a.idsubseccion ,
		       a.idactividad ,
		       a.idaccion ,
		       a.codigoaccion ,
		       a.estadoactividad ,
		       a.idtipomovimiento ,
		       coalesce(a.tiempotrabajado , null, 0),
		       --DATE_PART('minute', fechatermino::timestamp - fechainicio::timestamp),
		       to_char(a.fechainicio,'dd-mm-yyyy') ,
		       to_char(a.fechainicio,'HH24:mi:ss') ,
		       to_char(a.fechatermino,'dd-mm-yyyy') ,
		       to_char(a.fechatermino,'HH24:mi:ss') ,
		       cast('' as varchar),
		       a.idoperador ,
		       b.nombreoperador ,
		       c.codigoseccion  ,
		       a.idmotivocierre ,
		       a.idcausacierre 
		from mct_movimientoordentrabajo  a,
		     mct_operador b,
		     mct_seccion c
		where codhojaruta = roadmapcodes
	      and estadoactividad = 1
	      and a.idoperador  = b.idoperador 
	      and a.idseccion  = c.idseccion ;

END;
$$;


ALTER FUNCTION traking.evtlistregisterjobbyhr(roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 2107 (class 1255 OID 17313)
-- Name: evtlistregisterjobbyhr_rtm(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistregisterjobbyhr_rtm(roadmapcodes character varying) RETURNS TABLE(idregisterjob bigint, idmachine bigint, idsection bigint, idsubsection bigint, idactivity bigint, idaction bigint, actioncode character varying, idactivitystatus bigint, idmovetype bigint, tiemwork bigint, startdate text, starttime text, enddate text, endtime text, description character varying, idoperator bigint, operatorname character varying, codesection character varying, idclosemotive bigint, idclosecause bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		select a.idmovimientoordentrabajo ,
		       a.idmaquina ,
		       a.idseccion,
		       a.idsubseccion ,
		       a.idactividad ,
		       a.idaccion ,
		       a.codigoaccion ,
		       a.estadoactividad ,
		       a.idtipomovimiento ,
		       coalesce(a.tiempotrabajado , null, 0),
		       --DATE_PART('minute', fechatermino::timestamp - fechainicio::timestamp),
		       to_char(a.fechainicio,'dd-mm-yyyy') ,
		       to_char(a.fechainicio,'HH24:mi:ss') ,
		       to_char(a.fechatermino,'dd-mm-yyyy') ,
		       to_char(a.fechatermino,'HH24:mi:ss') ,
		       cast('' as varchar),
		       a.idoperador ,
		       b.nombreoperador ,
		       c.codigoseccion  ,
		       a.idmotivocierre ,
		       a.idcausacierre 
		from mct_movimientoordentrabajo  a,
		     mct_operador b,
		     mct_seccion c
		where codhojaruta = roadmapcodes
	      and a.idoperador = b.idoperador 
	      and a.idseccion  = c.idseccion 
	      and a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
		                                      from mct_movimientoordentrabajo b 
		                                     where b.idhojaruta = a.idhojaruta );

END;
$$;


