--
-- TOC entry 2190 (class 1255 OID 17314)
-- Name: evtlistregistroarmadodesarme(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistregistroarmadodesarme(tipotareas bigint) RETURNS TABLE(item bigint, idot bigint, evaluador character varying, nombreproducto character varying, nombrecliente character varying, fechacreacion character varying, estadoproceso character varying, operadoresml character varying, operadoresma character varying, nombresml character varying, nombres character varying, cantidad bigint, iniciotarea character varying, diasinicio bigint, terminotarea character varying, diastarea bigint, kpitarea bigint, colorkpi character varying, fechaentregaclte character varying)
    LANGUAGE plpgsql
    AS $$
declare	 

		sp_jason	    varchar;
		sp_lastacti 	VARCHAR;
	    sp_estadolast   integer;
		rec1 			record;
		rec_ope			record;

        sp_lista        varchar;
        sp_listafin		varchar;

		sp_inicio		timestamp;
		sp_termino		timestamp;

        sp_cantope		integer;
        sp_kpi			integer;
		sp_colorestado	varchar;

        sp_abiertos     integer;
        sp_cerrados     integer;

        sp_listaML		varchar;
		sp_listaMA		varchar;

        sp_pausado		bigint;

        sp_nombresML	varchar;
		sp_nombres		varchar;

	   
begin

	
	if (tipotareas = 1 ) then -- esto para armado

		 FOR rec1 IN ( 
		
					select row_number() over (order by a.fechafaceclte asc ) as item,
                           a.idordentrabajo ,
					       j.nombre,
						   case 
							  when a.idfamilia = 11 then c.nombreproducto
							  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as producto,
					       b.nombrecorto ,
					       a.fechacreacion	,
                           a.fechafaceclte		       				            
					  from mct_ordentrabajo a ,
					 	   mct_cliente b,
				 		   mct_producto c,
					       mct_modelo g,
					       mct_subfamilia h,
					       mct_etapaparam i,
					       mct_usuario j
					 where a.idestadoorden >= 6 and a.idestadoorden < 9 
					   and a.idordentrabajo >= 30000
                       and a.idordentrabajo not in (33412, 33499, 33413, 33393, 33519,33588)
--and a.idordentrabajo in (
--33547,33548,33430,33397,33308,33559,33560,33563,33564,33583,33591,33601,33609,33610
--)
					   and a.idfamilia in (8,15)
					   and a.idtipoorden in (1,2,3)
					   and a.debaja != 1
					   and (a.fechacreacion >= '2023-01-01' or idordentrabajo in (30968))
					   and a.idcliente = b.idcliente 
					   and a.idproducto = c.idproducto 
					   and c.idmodelo = g.idmodelo 
					   and g.idsubfamilia = h.idsubfamilia 
					   and c.idetapaparam = i.idetapaparam 
					   and a.idusuario = j.idusuario 
                    order by a.fechafaceclte asc	 
			)
				
			Loop
	
	
				select min(a.fechainicio),
				       max(a.fechatermino)
                  into sp_inicio,
                       sp_termino
				  from mct_movimientoordentrabajo a
				  left join mct_operador b on a.idoperador = b.idoperador
				 where a.idordentrabajo = rec1.idordentrabajo
				   and a.idaccion in (165); -- Armado = 165, Desarme = 173

				sp_cantope		:= 0;
				sp_lista 		:= '';
                sp_listafin		:= '';
                sp_kpi			:= 0;
				sp_colorestado	:= '';

                sp_abiertos     := 0;
        		sp_cerrados     := 0;

                sp_listaML		:= '';
		        sp_listaMA		:= '';

                sp_pausado		:= 0;

				sp_nombresML	:= '';
				sp_nombres		:= '';
								   
				FOR rec_ope IN (   
						select b.nombreoperador ,
						       b.iniciales,
                               a.estadoactividad 	,
                               a.terminoarmadodesarme ,
                               a.iniciaarmadodesarme,
							   b.nombreoperador
						  from mct_movimientoordentrabajo a
						  left join mct_operador b on a.idoperador = b.idoperador
						 where a.idordentrabajo = rec1.idordentrabajo
						   and a.idaccion in (165) -- Armado, Desarme = 173
                           --and a.estadoactividad = 1
                          order by a.estadoactividad desc, a.terminoarmadodesarme desc
						)
				    loop 	
								
						sp_listafin 	:= rec_ope.iniciales||','||sp_listafin;

						if (rec_ope.terminoarmadodesarme = 2) then
							sp_pausado	:= 1;
                        else
                            sp_pausado	:= 0;
 						end if;

                        if (rec_ope.estadoactividad = 1) then
							
							sp_abiertos	:= sp_abiertos + 1;

							sp_cantope	:= sp_cantope + 1;	

                            if (rec_ope.iniciaarmadodesarme is true) then
								sp_listaML 		:= rec_ope.iniciales||','||sp_listaML;
                                sp_nombresML 	:= rec_ope.nombreoperador||','||sp_nombresML;
                            else
								sp_lista 	:= rec_ope.iniciales||','||sp_lista;
                                sp_nombres 	:= rec_ope.nombreoperador||','||sp_nombres;
                            end if;
					    	

                        elsif (rec_ope.estadoactividad = 2) then

 							sp_cerrados	:= sp_cerrados + 1;

                        end if;
									           
				END LOOP;

				if (sp_lista is null or sp_lista = '') then
					sp_lista	:= null;
				else
					sp_lista	:= cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
					sp_listafin := cast(substring(sp_listafin,1,length(sp_listafin)-1) as varchar);
					sp_listaML	:= cast(substring(sp_listaML,1,length(sp_listaML)-1) as varchar);

                    sp_nombresML:= cast(substring(sp_nombresML,1,length(sp_nombresML)-1) as varchar);
                    sp_nombres	:= cast(substring(sp_nombres,1,length(sp_nombres)-1) as varchar);
				end if;

				--sp_colorestado = 'btn-danger';
                sp_colorestado	:= 'red';
				if (sp_inicio is not null and sp_termino is not null) then
                   
                    if (sp_abiertos > sp_cerrados and sp_cerrados > 0) then
						--sp_colorestado	:= 'btn-warning';
                        sp_colorestado	:= 'orange';
						sp_termino		:= null;
                    elsif (sp_cerrados > sp_abiertos and sp_abiertos > 0) then
						--sp_colorestado	:= 'btn-warning';
                        sp_colorestado	:= 'orange';
						sp_termino		:= null;
                    elsif (sp_cerrados = sp_abiertos and sp_abiertos > 0 and sp_cerrados > 0) then
						--sp_colorestado	:= 'btn-warning';
                        sp_colorestado	:= 'orange';
						sp_termino		:= null;
					else 
						--sp_lista		:= sp_listafin;
						sp_listaML		:= null;
						--sp_colorestado	:= 'btn-success';
                        sp_colorestado	:= 'lightgreen';
						sp_cantope		:= 0;
						sp_lista		:= null;

                        sp_nombresML	:= null;
						sp_nombres		:= null;
                    end if;
					
				elsif (sp_inicio is not null and sp_termino is null) then
					--sp_colorestado	:= 'btn-warning';
                    sp_colorestado	:= 'orange';
				end if;
	
				if (sp_pausado = 1) then
					sp_colorestado	:= 'black';
				end if;

		        item 			:= rec1.item;
		        idot		 	:= rec1.idordentrabajo; 
		        evaluador 		:= rec1.nombre;
		        nombreproducto 	:= rec1.producto;
		        nombrecliente 	:= rec1.nombrecorto;
		        fechacreacion 	:= cast(to_char(rec1.fechacreacion, 'dd-mm-yyyy') as varchar);
		        estadoproceso 	:= sp_colorestado;
		        operadoresml 	:= sp_listaML;
                operadoresma 	:= sp_lista;
                nombresml	 	:= sp_nombresML;
                nombres	 		:= sp_nombres;
		        cantidad 		:= sp_cantope; 
		        iniciotarea 	:= cast(to_char(sp_inicio, 'dd-mm-yyyy') as varchar); 
		        diasinicio 		:= date_part('day', date(sp_inicio)::timestamp - date(rec1.fechacreacion)::timestamp );
		        terminotarea 	:= cast(to_char(sp_termino, 'dd-mm-yyyy') as varchar);
		        diastarea 		:= coalesce(date_part('day', date(sp_termino)::timestamp - date(sp_inicio)::timestamp ), 0);
		        kpitarea 		:= 5 - date_part('day', sp_termino - sp_inicio );
		        colorkpi 		:= 'green';
                fechaentregaclte 	:= cast(to_char(rec1.fechafaceclte, 'dd-mm-yyyy') as varchar);

				RETURN NEXT;
	
		END LOOP;


	else

		 FOR rec1 IN ( 
		
					select row_number() over (order by a.fechafaceclte asc ) as item,
                           a.idordentrabajo ,
					       j.nombre,
						   case 
							  when a.idfamilia = 11 then c.nombreproducto
							  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as producto,
					       b.nombrecorto ,
					       a.fechacreacion	,
                           a.fechafaceclte			       				            
					  from mct_ordentrabajo a ,
					 	   mct_cliente b,
				 		   mct_producto c,
					       mct_modelo g,
					       mct_subfamilia h,
					       mct_etapaparam i,
					       mct_usuario j
					 where a.idestadoorden < 3
					   and a.idordentrabajo >= 30000
                       and a.idordentrabajo not in (33659,33660)
					   and a.idfamilia in (8,15)
					   and a.idtipoorden = 1
					   and a.debaja != 1
					   and (a.fechacreacion >= '2023-01-01' or idordentrabajo in (30968))
					   and a.idcliente = b.idcliente 
					   and a.idproducto = c.idproducto 
					   and c.idmodelo = g.idmodelo 
					   and g.idsubfamilia = h.idsubfamilia 
					   and c.idetapaparam = i.idetapaparam 
					   and a.idusuario = j.idusuario 
                    order by a.fechafaceclte asc	 
			)
				
			Loop
	
	
				select min(a.fechainicio),
				       max(a.fechatermino)
                  into sp_inicio,
                       sp_termino
				  from mct_movimientoordentrabajo a
				  left join mct_operador b on a.idoperador = b.idoperador
				 where a.idordentrabajo = rec1.idordentrabajo
				   and a.idaccion in (173); -- Armado = 165, Desarme = 173

				sp_cantope		:= 0;
				sp_lista 		:= '';
				sp_listafin		:= '';
                sp_kpi			:= 0;
				sp_colorestado	:= '';

				sp_abiertos     := 0;
        		sp_cerrados     := 0;

                sp_listaML		:= '';
		        sp_listaMA		:= '';

                sp_pausado		:= 0;
								   
				FOR rec_ope IN (   
						select b.nombreoperador ,
						       b.iniciales,
                               a.estadoactividad 	,
                               a.terminoarmadodesarme ,
                               a.iniciaarmadodesarme,
							   b.nombreoperador
						from mct_movimientoordentrabajo a
						left join mct_operador b on a.idoperador = b.idoperador
						where a.idordentrabajo = rec1.idordentrabajo
                          --and a.estadoactividad = 1
						  and a.idaccion in (173) -- Armado, Desarme = 173
                     order by a.estadoactividad desc, a.terminoarmadodesarme desc
						)
				    loop 	
  
						sp_listafin 	:= rec_ope.iniciales||','||sp_listafin;

						if (rec_ope.terminoarmadodesarme = 2) then
							sp_pausado	:= 1;
                        else
                            sp_pausado	:= 0;
 						end if;

                        if (rec_ope.estadoactividad = 1) then
							
							sp_abiertos	:= sp_abiertos + 1;

							sp_cantope	:= sp_cantope + 1;	

                            if (rec_ope.iniciaarmadodesarme is true) then
								sp_listaML 		:= rec_ope.iniciales||','||sp_listaML;
                                sp_nombresML 	:= rec_ope.nombreoperador||','||sp_nombresML;
                            else
								sp_lista 	:= rec_ope.iniciales||','||sp_lista;
                                sp_nombres 	:= rec_ope.nombreoperador||','||sp_nombres;
                            end if;

                        elsif (rec_ope.estadoactividad = 2) then

 							sp_cerrados	:= sp_cerrados + 1;

                        end if;
								
															           
				END LOOP;

				if (sp_lista is null or sp_lista = '') then
					sp_lista	:= null;
				else
					sp_lista	:= cast(substring(sp_lista,1,length(sp_lista)-1) as varchar);
					sp_listafin := cast(substring(sp_listafin,1,length(sp_listafin)-1) as varchar);
					sp_listaML	:= cast(substring(sp_listaML,1,length(sp_listaML)-1) as varchar);

                    sp_nombresML:= cast(substring(sp_nombresML,1,length(sp_nombresML)-1) as varchar);
                    sp_nombres	:= cast(substring(sp_nombres,1,length(sp_nombres)-1) as varchar);
				end if;

				--sp_colorestado = 'btn-danger';
                sp_colorestado	:= 'red';
				if (sp_inicio is not null and sp_termino is not null) then
                   
                    if (sp_abiertos > sp_cerrados and sp_cerrados > 0) then
						--sp_colorestado	:= 'btn-warning';
                        sp_colorestado	:= 'orange';
						sp_termino		:= null;
                    elsif (sp_cerrados > sp_abiertos and sp_abiertos > 0) then
						--sp_colorestado	:= 'btn-warning';
                        sp_colorestado	:= 'orange';
						sp_termino		:= null;
                    elsif (sp_cerrados = sp_abiertos and sp_abiertos > 0 and sp_cerrados > 0) then
						--sp_colorestado	:= 'btn-warning';
                        sp_colorestado	:= 'orange';
						sp_termino		:= null;
					else 
						--sp_lista		:= sp_listafin;
						sp_listaML		:= null;
						--sp_colorestado	:= 'btn-success';
                        sp_colorestado	:= 'lightgreen';
						sp_cantope		:= 0;
						sp_lista		:= null;

                        sp_nombresML	:= null;
						sp_nombres		:= null;

                    end if;
					
				elsif (sp_inicio is not null and sp_termino is null) then
					--sp_colorestado	:= 'btn-warning';
                    sp_colorestado	:= 'orange';
				end if;
	
				if (sp_pausado = 1) then
					sp_colorestado	:= 'black';
				end if;

		        item 			:= rec1.item;
		        idot		 	:= rec1.idordentrabajo; 
		        evaluador 		:= rec1.nombre;
		        nombreproducto 	:= rec1.producto;
		        nombrecliente 	:= rec1.nombrecorto;
		        fechacreacion 	:= cast(to_char(rec1.fechacreacion, 'dd-mm-yyyy') as varchar);
		        estadoproceso 	:= sp_colorestado;
		        operadoresml 	:= sp_listaML;
                operadoresma 	:= sp_lista;
                nombresml	 	:= sp_nombresML;
                nombres	 		:= sp_nombres;
		        cantidad 		:= sp_cantope; 
		        iniciotarea 	:= cast(to_char(sp_inicio, 'dd-mm-yyyy') as varchar); 
		        diasinicio 		:= date_part('day', date(sp_inicio)::timestamp - date(rec1.fechacreacion)::timestamp );
		        terminotarea 	:= cast(to_char(sp_termino, 'dd-mm-yyyy') as varchar);
		        diastarea 		:= coalesce(date_part('day', date(sp_termino)::timestamp - date(sp_inicio)::timestamp ), 0);
		        kpitarea 		:= 5 - date_part('day', sp_termino - sp_inicio );
		        colorkpi 		:= 'green';
                fechaentregaclte 	:= cast(to_char(rec1.fechafaceclte, 'dd-mm-yyyy') as varchar);

				RETURN NEXT;
	
		END LOOP;

	end if;
	 		 
	
END;
$$;


ALTER FUNCTION traking.evtlistregistroarmadodesarme(tipotareas bigint) OWNER TO postgres;

--
-- TOC entry 2162 (class 1255 OID 17316)
-- Name: evtlistregistroarmadodesarmeonline(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistregistroarmadodesarmeonline(tipotareas bigint) RETURNS TABLE(item bigint, prioridad bigint, fechaentregaclte character varying, idot bigint, nombreproducto character varying, evaluador character varying, nombrecliente character varying, fechacreacion character varying, iniciodesarme character varying, terminodesarme character varying, bombapiso character varying, tiempodesarme character varying, statusdesarme character varying, colorstatusdesarme character varying, fecha100mecanizado character varying, inicioarmado character varying, terminoarmado character varying, bombaproceso character varying, tiempoarmado character varying, statusarmado character varying, colorstatusarmado character varying)
    LANGUAGE plpgsql
    AS $$
declare	 

		sp_jason	    varchar;
		rec1 			record;

		sp_inicioar			timestamp;
		sp_terminoar		timestamp;

		sp_iniciodes		timestamp;
		sp_terminodes		timestamp;
        sp_fecha_autoriza	timestamp;

		sp_colorestadodes	varchar;
        sp_colorestadoar	varchar;

		sp_textoestadodes	varchar;
        sp_textoestadoar	varchar;

		sp_estado_armado	bigint;
		sp_estado_desarme	bigint;

        sp_pausado			bigint;
	   
begin

	 FOR rec1 IN ( 
	
             select count(*),
                    row_number() over (order by tab.fechacreacion desc ) as item,
                    tab.idordentrabajo,
                    tab.iniciales,
                    tab.producto,
                    tab.nombrecorto,
                    tab.fechacreacion,
                    tab.fechafaceclte ,
                    tab.fecha100tm
               from (
						select a.idordentrabajo ,
						       j.iniciales,
							   case 
								  when a.idfamilia = 11 then c.nombreproducto
								  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
							   end as producto,
						       b.nombrecorto ,
						       a.fechacreacion	,
	                           a.fechafaceclte	,
                               a.fecha100tm	       				            
						  from mct_ordentrabajo a ,
						 	   mct_cliente b,
					 		   mct_producto c,
						       mct_modelo g,
						       mct_subfamilia h,
						       mct_etapaparam i,
						       mct_usuario j
						 where a.idestadoorden >= 6 and a.idestadoorden < 9 
						   and a.idordentrabajo >= 30000
	                       and a.idordentrabajo not in (33412, 33499, 33413, 33393, 33519,33588)
						   and a.idfamilia in (8,15)
						   and a.idtipoorden in (1,2,3)
						   and a.debaja != 1
						   and (a.fechacreacion >= '2023-01-01' or idordentrabajo in (30968))
						   and a.idcliente = b.idcliente 
						   and a.idproducto = c.idproducto 
						   and c.idmodelo = g.idmodelo 
						   and g.idsubfamilia = h.idsubfamilia 
						   and c.idetapaparam = i.idetapaparam 
						   and a.idusuario = j.idusuario  
	             union
						select a.idordentrabajo ,
						       j.iniciales,
							   case 
								  when a.idfamilia = 11 then c.nombreproducto
								  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
							   end as producto,
						       b.nombrecorto ,
						       a.fechacreacion	,
	                           a.fechafaceclte	,
                               a.fecha100tm	  			       				            
						  from mct_ordentrabajo a ,
						 	   mct_cliente b,
					 		   mct_producto c,
						       mct_modelo g,
						       mct_subfamilia h,
						       mct_etapaparam i,
						       mct_usuario j
						 where a.idestadoorden < 3
						   and a.idordentrabajo >= 30000
	                       and a.idordentrabajo not in (33659,33660)
						   and a.idfamilia in (8,15)
						   and a.idtipoorden = 1
						   and a.debaja != 1
						   and (a.fechacreacion >= '2023-01-01' or idordentrabajo in (30968))
						   and a.idcliente = b.idcliente 
						   and a.idproducto = c.idproducto 
						   and c.idmodelo = g.idmodelo 
						   and g.idsubfamilia = h.idsubfamilia 
						   and c.idetapaparam = i.idetapaparam 
						   and a.idusuario = j.idusuario 
                  ) tab
                  where not exists (select 'x' from traking.mct_registroarmadodesarmeonline a where a.idot = tab.idordentrabajo)
                  group by tab.idordentrabajo,
						   tab.iniciales,
                           tab.producto,
                           tab.nombrecorto,
                           tab.fechacreacion,
                           tab.fechafaceclte,
                           tab.fecha100tm
                  order by tab.fechacreacion desc
		)				
		Loop

			select min(a.fechainicio),
			       max(a.fechatermino)
              into sp_iniciodes,
                   sp_terminodes
			  from mct_movimientoordentrabajo a
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion in (173); -- Armado = 165, Desarme = 173

			select min(a.fechainicio),
			       max(a.fechatermino)
              into sp_inicioar,
                   sp_terminoar
			  from mct_movimientoordentrabajo a
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion in (165); -- Armado = 165, Desarme = 173

			--sp_colorestado		:= '';
            sp_estado_armado	:= 0;
            sp_estado_desarme	:= 0;
            sp_pausado			:= 0;
            sp_fecha_autoriza	:= null;

            select fecha_real_termino
              into sp_fecha_autoriza
              from traking.mct_progavisos
             where idordentrabajo = rec1.idordentrabajo
               and idsla = 5;
				
			select a.terminoarmadodesarme
              into sp_estado_desarme
			  from mct_movimientoordentrabajo a
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion in (173); -- Armado, Desarme = 173	
			     
			select a.terminoarmadodesarme
              into sp_estado_armado
			  from mct_movimientoordentrabajo a
			 where a.idordentrabajo = rec1.idordentrabajo
			   and a.idaccion in (165); -- Armado, Desarme = 173

			-- Status armado
            sp_textoestadoar	:= '';
            if (sp_inicioar is null and sp_terminoar is null) then
				sp_textoestadoar	:= 'Sin Movimiento';
                sp_colorestadoar	:= 'orangered';
			elsif (sp_inicioar is not null and sp_terminoar is null) then
				sp_textoestadoar	:= 'En Armado';
                sp_colorestadoar	:= 'yellow';
            elsif (sp_inicioar is not null and sp_terminoar is not null) then
				sp_textoestadoar	:= 'Armada';
                sp_colorestadoar	:= 'lightgreen';
			else
                sp_colorestadoar	:= 'white';
			end if;

			if (sp_estado_armado = 2) then
				sp_textoestadoar	:= 'En Pausa Armado';
                sp_colorestadoar	:= 'yellow';
			end if;

			-- Status desarme
			sp_textoestadodes	:= '';
            if (sp_iniciodes is null and sp_terminodes is null) then
				sp_textoestadodes	:= 'Sin Movimiento';
                sp_colorestadodes	:= 'orangered';
			elsif (sp_iniciodes is not null and sp_terminodes is null) then
				sp_textoestadodes	:= 'En Desarme';
                sp_colorestadodes	:= 'yellow';
            elsif (sp_iniciodes is not null and sp_terminodes is not null) then
				sp_textoestadodes	:= 'Desarmada';
                sp_colorestadodes	:= 'lightgreen';
			else
                sp_colorestadodes	:= 'white';
			end if;

			if (sp_estado_desarme = 2) then
				sp_textoestadodes	:= 'En Pausa Desarme';
                sp_colorestadodes	:= 'yellow';
			end if;

	        item 				:= rec1.item;
            prioridad			:= rec1.item;
	        fechaentregaclte 	:= cast(to_char(rec1.fechafaceclte, 'dd-mm-yyyy') as varchar);
	        idot		 		:= rec1.idordentrabajo; 
            nombreproducto 		:= rec1.producto;
	        evaluador 			:= rec1.iniciales;
	        nombrecliente 		:= rec1.nombrecorto;
	        fechacreacion 		:= cast(to_char(rec1.fechacreacion, 'dd-mm-yyyy hh24:mm') as varchar);
			iniciodesarme 		:= cast(to_char(sp_iniciodes, 'dd-mm-yyyy hh24:mm') as varchar); 
    		terminodesarme 		:= cast(to_char(sp_terminodes, 'dd-mm-yyyy hh24:mm') as varchar);
    		bombapiso 			:= coalesce(
									    concat(
									        extract(day from (sp_iniciodes::timestamp - rec1.fechacreacion::timestamp))::bigint, 'd ',
									        extract(hour from (sp_iniciodes::timestamp - rec1.fechacreacion::timestamp))::bigint, 'h ',
									        extract(minute from (sp_iniciodes::timestamp - rec1.fechacreacion::timestamp))::bigint, 'm'
									    ),
									    null
									);
    		tiempodesarme 		:= coalesce(
									    concat(
									        extract(day from (sp_terminodes::timestamp - sp_iniciodes::timestamp))::bigint, 'd ',
									        extract(hour from (sp_terminodes::timestamp - sp_iniciodes::timestamp))::bigint, 'h ',
									        extract(minute from (sp_terminodes::timestamp - sp_iniciodes::timestamp))::bigint, 'm'
									    ),
									    null
									);

    		statusdesarme 		:= sp_textoestadodes;
			colorstatusdesarme	:= sp_colorestadodes;
			fecha100mecanizado	:= cast(to_char(rec1.fecha100tm, 'dd-mm-yyyy') as varchar);  
			inicioarmado 		:= cast(to_char(sp_inicioar, 'dd-mm-yyyy hh24:mm') as varchar); 
    		terminoarmado 		:= cast(to_char(sp_terminoar, 'dd-mm-yyyy hh24:mm') as varchar);
    		bombaproceso 		:= coalesce(
									    concat(
									        extract(day from (sp_terminoar::timestamp - sp_fecha_autoriza::timestamp))::bigint, 'd ',
									        extract(hour from (sp_terminoar::timestamp - sp_fecha_autoriza::timestamp))::bigint, 'h ',
									        extract(minute from (sp_terminoar::timestamp - sp_fecha_autoriza::timestamp))::bigint, 'm'
									    ),
									    null
									); 
    		tiempoarmado 		:= coalesce(
									    concat(
									        extract(day from (sp_terminoar::timestamp - sp_inicioar::timestamp))::bigint, 'd ',
									        extract(hour from (sp_terminoar::timestamp - sp_inicioar::timestamp))::bigint, 'h ',
									        extract(minute from (sp_terminoar::timestamp - sp_inicioar::timestamp))::bigint, 'm'
									    ),
									    null
									);
    		statusarmado 		:= sp_textoestadoar;
			colorstatusarmado	:= sp_colorestadoar;

			insert into traking.mct_registroarmadodesarmeonline 
                    values ((select coalesce(max(a.item),0) + 1 from traking.mct_registroarmadodesarmeonline a), 
					        (select coalesce(max(a.prioridad),0) + 1 from traking.mct_registroarmadodesarmeonline a),
					        fechaentregaclte,
					        idot, 
					        nombreproducto,
					        evaluador, 
					        nombrecliente, 
					        fechacreacion, 
					        iniciodesarme, 
					        terminodesarme,
					        bombapiso,
					        tiempodesarme,
					        statusdesarme,
					        colorstatusdesarme,
							fecha100mecanizado,
					        inicioarmado, 
					        terminoarmado,
					        bombaproceso,
					        tiempoarmado,
					        statusarmado,
					        colorstatusarmado);
            
			--RETURN NEXT;

	END LOOP;

	RETURN QUERY

	select *
	  from mct_registroarmadodesarmeonline
     order by prioridad asc;
	 		 
END;
$$;


ALTER FUNCTION traking.evtlistregistroarmadodesarmeonline(tipotareas bigint) OWNER TO postgres;

--
-- TOC entry 1786 (class 1255 OID 17318)
-- Name: evtlistregistroarmadodesarmesoloot(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistregistroarmadodesarmesoloot() RETURNS TABLE(idordentrabajo bigint, idaccion bigint, ordenaccion character varying, productoordenaccion character varying)
    LANGUAGE plpgsql
    AS $$
declare	 

	   
begin

	RETURN QUERY

	select distinct a.idordentrabajo as idordentrabajo,
           a.idaccion,
           case
				when a.idaccion = 165 then
					 cast('ARMADO-'||a.idordentrabajo as varchar)
                when a.idaccion = 173 then
					 cast('DESARME'||a.idordentrabajo as varchar)
           end as ordenaccion,
           case 
			  when bb.idfamilia = 11 then 
                   case
						when a.idaccion = 165 then
					 		cast('ARMADO-'||a.idordentrabajo||'-'||c.nombreproducto as varchar)
                		when a.idaccion = 173 then
					 		cast('DESARME'||a.idordentrabajo||'-'||c.nombreproducto as varchar)
           		   end
			  else 
                   case
						when a.idaccion = 165 then
					 		cast('ARMADO-'||a.idordentrabajo||'-'||h.sigla||' '||g.nombremodelo||' '||i.nombreparam as varchar)
                		when a.idaccion = 173 then
					 		cast('DESARME'||a.idordentrabajo||'-'||h.sigla||' '||g.nombremodelo||' '||i.nombreparam as varchar)
           		   end
                   
		   end as productoordenaccion
	  from mct_movimientoordentrabajo a
      left join mct_ordentrabajo bb on a.idordentrabajo = bb.idordentrabajo
	  left join mct_cliente b on bb.idcliente = b.idcliente 
	  left join  mct_producto c on bb.idproducto = c.idproducto
      left join  mct_modelo g on c.idmodelo = g.idmodelo
      left join  mct_subfamilia h on g.idsubfamilia = h.idsubfamilia
      left join  mct_etapaparam i on c.idetapaparam = i.idetapaparam 
	 where a.idaccion in (165,173)
	   and a.estadoactividad = 1;
		 	
	
END;
$$;


ALTER FUNCTION traking.evtlistregistroarmadodesarmesoloot() OWNER TO postgres;

--
-- TOC entry 1985 (class 1255 OID 17319)
-- Name: evtlistrepenrep(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistrepenrep(idcustomer bigint) RETURNS TABLE(id bigint, ot bigint, fechar character varying, fechaa character varying, fechae character varying, tipo character varying, modelo character varying, avance bigint, monto bigint, otcliente character varying, recicla bigint, reciclado bigint, ahorro character varying, ciclo character varying)
    LANGUAGE plpgsql
    AS $$
declare

--	variable recicla es para reutilizacion
--	variable reciclado es para reciclaje

    sp_id      		bigint;
    sp_ot      		bigint;
    sp_fechar  		varchar;
    sp_fechaa  		timestamp;
    sp_fechae  		varchar;
    sp_tipo    		varchar;
    sp_modelo  		varchar;
    sp_avance  		numeric;
    sp_monto   		bigint;
    sp_estado  		bigint;
   
    sp_fechat  		varchar;
    sp_dias    		bigint;
    sp_diast   		bigint;
    sp_porc    		bigint;
   
   -- Reutilizacion
    sp_recicla      bigint;
    sp_tot_piezas   bigint;
    sp_tot_reci     bigint;
   
    sp_reciclado    bigint;
    sp_tot_piezasr  bigint;
    sp_tot_recic    bigint;
   
    sp_dife    		bigint;
   
    sp_diassla 		bigint;
    cuenta_habiles	bigint;
	sp_i            bigint;
	dia_dow         bigint;
    new_fechae      varchar;
    fecha_paso      timestamp;
    intervalo    	varchar;
    tot_ciclos		bigint;
   
    sp_producto		varchar;
   
    rec1 	   		record;
   
BEGIN

	--select idordentrabajo , fechaentrega, fecharecepcion from mct_ordentrabajo mo where idordentrabajo  in (30229,30277,30412,30496,30509,30521)
	
	--select * from mct_progavisos mp where idordentrabajo  in (30229,30277,30412,30496,30509,30521) and idsla  = 5
	
	if ( idcustomer = 77 ) then 
	
		FOR rec1 IN (   
	       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
	              a.idordentrabajo as sp_ot,
	              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
	              --to_char(a.fechaentrega, 'dd-mm-yyyy') as sp_fechae, -- Esto se cambia para igualar a prioridades
	              to_char(a.fechafaceclte, 'dd-mm-yyyy') as sp_fechae,
	              d.sigla as sp_tipo,
	              case 
	                when idlineadiseno = 1 then 'DE DISEÑO'
	                when idlineadiseno = 2 then 'DE LINEA'
