ALTER FUNCTION traking.evtlistrepenrep(idcustomer bigint) OWNER TO postgres;

--
-- TOC entry 1416 (class 1255 OID 17321)
-- Name: evtlistrepeva(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistrepeva(idcustomer bigint) RETURNS TABLE(id bigint, ot bigint, fechar character varying, fechaa character varying, fechae character varying, tipo character varying, modelo character varying, avance bigint, monto bigint, otcliente character varying, recicla bigint, reciclado bigint, ahorro bigint, ciclo character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_id      integer;
    sp_ot      integer;
    sp_fechar  varchar;
    sp_fechaa  varchar;
    sp_fechae  varchar;
    sp_tipo    varchar;
    sp_modelo  varchar;
    sp_avance  integer;
    sp_monto   integer;
    sp_estado  integer;
   
    sp_fechat  varchar;
    sp_dias    integer;
    sp_diast   integer;
    sp_porc    integer;
      
    sp_dife    integer;
    tot_ciclos		integer;
      
    rec1 	   record;
   
BEGIN

	if ( idcustomer = 77 ) then 
	
	FOR rec1 IN (   
       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
              a.idordentrabajo as sp_ot,
              a.fecharecepcion as sp_fechar,
              to_char(a.fechaentrega, 'dd-mm-yyyy') as sp_fechae,
              d.sigla as sp_tipo,
              case 
                when idlineadiseno = 1 then 'DE DISEÑO'
                when idlineadiseno = 2 then 'DE LINEA'
              end||' - '||d.sigla||' '||c.nombreneptuno as sp_modelo,
              coalesce (a.montorepfab, 0) as sp_monto,
              a.otcliente 
         from mct_ordentrabajo a,
              mct_producto b,
              mct_modelo c,
              mct_subfamilia d
        where a.idordentrabajo >= 30000
          --and a.idcliente = idcustomer
          and a.idtipoorden = 1
          and a.idfamilia = 8
          and a.flagapp = 1
          and a.idestadoorden <= 4 and a.idestadoorden > 0
          and a.idproducto = b.idproducto 
          and b.idmodelo = c.idmodelo 
          and c.idsubfamilia = d.idsubfamilia 
          and a.debaja < 1
          )
		loop           
        

		    sp_avance  := 0;
		    sp_fechat  := '';
		    sp_dias    := 0;
		    sp_dife    := 0;
		    sp_diast   := 0;
		    sp_porc    := 0;
		        
		       select to_char(fecha_termino,'dd-mm-yyyy'),
		              estado
		         into sp_fechat,
		              sp_estado
		         from mct_progavisos mp 
		        where idsla = 3
		          and idordentrabajo = rec1.sp_ot;  
		        
		         
		        if ( sp_estado = 1 or now() >= to_date(sp_fechat,'dd-mm-yyyy')) then
		        
		           sp_avance := 100;
		        
		        end if;
		        
		        if ( now() < to_date(sp_fechat,'dd-mm-yyyy')) then
		           	
		            --sp_diast := date_part('day', to_date(sp_fechat,'dd-mm-yyyy') - rec1.sp_fechar )  ; solicitado por heraldo y reemplazado por la linea de abajo
		            sp_diast := date_part('day', current_date - rec1.sp_fechar )  ;
		            sp_dias  := date_part('day', to_date(sp_fechat,'dd-mm-yyyy') - now() ) ;
		           
		           
		        --   
		            sp_dife   := sp_diast - sp_dias;
		            if (sp_diast = 0) then
		                sp_diast	:= 1;
		            end if;
		           	--sp_avance := 100 - (round( (sp_dife * 100)/sp_diast  ));
		           	sp_avance := (sp_dife * 100)/sp_diast  ;
		        
		        end if;
		         
			    id      	:= rec1.sp_id;
			    ot      	:= rec1.sp_ot;
			    fechar  	:= to_char(rec1.sp_fechar,'dd-mm-yyyy');
			    fechaa  	:= sp_fechaa;
			    fechae  	:= sp_fechat;
			    tipo    	:= rec1.sp_tipo;
			    modelo  	:= cast(coalesce(rec1.sp_modelo,'S/M') as varchar);
			    if (sp_avance < 0) then
			    	avance  	:= sp_avance * -1;
			    else
			    	avance  	:= sp_avance;
			    end if;
			    monto   	:= rec1.sp_monto;
			    otcliente 	:= rec1.otcliente;
			    recicla     := 0;
			    reciclado	:= 0;
			    ahorro      := 0;
			   	-- Saca ciclos
		        tot_ciclos	:= 0;--traking.evtgetcantidadciclos(ot);
		        if (tot_ciclos = 0) then
				    ciclo	:= '-';	        
		        else
			    	ciclo	:= tot_ciclos;		        
		        end if;			    
		     
		      RETURN next;
		     
		END LOOP;		
	
	else
	
	FOR rec1 IN (   
       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
              a.idordentrabajo as sp_ot,
              a.fecharecepcion as sp_fechar,
