CREATE FUNCTION traking.evtlistrepsina(idcustomer bigint) RETURNS TABLE(id bigint, ot bigint, fechar character varying, fechaa character varying, fechae character varying, tipo character varying, modelo character varying, avance bigint, monto bigint, otcliente character varying, recicla bigint, reciclado bigint, ahorro character varying, ciclo character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_id      integer;
    sp_ot      integer;
    sp_fechar  varchar;
    sp_fechaa  varchar;
    sp_fechae  varchar;
    sp_fechaeit  varchar;
    sp_tipo    varchar;
    sp_modelo  varchar;
    sp_avance  integer;
    sp_monto   integer;
    rec1 	   record;

   -- Reutilizacion
    sp_recicla      integer;
    sp_tot_piezas   integer;
    sp_tot_reci     integer;
   
    sp_reciclado    integer;
    sp_tot_piezasr  integer;
    sp_tot_recic    integer;
   
    tot_ciclos		integer;
   
