              case 
                when idlineadiseno = 1 then 'DE DISEÑO'
                when idlineadiseno = 2 then 'DE LINEA'
              end||' - '||d.sigla||' '||c.nombreneptuno as sp_modelo,
              coalesce (a.montorepfab, 0) as sp_monto,
              a.otcliente  ,
              coalesce (b.tonelada , 4.5) as tonelada
         from mct_ordentrabajo a,
              mct_producto b,
              mct_modelo c,
              mct_subfamilia d
        where a.idordentrabajo >= 30000
          and a.idcliente = idcustomer
          and a.idtipoorden = 1
          and a.idfamilia = 8
          and a.flagapp = 1
          and a.idestadoorden in (0,5,6,7,8)
		  and (a.ordencompra is null or a.ordencompra = 0 or a.ordencompra < 0)
          and a.idproducto = b.idproducto 
          and b.idmodelo = c.idmodelo 
          and c.idsubfamilia = d.idsubfamilia 
      union
        select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
              a.idordentrabajo as sp_ot,
              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
              to_char(a.fechaentrega, 'dd-mm-yyyy') as sp_fechae,
              d.sigla as sp_tipo,
              case 
                when idlineadiseno = 1 then 'DE DISEÑO'
                when idlineadiseno = 2 then 'DE LINEA'
              end||' - '||d.sigla||' '||c.nombreneptuno as sp_modelo,
              coalesce (a.montorepfab, 0) as sp_monto,
              a.otcliente  ,
              coalesce (b.tonelada , 4.5) as tonelada
         from mct_ordentrabajo a,
              mct_producto b,
              mct_modelo c,
              mct_subfamilia d
        where a.idordentrabajo >= 30000
          and a.idcliente = idcustomer
          and a.idtipoorden = 1
          and a.idfamilia = 11
          and a.flagapp = 1
          and a.idestadoorden in (0,5,6,7,8)
		  and (a.ordencompra is null or a.ordencompra = 0 or a.ordencompra < 0)
          and a.idproducto = b.idproducto 
          and b.idmodelo = c.idmodelo 
          and c.idsubfamilia = d.idsubfamilia      
	   
	   ) as tabla
	   order by 2 desc
	   
          )
          
		loop           
         
		
		       select coalesce (to_char(fecha_inicio,'dd-mm-yyyy'),'')
		         into sp_fechaa
		         from mct_progavisos mp 
		        where idsla = 5
		          and idordentrabajo = rec1.sp_ot;   

		       select coalesce (to_char(fecha_real_termino,'dd-mm-yyyy'),'')
		         into sp_fechaeit
		         from mct_progavisos mp 
		        where idsla = 3
		          and idordentrabajo = rec1.sp_ot; 

		         
		         select 
		                case
		                   when now() >= max(fecha_real_termino) then date_part('day', now() - min(fecha_real_termino))
		                   when max(fecha_autoriza_cliente) is not null then date_part('day', max(fecha_autoriza_cliente) - min(fecha_inicio))
		                   else date_part('day', now() - min(fecha_inicio))
		                end
		           into sp_avance
		                --max(coalesce (fecha_autoriza_cliente ,now()))
		           from mct_progavisos 
		          where idordentrabajo = rec1.sp_ot
		            and idsla in (4,5);
		           
		    	sp_tot_piezas := 0;
		    	sp_tot_reci   := 0;

			    -- % de reutilización
			    select sum(cantidad)
			      into sp_tot_piezas
				  from mct_checklistinftecvalido mc 
				 where idordentrabajo = rec1.sp_ot
				   and upper(criterio) not in ('RPO');
				   
				select sum(cantidad)
				  into sp_tot_reci
				  from mct_checklistinftecvalido mc 
				 where idordentrabajo = rec1.sp_ot
				   and upper(criterio) not in ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO');
				  
				  
				if (sp_tot_piezas = 0) then
				   sp_tot_piezas := 1;
				end if;
			
				sp_recicla := 0;
			 
			    sp_recicla := round( (sp_tot_reci * 100) / sp_tot_piezas);
			     
			   
			   	sp_tot_piezasr := 0;
			    sp_tot_recic   := 0;
		   
			     -- % de reciclaje
			    select sum(cantidad)
			      into sp_tot_piezasr
				  from mct_checklistinftecvalido mc 
