    sp_total				bigint;
    sp_totrecep				bigint;
   
    sp_producto				varchar;
   
    sp_tieneregistro		bigint;
   
    sp_tienedefecto			bigint;
   
   	sp_funcav			   	numeric;
   
    sp_estaenproceso		bigint;

    sp_montoadicional		bigint;
   
begin
		 
	fechadesde			:= '';
    fechahasta			:= '';
    parte1				:= 0;
    parte1_D			:= 0;
   
    parte2				:= 0;
    parte2_D			:= 0;
    corte				:= 0;
    sp_tienedefecto		:= 0;
   
	if (periodos != '-1') then

		--select to_char(now() - interval '1 year','yyyy')
		select to_char(now(),'yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		--select to_char(now(),'yyyy')
		select to_char(now() + interval '1 year','yyyy')
		  into anofin;
		 
		fechahasta	:= anofin||'-'||mes||'-'||ultimodia;
	
	    fechadesde	:= '2023-10-01'; -- solicitado por HC
		
		FOR rec1 IN (   
						
		          select ROW_NUMBER() OVER (ORDER BY tabla.fechaentregaclte asc, tabla.ot asc) AS item,
		                 tabla.ot,
					     tabla.idestadoorden,
		                 tabla.mec,
		                 tabla.idfamilia,
		                 tabla.sigla,
		                 tabla.idproducto,
		                 tabla.producto,
		                 tabla.nombrecorto,
		                 tabla.nombre, 
		                 to_char(tabla.fechaentregaclte, 'dd-mm-yyyy') as fechaentregaclte ,
		                 tabla.fechaentregaclte as fechaentregacltecal,
		                 cast(to_char(tabla.fechaentregaclte,'dd') as integer) as dia,
		                 tabla.dias,
		                 tabla.avancefund,
		                 tabla.avancemec,
		                 tabla.monto,
		                 tabla.fechadespacho
		            from (
					select a.idordentrabajo as ot,
					       a.idestadoorden,
					       0 as mec,
					       a.idfamilia,					       
						   d.sigla||'_'||e.sigla as sigla,
						   a.idproducto,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   b.nombrecorto ,
						   j.nombre ,
						   a.fechafaceclte as fechaentregaclte,				       
						   cast(date_part('day', fechafaceclte - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(a.montorepfab)                                         as monto,
						   a.fechadespacho
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   --and a.idfamilia in (idfamilysB, idfamilysR, idfamilysO)
				       and case 
                           WHEN idfamilysr = 10 THEN 
                                a.idfamilia in (idfamilysB, idfamilysR, idfamilysO) and a.idlineadiseno in (1,2,4)
                           WHEN idfamilysr = 102 THEN  
                                a.idfamilia in (idfamilysB, 10, idfamilysO) and a.idlineadiseno in (3) 
                           WHEN idfamilysr = 103 THEN  
                                a.idfamilia in (idfamilysB, 10, idfamilysO)      
                           ELSE 
                                a.idfamilia in (idfamilysB, idfamilysR, idfamilysO)
                          end
				       --and a.flagfacturacion is true
					   and a.debaja < 1
					   --and a.checklistvalido = true
					   and (a.fechafaceclte >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by a.idordentrabajo ,
					       a.idestadoorden,
					       d.sigla||'_'||e.sigla,
					       a.idproducto,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar),
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar)				         
				union 
					select a.idordentrabajo  as ot,
					       a.idestadoorden,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_CON' as sigla,
						   a.idproducto,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       'SEBASTIAN CUADRA' as nombre,
					       a.fechaentrega as fechaentregaclte,
					       cast(date_part('day', a.fechaentrega - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto,
						   a.fechadespacho
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDC
					 where a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   --and a.idfamilia       in (11, idfamilysO)
					   and a.idfamilia       in (11)
					   --and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechaentrega >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            a.idestadoorden,
					            k.idesmecanizado ,
					            a.idfamilia,
					 	        e.sigla||'_CON',
								e.nombrefamilia ,
								a.idproducto,
								c.nombreproducto,
								b.nombrecorto ,
								cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechaentrega - current_date) as bigint)
				union 
					select a.idordentrabajo  as ot,
					       a.idestadoorden,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_SIN' as sigla,
						   a.idproducto,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       j.nombre as nombre,
					       a.fechaentrega as fechaentregaclte,
					       cast(date_part('day', a.fechaentrega - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto,
						   a.fechadespacho
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDS
					 where a.idordentrabajo >= 30000
					   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   --and a.idfamilia       in (11, idfamilysO)
					   and a.idfamilia       in (11)
					   --and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechaentrega >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            a.idestadoorden,
					            a.idfamilia,
					            k.idesmecanizado ,
					 	        e.sigla||'_SIN',
								e.nombrefamilia ,
								a.idproducto,
								c.nombreproducto,
								b.nombrecorto ,
								j.nombre,
								cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechaentrega - current_date) as bigint)								
						 ) as tabla
				
						   						   
					)
	     		loop 
		     		
		     		--raise notice '%', rec1.ot||' SQ- '||rec1.idestadoorden||' - '||rec1.fechadespacho;

		     		sp_tieneregistro	:= 0;
		     	
		     	    if ( rec1.idfamilia in (11, 15) ) then
		     	    
		     	        select count(*) 
		     	          into sp_tieneregistro
		     		      from mct_checklistinftec a
		     		     where a.idordentrabajo = rec1.ot
		     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
		     	    
		     	    else
		     	    
						select count(*) 
		     	          into sp_tieneregistro
		     		      from mct_checklistinftecvalido a
		     		     where a.idordentrabajo = rec1.ot
		     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');	     	    
		     	    
		     	    end if;

--		     		if (select distinct 1 
--		     		      from mct_checklistinftecvalido a
--		     		     where a.idordentrabajo = rec1.ot
--		     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL') ) then
		     		       
		     	 --   if ( sp_tieneregistro > 0) then

			     		sp_total	:= 0;
	    				sp_totrecep	:= 0;
	
	    			    if ( rec1.idfamilia in (11, 15) ) then
	    			    
	    			    -- Saca totales piezas y totales recepcionados
			     		    select coalesce (sum(cantidad) , 0)
			     		      into sp_total
			     		      from mct_checklistinftec a 
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
	    			    
	    			    else
	    			    
	    			    -- Saca totales piezas y totales recepcionados
			     		    select coalesce (sum(cantidad) , 0)
			     		      into sp_total
			     		      from mct_checklistinftecvalido a 
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
	    			    
	    			    end if;
			     		
			     		
				     		select coalesce (sum(cantidad) , 0)
			     		      into sp_totrecep 
			     		      from mct_checklistinftecrecept a
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.codigoqr in (rec1.ot||'FAB_FU', rec1.ot||'FAB_FUPL');
			     	
			     		-- Acumula Totales parte1 y part2 del mes
			     		
			     	
			     	    if (rec1.dia > 15 ) then
	
			     	       if ( corte = 0 and (parte1 > 0 or parte1_D > 0) ) then
			     	       
					
					     		 corte				:= 1;
					     		 
					     		 if (rec1.idestadoorden = 9) then
					     		    parte2_D := parte2_D + rec1.monto;
					     		 else
					     		    parte2	 := parte2 + rec1.monto;
					     		 end if;
					     		
					     		 --parte2	 := parte2 + rec1.monto;
			     	       
					       else
			     	       
					     		 if (rec1.idestadoorden = 9) then
					     		    parte2_D := parte2_D + rec1.monto;
					     		 else
					     		    parte2	 := parte2 + rec1.monto;
					     		 end if;
			     	       		
			     	       end if;
	
				     		 
			     	    
				     	else
				     		--parte1	 := parte1 + rec1.monto;
				     		if (rec1.idestadoorden = 9) then
					     		parte1_D := parte1_D + rec1.monto;
					     	else
					     		parte1	 := parte1 + rec1.monto;
					     	end if;
			     	    end if;
			     	   
					    -- calcula avance mecanizado	
			     	    sp_sumatotallcc  := 0;

			     	 FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec1.ot 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
--				       			   select coalesce (sum(cantidad),0)
--								     into sp_liberadascc
--								     from mct_hojarutatemp
--								    where idhojarutatemp = rec_lcc.idhojarutatemp
--								      and idboleano = 1
--					                  and idareaclasificacion in (0,1,2,3,4,5);
					                 
				     			   select case
					     			         when idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when idimprimehojas = 2 then
					     			              coalesce (sum(cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp
								    where idhojarutatemp = rec_lcc.idhojarutatemp
								      and idboleano = 1
					                  and idareaclasificacion in (0,1,2,3,4,5)
					                 group by idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo     
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.ot
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;

							     
						-- aca sacamos la cantidad de piezas liberadas de control de calidad
						select count(*)  
					      into sp_liberadascc
					      from mct_movimientoordentrabajo a
					     where a.codigoaccion   = 'L_CC'
					 	   and a.idordentrabajo = rec1.ot; 
							      
							if ( sp_canthr = 0) then
							     sp_avance := 0;
						    else
								 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
				            end if;		
				           
	
				        if ( rec1.idfamilia in (11, 15) ) then
				        
						-- Fundicion
						-- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(a.cantidad), 0),
							          a.codigoqr
							     into sp_cantidad_fu,
							          sp_codigoqr_fu
							     from mct_checklistinftec a
							    where a.tipotrabajostd = 'FAB_FU'
							      and a.idordentrabajo = rec1.ot
							      group by a.codigoqr, a.fecharequerida;
							     
							     
				        else
				        
				        -- Fundicion
						-- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(a.cantidad), 0),
							          a.codigoqr
							     into sp_cantidad_fu,
							          sp_codigoqr_fu
							     from mct_checklistinftecvalido a
							    where a.tipotrabajostd = 'FAB_FU'
							      and a.idordentrabajo = rec1.ot
							      group by a.codigoqr, a.fecharequerida;
							     
				        
				        end if;

							     
					   -- aca sacamos el total de piezas recepcionadas   
					   select coalesce ( sum(cantidad), 0) * 100
					     into sp_recept_fu
					     from mct_checklistinftecrecept
					    where codigoqr = sp_codigoqr_fu; 
	
					   if (sp_cantidad_fu = 0 ) then
		                   sp_cantidad_fu := 1;
		               end if;
		              
					  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
					   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
					  
					   if ( sp_cantidad_fu = 0 ) then
					       sp_avance_fu = 999;
					   end if;
							  
					     if ( rec1.idproducto in (10,11,12,13,14,15,16,17)) then
					     
					     	select nombreproductonepcast 
					     	  into sp_producto
					     	  from mct_productonepcast 
					     	 where idproductonepcast = rec1.idproducto;
					     	  					     
					     else
					     
					     	sp_producto	:= rec1.producto;
					     end if;
							
					     select count(*)
				           into sp_tienedefecto
				           from traking.mct_defectofundicion a
				          where a.idordentrabajo = rec1.ot;
				         
				         
				     
				         item 				:= rec1.item; 
				         idordentrabajo 	:= rec1.ot; 
				         nombretipoorden 	:= rec1.sigla||'_'||rec1.idestadoorden; 
				         --producto 			:= rec1.producto; 
				         producto 			:= sp_producto;
				         nombrecliente 		:= rec1.nombrecorto;
				         nombreusuario 		:= rec1.nombre;
				         fechaentregaclte 	:= rec1.fechaentregaclte;
				         fechaentregacltecal:= rec1.fechaentregacltecal;
				         diascliente 		:= rec1.dias;
				         --avancefund 		:= rec1.avancefund;
				         avancefund			:= sp_avance_fu;
				         --avancemec 			:= rec1.avancemec;
				        
				         

				        select coalesce (salav)
	                      into sp_funcav 
	                      from traking.calcularavancemecanizado(rec1.ot);

				         avancemec			:= sp_funcav;
				        
				         montototal 		:= rec1.monto;
				         totalpieza			:= sp_total;
	         			 totalrecep			:= sp_totrecep;
	         			 tienedefecto		:= sp_tienedefecto;
	         			
	         			 select count(*)
				          into sp_estaenproceso
				          from traking.mct_movimientoordentrabajo a
				         where a.idordentrabajo = rec1.ot
				           and a.estadoactividad = 1;
				      
				         estaenproceso  := sp_estaenproceso;
				        
				         
				         if (rec1.idfamilia = 8) then
				         
				         	select coalesce(sum(montorepfab),0)
				         	  into montototalot
				         	  from mct_ordentrabajo a 
				         	 where a.idordentrabajo = rec1.ot;
				         
				         elsif (rec1.idfamilia = 11) then
				         
				         	select coalesce(sum(cantidad*costo) ,0)
				         	  into montototalot
				         	  from mct_ordentrabajorepuesto a
				         	 where a.idordentrabajo = rec1.ot;
				         	
				         elsif (rec1.idfamilia = 10 or rec1.idfamilia = 15) then

				           	select coalesce(sum(montorepfab),0) 
				         	  into montototalot
				         	  from mct_ordentrabajo a 
				         	 where a.idordentrabajo = rec1.ot;
				         	
				         	select coalesce(sum(cantidad*costo) ,0)
				         	  into sp_montoadicional
				         	  from mct_ordentrabajorepuesto a
				         	 where a.idordentrabajo = rec1.ot;
				         	
				         	montototalot	:= montototalot + sp_montoadicional;
				         	
				         else
				         
				         	montototalot	:= 0;
				         
				         end if;
				              		    
				         return next;
				            	
			       	       
	     		end loop;
	     		
			
	else
	
		FOR rec1 IN (   
						
		          select ROW_NUMBER() OVER (ORDER BY tabla.fechaentregaclte asc, tabla.ot asc) AS item,
		                 tabla.ot,
					     tabla.idestadoorden,
		                 tabla.mec,
		                 tabla.idfamilia,
		                 tabla.sigla,
		                 tabla.idproducto,
		                 tabla.producto,
		                 tabla.nombrecorto,
		                 tabla.nombre, 
		                 to_char(tabla.fechaentregaclte, 'dd-mm-yyyy') as fechaentregaclte ,
		                 tabla.fechaentregaclte as fechaentregacltecal ,
		                 cast(to_char(tabla.fechaentregaclte,'dd') as integer) as dia,
		                 tabla.dias,
		                 tabla.avancefund,
		                 tabla.avancemec,
		                 tabla.monto
		            from (
					select a.idordentrabajo as ot,
					       a.idestadoorden,
					       0 as mec,
					       a.idfamilia,					       
						   d.sigla||'_'||e.sigla as sigla,
						   a.idproducto,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar) as producto,
						   b.nombrecorto ,
						   j.nombre ,
						   a.fechafaceclte as fechaentregaclte,				       
						   cast(date_part('day', fechafaceclte - now() ) as bigint)   as dias,
						   cast(0 as bigint) 										  as avancefund,
						   cast(0 as bigint) 										  as avancemec,
						   sum(a.montorepfab)                                         as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b         		 on a.idcliente = b.idcliente
					  left join  mct_producto c        		 on a.idproducto = c.idproducto 
					  left join  mct_tipoorden d       		 on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e         		 on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f     		 on a.idestadoorden = f.idestadoorden
					  left join  mct_modelo g          		 on c.idmodelo = g.idmodelo
					  left join  mct_subfamilia h      		 on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i      		 on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j               on a.idusuario = j.idusuario
					 where a.idordentrabajo >= 30000
				       and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   --and a.idfamilia in (idfamilysB, idfamilysR, idfamilysO)
				       and case 
                           WHEN idfamilysr = 10 THEN 
                                a.idfamilia in (idfamilysB, idfamilysR, idfamilysO) and a.idlineadiseno in (1,2,4)
                           WHEN idfamilysr = 102 THEN  
                                a.idfamilia in (idfamilysB, 10, idfamilysO) and a.idlineadiseno in (3) 
                           ELSE 
                                a.idfamilia in (idfamilysB, idfamilysR, idfamilysO)
                          end
				      -- and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.checklistvalido = true
					   and (a.fechafaceclte >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafaceclte <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					 group by a.idordentrabajo ,
					       a.idestadoorden,
					       d.sigla||'_'||e.sigla,
					       a.idproducto,
						   cast(case 
							  when a.idfamilia = 11 then c.nombreproducto
						      else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as varchar),
						   b.nombrecorto ,
						   j.nombre ,
						   cast(to_char(a.fechafaceclte ,'dd-mm-yyyy') as varchar)				         
				union 
					select a.idordentrabajo  as ot,
					       a.idestadoorden,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_CON' as sigla,
						   a.idproducto,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       'SEBASTIAN CUADRA' as nombre,
					       a.fechafundicion2 as fechaentregaclte,
					       cast(date_part('day', a.fechafundicion2 - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDC
					 where a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   --and a.idfamilia       in (11, idfamilysO)
					   and a.idfamilia       in (11)
					   --and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechafundicion2 >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechafundicion2 <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					       a.idestadoorden,
					            k.idesmecanizado ,
					            a.idfamilia,
					 	        e.sigla||'_CON',
					 	        a.idproducto,
								e.nombrefamilia ,
								c.nombreproducto,
								b.nombrecorto ,
								cast(to_char(a.fechafundicion2 ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechafundicion2 - current_date) as bigint)
				union 
					select a.idordentrabajo  as ot,
					       a.idestadoorden,
					       k.idesmecanizado as mec,
					       a.idfamilia,
						   e.sigla||'_SIN' as sigla,
						   a.idproducto,
						   c.nombreproducto  as producto,
					       b.nombrecorto ,
					       j.nombre as nombre,
					       a.fechaentrega as fechaentregaclte,
					       cast(date_part('day', a.fechaentrega - current_date) as bigint) as dias,
					       cast(0 as bigint) as avancefund,
						   cast(0 as bigint) as avancemec,
					       sum(k.costo * k.cantidad)  as monto
					  from mct_ordentrabajo a
					  left join  mct_cliente b      on a.idcliente = b.idcliente
					  left join  mct_producto c     on a.idproducto = c.idproducto
					  left join  mct_tipoorden d    on a.idtipoorden = d.idtipoorden
					  left join  mct_familia e      on a.idfamilia = e.idfamilia
					  left join  mct_estadoorden f  on a.idestadoorden = f.idestadoorden 
					  left join  mct_modelo g       on c.idmodelo = g.idmodelo 
					  left join  mct_subfamilia h   on g.idsubfamilia = h.idsubfamilia 
					  left join  mct_etapaparam i   on c.idetapaparam = i.idetapaparam
					  left join  mct_usuario j      on a.idusuario = j.idusuario 
					       join  mct_ordentrabajorepuesto k on a.idordentrabajo = k.idordentrabajo and k.idesmecanizado = idfamilysDS
					 where a.idordentrabajo >= 30000
					   and a.idestadoorden  >= 6 and a.idestadoorden <= 9
					   --and a.idfamilia       in (11, idfamilysO)
					   and a.idfamilia       in (11)
					   --and a.flagfacturacion is true
					   and a.debaja < 1
					   and (a.fechaentrega >= TO_TIMESTAMP(desde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechaentrega <= TO_TIMESTAMP(hasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) 
					   group by a.idordentrabajo ,
					            a.idestadoorden,
					            a.idfamilia,
					            k.idesmecanizado ,
					 	        e.sigla||'_SIN',
					 	        a.idproducto,
								e.nombrefamilia ,
								c.nombreproducto,
								b.nombrecorto ,
								j.nombre,
								cast(to_char(a.fechaentrega ,'dd-mm-yyyy') as varchar) 	,
								cast(date_part('day', a.fechaentrega - current_date) as bigint)								
						 ) as tabla
						   						   
					)
	     		loop 

		     		sp_tieneregistro	:= 0;
		     	
		     	    if ( rec1.idfamilia in (11, 15) ) then
		     	    
		     	        select count(*) 
		     	          into sp_tieneregistro
		     		      from mct_checklistinftec a
		     		     where a.idordentrabajo = rec1.ot
		     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
		     	    
		     	    else
		     	    
						select count(*) 
		     	          into sp_tieneregistro
		     		      from mct_checklistinftecvalido a
		     		     where a.idordentrabajo = rec1.ot
		     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');		     	    
		     	    
		     	    end if;

--		     		if (select distinct 1 
--		     		      from mct_checklistinftecvalido a
--		     		     where a.idordentrabajo = rec1.ot
--		     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL') ) then
		     		       
		     	    if ( sp_tieneregistro > 0) then
		     		       
			     		sp_total	:= 0;
	    				sp_totrecep	:= 0;

			     		
	    			    if ( rec1.idfamilia in (11, 15) ) then
	    			    
	    			    -- Saca totales piezas y totales recepcionados
			     		    select coalesce (sum(cantidad) , 0)
			     		      into sp_total
			     		      from mct_checklistinftec a 
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
	    			    
	    			    else
	    			    
	    			    -- Saca totales piezas y totales recepcionados
			     		    select coalesce (sum(cantidad) , 0)
			     		      into sp_total
			     		      from mct_checklistinftecvalido a 
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.tipotrabajostd in ('FAB_FU', 'FAB_FUPL');
	    			    
	    			    end if;
			     		
			     		
				     		select coalesce (sum(cantidad) , 0)
			     		      into sp_totrecep 
			     		      from mct_checklistinftecrecept a
			     		     where a.idordentrabajo = rec1.ot
			     		       and a.codigoqr in (rec1.ot||'FAB_FU', rec1.ot||'FAB_FUPL');
			     		    
--			     		end if;
			     	
			     	    if (rec1.dia > 15 ) then
	
			     	       if ( corte = 0 and (parte1 > 0 or parte1_D > 0) ) then
			     	       
--					     	     item 				:= 0; 
--						         idordentrabajo 	:= 0; 
--						         nombretipoorden 	:= 0; 
--						         producto 			:= 'TOTAL'; 
--						         nombrecliente 		:= 0;
--						         nombreusuario 		:= 0;
--						         fechaentregaclte 	:= 0;
--						         fechaentregacltecal:= null;
--						         diascliente 		:= 0;
--						         avancefund			:= 0;
--						         avancemec			:= 0;
--						         montototal 		:= parte1 + parte1_D;
--				    			 totalpieza			:= 0;
--	         	    			 totalrecep			:= 0;
--	         	    			 tienedefecto		:= 0;
--						        
--					     		 return next;	
--
--					     	     item 				:= -9; 
--						         idordentrabajo 	:= 0; 
--						         nombretipoorden 	:= 0; 
--						         producto 			:= 'TOTAL DESPACHO'; 
--						         nombrecliente 		:= 0;
--						         nombreusuario 		:= 0;
--						         fechaentregaclte 	:= 0;
--						         fechaentregacltecal:= null;
--						         diascliente 		:= 0;
--						         avancefund			:= 0;
--						         avancemec			:= 0;
--						         montototal 		:= parte1_D;
--				    			 totalpieza			:= 0;
--	         	    			 totalrecep			:= 0;
--	         	    			 tienedefecto		:= 0;
			         
						         corte				:= 1;
						        
					     		 return next;	
					     		
					     		 --parte2	 := parte2 + rec1.monto;

					     		 if (rec1.idestadoorden = 9) then
					     		    parte2_D := parte2_D + rec1.monto;
					     		 else
					     		    parte2	 := parte2 + rec1.monto;
					     		 end if;
					     		
					       else
			     	       
			     	       		 --parte2	 := parte2 + rec1.monto;
					     		 if (rec1.idestadoorden = 9) then
					     		    parte2_D := parte2_D + rec1.monto;
					     		 else
					     		    parte2	 := parte2 + rec1.monto;
					     		 end if;
					     		
			     	       end if;
	
				     		 
			     	    
				     	else
				     		--parte1	 := parte1 + rec1.monto;

					     		 if (rec1.idestadoorden = 9) then
					     		    parte1_D := parte1_D + rec1.monto;
					     		 else
					     		    parte1	 := parte1 + rec1.monto;
					     		 end if;
					     		
			     	    end if;
			     	   
					    -- calcula avance mecanizado	
			     	    sp_sumatotallcc  := 0;

			     	 FOR rec_lcc IN (   
									select distinct b.idhojarutatemp
									  from mct_movimientoordentrabajo a,
									       mct_hojaruta b,
									       mct_hojarutatemp c
									 where a.codigoaccion = 'L_CC'
								       and a.idordentrabajo = rec1.ot 
								       and a.idhojaruta = b.idhojaruta 
								       and b.idhojarutatemp = c.idhojarutatemp 
								       and c.idboleano = 1
					                   and c.idareaclasificacion in (0,1,2,3,4,5)
									)
				     		loop 	

				     			   sp_liberadascc	:= 0;
								   
--				       			   select coalesce (sum(cantidad),0)
--								     into sp_liberadascc
--								     from mct_hojarutatemp
--								    where idhojarutatemp = rec_lcc.idhojarutatemp
--								      and idboleano = 1
--					                  and idareaclasificacion in (0,1,2,3,4,5);
					                 
				     			   select case
					     			         when mh.idimprimehojas = 1 then
					     			              coalesce (count(*),0)
					     			         when mh.idimprimehojas = 2 then
					     			              coalesce (sum(mh.cantidad),0)     
					     			         else
					     			              0
					     			      end
								     into sp_liberadascc
								     from mct_hojarutatemp mh
								    where mh.idhojarutatemp = rec_lcc.idhojarutatemp
								      and mh.idboleano = 1
					                  and mh.idareaclasificacion in (0,1,2,3,4,5)
					                 group by mh.idimprimehojas;
						     
						 			sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
						           
				  			END LOOP;
				  		
				  	   sp_sumatotallcc := sp_sumatotallcc * 100;
				  	   -- hasta aca el nuevo calculo
				  	     
					   
					   select sum(total)
					     from (
							   select case 
								        when mh.idimprimehojas = 1 then
							     			 coalesce (count(*),0)
							     	    when mh.idimprimehojas = 2 then
							     			 coalesce (sum(mh.cantidad),0)     
							     		else
							     			 0	
							          end as total
							     from mct_hojarutatemp mh
							    where mh.idordentrabajo = rec1.ot
							      and mh.idboleano = 1
							      and mh.idareaclasificacion in (0,1,2,3,4,5)
							     group by mh.idimprimehojas
						    ) as tabla
					   into sp_canthr;
					  

						-- aca sacamos la cantidad de piezas liberadas de control de calidad
						select count(*)  
					      into sp_liberadascc
					      from mct_movimientoordentrabajo a
					     where a.codigoaccion   = 'L_CC'
					 	   and a.idordentrabajo = rec1.ot; 
							      
							if ( sp_canthr = 0) then
							     sp_avance := 0;
						    else
								 sp_avance := round(sp_sumatotallcc / sp_canthr , 2);
				            end if;		
				           
				           
				        if ( rec1.idfamilia in (11, 15) ) then
				        
						-- Fundicion
						-- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(a.cantidad), 0),
							          a.codigoqr
							     into sp_cantidad_fu,
							          sp_codigoqr_fu
							     from mct_checklistinftec a
							    where a.tipotrabajostd = 'FAB_FU'
							      and a.idordentrabajo = rec1.ot
							      group by a.codigoqr, a.fecharequerida;
							     
							     
				        else
				        
				        -- Fundicion
						-- aca sacamos las piezas totales solicitadas a fundicion  
							   select coalesce ( sum(a.cantidad), 0),
							          a.codigoqr
							     into sp_cantidad_fu,
							          sp_codigoqr_fu
							     from mct_checklistinftecvalido a
							    where a.tipotrabajostd = 'FAB_FU'
							      and a.idordentrabajo = rec1.ot
							      group by a.codigoqr, a.fecharequerida;
							     
				        
				        end if;

							   -- aca sacamos el total de piezas recepcionadas   
							   select coalesce ( sum(cantidad), 0) * 100
							     into sp_recept_fu
							     from mct_checklistinftecrecept
							    where codigoqr = sp_codigoqr_fu; 
			
							   if (sp_cantidad_fu = 0 ) then
				                   sp_cantidad_fu := 1;
				               end if;
				              
							  -- sp_avance_fu := round((sp_recept_fu * 100.00 ) / sp_cantidad_fu , 2);
							   sp_avance_fu := round(sp_recept_fu / sp_cantidad_fu , 2);
							  
							   if ( sp_cantidad_fu = 0 ) then
							       sp_avance_fu = 999;
							   end if;
	
					     if ( rec1.idproducto in (10,11,12,13,14,15,16,17)) then
					     
					     	select nombreproductonepcast 
					     	  into sp_producto
					     	  from mct_productonepcast 
					     	 where idproductonepcast = rec1.idproducto;
					     	  					     
					     else
					     
					     	sp_producto	:= rec1.producto;
					     end if;
					    
					     select count(*)
				           into sp_tienedefecto
				           from traking.mct_defectofundicion a
				          where a.idordentrabajo = rec1.ot;
				     
				         item 				:= rec1.item; 
				         idordentrabajo 	:= rec1.ot; 
				         nombretipoorden 	:= rec1.sigla||'_'||rec1.idestadoorden; 
				         --producto 			:= rec1.producto; 
				         producto 			:= sp_producto;
				         nombrecliente 		:= rec1.nombrecorto;
				         nombreusuario 		:= rec1.nombre;
				         fechaentregaclte 	:= rec1.fechaentregaclte;
				         fechaentregacltecal:= rec1.fechaentregacltecal;
				         diascliente 		:= rec1.dias;
				         --avancefund 		:= rec1.avancefund;
				         avancefund			:= sp_avance_fu;
				         --avancemec 			:= rec1.avancemec;
	
				         select coalesce (salav)
	                      into sp_funcav 
	                      from traking.calcularavancemecanizado(rec1.ot);
	                     
				         --avancemec			:= sp_avance;
				        
				         avancemec			:= sp_funcav;
				         if ( rec1.idfamilia = 11 and rec1.mec = 2) then
				             avancemec		:= 999;
				         end if;
				        
				         montototal 		:= rec1.monto;
				         totalpieza			:= sp_total;
	         			 totalrecep			:= sp_totrecep;
	         			 tienedefecto		:= sp_tienedefecto;
	         			
	         			 select count(*)
				          into sp_estaenproceso
				          from traking.mct_movimientoordentrabajo a
				         where a.idordentrabajo = rec1.ot
				           and a.estadoactividad = 1;
				      
				         estaenproceso  := sp_estaenproceso;
	         			
				         if (rec1.idfamilia = 8) then
				         
				         	select coalesce(sum(montorepfab),0)
				         	  into montototalot
				         	  from mct_ordentrabajo a 
				         	 where a.idordentrabajo = rec1.ot;
				         
				         elsif (rec1.idfamilia = 11) then
				         
				         	select coalesce(sum(cantidad*costo) ,0)
				         	  into montototalot
				         	  from mct_ordentrabajorepuesto a
				         	 where a.idordentrabajo = rec1.ot;
				         	
				         elsif (rec1.idfamilia = 10 or rec1.idfamilia = 15) then

				           	select coalesce(sum(montorepfab),0) 
				         	  into montototalot
				         	  from mct_ordentrabajo a 
				         	 where a.idordentrabajo = rec1.ot;
				         	
				         	select coalesce(sum(cantidad*costo) ,0)
				         	  into sp_montoadicional
				         	  from mct_ordentrabajorepuesto a
				         	 where a.idordentrabajo = rec1.ot;
				         	
				         	montototalot	:= montototalot + sp_montoadicional;
				         	
				         else
				         
				         	montototalot	:= 0;
				         
				         end if;
				        			     		    
				         return next;
				           
		     		       
		     		end if;       

			       	       
	     		end loop;	
			
			
	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtlistresumencalendariogeneralot(idfamilysb bigint, idfamilysr bigint, idfamilysds bigint, idfamilysdc bigint, idfamilyso bigint, periodos character varying, desde character varying, hasta character varying) OWNER TO postgres;

--
-- TOC entry 1014 (class 1255 OID 17326)
-- Name: evtlistroadmapbodypdf(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistroadmapbodypdf(roadmapse character varying) RETURNS TABLE(activityname character varying, codesection character varying, tothour integer)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		 
			select --a.idhojaruta , 
			       --a.idordentrabajoparte ,
			       --b.idparte ,
			       --c.idcomponente ,
			       --d.idevaluacion ,
			       --d.idtipotrabajo ,
			       --e.idcomponentetipotrabajo ,
			       --f.idactividad ,
			       g.nombreactividad ,
			       --h.idseccion ,
			       --h.idactividad ,
			       i.codigoseccion ,
			       0
			from mct_hojaruta a
			  left join  mct_ordentrabajoparte b         on a.idordentrabajoparte  = b.idordentrabajoparte
			  left join  mct_parte c                     on b.idparte = c.idparte
			  left join  mct_evaluacion d                on b.idordentrabajoparte  = d.idordentrabajoparte
			  left join  mct_componentetipotrabajo e     on e.idcomponente  = c.idcomponente and  e.idtipotrabajo = d.idtipotrabajo
			  left join  mct_partetipotrabajoactividad f on f.idpartetipotrabajo = e.idcomponentetipotrabajo
			  left join  mct_actividad g                 on g.idactividad = f.idactividad
			  left join  mct_seccionactividad h          on g.idactividad = h.idactividad
			  left join  mct_seccion i                   on h.idseccion = i.idseccion
			where a.codhojaruta = roadmapse
			  and e.idtipotrabajo = d.idtipotrabajo 
			  order by f.idpartetipotrabajo asc;

END;
$$;


ALTER FUNCTION traking.evtlistroadmapbodypdf(roadmapse character varying) OWNER TO postgres;

--
-- TOC entry 1393 (class 1255 OID 17327)
-- Name: evtlistroadmapdata(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistroadmapdata(roadmapse character varying) RETURNS TABLE(idhojarutatemp bigint, nombreparte character varying, idcomponente bigint, nombrecomponente character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		 
    select a.idhojarutatemp,
           cast(upper(b.componentechecklist)||' - '||b.textoadicional as varchar),
           b.idcomponente,
           cast(upper(c.nombrecomponente)||' - '||b.textoadicional as varchar)
      from mct_detallehojarutatemp a,
           mct_hojarutatemp b ,
           mct_componente c
     where a.codhojaruta = roadmapse
       and a.idhojarutatemp = b.idhojarutatemp
       and b.idcomponente = c.idcomponente;
    

END;
$$;


ALTER FUNCTION traking.evtlistroadmapdata(roadmapse character varying) OWNER TO postgres;

--
-- TOC entry 1857 (class 1255 OID 17328)
-- Name: evtlistroadmapheadpdf(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistroadmapheadpdf(idworkorderse bigint) RETURNS TABLE(idworkorder bigint, workordername character varying, rodmapcode character varying, customername character varying, idpart bigint, partname character varying, quantity integer, idblueprint bigint, blueprintname character varying, idmaterial bigint, materialname character varying, idparttype bigint, parttypename character varying, critical bigint, criticalname text, comercialdesc character varying, idpurchasetype bigint, purchasetypename character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		 
		select f.idordentrabajo, f.nombreordentrabajo, b.codhojaruta, i.nombrecliente, a.idparte, 
		       c.nombreparte, h.cantidad, c.idplano, e.nombreplano, c.idmaterial, d.nombrematerial, 
		       c.idtipoparte, j.nombretipoparte, 
		       c.escritico, 
		       case when c.escritico=1 then '** ES COMPONENTE CRITICO ** '
                    when c.escritico=2 then '** NO ES CRITICO **'
                   else '** NO DEFINIDO **'
               end,
               c.descripcioncomercial ,
               c.idtipocompra ,
               l.nombretipocompra 
		from mct_ordentrabajo f		
			left join  mct_ordentrabajoparte a on a.idordentrabajo      = f.idordentrabajo 
			left join  mct_hojaruta b          on a.idordentrabajoparte = b.idordentrabajoparte
			left join  mct_parte c             on a.idparte             = c.idparte
			left join  mct_material d          on c.idmaterial          = d.idmaterial
			left join  mct_plano e             on c.idplano             = e.idplano	     
			left join  mct_producto g          on f.idproducto          = g.idproducto
	   	 	left join  mct_productoparte h     on a.idparte             = h.idparte --and g.idproducto = h.idproducto
	   	 	left join  mct_cliente i           on f.idcliente           = i.idcliente
			left join  mct_tipoparte j         on c.idtipoparte         = j.idtipoparte
			left join  mct_boleano k           on c.escritico           = k.idboleano
			left join  mct_tipocompra l        on c.idtipocompra        = l.idtipocompra
		where f.idordentrabajo = idworkorderse
		 and g.idproducto = h.idproducto 
		 		 and c.idtipoparte <> 17
		 order by a.idparte asc;

END;
$$;


ALTER FUNCTION traking.evtlistroadmapheadpdf(idworkorderse bigint) OWNER TO postgres;

--
-- TOC entry 1525 (class 1255 OID 17329)
-- Name: evtlistroadmapprioridad(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistroadmapprioridad(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idroadmap bigint, roadmapcode character varying, idpart bigint, txtpart text, partname character varying, idpartworkorder bigint, lastmov character varying, namelastmov character varying, colorstatus integer, funditiondate timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

        SELECT traking.mct_ordentrabajoparte.idordentrabajo,
               traking.mct_hojaruta.idhojaruta, 
               traking.mct_hojaruta.codhojaruta, 
               traking.mct_parte.idparte,
               LPAD(traking.mct_parte.idparte::integer::text::varchar, 3, '0'),
               traking.mct_parte.nombreparte,
               traking.mct_hojaruta.idordentrabajoparte,
               cast('S_FU' as varchar),
               cast('Solicitud Fundicion' as varchar),
               0,
               coalesce(traking.mct_hojaruta.fechafundicion, now())
        FROM traking.mct_hojaruta,
             traking.mct_ordentrabajoparte,
             traking.mct_parte
       where traking.mct_hojaruta.idordentrabajoparte=traking.mct_ordentrabajoparte.idordentrabajoparte
         and traking.mct_ordentrabajoparte.idparte = traking.mct_parte.idparte
         and traking.mct_ordentrabajoparte.idordentrabajo = idworkorders;

END;
$$;


