--
-- TOC entry 1315 (class 1255 OID 17332)
-- Name: evtlistroadmaptempheadpdf(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistroadmaptempheadpdf(idworkorderse bigint, idroadmaptempse bigint) RETURNS TABLE(idworkorder bigint, idroadmaptemp bigint, idcomponent bigint, workordername character varying, rodmapcode character varying, customername character varying, correlative bigint, partname character varying, materialname character varying, blueprintname character varying, quantity bigint, partworkname text, aditionaltext character varying, familyname character varying, idimprimehojas bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

        if ( idroadmaptempse = 0) then
 
            RETURN QUERY
            
		        select a.idordentrabajo ,
				       a.idhojarutatemp ,
				       a.idcomponente ,
					   d.nombreordentrabajo ,
					   b.codhojaruta ,
					   e.nombrecliente ,
					   b.correlativoparte ,
				       c.nombrecomponente ,
				       a.nombrematerial ,
				       a.nombreplano ,
				       a.cantidad ,
				       case
				          when a.idtrabajohr = 1 then 'FABRICACIÓN'
				          when a.idtrabajohr = 2 then 'RECUPERACIÓN'
				          else 'N/A'
				       end,
				       a.textoadicional ,
				       f.nombrefamilia ,
				       a.idimprimehojas 
				  from mct_hojarutatemp a,
				       mct_detallehojarutatemp b,
				       mct_componente c,
				       mct_ordentrabajo d ,
				       mct_cliente e,
				       mct_familia f
				 where a.idhojarutatemp = b.idhojarutatemp 
				   and a.idordentrabajo = idworkorderse
			       and d.idcliente      = e.idcliente 
				   and a.idordentrabajo = d.idordentrabajo 
				   and a.idcomponente   = c.idcomponente
				   and d.idfamilia = f.idfamilia ;
		  
        else
        
            RETURN QUERY

				select a.idordentrabajo ,
				       a.idhojarutatemp ,
				       a.idcomponente ,
					   d.nombreordentrabajo ,
					   b.codhojaruta ,
					   e.nombrecliente ,
					   b.correlativoparte ,
				       c.nombrecomponente ,
				       a.nombrematerial ,
				       a.nombreplano ,
				       a.cantidad    ,
				       case
				          when a.idtrabajohr = 1 then 'FABRICACIÓN'
				          when a.idtrabajohr = 2 then 'RECUPERACIÓN'
				          else 'N/A'
				       end,
				       a.textoadicional ,
				       f.nombrefamilia  ,
				       a.idimprimehojas  
				  from mct_hojarutatemp a,
				       mct_detallehojarutatemp b,
				       mct_componente c,
				       mct_ordentrabajo d ,
				       mct_cliente e,
				       mct_familia f
				 where a.idhojarutatemp = b.idhojarutatemp 
				   and a.idordentrabajo = idworkorderse
				   and a.idhojarutatemp = idroadmaptempse
			       and d.idcliente      = e.idcliente 
				   and a.idordentrabajo = d.idordentrabajo 
				   and a.idcomponente   = c.idcomponente
				   and d.idfamilia = f.idfamilia ;      
        
        end if;
       


	
END;
$$;


ALTER FUNCTION traking.evtlistroadmaptempheadpdf(idworkorderse bigint, idroadmaptempse bigint) OWNER TO postgres;

--
-- TOC entry 2185 (class 1255 OID 17333)
-- Name: evtlistroadmaptempheadpdfpieza(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistroadmaptempheadpdfpieza(idworkorderse bigint, idroadmaptempse bigint) RETURNS TABLE(idworkorder bigint, idroadmaptemp bigint, idcomponent bigint, workordername character varying, rodmapcode character varying, customername character varying, correlative bigint, partname character varying, materialname character varying, blueprintname character varying, quantity bigint, criterioevaluacionname character varying, aditionaltext character varying, familyname character varying, idimprimehojas bigint, checklisturgente boolean, productname text, nombrezona character varying, cambiamaterial boolean, textocambiamaterial character varying, cambiaplano boolean, textocambiaplano character varying, cambiatrabajo boolean, textocambiatrabajo character varying, cambiacantidad boolean, textocambiacantidad character varying, cambiazona boolean, textocambiazona character varying)
    LANGUAGE plpgsql
    AS $$
declare

	    rec_trab       			RECORD;	

	    sp_cambiamaterial		boolean;
    	sp_textocambiamaterial	varchar;

    	sp_cambiaplano			boolean;
    	sp_textocambiaplano		varchar;

    	sp_cambiatrabajo		boolean;
    	sp_textocambiatrabajo	varchar;

    	sp_cambiacantidad		boolean;
    	sp_textocambiacantidad	varchar;

    	sp_cambiazona			boolean;
    	sp_textocambiazona		varchar;
   
BEGIN

        if ( idroadmaptempse = 0) then
 
            RETURN QUERY
            
		        select a.idordentrabajo ,
				       a.idhojarutatemp ,
				       a.idcomponente ,
					   d.nombreordentrabajo ,
					   b.codhojaruta ,
					   e.nombrecliente ,
					   b.correlativoparte ,
				       c.nombrecomponente ,
				       a.nombrematerial ,
				       a.nombreplano ,
				       a.cantidad ,
				       --g.nombrecriterioevaluacion ,
				       g.alias as nombrecriterioevaluacion,
				       --case
				       --   when a.idtrabajohr = 1 then 'FABRICACIÓN'
				       --   when a.idtrabajohr = 2 then 'RECUPERACIÓN'
				       --   else 'N/A'
				       --end,
				       a.textoadicional ,
				       f.nombrefamilia ,
				       a.idimprimehojas ,
				       d.checklisturgente ,
				       j.sigla ||' '||i.nombremodelo||' '||k.nombreparam ,
				       coalesce(a.nombrezona,'') 
				  from mct_hojarutatemp a
				  left join  mct_detallehojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
				  left join  mct_componente c on a.idcomponente   = c.idcomponente
				  left join  mct_ordentrabajo d on a.idordentrabajo = d.idordentrabajo 
				  left join  mct_cliente e on d.idcliente      = e.idcliente 
				  left join  mct_familia f on d.idfamilia = f.idfamilia
				  left join  mct_criterioevaluacion g on a.idcriterioevaluacion = g.idcriterioevaluacion
				  left join  mct_producto h on  d.idproducto = h.idproducto
				  left join  mct_modelo i on h.idmodelo = i.idmodelo 
				  left join  mct_subfamilia j on i.idsubfamilia = j.idsubfamilia
				  left join  mct_etapaparam k on h.idetapaparam = k.idetapaparam
				 where a.idordentrabajo = idworkorderse;
		  
        else
        
  		    FOR rec_trab IN (   
				  
			        select a.idordentrabajo ,
					       a.idhojarutatemp ,
					       a.idcomponente ,
						   d.nombreordentrabajo ,
						   b.codhojaruta ,
						   e.nombrecliente ,
						   b.correlativoparte ,
					       c.nombrecomponente ,
					       a.nombrematerial ,
					       a.nombreplano ,
					       a.cantidad ,
					       --g.nombrecriterioevaluacion ,
				           g.alias as nombrecriterioevaluacion,
					       --case
					       --   when a.idtrabajohr = 1 then 'FABRICACIÓN'
					       --   when a.idtrabajohr = 2 then 'RECUPERACIÓN'
					       --   else 'N/A'
					       --end,
					       a.textoadicional ,
					       f.nombrefamilia ,
					       a.idimprimehojas ,
					       d.checklisturgente ,
					       j.sigla ||' '||i.nombremodelo||' '||k.nombreparam as nombrezona,
					       coalesce(a.nombrezona,'') as nombrezona
					  from mct_hojarutatemp a
					  left join  mct_detallehojarutatemp b on a.idhojarutatemp = b.idhojarutatemp
					  left join  mct_componente c on a.idcomponente   = c.idcomponente
					  left join  mct_ordentrabajo d on a.idordentrabajo = d.idordentrabajo 
					  left join  mct_cliente e on d.idcliente      = e.idcliente 
					  left join  mct_familia f on d.idfamilia = f.idfamilia
					  left join  mct_criterioevaluacion g on a.idcriterioevaluacion = g.idcriterioevaluacion
					  left join  mct_producto h on  d.idproducto = h.idproducto
					  left join  mct_modelo i on h.idmodelo = i.idmodelo 
					  left join  mct_subfamilia j on i.idsubfamilia = j.idsubfamilia
					  left join  mct_etapaparam k on h.idetapaparam = k.idetapaparam
					 where a.idordentrabajo = idworkorderse
					   and a.idhojarutatemp = idroadmaptempse
				  
         		       )
				
				loop 	

					
					sp_cambiamaterial		:= false;
    				sp_textocambiamaterial	:= '';

    				sp_cambiaplano			:= false;
    				sp_textocambiaplano		:= '';

    				sp_cambiatrabajo		:= false;
    				sp_textocambiatrabajo		:= '';

    				sp_cambiacantidad		:= false;
    				sp_textocambiacantidad	:= '';

    				sp_cambiazona			:= false;
    				sp_textocambiazona		:= '';
    			
    			     select a.cambiamaterial,
    			            case
	    			            when a.cambiamaterial is true then
	    			                 'Material MAL Ingresado a Check List'
	    			            else
	    			                 ''
	    			        end,
    			            a.cambiaplano,
    			            case
	    			            when a.cambiaplano is true then
	    			                 'Número de Plano MAL Ingresado a Check List'
	    			            else
	    			                 ''
	    			        end,
    			            a.cambiatrabajo,
    			            case
	    			            when a.cambiatrabajo is true then
	    			                 'Trabajo a Ejecutar MAL Ingresado a Check List'
	    			            else
	    			                 ''
	    			        end,
    			            a.cambiacantidad,
    			            case
	    			            when a.cambiacantidad is true then
	    			                 'Cantidades MAL Ingresadas a Check List'
	    			            else
	    			                 ''
	    			        end,
    			            a.cambiazona,
    			            case
	    			            when a.cambiazona is true then
	    			                 'Zona MAL Ingresada a Check List'
	    			            else
	    			                 ''
	    			        end
    			       into sp_cambiamaterial,
    			            sp_textocambiamaterial,
    			            sp_cambiaplano,
    			            sp_textocambiaplano,
    			            sp_cambiatrabajo,
    			            sp_textocambiatrabajo,
    			            sp_cambiacantidad,
    			            sp_textocambiacantidad,
    			            sp_cambiazona,
    			            sp_textocambiazona
    			       from mct_hojarutatempcambio a
    			       -- join mct_hojarutatempcambio b on a.idhojarutatemp = b.idhojarutatemp and a.idhojarutatempcambio = ( select max(b.idhojarutatempcambio) from mct_hojarutatempcambio b where a.idhojarutatemp = b.idhojarutatemp  ) 
                      where a.idhojarutatemp = idroadmaptempse
                        and a.idhojarutatempcambio = ( select max(b.idhojarutatempcambio) from mct_hojarutatempcambio b where a.idhojarutatemp = b.idhojarutatemp  );
    			       
					 idworkorder			:= rec_trab.idordentrabajo; 
			         idroadmaptemp 			:= rec_trab.idhojarutatemp;  
			         idcomponent 			:= rec_trab.idcomponente; 
			         workordername 			:= rec_trab.nombreordentrabajo;  
			         rodmapcode 			:= rec_trab.codhojaruta;  
			         customername 			:= rec_trab.nombrecliente;  
			         correlative 			:= rec_trab.correlativoparte;  
			         partname 				:= rec_trab.nombrecomponente; 
			         materialname 			:= rec_trab.nombrematerial; 
			         blueprintname 			:= rec_trab.nombreplano; 
			         quantity 				:= rec_trab.cantidad;  
			         criterioevaluacionname := rec_trab.nombrecriterioevaluacion;  
			         aditionaltext 			:= rec_trab.textoadicional;  
			         familyname 			:= rec_trab.nombrefamilia;  
			         idimprimehojas 		:= rec_trab.idimprimehojas;  
			         checklisturgente 		:= rec_trab.checklisturgente; 
			         productname 			:= rec_trab.nombrezona;  
			         nombrezona 			:= rec_trab.nombrezona; 
			        
					 cambiamaterial			:= sp_cambiamaterial;
    				 textocambiamaterial	:= sp_textocambiamaterial;

    				 cambiaplano			:= sp_cambiaplano;
    				 textocambiaplano		:= sp_textocambiaplano;

    				 cambiatrabajo			:= sp_cambiatrabajo;
    				 textocambiatrabajo		:= sp_textocambiatrabajo;

    				 cambiacantidad			:= sp_cambiacantidad;
    				 textocambiacantidad	:= sp_textocambiacantidad;

    				 cambiazona				:= sp_cambiazona;
    				 textocambiazona		:= sp_textocambiazona;			        
					
					return next;
				
				end loop;
				
		end if;
       

END;
$$;


ALTER FUNCTION traking.evtlistroadmaptempheadpdfpieza(idworkorderse bigint, idroadmaptempse bigint) OWNER TO postgres;

--
-- TOC entry 980 (class 1255 OID 17335)
-- Name: evtlistscandata(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistscandata(scancode character varying) RETURNS TABLE(idworkorder bigint, idcomponent bigint, idclient bigint, idproduct bigint, productname character varying, customername character varying, componentname character varying, idnoconformidadcald bigint, idseccion bigint, comentario character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
		return QUERY
		select  
				d.idordentrabajo,
				c.idcomponente,
				e.idcliente,
				f.idproducto,
				f.nombreproducto,
				e.nombrecliente, 
		        c.nombrecomponente,   
		        coalesce(g.idnoconformidadcald,0) as idnoconformidadcald,
		        case 
		           when g.idcierre = 0 then coalesce(g.idseccion,0)
		           else 0
		        end as idseccion,
		        case 
		           when g.idcierre = 0 then coalesce(g.comentario,'')
		           else ''
		        end as comentario
		from mct_detallehojarutatemp a,
		       mct_hojarutatemp b,
		       mct_componente c,
		       mct_ordentrabajo d,
		       mct_cliente e,
		       mct_producto f
		left join  traking.mct_noconformidadcald g on (  g.codhojaruta = scancode and g.idcierre = 0 )
		where a.codhojaruta = scancode
		   and a.idhojarutatemp = b.idhojarutatemp 
		   and b.idcomponente = c.idcomponente
		   and b.idordentrabajo = d.idordentrabajo 
		   and e.idcliente = d.idcliente 
		   and f.idproducto = d.idproducto
		   ;


   END;
$$;


ALTER FUNCTION traking.evtlistscandata(scancode character varying) OWNER TO postgres;

--
-- TOC entry 1958 (class 1255 OID 17336)
-- Name: evtlistscreenplanta(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistscreenplanta(idsections bigint) RETURNS TABLE(machinename character varying, roadmapcode character varying, idpart bigint, partname character varying, blueprintname character varying, priority integer, lastactivity character varying, termino character varying)
    LANGUAGE plpgsql
    AS $$
declare

		sp_lastacti 	VARCHAR;
		rec1 			record;
	   
BEGIN

    --RETURN QUERY
			 		 
	   FOR rec1 IN (   
					select --a.idmovimientoordentrabajo,
					       --a.idmaquina ,
					       b.nombremaquina 		as machinename,
					       a.codhojaruta 		as roadmapcode,
					       a.idparte 			as idpart,
					       c.nombreparte 		as partname,
					       --c.idplano ,
					       d.nombreplano 		as blueprintname,
					       cast(1 as integer)	as priority,
					       a.idhojaruta ,
					       case
					           when a.idmotivocierre = 25 then
					                cast('P' as varchar) 
					           when a.idmotivocierre = 42 then 
					                cast('J' as varchar) 
					           else 
					                null				
					       end as termino
					from mct_movimientoordentrabajo a,
					     mct_maquina b,
					     mct_parte c,
					     mct_plano d,
					     mct_ordentrabajo e
					where a.idseccion = idsections
					and   a.idmaquina is not null
					and   a.idmaquina = b.idmaquina
					and   a.idparte = c.idparte 
					and   c.idplano = d.idplano
					and   a.idordentrabajo = e.idordentrabajo 
					and   e.idestadoorden < 8
					and   a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
							                                           from mct_movimientoordentrabajo b 
							                                          where b.idhojaruta = a.idhojaruta 
							                                            and idseccion = a.idseccion )
		            union
		            select --a.idmovimientoordentrabajo,
					       --a.idmaquina ,
					       b.nombremaquina 		as machinename,
					       a.codhojaruta 		as roadmapcode,
					       a.idparte 			as idpart,
					       c.nombrecomponente 	as partname,
					       --c.idplano ,
					       d.nombreplano 		as blueprintname,
					       cast(1 as integer)	as priority,
					       a.idhojaruta ,
					       case
					           when a.idmotivocierre = 25 then
					                cast('P' as varchar) 
					           when a.idmotivocierre = 42 then 
					                cast('J' as varchar) 
					           else 
					                null				
					       end as termino
					from mct_movimientoordentrabajo a,
					     mct_maquina b,
					     mct_componente c,
					     mct_hojarutatemp d,
					     mct_ordentrabajo e
					where a.idseccion = idsections
					and   a.idmaquina is not null
					and   a.idmaquina = b.idmaquina
					and   a.idparte   = c.idcomponente 
					and   a.idordentrabajo = d.idordentrabajo 
					and   a.idparte = d.idcomponente 
					and   a.idordentrabajo = e.idordentrabajo 
					and   e.idestadoorden < 8
					and   a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
							                                           from mct_movimientoordentrabajo b 
							                                          where b.idhojaruta = a.idhojaruta 
							                                            and idseccion = a.idseccion )
							                                       
					)
		loop 				 
		
		      sp_lastacti	 := '';
		      
		      select codigoaccion
		        into sp_lastacti
		        from mct_movimientoordentrabajo mm
		       where idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
		                                           from mct_movimientoordentrabajo b 
		                                          where b.idhojaruta = rec1.idhojaruta );
		                                         
		      
		      machinename	:=  rec1.machinename; 
		      roadmapcode 	:=	rec1.roadmapcode; 
		      idpart 		:=	rec1.idpart; 
		      partname 		:=	rec1.partname;
		      blueprintname :=	rec1.blueprintname; 
		      priority 		:=	rec1.priority; 
		      lastactivity 	:=	sp_lastacti; 
		      termino 		:=	rec1.termino; 

		      RETURN NEXT;
		     
		END LOOP;
END;
$$;


ALTER FUNCTION traking.evtlistscreenplanta(idsections bigint) OWNER TO postgres;

