--
-- TOC entry 2373 (class 1255 OID 17339)
-- Name: evtlistseqblueprint(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistseqblueprint(bpname character varying) RETURNS TABLE(idblueprint bigint, blueprintname text, lastblueprint text, quantityblueprint bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ((select count(*) from (select regexp_split_to_table(bpname, '-')) as a) = 3 ) then
	    RETURN QUERY
    
        SELECT max(traking.mct_plano.idplano), 
               split_part(bpname,'-',1)||'-'||split_part(bpname,'-',2),
               max(traking.mct_plano.nombreplano), 
               count(*)
          FROM traking.mct_plano
         WHERE traking.mct_plano.nombreplano like '%'||split_part(bpname,'-',1)||'-'||split_part(bpname,'-',2)||'%'
           and traking.mct_plano.idtipoplano = 44
           and substr(split_part(nombreplano,'-',3),1,1) between  '0' and '9'
		group by split_part(bpname,'-',1)||'-'||split_part(bpname,'-',2);
	
	else
	
    	RETURN QUERY
    
        SELECT max(traking.mct_plano.idplano), 
               split_part(bpname,'-',1),
               max(traking.mct_plano.nombreplano), 
               count(*)
          FROM traking.mct_plano
         WHERE traking.mct_plano.nombreplano like '%'||split_part(bpname,'-',1)||'%'
           and traking.mct_plano.idtipoplano = 40
           and substr(split_part(nombreplano,'-',2),1,1) between  '0' and '9'
		group by split_part(bpname,'-',1);

	end if;

END;
$$;


ALTER FUNCTION traking.evtlistseqblueprint(bpname character varying) OWNER TO postgres;

--
-- TOC entry 2054 (class 1255 OID 17340)
-- Name: evtlistsimulacionmaquinaop(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistsimulacionmaquinaop(startdate character varying, enddate character varying) RETURNS TABLE(idsimulacionmaquinaop bigint, fechadesde character varying, fechahasta character varying, nombreseccion character varying, nombremaquina character varying, operador1 character varying, operador2 character varying, normal bigint, masdos bigint, mascuatro bigint, masseis bigint, usercreate character varying, datecreate timestamp without time zone, userupdate character varying, dateupdate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
declare

	sp_tiene	integer;

BEGIN

  	  sp_tiene := 0;
   
	    select count(*)
	      into sp_tiene
		  from mct_simulacionmaquinaop a
		 where (a.fechadesde >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechahasta <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) ;
	    
		if (sp_tiene = 0) then 
		
			INSERT INTO traking.mct_simulacionmaquinaop
						(idsimulacionmaquinaop, 
						 fechadesde, 
						 fechahasta, 
						 nombreseccion, 
						 nombremaquina, 
						 usuariocreacion, 
						 fechacreacion
						 )
				select nextval('mct_simulacionmaquinaop_seq'),
				       to_date(startdate, 'yyyy-mm-dd'),
				       to_date(enddate, 'yyyy-mm-dd'),
			           c.nombreseccion , 
			           a.nombremaquina,
			           'admin',
			           now()
				from mct_maquina a,
				     mct_subseccion b,
				     mct_seccion c
				where a.idsubseccion = b.idsubseccion 
				and   b.idseccion = c.idseccion 
				and   b.idseccion in (1,6,9,7,3,5)
				order by b.idseccion , nombremaquina ;		 
						 
		end if; 
	
	
        RETURN QUERY
        
		select a.idsimulacionmaquinaop,
	 	       cast(to_char(a.fechadesde, 'dd-mm-yyyy') as varchar),
			   cast(to_char(a.fechahasta, 'dd-mm-yyyy') as varchar),
			   a.nombreseccion,
			   a.nombremaquina,
			   a.operador1,
			   a.operador2,
			   a.normal,
			   a.masdos,
			   a.mascuatro,
		       a.masseis,
			   a.usuariocreacion,
			   a.fechacreacion,
			   a.usuariomodificacion,
			   a.fechamodificacion
	      from mct_simulacionmaquinaop a
		 where (a.fechadesde >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and a.fechahasta <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS')) ;
    

END;
$$;


ALTER FUNCTION traking.evtlistsimulacionmaquinaop(startdate character varying, enddate character varying) OWNER TO postgres;

