--
-- TOC entry 1582 (class 1255 OID 17343)
-- Name: evtlisttiempotrabajoonline(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisttiempotrabajoonline(roadmapcodes character varying) RETURNS TABLE(codesection character varying, operatorname character varying, timework integer)
    LANGUAGE plpgsql
    AS $$

begin 

    RETURN QUERY
    
    select tab.codigoaccion,
           tab.nombreaccion,
           cast(sum(tab.timework) as integer)
      from (
			select a.codigoaccion  ,
			       b.nombreaccion  ,
			       case
					   when a.fechatermino is null then
							  cast((date_part('day', now()::timestamp - (a.fechainicio)::timestamp ) * 1440 + 
									date_part('hour', now()::timestamp - (a.fechainicio)::timestamp ) * 60 + 
									date_part('minute', now()::timestamp - (a.fechainicio)::timestamp )) as integer)
					   when a.fechatermino is not null then 
						      cast((date_part('day', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp ) * 1440 + 
								    date_part('hour', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp ) * 60 + 
								    date_part('minute', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp )) as integer)		          
				   end as timework
			from mct_movimientoordentrabajo a,
			     mct_accion b
			where a.codhojaruta = roadmapcodes
			and   a.codigoaccion = b.codigoaccion 
			group by a.codigoaccion, 
			         b.nombreaccion, 
			         case
						 when a.fechatermino is null then
							  cast((date_part('day', now()::timestamp - (a.fechainicio)::timestamp ) * 1440 + 
									date_part('hour', now()::timestamp - (a.fechainicio)::timestamp ) * 60 + 
									date_part('minute', now()::timestamp - (a.fechainicio)::timestamp )) as integer)
						 when a.fechatermino is not null then 
						      cast((date_part('day', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp ) * 1440 + 
								    date_part('hour', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp ) * 60 + 
								    date_part('minute', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp )) as integer)		          
				    end
				    
				    ) tab
			group by tab.codigoaccion,
                     tab.nombreaccion
			order by tab.codigoaccion asc;
		
END;
$$;


ALTER FUNCTION traking.evtlisttiempotrabajoonline(roadmapcodes character varying) OWNER TO postgres;

