--
-- TOC entry 1990 (class 1255 OID 17346)
-- Name: evtlisttmpbodytracingts_prioridades(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisttmpbodytracingts_prioridades(idworkorders bigint) RETURNS TABLE(item bigint, idworkorder bigint, idpartworkorder bigint, idpart bigint, partname character varying, timeday integer, tothour character varying, deadtime character varying, idroadmap bigint, coderoadmap character varying, lastactivity character varying, statuslastactivity bigint, stjason character varying, rownum integer, idmovot bigint, actioncode character varying, activstatus bigint, itemcorr character varying, maquina character varying, plano character varying, operador character varying)
    LANGUAGE plpgsql
    AS $$
declare	 

	rec3 				record;
	sp_lastacti 		VARCHAR;
	sp_estadolast   	integer;
    sp_fechasolicitud	timestamp;
   
    sp_tiempo			bigint;
    
    intervalo			varchar;
    sp_diferencia		varchar;
    sp_operador			varchar;

begin
	
	delete 
	  from traking.mct_tmpbodytracingts_prioridades a
	 where a.idworkorder = idworkorders;

	   	   FOR rec3 IN (  
					select a.idordentrabajo            as idordentrabajo,
					       coalesce (e.nombrezona,'I') as nombrezona,
					       e.nombrezona,
					       a.idordentrabajoparte       as idordentrabajoparte,
					       a.idcomponente              as idparte ,
					       coalesce (b.nombrecomponente||' '||e.textoadicional , b.nombrecomponente) as nombreparte,
					       1                           as uno,
					       c.idhojaruta                as idhojaruta,
					       c.codhojaruta               as codhojaruta,
					       a.itemcorr ,
					       case 
					          when e.idimprimehojas = 2 then 1
					          else e.cantidad 
					       end as cantidad,
					       e.idimprimehojas,
					       e.idareaclasificacion ,
					       coalesce (g.sigla, 'STD') as sigla,
					       coalesce (e.nombrezona , 'I') as siglazona,
					       e.nombreplano 
					  from mct_ordentrabajoparte a
					  inner join mct_componente b             on a.idcomponente = b.idcomponente 
					  inner join mct_hojaruta c               on a.idordentrabajoparte = c.idordentrabajoparte     
					   left join mct_detallehojarutatemp f    on c.codhojaruta = f.codhojaruta 
					   left join mct_hojarutatemp e           on e.idhojarutatemp  = f.idhojarutatemp  
					   left join mct_areaclasificacion g      on e.idareaclasificacion = g.idareaclasificacion 
					 where a.idordentrabajo = idworkorders
					   and c.idhojarutatemp = e.idhojarutatemp 
					   and e.idboleano = 1
					   and e.aplicahojaruta is true
					  order by coalesce (e.nombrezona,'I'), b.nombrecomponente asc,c.codhojaruta asc
					  )
			   Loop
					  select a.codigoaccion, 
				             a.estadoactividad,
				             a.fechainicio,
				             cast(case
					          when a.fechatermino is null then
					          	   cast((date_part('day', now()::timestamp - a.fechainicio::timestamp ) * 1440 + 
						         		 date_part('hour', now()::timestamp - a.fechainicio::timestamp ) * 60 + 
								 		 date_part('minute', now()::timestamp - a.fechainicio::timestamp )) as integer)
					          when fechatermino is not null then 
					          	   cast((date_part('day', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 1440 + 
						         		 date_part('hour', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 60 + 
								 		 date_part('minute', a.fechatermino::timestamp - a.fechainicio::timestamp )) as integer)		          
					       end as varchar) as tiempo,
					       c.nombreoperador
				        into sp_lastacti, 
				             sp_estadolast,
				             sp_fechasolicitud,
				             sp_tiempo,
				             sp_operador
				        from mct_movimientoordentrabajo a
				        left join mct_operador c on a.idoperador = c.idoperador
				       where a.idmovimientoordentrabajo = (select max(idmovimientoordentrabajo) 
				                                           from mct_movimientoordentrabajo b 
				                                          where b.idhojaruta = rec3.idhojaruta )
				         and estadoactividad in (2, 7);
				                                         
         
				        intervalo := ''''||sp_tiempo||' minute';
		                sp_diferencia     :=  to_char(intervalo::interval, 'HH24:MI');
		     
						INSERT INTO traking.mct_tmpbodytracingts_prioridades
						            (
							         idworkorder, 
							         idpartworkorder, 
							         idpart, 
							         partname,
							         timeday, 
							         tothour,
							         deadtime,
							         idroadmap, 
							         coderoadmap,
							         lastactivity,
							         statuslastactivity, 
							         stjason, 
							         rownum, 
							         idmovot, 
							         actioncode,
							         activstatus,
							         itemcorr,
							         maquina,
							         plano,
							         operador
						             )
						       VALUES(
						              idworkorders,
						              rec3.idordentrabajoparte,
						              rec3.idparte,
						              rec3.nombreparte,
						              0,
						              null,
						              null,
						              rec3.idhojaruta,
						              rec3.codhojaruta,
						              sp_lastacti||'/('||sp_diferencia||')',
						              0,
						              null,
						              0,
						              0,
						              case
						                 when sp_lastacti in ('S_CC','S_FU','S_PA','S_REC','S_SLD') then 'PROVEEDORES'
						                 when sp_lastacti in ('L_CC','R_TM') then 'TERMINADA'
						                 when sp_lastacti in ('RE_CC','CC_OK','R/E_CC','CC','CC_PA','M_CC','CC') then 'CONTROL DE CALIDAD'
						                 else 'MECANIZADO'
						              end,
						              case
						                 when sp_lastacti in ('S_CC','S_FU','S_PA','S_REC','S_SLD') then 1
						                 when sp_lastacti in ('L_CC','R_TM') then 4
						                 when sp_lastacti in ('RE_CC','CC_OK','R/E_CC','CC','CC_PA','M_CC','CC') then 3
						                 else 2
						              end,
						              --rec3.itemcorr,
						              rec3.siglazona||'-'||rec3.sigla||'-'||LPAD(rec3.itemcorr::integer::text::varchar, 3, '0'),
						              'N/A',
						              rec3.nombreplano,
						              sp_operador
						             );
						            		                                   
			     
			END LOOP;
		
		    return QUERY
		    
		    select row_number() over (order by a.itemcorr  asc),
			       a.idworkorder, 
			       a.idpartworkorder, 
			       a.idpart, 
			       a.partname, 
			       cast(a.timeday as integer), 
			       coalesce(a.tothour, '0' ), 
			       coalesce(a.deadtime, '0' ), 
			       a.idroadmap, 
			       a.coderoadmap,
			       a.lastactivity, 
			       a.statuslastactivity, 
			       a.stjason, 
			       cast(a.rownum as integer), 
			       a.idmovot, 
			       a.lastactivity, --cast('N/A' as varchar), 
			       a.activstatus, 
			       a.itemcorr, 
			       a.maquina,
			       a.plano,
			       a.operador 
		      from traking.mct_tmpbodytracingts_prioridades a
		     where a.idworkorder = idworkorders
		       and a.actioncode != 'TERMINADA'
		       and a.lastactivity is not null;
	
	
END;
$$;


ALTER FUNCTION traking.evtlisttmpbodytracingts_prioridades(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1139 (class 1255 OID 17348)
-- Name: evtlisttmpreporteavancemecanizado(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisttmpreporteavancemecanizado(idworkorders bigint) RETURNS TABLE(item bigint, idworkorder bigint, idroadmap bigint, itemcorr character varying, coderoadmap character varying, partname character varying, lastactivity character varying, requestdate character varying, days bigint, quantity bigint, orderroadmap bigint, conceptname character varying)
    LANGUAGE plpgsql
    AS $$
declare	 

	rec1 				record;
	sp_lastacti 		VARCHAR;
	sp_estadolast   	integer;
    sp_fechasolicitud	timestamp;

begin

