--

CREATE FUNCTION traking.evtlisttrabajosonline() RETURNS TABLE(idareaapp bigint, nombrearea character varying, idseccionapp bigint, nombreseccionapp character varying, idmaquina bigint, nombremaquina character varying, idoperador bigint, nombreoperador character varying, idperfil bigint, nombreperfil character varying, idseccionprincipal bigint, nombreseccionpri character varying, idcargo bigint, nombrecargo character varying, idcargoapp bigint, nombrecargoapp character varying, rut character varying, hojaruta character varying, idot bigint, accion character varying, fechainicio character varying, fechatermino character varying, observacion character varying, idmaquinatra bigint, inicioam character varying, iniciopm character varying, tipotrabajo character varying, producto character varying, nompreparte character varying, plano character varying, tmpoacum bigint, ausentetn boolean, ausentevac boolean, ausenteper boolean)
    LANGUAGE plpgsql
    AS $$
declare	 

	rec_mat 			record;

	sp_hojaruta			varchar;
	sp_idot				bigint;
	sp_accion			varchar;
    sp_fechainicio		varchar;
    sp_fechatermino		varchar;
    sp_observacion		varchar;
    sp_idmaquina		bigint;
    
    sp_inicioam 		varchar;
    sp_iniciopm 		varchar;
    sp_tipotrabajo 		varchar;
    sp_producto 		varchar;
    sp_nompreparte 		varchar;
    sp_plano 			varchar;
    sp_tmpoacum 		bigint;
    sp_nombreaccion		varchar;
    sp_minfechainicioam	timestamp;
    sp_minfechainiciopm	timestamp;
	

    sp_sinmarcaAM       bigint;
    sp_sinmarcaPM       bigint;

begin


   FOR rec_mat IN (  
			select a.idareaapp ,
			       f.nombrearea,
			       a.idseccionapp ,
			       g.nombreseccion,
			       a.idmaquina ,
			       c.nombremaquina,			       
			       a.idoperador ,
			       a.nombreoperador ,
			       a.idperfil ,
			       b.nombreperfil,			       
			       a.idseccionprincipal ,
			       d.nombreseccion,
			       a.idcargo,
			       e.nombrecargo,			       
			       a.idcargoapp ,
			       h.nombrecargo,
			       a.rut ,
                   i.ausenteTN as ausentetn,
                   i.ausenteVAC as ausentevac,
                   i.ausentePER as ausenteper,
                   j.statusactivo,
                   j.inicioam,
                   j.iniciopm,
                   j.fechacreacion
			from mct_operador a
			left join mct_perfil b  on a.idperfil = b.idperfil 
			left join mct_maquina c on a.idmaquina = c.idmaquina
			left join mct_seccion d on a.idseccionprincipal = d.idseccion 
			left join mct_cargo e   on a.idcargo = e.idcargo 
			left join mct_area f    on a.idareaapp = f.idarea 
			left join mct_seccion g on a.idseccionapp = g.idseccion 
			left join mct_cargo h   on a.idcargoapp = h.idcargo
            left join mct_trabajoonlineausente i on a.idoperador = i.idoperador
            left join mct_trabajoonlinealaespera j on a.idoperador = j.idoperador
			where a.estado = 1
			  and a.idareaapp is not null
			  and a.idareaapp not in (8,7,6,4)
			  and a.idseccionapp not in (85)
			order by g.ordentrabajoonline,1,4,5
			  )
	   Loop

	      idareaapp				:= rec_mat.idareaapp;
		  nombrearea			:= rec_mat.nombrearea;
		  idseccionapp			:= rec_mat.idseccionapp;
		  nombreseccionapp		:= rec_mat.nombreseccion;
		  idmaquina				:= rec_mat.idmaquina;
		    
		 
		  idoperador			:= rec_mat.idoperador;
		  nombreoperador		:= rec_mat.nombreoperador;
		  idperfil				:= rec_mat.idperfil;
		  nombreperfil			:= rec_mat.nombreperfil;    
		  idseccionprincipal	:= rec_mat.idseccionprincipal;
		  nombreseccionpri		:= rec_mat.nombreseccion;
		  idcargo				:= rec_mat.idcargo;
		  nombrecargo			:= rec_mat.nombrecargo;	       
		  idcargoapp			:= rec_mat.idcargoapp;
		  nombrecargoapp		:= rec_mat.nombrecargo;
		  rut					:= rec_mat.rut;	   
		 

		  select a.codhojaruta ,
		         a.idordentrabajo ,
		         a.codigoaccion ,
		         to_char(a.fechainicio , 'dd-mm-yyyy hh24:mi:ss'),
		         to_char(a.fechatermino , 'dd-mm-yyyy hh24:mi:ss'),
		         a.observacion ,
		         a.idmaquina,
		         d.nombreplano ,
		         d.componentechecklist ,
		         e.nombreaccion
		    into sp_hojaruta,
				 sp_idot,
				 sp_accion,
			     sp_fechainicio,
			     sp_fechatermino,
			     sp_observacion,
			     sp_idmaquina,
          		 sp_plano,
          		 sp_nompreparte,
          		 sp_nombreaccion
		    from mct_movimientoordentrabajo a 
		    left join mct_ordentrabajo b        on a.idordentrabajo = b.idordentrabajo 
		    left join mct_detallehojarutatemp c on a.codhojaruta = c.codhojaruta 
		    left join mct_hojarutatemp d        on c.idhojarutatemp = d.idhojarutatemp 
		    left join mct_accion e              on a.codigoaccion = e.codigoaccion
		   where a.idoperador = rec_mat.idoperador
		     and a.estadoactividad = 1;
		    
		  hojaruta		:= sp_hojaruta; 
		  idot			:= sp_idot;
	      accion		:= sp_accion;
          fechainicio	:= sp_fechainicio;
          fechatermino	:= sp_fechatermino;
          observacion	:= sp_observacion;
          idmaquinatra	:= sp_idmaquina;
         
          if (rec_mat.idseccionapp in (6,13,14,36)) then
              nombremaquina			:= sp_nombreaccion;
          else
		      nombremaquina			:= rec_mat.nombremaquina;
		  end if;
		    
         
          select sum(case
					  when a.fechatermino is null then
						   cast((date_part('day', now()::timestamp - (a.fechainicio)::timestamp ) * 1440 + 
						   date_part('hour', now()::timestamp - (a.fechainicio)::timestamp ) * 60 + 
						   date_part('minute', now()::timestamp - (a.fechainicio)::timestamp )) as integer)
					  when a.fechatermino is not null then 
						   cast((date_part('day', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp ) * 1440 + 
					       date_part('hour', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp ) * 60 + 
						   date_part('minute', (a.fechatermino)::timestamp - (a.fechainicio)::timestamp )) as integer)		          
					  end)
			 into sp_tmpoacum
			 from mct_movimientoordentrabajo a 
			where a.codhojaruta = sp_hojaruta ;
		
		    -- Para bombas
			select case 
			          when a.idfamilia = 11 then c.nombreproducto
			          else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
			       end as producto,
			       d.sigla||'_'||e.sigla
			       --d.sigla as siglatipo,
			       --e.sigla as siglafam
			  into sp_producto,
			       sp_tipotrabajo  
			  from mct_ordentrabajo a,
			       mct_producto c,
			       mct_tipoorden d,
			       mct_familia e,
			       mct_modelo g,
			       mct_subfamilia h,
			       mct_etapaparam i
			 where a.idordentrabajo = sp_idot
			   and a.idproducto = c.idproducto 
			   and a.idtipoorden = d.idtipoorden 
			   and a.idfamilia = e.idfamilia
			   and c.idmodelo = g.idmodelo 
			   and g.idsubfamilia = h.idsubfamilia 
			   and c.idetapaparam = i.idetapaparam ;  
		  
		  select coalesce(min(a.fechainicio), '1900-01-01')
		    into sp_minfechainicioam
		    from mct_movimientoordentrabajo a 
		   where a.idoperador = rec_mat.idoperador
		     and a.fechainicio >= to_timestamp(to_char(current_date,'yyyymmdd')||' 05:00:00', 'yyyymmdd hh24:mi:ss');
		    
		  inicioam 		:= 'verde';
          iniciopm 		:= 'verde';
         
		  if (sp_minfechainicioam > to_timestamp(to_char(current_date,'yyyymmdd')||' 07:45:00', 'yyyymmdd hh24:mi:ss') or
              sp_minfechainicioam = '1900-01-01') then
             if (sp_minfechainicioam = '1900-01-01') then
				inicioam 		:= 'default';
			 else
				inicioam 		:= 'rojo';
			 end if;

		  else
		   	 inicioam 		:= 'verde';
		  end if;
		  
		  select coalesce(min(a.fechainicio), '1900-01-01')
		    into sp_minfechainiciopm
			from mct_movimientoordentrabajo a 
		   where a.idoperador = rec_mat.idoperador
	  	     and a.fechainicio >= to_timestamp(to_char(current_date,'yyyymmdd')||' 13:45:00', 'yyyymmdd hh24:mi:ss');
		  
		  if (sp_minfechainiciopm > to_timestamp(to_char(current_date,'yyyymmdd')||' 14:00:00', 'yyyymmdd hh24:mi:ss') or
              sp_minfechainiciopm = '1900-01-01') then
             if (sp_minfechainiciopm = '1900-01-01') then
				iniciopm 		:= 'default';
			 else
				iniciopm 		:= 'rojo';
			 end if;
		  	 
		  else
		   	 iniciopm 		:= 'verde';
		  end if;
		 
          
		  -- Esto para trabajosonline con ausencias
          tipotrabajo 	:= sp_tipotrabajo;
          if (rec_mat.ausentetn is true) then
				tipotrabajo	:= 'Op. Turno Noche';
          elsif (rec_mat.ausentevac is true) then
				tipotrabajo	:= 'Op. Vacaciones';
          elsif (rec_mat.ausenteper is true) then
				tipotrabajo	:= 'Op Permiso';
          end if;

		  -- Esto para trabajosonline con espera de asignacion de trabajo
          if ( rec_mat.inicioam is true and rec_mat.statusactivo is true) then

			  tipotrabajo	:= 'A LA ESPERA DE TRABAJO';
			  if (rec_mat.fechacreacion > to_timestamp(to_char(current_date,'yyyymmdd')||' 07:45:00', 'yyyymmdd hh24:mi:ss') or
	              rec_mat.fechacreacion = '1900-01-01') then
	             if (rec_mat.fechacreacion = '1900-01-01') then

	                select count(*)
			          into sp_sinmarcaAM
					  from mct_movimientoordentrabajo a
					where a.idoperador = rec_mat.idoperador
			          and a.fechainicio >= to_timestamp(to_char(current_date,'yyyymmdd')||' 07:00:00', 'yyyymmdd hh24:mi:ss')
			          and a.fechainicio < to_timestamp(to_char(current_date,'yyyymmdd')||' 08:00:00', 'yyyymmdd hh24:mi:ss');
	
	                if (sp_sinmarcaAM = 0) then
						inicioam 		:= 'rojo';
	                else
						inicioam 		:= 'default';
	                end if;

					--inicioam 		:= 'default';
				 else
					inicioam 		:= 'rojo';
				 end if;
			  	 
			  else
			   	 inicioam 		:= 'verde';
			  end if;

          elsif ( rec_mat.iniciopm is true and rec_mat.statusactivo is true ) then

			  tipotrabajo	:= 'A LA ESPERA DE TRABAJO';
			  if (rec_mat.fechacreacion > to_timestamp(to_char(current_date,'yyyymmdd')||' 14:00:00', 'yyyymmdd hh24:mi:ss') or
	              rec_mat.fechacreacion = '1900-01-01') then
	             if (rec_mat.fechacreacion = '1900-01-01') then

	                select count(*)
			          into sp_sinmarcaPM
					  from mct_movimientoordentrabajo a
					where a.idoperador = rec_mat.idoperador
			          and a.fechainicio >= to_timestamp(to_char(current_date,'yyyymmdd')||' 13:45:00', 'yyyymmdd hh24:mi:ss')
			          and a.fechainicio < to_timestamp(to_char(current_date,'yyyymmdd')||' 14:00:00', 'yyyymmdd hh24:mi:ss');
	
	                if (sp_sinmarcaPM = 0) then
						iniciopm 		:= 'rojo';
	                else
						iniciopm 		:= 'default';
	                end if;

					--iniciopm 		:= 'default';
				 else
					iniciopm 		:= 'rojo';
				 end if;
			  	 
			  else
			   	 iniciopm 		:= 'verde';
			  end if;

          end if;
          

		  if (rec_mat.ausentetn is not true and rec_mat.ausentevac is not true and rec_mat.ausenteper is not true) then

                select count(*)
		          into sp_sinmarcaAM
				  from mct_movimientoordentrabajo a
				where a.idoperador = rec_mat.idoperador
		          and a.fechainicio >= to_timestamp(to_char(current_date,'yyyymmdd')||' 07:00:00', 'yyyymmdd hh24:mi:ss')
		          and a.fechainicio < to_timestamp(to_char(current_date,'yyyymmdd')||' 08:00:00', 'yyyymmdd hh24:mi:ss');

                if (sp_sinmarcaAM = 0) then
					inicioam 		:= 'rojo';
                end if;


                if ( now() >= to_timestamp(to_char(current_date,'yyyymmdd')||' 14:00:00', 'yyyymmdd hh24:mi:ss') ) then

	                select count(*)
			          into sp_sinmarcaPM
					  from mct_movimientoordentrabajo a
					where a.idoperador = rec_mat.idoperador
			          and a.fechainicio >= to_timestamp(to_char(current_date,'yyyymmdd')||' 13:45:00', 'yyyymmdd hh24:mi:ss')
			          and a.fechainicio < to_timestamp(to_char(current_date,'yyyymmdd')||' 14:00:00', 'yyyymmdd hh24:mi:ss');
	
	                if (sp_sinmarcaPM = 0) then
						iniciopm 		:= 'rojo';
	                end if;

                end if;

          end if;

          producto 		:= sp_producto;
          nompreparte 	:= sp_nompreparte;
          plano 		:= sp_plano;
		  tmpoacum		:= coalesce(sp_tmpoacum,0);
 
          ausenteTN		:= rec_mat.ausentetn;
          ausenteVAC	:= rec_mat.ausentevac;
          ausentePER	:= rec_mat.ausenteper;
      
	      return next;
	     
	   END LOOP;
	
END;
$$;


ALTER FUNCTION traking.evtlisttrabajosonline() OWNER TO postgres;

--
-- TOC entry 1343 (class 1255 OID 17357)
-- Name: evtlisttracingmovactivity(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisttracingmovactivity(idroadmapcodes bigint) RETURNS TABLE(codesection character varying, operatorname character varying, timework integer)
    LANGUAGE plpgsql
    AS $$

begin 

    RETURN QUERY
    
			select --a.idseccion , 
				   c.codigoseccion ,
			      -- a.idoperador , 
			       b.nombreoperador ,
			       --a.fechainicio , 
			       --a.fechatermino ,
			       cast(sum(date_part('day', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 1440 + 
			       date_part('hour', a.fechatermino::timestamp - a.fechainicio::timestamp ) * 60 + 
			       date_part('minute', a.fechatermino::timestamp - a.fechainicio::timestamp )) as integer)
			from mct_movimientoordentrabajo a,
			     mct_operador b,
			     mct_seccion c
			where a.idhojaruta = idroadmapcodes
			and   a.idoperador = b.idoperador
			and   a.idseccion  = c.idseccion 
			group by c.codigoseccion ,
			      -- a.idoperador , 
			       b.nombreoperador 
			order by c.codigoseccion asc;
		
END;
$$;


ALTER FUNCTION traking.evtlisttracingmovactivity(idroadmapcodes bigint) OWNER TO postgres;

--
-- TOC entry 915 (class 1255 OID 17358)
-- Name: evtlisttraechecklisthojarutaurgente(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisttraechecklisthojarutaurgente(idworkorders bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
	
DECLARE	
	   
	   -- Desde aca para generar las Hojas de rutas automaticas
	    rec_hr					RECORD;
	   
        indice   				INTEGER;
        tope	   				INTEGER;	
  
        sp_hrchar               TEXT;
        sp_partchar             TEXT;
        sp_itemchar             TEXT;
        sp_corrchar             TEXT;
       
        sp_idpwo   				INTEGER;       
         						    
begin
	           
	  -- Esto inserta los registros en la tabla principal de Hojarutatemp
	  insert into mct_hojarutatemp (
	               idhojarutatemp, 
		           idordentrabajo, 
		           nombreplano, 
		           cantidad, 
		           usuariocreacion, 
		           fechacreacion, 
		           idimprimehojas, 
		           idboleano, 
		           idcriterioevaluacion, 
		           materialchecklist, 
		           componentechecklist,
		           textoadicional,
		           idcomponente ,
		           idmaterial ,
		           nombrematerial ,
		           idareaclasificacion ,
		           traeurgente,
		           nombrezona 
		         )
			     select nextval('mct_hojarutatemp_seq'),
			            a.idordentrabajo ,
			            a.plano,
			            a.cantidad,
			            'admin',
			            now(),
			            2,
			            1,
			            b.idcriterioevaluacion ,
			            a.material,
			            a.nombreparte,
			            'N/A',
			            a.idcomponente ,
			            a.idmaterial ,
			            a.nombrematerial ,
			            coalesce (d.idareaclasificacion, 0) ,
			            true,
			            a.nombrezona 
			       from mct_checklistinftec a
			       left join mct_criterioevaluacion b on a.criterio = b.nombrecriterioevaluacion
			       join mct_progavisos c on c.idordentrabajo = a.idordentrabajo and c.idsla = 5 and c.estado = 1 
			       left join mct_componente d on a.idcomponente = d.idcomponente 
			      where b.idcriterioevaluacion not in (5, 6)
			        and a.idordentrabajo = idworkorders;
	  
      FOR rec_hr IN (   
					 select ROW_NUMBER() OVER (ORDER BY idareaclasificacion asc) AS item,
					        idhojarutatemp ,
					        idordentrabajo ,
					        idcomponente ,
					        cantidad ,
					        idimprimehojas ,
					        idareaclasificacion 
					   from mct_hojarutatemp 
					  where idordentrabajo = idworkorders	 
                       
         		       )
					
		loop 	
		
			insert into mct_hojarutaactividadtemp 
	                (
	                idhojarutaactividadtemp ,
	                idhojarutatemp ,
	                idactividad ,
	                tiempoproduccion ,
	                orden 
	                )        	     
					select nextval('mct_hojarutaactividadtemp_seq'),
					       rec_hr.idhojarutatemp,
					       a.idactividad , 
					       a.tiempoproduccion , 
					       a.orden 
					  from mct_partetipotrabajoactividad a 
					 where a.idpartetipotrabajo = ( select idcomponentetipotrabajo 
											        from mct_componentetipotrabajo 
											       where idcomponente  = rec_hr.idcomponente
											         and idtipotrabajo in (21))
					order by idpartetipotrabajoactividad  asc, orden asc;
		
		    if ( rec_hr.idimprimehojas = 1 ) then
		    
		       tope  := 1;
		      
		    else
		 
		    	tope := coalesce(rec_hr.cantidad,0);
		    
		    end if;
 
			indice := 1;

			loop						
			
				sp_hrchar   := LPAD(rec_hr.idordentrabajo::integer::text::varchar, 6, '0');  
				sp_partchar := LPAD(rec_hr.idcomponente::integer::text::varchar, 3, '0');
				sp_itemchar := LPAD(rec_hr.item::integer::text::varchar, 3, '0'); 	
				sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
				
				insert into mct_detallehojarutatemp 
				           (iddetallehojarutatemp 
				           ,idhojarutatemp 
				           ,codhojaruta 
				           ,correlativoparte
				           )
				     VALUES
				           (nextval('traking.mct_detallehojarutatemp_seq')
				           ,rec_hr.idhojarutatemp
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
				           ,indice
				           );                     
		
				         
				sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
			
				insert into mct_ordentrabajoparte 
				           (idordentrabajoparte 
				           ,idordentrabajo 
				           ,idcomponente 
				           ,itemparte
				           ,itemcorr 
				           )
				     VALUES
				           (sp_idpwo
				           ,rec_hr.idordentrabajo
				           ,rec_hr.idcomponente 
				           ,indice
				           ,rec_hr.item
				           );   
		
				-- Esto es para igualar la tabla Hoja Ruta
			    insert into mct_hojaruta 
				           (idhojaruta 
				           ,idordentrabajoparte 
				           ,codhojaruta 
				           ,usuariocreacion 
				           ,fechacreacion
				           ,modalidad 
				           ,idhojarutatemp 
				           )
				     VALUES
				           (nextval('traking.mct_hojaruta_seq')
				           ,sp_idpwo
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
				           ,'admin' 
				           ,now()
				           ,1
				           ,rec_hr.idhojarutatemp
				           ); 
				          
				 indice := indice + 1;
				                           				   
				 EXIT when indice > tope;
				                    
			END loop;  		
		
		
	  	END LOOP;	
	  
	    update mct_checklistinftec
	       set flagtraeurgente = true 
	     where idordentrabajo = idworkorders;
			       
END;
$$;


ALTER FUNCTION traking.evtlisttraechecklisthojarutaurgente(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1864 (class 1255 OID 17360)
-- Name: evtlisttransitionot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisttransitionot(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idevaluator bigint, evaluatorname character varying, receptiondate character varying, orderstatus bigint, usercreate character varying, idusercreate bigint, userupdate character varying, idquotation bigint, idpurshase bigint, deliverydate character varying, inpuguide bigint, outputguide bigint, customername character varying, productname character varying, idordertype bigint, ordertypename character varying, idfamily bigint, familyname character varying, idlinedesign bigint, linedesignname text, infrstatus integer, infrdate character varying, idinfrrecepcionador integer, infrday integer, kpiinfr integer, infstatus integer, infdate character varying, idinfevaluator integer, infday integer, kpiinf integer, cotistatus integer, cotidate character varying, cotiday integer, kpicoti integer, autstatus integer, autdate character varying, autday integer, kpiaut integer, solpstatus integer, solpdate character varying, solpday integer, kpisolp integer, rplastatus integer, rpladate character varying, rpladay integer, kpirpla integer, iduserentrpla integer, iduserrecrpla integer, plastatus integer, pladate character varying, iduserent integer, iduserrec integer, pladay integer, kpipla integer, entdesstatus integer, entdesdate character varying, entdesday integer, kpientdes integer, desstatus integer, desdate character varying, desday integer, kpides integer, irstatus integer, checklisturgente boolean, repairfabcost text, terminoir character varying, terminoit character varying, terminocot character varying, terminoaut character varying, terminosolp character varying, terminorp character varying, terminoep character varying, terminoif character varying, terminodes character varying, avance integer, debajaestado integer, checklistvalido boolean, cantidadsla integer, subeguiasalida boolean, validaplanificacionhr boolean, fechavalidacheck character varying, fecha100mec character varying, fechafaceclte character varying, diasclte bigint)
    LANGUAGE plpgsql
    AS $$
declare
	       
		sp_idordentrabajo		integer;
	    sp_idusuario			integer;
	    sp_fecharecepcion		timestamp;
	    sp_idestadoorden		integer;
	    sp_usuariocreacion		varchar;
	    sp_idusuariocrea		integer;
	    sp_usuariomodificacion	varchar;
	    sp_idcotizacion		    integer;
	    sp_ordencompra			integer;
	    sp_fechaentrega			varchar;
	    sp_guiaentrante			integer;
	    sp_guiasaliente			integer;
	
	   	-- informe recepcion
		sp_estadoinfr			integer;
	    sp_fechainfr			timestamp;
	    sp_recepcionador  	    integer;   
	    sp_diasinfr             integer;
	    sp_kpiinfr              integer;
	    sp_estadoirr            integer;
	   
	    -- informe tecnico
		sp_estadoinf			integer;
	    sp_fechainf				timestamp;
	    sp_evaluador  	        integer;   
	    sp_diasinf              integer;
	    sp_kpiinf               integer;
	    sp_estadoir             integer;
	   
	   	-- cotizacion
		sp_estadocoti			integer;
	    sp_fechacoti			timestamp;  
	    sp_diascoti             integer;
	    sp_kpicoti              integer;
	   
	   	-- autorizacion
		sp_estadoaut			integer;
	    sp_fechaaut	  	 	    timestamp;  
	    sp_diasaut              integer;	   
	    sp_kpiaut               integer;
	 
	   	-- solicitud proveedores
		sp_estadosolp		    integer;
	    sp_fechasolp	  	    timestamp;  
	    sp_diassolp             integer;	   
	    sp_kpisolp              integer;
	   
	   	-- recepcion planos
		sp_estadorpla			integer;
	    sp_fecharpla	  	 	timestamp;
	    sp_entregarpla	  	 	integer; 	
	    sp_reciberpla	  	 	integer; 	   
	    sp_diasrpla             integer;		   
	    sp_kpirpla              integer;

	   	-- entrega planos
		sp_estadopla			integer;
	    sp_fechapla	  	 	    timestamp;
	    sp_entregapla	  	 	integer; 	
	    sp_recibepla	  	 	integer; 	   
	    sp_diaspla              integer;		   
	    sp_kpipla               integer;
	   
	   	-- entrega despacho
		sp_estadoentdes			integer;
	    sp_fechaentdes	  	 	timestamp;   
	    sp_diasentdes           integer;	
	    sp_kpientdes            integer;
	   
	   	-- despacho
		sp_estadodes			integer;
	    sp_fechades	  	 	    timestamp;  
	    sp_fechadespacho	  	timestamp;
	    sp_diasdes              integer;		   
	    sp_kpides               integer;
	   
	    sp_fechaant	 		    timestamp;
	    sp_terminoir            varchar;
	    sp_terminoit			varchar;
	    sp_terminocot			varchar;
	    sp_terminoaut			varchar;
	    sp_terminosolp			varchar;
	    sp_terminorp			varchar;
	    sp_terminoep			varchar;
	    sp_terminoif			varchar;
	    sp_terminodes			varchar;
	   
	    sp_avance               integer;
	    sp_debaja				integer;
	    sp_checklistvalido		boolean;
	   
	    sp_canthr               integer;
	    sp_liberadascc          integer;	   
	    sp_cantidadsla			integer;
	    sp_tienegds 			integer;

        sp_sumatotallcc         integer;
        rec_lcc      			RECORD;

	   	rec1  				    record;
	   
	    sp_familia				integer;
		sp_solicitado			integer;
		sp_despachado			integer;	 
	
	    sp_idproducto			integer;
	
	    sp_validaplanificacionhr		boolean;

        sp_fechavalidacheck 	varchar;
        sp_fecha100mec 			varchar;
        sp_fechafaceclte 		varchar;
        sp_diasclte 			bigint;
begin
	
	    sp_avance		:= 0;
	    sp_debaja		:= 0;
	    sp_checklistvalido	:= null;
	    sp_cantidadsla	:= 0;
	   
	    -- informe recepcion
		sp_estadoinfr	:= 0;
	    sp_fechainfr    := null;
	    sp_recepcionador:= 0;   
	    sp_diasinfr	    := 0;
	    sp_estadoirr	:= 0;
	   
      	-- informe tecnico
		sp_estadoinf	:= 0;
	    sp_fechainf     := null;
	    sp_evaluador	:= 0;   
	    sp_diasinf	    := 0;
	    sp_estadoir	    := 0;
	   
	   	-- cotizacion
		sp_estadocoti	:= 0;
	    sp_fechacoti    := null;
	    sp_diascoti	    := 0;

	   	-- autorizacion
		sp_estadoaut	:= 0;
	    sp_fechaaut     := null; 
	    sp_diasaut	    := 0;	   

	   	-- solicitud proveedores
		sp_estadosolp   := 0;
	    sp_fechasolp	:= null;  
	    sp_diassolp     := 0;	   
	    sp_kpisolp      := 0;
	   
	   	-- recepcion planos
		sp_estadorpla	:= 0;
	    sp_fecharpla    := null;
	    sp_entregarpla	:= 0;	
	    sp_reciberpla	:= 0;	   
	    sp_diasrpla 	:= 0;		   

	   	-- entrega planos
		sp_estadopla	:= 0;
	    sp_fechapla     := null;
	    sp_entregapla	:= 0;	
	    sp_recibepla	:= 0;	   
	    sp_diaspla 	    := 0;		   

	   	-- entrega despacho
		sp_estadoentdes	:= 0;
	    sp_fechaentdes  := null;   
	    sp_diasentdes	:= 0;

	   	-- despacho
		sp_estadodes	:= 0;
	    sp_fechades     := null;   
	    sp_fechadespacho:= null;
	    sp_diasdes	    := 0;
	   
	   	sp_fechaant	    := null;
	    sp_tienegds		:= 0;
	   
	    sp_familia		:= 0;
	   
	    sp_solicitado	:= 0;
		sp_despachado	:= 0;
	
	    sp_validaplanificacionhr	:= false;
	   
	   
	   select count(*) 
	     into sp_cantidadsla
	     from mct_progavisos 
	    where idordentrabajo = idworkorders;
	  

	   select a.fecharecepcion ,
	          coalesce (a.debaja , 0),
	          a.checklistvalido,
	          a.fechadespacho ,
	          a.idfamilia,
	          a.idproducto,
	          a.validaplanificacionhr ,
			  to_char(a.fechachecklistvalido,'dd-mm-yyyy'),
              to_char(a.fecha100tm,'dd-mm-yyyy'),
              to_char(a.fechafaceclte, 'dd-mm-yyyy'),
              date_part('day', a.fechafaceclte - current_date)
	     into sp_fecharecepcion,
	          sp_debaja,
	          sp_checklistvalido,
	          sp_fechadespacho,
	          sp_familia,
	          sp_idproducto,
	          sp_validaplanificacionhr,
			  sp_fechavalidacheck,
	          sp_fecha100mec,
	          sp_fechafaceclte ,
	          sp_diasclte
	     from mct_ordentrabajo a
	    where idordentrabajo = idworkorders;
	   
	   
	   if ( sp_familia = 8 ) then

		   -- sp_fecharecepcion := now() - interval '10 day';
		   select count(*)
		     into sp_tienegds
		     from mct_infcotipdf  
		    where idordentrabajo = idworkorders
		      and idproceso = 9
		      and infcoti = 90
		      and nombrearchivo like 'GDS_%';
	     
	   end if;
	  

	   if ( sp_familia in  (10, 11) ) then

--		    sp_fecharecepcion := now() - interval '10 day';
--		   select count(*)
--		     into sp_tienegds
--		     from mct_infcotipdf  
--		    where idordentrabajo = idworkorders
--		      and idproceso = 9
--		      and infcoti = 90
--		      and nombrearchivo like 'GDS_%';
		     
           select coalesce (sum(a.cantidad) , 0) ,
		          coalesce (sum(c.qdespacho) , 0)
		     into sp_solicitado,
		          sp_despachado
             from mct_ordentrabajorepuesto a
             left join mct_despachopartecabecera b on a.idordentrabajo = b.idordentrabajo 
             left join mct_despachopartedetalle c  on b.iddespachopartecabecera = c.iddespachopartecabecera  and a.idordentrabajorepuesto = c.idparte
            where a.idordentrabajo = idworkorders;		
           
            if (sp_despachado >= sp_solicitado ) then
               sp_tienegds	:= 1;
            else
               sp_tienegds	:= 0;
            end if;
	     
	   end if;
	     
	   -- Desde aca para avance
		sp_sumatotallcc  := 0;
				   			   
		FOR rec_lcc IN (   
				select distinct b.idhojarutatemp
				  from mct_movimientoordentrabajo a,
				       mct_hojaruta b
				 where a.codigoaccion = 'L_CC'
			       and a.idordentrabajo = idworkorders
			       and a.idhojaruta = b.idhojaruta 
					)
	     		loop 	
	
					 sp_liberadascc	:= 0;
									   
					 select coalesce (sum(cantidad),0)
					   into sp_liberadascc
				       from mct_hojarutatemp
				      where idhojarutatemp = rec_lcc.idhojarutatemp
				        and idboleano = 1
			            and idareaclasificacion in (0,1,2,3,4,5);
							     
				 	 sp_sumatotallcc := sp_sumatotallcc + sp_liberadascc;
							           
				END LOOP;
					  		
			sp_sumatotallcc := sp_sumatotallcc * 100;
		  -- hasta aca el nuevo calculo

	   	  -- aca sacamos la cantidad de piezas totales
		  select coalesce ( sum(cantidad), 0)
			into sp_canthr
	        from mct_hojarutatemp mh
		   where idordentrabajo = idworkorders
	         and idboleano = 1
	    	 and idareaclasificacion in (0,1,2,3,4,5);
						      
		 if ( sp_canthr = 0) then
			  sp_avance := 0;
		 else
              sp_avance := round(sp_sumatotallcc / sp_canthr);
         end if;
			              
	   -- Hasta aca
	 
	   FOR rec1 IN (   
				     select a.idsla ,
	       			    	a.estado,
	       			    	a.fecha_termino ,
	                        a.fecha_real_termino ,
	                        0 as dias,
	                        coalesce (a.idusuarioentrega, 0) as idusuarioentrega,
	                        coalesce (a.idusuariorecibe, 0) as idusuariorecibe,
	                        coalesce (a.idusuarioentregapla, 0) as idusuarioentregapla,
	                        coalesce (a.idusuariorecibepla, 0) as idusuariorecibepla,
	                        coalesce (date_part('day',a.fecha_real_termino - a.fecha_termino), 0) as demora,
		 	      			coalesce (date_part('day',a.fecha_termino - a.fecha_inicio), 0) as diasplanificados,
		 	   	   			coalesce (date_part('day',a.fecha_real_termino - a.fecha_inicio), 0) as diasreales 	,
		 	   	   			coalesce (a.idestadoir, 0) as idestadoir,
		 	   	   			a.idusuarioinfrec as idusuarioinfrec,
		 	   	   			b.nombre as nombreusuarioinfrec
	                   from mct_progavisos a
	                   left join mct_usuario b on a.idusuarioinfrec = b.idusuario 
	                  where a.idordentrabajo = idworkorders
	                  order by a.ordenproceso asc, a.idsla asc
					)
		loop 				 
		
		      -- informe recepcion
		      if rec1.idsla = 10 then		
		      	 sp_estadoirr     := rec1.idestadoir;
		      	 sp_recepcionador := rec1.idusuarioinfrec;
		      	 sp_terminoir:= to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then
		            sp_estadoinfr := rec1.estado;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diasinfr  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diasinf  := date_part('day', rec1.fecha_real_termino - sp_fecharecepcion);
		               sp_diasinfr  := rec1.diasreales;
		               sp_kpiinfr   := rec1.demora;
		               sp_fechaant  := rec1.fecha_real_termino;
		               sp_fechainfr := rec1.fecha_real_termino;
		            end if;		         
		         end if;      
		      end if;
		     
		      -- informe tecnico
		      if rec1.idsla = 3 then		
		      	 sp_estadoir := rec1.idestadoir;
		      	 sp_terminoit:= to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then
		            sp_estadoinf := rec1.estado;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diasinf  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diasinf  := date_part('day', rec1.fecha_real_termino - sp_fecharecepcion);
		               sp_diasinf  := rec1.diasreales;
		               sp_kpiinf   := rec1.demora;
		               sp_fechaant := rec1.fecha_real_termino;
		               sp_fechainf := rec1.fecha_real_termino;
		            end if;		         
		         end if;      
		      end if;
		     
		    
		      -- cotizacion
		      if rec1.idsla = 4 then		
		      	 sp_terminocot := to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then 		
		            sp_estadocoti := rec1.estado;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diascoti  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diascoti  := date_part('day', rec1.fecha_real_termino - sp_fechaant);
		               sp_diascoti  := rec1.diasreales;
		               sp_kpicoti   := rec1.demora;
		               sp_fechaant  := rec1.fecha_real_termino;
		               sp_fechacoti := rec1.fecha_real_termino;
		            end if;		       
		         end if;		      
		      end if;
		     
		      -- autorizacion
		      if rec1.idsla = 5 then	
		         sp_terminoaut := to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then 	
		         	sp_estadoaut := rec1.estado;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diasaut  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diasaut   := date_part('day', rec1.fecha_real_termino - sp_fechaant);
		               sp_diasaut  := rec1.diasreales;
		               sp_kpiaut   := rec1.demora;
		               sp_fechaant  := rec1.fecha_real_termino;
		               sp_fechaaut  := rec1.fecha_real_termino;
		            end if;		       
		         end if;		      
		      end if;

		      -- solicitud proveedores
		      if rec1.idsla = 11 then	
		         sp_terminosolp := to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then 	
		         	sp_estadosolp := rec1.estado;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diassolp  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diasaut   := date_part('day', rec1.fecha_real_termino - sp_fechaant);
		               sp_diassolp   := rec1.diasreales;
		               sp_kpisolp    := rec1.demora;
		               sp_fechaant   := rec1.fecha_real_termino;
		               sp_fechasolp  := rec1.fecha_real_termino;
		            end if;		       
		         end if;		      
		      end if;
		     
		      -- recepción plano
		      if rec1.idsla = 6 then
		         sp_terminorp := to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then 
		            sp_estadorpla := rec1.estado;
		           	sp_entregarpla := rec1.idusuarioentregapla;
		            sp_reciberpla  := rec1.idusuariorecibepla;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diasrpla  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diaspla   := date_part('day', rec1.fecha_real_termino - sp_fechaant);
		               sp_diasrpla  := rec1.diasreales;
		               sp_kpirpla   := rec1.demora;
		               sp_fechaant  := rec1.fecha_real_termino;
		               sp_fecharpla := rec1.fecha_real_termino;
		            end if;		       
		         end if;		      
		      end if;		     

		     -- entrega plano
		      if rec1.idsla = 7 then
		         sp_terminoep := to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then 
		            sp_estadopla := rec1.estado;
		           	sp_entregapla := rec1.idusuarioentrega;
		            sp_recibepla  := rec1.idusuariorecibe;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diaspla  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diaspla   := date_part('day', rec1.fecha_real_termino - sp_fechaant);
		               sp_diaspla  := rec1.diasreales;
		               sp_kpipla   := rec1.demora;
		               sp_fechaant  := rec1.fecha_real_termino;
		               sp_fechapla  := rec1.fecha_real_termino;
		            end if;		       
		         end if;		      
		      end if;
		     
		      -- entdespacho
		      if rec1.idsla = 8 then	
		         sp_terminoif := to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then 	
		            sp_estadoentdes := rec1.estado;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diasentdes  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diasentdes   := date_part('day', rec1.fecha_real_termino - sp_fechaant);
		               sp_diasentdes  := rec1.diasreales;
		               sp_kpientdes   := rec1.demora;
		               sp_fechaant  := rec1.fecha_real_termino;
		               sp_fechaentdes  := rec1.fecha_real_termino;
		            end if;		       
		         end if;		      
		      end if;
         
		     -- despacho
		      if rec1.idsla = 9 then		 
		         sp_terminodes := to_char(rec1.fecha_termino,'yyyy-mm-dd hh24:mi:ss');
		         if rec1.estado != 0 then 	
		            sp_estadodes := rec1.estado;
		            if rec1.fecha_real_termino is null then
		            
		               sp_diasdes  := date_part('day', now() - sp_fecharecepcion);
		            else
		               --sp_diasdes   := date_part('day', rec1.fecha_real_termino - sp_fechaant);
		               sp_diasdes   := rec1.diasreales;
		               sp_kpides    := rec1.demora;
		               sp_fechaant  := rec1.fecha_real_termino;
		               sp_fechades  := rec1.fecha_real_termino;
		            end if;		       
		         end if;		      
		      end if;
		     
		     
	  END LOOP;
	 
	  
	  if ( sp_idproducto in (10,11,12,13,14,15,16,17) and sp_familia = 11) then
	  
		  return QUERY
		 
		  	select a.idordentrabajo ,
	           a.idusuario ,
	           b.nombre ,
	           cast(to_char(a.fecharecepcion,'dd-mm-yyyy') as varchar),
	           a.idestadoorden ,
	           a.usuariocreacion ,
	           b.idusuario ,
	           a.usuariomodificacion ,
	           a.idcotizacion,
	           a.ordencompra ,
	           cast(to_char(a.fechaentrega,'dd-mm-yyyy') as varchar),
	           a.guiaentrante ,
	           a.guiasaliente ,
	           c.nombrecliente ,
	           d.nombreproductonepcast ,
	           a.idtipoorden ,
	           e.nombretipoorden ,
	           a.idfamilia ,
	           f.nombrefamilia ,
	           a.idlineadiseno ,
		       case
		          when a.idlineadiseno = 1 then 'DE DISEÑO'
		          when a.idlineadiseno = 2 then 'DE LÍNEA'
		          when a.idlineadiseno = 3 then 'COMERCIAL'	          
		       end,
		       -- informe recepcion
			   sp_estadoinfr,
			   cast(to_char(sp_fechainfr,'dd-mm-yyyy') as varchar),
			   sp_recepcionador, 
			   sp_diasinfr,
			   sp_kpiinfr,
		       -- informe tecnico
			   sp_estadoinf,
			   cast(to_char(sp_fechainf,'dd-mm-yyyy') as varchar),
			   sp_evaluador, 
			   sp_diasinf,
			   sp_kpiinf,
			   -- cotizacion
			   sp_estadocoti,
			   cast(to_char(sp_fechacoti,'dd-mm-yyyy') as varchar),
			   sp_diascoti,	
			   sp_kpicoti,
			   -- autorizacion
			   sp_estadoaut,
			   cast(to_char(sp_fechaaut,'dd-mm-yyyy')  as varchar),
			   sp_diasaut,   
			   sp_kpiaut,
			   -- solicitud de proveedores
			   sp_estadosolp,
			   cast(to_char(sp_fechasolp,'dd-mm-yyyy')  as varchar),
			   sp_diassolp,   
			   sp_kpisolp,
			   -- recepcion planos
			   sp_estadorpla,
			   cast(to_char(sp_fecharpla,'dd-mm-yyyy') as varchar),
			   sp_diasrpla,	
			   sp_kpirpla,
			   sp_entregarpla,
			   sp_reciberpla,
			   -- entrega planos
			   sp_estadopla,
			   cast(to_char(sp_fechapla,'dd-mm-yyyy') as varchar),
			   sp_entregapla,
			   sp_recibepla,   
			   sp_diaspla,	
			   sp_kpipla,		   
			   -- entrega despacho
			   sp_estadoentdes,
			   cast(to_char(sp_fechaentdes,'dd-mm-yyyy') as varchar),
			   sp_diasentdes,
			   sp_kpientdes,
			   -- despacho
			   sp_estadodes,
			   cast(to_char(sp_fechadespacho,'dd-mm-yyyy') as varchar),
			   sp_diasdes,
			   sp_kpides,
			   sp_estadoir,
			   a.checklisturgente ,
			   trim(cast(to_char(round(coalesce (a.montorepfab,0)),'999,999,999') as varchar )) ,
			   sp_terminoir,
			   sp_terminoit,
			   sp_terminocot,
			   sp_terminoaut,
			   sp_terminosolp,
			   sp_terminorp,
			   sp_terminoep,
			   sp_terminoif,
			   sp_terminodes,
			   --98,
			   sp_avance,
			   cast(sp_debaja as integer),
			   sp_checklistvalido,
			   sp_cantidadsla,
			   case
			   		when sp_tienegds = 0 then 
			   		     false
			   		else
			   			 true
			   		     
			   end,
			   sp_validaplanificacionhr,
			   sp_fechavalidacheck,
	           sp_fecha100mec,
	           sp_fechafaceclte ,
	           sp_diasclte
	      from mct_ordentrabajo a 
	      join mct_usuario b        on a.idusuario = b.idusuario
	      join mct_cliente c        on a.idcliente = c.idcliente
	      left join mct_productonepcast d  on a.idproducto = d.idproductonepcast
	      join mct_tipoorden e      on a.idtipoorden = e.idtipoorden
	      join mct_familia f        on a.idfamilia = f.idfamilia
	     where a.idordentrabajo = idworkorders;	 	  
	  
	  
	  else 
	  
	  
		  return QUERY
		 
		  	select a.idordentrabajo ,
	           a.idusuario ,
	           b.nombre ,
	           cast(to_char(a.fecharecepcion,'dd-mm-yyyy') as varchar),
	           a.idestadoorden ,
	           a.usuariocreacion ,
	           b.idusuario ,
	           a.usuariomodificacion ,
	           a.idcotizacion,
	           a.ordencompra ,
	           cast(to_char(a.fechaentrega,'dd-mm-yyyy') as varchar),
	           a.guiaentrante ,
	           a.guiasaliente ,
	           c.nombrecliente ,
	           d.nombreproducto ,
	           a.idtipoorden ,
	           e.nombretipoorden ,
	           a.idfamilia ,
	           f.nombrefamilia ,
	           a.idlineadiseno ,
		       case
		          when a.idlineadiseno = 1 then 'DE DISEÑO'
		          when a.idlineadiseno = 2 then 'DE LÍNEA'
		          when a.idlineadiseno = 3 then 'COMERCIAL'	          
		       end,
		       -- informe recepcion
			   sp_estadoinfr,
			   cast(to_char(sp_fechainfr,'dd-mm-yyyy') as varchar),
			   sp_recepcionador, 
			   sp_diasinfr,
			   sp_kpiinfr,
		       -- informe tecnico
			   sp_estadoinf,
			   cast(to_char(sp_fechainf,'dd-mm-yyyy') as varchar),
			   sp_evaluador, 
			   sp_diasinf,
			   sp_kpiinf,
			   -- cotizacion
			   sp_estadocoti,
			   cast(to_char(sp_fechacoti,'dd-mm-yyyy') as varchar),
			   sp_diascoti,	
			   sp_kpicoti,
			   -- autorizacion
			   sp_estadoaut,
			   cast(to_char(sp_fechaaut,'dd-mm-yyyy')  as varchar),
			   sp_diasaut,   
			   sp_kpiaut,
			   -- solicitud de proveedores
			   sp_estadosolp,
			   cast(to_char(sp_fechasolp,'dd-mm-yyyy')  as varchar),
			   sp_diassolp,   
			   sp_kpisolp,
			   -- recepcion planos
			   sp_estadorpla,
			   cast(to_char(sp_fecharpla,'dd-mm-yyyy') as varchar),
			   sp_diasrpla,	
			   sp_kpirpla,
			   sp_entregarpla,
			   sp_reciberpla,
			   -- entrega planos
			   sp_estadopla,
			   cast(to_char(sp_fechapla,'dd-mm-yyyy') as varchar),
			   sp_entregapla,
			   sp_recibepla,   
			   sp_diaspla,	
			   sp_kpipla,		   
			   -- entrega despacho
			   sp_estadoentdes,
			   cast(to_char(sp_fechaentdes,'dd-mm-yyyy') as varchar),
			   sp_diasentdes,
			   sp_kpientdes,
			   -- despacho
			   sp_estadodes,
			   cast(to_char(sp_fechadespacho,'dd-mm-yyyy') as varchar),
			   sp_diasdes,
			   sp_kpides,
			   sp_estadoir,
			   a.checklisturgente ,
			   trim(cast(to_char(round(coalesce (a.montorepfab,0)),'999,999,999') as varchar )) ,
			   sp_terminoir,
			   sp_terminoit,
			   sp_terminocot,
			   sp_terminoaut,
			   sp_terminosolp,
			   sp_terminorp,
			   sp_terminoep,
			   sp_terminoif,
			   sp_terminodes,
			   --98,
			   sp_avance,
			   cast(sp_debaja as integer),
			   sp_checklistvalido,
			   sp_cantidadsla,
			   case
			   		when sp_tienegds = 0 then 
			   		     false
			   		else
			   			 true
			   		     
			   end,
			   sp_validaplanificacionhr,
			   sp_fechavalidacheck,
	           sp_fecha100mec,
	           sp_fechafaceclte ,
	           sp_diasclte
	      from mct_ordentrabajo a 
	      join mct_usuario b        on a.idusuario = b.idusuario
	      join mct_cliente c        on a.idcliente = c.idcliente
	      left join mct_producto d  on a.idproducto = d.idproducto
	      join mct_tipoorden e      on a.idtipoorden = e.idtipoorden
	      join mct_familia f        on a.idfamilia = f.idfamilia
	     where a.idordentrabajo = idworkorders;	  
	  
	  end if;

     
END;
$$;


