--
-- TOC entry 2356 (class 1255 OID 17362)
-- Name: evtlisttransitionothist(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlisttransitionothist(idworkorders bigint) RETURNS TABLE(idworkorderhist bigint, receptiondatehist character varying, deliverydatehist character varying, fileinf text, filecot text, filedes text)
    LANGUAGE plpgsql
    AS $$
declare
	       
	    arreglo     varchar[];
	   
	    textoin     varchar;
	    sp_salir    integer;   
	
begin

	delete from mct_ottemphist; 
    delete from mct_arreglohist;
	    
    insert into mct_arreglohist (
	select array(
	 select idot 
	   from (
			select idordentrabajo as idot
		      from mct_ordentrabajo
		     where idordentrabajo = idworkorders 
			 union
			select idordentrabajoanterior  as idot
		      from mct_ordentrabajo 
		     where idordentrabajo = idworkorders
			 union
			select idordentrabajoanterior  as idot
		      from mct_ordentrabajo 
		     where idordentrabajoanterior = idworkorders	 
			 union
			select idordentrabajo  as idot
		      from mct_ordentrabajo
		     where idordentrabajoanterior = idworkorders	) a) );
     
		select columna 
		  from (
			   select array_agg(c) as columna
				from (
			       select unnest(columnatexto)
			       from mct_arreglohist
				) as dt(c)
				) a
		   into arreglo;
			
	    textoin := '(';
		     	 
	    FOR i IN array_lower(arreglo, 1) .. array_upper(arreglo, 1)
			  loop
			   insert into mct_ottemphist values (idworkorders, arreglo[i]);
               ---anterior := anterior + 1;
		
	    END LOOP;
			  
	   -- textoin := replace(textoin, '(,', '') ;
			 
		sp_salir := 0;
	
	    WHILE sp_salir < 5
    
        LOOP
	 
            insert into mct_arreglohist (
				select array(
					 select idot 
					   from (
                        
						select idordentrabajo as idot
					      from mct_ordentrabajo
						     where idordentrabajo  in (select cast(idottemp as integer) from mct_ottemphist where idordentrabajo = idworkorders) and idordentrabajo > 0
							 union
							select idordentrabajoanterior  as idot
						      from mct_ordentrabajo 
						     where idordentrabajo  in (select cast(idottemp as integer) from mct_ottemphist where idordentrabajo = idworkorders) and idordentrabajo > 0
							 union
							select idordentrabajoanterior  as idot
						      from mct_ordentrabajo 
						     where idordentrabajoanterior  in (select cast(idottemp as integer) from mct_ottemphist where idordentrabajo = idworkorders) and idordentrabajoanterior > 0
							 union
							select idordentrabajo  as idot
						      from mct_ordentrabajo
						     where idordentrabajoanterior in (select cast(idottemp as integer) from mct_ottemphist where idordentrabajo = idworkorders) and idordentrabajoanterior > 0 	) a) );
						    
	
			sp_salir := sp_salir + 1;
		
			select columna 
			  from (
				   select array_agg(c) as columna
					from (
				       select unnest(columnatexto)
				       from mct_arreglohist
					) as dt(c)
					) a
			   into arreglo;
				
			--actual := 0;     	 
		    FOR i IN array_lower(arreglo, 1) .. array_upper(arreglo, 1)
				  loop
				   insert into mct_ottemphist values (idworkorders, arreglo[i]);
			       --actual := actual + 1;
		    END LOOP;

        END LOOP;
       
    RETURN QUERY
      
       select a.idordentrabajo ,
	          cast(to_char(a.fecharecepcion, 'dd-mm-yyyy') as varchar),
	          cast(to_char(a.fechadespacho, 'dd-mm-yyyy') as varchar),
	          b.archivoadjunto ,
	          c.archivoadjunto ,
	          d.archivoadjunto 
	   from mct_ordentrabajo a
	   left join  mct_infcotipdf b on a.idordentrabajo = b.idordentrabajo and b.infcoti = 30
	   left join  mct_infcotipdf c on a.idordentrabajo = c.idordentrabajo and c.infcoti = 40 
	   left join  mct_infcotipdf d on a.idordentrabajo = d.idordentrabajo and d.infcoti = 80
	  where a.idordentrabajo in (select distinct cast(idottemp as integer) from mct_ottemphist where idordentrabajo = idworkorders and cast(idottemp as integer) > 0)
      order by a.idordentrabajo asc;
    

    --return textoin;   
		   
END;
$$;


ALTER FUNCTION traking.evtlisttransitionothist(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1964 (class 1255 OID 17363)
-- Name: evtlistvalidationevaluation(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistvalidationevaluation(idworkorders bigint) RETURNS TABLE(idvalidation integer, validationname character varying, quantity bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
			select 1,
			      cast('Evaluacion partes' as varchar) ,
			      a.idordentrabajoparte
			from mct_ordentrabajoparte a,
			     mct_evaluacion b
			where idordentrabajo = idworkorders
			and a.idordentrabajoparte = b.idordentrabajoparte 
			and (b.observacion is null or b.observacion = '');

END;
$$;


ALTER FUNCTION traking.evtlistvalidationevaluation(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1788 (class 1255 OID 17364)
-- Name: evtlistvalidationmetrology(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistvalidationmetrology(idworkorderf bigint) RETURNS TABLE(idvalidation integer, validationname character varying, quantity numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
    select 2, 
           cast('Metrologia partes'  as varchar), 
           sum(uno)-sum(dos) from 
         (
			select count(*) as uno, 0 as dos
			  from mct_ordentrabajo a,
			       mct_productoplano b,
			       mct_planoadjunto c,
			       mct_plano d,
			       mct_tipoplano e
			 where a.idordentrabajo = idworkorderf
			   and a.idproducto  = b.idproducto 
			   and b.idplano     = c.idplano 
			   and c.idplano     = d.idplano 
			   and d.idtipoplano = e.idtipoplano 
			 union 
			select 0 as uno, count(*) as dos
			  from mct_ordentrabajo a,
			       mct_productoplano b,
			       mct_planoadjunto c,
			       mct_plano d,
			       mct_tipoplano e,
			       mct_metrologiaot f
			 where a.idordentrabajo = idworkorderf
			   and a.idproducto  = b.idproducto 
			   and b.idplano     = c.idplano 
			   and c.idplano     = d.idplano 
			   and d.idtipoplano = e.idtipoplano 
			   and f.idplano     = b.idplano
			   and a.idordentrabajo = f.idordentrabajo 
			   ) aa;

END;
$$;


ALTER FUNCTION traking.evtlistvalidationmetrology(idworkorderf bigint) OWNER TO postgres;

--
-- TOC entry 1502 (class 1255 OID 17365)
-- Name: evtlistworkorderbombas(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistworkorderbombas(idfamily bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, idworkorder bigint, customershortname character varying, ordertypename character varying, productname text, purshaseorder bigint, itemcode bigint, creationdate character varying, deliverydate character varying, dispatchdate character varying, customerot character varying, quotation bigint, blueprintname character varying, componentname character varying, materialname character varying, outputguide bigint, statusname character varying, iddespachopartecabecera bigint, quantity bigint, quantitydispatch bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    	RETURN QUERY
    
			select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) AS item,
			       a.idordentrabajo ,
			       d.nombrecorto ,       
			       e.nombretipoorden ,
			       case
				       when i.idetapaparam < 13 then case
				          when a.idfamilia = 8 then k.sigla||' '||j.nombremodelo||' '||l.nombreparam 
				          when a.idfamilia = 10 then b.nombrecomponentetemp
				       end
				       when i.idetapaparam = 13 then case
				          when a.idfamilia = 8 then k.sigla||' '||j.nombremodelo
				          when a.idfamilia = 10 then b.nombrecomponentetemp
				       end
			       end,
			       a.ordencompra ,
			       b.codigopieza ,      
			 	   cast(to_char(a.fechacreacion, 'dd-mm-yyyy') as varchar) ,
				   cast(to_char(a.fechaentrega, 'dd-mm-yyyy') as varchar) ,
			       cast(to_char(g.fechadespacho, 'dd-mm-yyyy') as varchar),     
			       a.otcliente ,
			       case
			           when a.idfamilia = 8 then coalesce (a.montorepfab,0)
			           when a.idfamilia = 10 then  coalesce (b.costo,0)
			       end,
			       b.nombreplano ,
			       b.nombrecomponentetemp ,
			       b.nombrematerialtemp ,
			       g.guiasaliente ,
			       f.nombreestado ,
			       g.iddespachopartecabecera ,       
			       b.cantidad ,
			       sum(h.qdespacho) 
			  from mct_ordentrabajo a
			  left join mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
			  left join mct_cliente d on a.idcliente = d.idcliente
			  left join mct_tipoorden e on a.idtipoorden = e.idtipoorden 
			  left join mct_estadoorden f on a.idestadoorden = f.idestadoorden 
			  left join mct_despachopartecabecera g on a.idordentrabajo = g.idordentrabajo
			  left join mct_despachopartedetalle h on g.iddespachopartecabecera = h.iddespachopartecabecera and b.idordentrabajorepuesto = h.idordentrabajoparte 
			  left join mct_producto i on a.idproducto = i.idproducto 
			  left join mct_modelo j on i.idmodelo = j.idmodelo 
			  left join mct_subfamilia k on j.idsubfamilia = k.idsubfamilia
			  left join mct_etapaparam l on i.idetapaparam = l.idetapaparam 
			 where a.fechacreacion >= to_date(startdate,'yyyy-mm-dd') 
			   and a.fechacreacion <= to_date(enddate,'yyyy-mm-dd') 
			   and a.idfamilia = idfamily
			   group by a.idordentrabajo ,
			            d.nombrecorto ,
				        e.nombretipoorden ,
					    case
						  when i.idetapaparam < 13 then case
						          when a.idfamilia = 8 then k.sigla||' '||j.nombremodelo||' '||l.nombreparam 
						          when a.idfamilia = 10 then b.nombrecomponentetemp
						  end
						  when i.idetapaparam = 13 then case
						          when a.idfamilia = 8 then k.sigla||' '||j.nombremodelo
						          when a.idfamilia = 10 then b.nombrecomponentetemp
						  end
					    end,
				        a.ordencompra ,
			 	        b.codigopieza ,       
			 	        cast(to_char(a.fechacreacion, 'dd-mm-yyyy') as varchar) ,
				        cast(to_char(a.fechaentrega, 'dd-mm-yyyy') as varchar) ,
			    	    cast(to_char(g.fechadespacho, 'dd-mm-yyyy') as varchar),
			     	    a.otcliente ,
				        case
				           when a.idfamilia = 8 then coalesce (a.montorepfab,0)
				           when a.idfamilia = 10 then  coalesce (b.costo,0)
				        end,
			       		b.nombreplano ,
			       		b.nombrecomponentetemp ,
			       		b.nombrematerialtemp ,
			       		g.guiasaliente ,
			       		f.nombreestado ,
			            g.iddespachopartecabecera ,       		
			       		b.cantidad 
			   order by a.idordentrabajo desc;
			  
END;
$$;


ALTER FUNCTION traking.evtlistworkorderbombas(idfamily bigint, startdate character varying, enddate character varying) OWNER TO postgres;

--
-- TOC entry 1858 (class 1255 OID 17366)
-- Name: evtlistworkorderdata(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistworkorderdata(idworkorders bigint) RETURNS TABLE(idworkorder bigint, idevaluator bigint, evaluatorname character varying, receptiondate character varying, orderstatus bigint, usercreate character varying, idusercreate bigint, userupdate character varying, idquotation bigint, idpurshase bigint, deliverydate character varying, inpuguide bigint, outputguide bigint, customername character varying, productname character varying, idordertype bigint, ordertypename character varying, idfamily bigint, familyname character varying, idlinedesign bigint, linedesignname text, fechafundicion character varying)
    LANGUAGE plpgsql
    AS $$
	
begin
	 
	  return QUERY
	 
	  	select a.idordentrabajo ,
           a.idusuario ,
           b.nombre ,
           cast(to_char(a.fecharecepcion,'dd-mm-yyyy') as varchar),
           a.idestadoorden ,
           a.usuariocreacion ,
           b.idusuario ,
           a.usuariomodificacion ,
           a.idcotizacion,
           a.ordencompra ,
           case
	           when a.idestadoorden < 6 then
	                cast(to_char(now() + interval '9 days','dd-mm-yyyy') as varchar)
	           else
	                cast(to_char(a.fechaentrega,'dd-mm-yyyy') as varchar)
	       end,     
          -- cast(to_char(a.fechaentrega,'dd-mm-yyyy') as varchar) as entrega,
           a.guiaentrante ,
           a.guiasaliente ,
           c.nombrecliente ,
           d.nombreproducto ,
           a.idtipoorden ,
           e.nombretipoorden ,
           a.idfamilia ,
           f.nombrefamilia ,
           a.idlineadiseno ,
	       case
	          when a.idlineadiseno = 1 then 'DE DISEÑO'
	          when a.idlineadiseno = 2 then 'DE LÍNEA'
	          when a.idlineadiseno = 3 then 'COMERCIAL'	          
	       end,
	       cast(to_char(a.fechaentrega - interval '14 days','dd-mm-yyyy') as varchar) as fechafundicion
      from mct_ordentrabajo a 
      join mct_usuario b        on a.idusuario = b.idusuario
      join mct_cliente c        on a.idcliente = c.idcliente
      left join mct_producto d  on a.idproducto = d.idproducto
      join mct_tipoorden e      on a.idtipoorden = e.idtipoorden
      join mct_familia f        on a.idfamilia = f.idfamilia
     where a.idordentrabajo = idworkorders;
     
END;
$$;


ALTER FUNCTION traking.evtlistworkorderdata(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 2323 (class 1255 OID 17367)
-- Name: evtlistworkorderdesgaste(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlistworkorderdesgaste(idfamily bigint, startdate character varying, enddate character varying) RETURNS TABLE(item bigint, idworkorder bigint, customershortname character varying, ordertypename character varying, purshaseorder bigint, itemcode bigint, creationdate character varying, deliverydate character varying, dispatchdate character varying, customerot character varying, quotation bigint, nepcastproductname character varying, blueprintname character varying, componentname character varying, materialname character varying, outputguide bigint, statusname character varying, iddespachopartecabecera bigint, quantity bigint, quantitydispatch bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
    
			select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) AS item,
			       a.idordentrabajo ,
			       d.nombrecorto ,       
			       e.nombretipoorden ,
			       a.ordencompra ,
			       b.codigopieza ,      
			 	   cast(to_char(a.fechacreacion, 'dd-mm-yyyy') as varchar) ,
				   cast(to_char(a.fechaentrega, 'dd-mm-yyyy') as varchar) ,
			       cast(to_char(g.fechadespacho, 'dd-mm-yyyy') as varchar),     
			       a.otcliente ,
			       b.costo ,
			       c.nombreproductonepcast ,       
			       b.nombreplano ,
			       b.nombrecomponentetemp ,
			       b.nombrematerialtemp ,
			       g.guiasaliente ,
			       f.nombreestado ,
			       g.iddespachopartecabecera ,       
			       b.cantidad ,
			       sum(h.qdespacho) 
			  from mct_ordentrabajo a
			  left join  mct_ordentrabajorepuesto b on a.idordentrabajo = b.idordentrabajo
			  left join  mct_productonepcast c on b.idproductonepcast = c.idproductonepcast
			  left join  mct_cliente d on a.idcliente = d.idcliente
			  left join  mct_tipoorden e on a.idtipoorden = e.idtipoorden
			  left join  mct_estadoorden f on a.idestadoorden = f.idestadoorden
			  left join  mct_despachopartecabecera g on a.idordentrabajo = g.idordentrabajo
			  left join  mct_despachopartedetalle h on g.iddespachopartecabecera = h.iddespachopartecabecera and b.idordentrabajorepuesto = h.idordentrabajoparte
			 where g.fechadespacho >= to_date(startdate,'yyyy-mm-dd') 
			   and g.fechadespacho <= to_date(enddate,'yyyy-mm-dd') 
			   and a.idfamilia = idfamily
			   group by a.idordentrabajo ,
			            d.nombrecorto ,
				        e.nombretipoorden ,
				        a.ordencompra ,
			 	        b.codigopieza ,       
			 	        cast(to_char(a.fechacreacion, 'dd-mm-yyyy') as varchar) ,
				        cast(to_char(a.fechaentrega, 'dd-mm-yyyy') as varchar) ,
			    	    cast(to_char(g.fechadespacho, 'dd-mm-yyyy') as varchar),
			     	    a.otcliente ,
			      	    b.costo ,
			       		c.nombreproductonepcast ,       
			       		b.nombreplano ,
			       		b.nombrecomponentetemp ,
			       		b.nombrematerialtemp ,
			       		g.guiasaliente ,
			       		f.nombreestado ,
			            g.iddespachopartecabecera ,       		
			       		b.cantidad 
			   order by a.idordentrabajo desc;

END;
$$;


