--
-- TOC entry 1434 (class 1255 OID 17369)
-- Name: evtloginapp(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtloginapp(users character varying) RETURNS TABLE(iduser bigint, username character varying, passwd character varying, dni character varying, name character varying, mail character varying, namecustomer character varying, idcustomer bigint)
    LANGUAGE plpgsql
    AS $$
declare
	sp_idcliente	bigint;
	sp_idusuario	bigint;
begin
	
	sp_idcliente	:= 0;
    sp_idusuario	:= 0;

	select idcliente ,
	       idusuario
	  into sp_idcliente,
	  	   sp_idusuario
	  from mct_usuario mu 
	 where usuario = users;

	if ( sp_idcliente = 77 ) then
	
	
		if ( sp_idusuario in (4,34,22,6,83,40,20,39,41,5,35,49, 17, 44, 19, 27) ) then
	
		    RETURN QUERY
		    
		    select a.idusuario,
		           a.usuario ,
		           "password" ,
		           a.rut ,
		           a.nombre,
		           a.email ,
		           nombrecliente,
		           a.idcliente 
		      from mct_usuario a,
		           mct_cliente b
		    where usuario = users
		      and a.idcliente = b.idcliente;
	     
		else

		    RETURN QUERY
		    
		    select a.idusuario,
		           a.usuario ,
		           cast("password"||'xxx' as varchar),
		           a.rut ,
		           a.nombre,
		           a.email ,
		           nombrecliente,
		           a.idcliente 
		      from mct_usuario a,
		           mct_cliente b
		    where usuario = users
		      and a.idcliente = b.idcliente;		
		
		end if;
    


	else

		    RETURN QUERY
		    
		    select a.idusuario,
		           a.usuario ,
		           "password" ,
		           a.rut ,
		           a.nombre,
		           a.email ,
		           nombrecliente,
		           a.idcliente 
		      from mct_usuario a,
		           mct_cliente b
		    where usuario = users
		      and a.idcliente = b.idcliente;
		     
	end if;


		     
		
END;
$$;


ALTER FUNCTION traking.evtloginapp(users character varying) OWNER TO postgres;

--
-- TOC entry 1487 (class 1255 OID 17370)
-- Name: evtloginappnewtablet(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtloginappnewtablet(users character varying) RETURNS TABLE(iduser bigint, username character varying, passwd character varying, dni character varying, name character varying, mail character varying, namecustomer character varying, idcustomer bigint, flagevaluacion boolean, flagcambioingenieria boolean, flagcontrolmaquina boolean, flagdespacho boolean, flagdefectofundicion boolean, flaginsp boolean, flaglimpiezamaquina boolean, flagmateriaprima boolean, flagnoconformidad boolean, flagnoconformidadcald boolean, flagotra1 boolean, flagotra2 boolean, flagotra3 boolean, flagotra4 boolean, flagotra5 boolean, flagotra6 boolean, flagotra7 boolean, flagotra8 boolean, flagotra9 boolean, flagotra10 boolean)
    LANGUAGE plpgsql
    AS $$
