--
-- TOC entry 1062 (class 1255 OID 17371)
-- Name: evtloginuser(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtloginuser(userup character varying, passwordup character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
      sp_password     varchar;
	  sp_idusuario    varchar;
	  sp_perfil       varchar;
	  sp_sesionestado INTEGER;
BEGIN

     IF (SELECT 1 
           FROM traking.mct_usuario
          WHERE usuario=userup ) then
         
			 IF ( SELECT 1 	
			        FROM traking.mct_usuario
				   WHERE (usuario=userup AND password = passwordup) ) THEN
						
				  SELECT sesionestado, 
				         idusuario,
				         idperfil
					INTO sp_sesionestado, 
				         sp_idusuario,
				         sp_perfil
					FROM traking.mct_usuario
				   WHERE (usuario=userup AND password = passwordup);
						
 				IF ( sp_sesionestado = 1 ) then
						
				    RETURN CONCAT('0:Usuario tiene una sesion activa:',sp_idusuario,':',sp_perfil);
						
				else
					    
					UPDATE traking.mct_usuario 
					   SET sesionestado = 1
				     WHERE (usuario=userup AND password = passwordup);
								
					RETURN CONCAT('0:Exito:',sp_idusuario,':',sp_perfil);
						
				END IF;
					
			 else
			 
				RETURN '1:La contraseña es incorrecta, vuelva a intentarlo:-1';
			
			 END IF;
			
		 else
		 
			RETURN '1:El Usuario no se encuentra registrado:-1';
		
		END IF;
	
	RETURN '1:Error en la autentificación:-1';
END;
$$;


ALTER FUNCTION traking.evtloginuser(userup character varying, passwordup character varying) OWNER TO postgres;

--
-- TOC entry 1950 (class 1255 OID 17372)
-- Name: evtloginuserdesktop(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtloginuserdesktop(userup character varying, passwordup character varying) RETURNS TABLE(iduser bigint, idcon bigint, msgcon character varying, idprofile bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
      sp_password     varchar;
	  sp_idusuario    varchar;
	  sp_perfil       varchar;
	  sp_sesionestado INTEGER;
BEGIN

     IF (SELECT 1 
           FROM traking.mct_usuario
          WHERE usuario=userup ) then
         
			 IF ( SELECT 1 	
			        FROM traking.mct_usuario
				   WHERE (usuario=userup AND password = passwordup) ) THEN
						
				  SELECT sesionestado, 
				         idusuario,
				         idperfil
					INTO sp_sesionestado, 
				         sp_idusuario,
				         sp_perfil
					FROM traking.mct_usuario
				   WHERE (usuario=userup AND password = passwordup);
						
	 				IF ( sp_sesionestado = 1 ) then
							
	 				    iduser = sp_idusuario;
	 				    idcon  = 0;
	 				    msgcon = 'Usuario tiene una sesion activa';
	 				    idprofile = sp_perfil;

                        if (select 1
                              from traking.mct_bitacoraaccesos
                             where idusuario = cast(sp_idusuario as bigint)) then

							update traking.mct_bitacoraaccesos
                               set fechaultimaconexion = now()
                             where idusuario = cast(sp_idusuario as bigint);

						else

							insert into traking.mct_bitacoraaccesos (
										idusuario,
										usuario,
										fechaultimaconexion)
								values (cast(sp_idusuario as bigint),
                                        userup,
                                        now()
									);

						end if;	 				   

	 				    return next;
	
	 				   --RETURN CONCAT('0:Usuario tiene una sesion activa:',sp_idusuario,':',sp_perfil);
							
					else
						    
                        if (select 1
                              from traking.mct_bitacoraaccesos
                             where idusuario = cast(sp_idusuario as bigint)) then

							update traking.mct_bitacoraaccesos
                               set fechaultimaconexion = now()
                             where idusuario = cast(sp_idusuario as bigint);

						else

							insert into traking.mct_bitacoraaccesos (
										idusuario,
										usuario,
										fechaultimaconexion)
								values (cast(sp_idusuario as bigint),
                                        userup,
                                        now()
									);

						end if;

						UPDATE traking.mct_usuario 
						   SET sesionestado = 1
					     WHERE (usuario=userup AND password = passwordup);
									
					    iduser = sp_idusuario;
	 				    idcon  = 0;
	 				    msgcon = 'Exito';
	 				    idprofile = sp_perfil;
	 				   
	 				    return next;
						--RETURN CONCAT('0:Exito:',sp_idusuario,':',sp_perfil);
							
					END IF;
					
			 else

			 	iduser = 0;
 				idcon  = 1;
 				msgcon = 'La contraseña es incorrecta, intente nuevamente';
 				idprofile = 0;
 			
 			    return next;
 				 				   
				--RETURN '1:La contraseña  no es vñalida, intente nuevamente:-1';
			
			 END IF;
			
	else

		iduser = 0;
 		idcon  = 2;
 		msgcon = 'El Usuario no se encuentra registrado, intente nuevamente';
 		idprofile = 0;
 		
 	    return next;
		--RETURN '1:El Usuario no se encuentra registrado:-1';
		
	END IF;
	
--	RETURN '1:Error en la autentificación:-1';
END;
$$;


ALTER FUNCTION traking.evtloginuserdesktop(userup character varying, passwordup character varying) OWNER TO postgres;

--
-- TOC entry 1933 (class 1255 OID 17373)
-- Name: evtlogoutuser(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtlogoutuser(userup character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
      sp_password     varchar;
	  sp_idusuario    varchar;
	  sp_sesionestado INTEGER;
BEGIN

    IF (SELECT 1 
          FROM traking.mct_usuario 
         WHERE usuario=userup ) THEN
						
		 SELECT sesionestado, 
		        idusuario  
		   INTO sp_sesionestado, 
		        sp_idusuario 	
		   FROM traking.mct_usuario
		  WHERE (usuario=userup);
						
		IF ( sp_sesionestado = 0 ) then
		
			RETURN '0:Usuario NO tiene sesion activa:-1';
		
		else
		
			UPDATE traking.mct_usuario 
			   SET sesionestado = 0
			 WHERE (usuario=userup);
			
			RETURN CONCAT('0:Exito:',sp_idusuario);
		
		END IF;
	
	 else
	 
		RETURN '1:Usuario no registrado:-1';
	
	END IF;

	RETURN '1:Error en autentificacion:-1';
END;
$$;


ALTER FUNCTION traking.evtlogoutuser(userup character varying) OWNER TO postgres;

--
-- TOC entry 1224 (class 1255 OID 17374)
-- Name: evtnotifmailsla(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtnotifmailsla() RETURNS TABLE(ot_out bigint, email_out character varying, subject_out character varying, body_out character varying)
    LANGUAGE plpgsql
    AS $$

declare

		sp_idsla				INTEGER;
		sp_nombresla			VARCHAR(100);
		rec1 					record;
	
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_cuerpo               varchar;
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_ingeniero            varchar;
	    dias_texto              integer;
	    texto_atraso            varchar;
	    texto_asunto            varchar;
	    texto_cuerpo            varchar;
	    nombre_producto         varchar;
	    nombre_cliente          varchar;
	   
		rec_email               RECORD;
	    cur_email               CURSOR(sp_idnoti integer)
		                    		  FOR select distinct c.emaildestino 
		         						    from mct_notificacionlista a,
		         						         mct_listaemail b,
		         						         mct_email c
		         						   where a.idnotificacion = sp_idnoti
		         					         and a.idlista = b.idlista
		         						     and b.idemail = c.idemail ;
	
BEGIN
	
	   FOR rec1 IN (   
					SELECT a.idordentrabajo,
						   a.idsla,
						   b.nombresla ,
						   a.fecha_inicio,
						   a.fecha_termino,
						   a.fecha_inicio_aviso,
						   a.dias_tramo,
						   a.nro_alarmas_enviada,
						   a.reintentos,
						   a.idlista,
						   a.estado,
						   CURRENT_DATE::DATE - a.fecha_termino::DATE as dias
					  FROM traking.mct_progavisos a,
					       traking.mct_sla b 
					 WHERE a.estado= 0
					   and now() >= fecha_inicio_aviso 
					   and a.idsla = b.idsla 
					   and a.idordentrabajo >= 30000
				  ORDER BY idordentrabajo desc
					)
		LOOP	
									

	   
	    sp_texto        := '';
	    sp_asunto       := '';
	    sp_cuerpo       := '';
	    sp_ingeniero    := '';
	    dias_texto      := 0;
	    texto_atraso    := '';
	    texto_asunto    := '';
	    texto_cuerpo    := '';
	    nombre_producto := '';
	    nombre_cliente  := '';
	   
		select asunto, 
		       cuerpo 
		  into sp_asunto,
		       sp_cuerpo
		  from mct_cuerpomensaje 
		 where idnotificacion = 11;
		
		select b.nombre ,
		       a.nombreordentrabajo,
		       c.nombrecliente 
		  into sp_ingeniero,
		       nombre_producto,
		       nombre_cliente
		  from mct_ordentrabajo a,
		       mct_usuario b,
		       mct_cliente c
		 where idordentrabajo = rec1.idordentrabajo
		   and a.idusuario = b.idusuario
		   and a.idcliente = c.idcliente ;
		
		
		 if rec1.dias <= 0 then
		    dias_texto   := rec1.dias * -1;
		    texto_atraso := 'le quedan '||dias_texto||' días ';
		 else
		    dias_texto   := rec1.dias;
		    texto_atraso := 'lleva '||dias_texto||' días de atraso ';	 
		 end if;
		
			    
	     sp_lista := '';
	   
	      FOR rec_email IN (   
						select distinct c.emaildestino 
	         			  from mct_notificacionlista a,
	         				   mct_listaemail b,
	         		           mct_email c
	         		     where a.idnotificacion = rec1.idsla
	         	           and a.idlista = b.idlista
	         		       and b.idemail = c.idemail 
						)
			loop 	
			
			     sp_lista := rec_email.emaildestino||','||sp_lista;
			           
		  END LOOP;
	 
		 if ( rec1.idsla = 4 ) then
	         sp_ingeniero := 'LUIS RODRIGUEZ';
	     end if;
	 
		 texto_asunto := REPLACE(sp_asunto,'_valor_ot',rec1.idordentrabajo::varchar);
		 texto_cuerpo := REPLACE(sp_cuerpo,'_valor_ot',rec1.idordentrabajo::varchar);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_valor_ingeniero',sp_ingeniero);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_texto_dias',texto_atraso);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_valor_proceso',rec1.nombresla);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_valor_fecha',sp_fecha_hoy);		 

		 texto_cuerpo := REPLACE(texto_cuerpo,'_valor_nombre',nombre_producto);	
		 texto_cuerpo := REPLACE(texto_cuerpo,'_valor_cliente',nombre_cliente);	
						
		 ot_out      := rec1.idordentrabajo;
		 email_out   := sp_lista;
		 subject_out := texto_asunto;
		 body_out    := texto_cuerpo;
		 								
							
				RETURN NEXT; 	
						
				UPDATE traking.mct_progavisos 
				   SET nro_alarmas_enviada = nro_alarmas_enviada + 1 
				 WHERE idordentrabajo = rec1.idordentrabajo 
				   and idsla = rec1.idsla;
				--END IF;

END LOOP;

END;
$$;


ALTER FUNCTION traking.evtnotifmailsla() OWNER TO postgres;

--
-- TOC entry 1165 (class 1255 OID 17375)
-- Name: evtnotifmailslasolca(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtnotifmailslasolca() RETURNS TABLE(ot_out bigint, email_out character varying, subject_out character varying, body_out character varying)
    LANGUAGE plpgsql
    AS $$

declare

		sp_idsla				INTEGER;
		sp_nombresla			VARCHAR(100);
		rec1 					record;
	
	    sp_lista                varchar;
	    sp_notificacion         integer;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_cuerpo               varchar;
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_ingeniero            varchar;
	    dias_texto              integer;
	    texto_atraso            varchar;
	    texto_asunto            varchar;
	    texto_cuerpo            varchar;
	    nombre_producto         varchar;
	    nombre_cliente          varchar;
	    sp_nombrebomba          varchar;
	    sp_porcentaje           integer;
	    cant_sol                integer;
	    cant_recep              integer;
	    sp_dias                 integer;
	   
		rec_email               RECORD;
	    cur_email               CURSOR(sp_idnoti integer)
		                    		  FOR select distinct c.emaildestino 
		         						    from mct_notificacionlista a,
		         						         mct_listaemail b,
		         						         mct_email c
		         						   where a.idnotificacion = sp_idnoti
		         					         and a.idlista = b.idlista
		         						     and b.idemail = c.idemail ;
	
BEGIN
	
	   FOR rec1 IN (   
					SELECT distinct a.idordentrabajo,
					       a.qrcode ,
					       a.tipotrabajo ,
					       a.idusuario ,
					       b.nombre ,
						   a.fecha_inicio,
						   a.fecha_termino,
						   a.fecha_inicio_aviso,
						   a.idlista,
						   a.estado,
						   CURRENT_DATE::DATE - a.fecha_termino::DATE as dias
					  FROM traking.mct_progavisoschecklist a,
					       traking.mct_checklistinftec c,
					       traking.mct_usuario b
					 WHERE a.estado= 0
					   and now() >= fecha_inicio_aviso 
					   and a.idordentrabajo  >= 30000
					   --and a.idordentrabajo = 30036
					   and a.idordentrabajo = c.idordentrabajo 
					   and a.sigla = 'FAB_CA'
					   and a.sigla = c.tipotrabajostd 
					   and a.idusuario  = b.idusuario 
				  ORDER BY idordentrabajo desc
					)
		LOOP						
		
	   
	    sp_texto        := '';
	    sp_asunto       := '';
	    sp_cuerpo       := '';
	    sp_ingeniero    := '';
	    dias_texto      := 0;
	    texto_atraso    := '';
	    texto_asunto    := '';
	    texto_cuerpo    := '';
	    nombre_producto := '';
	    nombre_cliente  := '';
	    sp_porcentaje   := 0;
	    cant_sol        := 0;
	    cant_recep      := 0;
	    sp_dias         := 0;
	   
	    sp_notificacion := 0;
	   

	   
	    if (rec1.dias = 0) then
	    
	       sp_notificacion := 33;
	      
	    		select asunto, 
				       cuerpo 
				  into sp_asunto,
				       sp_cuerpo
				  from mct_cuerpomensaje 
				 where idnotificacion = 33;
		
	    end if;
	    if (rec1.dias > 0) then

	    	sp_notificacion := 32;
	    	      
	    		select asunto, 
				       cuerpo 
				  into sp_asunto,
				       sp_cuerpo
				  from mct_cuerpomensaje 
				 where idnotificacion = 32;
		
	    end if;
	    if (rec1.dias < 0) then
	    
	    	sp_notificacion := 34;
	    
	            select asunto, 
				       cuerpo 
				  into sp_asunto,
				       sp_cuerpo
				  from mct_cuerpomensaje 
				 where idnotificacion = 34;
		
	    end if;	   
	
	   -- Saca cantidad total solicitada
	    select coalesce (sum(cantidad),0)
	      into cant_sol
	      from mct_checklistinftec  
	     where codigoqr = rec1.qrcode;
	    
	    -- Saca cantidad entregada
	    select coalesce (sum(cantidad),0) 
	      into cant_recep
	      from mct_checklistinftecrecept 
	     where codigoqr = rec1.qrcode;
		
	    if (cant_sol > 0) then
	       sp_porcentaje := round((cant_recep * 100)/cant_sol);
			    
	    else
	       sp_porcentaje := 0;
	    end if;
	      sp_lista := '';
	   
	      FOR rec_email IN (   
						select distinct c.emaildestino 
	         			  from mct_notificacionlista a,
	         				   mct_listaemail b,
	         		           mct_email c
	         		     where a.idnotificacion = sp_notificacion
	         	           and a.idlista = b.idlista
	         		       and b.idemail = c.idemail 
						)
			loop 	
			
			     sp_lista := rec_email.emaildestino||','||sp_lista;
			           
		  END LOOP;
	 
		-- Extrae el nombre del modelo
	    select e.sigla||' '||d.nombremodelo||' '||f.nombreparam 
		  into sp_nombrebomba
		  from mct_ordentrabajo a
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
	  	 where a.idordentrabajo = rec1.idordentrabajo;
  	
	 
		 texto_asunto := REPLACE(sp_asunto,'_val_ot',rec1.idordentrabajo::varchar);
		 texto_asunto := REPLACE(texto_asunto,'_val_modelo',sp_nombrebomba::varchar);
				
		 texto_cuerpo := REPLACE(sp_cuerpo,'_val_ot',rec1.idordentrabajo::varchar);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_val_ingeniero',rec1.nombre);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_val_fecha',sp_fecha_hoy);		 
		 texto_cuerpo := REPLACE(texto_cuerpo,'_val_modelo',sp_nombrebomba::varchar);
		
		 if (rec1.dias > 0) then
		     texto_cuerpo := REPLACE(texto_cuerpo,'_val_dias',rec1.dias::varchar);	
		     texto_cuerpo := REPLACE(texto_cuerpo,'_val_porcentaje',sp_porcentaje::varchar);
		 end if;
		 if (rec1.dias = 0) then
		     texto_cuerpo := REPLACE(texto_cuerpo,'_val_dias',rec1.dias::varchar);		       
		 end if;
	
		 if (rec1.dias < 0) then
		     sp_dias      := rec1.dias*-1;
		     texto_cuerpo := REPLACE(texto_cuerpo,'_val_dias',sp_dias::varchar);		       
		 end if;
		
		 ot_out      := rec1.idordentrabajo;
		 email_out   := sp_lista;
		 subject_out := texto_asunto;
		 body_out    := texto_cuerpo;
		 								
							
		 RETURN NEXT; 	
						
