declare

		sp_idsla				INTEGER;
		sp_nombresla			VARCHAR(100);
		rec1 					record;
	
	    sp_lista                varchar;
	    sp_notificacion         integer;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_cuerpo               varchar;
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_ingeniero            varchar;
	    dias_texto              integer;
	    texto_atraso            varchar;
	    texto_asunto            varchar;
	    texto_cuerpo            varchar;
	    nombre_producto         varchar;
	    nombre_cliente          varchar;
	    sp_nombrebomba          varchar;
	    sp_porcentaje           integer;
	    cant_sol                integer;
	    cant_recep              integer;
	    sp_dias                 integer;
	   
		rec_email               RECORD;
	    cur_email               CURSOR(sp_idnoti integer)
		                    		  FOR select distinct c.emaildestino 
		         						    from mct_notificacionlista a,
		         						         mct_listaemail b,
		         						         mct_email c
		         						   where a.idnotificacion = sp_idnoti
		         					         and a.idlista = b.idlista
		         						     and b.idemail = c.idemail ;
	
BEGIN
	
	   FOR rec1 IN (   
					SELECT distinct a.idordentrabajo,
					       a.qrcode ,
					       a.tipotrabajo ,
					       a.idusuario ,
					       b.nombre ,
						   a.fecha_inicio,
						   a.fecha_termino,
						   a.fecha_inicio_aviso,
						   a.idlista,
						   a.estado,
						   CURRENT_DATE::DATE - a.fecha_termino::DATE as dias
					  FROM traking.mct_progavisoschecklist a,
					       traking.mct_checklistinftec c,
					       traking.mct_usuario b
					 WHERE a.estado= 0
					   and now() >= fecha_inicio_aviso 
					   and a.idordentrabajo  >= 30000
					   --and a.idordentrabajo = 30036
					   and a.idordentrabajo = c.idordentrabajo 
					   and a.sigla = 'FAB_PA'
					   and a.sigla = c.tipotrabajostd 
					   and a.idusuario  = b.idusuario 
				  ORDER BY idordentrabajo desc
					)
		LOOP	
									
	   
	    sp_texto        := '';
	    sp_asunto       := '';
	    sp_cuerpo       := '';
	    sp_ingeniero    := '';
	    dias_texto      := 0;
	    texto_atraso    := '';
	    texto_asunto    := '';
	    texto_cuerpo    := '';
	    nombre_producto := '';
	    nombre_cliente  := '';
	    sp_porcentaje   := 0;
	    cant_sol        := 0;
	    cant_recep      := 0;
	    sp_dias         := 0;
	   
	    sp_notificacion := 0;
	   
	   
	    if (rec1.dias = 0) then
	    
	       sp_notificacion := 30;
	      
	    		select asunto, 
				       cuerpo 
				  into sp_asunto,
				       sp_cuerpo
				  from mct_cuerpomensaje 
				 where idnotificacion = 30;
		
	    end if;
	    if (rec1.dias > 0) then

	    	sp_notificacion := 29;
	    	      
	    		select asunto, 
				       cuerpo 
				  into sp_asunto,
				       sp_cuerpo
				  from mct_cuerpomensaje 
				 where idnotificacion = 29;
		
	    end if;
	    if (rec1.dias < 0) then
	    
	    	sp_notificacion := 31;
	    
	            select asunto, 
				       cuerpo 
				  into sp_asunto,
				       sp_cuerpo
				  from mct_cuerpomensaje 
				 where idnotificacion = 31;
		
	    end if;	   
	
	   -- Saca cantidad total solicitada
	    select coalesce (sum(cantidad),0)
	      into cant_sol
	      from mct_checklistinftec  
	     where codigoqr = rec1.qrcode;
	    
	    -- Saca cantidad entregada
	    select coalesce (sum(cantidad),0) 
	      into cant_recep
	      from mct_checklistinftecrecept 
	     where codigoqr = rec1.qrcode;
		
	    if (cant_sol > 0) then
	       sp_porcentaje := round((cant_recep * 100)/cant_sol);
			    
	    else
	       sp_porcentaje := 0;
	    end if;
	      sp_lista := '';
	   
	      FOR rec_email IN (   
						select distinct c.emaildestino 
	         			  from mct_notificacionlista a,
	         				   mct_listaemail b,
	         		           mct_email c
	         		     where a.idnotificacion = sp_notificacion
	         	           and a.idlista = b.idlista
	         		       and b.idemail = c.idemail 
						)
			loop 	
			
			     sp_lista := rec_email.emaildestino||','||sp_lista;
			           
		  END LOOP;
	 
		-- Extrae el nombre del modelo
	    select e.sigla||' '||d.nombremodelo||' '||f.nombreparam 
		  into sp_nombrebomba
		  from mct_ordentrabajo a
		  join mct_producto c        on a.idproducto = c.idproducto
		  join mct_modelo d          on c.idmodelo = d.idmodelo
		  join mct_subfamilia e      on d.idsubfamilia = e.idsubfamilia
		  left join mct_etapaparam f on c.idetapaparam = f.idetapaparam
	  	 where a.idordentrabajo = rec1.idordentrabajo;
  	
	 
		 texto_asunto := REPLACE(sp_asunto,'_val_ot',rec1.idordentrabajo::varchar);
		 texto_asunto := REPLACE(texto_asunto,'_val_modelo',sp_nombrebomba::varchar);
				
		 texto_cuerpo := REPLACE(sp_cuerpo,'_val_ot',rec1.idordentrabajo::varchar);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_val_ingeniero',rec1.nombre);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_val_fecha',sp_fecha_hoy);		 
		 texto_cuerpo := REPLACE(texto_cuerpo,'_val_modelo',sp_nombrebomba::varchar);
		
		 if (rec1.dias > 0) then
		     texto_cuerpo := REPLACE(texto_cuerpo,'_val_dias',rec1.dias::varchar);	
		     texto_cuerpo := REPLACE(texto_cuerpo,'_val_porcentaje',sp_porcentaje::varchar);
		 end if;
		 if (rec1.dias = 0) then
		     texto_cuerpo := REPLACE(texto_cuerpo,'_val_dias',rec1.dias::varchar);		       
		 end if;
	
		 if (rec1.dias < 0) then
		     sp_dias      := rec1.dias*-1;
		     texto_cuerpo := REPLACE(texto_cuerpo,'_val_dias',sp_dias::varchar);		       
		 end if;
		
		 ot_out      := rec1.idordentrabajo;
		 email_out   := sp_lista;
		 subject_out := texto_asunto;
		 body_out    := texto_cuerpo;
		 								
							
		 RETURN NEXT; 	
						
			--	UPDATE traking.mct_progavisos 
			--	   SET nro_alarmas_enviada = nro_alarmas_enviada + 1 
			--	 WHERE idordentrabajo = rec1.idordentrabajo 
			--	   and idsla = rec1.idsla;
				--END IF;

END LOOP;

END;
$$;


ALTER FUNCTION traking.evtnotifmailslasolpa() OWNER TO postgres;

--
-- TOC entry 1412 (class 1255 OID 17385)
-- Name: evtregistragestionncfimputacion(bigint, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtregistragestionncfimputacion(p_idgestionncf bigint, p_descripcion character varying, p_usuario character varying, p_areas character varying, p_subareas character varying) RETURNS TABLE(codigo integer, descripcion character varying, idgestionncfimputacion bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

    sp_idgestionncfimputacion bigint;

    sp_areas_array varchar[];
    sp_subareas_array varchar[];

    sp_idarea bigint;
    sp_idsubarea bigint;

    sp_requieresubarea boolean;

    sp_areaexiste integer;
    sp_subareaexiste integer;
    sp_cantidad integer;

    sp_cantidad_areas integer;
    sp_cantidad_subareas integer;

    sp_i integer;

BEGIN

    /*
     * ==============================================================
     * 1. VALIDAR ID GESTION NCF
     * ==============================================================
     */

    IF p_idgestionncf IS NULL OR p_idgestionncf <= 0 THEN

        codigo := -1;
        descripcion := 'ID de Gestión NCF no válido';
        idgestionncfimputacion := -1;

        RETURN NEXT;
        RETURN;

    END IF;


    /*
     * ==============================================================
     * 2. VALIDAR QUE EXISTA EL RECHAZO
     * ==============================================================
     */

    SELECT COUNT(*)
      INTO sp_cantidad
      FROM mct_gestionncf
     WHERE idgestionncf = p_idgestionncf;

    IF sp_cantidad = 0 THEN

        codigo := -2;
        descripcion := 'No existe la Gestión NCF indicada';
        idgestionncfimputacion := -1;

        RETURN NEXT;
        RETURN;

    END IF;


    /*
     * ==============================================================
     * 3. CONTROLAR QUE NO HAYA SIDO IMPUTADO ANTERIORMENTE
     * ==============================================================
     */

    SELECT COUNT(*)
      INTO sp_cantidad
      FROM mct_gestionncfimputacion
     WHERE idgestionncf = p_idgestionncf;

    IF sp_cantidad > 0 THEN

        codigo := -3;
        descripcion := 'El rechazo ya fue imputado anteriormente';
        idgestionncfimputacion := -1;

        RETURN NEXT;
        RETURN;

    END IF;


    /*
     * ==============================================================
     * 4. VALIDAR DESCRIPCION EJECUTIVA
     * ==============================================================
     */

    IF p_descripcion IS NULL
       OR LENGTH(TRIM(p_descripcion)) = 0 THEN

        codigo := -4;
        descripcion := 'Debe ingresar la Descripción Ejecutiva de lo Sucedido';
        idgestionncfimputacion := -1;

        RETURN NEXT;
        RETURN;

    END IF;


    /*
     * ==============================================================
     * 5. VALIDAR AREAS
     * ==============================================================
     */

    IF p_areas IS NULL
       OR LENGTH(TRIM(p_areas)) = 0 THEN

        codigo := -5;
        descripcion := 'Debe seleccionar al menos un área de imputación';
        idgestionncfimputacion := -1;

        RETURN NEXT;
        RETURN;

    END IF;


    IF p_subareas IS NULL
       OR LENGTH(TRIM(p_subareas)) = 0 THEN

        codigo := -6;
        descripcion := 'Lista de subáreas no válida';
        idgestionncfimputacion := -1;

        RETURN NEXT;
        RETURN;

    END IF;


    /*
     * ==============================================================
     * 6. CONVERTIR STRINGS A ARRAYS
     * ==============================================================

       Ejemplo:

       p_areas    = '2,4'
       p_subareas = '10,0'

       Resultado:

       [2,10] = MECANIZADO CNC / TORNO HORIZONTAL
       [4,0]  = CONTROL DE CALIDAD / SIN SUBAREA
     */

    sp_areas_array :=
        string_to_array(
            REPLACE(p_areas, ' ', ''),
            ','
        );

    sp_subareas_array :=
        string_to_array(
            REPLACE(p_subareas, ' ', ''),
            ','
        );


    sp_cantidad_areas :=
        array_length(sp_areas_array, 1);

    sp_cantidad_subareas :=
        array_length(sp_subareas_array, 1);


    IF sp_cantidad_areas IS NULL
       OR sp_cantidad_areas = 0 THEN

        codigo := -7;
        descripcion := 'Debe seleccionar al menos un área de imputación';
        idgestionncfimputacion := -1;

        RETURN NEXT;
        RETURN;

    END IF;


    /*
     * Debe venir una subarea por cada area.
     * Cuando no aplica se envía 0.
     */

    IF sp_cantidad_subareas IS NULL
       OR sp_cantidad_areas <> sp_cantidad_subareas THEN

        codigo := -8;
        descripcion := 'La cantidad de áreas y subáreas no coincide';
        idgestionncfimputacion := -1;

        RETURN NEXT;
        RETURN;

    END IF;


    /*
     * ==============================================================
     * 7. VALIDAR TODAS LAS SELECCIONES ANTES DE INSERTAR
     * ==============================================================
     */

    FOR sp_i IN 1..sp_cantidad_areas LOOP

        /*
         * ----------------------------------------------------------
         * Convertir área a BIGINT
         * ----------------------------------------------------------
         */

        BEGIN

            sp_idarea :=
                TRIM(sp_areas_array[sp_i])::bigint;

        EXCEPTION
            WHEN OTHERS THEN

                codigo := -9;
                descripcion := 'Existe un identificador de área no válido';
                idgestionncfimputacion := -1;

                RETURN NEXT;
                RETURN;

        END;


        /*
         * ----------------------------------------------------------
         * Convertir subárea a BIGINT
         * ----------------------------------------------------------
         */

        BEGIN

            sp_idsubarea :=
                TRIM(sp_subareas_array[sp_i])::bigint;

        EXCEPTION
            WHEN OTHERS THEN

                codigo := -10;
                descripcion := 'Existe un identificador de subárea no válido';
                idgestionncfimputacion := -1;

                RETURN NEXT;
                RETURN;

        END;


        /*
         * 0 significa SIN SUBAREA
         */

        IF sp_idsubarea = 0 THEN
            sp_idsubarea := NULL;
        END IF;


        /*
         * ----------------------------------------------------------
         * Validar existencia del área
         * ----------------------------------------------------------
         */

        SELECT
            COUNT(*)
          INTO sp_areaexiste
          FROM mct_areaimputacionrechazo
         WHERE idareaimputacionrechazo = sp_idarea
           AND activo = true;


        IF sp_areaexiste = 0 THEN

            codigo := -11;
            descripcion := 'Existe un área de imputación inexistente o inactiva';
            idgestionncfimputacion := -1;

            RETURN NEXT;
            RETURN;

        END IF;


        /*
         * ----------------------------------------------------------
         * Saber si requiere subárea
         * ----------------------------------------------------------
         */

        SELECT requieresubarea
          INTO sp_requieresubarea
          FROM mct_areaimputacionrechazo
         WHERE idareaimputacionrechazo = sp_idarea
           AND activo = true;


        /*
         * ----------------------------------------------------------
         * AREA QUE REQUIERE SUBAREA
         * ----------------------------------------------------------
         */

        IF sp_requieresubarea = true THEN

            IF sp_idsubarea IS NULL THEN

                codigo := -12;
                descripcion := 'El área seleccionada requiere una subárea';
                idgestionncfimputacion := -1;

                RETURN NEXT;
                RETURN;

            END IF;


            /*
             * Validar que la subárea exista y pertenezca
             * exactamente al área indicada.
             */

            SELECT COUNT(*)
              INTO sp_subareaexiste
              FROM mct_subareaimputacionrechazo
             WHERE idsubareaimputacionrechazo = sp_idsubarea
               AND idareaimputacionrechazo = sp_idarea
               AND activo = true;


            IF sp_subareaexiste = 0 THEN

                codigo := -13;
                descripcion := 'La subárea seleccionada no pertenece al área indicada';
                idgestionncfimputacion := -1;

                RETURN NEXT;
                RETURN;

            END IF;


        ELSE

            /*
             * ------------------------------------------------------
             * AREA QUE NO UTILIZA SUBAREA
             * ------------------------------------------------------
             */

            IF sp_idsubarea IS NOT NULL THEN

                codigo := -14;
                descripcion := 'El área seleccionada no requiere subárea';
                idgestionncfimputacion := -1;

                RETURN NEXT;
                RETURN;

            END IF;

        END IF;

    END LOOP;


    /*
     * ==============================================================
     * 8. INSERTAR CABECERA
     * ==============================================================
     */

INSERT INTO mct_gestionncfimputacion
(
    idgestionncf,
    descripcion,
    fechaimputacion,
    usuario,
    estado
)
VALUES
(
    p_idgestionncf,
    TRIM(p_descripcion),
    NOW(),
    p_usuario,
    'REALIZADA'
)
RETURNING mct_gestionncfimputacion.idgestionncfimputacion
INTO sp_idgestionncfimputacion;


    /*
     * ==============================================================
     * 9. INSERTAR DETALLES
     * ==============================================================
     */

    FOR sp_i IN 1..sp_cantidad_areas LOOP

        sp_idarea :=
            TRIM(sp_areas_array[sp_i])::bigint;

        sp_idsubarea :=
            TRIM(sp_subareas_array[sp_i])::bigint;


        IF sp_idsubarea = 0 THEN
            sp_idsubarea := NULL;
        END IF;


        INSERT INTO mct_gestionncfimputaciondetalle
        (
            idgestionncfimputacion,
            idareaimputacionrechazo,
            idsubareaimputacionrechazo
        )
        VALUES
        (
            sp_idgestionncfimputacion,
            sp_idarea,
            sp_idsubarea
        );

    END LOOP;


    /*
     * ==============================================================
     * 10. RESPUESTA
     * ==============================================================
     */

    codigo := 0;
    descripcion := 'Imputación realizada correctamente';
    idgestionncfimputacion := sp_idgestionncfimputacion;

    RETURN NEXT;
    RETURN;

END;

$$;


ALTER FUNCTION traking.evtregistragestionncfimputacion(p_idgestionncf bigint, p_descripcion character varying, p_usuario character varying, p_areas character varying, p_subareas character varying) OWNER TO postgres;

--
-- TOC entry 1698 (class 1255 OID 17387)
-- Name: evtregistragestionncfmailenvio(bigint, character varying, character varying, character varying, text, text); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtregistragestionncfmailenvio(p_idgestionncf bigint, p_codhojaruta character varying, p_tipo character varying, p_asunto character varying, p_cuerpo text, p_emaildestino text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE

    sp_idgestionncfmailenvio bigint;

BEGIN

    /*
     * ==============================================================
     * VALIDACIONES BASICAS
     * ==============================================================
     */

    IF p_idgestionncf IS NULL
       OR p_idgestionncf <= 0 THEN

        RETURN -1;

    END IF;


    IF p_tipo IS NULL
       OR LENGTH(TRIM(p_tipo)) = 0 THEN

        RETURN -1;

    END IF;


    /*
     * ==============================================================
     * REGISTRAR SNAPSHOT DEL CORREO
     * ==============================================================
     */

    INSERT INTO traking.mct_gestionncfmailenvio
    (
        idgestionncf,
        codhojaruta,
        tipo,
        asunto,
        cuerpo,
        emaildestino,
        fechaenvio,
        enviado,
        resultadoenvio
    )
    VALUES
    (
        p_idgestionncf,
        p_codhojaruta,
        UPPER(TRIM(p_tipo)),
        p_asunto,
        p_cuerpo,
        p_emaildestino,
        NOW(),
        false,
        'PENDIENTE'
    )
    RETURNING idgestionncfmailenvio
    INTO sp_idgestionncfmailenvio;


    RETURN sp_idgestionncfmailenvio;

END;

$$;


ALTER FUNCTION traking.evtregistragestionncfmailenvio(p_idgestionncf bigint, p_codhojaruta character varying, p_tipo character varying, p_asunto character varying, p_cuerpo text, p_emaildestino text) OWNER TO postgres;

