CREATE FUNCTION traking.evtreparafechavencimientodefectofundicion() RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare

	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;
    
    sp_totalrespaldos 	bigint;
    sp_totalcargas		bigint;
   
    sp_horas			bigint;
    sp_atrasocarga		bigint;
    sp_diasem			bigint;
   
    sp_fechavenc		varchar;

BEGIN
		
  	    FOR rec1 IN (   
			 	 SELECT a.iddefectofundicion,
			 	        a.correlativo,
						a.fechacreacion,
						to_date(traking.calculavencimientodefecto(a.fechacreacion),'dd-mm-yyyy') as vencimiento
		 	 	    FROM traking.mct_defectofundicion a
				   where a.fechavencimiento is null
			)
		loop
		        
		    update mct_defectofundicion 
		       set fechavencimiento = rec1.vencimiento
		     where iddefectofundicion = rec1.iddefectofundicion;
			
			--raise notice '%', rec1.iddefectofundicion||' - '||sp_fechavenc;
		
	--return next;

	end loop;

	return 0;
		 
END;
$$;


