--
-- TOC entry 884 (class 1255 OID 17390)
-- Name: evtrespdefecto(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtrespdefecto(elemento character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
	strinTmp 		varchar(500) 	= '';
	var_record1 	record;
    primero			integer;
			  
BEGIN 

	primero	:= 0;
	FOR var_record1 in (
           select replace(replace(replace(replace(regexp_split_to_table,'"name":',''),'"',''),'}',''),']','') as texto from regexp_split_to_table(elemento,',') 
           where regexp_split_to_table like '%name%'
           )
     loop
	     
	    if (primero = 0) then 
		    primero	:= 1;
		    strinTmp := CONCAT(var_record1.texto);
		else 
		    strinTmp := CONCAT(strinTmp,E'\n',var_record1.texto);
		end if;
	
	end loop;
	 
    return strinTmp;
END			
$$;


ALTER FUNCTION traking.evtrespdefecto(elemento character varying) OWNER TO postgres;

--
-- TOC entry 1035 (class 1255 OID 17391)
-- Name: evtrespgestionncf(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtrespgestionncf(elemento character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
	strinTmp 		varchar(500) 	= '';
	var_record1 	record;
    primero			integer;
			  
BEGIN 

	primero	:= 0;
	FOR var_record1 in (
           select replace(replace(replace(replace(regexp_split_to_table,'"name":',''),'"',''),'}',''),']','') as texto from regexp_split_to_table(elemento,',') 
           where regexp_split_to_table like '%name%'
           )
     loop
	     
	    if (primero = 0) then 
		    primero	:= 1;
		    strinTmp := CONCAT(var_record1.texto);
		else 
		    strinTmp := CONCAT(strinTmp,E'\n',var_record1.texto);
		end if;
	
	end loop;
	 
    return strinTmp;
END			
$$;


