CREATE FUNCTION traking.evttablaanalisisdefectopdf(iddefectofundicions bigint) RETURNS TABLE(rowspan bigint, item bigint, nombrecausa character varying, nombreaccion character varying, nombreresponsable character varying, fechaejecucion character varying, nombrerespaldo character varying)
    LANGUAGE plpgsql
    AS $$
declare
	strinTmp 		varchar(500) 	= '';
	causa 			varchar(500) 	= '';
	var_record1 	record;
	var_record2 	record;
	indexi			INTEGER = 0;
    fectcausa		INTEGER = -1;
    val_rowSpam     INTEGER = 0;
    respaldo        varchar(500) 	= '';
    primero			integer = 0;
BEGIN

	FOR var_record1 in (
		
	    select b.iddefectocausa,
		       b.descripcion,
		       c.iddefectocausaaccion,
		       c.descripcion defecaccion,
		       to_char(c.fechaejecucion, 'dd-mm-yyyy') as fechaejecucion,
		       c.jsonresponsable,
		       traking.evtrespdefecto(c.jsonresponsable) responsable
		       --d.nombrerespaldo,
		       --d.nombrearchivo
	      from traking.mct_defectofundicion a
	      left join traking.mct_defectocausa b          on a.iddefectofundicion = b.iddefectofundicion
	      left join traking.mct_defectocausaaccion c    on b.iddefectocausa = c.iddefectocausa
	     -- left join traking.mct_defectocausaaccionpdf d on c.iddefectocausaaccion = d.iddefectocausaaccion
	     where a.iddefectofundicion = iddefectofundicions
	     order by b.iddefectocausa asc, c.iddefectocausaaccion  asc--, d.iddefectocausaaccionpdf asc

	  )
	  loop
		  
		raise notice '%', fectcausa||' - '||var_record1.iddefectocausa||' - '||var_record1.iddefectocausaaccion;
	
		 if ( fectcausa <> var_record1.iddefectocausa) then 
		 	
		    indexi = 1;
		 	fectcausa := var_record1.iddefectocausa;
		 	causa     := var_record1.descripcion;
			 
		    select count(*) 
		      into val_rowSpam
			  from traking.mct_defectofundicion a
			  left join traking.mct_defectocausa b          on a.iddefectofundicion = b.iddefectofundicion
			  left join traking.mct_defectocausaaccion c    on b.iddefectocausa = c.iddefectocausa
			  --left join traking.mct_defectocausaaccionpdf d on c.iddefectocausaaccion = d.iddefectocausaaccion
			 where a.iddefectofundicion = iddefectofundicions 
			   and b.iddefectocausa = fectcausa
			   and c.iddefectocausaaccion = var_record1.iddefectocausaaccion;
			  	
			  --raise notice '%', var_record1.iddefectocausaaccion;
			  
			  --raise notice '%', var_record1.iddefectocausa||' - '||var_record1.iddefectocausaaccion;
			 
			  primero	:= 0;
			  FOR var_record2 in (
			   		select ROW_NUMBER() OVER (ORDER BY d.iddefectocausaaccionpdf asc) AS item,
			   		       d.nombrerespaldo
			  		  from traking.mct_defectofundicion a
			  		  left join traking.mct_defectocausa b          on a.iddefectofundicion = b.iddefectofundicion
			  		  left join traking.mct_defectocausaaccion c    on b.iddefectocausa = c.iddefectocausa
			  		  left join traking.mct_defectocausaaccionpdf d on c.iddefectocausaaccion = d.iddefectocausaaccion
			  		 where a.iddefectofundicion = iddefectofundicions 
			  		   and b.iddefectocausa = fectcausa
			  		   and c.iddefectocausaaccion = var_record1.iddefectocausaaccion
			  		 )
			  loop 
				    if (primero = 0) then 
				       primero	:= 1;
				       respaldo := concat(var_record2.item||'. ',var_record2.nombrerespaldo);
				    else 
				       respaldo := concat(respaldo,E'\n'||var_record2.item||'. ',var_record2.nombrerespaldo);
				    end if;
				   
				   --raise notice '%', respaldo;
			  		
			  end loop;	   
		 else
		    indexi = indexi + 1;
		    causa = '';
		    primero	:= 0;
			  FOR var_record2 in (
			   		select ROW_NUMBER() OVER (ORDER BY d.iddefectocausaaccionpdf asc) AS item,
			   		       d.nombrerespaldo
			  		  from traking.mct_defectofundicion a
			  		  left join traking.mct_defectocausa b          on a.iddefectofundicion = b.iddefectofundicion
			  		  left join traking.mct_defectocausaaccion c    on b.iddefectocausa = c.iddefectocausa
			  		  left join traking.mct_defectocausaaccionpdf d on c.iddefectocausaaccion = d.iddefectocausaaccion
			  		 where a.iddefectofundicion = iddefectofundicions 
			  		   and b.iddefectocausa = fectcausa
			  		   and c.iddefectocausaaccion = var_record1.iddefectocausaaccion
			  		 )
			  loop 
				    if (primero = 0) then 
				       primero	:= 1;
				       respaldo := concat(var_record2.item||'. ',var_record2.nombrerespaldo);
				    else 
				       respaldo := concat(respaldo,E'\n'||var_record2.item||'. ',var_record2.nombrerespaldo);
				    end if;
				   
				   --raise notice '%', respaldo;
			  		
			  end loop;	 
		 end if;
		
		 rowspan 			:= val_rowSpam;
         item 				:= indexi;
         nombrecausa 		:= causa;
         nombreaccion 		:= cast(indexi||'. '||var_record1.defecaccion as varchar);
         nombreresponsable 	:= var_record1.responsable;
         fechaejecucion 	:= var_record1.fechaejecucion;        
         nombrerespaldo 	:= respaldo;
                	
	  	 return next;
	  
	  end loop;
END;
$$;


ALTER FUNCTION traking.evttablaanalisisdefectopdf(iddefectofundicions bigint) OWNER TO postgres;

