--
-- TOC entry 2064 (class 1255 OID 17394)
-- Name: evtupdatebypartwo(bigint, bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatebypartwo(idpartworkorderup bigint, idworktypeup bigint, observationup character varying, idreparefabup bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

	sp_reparafab	integer;

BEGIN 

	if (idworktypeup = 21) then
		sp_reparafab = 1;
	else
		sp_reparafab = 2;
	end if;
	
	update traking.mct_evaluacion
	   set idtipotrabajo   = idworktypeup,
	       observacion     = observationup,
	       idreparafabrica = sp_reparafab
	 where idordentrabajoparte = idpartworkorderup  ;
	       
END			
$$;


ALTER FUNCTION traking.evtupdatebypartwo(idpartworkorderup bigint, idworktypeup bigint, observationup character varying, idreparefabup bigint) OWNER TO postgres;

--
