-- Name: evtupdatebypartwoinsumo(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatebypartwoinsumo(idpartworkorderup bigint, idworktypeup bigint, insumocomp bigint, insumorec bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

	sp_reparafab	integer;

BEGIN 

	update traking.mct_evaluacion
	   set idtipotrabajo   = 21,
	       cantidadcompra     = insumocomp,
	       cantidadrecupera   = insumorec,
	       idreparafabrica = 1
	 where idordentrabajoparte = idpartworkorderup  ;
	       
END			
$$;


