--
-- TOC entry 1984 (class 1255 OID 17396)
-- Name: evtupdatechecklistinftecdetinf(bigint, character varying, bigint, character varying, character varying, boolean, bigint, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatechecklistinftecdetinf(idchecklistinftecup bigint, partnameup character varying, quantityup bigint, repaircriteriaup character varying, repairup character varying, returncompup boolean, indexrowup bigint, idcomponenteup bigint, idmaterialup bigint, materialnameup character varying, blueprintup character varying, nombrezonaup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_fecha_requerida      varchar;
    sp_criterioname			varchar;
    sp_nombrecomponente		varchar;
    sp_nombrematerial		varchar;
   
    sp_criterio				varchar;
    sp_texto				varchar;
   
    sp_idot					bigint;
			  
BEGIN 
	
	sp_criterioname		:= '';
    sp_nombrecomponente	:= '';
    sp_nombrematerial	:= '';
   
    sp_criterio			:= '';
    sp_texto			:= '';
   
    sp_idot				:= 0;

	select nombrecriterioevaluacion 
	  into sp_criterioname
	  from mct_criterioevaluacion 
	 where idcriterioevaluacion = cast(repaircriteriaup as bigint);

	select nombrecomponente  
	  into sp_nombrecomponente 
	  from mct_componente 
	 where idcomponente = cast(idcomponenteup as bigint);
	
	select nombrematerial  
	  into sp_nombrematerial 
	  from mct_material  
     where idmaterial  = cast(idmaterialup as bigint);
		
		
	if ( idchecklistinftecup = -1 ) then
	

		select idordentrabajo  
	 	  into sp_idot 
		  from mct_checklistinftec  
		 where idchecklistinftec = indexrowup;

	    --if ( sp_criterio not in  'FAB_FU' && sp_criterio != 'FAB_PA' && sp_criterio != 'FAB_CA' && && sp_criterio != 'RPO' ) then
	    if ( upper(sp_criterioname) not in  ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO', 'STOCK_CC', 'RPO_SM') ) then
	    
	        sp_criterio := 'OTROS';
	        sp_texto    := sp_idot||sp_criterio;
	       
	    else
	    
	        sp_criterio := upper(sp_criterioname);
	        sp_texto    := sp_idot||upper(sp_criterioname);
	       
	    end if;	
	   
		insert into mct_checklistinftec 
		           (
		           idchecklistinftec,
		           idordentrabajo ,
		           nombreparte ,
		           cantidad ,
		           material ,
		           criterio ,
		           reparacion ,
		           plano ,
		           usuariocreacion ,
		           fechacreacion ,
		           indicefila ,
		           codigoqr ,
		           tipotrabajostd ,
		           fecharequerida ,
		           devolucion ,
		           muestrachecklist ,
		           flagpantallafacturacion ,
		           idcomponente ,
		           nombrecomponente ,
		           idmaterial ,
		           nombrematerial ,
		           pesocomponente ,
		           flagtraeurgente ,
		           idesmecanizado ,
		           idcriterioevaluacion ,
		           nombrezona ,
		           idchecklistinftecparamdet ,
		           idpadre
		           )
		      select nextval('mct_checklistinftec_seq'),
		           	 idordentrabajo ,
		             nombreparte ,
		             quantityup ,
		             material ,
		             sp_criterioname ,
		             repairup ,
		             blueprintup ,
		             usuariocreacion ,
		             fechacreacion ,
		             indicefila ,
		             sp_texto ,
		             upper(sp_criterio) ,
		             fecharequerida ,
		             returncompup ,
		             muestrachecklist ,
		             flagpantallafacturacion ,
		             idcomponenteup ,
		             sp_nombrecomponente ,
		             idmaterialup ,
		             sp_nombrematerial ,
		             pesocomponente ,
		             flagtraeurgente ,
		             idesmecanizado ,
		             cast(repaircriteriaup as bigint),
		             nombrezona ,
		             idchecklistinftecparamdet ,
		             indexrowup
		        from mct_checklistinftec 
		       where idchecklistinftec = indexrowup;
	else

		select idordentrabajo  
	 	  into sp_idot 
		  from mct_checklistinftec  
		 where idchecklistinftec = idchecklistinftecup;

	    --if ( sp_criterio not in  'FAB_FU' && sp_criterio != 'FAB_PA' && sp_criterio != 'FAB_CA' && && sp_criterio != 'RPO' ) then
	    if ( upper(sp_criterioname) not in  ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO', 'STOCK_CC', 'RPO_SM') ) then
	    
	        sp_criterio := 'OTROS';
	        sp_texto    := sp_idot||sp_criterio;
	       
	    else
	    
	        sp_criterio := upper(sp_criterioname);
	        sp_texto    := sp_idot||upper(sp_criterioname);
	       
	    end if;	
		
		update traking.mct_checklistinftec
	 	   set cantidad = quantityup,
	 	       criterio = sp_criterioname,
	 	       idcriterioevaluacion = cast(repaircriteriaup as bigint),
	 	       reparacion = repairup,
	 	       devolucion  = returncompup,
	 	       tipotrabajostd = upper(sp_criterio),--upper(sp_criterioname),
	 	       codigoqr = sp_texto, --idordentrabajo||upper(sp_criterioname),
	 	       idcomponente = idcomponenteup,
	 	       nombrecomponente = sp_nombrecomponente,
	 	       idmaterial = idmaterialup,
	 	       nombrematerial = sp_nombrematerial,
	 	       plano = blueprintup,
	 	       nombrezona = nombrezonaup,
	 	       nombreparte = partnameup,
	 	       material = materialnameup
		 where idchecklistinftec = idchecklistinftecup;
		
	end if;

END			
$$;


ALTER FUNCTION traking.evtupdatechecklistinftecdetinf(idchecklistinftecup bigint, partnameup character varying, quantityup bigint, repaircriteriaup character varying, repairup character varying, returncompup boolean, indexrowup bigint, idcomponenteup bigint, idmaterialup bigint, materialnameup character varying, blueprintup character varying, nombrezonaup character varying) OWNER TO postgres;

