			       a.usuariocreacion, 
			       a.fechacreacion, 
			       a.indicefila, 
			       a.codigoqr, 
			       a.tipotrabajostd, 
			       a.fecharequerida, 
			       a.devolucion, 
			       a.muestrachecklist, 
			       a.flagpantallafacturacion, 
			       a.idcomponente, 
			       a.nombrecomponente, 
			       a.idmaterial, 
			       a.nombrematerial, 
			       a.pesocomponente, 
			       a.flagtraeurgente, 
			       a.idesmecanizado, 
			       a.idcriterioevaluacion, 
			       a.nombrezona, 
			       a.idchecklistinftecparamdet, 
			       a.idpadre ,
			       a.idchecklistinftec ,
			       a.noaplicasolicitud
			       --a.checklistvalido, 
			       --a.firmaingreso, 
			       --a.timbretrabajo, 
			       --a.materialconforme, 
			       --a.cantidadconforme, 
			       --a.planoconforme, 
			       --a.nombreconforme, 
			       --a.observacion
			  from traking.mct_checklistinftec a
			 where a.idordentrabajo = idworkorderup;

	end if;


END			
