CREATE FUNCTION traking.evtupdatechecklistinftecparamdet(idchecklistinftecparamdetup bigint, partnameup character varying, quantityup bigint, materialnameup character varying, repaircriteriaup character varying, repairup character varying, blueprintup character varying, idmaterialup bigint, idcomponenteup bigint, nombrezonaup character varying, pesocomponenteup double precision, idpadreup bigint, userupdate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_fecha_requerida      varchar;
    dias_totales            integer;
    dias_totalesaviso       integer;   
    minima_fecha            timestamp;
    maxima_fecha            timestamp;
    fecha_aviso             timestamp;   
   
    sp_estadoot             integer;
    sp_criterioname			varchar;
    sp_idcab				integer;
    sp_iddet				integer;
			  
BEGIN 
	
	sp_criterioname	:= '';
    sp_idcab		:= 0;

    if ( idchecklistinftecparamdetup = -1 ) then
    
        select nombrecriterioevaluacion
          into sp_criterioname    
          from mct_criterioevaluacion mc 
         where idcriterioevaluacion = cast(repaircriteriaup as bigint);
       
	    select a.idchecklistinftecparamcab 
	      into sp_idcab
	      from mct_checklistinftecparamdet a
	     where a.idchecklistinftecparamdet = idpadreup;   

 	   
		INSERT INTO traking.mct_checklistinftecparamdet
				(idchecklistinftecparamdet, 
				 idchecklistinftecparamcab, 
				 nombreparte, 
				 cantidad, 
				 material, 
				 criterio, 
				 reparacion, plano, idcomponente, idmaterial, idesmecanizado, idcriterioevaluacion, 
				 nombrezona, usuariocreacion, fechacreacion, pesocomponente, idpadre)
		  VALUES(nextval('mct_checklistinftecparamdet_seq'), 
	             sp_idcab, 
	             partnameup, 
	             quantityup, 
	             materialnameup, 
	             sp_criterioname, 
	             repairup, blueprintup, idcomponenteup, idmaterialup, 2, cast(repaircriteriaup as bigint),
	             nombrezonaup, 'admin', now(),  pesocomponenteup, idpadreup);


 
    else
    
    select coalesce (max(b.idrevisionchecklistparam), 0)
      into sp_idcab
      from mct_checklistinftecparamdet a
      left join mct_revisionchecklistparam b on a.idchecklistinftecparamcab = b.idchecklistinftecparamcab
     where a.idchecklistinftecparamdet = idchecklistinftecparamdetup;   
     
	INSERT INTO traking.mct_revisionchecklistinftecparamdet
		         (
		          idrevisionchecklistinftecparamdet,
		          idrevisionchecklistparam, 
		          idchecklistinftecparamdet, 
		          idchecklistinftecparamcab,
		          nombreparte, 
		          cantidad, 
		          material, 
		          criterio, 
		          reparacion, 
		          plano, 
		          idcomponente, 
		          idmaterial, 
		          idesmecanizado, 
		          idcriterioevaluacion, 
		          nombrezona, 
		          usuariocreacion, 
		          fechacreacion, 
		          usuariomodificacion, 
		          fechamodificacion, 
		          pesocomponente
		          )
	      select  nextval('mct_revisionchecklistinftecparamdet_seq'),
		          sp_idcab, 
		          a.idchecklistinftecparamdet, 
		          a.idchecklistinftecparamcab,
		          a.nombreparte, 
		          a.cantidad, 
		          a.material, 
		          a.criterio, 
		          a.reparacion, 
		          a.plano, 
		          a.idcomponente, 
		          a.idmaterial, 
		          a.idesmecanizado, 
		          a.idcriterioevaluacion, 
		          a.nombrezona, 
		          a.usuariocreacion, 
		          a.fechacreacion, 
		          a.usuariomodificacion, 
		          a.fechamodificacion, 
		          coalesce(a.pesocomponente,0)
		     from mct_checklistinftecparamdet a
		    where a.idchecklistinftecparamdet = idchecklistinftecparamdetup;


	select nombrecriterioevaluacion 
	  into sp_criterioname
	  from mct_criterioevaluacion 
	 where idcriterioevaluacion = cast(repaircriteriaup as bigint);

	update traking.mct_checklistinftecparamdet 
 	   set nombreparte = partnameup,
 	       cantidad = quantityup,
 	       material = materialnameup,
 	       criterio = sp_criterioname,
 	       idcriterioevaluacion = cast(repaircriteriaup as bigint),
 	       reparacion = repairup,
 	       plano = blueprintup,
 	       idmaterial = idmaterialup,
 	       idcomponente = idcomponenteup,
 	       nombrezona = nombrezonaup,
 	       pesocomponente = pesocomponenteup ,
 	       usuariomodificacion = userupdate,
	       fechamodificacion = now()
	 where idchecklistinftecparamdet = idchecklistinftecparamdetup;    
 	   
    end if;
   
END			
$$;


