CREATE FUNCTION traking.evtupdatecierrearmadodesarme(idordentrabajoi bigint, idclosemotivei bigint, idclosecausei bigint, rutresponsablecierratrabajoi character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
BEGIN

	if (idclosecausei = 420 ) then -- cerrado completo por ML
	
		--	Se actualiza el registro en proceso	
	    update traking.mct_movimientoordentrabajo 
	       set idmotivocierre = idclosemotivei,
	           idcausacierre  = 42,
	           fechatermino   = now(),
	           estadoactividad = 2 ,
               terminoarmadodesarme = 1,
               rutresponsablecierratrabajo = rutresponsablecierratrabajoi
	     where idordentrabajo = idordentrabajoi
		   and idaccion in (165, 173)
		   and estadoactividad = 1; 	
	
	else
	 -- cerrado completo por MA
		--	Se actualiza el registro en proceso	
	    update traking.mct_movimientoordentrabajo 
	       set idmotivocierre = idclosemotivei,
	           idcausacierre  = 42,
	           fechatermino   = now(),
	           estadoactividad = 2 ,
               terminoarmadodesarme = 2
	     where idordentrabajo = idordentrabajoi
		   and idaccion in (165, 173)
		   and estadoactividad = 1; 		
	
	end if;
 
  
END;
$$;


