--
-- TOC entry 1752 (class 1255 OID 17413)
-- Name: evtupdatecopycomponenthr(bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatecopycomponenthr(idworkorderse bigint, idroadmaptemp bigint, idcomponentcopytemp bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare

		rec1 			record;
	    sp_tiene        integer := 0;
begin
	
	  FOR rec1 IN (   
					select a.idactividad ,
					       a.tiempoproduccion , 
					       a.orden 
				      from mct_hojarutaactividadtemp a 
				     where a.idhojarutatemp = idroadmaptemp
				       and a.idactividad not in (select b.idactividad 
				                                 from mct_hojarutaactividadtemp b
				                                where b.idhojarutatemp = idcomponentcopytemp 
				                                  and a.idactividad = b.idactividad )
				       order by orden asc
							                                       
				  )
		loop 	
	            
		   sp_tiene:= 1;
		  
		
		   insert into mct_hojarutaactividadtemp 
		               (
		                idhojarutaactividadtemp ,
		                idhojarutatemp ,
		                idactividad ,
		                tiempoproduccion ,
		                orden 
		               )
                 values
                       (
                        nextval('mct_hojarutaactividadtemp_seq'),
                        idcomponentcopytemp,
                        rec1.idactividad,
                        rec1.tiempoproduccion,
                        rec1.orden
                  );
				     
		END LOOP;
	   
	if (sp_tiene = 0) then
	    return 9;
	else
		RETURN 1;
	end if;


	
END;
$$;


ALTER FUNCTION traking.evtupdatecopycomponenthr(idworkorderse bigint, idroadmaptemp bigint, idcomponentcopytemp bigint) OWNER TO postgres;

