--
-- TOC entry 1080 (class 1255 OID 17416)
-- Name: evtupdateevaluationdesktopapprove(bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdateevaluationdesktopapprove(idworkorderup bigint, iduserup bigint, conclusionup character varying, recomendationup character varying, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare

    sp_cliente     integer;
    sp_producto    integer;
    sp_tipoorden   integer;
    sp_neto        integer;
    sp_iva         integer;
    sp_total       integer;
    sp_cotizacion  integer;
    sp_estado      integer;
   
    sp_solicitudseq      integer;

BEGIN 
		    
	   update traking.mct_ordentrabajo
		  set idusuario  = iduserup,
		      conclusion = conclusionup,
		      recomendacion =recomendationup,
		      idestadoorden = 4,
		      usuariomodificacion = userupdateup,
		      fechamodificacion = now()
		where idordentrabajo = idworkorderup;
	   
	   
	   select idcliente,idproducto,idtipoorden
	     into sp_cliente, sp_producto, sp_tipoorden
		 from mct_ordentrabajo mo
        where idordentrabajo = idworkorderup;
       
       select round( sum(d.factorreparacion*c.costofabricacion)/100), 
       		  round((sum(d.factorreparacion*c.costofabricacion)/100)*0.19),
      		  round((sum(d.factorreparacion*c.costofabricacion)/100)+(sum(d.factorreparacion*c.costofabricacion)/100)*0.19)
      	  into sp_neto,
      	       sp_iva,
      	       sp_total
		  from mct_evaluacion a, 
		       mct_ordentrabajoparte b,
		       mct_parte c,
		       mct_tipotrabajo d
		 where a.idordentrabajoparte = b.idordentrabajoparte
		   and b.idordentrabajo = idworkorderup
		   and b.idparte = c.idparte
		   and a.idtipotrabajo = d.idtipotrabajo;
		  
		sp_cotizacion = nextval('traking.mct_cotizacion_seq');
		  
		INSERT INTO traking.mct_cotizacion
					(idcotizacion, 
					 nombrecotizacion, 
					 idcliente, 
					 idproducto, 
					 idtipoorden, 
					 montoneto, 
					 iva, 
					 total, 
					 estado, 
					 idordentrabajo,  
					 usuariocreacion, 
					 fechacreacion)
		      values ( sp_cotizacion,
		              'Cotizacion para OT : '||idworkorderup,
		              sp_cliente, 
		              sp_producto, 
		              sp_tipoorden, 
		              sp_neto, 
		              sp_iva, 
		              sp_total, 
		              1, 
		              idworkorderup, 
		              'admin', 
		              now());
		             
		 update mct_ordentrabajo
		    set idcotizacion = sp_cotizacion
		  where idordentrabajo = idworkorderup ;
		 
		 
		sp_solicitudseq = nextval('traking.inv_solicitud_seq');
	
		INSERT INTO traking.inv_solicitud
		            (idsolicitud, 
		             idordentrabajo, 
		             estado, 
		             usuariocreacion, 
		             fechacreacion)
		      VALUES(sp_solicitudseq, 
		             idworkorderup, 
		             1, 
		             'admin', 
		             now()
		             );

		insert into traking.inv_solicituddetalle
		           (idsolicituddetalle, 
		            idsolicitud, 
		            idtipoparte, 
		            idordentrabajoparte, 
		            idhojaruta, 
		            idplano, 
		            idmaterial, 
		            estado, 
		            usuariocreacion, 
		            fechacreacion
		            )
		select nextval('traking.inv_solicituddetalle_seq'),
		       sp_solicitudseq,
		       b.idtipoparte ,
		       a.idordentrabajoparte , 
		       c.idhojaruta ,
		       b.idplano ,
		       b.idmaterial ,
               1,
               'admin',
               now()        
		  from mct_ordentrabajoparte a,
		       mct_parte b,
		       mct_hojaruta c
		 where a.idordentrabajo = idworkorderup
		   and b.idtipoparte = 12
		   and a.idparte = b.idparte
		   and a.idordentrabajoparte = c.idordentrabajoparte ;
		             
	       
END			
$$;


ALTER FUNCTION traking.evtupdateevaluationdesktopapprove(idworkorderup bigint, iduserup bigint, conclusionup character varying, recomendationup character varying, userupdateup character varying) OWNER TO postgres;

