--
-- TOC entry 1883 (class 1255 OID 17420)
-- Name: evtupdatefacturacionscreenfacclte(bigint, boolean, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatefacturacionscreenfacclte(idworkorders bigint, facflab boolean, datetm character varying, dateclte character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

	    dias_totalescheck           integer;
	    dias_totalesaviso           integer;   
	    minima_fechacheck           timestamp;
	    maxima_fechacheck           timestamp; 
	    intervalocheck          	varchar;
    	intervalocheckavi       	varchar;  
    
        sp_idordertype				integer;
        sp_idfamily					integer;
        sp_ot						integer;
        sp_mec						integer;
        sp_cant						integer;

        sp_fechatm					timestamp;
        sp_fechaclte				timestamp;
        sp_fechafund				timestamp;
        
        -- Cambios el dia 08/09 pedidos por HC
        sp_fechamod					timestamp;
        sp_fechacol					timestamp;
       
        sp_fechaactual				timestamp;
       
BEGIN

		sp_idordertype	:= 0;
        -- Fechas
        sp_fechatm		:= null;
        sp_fechaclte	:= null;
        sp_fechafund	:= null;
        sp_fechaactual	:= null;
       
	    select idtipoorden ,
	           idfamilia ,
	           fechafaceclte
	      into sp_idordertype,
	           sp_idfamily,
	           sp_fechaactual
	      from mct_ordentrabajo mo 
	     where idordentrabajo = idworkorders;
	
        select idordentrabajo , idesmecanizado , count(*)
          into sp_ot, sp_mec, sp_cant
	      from mct_ordentrabajorepuesto mo 
	     where idordentrabajo = idworkorders 
	     group by idordentrabajo , idesmecanizado
	     having count(*) >= 1	
	     limit 1;

												  
	    if ( sp_idordertype in ( 2 , 7) ) then
	    
		    if ( sp_idfamily in (8, 10, 15) ) then
			   
		        sp_fechaclte	:=  to_date(dateclte,'yyyy-mm-dd');
			    sp_fechatm		:=	sp_fechaclte - interval '5 days';
			    sp_fechafund	:=	sp_fechaclte - interval '15 days';	
			   
			    -- Cambios el 08/09 pedidos por HC
			    sp_fechamod		:=	sp_fechaclte - interval '25 days';
			    sp_fechacol		:=	sp_fechamod + interval '2 days';
	    
		    end if;	    
		   
		    if ( sp_idfamily in (11) ) then

		        if ( sp_mec = 1 ) then
		        
			        sp_fechaclte	:=  to_date(dateclte,'yyyy-mm-dd');
				    sp_fechatm		:=	sp_fechaclte - interval '5 days';
				    sp_fechafund	:=	sp_fechaclte - interval '10 days';			     
				    
				    -- Cambios el 08/09 pedidos por HC
			        sp_fechamod		:=	sp_fechaclte - interval '25 days';
			        sp_fechacol		:=	sp_fechamod + interval '2 days';
			        
		        else
		        
		  			sp_fechaclte	:=  to_date(dateclte,'yyyy-mm-dd');
				    sp_fechatm		:=	sp_fechaclte - interval '5 days';
				    sp_fechafund	:=	sp_fechaclte - interval '10 days';	
				   
				    -- Cambios el 08/09 pedidos por HC
			        sp_fechamod		:=	sp_fechaclte - interval '15 days';
			        sp_fechacol		:=	sp_fechamod + interval '2 days';
		        
		        end if;
		       
	    
		    end if;	    
		   
	    elsif ( sp_idordertype in  (1, 3)) then
	    
		    if ( sp_idfamily in (8, 10, 15) ) then

		        sp_fechaclte	:=  to_date(dateclte,'yyyy-mm-dd');
			    sp_fechatm		:=	sp_fechaclte - interval '5 days';
			    sp_fechafund	:=	sp_fechaclte - interval '15 days';
			   
			    -- Cambios el 08/09 pedidos por HC
			    sp_fechamod		:=	sp_fechaclte - interval '25 days';
			    sp_fechacol		:=	sp_fechamod + interval '2 days';
	    
		    end if;	   	    
	    
	    end if;
	   
	 	update traking.mct_ordentrabajo
	       set fechafaceclte = sp_fechaclte,
	           flagfacturacion = facflab,
	           fechafacetm = sp_fechatm,
	           fechafundicion = sp_fechafund,
	           fechafundicion2 = sp_fechafund,
	           fechafundicionmodelo = sp_fechamod,
	           fechafundicioncal = sp_fechacol
	     where idordentrabajo = idworkorders;
	    
		if (sp_fechaclte < sp_fechaactual) then
		
		    update mct_checklistinftec 
		       set adelantafecha = true,
		           atrasafecha = false
		     where idordentrabajo = idworkorders;
		    
		    update mct_checklistinftecvalido  
		       set adelantafecha = true,
		           atrasafecha = false
		     where idordentrabajo = idworkorders;
		    
		
		end if;
	
		if (sp_fechaclte > sp_fechaactual) then
		
		    update mct_checklistinftec 
		       set atrasafecha = true,
		           adelantafecha = false
		     where idordentrabajo = idworkorders;
		    
		    update mct_checklistinftecvalido  
		       set atrasafecha = true,
		           adelantafecha = false
		     where idordentrabajo = idworkorders;
		    
		
		end if;

--	 if ( substring(dateclte,3,1) = '-') then
--	 
----		update traking.mct_ordentrabajo
----	       set fechafaceclte = to_date(dateclte,'dd-mm-yyyy'),
----	           flagfacturacion = facflab, 
----	           --fechafacetm = fechafacetm - interval '7 days'
----	           fechafacetm = to_date(dateclte,'dd-mm-yyyy') - interval '7 days',
----	           fechafundicion = to_date(dateclte,'dd-mm-yyyy') - interval '22 days',
----	           fechafundicion2 = to_date(dateclte,'dd-mm-yyyy') - interval '22 days'
----	     where idordentrabajo = idworkorders;	
--	    
--		update traking.mct_ordentrabajo
--	       set fechafaceclte = to_date(dateclte,'dd-mm-yyyy'),
--	           flagfacturacion = facflab, 
--	           --fechafacetm = fechafacetm - interval '7 days'
--	           fechafacetm = to_date(dateclte,'dd-mm-yyyy') - interval '7 days',
--	           fechafundicion = to_date(dateclte,'dd-mm-yyyy') - interval '22 days',
--	           fechafundicion2 = to_date(dateclte,'dd-mm-yyyy') - interval '22 days'
--	     where idordentrabajo = idworkorders;	 	    
--	 
--	 else
--
