--
-- TOC entry 1323 (class 1255 OID 17421)
-- Name: evtupdatefacturacionscreenfaccltedesgaste(bigint, boolean, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatefacturacionscreenfaccltedesgaste(idworkorders bigint, facflab boolean, idfamilyitemot bigint, datetm character varying, dateclte character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

	sp_fechaclte	timestamp;

BEGIN

	select fechafaceclte 
	  into sp_fechaclte
	  from mct_ordentrabajo mo 
	 where idordentrabajo = idworkorders;
	
	if (to_date(dateclte,'yyyy-mm-dd') < sp_fechaclte) then
	
	    update mct_checklistinftec 
	       set adelantafecha = true,
		       atrasafecha = false
	     where idordentrabajo = idworkorders;
	    
	    update mct_checklistinftecvalido  
	       set adelantafecha = true,
		       atrasafecha = false
	     where idordentrabajo = idworkorders;
	    
	
	end if;

	if (to_date(dateclte,'yyyy-mm-dd') > sp_fechaclte) then
	
	    update mct_checklistinftec 
	       set atrasafecha = true,
		       adelantafecha = false
	     where idordentrabajo = idworkorders;
	    
	    update mct_checklistinftecvalido  
	       set atrasafecha = true,
		       adelantafecha = false
	     where idordentrabajo = idworkorders;
	    
	
	end if;

	    if (idfamilyitemot = 111 or idfamilyitemot = 1111) then 

			update traking.mct_ordentrabajo
		       set fechaentrega = to_date(dateclte,'yyyy-mm-dd'),
		           fechafaceclte = to_date(dateclte,'yyyy-mm-dd'),
		           fechafacetm = to_date(dateclte,'yyyy-mm-dd') - interval '15 days',
		           fechafundicion = to_date(dateclte,'yyyy-mm-dd') - interval '15 days',
		           fechafundicion2 = to_date(dateclte,'yyyy-mm-dd') - interval '15 days',
			       flagfacturacion = facflab
		     where idordentrabajo = idworkorders;
		    
	    end if;
	   
	    if (idfamilyitemot = 112) then

			update traking.mct_ordentrabajo
		       set fechaentrega = to_date(dateclte,'yyyy-mm-dd'),
		           fechafaceclte = to_date(dateclte,'yyyy-mm-dd'),
		           --fechafacetm = fechafacetm - interval '7 days'
		           fechafacetm = to_date(dateclte,'yyyy-mm-dd'),
		           fechafundicion = to_date(dateclte,'yyyy-mm-dd'),
		           fechafundicion2 = to_date(dateclte,'yyyy-mm-dd'),
			       flagfacturacion = facflab
		     where idordentrabajo = idworkorders;
		    
	    end if;
	   
	
	   	if (idfamilyitemot = 8) then
	   	
	   		update traking.mct_ordentrabajo
		       set fechafaceclte = to_date(dateclte,'yyyy-mm-dd'),
			       fechafacetm = to_date(dateclte,'yyyy-mm-dd') - interval '7 days',
			       fechafundicion = to_date(dateclte,'yyyy-mm-dd') - interval '15 days',
			       fechafundicion2 = to_date(dateclte,'yyyy-mm-dd') - interval '15 days',
			       flagfacturacion = facflab
		     where idordentrabajo = idworkorders;	

	    end if;
	   
END;
$$;


ALTER FUNCTION traking.evtupdatefacturacionscreenfaccltedesgaste(idworkorders bigint, facflab boolean, idfamilyitemot bigint, datetm character varying, dateclte character varying) OWNER TO postgres;

--
-- TOC entry 1953 (class 1255 OID 17422)
-- Name: evtupdatefacturacionscreenfechatm(bigint, boolean, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatefacturacionscreenfechatm(idworkorders bigint, facflab boolean, datetm character varying, dateclte character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 
    
        sp_idordertype				integer;
        sp_idfamily					integer;
        sp_ot						integer;
        sp_mec						integer;
        sp_cant						integer;

        sp_fechatm					timestamp;
        sp_fechaclte				timestamp;
        sp_fechafacetm				timestamp;
        sp_fechafund				timestamp;
        
        -- Cambios el dia 08/09 pedidos por HC
        sp_fechamod					timestamp;
        sp_fechacol					timestamp;
       
        sp_fechaactual				timestamp;
       
BEGIN

		sp_idordertype	:= 0;
        sp_idfamily		:= 0;
        -- Fechas
        sp_fechatm		:= null;
       
	    select idtipoorden ,
	           idfamilia ,
	           fechafaceclte,
               fechafacetm
	      into sp_idordertype,
	           sp_idfamily,
	           sp_fechaactual,
               sp_fechafacetm
	      from mct_ordentrabajo mo 
	     where idordentrabajo = idworkorders;
							  
	    if ( sp_idordertype in ( 2 , 7) ) then
	    
		    if ( sp_idfamily in (8, 10, 15) ) then
			   
		        sp_fechatm	:=  to_date(datetm,'yyyy-mm-dd');
	    
		    end if;	    
		   
		    if ( sp_idfamily in (11) ) then

		        if ( sp_mec = 1 ) then
		        
			        sp_fechatm	:=  to_date(datetm,'yyyy-mm-dd');
			        
		        else
		        
		  			sp_fechatm	:=  to_date(datetm,'yyyy-mm-dd');
		        
		        end if;
		       
	    
		    end if;	    
		   
	    elsif ( sp_idordertype in  (1, 3)) then
	    
		    if ( sp_idfamily in (8, 10, 15) ) then

		        sp_fechatm	:=  to_date(datetm,'yyyy-mm-dd');

		    end if;	   	    
	    
	    end if;
	   
	 	update traking.mct_ordentrabajo
	       set fechafacetm = sp_fechatm,
               fechafacetmaviso = sp_fechafacetm
	     where idordentrabajo = idworkorders;
	      
END;
$$;


ALTER FUNCTION traking.evtupdatefacturacionscreenfechatm(idworkorders bigint, facflab boolean, datetm character varying, dateclte character varying) OWNER TO postgres;

