--

CREATE FUNCTION traking.evtupdatemailnotif(ot_in bigint, idsla_in bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

declare

		sp_date1						DATE;
	  sp_date2						DATE;
		sp_idsla						INTEGER;
		sp_nombresla				VARCHAR(12);
		sp_idestadoinicial	INTEGER;
		sp_idestadofinal		INTEGER;
		sp_escritico				INTEGER;
		sp_diastramo				INTEGER;
		sp_diasinicioaviso	INTEGER;
		sp_reintentos				INTEGER;
		sp_idlista					INTEGER;
		sp_estado						INTEGER;
		sp_fecha            TIMESTAMP;
		rec1 								record;
		sp_dias1            INTEGER;
		sp_dias2            INTEGER;
		sp_dias_aux         INTEGER;
		sp_dura_anterior    INTEGER;
	
BEGIN

      IF (SELECT 1 FROM mct_progavisos WHERE idordentrabajo = ot_in AND
			   idsla_in = idsla ) THEN 
				 UPDATE mct_progavisos SET estado = 1 WHERE idordentrabajo = ot_in AND
			   idsla_in = idsla;
				 RETURN '0:Exito';
		 ELSE
		    RETURN '1:No existe ';
		 END IF;

END;
$$;


