--
-- TOC entry 1874 (class 1255 OID 17429)
-- Name: evtupdatepassapp(character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatepassapp(keyrecup character varying, username character varying, passwd1 character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

BEGIN 
         
	IF (SELECT 1 
          FROM traking.mct_usuario
         WHERE usuario = username
           and "password" = keyrecup ) THEN

			update traking.mct_usuario 
			   set "password"   = passwd1
			 where usuario = username  ;
	
		    RETURN '0:Clave correcta';
	else
		RETURN '1:Clave incorrecta';
	end if;
	       
END			
$$;


