--
-- TOC entry 1764 (class 1255 OID 17430)
-- Name: evtupdatepdffileapp(bigint, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatepdffileapp(iduserup bigint, idcustomerup bigint, idworkorderup bigint, codpdffileappup bigint, tokenup character varying) RETURNS TABLE(flagenvio character varying, asuntoenvio text, mensajeenvio text)
    LANGUAGE plpgsql
    AS $$
declare 

   sp_idpdffileapp	integer;
   sp_cantidaddes	integer;  
   sp_nombrefile    varchar;
   sp_nombreuser	varchar;
   sp_nombreempresa	varchar;
   sp_asunto		varchar;
   sp_cuerpo		varchar;
  
   sp_cantidad		integer;
  
   texto_asunto		varchar;
   texto_cuerpo		varchar;
  
BEGIN 
	
   sp_idpdffileapp	:= 0;
   sp_cantidaddes	:= 0;
   sp_nombrefile	:= '';
   sp_nombreuser	:= '';
   sp_nombreempresa	:= '';
   sp_asunto		:= '';
   sp_cuerpo		:= '';
  
   sp_cantidad		:= 0;
  
   texto_asunto		:= '';
  
		select a.nombre,
		       b.nombrecliente
		  into sp_nombreuser,
		       sp_nombreempresa
		  from mct_usuario a,
		       mct_cliente b
		where a.idusuario = iduserup
		  and a.idcliente = b.idcliente ;

	
		select idpdffileapp,
		       cantidaddes,
		       nombre
		  into sp_idpdffileapp,
		       sp_cantidaddes,
		       sp_nombrefile
		  from mct_pdffileapp mp 
		 where codpdffileapp = codpdffileappup;
		
		select coalesce (count(*),0)
		  into sp_cantidad
		  from mct_enviofileapp me 
		 where idusuario = iduserup
	 	   and idcliente = idcustomerup
		   and idpdffileapp = sp_idpdffileapp
		   and idordentrabajo = idworkorderup;
		  
		
		select asunto,
		       cuerpo
		  into sp_asunto,
		       sp_cuerpo
		  from mct_cuerpomensaje mc 
		 where idcuerpomensaje= 41;


		 texto_asunto := REPLACE(sp_asunto,'_val_nombrefile',sp_nombrefile::varchar);
				
		 texto_cuerpo := REPLACE(sp_cuerpo,'_val_usuario',sp_nombreuser::varchar);
		 texto_cuerpo := REPLACE(texto_cuerpo,'_val_empresa',sp_nombreempresa::varchar);	
		
		
		 flagenvio := 'NO';		
		 if (sp_cantidad < sp_cantidaddes) then

		 	flagenvio := 'SI';
		 		
		 end if;
		
		 asuntoenvio	:= texto_asunto;
		 mensajeenvio	:= texto_cuerpo;
		  
		RETURN NEXT; 	

END			
$$;


ALTER FUNCTION traking.evtupdatepdffileapp(iduserup bigint, idcustomerup bigint, idworkorderup bigint, codpdffileappup bigint, tokenup character varying) OWNER TO postgres;

