--
-- TOC entry 1545 (class 1255 OID 17432)
-- Name: evtupdateprogramafacturaciondescarte(bigint, boolean, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdateprogramafacturaciondescarte(idordentrabajos bigint, checkdescarteup boolean, periodoup bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare

	sp_tiene		bigint;
	
BEGIN


	update traking.mct_ordentrabajo
       set checkdescarte = checkdescarteup
     where idordentrabajo = idordentrabajos;

	select coalesce(count(*), 0)
	  into sp_tiene
	  from mct_programafacturacionresumenfoto a 
	 where a.idordentrabajo = idordentrabajos
       and a.periodo = periodoup;

	if (sp_tiene > 0) then

		update mct_programafacturacionresumenfoto
		   set checkdescarte = checkdescarteup
	 	 where idordentrabajo = idordentrabajos
           and periodo = periodoup;

	else
	
		INSERT INTO traking.mct_programafacturacionresumenfoto
		           (idprogramafacturacionresumenfoto, 
		            idordentrabajo, 
		            checkdescarte, 
		            periodo
		            )
		     VALUES(nextval('traking.mct_programafacturacionresumenfoto_seq'), 
		            idordentrabajos, 
		            checkdescarteup,
		            periodoup
		           );

	end if;
	   
END;
$$;


