--
-- TOC entry 2288 (class 1255 OID 17434)
-- Name: evtupdateregisterjob(bigint, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdateregisterjob(idregisterjob bigint, idclosemotive bigint, idclosecause bigint, idaction bigint, roadmapcodes character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare

	   	--sp_codigoaccion     varchar;
	    sp_newmov           integer;
	   
	    sp_idordentrabajo	integer; 
        sp_idhojaruta		integer; 
        sp_codhojaruta		varchar;
        sp_idparte			integer;
        sp_idmaquina		integer; 
        sp_idseccion		integer; 
        sp_idactividad		integer; 
        sp_idaccion			integer; 
        sp_codigoaccion		varchar; 
        sp_estadoactividad	integer; 
        sp_numeroinspeccion	varchar; 
        sp_operadorentrega	integer; 
        sp_operadorrecibe	integer; 
        sp_idoperador		integer; 
        sp_idtipomovimiento	integer; 
        sp_idsubseccion		integer; 
        sp_tiempotrabajado	integer; 
        sp_idmotivocierre	integer; 
        sp_observacion		varchar;
        sp_idcausacierre	integer;
       
        sp_glosamotivo      varchar;
        sp_nombreaccion     varchar;
	   
BEGIN

	--	Se actualiza el registro en proceso	
    update traking.mct_movimientoordentrabajo 
       set idmotivocierre = idclosemotive,
           idcausacierre  = idclosecause,
       --    idaccion       = idaction,
       --    codigoaccion   = sp_codigoaccion,
           fechatermino   = now(),
           estadoactividad = 2 
     where idmovimientoordentrabajo = idregisterjob;
       
    --	Sacamos el codigo de la accion asociada al motivo de cierre
      select codigoaccion ,
             nombreaccion
	    into sp_codigoaccion,
	         sp_nombreaccion
	    from mct_accion 
	   where idaccion = idclosemotive;
	
	
	  if ( idclosecause = 43 ) then
	  
	          sp_glosamotivo := 'PIEZA DEFECTUOSA por '||sp_nombreaccion;
			--	Sacamos el registro anterior para insertarlo como un nuevo registro no conforme
		      select idordentrabajo, 
		             idhojaruta, 
		             codhojaruta, 
		             idparte, 
		             idmaquina, 
		             idseccion, 
		             idactividad, 
		             idaccion, 
		             --codigoaccion, 
		             estadoactividad, 
		             numeroinspeccion, 
		             operadorentrega, 
		             operadorrecibe, 
		             idoperador, 
		             idtipomovimiento, 
		             idsubseccion, 
		             tiempotrabajado, 
		             idmotivocierre, 
		             idcausacierre,
		             observacion
		        into sp_idordentrabajo, 
		             sp_idhojaruta, 
		             sp_codhojaruta, 
		             sp_idparte, 
		             sp_idmaquina, 
		             sp_idseccion, 
		             sp_idactividad, 
		             sp_idaccion, 
		             --sp_codigoaccion, 
		             sp_estadoactividad, 
		             sp_numeroinspeccion, 
		             sp_operadorentrega, 
		             sp_operadorrecibe, 
		             sp_idoperador, 
		             sp_idtipomovimiento, 
		             sp_idsubseccion, 
		             sp_tiempotrabajado, 
		             sp_idmotivocierre, 
		             sp_idcausacierre,
		             sp_observacion
		        from mct_movimientoordentrabajo 
		       where idmovimientoordentrabajo = idregisterjob;
		      
		      sp_newmov := nextval('traking.mct_movimientoordentrabajo_seq');	
		     
		     INSERT INTO traking.mct_movimientoordentrabajo
						(idmovimientoordentrabajo, 
						 idordentrabajo, 
						 idhojaruta, 
						 codhojaruta, 
						 idparte, 
						 idmaquina, 
						 idseccion, 
						 idactividad, 
						 idaccion, 
						 fechainicio, 
						 fechatermino, 
						 codigoaccion, 
						 estadoactividad, 
						 numeroinspeccion, 
						 operadorentrega, 
						 operadorrecibe, 
						 idoperador, 
						 idtipomovimiento, 
						 idsubseccion, 
						 tiempotrabajado, 
						 idmotivocierre, 
						 idcausacierre, 
						 observacion
						 )
			    values ( sp_newmov, 
			             sp_idordentrabajo, 
			             sp_idhojaruta, 
			             sp_codhojaruta, 
			             sp_idparte, 
			             sp_idmaquina, 
			             sp_idseccion, 
			             sp_idactividad, 
			             sp_idcausacierre, 
			             now(), 
