ALTER FUNCTION traking.evtupdateregisterjobcc(idregisterjob bigint, idclosemotive bigint, idclosecause bigint, idaction bigint, roadmapcodes character varying, insp bigint, checkcc boolean, description character varying, idoperatorresponsable bigint, motivoreprocc character varying, mpn bigint) OWNER TO postgres;

--
-- TOC entry 1444 (class 1255 OID 17437)
-- Name: evtupdateregisterjobmovil(bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdateregisterjobmovil(idregisterjob bigint, idclosecause bigint, numeroinspeccionup character varying, roadmapcodes character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare

	sp_glosamotivo      varchar;
	   
BEGIN

	if ( numeroinspeccionup = '0000000000') then
	
		raise notice '%', 'Entro por aca';

	    update traking.mct_movimientoordentrabajo 
	       set idcausacierre   = idclosecause,
	           idmotivocierre  = idclosecause,
	           fechatermino    = now(),
	           estadoactividad = 2 
	     where idmovimientoordentrabajo = idregisterjob;
	    
	else
	
		sp_glosamotivo := 'INSP/MPN : '||numeroinspeccionup;
	
		--	Se actualiza el registro en proceso	
	    update traking.mct_movimientoordentrabajo 
	       set idcausacierre   = idclosecause,
	           idmotivocierre  = idclosecause,
	           numeroinspeccion = numeroinspeccionup,
	           fechatermino    = now(),
	           observacion = observacion||E'\n'||sp_glosamotivo,
	           estadoactividad = 2 
	     where idmovimientoordentrabajo = idregisterjob;
    
	end if;

       

END;
$$;


