						 idoperador, 
						 idtipomovimiento, 
						 idsubseccion, 
						 tiempotrabajado, 
						 idmotivocierre, 
						 idcausacierre, 
						 observacion
						 )
			    values ( sp_newmov, 
			             sp_idordentrabajo, 
			             sp_idhojaruta, 
			             sp_codhojaruta, 
			             sp_idparte, 
			             sp_idmaquina, 
			             sp_idseccion, 
			             sp_idactividad, 
			             sp_idcausacierre, 
			             now(), 
			             now(), 
			             sp_codigoaccion, 
			             sp_estadoactividad, 
			             sp_numeroinspeccion, 
			             sp_operadorentrega, 
			             sp_operadorrecibe, 
			             sp_idoperador, 
			             sp_idtipomovimiento, 
			             sp_idsubseccion, 
			             sp_tiempotrabajado, 
			             90,
			             sp_idmotivocierre, 
			             sp_observacion||E'\n'||sp_glosamotivo
			             );
	  
	  end if;


END;
$$;


