--

CREATE FUNCTION traking.evtupdatesubedocumento(idworkorderup bigint, idevaluatorup bigint, idevaluatorentup bigint, idevaluatorrecup bigint, idprocessup bigint, idquotation bigint, idpurshase bigint, outputguide bigint, repaircost bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_estado_aut           integer;
    sp_fecha_termino        timestamp;
    sp_fecha_real_termino   timestamp;
    sp_diferencia           integer;
   	rec_progav              RECORD;
    intervalo               varchar;
    intervaloini            varchar;
    intervaloter            varchar;
    intervaloavi            varchar;

    intervalocheck          varchar;
    intervalocheckavi       varchar;      
   
    sp_nueva_fecha_inicio   timestamp;
    sp_nueva_fecha_termino  timestamp;
	sp_nueva_fecha_aviso    timestamp;


    sp_fecha_requerida      varchar;
    dias_totales            integer;
    dias_totalesaviso       integer;   
    minima_fecha            timestamp;
    maxima_fecha            timestamp;
    fecha_aviso             timestamp;   
   
    sp_estadoot             integer;
    sp_ordertype			integer;
    
    sp_idfamilia			integer;
	sp_totaldesp			bigint;
	sp_total				bigint; 

BEGIN 
	
	sp_estado_aut 	:= 0;
    sp_estadoot		:= 0;
    sp_idfamilia	:= 0;
   
    select idestadoorden ,
           idtipoorden,
           idfamilia
      into sp_estadoot,
           sp_ordertype,
           sp_idfamilia
      from mct_ordentrabajo 
     where idordentrabajo = idworkorderup;

    -- Proceso nuevo
    if idprocessup = 10 then
    	
    	update traking.mct_progavisos
		   set estado = 1,
		       fecha_real_termino = now(),
		       idusuarioinfrec = idevaluatorup
		 where idordentrabajo = idworkorderup 
		   and idsla = idprocessup;
		 
	    
		select cast(date_part('day',fecha_real_termino - fecha_termino) as integer),
		       to_date(to_char(fecha_termino,'yyyymmdd'), 'yyyymmdd'),
		       to_date(to_char(fecha_real_termino,'yyyymmdd'), 'yyyymmdd')
		  into sp_diferencia,
		       sp_fecha_termino,
		       sp_fecha_real_termino
		  from mct_progavisos 
		 where idordentrabajo = idworkorderup
		   and idsla = idprocessup;
		
		intervalo := ''''||sp_diferencia||' day';
	
		if ( sp_fecha_real_termino != sp_fecha_termino ) then	  
		
		   FOR rec_progav IN (   
					select idsla,
					       fecha_inicio + intervalo::interval as fecha_inicio,
					       date_part('dow', fecha_inicio + intervalo::interval) as diaini,
					       fecha_termino + intervalo::interval as fecha_termino,
					       date_part('dow', fecha_termino + intervalo::interval) as diater,
					       fecha_inicio_aviso + intervalo::interval as fecha_inicio_aviso,
					       date_part('dow', fecha_inicio_aviso + intervalo::interval) as diaavi
					  from mct_progavisos 
					 where idsla >= 3 and idsla not in (8,9)
					   and idordentrabajo = idworkorderup
					   and estado = 0
				  order by ordenproceso 
							)
			   loop 	
			   
			   intervaloini := '0 day';
		       intervaloter := '0 day';
		       intervaloavi := '0 day';
			   
               if (rec_progav.diaini = 6) then 
               		   intervaloini := '2 day';
               elsif (rec_progav.diaini = 0) then 
               		   intervaloini := '1 day';
               end if;

               if (rec_progav.diater = 6) then 
               		   intervaloter := '2 day';
               elsif (rec_progav.diater = 0) then 
               		   intervaloter := '1 day';
               end if;

               if (rec_progav.diaavi = 6) then 
               		   intervaloavi := '2 day';
               elsif (rec_progav.diaavi = 0) then 
               		   intervaloavi := '1 day';
               end if;             
              
			   update mct_progavisos 
			      set fecha_inicio  = rec_progav.fecha_inicio + intervaloini::interval,
			          fecha_termino = rec_progav.fecha_termino + intervaloter::interval ,
			          fecha_inicio_aviso = rec_progav.fecha_inicio_aviso + intervaloavi::interval 
			    where idsla = rec_progav.idsla
			      and idordentrabajo = idworkorderup;
			   			           
		   END LOOP;
		end if;
	    -- Cambia fechas
		  
	end if;

	if idprocessup = 3 then
	
		if sp_estadoot < 4 then
			update traking.mct_ordentrabajo 
			   set idestadoorden = 4
			 where idordentrabajo = idworkorderup;
		end if;
		
		update traking.mct_progavisos
		   set estado   = 1,
		       fecha_real_termino = now()
		 where idordentrabajo = idworkorderup 
		   and idsla = idprocessup;
		  
	    -- cambiar las fechas
	    
		select cast(date_part('day',fecha_real_termino - fecha_termino) as integer),
		       to_date(to_char(fecha_termino,'yyyymmdd'), 'yyyymmdd'),
		       to_date(to_char(fecha_real_termino,'yyyymmdd'), 'yyyymmdd')
		  into sp_diferencia,
		       sp_fecha_termino,
		       sp_fecha_real_termino
		  from mct_progavisos 
		 where idordentrabajo = idworkorderup
		   and idsla = idprocessup;
		
		intervalo := ''''||sp_diferencia||' day';
	
		if ( sp_fecha_real_termino != sp_fecha_termino ) then	  
		
		   FOR rec_progav IN (   
					select idsla,
					       fecha_inicio + intervalo::interval as fecha_inicio,
					       date_part('dow', fecha_inicio + intervalo::interval) as diaini,
					       fecha_termino + intervalo::interval as fecha_termino,
					       date_part('dow', fecha_termino + intervalo::interval) as diater,
					       fecha_inicio_aviso + intervalo::interval as fecha_inicio_aviso,
					       date_part('dow', fecha_inicio_aviso + intervalo::interval) as diaavi
					  from mct_progavisos 
					 where idsla > idprocessup and idsla not in (8,9)
					   and idordentrabajo = idworkorderup
					   and estado = 0
				  order by ordenproceso
							)
			   loop 	
			   
			   intervaloini := '0 day';
		       intervaloter := '0 day';
		       intervaloavi := '0 day';
			   
               if (rec_progav.diaini = 6) then 
               		   intervaloini := '2 day';
               elsif (rec_progav.diaini = 0) then 
               		   intervaloini := '1 day';
               end if;

               if (rec_progav.diater = 6) then 
               		   intervaloter := '2 day';
               elsif (rec_progav.diater = 0) then 
               		   intervaloter := '1 day';
               end if;

               if (rec_progav.diaavi = 6) then 
               		   intervaloavi := '2 day';
               elsif (rec_progav.diaavi = 0) then 
               		   intervaloavi := '1 day';
               end if;             
              
			   update mct_progavisos 
			      set fecha_inicio  = rec_progav.fecha_inicio + intervaloini::interval,
			          fecha_termino = rec_progav.fecha_termino + intervaloter::interval ,
			          fecha_inicio_aviso = rec_progav.fecha_inicio_aviso + intervaloavi::interval 
			    where idsla = rec_progav.idsla
			      and idordentrabajo = idworkorderup;
			   			           
		   END LOOP;
		end if;
	    -- Cambia fechas
		  
	end if;


	if idprocessup = 8 then

		if ( sp_estadoot < 9 ) then		
	
			update traking.mct_ordentrabajo 
			   set guiasaliente = outputguide,
			       idestadoorden = 8,
			       fechadespacho = now()
			 where idordentrabajo = idworkorderup;
		
		end if;
		
		update traking.mct_progavisos
		   set estado   = 1,
		       fecha_real_termino = now()
		 where idordentrabajo = idworkorderup 
		   and idsla = idprocessup;

	    -- cambiar las fechas

		if ( sp_estadoot < 9 ) then			  
		  
			select cast(date_part('day',fecha_real_termino - fecha_termino) as integer),
			       to_date(to_char(fecha_termino,'yyyymmdd'), 'yyyymmdd'),
			       to_date(to_char(fecha_real_termino,'yyyymmdd'), 'yyyymmdd')
			  into sp_diferencia,
			       sp_fecha_termino,
			       sp_fecha_real_termino
			  from mct_progavisos 
			 where idordentrabajo = idworkorderup
			   and idsla = idprocessup;
			
			intervalo := ''''||sp_diferencia||' day';
			if ( sp_fecha_real_termino != sp_fecha_termino ) then	  
			   FOR rec_progav IN (   
						select idsla,
						       fecha_inicio + intervalo::interval as fecha_inicio,
						       date_part('dow', fecha_inicio + intervalo::interval) as diaini,
						       fecha_termino + intervalo::interval as fecha_termino,
						       date_part('dow', fecha_termino + intervalo::interval) as diater,
						       fecha_inicio_aviso + intervalo::interval as fecha_inicio_aviso,
						       date_part('dow', fecha_inicio_aviso + intervalo::interval) as diaavi
						  from mct_progavisos 
						 where idsla > idprocessup and idsla not in (8,9)
						   and idordentrabajo = idworkorderup
						   and estado = 0
					  order by ordenproceso
								)
				   loop 	
				   
				   intervaloini := '0 day';
			       intervaloter := '0 day';
			       intervaloavi := '0 day';
				   
	               if (rec_progav.diaini = 6) then 
	               		   intervaloini := '2 day';
	               elsif (rec_progav.diaini = 0) then 
	               		   intervaloini := '1 day';
	               end if;
	
	               if (rec_progav.diater = 6) then 
	               		   intervaloter := '2 day';
	               elsif (rec_progav.diater = 0) then 
	               		   intervaloter := '1 day';
	               end if;
	
	               if (rec_progav.diaavi = 6) then 
	               		   intervaloavi := '2 day';
	               elsif (rec_progav.diaavi = 0) then 
	               		   intervaloavi := '1 day';
	               end if;             
	              
				   update mct_progavisos 
				      set fecha_inicio  = rec_progav.fecha_inicio + intervaloini::interval,
				          fecha_termino = rec_progav.fecha_termino + intervaloter::interval ,
				          fecha_inicio_aviso = rec_progav.fecha_inicio_aviso + intervaloavi::interval 
				    where idsla = rec_progav.idsla
				      and idordentrabajo = idworkorderup;
				   			           
			   END LOOP;
			end if;
	
		end if;	
	    -- Cambia fechas
	    		  
	end if;

END			
$$;


