--

CREATE FUNCTION traking.evtupdatetransitionotbaja(idworkorderup bigint, idevaluatorup bigint, idevaluatorentup bigint, idevaluatorrecup bigint, idprocessup bigint, idquotation bigint, idpurshase bigint, outputguide bigint, repaircost bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

    sp_estado_aut           integer;
    sp_fecha_termino        timestamp;
    sp_fecha_real_termino   timestamp;
    sp_diferencia           integer;
   	rec_progav              RECORD;
    intervalo               varchar;
    intervaloini            varchar;
    intervaloter            varchar;
    intervaloavi            varchar;

    intervalocheck          varchar;
    intervalocheckavi       varchar;      
   
    sp_nueva_fecha_inicio   timestamp;
    sp_nueva_fecha_termino  timestamp;
	sp_nueva_fecha_aviso    timestamp;


    sp_fecha_requerida      varchar;
    dias_totales            integer;
    dias_totalesaviso       integer;   
    minima_fecha            timestamp;
    maxima_fecha            timestamp;
    fecha_aviso             timestamp;   
			  
BEGIN 
	
	sp_estado_aut := 0;

	if idprocessup = 5 then
	
		update traking.mct_progavisos
		   set estado = 1,
		       fecha_real_termino = now()
		 where idordentrabajo = idworkorderup 
		   and idsla in (5,6,7);
		  
		update traking.mct_ordentrabajo 
		   set --idestadoorden = 0,
		       debaja = 1
		 where idordentrabajo = idworkorderup;
		  
	end if;


END			
$$;


