--
-- TOC entry 1129 (class 1255 OID 17450)
-- Name: evtupdatevuelveatrasdetallecalendariodiario(bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatevuelveatrasdetallecalendariodiario(idworkorders bigint, productoscharacter character varying, idusers bigint, periodos character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
    sp_fami					integer;
    sp_mec					integer;

    ultimodia				varchar;
    ano						varchar;
    anofin                  varchar;
   
    fechadesde				varchar;
    fechahasta            	varchar;
    mes						varchar;
   
    parte1					integer;
    parte2					integer;
    corte                   integer;
   
begin

	fechadesde	:= '';
    fechahasta	:= '';
    parte1		:= 0;
    parte2		:= 0;
    corte		:= 0;
   
	if (periodos != '-1') then

		select to_char(now() - interval '2 year','yyyy')
		  into ano;
		 
		select lpad(periodos, 2,'0')
		  into mes;
		 
		fechadesde	:= ano||'-'||mes||'-01';

	    select to_char(((date_trunc('month', to_date(fechadesde,'yyyy-mm-dd')) + interval '1 month') - interval '1 day')::date, 'dd')
		  into ultimodia;
		 
		select to_char(now() + interval '2 year','yyyy')
		  into anofin;
		 
		fechahasta	:= anofin||'-'||mes||'-'||ultimodia;

	    
	    update mct_ordentrabajo 
	       set fechafundicion3 = fechafundicion2 
	     where idordentrabajo >= 30000
		   and idestadoorden  >= 6 and idestadoorden < 9
		   and flagfacturacion is true
		   and (fechafundicion3 >= TO_TIMESTAMP(fechadesde||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and fechafundicion3 <= TO_TIMESTAMP(fechahasta||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
		   and debaja < 1;
		   --and checklistvalido = true;

	end if;
	 
END;
$$;


ALTER FUNCTION traking.evtupdatevuelveatrasdetallecalendariodiario(idworkorders bigint, productoscharacter character varying, idusers bigint, periodos character varying) OWNER TO postgres;

--
-- TOC entry 1095 (class 1255 OID 17451)
-- Name: evtupdatmovequeueroadmapmachine(character varying, bigint, integer); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtupdatmovequeueroadmapmachine(machine character varying, roadmap bigint, orderroadmap integer) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare

		sp_idmachine		bigint;
	    sp_maxorden         integer;
	
BEGIN
	
	    sp_maxorden := 0;
	   
		select idmaquina into sp_idmachine
		  from mct_maquina 
		 where nombremaquina = machine;
		
		if (select 1
		      from mct_colatrabajo
		     where idmaquina = sp_idmachine
		       and idhojaruta = roadmap ) then
	
		    update traking.mct_colatrabajo
		       set idmaquina = sp_idmachine,
		           orden     = orderroadmap
		     where idhojaruta = roadmap;
		      
		       
		else
		
		        insert into mct_colatrabajo 
                    (idcolatrabajo
                    ,idmaquina 
                    ,idhojaruta 
                    ,idestadocolatrabajo 
                    ,usuariocreacion 
                    ,fechacreacion
                    ,orden)
                VALUES
                    (nextval('traking.mct_colatrabajo_seq')
                    ,sp_idmachine
                    ,roadmap
                    ,1
                    ,'admin'
                    ,now()
                    ,sp_maxorden + 1);
							
                   
		end if;

END;
$$;


ALTER FUNCTION traking.evtupdatmovequeueroadmapmachine(machine character varying, roadmap bigint, orderroadmap integer) OWNER TO postgres;

