--
-- TOC entry 1106 (class 1255 OID 17454)
-- Name: evtvalidaoperadorarmadodesarme(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtvalidaoperadorarmadodesarme(idoperators bigint) RETURNS TABLE(idordentrabajo bigint, idmovimientoordentrabajo bigint, idmotivocierre bigint, idcausacierre bigint, idaccion bigint, ordenaccion character varying, producto character varying, productoordenaccion character varying, iniciaarmadodesarme boolean, rutresponsablecierratrabajo character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN

	return query
	
	select a.idordentrabajo,
           a.idmovimientoordentrabajo,
           a.idmotivocierre,
           a.idcausacierre,
           a.idaccion,
		   case
				when a.idaccion = 165 then
					 cast(a.idordentrabajo||'-ARMADO' as varchar)
                when a.idaccion = 173 then
					 cast(a.idordentrabajo||'-DESARME' as varchar)
           end as ordenaccion,
		   case 
			  when bb.idfamilia = 11 then c.nombreproducto
			  else 
                   cast(h.sigla||' '||g.nombremodelo||' '||i.nombreparam as varchar)
		   end as producto,
		   case 
			  when bb.idfamilia = 11 then 
                   case
						when a.idaccion = 165 then
					 		cast('ARMADO-'||a.idordentrabajo||'-'||c.nombreproducto as varchar)
                		when a.idaccion = 173 then
					 		cast('DESARME'||a.idordentrabajo||'-'||c.nombreproducto as varchar)
           		   end
			  else 
                   case
						when a.idaccion = 165 then
					 		cast('ARMADO-'||a.idordentrabajo||'-'||h.sigla||' '||g.nombremodelo||' '||i.nombreparam as varchar)
                		when a.idaccion = 173 then
					 		cast('DESARME'||a.idordentrabajo||'-'||h.sigla||' '||g.nombremodelo||' '||i.nombreparam as varchar)
           		   end
                   
		   end as productoordenaccion,
           a.iniciaarmadodesarme,
           a.rutresponsablecierratrabajo
	  from mct_movimientoordentrabajo a 
      left join mct_ordentrabajo bb on a.idordentrabajo = bb.idordentrabajo
	  left join mct_cliente b on bb.idcliente = b.idcliente 
	  left join mct_producto c on bb.idproducto = c.idproducto
      left join mct_modelo g on c.idmodelo = g.idmodelo
      left join mct_subfamilia h on g.idsubfamilia = h.idsubfamilia
      left join mct_etapaparam i on c.idetapaparam = i.idetapaparam 
	 where a.idoperador = idoperators
	   and a.idaccion in (165, 173)
	   and a.estadoactividad = 1;

  
 END;
$$;


ALTER FUNCTION traking.evtvalidaoperadorarmadodesarme(idoperators bigint) OWNER TO postgres;

