--
-- TOC entry 2182 (class 1255 OID 17457)
-- Name: evtvalidateordenarmadodesarme(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtvalidateordenarmadodesarme(idots bigint, tipos bigint) RETURNS TABLE(idworkorder bigint, ordertype character varying, customername character varying, productname character varying, partname character varying, tipworkname character varying, status bigint)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombretipoorden		varchar;
		sp_nombrecliente		varchar;
		sp_nombreproducto		varchar;
		sp_idordentrabajoparte	integer;	
		sp_nombreparte			varchar;
		sp_idordentrabajo		integer;
	
	    sp_modalidad            integer;
	   	sp_bloqueo              integer;

		sp_tipoproducto			bigint;
       
        sp_bloquea				bigint;
	
begin

    if (tipos = 1) then -- es armado

		select count(*)
	      into sp_bloquea
	      from mct_movimientoordentrabajo
	     where idordentrabajo = idots
	       and idaccion = 165
	       and terminoarmadodesarme = 1;

    else 

		select count(*)
	      into sp_bloquea
	      from mct_movimientoordentrabajo
	     where idordentrabajo = idots
	       and idaccion = 173
	       and terminoarmadodesarme = 1;

    end if;


	return QUERY	

	select a.idordentrabajo,
           cast(a.idtipoorden as varchar),
           b.nombrecliente,
           --a.nombreordentrabajo,
		   case 
			  when a.idfamilia = 11 then c.nombreproducto
			  else 
                   cast(h.sigla||' '||g.nombremodelo||' '||i.nombreparam as varchar)
		   end as nombreordentrabajo,
           cast(sp_bloquea as varchar),
           cast('ARMADO-DESARME' as varchar),
           a.idestadoorden
      from mct_ordentrabajo a
      left join mct_cliente b on a.idcliente = b.idcliente
	  left join mct_producto c on a.idproducto = c.idproducto
      left join mct_modelo g on c.idmodelo = g.idmodelo
      left join mct_subfamilia h on g.idsubfamilia = h.idsubfamilia
      left join mct_etapaparam i on c.idetapaparam = i.idetapaparam 
     where a.idordentrabajo = idots;

END;
$$;


ALTER FUNCTION traking.evtvalidateordenarmadodesarme(idots bigint, tipos bigint) OWNER TO postgres;

--
-- TOC entry 2109 (class 1255 OID 17458)
-- Name: evtvalidateregisterjob(bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtvalidateregisterjob(idsections bigint, idsubsections bigint, idmachines bigint, roadmapcodes character varying) RETURNS TABLE(idregisterjob bigint, idmachine bigint, idsection bigint, idsubsection bigint, idactivity bigint, idaction bigint, actioncode character varying, idactivitystatus bigint, idmovetype bigint, tiemwork bigint, startdate text, starttime text, enddate text, endtime text, description character varying, idoperator bigint, operatorname character varying, codesection character varying, idclosemotive bigint, idclosecause bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		select a.idmovimientoordentrabajo ,
		       a.idmaquina ,
		       a.idseccion,
		       a.idsubseccion ,
		       a.idactividad ,
		       a.idaccion ,
		       a.codigoaccion ,
		       a.estadoactividad ,
		       a.idtipomovimiento ,
		       coalesce(a.tiempotrabajado , null, 0),
		       --DATE_PART('minute', fechatermino::timestamp - fechainicio::timestamp),
		       to_char(a.fechainicio,'dd-mm-yyyy') ,
		       to_char(a.fechainicio,'HH24:mi:ss') ,
		       to_char(a.fechatermino,'dd-mm-yyyy') ,
		       to_char(a.fechatermino,'HH24:mi:ss') ,
		       cast('' as varchar),
		       a.idoperador ,
		       b.nombreoperador ,
		       c.codigoseccion ,
		       a.idmotivocierre ,
		       a.idcausacierre 
		from mct_movimientoordentrabajo  a,
		     mct_operador b,
		     mct_seccion c
		where a.idseccion = idsections
	      and a.idsubseccion = idsubsections
	      and a.idmaquina = idmachines
	      and a.estadoactividad = 2
	      and codhojaruta = roadmapcodes
	      and a.idoperador  = b.idoperador 
	      and a.idseccion  = c.idseccion
	      and a.idmovimientoordentrabajo = (select max(b.idmovimientoordentrabajo) 
	                                          from mct_movimientoordentrabajo b
	                                         where b.idseccion = idsections
	                                           and b.idsubseccion = idsubsections
	                                           and b.idmaquina  = idmachines
	                                           and b.estadoactividad = 2
	                                           and b.codhojaruta = roadmapcodes);

END;
$$;


ALTER FUNCTION traking.evtvalidateregisterjob(idsections bigint, idsubsections bigint, idmachines bigint, roadmapcodes character varying) OWNER TO postgres;

--
-- TOC entry 2252 (class 1255 OID 17459)
-- Name: evtvalidateregisterjobexisthr(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtvalidateregisterjobexisthr(coderoadmap character varying) RETURNS TABLE(idworkorder bigint, ordertype character varying, customername character varying, productname character varying, partname character varying, tipworkname character varying, status bigint)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombretipoorden		varchar;
		sp_nombrecliente		varchar;
		sp_nombreproducto		varchar;
		sp_idordentrabajoparte	integer;	
		sp_nombreparte			varchar;
		sp_idordentrabajo		integer;
	
	    sp_modalidad            integer;
	   	sp_bloqueo              integer;

		sp_tipoproducto			bigint;
	
begin
	
	    sp_bloqueo := 0;
	   
	    select estadobloqueo
	      into sp_bloqueo
	      from mct_movimientobloqueo mm 
	    where codhojaruta = coderoadmap;
	
		if (select distinct 1
		      from mct_hojaruta mh 
		     where codhojaruta = coderoadmap ) then
		
		
		        select idordentrabajoparte,
		               modalidad
		          into sp_idordentrabajoparte,
		               sp_modalidad
		          from mct_hojaruta mh 
		         where codhojaruta = coderoadmap;
		        

		        if (sp_modalidad = 1) then

					select b.nombrecomponente ,
					       a.idordentrabajo 
					  into sp_nombreparte,
					       sp_idordentrabajo
					  from mct_ordentrabajoparte a,
					       mct_componente b
					 where a.idordentrabajoparte = sp_idordentrabajoparte
					 and   a.idcomponente = b.idcomponente ; 	
					
					ordertype		:= 'TRANSICIÓN';
		        
		        else
		        
					select b.nombreparte,
					       a.idordentrabajo 
					  into sp_nombreparte,
					       sp_idordentrabajo
					  from mct_ordentrabajoparte a,
					       mct_parte b
					 where a.idordentrabajoparte = sp_idordentrabajoparte
					 and   a.idparte = b.idparte; 
					
					ordertype		:= 'AUTOMÁTICA';
				
		        end if;

				select idproducto 
				  into sp_tipoproducto
				  from mct_ordentrabajo 
			  	 where idordentrabajo = sp_idordentrabajo;
					
				if (sp_tipoproducto <= 17 ) then
				
					select distinct d.nombretipoorden ,
						   b.nombrecliente ,
						   c.nombreproductonepcast 
					  into sp_nombretipoorden,
					       sp_nombrecliente,
					       sp_nombreproducto	   
					  from mct_ordentrabajo a,
						   mct_cliente b,
						   mct_productonepcast c,
						   mct_tipoorden d
					 where idordentrabajo = sp_idordentrabajo
					   and a.idcliente  = b.idcliente 
					   and a.idproducto = c.idproductonepcast  
					   and a.idtipoorden = d.idtipoorden ;
					
				else
				
					select distinct d.nombretipoorden ,
						   b.nombrecliente ,
						   c.nombreproducto 
					  into sp_nombretipoorden,
				 	       sp_nombrecliente,
					       sp_nombreproducto
					  from mct_ordentrabajo a,
						   mct_cliente b,
						   mct_producto c,
						   mct_tipoorden d
					 where idordentrabajo = sp_idordentrabajo
				  	   and a.idcliente  = b.idcliente 
					   and a.idproducto = c.idproducto 
					   and a.idtipoorden = d.idtipoorden ;
					
				end if;
			
				 idworkorder	:= sp_idordentrabajo;
				 --ordertype		:= 'AUTOMÁTICA';
				 customername	:= sp_nombrecliente;
				 productname	:= sp_nombreproducto;
				 partname		:= sp_nombreparte;
				 tipworkname	:= sp_nombretipoorden;
				 status         := sp_bloqueo;
		
				 RETURN NEXT;
		
		else
		   if ( select distinct 1 
		          from mct_detallehojarutatemp 
		         where codhojaruta  = coderoadmap ) then
				
				select idproducto 
				  into sp_tipoproducto
				  from mct_ordentrabajo 
			  	 where idordentrabajo = sp_idordentrabajo;
			  	
			  	if (sp_tipoproducto <= 17 ) then
			  	
			       select a.idordentrabajo ,
					      d.nombrecomponente ,
					      e.nombrecliente ,
					      f.nombreproductonepcast  ,
					      g.nombretipoorden
					 into sp_idordentrabajo,
					      sp_nombreparte,
					      sp_nombrecliente,
					      sp_nombreproducto,
					      sp_nombretipoorden
					 from mct_hojarutatemp a,
					      mct_detallehojarutatemp b,
					      mct_ordentrabajo c,
					      mct_componente d,
					      mct_cliente e,
					      mct_productonepcast f,
					      mct_tipoorden g
				 	where b.codhojaruta    = coderoadmap
				 	and   a.idhojarutatemp = b.idhojarutatemp 
					and   a.idordentrabajo = c.idordentrabajo 
					and   a.idcomponente   = d.idcomponente 
					and   c.idcliente      = e.idcliente 
					and   c.idproducto     = f.idproductonepcast 
					and   c.idtipoorden    = g.idtipoorden ;	
				
			  	else

			       select a.idordentrabajo ,
					      d.nombrecomponente ,
					      e.nombrecliente ,
					      f.nombreproducto ,
					      g.nombretipoorden
					 into sp_idordentrabajo,
					      sp_nombreparte,
					      sp_nombrecliente,
					      sp_nombreproducto,
					      sp_nombretipoorden
					 from mct_hojarutatemp a,
					      mct_detallehojarutatemp b,
					      mct_ordentrabajo c,
					      mct_componente d,
					      mct_cliente e,
					      mct_producto f,
					      mct_tipoorden g
				 	where b.codhojaruta    = coderoadmap
				 	and   a.idhojarutatemp = b.idhojarutatemp 
					and   a.idordentrabajo = c.idordentrabajo 
					and   a.idcomponente   = d.idcomponente 
					and   c.idcliente      = e.idcliente 
					and   c.idproducto     = f.idproducto 
					and   c.idtipoorden    = g.idtipoorden ;			  	
			  	
			  	end if;
			  
		   
				idworkorder		:= sp_idordentrabajo;
			    ordertype		:= 'TRANSICIÓN';
				customername	:= sp_nombrecliente;
				productname		:= sp_nombreproducto;
				partname		:= sp_nombreparte;
				tipworkname		:= sp_nombretipoorden;
				status          := sp_bloqueo;
		
			   RETURN NEXT;
					     
		   end if;
		
		end if;

END;
$$;


ALTER FUNCTION traking.evtvalidateregisterjobexisthr(coderoadmap character varying) OWNER TO postgres;

--
-- TOC entry 2349 (class 1255 OID 17460)
-- Name: evtvalidateregisterjobexisthr_sqz(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtvalidateregisterjobexisthr_sqz(coderoadmap character varying) RETURNS TABLE(idworkorder bigint, ordertype character varying, customername character varying, productname character varying, partname character varying, tipworkname character varying, status bigint)
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombretipoorden		varchar;
		sp_nombrecliente		varchar;
		sp_nombreproducto		varchar;
		sp_idordentrabajoparte	integer;	
		sp_nombreparte			varchar;
		sp_idordentrabajo		integer;
	
	    sp_modalidad            integer;
	   	sp_bloqueo              integer;

		sp_tipoproducto			bigint;
	
begin
	
	    sp_bloqueo := 0;
	   
	    select estadobloqueo
	      into sp_bloqueo
	      from mct_movimientobloqueo mm 
	    where codhojaruta = coderoadmap;
	
		if (select distinct 1
		      from mct_hojaruta mh 
		     where codhojaruta = coderoadmap ) then
		
		
		        select idordentrabajoparte,
		               modalidad
		          into sp_idordentrabajoparte,
		               sp_modalidad
		          from mct_hojaruta mh 
		         where codhojaruta = coderoadmap;
		        

		        if (sp_modalidad = 1) then

					select b.nombrecomponente ,
					       a.idordentrabajo 
					  into sp_nombreparte,
					       sp_idordentrabajo
					  from mct_ordentrabajoparte a,
					       mct_componente b
					 where a.idordentrabajoparte = sp_idordentrabajoparte
					 and   a.idcomponente = b.idcomponente ; 	
					
					ordertype		:= 'TRANSICIÓN';
		        
		        else
		        
					select b.nombreparte,
					       a.idordentrabajo 
					  into sp_nombreparte,
					       sp_idordentrabajo
					  from mct_ordentrabajoparte a,
					       mct_parte b
					 where a.idordentrabajoparte = sp_idordentrabajoparte
					 and   a.idparte = b.idparte; 
					
					ordertype		:= 'AUTOMÁTICA';
				
		        end if;

				select idproducto 
				  into sp_tipoproducto
				  from mct_ordentrabajo 
			  	 where idordentrabajo = sp_idordentrabajo;
					
				if (sp_tipoproducto <= 17 ) then
				
					select distinct d.nombretipoorden ,
						   b.nombrecliente ,
						   c.nombreproductonepcast 
					  into sp_nombretipoorden,
					       sp_nombrecliente,
					       sp_nombreproducto	   
					  from mct_ordentrabajo a,
						   mct_cliente b,
						   mct_productonepcast c,
						   mct_tipoorden d
					 where idordentrabajo = sp_idordentrabajo
					   and a.idcliente  = b.idcliente 
					   and a.idproducto = c.idproductonepcast  
					   and a.idtipoorden = d.idtipoorden ;
					
				else
				
					select distinct d.nombretipoorden ,
						   b.nombrecliente ,
						   c.nombreproducto 
					  into sp_nombretipoorden,
				 	       sp_nombrecliente,
					       sp_nombreproducto
					  from mct_ordentrabajo a,
						   mct_cliente b,
						   mct_producto c,
						   mct_tipoorden d
					 where idordentrabajo = sp_idordentrabajo
				  	   and a.idcliente  = b.idcliente 
					   and a.idproducto = c.idproducto 
					   and a.idtipoorden = d.idtipoorden ;
					
				end if;
			
				 idworkorder	:= sp_idordentrabajo;
				 --ordertype		:= 'AUTOMÁTICA';
				 customername	:= sp_nombrecliente;
				 productname	:= sp_nombreproducto;
				 partname		:= sp_nombreparte;
				 tipworkname	:= sp_nombretipoorden;
				 status         := sp_bloqueo;
		
				 RETURN NEXT;
		
		else
		   if ( select distinct 1 
		          from mct_detallehojarutatemp 
		         where codhojaruta  = coderoadmap ) then
				
				select idproducto 
				  into sp_tipoproducto
				  from mct_ordentrabajo 
			  	 where idordentrabajo = sp_idordentrabajo;
			  	
			  	if (sp_tipoproducto <= 17 ) then
			  	
			       select a.idordentrabajo ,
					      d.nombrecomponente ,
					      e.nombrecliente ,
					      f.nombreproductonepcast  ,
					      g.nombretipoorden
					 into sp_idordentrabajo,
					      sp_nombreparte,
					      sp_nombrecliente,
					      sp_nombreproducto,
					      sp_nombretipoorden
					 from mct_hojarutatemp a,
					      mct_detallehojarutatemp b,
					      mct_ordentrabajo c,
					      mct_componente d,
					      mct_cliente e,
					      mct_productonepcast f,
					      mct_tipoorden g
				 	where b.codhojaruta    = coderoadmap
				 	and   a.idhojarutatemp = b.idhojarutatemp 
					and   a.idordentrabajo = c.idordentrabajo 
					and   a.idcomponente   = d.idcomponente 
					and   c.idcliente      = e.idcliente 
					and   c.idproducto     = f.idproductonepcast 
					and   c.idtipoorden    = g.idtipoorden ;	
				
			  	else

			       select a.idordentrabajo ,
					      d.nombrecomponente ,
					      e.nombrecliente ,
					      f.nombreproducto ,
					      g.nombretipoorden
					 into sp_idordentrabajo,
					      sp_nombreparte,
					      sp_nombrecliente,
					      sp_nombreproducto,
					      sp_nombretipoorden
					 from mct_hojarutatemp a,
					      mct_detallehojarutatemp b,
					      mct_ordentrabajo c,
					      mct_componente d,
					      mct_cliente e,
					      mct_producto f,
					      mct_tipoorden g
				 	where b.codhojaruta    = coderoadmap
				 	and   a.idhojarutatemp = b.idhojarutatemp 
					and   a.idordentrabajo = c.idordentrabajo 
					and   a.idcomponente   = d.idcomponente 
					and   c.idcliente      = e.idcliente 
					and   c.idproducto     = f.idproducto 
					and   c.idtipoorden    = g.idtipoorden ;			  	
			  	
			  	end if;
			  
		   
				idworkorder		:= sp_idordentrabajo;
			    ordertype		:= 'TRANSICIÓN';
				customername	:= sp_nombrecliente;
				productname		:= sp_nombreproducto;
				partname		:= sp_nombreparte;
				tipworkname		:= sp_nombretipoorden;
				status          := sp_bloqueo;
		
			   RETURN NEXT;
					     
		   end if;
		
		end if;

END;
$$;


ALTER FUNCTION traking.evtvalidateregisterjobexisthr_sqz(coderoadmap character varying) OWNER TO postgres;

--
-- TOC entry 1133 (class 1255 OID 17461)
-- Name: evtvalidateregisterjoblcc(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.evtvalidateregisterjoblcc(roadmapcodes character varying) RETURNS TABLE(validation character varying, idoperator bigint, operatorname character varying, idsection bigint, codesection character varying, idmachine bigint, machinename character varying, startdate text, starttime text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		-- esto es si la hoja de ruta esta en proceso en otra seccion o en otra maquina
		select cast('LCC' as varchar),
		       a.idoperador ,
			   b.nombreoperador ,
		       a.idseccion ,
		       cast('NA' as varchar),
		       a.idmaquina ,
		       cast('NA' as varchar),
		       to_char(a.fechainicio, 'dd-mm-yyyy'),
		       to_char(a.fechainicio, 'HH24:mi:ss')
		from mct_movimientoordentrabajo a,
		     mct_operador b
		where a.codhojaruta = roadmapcodes
		and a.estadoactividad = 2
		and a.codigoaccion = 'L_CC'
		and b.idoperador = a.idoperador ;

END;
$$;


