CREATE FUNCTION traking.evtvalidateroadmap(coderoadmap character varying, actioncodes character varying) RETURNS TABLE(quantity bigint, actioncode character varying)
    LANGUAGE plpgsql
    AS $$
declare

		sp_cantidad		integer;
		sp_accion		varchar;

	
begin
	
		if (select 1
		      from mct_movimientoordentrabajo 
		     where codhojaruta = coderoadmap
		       and codigoaccion = actioncodes ) then
		      
