--
-- TOC entry 1311 (class 1255 OID 17466)
-- Name: fecha(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.fecha(dia bigint) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
declare 
   
    intervalo    varchar;
    sp_fecha     timestamp;
    indice       integer;
    dias_totales integer;
    dia_inicial  integer;
    
   
begin 
	
	indice       := 1;
    dias_totales := 0;

    select date_part('dow', now()) into dia_inicial;
   
   
    WHILE indice <= dia
    
        LOOP

            if ( dia_inicial < 6 ) then
               dias_totales := dias_totales + 1;
               dia_inicial  := dia_inicial + 1;
               indice       := indice + 1;
            else
               dia_inicial  := 1;
               dias_totales := dias_totales + 2;
                          --   indice       := indice + 1;
            end if;

        END LOOP;
	
                   
       if ( dia_inicial = 6 ) then
                      dias_totales := dias_totales + 2;
                     
       end if;
      
	intervalo := ''''||dias_totales||' day';
	
	select now() + intervalo::interval into sp_fecha;

    return sp_fecha;
	
END
$$;


ALTER FUNCTION traking.fecha(dia bigint) OWNER TO postgres;

