-- Name: findclientecom(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.findclientecom(idclientecoms bigint) RETURNS TABLE(idclientecom bigint, nombreclientecom character varying, idareainteres bigint, nombreareainteres character varying, idparquebomba bigint, nombreparquebomba character varying, idtipoclientecom bigint, nombretipoclientecom character varying, status integer, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

        SELECT traking.mct_clientecom.idclientecom, 
               traking.mct_clientecom.nombreclientecom, 
               traking.mct_clientecom.idareainteres, 
               traking.mct_clientecom.nombreareainteres, 
               traking.mct_clientecom.idparquebomba,              
               traking.mct_clientecom.nombreparquebomba,              
               traking.mct_clientecom.idtipoclientecom, 
               traking.mct_tipoclientecom.nombretipoclientecom,
               traking.mct_clientecom.estado,
		       case 
				   when traking.mct_clientecom.estado = 1 then
				        cast('Activo' as varchar)
				   else 
				        cast('Inactivo' as varchar)
			   end as nombrestado,
               traking.mct_clientecom.fechacreacion,
               traking.mct_clientecom.usuariocreacion,
               traking.mct_clientecom.fechamodificacion,
               traking.mct_clientecom.usuariomodificacion
        FROM traking.mct_clientecom, 
             traking.mct_tipoclientecom
       where traking.mct_clientecom.idclientecom = idclientecoms
         and traking.mct_clientecom.idtipoclientecom = traking.mct_tipoclientecom.idtipoclientecom
    order by traking.mct_clientecom.nombreclientecom asc,
             traking.mct_clientecom.usuariocreacion asc;

END;
$$;


ALTER FUNCTION traking.findclientecom(idclientecoms bigint) OWNER TO postgres;

