--

CREATE FUNCTION traking.findmachine(idmachines bigint) RETURNS TABLE(idsubsection bigint, subsectionname character varying, idmachine bigint, namemachine character varying, codemachine character varying, codenew character varying, codelcd character varying, status integer, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying, qrcodigo character varying, idseccion bigint, nombreseccion character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_maquina.idsubseccion, 
               traking.mct_subseccion.nombresubseccion,
               traking.mct_maquina.idmaquina, 
               traking.mct_maquina.nombremaquina, 
               traking.mct_maquina.codigomaquina,
               traking.mct_maquina.codigonuevo,
               traking.mct_maquina.codigolcd,
               traking.mct_maquina.estado,
               traking.mct_estado.nombreestado,
               traking.mct_maquina.fechacreacion,
               traking.mct_maquina.usuariocreacion,
               traking.mct_maquina.fechamodificacion,
               traking.mct_maquina.usuariomodificacion,
               traking.mct_maquina.qrcodigo,
               traking.mct_seccionmaquina.idseccion,
               traking.mct_seccion.nombreseccion
          FROM traking.mct_maquina 
          left join traking.mct_estado      on traking.mct_maquina.estado=traking.mct_estado.idestado
          left join traking.mct_subseccion  on traking.mct_maquina.idsubseccion=traking.mct_subseccion.idsubseccion
          left join traking.mct_seccionmaquina on traking.mct_seccionmaquina.idmaquina = traking.mct_maquina.idmaquina
          left join traking.mct_seccion        on traking.mct_seccion.idseccion = traking.mct_seccionmaquina.idseccion
         WHERE traking.mct_maquina.idmaquina = idmachines;

END;
$$;


ALTER FUNCTION traking.findmachine(idmachines bigint) OWNER TO postgres;

