--
-- TOC entry 1770 (class 1255 OID 17505)
-- Name: findoperatorbyrut(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.findoperatorbyrut(ruts character varying) RETURNS TABLE(idprofile bigint, profilename character varying, idoperator bigint, nameoperator character varying, status bigint, statusname character varying, rut character varying, idmachine bigint, namemachine character varying, movilizacionpropia boolean, direccion character varying, idsector bigint, nombresector character varying, telefonocontacto bigint, aplicacontrolturno boolean, aplicacontrolturnofund boolean, aplicacontrolturnofund2 boolean, idseccionprincipal bigint, nombreseccionprincipal character varying, idcargo bigint, nombrecargo character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_operador.idperfil,
               traking.mct_perfil.nombreperfil,
               traking.mct_operador.idoperador,
               traking.mct_operador.nombreoperador,
               traking.mct_operador.estado,
               traking.mct_estado.nombreestado,
			   cast(coalesce(traking.mct_operador.rut||'-'||traking.mct_operador.digito ,'SINRUT') as varchar) ,
			   traking.mct_operador.idmaquina,
			   coalesce((SELECT traking.mct_maquina.nombremaquina 
						   FROM traking.mct_maquina WHERE traking.mct_operador.idmaquina = traking.mct_maquina.idmaquina),'SINMACH'),     
	           traking.mct_operador.movilizacionpropia ,
	           traking.mct_operador.direccion ,
	           traking.mct_operador.idsector ,
	           traking.mct_sector.nombresector ,
	           traking.mct_operador.telefonocontacto ,
	           traking.mct_operador.aplicacontrolturno ,
	           traking.mct_operador.aplicacontrolturnofund ,
	           traking.mct_operador.aplicacontrolturnofund2  ,
	           traking.mct_operador.idseccionprincipal,
	           traking.mct_seccion.nombreseccion ,	
	           
	           traking.mct_operador.idcargo,
	           traking.mct_cargo.nombrecargo ,	
	           
               traking.mct_operador.fechacreacion,
               traking.mct_operador.usuariocreacion,
               traking.mct_operador.fechamodificacion,
               traking.mct_operador.usuariomodificacion
          FROM traking.mct_operador 
          left join traking.mct_estado   on traking.mct_operador.estado   = traking.mct_estado.idestado
          left join traking.mct_perfil   on traking.mct_operador.idperfil = traking.mct_perfil.idperfil
          left join traking.mct_sector   on traking.mct_operador.idsector = traking.mct_sector.idsector 
          left join traking.mct_seccion  on traking.mct_operador.idseccionprincipal = traking.mct_seccion.idseccion 
          left join traking.mct_cargo    on traking.mct_operador.idcargo = traking.mct_cargo.idcargo
         WHERE traking.mct_operador.rut=ruts
           and traking.mct_operador.estado = 1;

END;
$$;


ALTER FUNCTION traking.findoperatorbyrut(ruts character varying) OWNER TO postgres;

