--
-- TOC entry 1998 (class 1255 OID 17508)
-- Name: findoperatorsection(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.findoperatorsection(idsections bigint) RETURNS TABLE(idprofile bigint, profilename character varying, idoperator bigint, nameoperator character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		select b.idperfil,
		       c.nombreperfil, 
		       b.idoperador, 
		       b.nombreoperador, 
		       b.estado,
		       d.nombreestado,
		       b.fechacreacion,
		       b.usuariocreacion,
		       b.fechamodificacion, 
		       b.usuariomodificacion
		  from mct_operadorseccion a,
		       mct_operador b,
		       mct_perfil c,
		       mct_estado d
		 where a.idseccion = idsections
		   and b.idperfil  = c.idperfil
		   and b.estado    = d.idestado;

END;
$$;


ALTER FUNCTION traking.findoperatorsection(idsections bigint) OWNER TO postgres;

