               traking.mct_proveedorparte.idproveedorparte,
               traking.mct_proveedorparte.idproveedor,
               traking.mct_proveedorparte.idparte,
               traking.mct_proveedorparte.costo
        FROM traking.mct_proveedorparte, traking.mct_parte
        WHERE traking.mct_proveedorparte.idproveedor=idproviderf
          and traking.mct_parte.idparte=traking.mct_proveedorparte.idparte;

END;
$$;


