--
-- TOC entry 1376 (class 1255 OID 17533)
-- Name: findquotation(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.findquotation(idquotations bigint) RETURNS TABLE(idquotation bigint, namequotation character varying, idcustomer bigint, namecustomer character varying, idproduct bigint, nameproduct character varying, idordertype bigint, nameordertype character varying, idworkorder bigint, amountnet bigint, iva bigint, total bigint, discount bigint, observation character varying, deliveryday bigint, idtransport bigint, idpaycondition bigint, status bigint, namestatus character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_cotizacion.idcotizacion, 
               traking.mct_cotizacion.nombrecotizacion,                 
               traking.mct_cotizacion.idcliente, 
               traking.mct_cliente.nombrecliente,               
               traking.mct_cotizacion.idproducto, 
               traking.mct_producto.nombreproducto,               
               traking.mct_cotizacion.idtipoorden, 
               traking.mct_tipoorden.nombretipoorden,               
               traking.mct_cotizacion.idordentrabajo, 
               traking.mct_cotizacion.montoneto,
               traking.mct_cotizacion.iva,
               traking.mct_cotizacion.total,
               traking.mct_cotizacion.descuento,               
               traking.mct_cotizacion.observacion,
               traking.mct_cotizacion.diasentrega ,   
               traking.mct_cotizacion.idtransporte ,   
               traking.mct_cotizacion.idcondicionpago ,   
               traking.mct_cotizacion.estado,
               traking.mct_estado.nombreestado,  
               traking.mct_cotizacion.fechacreacion,
               traking.mct_cotizacion.usuariocreacion,
               traking.mct_cotizacion.fechamodificacion,
               traking.mct_cotizacion.usuariomodificacion
        FROM traking.mct_cotizacion, 
             traking.mct_cliente,
             traking.mct_producto,
             traking.mct_estado,
             traking.mct_tipoorden
       where traking.mct_cotizacion.idcotizacion=idquotations
         and traking.mct_cotizacion.estado=traking.mct_estado.idestado
         and traking.mct_cotizacion.idcliente=traking.mct_cliente.idcliente
         and traking.mct_cotizacion.idproducto=traking.mct_producto.idproducto
         and traking.mct_cotizacion.idtipoorden=traking.mct_tipoorden.idtipoorden;

END;
$$;


ALTER FUNCTION traking.findquotation(idquotations bigint) OWNER TO postgres;

