               traking.mct_usuario.rut,
               traking.mct_usuario.nombre,
               traking.mct_usuario.email,
               traking.mct_usuario.idcliente ,
               traking.mct_cliente.nombrecliente ,
               traking.mct_usuario.fechacreacion,
               traking.mct_usuario.usuariocreacion,
               traking.mct_usuario.fechamodificacion,
               traking.mct_usuario.usuariomodificacion
        FROM traking.mct_usuario 
        left join traking.mct_estado  on traking.mct_usuario.estado    = traking.mct_estado.idestado
        left join traking.mct_perfil  on traking.mct_usuario.idperfil  = traking.mct_perfil.idperfil
        left join traking.mct_cliente on traking.mct_usuario.idcliente = traking.mct_cliente.idcliente 
    WHERE traking.mct_usuario.idusuario=idusers;

END;
$$;


