-- Name: findviewproduct(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.findviewproduct(idproducts bigint) RETURNS TABLE(idproduct bigint, productname character varying, manufacturername character varying, modelname character varying, customername character varying, statusname character varying, flowval bigint, rpmval bigint, lengthval bigint, heightval bigint, powerval bigint, phaseparam character varying, generalplan character varying, materialname character varying, totalcost bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_producto.idproducto, 
               traking.mct_producto.nombreproducto,                   
               traking.mct_fabricante.nombrefabricante,
               traking.mct_modelo.nombremodelo,
               traking.mct_cliente.nombrecliente,
               traking.mct_estado.nombreestado, 
               traking.mct_producto.caudal,
               traking.mct_producto.rpm,
               traking.mct_producto.largo,
               traking.mct_producto.altura,
               traking.mct_producto.potencia,
               traking.mct_etapaparam.nombreparam,
               traking.mct_producto.planogeneral,
               traking.mct_material.nombrematerial,
               sum(traking.mct_parte.costofabricacion)
        FROM traking.mct_producto, 
             traking.mct_estado,
             traking.mct_modelo,
             traking.mct_cliente,
             traking.mct_fabricante,
             traking.mct_etapaparam,
             traking.mct_material,
             traking.mct_productoparte,
             traking.mct_parte
       where traking.mct_producto.idproducto = idproducts
         and traking.mct_producto.estado=traking.mct_estado.idestado
         and traking.mct_producto.idmodelo=traking.mct_modelo.idmodelo
         and traking.mct_producto.idcliente=traking.mct_cliente.idcliente
         and traking.mct_producto.idfabricante=traking.mct_fabricante.idfabricante
         and traking.mct_producto.idetapaparam=traking.mct_etapaparam.idetapaparam
         and traking.mct_producto.idmaterial = traking.mct_material.idmaterial
         and traking.mct_productoparte.idproducto = traking.mct_producto.idproducto
         and traking.mct_parte.idparte = traking.mct_productoparte.idparte 
        group by traking.mct_producto.idproducto, 
               traking.mct_producto.nombreproducto,                   
               traking.mct_fabricante.nombrefabricante, 
               traking.mct_modelo.nombremodelo, 
               traking.mct_cliente.nombrecliente,
               traking.mct_estado.nombreestado, 
               traking.mct_producto.caudal,
               traking.mct_producto.rpm,
               traking.mct_producto.largo,
               traking.mct_producto.altura,
               traking.mct_producto.potencia,
               traking.mct_etapaparam.nombreparam,
               traking.mct_producto.planogeneral,
               traking.mct_material.nombrematerial;
        
END;
$$;


ALTER FUNCTION traking.findviewproduct(idproducts bigint) OWNER TO postgres;

--
-- TOC entry 1230 (class 1255 OID 17551)
-- Name: findworkorder(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.findworkorder(idworkorders bigint) RETURNS TABLE(idworkorder bigint, workordername character varying, idcustomer bigint, customername character varying, quotation bigint, idordertype bigint, ordertypename character varying, idproduct bigint, productname character varying, purshaseorder bigint, receptiondate timestamp without time zone, deliverydate timestamp without time zone, requestdate timestamp without time zone, orderstatus bigint, iduser bigint, name character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_ordentrabajo.idordentrabajo, 
               traking.mct_ordentrabajo.nombreordentrabajo,                    
               traking.mct_ordentrabajo.idcliente, 
               traking.mct_cliente.nombrecliente,
               traking.mct_ordentrabajo.idcotizacion,
               traking.mct_ordentrabajo.idtipoorden, 
               traking.mct_tipoorden.nombretipoorden,
               traking.mct_ordentrabajo.idproducto, 
               traking.mct_producto.nombreproducto,
               traking.mct_ordentrabajo.ordencompra,
               traking.mct_ordentrabajo.fecharecepcion,
               traking.mct_ordentrabajo.fechaentrega,
               traking.mct_ordentrabajo.fechasolicitudentrega,
               traking.mct_ordentrabajo.idestadoorden,
               traking.mct_ordentrabajo.idusuario,
               traking.mct_usuario.nombre,
               traking.mct_ordentrabajo.idestadoorden,
               traking.mct_estado.nombreestado,  
               traking.mct_ordentrabajo.fechacreacion,
               traking.mct_ordentrabajo.usuariocreacion,
               traking.mct_ordentrabajo.fechamodificacion,
               traking.mct_ordentrabajo.usuariomodificacion
          FROM traking.mct_ordentrabajo, 
               traking.mct_cliente,
               traking.mct_tipoorden,
               traking.mct_producto,
               traking.mct_estado,
               traking.mct_usuario
         where traking.mct_ordentrabajo.idordentrabajo=idworkorders
           and traking.mct_ordentrabajo.idestadoorden=traking.mct_estado.idestado
           and traking.mct_ordentrabajo.idcliente=traking.mct_cliente.idcliente
           and traking.mct_ordentrabajo.idtipoorden=traking.mct_tipoorden.idtipoorden
           and traking.mct_ordentrabajo.idproducto=traking.mct_producto.idproducto
           and traking.mct_ordentrabajo.idusuario=traking.mct_usuario.idusuario;

