CREATE FUNCTION traking.fn_soporte_actualizacantidad_ot_repuesto(p_idordentrabajorepuesto bigint, p_cantidad bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_rows INTEGER;
BEGIN
    UPDATE traking.mct_ordentrabajorepuesto
       SET cantidad = p_cantidad
     WHERE idordentrabajorepuesto = p_idordentrabajorepuesto;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows > 0 THEN
        RETURN 'Éxito: se actualizó correctamente el detalle repuesto con id ' || p_idordentrabajorepuesto;
    ELSE
        RETURN 'Error: no existe el detalle repuesto con id ' || p_idordentrabajorepuesto;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


