--
-- TOC entry 2317 (class 1255 OID 17553)
-- Name: fn_soporte_actualizaequipocirculante(text, text, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.fn_soporte_actualizaequipocirculante(p_desde text, p_hasta text, p_equipos bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_rows INTEGER;
BEGIN
    UPDATE traking.mct_equiposcirculantes
       SET numerodeequipos = p_equipos
     WHERE fechadesde >= TO_DATE(p_desde, 'DD-MM-YYYY')
       AND fechadesde <= TO_DATE(p_hasta, 'DD-MM-YYYY');

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows > 0 THEN
        RETURN 'Éxito: se actualizaron ' || v_rows || ' Periodo(s) correctamente';
    ELSE
        RETURN 'Error: no existen Periodo(s) entre las fechas ' || p_desde || ' y ' || p_hasta;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


ALTER FUNCTION traking.fn_soporte_actualizaequipocirculante(p_desde text, p_hasta text, p_equipos bigint) OWNER TO postgres;

