--
-- TOC entry 1659 (class 1255 OID 17569)
-- Name: fn_soporte_eliminaot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.fn_soporte_eliminaot(ots bigint) RETURNS TABLE(ok boolean, mensaje text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_count_ot INTEGER := 0;
    v_rows INTEGER := 0;
    v_total INTEGER := 0;
BEGIN
-- No usar porque si elimina la ultima OT queda desafazada la secuencia
    IF NOT EXISTS (
        SELECT 1
        FROM traking.mct_ordentrabajo
        WHERE idordentrabajo = ots
    ) THEN
        RETURN QUERY
        SELECT FALSE, 'Error: no existe la OT ' || ots;
        RETURN;
    END IF;

    DELETE FROM traking.mct_checklistinftec
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_checklistinftecvalido
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_checklistinftecrecept
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_hojarutatemp
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_detallehojarutatemp
    WHERE codhojaruta LIKE '%' || ots || '%';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_hojaruta
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_ordentrabajorepuesto
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_ordentrabajoparte
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_progavisos
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_infcotipdf
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_total := v_total + v_rows;

    DELETE FROM traking.mct_ordentrabajo
    WHERE idordentrabajo = ots;
    GET DIAGNOSTICS v_count_ot = ROW_COUNT;
    v_total := v_total + v_count_ot;

    IF v_count_ot > 0 THEN
        RETURN QUERY
        SELECT TRUE, 'Éxito: OT ' || ots || ' eliminada correctamente. Total registros eliminados: ' || v_total;
    ELSE
        RETURN QUERY
        SELECT FALSE, 'Error: no se pudo eliminar la OT ' || ots;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN QUERY
        SELECT FALSE, 'Error al eliminar la OT ' || ots || ': ' || SQLERRM;
END;
$$;


ALTER FUNCTION traking.fn_soporte_eliminaot(ots bigint) OWNER TO postgres;

--
-- TOC entry 1003 (class 1255 OID 17570)
-- Name: fn_soporte_habilitaotdespachotablet(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.fn_soporte_habilitaotdespachotablet(p_ots bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_estadoorden INTEGER;
BEGIN
    -- Buscar estado actual de la OT
    SELECT idestadoorden
      INTO v_estadoorden
      FROM traking.mct_ordentrabajo
     WHERE idordentrabajo = p_ots;

    -- Validar si existe la OT
    IF NOT FOUND THEN
        RETURN 'Error: no existe la OT ' || p_ots;
    END IF;

    -- Validar si ya fue despachada
    IF v_estadoorden >= 9 THEN
        RETURN 'Error: la OT ' || p_ots || ' ya fue despachada';
    END IF;

    -- Actualizar estado
    UPDATE traking.mct_ordentrabajo
       SET idestadoorden = 7
     WHERE idordentrabajo = p_ots;

    IF FOUND THEN
        RETURN 'Éxito: OT ' || p_ots || ' actualizada correctamente a estado 7';
    ELSE
        RETURN 'Error: no se pudo actualizar la OT ' || p_ots;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


ALTER FUNCTION traking.fn_soporte_habilitaotdespachotablet(p_ots bigint) OWNER TO postgres;

