CREATE FUNCTION traking.hojarutabyid(codhojarutai character varying) RETURNS TABLE(nombreplano character varying, idoperador bigint, nombreoperador character varying, idordentrabajo bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
	RETURN QUERY
	SELECT b.nombreplano,		 
		   b.idtrabajohr,
		   c.nombreoperador,
		   b.idordentrabajo
	  FROM traking.mct_hojaruta a
	left join traking.mct_hojarutatemp b on ( b.idhojarutatemp = a.idhojarutatemp )
	left join traking.mct_operador c on ( c.idoperador = b.idtrabajohr )
     where a.codhojaruta = codhojarutai;
END;
$$;


