-- Name: horashextras(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.horashextras(inoperador bigint, infechadesde character varying, infechahasta character varying) RETURNS TABLE(salidoperadorturno bigint, salidoperador bigint, salnombreoperador character varying, salfechaturno character varying, salhe numeric, salobservacion character varying, salfundicion integer)
    LANGUAGE plpgsql
    AS $$
declare 

    var_record1 			record;
	sp_desctmp				varchar(500);
    listoperador integer[] = 
    (SELECT ARRAY (SELECT  a.idoperador from traking.mct_operador a));
    sp_horaminuto			varchar;
   	sp_aplicaturnofund		boolean;
	sp_horanticipadadh		varchar := '07:30';
	sp_horanticipadasabado	varchar := '07:30';
	sp_horanticipadafestivo	varchar := '07:00';
	sp_horasalidanoche		varchar := '18:30';
	sp_salidanormaldf		varchar := '13:30';
	sp_salidanormaldh		varchar := '07:30';
	sp_finturno				varchar := '13:30';
	sp_ingresodf			varchar := '08:30';
	sp_ingresosabado		varchar := '08:30';
	sp_ingresodiahabil		varchar := '08:30';
	sp_finturnosabado		varchar := '12:30';
	sp_finturnohabil		varchar := '18:30';

    sp_turno13 				varchar := '13:00';
    sp_turno16 				varchar := '16:00';
    sp_turno18				varchar := '18:00';
    sp_turno20 				varchar := '20:00';
   	sp_turno2130 			varchar := '21:30';
     				
	sp_tipodia				integer;
	sp_cont					integer;
	sp_he					numeric := 0.0;
	sp_hetmp				numeric := 0.0;
	sp_flagbool				boolean;
begin
	
	 FOR var_record1 IN
		( 

			select * from  traking.mct_operador a
			      left join  traking.mct_operadorturnofund b on ( a.idoperador = b.idoperador )
			where    
			  (b.fechaturno between to_date(infechadesde,'yyyy-mm-dd') and  to_date(infechahasta,'yyyy-mm-dd') ) 
			--and a.idoperador = inoperador
			order by b.fechaturno

		)
	 loop
		   sp_he 		:= 0.0;
		  	sp_hetmp 	:= 0.0;
		   --0: Domingo
		   --6: Sabado
		   --1-5: Habil
		   select extract (DOW from  var_record1.fechaturno ) into sp_tipodia;
		   select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = var_record1.fechaturno;
		   if ( sp_cont >= 1) then 
		        -- Los festivos los hago pasar por Domingo
		  		sp_tipodia := 0;
		   end if;
		   raise notice '% % - % % % % % - % % % - % % - % %', 
		   		var_record1.fechaturno,
		   		var_record1.idoperador,
		 		var_record1.turno13,
		 		var_record1.turno16,
				var_record1.turno18,
				var_record1.turno20,
				var_record1.turno2130, 
				var_record1.turnonoche,
				var_record1.ingresoanticipado,
				var_record1.turnootro,
				sp_tipodia, 
				sp_cont,
				var_record1.esturnofundicion1,
				var_record1.esturnofundicion2;

			salidoperadorturno      :=  var_record1.idoperadorturnofund;
			salidoperador 			:= var_record1.idoperador;
			salnombreoperador 		:= var_record1.nombreoperador;
			salfechaturno 			:= var_record1.fechaturno;
			salhe					:= 0.0;
		    case
     				 when  var_record1.esturnofundicion1 		then salfundicion := 1;
     				 when  var_record1.esturnofundicion2 		then salfundicion := 2;
     				else salfundicion = 0;
     		end case;
		
			 -- Festivo o Domingo
			if ( sp_tipodia = 0 ) then 
				if (  var_record1.ingresoanticipado ) then 
					select c.nombrehoraminuto, c.aplicaturnofund  into sp_horaminuto, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutoingant;
					select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_ingresodf AS TIME) - CAST(sp_horaminuto AS TIME) as Tiempo) T;
       				sp_he :=  sp_hetmp + sp_he;
       		    	salobservacion := concat(to_char(var_record1.fechaturno,'dd-mm-yyyy'),' DomingoFestivo IA : ',sp_horaminuto,' IA : ', sp_ingresodf,'    HE: ',sp_he);
       		    	salhe := sp_he;
		   			return next;	
		    	end if;
		    
		    	-- Determino horario de salida
		    	sp_flagbool := true;
		       case
     				 when  var_record1.turno13 		then sp_finturno := sp_turno13;
     				 when  var_record1.turno16 		then sp_finturno := sp_turno16;
     				 when  var_record1.turno18 		then sp_finturno := sp_turno18;
     				 when  var_record1.turno20 		then sp_finturno := sp_turno20;
     				 when  var_record1.turno2130 	then sp_finturno := sp_turno2130;
     				 when  var_record1.turnootro 	then select c.nombrehoraminuto, c.aplicaturnofund  into sp_horaminuto, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutootro;
     				else sp_flagbool = false;
     			end case;
     			-- Valicacion que tenga un turno asignado
				if ( sp_flagbool ) then
					select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_ingresodf AS TIME) as Tiempo) T;
       				sp_he :=  sp_he + sp_hetmp;
       		    	salobservacion := concat(to_char(var_record1.fechaturno,'dd-mm-yyyy'),' DomingoFestivo IT : ',sp_ingresodf,' FT: ',sp_finturno,'  HE: ',sp_hetmp);
       		   		salhe := sp_hetmp;
		   			return next;
				end if;   
			
			end if;
		
			-- Sabados
			if ( sp_tipodia = 6 ) then 
				-- Validacion si entra anticipado
				if (  var_record1.ingresoanticipado ) then 
					select c.nombrehoraminuto, c.aplicaturnofund  into sp_horaminuto, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutoingant;
					select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_horanticipadasabado AS TIME) - CAST(sp_horaminuto AS TIME) as Tiempo) T;
       				sp_he :=  sp_he + sp_hetmp;
       		    	salobservacion := concat(to_char(var_record1.fechaturno,'dd-mm-yyyy'),' Sabado      IA :  ',sp_horaminuto,' FT ',sp_horanticipadasabado,'  HE',sp_hetmp);
       		    	salhe := sp_he;
		   			return next;	
		    	end if;
		    
		    	-- Determino horario de salida
		    	sp_flagbool := true;
		       case
     				 when  var_record1.turno13 		then sp_finturno := sp_turno13;
     				 when  var_record1.turno16 		then sp_finturno := sp_turno16;
     				 when  var_record1.turno18 		then sp_finturno := sp_turno18;
     				 when  var_record1.turno20 		then sp_finturno := sp_turno20;
     				 when  var_record1.turno2130 	then sp_finturno := sp_turno2130;
     				 when  var_record1.turnootro 	then select c.nombrehoraminuto, c.aplicaturnofund  into sp_finturno, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutootro;
     				else sp_flagbool = false;
     			end case;
     		
     			-- Calculo del exceso entre la hora normal de salida y el turno q cumplido
				if ( sp_flagbool ) then
					select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_finturnosabado AS TIME) as Tiempo) T;
       				sp_he :=  sp_he + sp_hetmp;
       		    	salobservacion := concat(to_char(var_record1.fechaturno,'dd-mm-yyyy'),' Sabado      SL : ',sp_finturnosabado,'  FT : ',sp_finturno,'  HE: ',sp_hetmp);
       		   		salhe := sp_he;
		   			return next;
				end if;  
     		
			end if;
		
			if ( sp_tipodia >= 1 and  sp_tipodia <= 5) then 
			
				-- Validacion si entra anticipado
				if (  var_record1.ingresoanticipado ) then 
					select c.nombrehoraminuto, c.aplicaturnofund  into sp_horaminuto, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutoingant;
					select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_horanticipadadh AS TIME) - CAST(sp_horaminuto AS TIME) as Tiempo) T;
       				sp_he :=  sp_he + sp_hetmp;
       		    	salobservacion := concat(to_char(var_record1.fechaturno,'dd-mm-yyyy'),' Dia habil IA : ',sp_horaminuto,'  IngNormal : ',sp_horanticipadadh);
       		    	salhe := sp_he;
		   			return next;	
		    	end if;
		    
		    		    	-- Determino horario de salida
		    	sp_flagbool := true;
		       case
     				-- when  var_record1.turno13 		then sp_finturno := sp_turno13;
     				-- when  var_record1.turno16 		then sp_finturno := sp_turno16;
     				 when  var_record1.turno18 		then sp_finturno := sp_turno18;
     				 when  var_record1.turno20 		then sp_finturno := sp_turno20;
     				 when  var_record1.turno2130 	then sp_finturno := sp_turno2130;
     				 when  var_record1.turnootro 	then select c.nombrehoraminuto, c.aplicaturnofund  into sp_finturno, sp_aplicaturnofund from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutootro;
     				else sp_flagbool = false;
     			end case;
     		     -- Calculo del exceso entre la hora normal de salida y el turno cumplido
				if ( sp_flagbool ) then
					raise notice '----- % %',sp_finturno,sp_salidanormaldh;
					if ( var_record1.turnootro ) then
							select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_ingresodiahabil AS TIME) as Tiempo) T;
       						salobservacion := concat('*',to_char(var_record1.fechaturno,'dd-mm-yyyy'),' Dia habil   FT ',sp_finturno,'  EL : ',sp_ingresodiahabil, '  HE: ',sp_hetmp);
       			    else
       			    		select extract(hour from T.Tiempo) +  (extract(minute from T.Tiempo) / 60) + (extract(seconds from T.Tiempo) / 3600) into sp_hetmp
       						from (select CAST(sp_finturno AS TIME) - CAST(sp_salidanormaldh AS TIME) as Tiempo) T;
       						salobservacion := concat(to_char(var_record1.fechaturno,'dd-mm-yyyy'),' Dia habil   FT ',sp_finturno,'  SL : ',sp_salidanormaldh, '  HE: ',sp_hetmp);
       				end if;
       					
       				sp_he :=  sp_hetmp;
       		    	
       		    	salhe := sp_he;
		   			return next;
				end if;  
			
			end if;
		--salentradanticipadahe := sp_he;
		--return next;
		
	END LOOP; 
return;
   
END
$$;


ALTER FUNCTION traking.horashextras(inoperador bigint, infechadesde character varying, infechahasta character varying) OWNER TO postgres;

--
-- TOC entry 1861 (class 1255 OID 17575)
-- Name: horashextrasv2(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.horashextrasv2(infechadesde character varying, infechahasta character varying, inarea bigint) RETURNS TABLE(salidoperador bigint, salidturno bigint, salnombreoperador character varying, saltipoturno character varying, salfechaturno character varying, salhe numeric, salhei numeric, salobservacion character varying, salfundicion integer, salestatus integer)
    LANGUAGE plpgsql
    AS $$
declare 

    var_record1 			record;
    var_record2 			record;
	sp_desctmp				varchar(500);
    sp_horaminuto			varchar;
   	sp_aplicaturnofund		boolean;

	sp_finturno				varchar := '13:30';
	sp_ingresodf			varchar := '08:30';
	sp_ingresosabado		varchar := '08:30';
	sp_ingresodiahabil		varchar := '08:30';
	sp_finturnosabado		varchar := '12:30';
	sp_finturnohabil		varchar := '18:30';

    sp_turno13 				varchar := '13:00';
    sp_turno16 				varchar := '16:00';
    sp_turno18				varchar := '18:00';
    sp_turno20 				varchar := '20:00';
   	sp_turno2130 			varchar := '21:30';
     				
	sp_tipodia				integer;
	sp_cont					integer;
	sp_he					numeric := 0.0;
	he1						numeric := 0.0;
	he2						numeric := 0.0;
	sp_hetmp				numeric := 0.0;
	sp_flagbool				boolean;
	queryHE					varchar;

begin
	
	sp_he 		:= 0.0;
	sp_hetmp 	:= 0.0;
	salhe		:= 0.0;
	salhei		:= 0.0;
	salobservacion := '';
	if ( inarea = 0 ) then
	   queryHE := concat('select * from  traking.mct_operador a left join  traking.mct_operadorturnofund b on ( a.idoperador = b.idoperador )
			where (b.fechaturno between to_date(',E'''',infechadesde,E'''',E',''','yyyy-mm-dd',E''') and  to_date(',E'''',infechahasta,E'''',E',''','yyyy-mm-dd',E'''))');
	else
	  queryHE := concat('select * from  traking.mct_operador a left join  traking.mct_operadorturnomaestranza b on ( a.idoperador = b.idoperador )
			where (b.fechaturno between to_date(',E'''',infechadesde,E'''',E',''','yyyy-mm-dd',E''') and  to_date(',E'''',infechahasta,E'''',E',''','yyyy-mm-dd',E'''))');	
	end if;

	 FOR var_record1 in execute queryHE
	 loop

			salhe			:= 0.0;
			salhei			:= 0.0;
		  	he1				:= 0.0;
		  	he2				:= 0.0;
		  	salobservacion 	:= '';
		  	saltipoturno 	:= '';
		   --0: Domingo
		   --6: Sabado
		   --1-5: Habil
		  		  	salidoperador 			:= var_record1.idoperador;
		  -- raise notice ' ----- > % % %', salidoperador, to_char(var_record1.fechaturno,'yyyy-mm-dd'), inarea;
		  		  

		  	for var_record2 in 
		         select * from traking.calculohorashextras(salidoperador,to_char(var_record1.fechaturno,'yyyy-mm-dd'), to_char(var_record1.fechaturno,'yyyy-mm-dd'),cast(inarea as integer))
		    loop
		 		raise notice ' % ----- > % %', salidoperador,var_record2.salhe, var_record2.salhei;
		 		he1 := var_record2.salhei;
		 		he2 := var_record2.salhe;
		 	end loop;
		 
		   select extract (DOW from  var_record1.fechaturno ) into sp_tipodia;
		   select count(*) into sp_cont from traking.mct_festivoferiado where fechafestivoferiado = var_record1.fechaturno;
		   if ( sp_cont >= 1) then 
		        -- Los festivos los hago pasar por Domingo
		  		sp_tipodia := 0;
		   end if;

			
			case
     				 when  inarea = 0		then salidturno := var_record1.idoperadorturnofund;
     				 when  inarea = 1 		then salidturno := var_record1.idoperadorturnomaestranza;
     				 else salidturno = 0;
     		end case;
			salnombreoperador 		:= var_record1.nombreoperador;
			salfechaturno 			:= var_record1.fechaturno;
			if ( var_record1.horaextraentrada <> he1 OR var_record1. horaextrasalida <> he2 ) then
				  salestatus = 1;
				  case
     				 when  inarea = 0		then update traking.mct_operadorturnofund        set  horaextraentrada = he1, horaextrasalida = he2 where idoperadorturnofund = salidturno        and idoperador = salidoperador;
     				 when  inarea = 1 		then update traking.mct_operadorturnomaestranza  set  horaextraentrada = he1, horaextrasalida = he2 where idoperadorturnomaestranza = salidturno and idoperador = salidoperador;
     				 else salidturno = 0;
     		      end case;
			      salobservacion := concat('**  ',cast(var_record1.horaextraentrada as numeric(5,2)),' ',var_record1. horaextrasalida,'  TipoDia: ',sp_tipodia,' ',to_char(var_record1.fechaturno,'dd-mm-yyyy'));
			else
				salestatus = 0;
				salobservacion := concat(' ',var_record1.horaextraentrada,' ',var_record1. horaextrasalida,'  TipoDia: ',sp_tipodia,' ',to_char(var_record1.fechaturno,'dd-mm-yyyy'));
			end if;

			if (  var_record1.ingresoanticipado ) then 
					saltipoturno := 'EA';
					select c.nombrehoraminuto  into sp_horaminuto from traking.mct_horaminuto c where c.idhoraminuto = var_record1.idhoraminutoingant;
       		    	salobservacion := concat(salobservacion,' Entrada ',sp_horaminuto);	
		    end if;
		    
		    	-- Determino horario de salida
		   sp_flagbool:= true;
		    case
	     				 when  var_record1.turno13 		then sp_finturno := sp_turno13;
	     				 when  var_record1.turno16 		then sp_finturno := sp_turno16;
	     				 when  var_record1.turno18 		then sp_finturno := sp_turno18;
	     				 when  var_record1.turno20 		then sp_finturno := sp_turno20;
	     				 when  var_record1.turno2130 	then sp_finturno := sp_turno2130;
	     				 when  var_record1.turnootro 	then select c.nombrehoraminuto into sp_horaminuto from traking.mct_horaminuto c 
     				                                     where c.idhoraminuto = var_record1.idhoraminutootro;
     				else sp_flagbool = false;
     			end case;
     			-- Valicacion que tenga un turno asignado
			if ( sp_flagbool ) then
					saltipoturno := 'TN';
       		    	salobservacion := concat(salobservacion,' Salida ',sp_finturno);	
			end if;   
		
		if ( var_record1.turnonoche ) then
				saltipoturno := 'QD';
				select c.nombrehoraminuto  into sp_finturno from traking.mct_horaminuto c 
			                               where c.idhoraminuto = var_record1.idhoraminutonoche;
				salobservacion := concat(salobservacion,' Salida ',sp_horaminuto);	
		
		end if;
		salhe  := he2;
	    salhei := he1;
		return next;
		
	END LOOP; 
return;
   
END
$$;


ALTER FUNCTION traking.horashextrasv2(infechadesde character varying, infechahasta character varying, inarea bigint) OWNER TO postgres;

--
-- TOC entry 1384 (class 1255 OID 17577)
-- Name: ia_evtgetfilepdfanterior(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.ia_evtgetfilepdfanterior(idots bigint) RETURNS TABLE(idinfcoti bigint, archivoadjunto text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    sp_idproducto bigint;
    sp_maxot      bigint;
BEGIN

    IF idots IS NULL THEN
        RAISE NOTICE 'Debe enviar un id de orden de trabajo válido.';
        RETURN;
    END IF;

    SELECT ot.idproducto
      INTO sp_idproducto
      FROM traking.mct_ordentrabajo ot
     WHERE ot.idordentrabajo = idots;

    IF sp_idproducto IS NULL THEN
        RAISE NOTICE 'No se encontró la OT % o no tiene producto asociado.', idots;
        RETURN;
    END IF;

    SELECT MAX(ot_ant.idordentrabajo)
      INTO sp_maxot
      FROM traking.mct_ordentrabajo ot_ant
     WHERE ot_ant.idproducto = sp_idproducto
       AND ot_ant.idordentrabajo < idots;

    IF sp_maxot IS NULL THEN
        RAISE NOTICE 'No existe una OT anterior para el producto % asociado a la OT %.',
            sp_idproducto,
            idots;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT pdf.idinfcotipdf AS idinfcoti,
           pdf.archivoadjunto
      FROM traking.mct_infcotipdf pdf
     WHERE pdf.idordentrabajo = sp_maxot
       AND pdf.idproceso = 3
       AND pdf.eshistoria IS NOT TRUE;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error en traking.ia_evtgetfilepdfanterior(idots=%): %',
            idots,
            SQLERRM;
END;
$$;


ALTER FUNCTION traking.ia_evtgetfilepdfanterior(idots bigint) OWNER TO postgres;

--
-- TOC entry 2188 (class 1255 OID 17578)
-- Name: ia_evtlistpicbycategory(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.ia_evtlistpicbycategory(idattachedcategorys bigint, idworkorders bigint, idcompevens bigint, idcompevendets bigint) RETURNS TABLE(idworkorderattachedtype bigint, idworkorder bigint, idattachedtype bigint, idattachedcategory bigint, nameattachedcategory character varying, picfile text, correlative bigint, nombrecomponenteevafotomanual character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    if (idcompevendets = -1) then

        RETURN QUERY
        
		select a.idordentrabajoadjunto,
		       a.idordentrabajo,
		       a.idtipoadjunto,
		       a.idcategoriaadjunto,
		       b.nombrecategoriaadjunto,
	           a.archivoadjunto,
		       a.correlativo,
               a.nombrecomponenteevafotomanual
		  from mct_ordentrabajotipoadjunto a
  	      left join mct_categoriaadjunto b on a.idcategoriaadjunto = b.idcategoriaadjunto
  	     where idtipoadjunto in (2)
  	       and a.idcategoriaadjunto = idattachedcategorys
  	       and a.idordentrabajo = idworkorders
           and a.idcomponenteevafoto = idcompevens
      order by fechacreacion asc, correlativo asc;

    else
        
        RETURN QUERY
        
  		select a.idordentrabajoadjunto,
		       a.idordentrabajo,
		       a.idtipoadjunto,
		       a.idcategoriaadjunto,
		       b.nombrecategoriaadjunto,
	           a.archivoadjunto,
		       a.correlativo,
               a.nombrecomponenteevafotomanual
		  from mct_ordentrabajotipoadjunto a
  	      left join mct_categoriaadjunto b on a.idcategoriaadjunto = b.idcategoriaadjunto
  	     where idtipoadjunto in (2)
  	       and a.idcategoriaadjunto = idattachedcategorys
  	       and a.idordentrabajo = idworkorders
           and a.idcomponenteevafoto = idcompevens
           and a.idcomponenteevafotodetalle = idcompevendets
      order by fechacreacion asc, correlativo asc;

    end if;

END;
$$;


ALTER FUNCTION traking.ia_evtlistpicbycategory(idattachedcategorys bigint, idworkorders bigint, idcompevens bigint, idcompevendets bigint) OWNER TO postgres;

--
-- TOC entry 1980 (class 1255 OID 17579)
-- Name: ia_listcategoryattachedbyuser(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.ia_listcategoryattachedbyuser() RETURNS TABLE(idcategory bigint, categoryname character varying)
    LANGUAGE plpgsql
    AS $$
Declare

	sp_usuario				varchar;
    sp_idoperador			bigint;
    sp_nombreoperador		varchar;
    sp_idperfil				bigint;
    sp_idseccionprincipal	bigint;
    sp_nombreseccion		varchar;
    sp_idcargo				bigint;
    sp_idareaapp			bigint;
    sp_nombrearea			varchar;
    sp_idseccionapp			bigint;
    sp_idcargoapp			bigint;
    sp_nombrecargo			varchar;

BEGIN

	    RETURN QUERY
	
	    SELECT a.idcategoriaadjunto , 
	           a.nombrecategoriaadjunto
	      FROM traking.mct_categoriaadjunto a
	     where a.estado = 1
	       and a.aplicacontrolproceso is not true
           AND a.aplicatmevaluadores is true
           and a.idcategoriaadjunto in (14,32,33,39)
         order by a.orden asc;

END;
$$;


ALTER FUNCTION traking.ia_listcategoryattachedbyuser() OWNER TO postgres;

