--
-- TOC entry 2024 (class 1255 OID 17581)
-- Name: insumodisponible(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.insumodisponible(idinsumoi bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
  disp_e  bigint;
  disp_i  bigint;
  disponible bigint;

begin
	
	disp_i := 0;
	disp_e := 0;


	if ( (select count(*) from traking.mct_insumoegreso where idinsumo = idinsumoi ) > 0 ) then

		select disp into disp_e from (
		select idinsumo, sum(stock) as disp
		from traking.mct_insumoegreso
		where idinsumo = idinsumoi
		group by idinsumo
	    ) as p;
	else 
	    disp_e = 0;
	end if;
	
	if ( (select count(*) from traking.mct_insumoingreso where idinsumo = idinsumoi ) > 0 ) then
	
		select disp into disp_i from (
		select idinsumo, sum(stock) as disp
		from traking.mct_insumoingreso
		where idinsumo = idinsumoi
		group by idinsumo
	   ) as p;
	else 
	    disp_i = 0;
	end if;
	disponible = disp_i - disp_e;

RETURN disponible;
END;
$$;


ALTER FUNCTION traking.insumodisponible(idinsumoi bigint) OWNER TO postgres;

