-- Name: invupdateaccount(bigint, character varying, character varying, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.invupdateaccount(idaccountup bigint, nameaccountup character varying, codeaccountup character varying, idgroupaccountup bigint, statusup bigint, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    update traking.inv_cuentacontable
    set nombrecuentacontable=nameaccountup,
        codigo = codeaccountup,
        idgrupocuentacontable = idgroupaccountup,
        estado=statusup,
        usuariomodificacion=userupdateup,
        fechamodificacion=now()
    where idcuentacontable = idaccountup;
END;
$$;


