--
-- TOC entry 1691 (class 1255 OID 17638)
-- Name: listaccionrecepciontablet(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listaccionrecepciontablet() RETURNS TABLE(idaction bigint, actionname character varying, actioncode character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
        SELECT traking.mct_accion.idaccion, 
               traking.mct_accion.nombreaccion, 
               traking.mct_accion.codigoaccion,
               traking.mct_accion.estado,
               traking.mct_estado.nombreestado,
               traking.mct_accion.fechacreacion,
               traking.mct_accion.usuariocreacion,
               traking.mct_accion.fechamodificacion,
               traking.mct_accion.usuariomodificacion
        FROM traking.mct_accion, traking.mct_estado
       where traking.mct_accion.estado=traking.mct_estado.idestado
         and traking.mct_accion.aplicarecepciontablet is true
      order by traking.mct_accion.nombreaccion asc;

END;
$$;


ALTER FUNCTION traking.listaccionrecepciontablet() OWNER TO postgres;

