--

CREATE FUNCTION traking.listaclientecomcombo() RETURNS TABLE(nombreclientecom character varying, idclientecom bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

	select distinct mc.nombreclientecom, cast(0 as bigint)
	  from traking.mct_clientecom mc
    order by mc.nombreclientecom asc;

END;
$$;


