--

CREATE FUNCTION traking.listaction() RETURNS TABLE(idaction bigint, actionname character varying, actioncode character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_accion.idaccion, 
               traking.mct_accion.nombreaccion, 
               traking.mct_accion.codigoaccion,
               traking.mct_accion.estado,
               traking.mct_estado.nombreestado,
