CREATE FUNCTION traking.listactividadgestioncalendario(idusers bigint) RETURNS TABLE(idactividadgestion bigint, fechaactividad character varying, fechaactividadcal timestamp without time zone, horaactividad character varying, idtipoactividadgestion bigint, nombretipoactividadgestion character varying, siglatipo character varying, descripciontipo character varying, idclientecom bigint, nombreclientecom character varying, siglacliente character varying, idareainteres bigint, nombreareainteres character varying, idclientecomcontacto bigint, nombrecontacto character varying, idmotivoactividadgestion bigint, nombremotivoactividadgestion character varying, siglamotivo character varying, descripcionmotivo character varying, idusuario bigint, nombreusuario character varying, siglausuario character varying, idestadoactividadgestion bigint, nombreestadoactividadgestion character varying, descripcionactividad character varying, telefonocontacto character varying, email character varying, idauditoriaactividadgestion bigint, nombreauditoriaactividadgestion character varying, descripcionauditoria character varying, status integer, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying, aplicatodoeldia boolean, idrecurrencia bigint, nombrerecurrencia character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

		if (idusers in (-1,5)) then


		    RETURN QUERY
	
			SELECT traking.mct_actividadgestion.idactividadgestion, 
                   cast(to_char(traking.mct_actividadgestion.fechaactividad, 'dd-mm-yyyy') as varchar) as fechaactividad ,
                   traking.mct_actividadgestion.fechaactividad as fechaactividadcal, 
                   cast(to_char(traking.mct_actividadgestion.horaactividad,'HH24:mi') as varchar) as horaactividad,
               
			       traking.mct_actividadgestion.idtipoactividadgestion, 
			       traking.mct_tipoactividadgestion.nombretipoactividadgestion , 
			       traking.mct_tipoactividadgestion.sigla  ,
			       traking.mct_actividadgestion.descripciontipo, 

				   traking.mct_actividadgestion.idclientecom,
	               traking.mct_actividadgestion.nombreclientecom,
traking.mct_clientecom.siglacliente,
	               traking.mct_actividadgestion.idareainteres,
	               traking.mct_actividadgestion.nombreareainteres,

			       traking.mct_actividadgestion.idclientecomcontacto, 
			       traking.mct_clientecomcontacto.nombrecontacto  ,

			       traking.mct_actividadgestion.idmotivoactividadgestion, 
			       traking.mct_motivoactividadgestion.nombremotivoactividadgestion ,
			       traking.mct_motivoactividadgestion.sigla ,
			       traking.mct_actividadgestion.descripcionmotivo, 
			       traking.mct_actividadgestion.idusuario, 
			       traking.mct_usuario.nombre ,
traking.mct_usuario.sigla ,

				   traking.mct_actividadgestion.idestadoactividadgestion,
				   traking.mct_estadoactividadgestion.nombreestadoactividadgestion,
	               traking.mct_actividadgestion.descripcionactividad,

traking.mct_clientecomcontacto.telefonocontacto ,
traking.mct_clientecomcontacto.email ,
coalesce(traking.mct_actividadgestion.idauditoriaactividadgestion,0) as idauditoriaactividadgestion,
traking.mct_auditoriaactividadgestion.nombreauditoriaactividadgestion,
traking.mct_actividadgestion.descripcionauditoria,

			       traking.mct_actividadgestion.estado, 
                   cast('' as varchar),
			       traking.mct_actividadgestion.fechacreacion, 
			       traking.mct_actividadgestion.usuariocreacion, 
			       traking.mct_actividadgestion.fechamodificacion,
			       traking.mct_actividadgestion.usuariomodificacion,
                   traking.mct_actividadgestion.aplicatodoeldia,
                   traking.mct_actividadgestion.idrecurrencia,
                   cast('' as varchar) as nombrerecurrencia
			  FROM traking.mct_actividadgestion
			  left join traking.mct_tipoactividadgestion on traking.mct_tipoactividadgestion.idtipoactividadgestion = traking.mct_actividadgestion.idtipoactividadgestion
			  left join traking.mct_clientecomcontacto   on traking.mct_clientecomcontacto.idclientecomcontacto  = traking.mct_actividadgestion.idclientecomcontacto  
			  left join traking.mct_motivoactividadgestion  on traking.mct_motivoactividadgestion.idmotivoactividadgestion  = traking.mct_actividadgestion.idmotivoactividadgestion 
			  left join traking.mct_usuario on traking.mct_usuario.idusuario = traking.mct_actividadgestion.idusuario 
              left join traking.mct_estadoactividadgestion on traking.mct_estadoactividadgestion.idestadoactividadgestion = traking.mct_actividadgestion.idestadoactividadgestion
              left join traking.mct_clientecom             on traking.mct_clientecom.idclientecom = traking.mct_clientecomcontacto.idclientecom			  
              left join traking.mct_auditoriaactividadgestion on traking.mct_auditoriaactividadgestion.idauditoriaactividadgestion = traking.mct_actividadgestion.idauditoriaactividadgestion
             order by traking.mct_actividadgestion.fechaactividad, traking.mct_actividadgestion.horaactividad;


		else

		    RETURN QUERY
	
			SELECT traking.mct_actividadgestion.idactividadgestion, 
                   cast(to_char(traking.mct_actividadgestion.fechaactividad, 'dd-mm-yyyy') as varchar) as fechaactividad ,
                   traking.mct_actividadgestion.fechaactividad as fechaactividadcal, 
