--

CREATE FUNCTION traking.listaleacion() RETURNS TABLE(idaleacion bigint, nombrealeacion character varying, idtipoaleacion bigint, nombretipoaleacion character varying, estado bigint, nombreestado character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	RETURN QUERY
	  	SELECT 
	  	    a.idaleacion,
            a.nombrealeacion,
	  		b.idtipoaleacion,
	  	    b.nombretipoaleacion ,	        
		    a.estado,
		    c.nombreestado,
		    a.fechacreacion,
		    a.usuariocreacion,
		    a.fechamodificacion,   
		    a.usuariomodificacion		            
	  FROM traking.mct_aleacion a
	  left join traking.mct_tipoaleacion b on ( a.idtipoaleacion = b.idtipoaleacion)
	  left join traking.mct_estado c       on ( a.estado = c.idestado)
	  order by b.idtipoaleacion,a.idaleacion;
      

END;
$$;


