    LANGUAGE plpgsql
    AS $$
BEGIN

	RETURN QUERY
	  	SELECT 
            a.idaleacionmetal,
	        a.idaleacion,
	        d.nombrealeacion,
            a.idmetal,            
	        b.nombremetal,
	        b.simbolo,
			COALESCE(a.nivelmin,0),
			COALESCE(a.nivelmax,0),
			COALESCE(a.valormaxperm,0),
		    a.estado,
		    c.nombreestado,
		    a.fechacreacion,
		    a.usuariocreacion,
		    a.fechamodificacion,   
		    a.usuariomodificacion		            
	  FROM traking.mct_aleacionmetal a
	  left join traking.mct_metal b on ( a.idmetal =  b.idmetal )
	  left join traking.mct_aleacion d on ( a.idaleacion = d.idaleacion)
	  left join traking.mct_estado c on ( a.estado = c.idestado)
	  order by a.idaleacion,a.idmetal;
      


END;
$$;


