--

CREATE FUNCTION traking.listalltipoinsumocombo(idtipoinsumos bigint) RETURNS TABLE(idtipoinsumo bigint, nombretipoinsumo character varying, estado bigint, nombreestado character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idtipoinsumos = -1 ) then

		RETURN QUERY
		SELECT a.idtipoinsumo,
			   a.nombretipoinsumo,
			   a.estado,
			   b.nombreestado,
			   a.fechacreacion,
			   a.usuariocreacion,
			   a.fechamodificacion,
			   a.usuariomodificacion
		  FROM traking.mct_tipoinsumo a
	      left join traking.mct_estado b on ( a.estado = b.idestado);
     
	elsif ( idtipoinsumos = 88  ) then
	
		RETURN QUERY
		SELECT a.idtipoinsumo,
			   a.nombretipoinsumo,
			   a.estado,
			   b.nombreestado,
			   a.fechacreacion,
			   a.usuariocreacion,
			   a.fechamodificacion,
			   a.usuariomodificacion
		  FROM traking.mct_tipoinsumo a
	      left join traking.mct_estado b on ( a.estado = b.idestado)
	     where a.idtipoinsumo not in (4,5,10);
	
	elsif ( idtipoinsumos = 99  ) then
	
		RETURN QUERY
		SELECT a.idtipoinsumo,
			   a.nombretipoinsumo,
			   a.estado,
			   b.nombreestado,
			   a.fechacreacion,
			   a.usuariocreacion,
			   a.fechamodificacion,
			   a.usuariomodificacion
		  FROM traking.mct_tipoinsumo a
	      left join traking.mct_estado b on ( a.estado = b.idestado)
	     where a.idtipoinsumo in (4,5,10);	
	
	end if;



END;
$$;


