BEGIN

    RETURN QUERY
        SELECT traking.mct_categoriaplanoparam.idcategoriaplano, 
               traking.mct_categoriaplanoparam.nombreparam, 
               traking.mct_categoriaplanoparam.estado,
               traking.mct_estado.nombreestado,
               traking.mct_categoriaplanoparam.fechacreacion,
               traking.mct_categoriaplanoparam.usuariocreacion,
               traking.mct_categoriaplanoparam.fechamodificacion,
               traking.mct_categoriaplanoparam.usuariomodificacion
        FROM traking.mct_categoriaplanoparam, traking.mct_estado
       where traking.mct_categoriaplanoparam.estado=traking.mct_estado.idestado
      order by 1 asc;

END;
$$;


ALTER FUNCTION traking.listblueprintcategory() OWNER TO postgres;

--
-- TOC entry 1198 (class 1255 OID 17661)
-- Name: listblueprintmetro(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listblueprintmetro(idproductf bigint) RETURNS TABLE(idtplane bigint, nametplane character varying, idblueprint bigint, blueprintname character varying, fileblueprint text, quantity bigint, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_plano.idtipoplano, 
               traking.mct_tipoplano.nombretipoplano,
               traking.mct_plano.idplano, 
               traking.mct_plano.nombreplano, 
               traking.mct_plano.archivoplano,
               traking.mct_plano.cantidad ,
               traking.mct_plano.estado,
               traking.mct_estado.nombreestado,
               traking.mct_plano.fechacreacion,
               traking.mct_plano.usuariocreacion,
               traking.mct_plano.fechamodificacion,
               traking.mct_plano.usuariomodificacion
          FROM traking.mct_plano, 
               traking.mct_estado,
               traking.mct_tipoplano,
               traking.mct_producto
    WHERE traking.mct_producto.idproducto=idproductf
      and traking.mct_plano.nombreplano like '%'||traking.mct_producto.planogeneral||'%'
      and traking.mct_plano.estado=traking.mct_estado.idestado
      and traking.mct_plano.idtipoplano=traking.mct_tipoplano.idtipoplano
      --and traking.mct_tipoplano.idtipoplano in (21,23,24,22)
      and traking.mct_tipoplano.idtipoplano in (39)
      and traking.mct_plano.idplano not in (select b.idplano from mct_productoplano b where b.idproducto = idproductf)
     order by 4 asc;

END;
$$;


ALTER FUNCTION traking.listblueprintmetro(idproductf bigint) OWNER TO postgres;

--
-- TOC entry 1144 (class 1255 OID 17662)
-- Name: listblueprintmetrocombo(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listblueprintmetrocombo(idworkorderf bigint) RETURNS TABLE(idblueprint bigint, blueprintname text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
			select b.idplano, d.nombreplano||'_'||e.nombretipoplano 
			  from mct_ordentrabajo a,
			       mct_productoplano b,
			       mct_planoadjunto c,
			       mct_plano d,
			       mct_tipoplano e
			 where a.idordentrabajo = idworkorderf
			   and a.idproducto  = b.idproducto 
			   and b.idplano     = c.idplano 
			   and c.idplano     = d.idplano 
			   and d.idtipoplano = e.idtipoplano 
			   order by 1 asc;

END;
$$;


ALTER FUNCTION traking.listblueprintmetrocombo(idworkorderf bigint) OWNER TO postgres;

