--

CREATE FUNCTION traking.listcaracterizacion(planos character varying) RETURNS TABLE(idcaracterizacion bigint, plano character varying, idcliente bigint, nombrecliente character varying, idfamilia bigint, nombrefamilia character varying, idproducto bigint, nombreproducto character varying, idproductonepcast bigint, nombreproductonepcast character varying, idcomponente bigint, nombrecomponente character varying, idmaterial bigint, nombrematerial character varying, codigomolde character varying, pesopiezacoladaascast numeric, porcentajeutilizacioncancha numeric, cantidadhorno numeric, iddoble bigint, nombredoble character varying, idsimple bigint, nombresimple character varying, pesopiezalimpia numeric, porcentajeascastretorno numeric, pesopiezaliberada numeric, porcentajepiezaliberada numeric, tiempodecolada numeric, tiempodefusion numeric, cucharas numeric, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
begin
	
	if (select 1 
	      from traking.mct_caracterizacion a
	     where a.plano = planos) then
	
		RETURN QUERY
		
		SELECT a.idcaracterizacion, 
		       a.plano, 
		       a.idcliente, 
		       coalesce (b.nombrecliente, '') ,
		       a.idfamilia,
		       coalesce (l.nombrefamilia, '') ,
		       a.idproducto, 
		       coalesce (c.nombreproducto, '') ,
		       a.idproductonepcast,
		       coalesce (d.nombreproductonepcast, '') ,
		       a.idcomponente, 
		       coalesce (e.nombrecomponente, '') ,
		       a.idmaterial, 
		       coalesce (f.nombrematerial, '') ,
		       a.codigomolde, 
		       a.pesopiezacoladaascast, 
		       a.porcentajeutilizacioncancha, 
		       a.cantidadhorno, 
		       a.iddoble, 
		       coalesce (g.nombredoble, '') ,
		       a.idsimple, 
		       coalesce (h.nombresimple, '') ,
		       a.pesopiezalimpia, 
		       a.porcentajeascastretorno, 
               a.pesopiezaliberada, 
		       a.porcentajepiezaliberada,
		       a.tiempodecolada, 
		       a.tiempodefusion, 
		       a.cucharas, 
		       a.estado, 
		       k.nombreestado ,
		       a.fechacreacion,
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion 
		  FROM traking.mct_caracterizacion a
		  left join traking.mct_cliente    b on a.idcliente = b.idcliente 
		  left join traking.mct_producto   c on a.idproducto = c.idproducto 
		  left join traking.mct_productonepcast d on a.idproductonepcast = d.idproductonepcast 
		  left join traking.mct_componente e on a.idcomponente = e.idcomponente 
		  left join traking.mct_material   f on a.idmaterial = f.idmaterial 
		  left join traking.mct_doble      g on a.iddoble = g.iddoble 
		  left join traking.mct_simple     h on a.idsimple = h.idsimple 
		  left join traking.mct_estado     k on a.estado = k.idestado 
		  left join traking.mct_familia    l on a.idfamilia = l.idfamilia 
		 where a.plano = planos;
	
	else
	
	    insert into traking.mct_caracterizacion(idcaracterizacion, plano)
	         values (nextval('traking.mct_caracterizacion_seq'),planos);
	
		RETURN QUERY
		
		SELECT a.idcaracterizacion, 
		       a.plano, 
		       a.idcliente, 
		       coalesce (b.nombrecliente, '') ,
		       a.idfamilia,
		       coalesce (l.nombrefamilia, '') ,
		       a.idproducto, 
		       coalesce (c.nombreproducto, '') ,
		       a.idproductonepcast,
		       coalesce (d.nombreproductonepcast, '') ,
		       a.idcomponente, 
		       coalesce (e.nombrecomponente, '') ,
		       a.idmaterial, 
		       coalesce (f.nombrematerial, '') ,
		       a.codigomolde, 
		       a.pesopiezacoladaascast, 
		       a.porcentajeutilizacioncancha, 
		       a.cantidadhorno, 
		       a.iddoble, 
		       coalesce (g.nombredoble, '') ,
		       a.idsimple, 
		       coalesce (h.nombresimple, '') ,
		       a.pesopiezalimpia, 
		       a.porcentajeascastretorno, 
               a.pesopiezaliberada, 
		       a.porcentajepiezaliberada,
		       a.tiempodecolada, 
		       a.tiempodefusion, 
		       a.cucharas, 
		       a.estado, 
		       k.nombreestado ,
		       a.fechacreacion,
		       a.usuariocreacion, 
		       a.fechamodificacion,
		       a.usuariomodificacion 
		  FROM traking.mct_caracterizacion a
		  left join traking.mct_cliente    b on a.idcliente = b.idcliente 
		  left join traking.mct_producto   c on a.idproducto = c.idproducto 
		  left join traking.mct_productonepcast d on a.idproductonepcast = d.idproductonepcast 
		  left join traking.mct_componente e on a.idcomponente = e.idcomponente 
		  left join traking.mct_material   f on a.idmaterial = f.idmaterial 
		  left join traking.mct_doble      g on a.iddoble = g.iddoble 
		  left join traking.mct_simple     h on a.idsimple = h.idsimple 
		  left join traking.mct_estado     k on a.estado = k.idestado 
		  left join traking.mct_familia    l on a.idfamilia = l.idfamilia 
		 where a.plano = planos;
		
	end if;


END;
$$;


ALTER FUNCTION traking.listcaracterizacion(planos character varying) OWNER TO postgres;

