--
-- TOC entry 1149 (class 1255 OID 17674)
-- Name: listcategoryattachedbyuser(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcategoryattachedbyuser(idusers bigint) RETURNS TABLE(idcategory bigint, categoryname character varying)
    LANGUAGE plpgsql
    AS $$
Declare

	sp_usuario				varchar;
    sp_idoperador			bigint;
    sp_nombreoperador		varchar;
    sp_idperfil				bigint;
    sp_idseccionprincipal	bigint;
    sp_nombreseccion		varchar;
    sp_idcargo				bigint;
    sp_idareaapp			bigint;
    sp_nombrearea			varchar;
    sp_idseccionapp			bigint;
    sp_idcargoapp			bigint;
    sp_nombrecargo			varchar;

BEGIN

		select a.usuario,
		       b.idoperador,
		       b.nombreoperador,
		       b.idperfil,
		       b.idseccionprincipal,
		       c.nombreseccion,
		       b.idcargo,
		       b.idareaapp,
		       d.nombrearea,
		       b.idseccionapp,
		       b.idcargoapp,
		       e.nombrecargo
		  into sp_usuario,
		       sp_idoperador,
		       sp_nombreoperador,
		       sp_idperfil,
		       sp_idseccionprincipal,
		       sp_nombreseccion,
		       sp_idcargo,
		       sp_idareaapp,
		       sp_nombrearea,
		       sp_idseccionapp,
		       sp_idcargoapp,
		       sp_nombrecargo
		  from mct_usuario a
		  left join mct_operador b on a.rut = b.rut||'-'||b.digito
		  left join mct_seccion c on b.idseccionprincipal = c.idseccion
		  left join mct_area d on b.idareaapp = d.idarea
		  left join mct_cargo e on b.idcargoapp = e.idcargo
		  left join mct_seccion f on b.idseccionapp = f.idseccion
		 where idusuario = idusers;

	if ( idusers IN (5, 91, 31, 105, 27, 6, 19, 140, 119 ) ) then

	    RETURN QUERY
	
	    SELECT a.idcategoriaadjunto , 
	           a.nombrecategoriaadjunto
	      FROM traking.mct_categoriaadjunto a
	     where a.estado = 1
	       and (a.aplicacontrolproceso is not true or a.idcategoriaadjunto = 40)
           AND a.aplicatmevaluadores is true
         order by a.orden asc;

	elsif ( idusers = 91 ) then

	    RETURN QUERY
	
	    SELECT a.idcategoriaadjunto , 
	           a.nombrecategoriaadjunto
	      FROM traking.mct_categoriaadjunto a
	     where a.estado = 1
	       and (a.aplicacontrolproceso is not true or a.idcategoriaadjunto = 40)
           and a.aplicatmevaluadores is true
         order by a.orden asc;

	elsif (sp_idareaapp = 7) then

	    RETURN QUERY
	
	    SELECT a.idcategoriaadjunto , 
	           a.nombrecategoriaadjunto
	      FROM traking.mct_categoriaadjunto a
	     where a.estado = 1
	       and (a.aplicacontrolproceso is not true or a.idcategoriaadjunto = 40)
           and a.aplicatmevaluadores is true
         order by a.orden asc;

	elsif (sp_idareaapp = 6) then

	    RETURN QUERY
	
	    SELECT a.idcategoriaadjunto , 
	           a.nombrecategoriaadjunto
	      FROM traking.mct_categoriaadjunto a
	     where a.estado = 1
	       and (a.aplicacontrolproceso is not true or a.idcategoriaadjunto = 40)
           and a.aplicaplanificacion is true
         order by a.orden asc;

	elsif (sp_idareaapp = 3) then

	    RETURN QUERY
	
	    SELECT a.idcategoriaadjunto , 
	           a.nombrecategoriaadjunto
	      FROM traking.mct_categoriaadjunto a
	     where a.estado = 1
	       and (a.aplicacontrolproceso is not true or a.idcategoriaadjunto = 40)
           and a.aplicacontrolcalidad is true
         order by a.orden asc;

	elsif (sp_idareaapp = 2) then

	    RETURN QUERY
	
	    SELECT a.idcategoriaadjunto , 
	           a.nombrecategoriaadjunto
	      FROM traking.mct_categoriaadjunto a
	     where a.estado = 1
	       and (a.aplicacontrolproceso is not true or a.idcategoriaadjunto = 40)
           and a.aplicacaldereria is true
         order by a.orden asc;

	end if;

END;
$$;


ALTER FUNCTION traking.listcategoryattachedbyuser(idusers bigint) OWNER TO postgres;

