-- Name: listchecklist(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listchecklist() RETURNS TABLE(idchecklist bigint, idcheckliststr character varying, checklistname character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_checklist.idchecklist , 
               cast(traking.mct_checklist.idchecklist as varchar) ,
               traking.mct_checklist.nombrechecklist , 
               traking.mct_checklist.estado,
               traking.mct_estado.nombreestado,
               traking.mct_checklist.fechacreacion,
               traking.mct_checklist.usuariocreacion,
               traking.mct_checklist.fechamodificacion,
               traking.mct_checklist.usuariomodificacion
        FROM traking.mct_checklist, traking.mct_estado
       where traking.mct_checklist.estado=traking.mct_estado.idestado
      order by 1 asc;

END;
$$;


ALTER FUNCTION traking.listchecklist() OWNER TO postgres;

