CREATE FUNCTION traking.listchecklistinftec() RETURNS TABLE(idchecklistinftec bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, usercreate character varying, datecreate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
		SELECT a.idchecklistinftec, 
		       a.idordentrabajo, 
		       a.nombreparte, 
		       a.cantidad, 
		       a.material, 
		       a.criterio, 
		       a.reparacion, 
		       a.plano, 
		       cast('<img src="assets/img/delete.png">' as varchar),
		       a.usuariocreacion, 
		       a.fechacreacion
		FROM traking.mct_checklistinftec a
	   where a.muestrachecklist = true
      order by a.criterio asc;

END;
$$;


