--

CREATE FUNCTION traking.listchecklistinftecbycod(code character varying, idworkorders bigint) RETURNS TABLE(idchecklistinftec bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, returncomp boolean, idcomponente bigint, componentegenerico character varying, idmaterial bigint, materialgenerico character varying, usercreate character varying, datecreate timestamp without time zone, indexrow bigint, idcriterioevaluacion bigint, nombrezona character varying, noaplicasolicitud boolean)
    LANGUAGE plpgsql
    AS $$
declare

    sp_string    varchar;
    sp_texto     varchar;
    sp_texto1    varchar;
    sp_texto2    varchar;
    sp_texto3    varchar;
    sp_texto4    varchar;
          
  
   
begin
	
	  if ( code like '%DEVOLUCION') then
	  
		    RETURN QUERY
				SELECT a.idchecklistinftec, 
			       a.idordentrabajo, 
			       a.nombreparte, 
			       a.cantidad, 
			       a.material, 
			       a.criterio, 
			       a.reparacion, 
			       a.plano, 
			       cast('<img src="assets/img/delete.png">' as varchar),
			       a.devolucion ,
			       a.idcomponente,
			       a.nombrecomponente ,
			       a.idmaterial,
			       a.nombrematerial ,
			       a.usuariocreacion, 
			       a.fechacreacion,
			       a.indicefila ,
			       a.idcriterioevaluacion ,
			       a.nombrezona,
			       a.noaplicasolicitud
			  FROM traking.mct_checklistinftec a
		     WHERE a.idordentrabajo = idworkorders
		       and a.devolucion = true
		      -- and a.muestrachecklist = true
	      order by a.indicefila asc;
	     
	  else
	  
		    RETURN QUERY
				SELECT a.idchecklistinftec, 
			       a.idordentrabajo, 
			       a.nombreparte, 
			       a.cantidad, 
			       a.material, 
			       a.criterio, 
			       a.reparacion, 
			       a.plano, 
			       cast('<img src="assets/img/delete.png">' as varchar),
			       a.devolucion ,
			       a.idcomponente,
			       a.nombrecomponente ,
			       a.idmaterial,
			       a.nombrematerial ,			       
			       a.usuariocreacion, 
			       a.fechacreacion,
			       a.indicefila ,
			       a.idcriterioevaluacion,
			       a.nombrezona,
			       a.noaplicasolicitud
			  FROM traking.mct_checklistinftec a
		     WHERE a.idordentrabajo = idworkorders
		       and upper( a.codigoqr)  = code
		       --and a.muestrachecklist = true
	      order by a.indicefila asc;	  
	  
	  end if;

END;
$$;


