--
-- TOC entry 1755 (class 1255 OID 17682)
-- Name: listchecklistinftecbyid_p(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listchecklistinftecbyid_p(idworkorders bigint) RETURNS TABLE(idchecklistinftec bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, returncomp boolean, idcomponente bigint, componentegenerico character varying, idmaterial bigint, materialgenerico character varying, usercreate character varying, datecreate timestamp without time zone, indexrow bigint, idcriterioevaluacion bigint, nombrezona character varying, idpadre bigint, estaparametrizado boolean, noaplicasolicitud boolean)
    LANGUAGE plpgsql
    AS $$
declare

	sp_tieneparam		integer;
	sp_parametrizado	boolean;
begin
	

		sp_tieneparam	:= 0;
		select count(*)
		  into sp_tieneparam
		  from mct_ordentrabajo a 
		  left join mct_producto b                on b.idproducto = a.idproducto 
		  left join mct_checklistinftecparamcab c on c.planogeneral = b.planogeneral 
		  left join mct_checklistinftecparamdet d on d.idchecklistinftecparamcab = c.idchecklistinftecparamcab
		 where a.idordentrabajo = idworkorders;
	 
	    RETURN QUERY
	
		SELECT a.idchecklistinftec, 
		       a.idordentrabajo, 
		       a.nombreparte, 
		       a.cantidad, 
		       a.material, 
		       a.criterio, 
		       a.reparacion, 
		       a.plano, 
		       cast('<img src="assets/img/delete.png">' as varchar),
		       a.devolucion ,
		       a.idcomponente,
		       a.nombrecomponente ,
		       a.idmaterial,
		       a.nombrematerial ,
		       a.usuariocreacion, 
		       a.fechacreacion,
		       a.indicefila ,
		       case
			       when a.idcriterioevaluacion is null then
			            b.idcriterioevaluacion 
			       else
			            a.idcriterioevaluacion
			   end,
		       a.nombrezona,
		       a.idpadre ,
		       case
			       when sp_tieneparam > 1 then
			            true
			       else
			            false
			   end,
			   a.noaplicasolicitud 
		  FROM traking.mct_checklistinftec a
		  left join mct_criterioevaluacion b   on upper(b.nombrecriterioevaluacion) = upper(a.criterio)  
	     WHERE a.idordentrabajo = idworkorders
	      -- and a.muestrachecklist = true
      --order by a.nombrezona, a.indicefila asc, idpadre asc;
     order by a.idpadre asc, a.idchecklistinftec asc;

END;
$$;


ALTER FUNCTION traking.listchecklistinftecbyid_p(idworkorders bigint) OWNER TO postgres;

