CREATE FUNCTION traking.listchecklistinftecbyid_pvalido(idworkorders bigint) RETURNS TABLE(idchecklistinftecvalido bigint, idchecklistinftec bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, returncomp boolean, idcomponente bigint, componentegenerico character varying, idmaterial bigint, materialgenerico character varying, usercreate character varying, datecreate timestamp without time zone, indexrow bigint, idcriterioevaluacion bigint, nombrezona character varying, idpadre bigint, estaparametrizado boolean, checklistvalido boolean, firmaingreso boolean, timbretrabajo boolean, materialconforme boolean, cantidadconforme boolean, planoconforme boolean, nombreconforme boolean, observacion character varying, noaplicasolicitud boolean)
    LANGUAGE plpgsql
    AS $$
declare

	sp_tieneparam		integer;
	sp_parametrizado	boolean;
begin
	

		sp_tieneparam	:= 0;
		select count(*)
		  into sp_tieneparam
		  from mct_ordentrabajo a 
		  left join mct_producto b                on b.idproducto = a.idproducto 
		  left join mct_checklistinftecparamcab c on c.planogeneral = b.planogeneral 
		  left join mct_checklistinftecparamdet d on d.idchecklistinftecparamcab = c.idchecklistinftecparamcab
		 where a.idordentrabajo = idworkorders;
	 
	    RETURN QUERY
	
		SELECT a.idchecklistinftecvalido, 
		       a.idchecklistinftec ,
		       a.idordentrabajo, 
		       a.nombreparte, 
		       a.cantidad, 
		       a.material, 
		       a.criterio, 
		       a.reparacion, 
		       a.plano, 
		       cast('<img src="assets/img/delete.png">' as varchar),
		       a.devolucion ,
		       a.idcomponente,
		       a.nombrecomponente ,
		       a.idmaterial,
		       a.nombrematerial ,
		       a.usuariocreacion, 
		       a.fechacreacion,
		       a.indicefila ,
		       case
			       when a.idcriterioevaluacion is null then
			            b.idcriterioevaluacion 
			       else
			            a.idcriterioevaluacion
			   end,
		       a.nombrezona,
		       a.idpadre ,
		       case
			       when sp_tieneparam > 1 then
			            true
			       else
			            false
			   end,
		       false,
			   a.firmaingreso,
               a.timbretrabajo,
               a.materialconforme,
               a.cantidadconforme,
               a.planoconforme,
               a.nombreconforme,
               a.observacion,
			   a.noaplicasolicitud
		  FROM traking.mct_checklistinftecvalido a
		  left join traking.mct_criterioevaluacion b on upper(b.nombrecriterioevaluacion) = upper(a.criterio)  
	     WHERE a.idordentrabajo = idworkorders
	      -- and a.muestrachecklist = true
      --order by a.indicefila asc, idpadre asc;
	     --order by a.nombrezona , a.nombreparte , a.indicefila asc, idpadre asc;
	    --order by a.indicefila asc, idpadre asc;
	     order by a.idpadre asc, a.idchecklistinftec asc;

END;
$$;


ALTER FUNCTION traking.listchecklistinftecbyid_pvalido(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1624 (class 1255 OID 17687)
-- Name: listchecklistinftecbyidinicial(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listchecklistinftecbyidinicial(idworkorders bigint) RETURNS TABLE(idchecklistinftec bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, returncomp boolean, idcomponente bigint, componentegenerico character varying, idmaterial bigint, materialgenerico character varying, usercreate character varying, datecreate timestamp without time zone, indexrow bigint, idcriterioevaluacion bigint, nombrezona character varying, noaplicasolicitud boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		SELECT a.idchecklistinftec, 
		       a.idordentrabajo, 
		       a.nombreparte, 
		       a.cantidad, 
		       a.material, 
		       a.criterio, 
		       a.reparacion, 
		       a.plano,
		       cast('' as varchar),
		       false,
		       cast(a.idcomponente as bigint) ,
		       cast(coalesce(b.nombrecomponente, '') as varchar),
		       cast(a.idmaterial as bigint),
		       cast(coalesce(c.nombrematerial, '') as varchar),
		       a.usuariocreacion, 
		       a.fechacreacion,
		       a.indicefila,
		       a.idcriterioevaluacion,
		       a.nombrezona,
		       false
		  FROM traking.mct_checklistinftecinicial a
		  left join mct_componente b on cast(a.idcomponente as bigint) = b.idcomponente
		  left join mct_material c   on cast(a.idmaterial as bigint) = c.idmaterial
	     WHERE a.idordentrabajo = idworkorders
      order by a.indicecarga asc;

END;
$$;


