CREATE FUNCTION traking.listchecklistinftecfundcab(iordentrabajos bigint) RETURNS TABLE(idchecklistinftecfundcab bigint, idordentrabajo bigint, idcliente bigint, nombrecliente character varying, idproducto bigint, nombreproducto character varying, idtipoorden bigint, nombretipoorden character varying, idfamilia bigint, nombrefamilia character varying, idusuario bigint, nombreusuario character varying, usercreate character varying, datecreate timestamp without time zone, userupdate character varying, dateupdate timestamp without time zone, linedesignname character varying, qrcode character varying, fechafundicion character varying)
    LANGUAGE plpgsql
    AS $$
declare
	sp_revision		bigint;
BEGIN
		  
	    RETURN QUERY

		SELECT d.idchecklistinftecfundcab ,
			   d.idordentrabajo  ,
			   a.idcliente ,
			   f.nombrecliente  ,
			   a.idproducto ,
			   a.nombreordentrabajo ,
			   a.idtipoorden ,
			   g.nombretipoorden ,
			   a.idfamilia ,
			   h.nombrefamilia ,
			   a.idusuario ,
			   e.nombre  ,
			   d.usuariocreacion ,
			   d.fechacreacion ,
			   d.usuariomodificacion ,
			   d.fechamodificacion,
			   cast(case
	          		when a.idlineadiseno = 1 then 'DE DISEÑO'
	          		when a.idlineadiseno = 2 then 'DE LÍNEA'
	          		when a.idlineadiseno = 3 then 'COMERCIAL'	          
	           end as varchar),
	           d.codigoqr ,
	           cast(to_char(a.fechaentrega - interval '21 days','dd-mm-yyyy') as varchar)
		  FROM traking.mct_ordentrabajo a
		  left join traking.mct_checklistinftecfundcab d  on a.idordentrabajo = d.idordentrabajo 
		  left join traking.mct_usuario e                 on a.idusuario = e.idusuario 
		  left join traking.mct_cliente f                 on a.idcliente = f.idcliente 
		  left join traking.mct_tipoorden g				  on g.idtipoorden = a.idtipoorden 
		  left join traking.mct_familia h				  on h.idfamilia = a.idfamilia 
	     WHERE a.idordentrabajo  = iordentrabajos ;
     
END;
$$;


ALTER FUNCTION traking.listchecklistinftecfundcab(iordentrabajos bigint) OWNER TO postgres;

--
-- TOC entry 935 (class 1255 OID 17692)
-- Name: listchecklistinftecfunddet(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listchecklistinftecfunddet(idchecklistinftecfundcabs bigint) RETURNS TABLE(idchecklistinftecfunddet bigint, idchecklistinftecfundcab bigint, idordentrabajo bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, idcomponente bigint, componentegenerico character varying, idmaterial bigint, materialgenerico character varying, idesmecanizado bigint, nombreesmecanizado character varying, idcriterioevaluacion bigint, nombrezona character varying, pesocomponente numeric, idpadre bigint, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

	SELECT a.idchecklistinftecfunddet, 
	       a.idchecklistinftecfundcab, 
	       d.idordentrabajo ,
	       a.nombreparte, 
	       a.cantidad, 
	       a.material, 
	       a.criterio, 
	       a.reparacion, 
	       a.plano, 
	       a.idcomponente, 
	       b.nombrecomponente ,
	       a.idmaterial, 
	       c.nombrematerial ,
	       a.idesmecanizado, 
	       case
		       when a.idesmecanizado = 1 then
		            cast('SI' as varchar)
		       else
		            cast('NO' as varchar)
		   end,
	       a.idcriterioevaluacion, 
	       a.nombrezona, 
	       a.pesocomponente ,
	       a.idpadre,
	       a.fechacreacion,
	       a.usuariocreacion, 
	       a.fechamodificacion, 
	       a.usuariomodificacion
	  FROM traking.mct_checklistinftecfunddet a
	  left join traking.mct_componente b             on a.idcomponente = b.idcomponente 
	  left join traking.mct_material   c             on a.idmaterial = c.idmaterial 
	  left join traking.mct_checklistinftecfundcab d on a.idchecklistinftecfundcab = d.idchecklistinftecfundcab 
	 where a.idchecklistinftecfundcab = idchecklistinftecfundcabs
	order by a.idchecklistinftecfunddet asc;

END;
$$;


ALTER FUNCTION traking.listchecklistinftecfunddet(idchecklistinftecfundcabs bigint) OWNER TO postgres;

--
-- TOC entry 2178 (class 1255 OID 17693)
-- Name: listchecklistinftecparamcab(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listchecklistinftecparamcab(idclientes bigint, planos character varying) RETURNS TABLE(idchecklistinftecparamcab bigint, idcustomer bigint, generalplan character varying, revision bigint, usercreate character varying, datecreate timestamp without time zone, userupdate character varying, dateupdate timestamp without time zone, checklistvalidado boolean, idmodelo bigint, nombremodelo character varying)
    LANGUAGE plpgsql
    AS $$
declare
	sp_revision		bigint;
BEGIN


	RETURN QUERY
		SELECT a.idchecklistinftecparamcab ,
			   a.idcliente ,
			   a.planogeneral ,
			   coalesce (cast(max(b.idrevisionchecklistparam) as bigint), 0),
			   a.usuariocreacion ,
			   a.fechacreacion ,
			   a.usuariomodificacion ,
			   a.fechamodificacion ,
			   a.checklistvalidado ,
			   a.idmodelo ,
			   c.nombremodelo 
		  FROM traking.mct_checklistinftecparamcab a
		  left join traking.mct_revisionchecklistparam b on a.idchecklistinftecparamcab = b.idchecklistinftecparamcab
		  left join traking.mct_modelo c 				 on c.idmodelo  = a.idmodelo 
	     WHERE a.idcliente = idclientes
	       and a.planogeneral = planos
	     group by a.idchecklistinftecparamcab, c.nombremodelo ;
     
END;
$$;


ALTER FUNCTION traking.listchecklistinftecparamcab(idclientes bigint, planos character varying) OWNER TO postgres;

--
-- TOC entry 1526 (class 1255 OID 17694)
-- Name: listchecklistinftecparamdet(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listchecklistinftecparamdet(idchecklistinftecparamcabs bigint, idworkorders bigint) RETURNS TABLE(idchecklistinftecparamdet bigint, idchecklistinftecparamcab bigint, idcustomer bigint, generalplan character varying, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, idcomponente bigint, componentegenerico character varying, idmaterial bigint, materialgenerico character varying, idesmecanizado bigint, nombreesmecanizado character varying, idcriterioevaluacion bigint, nombrezona character varying, pesocomponente numeric, idpadre bigint, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idworkorders > 0) then

		INSERT INTO traking.mct_checklistinftecinicial
				(
				idchecklistinftec, 
				idchecklistinftecparamdet,
				idordentrabajo, 
				nombreparte, 
				cantidad, 
				material, 
				criterio, 
				reparacion, 
				plano, 
				indicefila,
				codigoqr,
				tipotrabajostd,
				muestrachecklist ,
				flagpantallafacturacion ,
				idcriterioevaluacion,
				nombrezona,
				usuariocreacion, 
				fechacreacion, 	
				idcomponente ,
				idmaterial ,
				idesmecanizado 
				)
		select nextval('mct_checklistinftecinicial_seq'),
		       d.idchecklistinftecparamdet ,
		       idworkorders,
		       d.nombreparte ,
		       d.cantidad ,
		       d.material ,
		       d.criterio ,
		       d.reparacion ,
		       d.plano ,
		       ROW_NUMBER() OVER (ORDER BY d.idchecklistinftecparamdet asc) AS indicefila,
		       case 
			       when ( upper(d.criterio) not in  ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO', 'STOCK_CC', 'RPO_SM') ) then
			            idworkorders||'OTROS'
			       else
			            idworkorders||upper(d.criterio)
			   end ,
    
		       --idworkorders||upper(d.criterio),
		       --upper(d.criterio),
		       case 
			       when ( upper(d.criterio) not in  ('FAB_FU', 'FAB_PA', 'FAB_CA', 'RPO', 'STOCK_CC', 'RPO_SM') ) then
			            'OTROS'
			       else
			            upper(d.criterio)
			   end ,
		       true as muestrachecklist,
		       true as flagpantallafacturacion,
		       d.idcriterioevaluacion ,
		       d.nombrezona ,
		       d.usuariocreacion ,
		       d.fechacreacion ,
		       d.idcomponente,
		       d.idmaterial ,
		       2 as esmecanizado
		  from mct_ordentrabajo a
		  left join mct_producto b                on b.idproducto = a.idproducto 
		  left join mct_checklistinftecparamcab c on c.planogeneral = b.planogeneral 
		  left join mct_checklistinftecparamdet d on d.idchecklistinftecparamcab = c.idchecklistinftecparamcab
		  left join mct_componente e              on e.idcomponente = d.idcomponente 
		  left join mct_material f                on f.idmaterial = d.idmaterial 
		 where a.idordentrabajo = idworkorders
      order by d.idpadre asc, d.idchecklistinftecparamdet asc;
	
		
		INSERT INTO traking.mct_checklistinftec
					(
						idchecklistinftec, 
						idchecklistinftecparamdet,
						idordentrabajo, 
						nombreparte, 
						cantidad, 
						material, 
						criterio, 
						reparacion, 
						plano, 
						indicefila,
						codigoqr,
						tipotrabajostd,
						muestrachecklist ,
						flagpantallafacturacion ,
						idcriterioevaluacion,
						nombrezona,
						usuariocreacion, 
						fechacreacion, 	
						idcomponente ,
						idmaterial ,
						idesmecanizado ,
						nombrecomponente ,
						nombrematerial 
					)
			 select nextval('mct_checklistinftec_seq'),
					a.idchecklistinftecparamdet,
					a.idordentrabajo, 
					a.nombreparte, 
					a.cantidad, 
					a.material, 
					a.criterio, 
					a.reparacion, 
					a.plano, 
					a.indicefila,
					a.codigoqr,
					a.tipotrabajostd,
					a.muestrachecklist ,
					a.flagpantallafacturacion ,
					a.idcriterioevaluacion,
					a.nombrezona,
					a.usuariocreacion, 
					a.fechacreacion, 	
					a.idcomponente ,
					a.idmaterial ,
					a.idesmecanizado ,
					b.nombrecomponente ,
					c.nombrematerial 
			   from mct_checklistinftecinicial a
			   left join mct_componente b  on b.idcomponente = a.idcomponente 
		       left join mct_material c    on c.idmaterial = a.idmaterial 
			  where idordentrabajo = idworkorders;

			 update mct_checklistinftec as zz
			    set idpadre = idchecklistinftec 
			  where zz.idordentrabajo = idworkorders
			    and zz.idpadre = 0;
		
	end if;

		
    RETURN QUERY

	SELECT a.idchecklistinftecparamdet, 
	       a.idchecklistinftecparamcab, 
	       d.idcliente ,
	       d.planogeneral ,
	       a.nombreparte, 
	       a.cantidad, 
	       a.material, 
	       a.criterio, 
	       a.reparacion, 
	       a.plano, 
	       a.idcomponente, 
	       b.nombrecomponente ,
	       a.idmaterial, 
	       c.nombrematerial ,
	       a.idesmecanizado, 
	       case
		       when a.idesmecanizado = 1 then
		            cast('SI' as varchar)
		       else
		            cast('NO' as varchar)
		   end,
	       a.idcriterioevaluacion, 
	       a.nombrezona, 
	       a.pesocomponente ,
	       a.idpadre,
	       a.fechacreacion,
	       a.usuariocreacion, 
	       a.fechamodificacion, 
	       a.usuariomodificacion
	  FROM traking.mct_checklistinftecparamdet a
	  left join traking.mct_componente b on a.idcomponente = b.idcomponente 
	  left join traking.mct_material   c on a.idmaterial = c.idmaterial 
	  left join traking.mct_checklistinftecparamcab d on a.idchecklistinftecparamcab = d.idchecklistinftecparamcab 
	 where a.idchecklistinftecparamcab = idchecklistinftecparamcabs
	order by a.idpadre asc, a.idchecklistinftecparamdet asc;

END;
$$;


ALTER FUNCTION traking.listchecklistinftecparamdet(idchecklistinftecparamcabs bigint, idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1406 (class 1255 OID 17696)
-- Name: listchecklistinftectrabajo(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listchecklistinftectrabajo(idworkorders bigint) RETURNS TABLE(qrcode character varying, sigla character varying, tipworkname character varying, iduser bigint, username character varying, requesdate character varying, idnotification bigint, codfileinfcoti character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_cantidad      integer;
   
begin
	
	select count(*)
	  into sp_cantidad
	  from mct_checklistinftec
	 where idordentrabajo = idworkorders
	   and (criterio = '' or criterio is null);

	if ( sp_cantidad = 0 ) then
	
		RETURN QUERY
	   	
		select *
		  from (
				select distinct a.codigoqr, 
				       b.sigla , 
				       b.nombretipotrabajo , 
				       b.idusuarioresp , 
				       c.nombre ,
				       cast(to_char(fecharequerida,'dd-mm-yyyy') as varchar),
				       b.idnotificacion ,
				       b.codigoarchivoinftecpdf 
				  from mct_checklistinftec a
				left join  mct_tipotrabajochecklist b on a.tipotrabajostd = b.sigla
				left join  mct_usuario c              on b.idusuarioresp = c.idusuario 
				where idordentrabajo = idworkorders
				  and b.codigoarchivoinftecpdf not in ('80')
		       union
				select distinct idworkorders||'DEVOLUCION', 
				       b.sigla , 
				       b.nombretipotrabajo , 
				       b.idusuarioresp , 
				       c.nombre ,
				       cast(to_char(fecharequerida,'dd-mm-yyyy') as varchar),
				       b.idnotificacion ,
				       b.codigoarchivoinftecpdf 
				  from mct_checklistinftec a
				left join  mct_tipotrabajochecklist b on b.sigla = 'DEVOLUCION'
				left join  mct_usuario c              on b.idusuarioresp = c.idusuario 
				where idordentrabajo = idworkorders
				  and a.devolucion = true
		  ) tabla
		  order by codigoarchivoinftecpdf;
	
	
	end if;
	
END;
$$;


ALTER FUNCTION traking.listchecklistinftectrabajo(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 2236 (class 1255 OID 17697)
-- Name: listchecklistinftectrabajosm(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listchecklistinftectrabajosm(idworkorders bigint) RETURNS TABLE(qrcode character varying, sigla character varying, tipworkname character varying, iduser bigint, username character varying, requesdate character varying, idnotification bigint, codfileinfcoti character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_cantidad      integer;
   
begin
	
	select count(*)
	  into sp_cantidad
	  from mct_checklistinftec
	 where idordentrabajo = idworkorders
	   and (criterio = '' or criterio is null);

	if ( sp_cantidad = 0 ) then
	
		RETURN QUERY
		
		select *
		  from (
				select distinct a.codigoqr, 
				       b.sigla , 
				       b.nombretipotrabajo , 
				       b.idusuarioresp , 
				       c.nombre ,
				       cast(to_char(fecharequerida,'dd-mm-yyyy') as varchar),
				       b.idnotificacion ,
				       b.codigoarchivoinftecpdf 
				  from mct_checklistinftec a
				left join  mct_tipotrabajochecklist b on a.tipotrabajostd = b.sigla
				left join  mct_usuario c              on b.idusuarioresp = c.idusuario 
				where idordentrabajo = idworkorders
				  and a.tipotrabajostd = 'RPO_SM'
				  and b.codigoarchivoinftecpdf = '80'
		  ) tabla
		  order by codigoarchivoinftecpdf;
	
	
	end if;
	
END;
$$;


