--
-- TOC entry 1496 (class 1255 OID 17700)
-- Name: listclientecom(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listclientecom() RETURNS TABLE(idclientecom bigint, nombreclientecom character varying, idareainteres bigint, nombreareainteres character varying, idparquebomba bigint, nombreparquebomba character varying, idtipoclientecom bigint, nombretipoclientecom character varying, status integer, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

        SELECT traking.mct_clientecom.idclientecom, 
               traking.mct_clientecom.nombreclientecom, 
               traking.mct_clientecom.idareainteres, 
               traking.mct_clientecom.nombreareainteres, 
               traking.mct_clientecom.idparquebomba,              
               traking.mct_clientecom.nombreparquebomba,              
               traking.mct_clientecom.idtipoclientecom, 
               traking.mct_tipoclientecom.nombretipoclientecom,
               traking.mct_clientecom.estado,
		       case 
				   when traking.mct_clientecom.estado = 1 then
				        cast('Activo' as varchar)
				   else 
				        cast('Inactivo' as varchar)
			   end as nombrestado,
               traking.mct_clientecom.fechacreacion,
               traking.mct_clientecom.usuariocreacion,
               traking.mct_clientecom.fechamodificacion,
               traking.mct_clientecom.usuariomodificacion
        FROM traking.mct_clientecom, 
             traking.mct_tipoclientecom
       where traking.mct_clientecom.idtipoclientecom = traking.mct_tipoclientecom.idtipoclientecom
    order by traking.mct_clientecom.nombreclientecom asc,
             traking.mct_clientecom.usuariocreacion asc;

END;
$$;


ALTER FUNCTION traking.listclientecom() OWNER TO postgres;

--
-- TOC entry 1150 (class 1255 OID 17701)
-- Name: listclientecomcontacto(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listclientecomcontacto(idclientecoms bigint) RETURNS TABLE(idclientecomcontacto bigint, idclientecom bigint, nombreclientecom character varying, nombrecontacto character varying, idcargo bigint, nombrecargo character varying, telefonocontacto character varying, email character varying, idtomadecision bigint, nombretomadecision character varying, status integer, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

        SELECT traking.mct_clientecomcontacto.idclientecomcontacto, 
               traking.mct_clientecomcontacto.idclientecom, 
               traking.mct_clientecom.nombreclientecom,
               traking.mct_clientecomcontacto.nombrecontacto, 
               traking.mct_clientecomcontacto.idcargo, 
               traking.mct_clientecomcontacto.nombrecargo, 
               traking.mct_clientecomcontacto.telefonocontacto,              
               traking.mct_clientecomcontacto.email,              
               traking.mct_clientecomcontacto.idtomadecision, 
               case 
				   when traking.mct_clientecomcontacto.idtomadecision = 1 then
				        cast('SI' as varchar)
				   else 
				        cast('NO' as varchar)
			   end as nombretomadecision,
               traking.mct_clientecomcontacto.estado,
		       case 
				   when traking.mct_clientecomcontacto.estado = 1 then
				        cast('Activo' as varchar)
				   else 
				        cast('Inactivo' as varchar)
			   end as nombrestado,
               traking.mct_clientecomcontacto.fechacreacion,
               traking.mct_clientecomcontacto.usuariocreacion,
               traking.mct_clientecomcontacto.fechamodificacion,
               traking.mct_clientecomcontacto.usuariomodificacion
        FROM traking.mct_clientecomcontacto
        left join traking.mct_clientecom on traking.mct_clientecom.idclientecom = traking.mct_clientecomcontacto.idclientecom
       where traking.mct_clientecomcontacto.idclientecom = idclientecoms
    order by traking.mct_clientecomcontacto.nombrecontacto asc;

END;
$$;


ALTER FUNCTION traking.listclientecomcontacto(idclientecoms bigint) OWNER TO postgres;

