-- Name: listclientecomcontactocombo(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listclientecomcontactocombo(clientes character varying, areas character varying) RETURNS TABLE(idclientecomcontacto bigint, idclientecom bigint, nombreclientecom character varying, nombrecontacto character varying, idcargo bigint, nombrecargo character varying, telefonocontacto character varying, email character varying, idtomadecision bigint, nombretomadecision character varying, status integer, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

	select traking.mct_clientecomcontacto.idclientecomcontacto, 
	       traking.mct_clientecomcontacto.idclientecom, 
	       traking.mct_clientecom.nombreclientecom,
	       traking.mct_clientecomcontacto.nombrecontacto, 
	       traking.mct_clientecomcontacto.idcargo, 
	       traking.mct_clientecomcontacto.nombrecargo, 
	       traking.mct_clientecomcontacto.telefonocontacto,              
	       traking.mct_clientecomcontacto.email,              
	       traking.mct_clientecomcontacto.idtomadecision, 
	       case 
			   when traking.mct_clientecomcontacto.idtomadecision = 1 then
			        cast('SI' as varchar)
			   else 
			        cast('NO' as varchar)
		   end as nombretomadecision,
	       traking.mct_clientecomcontacto.estado,
	       case 
			   when traking.mct_clientecomcontacto.estado = 1 then
			        cast('Activo' as varchar)
			   else 
			        cast('Inactivo' as varchar)
		   end as nombrestado,
	       traking.mct_clientecomcontacto.fechacreacion,
	       traking.mct_clientecomcontacto.usuariocreacion,
	       traking.mct_clientecomcontacto.fechamodificacion,
	       traking.mct_clientecomcontacto.usuariomodificacion
	  from traking.mct_clientecom
	  left join traking.mct_clientecomcontacto on traking.mct_clientecomcontacto.idclientecom = traking.mct_clientecom.idclientecom
	 where traking.mct_clientecom.nombreclientecom = clientes
	   and traking.mct_clientecom.nombreareainteres = areas
	 order by traking.mct_clientecomcontacto.nombrecontacto asc;

END;
$$;


ALTER FUNCTION traking.listclientecomcontactocombo(clientes character varying, areas character varying) OWNER TO postgres;

