CREATE FUNCTION traking.listcomponent() RETURNS TABLE(idcomponent bigint, componentname character varying, directevaluation bigint, boleanname character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_componente.idcomponente , 
               traking.mct_componente.nombrecomponente , 
               traking.mct_componente.evaluaciondirecta ,
               traking.mct_boleano.nombreboleano, 
               traking.mct_componente.estado,
               traking.mct_estado.nombreestado,  
               traking.mct_componente.fechacreacion,
               traking.mct_componente.usuariocreacion,
               traking.mct_componente.fechamodificacion,
               traking.mct_componente.usuariomodificacion
        FROM traking.mct_componente
        left join traking.mct_estado on traking.mct_componente.estado=traking.mct_estado.idestado
        left join traking.mct_boleano on traking.mct_componente.evaluaciondirecta = traking.mct_boleano.idboleano 
        --where traking.mct_componente.estado in ( 1, 2 )
        where traking.mct_componente.estado in ( 2 )
              order by 1 desc;

END;
$$;


