--

CREATE FUNCTION traking.listcomponenteevafoto(idusers bigint) RETURNS TABLE(idcomponenteevafoto bigint, nombrecomponenteevafoto character varying, status bigint, cantidad bigint, tienedetalle boolean, orden bigint, aplicavtp boolean, aplicahr boolean, aplicaha boolean, aplicahv boolean)
    LANGUAGE plpgsql
    AS $$
Declare

	sp_usuario				varchar;
    sp_idoperador			bigint;
    sp_nombreoperador		varchar;
    sp_idperfil				bigint;
    sp_idseccionprincipal	bigint;
    sp_nombreseccion		varchar;
    sp_idcargo				bigint;
    sp_idareaapp			bigint;
    sp_nombrearea			varchar;
    sp_idseccionapp			bigint;
    sp_idcargoapp			bigint;
    sp_nombrecargo			varchar;

BEGIN

		select a.usuario,
		       b.idoperador,
		       b.nombreoperador,
		       b.idperfil,
		       b.idseccionprincipal,
		       c.nombreseccion,
		       b.idcargo,
		       b.idareaapp,
		       d.nombrearea,
		       b.idseccionapp,
		       b.idcargoapp,
		       e.nombrecargo
		  into sp_usuario,
		       sp_idoperador,
		       sp_nombreoperador,
		       sp_idperfil,
		       sp_idseccionprincipal,
		       sp_nombreseccion,
		       sp_idcargo,
		       sp_idareaapp,
		       sp_nombrearea,
		       sp_idseccionapp,
		       sp_idcargoapp,
		       sp_nombrecargo
		  from mct_usuario a
		  left join mct_operador b on a.rut = b.rut||'-'||b.digito
		  left join mct_seccion c on b.idseccionprincipal = c.idseccion
		  left join mct_area d on b.idareaapp = d.idarea
		  left join mct_cargo e on b.idcargoapp = e.idcargo
		  left join mct_seccion f on b.idseccionapp = f.idseccion
		 where idusuario = idusers;

	if ( idusers = 5 ) then

	    RETURN QUERY
	
	    SELECT a.idcomponenteevafoto , 
	           a.nombrecomponenteevafoto,
               a.estado,
               a.cantidad,
               a.tienedetalle,
               a.orden,
               a.aplicavtp,
               a.aplicahr,
               a.aplicaha,
               a.aplicahv
	      FROM traking.mct_componenteevafoto a
	     where a.estado = 1
         order by a.orden asc;

	elsif ( idusers = 91 ) then

	    RETURN QUERY
	
	    SELECT a.idcomponenteevafoto , 
	           a.nombrecomponenteevafoto,
               a.estado,
               a.cantidad,
               a.tienedetalle,
               a.orden,
               a.aplicavtp,
               a.aplicahr,
               a.aplicaha,
               a.aplicahv
	      FROM traking.mct_componenteevafoto a
	     where a.estado = 1
         order by a.orden asc;

	elsif (sp_idareaapp = 7) then

	    RETURN QUERY
	
	    SELECT a.idcomponenteevafoto , 
	           a.nombrecomponenteevafoto,
               a.estado,
               a.cantidad,
               a.tienedetalle,
               a.orden,
               a.aplicavtp,
               a.aplicahr,
               a.aplicaha,
               a.aplicahv
	      FROM traking.mct_componenteevafoto a
	     where a.estado = 1
         order by a.orden asc;

	elsif (sp_idareaapp = 6) then

	    RETURN QUERY
	
	    SELECT a.idcomponenteevafoto , 
	           a.nombrecomponenteevafoto,
               a.estado,
               a.cantidad,
               a.tienedetalle,
               a.orden,
               a.aplicavtp,
               a.aplicahr,
               a.aplicaha,
               a.aplicahv
	      FROM traking.mct_componenteevafoto a
	     where a.estado = 1
         order by a.orden asc;

	elsif (sp_idareaapp = 3) then

	    RETURN QUERY
	
	    SELECT a.idcomponenteevafoto , 
	           a.nombrecomponenteevafoto,
               a.estado,
               a.cantidad,
               a.tienedetalle,
               a.orden,
               a.aplicavtp,
               a.aplicahr,
               a.aplicaha,
               a.aplicahv
	      FROM traking.mct_componenteevafoto a
	     where a.estado = 1
         order by a.orden asc;

	elsif (sp_idareaapp = 2) then

	    RETURN QUERY
	
	    SELECT a.idcomponenteevafoto , 
	           a.nombrecomponenteevafoto,
               a.estado,
               a.cantidad,
               a.tienedetalle,
               a.orden,
               a.aplicavtp,
               a.aplicahr,
               a.aplicaha,
               a.aplicahv
	      FROM traking.mct_componenteevafoto a
	     where a.estado = 1
         order by a.orden asc;

	end if;

END;
$$;


ALTER FUNCTION traking.listcomponenteevafoto(idusers bigint) OWNER TO postgres;

--
-- TOC entry 1085 (class 1255 OID 17706)
-- Name: listcomponenteevafoto(bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomponenteevafoto(idusers bigint, tipos character varying, idcategoriai bigint) RETURNS TABLE(idcomponenteevafoto bigint, nombrecomponenteevafoto character varying, status bigint, cantidad bigint, tienedetalle boolean, orden bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE

    sp_usuario              varchar;
    sp_idoperador           bigint;
    sp_nombreoperador       varchar;
    sp_idperfil             bigint;
    sp_idseccionprincipal   bigint;
    sp_nombreseccion        varchar;
    sp_idcargo              bigint;
    sp_idareaapp            bigint;
    sp_nombrearea           varchar;
    sp_idseccionapp         bigint;
    sp_idcargoapp           bigint;
    sp_nombrecargo          varchar;

BEGIN

    SELECT a.usuario,
           b.idoperador,
           b.nombreoperador,
           b.idperfil,
           b.idseccionprincipal,
           c.nombreseccion,
           b.idcargo,
           b.idareaapp,
           d.nombrearea,
           b.idseccionapp,
           b.idcargoapp,
           e.nombrecargo
      INTO sp_usuario,
           sp_idoperador,
           sp_nombreoperador,
           sp_idperfil,
           sp_idseccionprincipal,
           sp_nombreseccion,
           sp_idcargo,
           sp_idareaapp,
           sp_nombrearea,
           sp_idseccionapp,
           sp_idcargoapp,
           sp_nombrecargo
      FROM mct_usuario a
      LEFT JOIN mct_operador b ON a.rut = b.rut || '-' || b.digito
      LEFT JOIN mct_seccion c ON b.idseccionprincipal = c.idseccion
      LEFT JOIN mct_area d ON b.idareaapp = d.idarea
      LEFT JOIN mct_cargo e ON b.idcargoapp = e.idcargo
      LEFT JOIN mct_seccion f ON b.idseccionapp = f.idseccion
     WHERE a.idusuario = idusers;

    IF (
        idusers IN (5, 91, 31, 105, 27, 6, 19, 140, 119)
        OR sp_idareaapp IN (2, 3, 6, 7)
    ) THEN

 RETURN QUERY
SELECT a.idcomponenteevafoto,
       a.nombrecomponenteevafoto,
       a.estado,
       CASE
           WHEN idcategoriai = 33 THEN COALESCE(a.cantidadmaximaespesores, a.cantidad)
           WHEN idcategoriai = 32 THEN COALESCE(a.cantidadmaximamaterialidad, a.cantidad)
           WHEN idcategoriai = 39 THEN COALESCE(a.cantidadmaximaend, a.cantidad)
           ELSE a.cantidad
       END AS cantidad,
       CASE
           WHEN upper(trim(tipos)) = 'HA'  THEN COALESCE(a.tienedetalleha, false)
           WHEN upper(trim(tipos)) = 'HR'  THEN COALESCE(a.tienedetallehr, false)
           WHEN upper(trim(tipos)) = 'HV'  THEN COALESCE(a.tienedetallehv, false)
           WHEN upper(trim(tipos)) = 'VTP' THEN COALESCE(a.tienedetallevtp, false)
           ELSE COALESCE(a.tienedetalle, false)
       END AS tienedetalle,
       a.orden
  FROM traking.mct_componenteevafoto a
 WHERE a.estado = 1
   AND (
            tipos IS NULL
         OR trim(tipos) = ''
         OR (upper(trim(tipos)) = 'HA'  AND a.aplicaha IS TRUE)
         OR (upper(trim(tipos)) = 'HR'  AND a.aplicahr IS TRUE)
         OR (upper(trim(tipos)) = 'HV'  AND a.aplicahv IS TRUE)
         OR (upper(trim(tipos)) = 'VTP' AND a.aplicavtp IS TRUE)
       )
 ORDER BY
       CASE
           WHEN upper(trim(tipos)) = 'HA'  THEN COALESCE(a.ordenha, a.orden)
           WHEN upper(trim(tipos)) = 'HR'  THEN COALESCE(a.ordenhr, a.orden)
           WHEN upper(trim(tipos)) = 'HV'  THEN COALESCE(a.ordenhv, a.orden)
           WHEN upper(trim(tipos)) = 'VTP' THEN COALESCE(a.ordenvtp, a.orden)
           ELSE a.orden
       END ASC;

    END IF;

END;
$$;


ALTER FUNCTION traking.listcomponenteevafoto(idusers bigint, tipos character varying, idcategoriai bigint) OWNER TO postgres;

