-- Name: listcomponenteevafotodetalle(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomponenteevafotodetalle(idcomponentes bigint) RETURNS TABLE(idcomponenteevafotodetalle bigint, idcomponenteevafoto bigint, nombrecomponenteevafotodetalle character varying, status bigint, orden bigint, cantidad bigint, cantidadcargada bigint)
    LANGUAGE plpgsql
    AS $$
Declare


BEGIN

	    RETURN QUERY
	
	    SELECT a.idcomponenteevafotodetalle,
               a.idcomponenteevafoto , 
	           a.nombrecomponenteevafotodetalle,
               a.estado,
               a.orden,
               b.cantidad,
               --cast(8 as bigint) as cantidadcargada
               (select count(*) from traking.mct_ordentrabajotipoadjunto b 
                 where b.idcomponenteevafoto = idcomponentes 
                   and b.idcomponenteevafotodetalle = a.idcomponenteevafotodetalle) as cantidadcargada
	      FROM traking.mct_componenteevafotodetalle a
          left join traking.mct_componenteevafoto b on a.idcomponenteevafoto = b.idcomponenteevafoto
	     where a.idcomponenteevafoto = idcomponentes
         order by a.orden asc;

END;
$$;


ALTER FUNCTION traking.listcomponenteevafotodetalle(idcomponentes bigint) OWNER TO postgres;

--
-- TOC entry 1337 (class 1255 OID 17708)
-- Name: listcomponenteevafotodetalle(bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomponenteevafotodetalle(idcomponentes bigint, idots bigint, idcategoriai bigint) RETURNS TABLE(idcomponenteevafotodetalle bigint, idcomponenteevafoto bigint, nombrecomponenteevafotodetalle character varying, status bigint, orden bigint, cantidad bigint, cantidadcargada bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    sp_tienedetalle boolean;
BEGIN

    SELECT COALESCE(a.tienedetalle, false)
      INTO sp_tienedetalle
      FROM traking.mct_componenteevafoto a
     WHERE a.idcomponenteevafoto = idcomponentes;

    /*
     * Caso 1: componente CON detalle
     */
    IF COALESCE(sp_tienedetalle, false) IS TRUE THEN

        RETURN QUERY
        SELECT a.idcomponenteevafotodetalle,
               a.idcomponenteevafoto,
               a.nombrecomponenteevafotodetalle,
               a.estado,
               a.orden,

               CASE
                   WHEN idcategoriai = 33 THEN COALESCE(b.cantidadmaximaespesores, b.cantidad)
                   WHEN idcategoriai = 32 THEN COALESCE(b.cantidadmaximamaterialidad, b.cantidad)
                   WHEN idcategoriai = 39 THEN COALESCE(b.cantidadmaximaend, b.cantidad)
                   ELSE b.cantidad
               END AS cantidad,

               (
                   SELECT COUNT(*)::bigint
                     FROM traking.mct_ordentrabajotipoadjunto x
                    WHERE x.idcomponenteevafoto = idcomponentes
                      AND x.idcomponenteevafotodetalle = a.idcomponenteevafotodetalle
                      AND x.idordentrabajo = idots
                      AND x.idcategoriaadjunto = idcategoriai
               ) AS cantidadcargada

          FROM traking.mct_componenteevafotodetalle a
          LEFT JOIN traking.mct_componenteevafoto b
                 ON a.idcomponenteevafoto = b.idcomponenteevafoto
         WHERE a.idcomponenteevafoto = idcomponentes
         ORDER BY a.orden ASC;

    /*
     * Caso 2: componente SIN detalle
     * Devuelve una fila virtual para que Flutter pueda leer cantidad y cantidadcargada.
     */
    ELSE

        RETURN QUERY
        SELECT NULL::bigint AS idcomponenteevafotodetalle,
               b.idcomponenteevafoto,
               b.nombrecomponenteevafoto::character varying AS nombrecomponenteevafotodetalle,
               b.estado AS status,
               b.orden,

               CASE
                   WHEN idcategoriai = 33 THEN COALESCE(b.cantidadmaximaespesores, b.cantidad)
                   WHEN idcategoriai = 32 THEN COALESCE(b.cantidadmaximamaterialidad, b.cantidad)
                   WHEN idcategoriai = 39 THEN COALESCE(b.cantidadmaximaend, b.cantidad)
                   ELSE b.cantidad
               END AS cantidad,

               (
                   SELECT COUNT(*)::bigint
                     FROM traking.mct_ordentrabajotipoadjunto x
                    WHERE x.idcomponenteevafoto = idcomponentes
                      AND x.idordentrabajo = idots
                      AND x.idcategoriaadjunto = idcategoriai
                      AND (
                            x.idcomponenteevafotodetalle IS NULL
                            OR x.idcomponenteevafotodetalle = 0
                          )
               ) AS cantidadcargada

          FROM traking.mct_componenteevafoto b
         WHERE b.idcomponenteevafoto = idcomponentes;

    END IF;

END;
$$;


ALTER FUNCTION traking.listcomponenteevafotodetalle(idcomponentes bigint, idots bigint, idcategoriai bigint) OWNER TO postgres;

--
-- TOC entry 1569 (class 1255 OID 17709)
-- Name: listcomponenteevafotodetallecontipo(bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomponenteevafotodetallecontipo(idcomponentes bigint, idots bigint, idcategoriai bigint, tipos character varying) RETURNS TABLE(idcomponenteevafotodetalle bigint, idcomponenteevafoto bigint, nombrecomponenteevafotodetalle character varying, status bigint, orden bigint, cantidad bigint, cantidadcargada bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

    sp_tienedetalle    boolean;
    sp_cantidaddetalle bigint;

BEGIN

    /*
     * ==========================================================
     * 1. OBTENER CONFIGURACIÓN DEL COMPONENTE SEGÚN TIPO DE BOMBA
     * ==========================================================
     *
     * Importante:
     * Si la configuración específica del tipo está NULL,
     * debe utilizarse la configuración general tienedetalle.
     *
     * Esto debe coincidir exactamente con
     * traking.listcomponenteevafotov2.
     */
    SELECT
           CASE
               WHEN upper(trim(tipos)) = 'HA' THEN
                   COALESCE(
                       a.tienedetalleha,
                       a.tienedetalle,
                       false
                   )

               WHEN upper(trim(tipos)) = 'HR' THEN
                   COALESCE(
                       a.tienedetallehr,
                       a.tienedetalle,
                       false
                   )

               WHEN upper(trim(tipos)) = 'HV' THEN
                   COALESCE(
                       a.tienedetallehv,
                       a.tienedetalle,
                       false
                   )

               WHEN upper(trim(tipos)) = 'VTP' THEN
                   COALESCE(
                       a.tienedetallevtp,
                       a.tienedetalle,
                       false
                   )

               ELSE
                   COALESCE(
                       a.tienedetalle,
                       false
                   )
           END,

           /*
            * Número máximo de detalles aplicables según tipo.
            *
            * Si es mayor que cero, se retornan los primeros N.
            * Si es cero o NULL, se retornan todos los detalles.
            */
           CASE
               WHEN upper(trim(tipos)) = 'HA' THEN
                   COALESCE(a.cantidaddetalleha, 0)

               WHEN upper(trim(tipos)) = 'HR' THEN
                   COALESCE(a.cantidaddetallehr, 0)

               WHEN upper(trim(tipos)) = 'HV' THEN
                   COALESCE(a.cantidaddetallehv, 0)

               WHEN upper(trim(tipos)) = 'VTP' THEN
                   COALESCE(a.cantidaddetallevtp, 0)

               ELSE
                   0
           END

      INTO sp_tienedetalle,
           sp_cantidaddetalle

      FROM traking.mct_componenteevafoto a

     WHERE a.idcomponenteevafoto = idcomponentes;


    /*
     * ==========================================================
     * 2. COMPONENTE CON DETALLES
     * ==========================================================
     *
     * Ejemplo:
     * Rodete 1
     * Rodete 2
     * Rodete 3
     * Rodete 4
     */
    IF COALESCE(sp_tienedetalle, false) IS TRUE THEN

        RETURN QUERY

        SELECT
               a.idcomponenteevafotodetalle,

               a.idcomponenteevafoto,

               /*
                * Nombre del detalle según tipo de bomba.
                * Si el nombre específico está vacío, usa el general.
                */
               CASE
                   WHEN upper(trim(tipos)) = 'HA' THEN
                       COALESCE(
                           NULLIF(
                               trim(a.nombrecomponenteevafotodetalleha),
                               ''
                           ),
                           a.nombrecomponenteevafotodetalle
                       )

                   WHEN upper(trim(tipos)) = 'HR' THEN
                       COALESCE(
                           NULLIF(
                               trim(a.nombrecomponenteevafotodetallehr),
                               ''
                           ),
                           a.nombrecomponenteevafotodetalle
                       )

                   WHEN upper(trim(tipos)) = 'HV' THEN
                       COALESCE(
                           NULLIF(
                               trim(a.nombrecomponenteevafotodetallehv),
                               ''
                           ),
                           a.nombrecomponenteevafotodetalle
                       )

                   WHEN upper(trim(tipos)) = 'VTP' THEN
                       COALESCE(
                           NULLIF(
                               trim(a.nombrecomponenteevafotodetallevtp),
                               ''
                           ),
                           a.nombrecomponenteevafotodetalle
                       )

                   ELSE
                       a.nombrecomponenteevafotodetalle
               END::character varying
                   AS nombrecomponenteevafotodetalle,

               a.estado::bigint
                   AS status,

               a.orden::bigint
                   AS orden,

               /*
                * Máximo de fotografías permitido por cada detalle.
                */
               CASE
                   WHEN idcategoriai = 33 THEN
                       COALESCE(
                           b.cantidadmaximaespesores,
                           b.cantidad
                       )

                   WHEN idcategoriai = 32 THEN
                       COALESCE(
                           b.cantidadmaximamaterialidad,
                           b.cantidad
                       )

                   WHEN idcategoriai = 39 THEN
                       COALESCE(
                           b.cantidadmaximaend,
                           b.cantidad
                       )

                   ELSE
                       b.cantidad
               END::bigint
                   AS cantidad,

               /*
                * Conteo individual por detalle.
                *
                * Una foto de Rodete 1 solamente cuenta para
                * Rodete 1; no afecta Rodete 2, 3, etc.
                */
               (
                   SELECT COUNT(*)::bigint

                     FROM traking.mct_ordentrabajotipoadjunto x

                    WHERE x.idordentrabajo =
                          idots

                      AND x.idcategoriaadjunto =
                          idcategoriai

                      AND x.idcomponenteevafoto =
                          idcomponentes

                      AND x.idcomponenteevafotodetalle =
                          a.idcomponenteevafotodetalle
               ) AS cantidadcargada

          FROM traking.mct_componenteevafotodetalle a

          LEFT JOIN traking.mct_componenteevafoto b
                 ON b.idcomponenteevafoto =
                    a.idcomponenteevafoto

         WHERE a.idcomponenteevafoto =
               idcomponentes

         ORDER BY
               a.orden ASC,
               a.idcomponenteevafotodetalle ASC

         /*
          * Si el tipo configura una cantidad de detalles,
          * devuelve los primeros N.
          *
          * Si está en cero, no aplica límite.
          */
         LIMIT CASE
                   WHEN COALESCE(sp_cantidaddetalle, 0) > 0
                       THEN sp_cantidaddetalle

                   ELSE NULL
               END;


    /*
     * ==========================================================
     * 3. COMPONENTE SIN DETALLES
     * ==========================================================
     *
     * Devuelve una fila virtual para que Flutter pueda conocer:
     *
     * - cantidad máxima;
     * - cantidad cargada;
     * - información del componente.
     */
    ELSE

        RETURN QUERY

        SELECT
               0::bigint
                   AS idcomponenteevafotodetalle,

               b.idcomponenteevafoto,

               b.nombrecomponenteevafoto::character varying
                   AS nombrecomponenteevafotodetalle,

               b.estado::bigint
                   AS status,

               b.orden::bigint
                   AS orden,

               CASE
                   WHEN idcategoriai = 33 THEN
                       COALESCE(
                           b.cantidadmaximaespesores,
                           b.cantidad
                       )

                   WHEN idcategoriai = 32 THEN
                       COALESCE(
                           b.cantidadmaximamaterialidad,
                           b.cantidad
                       )

                   WHEN idcategoriai = 39 THEN
                       COALESCE(
                           b.cantidadmaximaend,
                           b.cantidad
                       )

                   ELSE
                       b.cantidad
               END::bigint
                   AS cantidad,

               (
                   SELECT COUNT(*)::bigint

                     FROM traking.mct_ordentrabajotipoadjunto x

                    WHERE x.idordentrabajo =
                          idots

                      AND x.idcategoriaadjunto =
                          idcategoriai

                      AND x.idcomponenteevafoto =
                          idcomponentes

                      AND (
                              x.idcomponenteevafotodetalle IS NULL
                           OR x.idcomponenteevafotodetalle = 0
                          )
               ) AS cantidadcargada

          FROM traking.mct_componenteevafoto b

         WHERE b.idcomponenteevafoto =
               idcomponentes;

    END IF;

END;

$$;


ALTER FUNCTION traking.listcomponenteevafotodetallecontipo(idcomponentes bigint, idots bigint, idcategoriai bigint, tipos character varying) OWNER TO postgres;

--
-- TOC entry 1200 (class 1255 OID 17711)
-- Name: listcomponenteevafotov2(bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomponenteevafotov2(idusers bigint, tipos character varying, idcategoriai bigint, idworkorderi character varying) RETURNS TABLE(idcomponenteevafoto bigint, nombrecomponenteevafoto character varying, status bigint, cantidad bigint, tienedetalle boolean, orden bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

    sp_usuario              varchar;
    sp_idoperador           bigint;
    sp_nombreoperador       varchar;
    sp_idperfil             bigint;
    sp_idseccionprincipal   bigint;
    sp_nombreseccion        varchar;
    sp_idcargo              bigint;
    sp_idareaapp            bigint;
    sp_nombrearea           varchar;
    sp_idseccionapp         bigint;
    sp_idcargoapp           bigint;
    sp_nombrecargo          varchar;

    sp_idordentrabajo       bigint;

BEGIN

    /*
     * ==========================================================
     * 1. CONVERTIR Y VALIDAR LA OT
     * ==========================================================
     */
    sp_idordentrabajo :=
        NULLIF(trim(idworkorderi), '')::bigint;

    /*
     * ==========================================================
     * 2. OBTENER DATOS DEL USUARIO
     * ==========================================================
     */
    SELECT a.usuario,
           b.idoperador,
           b.nombreoperador,
           b.idperfil,
           b.idseccionprincipal,
           c.nombreseccion,
           b.idcargo,
           b.idareaapp,
           d.nombrearea,
           b.idseccionapp,
           b.idcargoapp,
           e.nombrecargo

      INTO sp_usuario,
           sp_idoperador,
           sp_nombreoperador,
           sp_idperfil,
           sp_idseccionprincipal,
           sp_nombreseccion,
           sp_idcargo,
           sp_idareaapp,
           sp_nombrearea,
           sp_idseccionapp,
           sp_idcargoapp,
           sp_nombrecargo

      FROM mct_usuario a

      LEFT JOIN mct_operador b
             ON a.rut = b.rut || '-' || b.digito

      LEFT JOIN mct_seccion c
             ON b.idseccionprincipal = c.idseccion

      LEFT JOIN mct_area d
             ON b.idareaapp = d.idarea

      LEFT JOIN mct_cargo e
             ON b.idcargoapp = e.idcargo

      LEFT JOIN mct_seccion f
             ON b.idseccionapp = f.idseccion

     WHERE a.idusuario = idusers;

    /*
     * ==========================================================
     * 3. VALIDAR AUTORIZACIÓN DEL USUARIO
     * ==========================================================
     */
    IF (
        idusers IN (
            5,
            91,
            31,
            105,
            27,
            6,
            19,
            140,
            119
        )
        OR sp_idareaapp IN (
            2,
            3,
            6,
            7
        )
    ) THEN

        /*
         * ======================================================
         * 4. CONSTRUIR LISTADO BASE
         * ======================================================
         *
         * En este CTE calculamos una sola vez:
         *
         * - cantidad máxima;
         * - si tiene detalle según el tipo de bomba;
         * - orden según el tipo de bomba.
         */
        RETURN QUERY

        WITH componentes_base AS (

            SELECT
                a.idcomponenteevafoto,

                a.nombrecomponenteevafoto,

                a.estado::bigint
                    AS status_resultado,

                CASE
                    WHEN idcategoriai = 33 THEN
                        COALESCE(
                            a.cantidadmaximaespesores,
                            a.cantidad
                        )

                    WHEN idcategoriai = 32 THEN
                        COALESCE(
                            a.cantidadmaximamaterialidad,
                            a.cantidad
                        )

                    WHEN idcategoriai = 39 THEN
                        COALESCE(
                            a.cantidadmaximaend,
                            a.cantidad
                        )

                    ELSE
                        a.cantidad
                END::bigint
                    AS cantidad_resultado,

                CASE
    WHEN upper(trim(tipos)) = 'HA' THEN
        COALESCE(
            a.tienedetalleha,
            a.tienedetalle,
            false
        )

    WHEN upper(trim(tipos)) = 'HR' THEN
        COALESCE(
            a.tienedetallehr,
            a.tienedetalle,
            false
        )

    WHEN upper(trim(tipos)) = 'HV' THEN
        COALESCE(
            a.tienedetallehv,
            a.tienedetalle,
            false
        )

    WHEN upper(trim(tipos)) = 'VTP' THEN
        COALESCE(
            a.tienedetallevtp,
            a.tienedetalle,
            false
        )

    ELSE
        COALESCE(
            a.tienedetalle,
            false
        )
END AS tiene_detalle_resultado,

                a.orden::bigint
                    AS orden_resultado,

                CASE
                    WHEN upper(trim(tipos)) = 'HA' THEN
                        COALESCE(
                            a.ordenha,
                            a.orden
                        )

                    WHEN upper(trim(tipos)) = 'HR' THEN
                        COALESCE(
                            a.ordenhr,
                            a.orden
                        )

                    WHEN upper(trim(tipos)) = 'HV' THEN
                        COALESCE(
                            a.ordenhv,
                            a.orden
                        )

                    WHEN upper(trim(tipos)) = 'VTP' THEN
                        COALESCE(
                            a.ordenvtp,
                            a.orden
                        )

                    ELSE
                        a.orden
                END
                    AS orden_tipo

            FROM traking.mct_componenteevafoto a

            WHERE a.estado = 1

              /*
               * Aplicabilidad según tipo de bomba.
               */
              AND (
                       tipos IS NULL
                    OR trim(tipos) = ''

                    OR (
                        upper(trim(tipos)) = 'HA'
                        AND a.aplicaha IS TRUE
                    )

                    OR (
                        upper(trim(tipos)) = 'HR'
                        AND a.aplicahr IS TRUE
                    )

                    OR (
                        upper(trim(tipos)) = 'HV'
                        AND a.aplicahv IS TRUE
                    )

                    OR (
                        upper(trim(tipos)) = 'VTP'
                        AND a.aplicavtp IS TRUE
                    )
              )
        )

        SELECT
            componente.idcomponenteevafoto,

            componente.nombrecomponenteevafoto,

            componente.status_resultado
                AS status,

            componente.cantidad_resultado
                AS cantidad,

            componente.tiene_detalle_resultado
                AS tienedetalle,

            componente.orden_resultado
                AS orden

        FROM componentes_base componente

        WHERE

            /*
             * ==================================================
             * EXCEPCIÓN: COMPONENTE "OTRO"
             * ==================================================
             *
             * El ID 29 siempre debe permanecer disponible.
             */
            componente.idcomponenteevafoto = 29

            OR

            /*
             * ==================================================
             * COMPONENTES SIN DETALLE
             * ==================================================
             *
             * El componente se muestra solo si no posee ninguna
             * fotografía para:
             *
             * OT + categoría + componente.
             *
             * Desde la primera foto guardada, desaparece.
             */
            (
                componente.tiene_detalle_resultado IS FALSE

                AND NOT EXISTS (

                    SELECT 1

                    FROM traking.mct_ordentrabajotipoadjunto foto

                    WHERE foto.idordentrabajo =
                          sp_idordentrabajo

                      AND foto.idcategoriaadjunto =
                          idcategoriai

                      AND foto.idcomponenteevafoto =
                          componente.idcomponenteevafoto
                )
            )

            OR

            /*
             * ==================================================
             * COMPONENTES CON DETALLE
             * ==================================================
             *
             * El componente permanece visible mientras exista
             * al menos un detalle activo que todavía no tenga
             * fotografías.
             *
             * Ejemplo:
             *
             * Rodete 1 registrado
             * Rodete 2 pendiente
             * Rodete 3 pendiente
             *
             * Resultado:
             * "Rodete" continúa apareciendo.
             */
            (
                componente.tiene_detalle_resultado IS TRUE

                AND EXISTS (

                    SELECT 1

                    FROM traking.mct_componenteevafotodetalle detalle

                    WHERE detalle.idcomponenteevafoto =
                          componente.idcomponenteevafoto

                      AND detalle.estado = 1

                      /*
                       * El detalle está pendiente cuando no existe
                       * ninguna fotografía registrada específicamente
                       * para ese detalle.
                       */
                      AND NOT EXISTS (

                          SELECT 1

                          FROM traking.mct_ordentrabajotipoadjunto foto

                          WHERE foto.idordentrabajo =
                                sp_idordentrabajo

                            AND foto.idcategoriaadjunto =
                                idcategoriai

                            AND foto.idcomponenteevafoto =
                                componente.idcomponenteevafoto

                            AND foto.idcomponenteevafotodetalle =
                                detalle.idcomponenteevafotodetalle
                      )
                )
            )

        ORDER BY
            componente.orden_tipo ASC,
            componente.orden_resultado ASC;

    END IF;

END;

$$;


ALTER FUNCTION traking.listcomponenteevafotov2(idusers bigint, tipos character varying, idcategoriai bigint, idworkorderi character varying) OWNER TO postgres;

