--
-- TOC entry 1082 (class 1255 OID 17716)
-- Name: listcomproadmaptempbyot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomproadmaptempbyot(idworkorders bigint) RETURNS TABLE(idroadmaptemp bigint, idworkorder bigint, idpartworkorder bigint, idcomponent bigint, componentname character varying, idmaterial bigint, materialname character varying, blueprintname character varying, quantity bigint, roadmapcode character varying, aditionaltext character varying, idworkhr bigint, workhr character varying, itemcorr bigint, idimprimehojas bigint, imprimehojasname character varying, idboleano bigint, boleanoname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
-- tabla de detalle del modal
	select a.idhojarutatemp ,
	       a.idordentrabajo ,
	       a.idordentrabajoparte ,
	       a.idcomponente ,
	       b.nombrecomponente ,
	       a.idmaterial ,
	       a.nombrematerial ,
	       a.nombreplano ,
	       a.cantidad ,
	       a.codhojaruta ,
	       a.textoadicional ,
	       a.idtrabajohr ,
	       cast(case
	          when a.idtrabajohr = 1 then 'FABRICACIÓN'
	          when a.idtrabajohr = 2 then 'RECUPERACIÓN'
	       end as varchar) as  imprimehojasname,
	       c.itemcorr,
	       a.idimprimehojas,
	       cast(case
	          when a.idimprimehojas = 1 then 'AGRUPADAS'
	          when a.idimprimehojas = 2 then 'INDIVIDUALES'
	       end as varchar) as  imprimehojasname,
	       a.idboleano,
	       d.nombreboleano 
	from mct_hojarutatemp a
	left join mct_componente b on a.idcomponente = b.idcomponente 
	left join mct_ordentrabajoparte c on a.idordentrabajoparte = c.idordentrabajoparte 
	left join mct_boleano d on a.idboleano = d.idboleano 		
	--left join mct_material   c on a.idmaterial = c.idmaterial 
	where a.idordentrabajo = idworkorders
	  and a.idperfil = 0
	order by a.idhojarutatemp ;
	
	END;
$$;


