--
-- TOC entry 998 (class 1255 OID 17718)
-- Name: listcomproadmaptempbyotcmbpieza(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomproadmaptempbyotcmbpieza(idareaclasificacions bigint) RETURNS TABLE(idcomponent bigint, componentname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

   if ( idareaclasificacions = -1 ) then -- esto aplica para cuando se carga el combo box desde hoja ruta pieza
	
	    RETURN QUERY
    
		select  a.idcomponente ,
		        a.nombrecomponente 
		from mct_componente a 
		where a.estado = 2
		  and (a.idareaclasificacion in (1,2,3,4,5)
		  )
		order by a.nombrecomponente;
	
	elsif ( idareaclasificacions = 99 ) then -- esto aplica para cuando se carga el combo box desde hoja ruta checklist
	
	    RETURN QUERY
    
--		select  a.idcomponente ,
--		        a.nombrecomponente 
--		from mct_componente a 
--		where a.estado = 2
--		  and (a.idareaclasificacion in (1,2,3,4,5)
--		  or a.idcomponente = 383)
--		order by a.nombrecomponente;
	
	    select * from ( 
		select  a.idcomponente ,
		        a.nombrecomponente 
		from mct_componente a 
		where a.estado = 2
		  and (a.idareaclasificacion in (1,2,3,4,5)
		  or a.idcomponente in(383))
		union
		select  a.idcomponente ,
		        a.nombrecomponente 
		from mct_componente a 
		where a.estado = 1
		  and a.idcomponente in (296,141,158,172,117,128,159, 136) ) as tabla
		order by 2;
	
	else
	
	    RETURN QUERY
    
		select  a.idcomponente ,
		        a.nombrecomponente 
		from mct_componente a 
		where a.estado = 2
		  and a.idareaclasificacion in (idareaclasificacions)
		order by a.nombrecomponente;
	
	end if;
	

END;
$$;


ALTER FUNCTION traking.listcomproadmaptempbyotcmbpieza(idareaclasificacions bigint) OWNER TO postgres;

--
-- TOC entry 1534 (class 1255 OID 17719)
-- Name: listcomproadmaptempchecklistbyot(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomproadmaptempchecklistbyot(idworkorders bigint, idclasificacions bigint) RETURNS TABLE(idroadmaptemp bigint, idworkorder bigint, idpartworkorder bigint, idcomponent bigint, componentname character varying, idmaterial bigint, materialname character varying, blueprintname character varying, quantity bigint, roadmapcode character varying, aditionaltext character varying, idcriterioevaluacion bigint, criterioevaluacionname character varying, itemcorr bigint, idimprimehojas bigint, imprimehojasname character varying, idboleano bigint, boleanoname character varying, materialchecklist character varying, componentechecklist character varying, nombrezona character varying, usercreate character varying, aplicahojaruta boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idclasificacions = 99 ) then
	
	    RETURN QUERY
	    
		-- tabla de detalle del modal
		select a.idhojarutatemp ,
		       a.idordentrabajo ,
		       a.idordentrabajoparte ,
		       a.idcomponente ,
		       b.nombrecomponente ,
		       a.idmaterial ,
		       a.nombrematerial ,
		       a.nombreplano ,
		       a.cantidad ,
		       a.codhojaruta ,
		       a.textoadicional ,
		       a.idcriterioevaluacion ,
		       --e.nombrecriterioevaluacion ,
		       e.alias ,
		       c.itemcorr,
		       a.idimprimehojas,
		       cast(case
		          when a.idimprimehojas = 1 then 'AGRUPADAS'
		          when a.idimprimehojas = 2 then 'INDIVIDUALES'
		       end as varchar) as  imprimehojasname,
		       a.idboleano,
		       d.nombreboleano,
		       coalesce (a.materialchecklist, 'No viene de Checklist') ,
		       coalesce (a.componentechecklist, 'No viene de Checklist') ,
		       coalesce(a.nombrezona,'') ,
		       a.usuariocreacion ,
		       a.aplicahojaruta 
		from mct_hojarutatemp a
		left join mct_componente b on a.idcomponente = b.idcomponente 
		left join mct_ordentrabajoparte c on a.idordentrabajoparte = c.idordentrabajoparte 
		left join mct_boleano d on a.idboleano = d.idboleano 		
		left join mct_criterioevaluacion e on a.idcriterioevaluacion = e.idcriterioevaluacion 
		--left join mct_material   c on a.idmaterial = c.idmaterial 
		where a.idordentrabajo = idworkorders
		  and a.idperfil = 0
		  and a.idareaclasificacion in (0,1,2,3,4,5)
		order by a.idhojarutatemp ;

	else
	
	    RETURN QUERY
	    
		-- tabla de detalle del modal
		select a.idhojarutatemp ,
		       a.idordentrabajo ,
		       a.idordentrabajoparte ,
		       a.idcomponente ,
		       b.nombrecomponente ,
		       a.idmaterial ,
		       a.nombrematerial ,
		       a.nombreplano ,
		       a.cantidad ,
		       a.codhojaruta ,
		       a.textoadicional ,
		       a.idcriterioevaluacion ,
		       --e.nombrecriterioevaluacion ,
		       e.alias ,
		       c.itemcorr,
		       a.idimprimehojas,
		       cast(case
		          when a.idimprimehojas = 1 then 'AGRUPADAS'
		          when a.idimprimehojas = 2 then 'INDIVIDUALES'
		       end as varchar) as  imprimehojasname,
		       a.idboleano,
		       d.nombreboleano,
		       coalesce (a.materialchecklist, 'No viene de Checklist') ,
		       coalesce (a.componentechecklist, 'No viene de Checklist')  ,
		       coalesce(a.nombrezona,'')   ,
		       a.usuariocreacion  ,
		       a.aplicahojaruta 
		from mct_hojarutatemp a
		left join mct_componente b on a.idcomponente = b.idcomponente 
		left join mct_ordentrabajoparte c on a.idordentrabajoparte = c.idordentrabajoparte 
		left join mct_boleano d on a.idboleano = d.idboleano 		
		left join mct_criterioevaluacion e on a.idcriterioevaluacion = e.idcriterioevaluacion 
		--left join mct_material   c on a.idmaterial = c.idmaterial 
		where a.idordentrabajo = idworkorders
		  and a.idperfil = 0
		  and a.idareaclasificacion in (0, idclasificacions )
		order by a.idhojarutatemp ;

	end if;

	
END;
$$;


ALTER FUNCTION traking.listcomproadmaptempchecklistbyot(idworkorders bigint, idclasificacions bigint) OWNER TO postgres;

