		left join mct_criterioevaluacion e on a.idcriterioevaluacion = e.idcriterioevaluacion 
		--left join mct_material   c on a.idmaterial = c.idmaterial 
		where a.idordentrabajo = idworkorders
		  and a.idperfil = 0
		  and a.idareaclasificacion in (8)
		  and a.componentechecklist is null
		  --and a.solicitudgenerada = false
		order by a.idhojarutatemp ;

	elseif ( idclasificacions = 88 ) then -- trae solo los que no han sido generados
	
	    RETURN QUERY
	    
		-- tabla de detalle del modal
		select a.idhojarutatemp ,
		       a.idordentrabajo ,
		       a.idordentrabajoparte ,
		       a.idcomponente ,
		       --b.nombrecomponente ,
			   cast(coalesce ( upper( coalesce(a.componentechecklist, b.nombrecomponente) )||' - '||a.textoadicional , b.nombrecomponente) as varchar),
		       a.idmaterial ,
		       a.nombrematerial ,
		       a.nombreplano ,
		       a.cantidad ,
		       a.codhojaruta ,
		       a.textoadicional ,
		       a.idcriterioevaluacion ,
		       --e.nombrecriterioevaluacion ,
		       e.alias ,
		       c.itemcorr,
		       a.idimprimehojas,
		       cast(case
		          when a.idimprimehojas = 1 then 'AGRUPADAS'
		          when a.idimprimehojas = 2 then 'INDIVIDUALES'
		       end as varchar) as  imprimehojasname,
		       a.idboleano,
		       d.nombreboleano ,
		       a.nombrezona 
		from mct_hojarutatemp a
		left join mct_componente b on a.idcomponente = b.idcomponente 
		left join mct_ordentrabajoparte c on a.idordentrabajoparte = c.idordentrabajoparte 
		left join mct_boleano d on a.idboleano = d.idboleano 		
		left join mct_criterioevaluacion e on a.idcriterioevaluacion = e.idcriterioevaluacion 
		--left join mct_material   c on a.idmaterial = c.idmaterial 
		where a.idordentrabajo = idworkorders
		  and a.idperfil = 0
		  and a.idareaclasificacion in (8)
		  and a.componentechecklist is null
		  and a.solicitudgenerada = false
		order by a.idhojarutatemp ;

	elseif ( idclasificacions = 99 ) then
	
	    RETURN QUERY
	    
		-- tabla de detalle del modal
		select a.idhojarutatemp ,
		       a.idordentrabajo ,
		       a.idordentrabajoparte ,
		       a.idcomponente ,
		       --b.nombrecomponente ,
			   cast(coalesce ( upper( coalesce(a.componentechecklist, b.nombrecomponente) )||' - '||a.textoadicional , b.nombrecomponente) as varchar),
		       a.idmaterial ,
		       a.nombrematerial ,
		       a.nombreplano ,
		       a.cantidad ,
		       a.codhojaruta ,
		       a.textoadicional ,
		       a.idcriterioevaluacion ,
		       --e.nombrecriterioevaluacion ,
		       e.alias ,
		       c.itemcorr,
		       a.idimprimehojas,
		       cast(case
		          when a.idimprimehojas = 1 then 'AGRUPADAS'
		          when a.idimprimehojas = 2 then 'INDIVIDUALES'
		       end as varchar) as  imprimehojasname,
		       a.idboleano,
		       d.nombreboleano ,
		       a.nombrezona 
		from mct_hojarutatemp a
		left join mct_componente b on a.idcomponente = b.idcomponente 
		left join mct_ordentrabajoparte c on a.idordentrabajoparte = c.idordentrabajoparte 
		left join mct_boleano d on a.idboleano = d.idboleano 		
		left join mct_criterioevaluacion e on a.idcriterioevaluacion = e.idcriterioevaluacion 
		--left join mct_material   c on a.idmaterial = c.idmaterial 
		where a.idordentrabajo = idworkorders
		  and a.idperfil = 0
		  and a.idareaclasificacion in (0,1,2,3,4,5)
		  and a.componentechecklist is null
		order by a.idhojarutatemp ;

	else
	
	    RETURN QUERY
	    
		-- tabla de detalle del modal
		select a.idhojarutatemp ,
		       a.idordentrabajo ,
		       a.idordentrabajoparte ,
		       a.idcomponente ,
		       --b.nombrecomponente ,
			   cast(coalesce ( upper( coalesce(a.componentechecklist, b.nombrecomponente) )||' - '||a.textoadicional , b.nombrecomponente) as varchar),
		       a.idmaterial ,
		       a.nombrematerial ,
		       a.nombreplano ,
		       a.cantidad ,
		       a.codhojaruta ,
		       a.textoadicional ,
		       a.idcriterioevaluacion ,
		       --e.nombrecriterioevaluacion ,
		       e.alias ,
		       c.itemcorr,
		       a.idimprimehojas,
		       cast(case
		          when a.idimprimehojas = 1 then 'AGRUPADAS'
		          when a.idimprimehojas = 2 then 'INDIVIDUALES'
		       end as varchar) as  imprimehojasname,
		       a.idboleano,
		       d.nombreboleano  ,
		       a.nombrezona 
		from mct_hojarutatemp a
		left join mct_componente b on a.idcomponente = b.idcomponente 
		left join mct_ordentrabajoparte c on a.idordentrabajoparte = c.idordentrabajoparte 
		left join mct_boleano d on a.idboleano = d.idboleano 		
		left join mct_criterioevaluacion e on a.idcriterioevaluacion = e.idcriterioevaluacion 
		--left join mct_material   c on a.idmaterial = c.idmaterial 
		where a.idordentrabajo = idworkorders
		  and a.idperfil = 0
		  and a.idareaclasificacion in (idclasificacions )
		order by a.idhojarutatemp ;

	end if;

	
END;
$$;


