--
-- TOC entry 2176 (class 1255 OID 17721)
-- Name: listcomproadmaptempsectionbyot(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listcomproadmaptempsectionbyot(idworkorders bigint, idprofiles bigint) RETURNS TABLE(idroadmaptemp bigint, idworkorder bigint, idpartworkorder bigint, idcomponent bigint, componentname character varying, idmaterial bigint, materialname character varying, blueprintname character varying, quantity bigint, roadmapcode character varying, aditionaltext character varying, idworkhr bigint, itemcorr bigint, idprofile bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
-- tabla de detalle del modal
	select a.idhojarutatemp ,
	       a.idordentrabajo ,
	       a.idordentrabajoparte ,
	       a.idcomponente ,
	       b.nombrecomponente ,
	       a.idmaterial ,
	       a.nombrematerial ,
	       a.nombreplano ,
	       a.cantidad ,
	       a.codhojaruta ,
	       a.textoadicional ,
	       a.idtrabajohr ,
	       c.itemcorr,
	       a.idperfil 
	from mct_hojarutatemp a
	left join mct_componente b on a.idcomponente = b.idcomponente 
	left join mct_ordentrabajoparte c on a.idordentrabajoparte = c.idordentrabajoparte 	
	--left join mct_material   c on a.idmaterial = c.idmaterial 
	where a.idordentrabajo = idworkorders
	  and a.idperfil = idprofiles
	order by a.idhojarutatemp ;
	
	END;
$$;


