CREATE FUNCTION traking.listcustomer() RETURNS TABLE(idcustomer bigint, dni character varying, customername character varying, phone character varying, address character varying, email character varying, iditem bigint, itemname character varying, idcountry bigint, countryname character varying, idcity bigint, cityname character varying, contact character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_cliente.idcliente, 
               traking.mct_cliente.rut, 
               traking.mct_cliente.nombrecliente, 
               traking.mct_cliente.telefono, 
               traking.mct_cliente.direccion, 
               traking.mct_cliente.email,              
               traking.mct_cliente.idrubro, 
               traking.mct_rubro.nombrerubro,               
               traking.mct_cliente.idpais, 
               traking.mct_pais.nombrepais,
               traking.mct_cliente.idciudad, 
               traking.mct_ciudad.nombreciudad,
               traking.mct_cliente.contacto ,
               traking.mct_cliente.estado,
               traking.mct_estado.nombreestado,  
               traking.mct_cliente.fechacreacion,
               traking.mct_cliente.usuariocreacion,
               traking.mct_cliente.fechamodificacion,
               traking.mct_cliente.usuariomodificacion
          FROM traking.mct_cliente, 
               traking.mct_estado,
               traking.mct_rubro,
               traking.mct_pais,
               traking.mct_ciudad
         where traking.mct_cliente.estado=traking.mct_estado.idestado
           and traking.mct_cliente.idrubro=traking.mct_rubro.idrubro
           and traking.mct_cliente.idpais=traking.mct_pais.idpais
           and traking.mct_cliente.idciudad=traking.mct_ciudad.idciudad
           and traking.mct_cliente.estado = 1
          order by traking.mct_cliente.nombrecliente;

END;
