--
-- TOC entry 1928 (class 1255 OID 17731)
-- Name: listdefectobysubsection(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listdefectobysubsection(idsubsections bigint) RETURNS TABLE(iddefecto bigint, namedefecto character varying, idsubsection bigint, namesubsection character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idsubsections = 999) then

	    RETURN QUERY
        SELECT traking.mct_defecto.iddefecto, 
               traking.mct_defecto.nombre,
               traking.mct_defecto.idsubseccion, 
               traking.mct_subseccion.nombresubseccion,
               traking.mct_defecto.estado,
               traking.mct_estado.nombreestado,
               traking.mct_defecto.fechacreacion,
               traking.mct_defecto.usuariocreacion,
               traking.mct_defecto.fechamodificacion,
               traking.mct_defecto.usuariomodificacion
        FROM traking.mct_defecto
        left join traking.mct_estado on traking.mct_defecto.estado=traking.mct_estado.idestado
        left join traking.mct_subseccion on traking.mct_defecto.idsubseccion=traking.mct_subseccion.idsubseccion
    WHERE traking.mct_defecto.idsubseccion = 999;
        --WHERE traking.mct_defecto.idsubseccion != 999;
	
	else
	
	    RETURN QUERY
        SELECT traking.mct_defecto.iddefecto, 
               traking.mct_defecto.nombre,
               traking.mct_defecto.idsubseccion, 
               traking.mct_subseccion.nombresubseccion,
               traking.mct_defecto.estado,
               traking.mct_estado.nombreestado,
               traking.mct_defecto.fechacreacion,
               traking.mct_defecto.usuariocreacion,
               traking.mct_defecto.fechamodificacion,
               traking.mct_defecto.usuariomodificacion
        FROM traking.mct_defecto
        left join traking.mct_estado on traking.mct_defecto.estado=traking.mct_estado.idestado
        left join traking.mct_subseccion on traking.mct_defecto.idsubseccion=traking.mct_subseccion.idsubseccion
    --WHERE traking.mct_defecto.idsubseccion  = idsubsections;
        WHERE traking.mct_defecto.idsubseccion != 999;
   
	end if;



END;
$$;


ALTER FUNCTION traking.listdefectobysubsection(idsubsections bigint) OWNER TO postgres;

--
-- TOC entry 1808 (class 1255 OID 17732)
-- Name: listdefectocausa(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listdefectocausa(iddefectofundicions bigint) RETURNS TABLE(iddefectocausa bigint, iddefectofundicion bigint, descripcion character varying, estado bigint, statusname character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying, pendientecarga boolean)
    LANGUAGE plpgsql
    AS $$
declare

	rec_trab       		RECORD;
	sp_totalrespaldos	bigint;
	sp_totalcargas		bigint;
    sp_pendientecarga	boolean;
   
BEGIN

	FOR rec_trab IN ( 

	        SELECT traking.mct_defectocausa.iddefectocausa , 
	               traking.mct_defectocausa.iddefectofundicion ,
	               traking.mct_defectocausa.descripcion , 
	               traking.mct_defectocausa.estado,
	               traking.mct_estado.nombreestado,
	               traking.mct_defectocausa.fechacreacion,
	               traking.mct_defectocausa.usuariocreacion,
	               traking.mct_defectocausa.fechamodificacion,
	               traking.mct_defectocausa.usuariomodificacion
	        FROM traking.mct_defectocausa, 
	             traking.mct_estado
	       where traking.mct_defectocausa.iddefectofundicion = iddefectofundicions
	         and traking.mct_defectocausa.estado = traking.mct_estado.idestado
	        order by 4 asc
          )
        loop 
        
		        iddefectocausa		:= rec_trab.iddefectocausa;
		        iddefectofundicion	:= rec_trab.iddefectofundicion;
		        descripcion			:= rec_trab.descripcion;
		        estado				:= rec_trab.estado;
		        statusname 			:= rec_trab.nombreestado;
		        fechacreacion 		:= rec_trab.fechacreacion;
		        usuariocreacion 	:= rec_trab.usuariocreacion;
		        fechamodificacion 	:= rec_trab.fechamodificacion;
		        usuariomodificacion := rec_trab.usuariomodificacion;
         
				select count(*)
				  into sp_totalrespaldos
				  from mct_defectocausaaccion a,
				       mct_defectocausaaccionpdf b
				 where a.iddefectocausa = rec_trab.iddefectocausa
				   and a.iddefectocausaaccion = b.iddefectocausaaccion ;
				 
				select count(*)
				  into sp_totalcargas
				  from mct_defectocausaaccion a,
				       mct_defectocausaaccionpdf b
				 where a.iddefectocausa = rec_trab.iddefectocausa
				   and a.iddefectocausaaccion = b.iddefectocausaaccion
				   and (length(tipo) > 0);
				
				        
		         pendientecarga	:= false;
		         if (sp_totalrespaldos > 0) then		
		             if (sp_totalcargas < sp_totalrespaldos ) then 
		                 pendientecarga	:= true;
		             end if;
		             
		         end if;  
    
		    	return next;
		    
        end loop;
        
		    
END;
$$;


ALTER FUNCTION traking.listdefectocausa(iddefectofundicions bigint) OWNER TO postgres;

--
-- TOC entry 1737 (class 1255 OID 17733)
-- Name: listdefectocausaaccion(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listdefectocausaaccion(iddefectocausas bigint) RETURNS TABLE(iddefectocausaaccion bigint, iddefectocausa bigint, descripcion character varying, fechaejecucion character varying, jsonresponsable character varying, estado bigint, statusname character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying, pendientecarga boolean)
    LANGUAGE plpgsql
    AS $$
declare

	rec_trab       		RECORD;
	sp_totalrespaldos	bigint;
	sp_totalcargas		bigint;
    sp_pendientecarga	boolean;

BEGIN

		   

	    FOR rec_trab IN (  

		        SELECT traking.mct_defectocausaaccion.iddefectocausaaccion , 
		        	   traking.mct_defectocausaaccion.iddefectocausa ,              
		               traking.mct_defectocausaaccion.descripcion , 
		               cast(to_char(traking.mct_defectocausaaccion.fechaejecucion, 'yyyy-mm-dd') as varchar)  as fechaejecucion,
		               traking.mct_defectocausaaccion.jsonresponsable  ,
		               traking.mct_defectocausaaccion.estado,
		               traking.mct_estado.nombreestado,
		               traking.mct_defectocausaaccion.fechacreacion,
		               traking.mct_defectocausaaccion.usuariocreacion,
		               traking.mct_defectocausaaccion.fechamodificacion,
		               traking.mct_defectocausaaccion.usuariomodificacion
		        FROM traking.mct_defectocausaaccion, 
		             traking.mct_estado
		       where traking.mct_defectocausaaccion.iddefectocausa = iddefectocausas
		         and traking.mct_defectocausaaccion.estado = traking.mct_estado.idestado
		        order by 4 asc	    
	    			   
	    	)
	    	loop
	   
		         iddefectocausaaccion	:= rec_trab.iddefectocausaaccion;
		         iddefectocausa			:= rec_trab.iddefectocausa;
		         descripcion			:= rec_trab.descripcion;
		         fechaejecucion			:= rec_trab.fechaejecucion;
		         jsonresponsable		:= rec_trab.jsonresponsable;
		         estado					:= rec_trab.estado;
		         statusname				:= rec_trab.nombreestado;
		         fechacreacion			:= rec_trab.fechacreacion;
		         usuariocreacion		:= rec_trab.usuariocreacion;
		         fechamodificacion		:= rec_trab.fechamodificacion;
		         usuariomodificacion	:= rec_trab.usuariomodificacion;
 
				select count(*)
				  into sp_totalrespaldos
				  from mct_defectocausaaccionpdf md
				 where md.iddefectocausaaccion  = rec_trab.iddefectocausaaccion;
				 
				select count(*)
				  into sp_totalcargas
				  from mct_defectocausaaccionpdf md
				 where md.iddefectocausaaccion  = rec_trab.iddefectocausaaccion
				   and (length(tipo) > 0);
				
		         pendientecarga	:= false;
		         if (sp_totalrespaldos > 0) then		
		             if (sp_totalcargas < sp_totalrespaldos ) then 
		                 pendientecarga	:= true;
		             end if;
		             
		         end if;  
    
		    	return next;
		    
	    	end loop;


END;
$$;


ALTER FUNCTION traking.listdefectocausaaccion(iddefectocausas bigint) OWNER TO postgres;

