        SELECT traking.mct_familia.idfamilia, 
               traking.mct_familia.nombrefamilia, 
               traking.mct_familia.estado, 
               traking.mct_estado.nombreestado,
               traking.mct_familia.fechacreacion,
               traking.mct_familia.usuariocreacion,
               traking.mct_familia.fechamodificacion,
               traking.mct_familia.usuariomodificacion
          FROM traking.mct_familia, 
               traking.mct_estado
         where traking.mct_familia.estado=traking.mct_estado.idestado
           and traking.mct_familia.idfamilia in (8, 10, 11, 14, 15, 24)
           and traking.mct_familia.tipouso = 1
      order by traking.mct_familia.idfamilia asc;

END;
$$;


