--
-- TOC entry 946 (class 1255 OID 17747)
-- Name: listformqrbyot(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listformqrbyot(idots bigint) RETURNS TABLE(idworkorder bigint, customername character varying, idordertype bigint, ordertypename character varying, modelname character varying, neptunomodelname character varying, manufacturername character varying, materialname character varying, paramname character varying, generalplan character varying, powerval bigint, rpmval bigint, flowval bigint, lengthval bigint, heightval bigint, subfamilyname character varying, siglaname character varying, familyname character varying, tagname character varying, datedispatch character varying, totaltime character varying)
    LANGUAGE plpgsql
    AS $$
declare
	
	sp_fechacreacion	timestamp;

	    rec1 	   		record;
	   
		sp_operacion	varchar;
	    fechad_ant		timestamp;
	    fechac_ant		timestamp;
	    tienemas		integer;
	   
begin
	
--	select fechacreacion
--	  into sp_fechacreacion
--	  from mct_ordentrabajo mo 
--	 where idordentrabajoanterior = idots;
	
   	FOR rec1 IN (   
   	        select * 
   	        from (
		    select row_number() over (order by fechadespacho asc) as item,
		          ot ,
		          otanterior,
		          fechadespacho,
		          to_char(age(current_timestamp, fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS')
		     from mct_relacionotciclo,
		          mct_ordentrabajo
		    where ot = idots 
		      and pantalla = 'hist'
		      and otanterior = idordentrabajo
		      and fechadespacho is not null) tabla
		      order by 1 desc
		      )
		loop    
		   
			if rec1.ot = rec1.otanterior then
			
			  tienemas := 0;
			  select count(*)
			    into tienemas
			    from mct_ordentrabajo
			   where idordentrabajoanterior = rec1.ot;
			  
			  if ( tienemas = 1 ) then

			      select 
			             --to_char(age(fechacreacion, rec1.fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS')
			             trim(cast(to_char(round(EXTRACT(Epoch FROM fechacreacion-rec1.fechadespacho)/3600),'999,999,999') as varchar ))
			        into sp_operacion
			        from mct_ordentrabajo mo 
			       where idordentrabajoanterior = rec1.otanterior;	
		      
			  else

			      select 
			             --to_char(age(fechacreacion, rec1.fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS')
			             trim(cast(to_char(round(EXTRACT(Epoch FROM current_timestamp - rec1.fechadespacho)/3600),'999,999,999') as varchar ))
			        into sp_operacion
			        from mct_ordentrabajo
			       where idordentrabajo = rec1.otanterior;			  
			  
			  end if;
			    

		    else
		      select 
		             --to_char(age(fechacreacion, rec1.fechadespacho), 'YY "año(s)" mm "mes(es)" DD "día(s) y" HH24:MI:SS')
		             trim(cast(to_char(round(EXTRACT(Epoch FROM fechacreacion-rec1.fechadespacho)/3600),'999,999,999') as varchar ))
		        into sp_operacion
		        from mct_ordentrabajo mo 
		       where idordentrabajoanterior = rec1.otanterior;		    
		    end if;
		      
--		       item			:= 	rec1.item;
--		       fechad		:=	to_char(rec1.fechadespacho,'dd-mm-yyyy');
--		       tpooperacion	:=	sp_operacion;
		      
		      -- tpooperacion	:= trim(cast(to_char(round(EXTRACT(Epoch FROM current_timestamp-rec1.fechadespacho)/3600),'999,999,999') as varchar ));
		     
		
		
		end loop;
	
    RETURN QUERY
			select a.idordentrabajo ,
			       b.nombrecliente ,
			       a.idtipoorden ,
			       c.nombretipoorden ,
			       f.nombremodelo ,
			       case
			          when i.nombreparam != '0' then f.nombreneptuno||' '||i.nombreparam 
			          when i.nombreparam = '0' then f.nombreneptuno 
                      else f.nombreneptuno
			       end,
			     --  f.nombreneptuno ,
			       cast('NEPTUNO PUMPS' as varchar),
			       g.nombrematerial ,
			       i.nombreparam ,
			       d.planogeneral ,
			       d.potencia ,
			       d.rpm ,
			       d.caudal ,
			       d.largo ,
			       d.altura ,
			       h.nombresubfamilia ,
			       h.sigla ,
			       e.nombrefamilia ,
			       a.tag,
			       cast(to_char(a.fechadespacho,'dd-mm-yyyy') as varchar),
			       --coalesce (sp_operacion,'0'),
			       case
			          when sp_operacion is null then trim(to_char(round(EXTRACT(Epoch FROM now()-a.fechadespacho)/3600),'999,999,999') ) 
			          else sp_operacion
			       end
--			       cast(case
--			         when a.fechadespacho is null then '0'
--			         --else date_part('day', sp_fechacreacion - a.fechadespacho )*24
--			         else '0'--trim(to_char(round(EXTRACT(Epoch FROM sp_fechacreacion-a.fechadespacho)/3600),'999,999,999') ) 
--			       end as varchar)
			  from mct_ordentrabajo a ,
			       mct_cliente b,
			       mct_tipoorden c,
			       mct_producto d,
			       mct_familia e,
			       mct_modelo f,
			       mct_material g,
			       mct_subfamilia h,
			       mct_etapaparam i
			 where a.idordentrabajo = idots
			   and a.idcliente = b.idcliente 
			   and a.idtipoorden = c.idtipoorden
			   and a.idproducto = d.idproducto 
			   and a.idfamilia = e.idfamilia 
			   and d.idmodelo = f.idmodelo 
			   and d.idmaterial = g.idmaterial 
			   and f.idsubfamilia = h.idsubfamilia 
			   and d.idetapaparam = i.idetapaparam ;
        
END;
$$;


ALTER FUNCTION traking.listformqrbyot(idots bigint) OWNER TO postgres;

