--
-- TOC entry 1774 (class 1255 OID 17751)
-- Name: listgestionncfcausa(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listgestionncfcausa(idgestionncfs bigint) RETURNS TABLE(idgestionncfcausa bigint, idgestionncf bigint, descripcion character varying, estado bigint, statusname character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying, pendientecarga boolean)
    LANGUAGE plpgsql
    AS $$
declare

	rec_trab       		RECORD;
	sp_totalrespaldos	bigint;
	sp_totalcargas		bigint;
    sp_pendientecarga	boolean;
   
BEGIN

	FOR rec_trab IN ( 

	        SELECT traking.mct_gestionncfcausa.idgestionncfcausa , 
	               traking.mct_gestionncfcausa.idgestionncf ,
	               traking.mct_gestionncfcausa.descripcion , 
	               traking.mct_gestionncfcausa.estado,
	               traking.mct_estado.nombreestado,
	               traking.mct_gestionncfcausa.fechacreacion,
	               traking.mct_gestionncfcausa.usuariocreacion,
	               traking.mct_gestionncfcausa.fechamodificacion,
	               traking.mct_gestionncfcausa.usuariomodificacion
	        FROM traking.mct_gestionncfcausa, 
	             traking.mct_estado
	       where traking.mct_gestionncfcausa.idgestionncf = idgestionncfs
	         and traking.mct_gestionncfcausa.estado = traking.mct_estado.idestado
	        order by 4 asc
          )
        loop 
        
		        idgestionncfcausa	:= rec_trab.idgestionncfcausa;
		        idgestionncf		:= rec_trab.idgestionncf;
		        descripcion			:= rec_trab.descripcion;
		        estado				:= rec_trab.estado;
		        statusname 			:= rec_trab.nombreestado;
		        fechacreacion 		:= rec_trab.fechacreacion;
		        usuariocreacion 	:= rec_trab.usuariocreacion;
		        fechamodificacion 	:= rec_trab.fechamodificacion;
		        usuariomodificacion := rec_trab.usuariomodificacion;
         
				select count(*)
				  into sp_totalrespaldos
				  from mct_gestionncfcausaaccion a,
				       mct_gestionncfcausaaccionpdf b
				 where a.idgestionncfcausa = rec_trab.idgestionncfcausa
				   and a.idgestionncfcausaaccion = b.idgestionncfcausaaccion ;
				 
				select count(*)
				  into sp_totalcargas
				  from mct_gestionncfcausaaccion a,
				       mct_gestionncfcausaaccionpdf b
				 where a.idgestionncfcausa = rec_trab.idgestionncfcausa
				   and a.idgestionncfcausaaccion = b.idgestionncfcausaaccion
				   and (length(tipo) > 0);
				
				        
		         pendientecarga	:= false;
		         if (sp_totalrespaldos > 0) then		
		             if (sp_totalcargas < sp_totalrespaldos ) then 
		                 pendientecarga	:= true;
		             end if;
		             
		         end if;  
    
		    	return next;
		    
        end loop;
        
		    
END;
$$;


ALTER FUNCTION traking.listgestionncfcausa(idgestionncfs bigint) OWNER TO postgres;

--
-- TOC entry 1688 (class 1255 OID 17752)
