--

CREATE FUNCTION traking.listgestionncfcausaaccion(idgestionncfcausas bigint) RETURNS TABLE(idgestionncfcausaaccion bigint, idgestionncfcausa bigint, descripcion character varying, fechaejecucion character varying, jsonresponsable character varying, estado bigint, statusname character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying, pendientecarga boolean)
    LANGUAGE plpgsql
    AS $$
declare

	rec_trab       		RECORD;
	sp_totalrespaldos	bigint;
	sp_totalcargas		bigint;
    sp_pendientecarga	boolean;

BEGIN

		   

	    FOR rec_trab IN (  

		        SELECT traking.mct_gestionncfcausaaccion.idgestionncfcausaaccion , 
		        	   traking.mct_gestionncfcausaaccion.idgestionncfcausa ,              
		               traking.mct_gestionncfcausaaccion.descripcion , 
		               cast(to_char(traking.mct_gestionncfcausaaccion.fechaejecucion, 'yyyy-mm-dd') as varchar)  as fechaejecucion,
		               traking.mct_gestionncfcausaaccion.jsonresponsable  ,
		               traking.mct_gestionncfcausaaccion.estado,
		               traking.mct_estado.nombreestado,
		               traking.mct_gestionncfcausaaccion.fechacreacion,
		               traking.mct_gestionncfcausaaccion.usuariocreacion,
		               traking.mct_gestionncfcausaaccion.fechamodificacion,
		               traking.mct_gestionncfcausaaccion.usuariomodificacion
		        FROM traking.mct_gestionncfcausaaccion, 
		             traking.mct_estado
		       where traking.mct_gestionncfcausaaccion.idgestionncfcausa = idgestionncfcausas
		         and traking.mct_gestionncfcausaaccion.estado = traking.mct_estado.idestado
		        order by 4 asc	    
	    			   
	    	)
	    	loop
	   
		         idgestionncfcausaaccion	:= rec_trab.idgestionncfcausaaccion;
		         idgestionncfcausa			:= rec_trab.idgestionncfcausa;
		         descripcion			:= rec_trab.descripcion;
		         fechaejecucion			:= rec_trab.fechaejecucion;
		         jsonresponsable		:= rec_trab.jsonresponsable;
		         estado					:= rec_trab.estado;
		         statusname				:= rec_trab.nombreestado;
		         fechacreacion			:= rec_trab.fechacreacion;
		         usuariocreacion		:= rec_trab.usuariocreacion;
		         fechamodificacion		:= rec_trab.fechamodificacion;
		         usuariomodificacion	:= rec_trab.usuariomodificacion;
 
				select count(*)
				  into sp_totalrespaldos
				  from mct_gestionncfcausaaccionpdf md
				 where md.idgestionncfcausaaccion  = rec_trab.idgestionncfcausaaccion;
				 
				select count(*)
				  into sp_totalcargas
				  from mct_gestionncfcausaaccionpdf md
				 where md.idgestionncfcausaaccion  = rec_trab.idgestionncfcausaaccion
				   and (length(tipo) > 0);
				
		         pendientecarga	:= false;
		         if (sp_totalrespaldos > 0) then		
		             if (sp_totalcargas < sp_totalrespaldos ) then 
		                 pendientecarga	:= true;
		             end if;
		             
		         end if;  
    
		    	return next;
		    
	    	end loop;


END;
$$;


ALTER FUNCTION traking.listgestionncfcausaaccion(idgestionncfcausas bigint) OWNER TO postgres;

