		  left join traking.mct_tipoarchivogestionncf on traking.mct_tipoarchivogestionncf.idtipoarchivogestionncf = traking.mct_gestionncfpdf.idtipoarchivodefecto  
		 where traking.mct_gestionncfpdf.idgestionncf = idgestionncfs;	
		  

END;
$$;


