CREATE FUNCTION traking.listhoraminuto() RETURNS TABLE(idhoraminuto bigint, nombrehoraminuto character varying, aplicaturnodia boolean, aplicaturnonoche boolean, aplicadiacompleto boolean, aplicaturnoespecial boolean)
    LANGUAGE plpgsql
    AS $$
declare
   sp_cantidad    integer;
BEGIN


	    RETURN QUERY
	    
		select a.idhoraminuto ,
		       a.nombrehoraminuto ,
		       a.aplicaturnodia ,
		       a.aplicaturnonoche ,
		       a.aplicadiacompleto ,
		       a.aplicaturnoespecial  
		  from traking.mct_horaminuto a
		order by a.nombrehoraminuto asc ;
		
END;
$$;


