--
-- TOC entry 1050 (class 1255 OID 17756)
-- Name: listhoraminutofiltro(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listhoraminutofiltro(filtros bigint) RETURNS TABLE(idhoraminuto bigint, nombrehoraminuto character varying, aplicaturnodia boolean, aplicaturnonoche boolean, aplicadiacompleto boolean, aplicaturnoespecial boolean)
    LANGUAGE plpgsql
    AS $$
declare
   sp_cantidad    integer;
BEGIN


	    if ( filtros = -1 ) then

	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			order by a.nombrehoraminuto asc ;
	
	    elsif ( filtros = 1 ) then

	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 where a.aplicaturnodia is true
			order by a.nombrehoraminuto asc ;
	
	    elsif ( filtros = 2 ) then

	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 where a.aplicaturnonoche is true
			order by a.nombrehoraminuto asc ;
		
	    elsif ( filtros = 20 ) then -- esto es ara el turno de planificacion

	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 --where a.aplicaturnonoche is true
			 where a.idhoraminuto in (39,40,42,45,46,47,48)
			order by a.nombrehoraminuto asc ;
		
		
		elsif ( filtros = 22 ) then

	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 where a.idhoraminuto in (39,40,45,46,47,48)
			order by a.nombrehoraminuto asc ;
		
	    elsif ( filtros = 3 ) then
	    
	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 where a.aplicadiacompleto is true
			order by a.nombrehoraminuto asc ;
		
	    elsif ( filtros = 4 ) then
	    
	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 where a.aplicaturnoespecial is true
			order by a.nombrehoraminuto asc ;

	   elsif ( filtros = 5 ) then
	    
	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 where a.aplicaturnofund  is true
			order by a.nombrehoraminuto asc ;

	   elsif ( filtros = 7 ) then -- esto es para ingreso anticipado
	    
	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 where a.aplicaingresoanticipado is true
			order by a.nombrehoraminuto asc ;
		
		elsif ( filtros = 6 ) then
	    
	        return QUERY
	        
			select a.idhoraminuto ,
			       a.nombrehoraminuto ,
			       a.aplicaturnodia ,
			       a.aplicaturnonoche ,
			       a.aplicadiacompleto ,
			       a.aplicaturnoespecial  
			  from traking.mct_horaminuto a
			 where a.aplicaturnofundext is true
			order by a.nombrehoraminuto asc ;
		
	    end if;

		
END;
$$;


ALTER FUNCTION traking.listhoraminutofiltro(filtros bigint) OWNER TO postgres;

--
-- TOC entry 1079 (class 1255 OID 17757)
-- Name: listhorasextrasdetallefundicion1(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listhorasextrasdetallefundicion1(fechadesde character varying, fechahasta character varying, idoperadors bigint) RETURNS TABLE(idoperador bigint, nombreoperador character varying, fechaturno character varying, horasalida character varying, horasextrasalida numeric, horaentrada character varying, horasextraentrada numeric, total numeric)
    LANGUAGE plpgsql
    AS $$
declare 

	rec_hora		RECORD;
    indice      	bigint;
   
    lunesaviernesTot	numeric;
    sabadoTot			numeric;
    domingoTot			numeric;
   
    sp_turno13				boolean; 
    sp_turno16 				boolean;
    sp_turno18 				boolean; 
    sp_turno20 				boolean; 
    sp_turno2130 			boolean; 
    sp_turnonoche 			boolean; 
    sp_idhoraminutonoche  	integer; 
    sp_turnootro 			boolean;
    sp_idhoraminutootro 	integer;	
    sp_idhoraminutoingant	integer;
    sp_ingresoanticipado	boolean;
       
    textoentrada			varchar;
    textosalida				varchar;
    sumatotalsal			numeric;
    sumatotalent			numeric;
   
begin
	
	 lunesaviernesTot	:= 0;
	 sabadoTot			:= 0;
	 domingoTot			:= 0;
	 sumatotalsal		:= 0;
	 sumatotalent		:= 0;
	
	 textoentrada		:= '';
     textosalida		:= '';
    
	 if ( idoperadors = -1 ) then
	 
		 FOR rec_hora IN ( 
	
				select to_char(a.fechaturno, 'dd-mm-yyyy') as fecha,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + horaextrasalida) as total
				  from mct_operadorturnofund a 
				 where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				   and a.esturnofundicion1 is true
				   and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				 group by a.fechaturno	 
				 order by a.fechaturno asc
		      
		      )
		      loop
		      	
				    idoperador 			:= 0;
			        nombreoperador 		:= ''; 
			        fechaturno 			:= rec_hora.fecha;
			        horasalida 			:= '';
			        horasextrasalida 	:= rec_hora.horasalida;
			        horaentrada 		:= '';
			        horasextraentrada 	:= rec_hora.horaentrada; 
			        total 				:= rec_hora.total;
				   
			        sumatotalsal		:= sumatotalsal + rec_hora.horasalida;
				 	sumatotalent		:= sumatotalent + rec_hora.horaentrada;
	
				    return next;
			      
		      END loop;

		      idoperador 		:= -1;
			  nombreoperador 	:= ''; 
			  fechaturno 		:= 'TOTAL';
			  horasalida 		:= '';
			  horasextrasalida 	:= sumatotalsal;
			  horaentrada 		:= '';
			  horasextraentrada := sumatotalent; 
			  total 			:= sumatotalsal + sumatotalent;
				   
			  return next;
			 
	 else 
	 
		 FOR rec_hora IN ( 
	
				select a.idoperador ,
				       b.nombreoperador ,
				       to_char(a.fechaturno, 'dd-mm-yyyy') as fecha,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + horaextrasalida) as total
				  from mct_operadorturnofund a 
				  left join mct_operador b on b.idoperador = a.idoperador 
				 where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				   and a.idoperador = idoperadors
				   and a.esturnofundicion1 is true
				   and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				 group by a.idoperador, b.nombreoperador , a.fechaturno	 
				 order by a.idoperador asc, a.fechaturno asc
		      
		      )
		      loop
		
			    textoentrada	:= '';
    			textosalida  	:= '';
    		
				select a.turno13 , 
				       a.turno16 , 
				       a.turno18 , 
				       a.turno20 , 
				       a.turno2130 , 
				       a.turnonoche , 
				       a.idhoraminutonoche  , 
				       a.turnootro ,
				       a.idhoraminutootro ,
				       a.ingresoanticipado,
				       a.idhoraminutoingant 
				  into sp_turno13, 
					   sp_turno16,
					   sp_turno18, 
					   sp_turno20, 
					   sp_turno2130, 
					   sp_turnonoche, 
					   sp_idhoraminutonoche,
					   sp_turnootro,
					   sp_idhoraminutootro,	
					   sp_ingresoanticipado,
					   sp_idhoraminutoingant     
				  from mct_operadorturnofund a
				 where a.fechaturno = to_date(rec_hora.fecha,'dd-mm-yyyy')
				   and a.idoperador = rec_hora.idoperador
				   and a.esturnofundicion1 is true;
			
				if ( sp_turno13 is true) then
					textosalida := '13:00';
				elsif ( sp_turno16 is true ) then
						textosalida := '16:00';
				elsif ( sp_turno18 is true ) then
						textosalida := '18:00';	
				elsif ( sp_turno20 is true ) then
						textosalida := '20:00';	
				elsif ( sp_turno2130 is true ) then
						textosalida := '21:30';
			    elsif ( sp_turnonoche is true) then
			            select nombrehoraminuto 
			              into textosalida
			              from mct_horaminuto mh 
			             where idhoraminuto = sp_idhoraminutonoche;
			    
			    elsif ( sp_turnootro is true) then
					    select nombrehoraminuto 
					      into textosalida
					      from mct_horaminuto mh 
					     where idhoraminuto = sp_idhoraminutootro;

			    end if;
				 
			    if ( sp_ingresoanticipado is true) then
					 select nombrehoraminuto 
				       into textoentrada
				       from mct_horaminuto mh 
				      where idhoraminuto = sp_idhoraminutoingant;

				elsif (textosalida != '') then
				    if ( date_part('dow', to_date(rec_hora.fecha,'dd-mm-yyyy')) = 0 ) then
				       textoentrada = '08:30';
				    else
					   textoentrada = '07:30';
					end if;
			    end if;					  

			 
				    idoperador 			:= rec_hora.idoperador;
			        nombreoperador 		:= rec_hora.nombreoperador; 
			        fechaturno 			:= rec_hora.fecha;
			        horasalida 			:= textosalida;
			        horasextrasalida 	:= rec_hora.horasalida;
			        horaentrada 		:= textoentrada;
			        horasextraentrada 	:= rec_hora.horaentrada; 
			        total 				:= rec_hora.total;
				   
			        sumatotalsal		:= sumatotalsal + rec_hora.horasalida;
				 	sumatotalent		:= sumatotalent + rec_hora.horaentrada;
				 
				    return next;
				   
		      END loop;
		      
		      idoperador 		:= -1;
			  nombreoperador 	:= ''; 
			  fechaturno 		:= 'TOTAL';
			  horasalida 		:= '';
			  horasextrasalida 	:= sumatotalsal;
			  horaentrada 		:= '';
			  horasextraentrada := sumatotalent; 
			  total 			:= sumatotalsal + sumatotalent;
				   
			  return next;
				   
	   
	 end if;
	
   
END
$$;


ALTER FUNCTION traking.listhorasextrasdetallefundicion1(fechadesde character varying, fechahasta character varying, idoperadors bigint) OWNER TO postgres;

