    sp_turno20 				boolean; 
    sp_turno2130 			boolean; 
    sp_turnonoche 			boolean; 
    sp_idhoraminutonoche  	integer; 
    sp_turnootro 			boolean;
    sp_idhoraminutootro 	integer;	
    sp_idhoraminutoingant	integer;
    sp_ingresoanticipado	boolean;
       
    textoentrada			varchar;
    textosalida				varchar;
    sumatotalsal			numeric;
    sumatotalent			numeric;
   
begin
	
	 lunesaviernesTot	:= 0;
	 sabadoTot			:= 0;
	 domingoTot			:= 0;
	 sumatotalsal		:= 0;
	 sumatotalent		:= 0;
	
