		 FOR rec_hora IN ( 
	
				select to_char(a.fechaturno, 'dd-mm-yyyy') as fecha,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + horaextrasalida) as total
				  from mct_operadorturnomaestranza a 
				 where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				   and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				 group by a.fechaturno	 
				 order by a.fechaturno asc
		      
		      )
		      loop
		      	
				    idoperador 			:= 0;
			        nombreoperador 		:= ''; 
			        fechaturno 			:= rec_hora.fecha;
			        horasalida 			:= '';
			        horasextrasalida 	:= rec_hora.horasalida;
			        horaentrada 		:= '';
			        horasextraentrada 	:= rec_hora.horaentrada; 
			        total 				:= rec_hora.total;
				   
			        sumatotalsal		:= sumatotalsal + rec_hora.horasalida;
				 	sumatotalent		:= sumatotalent + rec_hora.horaentrada;
	
				    return next;
			      
		      END loop;

		      idoperador 		:= -1;
			  nombreoperador 	:= ''; 
			  fechaturno 		:= 'TOTAL';
			  horasalida 		:= '';
			  horasextrasalida 	:= sumatotalsal;
			  horaentrada 		:= '';
			  horasextraentrada := sumatotalent; 
			  total 			:= sumatotalsal + sumatotalent;
				   
			  return next;
			 
	 else 
	 
		 FOR rec_hora IN ( 
	
				select a.idoperador ,
				       b.nombreoperador ,
				       to_char(a.fechaturno, 'dd-mm-yyyy') as fecha,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + horaextrasalida) as total
				  from mct_operadorturnomaestranza a 
				  left join mct_operador b on b.idoperador = a.idoperador 
				 where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				   and a.idoperador = idoperadors
				   and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				 group by a.idoperador, b.nombreoperador , a.fechaturno	 
				 order by a.idoperador asc, a.fechaturno asc
		      
		      )
		      loop
		      	
			    textoentrada	:= '';
    			textosalida  	:= '';
    		
				select a.turno13 , 
				       a.turno16 , 
				       a.turno18 , 
				       a.turno20 , 
				       a.turno2130 , 
				       a.turnonoche , 
				       a.idhoraminutonoche  , 
				       a.turnootro ,
				       a.idhoraminutootro ,
				       a.ingresoanticipado,
				       a.idhoraminutoingant 
				  into sp_turno13, 
					   sp_turno16,
					   sp_turno18, 
					   sp_turno20, 
					   sp_turno2130, 
					   sp_turnonoche, 
					   sp_idhoraminutonoche,
					   sp_turnootro,
					   sp_idhoraminutootro,	
					   sp_ingresoanticipado,
					   sp_idhoraminutoingant     
				  from mct_operadorturnomaestranza a
				 where a.fechaturno = to_date(rec_hora.fecha,'dd-mm-yyyy')
				   and a.idoperador = rec_hora.idoperador;
			
				if ( sp_turno13 is true) then
					textosalida := '13:00';
				elsif ( sp_turno16 is true ) then
						textosalida := '16:00';
				elsif ( sp_turno18 is true ) then
						textosalida := '18:00';	
				elsif ( sp_turno20 is true ) then
						textosalida := '20:00';	
				elsif ( sp_turno2130 is true ) then
						textosalida := '21:30';
			    elsif ( sp_turnonoche is true) then
			            select nombrehoraminuto 
			              into textosalida
			              from mct_horaminuto mh 
			             where idhoraminuto = sp_idhoraminutonoche;
			    
			    elsif ( sp_turnootro is true) then
					    select nombrehoraminuto 
					      into textosalida
					      from mct_horaminuto mh 
					     where idhoraminuto = sp_idhoraminutootro;

			    end if;
				 
			    if ( sp_ingresoanticipado is true) then
					 select nombrehoraminuto 
				       into textoentrada
				       from mct_horaminuto mh 
				      where idhoraminuto = sp_idhoraminutoingant;

				elsif (textosalida != '') then
				    if ( date_part('dow', to_date(rec_hora.fecha,'dd-mm-yyyy')) = 0 ) then
				       textoentrada = '08:30';
				    else
					   textoentrada = '07:30';
					end if;
			    end if;					  

			 
				    idoperador 			:= rec_hora.idoperador;
			        nombreoperador 		:= rec_hora.nombreoperador; 
			        fechaturno 			:= rec_hora.fecha;
			        horasalida 			:= textosalida;
			        horasextrasalida 	:= rec_hora.horasalida;
			        horaentrada 		:= textoentrada;
			        horasextraentrada 	:= rec_hora.horaentrada; 
			        total 				:= rec_hora.total;
				   
			        sumatotalsal		:= sumatotalsal + rec_hora.horasalida;
				 	sumatotalent		:= sumatotalent + rec_hora.horaentrada;
				 
				    return next;
				   
		      END loop;
		      
		      idoperador 		:= -1;
			  nombreoperador 	:= ''; 
			  fechaturno 		:= 'TOTAL';
			  horasalida 		:= '';
			  horasextrasalida 	:= sumatotalsal;
			  horaentrada 		:= '';
			  horasextraentrada := sumatotalent; 
			  total 			:= sumatotalsal + sumatotalent;
				   
			  return next;
				   
	   
	 end if;
	
   
END
$$;


ALTER FUNCTION traking.listhorasextrasdetallemaestranza(fechadesde character varying, fechahasta character varying, idoperadors bigint) OWNER TO postgres;

--
-- TOC entry 2304 (class 1255 OID 17760)
-- Name: listhorasextrasresumen(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listhorasextrasresumen(fechadesde character varying, fechahasta character varying, idoperadors bigint) RETURNS TABLE(idhorasextras bigint, origen character varying, dias character varying, horasextraentrada numeric, horasextrasalida numeric, total numeric)
    LANGUAGE plpgsql
    AS $$
declare 

	rec_hora		RECORD;
    indice      	bigint;
   
    lunesaviernesEnt	numeric;
    lunesaviernesSal	numeric;
    lunesaviernesTot	numeric;
   
    sabadoEnt			numeric;
    sabadoSal			numeric;
    sabadoTot			numeric;
   
    domingoEnt			numeric;
    domingoSal			numeric;
    domingoTot			numeric;
   
    totalEnt			numeric;
    totalSal			numeric;
    totalTot			numeric;
   
    sp_origen			varchar;
   
begin
	
	 lunesaviernesEnt	:= 0;
	 lunesaviernesSal	:= 0;
	 lunesaviernesTot	:= 0;
	
	 sabadoEnt			:= 0;
	 sabadoSal			:= 0;
	 sabadoTot			:= 0;
	
	 domingoEnt			:= 0;
	 domingoSal			:= 0;
	 domingoTot			:= 0;
	
	 totalEnt			:= 0;
     totalSal			:= 0;
     totalTot			:= 0;
	
	 
	 if ( idoperadors = -1 ) then
	 
		 FOR rec_hora IN ( 
	
				select date_part('dow', a.fechaturno) as diasem,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + horaextrasalida) as total
				  from mct_operadorturnomaestranza a 
				 where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				   and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				 group by date_part('dow', a.fechaturno)	 
		      
		      )
		      loop
		      	
			      if ( rec_hora.diasem in (1,2,3,4,5) ) then 
			      
			      	  lunesaviernesEnt	:= lunesaviernesEnt + rec_hora.horaentrada;
		 			  lunesaviernesSal	:= lunesaviernesSal + rec_hora.horasalida;
		 			  lunesaviernesTot	:= lunesaviernesTot + rec_hora.total;
			      
			      elsif ( rec_hora.diasem in (6) ) then
			      
			          sabadoEnt	:= sabadoEnt + rec_hora.horaentrada;
		 			  sabadoSal	:= sabadoSal + rec_hora.horasalida;
		 			  sabadoTot	:= sabadoTot + rec_hora.total;
			      
			      elsif ( rec_hora.diasem in (0) ) then 
			      
			          domingoEnt	:= domingoEnt + rec_hora.horaentrada;
		 			  domingoSal	:= domingoSal + rec_hora.horasalida;
		 			  domingoTot	:= domingoTot + rec_hora.total;
			      
			      end if;
			 
		      END loop;
		      
	    idhorasextras		:= 1;
	    origen				:= 'MAESTRANZA';
	    dias				:= 'LUNES - VIERNES';
	    horasextraentrada	:= lunesaviernesEnt;
	    horasextrasalida	:= lunesaviernesSal;
	    total				:= lunesaviernesTot;
	   
	    return next;
	
	    idhorasextras		:= 2;
	    origen				:= '';
	    dias				:= 'SÁBADO';
	    horasextraentrada	:= sabadoEnt;
	    horasextrasalida	:= sabadoSal;
	    total				:= sabadoTot;
	   
	    return next;
	   
	    idhorasextras		:= 3;
	    origen				:= '';
	    dias				:= 'DOMINGO';
	    horasextraentrada	:= domingoEnt;
	    horasextrasalida	:= domingoSal;
	    total				:= domingoTot;
	   
	    return next;
	   
	    idhorasextras		:= -1;
	    origen				:= '';
	    dias				:= 'TOTAL';
	    horasextraentrada	:= lunesaviernesEnt + sabadoEnt + domingoEnt;
	    horasextrasalida	:= lunesaviernesSal + sabadoSal + domingoSal;
	    total				:= lunesaviernesTot + sabadoTot + domingoTot;
	   
	    return next;
	   
	    totalEnt			:= totalEnt + lunesaviernesEnt + sabadoEnt + domingoEnt;
        totalSal			:= totalSal + lunesaviernesSal + sabadoSal + domingoSal;
        totalTot			:= totalTot + lunesaviernesTot + sabadoTot + domingoTot;

	
	   -- Fundicion 1
		FOR rec_hora IN ( 
	
				select date_part('dow', a.fechaturno) as diasem,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + horaextrasalida) as total
				  from mct_operadorturnofund a 
				 where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				   and a.esturnofundicion1 is true
				   and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				 group by date_part('dow', a.fechaturno)	 
		      
		      )
		      loop
		      	
			      if ( rec_hora.diasem in (1,2,3,4,5) ) then 
			      
			      	  lunesaviernesEnt	:= lunesaviernesEnt + rec_hora.horaentrada;
		 			  lunesaviernesSal	:= lunesaviernesSal + rec_hora.horasalida;
		 			  lunesaviernesTot	:= lunesaviernesTot + rec_hora.total;
			      
			      elsif ( rec_hora.diasem in (6) ) then
			      
			          sabadoEnt	:= sabadoEnt + rec_hora.horaentrada;
		 			  sabadoSal	:= sabadoSal + rec_hora.horasalida;
		 			  sabadoTot	:= sabadoTot + rec_hora.total;
			      
			      elsif ( rec_hora.diasem in (0) ) then 
			      
			          domingoEnt	:= domingoEnt + rec_hora.horaentrada;
		 			  domingoSal	:= domingoSal + rec_hora.horasalida;
		 			  domingoTot	:= domingoTot + rec_hora.total;
			      
			      end if;
			 
		      END loop;
		      
	    idhorasextras		:= 1;
	    origen				:= 'FUNDICIÓN (1)';
	    dias				:= 'LUNES - VIERNES';
	    horasextraentrada	:= lunesaviernesEnt;
	    horasextrasalida	:= lunesaviernesSal;
	    total				:= lunesaviernesTot;
	   
	    return next;
	
	    idhorasextras		:= 2;
	    origen				:= '';
	    dias				:= 'SÁBADO';
	    horasextraentrada	:= sabadoEnt;
	    horasextrasalida	:= sabadoSal;
	    total				:= sabadoTot;
	   
	    return next;
	   
	    idhorasextras		:= 3;
	    origen				:= '';
	    dias				:= 'DOMINGO';
	    horasextraentrada	:= domingoEnt;
	    horasextrasalida	:= domingoSal;
	    total				:= domingoTot;
	   
	    return next;
	   
	    idhorasextras		:= -2;
	    origen				:= '';
	    dias				:= 'TOTAL';
	    horasextraentrada	:= lunesaviernesEnt + sabadoEnt + domingoEnt;
	    horasextrasalida	:= lunesaviernesSal + sabadoSal + domingoSal;
	    total				:= lunesaviernesTot + sabadoTot + domingoTot;
	   
	    return next;	   

	    totalEnt			:= totalEnt + lunesaviernesEnt + sabadoEnt + domingoEnt;
        totalSal			:= totalSal + lunesaviernesSal + sabadoSal + domingoSal;
        totalTot			:= totalTot + lunesaviernesTot + sabadoTot + domingoTot;
       
		
	   -- Fundicion 1
		FOR rec_hora IN ( 
	
				select date_part('dow', a.fechaturno) as diasem,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + horaextrasalida) as total
				  from mct_operadorturnofund a 
				 where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				   and a.esturnofundicion2 is true
				   and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				 group by date_part('dow', a.fechaturno)	 
		      
		      )
		      loop
		      	
			      if ( rec_hora.diasem in (1,2,3,4,5) ) then 
			      
			      	  lunesaviernesEnt	:= lunesaviernesEnt + rec_hora.horaentrada;
		 			  lunesaviernesSal	:= lunesaviernesSal + rec_hora.horasalida;
		 			  lunesaviernesTot	:= lunesaviernesTot + rec_hora.total;
			      
			      elsif ( rec_hora.diasem in (6) ) then
			      
			          sabadoEnt	:= sabadoEnt + rec_hora.horaentrada;
		 			  sabadoSal	:= sabadoSal + rec_hora.horasalida;
		 			  sabadoTot	:= sabadoTot + rec_hora.total;
			      
			      elsif ( rec_hora.diasem in (0) ) then 
			      
			          domingoEnt	:= domingoEnt + rec_hora.horaentrada;
		 			  domingoSal	:= domingoSal + rec_hora.horasalida;
		 			  domingoTot	:= domingoTot + rec_hora.total;
			      
			      end if;
			 
		      END loop;
		      
	    idhorasextras		:= 1;
	    origen				:= 'FUNDICIÓN (2)';
	    dias				:= 'LUNES - VIERNES';
	    horasextraentrada	:= lunesaviernesEnt;
	    horasextrasalida	:= lunesaviernesSal;
	    total				:= lunesaviernesTot;
	   
	    return next;
	
	    idhorasextras		:= 2;
	    origen				:= '';
	    dias				:= 'SÁBADO';
	    horasextraentrada	:= sabadoEnt;
	    horasextrasalida	:= sabadoSal;
	    total				:= sabadoTot;
	   
	    return next;
	   
	    idhorasextras		:= 3;
	    origen				:= '';
	    dias				:= 'DOMINGO';
	    horasextraentrada	:= domingoEnt;
	    horasextrasalida	:= domingoSal;
	    total				:= domingoTot;
	   
	    return next;

	   	idhorasextras		:= -3;
	    origen				:= '';
	    dias				:= 'TOTAL';
	    horasextraentrada	:= lunesaviernesEnt + sabadoEnt + domingoEnt;
	    horasextrasalida	:= lunesaviernesSal + sabadoSal + domingoSal;
	    total				:= lunesaviernesTot + sabadoTot + domingoTot;
	   
	    return next;	
	   
	    totalEnt			:= totalEnt + lunesaviernesEnt + sabadoEnt + domingoEnt;
        totalSal			:= totalSal + lunesaviernesSal + sabadoSal + domingoSal;
        totalTot			:= totalTot + lunesaviernesTot + sabadoTot + domingoTot;

	   	idhorasextras		:= -9;
	    origen				:= '';
	    dias				:= 'TOTAL GENERAL';
	    horasextraentrada	:= totalEnt;
	    horasextrasalida	:= totalSal;
	    total				:= totalTot;
	   
	    return next;	
	   
	 else 
	
	     select case
		           when a.aplicacontrolturno is true then
		                 'MAESTRANZA'
		           when a.aplicacontrolturnofund is true then
		           		 'FUNDICION (1)'
		           when a.aplicacontrolturnofund2 is true then
		                 'FUNDICION (2)'
		        end
		   into sp_origen
	       from mct_operador a 
	      where a.idoperador = idoperadors;
	     
		 FOR rec_hora IN ( 
	
		        
				select date_part('dow', a.fechaturno) as diasem,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + a.horaextrasalida) as total
				  from mct_operadorturnomaestranza a 
				  where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				    and a.idoperador = idoperadors
				    and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				  group by date_part('dow', fechaturno)	
				union
				select date_part('dow', a.fechaturno) as diasem,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + a.horaextrasalida) as total
				  from mct_operadorturnofund a 
				  where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				    and a.idoperador = idoperadors
				    and a.esturnofundicion1 is true
				    and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				  group by date_part('dow', fechaturno)
				union
				select date_part('dow', a.fechaturno) as diasem,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
				       sum(a.horaextraentrada + a.horaextrasalida) as total
				  from mct_operadorturnofund a 
				  where a.fechaturno >= to_date(fechadesde, 'yyyy-mm-dd') and a.fechaturno <= to_date(fechahasta, 'yyyy-mm-dd')
				    and a.idoperador = idoperadors
				    and a.esturnofundicion2 is true
				    and a.fechaturno >= to_date('2022-11-14', 'yyyy-mm-dd')
				  group by date_part('dow', fechaturno)
				 
		      
		      )
		      loop
		      	
			      if ( rec_hora.diasem in (1,2,3,4,5) ) then 
			      
			      	  lunesaviernesEnt	:= lunesaviernesEnt + rec_hora.horaentrada;
		 			  lunesaviernesSal	:= lunesaviernesSal + rec_hora.horasalida;
		 			  lunesaviernesTot	:= lunesaviernesTot + rec_hora.total;
			      
			      elsif ( rec_hora.diasem in (6) ) then
			      
			          sabadoEnt	:= sabadoEnt + rec_hora.horaentrada;
		 			  sabadoSal	:= sabadoSal + rec_hora.horasalida;
		 			  sabadoTot	:= sabadoTot + rec_hora.total;
			      
			      elsif ( rec_hora.diasem in (0) ) then 
			      
			          domingoEnt	:= domingoEnt + rec_hora.horaentrada;
		 			  domingoSal	:= domingoSal + rec_hora.horasalida;
		 			  domingoTot	:= domingoTot + rec_hora.total;
			      
			      end if;
			 
		      END loop;
		      
	    idhorasextras		:= 1;
	    origen				:= sp_origen;
	    dias				:= 'LUNES - VIERNES';
	    horasextraentrada	:= lunesaviernesEnt;
	    horasextrasalida	:= lunesaviernesSal;
	    total				:= lunesaviernesTot;
	   
	    return next;
	
	    idhorasextras		:= 2;
	    origen				:= '';
	    dias				:= 'SÁBADO';
	    horasextraentrada	:= sabadoEnt;
	    horasextrasalida	:= sabadoSal;
	    total				:= sabadoTot;
	   
	    return next;
	   
	    idhorasextras		:= 3;
	    origen				:= '';
	    dias				:= 'DOMINGO';
	    horasextraentrada	:= domingoEnt;
	    horasextrasalida	:= domingoSal;
	    total				:= domingoTot;
	   
	    return next;

	   	idhorasextras		:= -1;
	    origen				:= '';
	    dias				:= 'TOTAL';
	    horasextraentrada	:= lunesaviernesEnt + sabadoEnt + domingoEnt;
	    horasextrasalida	:= lunesaviernesSal + sabadoSal + domingoSal;
	    total				:= lunesaviernesTot + sabadoTot + domingoTot;
	   
	    return next;	
	   
		totalEnt			:= totalEnt + lunesaviernesEnt + sabadoEnt + domingoEnt;
        totalSal			:= totalSal + lunesaviernesSal + sabadoSal + domingoSal;
        totalTot			:= totalTot + lunesaviernesTot + sabadoTot + domingoTot;
       
	 end if;
	

END
$$;


ALTER FUNCTION traking.listhorasextrasresumen(fechadesde character varying, fechahasta character varying, idoperadors bigint) OWNER TO postgres;

--
-- TOC entry 1894 (class 1255 OID 17762)
-- Name: listhorasextrasresumen_backup(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listhorasextrasresumen_backup(fechadesde character varying, fechahasta character varying, idoperadors bigint) RETURNS TABLE(idhorasextras bigint, origen character varying, dias character varying, horasextraentrada numeric, horasextrasalida numeric, total numeric)
