	 domingoSal			:= 0;
	 domingoTot			:= 0;
	
	 totalEnt			:= 0;
     totalSal			:= 0;
     totalTot			:= 0;
	
	 
	 if ( idoperadors = -1 ) then
	 
		 FOR rec_hora IN ( 
	
				select date_part('dow', a.fechaturno) as diasem,
				       sum(a.horaextraentrada)        as horaentrada,
				       sum(a.horaextrasalida)         as horasalida,
