--
-- TOC entry 2260 (class 1255 OID 17764)
-- Name: listhorno(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listhorno() RETURNS TABLE(idhorno bigint, nombrehorno character varying, estado bigint, nombreestado character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	RETURN QUERY
	SELECT a.idhorno,
		   a.nombrehorno,
		   a.estado,
		   b.nombreestado,
		   a.fechacreacion,
		   a.usuariocreacion,
		   a.fechamodificacion,
		   a.usuariomodificacion		               
	  FROM traking.mct_horno a
	left join traking.mct_estado b on ( a.estado = b.idestado)
  order by a.nombrehorno;


END;
$$;


ALTER FUNCTION traking.listhorno() OWNER TO postgres;

--
-- TOC entry 1208 (class 1255 OID 17765)
