--

CREATE FUNCTION traking.listhornocuba(idhornos bigint) RETURNS TABLE(idhornocuba bigint, idhorno bigint, nombrehorno character varying, idcuba bigint, nombrecuba character varying, peso numeric, idmaterial bigint, nombrematerial character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	RETURN QUERY
	SELECT a.idhornocuba,
	       a.idhorno,
		   b.nombrehorno,
		   a.idcuba,
		   c.nombrecuba,
		   a.peso,
		   a.idmaterial,
		   d.nombrematerial,
		   a.fechacreacion,
		   a.usuariocreacion,
		   a.fechamodificacion,
		   a.usuariomodificacion		               
	  FROM traking.mct_hornocuba a
	  left join mct_horno b on a.idhorno = b.idhorno
	  left join mct_cuba c on a.idcuba = c.idcuba
	  left join mct_material d on a.idmaterial = d.idmaterial
	 where a.idhorno = idhornos
	 order by b.nombrehorno, c.nombrecuba;


END;
$$;


