--
-- TOC entry 1017 (class 1255 OID 17768)
-- Name: listinsumoegreso(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listinsumoegreso() RETURNS TABLE(idinsumoegreso bigint, idinsumo bigint, nombreinsumo character varying, codigoplaca character varying, codigobarras character varying, stock bigint, idmarca bigint, nombremarca character varying, idoperador bigint, nombreoperador character varying, codhojaruta character varying, iddetallehojarutatemp bigint, nombreplano character varying, idtrabajohr bigint, trabajadorasignado character varying, idordentrabajo bigint, usuariocreacion character varying, nombreusucreacion character varying, fechacreacion character varying, usuariomodificacion character varying, nombreusumodificacion character varying, fechamodificacion character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
	RETURN QUERY
	SELECT 
		 a.idinsumoegreso, 
		 a.idinsumo,
		 b.nombreinsumo,
		 b.codigoplaca,
		 a.codigobarras,
		 a.stock, 
		 e.idmarca,
		 e.nombremarca,
		 f.idoperador,
         f.nombreoperador,
		 a.codhojaruta,
		 g.idhojarutatemp,		 
		 h.nombreplano,		 
		 h.idtrabajohr,
		 i.nombre as trabajadorasignado,
		 h.idordentrabajo,
		 a.usuariocreacion,
		 c.nombre as nombreusucreacion,
		 cast(to_char(a.fechacreacion, 'dd-mm-yyyy  HH24:MI:SS') as varchar) as fechacreacion,
		 a.usuariomodificacion,
		 d.nombre as nombreusumodificacion,
		 cast(to_char(a.fechamodificacion, 'dd-mm-yyyy  HH24:MI:SS') as varchar) as fechamodificacion
	FROM traking.mct_insumoegreso a
	left join traking.mct_insumo b on  ( a.idinsumo = b.idinsumo )
    left join traking.mct_usuario c on ( a.usuariocreacion = c.usuario )
    left join traking.mct_usuario d on ( a.usuariomodificacion = c.usuario  )
   	left join traking.mct_marca e on   ( b.idmarca = e.idmarca )
    left join traking.mct_operador f on ( a.idoperador = f.idoperador )
    left join traking.mct_detallehojarutatemp g on ( a.codhojaruta = g.codhojaruta )
    left join traking.mct_hojarutatemp h on ( g.idhojarutatemp = h.idhojarutatemp )
    left join traking.mct_usuario i on ( i.idusuario  = h.idtrabajohr  )
    order by  a.idinsumoegreso desc;
    
END;
$$;


ALTER FUNCTION traking.listinsumoegreso() OWNER TO postgres;

