--

CREATE FUNCTION traking.listinsumootro() RETURNS TABLE(idinsumo bigint, idtipoinsumo bigint, nombretipoinsumo character varying, nombreinsumo character varying, idmaterial bigint, nombrematerial character varying, diametroint numeric, diametroext numeric, largo numeric, texto character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
	RETURN QUERY

	select a.idinsumo ,
	       a.idtipoinsumo ,
	       b.nombretipoinsumo ,
	       a.nombreinsumo ,
	       a.idmaterial ,
	       c.nombrematerial ,
	       a.diametroint,
	       a.diametroext,
	       a.largo,
	       cast(b.nombretipoinsumo||' - '||a.nombreinsumo||' - '||c.nombrematerial||' - '||a.diametroint||' (mm) - '||a.diametroext||' (mm) - '||a.largo||' (mm)' as varchar)
	  from mct_insumo a,
	       mct_tipoinsumo b,
	       mct_material c
	 where a.idtipoinsumo in (4,5,10)
	   and a.idtipoinsumo = b.idtipoinsumo 
	   and a.idmaterial = c.idmaterial ;
   

END;
$$;


