--
-- TOC entry 1418 (class 1255 OID 17772)
-- Name: listinsumootrodetalle(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listinsumootrodetalle(codigoqrs character varying) RETURNS TABLE(idinsumoingresootrodetalle bigint, idinsumo bigint, nombreinsumo character varying, codigoqr character varying, idtipoinsumo bigint, nombretipoinsumo character varying, idinsumoingresootro bigint, diametro numeric, diametroext numeric, diametroint numeric, largo numeric, texto text, resultado bigint, idmaterial bigint, nombrematerial character varying)
    LANGUAGE plpgsql
    AS $$
declare

    sp_id			integer;
	sp_entradas		numeric;
    sp_maxid		integer;
    sp_tipomov		varchar;

begin
	
	sp_entradas	:= 0.0;
    sp_tipomov	:= '';

	select a.idinsumoingresootrodetalle 
	  into sp_id
	  from mct_insumoingresootrodetalle a
	 where a.codigoqr = codigoqrs;
	
	select coalesce (sum(b.largo),0)
	  into sp_entradas
	  from mct_insumoingresootrodetallemov b
	 where b.idinsumoingresootrodetalle = sp_id
	   and b.tipomovimiento = 'ENTRADA';
	
	select coalesce (tipomovimiento , 'ND')
	  into sp_tipomov
	  from mct_insumoingresootrodetallemov
	 where idinsumoegresootrodetallemov = (select coalesce (max(c.idinsumoegresootrodetallemov),0)
											 from mct_insumoingresootrodetallemov c
											where c.codigoqr = codigoqrs);
	
	
	if (sp_tipomov = 'SALIDA' ) then

		RETURN QUERY
		
		select a.idinsumoingresootrodetalle,
		       b.idinsumo,
		       c.nombreinsumo,
		       a.codigoqr ,
		       c.idtipoinsumo,
		       d.nombretipoinsumo,
		       b.idinsumoingresootro,
		       c.diametro ,
		       c.diametroext,
		       c.diametroint,
		       c.largo, 
		       d.nombretipoinsumo||' - '||
		           c.nombreinsumo||' - '||
		           e.nombrematerial||' -  DExt.'||
		           c.diametroext||' (mm) - DInt.'||
		           c.diametroint||' (mm) - Largo.'||
		           c.largo||' (mm)'     ,
		       cast(9999 as bigint),
		       e.idmaterial ,
		       e.nombrematerial 
		  from mct_insumoingresootrodetalle a,
		       mct_insumoingresootro b,
		       mct_insumo c,
		       mct_tipoinsumo d,
		       mct_material e
		 where a.codigoqr = codigoqrs
		   and a.idinsumoingresootro = b.idinsumoingresootro 
		   and b.idinsumo = c.idinsumo 
		   and c.idtipoinsumo = d.idtipoinsumo 
		   and c.idmaterial = e.idmaterial ;
	  
	else
	
		RETURN QUERY
		
		select a.idinsumoingresootrodetalle,
		       b.idinsumo,
		       c.nombreinsumo,
		       a.codigoqr ,
		       c.idtipoinsumo,
		       d.nombretipoinsumo,
		       b.idinsumoingresootro,
		       c.diametro ,
		       c.diametroext,
		       c.diametroint,
		       c.largo, 
		       d.nombretipoinsumo||' - '||
		           c.nombreinsumo||' - '||
		           e.nombrematerial||' -  DExt.'||
		           c.diametroext||' (mm) - DInt.'||
		           c.diametroint||' (mm) - Largo.'||
		           c.largo||' (mm)'     ,
		       cast(c.largo - sp_entradas as bigint),
		       e.idmaterial ,
		       e.nombrematerial 
		  from mct_insumoingresootrodetalle a,
		       mct_insumoingresootro b,
		       mct_insumo c,
		       mct_tipoinsumo d,
		       mct_material e
		 where a.codigoqr = codigoqrs
		   and a.idinsumoingresootro = b.idinsumoingresootro 
		   and b.idinsumo = c.idinsumo 
		   and c.idtipoinsumo = d.idtipoinsumo 
		   and c.idmaterial = e.idmaterial ;
	  
	end if;



	   END;
$$;


ALTER FUNCTION traking.listinsumootrodetalle(codigoqrs character varying) OWNER TO postgres;

