--

CREATE FUNCTION traking.listinsumotable(idtipoinsumos bigint) RETURNS TABLE(idinsumo bigint, nombreinsumo character varying, idtipoinsumo bigint, nombretipoinsumo character varying, codigoplaca character varying, codigobarras character varying, calidad character varying, idmarca bigint, nombremarca character varying, stockminimo bigint, stockcritico bigint, estado bigint, nombreestado character varying, diametro numeric, diametroint numeric, diametroext numeric, largo numeric, idmaterial bigint, nombrematerial character varying, medida character varying, fechacreacion timestamp without time zone, usuariocreacion character varying, fechamodificacion timestamp without time zone, usuariomodificacion character varying)
    LANGUAGE plpgsql
    AS $$
begin
	
	if ( idtipoinsumos = -1 ) then
	
		RETURN QUERY
		SELECT 
			 a.idinsumo, 
			 a.nombreinsumo,
			 a.idtipoinsumo,
			 d.nombretipoinsumo,
			 a.codigoplaca,
			 a.codigobarras,
			 a.calidad,
			 a.idmarca,
			 c.nombremarca,
			 a.stockminimo,
			 a.stockcritico,
			 a.estado,
			 b.nombreestado,
			 -- nuevo
			 a.diametro,
			 a.diametroint,
			 a.diametroext,
			 a.largo,
			 a.idmaterial,
			 e.nombrematerial,
			 a.medida,
			 -- hasta aca
			 a.fechacreacion,
			 a.usuariocreacion,
			 a.fechamodificacion,
			 a.usuariomodificacion
		FROM traking.mct_insumo a
		left join traking.mct_estado b on ( a.estado = b.idestado )
		left join traking.mct_marca c on ( a.idmarca = c.idmarca)
		left join traking.mct_tipoinsumo d on ( a.idtipoinsumo = d.idtipoinsumo )
		left join traking.mct_material e   on e.idmaterial = a.idmaterial
	    order by a.idinsumo desc;
  
	elsif ( idtipoinsumos = 88  ) then

		RETURN QUERY
		SELECT 
			 a.idinsumo, 
			 a.nombreinsumo,
			 a.idtipoinsumo,
			 d.nombretipoinsumo,
			 a.codigoplaca,
			 a.codigobarras,
			 a.calidad,
			 a.idmarca,
			 c.nombremarca,
			 a.stockminimo,
			 a.stockcritico,
			 a.estado,
			 b.nombreestado,
			 -- nuevo
			 a.diametro,
			 a.diametroint,
			 a.diametroext,
			 a.largo,
			 a.idmaterial,
			 e.nombrematerial,
			 a.medida,
			 -- hasta aca
			 a.fechacreacion,
			 a.usuariocreacion,
			 a.fechamodificacion,
			 a.usuariomodificacion
		FROM traking.mct_insumo a
		left join traking.mct_estado b on ( a.estado = b.idestado )
		left join traking.mct_marca c on ( a.idmarca = c.idmarca)
		left join traking.mct_tipoinsumo d on ( a.idtipoinsumo = d.idtipoinsumo )
		left join traking.mct_material e   on e.idmaterial = a.idmaterial
	   where a.idtipoinsumo not in (4,5,10)
	    order by a.idinsumo desc;
	   
	elsif ( idtipoinsumos = 99  ) then

		RETURN QUERY
		SELECT 
			 a.idinsumo, 
			 a.nombreinsumo,
			 a.idtipoinsumo,
			 d.nombretipoinsumo,
			 a.codigoplaca,
			 a.codigobarras,
			 a.calidad,
			 a.idmarca,
			 c.nombremarca,
			 a.stockminimo,
			 a.stockcritico,
			 a.estado,
			 b.nombreestado,
			 -- nuevo
			 a.diametro,
			 a.diametroint,
			 a.diametroext,
			 a.largo,
			 a.idmaterial,
			 e.nombrematerial,
			 a.medida,
			 -- hasta aca
			 a.fechacreacion,
			 a.usuariocreacion,
			 a.fechamodificacion,
			 a.usuariomodificacion
		FROM traking.mct_insumo a
		left join traking.mct_estado b on ( a.estado = b.idestado )
		left join traking.mct_marca c on ( a.idmarca = c.idmarca)
		left join traking.mct_tipoinsumo d on ( a.idtipoinsumo = d.idtipoinsumo )
		left join traking.mct_material e   on e.idmaterial = a.idmaterial
	   where a.idtipoinsumo in (4,5,10)
	    order by a.idinsumo desc;
	   
	end if;

END;
$$;


ALTER FUNCTION traking.listinsumotable(idtipoinsumos bigint) OWNER TO postgres;

