--
-- TOC entry 2385 (class 1255 OID 17786)
-- Name: listmanagerscreenfamiliafacturacion_pendientedespacho_testsq(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listmanagerscreenfamiliafacturacion_pendientedespacho_testsq(idfamily bigint, desde character varying, hasta character varying) RETURNS TABLE(itemot bigint, idworkorder bigint, auttype character varying, ordertypename character varying, username character varying, familyname character varying, productname character varying, subproductname character varying, customername character varying, deliverydatetm character varying, deliverydateclte character varying, statusdispatch bigint, statuscliente bigint, advance numeric, advancefu numeric, advancepa numeric, advanceca numeric, advanceco numeric, advanceot numeric, advancecc numeric, itemcolor integer, statuscolor integer, fucolor integer, pacolor integer, cacolor integer, cocolor integer, otcolor integer, cccolor integer, delayfu integer, delaypa integer, delayca integer, delayco integer, delayot integer, delaycc integer, flagfact boolean, fundiciondate character varying, piezas character varying, estaenproceso bigint, advancez1 numeric, fundiciondatez1 character varying, fechaprobabledespacho character varying)
    LANGUAGE plpgsql
    AS $$

declare
   
    sp_funcav			   numeric;
	sp_funcavz1			   varchar;
   
    rec_ord          	   record;
   
   	sp_fechamaxlcc         timestamp;
	sp_dias_lcc            integer;

    sp_subproducto         varchar;
    sp_avance              numeric;
    sp_indice              integer;
    sp_estaenproceso       bigint;

    sp_fami					integer;
    sp_mec					integer;

    -- Variable para compras
    sp_cantidad_co         integer; 
	sp_codigoqr_co         varchar;  
	sp_fecharequerida_co   timestamp;
    sp_recept_co           integer;
    sp_maxfecha_co         timestamp;   
    sp_dias_atraso_co      integer;  
    sp_avance_co           numeric;
    sp_atraso_co           integer;   
    sp_color_co            integer;
    sp_dias_co             integer;
   
begin
	 
	sp_estaenproceso	:= 0;

	sp_indice 	:= 1;

	sp_fami		:= idfamily;
	if ( idfamily = 111) then
	   sp_fami = 11;
	   sp_mec = 1;
	elsif ( idfamily = 112) then
	   sp_fami = 11;
	   sp_mec = 2;	
	end if;

	FOR rec_ord IN (   
	
	        select ROW_NUMBER() OVER (ORDER BY fechaentrega asc) AS item,
	               idproducto,
	               idordentrabajo,
	               tipoautoriza,
	               nombretipoorden,
	               nombrefamilia,
	               producto,
	               nombrecorto,
	               fechaentrega,
	               fechaentregatm,
	               fechafacetm,
	               fechafaceclte,
	               fechaentregaclte,
	               dias,
	               diascliente,
	               idmodalidadcreacion,
	               nombre,
	               flagfacturacion,
	               siglatipo,
	               siglafam,
	               idfamilia,
	               fechafundicion,
	               checklistvalido,
	               fechamarcapendientedespacho,
	               idestadoorden,
				   fecprobdesp
	          from (	
					select a.idproducto,
					       a.idordentrabajo ,
					       case 
					          when a.ordencompra > 0 then 'S/A'
					          when a.ordencompra = 0 then 'S/A'
					          else 'S/A'
					       end as tipoautoriza,   
					       d.nombretipoorden ,
					       e.nombrefamilia ,
						   case 
							  when a.idfamilia = 11 then c.nombreproducto
							  else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
						   end as producto,
					       b.nombrecorto ,
					       a.fechaentrega ,
					       to_char(a.fechaentrega - interval '7 days','dd-mm-yyyy') as fechaentregatm ,
					       a.fechafacetm,
					       a.fechafaceclte,
					       to_char(a.fechafaceclte,'dd-mm-yyyy') as fechaentregaclte ,				       
					       date_part('day', a.fechafacetm - current_date) as dias,
					       date_part('day', a.fechafaceclte - current_date) as diascliente,				       
					       a.idmodalidadcreacion ,
					       j.nombre ,
					       a.flagfacturacion,
					       d.sigla as siglatipo,
					       e.sigla as siglafam,
					       a.idfamilia ,
					       coalesce (to_char(a.fechafundicion2, 'dd-mm-yyyy' ), to_char(a.fechaentrega - interval '21 days','dd-mm-yyyy')) as fechafundicion,
					       a.checklistvalido ,
					       a.fechamarcapendientedespacho,
					       a.idestadoorden,
                           to_char(a.fechaprobabledespacho,'dd-mm-yyyy') as fecprobdesp
					  from mct_ordentrabajo a,
					       mct_cliente b,
					       mct_producto c,
					       mct_tipoorden d,
					       mct_familia e,
					       mct_estadoorden f,
					       mct_modelo g,
					       mct_subfamilia h,
					       mct_etapaparam i,
					       mct_usuario j
					 where a.idcliente = b.idcliente 
					   and a.idproducto = c.idproducto 
					   and a.idtipoorden = d.idtipoorden 
					   and a.idfamilia = e.idfamilia
					   and a.idestadoorden = f.idestadoorden 
					   and c.idmodelo = g.idmodelo 
					   and g.idsubfamilia = h.idsubfamilia 
					   and c.idetapaparam = i.idetapaparam 
					   and a.idordentrabajo >= 30000
					   and a.idusuario = j.idusuario 
					   and a.idestadoorden  >= 6 and a.idestadoorden < 9
					   and a.idfamilia = sp_fami --in (8, 10, 15)
					   --and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.fechamarcapendientedespacho is not null
				 union 
					select a.idproducto ,
					       a.idordentrabajo ,
					       case 
					          when a.ordencompra > 0 then 'OC'
					          when a.ordencompra = 0 then 'OI'
					          else 'OI'
					       end as tipoautoriza,   
					       d.nombretipoorden ,
					       e.nombrefamilia ,
					       case 
					          when a.idfamilia = 11 then c.nombreproducto
					          else h.sigla||' '||g.nombremodelo||' '||i.nombreparam
					       end as producto,
					       b.nombrecorto ,
					       a.fechaentrega ,
					       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
					       a.fechafacetm,
					       a.fechafaceclte,
					       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
					       date_part('day', a.fechafacetm - current_date) as dias,
					       date_part('day', a.fechafaceclte - current_date) as diascliente,	
					       a.idmodalidadcreacion ,
					       j.nombre ,
					       a.flagfacturacion ,
					       d.sigla as siglatipo,
					       case
					       		when a.idproyecto = 1 then
					       		  e.sigla||'_PYTO'
					        	else
					        	  e.sigla
					       end as siglafam,
					       a.idfamilia ,
					       case
						       when sp_mec = 1 then
						            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
						            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'))
						       when sp_mec = 2 then 
						            to_char(a.fechafundicion ,'dd-mm-yyyy')
						   end as fechafundicion,
						   a.checklistvalido ,
					       a.fechamarcapendientedespacho,
					       a.idestadoorden,
                           to_char(a.fechaprobabledespacho,'dd-mm-yyyy') as fecprobdesp
					  from mct_ordentrabajo a,
					       mct_cliente b,
					       mct_producto c,
					       mct_tipoorden d,
					       mct_familia e,
					       mct_estadoorden f,
					       mct_modelo g,
					       mct_subfamilia h,
					       mct_etapaparam i,
					       mct_usuario j
					 where a.idcliente = b.idcliente 
					   and a.idproducto = c.idproducto 
					   and a.idtipoorden = d.idtipoorden 
					   and a.idfamilia = e.idfamilia
					   and a.idestadoorden = f.idestadoorden 
					   and c.idmodelo = g.idmodelo 
					   and g.idsubfamilia = h.idsubfamilia 
					   and c.idetapaparam = i.idetapaparam 
					   and a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   and a.idusuario = j.idusuario 
					   and a.idestadoorden  >= 5 and a.idestadoorden < 9
					   and a.idfamilia = sp_fami--11
					   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = sp_mec)
					   --and a.flagfacturacion is true
					   and a.debaja < 1
					   and a.fechamarcapendientedespacho is not null
				union 
					select --ROW_NUMBER() OVER (ORDER BY a.fechaentrega asc) AS item,
					       a.idproducto ,
					       a.idordentrabajo ,
					       case 
					          when a.ordencompra > 0 then 'OC'
					          when a.ordencompra = 0 then 'OI'
					          else 'OI'
					       end as tipoautoriza,   
					       d.nombretipoorden ,
					       e.nombrefamilia ,
                           c.nombreproductonepcast  as producto,
					       b.nombrecorto ,
					       a.fechaentrega ,
					       to_char(a.fechafacetm,'dd-mm-yyyy') as fechaentregatm ,
					       a.fechafacetm,
					       a.fechafaceclte,
					       to_char(a.fechafaceclte ,'dd-mm-yyyy') as fechaentregaclte ,				       
					       date_part('day', a.fechafacetm - current_date) as dias,
					       date_part('day', a.fechafaceclte - current_date) as diascliente,	
					       a.idmodalidadcreacion ,
					       j.nombre ,
					       a.flagfacturacion ,
					       d.sigla as siglatipo,
					       case
					       		when a.idproyecto = 1 then
					       		  e.sigla||'_PYTO'
					        	else
					        	  e.sigla
					       end as siglafam,
					       a.idfamilia ,
					       case
						       when sp_mec = 1 then
						            --coalesce (to_char(a.fechafundicion, 'dd-mm-yyyy'), to_char(a.fechafaceclte - interval '14 days','dd-mm-yyyy'))
						            coalesce (to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'), to_char(a.fechafaceclte - interval '10 days','dd-mm-yyyy'))
						       when sp_mec = 2 then 
						            to_char(a.fechafundicion ,'dd-mm-yyyy')
						   end as fechafundicion,
						   a.checklistvalido	 ,
					       a.fechamarcapendientedespacho,
					       a.idestadoorden,
                           to_char(a.fechaprobabledespacho,'dd-mm-yyyy') as fecprobdesp
					  from mct_ordentrabajo a,
					       mct_cliente b,
					       mct_productonepcast c,
					       mct_tipoorden d,
					       mct_familia e,
					       mct_estadoorden f,
					       mct_usuario j
					 where a.idcliente = b.idcliente 
					   and a.idproducto = c.idproductonepcast  
					   and a.idtipoorden = d.idtipoorden 
					   and a.idfamilia = e.idfamilia
					   and a.idestadoorden = f.idestadoorden 
					   and a.idordentrabajo >= 30000
					   and a.idordentrabajo not in (30855)
					   --and c.idresponsable = j.idusuario 
					   and a.idusuario = j.idusuario 
					   and a.idestadoorden  >= 5 and a.idestadoorden < 9
					   and a.idfamilia = sp_fami--11
					   and exists (select 'x' from mct_ordentrabajorepuesto mo where mo.idordentrabajo = a.idordentrabajo and mo.idesmecanizado = sp_mec)
					   --and a.flagfacturacion is true
					   and a.debaja < 1			
					   and a.fechamarcapendientedespacho is not null
				 ) tab
			     order by fechafaceclte asc
				)
	loop 	
	       
	        itemot		   := sp_indice;
		    idworkorder    := rec_ord.idordentrabajo;
			auttype        := rec_ord.tipoautoriza;	    
			ordertypename  := rec_ord.siglatipo;		
			username       := rec_ord.nombre;
		    familyname     := rec_ord.siglafam;	
			productname    := rec_ord.producto;
			subproductname := sp_subproducto;
		    customername   := rec_ord.nombrecorto;
				
		    deliverydatetm 	 := rec_ord.fechaentregatm;
		    deliverydateclte := rec_ord.fechaentregaclte;
			   
		    if (sp_avance >= 100) then
		        statusdispatch  := 0;
		    else
		    	statusdispatch  := rec_ord.dias;
		    end if;
	   
		    statuscliente  := rec_ord.diascliente;	
			   
		    if rec_ord.idfamilia in (8,10) then 
		       select to_char(rec_ord.fechamarcapendientedespacho + interval '5 days', 'dd-mm-yyyy')
		         into piezas;
		    else
		       select to_char(rec_ord.fechamarcapendientedespacho + interval '3 days', 'dd-mm-yyyy')
		         into piezas;
		    end if;
		      
		   -- Compras
			   -- aca sacamos las piezas totales solicitadas a compras  
			   select coalesce ( sum(cantidad), 0),
			          codigoqr, 
			          fecharequerida
			     into sp_cantidad_co,
			          sp_codigoqr_co,
			          sp_fecharequerida_co				          
			     from mct_checklistinftecvalido mc 
			    where tipotrabajostd = 'RPO'
			      and idordentrabajo = rec_ord.idordentrabajo
                  and noaplicasolicitud is false
			    group by codigoqr, fecharequerida;
			   
			   -- aca sacamos el total de piezas recepcionadas   
			   select coalesce ( sum(cantidad), 0),
			          max(fechacreacion)
			     into sp_recept_co,
			          sp_maxfecha_co	 			   
			     from mct_checklistinftecrecept
			    where codigoqr = sp_codigoqr_co;			    

		       sp_atraso_co := 0;
		       if (sp_cantidad_co = 0 ) then
                   sp_cantidad_co := 1;
               end if;				   
			   
			   sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			

			   sp_color_co  := 0;				  
		       if ( sp_avance_co >= 100) then
			       sp_color_co   := 1;
			   end if;	

		    select coalesce (salav)
              into sp_funcav 
              from traking.calcularavancemecanizado(rec_ord.idordentrabajo);
 
		    advance        := sp_funcav;
			
		    advancefu      := 0; 
			advancepa      := 0; 
			advanceca      := 0; 
			--advanceco      := 0; 
            advanceco      := coalesce(sp_avance_co,0);
			advanceot      := 0; 
			advancecc      := 0; 				
			itemcolor      := 0; 
   			statuscolor    := 0;   		
			fucolor        := 0; 
			pacolor        := 0; 
			cacolor        := 0; 		
			cocolor        := 0; 
			otcolor        := 0; 	
			cccolor        := 0; 			
			delayfu        := 0; 
			delaypa        := 0;  
			delayca        := 0;  
			delayco        := 0;  
			delayot        := cast(date_part('day', date(now())::timestamp - rec_ord.fechafaceclte) as bigint);  
			delaycc        := 0;  		
		    flagfact       := rec_ord.flagfacturacion;
		    fundiciondate  := to_char(rec_ord.fechamarcapendientedespacho, 'dd-mm-yyyy');
	      
	        if ( now() <= rec_ord.fechafaceclte ) then
	        	sp_estaenproceso	:= 0;
	        elsif (now() > rec_ord.fechafaceclte) then
	        	sp_estaenproceso	:= 1;
	        end if;
	       
	        estaenproceso  := sp_estaenproceso;
	       
		    sp_indice  	   := sp_indice + 1;

			select coalesce (avancemasfecha)
              into sp_funcavz1 
              from traking.calcularavancemecanizadozona1(rec_ord.idordentrabajo);

			SELECT cast(split_part(sp_funcavz1, '#', 1) as numeric)
              into advancez1;

			SELECT split_part(sp_funcavz1, '#', 2)
              into fundiciondatez1;

			fechaprobabledespacho := rec_ord.fecprobdesp;
		       
		 return next;
	       
	END LOOP;

END;
$$;


ALTER FUNCTION traking.listmanagerscreenfamiliafacturacion_pendientedespacho_testsq(idfamily bigint, desde character varying, hasta character varying) OWNER TO postgres;

