-- Name: listmotivoactividadgestion(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listmotivoactividadgestion() RETURNS TABLE(idmotivoactividadgestion bigint, nombremotivoactividadgestion character varying, status integer, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

