--
-- TOC entry 1011 (class 1255 OID 17799)
-- Name: listmotivoausencia(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listmotivoausencia(filtros bigint) RETURNS TABLE(idmotivoausencia bigint, nombremotivoausencia character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	-- filtros 1 = maestranza
	--         2 = fundicion
		    if ( filtros = 1 ) then

		 	    RETURN QUERY
		 	    
		        SELECT traking.mct_motivoausencia.idmotivoausencia, 
		               traking.mct_motivoausencia.nombremotivoausencia, 
		               traking.mct_motivoausencia.estado,
		               traking.mct_estado.nombreestado,
		               traking.mct_motivoausencia.fechacreacion,
		               traking.mct_motivoausencia.usuariocreacion,
		               traking.mct_motivoausencia.fechamodificacion,
		               traking.mct_motivoausencia.usuariomodificacion
		          FROM traking.mct_motivoausencia, 
		               traking.mct_estado
		         where traking.mct_motivoausencia.estado=traking.mct_estado.idestado
		           and traking.mct_motivoausencia.aplicaturnomasestranza is true
		        order by 1 asc;
		       
		    elsif ( filtros = 2 ) then

		 	    RETURN QUERY
		 	    
		        SELECT traking.mct_motivoausencia.idmotivoausencia, 
		               traking.mct_motivoausencia.nombremotivoausencia, 
		               traking.mct_motivoausencia.estado,
		               traking.mct_estado.nombreestado,
		               traking.mct_motivoausencia.fechacreacion,
		               traking.mct_motivoausencia.usuariocreacion,
		               traking.mct_motivoausencia.fechamodificacion,
		               traking.mct_motivoausencia.usuariomodificacion
		          FROM traking.mct_motivoausencia, 
		               traking.mct_estado
		         where traking.mct_motivoausencia.estado=traking.mct_estado.idestado
		           and traking.mct_motivoausencia.aplicafund  is true
		        order by 1 asc;
       
		    end if;



END;
$$;


ALTER FUNCTION traking.listmotivoausencia(filtros bigint) OWNER TO postgres;

--
-- TOC entry 2037 (class 1255 OID 17800)
-- Name: listmotivorecibefundicion(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listmotivorecibefundicion() RETURNS TABLE(idmotivorecibefundicion bigint, nombremotivorecibefundicion character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
