--
-- TOC entry 1939 (class 1255 OID 17809)
-- Name: listobjeto(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listobjeto() RETURNS TABLE(dato1 character varying)
    LANGUAGE plpgsql
    AS $$
    declare
    size INTEGER := 0;
    arreglo TEXT[] := ARRAY[]::TEXT[];
    arregloString  VARCHAR(2000);
begin
	
	arregloString := traking.evtlistcontrolequipo(-1, 31056, 'NA', 'NA');
    arregloString :=  replace(arregloString, '(', '');
    arregloString :=  replace(arregloString, ')', '');
    arreglo := string_to_array(arregloString,',');
    size := array_length(arreglo,1);
    for i IN 1..size
      Loop
			dato1 := arreglo[i];
		    return next;
      END Loop;

END;
$$;


ALTER FUNCTION traking.listobjeto() OWNER TO postgres;

