--
-- TOC entry 1279 (class 1255 OID 17811)
-- Name: listoperadorturnofundporfecha(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listoperadorturnofundporfecha(fechas character varying) RETURNS TABLE(item bigint, idoperadorturnofund bigint, idoperador bigint, nombreoperador character varying, idseccion bigint, nombreseccion character varying, fechaturno timestamp without time zone, turno13 boolean, nombreturno13 character varying, turno16 boolean, nombreturno16 character varying, turno18 boolean, nombreturno18 character varying, turno20 boolean, nombreturno20 character varying, turno2130 boolean, nombreturno2130 character varying, turnonoche boolean, nombreturnonoche character varying, idhoraminutonoche bigint, nombrehoraminutonoche character varying, motivoquedada character varying, turnootro boolean, nombreturnootro character varying, idhoraminutootro bigint, nombrehoraminutootro character varying, ausente boolean, nombreausente character varying, idmotivoausencia bigint, nombremotivoausencia character varying, idhoraminutofundext bigint, nombrehoraminutofundext character varying, motivoausencia character varying, motivootro character varying, ingresoanticipado boolean, idhoraminutoingant bigint, nombrehoraminutoingant character varying, motivoingresoanticipado character varying, movilizacionpropia boolean, idsector bigint, nombresector character varying, observacion character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
declare
   sp_cantidad    integer;
BEGIN

	sp_cantidad := 0;

	select count(*)
	  into sp_cantidad
	  from mct_operadorturnofund mo 
	 where mo.fechaturno = to_date(fechas,'yyyy-mm-dd')
	   and mo.esturnofundicion1 is true;

	
	if ( sp_cantidad > 0 ) then

	    RETURN QUERY
	    
		select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
		       b.idoperadorturnofund ,
		       b.idoperador ,
		       a.nombreoperador,
		       a.idseccionprincipal ,
		       --d.nombreseccion  ,
		       coalesce (k.nombrecargo,'SIN CARGO'),
		       b.fechaturno ,
		       b.turno13 ,
		       case
		           when b.turno13 is true then
		                cast( 'Tiene turno 13' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,		       
		       b.turno16 ,
		       case
		           when b.turno16 is true then
		                cast( 'Tiene turno 16' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.turno18 ,
		       case
		           when b.turno18 is true then
		                cast( 'Tiene turno 18' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.turno20 ,
		       case
		           when b.turno20 is true then
		                cast( 'Tiene turno 20' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.turno2130 ,
		       case
		           when b.turno2130 is true then
		                cast( 'Tiene turno 2130' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,		       
		       b.turnonoche ,
		       case
		           when b.turnonoche is true then
		                cast( g.nombrehoraminuto  as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.idhoraminutonoche  ,
		       h.nombrehoraminuto ,	
		       b.motivoquedada ,
		       b.turnootro ,
		       case
		           when b.turnootro is true then
		                cast( 'Tiene turno OTRO' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.idhoraminutootro ,
		       h.nombrehoraminuto as nombrehoraminutootro,		       
		       b.ausente ,
		       case
		           when b.ausente is true then
		                cast( 'Esta AUSENT' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.idmotivoausencia,
               f.nombremotivoausencia,
               b.idhoraminutofundext ,
		       i.nombrehoraminuto as nombrehoraminutootro,
		       b.motivoausencia,
		       b.motivootro,
		       
		       b.ingresoanticipado ,
		       b.idhoraminutoingant ,
		       j.nombrehoraminuto as nombrehoraminutoingant,
		       b.motivoingresoanticipado,
		       
		       a.movilizacionpropia ,
		       a.idsector ,
		       e.nombresector ,
		       b.observacion,
		       b.fechacreacion ,
		       b.usuariocreacion ,
		       b.fechamodificacion ,
		       b.usuariomodificacion 
		  from mct_operador a
		  left join traking.mct_operadorturnofund b  on a.idoperador = b.idoperador 
		  left join traking.mct_seccion d            on a.idseccionprincipal = d.idseccion
		  left join traking.mct_sector e             on a.idsector = e.idsector
		  left join traking.mct_motivoausencia f     on b.idmotivoausencia = f.idmotivoausencia 
		  left join traking.mct_horaminuto g	     on b.idhoraminutonoche = g.idhoraminuto
		  left join traking.mct_horaminuto h	     on b.idhoraminutootro = h.idhoraminuto
		  left join traking.mct_horaminuto i	     on b.idhoraminutofundext = i.idhoraminuto
		  left join traking.mct_horaminuto j	     on b.idhoraminutoingant = j.idhoraminuto
		  left join traking.mct_cargo k              on a.idcargo = k.idcargo 
		 where b.fechaturno = to_date(fechas,'yyyy-mm-dd')
		   and a.aplicacontrolturnofund is true
		order by d.ordencontroldiario, k.nombrecargo, a.nombreoperador ;
		
	else

	    RETURN QUERY
	    
		select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
		       cast(0 as bigint) ,
		       a.idoperador ,
		       a.nombreoperador,
		       a.idseccionprincipal ,
		       --d.nombreseccion  ,
		       coalesce (f.nombrecargo,'SIN CARGO'),
		       a.fechamodificacion ,
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       cast(0 as bigint) ,
		       cast('' as varchar),
		       cast('' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       cast(0 as bigint) ,
		       cast('' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       cast(0 as bigint),
               cast('' as varchar),
               cast(0 as bigint),
               cast('' as varchar),
               cast('' as varchar),
               cast('' as varchar),
               
               false,
		       cast(0 as bigint),
		       cast('' as varchar),
		       cast('' as varchar),
		       
		       a.movilizacionpropia ,
		       a.idsector ,
		       e.nombresector ,
		       cast('' as varchar),
		       a.fechacreacion ,
		       a.usuariocreacion ,
		       a.fechamodificacion ,
		       a.usuariomodificacion 
		  from mct_operador a
		  --left join traking.mct_operadorturno b   on a.idoperador = b.idoperador 
		  left join traking.mct_seccion d         on a.idseccionprincipal = d.idseccion
		  left join traking.mct_sector e          on a.idsector = e.idsector
		  left join traking.mct_cargo f           on a.idcargo = f.idcargo
		  --left join traking.mct_motivoausencia f  on b.idmotivoausencia = f.idmotivoausencia 
		  --left join traking.mct_horaminuto g	  on b.idhoraminuto = g.idhoraminuto
		 where a.estado = 1
		   and a.aplicacontrolturnofund  is true
		 order by d.ordencontroldiario, f.nombrecargo, a.nombreoperador ;
		 		
	end if;

END;
$$;


ALTER FUNCTION traking.listoperadorturnofundporfecha(fechas character varying) OWNER TO postgres;

