--
-- TOC entry 1547 (class 1255 OID 17819)
-- Name: listoperadorturnoporfechapdf(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listoperadorturnoporfechapdf(fechas character varying) RETURNS TABLE(item bigint, idoperadorturno bigint, idoperador bigint, nombreoperador character varying, idseccion bigint, nombreseccion character varying, fechaturno timestamp without time zone, turno13 boolean, nombreturno13 character varying, turno16 boolean, nombreturno16 character varying, turno18 boolean, nombreturno18 character varying, turno20 boolean, nombreturno20 character varying, turnoexcepcional boolean, nombreturnoexcepcional character varying, turnonoche boolean, nombreturnonoche character varying, idhoraminuto bigint, nombrehoraminuto character varying, turnootro boolean, nombreturnootro character varying, idhoraminutootro bigint, nombrehoraminutootro character varying, ausente boolean, nombreausente character varying, idmotivoausencia bigint, nombremotivoausencia character varying, movilizacionpropia boolean, nombresector character varying, observacion character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
declare
   sp_cantidad    integer;
BEGIN

	sp_cantidad := 0;

	select count(*)
	  into sp_cantidad
	  from mct_operadorturno mo 
	 where mo.fechaturno = to_date(fechas,'yyyy-mm-dd');

	
	if ( sp_cantidad > 0 ) then

	    RETURN QUERY
	    
		select ROW_NUMBER() OVER (ORDER BY a.movilizacionpropia, a.nombreoperador) AS item,
		       b.idoperadorturno ,
		       b.idoperador ,
		       a.nombreoperador,
		       a.idseccionprincipal ,
		       d.nombreseccion ,
		       b.fechaturno ,
		       b.turno13 ,
		       case
		           when b.turno13 is true then
		                cast( 'Tiene turno 13' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,		       
		       b.turno16 ,
		       case
		           when b.turno16 is true then
		                cast( 'Tiene turno 16' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.turno18 ,
		       case
		           when b.turno18 is true then
		                cast( 'Tiene turno 18' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.turno20 ,
		       case
		           when b.turno20 is true then
		                cast( 'Tiene turno 20' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.turnoexcepcional ,
		       case
		           when b.turnoexcepcional is true then
		                cast( 'Tiene turno EXCEPCIONAL6' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,		       
		       b.turnonoche ,
		       case
		           when b.turnonoche is true then
		                cast( 'Tiene turno NOCHE' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.idhoraminuto ,
		       g.nombrehoraminuto ,
		       
		       b.turnootro ,
		       case
		           when b.turnootro is true then
		                cast( 'Tiene turno OTRO' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.idhoraminutootro ,
		       h.nombrehoraminuto as nombrehoraminutootro,
		       
		       b.ausente ,
		       case
		           when b.ausente is true then
		                cast( 'Esta AUSENT' as varchar)
		           else
		                cast( 'No Tiene' as varchar)
		       end,
		       b.idmotivoausencia,
               f.nombremotivoausencia,
		       a.movilizacionpropia ,
		       e.nombresector ,
		       b.observacion,
		       b.fechacreacion ,
		       b.usuariocreacion ,
		       b.fechamodificacion ,
		       b.usuariomodificacion 
		  from mct_operador a
		  left join traking.mct_operadorturno b  on a.idoperador = b.idoperador 
		  left join traking.mct_seccion d        on a.idseccionprincipal = d.idseccion
		  left join traking.mct_sector e         on a.idsector = e.idsector
		  left join traking.mct_motivoausencia f on b.idmotivoausencia = f.idmotivoausencia 
		  left join traking.mct_horaminuto g	 on b.idhoraminuto = g.idhoraminuto
		  left join traking.mct_horaminuto h	 on b.idhoraminutootro = h.idhoraminuto
		 where b.fechaturno = to_date(fechas,'yyyy-mm-dd')
		   and a.aplicacontrolturno is true
		   and b.turnonoche is false
		   and b.ausente is false
		order by a.movilizacionpropia, a.nombreoperador ;
		
	else

	    RETURN QUERY
	    
		select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
		       cast(0 as bigint) ,
		       a.idoperador ,
		       a.nombreoperador,
		       a.idseccionprincipal ,
		       d.nombreseccion ,
		       a.fechamodificacion ,
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       cast(0 as bigint) ,
		       cast('' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       cast(0 as bigint) ,
		       cast('' as varchar),
		       false ,
		       cast( 'No Tiene' as varchar),
		       cast(0 as bigint),
               cast('' as varchar),
		       a.movilizacionpropia ,
		       e.nombresector ,
		       cast('' as varchar),
		       a.fechacreacion ,
		       a.usuariocreacion ,
		       a.fechamodificacion ,
		       a.usuariomodificacion 
		  from mct_operador a
		  --left join traking.mct_operadorturno b   on a.idoperador = b.idoperador 
		  left join traking.mct_seccion d         on a.idseccionprincipal = d.idseccion
		  left join traking.mct_sector e          on a.idsector = e.idsector
		  --left join traking.mct_motivoausencia f  on b.idmotivoausencia = f.idmotivoausencia 
		  --left join traking.mct_horaminuto g	  on b.idhoraminuto = g.idhoraminuto
		 where a.estado = 1
		   and a.aplicacontrolturno is true
		 order by d.nombreseccion, a.nombreoperador ;
		 		
	end if;

END;
$$;


ALTER FUNCTION traking.listoperadorturnoporfechapdf(fechas character varying) OWNER TO postgres;

