CREATE FUNCTION traking.listoperaporareaapp(idareaapps bigint) RETURNS TABLE(idoperator bigint, operatorname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		select a.idoperador ,
		       a.nombreoperador
		  from mct_operador a
		 where a.idareaapp = idareaapps
		   and a.estado in (1)
        order by a.nombreoperador;

END;
$$;


