--

CREATE FUNCTION traking.listoperaporareaappsinelmismo(idareaapps bigint, idoperadors bigint) RETURNS TABLE(idoperator bigint, operatorname character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
