--

CREATE FUNCTION traking.listoperatorbyhr(roadmapcode character varying) RETURNS TABLE(idprofile bigint, profilename character varying, idoperator bigint, nameoperator character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    
		select distinct b.idperfil ,
		       c.nombreperfil ,
		       a.idoperador ,       
		       b.nombreoperador ,
		       b.estado ,
		       d.nombreestado ,
		       b.fechacreacion ,
		       b.usuariocreacion ,
		       b.fechamodificacion ,
		       b.usuariomodificacion 
		  from mct_movimientoordentrabajo a,
		       mct_operador b,
		       mct_perfil c,
		       mct_estado d
		 where codhojaruta = roadmapcode
		   and a.idoperador = b.idoperador 
		   and b.idperfil = c.idperfil 
		   and b.estado = d.idestado
		   and b.estado in (0,1);

END;
$$;


