--

CREATE FUNCTION traking.listoperatorbysection(idsections bigint) RETURNS TABLE(idoperator bigint, operatorname character varying, idsection bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT a.idoperador,
               b.nombreoperador ,
               a.idseccion
          FROM mct_operadorseccion a,
               mct_operador b
         where a.idseccion = idsections
           and a.idoperador = b.idoperador
        order by b.nombreoperador ;

END;
$$;


