--
-- TOC entry 2144 (class 1255 OID 17835)
-- Name: listpart(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listpart() RETURNS TABLE(idpart bigint, partname character varying, idblueprint bigint, blueprintname character varying, idmaterial bigint, materialname character varying, manufacturingcost integer, principal bigint, principalname character varying, idparttype bigint, parttypename character varying, critical bigint, criticalname character varying, comercialdesc character varying, idpurchasetype bigint, purchasetypename character varying, idcomponent bigint, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_parte.idparte, 
               traking.mct_parte.nombreparte,                    
               traking.mct_parte.idplano, 
               traking.mct_plano.nombreplano,
               traking.mct_parte.idmaterial, 
               traking.mct_material.nombrematerial,
               traking.mct_parte.costofabricacion, 
               traking.mct_parte.esprincipal,
               mb.nombreboleano,
               traking.mct_parte.idtipoparte,   
               traking.mct_tipoparte.nombretipoparte,
               traking.mct_parte.escritico,
               traking.mct_boleano.nombreboleano,
               traking.mct_parte.descripcioncomercial ,
               traking.mct_parte.idtipocompra ,
               traking.mct_tipocompra.nombretipocompra ,
               traking.mct_parte.idcomponente ,
               traking.mct_parte.estado,
               traking.mct_estado.nombreestado,  
               traking.mct_parte.fechacreacion,
               traking.mct_parte.usuariocreacion,
               traking.mct_parte.fechamodificacion,
               traking.mct_parte.usuariomodificacion
        FROM traking.mct_parte 
        left join traking.mct_plano on traking.mct_parte.idplano=traking.mct_plano.idplano
        left join traking.mct_material on traking.mct_parte.idmaterial=traking.mct_material.idmaterial
        left join traking.mct_estado on traking.mct_parte.estado=traking.mct_estado.idestado
        left join traking.mct_boleano on traking.mct_parte.escritico=traking.mct_boleano.idboleano
        left join traking.mct_tipoparte on traking.mct_parte.idtipoparte=traking.mct_tipoparte.idtipoparte
        left join traking.mct_boleano mb on traking.mct_parte.esprincipal=mb.idboleano
        left join traking.mct_tipocompra on traking.mct_parte.idtipocompra = traking.mct_tipocompra.idtipocompra 
        order by 2 asc;

END;
$$;


ALTER FUNCTION traking.listpart() OWNER TO postgres;

