--
-- TOC entry 1656 (class 1255 OID 17837)
-- Name: listpartbybp(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listpartbybp(generalplan character varying, idproducts bigint) RETURNS TABLE(idpart bigint, partname text, idblueprint bigint, blueprintname character varying, idmaterial bigint, materialname character varying, manufacturingcost integer, principal bigint, principalname character varying, idparttype bigint, parttypename character varying, critical bigint, criticalname character varying, comercialdesc character varying, idpurchasetype bigint, purchasetypename character varying, idcomponent bigint, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_parte.idparte, 
               traking.mct_parte.nombreparte||'-'||traking.mct_plano.nombreplano,                    
               traking.mct_parte.idplano, 
               traking.mct_plano.nombreplano,
               traking.mct_parte.idmaterial, 
               traking.mct_material.nombrematerial,
               traking.mct_parte.costofabricacion, 
               traking.mct_parte.esprincipal,
               traking.mct_boleano.nombreboleano,
               traking.mct_parte.idtipoparte,   
               traking.mct_tipoparte.nombretipoparte,
               traking.mct_parte.escritico,
               mb.nombreboleano,
               traking.mct_parte.descripcioncomercial ,
               traking.mct_parte.idtipocompra ,
               traking.mct_tipocompra.nombretipocompra ,
               traking.mct_parte.idcomponente ,
               traking.mct_parte.estado,
               traking.mct_estado.nombreestado,  
               traking.mct_parte.fechacreacion,
               traking.mct_parte.usuariocreacion,
               traking.mct_parte.fechamodificacion,
               traking.mct_parte.usuariomodificacion
        FROM traking.mct_parte 
        inner join traking.mct_plano 		on traking.mct_parte.idplano=traking.mct_plano.idplano 
               and traking.mct_plano.nombreplano  like '%'||generalplan||'%'
        left join traking.mct_material 		on traking.mct_parte.idmaterial=traking.mct_material.idmaterial
        left join traking.mct_estado 		on traking.mct_parte.estado=traking.mct_estado.idestado
        left join traking.mct_boleano 		on traking.mct_parte.escritico=traking.mct_boleano.idboleano
        left join traking.mct_tipoparte 	on traking.mct_parte.idtipoparte=traking.mct_tipoparte.idtipoparte
        left join traking.mct_boleano mb 	on traking.mct_parte.esprincipal=mb.idboleano
        left join traking.mct_tipocompra 	on traking.mct_parte.idtipocompra = traking.mct_tipocompra.idtipocompra
        --left join traking.mct_plano         on traking.mct_plano.nombreplano  like '%'||generalplan||'%'
       where traking.mct_parte.idparte not in ( select mct_productoparte.idparte from mct_productoparte 
												where idproducto = idproducts
												  and mct_productoparte.idparte =  traking.mct_parte.idparte)
        order by 2 asc;

END;
$$;


ALTER FUNCTION traking.listpartbybp(generalplan character varying, idproducts bigint) OWNER TO postgres;

--
-- TOC entry 2148 (class 1255 OID 17838)
-- Name: listpartbyproduct(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listpartbyproduct(idproducts bigint) RETURNS TABLE(idpart bigint, partname character varying, idblueprint bigint, blueprintname character varying, idmaterial bigint, materialname character varying, manufacturingcost integer, principal bigint, principalname character varying, idparttype bigint, parttypename character varying, critical bigint, criticalname character varying, comercialdesc character varying, idpurchasetype bigint, purchasetypename character varying, idcomponent bigint, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_parte.idparte, 
               traking.mct_parte.nombreparte,                    
               traking.mct_parte.idplano, 
               traking.mct_plano.nombreplano,
               traking.mct_parte.idmaterial, 
               traking.mct_material.nombrematerial,
               traking.mct_parte.costofabricacion, 
               traking.mct_parte.esprincipal,
               mb.nombreboleano,
               traking.mct_parte.idtipoparte,   
               traking.mct_tipoparte.nombretipoparte,
               traking.mct_parte.escritico,
               traking.mct_boleano.nombreboleano,
               traking.mct_parte.descripcioncomercial ,
               traking.mct_parte.idtipocompra ,
               traking.mct_tipocompra.nombretipocompra ,
               traking.mct_parte.idcomponente ,
               traking.mct_parte.estado,
               traking.mct_estado.nombreestado,  
               traking.mct_parte.fechacreacion,
               traking.mct_parte.usuariocreacion,
               traking.mct_parte.fechamodificacion,
               traking.mct_parte.usuariomodificacion
        FROM traking.mct_parte 
        left join traking.mct_plano on traking.mct_parte.idplano=traking.mct_plano.idplano
        left join traking.mct_material on traking.mct_parte.idmaterial=traking.mct_material.idmaterial
        left join traking.mct_estado on traking.mct_parte.estado=traking.mct_estado.idestado
        left join traking.mct_boleano on traking.mct_parte.escritico=traking.mct_boleano.idboleano
        left join traking.mct_tipoparte on traking.mct_parte.idtipoparte=traking.mct_tipoparte.idtipoparte
        left join traking.mct_boleano mb on traking.mct_parte.esprincipal=mb.idboleano
        left join traking.mct_tipocompra on traking.mct_parte.idtipocompra = traking.mct_tipocompra.idtipocompra 
        inner join traking.mct_producto on traking.mct_plano.nombreplano like '%'||traking.mct_producto.planogeneral||'%' and traking.mct_producto.idproducto = idproducts
        order by 1 asc;

END;
$$;


ALTER FUNCTION traking.listpartbyproduct(idproducts bigint) OWNER TO postgres;

