--
-- TOC entry 1386 (class 1255 OID 17845)
-- Name: listplanocontrolmaqimagenbycomponente(character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listplanocontrolmaqimagenbycomponente(qrcodes character varying) RETURNS TABLE(idcomponenteplanocontrolmaq bigint, idcomponente bigint, nombrecomponente character varying, descripcionplano character varying, plano text)
    LANGUAGE plpgsql
    AS $$
declare

	sp_idcomponente	bigint;
  
begin
	
	select b.idcomponente 
	  into sp_idcomponente
	  from mct_detallehojarutatemp a,
	       mct_hojarutatemp b
	 where a.codhojaruta = qrcodes
	   and a.idhojarutatemp = b.idhojarutatemp ;

    RETURN QUERY
        SELECT traking.mct_componenteplanocontrolmaq.idcomponenteplanocontrolmaq ,
        	   traking.mct_componenteplanocontrolmaq.idcomponente ,
        	   traking.mct_componente.nombrecomponente ,
       		   traking.mct_componenteplanocontrolmaq.descripcionplano ,
               traking.mct_componenteplanocontrolmaq.plano 
        FROM traking.mct_componenteplanocontrolmaq
        left join traking.mct_componente on traking.mct_componente.idcomponente = traking.mct_componenteplanocontrolmaq.idcomponente
       where traking.mct_componenteplanocontrolmaq.idcomponente = sp_idcomponente;

END;
$$;


