-- Name: listproduct(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listproduct() RETURNS TABLE(idproduct bigint, productname character varying, idmanufacturer bigint, manufacturername character varying, idmodel bigint, modelname character varying, idcustomer bigint, customername character varying, status bigint, statusname character varying, flowval bigint, rpmval bigint, lengthval bigint, heightval bigint, powerval bigint, idphaseparam bigint, phaseparamname character varying, generalplan character varying, idmaterial bigint, materialname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_producto.idproducto, 
               traking.mct_producto.nombreproducto,                  
               traking.mct_producto.idfabricante, 
               traking.mct_fabricante.nombrefabricante,
               traking.mct_producto.idmodelo, 
               traking.mct_modelo.nombremodelo,
               traking.mct_producto.idcliente, 
               traking.mct_cliente.nombrecliente,
               traking.mct_producto.estado,
               traking.mct_estado.nombreestado, 
               traking.mct_producto.caudal,
               traking.mct_producto.rpm,
               traking.mct_producto.largo,
               traking.mct_producto.altura,
               traking.mct_producto.potencia,
               traking.mct_producto.idetapaparam,
               traking.mct_etapaparam.nombreparam,
               traking.mct_producto.planogeneral,
               traking.mct_producto.idmaterial,
               traking.mct_material.nombrematerial,
               traking.mct_producto.fechacreacion,
               traking.mct_producto.usuariocreacion,
               traking.mct_producto.fechamodificacion,
               traking.mct_producto.usuariomodificacion
        FROM traking.mct_producto, 
             traking.mct_estado,
             traking.mct_modelo,
             traking.mct_cliente,
             traking.mct_fabricante,
             traking.mct_etapaparam,
             traking.mct_material 
       where traking.mct_producto.estado=traking.mct_estado.idestado
         and traking.mct_producto.idmodelo=traking.mct_modelo.idmodelo
         and traking.mct_producto.idcliente=traking.mct_cliente.idcliente
         and traking.mct_producto.idfabricante=traking.mct_fabricante.idfabricante
         and traking.mct_producto.idetapaparam=traking.mct_etapaparam.idetapaparam
         and traking.mct_producto.idmaterial = traking.mct_material.idmaterial
        order by traking.mct_producto.idproducto desc;
        
END;
$$;


ALTER FUNCTION traking.listproduct() OWNER TO postgres;

