CREATE FUNCTION traking.listproductostockmaestranzabomba(idclientes bigint) RETURNS TABLE(idproducto bigint, nombreproducto character varying)
    LANGUAGE plpgsql
    AS $$
begin
	
	RETURN QUERY

	select a.idproducto,
	       cast(coalesce(c.sigla||' - '||b.nombremodelo||' - '||d.nombreparam, 'SIN PROD') as varchar)
	  from mct_producto a 
	  left join mct_modelo b on a.idmodelo = b.idmodelo 
	  left join mct_subfamilia c on b.idsubfamilia = c.idsubfamilia 
	  left join mct_etapaparam d on a.idetapaparam = d.idetapaparam 
	where idcliente = idclientes
	order by b.idsubfamilia asc, b.nombremodelo asc;

END;
$$;


