--
-- TOC entry 1800 (class 1255 OID 17862)
-- Name: listrecorridocontrolconsulta(character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listrecorridocontrolconsulta(fechads character varying, fechahs character varying, idoperadors bigint) RETURNS TABLE(item bigint, cantidad bigint, idoperador bigint, nombreoperador character varying, idcargo bigint, nombrecargo character varying, resumenpt numeric, resumenrt numeric, resumenepp numeric, resumenmar numeric)
    LANGUAGE plpgsql
    AS $$
declare
   sp_cantidad    integer;
begin
	
	if ( idoperadors = -1 ) then

	    return QUERY 
	    
		select ROW_NUMBER() OVER (ORDER BY d.ordencontroldiario, k.nombrecargo, b.nombreoperador) AS item,
		       count(*),
		       a.idoperador  ,
		       b.nombreoperador,
		       k.idcargo,
		       coalesce (k.nombrecargo,'SIN CARGO'),
		       sum(a.resumenpt)/count(*),
		       sum(a.resumenrt)/count(*),
		       sum(a.resumenepp)/count(*),
		       sum(a.resumenmar)/count(*)
		  from mct_recorridocontrol a
		  left join mct_operador b          on a.idoperador = b.idoperador
		  left join traking.mct_seccion d   on b.idseccionprincipal = d.idseccion
		  left join traking.mct_cargo k     on b.idcargo = k.idcargo 
		where a.fechacontrol >= to_date(fechads,'yyyy-mm-dd') and a.fechacontrol <= to_date(fechahs,'yyyy-mm-dd')
		group by a.idoperador, b.nombreoperador, k.idcargo, k.nombrecargo, d.ordencontroldiario
		order by d.ordencontroldiario, k.nombrecargo, b.nombreoperador ;	
	
	else
	
	    return QUERY
	    
		select ROW_NUMBER() OVER (ORDER BY d.ordencontroldiario, k.nombrecargo, b.nombreoperador) AS item,
		       count(*),
		       a.idoperador  ,
		       b.nombreoperador,
		       k.idcargo,
		       coalesce (k.nombrecargo,'SIN CARGO'),
		       sum(a.resumenpt)/count(*),
		       sum(a.resumenrt)/count(*),
		       sum(a.resumenepp)/count(*),
		       sum(a.resumenmar)/count(*)
		  from mct_recorridocontrol a
		  left join mct_operador b          on a.idoperador = b.idoperador
		  left join traking.mct_seccion d   on b.idseccionprincipal = d.idseccion
		  left join traking.mct_cargo k     on b.idcargo = k.idcargo 
		where a.fechacontrol >= to_date(fechads,'yyyy-mm-dd') and a.fechacontrol <= to_date(fechahs,'yyyy-mm-dd')
		  and a.idoperador = idoperadors
		group by a.idoperador, b.nombreoperador, k.idcargo, k.nombrecargo, d.ordencontroldiario
		order by d.ordencontroldiario, k.nombrecargo, b.nombreoperador ;	
	
	end if;


END;
$$;


ALTER FUNCTION traking.listrecorridocontrolconsulta(fechads character varying, fechahs character varying, idoperadors bigint) OWNER TO postgres;

--
-- TOC entry 1312 (class 1255 OID 17863)
-- Name: listrecorridocontrolporfecha(character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listrecorridocontrolporfecha(fechas character varying, origenf bigint) RETURNS TABLE(item bigint, idrecorridocontrol bigint, idoperador bigint, nombreoperador character varying, idseccion bigint, nombreseccion character varying, fechacontrol timestamp without time zone, control1pt boolean, control1rt boolean, control1epp boolean, control1mar boolean, control2pt boolean, control2rt boolean, control2epp boolean, control2mar boolean, control3pt boolean, control3rt boolean, control3epp boolean, control3mar boolean, control4pt boolean, control4rt boolean, control4epp boolean, control4mar boolean, resumenpt numeric, resumenrt numeric, resumenepp numeric, resumenmar numeric, observacion character varying, esfundicion1 boolean, esfundicion2 boolean, esmaestranza boolean, ausente boolean, idmotivoausencia bigint, nombremotivoausencia character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
declare
   sp_cantidad    integer;
BEGIN

	sp_cantidad := 0;

    if ( origenf = 1 ) then
    
		select count(*)
		  into sp_cantidad
		  from mct_recorridocontrol mo 
		 where mo.fechacontrol = to_date(fechas,'yyyy-mm-dd')
		   and mo.esfundicion1 is true;
	
		
		if ( sp_cantidad > 0 ) then
	
		    RETURN QUERY
		    
			select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
			       b.idrecorridocontrol  ,
			       b.idoperador ,
			       a.nombreoperador,
			       a.idseccionprincipal , 
			       coalesce (k.nombrecargo,'SIN CARGO'),
			       b.fechacontrol  ,
			       b.control1pt  ,	       
			       b.control1rt  ,
			       b.control1epp  ,
			       b.control1mar  ,
			       b.control2pt  ,	       
			       b.control2rt  ,
			       b.control2epp  ,
			       b.control2mar  ,
			       b.control3pt  ,	       
			       b.control3rt  ,
			       b.control3epp  ,
			       b.control3mar  ,
			       b.control4pt  ,	       
			       b.control4rt  ,
			       b.control4epp  ,
			       b.control4mar  ,
			       b.resumenpt  ,	       
			       b.resumenrt  ,
			       b.resumenepp  ,
			       b.resumenmar  ,
			       b.observacion,
			       b.esfundicion1,
			       b.esfundicion2,
			       b.esmaestranza,
			       b.ausente ,
			       b.idmotivoausencia ,
			       l.nombremotivoausencia ,
			       b.fechacreacion ,
			       b.usuariocreacion ,
			       b.fechamodificacion ,
			       b.usuariomodificacion 
			  from mct_operador a
			  left join traking.mct_recorridocontrol b  on a.idoperador = b.idoperador 
			  left join traking.mct_seccion d           on a.idseccionprincipal = d.idseccion
			  left join traking.mct_cargo k             on a.idcargo = k.idcargo 
			  left join traking.mct_motivoausencia l    on b.idmotivoausencia = l.idmotivoausencia 
			 where b.fechacontrol = to_date(fechas,'yyyy-mm-dd')
			   and b.esfundicion1 is true
			 order by d.ordencontroldiario, k.nombrecargo, a.nombreoperador ;
			

		else
	
		    RETURN QUERY
		    
			select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
			       cast(0 as bigint) ,
			       a.idoperador ,
			       a.nombreoperador,
			       a.idseccionprincipal , 
			       coalesce (k.nombrecargo,'SIN CARGO'),
			       a.fechamodificacion  ,
			       false  ,	       
			       false  ,
			       false  ,
			       false  ,	       
			       false  ,
			       false  ,			       
			       false  ,	       
			       false  ,
			       false  ,			       
			       false  ,	       
			       false ,
			       false  ,	
			       false  ,
			       false  ,
			       false  ,
			       false ,
			       cast(0 as numeric)  ,	       
			       cast(0 as numeric)  ,
			       cast(0 as numeric)  ,
			       cast(0 as numeric)  ,
			       cast('' as varchar),
			       true as esfundicion1,
			       false as esfundicion2,
			       false as esmaestranza,
			       false ,
			       cast(0 as bigint) ,
			       cast('' as varchar),
			       a.fechacreacion ,
			       a.usuariocreacion ,
			       a.fechamodificacion ,
			       a.usuariomodificacion 
			  from mct_operador a
			  --left join traking.mct_recorridocontrol b  on a.idoperador = b.idoperador 
			  left join traking.mct_seccion d           on a.idseccionprincipal = d.idseccion
			  left join traking.mct_cargo k             on a.idcargo = k.idcargo 
			 where a.estado = 1
			   and a.aplicacontrolturnofund  = true
			order by d.ordencontroldiario, k.nombrecargo, a.nombreoperador ;
		
		end if; 
    
    elsif ( origenf = 2 ) then
    
		select count(*)
		  into sp_cantidad
		  from mct_recorridocontrol mo 
		 where mo.fechacontrol = to_date(fechas,'yyyy-mm-dd')
		   and mo.esfundicion2 is true;
	
		
		if ( sp_cantidad > 0 ) then
	
		    RETURN QUERY
		    
			select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
			       b.idrecorridocontrol  ,
			       b.idoperador ,
			       a.nombreoperador,
			       a.idseccionprincipal , 
			       coalesce (k.nombrecargo,'SIN CARGO'),
			       b.fechacontrol  ,
			       b.control1pt  ,	       
			       b.control1rt  ,
			       b.control1epp  ,
			       b.control1mar  ,
			       b.control2pt  ,	       
			       b.control2rt  ,
			       b.control2epp  ,
			       b.control2mar  ,
			       b.control3pt  ,	       
			       b.control3rt  ,
			       b.control3epp  ,
			       b.control3mar  ,
			       b.control4pt  ,	       
			       b.control4rt  ,
			       b.control4epp  ,
			       b.control4mar  ,
			       b.resumenpt  ,	       
			       b.resumenrt  ,
			       b.resumenepp  ,
			       b.resumenmar  ,
			       b.observacion,
			       b.esfundicion1,
			       b.esfundicion2,
			       b.esmaestranza,
			       b.ausente ,
			       b.idmotivoausencia ,
			       l.nombremotivoausencia ,
			       b.fechacreacion ,
			       b.usuariocreacion ,
			       b.fechamodificacion ,
			       b.usuariomodificacion 
			  from mct_operador a
			  left join traking.mct_recorridocontrol b  on a.idoperador = b.idoperador 
			  left join traking.mct_seccion d           on a.idseccionprincipal = d.idseccion
			  left join traking.mct_cargo k             on a.idcargo = k.idcargo 
			  left join traking.mct_motivoausencia l    on b.idmotivoausencia = l.idmotivoausencia 
			 where b.fechacontrol = to_date(fechas,'yyyy-mm-dd')
			   and b.esfundicion2  = true
			order by d.ordencontroldiario, k.nombrecargo, a.nombreoperador ;
			
		else
	
		    RETURN QUERY
		    
			select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
			       cast(0 as bigint) ,
			       a.idoperador ,
			       a.nombreoperador,
			       a.idseccionprincipal , 
			       coalesce (k.nombrecargo,'SIN CARGO'),
			       a.fechamodificacion  ,
			       false  ,	       
			       false  ,
			       false  ,
			       false  ,	       
			       false  ,
			       false  ,			       
			       false  ,	       
			       false  ,
			       false  ,			       
			       false  ,	       
			       false ,
			       false  ,	
			       false  ,
			       false  ,
			       false  ,
			       false ,
			       cast(0 as numeric)  ,	       
			       cast(0 as numeric)  ,
			       cast(0 as numeric)  ,
			       cast(0 as numeric)  ,
			       cast('' as varchar),
			       false as esfundicion1,
			       true as esfundicion2,
			       false as esmaestranza,
			       false ,
			       cast(0 as bigint) ,
			       cast('' as varchar),
			       a.fechacreacion ,
			       a.usuariocreacion ,
			       a.fechamodificacion ,
			       a.usuariomodificacion 
			  from mct_operador a
			  --left join traking.mct_recorridocontrol b  on a.idoperador = b.idoperador 
			  left join traking.mct_seccion d           on a.idseccionprincipal = d.idseccion
			  left join traking.mct_cargo k             on a.idcargo = k.idcargo 
			 where a.estado = 1
			   and a.aplicacontrolturnofund2 = true
			order by d.ordencontroldiario, k.nombrecargo, a.nombreoperador ;
		
		end if;
		
    elsif ( origenf = 3 ) then
    
		select count(*)
		  into sp_cantidad
		  from mct_recorridocontrol mo 
		 where mo.fechacontrol = to_date(fechas,'yyyy-mm-dd')
		   and mo.esmaestranza is true;
	
		
		if ( sp_cantidad > 0 ) then
	
		    RETURN QUERY
		    
			select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
			       b.idrecorridocontrol  ,
			       b.idoperador ,
			       a.nombreoperador,
			       a.idseccionprincipal , 
			       coalesce (k.nombrecargo,'SIN CARGO'),
			       b.fechacontrol  ,
			       b.control1pt  ,	       
			       b.control1rt  ,
			       b.control1epp  ,
			       b.control1mar  ,
			       b.control2pt  ,	       
			       b.control2rt  ,
			       b.control2epp  ,
			       b.control2mar  ,
			       b.control3pt  ,	       
			       b.control3rt  ,
			       b.control3epp  ,
			       b.control3mar  ,
			       b.control4pt  ,	       
			       b.control4rt  ,
			       b.control4epp  ,
			       b.control4mar  ,
			       b.resumenpt  ,	       
			       b.resumenrt  ,
			       b.resumenepp  ,
			       b.resumenmar  ,
			       b.observacion,
			       b.esfundicion1,
			       b.esfundicion2,
			       b.esmaestranza,
			       b.ausente ,
			       b.idmotivoausencia ,
			       l.nombremotivoausencia ,
			       b.fechacreacion ,
			       b.usuariocreacion ,
			       b.fechamodificacion ,
			       b.usuariomodificacion 
			  from mct_operador a
			       join traking.mct_recorridocontrol b  on a.idoperador = b.idoperador 
			  left join traking.mct_seccion d           on a.idseccionprincipal = d.idseccion
			  left join traking.mct_cargo k             on a.idcargo = k.idcargo 
			  left join traking.mct_motivoausencia l    on b.idmotivoausencia = l.idmotivoausencia 
			 where b.fechacontrol = to_date(fechas,'yyyy-mm-dd')
			   and b.esmaestranza is true
			order by d.ordencontroldiario, k.nombrecargo, a.nombreoperador ;
			
		else
	
		    RETURN QUERY
		    
			select ROW_NUMBER() OVER (ORDER BY d.nombreseccion, a.nombreoperador) AS item,
			       cast(0 as bigint) ,
			       a.idoperador ,
			       a.nombreoperador,
			       a.idseccionprincipal , 
			       coalesce (k.nombrecargo,'SIN CARGO'),
			       a.fechamodificacion,
			       false  ,	       
			       false  ,
			       false  ,
			       false  ,	       
			       false  ,
			       false  ,			       
			       false  ,	       
			       false  ,
			       false  ,			       
			       false  ,	       
			       false  ,
			       false  ,	
			       false  ,
			       false  ,
			       false  ,
			       false ,
			       cast(0 as numeric)  ,	       
			       cast(0 as numeric)  ,
			       cast(0 as numeric)  ,
			       cast(0 as numeric)  ,
			       cast('' as varchar),
			       false as esfundicion1,
			       false as esfundicion2,
			       true as esmaestranza,
			       false ,
			       cast(0 as bigint) ,
			       cast('' as varchar),
			       a.fechacreacion ,
			       a.usuariocreacion ,
			       a.fechamodificacion ,
			       a.usuariomodificacion 
			  from mct_operador a
			  --left join traking.mct_recorridocontrol b  on a.idoperador = b.idoperador 
			  left join traking.mct_seccion d           on a.idseccionprincipal = d.idseccion
			  left join traking.mct_cargo k             on a.idcargo = k.idcargo 
			 where a.estado = 1
			   and a.aplicacontrolturno is true
			order by d.ordencontroldiario, k.nombrecargo, a.nombreoperador ;
			 		
		end if;
    
    end if;
   


END;
$$;


ALTER FUNCTION traking.listrecorridocontrolporfecha(fechas character varying, origenf bigint) OWNER TO postgres;

