CREATE FUNCTION traking.listsection() RETURNS TABLE(idsection bigint, namesection character varying, codesection character varying, codesectionprod character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying, idarea bigint, nombrearea character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_seccion.idseccion, 
               traking.mct_seccion.nombreseccion,
               traking.mct_seccion.codigoseccion, 
               traking.mct_seccion.codigoseccionprod , 
               traking.mct_seccion.estado, 
               traking.mct_estado.nombreestado,
               traking.mct_seccion.fechacreacion,
               traking.mct_seccion.usuariocreacion,
               traking.mct_seccion.fechamodificacion,
               traking.mct_seccion.usuariomodificacion,
               traking.mct_seccion.idarea, 
               traking.mct_area.nombrearea
          FROM traking.mct_seccion 
          left join traking.mct_estado on traking.mct_seccion.estado=traking.mct_estado.idestado
          left join traking.mct_area   on traking.mct_area.idarea = traking.mct_seccion.idarea
         where traking.mct_seccion.estado in (0,1)
         order by traking.mct_seccion.nombreseccion asc;

END;
