-- Name: listsla(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listsla() RETURNS TABLE(idsla bigint, slaname character varying, initialstatus bigint, initialstatusname character varying, finalstatus bigint, finalstatusname character varying, idbolean bigint, boleanname character varying, rembbalinea bigint, rembbadiseno bigint, remreplinea bigint, remrepdiseno bigint, fabbbalinea bigint, fabbbadiseno bigint, fabreplinea bigint, fabrepdiseno bigint, warningday bigint, retry bigint, idlist bigint, listname character varying, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
	
    RETURN QUERY
        SELECT traking.mct_sla.idsla, 
               traking.mct_sla.nombresla ,
               traking.mct_sla.idestadoinicial, 
               a.nombreestado,
               traking.mct_sla.idestadofinal, 
               b.nombreestado,
               traking.mct_sla.escritico, 
               traking.mct_boleano.nombreboleano ,

               traking.mct_sla.rembbalinea , 
               traking.mct_sla.rembbadiseno , 
               traking.mct_sla.remreplinea , 
               traking.mct_sla.remrepdiseno , 
               
               traking.mct_sla.fabbbalinea , 
               traking.mct_sla.fabbbadiseno , 
               traking.mct_sla.fabreplinea , 
               traking.mct_sla.fabrepdiseno ,
               
               traking.mct_sla.inicioaviso , 
               traking.mct_sla.reintentos, 
               traking.mct_sla.idlista, 
               traking.mct_lista.nombrelista ,
               traking.mct_sla.estado,
               traking.mct_estado.nombreestado,
               traking.mct_sla.fechacreacion,
               traking.mct_sla.usuariocreacion,
               traking.mct_sla.fechamodificacion,
               traking.mct_sla.usuariomodificacion
        FROM traking.mct_sla, 
             traking.mct_estado,
             traking.mct_estadoorden a,
             traking.mct_estadoorden b,
             traking.mct_boleano,
             traking.mct_lista
    WHERE traking.mct_sla.estado=traking.mct_estado.idestado
      and traking.mct_sla.idestadoinicial=a.idestadoorden 
      and traking.mct_sla.idestadofinal =b.idestadoorden 
      and traking.mct_sla.escritico = traking.mct_boleano.idboleano 
      and traking.mct_sla.idlista  = traking.mct_lista.idlista 
     order by traking.mct_sla.idsla;

END;
$$;


