--
-- TOC entry 1954 (class 1255 OID 17885)
-- Name: listsolcompbytab(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listsolcompbytab(idorkorder bigint, idtab bigint) RETURNS TABLE(indexrow bigint, idsolcomp bigint, idworkorder bigint, partname character varying, quantity bigint, materialname character varying, repaircriteria character varying, repair character varying, blueprintname character varying, deleterow character varying, usercreate character varying, datecreate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN

	
	if ( idtab = 0 ) then
	
        RETURN QUERY
        
		SELECT a.indicefila ,
		       a.idsolcomp, 
		       a.idordentrabajo, 
		       a.nombreparte, 
		       a.cantidad, 
		       a.material, 
		       a.criterio, 
		       a.reparacion, 
		       a.plano, 
		       cast('No' as varchar),
		       a.usuariocreacion, 
		       a.fechacreacion
     	  FROM traking.mct_solcompinicial a
	     WHERE a.idordentrabajo = idorkorder
      order by a.nombreparte asc;
    
    elsif ( idtab = 1 ) then

        RETURN QUERY
        
		SELECT a.indicefila ,
		       a.solcomp, 
		       a.idordentrabajo, 
		       a.nombreparte, 
		       a.cantidad, 
		       a.material, 
		       a.criterio, 
		       a.reparacion, 
		       a.plano, 
		       cast('No' as varchar),
		       a.usuariocreacion, 
		       a.fechacreacion
     	  FROM traking.mct_solcomp a
	     WHERE a.idordentrabajo = idorkorder
      order by a.nombreparte asc;
     
	     
	end if;
    

     
END;
$$;


