--
-- TOC entry 1228 (class 1255 OID 17886)
-- Name: listsolcompcabecera(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listsolcompcabecera() RETURNS TABLE(idsolcompcabecera bigint, idordentrabajo bigint, idusuario bigint, nombreusuario character varying, idsection bigint, nombresection character varying, idorigensolicitud bigint, nombreorigensolicitud character varying, requestdate timestamp without time zone, solicitudurgente boolean, nombresolicitudurgente character varying, observacion character varying, importacion boolean, status bigint, statusname character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying, impreso boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
        SELECT traking.mct_solcompcabecera.idsolcompcabecera ,
               traking.mct_solcompcabecera.idordentrabajo ,
               traking.mct_solcompcabecera.idusuario ,
               traking.mct_usuario.nombre ,
               traking.mct_solcompcabecera.idseccion ,
               traking.mct_seccion.nombreseccion ,
               traking.mct_solcompcabecera.idorigensolicitud ,
               case
                   when traking.mct_solcompcabecera.idorigensolicitud = 1 then 
                        cast('OT' as varchar)
                   when traking.mct_solcompcabecera.idorigensolicitud = 2 then 
                        cast('MANTENCION' as varchar)
                   when traking.mct_solcompcabecera.idorigensolicitud = 3 then 
                        cast('STOCK' as varchar)
                   else cast('OTRA' as varchar)
               end,
               traking.mct_solcompcabecera.fecharequerida ,
               traking.mct_solcompcabecera.solicitudurgente ,
               case
                   when traking.mct_solcompcabecera.solicitudurgente = true then 
                        cast('URGENTE' as varchar)
                   else  
                        cast('Normal' as varchar)
               end,
               traking.mct_solcompcabecera.observacion ,
               traking.mct_solcompcabecera.importacion ,
               traking.mct_solcompcabecera.estado,
               traking.mct_estado.nombreestado,
               traking.mct_solcompcabecera.fechacreacion,
               traking.mct_solcompcabecera.usuariocreacion,
               traking.mct_solcompcabecera.fechamodificacion,
               traking.mct_solcompcabecera.usuariomodificacion,
               traking.mct_solcompcabecera.impreso
          FROM traking.mct_solcompcabecera 
          left join traking.mct_estado   on traking.mct_solcompcabecera.estado=traking.mct_estado.idestado
          left join traking.mct_usuario  on traking.mct_solcompcabecera.idusuario = traking.mct_usuario.idusuario 
          left join traking.mct_seccion  on traking.mct_solcompcabecera.idseccion = traking.mct_seccion.idseccion 
          order by traking.mct_solcompcabecera.idsolcompcabecera desc;

END;
$$;


ALTER FUNCTION traking.listsolcompcabecera() OWNER TO postgres;

--
-- TOC entry 1641 (class 1255 OID 17887)
-- Name: listsolcompcabecerabyfecha(bigint, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listsolcompcabecerabyfecha(idindicador bigint, startdate character varying, enddate character varying) RETURNS TABLE(itemsol bigint, idsolcompcabecera bigint, idordentrabajo bigint, idusuario bigint, nombreusuario character varying, idsection bigint, nombresection character varying, idorigensolicitud bigint, nombreorigensolicitud character varying, requestdate character varying, solicitudurgente boolean, nombresolicitudurgente character varying, observacion character varying, cantidadtot bigint, cantidadrec bigint, avanceco numeric, atrasoco bigint, status bigint, statusname character varying, importacion boolean)
    LANGUAGE plpgsql
    AS $$
Declare
	rec1 				record;
	sp_cantidad			bigint;
    sp_repetitividad	bigint;
   
    sp_cantidad_co		integer;
    sp_recept_co		integer;
    sp_atraso_co        integer;
    sp_avance_co		numeric;
    sp_cantidadtot		integer;
    sp_cantidadrec		integer;

BEGIN
-- iddefectoi = -1: Todos

    
		 IF ( idindicador = -1 ) THEN 

	      	    FOR rec1 IN (
	      	    
			        SELECT ROW_NUMBER() OVER (ORDER BY traking.mct_solcompcabecera.fecharequerida asc) AS item,
			               traking.mct_solcompcabecera.idsolcompcabecera ,
			               traking.mct_solcompcabecera.idordentrabajo ,
			               traking.mct_solcompcabecera.idusuario ,
			               traking.mct_usuario.nombre ,
			               traking.mct_solcompcabecera.idseccion ,
			               traking.mct_seccion.nombreseccion ,
			               traking.mct_solcompcabecera.idorigensolicitud ,
			               case
			                   when traking.mct_solcompcabecera.idorigensolicitud = 1 then 
			                        cast('OT' as varchar)
			                   when traking.mct_solcompcabecera.idorigensolicitud = 2 then 
			                        cast('MANTENCION' as varchar)
			                   when traking.mct_solcompcabecera.idorigensolicitud = 3 then 
			                        cast('STOCK' as varchar)
			                   else cast('OTRA' as varchar)
			               end as nombreorigensolicitud,
			               traking.mct_solcompcabecera.fecharequerida ,
			               traking.mct_solcompcabecera.solicitudurgente ,
			               case
			                   when traking.mct_solcompcabecera.solicitudurgente = true then 
			                        cast('URGENTE' as varchar)
			                   else  
			                        cast('Normal' as varchar)
			               end as nombresolicitudurgente ,
			               traking.mct_solcompcabecera.observacion ,
			               traking.mct_solcompcabecera.estado,
			               traking.mct_estado.nombreestado,
			               traking.mct_solcompcabecera.fechacreacion,
			               traking.mct_solcompcabecera.usuariocreacion,
			               traking.mct_solcompcabecera.fechamodificacion,
			               traking.mct_solcompcabecera.usuariomodificacion,
			               traking.mct_solcompcabecera.importacion 
			          FROM traking.mct_solcompcabecera 
			          left join traking.mct_estado   on traking.mct_solcompcabecera.estado=traking.mct_estado.idestado
			          left join traking.mct_usuario  on traking.mct_solcompcabecera.idusuario = traking.mct_usuario.idusuario 
			          left join traking.mct_seccion  on traking.mct_solcompcabecera.idseccion = traking.mct_seccion.idseccion 
			          where  traking.mct_solcompcabecera.estado = 2
         
	      	    ) 
	      	    loop
	      	    
	      	    sp_cantidad_co 	:= 0;
	      	    sp_recept_co	:= 0;
	      	    sp_avance_co	:= 0;

	      	   
	      	    	-- Compras
					-- aca sacamos las piezas totales solicitadas a compras  
					  select coalesce ( sum(cantidad), 0)						
					    into sp_cantidad_co			          
			   	        from mct_solcompdetalle a 
					   where a.idsolcompcabecera = rec1.idsolcompcabecera;
							   
					-- aca sacamos el total de piezas recepcionadas   
					  select coalesce ( sum(a.cantidad), 0)
					    into sp_recept_co	 			   
				        from mct_solcompdetallerecept a,
				             mct_solcompdetalle b
				       where b.idsolcompcabecera = rec1.idsolcompcabecera
				         and a.idsolcompdetalle = b.idsolcompdetalle ;			    
			
			          sp_atraso_co := 0;
					  if (sp_cantidad_co = 0 ) then
			              sp_cantidad_co := 1;
			          end if;				   
							   
				      sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			
			
--				      sp_color_co  := 0;				  
--					  if ( sp_avance_co >= 100) then
--					       sp_color_co   := 1;
--				      end if;	
							  
				      itemsol					:= rec1.item;
				      idsolcompcabecera 		:= rec1.idsolcompcabecera;
                      idordentrabajo			:= rec1.idordentrabajo;
                      idusuario					:= rec1.idusuario;
                      nombreusuario 			:= rec1.nombre;
                      idsection 				:= rec1.idseccion;
                      nombresection 			:= rec1.nombreseccion;
	     			  idorigensolicitud 		:= rec1.idorigensolicitud;
	     			  nombreorigensolicitud 	:= rec1.nombreorigensolicitud; 
	     			  requestdate 				:= to_char(rec1.fecharequerida, 'dd-mm-yyyy');
	     			  solicitudurgente 			:= rec1.solicitudurgente;
	     			  nombresolicitudurgente 	:= rec1.nombresolicitudurgente;
         			  observacion 				:= rec1.observacion; 
         			  cantidadtot 				:= coalesce(sp_cantidad_co,0);
                      cantidadrec 				:= coalesce(sp_recept_co,0);
         			  avanceco 					:= coalesce(sp_avance_co,0);	
         			  atrasoco 					:= coalesce(sp_atraso_co,0);	
         			  status 					:= rec1.estado;
         			  statusname 				:= rec1.nombreestado;
         			  importacion 				:= rec1.importacion;
									  
	      	    
	      	    return next;
	      	   
	      	    end loop;
          
	     elsif ( startdate != 'NA' and enddate != 'NA' ) THEN 

	      	    FOR rec1 IN (
	      	    
			        SELECT ROW_NUMBER() OVER (ORDER BY traking.mct_solcompcabecera.fecharequerida asc) AS item,
			               traking.mct_solcompcabecera.idsolcompcabecera ,
			               traking.mct_solcompcabecera.idordentrabajo ,
			               traking.mct_solcompcabecera.idusuario ,
			               traking.mct_usuario.nombre ,
			               traking.mct_solcompcabecera.idseccion ,
			               traking.mct_seccion.nombreseccion ,
			               traking.mct_solcompcabecera.idorigensolicitud ,
			               case
			                   when traking.mct_solcompcabecera.idorigensolicitud = 1 then 
			                        cast('OT' as varchar)
			                   when traking.mct_solcompcabecera.idorigensolicitud = 2 then 
			                        cast('MANTENCION' as varchar)
			                   when traking.mct_solcompcabecera.idorigensolicitud = 3 then 
			                        cast('STOCK' as varchar)
			                   else cast('OTRA' as varchar)
			               end as nombreorigensolicitud,
			               traking.mct_solcompcabecera.fecharequerida ,
			               traking.mct_solcompcabecera.solicitudurgente ,
			               case
			                   when traking.mct_solcompcabecera.solicitudurgente = true then 
			                        cast('URGENTE' as varchar)
			                   else  
			                        cast('Normal' as varchar)
			               end as nombresolicitudurgente ,
			               traking.mct_solcompcabecera.observacion ,
			               traking.mct_solcompcabecera.estado,
			               traking.mct_estado.nombreestado,
			               traking.mct_solcompcabecera.fechacreacion,
			               traking.mct_solcompcabecera.usuariocreacion,
			               traking.mct_solcompcabecera.fechamodificacion,
			               traking.mct_solcompcabecera.usuariomodificacion,
			               traking.mct_solcompcabecera.importacion 
			          FROM traking.mct_solcompcabecera
			          left join traking.mct_estado   on traking.mct_solcompcabecera.estado=traking.mct_estado.idestado
			          left join traking.mct_usuario  on traking.mct_solcompcabecera.idusuario = traking.mct_usuario.idusuario 
			          left join traking.mct_seccion  on traking.mct_solcompcabecera.idseccion = traking.mct_seccion.idseccion 
			          where (traking.mct_solcompcabecera.fechacreacion >= TO_TIMESTAMP(startdate||' 00:00:00','yyyy-mm-dd HH24:MI:SS') and 
				             traking.mct_solcompcabecera.fechacreacion <= TO_TIMESTAMP(enddate||' 23:59:59','yyyy-mm-dd HH24:MI:SS'))
			          order by traking.mct_solcompcabecera.idsolcompcabecera desc
         
	      	    ) 
	      	    loop

	      	    sp_cantidad_co 	:= 0;
	      	    sp_recept_co	:= 0;
	      	    sp_avance_co	:= 0;

	      	   
	      	    	-- Compras
					-- aca sacamos las piezas totales solicitadas a compras  
					  select coalesce ( sum(cantidad), 0)						
					    into sp_cantidad_co			          
			   	        from mct_solcompdetalle a 
					   where a.idsolcompcabecera = rec1.idsolcompcabecera;
							   
					-- aca sacamos el total de piezas recepcionadas   
					  select coalesce ( sum(a.cantidad), 0)
					    into sp_recept_co	 			   
				        from mct_solcompdetallerecept a,
				             mct_solcompdetalle b
				       where b.idsolcompcabecera = rec1.idsolcompcabecera
				         and a.idsolcompdetalle = b.idsolcompdetalle ;			    
			
			          sp_atraso_co := 0;
					  if (sp_cantidad_co = 0 ) then
			              sp_cantidad_co := 1;
			          end if;				   
							   
				      sp_avance_co := round((sp_recept_co * 100.00 ) / sp_cantidad_co , 2);			
			
--				      sp_color_co  := 0;				  
--					  if ( sp_avance_co >= 100) then
--					       sp_color_co   := 1;
--				      end if;	
							  
				      itemsol					:= rec1.item;
				      idsolcompcabecera 		:= rec1.idsolcompcabecera;
                      idordentrabajo			:= rec1.idordentrabajo;
                      idusuario					:= rec1.idusuario;
                      nombreusuario 			:= rec1.nombre;
                      idsection 				:= rec1.idseccion;
                      nombresection 			:= rec1.nombreseccion;
	     			  idorigensolicitud 		:= rec1.idorigensolicitud;
	     			  nombreorigensolicitud 	:= rec1.nombreorigensolicitud; 
	     			  requestdate 				:= to_char(rec1.fecharequerida, 'dd-mm-yyyy');
	     			  solicitudurgente 			:= rec1.solicitudurgente;
	     			  nombresolicitudurgente 	:= rec1.nombresolicitudurgente;
         			  observacion 				:= rec1.observacion; 
         			  cantidadtot 				:= coalesce(sp_cantidad_co,0);
                      cantidadrec 				:= coalesce(sp_recept_co,0);
         			  avanceco 					:= coalesce(sp_avance_co,0);	
         			  atrasoco 					:= coalesce(sp_atraso_co,0);	
         			  status 					:= rec1.estado;
         			  statusname 				:= rec1.nombreestado;
         			  importacion 				:= rec1.importacion;
         			 
	      	    return next;
	      	   
	      	    end loop;
          	     
	     end if;


END;
$$;


