-- TOC entry 2251 (class 1255 OID 17895)
-- Name: listsolcompdetallerecep(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listsolcompdetallerecep(idsolcompcaberas bigint) RETURNS TABLE(idsolcompcabecera bigint, idsolcompdetalle bigint, idordentrabajo bigint, iduser bigint, idoperator bigint, nombreparte character varying, material character varying, plano character varying, indicefila bigint, quantity bigint, qrcode character varying, quantityrecept bigint, quantitybalance bigint, idpurshase character varying)
    LANGUAGE plpgsql
    AS $$

begin

		RETURN QUERY
		
--		select a.idsolcompcabecera ,
--		       a.idsolcompdetalle ,
--		       cast(0 as bigint),
--		       b.idusuario ,
--		       b.idoperatorrec ,
--		       a.nombreparte ,
--		       a.material ,
--		       a.plano ,
--		       a.indicefila ,
--		       a.cantidad ,
--		       a.codigoqr ,
--		       cast(coalesce(sum(b.cantidad),0) as bigint),
--			   cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint),
--			   b.ordendecompra 
--		  from mct_solcompdetalle a
--		  left join mct_solcompdetallerecept b on b.idsolcompdetalle = a.idsolcompdetalle 
--		 where a.idsolcompcabecera = idsolcompcaberas
--		 group by a.idsolcompcabecera ,
--		          a.idsolcompdetalle ,
--		          b.idusuario ,
--		          b.idoperatorrec ,
--		          a.nombreparte ,
--		          a.material ,
--		          a.plano ,
--		          a.indicefila ,
--		          a.cantidad ,
--		          a.codigoqr ,
--		          b.ordendecompra
--		   having a.cantidad > coalesce(sum(b.cantidad),0)
--		   order by a.indicefila asc;
		
		select a.idsolcompcabecera ,
		       a.idsolcompdetalle ,
		       cast(0 as bigint),
		       cast(0 as bigint) as idusuario ,
		       cast(0 as bigint) as idoperatorrec ,
		       a.nombreparte ,
		       a.material ,
		       a.plano ,
		       a.indicefila ,
		       a.cantidad ,
		       a.codigoqr ,
		       cast(coalesce(sum(b.cantidad),0) as bigint),
			   cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint),
