--
-- TOC entry 1551 (class 1255 OID 17898)
-- Name: listsolcompdetallereceppdf(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listsolcompdetallereceppdf(idsolcompcaberas bigint) RETURNS TABLE(idsolcompcabecera bigint, idsolcompdetalle bigint, idordentrabajo bigint, iduser bigint, idoperator bigint, nombreparte character varying, material character varying, plano character varying, indicefila bigint, quantity bigint, qrcode character varying, quantityrecept bigint, quantitybalance bigint)
    LANGUAGE plpgsql
    AS $$

begin

		RETURN QUERY
		
		select * 
		   from (		
				select a.idsolcompcabecera ,
				       a.idsolcompdetalle ,
				       cast(0 as bigint),
				       b.idusuario ,
				       b.idoperatorrec ,
				       a.nombreparte ,
				       a.material ,
				       a.plano ,
				       a.indicefila ,
				       a.cantidad ,
				       a.codigoqr ,
				       cast(coalesce(sum(b.cantidad),0) as bigint) as recepcionada,
					   cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint)	as pendiente	       
				  from mct_solcompdetalle a
				  left join mct_solcompdetallerecept b on b.idsolcompdetalle = a.idsolcompdetalle 
				 where a.idsolcompcabecera = idsolcompcaberas
				 group by a.idsolcompcabecera ,
				          a.idsolcompdetalle ,
				          b.idusuario ,
				          b.idoperatorrec ,
				          a.nombreparte ,
				          a.material ,
				          a.plano ,
				          a.indicefila ,
				          a.cantidad ,
				          a.codigoqr 
				   having a.cantidad > coalesce(sum(b.cantidad),0)
				 union 
				 select a.idsolcompcabecera ,
				       a.idsolcompdetalle ,
				       cast(0 as bigint),
				       b.idusuario ,
				       b.idoperatorrec ,
				       a.nombreparte ,
				       a.material ,
				       a.plano ,
				       a.indicefila ,
				       a.cantidad ,
				       a.codigoqr ,
				       b.cantidad as recepcionada,
					   0		  as oendiente     
				  from mct_solcompdetalle a
				  left join mct_solcompdetallerecept b on b.idsolcompdetalle = a.idsolcompdetalle 
				 where a.idsolcompcabecera = idsolcompcaberas
						   and exists ( select * 
						                     from mct_solcompdetallerecept b 
						                    where a.idsolcompdetalle = b.idsolcompdetalle
						                      and a.cantidad = b.cantidad 
						                      )
				                      
		      ) tabla
		    order by tabla.pendiente desc,
		             tabla.nombreparte asc;
		            
			
END;
$$;


ALTER FUNCTION traking.listsolcompdetallereceppdf(idsolcompcaberas bigint) OWNER TO postgres;

--
-- TOC entry 2392 (class 1255 OID 17899)
-- Name: listsolcompdetallerecepproveedor(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listsolcompdetallerecepproveedor(idsolcompcaberas bigint) RETURNS TABLE(idsolcompcabecera bigint, idsolcompdetalle bigint, idordentrabajo bigint, iduser bigint, idoperator bigint, nombreparte character varying, material character varying, plano character varying, indicefila bigint, quantity bigint, qrcode character varying, quantityrecept bigint, quantitybalance bigint, idpurshase character varying)
    LANGUAGE plpgsql
    AS $$

begin

		RETURN QUERY
		
		select a.idsolcompcabecera ,
		       a.idsolcompdetalle ,
		       cast(0 as bigint),
		       cast(0 as bigint) as idusuario ,
		       cast(0 as bigint) as idoperatorrec ,
		       a.nombreparte ,
		       a.material ,
		       a.plano ,
		       a.indicefila ,
		       a.cantidad ,
		       a.codigoqr ,
		       cast(coalesce(sum(b.cantidad),0) as bigint),
			   cast(a.cantidad - coalesce(sum(b.cantidad),0) as bigint),
			   cast('' as varchar) as ordendecompra 
		  from mct_solcompdetalle a,
		       mct_solcompdetallerecept b
		 -- left join mct_solcompdetallerecept b on b.idsolcompdetalle = a.idsolcompdetalle 
		 where a.idsolcompcabecera = idsolcompcaberas
		   and a.idsolcompdetalle = b.idsolcompdetalle 
		 group by a.idsolcompcabecera ,
		          a.idsolcompdetalle ,
		          --b.idusuario ,
		          --b.idoperatorrec ,
		          a.nombreparte ,
		          a.material ,
		          a.plano ,
		          a.indicefila ,
		          a.cantidad ,
		          a.codigoqr ,
		          cast('' as varchar)
		   having a.cantidad > coalesce(sum(b.cantidad),0)
		   order by a.indicefila asc;
			
END;
$$;


ALTER FUNCTION traking.listsolcompdetallerecepproveedor(idsolcompcaberas bigint) OWNER TO postgres;

