-- Name: listsp_gc_gestores(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listsp_gc_gestores(p_idusuario bigint) RETURNS TABLE(gestor text, idusuario_gestor bigint)
    LANGUAGE sql
    AS $$
  SELECT
    COALESCE(NULLIF(TRIM(u.sigla), ''), TRIM(u.nombre)) AS gestor,
    u.idusuario AS idusuario_gestor
  FROM traking.listusercombovendedores(p_idusuario) lv
  JOIN traking.mct_usuario u ON u.idusuario = lv.iduser
  ORDER BY 1;
$$;


ALTER FUNCTION traking.listsp_gc_gestores(p_idusuario bigint) OWNER TO postgres;

