--
-- TOC entry 2310 (class 1255 OID 17904)
-- Name: liststockproductosmaestranzabomba(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.liststockproductosmaestranzabomba(idcustomers bigint) RETURNS TABLE(item bigint, idstockproductosmaestranza bigint, idtipostock bigint, nombretipostock character varying, idcliente bigint, nombrecliente character varying, idproducto bigint, nombreproducto character varying, idcomponente bigint, nombrecomponente character varying, plano character varying, idmaterial bigint, nombrematerial character varying, stock bigint, stockcritico bigint, textoadicional character varying, usercreate character varying, datecreate timestamp without time zone, userupdate character varying, dateupdate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
declare
          
begin
	  
	if (idcustomers = -1) then
	
	    RETURN QUERY
	    
		SELECT ROW_NUMBER() OVER (ORDER BY a.idstockproductosmaestranza asc) AS item,
		       a.idstockproductosmaestranza , 
		       a.idtipostock ,
		       f.nombretipostock ,
		       a.idcliente ,
		       b.nombrecliente ,
		       a.idproducto , 
		       c.nombreproductonepcast  ,
		       a.idcomponente , 
		       g.nombreelementodesgaste  ,
		       a.plano ,
		       a.idmaterial , 
		       e.nombrematerial ,
		       a.stock , 
		       a.stockcritico , 
		       a.textoadicional ,
		       a.usuariocreacion, 
		       a.fechacreacion,
		       a.usuariomodificacion , 
		       a.fechamodificacion 
		  FROM traking.mct_stockproductosmaestranza a
		  left join traking.mct_cliente b     on a.idcliente = b.idcliente 
		  left join traking.mct_productonepcast c    on a.idproducto = c.idproductonepcast  
		  left join traking.mct_componente d  on a.idcomponente = d.idcomponente 
		  left join traking.mct_material e    on a.idmaterial = e.idmaterial
		  left join traking.mct_tipostock f   on a.idtipostock = f.idtipostock
		  left join traking.mct_elementodesgaste g    on a.idcomponente = g.idelementodesgaste 
	     WHERE a.idtipostock = 2
      order by a.idstockproductosmaestranza asc;
     
	else
	
	    RETURN QUERY
	    
		SELECT ROW_NUMBER() OVER (ORDER BY a.idstockproductosmaestranza asc) AS item,
		       a.idstockproductosmaestranza , 
		       a.idtipostock ,
		       f.nombretipostock ,
		       a.idcliente ,
		       b.nombrecliente ,
		       a.idproducto , 
		       cast(coalesce(h.sigla||' - '||g.nombremodelo||' - '||i.nombreparam, 'SIN PROD') as varchar),
		       a.idcomponente , 
		       d.nombrecomponente ,
		       a.plano ,
		       a.idmaterial , 
		       e.nombrematerial ,
		       a.stock , 
		       a.stockcritico , 
		       a.textoadicional ,
		       a.usuariocreacion, 
		       a.fechacreacion,
		       a.usuariomodificacion , 
		       a.fechamodificacion 
		  FROM traking.mct_stockproductosmaestranza a
		  left join traking.mct_cliente b     on a.idcliente = b.idcliente 
		  left join traking.mct_producto c    on a.idproducto = c.idproducto 
		  left join traking.mct_componente d  on a.idcomponente = d.idcomponente 
		  left join traking.mct_material e    on a.idmaterial = e.idmaterial 
		  left join traking.mct_tipostock f   on a.idtipostock = f.idtipostock 
		  left join mct_modelo g              on g.idmodelo = c.idmodelo 
	      left join mct_subfamilia h          on h.idsubfamilia = g.idsubfamilia 
	      left join mct_etapaparam i          on i.idetapaparam = c.idetapaparam
	     WHERE a.idcliente = idcustomers
	       and a.idtipostock = 1
      order by a.idstockproductosmaestranza asc;
     
	end if;


	     

END;
$$;


ALTER FUNCTION traking.liststockproductosmaestranzabomba(idcustomers bigint) OWNER TO postgres;

