        FROM traking.mct_rangohorario
        left join traking.mct_diassemana  on traking.mct_rangohorario.iddiassemana = traking.mct_diassemana.iddiassemana
        left join traking.mct_tipohorario on traking.mct_rangohorario.idtipohorario = traking.mct_tipohorario.idtipohorario 
        left join traking.mct_estado      on traking.mct_rangohorario.estado = traking.mct_estado.idestado
        order by traking.mct_diassemana.nombrediassemana asc, traking.mct_tipohorario.nombretipohorario asc;

END;
$$;


