--
-- TOC entry 1265 (class 1255 OID 17912)
-- Name: listtipoadjuntoporusuario(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listtipoadjuntoporusuario(idusers bigint) RETURNS TABLE(idtipoadjunto bigint, nombretipoadjunto character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

	if (idusers in (6, 5)) then
	
		RETURN QUERY
	
		SELECT a.idtipoadjunto,
			   a.nombretipoadjunto
		  FROM traking.mct_tipoadjunto a
         where a.idtipoadjunto in (4,5,6,7,8,9)
		 order by a.idtipoadjunto;
	
	elsif (idusers in (59, 130, 131)) then
	
		RETURN QUERY
	
		SELECT a.idtipoadjunto,
			   a.nombretipoadjunto
		  FROM traking.mct_tipoadjunto a
		 where a.idtipoadjunto in (7,8)
		 order by a.idtipoadjunto;
	
	elsif (idusers in (127)) then
	
		RETURN QUERY
	
		SELECT a.idtipoadjunto,
			   a.nombretipoadjunto
		  FROM traking.mct_tipoadjunto a
		 where a.idtipoadjunto in (9)
		 order by a.idtipoadjunto;
	
	else
	
		RETURN QUERY
	
		SELECT a.idtipoadjunto,
			   a.nombretipoadjunto
		  FROM traking.mct_tipoadjunto a
		 where a.idtipoadjunto in (4,5,6)
		 order by a.idtipoadjunto;	
	
	end if;


END;
$$;


ALTER FUNCTION traking.listtipoadjuntoporusuario(idusers bigint) OWNER TO postgres;

