-- Name: listusuarioappcontrolmaestranza(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listusuarioappcontrolmaestranza() RETURNS TABLE(item bigint, idusuario bigint, nombreusuario character varying, flagevaluacion boolean, flagcambioingenieria boolean, flagcontrolmaquina boolean, flagdespacho boolean, flagdefectofundicion boolean, flaginsp boolean, flaglimpiezamaquina boolean, flagmateriaprima boolean, flagnoconformidad boolean, flagnoconformidadcald boolean, flagotra1 boolean, flagotra2 boolean, flagotra3 boolean, flagotra4 boolean, flagotra5 boolean, flagotra6 boolean, flagotra7 boolean, flagotra8 boolean, flagotra9 boolean, flagotra10 boolean, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
declare
   sp_cantidad    integer;
BEGIN

	sp_cantidad := 0;

	select count(*)
	  into sp_cantidad
	  from mct_usuariocontrolmaestranza;

	
	if ( sp_cantidad > 0 ) then

	    RETURN QUERY
	    
		select ROW_NUMBER() OVER (ORDER BY a.nombre) AS item,
		       a.idusuario ,
		       a.nombre ,
			   b.flagevaluacion ,
			   b.flagcambioingenieria ,
			   b.flagcontrolmaquina ,
			   b.flagdespacho ,
		       b.flagdefectofundicion ,
			   b.flaginsp ,
			   b.flaglimpiezamaquina ,
			   b.flagmateriaprima ,
			   b.flagnoconformidad ,
			   b.flagnoconformidadcald ,
			   b.flagotra1 ,
			   b.flagotra2 ,
			   b.flagotra3 ,
			   b.flagotra4 ,
			   b.flagotra5 ,
