--
-- TOC entry 2303 (class 1255 OID 17944)
-- Name: listworkordermanual(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.listworkordermanual() RETURNS TABLE(idworkorderprev bigint, idworkorder bigint, workordername character varying, idcustomer bigint, customername character varying, quotation bigint, idordertype bigint, ordertypename character varying, idproduct bigint, productname character varying, purshaseorder bigint, receptiondate timestamp without time zone, deliverydate timestamp without time zone, idorderstatus bigint, statusname character varying, iduser bigint, name character varying, inputguide bigint, outputguide bigint, idfamily bigint, familyname character varying, idlinedesign bigint, tag character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying, customercontact character varying, observationcrea character varying, filebase64 character varying, idtipootdesgaste bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY

    SELECT
        traking.mct_ordentrabajo.idordentrabajoanterior,
        traking.mct_ordentrabajo.idordentrabajo,
        traking.mct_ordentrabajo.nombreordentrabajo,
        traking.mct_ordentrabajo.idcliente,
        traking.mct_cliente.nombrecliente,
        traking.mct_ordentrabajo.idcotizacion,
        traking.mct_ordentrabajo.idtipoorden,
        traking.mct_tipoorden.nombretipoorden,
        traking.mct_ordentrabajo.idproducto,
        traking.mct_producto.nombreproducto,
        traking.mct_ordentrabajo.ordencompra,
        traking.mct_ordentrabajo.fecharecepcion,
        traking.mct_ordentrabajo.fechaentrega,
        traking.mct_ordentrabajo.idestadoorden,
        traking.mct_estadoorden.nombreestado,
        traking.mct_ordentrabajo.idusuario,
        traking.mct_usuario.nombre,
        traking.mct_ordentrabajo.guiaentrante,
        traking.mct_ordentrabajo.guiasaliente,
        traking.mct_ordentrabajo.idfamilia,
        traking.mct_familia.nombrefamilia,
        traking.mct_ordentrabajo.idlineadiseno,
        traking.mct_ordentrabajo.tag,
        traking.mct_ordentrabajo.fechacreacion,
        traking.mct_ordentrabajo.usuariocreacion,
        traking.mct_ordentrabajo.fechamodificacion,
        traking.mct_ordentrabajo.usuariomodificacion,
        traking.mct_ordentrabajo.contactocliente,
        traking.mct_ordentrabajo.observacioncreacion,
        cast('NA' as varchar),

        -- NUEVO
        traking.mct_ordentrabajo.idtipootdesgaste

    FROM traking.mct_ordentrabajo

    LEFT JOIN traking.mct_estadoorden
        ON traking.mct_ordentrabajo.idestadoorden =
           traking.mct_estadoorden.idestadoorden

    LEFT JOIN traking.mct_cliente
        ON traking.mct_ordentrabajo.idcliente =
           traking.mct_cliente.idcliente

    LEFT JOIN traking.mct_tipoorden
        ON traking.mct_ordentrabajo.idtipoorden =
           traking.mct_tipoorden.idtipoorden

    LEFT JOIN traking.mct_producto
        ON traking.mct_ordentrabajo.idproducto =
           traking.mct_producto.idproducto

    LEFT JOIN traking.mct_usuario
        ON traking.mct_ordentrabajo.idusuario =
           traking.mct_usuario.idusuario

    LEFT JOIN traking.mct_familia
        ON traking.mct_ordentrabajo.idfamilia =
           traking.mct_familia.idfamilia

    WHERE traking.mct_ordentrabajo.idestadoorden < 7

    ORDER BY traking.mct_ordentrabajo.idordentrabajo DESC;

END;
$$;


