--

CREATE FUNCTION traking.listworkorderreplacement(idworkorders bigint) RETURNS TABLE(idworkorderreplacement bigint, idworkorder bigint, idcomponenttemp bigint, namecomponenttemp character varying, idnepcastproduct bigint, nepcastproductname character varying, idproduct bigint, productname character varying, quantity bigint, qdispatch bigint, idmaterialtemp bigint, namematerialtemp character varying, blueprintname character varying, cost bigint, componentcode bigint, itemoc character varying, idesmecanizado bigint, nombremecanizado character varying, datecreate timestamp without time zone, usercreate character varying, dateupdate timestamp without time zone, userupdate character varying)
    LANGUAGE plpgsql
    AS $$
declare

	rec1      			    record;
	sp_qdispatch			integer;

BEGIN

		FOR rec1 IN (   
			
			        SELECT traking.mct_ordentrabajorepuesto.idordentrabajorepuesto,
						   traking.mct_ordentrabajorepuesto.idordentrabajo,
						   traking.mct_ordentrabajorepuesto.idcomponentetemp,
						   traking.mct_ordentrabajorepuesto.nombrecomponentetemp,
						   traking.mct_ordentrabajorepuesto.idproductonepcast ,
						   traking.mct_productonepcast.nombreproductonepcast ,		   
						   traking.mct_ordentrabajorepuesto.idproducto ,
						   traking.mct_producto.nombreproducto ,			
						   traking.mct_ordentrabajorepuesto.cantidad,
						   traking.mct_ordentrabajorepuesto.idmaterialtemp,
						   traking.mct_ordentrabajorepuesto.nombrematerialtemp,
						   traking.mct_ordentrabajorepuesto.nombreplano,
						   traking.mct_ordentrabajorepuesto.costo,
						   traking.mct_ordentrabajorepuesto.codigopieza,
						   traking.mct_ordentrabajorepuesto.itemoc,
						   traking.mct_ordentrabajorepuesto.idesmecanizado,
						   case
						   	  when traking.mct_ordentrabajorepuesto.idesmecanizado = 1 then 
						   	  		cast('SI' as varchar)
						   	  when traking.mct_ordentrabajorepuesto.idesmecanizado = 2 then 
						   	  		cast('NO' as varchar)
						   end as mecanizado,
						   traking.mct_ordentrabajorepuesto.fechacreacion,
						   traking.mct_ordentrabajorepuesto.usuariocreacion,
						   traking.mct_ordentrabajorepuesto.fechamodificacion,
						   traking.mct_ordentrabajorepuesto.usuariomodificacion
			          FROM traking.mct_ordentrabajorepuesto 
			         left join  traking.mct_productonepcast on traking.mct_ordentrabajorepuesto.idproductonepcast = traking.mct_productonepcast.idproductonepcast 
			         left join  traking.mct_producto        on traking.mct_ordentrabajorepuesto.idproducto = traking.mct_producto.idproducto 
			         WHERE traking.mct_ordentrabajorepuesto.idordentrabajo = idworkorders
			       order by traking.mct_ordentrabajorepuesto.idordentrabajorepuesto asc
      
      					)
	     		loop 

		         select coalesce (sum(qdespacho) , 0)
		           into sp_qdispatch
		           from mct_despachopartedetalle md 
		          where idordentrabajoparte = rec1.idordentrabajorepuesto;   
      
		         idworkorderreplacement		:= rec1.idordentrabajorepuesto; 
		         idworkorder				:= rec1.idordentrabajo;
		         idcomponenttemp			:= rec1.idcomponentetemp;
		         namecomponenttemp 			:= rec1.nombrecomponentetemp; 
		         idnepcastproduct 			:= rec1.idproductonepcast; 
		         nepcastproductname 		:= rec1.nombreproductonepcast; 
		         idproduct 					:= rec1.idproducto;
		         productname 				:= rec1.nombreproducto;
		         quantity 					:= rec1.cantidad;
		         qdispatch 					:= sp_qdispatch;
		         idmaterialtemp 			:= rec1.idmaterialtemp; 
		         namematerialtemp 			:= rec1.nombrematerialtemp;
		         blueprintname 				:= rec1.nombreplano; 
		         cost 						:= rec1.costo;
		         componentcode 				:= rec1.codigopieza; 
		         itemoc 					:= rec1.itemoc;
		         idesmecanizado 			:= rec1.idesmecanizado;
		         nombremecanizado 			:= rec1.mecanizado; 
		         datecreate 				:= rec1.fechacreacion;
		         usercreate 				:= rec1.usuariocreacion;
		         dateupdate 				:= rec1.fechamodificacion; 
		         userupdate 				:= rec1.usuariomodificacion;
         
      
      		RETURN NEXT;
      	
      	end loop;

END;
$$;


ALTER FUNCTION traking.listworkorderreplacement(idworkorders bigint) OWNER TO postgres;

