--

CREATE FUNCTION traking.prueba_json(idroadmapcodes bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare

    sp_texto      varchar;
   	rec1 			record;
   	indice        integer;

    
   
BEGIN

   -- RETURN QUERY
           indice := 0;
           sp_texto := '"ot": {"data": 222, "estado": 0, "hr": "000222149004"}, "acc": "", "diaT": 1, "hrsMuerta": "-1000", "hrsT": "1192", "idhr": "33668", "item": 149, "nombreItem": "ADAPTADOR PARA TUBO PROTECTOR EJE",{';
    
    	   FOR rec1 IN (   
					 
					select row_number() over (order by idmovimientoordentrabajo ), 
					       idmovimientoordentrabajo, 
					       codigoaccion, 
					       estadoactividad
					from mct_movimientoordentrabajo  
				   where idhojaruta = 33668
					  
					)
		   loop 	
		   
		   		indice := indice + 1;
		        sp_texto := sp_texto||'procmin'||indice||':{id:'||rec1.idmovimientoordentrabajo||', data:'||rec1.codigoaccion||', estado: '||rec1.estadoactividad||'},';

		         
		   END LOOP;
		   
           --string_json:= sp_texto;
          
           --return next;
           
		  return sp_texto;
    
END;
$$;


