--
-- TOC entry 1721 (class 1255 OID 17954)
-- Name: recarga_ottrabajossol(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.recarga_ottrabajossol(idworkorders bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
	
DECLARE

	    sp_idusuario			integer;
	    sp_nombreingeniero		varchar;
	    sp_nombreproducto		varchar;
	    sp_nombremodelo			varchar;
	    sp_sigla				varchar;
	    sp_nombrebomba			varchar;
	   
	    sp_familia              integer;
	       
		sp_fecha_hoy            VARCHAR=to_char(now(),'DD-MM-YYYY hh24:mi');
	    sp_lista                varchar;
	   
	    sp_texto                varchar;
	    sp_asunto               varchar;
	    sp_senor                varchar;
	
		rec_email      			RECORD;
	    rec_trab       			RECORD;			
	   
	   -- Desde aca para generar las Hojas de rutas automaticas
	    rec_hr					RECORD;
	   
        indice   				INTEGER;
        tope	   				INTEGER;	
  
        sp_hrchar               TEXT;
        sp_partchar             TEXT;
        sp_itemchar             TEXT;
        sp_corrchar             TEXT;
       
        sp_idpwo   				INTEGER;     
        sp_idmaxcorr			integer;
       
       	sp_carga				varchar;
        sp_cuentaaudit			integer;
         						    
begin
	 
	if (select distinct 1 from mct_hojarutatemp mh where idordentrabajo = idworkorders) then
	
		return 9;
	
	else 

       -- Esto inserta los registros en la tabla principal de Hojarutatemp
	   insert into mct_hojarutatemp (
	               idhojarutatemp, 
		           idordentrabajo, 
		           nombreplano, 
		           cantidad, 
		           usuariocreacion, 
		           fechacreacion, 
		           idimprimehojas, 
		           idboleano, 
		           idcriterioevaluacion, 
		           materialchecklist, 
		           componentechecklist,
		           textoadicional,
		           idcomponente ,
		           idmaterial ,
		           nombrematerial ,
		           idareaclasificacion 
		         )
			     select nextval('mct_hojarutatemp_seq'),
			            a.idordentrabajo ,
			            a.plano,
			            a.cantidad,
			            'admin',
			            now(),
			            2,
			            1,
			            b.idcriterioevaluacion ,
			            a.material,
			            a.nombreparte,
			            'N/A',
			            a.idcomponente ,
			            a.idmaterial ,
			            a.nombrematerial ,
			            coalesce (d.idareaclasificacion, 0) 
			       from mct_checklistinftecvalido  a
			       left join mct_criterioevaluacion b on a.criterio = b.nombrecriterioevaluacion
			       join mct_progavisos c on c.idordentrabajo = a.idordentrabajo and c.idsla = 5 and c.estado = 1 
			       left join mct_componente d on a.idcomponente = d.idcomponente 
			      where b.idcriterioevaluacion not in (5, 6)
			        and a.idordentrabajo = idworkorders;
			       
	     --return 1;    
----			   
----	  
        FOR rec_hr IN (   
					 select ROW_NUMBER() OVER (ORDER BY idareaclasificacion asc) + 3 AS item,
					        idhojarutatemp ,
					        idordentrabajo ,
					        idcomponente ,
					        cantidad ,
					        idimprimehojas ,
					        idareaclasificacion ,
					        idordentrabajo
					   from mct_hojarutatemp mh 
					  where idordentrabajo	= idworkorders 
                       
       		       )
					
		 loop 	
		
			insert into mct_hojarutaactividadtemp 
	                (
	                idhojarutaactividadtemp ,
	                idhojarutatemp ,
	                idactividad ,
	                tiempoproduccion ,
	                orden 
	                )        	     
					select nextval('mct_hojarutaactividadtemp_seq'),
					       rec_hr.idhojarutatemp,
					       a.idactividad , 
					       a.tiempoproduccion , 
					       a.orden 
					  from mct_partetipotrabajoactividad a 
					 where a.idpartetipotrabajo = ( select idcomponentetipotrabajo 
											        from mct_componentetipotrabajo 
											       where idcomponente  = rec_hr.idcomponente
											         and idtipotrabajo in (21))
					order by idpartetipotrabajoactividad  asc, orden asc;
		

				
		     if ( rec_hr.idimprimehojas = 1 ) then
	    
		         tope  := 1;
		      
		     else
		 
		     	 tope := coalesce(rec_hr.cantidad,0);
		    
		     end if;
 
--		     sp_idmaxcorr := 0;
		   				
		   
--		     if ( sp_idmaxcorr > 0 ) then
--		         indice := sp_idmaxcorr + 1;
--		     else
				 indice := 1;
--             end if;
		
			 loop						
			
				sp_hrchar   := LPAD(rec_hr.idordentrabajo::integer::text::varchar, 6, '0');  
				sp_partchar := LPAD(rec_hr.idcomponente::integer::text::varchar, 3, '0');
				sp_itemchar := LPAD(rec_hr.item::integer::text::varchar, 2, '0'); 	
				sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
				
				insert into mct_detallehojarutatemp 
				           (iddetallehojarutatemp 
				           ,idhojarutatemp 
				           ,codhojaruta 
				           ,correlativoparte
				           ,item 
				           )
				     VALUES
				           (nextval('traking.mct_detallehojarutatemp_seq')
				           ,rec_hr.idhojarutatemp
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
				           ,indice
				           ,rec_hr.item
				           );                     
		
				         
						sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
					
						insert into mct_ordentrabajoparte 
						           (idordentrabajoparte 
						           ,idordentrabajo 
						           ,idcomponente 
						           ,itemparte
						           ,itemcorr 
						           )
						     VALUES
						           (sp_idpwo
						           ,rec_hr.idordentrabajo
						           ,rec_hr.idcomponente 
						           ,indice
						           ,rec_hr.item
						           );    
		
 				-- Esto es para igualar la tabla Hoja Ruta
			    insert into mct_hojaruta 
				           (idhojaruta 
				           ,idordentrabajoparte 
				           ,codhojaruta 
				           ,usuariocreacion 
				           ,fechacreacion
				           ,modalidad 
				           ,idhojarutatemp 
				           )
				     VALUES
				           (nextval('traking.mct_hojaruta_seq')
				           ,sp_idpwo
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
				           ,'admin' 
				           ,now()
				           ,1
				           ,rec_hr.idhojarutatemp
				           ); 
				          
				 indice := indice + 1;
				                           				   
				 EXIT when indice > tope;
				                    
			END loop;  		
		
		
	  	END LOOP;			   
	
	end if;

    return 0;
	       
			       
END;
$$;


ALTER FUNCTION traking.recarga_ottrabajossol(idworkorders bigint) OWNER TO postgres;

--
-- TOC entry 1299 (class 1255 OID 17956)
-- Name: sp_gc_eval_normalizado(date, date, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.sp_gc_eval_normalizado(p_f1 date, p_f2 date, p_idusuario bigint) RETURNS TABLE(gestor text, pct numeric, estado text, pct_equipo numeric, estado_equipo text)
    LANGUAGE sql
    AS $$
WITH
-- gestores reales (sin "CENTRO")
g AS (
  SELECT gestor
  FROM traking.sp_gc_gestores(p_idusuario)
),

top AS (
  SELECT *
  FROM traking.sp_gc_top_normalizado(p_f1, p_f2, p_idusuario)
),

kpi AS (
  SELECT *
  FROM traking.sp_gc_kpi_normalizado_completo(p_f1, p_f2, p_idusuario)
),

-- Equipos circulantes: global (uno solo)
eq AS (
  SELECT
    COALESCE(MAX(CASE WHEN metrica='EQUIPOS_CIRCULANTES' THEN cantidad END),0)::numeric AS eq_cant,
    COALESCE(MAX(CASE WHEN metrica='EQUIPOS_CIRCULANTES' THEN min_cant END),0)::numeric AS eq_min
  FROM top
),

-- Agendadas por gestor (para “gatear” el cálculo)
ag AS (
  SELECT
    gestor,
    COALESCE(MAX(CASE WHEN metrica='AGENDADAS' THEN cantidad END),0)::numeric AS ag_cant,
    COALESCE(MAX(CASE WHEN metrica='AGENDADAS' THEN min_cant END),0)::numeric AS ag_min
  FROM top
  GROUP BY gestor
),

-- Concretadas por gestor
conc AS (
  SELECT
    gestor,
    COALESCE(MAX(CASE WHEN metrica='CONCRETADAS' THEN cantidad END),0)::numeric AS conc_cant,
    COALESCE(MAX(CASE WHEN metrica='CONCRETADAS' THEN min_cant END),0)::numeric AS conc_min
  FROM top
  GROUP BY gestor
),

-- (Visita en Terreno) por gestor
actividad_vt AS (
  SELECT
    gestor,
    SUM(CASE WHEN bloque='TIPO_ACTIVIDAD' AND fila IN ('Visita en Terreno')
             THEN COALESCE(cantidad,0) ELSE 0 END)::numeric AS act_cant,
    MAX(CASE WHEN bloque='TIPO_ACTIVIDAD' AND fila IN ('Visita en Terreno')
             THEN COALESCE(min_cant,0) ELSE NULL END)::numeric AS act_min
  FROM kpi
  GROUP BY gestor
),

-- (Esporádico + Potencial) por gestor
cliente_ep AS (
  SELECT
    gestor,
    SUM(CASE WHEN bloque='TIPO_CLIENTE' AND fila IN ('Esporádico','Potencial')
             THEN COALESCE(cantidad,0) ELSE 0 END)::numeric AS cli_cant,
    MAX(CASE WHEN bloque='TIPO_CLIENTE' AND fila IN ('Esporádico','Potencial')
             THEN COALESCE(min_cant,0) ELSE NULL END)::numeric AS cli_min
  FROM kpi
  GROUP BY gestor
),

-- Nuevos Negocios por gestor
nuevos AS (
  SELECT
    gestor,
    SUM(CASE WHEN bloque='MOTIVO' AND fila='Nuevos Negocios'
             THEN COALESCE(cantidad,0) ELSE 0 END)::numeric AS nn_cant,
    MAX(CASE WHEN bloque='MOTIVO' AND fila='Nuevos Negocios'
             THEN COALESCE(min_cant,0) ELSE NULL END)::numeric AS nn_min
  FROM kpi
  GROUP BY gestor
),

-- (Capacitación Técnica + Visita a Planta) por gestor
capa_visita AS (
  SELECT
    gestor,
    SUM(CASE WHEN bloque='MOTIVO' AND fila IN ('Capacitación Técnica','Visita a Planta')
             THEN COALESCE(cantidad,0) ELSE 0 END)::numeric AS capa_cant,
    MAX(CASE WHEN bloque='MOTIVO' AND fila IN ('Capacitación Técnica','Visita a Planta')
             THEN COALESCE(min_cant,0) ELSE NULL END)::numeric AS capa_min
  FROM kpi
  GROUP BY gestor
),

eval AS (
  SELECT
    g.gestor,

    CASE
      -- ✅ si NO hubo actividad (agendadas=0), NO se evalúa: 0%
      WHEN COALESCE(a.ag_cant,0) = 0 THEN 0::numeric
      ELSE
        (
          (
            -- (B6/N6)*40
            -- (B6/N6)*50
--            (LEAST(1::numeric,
--                   CASE WHEN eq.eq_cant < eq.eq_min THEN eq.eq_cant/eq.eq_min ELSE 50 END
--                   --CASE WHEN eq.eq_min > 0 THEN eq.eq_cant/eq.eq_min ELSE 0 END
--            ) * 50) --Antes era 40
			(
			  CASE
			    WHEN eq.eq_cant >= 40 THEN 1::numeric
			    WHEN eq.eq_cant > 30 AND eq.eq_cant < 40 THEN 0.5::numeric
			    WHEN eq.eq_cant > 20 AND eq.eq_cant < 30 THEN 0.25::numeric
			    ELSE 0::numeric
			  END
			  * 50
			)

            -- + (1*5) (agendadas / 30) si agendadas > 30 asume (1 * 5)
            -- + (1*2.5) (agendadas / 30) si agendadas > 30 asume (1 * 2.5)
            + (LEAST(1::numeric,
                   CASE WHEN a.ag_cant < a.ag_min THEN a.ag_cant/a.ag_min ELSE 2.5 END
            ) * 2.5) -- Antes era 5
            --+ 5

            -- + (B5/N5)*5
            + (LEAST(1::numeric,
                     CASE WHEN c.conc_cant < COALESCE(c.conc_min,0) THEN c.conc_cant/c.conc_min ELSE 10 END
                     --CASE WHEN COALESCE(c.conc_min,0) > 0 THEN c.conc_cant/c.conc_min ELSE 0 END
              ) * 10)  -- Antes era 15

            -- + ((B14+B15)/N14)*15
            + (LEAST(1::numeric,
                     CASE WHEN vt.act_cant < COALESCE(vt.act_min,0) THEN vt.act_cant/vt.act_min ELSE 15 END
                     --CASE WHEN COALESCE(ce.cli_min,0) > 0 THEN ce.cli_cant/ce.cli_min ELSE 0 END
              ) * 15)

            -- + ((B14+B15)/N14)*15
            + (LEAST(1::numeric,
                     CASE WHEN ce.cli_cant < COALESCE(ce.cli_min,0) THEN ce.cli_cant/ce.cli_min ELSE 10 END
                     --CASE WHEN COALESCE(ce.cli_min,0) > 0 THEN ce.cli_cant/ce.cli_min ELSE 0 END
              ) * 10)  -- Antes era 15

            -- + (B19/N19)*2
            + (LEAST(1::numeric,
                     CASE WHEN n.nn_cant < COALESCE(n.nn_min,0) THEN n.nn_cant/n.nn_min ELSE 10 END
                     --CASE WHEN COALESCE(n.nn_min,0) > 0 THEN n.nn_cant/n.nn_min ELSE 0 END
              ) * 10)  -- Antes era 20

            -- + (1*5) (Esto es Capacitacion tecnica + visita planta ) / 1 fijo
            + (LEAST(1::numeric,
                     CASE WHEN cv.capa_cant < COALESCE(cv.capa_min,0) THEN cv.capa_cant/cv.capa_min ELSE 2.5 END
                     --CASE WHEN COALESCE(cv.capa_min,0) > 0 THEN cv.capa_cant/cv.capa_min ELSE 0 END
              ) * 2.5)  -- Antes era 5
            --+ 5

          ) / 100.0
        )::numeric
    END AS pct
  FROM g
  CROSS JOIN eq
  LEFT JOIN ag a            ON a.gestor = g.gestor
  LEFT JOIN conc c          ON c.gestor = g.gestor
  LEFT JOIN actividad_vt vt ON vt.gestor = g.gestor
  LEFT JOIN cliente_ep ce   ON ce.gestor = g.gestor
  LEFT JOIN nuevos n        ON n.gestor = g.gestor
  LEFT JOIN capa_visita cv  ON cv.gestor = g.gestor
),

equipo AS (
  SELECT AVG(pct)::numeric AS pct_equipo
  FROM eval
)

SELECT
  e.gestor,
  e.pct,
  CASE
    WHEN e.pct < 0.50 THEN 'DEFICIENTE'
    WHEN e.pct < 0.70 THEN 'ESPERADO'
    ELSE 'DESTACADO'
  END AS estado,
  (SELECT pct_equipo FROM equipo) AS pct_equipo,
  CASE
    WHEN (SELECT pct_equipo FROM equipo) < 0.50 THEN 'DEFICIENTE'
    WHEN (SELECT pct_equipo FROM equipo) < 0.70 THEN 'ESPERADO'
    ELSE 'DESTACADO'
  END AS estado_equipo
FROM eval e
ORDER BY e.gestor;
$$;


ALTER FUNCTION traking.sp_gc_eval_normalizado(p_f1 date, p_f2 date, p_idusuario bigint) OWNER TO postgres;

--
-- TOC entry 973 (class 1255 OID 17958)
-- Name: sp_gc_gestores(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.sp_gc_gestores(p_idusuario bigint) RETURNS TABLE(gestor text, idusuario_gestor bigint, nombre_gestor character varying, email_gestor character varying)
    LANGUAGE sql
    AS $$
  SELECT
    COALESCE(NULLIF(TRIM(u.sigla), ''), TRIM(u.nombre)) AS gestor,
    u.idusuario AS idusuario_gestor,
    u.nombre as nombre_gestor,
    u.email as email_gestor
  FROM traking.listusercombovendedores(p_idusuario) lv
  JOIN traking.mct_usuario u ON u.idusuario = lv.iduser
  ORDER BY 1;
$$;


ALTER FUNCTION traking.sp_gc_gestores(p_idusuario bigint) OWNER TO postgres;

--
-- TOC entry 1278 (class 1255 OID 17959)
-- Name: sp_gc_kpi_normalizado(date, date, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.sp_gc_kpi_normalizado(p_f1 date, p_f2 date, p_idusuario bigint) RETURNS TABLE(bloque text, fila text, gestor text, cantidad integer, pct numeric, prom_cant integer, prom_pct numeric, min_cant integer, min_pct numeric)
    LANGUAGE sql
    AS $$
WITH gestores AS (
    -- equipo (vendedores) del usuario "contexto"
    SELECT iduser as idusuario
    FROM traking.listusercombovendedores(p_idusuario)
),
base AS (
    SELECT
        a.idusuario,
        u.sigla                        AS gestor,            -- 👈 clave corta (AAA/BBB) si la usas así
        u.nombre                       AS gestor_nombre,     -- (por si lo quieres mostrar)
        COALESCE(ta.nombretipoactividadgestion, 'SIN TIPO')  AS tipo_actividad,
        COALESCE(tc.nombretipoclientecom, 'SIN TIPO CLIENTE') AS tipo_cliente,
        COALESCE(ma.nombremotivoactividadgestion, 'SIN MOTIVO') AS motivo
    FROM traking.mct_actividadgestion a
    JOIN gestores g
      ON g.idusuario = a.idusuario
    JOIN traking.mct_usuario u
      ON u.idusuario = a.idusuario
    LEFT JOIN traking.mct_tipoactividadgestion ta
      ON ta.idtipoactividadgestion = a.idtipoactividadgestion
    LEFT JOIN traking.mct_clientecom c
      ON c.idclientecom = a.idclientecom
    LEFT JOIN traking.mct_tipoclientecom tc
      ON tc.idtipoclientecom = c.idtipoclientecom
    LEFT JOIN traking.mct_motivoactividadgestion ma
      ON ma.idmotivoactividadgestion = a.idmotivoactividadgestion
    WHERE a.fechaactividad >= p_f1::timestamp
      AND a.fechaactividad < (p_f2::timestamp + interval '1 day')
),

-- ===================== TIPO_ACTIVIDAD =====================
act AS (
    SELECT
        'TIPO_ACTIVIDAD'::text AS bloque,
        tipo_actividad         AS fila,
        gestor,
        count(*)::int          AS cantidad
    FROM base
    GROUP BY tipo_actividad, gestor
),
act_tot AS (
    SELECT bloque, gestor, sum(cantidad)::numeric AS total_gestor
    FROM act
    GROUP BY bloque, gestor
),
act_norm AS (
    SELECT
        a.bloque,
        a.fila,
        a.gestor,
        a.cantidad,
        CASE WHEN t.total_gestor = 0 THEN NULL ELSE a.cantidad::numeric / t.total_gestor END AS pct,
        round(avg(a.cantidad) OVER (PARTITION BY a.bloque, a.fila))::int AS prom_cant,
        avg(CASE WHEN t.total_gestor = 0 THEN NULL ELSE a.cantidad::numeric / t.total_gestor END)
            OVER (PARTITION BY a.bloque, a.fila) AS prom_pct,
        NULL::int AS min_cant,
        NULL::numeric AS min_pct
    FROM act a
    JOIN act_tot t
      ON t.bloque = a.bloque AND t.gestor = a.gestor
),

-- ===================== TIPO_CLIENTE =====================
cli AS (
    SELECT
        'TIPO_CLIENTE'::text AS bloque,
        tipo_cliente          AS fila,
        gestor,
        count(*)::int         AS cantidad
    FROM base
    GROUP BY tipo_cliente, gestor
),
cli_tot AS (
    SELECT bloque, gestor, sum(cantidad)::numeric AS total_gestor
    FROM cli
    GROUP BY bloque, gestor
),
cli_norm AS (
    SELECT
        c.bloque,
        c.fila,
        c.gestor,
        c.cantidad,
        CASE WHEN t.total_gestor = 0 THEN NULL ELSE c.cantidad::numeric / t.total_gestor END AS pct,
        round(avg(c.cantidad) OVER (PARTITION BY c.bloque, c.fila))::int AS prom_cant,
        avg(CASE WHEN t.total_gestor = 0 THEN NULL ELSE c.cantidad::numeric / t.total_gestor END)
            OVER (PARTITION BY c.bloque, c.fila) AS prom_pct,
        NULL::int AS min_cant,
        NULL::numeric AS min_pct
    FROM cli c
    JOIN cli_tot t
      ON t.bloque = c.bloque AND t.gestor = c.gestor
),

-- ===================== MOTIVO =====================
mot AS (
    SELECT
        'MOTIVO'::text AS bloque,
        motivo          AS fila,
        gestor,
        count(*)::int   AS cantidad
    FROM base
    GROUP BY motivo, gestor
),
mot_tot AS (
    SELECT bloque, gestor, sum(cantidad)::numeric AS total_gestor
    FROM mot
    GROUP BY bloque, gestor
),
mot_norm AS (
    SELECT
        m.bloque,
        m.fila,
        m.gestor,
        m.cantidad,
        CASE WHEN t.total_gestor = 0 THEN NULL ELSE m.cantidad::numeric / t.total_gestor END AS pct,
        round(avg(m.cantidad) OVER (PARTITION BY m.bloque, m.fila))::int AS prom_cant,
        avg(CASE WHEN t.total_gestor = 0 THEN NULL ELSE m.cantidad::numeric / t.total_gestor END)
            OVER (PARTITION BY m.bloque, m.fila) AS prom_pct,
        NULL::int AS min_cant,
        NULL::numeric AS min_pct
    FROM mot m
    JOIN mot_tot t
      ON t.bloque = m.bloque AND t.gestor = m.gestor
)

SELECT * FROM act_norm
UNION ALL
SELECT * FROM cli_norm
UNION ALL
SELECT * FROM mot_norm
ORDER BY bloque, fila, gestor;
$$;


ALTER FUNCTION traking.sp_gc_kpi_normalizado(p_f1 date, p_f2 date, p_idusuario bigint) OWNER TO postgres;

--
-- TOC entry 1236 (class 1255 OID 17960)
-- Name: sp_gc_kpi_normalizado_completo(date, date, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.sp_gc_kpi_normalizado_completo(p_f1 date, p_f2 date, p_idusuario bigint) RETURNS TABLE(bloque text, fila text, gestor text, cantidad integer, pct numeric, prom_cant integer, prom_pct numeric, min_cant integer, min_pct numeric)
    LANGUAGE sql
    AS $$
WITH gestores AS (
    SELECT u.idusuario, u.sigla AS gestor
    FROM traking.listusercombovendedores(p_idusuario) lv
    JOIN traking.mct_usuario u ON u.idusuario = lv.iduser
),

concretadas AS (
    SELECT
        ag.idusuario,

        ta.idtipoactividadgestion,
        ta.nombretipoactividadgestion AS tipo_actividad,

        tc.idtipoclientecom,
        tc.nombretipoclientecom AS tipo_cliente,

        ma.idmotivoactividadgestion,
        ma.nombremotivoactividadgestion AS motivo

    FROM traking.mct_actividadgestion ag
    LEFT JOIN traking.mct_tipoactividadgestion ta
           ON ta.idtipoactividadgestion = ag.idtipoactividadgestion
    LEFT JOIN traking.mct_clientecomcontacto ccc
           ON ccc.idclientecomcontacto = ag.idclientecomcontacto
    LEFT JOIN traking.mct_clientecom cc
           ON cc.idclientecom = ccc.idclientecom
    LEFT JOIN traking.mct_tipoclientecom tc
           ON tc.idtipoclientecom = cc.idtipoclientecom
    LEFT JOIN traking.mct_motivoactividadgestion ma
           ON ma.idmotivoactividadgestion = ag.idmotivoactividadgestion
    WHERE ag.fechaactividad::date BETWEEN p_f1 AND p_f2
      AND ag.idestadoactividadgestion = 1
      AND ag.idusuario IN (SELECT idusuario FROM gestores)
),

tot_conc AS (
    SELECT idusuario, COUNT(*)::int AS total
    FROM concretadas
    GROUP BY idusuario
),

cat_tipo_actividad AS (
    SELECT idtipoactividadgestion AS sort_id,
           nombretipoactividadgestion AS fila
    FROM traking.mct_tipoactividadgestion
),

cat_tipo_cliente AS (
    SELECT idtipoclientecom AS sort_id,
           nombretipoclientecom AS fila
    FROM traking.mct_tipoclientecom
),

cat_motivo AS (
    SELECT idmotivoactividadgestion AS sort_id,
           nombremotivoactividadgestion AS fila
    FROM traking.mct_motivoactividadgestion
),

grid AS (
    SELECT 'TIPO_ACTIVIDAD'::text AS bloque, c.sort_id, c.fila, g.idusuario, g.gestor
    FROM cat_tipo_actividad c CROSS JOIN gestores g

    UNION ALL
    SELECT 'TIPO_CLIENTE'::text, c.sort_id, c.fila, g.idusuario, g.gestor
    FROM cat_tipo_cliente c CROSS JOIN gestores g

    UNION ALL
    SELECT 'MOTIVO'::text, c.sort_id, c.fila, g.idusuario, g.gestor
    FROM cat_motivo c CROSS JOIN gestores g
),

conteo AS (
    SELECT 'TIPO_ACTIVIDAD'::text AS bloque,
           idtipoactividadgestion AS sort_id,
           tipo_actividad AS fila,
           idusuario,
           COUNT(*)::int AS cantidad
    FROM concretadas
    GROUP BY 1,2,3,4

    UNION ALL
    SELECT 'TIPO_CLIENTE'::text,
           idtipoclientecom,
           tipo_cliente,
           idusuario,
           COUNT(*)::int
    FROM concretadas
    GROUP BY 1,2,3,4

    UNION ALL
    SELECT 'MOTIVO'::text,
           idmotivoactividadgestion,
           motivo,
           idusuario,
           COUNT(*)::int
    FROM concretadas
    GROUP BY 1,2,3,4
),

base AS (
    SELECT
        g.bloque,
        g.sort_id,
        g.fila,
        g.gestor,
        COALESCE(c.cantidad,0) AS cantidad,

        CASE
            WHEN COALESCE(tc.total,0) = 0 THEN 0::numeric
            ELSE ROUND((COALESCE(c.cantidad,0)::numeric / tc.total::numeric), 6)
        END AS pct,

        CASE
            WHEN g.bloque='TIPO_ACTIVIDAD'
             AND g.fila='Visita en Terreno' THEN 8

            WHEN g.bloque='TIPO_CLIENTE'
             AND g.fila IN ('Esporádico','Potencial') THEN 6

            WHEN g.bloque='MOTIVO'
             AND g.fila='Nuevos Negocios' THEN 9

            WHEN g.bloque='MOTIVO'
             AND g.fila IN ('Capacitación Técnica','Vista a Planta') THEN 1

            ELSE NULL
        END AS min_cant,

        CASE
            WHEN g.bloque='TIPO_ACTIVIDAD'
             AND g.fila='Visita en Terreno' THEN ROUND(8::numeric/30,2)

            WHEN g.bloque='TIPO_CLIENTE'
             AND g.fila IN ('Esporádico','Potencial') THEN ROUND(6::numeric/23,2)

            WHEN g.bloque='MOTIVO'
             AND g.fila='Nuevos Negocios' THEN ROUND(9::numeric/23,2)

            WHEN g.bloque='MOTIVO'
             AND g.fila IN ('Capacitación Técnica','Vista a Planta') THEN ROUND(1::numeric/23,2)

            ELSE NULL
        END AS min_pct

    FROM grid g
    LEFT JOIN conteo c
           ON c.bloque=g.bloque
          AND c.sort_id=g.sort_id
          AND c.fila=g.fila
          AND c.idusuario=g.idusuario
    LEFT JOIN tot_conc tc
           ON tc.idusuario=g.idusuario
),

prom AS (
    SELECT
        bloque,
        sort_id,
        fila,
        ROUND(AVG(cantidad))::int AS prom_cant,
        ROUND(AVG(pct)::numeric, 6) AS prom_pct
    FROM base
    GROUP BY 1,2,3
)

SELECT
    b.bloque,
    b.fila,
    b.gestor,
    b.cantidad,
    b.pct,
    p.prom_cant,
    p.prom_pct,
    b.min_cant,
    b.min_pct
FROM base b
JOIN prom p
  ON p.bloque=b.bloque
 AND p.sort_id=b.sort_id
 AND p.fila=b.fila
ORDER BY
    CASE b.bloque
        WHEN 'TIPO_ACTIVIDAD' THEN 1
        WHEN 'TIPO_CLIENTE' THEN 2
        ELSE 3
    END,
    b.sort_id,
    b.gestor;
$$;


ALTER FUNCTION traking.sp_gc_kpi_normalizado_completo(p_f1 date, p_f2 date, p_idusuario bigint) OWNER TO postgres;

--
-- TOC entry 2339 (class 1255 OID 17961)
-- Name: sp_gc_kpi_normalizado_completo_resp(date, date, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.sp_gc_kpi_normalizado_completo_resp(p_f1 date, p_f2 date, p_idusuario bigint) RETURNS TABLE(bloque text, fila text, gestor text, cantidad integer, pct numeric, prom_cant integer, prom_pct numeric, min_cant integer, min_pct numeric)
    LANGUAGE sql
    AS $$
WITH gestores AS (
    SELECT u.idusuario, u.sigla AS gestor
    FROM traking.listusercombovendedores(p_idusuario) lv
    JOIN traking.mct_usuario u ON u.idusuario = lv.iduser
),

-- ✅ catálogo SIEMPRE incluye “SIN …” para que calce con COALESCE
catalogo AS (
    -- TIPO_ACTIVIDAD
    SELECT 'TIPO_ACTIVIDAD'::text AS bloque, ta.nombretipoactividadgestion::text AS fila
    FROM traking.mct_tipoactividadgestion ta
    UNION ALL
    SELECT 'TIPO_ACTIVIDAD', 'SIN TIPO'::text

    UNION ALL
    -- TIPO_CLIENTE
    SELECT 'TIPO_CLIENTE', tc.nombretipoclientecom::text
    FROM traking.mct_tipoclientecom tc
    UNION ALL
    SELECT 'TIPO_CLIENTE', 'SIN TIPO CLIENTE'::text

    UNION ALL
    -- MOTIVO
    SELECT 'MOTIVO', ma.nombremotivoactividadgestion::text
    FROM traking.mct_motivoactividadgestion ma
    UNION ALL
    SELECT 'MOTIVO', 'SIN MOTIVO'::text
),

grid AS (
    SELECT c.bloque, c.fila, g.gestor, g.idusuario
    FROM catalogo c
    CROSS JOIN gestores g
),

reales AS (
    -- ✅ TIPO_ACTIVIDAD (usar el mismo COALESCE del catálogo)
    SELECT
        'TIPO_ACTIVIDAD'::text AS bloque,
        COALESCE(ta.nombretipoactividadgestion, 'SIN TIPO')::text AS fila,
        u.sigla AS gestor,
        count(*)::int AS cantidad
    FROM traking.mct_actividadgestion a
    JOIN gestores gg ON gg.idusuario = a.idusuario
    JOIN traking.mct_usuario u ON u.idusuario = a.idusuario
    LEFT JOIN traking.mct_tipoactividadgestion ta ON ta.idtipoactividadgestion = a.idtipoactividadgestion
    WHERE a.fechaactividad >= p_f1::timestamp
      AND a.fechaactividad < (p_f2::timestamp + interval '1 day')
    GROUP BY 1,2,3

    UNION ALL

    -- ✅ TIPO_CLIENTE
    SELECT
        'TIPO_CLIENTE'::text,
        COALESCE(tc.nombretipoclientecom, 'SIN TIPO CLIENTE')::text AS fila,
        u.sigla AS gestor,
        count(*)::int AS cantidad
    FROM traking.mct_actividadgestion a
    JOIN gestores gg ON gg.idusuario = a.idusuario
    JOIN traking.mct_usuario u ON u.idusuario = a.idusuario
    LEFT JOIN traking.mct_clientecom c ON c.idclientecom = a.idclientecom
    LEFT JOIN traking.mct_tipoclientecom tc ON tc.idtipoclientecom = c.idtipoclientecom
    WHERE a.fechaactividad >= p_f1::timestamp
      AND a.fechaactividad < (p_f2::timestamp + interval '1 day')
    GROUP BY 1,2,3

    UNION ALL

    -- ✅ MOTIVO
    SELECT
        'MOTIVO'::text,
        COALESCE(ma.nombremotivoactividadgestion, 'SIN MOTIVO')::text AS fila,
        u.sigla AS gestor,
        count(*)::int AS cantidad
    FROM traking.mct_actividadgestion a
    JOIN gestores gg ON gg.idusuario = a.idusuario
    JOIN traking.mct_usuario u ON u.idusuario = a.idusuario
    LEFT JOIN traking.mct_motivoactividadgestion ma ON ma.idmotivoactividadgestion = a.idmotivoactividadgestion
    WHERE a.fechaactividad >= p_f1::timestamp
      AND a.fechaactividad < (p_f2::timestamp + interval '1 day')
    GROUP BY 1,2,3
),

grid_data AS (
    SELECT
        g.bloque,
        g.fila,
        g.gestor,
        COALESCE(r.cantidad, 0)::int AS cantidad
    FROM grid g
    LEFT JOIN reales r
      ON r.bloque = g.bloque
     AND r.fila   = g.fila
     AND r.gestor = g.gestor
),

totales_gestor AS (
    SELECT bloque, gestor, sum(cantidad)::numeric AS total_gestor
    FROM grid_data
    GROUP BY bloque, gestor
)

SELECT
    d.bloque,
    d.fila,
    d.gestor,
    d.cantidad,
    CASE WHEN t.total_gestor = 0 THEN 0::numeric
         ELSE d.cantidad::numeric / t.total_gestor
    END AS pct,
    round(avg(d.cantidad) OVER (PARTITION BY d.bloque, d.fila))::int AS prom_cant,
    avg(
        CASE WHEN t.total_gestor = 0 THEN 0::numeric
             ELSE d.cantidad::numeric / t.total_gestor
        END
    ) OVER (PARTITION BY d.bloque, d.fila) AS prom_pct,
    NULL::int AS min_cant,
    NULL::numeric AS min_pct
FROM grid_data d
JOIN totales_gestor t
  ON t.bloque = d.bloque AND t.gestor = d.gestor
ORDER BY d.bloque, d.fila, d.gestor;
$$;


ALTER FUNCTION traking.sp_gc_kpi_normalizado_completo_resp(p_f1 date, p_f2 date, p_idusuario bigint) OWNER TO postgres;

--
-- TOC entry 1681 (class 1255 OID 17962)
-- Name: sp_gc_top_normalizado(date, date, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.sp_gc_top_normalizado(p_f1 date, p_f2 date, p_idusuario bigint) RETURNS TABLE(metrica text, gestor text, cantidad integer, pct numeric, min_cant integer, min_pct numeric, prom_cant integer, prom_pct numeric)
    LANGUAGE sql
    AS $$
WITH
g AS (
  SELECT * FROM traking.sp_gc_gestores(p_idusuario)
),
acts AS (
  SELECT ag.*
  FROM traking.mct_actividadgestion ag
  WHERE ag.fechaactividad::date BETWEEN p_f1 AND p_f2
),
base AS (
  SELECT
    g.gestor,
    COUNT(a.idactividadgestion)::int AS agendadas,
    SUM(CASE WHEN a.idestadoactividadgestion = 1 THEN 1 ELSE 0 END)::int AS concretadas
  FROM g
  LEFT JOIN acts a ON a.idusuario = g.idusuario_gestor
  GROUP BY g.gestor
),
calc AS (
  SELECT
    gestor,
    agendadas,
    concretadas,
    CASE
      WHEN agendadas = 0 THEN 0::numeric
      ELSE concretadas::numeric / agendadas::numeric
    END AS conc_pct
  FROM base
),
prom AS (
  SELECT
    ROUND(AVG(agendadas))::int AS prom_ag,
    ROUND(AVG(concretadas))::int AS prom_conc,
    COALESCE(AVG(conc_pct),0)::numeric AS prom_conc_pct
  FROM calc
),

-- ✅ NUEVO: EQUIPOS CIRCULANTES desde tabla (0 si no existe)
eq AS (
  SELECT
    COALESCE(SUM(ec.numerodeequipos), 0)::int AS equipos_cant
  FROM traking.mct_equiposcirculantes ec
  WHERE ec.fechadesde  = p_f1
    AND ec.fechahasta = p_f2
)

SELECT
  'AGENDADAS'::text AS metrica,
  c.gestor,
  c.agendadas AS cantidad,
  0::numeric  AS pct,
  30::int     AS min_cant,
  0::numeric  AS min_pct,
  (SELECT prom_ag FROM prom) AS prom_cant,
  0::numeric  AS prom_pct
FROM calc c

UNION ALL
SELECT
  'CONCRETADAS',
  c.gestor,
  c.concretadas,
  COALESCE(c.conc_pct,0)::numeric,
  23,
  0.75::numeric,
  (SELECT prom_conc FROM prom),
  (SELECT prom_conc_pct FROM prom)
FROM calc c

UNION ALL
SELECT
  'EQUIPOS_CIRCULANTES',
  'CENTRO',
  (SELECT equipos_cant FROM eq) AS cantidad,   -- ✅ aquí reemplazamos el 27
  0::numeric     AS pct,
  40::int        AS min_cant,
  0::numeric     AS min_pct,
  0::int         AS prom_cant,
  0::numeric     AS prom_pct

ORDER BY 1, 2;
$$;


ALTER FUNCTION traking.sp_gc_top_normalizado(p_f1 date, p_f2 date, p_idusuario bigint) OWNER TO postgres;

--
-- TOC entry 2039 (class 1255 OID 17963)
-- Name: test(); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.test() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare
	       
	    arreglo     varchar[];
	    arreglo2    varchar[];
	   
	    textoin     varchar;
	    sp_salir    integer;
	    anterior    integer;	
	   	actual      integer;	 
	
begin

	--select 5::int as var into temp table myvar;

	create temp table ot_temp(id varchar);

    insert into tabla_prueba (
	select array(
	 select idot 
	   from (
			select idordentrabajo as idot
		      from mct_ordentrabajo
		     where idordentrabajo = 262 
			 union
			select idordentrabajoanterior  as idot
		      from mct_ordentrabajo 
		     where idordentrabajo = 262
			 union
			select idordentrabajoanterior  as idot
		      from mct_ordentrabajo 
		     where idordentrabajoanterior = 262	 
			 union
			select idordentrabajo  as idot
		      from mct_ordentrabajo
		     where idordentrabajoanterior = 262	) a) );
     
		select columna 
		  from (
			   select array_agg(c) as columna
				from (
			       select unnest(column_name)
			       from tabla_prueba
				) as dt(c)
				) a
		   into arreglo;
			
	    textoin := '(';
		     	 
	    FOR i IN array_lower(arreglo, 1) .. array_upper(arreglo, 1)
			  loop
			   insert into ot_temp values (arreglo[i]);
               anterior := anterior + 1;
		
	    END LOOP;
			  
	   -- textoin := replace(textoin, '(,', '') ;
			 

		sp_salir := 0;
	
	    WHILE sp_salir < 5
    
        LOOP
	 
            insert into tabla_prueba (
				select array(
					 select idot 
					   from (
                        
						select idordentrabajo as idot
					      from mct_ordentrabajo
						     where idordentrabajo  in (select cast(id as integer) from ot_temp) and idordentrabajo > 0
							 union
							select idordentrabajoanterior  as idot
						      from mct_ordentrabajo 
						     where idordentrabajo  in (select cast(id as integer) from ot_temp) and idordentrabajo > 0
							 union
							select idordentrabajoanterior  as idot
						      from mct_ordentrabajo 
						     where idordentrabajoanterior  in (select cast(id as integer) from ot_temp) and idordentrabajoanterior > 0
							 union
							select idordentrabajo  as idot
						      from mct_ordentrabajo
						     where idordentrabajoanterior in (select cast(id as integer) from ot_temp) and idordentrabajoanterior > 0 	) a) );
						    
	
			sp_salir := sp_salir + 1;
		
			select columna 
			  from (
				   select array_agg(c) as columna
					from (
				       select unnest(column_name)
				       from tabla_prueba
					) as dt(c)
					) a
			   into arreglo;
				
			actual := 0;     	 
		    FOR i IN array_lower(arreglo, 1) .. array_upper(arreglo, 1)
				  loop
				   insert into ot_temp values (arreglo[i]);
			       actual := actual + 1;
		    END LOOP;
		   
		    --if (anterior = actual) then
		    --    sp_salir := 1;
		    --else
		    --    anterior := actual;
		    --end if;
			 

        END LOOP;
       
    --drop table ot_temp;
    
    return textoin;   
		   
END;
$$;


