--
-- TOC entry 1163 (class 1255 OID 17964)
-- Name: test_evtlistrepenrep(bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.test_evtlistrepenrep(idcustomer bigint) RETURNS TABLE(id bigint, ot bigint, fechar character varying, fechaa character varying, fechae character varying, tipo character varying, modelo character varying, avance bigint, monto bigint)
    LANGUAGE plpgsql
    AS $$
declare

    sp_id      		integer;
    sp_ot      		integer;
    sp_fechar  		varchar;
    sp_fechaa  		timestamp;
    sp_fechae  		varchar;
    sp_tipo    		varchar;
    sp_modelo  		varchar;
    sp_avance  		numeric;
    sp_monto   		integer;
    sp_estado  		integer;
   
    sp_fechat  		varchar;
    sp_dias    		integer;
    sp_diast   		integer;
    sp_porc    		integer;
         
    sp_dife    		integer;
   
    sp_diassla 		integer;
    cuenta_habiles	integer;
	sp_i            integer;
	dia_dow         integer;
    new_fechae      varchar;
    fecha_paso      timestamp;
    intervalo    	varchar;
   
    rec1 	   		record;
   
BEGIN

	FOR rec1 IN (   
       select ROW_NUMBER() OVER (ORDER BY a.idordentrabajo desc) as sp_id,
              a.idordentrabajo as sp_ot,
              to_char(a.fecharecepcion, 'dd-mm-yyyy') as sp_fechar,
              to_char(a.fechaentrega, 'dd-mm-yyyy') as sp_fechae,
              d.sigla as sp_tipo,
              case 
                when idlineadiseno = 1 then 'DE DISEÑO'
                when idlineadiseno = 2 then 'DE LINEA'
              end||' - '||d.sigla||' '||c.nombremodelo as sp_modelo,
              coalesce (a.montorepfab, 0) as sp_monto,
              a.idlineadiseno
         from mct_ordentrabajo a,
              mct_producto b,
              mct_modelo c,
              mct_subfamilia d
        where a.idordentrabajo >= 30000
          and a.idcliente = 6
          and a.idtipoorden = 1
          and a.flagapp = 1
          and a.idfamilia = 8
          and a.idestadoorden >= 6 and a.idestadoorden < 9
          and a.idproducto = b.idproducto 
          and b.idmodelo = c.idmodelo 
          and c.idsubfamilia = d.idsubfamilia 
          and a.ordencompra is not null
          and a.ordencompra > 0
          )
		loop           
		
		   if ( rec1.idlineadiseno = 1 ) then
		   
		      select rembbadiseno
		        into sp_diassla
		        from mct_sla 
		       where idsla = 8;
		      
		   else 
		   
		      select rembbalinea 
		        into sp_diassla
		        from mct_sla 
		       where idsla = 8;
		      
		   
		   end if;
		  
		   select fecha_autoriza_cliente
		     into sp_fechaa
		     from mct_progavisos mp 
		    where idsla = 5
		      and idordentrabajo = rec1.sp_ot;     
		         
		     
		     
			sp_i := 1;
		    cuenta_habiles := 0;
	
		    fecha_paso := sp_fechaa;
	  
	    
	        while ( sp_i <= sp_diassla) loop
	              
	              fecha_paso := fecha_paso + interval '1 day';
	             
	              dia_dow := date_part('dow', fecha_paso);
	              if ( dia_dow in (1,2,3,4,5) ) then
	              	  sp_i := sp_i + 1;	  
	              end if;
	              cuenta_habiles := cuenta_habiles + 1;	              

	        end loop;
	       	             
	       	--cuenta_habiles := cuenta_habiles + 1;
		   
		   	intervalo := ''''||cuenta_habiles||' day';
				
			select to_char(sp_fechaa + intervalo::interval, 'dd-mm-yyyy') into new_fechae;
		    	       
		    sp_avance  := 0;
		    --sp_fechat  := '';
		    sp_dias    := 0;
		    sp_dife    := 0;
		    sp_diast   := 0;
		    sp_porc    := 0;
		      

		       select to_char(fecha_termino,'dd-mm-yyyy'),
		              estado
		         into sp_fechae,
		              sp_estado
		         from mct_progavisos mp 
		        where idsla = 8
		          and idordentrabajo = rec1.sp_ot;  
		         
		         
		        if ( now() >= to_date(new_fechae,'dd-mm-yyyy')) then
		        
		           sp_avance := 100;
		        
		        end if;
		       
		        if ( now() < to_date(new_fechae,'dd-mm-yyyy')) then
		        
		           	
		            sp_diast := date_part('day', to_date(new_fechae,'dd-mm-yyyy') - sp_fechaa)  ;
		            sp_dias  := date_part('day', now() - sp_fechaa ) ;
		        --   
		            sp_dife   := sp_diast - sp_dias;
		            sp_avance := round( (sp_dife * 100)/sp_diast  );
		        
		        end if;
		       
		        if (sp_dias = 0) then
		        
		           sp_avance := 0;
		        
		        end if;

		       	if (sp_avance > 100) then
		        
		           sp_avance := 100;
		        
		        end if;
		       
		         
			    id      := rec1.sp_id;
			    ot      := rec1.sp_ot;
			    fechar  := rec1.sp_fechar;
			    fechaa  := to_char(sp_fechaa,'dd-mm-yyyy');
			    --fechae  := rec1.sp_fechae;
			    fechae  := new_fechae;
			    tipo    := rec1.sp_tipo;
			    modelo  := rec1.sp_modelo;
			    avance  := sp_avance;
			    monto   := rec1.sp_monto;
			    
		     
		      RETURN next;
		     
		END LOOP;		     

END;
$$;


ALTER FUNCTION traking.test_evtlistrepenrep(idcustomer bigint) OWNER TO postgres;

--
-- TOC entry 1821 (class 1255 OID 17965)
-- Name: updateaction(bigint, character varying, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateaction(idactionup bigint, nameactionup character varying, codeactionup character varying, statusup bigint, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    update traking.mct_accion
    set nombreaccion=nameactionup,
        codigoaccion=codeactionup,
