--
-- TOC entry 2197 (class 1255 OID 17975)
-- Name: updatebloqworkorder(bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updatebloqworkorder(idworkorderup bigint, idorderstatusup bigint, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

	if ( idorderstatusup = 999 ) then 
	
		if ( select 1 
		       from traking.mct_ordentrabajo 
		      where idordentrabajo = idworkorderup
		        and flagapp = 0) then
		        
			    update traking.mct_ordentrabajo 
			    set flagapp = 1
			    where idordentrabajo = idworkorderup;
	    else
			    update traking.mct_ordentrabajo 
			    set flagapp = 0
			    where idordentrabajo = idworkorderup;    
	    end if;
   
	elsif ( idorderstatusup = 11) then
	
		     update traking.mct_ordentrabajo 
			    set idestadoorden = 11
			  where idordentrabajo = idworkorderup;
	
	end if;

END;
$$;


ALTER FUNCTION traking.updatebloqworkorder(idworkorderup bigint, idorderstatusup bigint, userupdateup character varying) OWNER TO postgres;

