--
-- TOC entry 1667 (class 1255 OID 17982)
-- Name: updatechangedateowkorder(bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updatechangedateowkorder(idworkorder bigint, deliverydate character varying, observationup character varying, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

	sp_fecha					timestamp;

    sp_fechatm					timestamp;
    sp_fechaclte				timestamp;
    sp_fechafund				timestamp;
    sp_familia					integer;
    sp_ordertype				integer;
   
    sp_mec						integer;

BEGIN

	sp_familia		:= 0;
	sp_ordertype	:= 0;
    sp_mec			:= 0;

	select fechaentrega ,
	       idfamilia ,
	       idtipoorden 
	  into sp_fecha,
	       sp_familia,
	       sp_ordertype
	  from mct_ordentrabajo 
	 where idordentrabajo = idworkorder;
	
	if ( sp_ordertype = 2) then
	    
		    if ( sp_familia in (8, 10, 15) ) then

		        sp_fechaclte	:=  to_date(deliverydate,'yyyy-mm-dd');
			    sp_fechatm		:=	sp_fechaclte - interval '7 days';
			    sp_fechafund	:=	sp_fechatm - interval '15 days';	
	    
		    end if;	    
		   
		    if ( sp_familia in (11) ) then

				select max(idesmecanizado)
				  into sp_mec
				  from mct_ordentrabajorepuesto 
				 where idordentrabajo = idworkorder;
	
		        if ( sp_mec = 1 ) then
		        
			        sp_fechaclte	:=  to_date(deliverydate,'yyyy-mm-dd');
				    sp_fechatm		:=	sp_fechaclte - interval '15 days';
				    sp_fechafund	:=	sp_fechatm ;			        
			        
		        else
		        
		  			sp_fechaclte	:=  to_date(deliverydate,'yyyy-mm-dd');
				    sp_fechatm		:=	to_date(deliverydate,'yyyy-mm-dd');
				    sp_fechafund	:=	to_date(deliverydate,'yyyy-mm-dd');	      
		        
		        end if;
		       
	    
		    end if;	    
		   
	elsif ( sp_ordertype = 1) then
	    
		    if ( sp_familia in (8, 10, 15) ) then

		        sp_fechaclte	:=  to_date(deliverydate,'yyyy-mm-dd');
			    sp_fechatm		:=	sp_fechaclte - interval '7 days';
			    sp_fechafund	:=	sp_fechatm - interval '15 days';	
	    
		    end if;	   	    
	    
	end if;
	   
	   
    update traking.mct_ordentrabajo 
	   set fechaentrega = to_date(deliverydate,'yyyy-mm-dd'),
	       fechafaceclte = sp_fechaclte,
	       fechafacetm = sp_fechatm,
	       fechafundicion = sp_fechafund,
	       fechafundicion2 = sp_fechafund
     where idordentrabajo = idworkorder;
    
    
	insert into mct_ordentrabajoprorroga
			(
			idordentrabajoprorroga,
			idordentrabajo,
			observacion,
			fechaentrega,
			nuevafechaentrega,
			usuariocreacion,
			fechacreacion
			)
	values 
			(
			nextval('mct_ordentrabajoprorroga_seq'),
			idworkorder,
			observationup,
			sp_fecha,
			to_date(deliverydate,'yyyy-mm-dd'),
			usercreate,
			now()
		    );

END;
$$;


ALTER FUNCTION traking.updatechangedateowkorder(idworkorder bigint, deliverydate character varying, observationup character varying, usercreate character varying) OWNER TO postgres;

