--
-- TOC entry 1617 (class 1255 OID 17988)
-- Name: updatecomponenttipwork(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updatecomponenttipwork(idcomponenttipworkup bigint, descriptionup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

	checklist    integer[];
    indice       integer;
    desde        integer := 1;
    texto        varchar := '';
    val_check    varchar := '';

BEGIN

	checklist := string_to_array(descriptionup,',');
    indice    := array_length(checklist,1);
   
    while desde <= indice LOOP
    
      select nombrechecklist
        into val_check
      from mct_checklist 
      where idchecklist = checklist[desde];
     
      if (desde = 1) then
            texto := E'\n-'||val_check;
      else
            texto := texto ||E'\n- '||val_check;
      end if;
     
      desde := desde + 1;
     
    End loop;
	
    update traking.mct_componentetipotrabajo 
       set descripcion = descriptionup,
           descripciontexto = texto
     where idcomponentetipotrabajo = idcomponenttipworkup;
    
  --  return  texto;
  -- array_upper y array_lower
   
END;
$$;


ALTER FUNCTION traking.updatecomponenttipwork(idcomponenttipworkup bigint, descriptionup character varying) OWNER TO postgres;

