--
-- TOC entry 1831 (class 1255 OID 17999)
-- Name: updateemergenciaot(bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateemergenciaot(idordentrabajoup bigint, userupdateup character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare

	avanceco	numeric;
    avancepa	numeric;
   
BEGIN
   
 update traking.mct_ordentrabajo
    set emergenciaot = true,
        fechaemergenciaotvalido = now(),
        usuarioemergenciaot = userupdateup
    where idordentrabajo = idordentrabajoup;
   
    select round(coalesce(salav))
      into avancepa
      from traking.calcularavancepanol(idordentrabajoup);
   
    select round(coalesce(salav))
      into avanceco
      from traking.calcularavancerpo(idordentrabajoup);
     
   return avanceco||'#'||avancepa;
   
END;
$$;


ALTER FUNCTION traking.updateemergenciaot(idordentrabajoup bigint, userupdateup character varying) OWNER TO postgres;

