--
-- TOC entry 2027 (class 1255 OID 18019)
-- Name: updatekit(bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updatekit(idkitup bigint, nombrekitup character varying, montokitup bigint, userupdateup character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE 
    sp_cantidad BIGINT;
    v_rows      INTEGER;
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM traking.mct_kit
         WHERE idkit = idkitup
    ) THEN
        RETURN '1:Error: no existe el kit ' || idkitup;
    END IF;

    SELECT COALESCE(SUM(a.cantidad), 0)
      INTO sp_cantidad
      FROM traking.mct_kitdetalle a
     WHERE a.idkit = idkitup;

    IF sp_cantidad = 0 THEN
        RETURN '1:Error: el kit ' || idkitup || ' no tiene detalle o la cantidad total es 0';
    END IF;

    UPDATE traking.mct_kit
       SET nombrekit = nombrekitup,
           montokit = montokitup,
           usuariomodificacion = userupdateup,
           fechamodificacion = NOW()
     WHERE idkit = idkitup;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RETURN '1:Error: no se pudo actualizar el kit ' || idkitup;
    END IF;

    UPDATE traking.mct_kitdetalle
       SET valorkit = ROUND((montokitup::numeric / sp_cantidad::numeric), 2)
     WHERE idkit = idkitup;

    RETURN '0:Éxito';

EXCEPTION
    WHEN OTHERS THEN
        RETURN '1:Error: ' || SQLERRM;
END;
$$;


ALTER FUNCTION traking.updatekit(idkitup bigint, nombrekitup character varying, montokitup bigint, userupdateup character varying) OWNER TO postgres;

--
-- TOC entry 1988 (class 1255 OID 18020)
-- Name: updatekitdetalle(bigint, bigint, character varying, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updatekitdetalle(idkitdetalleup bigint, idkitup bigint, nombrekitdetalleup character varying, planoup character varying, cantidadup bigint, userupdateup character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE 
    sp_cantidad  BIGINT;
    sp_montokit  NUMERIC;
    v_rows       INTEGER;
BEGIN
    -- Validar que exista el kit
    IF NOT EXISTS (
        SELECT 1
          FROM traking.mct_kit
         WHERE idkit = idkitup
    ) THEN
        RETURN '1:Error: no existe el kit ' || idkitup;
    END IF;

    -- Validar que exista el detalle dentro del kit
    IF NOT EXISTS (
        SELECT 1
          FROM traking.mct_kitdetalle
         WHERE idkitdetalle = idkitdetalleup
           AND idkit = idkitup
    ) THEN
        RETURN '1:Error: no existe el detalle ' || idkitdetalleup || ' para el kit ' || idkitup;
    END IF;

    -- Obtener monto del kit
    SELECT COALESCE(a.montokit, 0)
      INTO sp_montokit
      FROM traking.mct_kit a
     WHERE a.idkit = idkitup;

    -- Actualizar detalle
    UPDATE traking.mct_kitdetalle
       SET nombrekitdetalle     = nombrekitdetalleup,
           plano                = planoup,
           cantidad             = cantidadup,
           usuariomodificacion  = userupdateup,
           fechamodificacion    = NOW()
     WHERE idkitdetalle = idkitdetalleup
       AND idkit = idkitup;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RETURN '1:Error: no se pudo actualizar el detalle ' || idkitdetalleup;
    END IF;

    -- Recalcular cantidad total del kit
    SELECT COALESCE(SUM(a.cantidad), 0)
      INTO sp_cantidad
      FROM traking.mct_kitdetalle a
     WHERE a.idkit = idkitup;

    IF sp_cantidad = 0 THEN
        RETURN '1:Error: el kit ' || idkitup || ' no tiene detalle o la cantidad total es 0';
    END IF;

    -- Recalcular valor unitario para todos los detalles del kit
    UPDATE traking.mct_kitdetalle
       SET valorkit = ROUND((sp_montokit::numeric / sp_cantidad::numeric), 2)
     WHERE idkit = idkitup;

    RETURN '0:Éxito';

EXCEPTION
    WHEN OTHERS THEN
        RETURN '1:Error: ' || SQLERRM;
END;
$$;


ALTER FUNCTION traking.updatekitdetalle(idkitdetalleup bigint, idkitup bigint, nombrekitdetalleup character varying, planoup character varying, cantidadup bigint, userupdateup character varying) OWNER TO postgres;

