--

CREATE FUNCTION traking.updatemachine(idsubsectionup bigint, idmachineup bigint, namemachine character varying, codemachineup character varying, codenewup character varying, codelcdup character varying, statusup integer, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare 

	md5temp 	varchar;

BEGIN

	md5temp = CAST(idmachineup AS varchar);

    SELECT MD5(md5temp) into md5temp;
   
    update traking.mct_maquina
       set idsubseccion=idsubsectionup,
           nombremaquina=namemachine,
           codigomaquina=codemachineup,
           codigonuevo=codenewup,
           codigolcd=codelcdup,
           estado=statusup,
           usuariomodificacion=userupdateup,
           fechamodificacion=now(),
           qrcodigo = md5temp
     where idmaquina = idmachineup;

END;
$$;


