-- TOC entry 1717 (class 1255 OID 18035)
-- Name: updateoperator(bigint, bigint, character varying, character varying, bigint, boolean, character varying, bigint, bigint, boolean, boolean, boolean, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateoperator(idprofileup bigint, idoperatorup bigint, nameoperatorup character varying, rut character varying, idmachine bigint, movilizacionpropiaup boolean, direccionup character varying, idsectorup bigint, telefonocontactoup bigint, aplicacontrolturnoup boolean, aplicacontrolturnofundup boolean, aplicacontrolturnofund2up boolean, idseccionprincipalup bigint, idcargoup bigint, statusup bigint, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
		rutn 		VARCHAR := '';
		rutd 		VARCHAR := '';
		sp_idperfil	bigint	:= 6;
begin
	 
	if (idseccionprincipalup = 11 ) then
		sp_idperfil	:= 9;
	elsif (idseccionprincipalup = 14 ) then
		sp_idperfil	:= 8;	
	elsif (idseccionprincipalup = 76 ) then
		sp_idperfil	:= 16;
	elsif (idseccionprincipalup = 77 ) then
		sp_idperfil	:= 16;
	elsif (idseccionprincipalup = 39 ) then
		sp_idperfil	:= 14;
	elsif (idseccionprincipalup = 36 ) then
		sp_idperfil	:= 15;
	end if;

    rutn := split_part(rut,'-',1);
	rutd := split_part(rut,'-',2);
	
    update traking.mct_operador
       set idperfil=sp_idperfil,
           nombreoperador=nameoperatorup,
           estado=statusup,
           usuariomodificacion=userupdateup,
           fechamodificacion=now(),
		   rut = rutn,
		   digito = rutd,
		   idmaquina = idmachine,
           movilizacionpropia = movilizacionpropiaup,
           direccion = direccionup,
           idsector = idsectorup,
           telefonocontacto = telefonocontactoup,
           aplicacontrolturno = aplicacontrolturnoup,
           aplicacontrolturnofund = aplicacontrolturnofundup,
           aplicacontrolturnofund2 = aplicacontrolturnofund2up,
           idseccionprincipal = idseccionprincipalup	,
           idcargo = idcargoup
		   
    where idoperador = idoperatorup;
END;
$$;


ALTER FUNCTION traking.updateoperator(idprofileup bigint, idoperatorup bigint, nameoperatorup character varying, rut character varying, idmachine bigint, movilizacionpropiaup boolean, direccionup character varying, idsectorup bigint, telefonocontactoup bigint, aplicacontrolturnoup boolean, aplicacontrolturnofundup boolean, aplicacontrolturnofund2up boolean, idseccionprincipalup bigint, idcargoup bigint, statusup bigint, userupdateup character varying) OWNER TO postgres;

--
-- TOC entry 1473 (class 1255 OID 18036)
-- Name: updateordercopy(bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateordercopy(idworkorderfrom bigint, idworkorderto bigint, usercreate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 
	   
	    sp_hrchar            TEXT;
        sp_partchar          TEXT;
        sp_itemchar          TEXT;      
        sp_corrchar          TEXT;
       
        sp_idhrt             INTEGER; 

        indice   		     INTEGER;
        tope	   		     INTEGER;
        sp_item              integer;
		                           
		rec_hrparte          RECORD;
        cur_hrparte          CURSOR(sp_idotf integer)  FOR
								       select idhojarutatemp,
								              idcomponente ,
								              idmaterial , 
								              nombreplano ,
								              cantidad,
								              nombrematerial ,
								              textoadicional ,
								              idtrabajohr ,
								              idimprimehojas ,
								              idboleano
								         from mct_hojarutatemp
								        where idordentrabajo = sp_idotf 
								     order by idhojarutatemp ; 

		rec_hractiv          RECORD;	
        cur_hractiv          CURSOR(sp_idhr integer)  FOR
								       select idactividad , 
								              tiempoproduccion , 
								              orden 
								         from mct_hojarutaactividadtemp 
								        where idhojarutatemp = sp_idhr 
								     order by orden ;
								    
	    sp_idpwo   		     INTEGER;							    
         						           
         						           
begin
	
        sp_hrchar       := '';
        sp_partchar     := '';
        sp_corrchar     := '';	       
    
        sp_item         := 1;
       
        OPEN cur_hrparte(idworkorderfrom);

        loop 
                
            FETCH cur_hrparte INTO rec_hrparte;

            EXIT WHEN NOT FOUND;
           
                   sp_idhrt := nextval('mct_hojarutatemp_seq');
	                
		           INSERT INTO traking.mct_hojarutatemp
		                      (idhojarutatemp, 
		                       idordentrabajo, 
		                       idcomponente, 
		                       idmaterial, 
		                       nombreplano, 
		                       cantidad, 
		                       usuariocreacion, 
		                       fechacreacion,
		                       nombrematerial ,
		                       textoadicional ,
		                       idtrabajohr ,
		                       idimprimehojas ,
		                       idboleano
		                       )
						VALUES(sp_idhrt, 
					           idworkorderto, 
					           rec_hrparte.idcomponente, 
					           rec_hrparte.idmaterial, 
					           rec_hrparte.nombreplano,
					           rec_hrparte.cantidad,  
					           usercreate, 
					           now(),
					           rec_hrparte.nombrematerial,
					           rec_hrparte.textoadicional,
					           rec_hrparte.idtrabajohr,
					           rec_hrparte.idimprimehojas,
					           rec_hrparte.idboleano
					           );

					if ( rec_hrparte.idimprimehojas = 1 ) then
    
       					tope  := 1;
      
   					else
 
    					tope := coalesce(rec_hrparte.cantidad,0);
    
    				end if;
		                   
					--tope := coalesce(rec_hrparte.cantidad,0);
						           
					indice := 1;
						
					loop						
					
						sp_hrchar   := LPAD(idworkorderto::integer::text::varchar, 6, '0');  
						sp_partchar := LPAD(rec_hrparte.idcomponente::integer::text::varchar, 3, '0');
						sp_itemchar := LPAD(sp_item::integer::text::varchar, 3, '0'); 
						sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
						
						insert into mct_detallehojarutatemp 
						           (iddetallehojarutatemp 
						           ,idhojarutatemp 
						           ,codhojaruta 
						           ,correlativoparte
						           )
						     VALUES
						           (nextval('traking.mct_detallehojarutatemp_seq')
						           ,sp_idhrt
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,indice
						           );                     


						sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
					
						insert into mct_ordentrabajoparte 
						           (idordentrabajoparte 
						           ,idordentrabajo 
						           ,idcomponente 
						           ,itemparte 
						           ,itemcorr 
						           )
						     VALUES
						           (sp_idpwo
						           ,idworkorderto
						           ,rec_hrparte.idcomponente 
						           ,indice
						           ,sp_item
						           );   
				
						          
		          
						-- Esto es para igualar la tabla Hoja Ruta
					    insert into mct_hojaruta 
						           (idhojaruta 
						           ,idordentrabajoparte 
						           ,codhojaruta 
						           ,usuariocreacion 
						           ,fechacreacion 
						           ,modalidad
						           ,idhojarutatemp 
						           )
						     VALUES
						           (nextval('traking.mct_hojaruta_seq')
						           ,sp_idpwo
						           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar 
						           ,'admin' 
						           ,now()
						           ,1
						           ,sp_idhrt
						           ); 

						 indice := indice + 1;
						                           				   
						 EXIT when indice > tope;
						                    
					END loop;   
					
				    sp_item := sp_item + 1;
		
				    OPEN cur_hractiv(rec_hrparte.idhojarutatemp);

			        loop 
			                
			            FETCH cur_hractiv INTO rec_hractiv;
			
			            EXIT WHEN NOT FOUND;

						       INSERT INTO traking.mct_hojarutaactividadtemp
											(idhojarutaactividadtemp, 
											 idhojarutatemp, 
											 idactividad, 
											 tiempoproduccion, 
											 orden)
									  VALUES(nextval('mct_hojarutaactividadtemp_seq'),
									         sp_idhrt, 
									         rec_hractiv.idactividad, 
									         rec_hractiv.tiempoproduccion, 
									         rec_hractiv.orden
									        );

			           
			        End Loop;
        
        			CLOSE cur_hractiv;
       

        End Loop;
        
        CLOSE cur_hrparte;
                                  	               

END
$$;


ALTER FUNCTION traking.updateordercopy(idworkorderfrom bigint, idworkorderto bigint, usercreate character varying) OWNER TO postgres;

