--

CREATE FUNCTION traking.updateorderstatus(idorderstatusup bigint, orderstatusnameup character varying, statusup bigint, userupdate character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    update traking.mct_estadoorden
    set nombreestado=orderstatusnameup,
        estado=statusup,
        usuariomodificacion=userupdate,
        fechamodificacion=now()
       WHERE traking.mct_estadoorden.idestadoorden=idorderstatusup;
END;
$$;


