--

CREATE FUNCTION traking.updatepart(idpartup bigint, partnameup character varying, idblueprintup bigint, idmaterialup bigint, idparttypeup bigint, manufacturingcostup integer, principal bigint, critical bigint, comercialdesc character varying, idpurchasetype bigint, idcomponent bigint, statusup bigint, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    update traking.mct_parte
    set nombreparte=partnameup,
        idplano=idblueprintup,
        idmaterial=idmaterialup,
        idtipoparte=idparttypeup,
        costofabricacion=manufacturingcostup,
        esprincipal=principal,
        escritico=critical,
        descripcioncomercial = comercialdesc,
        idtipocompra  = idpurchasetype,
        --idcomponente = idcomponent,
        estado=statusup,
        usuariomodificacion=userupdateup,
        fechamodificacion=now()
    where idparte = idpartup;
END;
$$;


