--
-- TOC entry 1427 (class 1255 OID 18044)
-- Name: updateprioridadregistroarmadodesarmeonline(bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateprioridadregistroarmadodesarmeonline(idotup bigint, prioridadup bigint) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows INTEGER;
BEGIN
    UPDATE traking.mct_registroarmadodesarmeonline
       SET prioridad = prioridadup
     WHERE idot = idotup;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows > 0 THEN
        RETURN '0:Éxito';
    ELSE
        RETURN '1:Error: no existe registro en mct_registroarmadodesarmeonline para la OT ' || idotup;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN '1:Error: ' || SQLERRM;
END;
$$;


ALTER FUNCTION traking.updateprioridadregistroarmadodesarmeonline(idotup bigint, prioridadup bigint) OWNER TO postgres;

--
-- TOC entry 1908 (class 1255 OID 18045)
-- Name: updateproduct(bigint, character varying, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateproduct(idproductup bigint, productnameup character varying, idmanufacturerup bigint, idmodelup bigint, idcustomerup bigint, statusup bigint, flowvalup bigint, rpmvalup bigint, lengthvalup bigint, heightvalup bigint, powervalup bigint, idphaseparam bigint, generalplan character varying, idmaterialup bigint, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare

		sp_nombreproducto		varchar;
	    sp_nombreetapa          varchar;
	   
begin

		select nombreparam 
	      into sp_nombreetapa
    	  from traking.mct_etapaparam 
    	 where idetapaparam = idphaseparam;
		
    	if ( idphaseparam = 13 ) then
    	
	 	   	  select c.nombrefamilia||' - '||b.nombresubfamilia||' - '||a.nombremodelo
		   	    into sp_nombreproducto
				from mct_modelo a,
				     mct_subfamilia b,
				     mct_familia c
				where a.idmodelo = idmodelup
				and a.idsubfamilia = b.idsubfamilia 
				and b.idfamilia  = c.idfamilia ;   	
    	
    	else

		   	  select c.nombrefamilia||' - '||b.nombresubfamilia||' - '||a.nombremodelo||' - '||sp_nombreetapa
		   	    into sp_nombreproducto
				from mct_modelo a,
				     mct_subfamilia b,
				     mct_familia c
				where a.idmodelo = idmodelup
				and a.idsubfamilia = b.idsubfamilia 
				and b.idfamilia  = c.idfamilia ;    	
    	
    	end if;
	


		    update traking.mct_producto
		    set nombreproducto=sp_nombreproducto,
		        idmodelo=idmodelup,
		        idfabricante=idmanufacturerup,
		        idcliente=idcustomerup,
		        estado=statusup,
		        caudal=flowvalup,
		        rpm=rpmvalup,
		        largo=lengthvalup,
		        altura=heightvalup,
		        potencia=powervalup,
		        idetapaparam=idphaseparam,
		        planogeneral=generalplan,
		        idmaterial =idmaterialup,
		        usuariomodificacion=userupdateup,
		        fechamodificacion=now()
		    where idproducto = idproductup;
END;
$$;


