--
-- TOC entry 1789 (class 1255 OID 18055)
-- Name: updateroadmaptemp(bigint, bigint, bigint, bigint, character varying, character varying, bigint, character varying, bigint, bigint, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateroadmaptemp(idroadmaptempup bigint, idworkorderup bigint, idcomponentup bigint, idmaterialup bigint, materialname character varying, blueprintname character varying, quantityup bigint, aditionaltext character varying, idworkhr bigint, idimprimehojasup bigint, idboleanoup bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 
		sp_cant						integer;
        sp_hrchar                   TEXT;
        sp_partchar                 TEXT;
        sp_corrchar                 TEXT;
        sp_itemchar                 TEXT;      
       
        sp_part						integer;

        indice   				    INTEGER;
        tope	   				    INTEGER;
	
        sp_idpwo   				    INTEGER;
        sp_maxitem                  integer;     
       
        sp_imprime                  integer;
	
BEGIN

	select count(*)
	  into sp_cant
	  from mct_detallehojarutatemp 
	 where idhojarutatemp = idroadmaptempup;
	
	
	select idimprimehojas 
	  into sp_imprime
	  from mct_hojarutatemp mh 
	 where idhojarutatemp =  idroadmaptempup;
	
	sp_maxitem      := 0;

	select max(a.itemcorr)+1
	  into sp_maxitem
	  from mct_ordentrabajoparte a
     where a.idordentrabajo = idworkorderup;
	
	if ( quantityup <> sp_cant or sp_imprime <> idimprimehojasup ) then
	
	   -- Primero borra las hojas de ruta asociadas a los idordentrabajoparte de la ot
	   --delete from mct_hojaruta 
	   -- where idordentrabajoparte in (select idordentrabajoparte 
		--							    from mct_ordentrabajoparte mo 
		--							   where idordentrabajo = idworkorderup
		--							     and idcomponente   = idcomponentup);

	    delete from mct_ordentrabajoparte mo 
		 where idordentrabajoparte in ( select idordentrabajoparte
		                                  from mct_hojaruta
		                                 where idhojarutatemp = idroadmaptempup) ;	  
		                                
		delete from mct_hojaruta 
	     where idhojarutatemp = idroadmaptempup;										    
	
	   -- Luego elimina los idordentrabajoparte de la ot
	   --delete from mct_ordentrabajoparte mo 
	   --      where idordentrabajo = idworkorderup
	   --        and idcomponente   = idcomponentup;
	          

		                                
		select idcomponente
	      into sp_part
	      from mct_hojarutatemp 
	     where idhojarutatemp = idroadmaptempup;
		
	    delete from mct_detallehojarutatemp 
	     where idhojarutatemp = idroadmaptempup;

	   -- delete from traking.mct_hojarutaactividadtemp 
	   --  where mct_hojarutaactividadtemp.idhojarutatemp = idroadmaptempup;
	    
	    if ( idimprimehojasup = 1 ) then
	    
	       tope  := 1;
	    
	    else
	    
	    	tope := coalesce(quantityup,0);
	    
	    end if;

			indice := 1;
				
			loop						
			
				sp_hrchar   := LPAD(idworkorderup::integer::text::varchar, 6, '0');  
				sp_partchar := LPAD(sp_part::integer::text::varchar, 3, '0');
		        sp_itemchar := LPAD(sp_maxitem::integer::text::varchar, 3, '0'); 	
		        sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
				
				insert into mct_detallehojarutatemp 
				           (iddetallehojarutatemp 
				           ,idhojarutatemp 
				           ,codhojaruta 
				           ,correlativoparte
				           )
				     VALUES
				           (nextval('traking.mct_detallehojarutatemp_seq')
				           ,idroadmaptempup
				           --,sp_hrchar||sp_partchar||sp_corrchar||'C' 
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar
				           ,indice
				           );                     
		
				sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
			
				insert into mct_ordentrabajoparte 
				           (idordentrabajoparte 
				           ,idordentrabajo 
				           ,idcomponente 
				           ,itemparte
				           ,itemcorr 
				           )
				     VALUES
				           (sp_idpwo
				           ,idworkorderup
				           ,idcomponentup 
				           ,indice
				           ,sp_maxitem
				           );   
		
				-- Esto es para igualar la tabla Hoja Ruta
			    insert into mct_hojaruta 
				           (idhojaruta 
				           ,idordentrabajoparte 
				           ,codhojaruta 
				           ,usuariocreacion 
				           ,fechacreacion
				           ,modalidad 
				           ,idhojarutatemp 
				           )
				     VALUES
				           (nextval('traking.mct_hojaruta_seq')
				           ,sp_idpwo
				           --,sp_hrchar||sp_partchar||sp_corrchar||'C' 
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar
				           ,'admin' 
				           ,now()
				           ,1
				           ,idroadmaptempup
				           ); 
		          
				 indice := indice + 1;
				                           				   
				 EXIT when indice > tope;
				                    
			END loop;                
	
	end if;
	 
	 
	update traking.mct_hojarutatemp 
	   set idmaterial = idmaterialup,
	       nombreplano = blueprintname,
	       cantidad  = quantityup,
	       nombrematerial = materialname,
	       textoadicional = aditionaltext,
	       idtrabajohr = idworkhr,
	       idimprimehojas = idimprimehojasup,
	       idboleano = idboleanoup
	 where idordentrabajo = idworkorderup
	   and idhojarutatemp = idroadmaptempup;
	                  
END
$$;


ALTER FUNCTION traking.updateroadmaptemp(idroadmaptempup bigint, idworkorderup bigint, idcomponentup bigint, idmaterialup bigint, materialname character varying, blueprintname character varying, quantityup bigint, aditionaltext character varying, idworkhr bigint, idimprimehojasup bigint, idboleanoup bigint) OWNER TO postgres;

--
-- TOC entry 2042 (class 1255 OID 18056)
-- Name: updateroadmaptempchecklist(bigint, bigint, bigint, bigint, character varying, character varying, bigint, character varying, bigint, bigint, bigint, character varying, boolean, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateroadmaptempchecklist(idroadmaptempup bigint, idworkorderup bigint, idcomponentup bigint, idmaterialup bigint, materialname character varying, blueprintname character varying, quantityup bigint, aditionaltext character varying, idcriterioevaluacionup bigint, idimprimehojasup bigint, idboleanoup bigint, nombrezonaup character varying, aplicahojarutaup boolean, usercreateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 
		sp_cant						integer;
        sp_hrchar                   TEXT;
        sp_partchar                 TEXT;
        sp_corrchar                 TEXT;
        sp_itemchar                 TEXT;      
        sp_area						integer;
       
        sp_part						integer;
        sp_componente				integer;

        indice   				    INTEGER;
        tope	   				    INTEGER;
	
        sp_idpwo   				    INTEGER;
        sp_maxitem                  integer;     
       
        sp_imprime                  integer;
        sp_actividad				integer;
        sp_detalle					integer;
       
        sp_cambiaplano				varchar;
        sp_cambiazona				varchar;
        sp_cambiacriterio			integer;
        sp_cambiamaterial			integer;
        sp_cambiacantidad			integer;
       
        sp_planoboleano				boolean;
        sp_zonaboleano				boolean;
        sp_criterioboleano			boolean;
        sp_materialboleano			boolean;
        sp_cantidadboleano			boolean;
        
        sp_idcambio					integer;
       
        sp_idmaterial				bigint;
        sp_idcriterioevaluacion		bigint;
        sp_idchecklistinftecvalido	bigint;
       
        sp_nombrecriterio			varchar;
        sp_nombrematerial			varchar;
	
BEGIN
	
	--select count(*)
	--  into sp_cant
	--  from mct_detallehojarutatemp 
	-- where idhojarutatemp = idroadmaptempup;
	
	sp_actividad	:= 0;
	sp_cant			:= 0;
    sp_part         := 0;
    sp_area			:= 0;
   
    sp_idmaterial	:= 0;
    sp_idcriterioevaluacion	:= 0;
    sp_idchecklistinftecvalido	:= 0;
   
    sp_nombrecriterio	:= '';
    sp_nombrematerial	:= '';
   
    -- Para control en cambios de datos
   
    sp_cambiaplano		:= '';
    sp_cambiazona		:= '';
    sp_cambiacriterio	:= 0;
    sp_cambiamaterial	:= 0;
    sp_cambiacantidad	:= 0;
       
       
    sp_planoboleano		:= false;
    sp_zonaboleano		:= false;
    sp_criterioboleano	:= false;
    sp_materialboleano	:= false;
    sp_cantidadboleano	:= false;

	select count(*)
	  into sp_actividad
	  from mct_hojarutaactividadtemp mh 
	 where idhojarutatemp = idroadmaptempup;
	
	
	sp_detalle	:= 0;

	select count(*)
	  into sp_detalle
	  from mct_detallehojarutatemp  
	 where idhojarutatemp = idroadmaptempup;
	
	select idimprimehojas ,
	       coalesce (idcomponente,0) ,
	       cantidad,
	       idmaterial,
	       idcriterioevaluacion,
	       idchecklistinftecvalido
	  into sp_imprime,
	       sp_componente,
	       sp_cant,
	       sp_idmaterial,
	       sp_idcriterioevaluacion,
	       sp_idchecklistinftecvalido
	  from mct_hojarutatemp mh 
	 where idhojarutatemp =  idroadmaptempup;
	
	sp_maxitem      := 0;

	select coalesce (max(a.itemcorr),0)+1
	  into sp_maxitem
	  from mct_ordentrabajoparte a
     where a.idordentrabajo = idworkorderup;
	
	if ( quantityup <> sp_cant or sp_imprime <> idimprimehojasup or sp_componente = 0 or sp_detalle < 1 ) then
	
	   -- Luego elimina los idordentrabajoparte de la ot
		delete from mct_hojaruta 
	     where idhojarutatemp = idroadmaptempup;	
	    
	   -- Primero borra las hojas de ruta asociadas a los idordentrabajoparte de la ot
	    delete from mct_ordentrabajoparte
		 where idordentrabajoparte in ( select idordentrabajoparte
		                                  from mct_hojaruta
		                                 where idhojarutatemp = idroadmaptempup) ;	  		                                										    
	    
	   -- Luego elimina los idordentrabajoparte de la ot		                                
		select coalesce (idcomponente, 0)
	      into sp_part
	      from mct_hojarutatemp 
	     where idhojarutatemp = idroadmaptempup;

	    if ( sp_part <> idcomponentup) then
	    
	       sp_part := idcomponentup;
	    
	    end if;
	   
	    delete from mct_detallehojarutatemp 
	     where idhojarutatemp = idroadmaptempup;

	    --delete from traking.mct_hojarutaactividadtemp 
	    -- where mct_hojarutaactividadtemp.idhojarutatemp = idroadmaptempup;
	    
	    if ( idimprimehojasup = 1 ) then
	    
	        tope  := 1;
	    
	    else
	    
	    	tope := coalesce(quantityup,0);
	    
	    end if;

			indice := 1;
				
			loop						
			
				sp_hrchar   := LPAD(idworkorderup::integer::text::varchar, 6, '0');  
				sp_partchar := LPAD(sp_part::integer::text::varchar, 3, '0');
		        sp_itemchar := LPAD(sp_maxitem::integer::text::varchar, 3, '0'); 	
		        sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
				
				insert into mct_detallehojarutatemp 
				           (iddetallehojarutatemp 
				           ,idhojarutatemp 
				           ,codhojaruta 
				           ,correlativoparte
				           )
				     VALUES
				           (nextval('traking.mct_detallehojarutatemp_seq')
				           ,idroadmaptempup
				           --,sp_hrchar||sp_partchar||sp_corrchar||'C' 
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar
				           ,indice
				           );                     
		
				sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
			
				insert into mct_ordentrabajoparte 
				           (idordentrabajoparte 
				           ,idordentrabajo 
				           ,idcomponente 
				           ,itemparte
				           ,itemcorr 
				           )
				     VALUES
				           (sp_idpwo
				           ,idworkorderup
				           ,idcomponentup 
				           ,indice
				           ,sp_maxitem
				           );   
		
				-- Esto es para igualar la tabla Hoja Ruta
			    insert into mct_hojaruta 
				           (idhojaruta 
				           ,idordentrabajoparte 
				           ,codhojaruta 
				           ,usuariocreacion 
				           ,fechacreacion
				           ,modalidad 
				           ,idhojarutatemp 
				           )
				     VALUES
				           (nextval('traking.mct_hojaruta_seq')
				           ,sp_idpwo
				           --,sp_hrchar||sp_partchar||sp_corrchar||'C' 
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar
				           ,'admin' 
				           ,now()
				           ,1
				           ,idroadmaptempup
				           ); 
		          
				 indice := indice + 1;
				                           				   
				 EXIT when indice > tope;
				                    
			END loop;                
	
	end if;

    -- Valida si existe actividad para la parte
    if ( sp_actividad < 1 ) then
 
    	    insert into mct_hojarutaactividadtemp 
	                (
	                idhojarutaactividadtemp ,
	                idhojarutatemp ,
	                idactividad ,
	                tiempoproduccion ,
	                orden 
	                )        	     
			select nextval('mct_hojarutaactividadtemp_seq'),
			       idroadmaptempup,
			       idactividad , 
			       tiempoproduccion , 
			       orden 
			  from mct_partetipotrabajoactividad mp 
			 where idpartetipotrabajo = ( select idcomponentetipotrabajo 
									        from mct_componentetipotrabajo mc
									       where idcomponente  = idcomponentup
									         and idtipotrabajo in (21))
			order by idpartetipotrabajoactividad  asc, orden asc;
		
    end if;
			 
    select coalesce (idareaclasificacion , 0)
      into sp_area
      from mct_componente mc 
     where idcomponente = idcomponentup;
    

    sp_cambiaplano		:= '';
    sp_cambiazona		:= '';
    sp_cambiacriterio	:= 0;
    sp_cambiamaterial	:= 0;
    sp_cambiacantidad	:= 0;
   
    select nombreplano,
           nombrezona,
           idcriterioevaluacion,
           idmaterial,
           cantidad
      into sp_cambiaplano,
    	   sp_cambiazona,
    	   sp_cambiacriterio,
    	   sp_cambiamaterial,
    	   sp_cambiacantidad
      from mct_hojarutatemp mh
     where idhojarutatemp = idroadmaptempup;
   
    sp_planoboleano		:= false;
    sp_zonaboleano		:= false;
    sp_criterioboleano	:= false;
    sp_materialboleano	:= false;
    sp_cantidadboleano	:= false;
   
    if (sp_cambiaplano != blueprintname) then
    	sp_planoboleano	:= true;
    end if;
   
    if (sp_cambiazona != nombrezonaup) then
    	sp_zonaboleano	:= true;
    end if;
   
    if (sp_cambiacriterio != idcriterioevaluacionup) then
    	sp_criterioboleano	:= true;
    end if;
   
    if (sp_cambiamaterial != idmaterialup) then
    	sp_materialboleano	:= true;
    end if;
   
    if (sp_cambiacantidad != quantityup) then
    	sp_cantidadboleano	:= true;
    end if;

    sp_idcambio				:= 0;
    			    
    select idhojarutatempcambio
      into sp_idcambio
      from mct_hojarutatempcambio mh
     where idhojarutatemp = idroadmaptempup;   			    
    			   
    if (sp_idcambio > 0) then
                    
  	    if ( sp_planoboleano = true ) then
	    
	         update traking.mct_hojarutatempcambio
	            set cambiaplano = sp_planoboleano, 
	                fechamodificacion = now(),
	                usuariomodificacion = usercreateup
	          where idhojarutatempcambio = sp_idcambio;
	
	    end if;         
	   
	    if ( sp_zonaboleano  = true ) then
	    
	         update traking.mct_hojarutatempcambio
	            set cambiazona = sp_zonaboleano,
	                fechamodificacion = now(),
	                usuariomodificacion = usercreateup
	          where idhojarutatempcambio = sp_idcambio;
	
	    end if; 
	   
	   
	    if ( sp_criterioboleano = true) then
	    
	         update traking.mct_hojarutatempcambio
	            set cambiatrabajo = sp_criterioboleano,
	                fechamodificacion = now(),
	                usuariomodificacion = usercreateup
	          where idhojarutatempcambio = sp_idcambio;
	
	    end if; 
	   
	   
	    if ( sp_materialboleano = true) then
	    
	         update traking.mct_hojarutatempcambio
	            set cambiamaterial = sp_materialboleano, 
	                fechamodificacion = now(),
	                usuariomodificacion = usercreateup
	          where idhojarutatempcambio = sp_idcambio;
	
	    end if; 
	   
	   
	    if ( sp_cantidadboleano = true) then
	    
	         update traking.mct_hojarutatempcambio
	            set cambiacantidad = sp_cantidadboleano,
	                fechamodificacion = now(),
	                usuariomodificacion = usercreateup
	          where idhojarutatempcambio = sp_idcambio;
	
	    end if; 
	   
                    
    else 
                    
	    if ( sp_planoboleano = true or 
	         sp_zonaboleano  = true or 
	         sp_criterioboleano = true or 
	         sp_materialboleano = true or 
	         sp_cantidadboleano = true) then
	    
			    INSERT INTO traking.mct_hojarutatempcambio
			          (idhojarutatempcambio, idhojarutatemp, cambiamaterial, cambiaplano, cambiatrabajo, cambiacantidad, cambiazona, usuariocreacion, fechacreacion)
			         VALUES(nextval('traking.mct_hojarutatempcambio_seq'), 
			                idroadmaptempup, 
			                sp_materialboleano, 
			                sp_planoboleano, 
			                sp_criterioboleano, 
			                sp_cantidadboleano, 
			                sp_zonaboleano, 
			                usercreateup, 
			                now()
			               );
	
	    end if;                    
                    
    end if;
                   
   
--    if ( sp_planoboleano = true or 
--         sp_zonaboleano  = true or 
--         sp_criterioboleano = true or 
--         sp_materialboleano = true or 
--         sp_cantidadboleano = true) then
--    
--		    INSERT INTO traking.mct_hojarutatempcambio
--		          (idhojarutatempcambio, idhojarutatemp, cambiamaterial, cambiaplano, cambiatrabajo, cambiacantidad, cambiazona, usuariocreacion, fechacreacion)
--		         VALUES(nextval('traking.mct_hojarutatempcambio_seq'), 
--		                idroadmaptempup, 
--		                sp_materialboleano, 
--		                sp_planoboleano, 
--		                sp_criterioboleano, 
--		                sp_cantidadboleano, 
--		                sp_zonaboleano, 
--		                usercreateup, 
--		                now()
--		               );
--
--    end if;
   
    
	update traking.mct_hojarutatemp 
	   set idmaterial = idmaterialup,
	       nombreplano = blueprintname,
	       cantidad  = quantityup,
	       nombrematerial = materialname,
	       textoadicional = aditionaltext,
	       idcriterioevaluacion = idcriterioevaluacionup,
	       idimprimehojas = idimprimehojasup,
	       idboleano = idboleanoup,
	       idcomponente = idcomponentup,
	       idareaclasificacion = sp_area,
	       nombrezona = nombrezonaup,
	       usuariocreacion = usercreateup,
	       aplicahojaruta = aplicahojarutaup
	 where idordentrabajo = idworkorderup
	   and idhojarutatemp = idroadmaptempup;
	  
	  

	if ( quantityup <> sp_cant or idmaterialup <> sp_idmaterial or idcriterioevaluacionup <> sp_idcriterioevaluacion ) then
	
		INSERT INTO traking.mct_checklistinftecvalidocambio
		       (
		        idchecklistinftecvalidocambio, 
		        idchecklistinftecvalido, 
		        idordentrabajo, 
		        cantidad, 
		        idmaterial, 
		        --material, 
		        idcriterioevaluacion, 
		        --criterio, 
		        usuariocreacion, 
		        fechacreacion
		        )
		  VALUES(
		        nextval('traking.mct_checklistinftecvalidocambio_seq'), 
		        sp_idchecklistinftecvalido, 
		        idworkorderup, 
		        sp_cant, 
		        sp_idmaterial, 
		        --'',
		        sp_idcriterioevaluacion, 
		        --'', 
		        usercreateup, 
		        now()
		        );
		       
		
        if ( quantityup <> sp_cant ) then
        
        	update mct_checklistinftecvalido 
			   set cantidad = quantityup
			 where idchecklistinftecvalido = sp_idchecklistinftecvalido;
			
        end if;

        if ( idmaterialup <> sp_idmaterial ) then
        
            select nombrematerial
              into sp_nombrematerial
              from mct_material 
             where idmaterial = idmaterialup;
            
        	update mct_checklistinftecvalido 
			   set idmaterial = idmaterialup,
			       nombrematerial = sp_nombrematerial
			 where idchecklistinftecvalido = sp_idchecklistinftecvalido;
			
        end if;
       
       
        if ( idcriterioevaluacionup <> sp_idcriterioevaluacion ) then
        
            select nombrecriterioevaluacion
              into sp_nombrecriterio
              from mct_criterioevaluacion mc
             where idcriterioevaluacion = idcriterioevaluacionup;
             
             
        	update mct_checklistinftecvalido 
			   set idcriterioevaluacion = idcriterioevaluacionup,
			       criterio = sp_nombrecriterio,
			       codigoqr = idworkorderup||upper(sp_nombrecriterio),
			       tipotrabajostd = upper(sp_nombrecriterio)
			 where idchecklistinftecvalido = sp_idchecklistinftecvalido;
			
        end if;
       
	end if;
	                  
END
$$;


ALTER FUNCTION traking.updateroadmaptempchecklist(idroadmaptempup bigint, idworkorderup bigint, idcomponentup bigint, idmaterialup bigint, materialname character varying, blueprintname character varying, quantityup bigint, aditionaltext character varying, idcriterioevaluacionup bigint, idimprimehojasup bigint, idboleanoup bigint, nombrezonaup character varying, aplicahojarutaup boolean, usercreateup character varying) OWNER TO postgres;

--
-- TOC entry 1103 (class 1255 OID 18058)
-- Name: updateroadmaptemppieza(bigint, bigint, bigint, bigint, character varying, character varying, bigint, character varying, bigint, bigint, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateroadmaptemppieza(idroadmaptempup bigint, idworkorderup bigint, idcomponentup bigint, idmaterialup bigint, materialname character varying, blueprintname character varying, quantityup bigint, aditionaltext character varying, idcriterioevaluacionup bigint, idimprimehojasup bigint, idboleanoup bigint, nombrezonaup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 
		sp_cant						integer;
        sp_hrchar                   TEXT;
        sp_partchar                 TEXT;
        sp_corrchar                 TEXT;
        sp_itemchar                 TEXT;      
       
        sp_part						integer;

        indice   				    INTEGER;
        tope	   				    INTEGER;
	
        sp_idpwo   				    INTEGER;
        sp_maxitem                  integer;     
       
        sp_imprime                  integer;
	
BEGIN

	select count(*)
	  into sp_cant
	  from mct_detallehojarutatemp 
	 where idhojarutatemp = idroadmaptempup;
	
	
	select idimprimehojas 
	  into sp_imprime
	  from mct_hojarutatemp mh 
	 where idhojarutatemp =  idroadmaptempup;
	
	sp_maxitem      := 0;

	select max(a.itemcorr)+1
	  into sp_maxitem
	  from mct_ordentrabajoparte a
     where a.idordentrabajo = idworkorderup;
	
	if ( quantityup <> sp_cant or sp_imprime <> idimprimehojasup ) then
	
	   -- Primero borra las hojas de ruta asociadas a los idordentrabajoparte de la ot
	   --delete from mct_hojaruta 
	   -- where idordentrabajoparte in (select idordentrabajoparte 
		--							    from mct_ordentrabajoparte mo 
		--							   where idordentrabajo = idworkorderup
		--							     and idcomponente   = idcomponentup);

	    delete from mct_ordentrabajoparte mo 
		 where idordentrabajoparte in ( select idordentrabajoparte
		                                  from mct_hojaruta
		                                 where idhojarutatemp = idroadmaptempup) ;	  
		                                
		delete from mct_hojaruta 
	     where idhojarutatemp = idroadmaptempup;										    
	
	   -- Luego elimina los idordentrabajoparte de la ot
	   --delete from mct_ordentrabajoparte mo 
	   --      where idordentrabajo = idworkorderup
	   --        and idcomponente   = idcomponentup;
	          

		                                
		select idcomponente
	      into sp_part
	      from mct_hojarutatemp 
	     where idhojarutatemp = idroadmaptempup;
		
	    delete from mct_detallehojarutatemp 
	     where idhojarutatemp = idroadmaptempup;

	   -- delete from traking.mct_hojarutaactividadtemp 
	   --  where mct_hojarutaactividadtemp.idhojarutatemp = idroadmaptempup;
	    
	    if ( idimprimehojasup = 1 ) then
	    
	       tope  := 1;
	    
	    else
	    
	    	tope := coalesce(quantityup,0);
	    
	    end if;

			indice := 1;
				
			loop						
			
				sp_hrchar   := LPAD(idworkorderup::integer::text::varchar, 6, '0');  
				sp_partchar := LPAD(sp_part::integer::text::varchar, 3, '0');
		        sp_itemchar := LPAD(sp_maxitem::integer::text::varchar, 3, '0'); 	
		        sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
				
				insert into mct_detallehojarutatemp 
				           (iddetallehojarutatemp 
				           ,idhojarutatemp 
				           ,codhojaruta 
				           ,correlativoparte
				           )
				     VALUES
				           (nextval('traking.mct_detallehojarutatemp_seq')
				           ,idroadmaptempup
				           --,sp_hrchar||sp_partchar||sp_corrchar||'C' 
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar
				           ,indice
				           );                     
		
				sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
			
				insert into mct_ordentrabajoparte 
				           (idordentrabajoparte 
				           ,idordentrabajo 
				           ,idcomponente 
				           ,itemparte
				           ,itemcorr 
				           )
				     VALUES
				           (sp_idpwo
				           ,idworkorderup
				           ,idcomponentup 
				           ,indice
				           ,sp_maxitem
				           );   
		
				-- Esto es para igualar la tabla Hoja Ruta
			    insert into mct_hojaruta 
				           (idhojaruta 
				           ,idordentrabajoparte 
				           ,codhojaruta 
				           ,usuariocreacion 
				           ,fechacreacion
				           ,modalidad 
				           ,idhojarutatemp 
				           )
				     VALUES
				           (nextval('traking.mct_hojaruta_seq')
				           ,sp_idpwo
				           --,sp_hrchar||sp_partchar||sp_corrchar||'C' 
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar
				           ,'admin' 
				           ,now()
				           ,1
				           ,idroadmaptempup
				           ); 
		          
				 indice := indice + 1;
				                           				   
				 EXIT when indice > tope;
				                    
			END loop;                
	
	end if;
	 
	 
	update traking.mct_hojarutatemp 
	   set idmaterial = idmaterialup,
	       nombreplano = blueprintname,
	       cantidad  = quantityup,
	       nombrematerial = materialname,
	       textoadicional = aditionaltext,
	       idcriterioevaluacion = idcriterioevaluacionup,
	       idimprimehojas = idimprimehojasup,
	       idboleano = idboleanoup,
	       nombrezona = nombrezonaup
	 where idordentrabajo = idworkorderup
	   and idhojarutatemp = idroadmaptempup;
	                  
END
$$;


ALTER FUNCTION traking.updateroadmaptemppieza(idroadmaptempup bigint, idworkorderup bigint, idcomponentup bigint, idmaterialup bigint, materialname character varying, blueprintname character varying, quantityup bigint, aditionaltext character varying, idcriterioevaluacionup bigint, idimprimehojasup bigint, idboleanoup bigint, nombrezonaup character varying) OWNER TO postgres;

--
-- TOC entry 1610 (class 1255 OID 18059)
-- Name: updateroadmaptempsection(bigint, bigint, bigint, bigint, character varying, character varying, bigint, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateroadmaptempsection(idroadmaptempup bigint, idworkorderup bigint, idcomponentup bigint, idmaterialup bigint, materialname character varying, blueprintname character varying, quantityup bigint, aditionaltext character varying, idworkhr bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 
		sp_cant						integer;
        sp_hrchar                   TEXT;
        sp_partchar                 TEXT;
        sp_corrchar                 TEXT;
        sp_itemchar                 TEXT;       
       
        sp_part						integer;

        indice   				    INTEGER;
        tope	   				    INTEGER;
	
        sp_idpwo   				    INTEGER;
        sp_maxitem                  integer;
        sp_perfil                   integer;
       
        sp_seccion_text             varchar;
	
BEGIN

	select count(*)
	  into sp_cant
	  from mct_detallehojarutatemp 
	 where idhojarutatemp = idroadmaptempup;
	
	
	sp_maxitem      := 0;
    sp_perfil       := 0;

	select max(a.itemcorr)+1
	  into sp_maxitem
	  from mct_ordentrabajoparte a
     where a.idordentrabajo = idworkorderup;
    
    
    select idperfil 
      into sp_perfil
      from mct_hojarutatemp mh 
     where idhojarutatemp = idroadmaptempup;
   
   
	if ( quantityup <> sp_cant ) then
	
	    sp_seccion_text   := '';

	    if ( sp_perfil = 16 ) then
	    
	        sp_seccion_text   := 'F';
	    
	    elsif ( sp_perfil = 15 ) then
	
	            sp_seccion_text   := 'TM';
	           
	    elsif ( sp_perfil = 14 ) then
	    
	            sp_seccion_text   := 'P';
	           
	    elsif ( sp_perfil = 9 ) then
	        
	            sp_seccion_text   := 'C';
	           
	    elsif ( sp_perfil = 8 ) then
	        
	            sp_seccion_text   := 'CC';
	 
	    elsif ( sp_perfil = 17 ) then
	        
	            sp_seccion_text   := 'A';
	           
	    end if;
	   

	   	   -- Luego elimina los idordentrabajoparte de la ot
		delete from mct_ordentrabajoparte mo 
		 where idordentrabajoparte in ( select idordentrabajoparte
		                                  from mct_hojaruta
		                                 where idhojarutatemp = idroadmaptempup) ;	  
		                                
	   -- Primero borra las hojas de ruta asociadas a los idordentrabajoparte de la ot   
		delete from mct_hojaruta 
	     where idhojarutatemp = idroadmaptempup;									    
									    
		select idcomponente
	      into sp_part
	      from mct_hojarutatemp 
	     where idhojarutatemp = idroadmaptempup;
		
	    delete from traking.mct_detallehojarutatemp 
	     where idhojarutatemp = idroadmaptempup;

	    delete from traking.mct_hojarutaactividadtemp 
	     where mct_hojarutaactividadtemp.idhojarutatemp = idroadmaptempup;
	       
	    	tope := coalesce(quantityup,0);
		           
			indice := 1;
				
			loop						
		
				sp_hrchar   := LPAD(idworkorderup::integer::text::varchar, 6, '0');  
				sp_partchar := LPAD(sp_part::integer::text::varchar, 3, '0');
		        sp_itemchar := LPAD(sp_maxitem::integer::text::varchar, 3, '0'); 	
		        sp_corrchar := LPAD(indice::integer::text::varchar, 3, '0'); 
				
				insert into mct_detallehojarutatemp 
				           (iddetallehojarutatemp 
				           ,idhojarutatemp 
				           ,codhojaruta 
				           ,correlativoparte
				           )
				     VALUES
				           (nextval('traking.mct_detallehojarutatemp_seq')
				           ,idroadmaptempup
				           --,sp_hrchar||sp_partchar||sp_corrchar||'C' 
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar||sp_seccion_text 
				           ,indice
				           );                     
		
				sp_idpwo := nextval('traking.mct_ordentrabajoparte_seq');
			
				insert into mct_ordentrabajoparte 
				           (idordentrabajoparte 
				           ,idordentrabajo 
				           ,idcomponente 
				           ,itemparte 
				           ,itemcorr 
				           )
				     VALUES
				           (sp_idpwo
				           ,idworkorderup
				           ,idcomponentup 
				           ,indice
				           ,sp_maxitem
				           );   
		
				-- Esto es para igualar la tabla Hoja Ruta
			    insert into mct_hojaruta 
				           (idhojaruta 
				           ,idordentrabajoparte 
				           ,codhojaruta 
				           ,usuariocreacion 
				           ,fechacreacion
				           ,modalidad 
				           ,idhojarutatemp 
				           )
				     VALUES
				           (nextval('traking.mct_hojaruta_seq')
				           ,sp_idpwo
				           --,sp_hrchar||sp_partchar||sp_corrchar||'C' 
				           ,sp_hrchar||sp_partchar||sp_itemchar||sp_corrchar||sp_seccion_text 
				           ,'admin' 
				           ,now()
				           ,1
				           ,idroadmaptempup
				           ); 
		          
				 indice := indice + 1;
				                           				   
				 EXIT when indice > tope;
				                    
			END loop;                
	
	end if;
	 
	 
	update traking.mct_hojarutatemp 
	   set idmaterial = idmaterialup,
	       nombreplano = blueprintname,
	       cantidad  = quantityup,
	       nombrematerial = materialname,
	       textoadicional = aditionaltext,
	       idtrabajohr = idworkhr
	 where idordentrabajo = idworkorderup
	   and idhojarutatemp = idroadmaptempup;
	                  
END
$$;


ALTER FUNCTION traking.updateroadmaptempsection(idroadmaptempup bigint, idworkorderup bigint, idcomponentup bigint, idmaterialup bigint, materialname character varying, blueprintname character varying, quantityup bigint, aditionaltext character varying, idworkhr bigint) OWNER TO postgres;

--
-- TOC entry 1160 (class 1255 OID 18060)
-- Name: updateroadmaptemptraspaso(character varying, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateroadmaptemptraspaso(roadmapcodeorigenup character varying, roadmapcodedestinoup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare 

        sp_idhojarutatemporigen     bigint;
        sp_idhojarutatempdestino    bigint;       
        sp_tienemov					bigint;
       
        sp_tienemovdes				bigint;
       
        sp_idhojarutaorigen			bigint;
        sp_idhojarutaorigen100		bigint;
       
        sp_otorigen                 bigint;
        sp_otdestino                bigint;
       
        sp_idhojarutadestino		bigint;
        sp_idhojarutadestino100		bigint;
	
BEGIN

	sp_idhojarutatemporigen		:= 0;
	sp_idhojarutatempdestino	:= 0;
    sp_tienemov					:= 0;
   
    sp_otorigen                 := 0;
    sp_otdestino                := 0;
   
    sp_idhojarutaorigen			:= 0;
    sp_idhojarutaorigen100		:= 0;
    sp_idhojarutadestino		:= 0;
    sp_idhojarutadestino100		:= 0;

	-- Aca saca el idhojaruta de la hr de origen
	select a.idhojaruta,
	       a.idhojaruta * 1000,
	       b.idordentrabajo  -- 19795
	  into sp_idhojarutaorigen,
	       sp_idhojarutaorigen100,
	       sp_otorigen
	  from mct_hojaruta a,
	       mct_hojarutatemp b
	 where a.codhojaruta = roadmapcodeorigenup
	   and a.idhojarutatemp = b.idhojarutatemp ;
 
       
	-- Aca saca el idhojaruta de la hr de destino
	select a.idhojaruta,
	       a.idhojaruta * 1000,
	       b.idordentrabajo -- 5505
	  into sp_idhojarutadestino,
	       sp_idhojarutadestino100,
	       sp_otdestino
	  from mct_hojaruta a,
	       mct_hojarutatemp b
	 where a.codhojaruta = roadmapcodedestinoup
	   and a.idhojarutatemp = b.idhojarutatemp ;
	 
	-- Aca saca la cantidad de movimientos que tiene la HR de origen
	select count(*)
	  into sp_tienemov
	  from mct_movimientoordentrabajo mm 
	 where codhojaruta = roadmapcodeorigenup;
	
	-- Aca saca la cantidad de movimientos que tiene la HR de destino
	select count(*)
	  into sp_tienemovdes
	  from mct_movimientoordentrabajo mm 
	 where codhojaruta = roadmapcodedestinoup;	
	
	if (sp_idhojarutaorigen > 0 and sp_tienemov > 0) then
	
	   if ( sp_tienemovdes > 0) then

	        raise notice '%', 'Entro aca '||sp_tienemovdes;
	   
	        -- Respaldamos el destino
			update mct_movimientoordentrabajo
			   set idhojaruta = sp_idhojarutadestino100,
			       codhojaruta = roadmapcodedestinoup||'_transitorio'	       
		     where idhojaruta = sp_idhojarutadestino
		       and codhojaruta = roadmapcodedestinoup;
		              
	        -- Cambiamos el origen
			update traking.mct_movimientoordentrabajo 
			   set idhojaruta = sp_idhojarutadestino,
			       codhojaruta = roadmapcodedestinoup,
			       idordentrabajo = sp_otdestino
			 where idhojaruta = sp_idhojarutaorigen
			   and codhojaruta = roadmapcodeorigenup;
			  
			-- Cambiamos el destino
			update traking.mct_movimientoordentrabajo 
			   set idhojaruta = sp_idhojarutaorigen,
			       codhojaruta = roadmapcodeorigenup,
			       idordentrabajo = sp_otorigen
			 where idhojaruta = sp_idhojarutadestino100
			   and codhojaruta = roadmapcodedestinoup||'_transitorio';
			  
	   else
	   
	        raise notice '%', 'Entro aca 2 '||sp_tienemovdes;
	       
			update traking.mct_movimientoordentrabajo 
			   set idhojaruta = sp_idhojarutadestino,
			       codhojaruta = roadmapcodedestinoup,
			       idordentrabajo = sp_otdestino
			       --fechatermino = now()
			 where idhojaruta = sp_idhojarutaorigen
			   and codhojaruta = roadmapcodeorigenup;
		  
	   end if;

		
	  
	end if;
	 

	                  
END
$$;


ALTER FUNCTION traking.updateroadmaptemptraspaso(roadmapcodeorigenup character varying, roadmapcodedestinoup character varying) OWNER TO postgres;

