--
-- TOC entry 2204 (class 1255 OID 18064)
-- Name: updateseqblueprint(bigint, character varying, character varying, bigint); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateseqblueprint(idblueprintup bigint, nameblueprintup character varying, lastblueprintup character varying, quantityup bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE 

       	sp_ultimocorr   	INTEGER;
       	sp_plano			VARCHAR;
      	sp_seqchar			VARCHAR;
      	sp_tope				INTEGER;
       
BEGIN

	
	if ((select count(*) from (select regexp_split_to_table(lastblueprintup, '-')) as a) = 3 ) then
	
		sp_plano = split_part(lastblueprintup,'-',1)||'-'||split_part(lastblueprintup,'-',2);
	
		sp_ultimocorr = cast(split_part(lastblueprintup,'-',3) as integer);
	
		sp_ultimocorr = sp_ultimocorr + 1;
	
		sp_tope = sp_ultimocorr + quantityup;
		
		while sp_ultimocorr < sp_tope 
		    loop
		    
		    	if ( sp_ultimocorr < 100) then
		    		sp_seqchar := LPAD(sp_ultimocorr::integer::text::varchar, 2, '0');
		    	else
		    		sp_seqchar := LPAD(sp_ultimocorr::integer::text::varchar, 3, '0');
		    	end if;
		    	
		    	INSERT INTO traking.mct_plano
						(idplano, 
						 idtipoplano, 
						 nombreplano, 
						 estado, 
						 usuariocreacion, 
						 fechacreacion, 
						 usuariomodificacion, 
						 fechamodificacion, 
						 archivoplano, 
						 cantidad)
				  VALUES(nextval('mct_plano_seq'), 
                         40, 
                         sp_plano||'-'||sp_seqchar, 
                         1, 
                         'admin', 
                         now(), 
                         'admin', 
                         now(), 
                         '', 
                         1);
		    	
		        sp_ultimocorr := sp_ultimocorr + 1;
		    
		    end loop;
		   
	else
		   
		sp_plano = split_part(lastblueprintup,'-',1);
	
		sp_ultimocorr = cast(split_part(lastblueprintup,'-',2) as integer);
	
		sp_ultimocorr = sp_ultimocorr + 1;
	
		sp_tope = sp_ultimocorr + quantityup;
		
		while sp_ultimocorr < sp_tope 
		    loop
		    
		    	if ( sp_ultimocorr < 100) then
		    		sp_seqchar := LPAD(sp_ultimocorr::integer::text::varchar, 2, '0');
		    	else
		    		sp_seqchar := LPAD(sp_ultimocorr::integer::text::varchar, 3, '0');
		    	end if;
		    	
		    	INSERT INTO traking.mct_plano
						(idplano, 
						 idtipoplano, 
						 nombreplano, 
						 estado, 
						 usuariocreacion, 
						 fechacreacion, 
						 usuariomodificacion, 
						 fechamodificacion, 
						 archivoplano, 
						 cantidad)
				  VALUES(nextval('mct_plano_seq'), 
                         40, 
                         sp_plano||'-'||sp_seqchar, 
                         1, 
                         'admin', 
                         now(), 
                         'admin', 
                         now(), 
                         '', 
                         1);
		    	
		        sp_ultimocorr := sp_ultimocorr + 1;
		    
		    end loop;
		   
	end if;
		   	
   
END;
$$;


ALTER FUNCTION traking.updateseqblueprint(idblueprintup bigint, nameblueprintup character varying, lastblueprintup character varying, quantityup bigint) OWNER TO postgres;

