--
-- TOC entry 2258 (class 1255 OID 18082)
-- Name: updateuser(bigint, bigint, character varying, character varying, integer, character varying, character varying, character varying, bigint, character varying); Type: FUNCTION; Schema: traking; Owner: postgres
--

CREATE FUNCTION traking.updateuser(idprofileup bigint, iduserup bigint, userup character varying, passwordup character varying, statusup integer, dniup character varying, nameup character varying, emailup character varying, idcustomerup bigint, userupdateup character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

declare 

	md5temp 	varchar;

BEGIN

	
	md5temp = concat(CAST(iduserup AS varchar),dniup);
    SELECT MD5(md5temp) into md5temp;
   
    update traking.mct_usuario
    set idperfil=idprofileup,
        usuario=userup,
        password=passwordup,
        estado=statusup,
        rut=dniup,
        nombre=nameup,
 --       "lastname"=lastnameup,
        email=emailup,
        idcliente=idcustomerup,
        usuariomodificacion=userupdateup,
        fechamodificacion=now(),
        hashcodecredencial=md5temp
    where idusuario = iduserup;
END;
$$;


ALTER FUNCTION traking.updateuser(idprofileup bigint, iduserup bigint, userup character varying, passwordup character varying, statusup integer, dniup character varying, nameup character varying, emailup character varying, idcustomerup bigint, userupdateup character varying) OWNER TO postgres;

